def send_static_file(self, filename: str) -> Response:
    if not self.has_static_folder:
        raise RuntimeError("'static_folder' must be set to serve static_files.")
    max_age = self.get_send_file_max_age(filename)
    return send_from_directory(t.cast(str, self.static_folder), filename, max_age=max_age)

def open_resource(self, resource: str, mode: str='rb', encoding: str | None=None) -> t.IO[t.AnyStr]:
    if mode not in {'r', 'rt', 'rb'}:
        raise ValueError('Resources can only be opened for reading.')
    path = os.path.join(self.root_path, resource)
    if mode == 'rb':
        return open(path, mode)
    return open(path, mode, encoding=encoding)

def open_instance_resource(self, resource: str, mode: str='rb', encoding: str | None='utf-8') -> t.IO[t.AnyStr]:
    path = os.path.join(self.instance_path, resource)
    if 'b' in mode:
        return open(path, mode)
    return open(path, mode, encoding=encoding)

def create_jinja_environment(self) -> Environment:
    options = dict(self.jinja_options)
    if 'autoescape' not in options:
        options['autoescape'] = self.select_jinja_autoescape
    if 'auto_reload' not in options:
        auto_reload = self.config['TEMPLATES_AUTO_RELOAD']
        if auto_reload is None:
            auto_reload = self.debug
        options['auto_reload'] = auto_reload
    rv = self.jinja_environment(self, **options)
    rv.globals.update(url_for=self.url_for, get_flashed_messages=get_flashed_messages, config=self.config, request=request, session=session, g=g)
    rv.policies['json.dumps_function'] = self.json.dumps
    return rv

def create_url_adapter(self, request: Request | None) -> MapAdapter | None:
    if request is not None:
        if (trusted_hosts := self.config['TRUSTED_HOSTS']) is not None:
            request.trusted_hosts = trusted_hosts
        request.host = get_host(request.environ, request.trusted_hosts)
        subdomain = None
        server_name = self.config['SERVER_NAME']
        if self.url_map.host_matching:
            server_name = None
        elif not self.subdomain_matching:
            subdomain = self.url_map.default_subdomain or ''
        return self.url_map.bind_to_environ(request.environ, server_name=server_name, subdomain=subdomain)
    if self.config['SERVER_NAME'] is not None:
        return self.url_map.bind(self.config['SERVER_NAME'], script_name=self.config['APPLICATION_ROOT'], url_scheme=self.config['PREFERRED_URL_SCHEME'])
    return None

def raise_routing_exception(self, request: Request) -> t.NoReturn:
    if not self.debug or not isinstance(request.routing_exception, RequestRedirect) or request.routing_exception.code in {307, 308} or (request.method in {'GET', 'HEAD', 'OPTIONS'}):
        raise request.routing_exception
    from .debughelpers import FormDataRoutingRedirect
    raise FormDataRoutingRedirect(request)

def update_template_context(self, ctx: AppContext, context: dict[str, t.Any]) -> None:
    names: t.Iterable[str | None] = (None,)
    if ctx.has_request:
        names = chain(names, reversed(ctx.request.blueprints))
    orig_ctx = context.copy()
    for name in names:
        if name in self.template_context_processors:
            for func in self.template_context_processors[name]:
                context.update(self.ensure_sync(func)())
    context.update(orig_ctx)

def make_shell_context(self) -> dict[str, t.Any]:
    rv = {'app': self, 'g': g}
    for processor in self.shell_context_processors:
        rv.update(processor())
    return rv

def run(self, host: str | None=None, port: int | None=None, debug: bool | None=None, load_dotenv: bool=True, **options: t.Any) -> None:
    if os.environ.get('FLASK_RUN_FROM_CLI') == 'true':
        if not is_running_from_reloader():
            click.secho(' * Ignoring a call to \'app.run()\' that would block the current \'flask\' CLI command.\n   Only call \'app.run()\' in an \'if __name__ == "__main__"\' guard.', fg='red')
        return
    if get_load_dotenv(load_dotenv):
        cli.load_dotenv()
        if 'FLASK_DEBUG' in os.environ:
            self.debug = get_debug_flag()
    if debug is not None:
        self.debug = bool(debug)
    server_name = self.config.get('SERVER_NAME')
    sn_host = sn_port = None
    if server_name:
        sn_host, _, sn_port = server_name.partition(':')
    if not host:
        if sn_host:
            host = sn_host
        else:
            host = '127.0.0.1'
    if port or port == 0:
        port = int(port)
    elif sn_port:
        port = int(sn_port)
    else:
        port = 5000
    options.setdefault('use_reloader', self.debug)
    options.setdefault('use_debugger', self.debug)
    options.setdefault('threaded', True)
    cli.show_server_banner(self.debug, self.name)
    from werkzeug.serving import run_simple
    try:
        run_simple(t.cast(str, host), port, self, **options)
    finally:
        self._got_first_request = False

