def handle_http_exception(self, ctx: AppContext, e: HTTPException) -> HTTPException | ft.ResponseReturnValue:
    if e.code is None:
        return e
    if isinstance(e, RoutingException):
        return e
    handler = self._find_error_handler(e, ctx.request.blueprints)
    if handler is None:
        return e
    return self.ensure_sync(handler)(e)

def handle_user_exception(self, ctx: AppContext, e: Exception) -> HTTPException | ft.ResponseReturnValue:
    if isinstance(e, BadRequestKeyError) and (self.debug or self.config['TRAP_BAD_REQUEST_ERRORS']):
        e.show_exception = True
    if isinstance(e, HTTPException) and (not self.trap_http_exception(e)):
        return self.handle_http_exception(ctx, e)
    handler = self._find_error_handler(e, ctx.request.blueprints)
    if handler is None:
        raise
    return self.ensure_sync(handler)(e)

def handle_exception(self, ctx: AppContext, e: Exception) -> Response:
    exc_info = sys.exc_info()
    got_request_exception.send(self, _async_wrapper=self.ensure_sync, exception=e)
    propagate = self.config['PROPAGATE_EXCEPTIONS']
    if propagate is None:
        propagate = self.testing or self.debug
    if propagate:
        if exc_info[1] is e:
            raise
        raise e
    self.log_exception(ctx, exc_info)
    server_error: InternalServerError | ft.ResponseReturnValue
    server_error = InternalServerError(original_exception=e)
    handler = self._find_error_handler(server_error, ctx.request.blueprints)
    if handler is not None:
        server_error = self.ensure_sync(handler)(server_error)
    return self.finalize_request(ctx, server_error, from_error_handler=True)

def dispatch_request(self, ctx: AppContext) -> ft.ResponseReturnValue:
    req = ctx.request
    if req.routing_exception is not None:
        self.raise_routing_exception(req)
    rule: Rule = req.url_rule
    if getattr(rule, 'provide_automatic_options', False) and req.method == 'OPTIONS':
        return self.make_default_options_response(ctx)
    view_args: dict[str, t.Any] = req.view_args
    return self.ensure_sync(self.view_functions[rule.endpoint])(**view_args)

def full_dispatch_request(self, ctx: AppContext) -> Response:
    if not self._got_first_request and self.should_ignore_error is not None:
        import warnings
        warnings.warn("The 'should_ignore_error' method is deprecated and will be removed in Flask 3.3. Handle errors as needed in teardown handlers instead.", DeprecationWarning, stacklevel=1)
    self._got_first_request = True
    try:
        request_started.send(self, _async_wrapper=self.ensure_sync)
        rv = self.preprocess_request(ctx)
        if rv is None:
            rv = self.dispatch_request(ctx)
    except Exception as e:
        rv = self.handle_user_exception(ctx, e)
    return self.finalize_request(ctx, rv)

def finalize_request(self, ctx: AppContext, rv: ft.ResponseReturnValue | HTTPException, from_error_handler: bool=False) -> Response:
    response = self.make_response(rv)
    try:
        response = self.process_response(ctx, response)
        request_finished.send(self, _async_wrapper=self.ensure_sync, response=response)
    except Exception:
        if not from_error_handler:
            raise
        self.logger.exception('Request finalizing failed with an error while handling an error')
    return response

def ensure_sync(self, func: t.Callable[..., t.Any]) -> t.Callable[..., t.Any]:
    if iscoroutinefunction(func):
        return self.async_to_sync(func)
    return func

def async_to_sync(self, func: t.Callable[..., t.Coroutine[t.Any, t.Any, t.Any]]) -> t.Callable[..., t.Any]:
    try:
        from asgiref.sync import async_to_sync as asgiref_async_to_sync
    except ImportError:
        raise RuntimeError("Install Flask with the 'async' extra in order to use async views.") from None
    return asgiref_async_to_sync(func)

def url_for(self, /, endpoint: str, *, _anchor: str | None=None, _method: str | None=None, _scheme: str | None=None, _external: bool | None=None, **values: t.Any) -> str:
    if (ctx := _cv_app.get(None)) is not None and ctx.has_request:
        url_adapter = ctx.url_adapter
        blueprint_name = ctx.request.blueprint
        if endpoint[:1] == '.':
            if blueprint_name is not None:
                endpoint = f'{blueprint_name}{endpoint}'
            else:
                endpoint = endpoint[1:]
        if _external is None:
            _external = _scheme is not None
    else:
        if ctx is not None:
            url_adapter = ctx.url_adapter
        else:
            url_adapter = self.create_url_adapter(None)
        if url_adapter is None:
            raise RuntimeError("Unable to build URLs outside an active request without 'SERVER_NAME' configured. Also configure 'APPLICATION_ROOT' and 'PREFERRED_URL_SCHEME' as needed.")
        if _external is None:
            _external = True
    if _scheme is not None and (not _external):
        raise ValueError("When specifying '_scheme', '_external' must be True.")
    self.inject_url_defaults(endpoint, values)
    try:
        rv = url_adapter.build(endpoint, values, method=_method, url_scheme=_scheme, force_external=_external)
    except BuildError as error:
        values.update(_anchor=_anchor, _method=_method, _scheme=_scheme, _external=_external)
        return self.handle_url_build_error(error, endpoint, values)
    if _anchor is not None:
        _anchor = _url_quote(_anchor, safe="%!#$&'()*+,/:;=?@")
        rv = f'{rv}#{_anchor}'
    return rv

def make_response(self, rv: ft.ResponseReturnValue) -> Response:
    status: int | None = None
    headers: HeadersValue | None = None
    if isinstance(rv, tuple):
        len_rv = len(rv)
        if len_rv == 3:
            rv, status, headers = rv
        elif len_rv == 2:
            if isinstance(rv[1], (Headers, dict, tuple, list)):
                rv, headers = rv
            else:
                rv, status = rv
        else:
            raise TypeError('The view function did not return a valid response tuple. The tuple must have the form (body, status, headers), (body, status), or (body, headers).')
    if rv is None:
        raise TypeError(f'The view function for {request.endpoint!r} did not return a valid response. The function either returned None or ended without a return statement.')
    if not isinstance(rv, self.response_class):
        if isinstance(rv, (str, bytes, bytearray)) or isinstance(rv, cabc.Iterator):
            rv = self.response_class(rv, status=status, headers=headers)
            status = headers = None
        elif isinstance(rv, (dict, list)):
            rv = self.json.response(rv)
        elif isinstance(rv, BaseResponse) or callable(rv):
            try:
                rv = self.response_class.force_type(rv, request.environ)
            except TypeError as e:
                raise TypeError(f'{e}\nThe view function did not return a valid response. The return type must be a string, dict, list, tuple with headers or status, Response instance, or WSGI callable, but it was a {type(rv).__name__}.').with_traceback(sys.exc_info()[2]) from None
        else:
            raise TypeError(f'The view function did not return a valid response. The return type must be a string, dict, list, tuple with headers or status, Response instance, or WSGI callable, but it was a {type(rv).__name__}.')
    rv = t.cast(Response, rv)
    if status is not None:
        if isinstance(status, (str, bytes, bytearray)):
            rv.status = status
        else:
            rv.status_code = status
    if headers:
        rv.headers.update(headers)
    return rv

def preprocess_request(self, ctx: AppContext) -> ft.ResponseReturnValue | None:
    req = ctx.request
    names = (None, *reversed(req.blueprints))
    for name in names:
        if name in self.url_value_preprocessors:
            for url_func in self.url_value_preprocessors[name]:
                url_func(req.endpoint, req.view_args)
    for name in names:
        if name in self.before_request_funcs:
            for before_func in self.before_request_funcs[name]:
                rv = self.ensure_sync(before_func)()
                if rv is not None:
                    return rv
    return None

def process_response(self, ctx: AppContext, response: Response) -> Response:
    for func in ctx._after_request_functions:
        response = self.ensure_sync(func)(response)
    for name in chain(ctx.request.blueprints, (None,)):
        if name in self.after_request_funcs:
            for func in reversed(self.after_request_funcs[name]):
                response = self.ensure_sync(func)(response)
    if not self.session_interface.is_null_session(ctx._get_session()):
        self.session_interface.save_session(self, ctx._get_session(), response)
    return response

def do_teardown_request(self, ctx: AppContext, exc: BaseException | None=None) -> None:
    collect_errors = _CollectErrors()
    for name in chain(ctx.request.blueprints, (None,)):
        if name in self.teardown_request_funcs:
            for func in reversed(self.teardown_request_funcs[name]):
                with collect_errors:
                    self.ensure_sync(func)(exc)
    with collect_errors:
        request_tearing_down.send(self, _async_wrapper=self.ensure_sync, exc=exc)
    collect_errors.raise_any('Errors during request teardown')

