def find_best_app(module: ModuleType) -> Flask:
    from . import Flask
    for attr_name in ('app', 'application'):
        app = getattr(module, attr_name, None)
        if isinstance(app, Flask):
            return app
    matches = [v for v in module.__dict__.values() if isinstance(v, Flask)]
    if len(matches) == 1:
        return matches[0]
    elif len(matches) > 1:
        raise NoAppException(f"Detected multiple Flask applications in module '{module.__name__}'. Use '{module.__name__}:name' to specify the correct one.")
    for attr_name in ('create_app', 'make_app'):
        app_factory = getattr(module, attr_name, None)
        if inspect.isfunction(app_factory):
            try:
                app = app_factory()
                if isinstance(app, Flask):
                    return app
            except TypeError as e:
                if not _called_with_wrong_args(app_factory):
                    raise
                raise NoAppException(f"Detected factory '{attr_name}' in module '{module.__name__}', but could not call it without arguments. Use '{module.__name__}:{attr_name}(args)' to specify arguments.") from e
    raise NoAppException(f"Failed to find Flask application or factory in module '{module.__name__}'. Use '{module.__name__}:name' to specify one.")

def _called_with_wrong_args(f: t.Callable[..., Flask]) -> bool:
    tb = sys.exc_info()[2]
    try:
        while tb is not None:
            if tb.tb_frame.f_code is f.__code__:
                return False
            tb = tb.tb_next
        return True
    finally:
        del tb

def find_app_by_string(module: ModuleType, app_name: str) -> Flask:
    from . import Flask
    try:
        expr = ast.parse(app_name.strip(), mode='eval').body
    except SyntaxError:
        raise NoAppException(f'Failed to parse {app_name!r} as an attribute name or function call.') from None
    if isinstance(expr, ast.Name):
        name = expr.id
        args = []
        kwargs = {}
    elif isinstance(expr, ast.Call):
        if not isinstance(expr.func, ast.Name):
            raise NoAppException(f'Function reference must be a simple name: {app_name!r}.')
        name = expr.func.id
        try:
            args = [ast.literal_eval(arg) for arg in expr.args]
            kwargs = {kw.arg: ast.literal_eval(kw.value) for kw in expr.keywords if kw.arg is not None}
        except ValueError:
            raise NoAppException(f'Failed to parse arguments as literal values: {app_name!r}.') from None
    else:
        raise NoAppException(f'Failed to parse {app_name!r} as an attribute name or function call.')
    try:
        attr = getattr(module, name)
    except AttributeError as e:
        raise NoAppException(f'Failed to find attribute {name!r} in {module.__name__!r}.') from e
    if inspect.isfunction(attr):
        try:
            app = attr(*args, **kwargs)
        except TypeError as e:
            if not _called_with_wrong_args(attr):
                raise
            raise NoAppException(f'The factory {app_name!r} in module {module.__name__!r} could not be called with the specified arguments.') from e
    else:
        app = attr
    if isinstance(app, Flask):
        return app
    raise NoAppException(f"A valid Flask application was not obtained from '{module.__name__}:{app_name}'.")

def prepare_import(path: str) -> str:
    path = os.path.realpath(path)
    fname, ext = os.path.splitext(path)
    if ext == '.py':
        path = fname
    if os.path.basename(path) == '__init__':
        path = os.path.dirname(path)
    module_name = []
    while True:
        path, name = os.path.split(path)
        module_name.append(name)
        if not os.path.exists(os.path.join(path, '__init__.py')):
            break
    if sys.path[0] != path:
        sys.path.insert(0, path)
    return '.'.join(module_name[::-1])

def with_appcontext(f: F) -> F:

    @click.pass_context
    def decorator(ctx: click.Context, /, *args: t.Any, **kwargs: t.Any) -> t.Any:
        if not current_app:
            app = ctx.ensure_object(ScriptInfo).load_app()
            ctx.with_resource(app.app_context())
        return ctx.invoke(f, *args, **kwargs)
    return update_wrapper(decorator, f)

def load_dotenv(path: str | os.PathLike[str] | None=None, load_defaults: bool=True) -> bool:
    try:
        import dotenv
    except ImportError:
        if path or os.path.isfile('.env') or os.path.isfile('.flaskenv'):
            click.secho(' * Tip: There are .env files present. Install python-dotenv to use them.', fg='yellow', err=True)
        return False
    data: dict[str, str | None] = {}
    if load_defaults:
        for default_name in ('.flaskenv', '.env'):
            if not (default_path := dotenv.find_dotenv(default_name, usecwd=True)):
                continue
            data |= dotenv.dotenv_values(default_path, encoding='utf-8')
    if path is not None and os.path.isfile(path):
        data |= dotenv.dotenv_values(path, encoding='utf-8')
    for key, value in data.items():
        if key in os.environ or value is None:
            continue
        os.environ[key] = value
    return bool(data)

def show_server_banner(debug: bool, app_import_path: str | None) -> None:
    if is_running_from_reloader():
        return
    if app_import_path is not None:
        click.echo(f" * Serving Flask app '{app_import_path}'")
    if debug is not None:
        click.echo(f" * Debug mode: {('on' if debug else 'off')}")

def _validate_key(ctx: click.Context, param: click.Parameter, value: t.Any) -> t.Any:
    cert = ctx.params.get('cert')
    is_adhoc = cert == 'adhoc'
    try:
        import ssl
    except ImportError:
        is_context = False
    else:
        is_context = isinstance(cert, ssl.SSLContext)
    if value is not None:
        if is_adhoc:
            raise click.BadParameter('When "--cert" is "adhoc", "--key" is not used.', ctx, param)
        if is_context:
            raise click.BadParameter('When "--cert" is an SSLContext object, "--key" is not used.', ctx, param)
        if not cert:
            raise click.BadParameter('"--cert" must also be specified.', ctx, param)
        ctx.params['cert'] = (cert, value)
    elif cert and (not (is_adhoc or is_context)):
        raise click.BadParameter('Required when using "--cert".', ctx, param)
    return value

def load_app(self) -> Flask:
    if self._loaded_app is not None:
        return self._loaded_app
    app: Flask | None = None
    if self.create_app is not None:
        app = self.create_app()
    elif self.app_import_path:
        path, name = (re.split(':(?![\\\\/])', self.app_import_path, maxsplit=1) + [None])[:2]
        import_name = prepare_import(path)
        app = locate_app(import_name, name)
    else:
        for path in ('wsgi.py', 'app.py'):
            import_name = prepare_import(path)
            app = locate_app(import_name, None, raise_if_not_found=False)
            if app is not None:
                break
    if app is None:
        raise NoAppException("Could not locate a Flask application. Use the 'flask --app' option, 'FLASK_APP' environment variable, or a 'wsgi.py' or 'app.py' file in the current directory.")
    if self.set_debug_flag:
        app.debug = get_debug_flag()
    self._loaded_app = app
    return app

def command(self, *args: t.Any, **kwargs: t.Any) -> t.Callable[[t.Callable[..., t.Any]], click.Command]:
    wrap_for_ctx = kwargs.pop('with_appcontext', True)

    def decorator(f: t.Callable[..., t.Any]) -> click.Command:
        if wrap_for_ctx:
            f = with_appcontext(f)
        return super(AppGroup, self).command(*args, **kwargs)(f)
    return decorator

def group(self, *args: t.Any, **kwargs: t.Any) -> t.Callable[[t.Callable[..., t.Any]], click.Group]:
    kwargs.setdefault('cls', AppGroup)
    return super().group(*args, **kwargs)

def from_envvar(self, variable_name: str, silent: bool=False) -> bool:
    rv = os.environ.get(variable_name)
    if not rv:
        if silent:
            return False
        raise RuntimeError(f'The environment variable {variable_name!r} is not set and as such configuration could not be loaded. Set this variable and make it point to a configuration file')
    return self.from_pyfile(rv, silent=silent)

def from_prefixed_env(self, prefix: str='FLASK', *, loads: t.Callable[[str], t.Any]=json.loads) -> bool:
    prefix = f'{prefix}_'
    for key in sorted(os.environ):
        if not key.startswith(prefix):
            continue
        value = os.environ[key]
        key = key.removeprefix(prefix)
        try:
            value = loads(value)
        except Exception:
            pass
        if '__' not in key:
            self[key] = value
            continue
        current = self
        *parts, tail = key.split('__')
        for part in parts:
            if part not in current:
                current[part] = {}
            current = current[part]
        current[tail] = value
    return True

def from_object(self, obj: object | str) -> None:
    if isinstance(obj, str):
        obj = import_string(obj)
    for key in dir(obj):
        if key.isupper():
            self[key] = getattr(obj, key)

def from_file(self, filename: str | os.PathLike[str], load: t.Callable[[t.IO[t.Any]], t.Mapping[str, t.Any]], silent: bool=False, text: bool=True) -> bool:
    filename = os.path.join(self.root_path, filename)
    try:
        with open(filename, 'r' if text else 'rb') as f:
            obj = load(f)
    except OSError as e:
        if silent and e.errno in (errno.ENOENT, errno.EISDIR):
            return False
        e.strerror = f'Unable to load configuration file ({e.strerror})'
        raise
    return self.from_mapping(obj)

def from_mapping(self, mapping: t.Mapping[str, t.Any] | None=None, **kwargs: t.Any) -> bool:
    mappings: dict[str, t.Any] = {}
    if mapping is not None:
        mappings.update(mapping)
    mappings.update(kwargs)
    for key, value in mappings.items():
        if key.isupper():
            self[key] = value
    return True

def get_namespace(self, namespace: str, lowercase: bool=True, trim_namespace: bool=True) -> dict[str, t.Any]:
    rv = {}
    for k, v in self.items():
        if not k.startswith(namespace):
            continue
        if trim_namespace:
            key = k[len(namespace):]
        else:
            key = k
        if lowercase:
            key = key.lower()
        rv[key] = v
    return rv

