    names: t.Iterable[str | None] = (None,)
    if '.' in endpoint:
        names = chain(names, reversed(_split_blueprint_path(endpoint.rpartition('.')[0])))
    for name in names:
        if name in self.url_default_functions:
            for func in self.url_default_functions[name]:
                func(endpoint, values)

def handle_url_build_error(self, error: BuildError, endpoint: str, values: dict[str, t.Any]) -> str:
    for handler in self.url_build_error_handlers:
        try:
            rv = handler(error, endpoint, values)
        except BuildError as e:
            error = e
        else:
            if rv is not None:
                return rv
    if error is sys.exc_info()[1]:
        raise
    raise error

def add_url_rule(self, rule: str, endpoint: str | None=None, view_func: ft.RouteCallable | None=None, **options: t.Any) -> None:
    if self.url_prefix is not None:
        if rule:
            rule = '/'.join((self.url_prefix.rstrip('/'), rule.lstrip('/')))
        else:
            rule = self.url_prefix
    options.setdefault('subdomain', self.subdomain)
    if endpoint is None:
        endpoint = _endpoint_from_view_func(view_func)
    defaults = self.url_defaults
    if 'defaults' in options:
        defaults = dict(defaults, **options.pop('defaults'))
    self.app.add_url_rule(rule, f'{self.name_prefix}.{self.name}.{endpoint}'.lstrip('.'), view_func, defaults=defaults, **options)

