        elif sys.platform.startswith('win'):
            base_ext = '.dll'
        libname_ext = [libname + base_ext]
        so_ext = sysconfig.get_config_var('EXT_SUFFIX')
        if not so_ext == base_ext:
            libname_ext.insert(0, libname + so_ext)
    else:
        libname_ext = [libname]
    loader_path = os.path.abspath(loader_path)
    if not os.path.isdir(loader_path):
        libdir = os.path.dirname(loader_path)
    else:
        libdir = loader_path
    for ln in libname_ext:
        libpath = os.path.join(libdir, ln)
        if os.path.exists(libpath):
            try:
                return ctypes.cdll[libpath]
            except OSError:
                raise
    raise OSError('no file with expected extension')

@property
def contents(self):
    full_dtype = np.dtype((self._dtype_, self._shape_))
    full_ctype = ctypes.c_char * full_dtype.itemsize
    buffer = ctypes.cast(self, ctypes.POINTER(full_ctype)).contents
    return np.frombuffer(buffer, dtype=full_dtype).squeeze(axis=0)

def _ctype_ndarray(element_type, shape):
    for dim in shape[::-1]:
        element_type = dim * element_type
        element_type.__module__ = None
    return element_type

def _get_scalar_type_map():
    ct = ctypes
    simple_types = [ct.c_byte, ct.c_short, ct.c_int, ct.c_long, ct.c_longlong, ct.c_ubyte, ct.c_ushort, ct.c_uint, ct.c_ulong, ct.c_ulonglong, ct.c_float, ct.c_double, ct.c_bool]
    return {np.dtype(ctype): ctype for ctype in simple_types}

@set_module('numpy.ctypeslib')
def as_ctypes_type(dtype):
    return _ctype_from_dtype(np.dtype(dtype))

@set_module('numpy.ctypeslib')
def as_array(obj, shape=None):
    if isinstance(obj, ctypes._Pointer):
        if shape is None:
            raise TypeError('as_array() requires a shape argument when called on a pointer')
        p_arr_type = ctypes.POINTER(_ctype_ndarray(obj._type_, shape))
        obj = ctypes.cast(obj, p_arr_type).contents
    return np.asarray(obj)

@set_module('numpy.ctypeslib')
def as_ctypes(obj):
    ai = obj.__array_interface__
    if ai['strides']:
        raise TypeError('strided arrays not supported')
    if ai['version'] != 3:
        raise TypeError('only __array_interface__ version 3 supported')
    addr, readonly = ai['data']
    if readonly:
        raise TypeError('readonly arrays unsupported')
    ctype_scalar = as_ctypes_type(ai['typestr'])
    result_type = _ctype_ndarray(ctype_scalar, ai['shape'])
    result = result_type.from_address(addr)
    result.__keep = obj
    return result

def process_f2cmap_dict(f2cmap_all, new_map, c2py_map, verbose=False):
    f2cmap_mapped = []
    new_map_lower = {}
    for k, d1 in new_map.items():
        d1_lower = {k1.lower(): v1 for k1, v1 in d1.items()}
        new_map_lower[k.lower()] = d1_lower
    for k, d1 in new_map_lower.items():
        if k not in f2cmap_all:
            f2cmap_all[k] = {}
        for k1, v1 in d1.items():
            if v1 in c2py_map:
                if k1 in f2cmap_all[k]:
                    outmess(f"\tWarning: redefinition of {{'{k}':{{'{k1}':'{f2cmap_all[k][k1]}'->'{v1}'}}}}\n")
                f2cmap_all[k][k1] = v1
                if verbose:
                    outmess(f'\tMapping "{k}(kind={k1})" to "{v1}"\n')
                f2cmap_mapped.append(v1)
            elif verbose:
                c2py_map_keys = list(c2py_map.keys())
                errmess(f"\tIgnoring map {{'{k}':{{'{k1}':'{v1}'}}}}: '{v1}' must be in {c2py_map_keys}\n")
    return (f2cmap_all, f2cmap_mapped)

def getctype(var):
    ctype = 'void'
    if isfunction(var):
        if 'result' in var:
            a = var['result']
        else:
            a = var['name']
        if a in var['vars']:
            return getctype(var['vars'][a])
        else:
            errmess(f'getctype: function {a} has no return value?!\n')
    elif issubroutine(var):
        return ctype
    elif ischaracter_or_characterarray(var):
        return 'character'
    elif isstring_or_stringarray(var):
        return 'string'
    elif 'typespec' in var and var['typespec'].lower() in f2cmap_all:
        typespec = var['typespec'].lower()
        f2cmap = f2cmap_all[typespec]
        ctype = f2cmap['']
        if 'kindselector' in var:
            if '*' in var['kindselector']:
                try:
                    ctype = f2cmap[var['kindselector']['*']]
                except KeyError:
                    raw_typespec = var['typespec']
                    star = var['kindselector']['*']
                    errmess(f'getctype: "{raw_typespec} * {star}" not supported.\n')
            elif 'kind' in var['kindselector']:
                if typespec + 'kind' in f2cmap_all:
                    f2cmap = f2cmap_all[typespec + 'kind']
                try:
                    ctype = f2cmap[var['kindselector']['kind']]
                except KeyError:
                    if typespec in f2cmap_all:
                        f2cmap = f2cmap_all[typespec]
                    try:
                        ctype = f2cmap[str(var['kindselector']['kind'])]
                    except KeyError:
                        kind = var['kindselector']['kind']
                        errmess(f'getctype: "{typespec}(kind={kind!r})" is mapped to C "{ctype}" (to override define {{{typespec!r}: {{{kind!r}: "<C typespec>"}}}} in {os.getcwd()}/.f2py_f2cmap file).\n')
    elif not isexternal(var):
        errmess(f'getctype: No C-type found in "{var}", assuming void.\n')
    return ctype

def f2cexpr(expr):
    expr = re.sub('\\blen\\b', 'f2py_slen', expr)
    return expr

def sign2map(a, var):
    out_a = a
    if isintent_out(var):
        for k in var['intent']:
            if k[:4] == 'out=':
                out_a = k[4:]
                break
    ret = {'varname': a, 'outvarname': out_a, 'ctype': getctype(var)}
    intent_flags = []
    for f, s in isintent_dict.items():
        if f(var):
            intent_flags.append(f'F2PY_{s}')
    if intent_flags:
        ret['intent'] = '|'.join(intent_flags)
    else:
        ret['intent'] = 'F2PY_INTENT_IN'
    if isarray(var):
        ret['varrformat'] = 'N'
    elif ret['ctype'] in c2buildvalue_map:
        ret['varrformat'] = c2buildvalue_map[ret['ctype']]
    else:
        ret['varrformat'] = 'O'
    ret['init'], ret['showinit'] = getinit(a, var)
    if hasinitvalue(var) and iscomplex(var) and (not isarray(var)):
        ret['init.r'], ret['init.i'] = markoutercomma(ret['init'][1:-1]).split('@,@')
    if isexternal(var):
        ret['cbnamekey'] = a
        if a in lcb_map:
            ret['cbname'] = lcb_map[a]
            ret['maxnofargs'] = lcb2_map[lcb_map[a]]['maxnofargs']
            ret['nofoptargs'] = lcb2_map[lcb_map[a]]['nofoptargs']
            ret['cbdocstr'] = lcb2_map[lcb_map[a]]['docstr']
            ret['cblatexdocstr'] = lcb2_map[lcb_map[a]]['latexdocstr']
        else:
            ret['cbname'] = a
            lcb_map_keys = list(lcb_map.keys())
            errmess(f'sign2map: Confused: external {a} is not in lcb_map{lcb_map_keys}.\n')
    if isstring(var):
        ret['length'] = getstrlength(var)
    if isarray(var):
        ret = dictappend(ret, getarrdims(a, var))
        dim = copy.copy(var['dimension'])
    if ret['ctype'] in c2capi_map:
        ret['atype'] = c2capi_map[ret['ctype']]
        ret['elsize'] = get_elsize(var)
    if debugcapi(var):
        il = [isintent_in, 'input', isintent_out, 'output', isintent_inout, 'inoutput', isrequired, 'required', isoptional, 'optional', isintent_hide, 'hidden', iscomplex, 'complex scalar', l_and(isscalar, l_not(iscomplex)), 'scalar', isstring, 'string', isarray, 'array', iscomplexarray, 'complex array', isstringarray, 'string array', iscomplexfunction, 'complex function', l_and(isfunction, l_not(iscomplexfunction)), 'function', isexternal, 'callback', isintent_callback, 'callback', isintent_aux, 'auxiliary']
        rl = []
        for i in range(0, len(il), 2):
            if il[i](var):
                rl.append(il[i + 1])
        if isstring(var):
            rl.append(f"slen({a})={ret['length']}")
        if isarray(var):
            ddim = ','.join(map(lambda x, y: f'{x}|{y}', var['dimension'], dim))
            rl.append(f'dims({ddim})')
        rl_str = ','.join(rl)
        if isexternal(var):
            ret['vardebuginfo'] = f"debug-capi:{a}=>{ret['cbname']}:{rl_str}"
        else:
            ret['vardebuginfo'] = f"debug-capi:{ret['ctype']} {a}={ret['showinit']}:{rl_str}"
        if isscalar(var):
            if ret['ctype'] in cformat_map:
                ret['vardebugshowvalue'] = f"debug-capi:{a}={cformat_map[ret['ctype']]}"
        if isstring(var):
            ret['vardebugshowvalue'] = f'debug-capi:slen({a})=%d {a}=\\"%s\\"'
        if isexternal(var):
            ret['vardebugshowvalue'] = f'debug-capi:{a}=%p'
    if ret['ctype'] in cformat_map:
        ret['varshowvalue'] = f"#name#:{a}={cformat_map[ret['ctype']]}"
        ret['showvalueformat'] = f"{cformat_map[ret['ctype']]}"
    if isstring(var):
        ret['varshowvalue'] = f'#name#:slen({a})=%d {a}=\\"%s\\"'
    ret['pydocsign'], ret['pydocsignout'] = getpydocsign(a, var)
    if hasnote(var):
        ret['note'] = var['note']
    return ret

def routsign2map(rout):
    global lcb_map
    name = rout['name']
    fname = getfortranname(rout)
    ret = {'name': name, 'texname': name.replace('_', '\\_'), 'name_lower': name.lower(), 'NAME': name.upper(), 'begintitle': gentitle(name), 'endtitle': gentitle(f'end of {name}'), 'fortranname': fname, 'FORTRANNAME': fname.upper(), 'callstatement': getcallstatement(rout) or '', 'usercode': getusercode(rout) or '', 'usercode1': getusercode1(rout) or ''}
    if '_' in fname:
        ret['F_FUNC'] = 'F_FUNC_US'
    else:
        ret['F_FUNC'] = 'F_FUNC'
    if '_' in name:
        ret['F_WRAPPEDFUNC'] = 'F_WRAPPEDFUNC_US'
    else:
        ret['F_WRAPPEDFUNC'] = 'F_WRAPPEDFUNC'
    lcb_map = {}
    if 'use' in rout:
        for u in rout['use'].keys():
            if u in cb_rules.cb_map:
                for un in cb_rules.cb_map[u]:
                    ln = un[0]
                    if 'map' in rout['use'][u]:
                        for k in rout['use'][u]['map'].keys():
                            if rout['use'][u]['map'][k] == un[0]:
                                ln = k
                                break
                    lcb_map[ln] = un[1]
    elif rout.get('externals'):
        externals = rout['externals']
        errmess(f"""routsign2map: Confused: function {ret['name']} has externals {externals!r} but no "use" statement.\n""")
    ret['callprotoargument'] = getcallprotoargument(rout, lcb_map) or ''
    if isfunction(rout):
        if 'result' in rout:
            a = rout['result']
        else:
            a = rout['name']
        ret['rname'] = a
        ret['pydocsign'], ret['pydocsignout'] = getpydocsign(a, rout)
        ret['ctype'] = getctype(rout['vars'][a])
        if hasresultnote(rout):
            ret['resultnote'] = rout['vars'][a]['note']
            rout['vars'][a]['note'] = ['See elsewhere.']
        if ret['ctype'] in c2buildvalue_map:
            ret['rformat'] = c2buildvalue_map[ret['ctype']]
        else:
            ret['rformat'] = 'O'
            errmess(f"routsign2map: no c2buildvalue key for type {ret['ctype']!r}\n")
        if debugcapi(rout):
            if ret['ctype'] in cformat_map:
                ret['routdebugshowvalue'] = f"debug-capi:{a}={cformat_map[ret['ctype']]}"
            if isstringfunction(rout):
                ret['routdebugshowvalue'] = f'debug-capi:slen({a})=%d {a}=\\"%s\\"'
        if isstringfunction(rout):
            ret['rlength'] = getstrlength(rout['vars'][a])
            if ret['rlength'] == '-1':
                errmess(f"routsign2map: expected explicit specification of the length of the string returned by the fortran function {rout['name']!r}; taking 10.\n")
                ret['rlength'] = '10'
    if hasnote(rout):
        ret['note'] = rout['note']
        rout['note'] = ['See elsewhere.']
    return ret

