def __getitem__(self, index):
    if not isinstance(index, tuple):
        index = (index,)
    fixed = []
    length, dims = (len(index), self.ndim)
    for slice_ in index:
        if slice_ is Ellipsis:
            fixed.extend([slice(None)] * (dims - length + 1))
            length = len(fixed)
        elif isinstance(slice_, int):
            fixed.append(slice(slice_, slice_ + 1, 1))
        else:
            fixed.append(slice_)
    index = tuple(fixed)
    if len(index) < dims:
        index += (slice(None),) * (dims - len(index))
    out = self.__class__(self.var, self.buf_size)
    for i, (start, stop, step, slice_) in enumerate(zip(self.start, self.stop, self.step, index)):
        out.start[i] = start + (slice_.start or 0)
        out.step[i] = step * (slice_.step or 1)
        out.stop[i] = start + (slice_.stop or stop - start)
        out.stop[i] = min(stop, out.stop[i])
    return out

def __array__(self, dtype=None, copy=None):
    slice_ = tuple((slice(*t) for t in zip(self.start, self.stop, self.step)))
    return self.var[slice_]

@property
def flat(self):
    for block in self:
        yield from block.flat

@property
def shape(self):
    return tuple(((stop - start - 1) // step + 1 for start, stop, step in zip(self.start, self.stop, self.step)))

@set_module('numpy.lib.array_utils')
def byte_bounds(a):
    ai = a.__array_interface__
    a_data = ai['data'][0]
    astrides = ai['strides']
    ashape = ai['shape']
    bytes_a = asarray(a).dtype.itemsize
    a_low = a_high = a_data
    if astrides is None:
        a_high += a.size * bytes_a
    else:
        for shape, stride in zip(ashape, astrides):
            if stride < 0:
                a_low += (shape - 1) * stride
            else:
                a_high += (shape - 1) * stride
        a_high += bytes_a
    return (a_low, a_high)

def _check_mode(mode, encoding, newline):
    if 't' in mode:
