@array_function_dispatch(_i0_dispatcher)
def i0(x):
    x = np.asanyarray(x)
    if x.dtype.kind == 'c':
        raise TypeError('i0 not supported for complex values')
    if x.dtype.kind != 'f':
        x = x.astype(float)
    x = np.abs(x)
    return piecewise(x, [x <= 8.0], [_i0_1, _i0_2])

@set_module('numpy')
def kaiser(M, beta):
    values = np.array([0.0, M, beta])
    M = values[1]
    beta = values[2]
    if M == 1:
        return np.ones(1, dtype=values.dtype)
    n = arange(0, M)
    alpha = (M - 1) / 2.0
    return i0(beta * sqrt(1 - ((n - alpha) / alpha) ** 2.0)) / i0(beta)

def _ureduce(a, func, keepdims=False, **kwargs):
    a = np.asanyarray(a)
    axis = kwargs.get('axis')
    out = kwargs.get('out')
    if keepdims is np._NoValue:
        keepdims = False
    nd = a.ndim
    if axis is not None:
        axis = _nx.normalize_axis_tuple(axis, nd)
        if keepdims and out is not None:
            index_out = tuple((0 if i in axis else slice(None) for i in range(nd)))
            kwargs['out'] = out[(Ellipsis,) + index_out]
        if len(axis) == 1:
            kwargs['axis'] = axis[0]
        else:
            keep = sorted(set(range(nd)) - set(axis))
            nkeep = len(keep)

            def reshape_arr(a):
                a = np.moveaxis(a, keep, range(nkeep))
                return a.reshape(a.shape[:nkeep] + (-1,))
            a = reshape_arr(a)
            weights = kwargs.get('weights')
            if weights is not None:
                kwargs['weights'] = reshape_arr(weights)
            kwargs['axis'] = -1
    elif keepdims and out is not None:
        index_out = (0,) * nd
        kwargs['out'] = out[(Ellipsis,) + index_out]
    r = func(a, **kwargs)
    if out is not None:
        return out
    if keepdims:
        if axis is None:
            index_r = (np.newaxis,) * nd
        else:
            index_r = tuple((np.newaxis if i in axis else slice(None) for i in range(nd)))
        r = r[(Ellipsis,) + index_r]
    return r

@array_function_dispatch(_median_dispatcher)
def median(a, axis=None, out=None, overwrite_input=False, keepdims=False):
    return _ureduce(a, func=_median, keepdims=keepdims, axis=axis, out=out, overwrite_input=overwrite_input)

@array_function_dispatch(_percentile_dispatcher)
def percentile(a, q, axis=None, out=None, overwrite_input=False, method='linear', keepdims=False, *, weights=None):
    a = np.asanyarray(a)
    if a.dtype.kind == 'c':
        raise TypeError('a must be an array of real numbers')
    weak_q = type(q) in (int, float)
    q = np.true_divide(q, 100, out=...)
    if not _quantile_is_valid(q):
        raise ValueError('Percentiles must be in the range [0, 100]')
    if weights is not None:
        if method != 'inverted_cdf':
            msg = f"Only method 'inverted_cdf' supports weights. Got: {method}."
            raise ValueError(msg)
        if axis is not None:
            axis = _nx.normalize_axis_tuple(axis, a.ndim, argname='axis')
        weights = _weights_are_valid(weights=weights, a=a, axis=axis)
        if np.any(weights < 0):
            raise ValueError('Weights must be non-negative.')
    return _quantile_unchecked(a, q, axis, out, overwrite_input, method, keepdims, weights, weak_q)

@array_function_dispatch(_quantile_dispatcher)
def quantile(a, q, axis=None, out=None, overwrite_input=False, method='linear', keepdims=False, *, weights=None):
    a = np.asanyarray(a)
    if a.dtype.kind == 'c':
        raise TypeError('a must be an array of real numbers')
    weak_q = type(q) in (int, float)
    q = np.asanyarray(q)
    if not _quantile_is_valid(q):
        raise ValueError('Quantiles must be in the range [0, 1]')
    if weights is not None:
        if method != 'inverted_cdf':
            msg = f"Only method 'inverted_cdf' supports weights. Got: {method}."
            raise ValueError(msg)
        if axis is not None:
            axis = _nx.normalize_axis_tuple(axis, a.ndim, argname='axis')
        weights = _weights_are_valid(weights=weights, a=a, axis=axis)
        if np.any(weights < 0):
            raise ValueError('Weights must be non-negative.')
    return _quantile_unchecked(a, q, axis, out, overwrite_input, method, keepdims, weights, weak_q)

def _get_gamma(virtual_indexes, previous_indexes, method):
    gamma = np.asanyarray(virtual_indexes - previous_indexes)
    gamma = method['fix_gamma'](gamma, virtual_indexes)
    return np.asanyarray(gamma, dtype=virtual_indexes.dtype)

def _get_indexes(arr, virtual_indexes, valid_values_count):
    previous_indexes = floor(virtual_indexes, out=...)
    next_indexes = add(previous_indexes, 1, out=...)
    indexes_above_bounds = virtual_indexes >= valid_values_count - 1
    if indexes_above_bounds.any():
        previous_indexes[indexes_above_bounds] = -1
        next_indexes[indexes_above_bounds] = -1
    indexes_below_bounds = virtual_indexes < 0
    if indexes_below_bounds.any():
        previous_indexes[indexes_below_bounds] = 0
        next_indexes[indexes_below_bounds] = 0
    if np.issubdtype(arr.dtype, np.inexact):
        virtual_indexes_nans = np.isnan(virtual_indexes)
        if virtual_indexes_nans.any():
            previous_indexes[virtual_indexes_nans] = -1
            next_indexes[virtual_indexes_nans] = -1
    previous_indexes = previous_indexes.astype(np.intp)
    next_indexes = next_indexes.astype(np.intp)
    return (previous_indexes, next_indexes)

def _quantile(arr: 'np.typing.ArrayLike', quantiles: np.ndarray, axis: int=-1, method: str='linear', out: np.ndarray | None=None, weights: 'np.typing.ArrayLike | None'=None, weak_q: bool=False) -> np.ndarray:
    arr = np.asanyarray(arr)
    values_count = arr.shape[axis]
    if axis != 0:
        arr = np.moveaxis(arr, axis, destination=0)
    supports_nans = np.issubdtype(arr.dtype, np.inexact) or arr.dtype.kind in 'Mm'
    if weights is None:
        try:
            method_props = _QuantileMethods[method]
        except KeyError:
            raise ValueError(f'{method!r} is not a valid method. Use one of: {_QuantileMethods.keys()}') from None
        virtual_indexes = method_props['get_virtual_index'](values_count, quantiles)
        virtual_indexes = np.asanyarray(virtual_indexes)
        if method_props['fix_gamma'] is None:
            supports_integers = True
        else:
            int_virtual_indices = np.issubdtype(virtual_indexes.dtype, np.integer)
            supports_integers = method == 'linear' and int_virtual_indices
        if supports_integers:
            if supports_nans:
                arr.partition(concatenate((virtual_indexes.ravel(), [-1])), axis=0)
                slices_having_nans = np.isnan(arr[-1, ...])
            else:
                arr.partition(virtual_indexes.ravel(), axis=0)
                slices_having_nans = np.array(False, dtype=bool)
            result = take(arr, virtual_indexes, axis=0, out=out)
        else:
            previous_indexes, next_indexes = _get_indexes(arr, virtual_indexes, values_count)
            arr.partition(np.unique(np.concatenate(([0, -1], previous_indexes.ravel(), next_indexes.ravel()))), axis=0)
            if supports_nans:
                slices_having_nans = np.isnan(arr[-1, ...])
            else:
                slices_having_nans = None
            previous = arr[previous_indexes]
            next = arr[next_indexes]
            gamma = _get_gamma(virtual_indexes, previous_indexes, method_props)
            if weak_q:
                gamma = float(gamma)
            else:
                result_shape = virtual_indexes.shape + (1,) * (arr.ndim - 1)
                gamma = gamma.reshape(result_shape)
            result = _lerp(previous, next, gamma, out=out)
    else:
        weights = np.asanyarray(weights)
        if axis != 0:
            weights = np.moveaxis(weights, axis, destination=0)
        index_array = np.argsort(arr, axis=0)
        arr = np.take_along_axis(arr, index_array, axis=0)
        if weights.shape == arr.shape:
            weights = np.take_along_axis(weights, index_array, axis=0)
        else:
            weights = weights.reshape(-1)[index_array, ...]
        if supports_nans:
            slices_having_nans = np.isnan(arr[-1, ...])
        else:
            slices_having_nans = np.array(False, dtype=bool)
        cdf = weights.cumsum(axis=0, dtype=np.float64)
        cdf /= cdf[-1, ...]
        if np.isnan(cdf[-1]).any():
            raise ValueError('Weights included NaN, inf or were all zero.')
        if quantiles.dtype.kind == 'f':
            cdf = cdf.astype(quantiles.dtype)
        if np.any(cdf[0, ...] == 0):
            cdf[cdf == 0] = -1

        def find_cdf_1d(arr, cdf):
            indices = np.searchsorted(cdf, quantiles, side='left')
            indices = minimum(indices, values_count - 1)
            result = take(arr, indices, axis=0)
            return result
        r_shape = arr.shape[1:]
        if quantiles.ndim > 0:
            r_shape = quantiles.shape + r_shape
        if out is None:
            result = np.empty_like(arr, shape=r_shape)
        else:
            if out.shape != r_shape:
                msg = f"Wrong shape of argument 'out', shape={r_shape} is required; got shape={out.shape}."
                raise ValueError(msg)
            result = out
        Nk = arr.shape[1:]
        for kk in np.ndindex(Nk):
            result[(...,) + kk] = find_cdf_1d(arr[np.s_[:,] + kk], cdf[np.s_[:,] + kk])
        if result.shape == () and result.dtype == np.dtype('O'):
            result = result.item()
    if np.any(slices_having_nans):
        if result.ndim == 0 and out is None:
            result = arr[-1]
        else:
            np.copyto(result, arr[-1, ...], where=slices_having_nans)
    return result

@array_function_dispatch(_trapezoid_dispatcher)
def trapezoid(y, x=None, dx=1.0, axis=-1):
    y = asanyarray(y)
    if x is None:
        d = dx
    else:
        x = asanyarray(x)
        if x.ndim == 1:
            d = diff(x)
            shape = [1] * y.ndim
            shape[axis] = d.shape[0]
            d = d.reshape(shape)
        else:
            d = diff(x, axis=axis)
    nd = y.ndim
    slice1 = [slice(None)] * nd
    slice2 = [slice(None)] * nd
    slice1[axis] = slice(1, None)
    slice2[axis] = slice(None, -1)
    try:
        ret = (d * (y[tuple(slice1)] + y[tuple(slice2)]) / 2.0).sum(axis)
    except ValueError:
        d = np.asarray(d)
        y = np.asarray(y)
        ret = add.reduce(d * (y[tuple(slice1)] + y[tuple(slice2)]) / 2.0, axis)
    return ret

@array_function_dispatch(_meshgrid_dispatcher)
def meshgrid(*xi, copy=True, sparse=False, indexing='xy'):
    ndim = len(xi)
    if indexing not in ['xy', 'ij']:
        raise ValueError("Valid values for `indexing` are 'xy' and 'ij'.")
    s0 = (1,) * ndim
    output = [np.asanyarray(x).reshape(s0[:i] + (-1,) + s0[i + 1:]) for i, x in enumerate(xi)]
    if indexing == 'xy' and ndim > 1:
        output[0] = output[0].reshape((1, -1) + s0[2:])
        output[1] = output[1].reshape((-1, 1) + s0[2:])
    if not sparse:
        output = np.broadcast_arrays(*output, subok=True)
    if copy:
        output = tuple((x.copy() for x in output))
    if sparse and (not copy):
        return tuple(output)
    return output

@array_function_dispatch(_delete_dispatcher)
def delete(arr, obj, axis=None):
    conv = _array_converter(arr)
    arr, = conv.as_arrays(subok=False)
    ndim = arr.ndim
    arrorder = 'F' if arr.flags.fnc else 'C'
    if axis is None:
        if ndim != 1:
            arr = arr.ravel()
        ndim = arr.ndim
        axis = ndim - 1
    else:
        axis = normalize_axis_index(axis, ndim)
    slobj = [slice(None)] * ndim
    N = arr.shape[axis]
    newshape = list(arr.shape)
    if isinstance(obj, slice):
        start, stop, step = obj.indices(N)
        xr = range(start, stop, step)
        numtodel = len(xr)
        if numtodel <= 0:
            return conv.wrap(arr.copy(order=arrorder), to_scalar=False)
        if step < 0:
            step = -step
            start = xr[-1]
            stop = xr[0] + 1
        newshape[axis] -= numtodel
        new = empty(newshape, arr.dtype, arrorder)
        if start == 0:
            pass
        else:
            slobj[axis] = slice(None, start)
            new[tuple(slobj)] = arr[tuple(slobj)]
        if stop == N:
            pass
        else:
            slobj[axis] = slice(stop - numtodel, None)
            slobj2 = [slice(None)] * ndim
            slobj2[axis] = slice(stop, None)
            new[tuple(slobj)] = arr[tuple(slobj2)]
        if step == 1:
            pass
        else:
            keep = ones(stop - start, dtype=bool)
            keep[:stop - start:step] = False
            slobj[axis] = slice(start, stop - numtodel)
            slobj2 = [slice(None)] * ndim
            slobj2[axis] = slice(start, stop)
            arr = arr[tuple(slobj2)]
            slobj2[axis] = keep
            new[tuple(slobj)] = arr[tuple(slobj2)]
        return conv.wrap(new, to_scalar=False)
    if isinstance(obj, (int, integer)) and (not isinstance(obj, bool)):
        single_value = True
    else:
        single_value = False
        _obj = obj
        obj = np.asarray(obj)
        if obj.size == 0 and (not isinstance(_obj, np.ndarray)):
            obj = obj.astype(intp)
        elif obj.size == 1 and obj.dtype.kind in 'ui':
            obj = obj.item()
            single_value = True
    if single_value:
        if obj < -N or obj >= N:
            raise IndexError(f'index {obj} is out of bounds for axis {axis} with size {N}')
        if obj < 0:
            obj += N
        newshape[axis] -= 1
        new = empty(newshape, arr.dtype, arrorder)
        slobj[axis] = slice(None, obj)
        new[tuple(slobj)] = arr[tuple(slobj)]
        slobj[axis] = slice(obj, None)
        slobj2 = [slice(None)] * ndim
        slobj2[axis] = slice(obj + 1, None)
        new[tuple(slobj)] = arr[tuple(slobj2)]
    else:
        if obj.dtype == bool:
            if obj.shape != (N,):
                raise ValueError(f'boolean array argument obj to delete must be one dimensional and match the axis length of {N}')
            keep = ~obj
        else:
            keep = ones(N, dtype=bool)
            keep[obj,] = False
        slobj[axis] = keep
        new = arr[tuple(slobj)]
    return conv.wrap(new, to_scalar=False)

@array_function_dispatch(_append_dispatcher)
def append(arr, values, axis=None):
    arr = asanyarray(arr)
    if axis is None:
        if arr.ndim != 1:
            arr = arr.ravel()
        values = ravel(values)
        axis = arr.ndim - 1
    return concatenate((arr, values), axis=axis)

@array_function_dispatch(_digitize_dispatcher)
def digitize(x, bins, right=False):
    x = _nx.asarray(x)
    bins = _nx.asarray(bins)
    if np.issubdtype(x.dtype, _nx.complexfloating):
        raise TypeError('x may not be complex')
    mono = _monotonicity(bins)
    if mono == 0:
        raise ValueError('bins must be monotonically increasing or decreasing')
    side = 'left' if right else 'right'
    if mono == -1:
        return len(bins) - _nx.searchsorted(bins[::-1], x, side=side)
    else:
        return _nx.searchsorted(bins, x, side=side)

def _call_as_normal(self, *args, **kwargs):
    excluded = self.excluded
    if not kwargs and (not excluded):
        func = self.pyfunc
        vargs = args
    else:
        nargs = len(args)
        names = [_n for _n in kwargs if _n not in excluded]
        inds = [_i for _i in range(nargs) if _i not in excluded]
        the_args = list(args)

        def func(*vargs):
            for _n, _i in enumerate(inds):
                the_args[_i] = vargs[_n]
            kwargs.update(zip(names, vargs[len(inds):]))
            return self.pyfunc(*the_args, **kwargs)
        vargs = [args[_i] for _i in inds]
        vargs.extend([kwargs[_n] for _n in names])
    return self._vectorize_call(func=func, args=vargs)

def _get_ufunc_and_otypes(self, func, args):
    if not args:
        raise ValueError('args can not be empty')
    if self.otypes is not None:
        otypes = self.otypes
        nin = len(args)
        nout = len(self.otypes)
        if func is not self.pyfunc or nin not in self._ufunc:
            ufunc = frompyfunc(func, nin, nout)
        else:
            ufunc = None
        if func is self.pyfunc:
            ufunc = self._ufunc.setdefault(nin, ufunc)
    else:
        args = [asarray(a) for a in args]
        if builtins.any((arg.size == 0 for arg in args)):
            raise ValueError('cannot call `vectorize` on size 0 inputs unless `otypes` is set')
        inputs = [arg.flat[0] for arg in args]
        outputs = func(*inputs)
        if self.cache:
            _cache = [outputs]

            def _func(*vargs):
                if _cache:
                    return _cache.pop()
                else:
                    return func(*vargs)
        else:
            _func = func
        if isinstance(outputs, tuple):
            nout = len(outputs)
        else:
            nout = 1
            outputs = (outputs,)
        otypes = ''.join([asarray(outputs[_k]).dtype.char for _k in range(nout)])
        ufunc = frompyfunc(_func, len(args), nout)
    return (ufunc, otypes)

def _vectorize_call(self, func, args):
    if self.signature is not None:
        res = self._vectorize_call_with_signature(func, args)
    elif not args:
        res = func()
    else:
        ufunc, otypes = self._get_ufunc_and_otypes(func=func, args=args)
        args = [asanyarray(a, dtype=object) for a in args]
        outputs = ufunc(*args, out=...)
        if ufunc.nout == 1:
            res = asanyarray(outputs, dtype=otypes[0])
        else:
            res = tuple((asanyarray(x, dtype=t) for x, t in zip(outputs, otypes)))
    return res

def _vectorize_call_with_signature(self, func, args):
    input_core_dims, output_core_dims = self._in_and_out_core_dims
    if len(args) != len(input_core_dims):
        raise TypeError(f'wrong number of positional arguments: expected {len(input_core_dims)!r}, got {len(args)!r}')
    args = tuple((asanyarray(arg) for arg in args))
    broadcast_shape, dim_sizes = _parse_input_dimensions(args, input_core_dims)
    input_shapes = _calculate_shapes(broadcast_shape, dim_sizes, input_core_dims)
    args = [np.broadcast_to(arg, shape, subok=True) for arg, shape in zip(args, input_shapes)]
    outputs = None
    otypes = self.otypes
    nout = len(output_core_dims)
    for index in np.ndindex(*broadcast_shape):
        results = func(*(arg[index] for arg in args))
        n_results = len(results) if isinstance(results, tuple) else 1
        if nout != n_results:
            raise ValueError(f'wrong number of outputs from pyfunc: expected {nout!r}, got {n_results!r}')
        if nout == 1:
            results = (results,)
        if outputs is None:
            for result, core_dims in zip(results, output_core_dims):
                _update_dim_sizes(dim_sizes, result, core_dims)
            outputs = _create_arrays(broadcast_shape, dim_sizes, output_core_dims, otypes, results)
        for output, result in zip(outputs, results):
            output[index] = result
    if outputs is None:
        if otypes is None:
            raise ValueError('cannot call `vectorize` on size 0 inputs unless `otypes` is set')
        if builtins.any((dim not in dim_sizes for dims in output_core_dims for dim in dims)):
            raise ValueError('cannot call `vectorize` with a signature including new output dimensions on size 0 inputs')
        outputs = _create_arrays(broadcast_shape, dim_sizes, output_core_dims, otypes)
    return outputs[0] if nout == 1 else outputs

def _hist_bin_sqrt(x, range):
    del range
    return _ptp(x) / np.sqrt(x.size)

def _hist_bin_sturges(x, range):
    del range
    return _ptp(x) / (np.log2(x.size) + 1.0)

def _hist_bin_rice(x, range):
    del range
    return _ptp(x) / (2.0 * x.size ** (1.0 / 3))

def _hist_bin_scott(x, range):
    del range
    return (24.0 * np.pi ** 0.5 / x.size) ** (1.0 / 3.0) * np.std(x)

def _hist_bin_doane(x, range):
    del range
    if x.size > 2:
        sg1 = np.sqrt(6.0 * (x.size - 2) / ((x.size + 1.0) * (x.size + 3)))
        sigma = np.std(x)
        if sigma > 0.0:
            temp = x - np.mean(x)
            np.true_divide(temp, sigma, temp)
            np.power(temp, 3, temp)
            g1 = np.mean(temp)
            return _ptp(x) / (1.0 + np.log2(x.size) + np.log2(1.0 + np.absolute(g1) / sg1))
    return 0.0

def _hist_bin_fd(x, range):
    del range
    iqr = np.subtract(*np.percentile(x, [75, 25]))
    return 2.0 * iqr * x.size ** (-1.0 / 3.0)

def _hist_bin_auto(x, range):
    fd_bw = _hist_bin_fd(x, range)
    sturges_bw = _hist_bin_sturges(x, range)
    sqrt_bw = _hist_bin_sqrt(x, range)
    fd_bw_corrected = max(fd_bw, sqrt_bw / 2)
    return min(fd_bw_corrected, sturges_bw)

def _ravel_and_check_weights(a, weights):
    a = np.asarray(a)
    if a.dtype == np.bool:
        msg = f'Converting input from {a.dtype} to {np.uint8} for compatibility.'
        warnings.warn(msg, RuntimeWarning, stacklevel=3)
        a = a.astype(np.uint8)
    if weights is not None:
        weights = np.asarray(weights)
        if weights.shape != a.shape:
            raise ValueError('weights should have the same shape as a.')
        weights = weights.ravel()
    a = a.ravel()
    return (a, weights)

def _get_outer_edges(a, range):
    if range is not None:
        first_edge, last_edge = range
        if first_edge > last_edge:
            raise ValueError('max must be larger than min in range parameter.')
        if not (np.isfinite(first_edge) and np.isfinite(last_edge)):
            raise ValueError(f'supplied range of [{first_edge}, {last_edge}] is not finite')
    elif a.size == 0:
        first_edge, last_edge = (0, 1)
    else:
        first_edge, last_edge = (a.min(), a.max())
        if not (np.isfinite(first_edge) and np.isfinite(last_edge)):
            raise ValueError(f'autodetected range of [{first_edge}, {last_edge}] is not finite')
    if first_edge == last_edge:
        first_edge = first_edge - 0.5
        last_edge = last_edge + 0.5
    return (first_edge, last_edge)

def _unsigned_subtract(a, b):
    signed_to_unsigned = {np.byte: np.ubyte, np.short: np.ushort, np.intc: np.uintc, np.int_: np.uint, np.longlong: np.ulonglong}
    dt = np.result_type(a, b)
    try:
        unsigned_dt = signed_to_unsigned[dt.type]
    except KeyError:
        return np.subtract(a, b, dtype=type(dt))
    else:
        return np.subtract(np.asarray(a, dtype=dt), np.asarray(b, dtype=dt), casting='unsafe', dtype=unsigned_dt)

def _get_bin_edges(a, bins, range, weights):
    n_equal_bins = None
    bin_edges = None
    if isinstance(bins, str):
        bin_name = bins
        if bin_name not in _hist_bin_selectors:
            raise ValueError(f'{bin_name!r} is not a valid estimator for `bins`')
        if weights is not None:
            raise TypeError('Automated estimation of the number of bins is not supported for weighted data')
        first_edge, last_edge = _get_outer_edges(a, range)
        if range is not None:
            keep = a >= first_edge
            keep &= a <= last_edge
            if not np.logical_and.reduce(keep):
                a = a[keep]
        if a.size == 0:
            n_equal_bins = 1
        else:
            width = _hist_bin_selectors[bin_name](a, (first_edge, last_edge))
            if width:
                if np.issubdtype(a.dtype, np.integer) and width < 1:
                    width = 1
                delta = _unsigned_subtract(last_edge, first_edge)
                n_equal_bins = int(np.ceil(delta / width))
            else:
                n_equal_bins = 1
    elif np.ndim(bins) == 0:
        try:
            n_equal_bins = operator.index(bins)
        except TypeError as e:
            raise TypeError('`bins` must be an integer, a string, or an array') from e
        if n_equal_bins < 1:
            raise ValueError('`bins` must be positive, when an integer')
        first_edge, last_edge = _get_outer_edges(a, range)
    elif np.ndim(bins) == 1:
        bin_edges = np.asarray(bins)
        if np.any(bin_edges[:-1] > bin_edges[1:]):
            raise ValueError('`bins` must increase monotonically, when an array')
    else:
        raise ValueError('`bins` must be 1d, when an array')
    if n_equal_bins is not None:
        bin_type = np.result_type(first_edge, last_edge, a)
        if np.issubdtype(bin_type, np.integer):
            bin_type = np.result_type(bin_type, float)
        bin_edges = np.linspace(first_edge, last_edge, n_equal_bins + 1, endpoint=True, dtype=bin_type)
        if np.any(bin_edges[:-1] >= bin_edges[1:]):
            raise ValueError(f'Too many bins for data range. Cannot create {n_equal_bins} finite-sized bins.')
        return (bin_edges, (first_edge, last_edge, n_equal_bins))
    else:
        return (bin_edges, None)

@array_function_dispatch(_histogram_bin_edges_dispatcher)
def histogram_bin_edges(a, bins=10, range=None, weights=None):
    a, weights = _ravel_and_check_weights(a, weights)
    bin_edges, _ = _get_bin_edges(a, bins, range, weights)
    return bin_edges

@array_function_dispatch(_histogram_dispatcher)
def histogram(a, bins=10, range=None, density=None, weights=None):
    a, weights = _ravel_and_check_weights(a, weights)
    bin_edges, uniform_bins = _get_bin_edges(a, bins, range, weights)
    if weights is None:
        ntype = np.dtype(np.intp)
    else:
        ntype = weights.dtype
    BLOCK = 65536
    simple_weights = weights is None or np.can_cast(weights.dtype, np.double) or np.can_cast(weights.dtype, complex)
    if uniform_bins is not None and simple_weights:
        first_edge, last_edge, n_equal_bins = uniform_bins
        n = np.zeros(n_equal_bins, ntype)
        norm_numerator = n_equal_bins
        norm_denom = _unsigned_subtract(last_edge, first_edge)
        for i in _range(0, len(a), BLOCK):
            tmp_a = a[i:i + BLOCK]
            if weights is None:
                tmp_w = None
            else:
                tmp_w = weights[i:i + BLOCK]
            keep = tmp_a >= first_edge
            keep &= tmp_a <= last_edge
            if not np.logical_and.reduce(keep):
                tmp_a = tmp_a[keep]
                if tmp_w is not None:
                    tmp_w = tmp_w[keep]
            tmp_a = tmp_a.astype(bin_edges.dtype, copy=False)
            f_indices = _unsigned_subtract(tmp_a, first_edge) / norm_denom * norm_numerator
            indices = f_indices.astype(np.intp)
            indices[indices == n_equal_bins] -= 1
            decrement = tmp_a < bin_edges[indices]
            indices[decrement] -= 1
            increment = (tmp_a >= bin_edges[indices + 1]) & (indices != n_equal_bins - 1)
            indices[increment] += 1
            if ntype.kind == 'c':
                n.real += np.bincount(indices, weights=tmp_w.real, minlength=n_equal_bins)
                n.imag += np.bincount(indices, weights=tmp_w.imag, minlength=n_equal_bins)
            else:
                n += np.bincount(indices, weights=tmp_w, minlength=n_equal_bins).astype(ntype)
    else:
        cum_n = np.zeros(bin_edges.shape, ntype)
        if weights is None:
            for i in _range(0, len(a), BLOCK):
                sa = np.sort(a[i:i + BLOCK])
                cum_n += _search_sorted_inclusive(sa, bin_edges)
        else:
            zero = np.zeros(1, dtype=ntype)
            for i in _range(0, len(a), BLOCK):
                tmp_a = a[i:i + BLOCK]
                tmp_w = weights[i:i + BLOCK]
                sorting_index = np.argsort(tmp_a)
                sa = tmp_a[sorting_index]
                sw = tmp_w[sorting_index]
                cw = np.concatenate((zero, sw.cumsum()))
                bin_index = _search_sorted_inclusive(sa, bin_edges)
                cum_n += cw[bin_index]
        n = np.diff(cum_n)
    if density:
        db = np.array(np.diff(bin_edges), float)
        return (n / db / n.sum(), bin_edges)
    return (n, bin_edges)

@array_function_dispatch(_histogramdd_dispatcher)
def histogramdd(sample, bins=10, range=None, density=None, weights=None):
    try:
        N, D = sample.shape
    except (AttributeError, ValueError):
        sample = np.atleast_2d(sample).T
        N, D = sample.shape
    nbin = np.empty(D, np.intp)
    edges = D * [None]
    dedges = D * [None]
    if weights is not None:
        weights = np.asarray(weights)
    try:
        M = len(bins)
        if M != D:
            raise ValueError('The dimension of bins must be equal to the dimension of the sample x.')
    except TypeError:
        bins = D * [bins]
    if range is None:
        range = (None,) * D
    elif len(range) != D:
        raise ValueError('range argument must have one entry per dimension')
    for i in _range(D):
        if np.ndim(bins[i]) == 0:
            if bins[i] < 1:
                raise ValueError(f'`bins[{i}]` must be positive, when an integer')
            smin, smax = _get_outer_edges(sample[:, i], range[i])
            try:
                n = operator.index(bins[i])
            except TypeError as e:
                raise TypeError(f'`bins[{i}]` must be an integer, when a scalar') from e
            edges[i] = np.linspace(smin, smax, n + 1)
        elif np.ndim(bins[i]) == 1:
            edges[i] = np.asarray(bins[i])
            if np.any(edges[i][:-1] > edges[i][1:]):
                raise ValueError(f'`bins[{i}]` must be monotonically increasing, when an array')
        else:
            raise ValueError(f'`bins[{i}]` must be a scalar or 1d array')
        nbin[i] = len(edges[i]) + 1
        dedges[i] = np.diff(edges[i])
    Ncount = tuple((np.searchsorted(edges[i], sample[:, i], side='right') for i in _range(D)))
    for i in _range(D):
        on_edge = sample[:, i] == edges[i][-1]
        Ncount[i][on_edge] -= 1
    xy = np.ravel_multi_index(Ncount, nbin)
    hist = np.bincount(xy, weights, minlength=nbin.prod())
    hist = hist.reshape(nbin)
    hist = hist.astype(float, casting='safe')
    core = D * (slice(1, -1),)
    hist = hist[core]
    if density:
        s = hist.sum()
        for i in _range(D):
            shape = np.ones(D, int)
            shape[i] = nbin[i] - 2
            hist = hist / dedges[i].reshape(shape)
        hist /= s
    if (hist.shape != nbin - 2).any():
        raise RuntimeError('Internal Shape Error')
    return (hist, edges)

@array_function_dispatch(_ix__dispatcher)
def ix_(*args):
    out = []
    nd = len(args)
    for k, new in enumerate(args):
        if not isinstance(new, _nx.ndarray):
            new = np.asarray(new)
            if new.size == 0:
                new = new.astype(_nx.intp)
        if new.ndim != 1:
            raise ValueError('Cross index must be 1 dimensional')
        if issubdtype(new.dtype, _nx.bool):
            new, = new.nonzero()
        new = new.reshape((1,) * k + (new.size,) + (1,) * (nd - k - 1))
        out.append(new)
    return tuple(out)

@array_function_dispatch(_fill_diagonal_dispatcher)
def fill_diagonal(a, val, wrap=False):
    if a.ndim < 2:
        raise ValueError('array must be at least 2-d')
    end = None
    if a.ndim == 2:
        step = a.shape[1] + 1
        if not wrap:
            end = a.shape[1] * a.shape[1]
    else:
        if not np.all(diff(a.shape) == 0):
            raise ValueError('All dimensions of input must be of equal length')
        step = 1 + np.cumprod(a.shape[:-1]).sum()
    a.flat[:end:step] = val

@set_module('numpy')
def diag_indices(n, ndim=2):
    idx = np.arange(n)
    return (idx,) * ndim

@array_function_dispatch(_diag_indices_from)
def diag_indices_from(arr):
    if not arr.ndim >= 2:
        raise ValueError('input array must be at least 2-d')
    if not np.all(diff(arr.shape) == 0):
        raise ValueError('All dimensions of input must be of equal length')
    return diag_indices(arr.shape[0], arr.ndim)

def _decode_line(line, encoding=None):
    if type(line) is bytes:
        if encoding is None:
            encoding = 'latin1'
        line = line.decode(encoding)
    return line

def _is_string_like(obj):
    try:
        obj + ''
    except (TypeError, ValueError):
        return False
    return True

def _is_bytes_like(obj):
    try:
        obj + b''
    except (TypeError, ValueError):
        return False
    return True

def flatten_dtype(ndtype, flatten_base=False):
    names = ndtype.names
    if names is None:
        if flatten_base:
            return [ndtype.base] * int(np.prod(ndtype.shape))
        return [ndtype.base]
    else:
        types = []
        for field in names:
            info = ndtype.fields[field]
            flat_dt = flatten_dtype(info[0], flatten_base)
            types.extend(flat_dt)
        return types

def str2bool(value):
    value = value.upper()
    if value == 'TRUE':
        return True
    elif value == 'FALSE':
        return False
    else:
        raise ValueError('Invalid boolean')

def easy_dtype(ndtype, names=None, defaultfmt='f%i', **validationargs):
    try:
        ndtype = np.dtype(ndtype)
    except TypeError:
        validate = NameValidator(**validationargs)
        nbfields = len(ndtype)
        if names is None:
            names = [''] * len(ndtype)
        elif isinstance(names, str):
            names = names.split(',')
        names = validate(names, nbfields=nbfields, defaultfmt=defaultfmt)
        ndtype = np.dtype({'formats': ndtype, 'names': names})
    else:
        if names is not None:
            validate = NameValidator(**validationargs)
            if isinstance(names, str):
                names = names.split(',')
            if ndtype.names is None:
                formats = tuple([ndtype.type] * len(names))
                names = validate(names, defaultfmt=defaultfmt)
                ndtype = np.dtype(list(zip(names, formats)))
            else:
                ndtype.names = validate(names, nbfields=len(ndtype.names), defaultfmt=defaultfmt)
        elif ndtype.names is not None:
            validate = NameValidator(**validationargs)
            numbered_names = tuple((f'f{i}' for i in range(len(ndtype.names))))
            if ndtype.names == numbered_names and defaultfmt != 'f%i':
                ndtype.names = validate([''] * len(ndtype.names), defaultfmt=defaultfmt)
            else:
                ndtype.names = validate(ndtype.names, defaultfmt=defaultfmt)
    return ndtype

def _delimited_splitter(self, line):
    if self.comments is not None:
        line = line.split(self.comments)[0]
    line = line.strip(' \r\n')
    if not line:
        return []
    return line.split(self.delimiter)

def validate(self, names, defaultfmt='f%i', nbfields=None):
    if names is None:
        if nbfields is None:
            return None
        names = []
    if isinstance(names, str):
        names = [names]
    if nbfields is not None:
        nbnames = len(names)
        if nbnames < nbfields:
            names = list(names) + [''] * (nbfields - nbnames)
        elif nbnames > nbfields:
            names = names[:nbfields]
    deletechars = self.deletechars
    excludelist = self.excludelist
    case_converter = self.case_converter
    replace_space = self.replace_space
    validatednames = []
    seen = {}
    nbempty = 0
    for item in names:
        item = case_converter(item).strip()
        if replace_space:
            item = item.replace(' ', replace_space)
        item = ''.join([c for c in item if c not in deletechars])
        if item == '':
            item = defaultfmt % nbempty
            while item in names:
                nbempty += 1
                item = defaultfmt % nbempty
            nbempty += 1
        elif item in excludelist:
            item += '_'
        cnt = seen.get(item, 0)
        if cnt > 0:
            validatednames.append(f'{item}_{cnt}')
        else:
            validatednames.append(item)
        seen[item] = cnt + 1
    return tuple(validatednames)

@classmethod
def _getdtype(cls, val):
    return np.array(val).dtype

@classmethod
def _getsubdtype(cls, val):
    return np.array(val).dtype.type

@classmethod
def _dtypeortype(cls, dtype):
    if dtype.type == np.datetime64:
        return dtype
    return dtype.type

@classmethod
def upgrade_mapper(cls, func, default=None):
    if callable(func):
        cls._mapper.insert(-1, (cls._getsubdtype(default), func, default))
        return
    elif hasattr(func, '__iter__'):
        if isinstance(func[0], (tuple, list)):
            for _ in func:
                cls._mapper.insert(-1, _)
            return
        if default is None:
            default = [None] * len(func)
        else:
            default = list(default)
            default.append([None] * (len(func) - len(default)))
        for fct, dft in zip(func, default):
            cls._mapper.insert(-1, (cls._getsubdtype(dft), fct, dft))

def upgrade(self, value):
    self._checked = True
    try:
        return self._strict_call(value)
    except ValueError:
        self._do_upgrade()
        return self.upgrade(value)

def update(self, func, default=None, testing_value=None, missing_values='', locked=False):
    self.func = func
    self._locked = locked
    if default is not None:
        self.default = default
        self.type = self._dtypeortype(self._getdtype(default))
    else:
        try:
            tester = func(testing_value or '1')
        except (TypeError, ValueError):
            tester = None
        self.type = self._dtypeortype(self._getdtype(tester))
    if missing_values is None:
        self.missing_values = set()
    else:
        if not np.iterable(missing_values):
            missing_values = [missing_values]
        if not all((isinstance(v, str) for v in missing_values)):
            raise TypeError('missing_values must be strings or unicode')
        self.missing_values.update(missing_values)

def _nan_mask(a, out=None):
    if a.dtype.kind not in 'fc':
        return True
    y = np.isnan(a, out=out)
    y = np.invert(y, out=y)
    return y

def _replace_nan(a, val):
    a = np.asanyarray(a)
    if a.dtype == np.object_:
        mask = np.not_equal(a, a, dtype=bool)
    elif issubclass(a.dtype.type, np.inexact):
        mask = np.isnan(a)
    else:
        mask = None
    if mask is not None:
        a = np.array(a, subok=True, copy=True)
        np.copyto(a, val, where=mask)
    return (a, mask)

def _copyto(a, val, mask):
    if isinstance(a, np.ndarray):
        np.copyto(a, val, where=mask, casting='unsafe')
    else:
        a = a.dtype.type(val)
    return a

def _remove_nan_1d(arr1d, second_arr1d=None, overwrite_input=False):
    if arr1d.dtype == object:
        c = np.not_equal(arr1d, arr1d, dtype=bool)
    else:
        c = np.isnan(arr1d)
    s = np.nonzero(c)[0]
    if s.size == arr1d.size:
        warnings.warn('All-NaN slice encountered', RuntimeWarning, stacklevel=6)
        if second_arr1d is None:
            return (arr1d[:0], None, True)
        else:
            return (arr1d[:0], second_arr1d[:0], True)
    elif s.size == 0:
        return (arr1d, second_arr1d, overwrite_input)
    else:
        if not overwrite_input:
            arr1d = arr1d.copy()
        enonan = arr1d[-s.size:][~c[-s.size:]]
        arr1d[s[:enonan.size]] = enonan
        if second_arr1d is None:
            return (arr1d[:-s.size], None, True)
        else:
            if not overwrite_input:
                second_arr1d = second_arr1d.copy()
            enonan = second_arr1d[-s.size:][~c[-s.size:]]
            second_arr1d[s[:enonan.size]] = enonan
            return (arr1d[:-s.size], second_arr1d[:-s.size], True)

def _divide_by_count(a, b, out=None):
    with np.errstate(invalid='ignore', divide='ignore'):
        if isinstance(a, np.ndarray):
            if out is None:
                return np.divide(a, b, out=a, casting='unsafe')
            else:
                return np.divide(a, b, out=out, casting='unsafe')
        elif out is None:
            try:
                return a.dtype.type(a / b)
            except AttributeError:
                return a / b
        else:
            return np.divide(a, b, out=out, casting='unsafe')

@array_function_dispatch(_nanmin_dispatcher)
def nanmin(a, axis=None, out=None, keepdims=np._NoValue, initial=np._NoValue, where=np._NoValue):
    kwargs = {}
    if keepdims is not np._NoValue:
        kwargs['keepdims'] = keepdims
    if initial is not np._NoValue:
        kwargs['initial'] = initial
    if where is not np._NoValue:
        kwargs['where'] = where
    if (type(a) is np.ndarray or type(a) is np.memmap) and a.dtype != np.object_:
        res = np.fmin.reduce(a, axis=axis, out=out, **kwargs)
        if np.isnan(res).any():
            warnings.warn('All-NaN slice encountered', RuntimeWarning, stacklevel=2)
    else:
        a, mask = _replace_nan(a, +np.inf)
        res = np.amin(a, axis=axis, out=out, **kwargs)
        if mask is None:
            return res
        kwargs.pop('initial', None)
        mask = np.all(mask, axis=axis, **kwargs)
        if np.any(mask):
            res = _copyto(res, np.nan, mask)
            warnings.warn('All-NaN axis encountered', RuntimeWarning, stacklevel=2)
    return res

@array_function_dispatch(_nanmax_dispatcher)
def nanmax(a, axis=None, out=None, keepdims=np._NoValue, initial=np._NoValue, where=np._NoValue):
    kwargs = {}
