@array_function_dispatch(_nanmean_dispatcher)
def nanmean(a, axis=None, dtype=None, out=None, keepdims=np._NoValue, *, where=np._NoValue):
    arr, mask = _replace_nan(a, 0)
    if mask is None:
        return np.mean(arr, axis=axis, dtype=dtype, out=out, keepdims=keepdims, where=where)
    if dtype is not None:
        dtype = np.dtype(dtype)
    if dtype is not None and (not issubclass(dtype.type, np.inexact)):
        raise TypeError('If a is inexact, then dtype must be inexact')
    if out is not None and (not issubclass(out.dtype.type, np.inexact)):
        raise TypeError('If a is inexact, then out must be inexact')
    cnt = np.sum(~mask, axis=axis, dtype=np.intp, keepdims=keepdims, where=where)
    tot = np.sum(arr, axis=axis, dtype=dtype, out=out, keepdims=keepdims, where=where)
    avg = _divide_by_count(tot, cnt, out=out)
    isbad = cnt == 0
    if isbad.any():
        warnings.warn('Mean of empty slice', RuntimeWarning, stacklevel=2)
    return avg

def _nanmedian1d(arr1d, overwrite_input=False):
    arr1d_parsed, _, overwrite_input = _remove_nan_1d(arr1d, overwrite_input=overwrite_input)
    if arr1d_parsed.size == 0:
        return arr1d[-1]
    return np.median(arr1d_parsed, overwrite_input=overwrite_input)

def _nanmedian(a, axis=None, out=None, overwrite_input=False):
    if axis is None or a.ndim == 1:
        part = a.ravel()
        if out is None:
            return _nanmedian1d(part, overwrite_input)
        else:
            out[...] = _nanmedian1d(part, overwrite_input)
            return out
    else:
        if a.shape[axis] < 600:
            return _nanmedian_small(a, axis, out, overwrite_input)
        result = np.apply_along_axis(_nanmedian1d, axis, a, overwrite_input)
        if out is not None:
            out[...] = result
        return result

def _nanmedian_small(a, axis=None, out=None, overwrite_input=False):
    a = np.ma.masked_array(a, np.isnan(a))
    m = np.ma.median(a, axis=axis, overwrite_input=overwrite_input)
    for i in range(np.count_nonzero(m.mask.ravel())):
        warnings.warn('All-NaN slice encountered', RuntimeWarning, stacklevel=5)
    fill_value = np.timedelta64('NaT') if m.dtype.kind == 'm' else np.nan
    if out is not None:
        out[...] = m.filled(fill_value)
        return out
    return m.filled(fill_value)

@array_function_dispatch(_nanmedian_dispatcher)
def nanmedian(a, axis=None, out=None, overwrite_input=False, keepdims=np._NoValue):
    a = np.asanyarray(a)
    if a.size == 0:
        return np.nanmean(a, axis, out=out, keepdims=keepdims)
    return fnb._ureduce(a, func=_nanmedian, keepdims=keepdims, axis=axis, out=out, overwrite_input=overwrite_input)

@array_function_dispatch(_nanpercentile_dispatcher)
def nanpercentile(a, q, axis=None, out=None, overwrite_input=False, method='linear', keepdims=np._NoValue, *, weights=None):
    a = np.asanyarray(a)
    if a.dtype.kind == 'c':
        raise TypeError('a must be an array of real numbers')
    weak_q = type(q) in (int, float)
    q = np.true_divide(q, 100, out=...)
    if not fnb._quantile_is_valid(q):
        raise ValueError('Percentiles must be in the range [0, 100]')
    if weights is not None:
        if method != 'inverted_cdf':
            msg = f"Only method 'inverted_cdf' supports weights. Got: {method}."
            raise ValueError(msg)
        if axis is not None:
            axis = _nx.normalize_axis_tuple(axis, a.ndim, argname='axis')
        weights = _weights_are_valid(weights=weights, a=a, axis=axis)
        if np.any(weights < 0):
            raise ValueError('Weights must be non-negative.')
    return _nanquantile_unchecked(a, q, axis, out, overwrite_input, method, keepdims, weights, weak_q)

@array_function_dispatch(_nanquantile_dispatcher)
def nanquantile(a, q, axis=None, out=None, overwrite_input=False, method='linear', keepdims=np._NoValue, *, weights=None):
    a = np.asanyarray(a)
    if a.dtype.kind == 'c':
        raise TypeError('a must be an array of real numbers')
    weak_q = type(q) in (int, float)
    q = np.asanyarray(q)
    if not fnb._quantile_is_valid(q):
        raise ValueError('Quantiles must be in the range [0, 1]')
    if weights is not None:
        if method != 'inverted_cdf':
            msg = f"Only method 'inverted_cdf' supports weights. Got: {method}."
            raise ValueError(msg)
        if axis is not None:
            axis = _nx.normalize_axis_tuple(axis, a.ndim, argname='axis')
        weights = _weights_are_valid(weights=weights, a=a, axis=axis)
        if np.any(weights < 0):
            raise ValueError('Weights must be non-negative.')
    return _nanquantile_unchecked(a, q, axis, out, overwrite_input, method, keepdims, weights, weak_q)

def _nanquantile_unchecked(a, q, axis=None, out=None, overwrite_input=False, method='linear', keepdims=np._NoValue, weights=None, weak_q=False):
    if a.size == 0:
        return np.nanmean(a, axis, out=out, keepdims=keepdims)
    return fnb._ureduce(a, func=_nanquantile_ureduce_func, q=q, weights=weights, keepdims=keepdims, axis=axis, out=out, overwrite_input=overwrite_input, method=method, weak_q=weak_q)

def _nanquantile_ureduce_func(a: np.ndarray, q: np.ndarray, weights: np.ndarray, axis: int | None=None, out=None, overwrite_input: bool=False, method='linear', weak_q=False):
    if axis is None or a.ndim == 1:
        part = a.ravel()
        wgt = None if weights is None else weights.ravel()
        result = _nanquantile_1d(part, q, overwrite_input, method, weights=wgt, weak_q=weak_q)
    elif weights is None:
        result = np.apply_along_axis(_nanquantile_1d, axis, a, q, overwrite_input, method, weights, weak_q)
        if q.ndim != 0:
            from_ax = [axis + i for i in range(q.ndim)]
            result = np.moveaxis(result, from_ax, list(range(q.ndim)))
    else:
        a = np.moveaxis(a, axis, -1)
        if weights is not None:
            weights = np.moveaxis(weights, axis, -1)
        if out is not None:
            result = out
        else:
            result = np.empty_like(a, shape=q.shape + a.shape[:-1])
        for ii in np.ndindex(a.shape[:-1]):
            result[(...,) + ii] = _nanquantile_1d(a[ii], q, weights=weights[ii], overwrite_input=overwrite_input, method=method, weak_q=weak_q)
        return result
    if out is not None:
        out[...] = result
    return result

def _nanquantile_1d(arr1d, q, overwrite_input=False, method='linear', weights=None, weak_q=False):
    arr1d, weights, overwrite_input = _remove_nan_1d(arr1d, second_arr1d=weights, overwrite_input=overwrite_input)
    if arr1d.size == 0:
        return np.full(q.shape, np.nan, dtype=arr1d.dtype)[()]
    return fnb._quantile_unchecked(arr1d, q, overwrite_input=overwrite_input, method=method, weights=weights, weak_q=weak_q)

@array_function_dispatch(_nanvar_dispatcher)
def nanvar(a, axis=None, dtype=None, out=None, ddof=0, keepdims=np._NoValue, *, where=np._NoValue, mean=np._NoValue, correction=np._NoValue):
    arr, mask = _replace_nan(a, 0)
    if mask is None:
        return np.var(arr, axis=axis, dtype=dtype, out=out, ddof=ddof, keepdims=keepdims, where=where, mean=mean, correction=correction)
    if dtype is not None:
        dtype = np.dtype(dtype)
    if dtype is not None and (not issubclass(dtype.type, np.inexact)):
        raise TypeError('If a is inexact, then dtype must be inexact')
    if out is not None and (not issubclass(out.dtype.type, np.inexact)):
        raise TypeError('If a is inexact, then out must be inexact')
    if correction != np._NoValue:
        if ddof != 0:
            raise ValueError("ddof and correction can't be provided simultaneously.")
        else:
            ddof = correction
    if type(arr) is np.matrix:
        _keepdims = np._NoValue
    else:
        _keepdims = True
    cnt = np.sum(~mask, axis=axis, dtype=np.intp, keepdims=_keepdims, where=where)
    if mean is not np._NoValue:
        avg = mean
    else:
        avg = np.sum(arr, axis=axis, dtype=dtype, keepdims=_keepdims, where=where)
        avg = _divide_by_count(avg, cnt)
    np.subtract(arr, avg, out=arr, casting='unsafe', where=where)
    arr = _copyto(arr, 0, mask)
    if issubclass(arr.dtype.type, np.complexfloating):
        sqr = np.multiply(arr, arr.conj(), out=arr, where=where).real
    else:
        sqr = np.multiply(arr, arr, out=arr, where=where)
    var = np.sum(sqr, axis=axis, dtype=dtype, out=out, keepdims=keepdims, where=where)
    try:
        var_ndim = var.ndim
    except AttributeError:
        var_ndim = np.ndim(var)
    if var_ndim < cnt.ndim:
        cnt = cnt.squeeze(axis)
    dof = cnt - ddof
    var = _divide_by_count(var, dof)
    isbad = dof <= 0
    if np.any(isbad):
        warnings.warn('Degrees of freedom <= 0 for slice.', RuntimeWarning, stacklevel=2)
        var = _copyto(var, np.nan, isbad)
    return var

@array_function_dispatch(_nanstd_dispatcher)
def nanstd(a, axis=None, dtype=None, out=None, ddof=0, keepdims=np._NoValue, *, where=np._NoValue, mean=np._NoValue, correction=np._NoValue):
    var = nanvar(a, axis=axis, dtype=dtype, out=out, ddof=ddof, keepdims=keepdims, where=where, mean=mean, correction=correction)
    if isinstance(var, np.ndarray):
        std = np.sqrt(var, out=var)
    elif hasattr(var, 'dtype'):
        std = var.dtype.type(np.sqrt(var))
    else:
        std = np.sqrt(var)
    return std

def zipfile_factory(file, *args, **kwargs):
    if not hasattr(file, 'read'):
        file = os.fspath(file)
    import zipfile
    kwargs['allowZip64'] = True
    return zipfile.ZipFile(file, *args, **kwargs)

@set_module('numpy')
def load(file, mmap_mode=None, allow_pickle=False, fix_imports=True, encoding='ASCII', *, max_header_size=_MAX_HEADER_SIZE):
    if encoding not in ('ASCII', 'latin1', 'bytes'):
        raise ValueError("encoding must be 'ASCII', 'latin1', or 'bytes'")
    pickle_kwargs = {'encoding': encoding, 'fix_imports': fix_imports}
    with contextlib.ExitStack() as stack:
        if hasattr(file, 'read'):
            fid = file
            own_fid = False
        else:
            fid = stack.enter_context(open(os.fspath(file), 'rb'))
            own_fid = True
        _ZIP_PREFIX = b'PK\x03\x04'
        _ZIP_SUFFIX = b'PK\x05\x06'
        N = len(format.MAGIC_PREFIX)
        magic = fid.read(N)
        if not magic:
            raise EOFError('No data left in file')
        fid.seek(-min(N, len(magic)), 1)
        if magic.startswith((_ZIP_PREFIX, _ZIP_SUFFIX)):
            stack.pop_all()
            ret = NpzFile(fid, own_fid=own_fid, allow_pickle=allow_pickle, pickle_kwargs=pickle_kwargs, max_header_size=max_header_size)
            return ret
        elif magic == format.MAGIC_PREFIX:
            if mmap_mode:
                if allow_pickle:
                    max_header_size = 2 ** 64
                return format.open_memmap(file, mode=mmap_mode, max_header_size=max_header_size)
            else:
                return format.read_array(fid, allow_pickle=allow_pickle, pickle_kwargs=pickle_kwargs, max_header_size=max_header_size)
        else:
            if not allow_pickle:
                raise ValueError('This file contains pickled (object) data. If you trust the file you can load it unsafely using the `allow_pickle=` keyword argument or `pickle.load()`.')
            try:
                return pickle.load(fid, **pickle_kwargs)
            except Exception as e:
