@array_function_dispatch(_tile_dispatcher)
def tile(A, reps):
    try:
        tup = tuple(reps)
    except TypeError:
        tup = (reps,)
    d = len(tup)
    if all((x == 1 for x in tup)) and isinstance(A, _nx.ndarray):
        return _nx.array(A, copy=True, subok=True, ndmin=d)
    else:
        c = _nx.array(A, copy=None, subok=True, ndmin=d)
    if d < c.ndim:
        tup = (1,) * (c.ndim - d) + tup
    shape_out = tuple((s * t for s, t in zip(c.shape, tup)))
    n = c.size
    if n > 0:
        for dim_in, nrep in zip(c.shape, tup):
            if nrep != 1:
                c = c.reshape(-1, n).repeat(nrep, 0)
            n //= dim_in
    return c.reshape(shape_out)

@set_module('numpy.lib.stride_tricks')
def as_strided(x, shape=None, strides=None, subok=False, writeable=True, *, check_bounds=None):
    base = np.array(x, copy=None, subok=subok)
    interface = dict(base.__array_interface__)
    if shape is not None:
        interface['shape'] = tuple(shape)
    if strides is not None:
        interface['strides'] = tuple(strides)
    array = np.asarray(DummyArray(interface, base=base))
    array._set_dtype(base.dtype)
    view = _maybe_view_as_subclass(base, array)
    if view.flags.writeable and (not writeable):
        view.flags.writeable = False
    if check_bounds:
        while isinstance(base.base, np.ndarray):
            base = base.base
        base_low, base_high = byte_bounds(base)
        view_low, view_high = byte_bounds(view)
        if view_low < base_low:
            raise ValueError(f'Given shape and strides would access memory out of bounds. View starts {base_low - view_low} bytes before lowest address')
        if view_high > base_high:
            raise ValueError(f'Given shape and strides would access memory out of bounds. View ends {view_high - base_high} bytes after highest address')
    return view

@array_function_dispatch(_sliding_window_view_dispatcher, module='numpy.lib.stride_tricks')
def sliding_window_view(x, window_shape, axis=None, *, subok=False, writeable=False):
    window_shape = tuple(window_shape) if np.iterable(window_shape) else (window_shape,)
    x = np.array(x, copy=None, subok=subok)
    window_shape_array = np.array(window_shape)
    if np.any(window_shape_array < 0):
        raise ValueError('`window_shape` cannot contain negative values')
    if axis is None:
        axis = tuple(range(x.ndim))
        if len(window_shape) != len(axis):
            raise ValueError(f'Since axis is `None`, must provide window_shape for all dimensions of `x`; got {len(window_shape)} window_shape elements and `x.ndim` is {x.ndim}.')
    else:
        axis = normalize_axis_tuple(axis, x.ndim, allow_duplicate=True)
        if len(window_shape) != len(axis):
            raise ValueError(f'Must provide matching length window_shape and axis; got {len(window_shape)} window_shape elements and {len(axis)} axes elements.')
    out_strides = x.strides + tuple((x.strides[ax] for ax in axis))
    x_shape_trimmed = list(x.shape)
    for ax, dim in zip(axis, window_shape):
        if x_shape_trimmed[ax] < dim:
            raise ValueError('window shape cannot be larger than input array shape')
        x_shape_trimmed[ax] -= dim - 1
    out_shape = tuple(x_shape_trimmed) + window_shape
    return as_strided(x, strides=out_strides, shape=out_shape, subok=subok, writeable=writeable)

@array_function_dispatch(_broadcast_to_dispatcher, module='numpy')
def broadcast_to(array, shape, subok=False):
    return _broadcast_to(array, shape, subok=subok, readonly=True)

def _broadcast_shape(*args):
    b = np.broadcast(*args[:64])
    for pos in range(64, len(args), 63):
        b = broadcast_to(0, b.shape)
        b = np.broadcast(b, *args[pos:pos + 63])
    return b.shape

@set_module('numpy')
def broadcast_shapes(*args):
