@finalize_array_function_like
@set_module('numpy')
def eye(N, M=None, k=0, dtype=float, order='C', *, device=None, like=None):
    if like is not None:
        return _eye_with_like(like, N, M=M, k=k, dtype=dtype, order=order, device=device)
    if M is None:
        M = N
    m = zeros((N, M), dtype=dtype, order=order, device=device)
    if k >= M:
        return m
    M = operator.index(M)
    k = operator.index(k)
    if k >= 0:
        i = k
    else:
        i = -k * M
    m[:M - k].flat[i::M + 1] = 1
    return m

@array_function_dispatch(_diag_dispatcher)
def diag(v, k=0):
    v = asanyarray(v)
    s = v.shape
    if len(s) == 1:
        n = s[0] + abs(k)
        res = zeros((n, n), v.dtype)
        if k >= 0:
            i = k
        else:
            i = -k * n
        res[:n - k].flat[i::n + 1] = v
        return res
    elif len(s) == 2:
        return diagonal(v, k)
    else:
        raise ValueError('Input must be 1- or 2-d.')

@array_function_dispatch(_diag_dispatcher)
def diagflat(v, k=0):
    conv = _array_converter(v)
    v, = conv.as_arrays(subok=False)
    v = v.ravel()
    s = len(v)
    n = s + abs(k)
    res = zeros((n, n), v.dtype)
    if k >= 0:
        i = arange(0, n - k, dtype=intp)
        fi = i + k + i * n
    else:
        i = arange(0, n + k, dtype=intp)
        fi = i + (i - k) * n
    res.flat[fi] = v
    return conv.wrap(res)

@finalize_array_function_like
@set_module('numpy')
def tri(N, M=None, k=0, dtype=float, *, like=None):
    warning_for_type = None
    try:
        N = operator.index(N)
    except TypeError:
        warning_for_type = warning_for_type or type(N)
    if like is not None:
        return _tri_with_like(like, N, M=M, k=k, dtype=dtype)
    if M is None:
        M = N
    else:
        try:
            M = operator.index(M)
        except TypeError:
            warning_for_type = warning_for_type or type(M)
    try:
        k = operator.index(k)
    except TypeError:
        warning_for_type = warning_for_type or type(k)
    m = greater_equal.outer(arange(N, dtype=_min_int(0, N)), arange(-k, M - k, dtype=_min_int(-k, M - k)))
    m = m.astype(dtype, copy=False)
    if warning_for_type:
        warnings.warn(f'Cannot convert {warning_for_type.__name__} safely to an integer.This will raise an error in future versions (Deprecated NumPy 2.5)', DeprecationWarning, skip_file_prefixes=(os.path.dirname(__file__),))
    return m

