def common_type(*arrays):
    is_complex = False
    precision = 0
    for a in arrays:
        try:
            t = a.dtype.type
        except AttributeError:
            raise TypeError(f"common_type takes array inputs, not '{a}'. To find a common type for dtypes or scalar types use np.result_type or np.promote_types instead.") from None
        if iscomplexobj(a):
            is_complex = True
        if issubclass(t, _nx.integer):
            p = 2
        else:
            p = array_precision.get(t)
            if p is None:
                raise TypeError("can't get common type for non-numeric array")
        precision = max(precision, p)
    if is_complex:
        return array_type[1][precision]
    else:
        return array_type[0][precision]

