def lineType(line):
    if isBlank(line):
        return COMMENT
    elif isLabel(line):
        return STATEMENT
    elif isComment(line):
        return COMMENT
    elif isContinuation(line):
        return CONTINUATION
    else:
        return STATEMENT

def fortranSourceLines(fo):
    numberingiter = LineIterator(fo)
    with_extra = itertools.chain(numberingiter, [''])
    pushbackiter = PushbackIterator(with_extra)
    for line in pushbackiter:
        t = lineType(line)
        if t == COMMENT:
            continue
        elif t == STATEMENT:
            lines = [line]
            for next_line in pushbackiter:
                t = lineType(next_line)
                if t == CONTINUATION:
                    lines.append(next_line[6:])
                else:
                    pushbackiter.pushback(next_line)
                    break
            yield (numberingiter.lineno, ''.join(lines))
        else:
            raise ValueError(f'jammed: continuation line not expected: {fo.name}:{numberingiter.lineno}')

def resolveAllDependencies(self):
    done_this = set()
    last_todo = set()
    while True:
        todo = set(self.allRoutineNames()) - done_this
        if todo == last_todo:
            break
        for rn in todo:
            r = self.getRoutine(rn)
            deps = r.dependencies()
            for d in deps:
                self.addRoutine(d)
            done_this.add(rn)
        last_todo = todo
    return todo

def _deprecate_argsort_axis(arr):
    if arr.ndim <= 1:
        return -1
    else:
        warnings.warn('In the future the default for argsort will be axis=-1, not the current None, to match its documentation and np.argsort. Explicitly pass -1 or None to silence this warning.', MaskedArrayFutureWarning, stacklevel=3)
        return None

def doc_note(initialdoc, note):
    if initialdoc is None:
        return
    if note is None:
        return initialdoc
    notesplit = re.split('\\n\\s*?Notes\\n\\s*?-----', inspect.cleandoc(initialdoc))
    notedoc = f'\n\nNotes\n-----\n{inspect.cleandoc(note)}\n'
    return ''.join(notesplit[:1] + [notedoc] + notesplit[1:])

def _recursive_fill_value(dtype, f):
    if dtype.names is not None:
        vals = []
        for name in dtype.names:
            field_dtype = dtype[name]
            val = _recursive_fill_value(field_dtype, f)
            if np.issubdtype(field_dtype, np.datetime64):
                if isinstance(val, dt.date):
                    val = np.datetime64(val)
                    val = np.array(val)
                elif isinstance(val, (int, np.integer)):
                    val = np.array(val).astype(field_dtype)
                else:
                    val = np.array(val)
            else:
                val = np.array(val)
            vals.append(val)
        return np.array(tuple(vals), dtype=dtype)[()]
    elif dtype.subdtype:
        subtype, shape = dtype.subdtype
        subval = _recursive_fill_value(subtype, f)
        return np.full(shape, subval)
    else:
        return f(dtype)

def _get_dtype_of(obj):
    if isinstance(obj, np.dtype):
        return obj
    elif hasattr(obj, 'dtype'):
        return obj.dtype
    else:
        return np.asanyarray(obj).dtype

def default_fill_value(obj):

    def _scalar_fill_value(dtype):
        if dtype.kind in 'Mm':
            return default_filler.get(dtype.str[1:], '?')
        else:
            return default_filler.get(dtype.kind, '?')
    dtype = _get_dtype_of(obj)
    return _recursive_fill_value(dtype, _scalar_fill_value)

def _recursive_set_fill_value(fillvalue, dt):
    fillvalue = np.resize(fillvalue, len(dt.names))
    output_value = []
    for fval, name in zip(fillvalue, dt.names):
        cdtype = dt[name]
        if cdtype.subdtype:
            cdtype = cdtype.subdtype[0]
        if cdtype.names is not None:
            output_value.append(tuple(_recursive_set_fill_value(fval, cdtype)))
        else:
            output_value.append(np.array(fval, dtype=cdtype).item())
    return tuple(output_value)

def _check_fill_value(fill_value, ndtype):
    ndtype = np.dtype(ndtype)
    if fill_value is None:
        fill_value = default_fill_value(ndtype)
        if ndtype.kind == 'u':
            fill_value = np.uint(fill_value)
    elif ndtype.names is not None:
        if isinstance(fill_value, (ndarray, np.void)):
            try:
                fill_value = np.asarray(fill_value, dtype=ndtype)
            except ValueError as e:
                err_msg = 'Unable to transform %s to dtype %s'
                raise ValueError(err_msg % (fill_value, ndtype)) from e
        else:
            fill_value = np.asarray(fill_value, dtype=object)
            fill_value = np.array(_recursive_set_fill_value(fill_value, ndtype), dtype=ndtype)
    elif isinstance(fill_value, str) and ndtype.char not in 'OSTVU':
        err_msg = 'Cannot set fill value of string with array of dtype %s'
        raise TypeError(err_msg % ndtype)
    else:
        try:
            fill_value = np.asarray(fill_value, dtype=ndtype)
        except (OverflowError, ValueError) as e:
            err_msg = 'Cannot convert fill_value %s to dtype %s'
            raise TypeError(err_msg % (fill_value, ndtype)) from e
    return np.array(fill_value)

def set_fill_value(a, fill_value):
    if isinstance(a, MaskedArray):
        a.set_fill_value(fill_value)

def get_fill_value(a):
    if isinstance(a, MaskedArray):
        result = a.fill_value
    else:
        result = default_fill_value(a)
    return result

def common_fill_value(a, b):
    t1 = get_fill_value(a)
    t2 = get_fill_value(b)
    if t1 == t2:
        return t1
    return None

def filled(a, fill_value=None):
    if hasattr(a, 'filled'):
        return a.filled(fill_value)
    elif isinstance(a, ndarray):
        return a
    elif isinstance(a, dict):
        return np.array(a, 'O')
    else:
        return np.array(a)

def get_masked_subclass(*arrays):
    if len(arrays) == 1:
        arr = arrays[0]
        if isinstance(arr, MaskedArray):
            rcls = type(arr)
        else:
            rcls = MaskedArray
    else:
        arrcls = [type(a) for a in arrays]
        rcls = arrcls[0]
        if not issubclass(rcls, MaskedArray):
            rcls = MaskedArray
        for cls in arrcls[1:]:
            if issubclass(cls, rcls):
                rcls = cls
    if rcls.__name__ == 'MaskedConstant':
        return MaskedArray
    return rcls

def getdata(a, subok=True):
    try:
        data = a._data
    except AttributeError:
        data = np.array(a, copy=None, subok=subok)
    if not subok:
        return data.view(ndarray)
    return data

def fix_invalid(a, mask=nomask, copy=True, fill_value=None):
    a = masked_array(a, copy=copy, mask=mask, subok=True)
    invalid = np.logical_not(np.isfinite(a._data))
    if not invalid.any():
        return a
    a._mask |= invalid
    if fill_value is None:
        fill_value = a.fill_value
    a._data[invalid] = fill_value
    return a

def _replace_dtype_fields_recursive(dtype, primitive_dtype):
    _recurse = _replace_dtype_fields_recursive
    if dtype.names is not None:
        descr = []
        for name in dtype.names:
            field = dtype.fields[name]
            if len(field) == 3:
                name = (field[-1], name)
            descr.append((name, _recurse(field[0], primitive_dtype)))
        new_dtype = np.dtype(descr)
    elif dtype.subdtype:
        descr = list(dtype.subdtype)
        descr[0] = _recurse(dtype.subdtype[0], primitive_dtype)
        new_dtype = np.dtype(tuple(descr))
    else:
        new_dtype = primitive_dtype
    if new_dtype == dtype:
        new_dtype = dtype
    return new_dtype

def _replace_dtype_fields(dtype, primitive_dtype):
    dtype = np.dtype(dtype)
    primitive_dtype = np.dtype(primitive_dtype)
    return _replace_dtype_fields_recursive(dtype, primitive_dtype)

def getmaskarray(arr):
    mask = getmask(arr)
    if mask is nomask:
        mask = make_mask_none(np.shape(arr), getattr(arr, 'dtype', None))
    return mask

def is_mask(m):
    try:
        return m.dtype.type is MaskType
    except AttributeError:
        return False

def _shrink_mask(m):
    if m.dtype.names is None and (not m.any()):
        return nomask
    else:
        return m

def make_mask(m, copy=False, shrink=True, dtype=MaskType):
    if m is nomask:
        return nomask
    dtype = make_mask_descr(dtype)
    if isinstance(m, ndarray) and m.dtype.fields and (dtype == np.bool):
        return np.ones(m.shape, dtype=dtype)
    copy = None if not copy else True
    result = np.array(filled(m, True), copy=copy, dtype=dtype, subok=True)
    if shrink:
        result = _shrink_mask(result)
    return result

def make_mask_none(newshape, dtype=None):
    if dtype is None:
        result = np.zeros(newshape, dtype=MaskType)
    else:
        result = np.zeros(newshape, dtype=make_mask_descr(dtype))
    return result

def mask_or(m1, m2, copy=False, shrink=True):
    if m1 is nomask or m1 is False:
        dtype = getattr(m2, 'dtype', MaskType)
        return make_mask(m2, copy=copy, shrink=shrink, dtype=dtype)
    if m2 is nomask or m2 is False:
        dtype = getattr(m1, 'dtype', MaskType)
        return make_mask(m1, copy=copy, shrink=shrink, dtype=dtype)
    if m1 is m2 and is_mask(m1):
        return _shrink_mask(m1) if shrink else m1
    dtype1, dtype2 = (getattr(m1, 'dtype', None), getattr(m2, 'dtype', None))
    if dtype1 != dtype2:
        raise ValueError(f"Incompatible dtypes '{dtype1}'<>'{dtype2}'")
    if dtype1.names is not None:
        newmask = np.empty(np.broadcast(m1, m2).shape, dtype1)
        _recursive_mask_or(m1, m2, newmask)
        return newmask
    return make_mask(umath.logical_or(m1, m2), copy=copy, shrink=shrink)

def flatten_mask(mask):

    def _flatmask(mask):
        """Flatten the mask and returns a (maybe nested) sequence of booleans."""
        mnames = mask.dtype.names
        if mnames is not None:
            return [flatten_mask(mask[name]) for name in mnames]
        else:
            return mask

    def _flatsequence(sequence):
        """Generates a flattened version of the sequence."""
        try:
            for element in sequence:
                if hasattr(element, '__iter__'):
                    yield from _flatsequence(element)
                else:
                    yield element
        except TypeError:
            yield sequence
    mask = np.asarray(mask)
    flattened = _flatsequence(_flatmask(mask))
    return np.array(list(flattened), dtype=bool)

def _check_mask_axis(mask, axis, keepdims=np._NoValue):
    kwargs = {} if keepdims is np._NoValue else {'keepdims': keepdims}
    if mask is not nomask:
        return mask.all(axis=axis, **kwargs)
    return nomask

def masked_where(condition, a, copy=True):
    cond = make_mask(condition, shrink=False)
    a = np.array(a, copy=copy, subok=True)
    cshape, ashape = (cond.shape, a.shape)
    if cshape and cshape != ashape:
        raise IndexError(f'Inconsistent shape between the condition and the input (got {cshape} and {ashape})')
    if hasattr(a, '_mask'):
        cond = mask_or(cond, a._mask)
        cls = type(a)
    else:
        cls = MaskedArray
    result = a.view(cls)
    result.mask = _shrink_mask(cond)
    if not copy and hasattr(a, '_mask') and (getmask(a) is nomask):
        a._mask = result._mask.view()
    return result

def masked_inside(x, v1, v2, copy=True):
    if v2 < v1:
        v1, v2 = (v2, v1)
    xf = filled(x)
    condition = (xf >= v1) & (xf <= v2)
    return masked_where(condition, x, copy=copy)

def masked_outside(x, v1, v2, copy=True):
    if v2 < v1:
        v1, v2 = (v2, v1)
    xf = filled(x)
    condition = (xf < v1) | (xf > v2)
    return masked_where(condition, x, copy=copy)

def masked_object(x, value, copy=True, shrink=True):
    if isMaskedArray(x):
        condition = umath.equal(x._data, value)
        mask = x._mask
    else:
        condition = umath.equal(np.asarray(x), value)
        mask = nomask
    mask = mask_or(mask, make_mask(condition, shrink=shrink))
    return masked_array(x, mask=mask, copy=copy, fill_value=value)

def masked_values(x, value, rtol=1e-05, atol=1e-08, copy=True, shrink=True):
    xnew = filled(x, value)
    if np.issubdtype(xnew.dtype, np.floating):
        mask = np.isclose(xnew, value, atol=atol, rtol=rtol)
    else:
        mask = umath.equal(xnew, value)
    ret = masked_array(xnew, mask=mask, copy=copy, fill_value=value)
    if shrink:
        ret.shrink_mask()
    return ret

def masked_invalid(a, copy=True):
    a = np.array(a, copy=None, subok=True)
    res = masked_where(~np.isfinite(a), a, copy=copy)
    if res._mask is nomask:
        res._mask = make_mask_none(res.shape, res.dtype)
    return res

def _recursive_printoption(result, mask, printopt):
    names = result.dtype.names
    if names is not None:
        for name in names:
            curdata = result[name]
            curmask = mask[name]
            _recursive_printoption(curdata, curmask, printopt)
    else:
        np.copyto(result, printopt, where=mask)

def _recursive_filled(a, mask, fill_value):
    names = a.dtype.names
    for name in names:
        current = a[name]
        if current.dtype.names is not None:
            _recursive_filled(current, mask[name], fill_value[name])
        else:
            np.copyto(current, fill_value[name], where=mask[name])

def flatten_structured_array(a):

    def flatten_sequence(iterable):
        """
        Flattens a compound of nested iterables.

        """
        for elm in iter(iterable):
            if hasattr(elm, '__iter__') and (not isinstance(elm, (str, bytes))):
                yield from flatten_sequence(elm)
            else:
                yield elm
    a = np.asanyarray(a)
    inishape = a.shape
    a = a.ravel()
    if isinstance(a, MaskedArray):
        out = np.array([tuple(flatten_sequence(d.item())) for d in a._data])
        out = out.view(MaskedArray)
        out._mask = np.array([tuple(flatten_sequence(d.item())) for d in getmaskarray(a)])
    else:
        out = np.array([tuple(flatten_sequence(d.item())) for d in a])
    if len(inishape) > 1:
        newshape = list(out.shape)
        newshape[0] = inishape
        out = out.reshape(tuple(flatten_sequence(newshape)))
    return out

def _arraymethod(funcname, onmask=True):

    def wrapped_method(self, *args, **params):
        result = getattr(self._data, funcname)(*args, **params)
        result = result.view(type(self))
        result._update_from(self)
        mask = self._mask
        if not onmask:
            result.__setmask__(mask)
        elif mask is not nomask:
            result._mask = getattr(mask, funcname)(*args, **params)
        return result
    methdoc = getattr(ndarray, funcname, None) or getattr(np, funcname, None)
    if methdoc is not None:
        wrapped_method.__doc__ = methdoc.__doc__
    wrapped_method.__name__ = funcname
    return wrapped_method

def _mareconstruct(subtype, baseclass, baseshape, basetype):
    _data = ndarray.__new__(baseclass, baseshape, basetype)
    _mask = ndarray.__new__(ndarray, baseshape, make_mask_descr(basetype))
    return subtype.__new__(subtype, _data, mask=_mask, dtype=basetype)

def is_masked(x):
    m = getmask(x)
    if m is nomask:
        return False
    elif m.any():
        return True
    return False

def _frommethod(methodname: str, reversed: bool=False):
    method = getattr(MaskedArray, methodname)
    assert callable(method)
    signature = inspect.signature(method)
    params = list(signature.parameters.values())
    params[0] = params[0].replace(name='a')
    if reversed:
        assert len(params) >= 2
        params[0], params[1] = (params[1], params[0])

        def wrapper(a, b, *args, **params):
            return getattr(asanyarray(b), methodname)(a, *args, **params)
    else:

        def wrapper(a, *args, **params):
            return getattr(asanyarray(a), methodname)(*args, **params)
    wrapper.__signature__ = signature.replace(parameters=params)
    wrapper.__name__ = wrapper.__qualname__ = methodname
    if method.__doc__ is not None:
        str_signature = f'{methodname}{signature}'
        wrapper.__doc__ = f'    {str_signature}\n{method.__doc__}'
    return wrapper

def take(a, indices, axis=None, out=None, mode='raise'):
    a = masked_array(a)
    return a.take(indices, axis=axis, out=out, mode=mode)

def power(a, b, third=None):
    if third is not None:
        raise MaskError('3-argument power not supported.')
    ma = getmask(a)
    mb = getmask(b)
    m = mask_or(ma, mb)
    fa = getdata(a)
    fb = getdata(b)
    if isinstance(a, MaskedArray):
        basetype = type(a)
    else:
        basetype = MaskedArray
    with np.errstate(divide='ignore', invalid='ignore'):
        result = np.where(m, fa, umath.power(fa, fb)).view(basetype)
    result._update_from(a)
    invalid = np.logical_not(np.isfinite(result.view(ndarray)))
    if m is not nomask:
        if not result.ndim:
            return masked
        result._mask = np.logical_or(m, invalid)
    if invalid.any():
        if not result.ndim:
            return masked
        elif result._mask is nomask:
            result._mask = invalid
        result._data[invalid] = result.fill_value
    return result

def argsort(a, axis=np._NoValue, kind=None, order=None, endwith=True, fill_value=None, *, stable=None, descending=None):
    a = np.asanyarray(a)
    if axis is np._NoValue:
        axis = _deprecate_argsort_axis(a)
    if isinstance(a, MaskedArray):
        return a.argsort(axis=axis, kind=kind, order=order, endwith=endwith, fill_value=fill_value, stable=stable, descending=descending)
    else:
        return a.argsort(axis=axis, kind=kind, order=order, stable=stable, descending=descending)

def sort(a, axis=-1, kind=None, order=None, endwith=True, fill_value=None, *, stable=None, descending=None):
    a = np.array(a, copy=True, subok=True)
    if axis is None:
        a = a.flatten()
        axis = 0
    if isinstance(a, MaskedArray):
        a.sort(axis=axis, kind=kind, order=order, endwith=endwith, fill_value=fill_value, stable=stable, descending=descending)
    else:
        a.sort(axis=axis, kind=kind, order=order, stable=stable, descending=descending)
    return a

def concatenate(arrays, axis=0):
    d = np.concatenate([getdata(a) for a in arrays], axis)
    rcls = get_masked_subclass(*arrays)
    data = d.view(rcls)
    for x in arrays:
        if getmask(x) is not nomask:
            break
    else:
        return data
    dm = np.concatenate([getmaskarray(a) for a in arrays], axis)
    dm = dm.reshape(d.shape)
    data._mask = _shrink_mask(dm)
    return data

def diag(v, k=0):
    output = np.diag(v, k).view(MaskedArray)
    if getmask(v) is not nomask:
        output._mask = np.diag(v._mask, k)
    return output

def left_shift(a, n):
    m = getmask(a)
    if m is nomask:
        d = umath.left_shift(filled(a), n)
        return masked_array(d)
    else:
        d = umath.left_shift(filled(a, 0), n)
        return masked_array(d, mask=m)

def right_shift(a, n):
    m = getmask(a)
    if m is nomask:
        d = umath.right_shift(filled(a), n)
        return masked_array(d)
    else:
        d = umath.right_shift(filled(a, 0), n)
        return masked_array(d, mask=m)

def put(a, indices, values, mode='raise'):
    try:
        return a.put(indices, values, mode=mode)
    except AttributeError:
        return np.asarray(a).put(indices, values, mode=mode)

def putmask(a, mask, values):
    if not isinstance(a, MaskedArray):
        a = a.view(MaskedArray)
    valdata, valmask = (getdata(values), getmask(values))
    if getmask(a) is nomask:
        if valmask is not nomask:
            a._sharedmask = True
            a._mask = make_mask_none(a.shape, a.dtype)
            np.copyto(a._mask, valmask, where=mask)
    elif a._hardmask:
        if valmask is not nomask:
            m = a._mask.copy()
            np.copyto(m, valmask, where=mask)
            a.mask |= m
    else:
        if valmask is nomask:
            valmask = getmaskarray(values)
        np.copyto(a._mask, valmask, where=mask)
    np.copyto(a._data, valdata, where=mask)

def transpose(a, axes=None):
    try:
        return a.transpose(axes)
    except AttributeError:
        return np.asarray(a).transpose(axes).view(MaskedArray)

def reshape(a, new_shape, order='C'):
    try:
        return a.reshape(new_shape, order=order)
    except AttributeError:
        _tmp = np.asarray(a).reshape(new_shape, order=order)
        return _tmp.view(MaskedArray)

def resize(x, new_shape):
    m = getmask(x)
    if m is not nomask:
        m = np.resize(m, new_shape)
    result = np.resize(x, new_shape).view(get_masked_subclass(x))
    if result.ndim:
        result._mask = m
    return result

def diff(a, /, n=1, axis=-1, prepend=np._NoValue, append=np._NoValue):
    if n == 0:
        return a
    if n < 0:
        raise ValueError('order must be non-negative but got ' + repr(n))
    a = np.ma.asanyarray(a)
    if a.ndim == 0:
        raise ValueError('diff requires input that is at least one dimensional')
    combined = []
    if prepend is not np._NoValue:
        prepend = np.ma.asanyarray(prepend)
        if prepend.ndim == 0:
            shape = list(a.shape)
            shape[axis] = 1
            prepend = np.broadcast_to(prepend, tuple(shape))
        combined.append(prepend)
    combined.append(a)
    if append is not np._NoValue:
        append = np.ma.asanyarray(append)
        if append.ndim == 0:
            shape = list(a.shape)
            shape[axis] = 1
            append = np.broadcast_to(append, tuple(shape))
        combined.append(append)
    if len(combined) > 1:
        a = np.ma.concatenate(combined, axis)
    return np.diff(a, n, axis)

def where(condition, x=_NoValue, y=_NoValue):
    missing = (x is _NoValue, y is _NoValue).count(True)
    if missing == 1:
        raise ValueError("Must provide both 'x' and 'y' or neither.")
    if missing == 2:
        return nonzero(condition)
    cf = filled(condition, False)
    xd = getdata(x)
    yd = getdata(y)
    cm = getmaskarray(condition)
    xm = getmaskarray(x)
    ym = getmaskarray(y)
    if x is masked and y is not masked:
        xd = np.zeros((), dtype=yd.dtype)
        xm = np.ones((), dtype=ym.dtype)
    elif y is masked and x is not masked:
        yd = np.zeros((), dtype=xd.dtype)
        ym = np.ones((), dtype=xm.dtype)
    data = np.where(cf, xd, yd)
    mask = np.where(cf, xm, ym)
    mask = np.where(cm, np.ones((), dtype=mask.dtype), mask)
    mask = _shrink_mask(mask)
    return masked_array(data, mask=mask)

def choose(indices, choices, out=None, mode='raise'):

    def fmask(x):
        """Returns the filled array, or True if masked."""
        if x is masked:
            return True
        return filled(x)

    def nmask(x):
        """Returns the mask, True if ``masked``, False if ``nomask``."""
        if x is masked:
            return True
        return getmask(x)
    c = filled(indices, 0)
    masks = [nmask(x) for x in choices]
    data = [fmask(x) for x in choices]
    outputmask = np.choose(c, masks, mode=mode)
    outputmask = make_mask(mask_or(outputmask, getmask(indices)), copy=False, shrink=True)
    d = np.choose(c, data, mode=mode, out=out).view(MaskedArray)
    if out is not None:
        if isinstance(out, MaskedArray):
            out.__setmask__(outputmask)
        return out
    d.__setmask__(outputmask)
    return d

def round(a, decimals=0, out=None):
    if out is None:
        return np.round(a, decimals, out)
    else:
        np.round(getdata(a), decimals, out)
        if hasattr(out, '_mask'):
            out._mask = getmask(a)
        return out

def round_(a, decimals=0, out=None):
    warnings.warn('numpy.ma.round_ is deprecated. Use numpy.ma.round instead.', DeprecationWarning, stacklevel=2)
    return round(a, decimals, out)

def _mask_propagate(a, axis):
    a = array(a, subok=False)
    m = getmask(a)
    if m is nomask or not m.any() or axis is None:
        return a
    a._mask = a._mask.copy()
    axes = normalize_axis_tuple(axis, a.ndim)
    for ax in axes:
        a._mask |= m.any(axis=ax, keepdims=True)
    return a

def dot(a, b, strict=False, out=None):
    if strict is True:
        if np.ndim(a) == 0 or np.ndim(b) == 0:
            pass
        elif b.ndim == 1:
            a = _mask_propagate(a, a.ndim - 1)
            b = _mask_propagate(b, b.ndim - 1)
        else:
            a = _mask_propagate(a, a.ndim - 1)
            b = _mask_propagate(b, b.ndim - 2)
    am = ~getmaskarray(a)
    bm = ~getmaskarray(b)
    if out is None:
        d = np.dot(filled(a, 0), filled(b, 0))
        m = ~np.dot(am, bm)
        if np.ndim(d) == 0:
            d = np.asarray(d)
        r = d.view(get_masked_subclass(a, b))
        r.__setmask__(m)
        return r
    else:
        d = np.dot(filled(a, 0), filled(b, 0), out._data)
        if out.mask.shape != d.shape:
            out._mask = np.empty(d.shape, MaskType)
        np.dot(am, bm, out._mask)
        np.logical_not(out._mask, out._mask)
        return out

def inner(a, b):
    fa = filled(a, 0)
    fb = filled(b, 0)
    if fa.ndim == 0:
        fa = fa.reshape((1,))
    if fb.ndim == 0:
        fb = fb.reshape((1,))
    return np.inner(fa, fb).view(MaskedArray)

def outer(a, b):
    fa = filled(a, 0).ravel()
    fb = filled(b, 0).ravel()
    d = np.outer(fa, fb)
    ma = getmask(a)
    mb = getmask(b)
    if ma is nomask and mb is nomask:
        return masked_array(d)
    ma = getmaskarray(a)
    mb = getmaskarray(b)
    m = make_mask(1 - np.outer(1 - ma, 1 - mb), copy=False)
    return masked_array(d, mask=m)

def _convolve_or_correlate(f, a, v, mode, propagate_mask):
    if propagate_mask:
        mask = f(getmaskarray(a), np.ones(np.shape(v), dtype=bool), mode=mode) | f(np.ones(np.shape(a), dtype=bool), getmaskarray(v), mode=mode)
        data = f(getdata(a), getdata(v), mode=mode)
    else:
        mask = ~f(~getmaskarray(a), ~getmaskarray(v), mode=mode)
        data = f(filled(a, 0), filled(v, 0), mode=mode)
    return masked_array(data, mask=mask)

def allequal(a, b, fill_value=True):
    m = mask_or(getmask(a), getmask(b))
    if m is nomask:
        x = getdata(a)
        y = getdata(b)
        d = umath.equal(x, y)
        return d.all()
    elif fill_value:
        x = getdata(a)
        y = getdata(b)
        d = umath.equal(x, y)
        dm = array(d, mask=m, copy=False)
        return dm.filled(True).all(None)
    else:
        return False

def allclose(a, b, masked_equal=True, rtol=1e-05, atol=1e-08):
    x = masked_array(a, copy=False)
    y = masked_array(b, copy=False)
    if y.dtype.kind != 'm':
        dtype = np.result_type(y, 1.0)
        if y.dtype != dtype:
            y = masked_array(y, dtype=dtype, copy=False)
    m = mask_or(getmask(x), getmask(y))
    xinf = np.isinf(masked_array(x, copy=False, mask=m)).filled(False)
    if not np.all(xinf == filled(np.isinf(y), False)):
        return False
    if not np.any(xinf):
        d = filled(less_equal(absolute(x - y), atol + rtol * absolute(y)), masked_equal)
        return np.all(d)
    if not np.all(filled(x[xinf] == y[xinf], masked_equal)):
        return False
    x = x[~xinf]
    y = y[~xinf]
    d = filled(less_equal(absolute(x - y), atol + rtol * absolute(y)), masked_equal)
    return np.all(d)

def asarray(a, dtype=None, order=None):
    order = order or 'C'
    return masked_array(a, dtype=dtype, copy=False, keep_mask=True, subok=False, order=order)

def asanyarray(a, dtype=None, order=None):
    if isinstance(a, MaskedArray) and (dtype is None or dtype == a.dtype) and (order in {None, 'A', 'K'} or (order == 'C' and a.flags.carray) or (order == 'F' and a.flags.f_contiguous)):
        return a
    return masked_array(a, dtype=dtype, copy=False, keep_mask=True, subok=True, order=order)

def _convert2ma(funcname: str, np_ret: str, np_ma_ret: str, params: dict[str, str] | None=None):
    func = getattr(np, funcname)
    params = params or {}

    @functools.wraps(func, assigned=set(functools.WRAPPER_ASSIGNMENTS) - {'__module__'})
    def wrapper(*args, **kwargs):
        common_params = kwargs.keys() & params.keys()
        extras = params | {p: kwargs.pop(p) for p in common_params}
        result = func.__call__(*args, **kwargs).view(MaskedArray)
        if 'fill_value' in common_params:
            result.fill_value = extras['fill_value']
        if 'hardmask' in common_params:
            result._hardmask = bool(extras['hardmask'])
        return result
    del wrapper.__wrapped__
    try:
        signature = inspect.signature(func)
    except ValueError:
        signature = inspect.Signature([inspect.Parameter('args', inspect.Parameter.VAR_POSITIONAL), inspect.Parameter('kwargs', inspect.Parameter.VAR_KEYWORD)])
    if params:
        sig_params = list(signature.parameters.values())
        sig_kwargs = None
        if sig_params[-1].kind is inspect.Parameter.VAR_KEYWORD:
            sig_kwargs = sig_params.pop()
        for param_name, default in params.items():
            new_param = inspect.Parameter(param_name, inspect.Parameter.KEYWORD_ONLY, default=default)
            sig_params.append(new_param)
        if sig_kwargs:
            sig_params.append(sig_kwargs)
        signature = signature.replace(parameters=sig_params)
    wrapper.__signature__ = signature
    if func.__doc__ is not None:
        assert np_ret in func.__doc__, f'Failed to replace `{np_ret}` with `{np_ma_ret}`. The documentation string for return type, {np_ret}, is not found in the docstring for `np.{func.__name__}`. Fix the docstring for `np.{func.__name__}` or update the expected string for return type.'
        wrapper.__doc__ = inspect.cleandoc(func.__doc__).replace(np_ret, np_ma_ret)
    return wrapper

def __init__(self, a, b):
    if a > b:
        a, b = (b, a)
    self.a = a
    self.b = b

def __call__(self, x):
    with np.errstate(invalid='ignore'):
