        elif newmask:
            result = masked
        return result
    self.filled(fill_value).max(axis=axis, out=out, **kwargs)
    if isinstance(out, MaskedArray):
        outmask = getmask(out)
        if outmask is nomask:
            outmask = out._mask = make_mask_none(out.shape)
