def take(self, indices, axis=None, out=None, mode='raise'):
    _data, _mask = (self._data, self._mask)
    cls = type(self)
    maskindices = getmask(indices)
    if maskindices is not nomask:
        indices = indices.filled(0)
    if out is None:
        out = _data.take(indices, axis=axis, mode=mode)[...].view(cls)
    else:
        np.take(_data, indices, axis=axis, mode=mode, out=out)
    if isinstance(out, MaskedArray):
        if _mask is nomask:
            outmask = maskindices
        else:
            outmask = _mask.take(indices, axis=axis, mode=mode)
            outmask |= maskindices
        out.__setmask__(outmask)
    return out[()]

@property
def mT(self):
    if self.ndim < 2:
        raise ValueError('matrix transpose with ndim < 2 is undefined')
    if self._mask is nomask:
        return masked_array(data=self._data.mT)
    else:
        return masked_array(data=self.data.mT, mask=self.mask.mT)

def tolist(self, fill_value=None):
    _mask = self._mask
    if _mask is nomask:
        return self._data.tolist()
    if fill_value is not None:
        return self.filled(fill_value).tolist()
    names = self.dtype.names
    if names:
        result = self._data.astype([(_, object) for _ in names])
        for n in names:
            result[n][_mask[n]] = None
        return result.tolist()
    if _mask is nomask:
        return [None]
    inishape = self.shape
    result = np.array(self._data.ravel(), dtype=object)
    result[_mask.ravel()] = None
    result = result.reshape(inishape)
    return result.tolist()

def __getstate__(self):
    cf = 'CF'[self.flags.fnc]
    data_state = super().__reduce__()[2]
    return data_state + (getmaskarray(self).tobytes(cf), self._fill_value)

def __getitem__(self, indx):
    m = self._mask
    if isinstance(m[indx], ndarray):
        return masked_array(data=self._data[indx], mask=m[indx], fill_value=self._fill_value[indx], hard_mask=self._hardmask)
    if m is not nomask and m[indx]:
        return masked
    return self._data[indx]

def __iter__(self):
    _data, _mask = (self._data, self._mask)
    if _mask is nomask:
        yield from _data
    else:
        for d, m in zip(_data, _mask):
            if m:
                yield masked
            else:
                yield d

def tolist(self):
    _mask = self._mask
    if _mask is nomask:
        return self._data.tolist()
    result = []
    for d, m in zip(self._data, self._mask):
        if m:
            result.append(None)
        else:
            result.append(d.item())
    return tuple(result)

def reduce(self, target, axis=np._NoValue):
    target = narray(target, copy=None, subok=True)
    m = getmask(target)
    if axis is np._NoValue and target.ndim > 1:
        name = self.__name__
        warnings.warn(f'In the future the default for ma.{name}.reduce will be axis=0, not the current None, to match np.{name}.reduce. Explicitly pass 0 or None to silence this warning.', MaskedArrayFutureWarning, stacklevel=2)
        axis = None
    if axis is not np._NoValue:
        kwargs = {'axis': axis}
    else:
        kwargs = {}
    if m is nomask:
        t = self.f.reduce(target, **kwargs)
    else:
        target = target.filled(self.fill_value_func(target)).view(type(target))
        t = self.f.reduce(target, **kwargs)
        m = umath.logical_and.reduce(m, **kwargs)
        if hasattr(t, '_mask'):
            t._mask = m
        elif m:
            t = masked
    return t

def fmask(x):
    if x is masked:
        return True
    return filled(x)

def nmask(x):
    if x is masked:
        return True
    return getmask(x)

def _scalar_heuristic(arr, elem):
    if not isinstance(elem, np.ndarray):
        return True
    elif arr.dtype.type is np.object_:
        if arr.dtype is not elem.dtype:
            return True
    elif type(arr).__getitem__ == ndarray.__getitem__:
        return False
    return None

def _recursive_or(a, b):
    for name in a.dtype.names:
        af, bf = (a[name], b[name])
        if af.dtype.names is not None:
            _recursive_or(af, bf)
        else:
            af |= bf

def count_masked(arr, axis=None):
    m = getmaskarray(arr)
    return m.sum(axis)

def masked_all(shape, dtype=float):
    a = masked_array(np.empty(shape, dtype), mask=np.ones(shape, make_mask_descr(dtype)))
    return a

def _fromnxfunction_function(_fromnxfunction):

    def decorator(npfunc, /):

        def wrapper(*args, **kwargs):
            return _fromnxfunction(npfunc, *args, **kwargs)
        functools.update_wrapper(wrapper, npfunc, assigned=('__name__', '__qualname__'))
        wrapper.__doc__ = ma.doc_note(npfunc.__doc__, 'The function is applied to both the ``_data`` and the ``_mask``, if any.')
        return wrapper
    return decorator

@_fromnxfunction_function
def _fromnxfunction_single(npfunc, a, /, *args, **kwargs):
    return masked_array(data=npfunc(np.asarray(a), *args, **kwargs), mask=npfunc(getmaskarray(a), *args, **kwargs))

@_fromnxfunction_function
def _fromnxfunction_seq(npfunc, arys, /, *args, **kwargs):
    return masked_array(data=npfunc(tuple((np.asarray(a) for a in arys)), *args, **kwargs), mask=npfunc(tuple((getmaskarray(a) for a in arys)), *args, **kwargs))

@_fromnxfunction_function
def _fromnxfunction_allargs(npfunc, /, *arys, **kwargs):
    out = tuple((masked_array(data=npfunc(np.asarray(a), **kwargs), mask=npfunc(getmaskarray(a), **kwargs)) for a in arys))
    return out[0] if len(out) == 1 else out

def flatten_inplace(seq):
    k = 0
    while k != len(seq):
        while hasattr(seq[k], '__iter__'):
            seq[k:k + 1] = seq[k]
        k += 1
    return seq

def apply_over_axes(func, a, axes):
    val = asarray(a)
    N = a.ndim
    if array(axes).ndim == 0:
        axes = (axes,)
    for axis in axes:
        if axis < 0:
            axis = N + axis
        args = (val, axis)
        res = func(*args)
        if res.ndim == val.ndim:
            val = res
        else:
            res = ma.expand_dims(res, axis)
            if res.ndim == val.ndim:
                val = res
            else:
                raise ValueError('function is not returning an array of the correct shape')
    return val

def average(a, axis=None, weights=None, returned=False, *, keepdims=np._NoValue):
    a = asarray(a)
    m = getmask(a)
    if axis is not None:
        axis = normalize_axis_tuple(axis, a.ndim, argname='axis')
    if keepdims is np._NoValue:
        keepdims_kw = {}
    else:
        keepdims_kw = {'keepdims': keepdims}
    if weights is None:
        avg = a.mean(axis, **keepdims_kw)
        scl = avg.dtype.type(a.count(axis))
    else:
        wgt = asarray(weights)
        if issubclass(a.dtype.type, (np.integer, np.bool)):
            result_dtype = np.result_type(a.dtype, wgt.dtype, 'f8')
        else:
            result_dtype = np.result_type(a.dtype, wgt.dtype)
        if a.shape != wgt.shape:
            if axis is None:
                raise TypeError('Axis must be specified when shapes of a and weights differ.')
            if wgt.shape != tuple((a.shape[ax] for ax in axis)):
                raise ValueError('Shape of weights must be consistent with shape of a along specified axis.')
            wgt = wgt.transpose(np.argsort(axis))
            wgt = wgt.reshape(tuple((s if ax in axis else 1 for ax, s in enumerate(a.shape))))
        if m is not nomask:
            wgt = wgt * ~a.mask
            wgt.mask |= a.mask
        scl = wgt.sum(axis=axis, dtype=result_dtype, **keepdims_kw)
        avg = np.multiply(a, wgt, dtype=result_dtype).sum(axis, **keepdims_kw) / scl
    if returned:
        if scl.shape != avg.shape:
            scl = np.broadcast_to(scl, avg.shape).copy()
        return (avg, scl)
    else:
        return avg

def median(a, axis=None, out=None, overwrite_input=False, keepdims=False):
    if not hasattr(a, 'mask'):
        m = np.median(getdata(a, subok=True), axis=axis, out=out, overwrite_input=overwrite_input, keepdims=keepdims)
        if isinstance(m, np.ndarray) and 1 <= m.ndim:
            return masked_array(m, copy=False)
        else:
            return m
    return _ureduce(a, func=_median, keepdims=keepdims, axis=axis, out=out, overwrite_input=overwrite_input)

def compress_nd(x, axis=None):
    x = asarray(x)
    m = getmask(x)
    if axis is None:
        axis = tuple(range(x.ndim))
    else:
        axis = normalize_axis_tuple(axis, x.ndim)
    if m is nomask or not m.any():
        return x._data
    if m.all():
        return nxarray([])
    data = x._data
    for ax in axis:
        axes = tuple(list(range(ax)) + list(range(ax + 1, x.ndim)))
        data = data[(slice(None),) * ax + (~m.any(axis=axes),)]
    return data

def compress_rowcols(x, axis=None):
    if asarray(x).ndim != 2:
        raise NotImplementedError('compress_rowcols works for 2D arrays only.')
    return compress_nd(x, axis=axis)

def compress_rows(a):
    a = asarray(a)
    if a.ndim != 2:
        raise NotImplementedError('compress_rows works for 2D arrays only.')
    return compress_rowcols(a, 0)

def compress_cols(a):
    a = asarray(a)
    if a.ndim != 2:
        raise NotImplementedError('compress_cols works for 2D arrays only.')
    return compress_rowcols(a, 1)

def mask_rowcols(a, axis=None):
    a = array(a, subok=False)
    if a.ndim != 2:
        raise NotImplementedError('mask_rowcols works for 2D arrays only.')
    m = getmask(a)
    if m is nomask or not m.any():
        return a
    maskedval = m.nonzero()
    a._mask = a._mask.copy()
    if not axis:
        a[np.unique(maskedval[0])] = masked
    if axis in [None, 1, -1]:
        a[:, np.unique(maskedval[1])] = masked
    return a

def mask_rows(a, axis=np._NoValue):
    if axis is not np._NoValue:
        warnings.warn('The axis argument has always been ignored, in future passing it will raise TypeError', DeprecationWarning, stacklevel=2)
    return mask_rowcols(a, 0)

def mask_cols(a, axis=np._NoValue):
    if axis is not np._NoValue:
        warnings.warn('The axis argument has always been ignored, in future passing it will raise TypeError', DeprecationWarning, stacklevel=2)
    return mask_rowcols(a, 1)

def ediff1d(arr, to_end=None, to_begin=None):
    arr = ma.asanyarray(arr).flat
    ed = arr[1:] - arr[:-1]
    arrays = [ed]
    if to_begin is not None:
        arrays.insert(0, to_begin)
    if to_end is not None:
        arrays.append(to_end)
    if len(arrays) != 1:
        ed = hstack(arrays)
    return ed

def unique(ar1, return_index=False, return_inverse=False):
    output = np.unique(ar1, return_index=return_index, return_inverse=return_inverse)
    if isinstance(output, tuple):
        output = list(output)
        output[0] = output[0].view(MaskedArray)
        output = tuple(output)
    else:
        output = output.view(MaskedArray)
    return output

def intersect1d(ar1, ar2, assume_unique=False):
    if assume_unique:
        aux = ma.concatenate((ar1, ar2))
    else:
        aux = ma.concatenate((unique(ar1), unique(ar2)))
    aux.sort()
    return aux[:-1][aux[1:] == aux[:-1]]

def in1d(ar1, ar2, assume_unique=False, invert=False):
    if not assume_unique:
        ar1, rev_idx = unique(ar1, return_inverse=True)
        ar2 = unique(ar2)
    ar = ma.concatenate((ar1, ar2))
    order = ar.argsort(kind='mergesort')
    sar = ar[order]
    if invert:
        bool_ar = sar[1:] != sar[:-1]
    else:
        bool_ar = sar[1:] == sar[:-1]
    flag = ma.concatenate((bool_ar, [invert]))
    indx = order.argsort(kind='mergesort')[:len(ar1)]
    if assume_unique:
        return flag[indx]
    else:
        return flag[indx][rev_idx]

def isin(element, test_elements, assume_unique=False, invert=False):
    element = ma.asarray(element)
    return in1d(element, test_elements, assume_unique=assume_unique, invert=invert).reshape(element.shape)

def setdiff1d(ar1, ar2, assume_unique=False):
    if assume_unique:
        ar1 = ma.asarray(ar1).ravel()
    else:
        ar1 = unique(ar1)
        ar2 = unique(ar2)
    return ar1[in1d(ar1, ar2, assume_unique=True, invert=True)]

def _covhelper(x, y=None, rowvar=True, allow_masked=True):
    x = ma.array(x, ndmin=2, copy=True, dtype=float)
    xmask = ma.getmaskarray(x)
    if not allow_masked and xmask.any():
        raise ValueError('Cannot process masked data.')
    if x.shape[0] == 1:
        rowvar = True
    rowvar = int(bool(rowvar))
    axis = 1 - rowvar
    if rowvar:
        tup = (slice(None), None)
    else:
        tup = (None, slice(None))
    if y is None:
        if x.shape[0] > 2 ** 24 or x.shape[1] > 2 ** 24:
            xnm_dtype = np.float64
        else:
            xnm_dtype = np.float32
        xnotmask = np.logical_not(xmask).astype(xnm_dtype)
    else:
        y = array(y, copy=False, ndmin=2, dtype=float)
        ymask = ma.getmaskarray(y)
        if not allow_masked and ymask.any():
            raise ValueError('Cannot process masked data.')
        if xmask.any() or ymask.any():
            if y.shape == x.shape:
                common_mask = np.logical_or(xmask, ymask)
                if common_mask is not nomask:
                    xmask = x._mask = y._mask = ymask = common_mask
                    x._sharedmask = False
                    y._sharedmask = False
        x = ma.concatenate((x, y), axis)
        if x.shape[0] > 2 ** 24 or x.shape[1] > 2 ** 24:
            xnm_dtype = np.float64
        else:
            xnm_dtype = np.float32
        xnotmask = np.logical_not(np.concatenate((xmask, ymask), axis)).astype(xnm_dtype)
    x -= x.mean(axis=rowvar)[tup]
    return (x, xnotmask, rowvar)

def cov(x, y=None, rowvar=True, bias=False, allow_masked=True, ddof=None):
    if ddof is not None and ddof != int(ddof):
        raise ValueError('ddof must be an integer')
    if ddof is None:
        if bias:
            ddof = 0
        else:
            ddof = 1
    x, xnotmask, rowvar = _covhelper(x, y, rowvar, allow_masked)
    if not rowvar:
        fact = np.dot(xnotmask.T, xnotmask) - ddof
        mask = np.less_equal(fact, 0, dtype=bool)
        with np.errstate(divide='ignore', invalid='ignore'):
            data = np.dot(filled(x.T, 0), filled(x.conj(), 0)) / fact
        result = ma.array(data, mask=mask).squeeze()
    else:
        fact = np.dot(xnotmask, xnotmask.T) - ddof
        mask = np.less_equal(fact, 0, dtype=bool)
        with np.errstate(divide='ignore', invalid='ignore'):
            data = np.dot(filled(x, 0), filled(x.T.conj(), 0)) / fact
        result = ma.array(data, mask=mask).squeeze()
    return result

def corrcoef(x, y=None, rowvar=True, allow_masked=True):
    corr = cov(x, y, rowvar, allow_masked=allow_masked)
    try:
        std = ma.sqrt(ma.diagonal(corr))
    except ValueError:
        return ma.MaskedConstant()
    corr /= ma.multiply.outer(std, std)
    return corr

def ndenumerate(a, compressed=True):
    for it, mask in zip(np.ndenumerate(a), getmaskarray(a).flat):
        if not mask:
            yield it
        elif not compressed:
            yield (it[0], masked)

def flatnotmasked_edges(a):
    m = getmask(a)
    if m is nomask or not np.any(m):
        return np.array([0, a.size - 1])
    unmasked = np.flatnonzero(~m)
    if len(unmasked) > 0:
        return unmasked[[0, -1]]
    else:
        return None

def notmasked_edges(a, axis=None):
    a = asarray(a)
    if axis is None or a.ndim == 1:
        return flatnotmasked_edges(a)
    m = getmaskarray(a)
    idx = array(np.indices(a.shape), mask=np.asarray([m] * a.ndim))
    return [tuple((idx[i].min(axis).compressed() for i in range(a.ndim))), tuple((idx[i].max(axis).compressed() for i in range(a.ndim)))]

def flatnotmasked_contiguous(a):
    m = getmask(a)
    if m is nomask:
        return [slice(0, a.size)]
    i = 0
    result = []
    for k, g in itertools.groupby(m.ravel()):
        n = len(list(g))
        if not k:
            result.append(slice(i, i + n))
        i += n
    return result

def notmasked_contiguous(a, axis=None):
    a = asarray(a)
    nd = a.ndim
    if nd > 2:
        raise NotImplementedError('Currently limited to at most 2D array.')
    if axis is None or nd == 1:
        return flatnotmasked_contiguous(a)
    result = []
    other = (axis + 1) % 2
    idx = [0, 0]
    idx[axis] = slice(None, None)
    for i in range(a.shape[other]):
        idx[other] = i
        result.append(flatnotmasked_contiguous(a[tuple(idx)]))
    return result

def _ezclump(mask):
    if mask.ndim > 1:
        mask = mask.ravel()
    idx = (mask[1:] ^ mask[:-1]).nonzero()
    idx = idx[0] + 1
    if mask[0]:
        if len(idx) == 0:
            return [slice(0, mask.size)]
        r = [slice(0, idx[0])]
        r.extend((slice(left, right) for left, right in zip(idx[1:-1:2], idx[2::2])))
    else:
        if len(idx) == 0:
            return []
        r = [slice(left, right) for left, right in zip(idx[:-1:2], idx[1::2])]
    if mask[-1]:
        r.append(slice(idx[-1], mask.size))
    return r

def clump_unmasked(a):
    mask = getattr(a, '_mask', nomask)
    if mask is nomask:
        return [slice(0, a.size)]
    return _ezclump(~mask)

def clump_masked(a):
    mask = ma.getmask(a)
    if mask is nomask:
        return []
    return _ezclump(mask)

def vander(x, n=None):
    _vander = np.vander(x, n)
    m = getmask(x)
    if m is not nomask:
        _vander[m] = 0
    return _vander

def polyfit(x, y, deg, rcond=None, full=False, w=None, cov=False):
    x = asarray(x)
    y = asarray(y)
    m = getmask(x)
    if y.ndim == 1:
        m = mask_or(m, getmask(y))
    elif y.ndim == 2:
        my = getmask(mask_rows(y))
        if my is not nomask:
            m = mask_or(m, my[:, 0])
    else:
        raise TypeError('Expected a 1D or 2D array for y!')
    if w is not None:
        w = asarray(w)
        if w.ndim != 1:
            raise TypeError('expected a 1-d array for weights')
        if w.shape[0] != y.shape[0]:
            raise TypeError('expected w and y to have the same length')
        m = mask_or(m, getmask(w))
    if m is not nomask:
        not_m = ~m
        if w is not None:
            w = w[not_m]
        return np.polyfit(x[not_m], y[not_m], deg, rcond, full, w, cov)
    else:
        return np.polyfit(x, y, deg, rcond, full, w, cov)

def _checknames(descr, names=None):
    ndescr = len(descr)
    default_names = [f'f{i}' for i in range(ndescr)]
    if names is None:
        new_names = default_names
    else:
        if isinstance(names, (tuple, list)):
            new_names = names
        elif isinstance(names, str):
            new_names = names.split(',')
        else:
            raise NameError(f'illegal input names {names!r}')
        nnames = len(new_names)
        if nnames < ndescr:
            new_names += default_names[nnames:]
    ndescr = []
    for n, d, t in zip(new_names, default_names, descr.descr):
        if n in reserved_fields:
            if t[0] in reserved_fields:
                ndescr.append((d, t[1]))
            else:
                ndescr.append(t)
        else:
            ndescr.append((n, t[1]))
    return np.dtype(ndescr)

def _mrreconstruct(subtype, baseclass, baseshape, basetype):
    _data = np.ndarray.__new__(baseclass, baseshape, basetype).view(subtype)
    _mask = np.ndarray.__new__(np.ndarray, baseshape, 'b1')
    return subtype.__new__(subtype, _data, mask=_mask, dtype=basetype)

def fromrecords(reclist, dtype=None, shape=None, formats=None, names=None, titles=None, aligned=False, byteorder=None, fill_value=None, mask=ma.nomask):
    _mask = getattr(reclist, '_mask', None)
    if isinstance(reclist, np.ndarray):
        if isinstance(reclist, ma.MaskedArray):
            reclist = reclist.filled().view(np.ndarray)
        if dtype is None:
            dtype = reclist.dtype
        reclist = reclist.tolist()
    mrec = np.rec.fromrecords(reclist, dtype=dtype, shape=shape, formats=formats, names=names, titles=titles, aligned=aligned, byteorder=byteorder).view(mrecarray)
    if fill_value is not None:
        mrec.fill_value = fill_value
    if mask is not ma.nomask:
        mask = np.asarray(mask)
        maskrecordlength = len(mask.dtype)
        if maskrecordlength:
            mrec._mask.flat = mask
        elif mask.ndim == 2:
            mrec._mask.flat = [tuple(m) for m in mask]
        else:
            mrec.__setmask__(mask)
    if _mask is not None:
        mrec._mask[:] = _mask
    return mrec

def _guessvartypes(arr):
    vartypes = []
    arr = np.asarray(arr)
    if arr.ndim == 2:
        arr = arr[0]
    elif arr.ndim > 2:
        raise ValueError('The array should be 2D at most!')
    for f in arr:
        try:
            int(f)
        except (ValueError, TypeError):
            try:
                float(f)
            except (ValueError, TypeError):
                try:
                    complex(f)
                except (ValueError, TypeError):
                    vartypes.append(arr.dtype)
                else:
                    vartypes.append(np.dtype(complex))
            else:
                vartypes.append(np.dtype(float))
        else:
            vartypes.append(np.dtype(int))
    return vartypes

def openfile(fname):
    if hasattr(fname, 'readline'):
        return fname
    try:
        f = open(fname)
    except FileNotFoundError as e:
        raise FileNotFoundError(f"No such file: '{fname}'") from e
    if f.readline()[:2] != '\\x':
        f.seek(0, 0)
        return f
    f.close()
    raise NotImplementedError('Wow, binary file')

@property
def _data(self):
    return np.ndarray.view(self, np.recarray)

@property
def _fieldmask(self):
    return self._mask

def __len__(self):
    if self.ndim:
        return len(self._data)
    return len(self.dtype)

def __setattr__(self, attr, val):
    if attr in ['mask', 'fieldmask']:
        self.__setmask__(val)
        return
    _localdict = object.__getattribute__(self, '__dict__')
    newattr = attr not in _localdict
    try:
        ret = object.__setattr__(self, attr, val)
    except Exception:
        fielddict = np.ndarray.__getattribute__(self, 'dtype').fields or {}
        optinfo = np.ndarray.__getattribute__(self, '_optinfo') or {}
        if not (attr in fielddict or attr in optinfo):
            raise
    else:
        fielddict = np.ndarray.__getattribute__(self, 'dtype').fields or {}
        if attr not in fielddict:
            return ret
        if newattr:
            try:
                object.__delattr__(self, attr)
            except Exception:
                return ret
    try:
        res = fielddict[attr][:2]
    except (TypeError, KeyError) as e:
        raise AttributeError(f'record array has no attribute {attr}') from e
    if val is ma.masked:
        _fill_value = _localdict['_fill_value']
        if _fill_value is not None:
            dval = _localdict['_fill_value'][attr]
        else:
            dval = val
        mval = True
    else:
        dval = ma.filled(val)
        mval = ma.getmaskarray(val)
    obj = np.ndarray.__getattribute__(self, '_data').setfield(dval, *res)
    _localdict['_mask'].__setitem__(attr, mval)
    return obj

def __setitem__(self, indx, value):
    ma.MaskedArray.__setitem__(self, indx, value)
    if isinstance(indx, str):
        self._mask[indx] = ma.getmaskarray(value)

def __str__(self):
    if self.size > 1:
        mstr = [f"({','.join([str(i) for i in s])})" for s in zip(*[getattr(self, f) for f in self.dtype.names])]
        return f"[{', '.join(mstr)}]"
    else:
        mstr = [f"{','.join([str(i) for i in s])}" for s in zip([getattr(self, f) for f in self.dtype.names])]
        return f"({', '.join(mstr)})"

def view(self, dtype=None, type=None):
    if type is None and dtype is not None and (not (isinstance(dtype, builtins.type) and issubclass(dtype, np.ndarray))) and ((dtype := np.dtype(dtype)).fields is None):
        type = self.__class__.__bases__[0]
    return super().view(*[a for a in (dtype, type) if a is not None])

def tolist(self, fill_value=None):
    if fill_value is not None:
        return self.filled(fill_value).tolist()
    result = np.array(self.filled().tolist(), dtype=object)
    mask = np.array(self._mask.tolist())
    result[mask] = None
    return result.tolist()

def __getstate__(self):
    state = (1, self.shape, self.dtype, self.flags.fnc, self._data.tobytes(), self._mask.tobytes(), self._fill_value)
    return state

def approx(a, b, fill_value=True, rtol=1e-05, atol=1e-08):
    m = mask_or(getmask(a), getmask(b))
    d1 = filled(a)
    d2 = filled(b)
    if d1.dtype.char == 'O' or d2.dtype.char == 'O':
        return np.equal(d1, d2).ravel()
    x = filled(masked_array(d1, copy=False, mask=m), fill_value).astype(np.float64)
    y = filled(masked_array(d2, copy=False, mask=m), 1).astype(np.float64)
    d = np.less_equal(umath.absolute(x - y), atol + rtol * umath.absolute(y))
    return d.ravel()

def almost(a, b, decimal=6, fill_value=True):
    m = mask_or(getmask(a), getmask(b))
    d1 = filled(a)
    d2 = filled(b)
    if d1.dtype.char == 'O' or d2.dtype.char == 'O':
        return np.equal(d1, d2).ravel()
    x = filled(masked_array(d1, copy=False, mask=m), fill_value).astype(np.float64)
    y = filled(masked_array(d2, copy=False, mask=m), 1).astype(np.float64)
    d = np.around(np.abs(x - y), decimal) <= 10.0 ** (-decimal)
    return d.ravel()

def _assert_equal_on_sequences(actual, desired, err_msg=''):
    assert_equal(len(actual), len(desired), err_msg)
    for k in range(len(desired)):
        assert_equal(actual[k], desired[k], f'item={k!r}\n{err_msg}')

def assert_equal_records(a, b):
    assert_equal(a.dtype, b.dtype)
    for f in a.dtype.names:
        af, bf = (operator.getitem(a, f), operator.getitem(b, f))
        if not af is masked and (not bf is masked):
            assert_equal(operator.getitem(a, f), operator.getitem(b, f))

def assert_equal(actual, desired, err_msg=''):
    if isinstance(desired, dict):
        if not isinstance(actual, dict):
            raise AssertionError(repr(type(actual)))
        assert_equal(len(actual), len(desired), err_msg)
        for k in desired:
            if k not in actual:
                raise AssertionError(f'{k} not in {actual}')
            assert_equal(actual[k], desired[k], f'key={k!r}\n{err_msg}')
        return
    if isinstance(desired, (list, tuple)) and isinstance(actual, (list, tuple)):
        return _assert_equal_on_sequences(actual, desired, err_msg='')
    if not (isinstance(actual, ndarray) or isinstance(desired, ndarray)):
        msg = build_err_msg([actual, desired], err_msg)
        if not desired == actual:
            raise AssertionError(msg)
        return
    if actual is masked and (not desired is masked) or (desired is masked and (not actual is masked)):
        msg = build_err_msg([actual, desired], err_msg, header='', names=('x', 'y'))
        raise ValueError(msg)
    actual = np.asanyarray(actual)
    desired = np.asanyarray(desired)
    actual_dtype, desired_dtype = (actual.dtype, desired.dtype)
    if actual_dtype.char == 'S' and desired_dtype.char == 'S':
        return _assert_equal_on_sequences(actual.tolist(), desired.tolist(), err_msg='')
    return assert_array_equal(actual, desired, err_msg)

def fail_if_equal(actual, desired, err_msg=''):
    if isinstance(desired, dict):
        if not isinstance(actual, dict):
            raise AssertionError(repr(type(actual)))
        fail_if_equal(len(actual), len(desired), err_msg)
        for k in desired:
            if k not in actual:
                raise AssertionError(repr(k))
            fail_if_equal(actual[k], desired[k], f'key={k!r}\n{err_msg}')
        return
    if isinstance(desired, (list, tuple)) and isinstance(actual, (list, tuple)):
        fail_if_equal(len(actual), len(desired), err_msg)
        for k in range(len(desired)):
            fail_if_equal(actual[k], desired[k], f'item={k!r}\n{err_msg}')
        return
    if isinstance(actual, np.ndarray) or isinstance(desired, np.ndarray):
        return fail_if_array_equal(actual, desired, err_msg)
    msg = build_err_msg([actual, desired], err_msg)
    if not desired != actual:
        raise AssertionError(msg)

def assert_almost_equal(actual, desired, decimal=7, err_msg='', verbose=True):
    if isinstance(actual, np.ndarray) or isinstance(desired, np.ndarray):
        return assert_array_almost_equal(actual, desired, decimal=decimal, err_msg=err_msg, verbose=verbose)
    msg = build_err_msg([actual, desired], err_msg=err_msg, verbose=verbose)
    if not round(abs(desired - actual), decimal) == 0:
        raise AssertionError(msg)

def assert_array_compare(comparison, x, y, err_msg='', verbose=True, header='', fill_value=True):
    m = mask_or(getmask(x), getmask(y))
    x = masked_array(x, copy=False, mask=m, keep_mask=False, subok=False)
    y = masked_array(y, copy=False, mask=m, keep_mask=False, subok=False)
    if x is masked and (not y is masked) or (y is masked and (not x is masked)):
        msg = build_err_msg([x, y], err_msg=err_msg, verbose=verbose, header=header, names=('x', 'y'))
        raise ValueError(msg)
    return np.testing.assert_array_compare(comparison, x.filled(fill_value), y.filled(fill_value), err_msg=err_msg, verbose=verbose, header=header)

def fail_if_array_equal(x, y, err_msg='', verbose=True):

    def compare(x, y):
        return not np.all(approx(x, y))
    assert_array_compare(compare, x, y, err_msg=err_msg, verbose=verbose, header='Arrays are not equal')

def assert_array_approx_equal(x, y, decimal=6, err_msg='', verbose=True):

    def compare(x, y):
        """Returns the result of the loose comparison between x and y)."""
        return approx(x, y, rtol=10.0 ** (-decimal))
    assert_array_compare(compare, x, y, err_msg=err_msg, verbose=verbose, header='Arrays are not almost equal')

def assert_array_almost_equal(x, y, decimal=6, err_msg='', verbose=True):

    def compare(x, y):
        """Returns the result of the loose comparison between x and y)."""
        return almost(x, y, decimal)
    assert_array_compare(compare, x, y, err_msg=err_msg, verbose=verbose, header='Arrays are not almost equal')

def assert_mask_equal(m1, m2, err_msg=''):
    if m1 is nomask:
        assert_(m2 is nomask)
    if m2 is nomask:
        assert_(m1 is nomask)
    assert_array_equal(m1, m2, err_msg=err_msg)

@set_module('numpy')
def asmatrix(data, dtype=None):
    return matrix(data, dtype=dtype, copy=False)

@set_module('numpy')
def bmat(obj, ldict=None, gdict=None):
    if isinstance(obj, str):
        if gdict is None:
            frame = sys._getframe().f_back
            glob_dict = frame.f_globals
            loc_dict = frame.f_locals
        else:
            glob_dict = gdict
            loc_dict = ldict
        return matrix(_from_string(obj, glob_dict, loc_dict))
    if isinstance(obj, (tuple, list)):
        arr_rows = []
        for row in obj:
            if isinstance(row, N.ndarray):
                return matrix(concatenate(obj, axis=-1))
            else:
                arr_rows.append(concatenate(row, axis=-1))
        return matrix(concatenate(arr_rows, axis=0))
    if isinstance(obj, N.ndarray):
        return matrix(obj)

def _align(self, axis):
    if axis is None:
        return self[0, 0]
    elif axis == 0:
        return self
    elif axis == 1:
        return self.transpose()
    else:
        raise ValueError('unsupported axis')

def _collapse(self, axis):
    if axis is None:
        return self[0, 0]
    else:
        return self

@property
def I(self):
    M, N = self.shape
    if M == N:
        from numpy.linalg import inv as func
    else:
        from numpy.linalg import pinv as func
    return asmatrix(func(self))

@property
def A(self):
    return self.__array__()

@property
def A1(self):
    return self.__array__().ravel()

@property
def T(self):
    return self.transpose()

@property
def H(self):
    if issubclass(self.dtype.type, N.complexfloating):
        return self.transpose().conjugate()
    else:
        return self.transpose()

def cheb2poly(c):
    from .polynomial import polyadd, polymulx, polysub
    [c] = pu.as_series([c])
    n = len(c)
    if n < 3:
        return c
    else:
        c0 = c[-2]
        c1 = c[-1]
        for i in range(n - 1, 1, -1):
            tmp = c0
            c0 = polysub(c[i - 2], c1)
            c1 = polyadd(tmp, polymulx(c1) * 2)
        return polyadd(c0, polymulx(c1))

