def trimseq(seq):
    if len(seq) == 0 or seq[-1] != 0:
        return seq
    else:
        for i in range(len(seq) - 1, -1, -1):
            if seq[i] != 0:
                break
        return seq[:i + 1]

def as_series(alist, trim=True):
    arrays = [np.array(a, ndmin=1, copy=None) for a in alist]
    for a in arrays:
        if a.size == 0:
            raise ValueError('Coefficient array is empty')
        if a.ndim != 1:
            raise ValueError('Coefficient array is not 1-d')
    if trim:
        arrays = [trimseq(a) for a in arrays]
    try:
        dtype = np.common_type(*arrays)
    except Exception as e:
        object_dtype = np.dtypes.ObjectDType()
        has_one_object_type = False
        ret = []
        for a in arrays:
            if a.dtype != object_dtype:
                tmp = np.empty(len(a), dtype=object_dtype)
                tmp[:] = a[:]
                ret.append(tmp)
            else:
                has_one_object_type = True
                ret.append(a.copy())
        if not has_one_object_type:
            raise ValueError('Coefficient arrays have no common type') from e
    else:
        ret = [np.array(a, copy=True, dtype=dtype) for a in arrays]
    return ret

def trimcoef(c, tol=0):
    if tol < 0:
        raise ValueError('tol must be non-negative')
    [c] = as_series([c])
    [ind] = np.nonzero(np.abs(c) > tol)
    if len(ind) == 0:
        return c[:1] * 0
    else:
        return c[:ind[-1] + 1].copy()

def getdomain(x):
    [x] = as_series([x], trim=False)
    if x.dtype.char in np.typecodes['Complex']:
        rmin, rmax = (x.real.min(), x.real.max())
        imin, imax = (x.imag.min(), x.imag.max())
        return np.array((complex(rmin, imin), complex(rmax, imax)))
    else:
        return np.array((x.min(), x.max()))

def mapparms(old, new):
    oldlen = old[1] - old[0]
    newlen = new[1] - new[0]
    off = (old[1] * new[0] - old[0] * new[1]) / oldlen
    scl = newlen / oldlen
    return (off, scl)

def mapdomain(x, old, new):
    if type(x) not in (int, float, complex) and (not isinstance(x, np.generic)):
        x = np.asanyarray(x)
    off, scl = mapparms(old, new)
    return off + scl * x

def _vander_nd(vander_fs, points, degrees):
    n_dims = len(vander_fs)
    if n_dims != len(points):
        raise ValueError(f'Expected {n_dims} dimensions of sample points, got {len(points)}')
    if n_dims != len(degrees):
        raise ValueError(f'Expected {n_dims} dimensions of degrees, got {len(degrees)}')
    if n_dims == 0:
        raise ValueError('Unable to guess a dtype or shape when no points are given')
    points = tuple(np.asarray(tuple(points)) + 0.0)
    vander_arrays = (vander_fs[i](points[i], degrees[i])[(...,) + _nth_slice(i, n_dims)] for i in range(n_dims))
    return functools.reduce(operator.mul, vander_arrays)

def _vander_nd_flat(vander_fs, points, degrees):
    v = _vander_nd(vander_fs, points, degrees)
    return v.reshape(v.shape[:-len(degrees)] + (-1,))

def _fromroots(line_f, mul_f, roots):
    if len(roots) == 0:
        return np.ones(1)
    else:
        [roots] = as_series([roots], trim=False)
        roots.sort()
        p = [line_f(-r, 1) for r in roots]
        n = len(p)
        while n > 1:
            m, r = divmod(n, 2)
            tmp = [mul_f(p[i], p[i + m]) for i in range(m)]
            if r:
                tmp[0] = mul_f(tmp[0], p[-1])
            p = tmp
            n = m
        return p[0]

def _valnd(val_f, c, *args):
    args = [np.asanyarray(a) for a in args]
    shape0 = args[0].shape
    if not all((a.shape == shape0 for a in args[1:])):
        if len(args) == 3:
            raise ValueError('x, y, z are incompatible')
        elif len(args) == 2:
            raise ValueError('x, y are incompatible')
        else:
            raise ValueError('ordinates are incompatible')
    it = iter(args)
    x0 = next(it)
    c = val_f(x0, c)
    for xi in it:
        c = val_f(xi, c, tensor=False)
    return c

def _gridnd(val_f, c, *args):
    for xi in args:
        c = val_f(xi, c)
    return c

def _div(mul_f, c1, c2):
    [c1, c2] = as_series([c1, c2])
    if c2[-1] == 0:
        raise ZeroDivisionError
    lc1 = len(c1)
    lc2 = len(c2)
    if lc1 < lc2:
        return (c1[:1] * 0, c1)
    elif lc2 == 1:
        return (c1 / c2[-1], c1[:1] * 0)
    else:
        quo = np.empty(lc1 - lc2 + 1, dtype=c1.dtype)
        rem = c1
        for i in range(lc1 - lc2, -1, -1):
            p = mul_f([0] * i + [1], c2)
            q = rem[-1] / p[-1]
            rem = rem[:-1] - q * p[:-1]
            quo[i] = q
        return (quo, trimseq(rem))

def _add(c1, c2):
    [c1, c2] = as_series([c1, c2])
    if len(c1) > len(c2):
        c1[:c2.size] += c2
        ret = c1
    else:
        c2[:c1.size] += c1
        ret = c2
    return trimseq(ret)

def _sub(c1, c2):
    [c1, c2] = as_series([c1, c2])
    if len(c1) > len(c2):
        c1[:c2.size] -= c2
        ret = c1
    else:
        c2 = -c2
        c2[:c1.size] += c1
        ret = c2
    return trimseq(ret)

def _fit(vander_f, x, y, deg, rcond=None, full=False, w=None):
    x = np.asarray(x) + 0.0
    y = np.asarray(y) + 0.0
    deg = np.asarray(deg)
    if deg.ndim > 1 or deg.dtype.kind not in 'iu' or deg.size == 0:
        raise TypeError('deg must be an int or non-empty 1-D array of int')
    if deg.min() < 0:
        raise ValueError('expected deg >= 0')
    if x.ndim != 1:
        raise TypeError('expected 1D vector for x')
    if x.size == 0:
        raise TypeError('expected non-empty vector for x')
    if y.ndim < 1 or y.ndim > 2:
        raise TypeError('expected 1D or 2D array for y')
    if len(x) != len(y):
        raise TypeError('expected x and y to have same length')
    if deg.ndim == 0:
        lmax = deg
        order = lmax + 1
        van = vander_f(x, lmax)
    else:
        deg = np.sort(deg)
        lmax = deg[-1]
        order = len(deg)
        van = vander_f(x, lmax)[:, deg]
    lhs = van.T
    rhs = y.T
    if w is not None:
        w = np.asarray(w) + 0.0
        if w.ndim != 1:
            raise TypeError('expected 1D vector for w')
        if len(x) != len(w):
            raise TypeError('expected x and w to have same length')
        lhs = lhs * w
        rhs = rhs * w
    if rcond is None:
        rcond = len(x) * np.finfo(x.dtype).eps
    if issubclass(lhs.dtype.type, np.complexfloating):
        scl = np.sqrt((np.square(lhs.real) + np.square(lhs.imag)).sum(1))
    else:
        scl = np.sqrt(np.square(lhs).sum(1))
    scl[scl == 0] = 1
    c, resids, rank, s = np.linalg.lstsq(lhs.T / scl, rhs.T, rcond)
    c = (c.T / scl).T
    if deg.ndim > 0:
        if c.ndim == 2:
            cc = np.zeros((lmax + 1, c.shape[1]), dtype=c.dtype)
        else:
            cc = np.zeros(lmax + 1, dtype=c.dtype)
        cc[deg] = c
        c = cc
    if rank != order and (not full):
        msg = 'The fit may be poorly conditioned'
        warnings.warn(msg, np.exceptions.RankWarning, stacklevel=2)
    if full:
        return (c, [resids, rank, s, rcond])
    else:
        return c

def _pow(mul_f, c, pow, maxpower):
    [c] = as_series([c])
    power = int(pow)
    if power != pow or power < 0:
        raise ValueError('Power must be a non-negative integer.')
    elif maxpower is not None and power > maxpower:
        raise ValueError('Power is too large')
    elif power == 0:
        return np.array([1], dtype=c.dtype)
    elif power == 1:
        return c
    else:
        prd = c
        for i in range(2, power + 1):
            prd = mul_f(prd, c)
        return prd

def _as_int(x, desc):
    try:
        return operator.index(x)
    except TypeError as e:
        raise TypeError(f'{desc} must be an integer, received {x}') from e

def _get_coefficients(self, other):
    if isinstance(other, ABCPolyBase):
        if not isinstance(other, self.__class__):
            raise TypeError('Polynomial types differ')
        elif not np.all(self.domain == other.domain):
            raise TypeError('Domains differ')
        elif not np.all(self.window == other.window):
            raise TypeError('Windows differ')
        elif self.symbol != other.symbol:
            raise ValueError('Polynomial symbols differ')
        return other.coef
    return other

def _generate_string(self, term_method):
    linewidth = np.get_printoptions().get('linewidth', 75)
    if linewidth < 1:
        linewidth = 1
    out = pu.format_float(self.coef[0])
    off, scale = self.mapparms()
    scaled_symbol, needs_parens = self._format_term(pu.format_float, off, scale)
    if needs_parens:
        scaled_symbol = '(' + scaled_symbol + ')'
    for i, coef in enumerate(self.coef[1:]):
        out += ' '
        power = str(i + 1)
        try:
            if coef >= 0:
                next_term = '+ ' + pu.format_float(coef, parens=True)
            else:
                next_term = '- ' + pu.format_float(-coef, parens=True)
        except TypeError:
            next_term = f'+ {coef}'
        next_term += term_method(power, scaled_symbol)
        line_len = len(out.split('\n')[-1]) + len(next_term)
        if i < len(self.coef[1:]) - 1:
            line_len += 2
        if line_len >= linewidth:
            next_term = next_term.replace(' ', '\n', 1)
        out += next_term
    return out

@classmethod
def _str_term_unicode(cls, i, arg_str):
    if cls.basis_name is None:
        raise NotImplementedError('Subclasses must define either a basis_name, or override _str_term_unicode(cls, i, arg_str)')
    return f'·{cls.basis_name}{i.translate(cls._subscript_mapping)}({arg_str})'

@classmethod
def _str_term_ascii(cls, i, arg_str):
    if cls.basis_name is None:
        raise NotImplementedError('Subclasses must define either a basis_name, or override _str_term_ascii(cls, i, arg_str)')
    return f' {cls.basis_name}_{i}({arg_str})'

def _format_term(self, scalar_format: Callable, off: float, scale: float):
    if off == 0 and scale == 1:
        term = self.symbol
        needs_parens = False
    elif scale == 1:
        term = f'{scalar_format(off)} + {self.symbol}'
        needs_parens = True
    elif off == 0:
        term = f'{scalar_format(scale)}{self.symbol}'
        needs_parens = True
    else:
        term = f'{scalar_format(off)} + {scalar_format(scale)}{self.symbol}'
        needs_parens = True
    return (term, needs_parens)

def trim(self, tol=0):
    coef = pu.trimcoef(self.coef, tol)
    return self.__class__(coef, self.domain, self.window, self.symbol)

def truncate(self, size):
    isize = int(size)
    if isize != size or isize < 1:
        raise ValueError('size must be a positive integer')
    if isize >= len(self.coef):
        coef = self.coef
    else:
        coef = self.coef[:isize]
    return self.__class__(coef, self.domain, self.window, self.symbol)

def convert(self, domain=None, kind=None, window=None):
    if kind is None:
        kind = self.__class__
    if domain is None:
        domain = kind.domain
    if window is None:
        window = kind.window
    return self(kind.identity(domain, window=window, symbol=self.symbol))

def integ(self, m=1, k=[], lbnd=None):
    off, scl = self.mapparms()
    if lbnd is None:
        lbnd = 0
    else:
        lbnd = off + scl * lbnd
    coef = self._int(self.coef, m, k, lbnd, 1.0 / scl)
    return self.__class__(coef, self.domain, self.window, self.symbol)

def deriv(self, m=1):
    off, scl = self.mapparms()
    coef = self._der(self.coef, m, scl)
    return self.__class__(coef, self.domain, self.window, self.symbol)

def roots(self):
    roots = self._roots(self.coef)
    return pu.mapdomain(roots, self.window, self.domain)

def linspace(self, n=100, domain=None):
    if domain is None:
        domain = self.domain
    x = np.linspace(domain[0], domain[1], n)
    y = self(x)
    return (x, y)

@classmethod
def fit(cls, x, y, deg, domain=None, rcond=None, full=False, w=None, window=None, symbol='x'):
    if domain is None:
        domain = pu.getdomain(x)
        if domain[0] == domain[1]:
            domain[0] -= 1
            domain[1] += 1
    elif isinstance(domain, list) and len(domain) == 0:
        domain = cls.domain
    if window is None:
        window = cls.window
    xnew = pu.mapdomain(x, domain, window)
    res = cls._fit(xnew, y, deg, w=w, rcond=rcond, full=full)
    if full:
        [coef, status] = res
        return (cls(coef, domain=domain, window=window, symbol=symbol), status)
    else:
        coef = res
        return cls(coef, domain=domain, window=window, symbol=symbol)

@classmethod
def fromroots(cls, roots, domain=[], window=None, symbol='x'):
    [roots] = pu.as_series([roots], trim=False)
    if domain is None:
        domain = pu.getdomain(roots)
    elif isinstance(domain, list) and len(domain) == 0:
        domain = cls.domain
    if window is None:
        window = cls.window
    deg = len(roots)
    off, scl = pu.mapparms(domain, window)
    rnew = off + scl * roots
    coef = cls._fromroots(rnew) / scl ** deg
    return cls(coef, domain=domain, window=window, symbol=symbol)

@classmethod
def identity(cls, domain=None, window=None, symbol='x'):
    if domain is None:
        domain = cls.domain
    if window is None:
        window = cls.window
    off, scl = pu.mapparms(window, domain)
    coef = cls._line(off, scl)
    return cls(coef, domain, window, symbol)

@classmethod
def basis(cls, deg, domain=None, window=None, symbol='x'):
    if domain is None:
        domain = cls.domain
    if window is None:
        window = cls.window
    ideg = int(deg)
    if ideg != deg or ideg < 0:
        raise ValueError('deg must be non-negative integer')
    return cls([0] * ideg + [1], domain, window, symbol)

@classmethod
def cast(cls, series, domain=None, window=None):
    if domain is None:
        domain = cls.domain
    if window is None:
        window = cls.window
    return series.convert(domain, cls, window)

