def print_new_cast_table(*, can_cast=True, legacy=False, flags=False):
    from numpy._core._multiarray_tests import get_all_cast_information
    cast_table = {-1: ' ', 0: '#', 1: '#', 2: '=', 3: '~', 4: '.'}
    flags_table = {0: '▗', 7: '█', 1: '▚', 2: '▐', 4: '▄', 3: '▜', 5: '▙', 6: '▟'}
    cast_info = namedtuple('cast_info', ['can_cast', 'legacy', 'flags'])
    no_cast_info = cast_info(' ', ' ', ' ')
    casts = get_all_cast_information()
    table = {}
    dtypes = set()
    for cast in casts:
        dtypes.add(cast['from'])
        dtypes.add(cast['to'])
        if cast['from'] not in table:
            table[cast['from']] = {}
        to_dict = table[cast['from']]
        can_cast = cast_table[cast['casting']]
        legacy = 'L' if cast['legacy'] else '.'
        flags = 0
        if cast['requires_pyapi']:
            flags |= 1
        if cast['supports_unaligned']:
            flags |= 2
        if cast['no_floatingpoint_errors']:
            flags |= 4
        flags = flags_table[flags]
        to_dict[cast['to']] = cast_info(can_cast=can_cast, legacy=legacy, flags=flags)
    types = np.typecodes['All']

    def sorter(x):
        dtype = np.dtype(x.type)
        try:
            indx = types.index(dtype.char)
        except ValueError:
            indx = np.inf
        return (indx, dtype.char)
    dtypes = sorted(dtypes, key=sorter)

    def print_table(field='can_cast'):
        print('X', end=' ')
        for dt in dtypes:
            print(np.dtype(dt.type).char, end=' ')
        print()
        for from_dt in dtypes:
            print(np.dtype(from_dt.type).char, end=' ')
            row = table.get(from_dt, {})
            for to_dt in dtypes:
                print(getattr(row.get(to_dt, no_cast_info), field), end=' ')
            print()
    if can_cast:
        print()
        print('Casting: # is equivalent, = is safe, ~ is same-kind, and . is unsafe')
        print()
        print_table('can_cast')
    if legacy:
        print()
        print('L denotes a legacy cast . a non-legacy one.')
        print()
        print_table('legacy')
    if flags:
        print()
        print(f'{flags_table[0]}: no flags, {flags_table[1]}: PyAPI, {flags_table[2]}: supports unaligned, {flags_table[4]}: no-float-errors')
        print()
        print_table('flags')

def _make_methods(functions, modname):
    methods_table = []
    codes = []
    for funcname, flags, code in functions:
        cfuncname = f'{modname}_{funcname}'
        if 'METH_KEYWORDS' in flags:
            signature = '(PyObject *self, PyObject *args, PyObject *kwargs)'
        else:
            signature = '(PyObject *self, PyObject *args)'
        methods_table.append(f'{{"{funcname}", (PyCFunction){cfuncname}, {flags}}},')
        func_code = f'
        static PyObject* {cfuncname}{signature}
        {{
        {code}
        }}
        '
        codes.append(func_code)
    methods_str = '
'.join(methods_table)
    body = '
'.join(codes) + f'
    static PyMethodDef methods[] = {{
    {methods_str}
    {{ NULL }}
    }};
    static struct PyModuleDef moduledef = {{
        PyModuleDef_HEAD_INIT,
        "{modname}",    /* m_name */
        NULL,           /* m_doc */
        -1,             /* m_size */
        methods,        /* m_methods */
    }};
    '
    return body

def _make_source(name, init, body):
    code = f'
    #include <Python.h>

    {body}

    PyMODINIT_FUNC
    PyInit_{name}(void) {{
    {init}
    }}
    '
    return code

def assert_(val, msg=''):
    __tracebackhide__ = True
    if not val:
        try:
            smsg = msg()
        except TypeError:
            smsg = msg
        raise AssertionError(smsg)

def assert_equal(actual, desired, err_msg='', verbose=True, *, strict=False):
    __tracebackhide__ = True
    if isinstance(desired, dict):
        if not isinstance(actual, dict):
            raise AssertionError(repr(type(actual)))
        assert_equal(len(actual), len(desired), err_msg, verbose)
        for k in desired:
            if k not in actual:
                raise AssertionError(repr(k))
            assert_equal(actual[k], desired[k], f'key={k!r}\n{err_msg}', verbose)
        return
    if isinstance(desired, (list, tuple)) and isinstance(actual, (list, tuple)):
        assert_equal(len(actual), len(desired), err_msg, verbose)
        for k in range(len(desired)):
            assert_equal(actual[k], desired[k], f'item={k!r}\n{err_msg}', verbose)
        return
    from numpy import imag, iscomplexobj, real
    from numpy._core import isscalar, ndarray, signbit
    if isinstance(actual, ndarray) or isinstance(desired, ndarray):
        return assert_array_equal(actual, desired, err_msg, verbose, strict=strict)
    msg = build_err_msg([actual, desired], err_msg, verbose=verbose)
    try:
        usecomplex = iscomplexobj(actual) or iscomplexobj(desired)
    except (ValueError, TypeError):
        usecomplex = False
    if usecomplex:
        if iscomplexobj(actual):
            actualr = real(actual)
            actuali = imag(actual)
        else:
            actualr = actual
            actuali = 0
        if iscomplexobj(desired):
            desiredr = real(desired)
            desiredi = imag(desired)
        else:
            desiredr = desired
            desiredi = 0
        try:
            assert_equal(actualr, desiredr)
            assert_equal(actuali, desiredi)
        except AssertionError:
            raise AssertionError(msg)
    if isscalar(desired) != isscalar(actual):
        raise AssertionError(msg)
    try:
        isdesnat = isnat(desired)
        isactnat = isnat(actual)
        dtypes_match = np.asarray(desired).dtype.type == np.asarray(actual).dtype.type
        if isdesnat and isactnat:
            if dtypes_match:
                return
            else:
                raise AssertionError(msg)
    except (TypeError, ValueError, NotImplementedError):
        pass
    try:
        isdesnan = isnan(desired)
        isactnan = isnan(actual)
        if isdesnan and isactnan:
            return
        array_actual = np.asarray(actual)
        array_desired = np.asarray(desired)
        if array_actual.dtype.char in 'Mm' or array_desired.dtype.char in 'Mm':
            raise NotImplementedError('cannot compare to a scalar with a different type')
        if desired == 0 and actual == 0:
            if not signbit(desired) == signbit(actual):
                raise AssertionError(msg)
    except (TypeError, ValueError, NotImplementedError):
        pass
    try:
        if not desired == actual:
            raise AssertionError(msg)
    except (DeprecationWarning, FutureWarning) as e:
        if 'elementwise == comparison' in e.args[0]:
            raise AssertionError(msg)
        else:
            raise

def assert_almost_equal(actual, desired, decimal=7, err_msg='', verbose=True):
    __tracebackhide__ = True
    from numpy import imag, iscomplexobj, real
    from numpy._core import ndarray
    try:
        usecomplex = iscomplexobj(actual) or iscomplexobj(desired)
    except ValueError:
        usecomplex = False

    def _build_err_msg():
        header = f'Arrays are not almost equal to {decimal} decimals'
        return build_err_msg([actual, desired], err_msg, verbose=verbose, header=header)
    if usecomplex:
        if iscomplexobj(actual):
            actualr = real(actual)
            actuali = imag(actual)
        else:
            actualr = actual
            actuali = 0
        if iscomplexobj(desired):
            desiredr = real(desired)
            desiredi = imag(desired)
        else:
            desiredr = desired
            desiredi = 0
        try:
            assert_almost_equal(actualr, desiredr, decimal=decimal)
            assert_almost_equal(actuali, desiredi, decimal=decimal)
        except AssertionError:
            raise AssertionError(_build_err_msg())
    if isinstance(actual, (ndarray, tuple, list)) or isinstance(desired, (ndarray, tuple, list)):
        return assert_array_almost_equal(actual, desired, decimal, err_msg)
    try:
        if not (isfinite(desired) and isfinite(actual)):
            if isnan(desired) or isnan(actual):
                if not (isnan(desired) and isnan(actual)):
                    raise AssertionError(_build_err_msg())
            elif not desired == actual:
                raise AssertionError(_build_err_msg())
            return
    except (NotImplementedError, TypeError):
        pass
    if abs(desired - actual) >= np.float64(1.5 * 10.0 ** (-decimal)):
        raise AssertionError(_build_err_msg())

def assert_approx_equal(actual, desired, significant=7, err_msg='', verbose=True):
    __tracebackhide__ = True
    import numpy as np
    actual, desired = map(float, (actual, desired))
    if desired == actual:
        return
    with np.errstate(invalid='ignore'):
        scale = 0.5 * (np.abs(desired) + np.abs(actual))
        scale = np.power(10, np.floor(np.log10(scale)))
    try:
        sc_desired = desired / scale
    except ZeroDivisionError:
        sc_desired = 0.0
    try:
        sc_actual = actual / scale
    except ZeroDivisionError:
        sc_actual = 0.0
    msg = build_err_msg([actual, desired], err_msg, header=f'Items are not equal to {significant} significant digits:', verbose=verbose)
    try:
        if not (isfinite(desired) and isfinite(actual)):
            if isnan(desired) or isnan(actual):
                if not (isnan(desired) and isnan(actual)):
                    raise AssertionError(msg)
            elif not desired == actual:
                raise AssertionError(msg)
            return
    except (TypeError, NotImplementedError):
        pass
    if np.abs(sc_desired - sc_actual) >= np.power(10.0, -(significant - 1)):
        raise AssertionError(msg)

