def requires_memory(free_bytes):
    import pytest

    def decorator(func):

        @wraps(func)
        def wrapper(*a, **kw):
            msg = check_free_memory(free_bytes)
            if msg is not None:
                pytest.skip(msg)
            try:
                return func(*a, **kw)
            except MemoryError:
                pytest.xfail('MemoryError raised')
        return wrapper
    return decorator

def check_free_memory(free_bytes):
    env_var = 'NPY_AVAILABLE_MEM'
    env_value = os.environ.get(env_var)
    if env_value is not None:
        try:
            mem_free = _parse_size(env_value)
        except ValueError as exc:
            raise ValueError(f'Invalid environment variable {env_var}: {exc}')
        msg = f'{free_bytes / 1000000000.0} GB memory required, but environment variable NPY_AVAILABLE_MEM={env_value} set'
    else:
        mem_free = _get_mem_available()
        if mem_free is None:
            msg = 'Could not determine available memory; set NPY_AVAILABLE_MEM environment variable (e.g. NPY_AVAILABLE_MEM=16GB) to run the test.'
            mem_free = -1
        else:
            free_bytes_gb = free_bytes / 1000000000.0
            mem_free_gb = mem_free / 1000000000.0
            msg = f'{free_bytes_gb} GB memory required, but {mem_free_gb} GB available'
    return msg if mem_free < free_bytes else None

def _parse_size(size_str):
    suffixes = {'': 1, 'b': 1, 'k': 1000, 'm': 1000 ** 2, 'g': 1000 ** 3, 't': 1000 ** 4, 'kb': 1000, 'mb': 1000 ** 2, 'gb': 1000 ** 3, 'tb': 1000 ** 4, 'kib': 1024, 'mib': 1024 ** 2, 'gib': 1024 ** 3, 'tib': 1024 ** 4}
    pipe_suffixes = '|'.join(suffixes.keys())
    size_re = re.compile(f'^\\s*(\\d+|\\d+\\.\\d+)\\s*({pipe_suffixes})\\s*$', re.I)
    m = size_re.match(size_str.lower())
    if not m or m.group(2) not in suffixes:
        raise ValueError(f'value {size_str!r} not a valid size')
    return int(float(m.group(1)) * suffixes[m.group(2)])

def _get_mem_available():
    try:
        import psutil
        return psutil.virtual_memory().available
    except (ImportError, AttributeError):
        pass
    if sys.platform.startswith('linux'):
        info = {}
        with open('/proc/meminfo', encoding='utf-8') as f:
            for line in f:
                p = line.split()
                info[p[0].strip(':').lower()] = int(p[1]) * 1024
        if 'memavailable' in info:
            return info['memavailable']
        else:
            return info['memfree'] + info['cached']
    return None

