def _flop_count(idx_contraction, inner, num_terms, size_dictionary):
    overall_size = _compute_size_by_dict(idx_contraction, size_dictionary)
    op_factor = max(1, num_terms - 1)
    if inner:
        op_factor += 1
    return overall_size * op_factor

def _compute_size_by_dict(indices, idx_dict):
    ret = 1
    for i in indices:
        ret *= idx_dict[i]
    return ret

def _find_contraction(positions, input_sets, output_set):
    idx_contract = set()
    idx_remain = output_set.copy()
    remaining = []
    for ind, value in enumerate(input_sets):
        if ind in positions:
            idx_contract |= value
        else:
            remaining.append(value)
            idx_remain |= value
    new_result = idx_remain & idx_contract
    idx_removed = idx_contract - new_result
    remaining.append(new_result)
    return (new_result, remaining, idx_removed, idx_contract)

def _optimal_path(input_sets, output_set, idx_dict, memory_limit):
    full_results = [(0, [], input_sets)]
    for iteration in range(len(input_sets) - 1):
        iter_results = []
        for curr in full_results:
            cost, positions, remaining = curr
            for con in itertools.combinations(range(len(input_sets) - iteration), 2):
                cont = _find_contraction(con, remaining, output_set)
                new_result, new_input_sets, idx_removed, idx_contract = cont
                new_size = _compute_size_by_dict(new_result, idx_dict)
                if new_size > memory_limit:
                    continue
                total_cost = cost + _flop_count(idx_contract, idx_removed, len(con), idx_dict)
                new_pos = positions + [con]
                iter_results.append((total_cost, new_pos, new_input_sets))
        if iter_results:
            full_results = iter_results
        else:
            path = min(full_results, key=lambda x: x[0])[1]
            path += [tuple(range(len(input_sets) - iteration))]
            return path
    if len(full_results) == 0:
        return [tuple(range(len(input_sets)))]
    path = min(full_results, key=lambda x: x[0])[1]
    return path

def _greedy_path(input_sets, output_set, idx_dict, memory_limit):
    if len(input_sets) == 1:
        return [(0,)]
    elif len(input_sets) == 2:
        return [(0, 1)]
    contract = _find_contraction(range(len(input_sets)), input_sets, output_set)
    idx_result, new_input_sets, idx_removed, idx_contract = contract
    naive_cost = _flop_count(idx_contract, idx_removed, len(input_sets), idx_dict)
    comb_iter = itertools.combinations(range(len(input_sets)), 2)
    known_contractions = []
    path_cost = 0
    path = []
    for iteration in range(len(input_sets) - 1):
        for positions in comb_iter:
            if input_sets[positions[0]].isdisjoint(input_sets[positions[1]]):
                continue
            result = _parse_possible_contraction(positions, input_sets, output_set, idx_dict, memory_limit, path_cost, naive_cost)
            if result is not None:
                known_contractions.append(result)
        if len(known_contractions) == 0:
            for positions in itertools.combinations(range(len(input_sets)), 2):
                result = _parse_possible_contraction(positions, input_sets, output_set, idx_dict, memory_limit, path_cost, naive_cost)
                if result is not None:
                    known_contractions.append(result)
            if len(known_contractions) == 0:
                path.append(tuple(range(len(input_sets))))
                break
        best = min(known_contractions, key=lambda x: x[0])
        known_contractions = _update_other_results(known_contractions, best)
        input_sets = best[2]
        new_tensor_pos = len(input_sets) - 1
        comb_iter = ((i, new_tensor_pos) for i in range(new_tensor_pos))
        path.append(best[1])
        path_cost += best[0][1]
    return path

def _parse_einsum_input(operands):
    if len(operands) == 0:
        raise ValueError('No input operands')
    if isinstance(operands[0], str):
        subscripts = operands[0].replace(' ', '')
        operands = [asanyarray(v) for v in operands[1:]]
        for s in subscripts:
            if s in '.,->':
                continue
            if s not in einsum_symbols:
                raise ValueError(f'Character {s} is not a valid symbol.')
    else:
        tmp_operands = list(operands)
        operand_list = []
        subscript_list = []
        for p in range(len(operands) // 2):
            operand_list.append(tmp_operands.pop(0))
            subscript_list.append(tmp_operands.pop(0))
        output_list = tmp_operands[-1] if len(tmp_operands) else None
        operands = [asanyarray(v) for v in operand_list]
        subscripts = ''
        last = len(subscript_list) - 1
        for num, sub in enumerate(subscript_list):
            for s in sub:
                if s is Ellipsis:
                    subscripts += '...'
                else:
                    try:
                        s = operator.index(s)
                    except TypeError as e:
                        raise TypeError('For this input type lists must contain either int or Ellipsis') from e
                    subscripts += einsum_symbols[s]
            if num != last:
                subscripts += ','
        if output_list is not None:
            subscripts += '->'
            for s in output_list:
                if s is Ellipsis:
                    subscripts += '...'
                else:
                    try:
                        s = operator.index(s)
                    except TypeError as e:
                        raise TypeError('For this input type lists must contain either int or Ellipsis') from e
                    subscripts += einsum_symbols[s]
    if '-' in subscripts or '>' in subscripts:
        invalid = subscripts.count('-') > 1 or subscripts.count('>') > 1
        if invalid or subscripts.count('->') != 1:
            raise ValueError("Subscripts can only contain one '->'.")
    if '.' in subscripts:
        used = subscripts.replace('.', '').replace(',', '').replace('->', '')
        unused = list(einsum_symbols_set - set(used))
        ellipse_inds = ''.join(unused)
        longest = 0
        if '->' in subscripts:
            input_tmp, output_sub = subscripts.split('->')
            split_subscripts = input_tmp.split(',')
            out_sub = True
        else:
            split_subscripts = subscripts.split(',')
            out_sub = False
        for num, sub in enumerate(split_subscripts):
            if '.' in sub:
                if sub.count('.') != 3 or sub.count('...') != 1:
                    raise ValueError('Invalid Ellipses.')
                if operands[num].shape == ():
                    ellipse_count = 0
                else:
                    ellipse_count = max(operands[num].ndim, 1)
                    ellipse_count -= len(sub) - 3
                if ellipse_count > longest:
                    longest = ellipse_count
                if ellipse_count < 0:
                    raise ValueError('Ellipses lengths do not match.')
                elif ellipse_count == 0:
                    split_subscripts[num] = sub.replace('...', '')
                else:
                    rep_inds = ellipse_inds[-ellipse_count:]
                    split_subscripts[num] = sub.replace('...', rep_inds)
        subscripts = ','.join(split_subscripts)
        if longest == 0:
            out_ellipse = ''
        else:
            out_ellipse = ellipse_inds[-longest:]
        if out_sub:
            subscripts += '->' + output_sub.replace('...', out_ellipse)
        else:
            output_subscript = ''
            tmp_subscripts = subscripts.replace(',', '')
            for s in sorted(set(tmp_subscripts)):
                if s not in einsum_symbols:
                    raise ValueError(f'Character {s} is not a valid symbol.')
                if tmp_subscripts.count(s) == 1:
                    output_subscript += s
            normal_inds = ''.join(sorted(set(output_subscript) - set(out_ellipse)))
            subscripts += '->' + out_ellipse + normal_inds
    if '->' in subscripts:
        input_subscripts, output_subscript = subscripts.split('->')
    else:
        input_subscripts = subscripts
        tmp_subscripts = subscripts.replace(',', '')
        output_subscript = ''
        for s in sorted(set(tmp_subscripts)):
            if s not in einsum_symbols:
                raise ValueError(f'Character {s} is not a valid symbol.')
            if tmp_subscripts.count(s) == 1:
                output_subscript += s
    for char in output_subscript:
        if output_subscript.count(char) != 1:
            raise ValueError(f'Output character {char} appeared more than once in the output.')
        if char not in input_subscripts:
            raise ValueError(f'Output character {char} did not appear in the input')
    if len(input_subscripts.split(',')) != len(operands):
        raise ValueError('Number of einsum subscripts must be equal to the number of operands.')
    return (input_subscripts, output_subscript, operands)

@array_function_dispatch(_einsum_path_dispatcher, module='numpy')
def einsum_path(*operands, optimize='greedy', einsum_call=False):
    path_type = optimize
    if path_type is True:
        path_type = 'greedy'
    if path_type is None:
        path_type = False
    explicit_einsum_path = False
    memory_limit = None
    if path_type is False or isinstance(path_type, str):
        pass
    elif len(path_type) and path_type[0] == 'einsum_path':
        explicit_einsum_path = True
    elif len(path_type) == 2 and isinstance(path_type[0], str) and isinstance(path_type[1], (int, float)):
        memory_limit = int(path_type[1])
        path_type = path_type[0]
    else:
        raise TypeError(f'Did not understand the path: {str(path_type)}')
    einsum_call_arg = einsum_call
    input_subscripts, output_subscript, operands = _parse_einsum_input(operands)
    input_list = input_subscripts.split(',')
    num_inputs = len(input_list)
    input_sets = [set(x) for x in input_list]
    output_set = set(output_subscript)
    indices = set(input_subscripts.replace(',', ''))
    num_indices = len(indices)
    dimension_dict = {}
    for tnum, term in enumerate(input_list):
        sh = operands[tnum].shape
        if len(sh) != len(term):
            raise ValueError(f'Einstein sum subscript {input_subscripts[tnum]} does not contain the correct number of indices for operand {tnum}.')
        for cnum, char in enumerate(term):
            dim = sh[cnum]
            if char in dimension_dict.keys():
                if dimension_dict[char] == 1:
                    dimension_dict[char] = dim
                elif dim not in (1, dimension_dict[char]):
                    raise ValueError(f'Size of label {char!r} for operand {tnum} ({dimension_dict[char]}) does not match previous terms ({dim}).')
            else:
                dimension_dict[char] = dim
    size_list = [_compute_size_by_dict(term, dimension_dict) for term in input_list + [output_subscript]]
    max_size = max(size_list)
    if memory_limit is None:
        memory_arg = max_size
    else:
        memory_arg = memory_limit
    if explicit_einsum_path:
        path = path_type[1:]
    elif path_type is False or num_inputs in [1, 2] or indices == output_set:
        path = [tuple(range(num_inputs))]
    elif path_type == 'greedy':
        path = _greedy_path(input_sets, output_set, dimension_dict, memory_arg)
    elif path_type == 'optimal':
        path = _optimal_path(input_sets, output_set, dimension_dict, memory_arg)
    else:
        raise KeyError('Path name %s not found', path_type)
    cost_list, scale_list, size_list, contraction_list = ([], [], [], [])
    for cnum, contract_inds in enumerate(path):
        contract_inds = tuple(sorted(contract_inds, reverse=True))
        contract = _find_contraction(contract_inds, input_sets, output_set)
        out_inds, input_sets, idx_removed, idx_contract = contract
        if not einsum_call_arg:
            cost = _flop_count(idx_contract, idx_removed, len(contract_inds), dimension_dict)
            cost_list.append(cost)
            scale_list.append(len(idx_contract))
            size_list.append(_compute_size_by_dict(out_inds, dimension_dict))
        tmp_inputs = []
        for x in contract_inds:
            tmp_inputs.append(input_list.pop(x))
        if cnum - len(path) == -1:
            idx_result = output_subscript
        else:
            sort_result = [(dimension_dict[ind], ind) for ind in out_inds]
            idx_result = ''.join([x[1] for x in sorted(sort_result)])
        input_list.append(idx_result)
        einsum_str = ','.join(tmp_inputs) + '->' + idx_result
        contraction = (contract_inds, einsum_str, input_list[:])
        contraction_list.append(contraction)
    if len(input_list) != 1:
        raise RuntimeError(f'Invalid einsum_path is specified: {len(input_list) - 1} more operands has to be contracted.')
    if einsum_call_arg:
        return (operands, contraction_list)
    overall_contraction = input_subscripts + '->' + output_subscript
    inner_product = sum((len(set(x)) for x in input_subscripts.split(','))) - num_indices > 0
    naive_cost = _flop_count(indices, inner_product, num_inputs, dimension_dict)
    opt_cost = sum(cost_list) + 1
    speedup = naive_cost / opt_cost
    max_i = max(size_list)
    path_print = f'  Complete contraction:  {overall_contraction}\n'
    path_print += f'         Naive scaling:  {num_indices}\n'
    path_print += f'     Optimized scaling:  {max(scale_list)}\n'
    path_print += f'      Naive FLOP count:  {naive_cost:.3e}\n'
    path_print += f'  Optimized FLOP count:  {opt_cost:.3e}\n'
    path_print += f'   Theoretical speedup:  {speedup:3.3f}\n'
    path_print += f'  Largest intermediate:  {max_i:.3e} elements\n'
    path_print += '-' * 74 + '\n'
    path_print += f"{'scaling':>6} {'current':>24} {'remaining':>40}\n"
    path_print += '-' * 74
    for n, contraction in enumerate(contraction_list):
        _, einsum_str, remaining = contraction
        remaining_str = ','.join(remaining) + '->' + output_subscript
        path_print += f'\n{scale_list[n]:4d}    {einsum_str:>24} {remaining_str:>40}'
    path = ['einsum_path'] + path
    return (path, path_print)

def _parse_eq_to_pure_multiplication(a_term, shape_a, b_term, shape_b, out):
    desired_a = ''
    desired_b = ''
    new_shape_a = []
    new_shape_b = []
    for ix in out:
        if ix in a_term:
            desired_a += ix
            new_shape_a.append(shape_a[a_term.index(ix)])
        else:
            new_shape_a.append(1)
        if ix in b_term:
            desired_b += ix
            new_shape_b.append(shape_b[b_term.index(ix)])
        else:
            new_shape_b.append(1)
    if desired_a != a_term:
        eq_a = f'{a_term}->{desired_a}'
    else:
        eq_a = None
    if desired_b != b_term:
        eq_b = f'{b_term}->{desired_b}'
    else:
        eq_b = None
    return (eq_a, eq_b, new_shape_a, new_shape_b, None, None, True)

@functools.lru_cache(2 ** 12)
def _parse_eq_to_batch_matmul(eq, shape_a, shape_b):
    lhs, out = eq.split('->')
    a_term, b_term = lhs.split(',')
    if len(a_term) != len(shape_a):
        raise ValueError(f"Term '{a_term}' does not match shape {shape_a}.")
    if len(b_term) != len(shape_b):
        raise ValueError(f"Term '{b_term}' does not match shape {shape_b}.")
    sizes = {}
    singletons = set()
    left = {}
    for ix, d in zip(a_term, shape_a):
        if d == 1:
            singletons.add(ix)
            continue
        if sizes.setdefault(ix, d) != d:
            raise ValueError(f'Index {ix} has mismatched sizes {sizes[ix]} and {d}.')
        left[ix] = True
    right = {}
    for ix, d in zip(b_term, shape_b):
        if d == 1:
            if ix not in left:
                singletons.add(ix)
            continue
        singletons.discard(ix)
        if sizes.setdefault(ix, d) != d:
            raise ValueError(f'Index {ix} has mismatched sizes {sizes[ix]} and {d}.')
        right[ix] = True
    bat_inds = []
    con_inds = []
    a_keep = []
    b_keep = []
    for ix in left:
        if right.pop(ix, False):
            if ix in out:
                bat_inds.append(ix)
            else:
                con_inds.append(ix)
        elif ix in out:
            a_keep.append(ix)
    for ix in right:
        if ix in out:
            b_keep.append(ix)
    if not con_inds:
        return _parse_eq_to_pure_multiplication(a_term, shape_a, b_term, shape_b, out)
    singletons = [ix for ix in out if ix in singletons]
    desired_a = ''.join((*bat_inds, *a_keep, *con_inds))
    if a_term != desired_a:
        eq_a = f'{a_term}->{desired_a}'
    else:
        eq_a = None
    desired_b = ''.join((*bat_inds, *con_inds, *b_keep))
    if b_term != desired_b:
        eq_b = f'{b_term}->{desired_b}'
    else:
        eq_b = None
    if bat_inds:
        lgroups = (bat_inds, a_keep, con_inds)
        rgroups = (bat_inds, con_inds, b_keep)
        ogroups = (bat_inds, a_keep, b_keep)
    else:
        lgroups = (a_keep, con_inds)
        rgroups = (con_inds, b_keep)
        ogroups = (a_keep, b_keep)
    if any((len(group) != 1 for group in lgroups)):
        new_shape_a = tuple((functools.reduce(operator.mul, (sizes[ix] for ix in ix_group), 1) for ix_group in lgroups))
    else:
        new_shape_a = None
    if any((len(group) != 1 for group in rgroups)):
        new_shape_b = tuple((functools.reduce(operator.mul, (sizes[ix] for ix in ix_group), 1) for ix_group in rgroups))
    else:
        new_shape_b = None
    if any((len(group) != 1 for group in ogroups)) or singletons:
        new_shape_ab = (1,) * len(singletons) + tuple((sizes[ix] for ix_group in ogroups for ix in ix_group))
    else:
        new_shape_ab = None
    out_produced = ''.join((*singletons, *bat_inds, *a_keep, *b_keep))
    if out_produced != out:
        perm_ab = tuple((out_produced.index(ix) for ix in out))
    else:
        perm_ab = None
    return (eq_a, eq_b, new_shape_a, new_shape_b, new_shape_ab, perm_ab, False)

def bmm_einsum(eq, a, b, out=None, **kwargs):
    eq_a, eq_b, new_shape_a, new_shape_b, new_shape_ab, perm_ab, pure_multiplication = _parse_eq_to_batch_matmul(eq, a.shape, b.shape)
    output_order = _parse_output_order(kwargs.pop('order', 'K'), a.flags.f_contiguous, b.flags.f_contiguous)
    if eq_a is not None:
        a = c_einsum(eq_a, a)
    if new_shape_a is not None:
        a = reshape(a, new_shape_a)
    if eq_b is not None:
        b = c_einsum(eq_b, b)
    if new_shape_b is not None:
        b = reshape(b, new_shape_b)
    if pure_multiplication:
        if output_order is not None:
            kwargs['order'] = output_order
        return multiply(a, b, out=out, **kwargs)
    matmul_out_compatible = new_shape_ab is None and perm_ab is None
    if matmul_out_compatible:
        kwargs['out'] = out
    ab = matmul(a, b, **kwargs)
    if new_shape_ab is not None:
        ab = reshape(ab, new_shape_ab)
    if perm_ab is not None:
        ab = ab.transpose(perm_ab)
    if out is not None and (not matmul_out_compatible):
        out[...] = ab
        ab = out
    elif output_order is not None:
        ab = asanyarray(ab, order=output_order)
    return ab

@array_function_dispatch(_einsum_dispatcher, module='numpy')
def einsum(*operands, out=None, optimize=False, **kwargs):
    specified_out = out is not None
    if optimize is False:
        if specified_out:
            kwargs['out'] = out
        return c_einsum(*operands, **kwargs)
    valid_einsum_kwargs = ['dtype', 'order', 'casting']
    unknown_kwargs = [k for k in kwargs if k not in valid_einsum_kwargs]
    if len(unknown_kwargs):
        raise TypeError(f'Did not understand the following kwargs: {unknown_kwargs}')
    operands, contraction_list = einsum_path(*operands, optimize=optimize, einsum_call=True)
    for num, contraction in enumerate(contraction_list):
        inds, einsum_str, _ = contraction
        tmp_operands = [operands.pop(x) for x in inds]
        handle_out = specified_out and num + 1 == len(contraction_list)
        if handle_out:
            kwargs['out'] = out
        if len(tmp_operands) == 2:
            new_view = bmm_einsum(einsum_str, *tmp_operands, **kwargs)
        else:
            new_view = c_einsum(einsum_str, *tmp_operands, **kwargs)
        operands.append(new_view)
        del tmp_operands, new_view
    if specified_out:
        return out
    else:
        return operands[0]

