@set_module('numpy')
def binary_repr(num, width=None):

    def err_if_insufficient(width, binwidth):
        if width is not None and width < binwidth:
            raise ValueError(f'Insufficient bit width={width!r} provided for binwidth={binwidth!r}')
    num = operator.index(num)
    if num == 0:
        return '0' * (width or 1)
    elif num > 0:
        binary = f'{num:b}'
        binwidth = len(binary)
        outwidth = binwidth if width is None else builtins.max(binwidth, width)
        err_if_insufficient(width, binwidth)
        return binary.zfill(outwidth)
    elif width is None:
        return f'-{-num:b}'
    else:
        poswidth = len(f'{-num:b}')
        if 2 ** (poswidth - 1) == -num:
            poswidth -= 1
        twocomp = 2 ** (poswidth + 1) + num
        binary = f'{twocomp:b}'
        binwidth = len(binary)
        outwidth = builtins.max(binwidth, width)
        err_if_insufficient(width, binwidth)
        return '1' * (outwidth - binwidth) + binary

@set_module('numpy')
def base_repr(number, base=2, padding=0):
    digits = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ'
    if base > len(digits):
        raise ValueError('Bases greater than 36 not handled in base_repr.')
    elif base < 2:
        raise ValueError('Bases less than 2 not handled in base_repr.')
    num = abs(int(number))
    res = []
    while num:
        res.append(digits[num % base])
        num //= base
    if padding:
        res.append('0' * padding)
    if number < 0:
        res.append('-')
    return ''.join(reversed(res or '0'))

