@array_function_dispatch(_isclose_dispatcher)
def isclose(a, b, rtol=1e-05, atol=1e-08, equal_nan=False):
    x, y, atol, rtol = (a if isinstance(a, (int, float, complex)) else asanyarray(a) for a in (a, b, atol, rtol))
    if (dtype := getattr(y, 'dtype', None)) is not None and dtype.kind != 'm':
        dt = multiarray.result_type(y, 1.0)
        y = asanyarray(y, dtype=dt)
    elif isinstance(y, int):
        y = float(y)
    if not (np.all(np.isfinite(atol)) and np.all(np.isfinite(rtol))):
        err_s = np.geterr()['invalid']
        err_msg = f'One of rtol or atol is not valid, atol: {atol}, rtol: {rtol}'
        if err_s == 'warn':
            warnings.warn(err_msg, RuntimeWarning, stacklevel=2)
        elif err_s == 'raise':
            raise FloatingPointError(err_msg)
        elif err_s == 'print':
            print(err_msg)
    with errstate(invalid='ignore'):
        result = less_equal(abs(x - y), atol + rtol * abs(y)) & isfinite(y) | (x == y)
        if equal_nan:
            result |= isnan(x) & isnan(y)
    return result[()]

@array_function_dispatch(_array_equal_dispatcher)
def array_equal(a1, a2, equal_nan=False):
    try:
        a1, a2 = (asarray(a1), asarray(a2))
    except Exception:
        return False
    if a1.shape != a2.shape:
        return False
    if not equal_nan:
        return builtins.bool(asanyarray(a1 == a2).all())
    if a1 is a2:
        return True
    cannot_have_nan = _dtype_cannot_hold_nan(a1.dtype) and _dtype_cannot_hold_nan(a2.dtype)
    if cannot_have_nan:
        return builtins.bool(asarray(a1 == a2).all())
    a1nan = isnan(a1)
    if a1nan.all():
        return builtins.bool(isnan(a2).all())
    equal_or_both_nan = (a1 == a2) | a1nan & isnan(a2)
    return builtins.bool(equal_or_both_nan.all())

