def verify_matching_signatures(implementation, dispatcher):
    implementation_spec = ArgSpec(*getargspec(implementation))
    dispatcher_spec = ArgSpec(*getargspec(dispatcher))
    if implementation_spec.args != dispatcher_spec.args or implementation_spec.varargs != dispatcher_spec.varargs or implementation_spec.keywords != dispatcher_spec.keywords or (bool(implementation_spec.defaults) != bool(dispatcher_spec.defaults)) or (implementation_spec.defaults is not None and len(implementation_spec.defaults) != len(dispatcher_spec.defaults)):
        raise RuntimeError(f'implementation and dispatcher for {implementation} have different function signatures')
    if implementation_spec.defaults is not None:
        if dispatcher_spec.defaults != (None,) * len(dispatcher_spec.defaults):
            raise RuntimeError('dispatcher functions can only use None for default argument values')

def array_function_dispatch(dispatcher=None, module=None, verify=True, docs_from_dispatcher=False):

    def decorator(implementation):
        if verify:
            if dispatcher is not None:
                verify_matching_signatures(implementation, dispatcher)
            else:
                co = implementation.__code__
                last_arg = co.co_argcount + co.co_kwonlyargcount - 1
                last_arg = co.co_varnames[last_arg]
                if last_arg != 'like' or co.co_kwonlyargcount == 0:
                    raise RuntimeError(f'__array_function__ expects `like=` to be the last argument and a keyword-only argument. {implementation} does not seem to comply.')
        if docs_from_dispatcher and dispatcher.__doc__ is not None:
            doc = inspect.cleandoc(dispatcher.__doc__)
            add_docstring(implementation, doc)
        public_api = _ArrayFunctionDispatcher(dispatcher, implementation)
        functools.update_wrapper(public_api, implementation)
        if not verify and (not getattr(implementation, '__text_signature__', None)):
            public_api.__signature__ = inspect.signature(dispatcher)
        if module is not None:
            public_api.__module__ = module
        ARRAY_FUNCTIONS.add(public_api)
        return public_api
    return decorator

def array_function_from_dispatcher(implementation, module=None, verify=True, docs_from_dispatcher=True):

    def decorator(dispatcher):
        return array_function_dispatch(dispatcher, module, verify=verify, docs_from_dispatcher=docs_from_dispatcher)(implementation)
    return decorator

