@set_module('numpy.rec')
def fromfile(fd, dtype=None, shape=None, offset=0, formats=None, names=None, titles=None, aligned=False, byteorder=None):
    if dtype is None and formats is None:
        raise TypeError("fromfile() needs a 'dtype' or 'formats' argument")
    shape = _deprecate_shape_0_as_None(shape)
    if shape is None:
        shape = (-1,)
    elif isinstance(shape, int):
        shape = (shape,)
    if hasattr(fd, 'readinto'):
        ctx = nullcontext(fd)
    else:
        ctx = open(os.fspath(fd), 'rb')
    with ctx as fd:
        if offset > 0:
            fd.seek(offset, 1)
        size = get_remaining_size(fd)
        if dtype is not None:
            descr = sb.dtype(dtype)
        else:
            descr = format_parser(formats, names, titles, aligned, byteorder).dtype
        itemsize = descr.itemsize
        shapeprod = sb.array(shape).prod(dtype=nt.intp)
        shapesize = shapeprod * itemsize
        if shapesize < 0:
            shape = list(shape)
            shape[shape.index(-1)] = size // -shapesize
            shape = tuple(shape)
            shapeprod = sb.array(shape).prod(dtype=nt.intp)
        nbytes = shapeprod * itemsize
        if nbytes > size:
            raise ValueError('Not enough bytes left in file for specified shape and type.')
        _array = recarray(shape, descr)
        nbytesread = fd.readinto(_array.data)
        if nbytesread != nbytes:
            raise OSError("Didn't read as many bytes as expected")
    return _array

@set_module('numpy.rec')
def array(obj, dtype=None, shape=None, offset=0, strides=None, formats=None, names=None, titles=None, aligned=False, byteorder=None, copy=True):
    if (isinstance(obj, (type(None), str)) or hasattr(obj, 'readinto')) and formats is None and (dtype is None):
        raise ValueError('Must define formats (or dtype) if object is None, string, or an open file')
    kwds = {}
    if dtype is not None:
        dtype = sb.dtype(dtype)
    elif formats is not None:
        dtype = format_parser(formats, names, titles, aligned, byteorder).dtype
    else:
        kwds = {'formats': formats, 'names': names, 'titles': titles, 'aligned': aligned, 'byteorder': byteorder}
    if obj is None:
        if shape is None:
            raise ValueError('Must define a shape if obj is None')
        return recarray(shape, dtype, buf=obj, offset=offset, strides=strides)
    elif isinstance(obj, bytes):
        return fromstring(obj, dtype, shape=shape, offset=offset, **kwds)
    elif isinstance(obj, (list, tuple)):
        if isinstance(obj[0], (tuple, list)):
            return fromrecords(obj, dtype=dtype, shape=shape, **kwds)
        else:
            return fromarrays(obj, dtype=dtype, shape=shape, **kwds)
    elif isinstance(obj, recarray):
        if dtype is not None and obj.dtype != dtype:
            new = obj.view(dtype)
        else:
            new = obj
        if copy:
            new = new.copy()
        return new
    elif hasattr(obj, 'readinto'):
        return fromfile(obj, dtype=dtype, shape=shape, offset=offset)
    elif isinstance(obj, ndarray):
        if dtype is not None and obj.dtype != dtype:
            new = obj.view(dtype)
        else:
            new = obj
        if copy:
            new = new.copy()
        return new.view(recarray)
    else:
        interface = getattr(obj, '__array_interface__', None)
        if interface is None or not isinstance(interface, dict):
            raise ValueError('Unknown input type')
        obj = sb.array(obj)
        if dtype is not None and obj.dtype != dtype:
            obj = obj.view(dtype)
        return obj.view(recarray)

def _parseFormats(self, formats, aligned=False):
    if formats is None:
        raise ValueError('Need formats argument')
    if isinstance(formats, list):
        dtype = sb.dtype([(f'f{i}', format_) for i, format_ in enumerate(formats)], aligned)
    else:
        dtype = sb.dtype(formats, aligned)
    fields = dtype.fields
    if fields is None:
        dtype = sb.dtype([('f1', dtype)], aligned)
        fields = dtype.fields
    keys = dtype.names
    self._f_formats = [fields[key][0] for key in keys]
    self._offsets = [fields[key][1] for key in keys]
    self._nfields = len(keys)

def _setfieldnames(self, names, titles):
    if names:
        if type(names) in [list, tuple]:
            pass
        elif isinstance(names, str):
            names = names.split(',')
        else:
            raise NameError(f'illegal input names {repr(names)}')
        self._names = [n.strip() for n in names[:self._nfields]]
    else:
        self._names = []
    self._names += [f'f{i}' for i in range(len(self._names), self._nfields)]
    _dup = find_duplicate(self._names)
    if _dup:
        raise ValueError(f'Duplicate field names: {_dup}')
    if titles:
        self._titles = [n.strip() for n in titles[:self._nfields]]
    else:
        self._titles = []
        titles = []
    if self._nfields > len(titles):
        self._titles += [None] * (self._nfields - len(titles))

def pprint(self):
    names = self.dtype.names
    maxlen = max((len(name) for name in names))
    rows = [f'{name:>{maxlen}}: {getattr(self, name)}' for name in names]
    return '\n'.join(rows)

