def _byte_order_str(dtype):
    swapped = np.dtype(int).newbyteorder('S')
    native = swapped.newbyteorder('S')
    byteorder = dtype.byteorder
    if byteorder == '=':
        return native.byteorder
    if byteorder == 'S':
        return swapped.byteorder
    elif byteorder == '|':
        return ''
    else:
        return byteorder

def _is_packed(dtype):
    align = dtype.isalignedstruct
    max_alignment = 1
    total_offset = 0
    for name in dtype.names:
        fld_dtype, fld_offset, title = _unpack_field(*dtype.fields[name])
        if align:
            total_offset = _aligned_offset(total_offset, fld_dtype.alignment)
            max_alignment = max(max_alignment, fld_dtype.alignment)
        if fld_offset != total_offset:
            return False
        total_offset += fld_dtype.itemsize
    if align:
        total_offset = _aligned_offset(total_offset, max_alignment)
    return total_offset == dtype.itemsize

def _from_ctypes_scalar(t):
    if getattr(t, '__ctype_be__', None) is t:
        return np.dtype('>' + t._type_)
    elif getattr(t, '__ctype_le__', None) is t:
        return np.dtype('<' + t._type_)
    else:
        return np.dtype(t._type_)

def dtype_from_ctypes_type(t):
    import _ctypes
    if issubclass(t, _ctypes.Array):
        return _from_ctypes_array(t)
    elif issubclass(t, _ctypes._Pointer):
        raise TypeError('ctypes pointers have no dtype equivalent')
    elif issubclass(t, _ctypes.Structure):
        return _from_ctypes_structure(t)
    elif issubclass(t, _ctypes.Union):
        return _from_ctypes_union(t)
    elif isinstance(getattr(t, '_type_', None), str):
        return _from_ctypes_scalar(t)
    else:
        raise NotImplementedError(f'Unknown ctypes type {t.__name__}')

@staticmethod
def _size_to_string(num_bytes):
    LOG2_STEP = 10
    STEP = 1024
    units = ['bytes', 'KiB', 'MiB', 'GiB', 'TiB', 'PiB', 'EiB']
    unit_i = max(num_bytes.bit_length() - 1, 1) // LOG2_STEP
    unit_val = 1 << unit_i * LOG2_STEP
    n_units = num_bytes / unit_val
    del unit_val
    if round(n_units) == STEP:
        unit_i += 1
        n_units /= STEP
    if unit_i >= len(units):
        new_unit_i = len(units) - 1
        n_units *= 1 << (unit_i - new_unit_i) * LOG2_STEP
        unit_i = new_unit_i
    unit_name = units[unit_i]
    if unit_i == 0:
        return f'{n_units:.0f} {unit_name}'
    elif round(n_units) < 1000:
        return f'{n_units:#.3g} {unit_name}'
    else:
        return f'{n_units:#.0f} {unit_name}'

def _newnames(datatype, order):
    oldnames = datatype.names
    nameslist = list(oldnames)
    if isinstance(order, str):
        order = [order]
    seen = set()
    if isinstance(order, (list, tuple)):
        for name in order:
            try:
                nameslist.remove(name)
            except ValueError:
                if name in seen:
                    raise ValueError(f'duplicate field name: {name}') from None
                else:
                    raise ValueError(f'unknown field name: {name}') from None
            seen.add(name)
        return tuple(list(order) + nameslist)
    raise ValueError(f'unsupported order value: {order}')

def _copy_fields(ary):
    dt = ary.dtype
    copy_dtype = {'names': dt.names, 'formats': [dt.fields[name][0] for name in dt.names]}
    return array(ary, dtype=copy_dtype, copy=True)

def _promote_fields(dt1, dt2):
    if (dt1.names is None or dt2.names is None) or dt1.names != dt2.names:
        raise DTypePromotionError(f'field names `{dt1.names}` and `{dt2.names}` mismatch.')
    identical = dt1 is dt2
    new_fields = []
    for name in dt1.names:
        field1 = dt1.fields[name]
        field2 = dt2.fields[name]
        new_descr = promote_types(field1[0], field2[0])
        identical = identical and new_descr is field1[0]
        if field1[2:] != field2[2:]:
            raise DTypePromotionError(f"field titles of field '{name}' mismatch")
        if len(field1) == 2:
            new_fields.append((name, new_descr))
        else:
            new_fields.append(((field1[2], name), new_descr))
    res = dtype(new_fields, align=dt1.isalignedstruct or dt2.isalignedstruct)
    if identical and res.itemsize == dt1.itemsize:
        for name in dt1.names:
            if dt1.fields[name][1] != res.fields[name][1]:
                return res
        return dt1
    return res

def _getfield_is_safe(oldtype, newtype, offset):
    if newtype.hasobject or oldtype.hasobject:
        if offset == 0 and _is_view_safe_cast(oldtype, newtype):
            return
        if oldtype.names is not None:
            for name in oldtype.names:
                if oldtype.fields[name][1] == offset and oldtype.fields[name][0] == newtype:
                    return
        raise TypeError('Cannot get/set field of an object array')
    return

def _view_is_safe(oldtype, newtype):
    if _is_view_safe_cast(oldtype, newtype):
        return
    if newtype.hasobject or oldtype.hasobject:
        raise TypeError('Cannot change data-type for array of references.')
    return

def _fix_names(field_spec):
    names = field_spec['names']
    for i, name in enumerate(names):
        if name is not None:
            continue
        j = 0
        while True:
            name = f'f{j}'
            if name not in names:
                break
            j = j + 1
        names[i] = name

def _add_trailing_padding(value, padding):
    if value.fields is None:
        field_spec = {'names': ['f0'], 'formats': [value], 'offsets': [0], 'itemsize': value.itemsize}
    else:
        fields = value.fields
        names = value.names
        field_spec = {'names': names, 'formats': [fields[name][0] for name in names], 'offsets': [fields[name][1] for name in names], 'itemsize': value.itemsize}
    field_spec['itemsize'] += padding
    return dtype(field_spec)

def _gcd(a, b):
    if not (math.isfinite(a) and math.isfinite(b)):
        raise ValueError(f'Can only find greatest common divisor of finite arguments, found "{a}" and "{b}"')
    while b:
        a, b = (b, a % b)
    return a

