def _parse_docstrings() -> str:
    type_list_ret = []
    for name, value, doc in _docstrings_list:
        s = textwrap.dedent(doc).replace('\n', '\n    ')
        lines = s.split('\n')
        new_lines = []
        indent = ''
        for line in lines:
            m = re.match('^(\\s+)[-=]+\\s*$', line)
            if m and new_lines:
                prev = textwrap.dedent(new_lines.pop())
                if prev == 'Examples':
                    indent = ''
                    new_lines.append(f'{m.group(1)}.. rubric:: {prev}')
                else:
                    indent = 4 * ' '
                    new_lines.append(f'{m.group(1)}.. admonition:: {prev}')
                new_lines.append('')
            else:
                new_lines.append(f'{indent}{line}')
        s = '\n'.join(new_lines)
        s_block = f'.. data:: {name}\n    :value: {value}\n    {s}'
        type_list_ret.append(s_block)
    return '\n'.join(type_list_ret)

def getargs(co):
    if not iscode(co):
        raise TypeError('arg is not a code object')
    nargs = co.co_argcount
    names = co.co_varnames
    args = list(names[:nargs])
    for i in range(nargs):
        if args[i][:1] in ['', '.']:
            raise TypeError('tuple function arguments are not supported')
    varargs = None
    if co.co_flags & CO_VARARGS:
        varargs = co.co_varnames[nargs]
        nargs = nargs + 1
    varkw = None
    if co.co_flags & CO_VARKEYWORDS:
        varkw = co.co_varnames[nargs]
    return (args, varargs, varkw)

def getargspec(func):
    if ismethod(func):
        func = func.__func__
    if not isfunction(func):
        raise TypeError('arg is not a Python function')
    args, varargs, varkw = getargs(func.__code__)
    return (args, varargs, varkw, func.__defaults__)

def getargvalues(frame):
    args, varargs, varkw = getargs(frame.f_code)
    return (args, varargs, varkw, frame.f_locals)

def strseq(object, convert, join=joinseq):
    if type(object) in [list, tuple]:
        return join([strseq(_o, convert, join) for _o in object])
    else:
        return convert(object)

def formatargspec(args, varargs=None, varkw=None, defaults=None, formatarg=str, formatvarargs=lambda name: '*' + name, formatvarkw=lambda name: '**' + name, formatvalue=lambda value: '=' + repr(value), join=joinseq):
    specs = []
    if defaults:
        firstdefault = len(args) - len(defaults)
    for i in range(len(args)):
        spec = strseq(args[i], formatarg, join)
        if defaults and i >= firstdefault:
            spec = spec + formatvalue(defaults[i - firstdefault])
        specs.append(spec)
    if varargs is not None:
        specs.append(formatvarargs(varargs))
    if varkw is not None:
        specs.append(formatvarkw(varkw))
    return '(' + ', '.join(specs) + ')'

def formatargvalues(args, varargs, varkw, locals, formatarg=str, formatvarargs=lambda name: '*' + name, formatvarkw=lambda name: '**' + name, formatvalue=lambda value: '=' + repr(value), join=joinseq):

    def convert(name, locals=locals, formatarg=formatarg, formatvalue=formatvalue):
        return formatarg(name) + formatvalue(locals[name])
    specs = [strseq(arg, convert, join) for arg in args]
    if varargs:
        specs.append(formatvarargs(varargs) + formatvalue(locals[varargs]))
    if varkw:
        specs.append(formatvarkw(varkw) + formatvalue(locals[varkw]))
    return '(' + ', '.join(specs) + ')'

