@contextlib.contextmanager
def patch_pickle() -> Generator[None]:
    orig_loads = pickle.loads
    try:
        setattr(pickle, 'loads', loads)
        yield
    finally:
        setattr(pickle, 'loads', orig_loads)

def _safe_fill_null(arr: pa.Array | pa.ChunkedArray, fill_value: Any) -> pa.Array | pa.ChunkedArray:
    import pyarrow.compute as pc
    is_windows = sys.platform in ['win32', 'cygwin']
    use_fallback = HAS_PYARROW and is_windows and (not pa_version_under21p0) and pa_version_under22p0
    if not use_fallback or isinstance(fill_value, (pa.Array, pa.ChunkedArray)):
        return pc.fill_null(arr, fill_value)
    fill_scalar = pa.scalar(fill_value, type=arr.type)
    if pa.types.is_duration(arr.type):

        def fill_null_duration(arr: pa.Array, fill_scalar: pa.Scalar) -> pa.Array:
            mask = pc.is_null(arr)
            zero_duration = pa.scalar(0, type=arr.type)
            arr_zeroed = pc.if_else(mask, zero_duration, arr)
            return pc.if_else(mask, fill_scalar, arr_zeroed)
        if isinstance(arr, pa.ChunkedArray):
            return pa.chunked_array([fill_null_duration(chunk, fill_scalar) for chunk in arr.chunks])
        return fill_null_duration(arr, fill_scalar)
    if isinstance(arr, pa.ChunkedArray):
        return pa.chunked_array([pc.if_else(pc.is_null(chunk), fill_scalar, chunk) for chunk in arr.chunks])
    return pc.if_else(pc.is_null(arr), fill_scalar, arr)

def import_optional_dependency(name: str, extra: str='', min_version: str | None=None, *, errors: Literal['raise', 'warn', 'ignore']='raise') -> types.ModuleType | None:
    assert errors in {'warn', 'raise', 'ignore'}
    package_name = INSTALL_MAPPING.get(name)
    install_name = package_name if package_name is not None else name
    msg = f'`Import {install_name}` failed. {extra} Use pip, conda, or your preferred package management tool to install the {install_name} package.'
    try:
        module = importlib.import_module(name)
    except ImportError as err:
        if errors == 'raise':
            raise ImportError(msg) from err
        return None
    parent = name.split('.', maxsplit=1)[0]
    if parent != name:
        install_name = parent
        module_to_get = sys.modules[install_name]
    else:
        module_to_get = module
    minimum_version = min_version if min_version is not None else VERSIONS.get(parent)
    if minimum_version:
        version = get_version(module_to_get)
        if version and Version(version) < Version(minimum_version):
            msg = f"Pandas requires version '{minimum_version}' or newer of '{parent}' (version '{version}' currently installed)."
            if errors == 'warn':
                warnings.warn(msg, UserWarning, stacklevel=find_stack_level())
                return None
            elif errors == 'raise':
                raise ImportError(msg)
            else:
                return None
    return module

