def apply(self, func: AggFuncType, axis: Axis=0, raw: bool=False, result_type: Literal['expand', 'reduce', 'broadcast'] | None=None, args=(), by_row: Literal[False, 'compat']='compat', engine: Callable | None | Literal['python', 'numba']=None, engine_kwargs: dict[str, bool] | None=None, **kwargs):
    if engine is None or isinstance(engine, str):
        from pandas.core.apply import frame_apply
        if engine is None:
            engine = 'python'
        if engine not in ['python', 'numba']:
            raise ValueError(f"Unknown engine '{engine}'")
        op = frame_apply(self, func=func, axis=axis, raw=raw, result_type=result_type, by_row=by_row, engine=engine, engine_kwargs=engine_kwargs, args=args, kwargs=kwargs)
