    elif hasattr(engine, '__pandas_udf__'):
        if result_type is not None:
            raise NotImplementedError(f'result_type={result_type!r} only implemented for the default engine')
        agg_axis = self._get_agg_axis(self._get_axis_number(axis))
        if not all(self.shape):
            func = cast('Callable', func)
            try:
                if axis == 0:
                    r = func(Series([], dtype=np.float64), *args, **kwargs)
                else:
                    r = func(Series(index=self.columns, dtype=np.float64), *args, **kwargs)
            except Exception:
                pass
            else:
                if not isinstance(r, Series):
                    if len(agg_axis):
                        r = func(Series([], dtype=np.float64), *args, **kwargs)
                    else:
                        r = np.nan
