        data: DataFrame | np.ndarray = self
        if raw:
            data = self.values
        result = engine.__pandas_udf__.apply(data=data, func=func, args=args, kwargs=kwargs, decorator=engine, axis=axis)
        if raw:
            if result.ndim == 2:
                return self._constructor(result, index=self.index, columns=self.columns)
            else:
                return self._constructor_sliced(result, index=agg_axis)
        return result
    else:
        raise ValueError(f'Unknown engine {engine}')

