    inplace = validate_bool_kwarg(inplace, 'inplace')
    renamed = self if inplace else self.copy(deep=False)
    if axis == 0:
        renamed.index = idx
    else:
        renamed.columns = idx
    if not inplace:
        return renamed
    return None

