def rank(self, axis: Axis=0, method: RankMethod='average', numeric_only: bool=False, na_option: RankNaOption='keep', ascending: bool=True, pct: bool=False) -> Self:
    axis_int = self._get_axis_number(axis)
    if na_option not in {'keep', 'top', 'bottom'}:
        msg = "na_option must be one of 'keep', 'top', or 'bottom'"
        raise ValueError(msg)

    def ranker(data):
        if data.ndim == 2:
            values = data.values
        else:
            values = data._values
        if isinstance(values, ExtensionArray):
            ranks = values._rank(axis=axis_int, method=method, ascending=ascending, na_option=na_option, pct=pct)
        else:
            ranks = algos.rank(values, axis=axis_int, method=method, ascending=ascending, na_option=na_option, pct=pct)
        ranks_obj = self._constructor(ranks, **data._construct_axes_dict())
