    if using_string_dtype():
        from pandas import StringDtype, array as pd_array
        return pd_array(result, dtype=StringDtype(na_value=np.nan))
    return result

def _to_local_pa_timestamp(self) -> pa.Array:
    import pyarrow as pa
    values = self._local_timestamps()
    mask = self._isnan
    return pa.array(values, mask=mask, type=pa.timestamp(self.unit))

@staticmethod
