@classmethod
def construct_from_string(cls, string) -> Self:
    if not isinstance(string, str):
        raise TypeError(f"'construct_from_string' expects a string, got {type(string)}")
    if string == 'string':
        return cls()
    elif string == 'str' and using_string_dtype():
        return cls(na_value=np.nan)
    elif string == 'string[python]':
        return cls(storage='python')
    elif string == 'string[pyarrow]':
        return cls(storage='pyarrow')
    else:
        raise TypeError(f"Cannot construct a '{cls.__name__}' from '{string}'")

def construct_array_type(self) -> type_t[BaseStringArray]:
    from pandas.core.arrays.string_arrow import ArrowStringArray
    if self.storage == 'python' and self._na_value is libmissing.NA:
        return StringArray
    elif self.storage == 'pyarrow' and self._na_value is libmissing.NA:
        return ArrowStringArray
    elif self.storage == 'python':
        return StringArray
    else:
        return ArrowStringArray

def __from_arrow__(self, array: pyarrow.Array | pyarrow.ChunkedArray) -> BaseStringArray:
    if self.storage == 'pyarrow':
        from pandas.core.arrays.string_arrow import ArrowStringArray, _check_pyarrow_available
        _check_pyarrow_available()
        if not pa.types.is_large_string(array.type):
            array = pc.cast(array, pa.large_string())
        return ArrowStringArray(array, dtype=self)
    else:
        import pyarrow
        if isinstance(array, pyarrow.Array):
            chunks = [array]
        else:
            chunks = array.chunks
        results = []
        for arr in chunks:
            arr = arr.to_numpy(zero_copy_only=False)
            arr = ensure_string_array(arr, na_value=self.na_value)
            results.append(arr)
    if len(chunks) == 0:
        arr = np.array([], dtype=object)
    else:
        arr = np.concatenate(results)
    new_string_array = StringArray.__new__(StringArray)
    NDArrayBacked.__init__(new_string_array, arr, self)
    return new_string_array

def tolist(self) -> list:
    if self.ndim > 1:
        return [x.tolist() for x in self]
    return list(self.to_numpy())

def _validate(self, dtype: StringDtype) -> None:
    if dtype._na_value is libmissing.NA:
        if len(self._ndarray) and (not lib.is_string_array(self._ndarray, skipna=True)):
            raise ValueError('StringArray requires a sequence of strings or pandas.NA')
        if self._ndarray.dtype != 'object':
            raise ValueError(f"StringArray requires a sequence of strings or pandas.NA. Got '{self._ndarray.dtype}' dtype instead.")
        if self._ndarray.ndim > 2:
            lib.convert_nans_to_NA(self._ndarray.ravel('K'))
        else:
            lib.convert_nans_to_NA(self._ndarray)
    else:
        if len(self._ndarray) and (not lib.is_string_array(self._ndarray, skipna=True)):
            raise ValueError('StringArray requires a sequence of strings or NaN')
        if self._ndarray.dtype != 'object':
            raise ValueError("StringArray requires a sequence of strings or NaN. Got '{self._ndarray.dtype}' dtype instead.")

def __arrow_array__(self, type=None):
    import pyarrow as pa
    if type is None:
        type = pa.string()
    values = self._ndarray.copy()
    values[self.isna()] = None
    return pa.array(values, type=type)

def _validate_setitem_value(self, value):
    if lib.is_scalar(value):
        if isna(value):
            value = self.dtype.na_value
        elif not isinstance(value, str):
            raise TypeError(f"Invalid value '{value}' for dtype '{self.dtype}'. Value should be a string or missing value, got '{type(value).__name__}' instead.")
    else:
        value = extract_array(value, extract_numpy=True)
        if not is_array_like(value):
            value = np.asarray(value, dtype=object)
        elif isinstance(value.dtype, type(self.dtype)):
            return value
        else:
            value = np.asarray(value)
        if len(value) and (not lib.is_string_array(value, skipna=True)):
            raise TypeError("Invalid value for dtype 'str'. Value should be a string or missing value (or array of those).")
    return value

def _accumulate(self, name: str, *, skipna: bool=True, **kwargs) -> StringArray:
    if name == 'cumprod':
        msg = f"operation '{name}' not supported for dtype '{self.dtype}'"
        raise TypeError(msg)
    tail: np.ndarray | None = None
    na_mask: np.ndarray | None = None
    ndarray = self._ndarray
    np_func = {'cumsum': np.cumsum, 'cummin': np.minimum.accumulate, 'cummax': np.maximum.accumulate}[name]
    if self._hasna:
        na_mask = cast('npt.NDArray[np.bool_]', isna(ndarray))
        if np.all(na_mask):
            return type(self)(ndarray, dtype=self.dtype)
        if skipna:
            if name == 'cumsum':
                ndarray = np.where(na_mask, '', ndarray)
            else:
                ndarray = ndarray.copy()
                missing.pad_or_backfill_inplace(ndarray, method='pad', axis=0)
                missing.pad_or_backfill_inplace(ndarray, method='backfill', axis=0)
        else:
            idx = np.argmax(na_mask)
            tail = np.empty(len(ndarray) - idx, dtype='object')
            tail[:] = self.dtype.na_value
            ndarray = ndarray[:idx]
    np_result = np_func(ndarray)
    if tail is not None:
        np_result = np.hstack((np_result, tail))
    elif na_mask is not None:
        np_result = np.where(na_mask, self.dtype.na_value, np_result)
    result = type(self)(np_result, dtype=self.dtype)
    return result

def searchsorted(self, value: NumpyValueArrayLike | ExtensionArray, side: Literal['left', 'right']='left', sorter: NumpySorter | None=None) -> npt.NDArray[np.intp] | np.intp:
    ndarray = self._ndarray
    if len(ndarray):
        if sorter is None:
            has_na = libmissing.checknull(ndarray[0]) or libmissing.checknull(ndarray[-1])
        else:
            has_na = libmissing.checknull(ndarray[sorter[0]]) or libmissing.checknull(ndarray[sorter[-1]])
    else:
        has_na = False
    if has_na:
        raise ValueError('searchsorted requires array to be sorted, which is impossible with NAs present.')
    return super().searchsorted(value=value, side=side, sorter=sorter)

def _from_pyarrow_array(self, pa_array):
    assert isinstance(pa_array, (pa.Array, pa.ChunkedArray))
    if not pa.types.is_large_string(pa_array.type):
        pa_array = pa_array.cast(pa.large_string())
    obj = type(self).__new__(type(self))
    if isinstance(pa_array, pa.Array):
        pa_array = pa.chunked_array([pa_array])
    obj._pa_array = pa_array
    obj._dtype = self._dtype
    obj._cache = {}
    return obj

