def generate(self, v) -> str:
    val = v.tostring(self.encoding)
    return f'({self.lhs.value} {self.op} {val})'

def convert_value(self, conv_val) -> TermValue:

    def stringify(value):
        if self.encoding is not None:
            return pprint_thing_encoded(value, encoding=self.encoding)
        return pprint_thing(value)
    kind = ensure_decoded(self.kind)
    meta = ensure_decoded(self.meta)
    if kind == 'datetime' or (kind and kind.startswith('datetime64')):
        if isinstance(conv_val, (int, float)):
            conv_val = stringify(conv_val)
        conv_val = ensure_decoded(conv_val)
        unit: TimeUnit = 'ns'
        if '[' in kind:
            unit = cast('TimeUnit', kind.split('[')[-1][:-1])
        conv_val = Timestamp(conv_val).as_unit(unit)
        if conv_val.tz is not None:
            conv_val = conv_val.tz_convert('UTC')
        return TermValue(conv_val, conv_val._value, kind)
    elif kind.startswith('timedelta'):
        unit = 'ns'
        if '[' in kind:
            unit = cast('TimeUnit', kind.split('[')[-1][:-1])
        if isinstance(conv_val, str):
            conv_val = Timedelta(conv_val)
        elif lib.is_integer(conv_val) or lib.is_float(conv_val):
            conv_val = Timedelta(conv_val, unit='s')
        else:
            conv_val = Timedelta(conv_val)
        conv_val = conv_val.as_unit(unit)._value
        return TermValue(int(conv_val), conv_val, kind)
    elif meta == 'category':
        metadata = extract_array(self.metadata, extract_numpy=True)
        result: npt.NDArray[np.intp] | np.intp | int
        if conv_val not in metadata:
            result = -2
        else:
            result = np.flatnonzero(metadata == conv_val)[0]
        return TermValue(result, result, 'integer')
    elif kind == 'integer':
        try:
            v_dec = Decimal(conv_val)
        except InvalidOperation:
            float(conv_val)
        else:
            conv_val = int(v_dec.to_integral_exact(rounding='ROUND_HALF_EVEN'))
        return TermValue(conv_val, conv_val, kind)
    elif kind == 'float':
        conv_val = float(conv_val)
        return TermValue(conv_val, conv_val, kind)
    elif kind == 'bool':
        if isinstance(conv_val, str):
            conv_val = conv_val.strip().lower() not in ['false', 'f', 'no', 'n', 'none', '0', '[]', '{}', '']
        else:
            conv_val = bool(conv_val)
        return TermValue(conv_val, conv_val, kind)
    elif isinstance(conv_val, str):
        return TermValue(conv_val, stringify(conv_val), 'string')
    else:
        raise TypeError(f'Cannot compare {conv_val} of type {type(conv_val)} to {kind} column')

def invert(self) -> Self:
    if self.filter is not None:
        self.filter = (self.filter[0], self.generate_filter_op(invert=True), self.filter[2])
    return self

def evaluate(self):
    try:
        self.condition = self.terms.prune(ConditionBinOp)
    except AttributeError as err:
        raise ValueError(f'cannot process expression [{self.expr}], [{self}] is not a valid condition') from err
    try:
        self.filter = self.terms.prune(FilterBinOp)
    except AttributeError as err:
        raise ValueError(f'cannot process expression [{self.expr}], [{self}] is not a valid filter') from err
    return (self.condition, self.filter)

def tostring(self, encoding) -> str:
    if self.kind == 'string':
        if encoding is not None:
            return str(self.converted)
        return f'"{self.converted}"'
    elif self.kind == 'float':
        return repr(self.converted)
    return str(self.converted)

def pr(left, right):
    if left is None:
        return right
    elif right is None:
        return left
    k = klass
    if isinstance(left, ConditionBinOp):
        if isinstance(right, ConditionBinOp):
            k = JointConditionBinOp
        elif isinstance(left, k):
            return left
        elif isinstance(right, k):
            return right
    elif isinstance(left, FilterBinOp):
        if isinstance(right, FilterBinOp):
            k = JointFilterBinOp
        elif isinstance(left, k):
            return left
        elif isinstance(right, k):
            return right
    return k(self.op, left, right, queryables=self.queryables, encoding=self.encoding).evaluate()

def _replacer(x) -> str:
    try:
        hexin = ord(x)
    except TypeError:
        hexin = x
    return hex(hexin)

def _raw_hex_id(obj) -> str:
    packed = struct.pack('@P', id(obj))
    return ''.join([_replacer(x) for x in packed])

def _get_pretty_string(obj) -> str:
    sio = StringIO()
    pprint.pprint(obj, stream=sio)
    return sio.getvalue()

def __delitem__(self, key: _KT) -> None:
    for mapping in self.maps:
        if key in mapping:
            del mapping[key]
            return
    raise KeyError(key)

@property
def has_resolvers(self) -> bool:
    return bool(len(self.resolvers))

def resolve(self, key: str, is_local: bool):
    try:
        if is_local:
            return self.scope[key]
        if self.has_resolvers:
            return self.resolvers[key]
        assert not is_local and (not self.has_resolvers)
        return self.scope[key]
    except KeyError:
        try:
            return self.temps[key]
        except KeyError as err:
            raise UndefinedVariableError(key, is_local) from err

def swapkey(self, old_key: str, new_key: str, new_value=None) -> None:
    if self.has_resolvers:
        maps = self.resolvers.maps + self.scope.maps
    else:
        maps = self.scope.maps
    maps.append(self.temps)
    for mapping in maps:
        if old_key in mapping:
            mapping[new_key] = new_value
            return

def _get_vars(self, stack, scopes: list[str]) -> None:
    variables = itertools.product(scopes, stack)
    for scope, (frame, _, _, _, _, _) in variables:
        d = getattr(frame, f'f_{scope}')
        self.scope = DeepChainMap(self.scope.new_child(d))

@property
def ntemps(self) -> int:
    return len(self.temps)

@property
def full_scope(self) -> DeepChainMap:
    maps = [self.temps, *self.resolvers.maps, *self.scope.maps]
    return DeepChainMap(*maps)

def _astype_nansafe(arr: np.ndarray, dtype: DtypeObj, copy: bool=True, skipna: bool=False) -> ArrayLike:
    if isinstance(dtype, ExtensionDtype):
        return dtype.construct_array_type()._from_sequence(arr, dtype=dtype, copy=copy)
    elif not isinstance(dtype, np.dtype):
        raise ValueError('dtype must be np.dtype or ExtensionDtype')
    if arr.dtype.kind in 'mM':
        from pandas.core.construction import ensure_wrapped_if_datetimelike
        wrapped = ensure_wrapped_if_datetimelike(arr)
        res = wrapped.astype(dtype, copy=copy)
        return np.asarray(res)
    if issubclass(dtype.type, str):
        shape = arr.shape
        if arr.ndim > 1:
            arr = arr.ravel()
        return lib.ensure_string_array(arr, skipna=skipna, convert_na_value=False).reshape(shape)
    elif np.issubdtype(arr.dtype, np.floating) and dtype.kind in 'iu':
        return astype_float_to_int_nansafe(arr, dtype, copy)
    elif arr.dtype == object:
        if lib.is_np_dtype(dtype, 'M'):
            from pandas.core.arrays import DatetimeArray
            dta = DatetimeArray._from_sequence(arr, dtype=dtype)
            return dta._ndarray
        elif lib.is_np_dtype(dtype, 'm'):
            from pandas.core.construction import ensure_wrapped_if_datetimelike
            tdvals = array_to_timedelta64(arr)
            tda = ensure_wrapped_if_datetimelike(tdvals)
            return tda.astype(dtype, copy=False)._ndarray
    if dtype.name in ('datetime64', 'timedelta64'):
        msg = f"The '{dtype.name}' dtype has no unit. Please pass in '{dtype.name}[ns]' instead."
        raise ValueError(msg)
    if copy or object in (arr.dtype, dtype):
        return arr.astype(dtype, copy=True)
    return arr.astype(dtype, copy=copy)

def astype_float_to_int_nansafe(values: np.ndarray, dtype: np.dtype, copy: bool) -> np.ndarray:
    if not np.isfinite(values).all():
        raise IntCastingNaNError("Cannot convert non-finite values (NA or inf) to integer. Replace or remove non-finite values or cast to an integer type that supports these values (e.g. 'Int64')")
    if dtype.kind == 'u':
        if not (values >= 0).all():
            raise ValueError(f'Cannot losslessly cast from {values.dtype} to {dtype}')
    with warnings.catch_warnings():
        warnings.filterwarnings('ignore', category=RuntimeWarning)
        return values.astype(dtype, copy=copy)

def astype_array(values: ArrayLike, dtype: DtypeObj, copy: bool=False) -> ArrayLike:
    if values.dtype == dtype:
        if copy:
            return values.copy()
        return values
    if not isinstance(values, np.ndarray):
        values = values.astype(dtype, copy=copy)
    else:
        values = _astype_nansafe(values, dtype, copy=copy)
    if isinstance(dtype, np.dtype) and issubclass(values.dtype.type, str):
        values = np.array(values, dtype=object)
    return values

def astype_array_safe(values: ArrayLike, dtype: Dtype, copy: bool=False, errors: IgnoreRaise='raise') -> ArrayLike:
    errors_legal_values = ('raise', 'ignore')
    if errors not in errors_legal_values:
        invalid_arg = f"Expected value of kwarg 'errors' to be one of {list(errors_legal_values)}. Supplied value is '{errors}'"
        raise ValueError(invalid_arg)
    if inspect.isclass(dtype) and issubclass(dtype, ExtensionDtype):
        msg = f"Expected an instance of {dtype.__name__}, but got the class instead. Try instantiating 'dtype'."
        raise TypeError(msg)
    dtype = pandas_dtype(dtype)
    if isinstance(dtype, NumpyEADtype):
        dtype = dtype.numpy_dtype
    try:
        new_values = astype_array(values, dtype, copy=copy)
    except (ValueError, TypeError):
        if errors == 'ignore':
            new_values = values
        else:
            raise
    return new_values

def astype_is_view(dtype: DtypeObj, new_dtype: DtypeObj) -> bool:
    if dtype.kind in 'iufb' and dtype.kind == new_dtype.kind:
        if hasattr(dtype, 'itemsize') and hasattr(new_dtype, 'itemsize'):
            return dtype.itemsize == new_dtype.itemsize
    if isinstance(dtype, np.dtype) and (not isinstance(new_dtype, np.dtype)):
        new_dtype, dtype = (dtype, new_dtype)
    if dtype == new_dtype:
        return True
    elif isinstance(dtype, np.dtype) and isinstance(new_dtype, np.dtype):
        if is_object_dtype(dtype) and is_string_dtype(new_dtype):
            return True
        return False
    elif is_string_dtype(dtype) and is_string_dtype(new_dtype):
        from pandas.core.arrays.string_ import StringDtype
        if isinstance(dtype, StringDtype) and dtype.storage == 'pyarrow' and (new_dtype == 'object'):
            return False
        return True
    elif is_object_dtype(dtype) and new_dtype.kind == 'O':
        return True
    elif dtype.kind in 'mM' and new_dtype.kind in 'mM':
        dtype = getattr(dtype, 'numpy_dtype', dtype)
        new_dtype = getattr(new_dtype, 'numpy_dtype', new_dtype)
        return getattr(dtype, 'unit', None) == getattr(new_dtype, 'unit', None)
    elif new_dtype == object and isinstance(dtype, (DatetimeTZDtype, PeriodDtype, IntervalDtype)):
        return False
    elif isinstance(dtype, CategoricalDtype) and (not isinstance(new_dtype, CategoricalDtype)):
        return False
    numpy_dtype = getattr(dtype, 'numpy_dtype', None)
    new_numpy_dtype = getattr(new_dtype, 'numpy_dtype', None)
    if numpy_dtype is None and isinstance(dtype, np.dtype):
        numpy_dtype = dtype
    if new_numpy_dtype is None and isinstance(new_dtype, np.dtype):
        new_numpy_dtype = new_dtype
    if numpy_dtype is not None and new_numpy_dtype is not None:
        return numpy_dtype == new_numpy_dtype
    return True

