def aggregate(self, func=None, *args, engine=None, engine_kwargs=None, **kwargs) -> DataFrame:
    relabeling, func, columns, order = reconstruct_func(func, **kwargs)
    func = maybe_mangle_lambdas(func)
    if maybe_use_numba(engine):
        kwargs['engine'] = engine
        kwargs['engine_kwargs'] = engine_kwargs
    op = GroupByApply(self, func, args=args, kwargs=kwargs)
    result = op.agg()
    if not is_dict_like(func) and result is not None:
        if not self.as_index and is_list_like(func):
            return result.reset_index()
        else:
            return cast('DataFrame', result)
    elif relabeling:
        result = cast('DataFrame', result)
        result = result.iloc[:, order]
        result = cast('DataFrame', result)
        result.columns = columns
    if result is None:
        if 'engine' in kwargs:
            del kwargs['engine']
            del kwargs['engine_kwargs']
        if maybe_use_numba(engine):
            return self._aggregate_with_numba(func, *args, engine_kwargs=engine_kwargs, **kwargs)
        result = self._python_agg_general(func, *args, **kwargs)
    if not self.as_index:
        result = self._insert_inaxis_grouper(result)
        result.index = default_index(len(result))
    return cast('DataFrame', result)

def transform(self, func=None, *args, engine=None, engine_kwargs=None, **kwargs):
    if func is None:
        return self._transform_multiple_funcs(kwargs, *args, engine=engine, engine_kwargs=engine_kwargs)
    elif is_dict_like(func):
        for val in func.values():
            if is_list_like(val):
                raise NotImplementedError('Passing a dict of lists to DataFrameGroupBy.transform is not yet supported and is intended to be implemented in a future release. See https://github.com/pandas-dev/pandas/issues/58318')
        return self._transform_multiple_funcs(func, *args, engine=engine, engine_kwargs=engine_kwargs, **kwargs)
    elif is_list_like(func):
        func = maybe_mangle_lambdas(func)
        return self._transform_multiple_funcs(func, *args, engine=engine, engine_kwargs=engine_kwargs, **kwargs)
    else:
        return self._transform(func, *args, engine=engine, engine_kwargs=engine_kwargs, **kwargs)

def _transform_multiple_funcs(self, func: list | dict, *args, engine: str | None=None, engine_kwargs: dict | None=None, **kwargs) -> DataFrame:
    from pandas.core.reshape.concat import concat
    if is_dict_like(func):
        func = cast('dict', func)
        results: list[Series] = []
        for name, agg in func.items():
            if isinstance(agg, NamedAgg):
                column_name = agg.column
                agg_func = agg.aggfunc
            elif isinstance(agg, tuple) and len(agg) == 2:
                column_name = agg[0]
                agg_func = agg[1]
            else:
                column_name = name
                agg_func = agg
            result = self._transform_single_column(column_name, agg_func, *args, engine=engine, engine_kwargs=engine_kwargs, **kwargs)
            result.name = name
            results.append(result)
        return concat(results, axis=1)
    assert is_list_like(func)
    results_list: list[Series] = []
    col_order: list[tuple] = []
    for column in self._obj_with_exclusions.columns:
        for agg_func in func:
            col_result = self._transform_single_column(column, agg_func, *args, engine=engine, engine_kwargs=engine_kwargs, **kwargs)
            col_result.name = (column, agg_func)
            results_list.append(col_result)
            col_order.append((column, agg_func))
    output = concat(results_list, ignore_index=True, axis=1)
    arrays = [list(x) for x in zip(*col_order, strict=False)]
    output.columns = MultiIndex.from_arrays(arrays)
    return output

def _transform_single_column(self, column_name: Hashable, agg_func: Callable | str, *args, engine: str | None=None, engine_kwargs: dict | None=None, **kwargs) -> Series:
    data = self._gotitem(column_name, ndim=1)
    return data.transform(agg_func, *args, engine=engine, engine_kwargs=engine_kwargs, **kwargs)

def filter(self, func, dropna: bool=True, *args, **kwargs) -> DataFrame:
    indices = []
    obj = self._selected_obj
    gen = self._grouper.get_iterator(obj)
    for name, group in gen:
        object.__setattr__(group, 'name', name)
        res = func(group, *args, **kwargs)
        try:
            res = res.squeeze()
        except AttributeError:
            pass
        if is_bool(res) or (is_scalar(res) and isna(res)):
            if notna(res) and res:
                indices.append(self._get_index(name))
        else:
            raise TypeError(f'filter function returned a {type(res).__name__}, but expected a scalar bool')
    return self._apply_filter(indices, dropna)

def _gotitem(self, key, ndim: int, subset=None):
    if ndim == 2:
        if subset is None:
            subset = self.obj
        return DataFrameGroupBy(subset, self.keys, level=self.level, grouper=self._grouper, exclusions=self.exclusions, selection=key, as_index=self.as_index, sort=self.sort, group_keys=self.group_keys, observed=self.observed, dropna=self.dropna)
    elif ndim == 1:
        if subset is None:
            subset = self.obj[key]
        return SeriesGroupBy(subset, self.keys, level=self.level, grouper=self._grouper, exclusions=self.exclusions, selection=key, as_index=self.as_index, sort=self.sort, group_keys=self.group_keys, observed=self.observed, dropna=self.dropna)
    raise AssertionError('invalid ndim for _gotitem')

def take(self, indices: TakeIndexer, **kwargs) -> DataFrame:
    if kwargs:
        warnings.warn('Passing additional arguments to DataFrameGroupBy.take is deprecated and will be removed in a future version of pandas.', Pandas4Warning, stacklevel=find_stack_level())
    result = self._op_via_apply('take', indices=indices, **kwargs)
