def get_groupby(obj: NDFrame, by: _KeysArgType | None=None, grouper: ops.BaseGrouper | None=None, group_keys: bool=True) -> GroupBy:
    if isinstance(obj, Series):
        from pandas.core.groupby.generic import SeriesGroupBy
        return SeriesGroupBy(obj=obj, keys=by, grouper=grouper, group_keys=group_keys)
    elif isinstance(obj, DataFrame):
        from pandas.core.groupby.generic import DataFrameGroupBy
        return DataFrameGroupBy(obj=obj, keys=by, grouper=grouper, group_keys=group_keys)
    else:
        raise TypeError(f'invalid type: {obj}')

@final
@property
def groups(self) -> dict[Hashable, Index]:
    if isinstance(self.keys, list) and len(self.keys) == 1:
        warnings.warn(f"In a future version, the keys of `groups` will be a tuple with a single element, e.g. ({self.keys[0]},) , instead of a scalar, e.g. {self.keys[0]}, when grouping by a list with a single element. Use ``df.groupby(by='a').groups`` instead of ``df.groupby(by=['a']).groups`` to avoid this warning", Pandas4Warning, stacklevel=find_stack_level())
    return self._grouper.groups

@final
@property
def indices(self) -> dict[Hashable, npt.NDArray[np.intp]]:
    return self._grouper.indices

@final
def _get_index(self, name):

    def get_converter(s):
        if isinstance(s, datetime.datetime):
            return lambda key: Timestamp(key)
        elif isinstance(s, np.datetime64):
            return lambda key: Timestamp(key).asm8
        else:
            return lambda key: key
    if isna(name):
        return self.indices.get(np.nan, [])
    if isinstance(name, tuple):
        name = tuple((np.nan if isna(comp) else comp for comp in name))
    if len(self.indices) > 0:
        index_sample = next(iter(self.indices))
    else:
        index_sample = None
    if isinstance(index_sample, tuple):
        if not isinstance(name, tuple):
            msg = 'must supply a tuple to get_group with multiple grouping keys'
            raise ValueError(msg)
        if not len(name) == len(index_sample):
            try:
                return self.indices[name]
            except KeyError as err:
                msg = 'must supply a same-length tuple to get_group with multiple grouping keys'
                raise ValueError(msg) from err
        converters = (get_converter(s) for s in index_sample)
        name = tuple((f(n) for f, n in zip(converters, name, strict=True)))
    else:
        converter = get_converter(index_sample)
        name = converter(name)
    return self.indices.get(name, [])

@final
def get_group(self, name) -> DataFrame | Series:
    keys = self.keys
    level = self.level
    if is_list_like(level) and len(level) == 1 or (is_list_like(keys) and len(keys) == 1):
        if isinstance(name, tuple) and len(name) == 1:
            name = name[0]
        else:
            raise KeyError(name)
    inds = self._get_index(name)
    if not len(inds):
        raise KeyError(name)
    return self._selected_obj.iloc[inds]

@final
def __iter__(self) -> Iterator[tuple[Hashable, NDFrameT]]:
    keys = self.keys
    level = self.level
    result = self._grouper.get_iterator(self._selected_obj)
    if is_list_like(level) and len(level) == 1 or (isinstance(keys, list) and len(keys) == 1):
        result = (((key,), group) for key, group in result)
    return result

@final
def _op_via_apply(self, name: str, *args, **kwargs):
    f = getattr(type(self._obj_with_exclusions), name)

    def curried(x):
        return f(x, *args, **kwargs)
    curried.__name__ = name
    if name in base.plotting_methods:
        return self._python_apply_plot(curried)
    is_transform = name in base.transformation_kernels
    result = self._python_apply_general(curried, self._obj_with_exclusions, is_transform=is_transform, not_indexed_same=not is_transform)
    if self._grouper.has_dropped_na and is_transform:
        result = self._set_result_index_ordered(result)
    return result

@final
def _wrap_aggregated_output(self, result: Series | DataFrame, qs: npt.NDArray[np.float64] | None=None):
    if not self.as_index:
        result = self._insert_inaxis_grouper(result, qs=qs)
        result = result._consolidate()
        result.index = default_index(len(result))
    else:
        index = self._grouper.result_index
        if qs is not None:
            index = _insert_quantile_level(index, qs)
        result.index = index
    return result

@final
def _transform_with_numba(self, func, *args, engine_kwargs=None, **kwargs):
    data = self._obj_with_exclusions
    index_sorting = self._grouper.result_ilocs
    df = data if data.ndim == 2 else data.to_frame()
    starts, ends, sorted_index, sorted_data = self._numba_prep(df)
    numba_.validate_udf(func)
    args, kwargs = prepare_function_arguments(func, args, kwargs, num_required_args=2)
    numba_transform_func = numba_.generate_numba_transform_func(func, **get_jit_arguments(engine_kwargs))
    result = numba_transform_func(sorted_data, sorted_index, starts, ends, len(df.columns), *args)
    result = result.take(np.argsort(index_sorting), axis=0)
    index = data.index
    if data.ndim == 1:
        result_kwargs = {'name': data.name}
        result = result.ravel()
    else:
        result_kwargs = {'columns': data.columns}
    return data._constructor(result, index=index, **result_kwargs)

@final
def _aggregate_with_numba(self, func, *args, engine_kwargs=None, **kwargs):
    data = self._obj_with_exclusions
    df = data if data.ndim == 2 else data.to_frame()
    starts, ends, sorted_index, sorted_data = self._numba_prep(df)
    numba_.validate_udf(func)
    args, kwargs = prepare_function_arguments(func, args, kwargs, num_required_args=2)
    numba_agg_func = numba_.generate_numba_agg_func(func, **get_jit_arguments(engine_kwargs))
    result = numba_agg_func(sorted_data, sorted_index, starts, ends, len(df.columns), *args)
    index = self._grouper.result_index
    if data.ndim == 1:
        result_kwargs = {'name': data.name}
        result = result.ravel()
    else:
        result_kwargs = {'columns': data.columns}
    res = data._constructor(result, index=index, **result_kwargs)
    if not self.as_index:
        res = self._insert_inaxis_grouper(res)
        res.index = default_index(len(res))
    return res

def apply(self, func, *args, include_groups: bool=False, **kwargs) -> NDFrameT:
    if include_groups:
        raise ValueError('include_groups=True is no longer allowed.')
    if isinstance(func, str):
        if hasattr(self, func):
            res = getattr(self, func)
            if callable(res):
                return res(*args, **kwargs)
            elif args or kwargs:
                raise ValueError(f'Cannot pass arguments to property {func}')
            return res
        else:
            raise TypeError(f"apply func should be callable, not '{func}'")
    elif args or kwargs:
        if callable(func):

            @wraps(func)
            def f(g):
                return func(g, *args, **kwargs)
        else:
            raise ValueError('func must be a callable if args or kwargs are supplied')
    else:
        f = func
    return self._python_apply_general(f, self._obj_with_exclusions)

@final
def _python_apply_general(self, f: Callable, data: DataFrame | Series, not_indexed_same: bool | None=None, is_transform: bool=False) -> NDFrameT:
    values, mutated = self._grouper.apply_groupwise(f, data)
    if not_indexed_same is None:
        not_indexed_same = mutated
    return self._wrap_applied_output(data, values, not_indexed_same, is_transform)

@final
def _python_apply_plot(self, f: Callable) -> NDFrameT:
    data = self._selected_obj
    values = []
    for key, group in self._grouper.get_iterator(data):
        if group.ndim == 1:
            group.name = key
        values.append(f(group))
    return self._wrap_applied_output(data, values, not_indexed_same=True)

def _agg_py_fallback(self, how: str, values: ArrayLike, ndim: int, alt: Callable) -> ArrayLike:
    assert alt is not None
    if values.ndim == 1:
        ser = Series(values, copy=False)
    else:
        df = DataFrame(values.T, dtype=values.dtype)
        assert df.shape[1] == 1
        ser = df.iloc[:, 0]
    try:
        res_values = self._grouper.agg_series(ser, alt, preserve_dtype=True)
    except Exception as err:
        msg = f'agg function failed [how->{how},dtype->{ser.dtype}]'
        raise type(err)(msg) from err
    dtype = ser.dtype
    if dtype == object:
        res_values = res_values.astype(object, copy=False)
    elif is_string_dtype(dtype):
        string_array_cls = dtype.construct_array_type()
        res_values = string_array_cls._from_sequence(res_values, dtype=dtype)
    return ensure_block_shape(res_values, ndim=ndim)

@final
def _wrap_transform_fast_result(self, result: NDFrameT) -> NDFrameT:
    obj = self._obj_with_exclusions
    ids = self._grouper.ids
    result = result.reindex(self._grouper.result_index, axis=0)
    if self.obj.ndim == 1:
        out = algorithms.take_nd(result._values, ids, allow_fill=self._grouper.has_dropped_na)
        output = obj._constructor(out, index=obj.index, name=obj.name)
    else:
        new_ax = result.index.take(ids)
        output = result._reindex_with_indexers({0: (new_ax, ids)}, allow_dups=True)
        output = output.set_axis(obj.index, axis=0)
    return output

@final
def _cumcount_array(self, ascending: bool=True) -> np.ndarray:
    ids = self._grouper.ids
    ngroups = self._grouper.ngroups
    sorter = get_group_index_sorter(ids, ngroups)
    ids, count = (ids[sorter], len(ids))
    if count == 0:
        return np.empty(0, dtype=np.int64)
    run = np.r_[True, ids[:-1] != ids[1:]]
    rep = np.diff(np.r_[np.nonzero(run)[0], count])
    out = (~run).cumsum()
    if ascending:
        out -= np.repeat(out[run], rep)
    else:
        out = np.repeat(out[np.r_[run[1:], True]], rep) - out
    if self._grouper.has_dropped_na:
        out = np.where(ids == -1, np.nan, out.astype(np.float64, copy=False))
    else:
        out = out.astype(np.int64, copy=False)
    rev = np.empty(count, dtype=np.intp)
    rev[sorter] = np.arange(count, dtype=np.intp)
    return out[rev]

