@final
def quantile(self, q: float | AnyArrayLike=0.5, interpolation: Literal['linear', 'lower', 'higher', 'nearest', 'midpoint']='linear', numeric_only: bool=False):
    mgr = self._get_data_to_aggregate(numeric_only=numeric_only, name='quantile')
    obj = self._wrap_agged_manager(mgr)
    splitter = self._grouper._get_splitter(obj)
    sdata = splitter._sorted_data
    starts, ends = lib.generate_slices(splitter._slabels, splitter.ngroups)
    if is_scalar(q):
        qs = np.array([q], dtype=np.float64)
        pass_qs: None | np.ndarray = None
    else:
        qs = np.asarray(q, dtype=np.float64)
        pass_qs = qs
    ids = self._grouper.ids
    ngroups = self._grouper.ngroups
    if self.dropna:
        ids = ids[ids >= 0]
    nqs = len(qs)
    func = partial(libgroupby.group_quantile, labels=ids, qs=qs, interpolation=interpolation, starts=starts, ends=ends)

    def blk_func(values: ArrayLike) -> ArrayLike:
        if isinstance(values, ExtensionArray):
            return values._groupby_quantile(qs=qs, interpolation=interpolation, ids=ids, ngroups=ngroups, starts=starts, ends=ends)
        if is_object_dtype(values.dtype):
            raise TypeError(f"dtype '{values.dtype}' does not support operation 'quantile'")
        if is_bool_dtype(values.dtype):
            raise TypeError('Cannot use quantile with bool dtype')
        mask = isna(values)
        inference: np.dtype | None = np.dtype(np.int64) if is_integer_dtype(values.dtype) else None
        vals = np.asarray(values)
        ncols = 1
        if vals.ndim == 2:
            ncols = vals.shape[0]
        out = np.empty((ncols, ngroups, nqs), dtype=np.float64)
        if vals.ndim == 1:
            func(out[0], values=vals, mask=mask, result_mask=None, is_datetimelike=False)
        else:
            for i in range(ncols):
                func(out[i], values=vals[i], mask=mask[i], result_mask=None, is_datetimelike=False)
        if vals.ndim == 1:
            out = out.ravel('K')
        else:
            out = out.reshape(ncols, ngroups * nqs)
        if inference is not None and interpolation not in {'linear', 'midpoint'}:
            out = out.astype(inference)
        return out
    res_mgr = sdata._mgr.grouped_reduce(blk_func)
    res = self._wrap_agged_manager(res_mgr)
    return self._wrap_aggregated_output(res, qs=pass_qs)

