@final
def sample(self, n: int | None=None, frac: float | None=None, replace: bool=False, weights: ListLike | None=None, random_state: RandomState | None=None):
    if self._selected_obj.empty:
        return self._selected_obj
    size = sample.process_sampling_size(n, frac, replace)
    if weights is not None:
        weights_arr = sample.preprocess_weights(self._selected_obj, weights, axis=0)
    random_state = com.random_state(random_state)
    group_iterator = self._grouper.get_iterator(self._selected_obj)
    sampled_indices = []
    for labels, obj in group_iterator:
        grp_indices = self.indices[labels]
        group_size = len(grp_indices)
        if size is not None:
            sample_size = size
        else:
            assert frac is not None
            sample_size = round(frac * group_size)
        grp_sample = sample.sample(group_size, size=sample_size, replace=replace, weights=None if weights is None else weights_arr[grp_indices], random_state=random_state)
        sampled_indices.append(grp_indices[grp_sample])
    concatenated_sampled_indices = np.concatenate(sampled_indices)
    return self._selected_obj.take(concatenated_sampled_indices, axis=0)

def _idxmax_idxmin(self, how: Literal['idxmax', 'idxmin'], ignore_unobserved: bool=False, skipna: bool=True, numeric_only: bool=False) -> NDFrameT:
    if not self.observed and any((ping._passed_categorical for ping in self._grouper.groupings)):
        expected_len = len(self._grouper.result_index)
        group_sizes = self._grouper.size()
        result_len = group_sizes[group_sizes > 0].shape[0]
        assert result_len <= expected_len
        has_unobserved = result_len < expected_len
        raise_err: bool | np.bool_ = not ignore_unobserved and has_unobserved
        data = self._obj_with_exclusions
        if raise_err and isinstance(data, DataFrame):
            if numeric_only:
                data = data._get_numeric_data()
            raise_err = len(data.columns) > 0
        if raise_err:
            raise ValueError(f"Can't get {how} of an empty group due to unobserved categories. Specify observed=True in groupby instead.")
    elif not skipna and self._obj_with_exclusions.isna().any(axis=None):
        raise ValueError(f'{how} with skipna=False encountered an NA value.')
    result = self._agg_general(numeric_only=numeric_only, min_count=1, alias=how, skipna=skipna)
    return result

def first(x: Series):
    arr = x.array[notna(x.array)]
    if not len(arr):
        return x.array.dtype.na_value
    return arr[0]

def last(x: Series):
    arr = x.array[notna(x.array)]
    if not len(arr):
        return x.array.dtype.na_value
    return arr[-1]

def get_grouper(obj: NDFrameT, key=None, level=None, sort: bool=True, observed: bool=True, validate: bool=True, dropna: bool=True) -> tuple[ops.BaseGrouper, frozenset[Hashable], NDFrameT]:
    group_axis = obj.index
    if level is not None:
        if isinstance(group_axis, MultiIndex):
            if is_list_like(level) and len(level) == 1:
                level = level[0]
            if key is None and is_scalar(level):
                key = group_axis.get_level_values(level)
                level = None
        else:
            if is_list_like(level):
                nlevels = len(level)
                if nlevels == 1:
                    level = level[0]
                elif nlevels == 0:
                    raise ValueError('No group keys passed!')
                else:
                    raise ValueError('multiple levels only valid with MultiIndex')
            if isinstance(level, str):
                if obj.index.name != level:
                    raise ValueError(f'level name {level} is not the name of the index')
            elif level > 0 or level < -1:
                raise ValueError('level > 0 or level < -1 only valid with MultiIndex')
            level = None
            key = group_axis
    if isinstance(key, Grouper):
        grouper, obj = key._get_grouper(obj, validate=False, observed=observed)
        if key.key is None:
            return (grouper, frozenset(), obj)
        else:
            return (grouper, frozenset({key.key}), obj)
    elif isinstance(key, ops.BaseGrouper):
        return (key, frozenset(), obj)
    if not isinstance(key, list):
        keys = [key]
        match_axis_length = False
    else:
        keys = key
        match_axis_length = len(keys) == len(group_axis)
    any_callable = any((callable(g) or isinstance(g, dict) for g in keys))
    any_groupers = any((isinstance(g, (Grouper, Grouping)) for g in keys))
    any_arraylike = any((isinstance(g, (list, tuple, Series, Index, np.ndarray)) for g in keys))
    if not any_callable and (not any_arraylike) and (not any_groupers) and match_axis_length and (level is None):
        if isinstance(obj, DataFrame):
            all_in_columns_index = all((g in obj.columns or g in obj.index.names for g in keys))
        else:
            assert isinstance(obj, Series)
            all_in_columns_index = all((g in obj.index.names for g in keys))
        if not all_in_columns_index:
            keys = [com.asarray_tuplesafe(keys)]
    if isinstance(level, (tuple, list)):
        if key is None:
            keys = [None] * len(level)
        levels = level
    else:
        levels = [level] * len(keys)
    groupings: list[Grouping] = []
    exclusions: set[Hashable] = set()

    def is_in_axis(key) -> bool:
        if not _is_label_like(key):
            if obj.ndim == 1:
                return False
            items = obj.axes[-1]
            try:
                items.get_loc(key)
            except (KeyError, TypeError, InvalidIndexError):
                return False
        return True

    def is_in_obj(gpr) -> bool:
        if not hasattr(gpr, 'name'):
            return False
        try:
            obj_gpr_column = obj[gpr.name]
        except (KeyError, IndexError, InvalidIndexError, OutOfBoundsDatetime):
            return False
        if isinstance(gpr, Series) and isinstance(obj_gpr_column, Series):
            return gpr._mgr.references_same_values(obj_gpr_column._mgr, 0)
        return False
    for gpr, level in zip(keys, levels, strict=True):
        if is_in_obj(gpr):
            in_axis = True
            exclusions.add(gpr.name)
        elif is_in_axis(gpr):
            if obj.ndim != 1 and gpr in obj:
                if validate:
                    obj._check_label_or_level_ambiguity(gpr, axis=0)
                in_axis, name, gpr = (True, gpr, obj[gpr])
                if gpr.ndim != 1:
                    raise ValueError(f"Grouper for '{name}' not 1-dimensional")
                exclusions.add(name)
            elif obj._is_level_reference(gpr, axis=0):
                in_axis, level, gpr = (False, gpr, None)
            else:
                raise KeyError(gpr)
        elif isinstance(gpr, Grouper) and gpr.key is not None:
            exclusions.add(gpr.key)
            in_axis = True
        else:
            in_axis = False
        ping = Grouping(group_axis, gpr, obj=obj, level=level, sort=sort, observed=observed, in_axis=in_axis, dropna=dropna) if not isinstance(gpr, Grouping) else gpr
        groupings.append(ping)
    if len(groupings) == 0 and len(obj):
        raise ValueError('No group keys passed!')
    if len(groupings) == 0:
        groupings.append(Grouping(default_index(0), np.array([], dtype=np.intp)))
    grouper = ops.BaseGrouper(group_axis, groupings, sort=sort, dropna=dropna)
    return (grouper, frozenset(exclusions), obj)

def _factorize_monotonic(grouping_vector, sort: bool) -> tuple | None:
    if isinstance(grouping_vector, (Series, Index)):
        dtype = grouping_vector.dtype
        if not isinstance(dtype, np.dtype) or dtype.kind not in 'iufmMb':
            return None
        ascending = grouping_vector.is_monotonic_increasing
        if not ascending and (not grouping_vector.is_monotonic_decreasing):
            return None
        arr = np.asarray(grouping_vector)
    elif isinstance(grouping_vector, np.ndarray):
        arr = grouping_vector
        if arr.dtype.kind not in 'iufmMb':
            return None
        if len(arr) <= 1:
            return None
        sample_idx = np.linspace(0, len(arr) - 1, num=min(8, len(arr)), dtype=np.intp)
        sample = arr[sample_idx]
        if not bool(np.all(sample[1:] >= sample[:-1])):
            if not bool(np.all(sample[1:] <= sample[:-1])):
                return None
        ascending = bool(np.all(arr[1:] >= arr[:-1]))
        if not ascending:
            if not bool(np.all(arr[1:] <= arr[:-1])):
                return None
    else:
        return None
    n = len(arr)
    if n <= 1:
        return None
    transitions = np.empty(n, dtype=bool)
    transitions[0] = True
    transitions[1:] = arr[1:] != arr[:-1]
    group_starts = np.flatnonzero(transitions)
    uniques = arr[group_starts]
    ngroups = len(group_starts)
    run_lengths = np.diff(group_starts, append=n)
    codes = np.repeat(np.arange(ngroups, dtype=np.intp), run_lengths)
    if sort and (not ascending):
        uniques = uniques[::-1].copy()
        codes = ensure_platform_int(ngroups - 1 - codes)
    return (codes, uniques)

def _get_grouper(self, obj: NDFrameT, validate: bool=True, observed: bool=True) -> tuple[ops.BaseGrouper, NDFrameT]:
    obj, _, _ = self._set_grouper(obj)
    grouper, _, obj = get_grouper(obj, [self.key], level=self.level, sort=self.sort, validate=validate, dropna=self.dropna, observed=observed)
    return (grouper, obj)

def _set_grouper(self, obj: NDFrameT, sort: bool=False, *, gpr_index: Index | None=None) -> tuple[NDFrameT, Index, npt.NDArray[np.intp] | None]:
    assert obj is not None
    if self.key is not None and self.level is not None:
        raise ValueError('The Grouper cannot specify both a key and a level!')
    if self._grouper is None:
        self._grouper = gpr_index
        self._indexer = self._indexer_deprecated
    if self.key is not None:
        key = self.key
        if getattr(gpr_index, 'name', None) == key and isinstance(obj, Series):
            assert self._grouper is not None
            if self._indexer is not None:
                reverse_indexer = self._indexer.argsort()
                unsorted_ax = self._grouper.take(reverse_indexer)
                ax = unsorted_ax.take(obj.index)
            else:
                ax = self._grouper.take(obj.index)
        else:
            if key not in obj._info_axis:
                raise KeyError(f'The grouper name {key} is not found')
            ax = Index(obj[key], name=key)
    else:
        ax = obj.index
        if self.level is not None:
            level = self.level
            if isinstance(ax, MultiIndex):
                level = ax._get_level_number(level)
                ax = Index(ax._get_level_values(level), name=ax.names[level])
            elif level not in (0, ax.name):
                raise ValueError(f'The level {level} is not valid')
    indexer: npt.NDArray[np.intp] | None = None
    if (self.sort or sort) and (not ax.is_monotonic_increasing):
        indexer = self._indexer_deprecated = ax.array.argsort(kind='mergesort', na_position='first')
        ax = ax.take(indexer)
        obj = obj.take(indexer, axis=0)
    return (obj, ax, indexer)

@cache_readonly
def _ilevel(self) -> int | None:
    level = self.level
    if level is None:
        return None
    if not isinstance(level, int):
        index = self._index
        if level not in index.names:
            raise AssertionError(f'Level {level} not in index')
        if isinstance(index, MultiIndex) and index.names.count(level) > 1:
            warnings.warn(f"Grouping by index level '{level}' which matches multiple index levels is ambiguous. Currently the first matching level is used. In a future version of pandas, this will raise a ValueError. Use the level number instead.", Pandas4Warning, stacklevel=find_stack_level())
        return index.names.index(level)
    return level

@cache_readonly
def _positional_selector(self) -> GroupByPositionalSelector:
    if TYPE_CHECKING:
        groupby_self = cast('groupby.GroupBy', self)
    else:
        groupby_self = self
    return GroupByPositionalSelector(groupby_self)

def __getitem__(self, arg: PositionalIndexer | tuple) -> DataFrame | Series:
    mask = self.groupby_object._make_mask_from_positional_indexer(arg)
    return self.groupby_object._mask_selected_obj(mask)

def validate_udf(func: Callable) -> None:
    if not callable(func):
        raise NotImplementedError('Numba engine can only be used with a single function.')
    udf_signature = list(inspect.signature(func).parameters.keys())
    expected_args = ['values', 'index']
    min_number_args = len(expected_args)
    if len(udf_signature) < min_number_args or udf_signature[:min_number_args] != expected_args:
        raise NumbaUtilError(f'The first {min_number_args} arguments to {func.__name__} must be {expected_args}')

@functools.cache
def generate_numba_agg_func(func: Callable[..., Scalar], nogil: bool, parallel: bool) -> Callable[[np.ndarray, np.ndarray, np.ndarray, np.ndarray, int, Any], np.ndarray]:
    numba_func = jit_user_function(func)
    if TYPE_CHECKING:
        import numba
    else:
        numba = import_optional_dependency('numba')

    @numba.jit(nogil=nogil, parallel=parallel)
    def group_agg(values: np.ndarray, index: np.ndarray, begin: np.ndarray, end: np.ndarray, num_columns: int, *args: Any) -> np.ndarray:
        assert len(begin) == len(end)
        num_groups = len(begin)
        result = np.empty((num_groups, num_columns))
        for i in numba.prange(num_groups):
            group_index = index[begin[i]:end[i]]
            for j in numba.prange(num_columns):
                group = values[begin[i]:end[i], j]
                result[i, j] = numba_func(group, group_index, *args)
        return result
    return group_agg

@functools.cache
def generate_numba_transform_func(func: Callable[..., np.ndarray], nogil: bool, parallel: bool) -> Callable[[np.ndarray, np.ndarray, np.ndarray, np.ndarray, int, Any], np.ndarray]:
    numba_func = jit_user_function(func)
    if TYPE_CHECKING:
        import numba
    else:
        numba = import_optional_dependency('numba')

    @numba.jit(nogil=nogil, parallel=parallel)
    def group_transform(values: np.ndarray, index: np.ndarray, begin: np.ndarray, end: np.ndarray, num_columns: int, *args: Any) -> np.ndarray:
        assert len(begin) == len(end)
        num_groups = len(begin)
        result = np.empty((len(values), num_columns))
        for i in numba.prange(num_groups):
            group_index = index[begin[i]:end[i]]
            for j in numba.prange(num_columns):
                group = values[begin[i]:end[i], j]
                result[begin[i]:end[i], j] = numba_func(group, group_index, *args)
        return result
    return group_transform

def extract_result(res):
    if hasattr(res, '_values'):
        res = res._values
        if res.ndim == 1 and len(res) == 1:
            warnings.warn('Converting a Series or array of length 1 into a scalar is deprecated and will be removed in a future version. If you wish to preserve the current behavior, have ``func`` return scalars.', category=Pandas4Warning, stacklevel=find_stack_level())
            res = res[0]
    return res

def _get_cython_vals(self, values: np.ndarray, uses_mask: bool=False) -> np.ndarray:
    how = self.how
    if how in ['median', 'std', 'sem', 'skew', 'kurt']:
        values = ensure_float64(values)
    elif values.dtype.kind in 'iu':
        if how in ['var', 'mean'] or (self.kind == 'transform' and self.has_dropped_na and (not uses_mask)):
            values = ensure_float64(values)
        elif how in ['sum', 'ohlc', 'prod', 'cumsum', 'cumprod']:
            if values.dtype.kind == 'i':
                values = ensure_int64(values)
            else:
                values = ensure_uint64(values)
    return values

def _get_result_dtype(self, dtype: np.dtype) -> np.dtype:
    how = self.how
    if how in ['sum', 'cumsum', 'sum', 'prod', 'cumprod']:
        if dtype == np.dtype(bool):
            return np.dtype(np.int64)
    elif how in ['mean', 'median', 'var', 'std', 'sem']:
        if dtype.kind in 'fc':
            return dtype
        elif dtype.kind in 'iub':
            return np.dtype(np.float64)
    return dtype

@final
def cython_operation(self, *, values: ArrayLike, axis: AxisInt, min_count: int=-1, comp_ids: np.ndarray, ngroups: int, **kwargs) -> ArrayLike:
    self._validate_axis(axis, values)
    if not isinstance(values, np.ndarray):
        return values._groupby_op(how=self.how, has_dropped_na=self.has_dropped_na, min_count=min_count, ngroups=ngroups, ids=comp_ids, **kwargs)
    return self._cython_op_ndim_compat(values, min_count=min_count, ngroups=ngroups, comp_ids=comp_ids, mask=None, **kwargs)

@final
def _get_splitter(self, data: NDFrame) -> DataSplitter:
    if isinstance(data, Series):
        klass: type[DataSplitter] = SeriesSplitter
    else:
        klass = FrameSplitter
    return klass(data, self.ngroups, sorted_ids=self._sorted_ids, sort_idx=self.result_ilocs)

@cache_readonly
def indices(self) -> dict[Hashable, npt.NDArray[np.intp]]:
    if len(self.groupings) == 1 and isinstance(self.result_index, CategoricalIndex):
        result = self.groupings[0].indices
    else:
        codes_list = [ping.codes for ping in self.groupings]
        result = get_indexer_dict(codes_list, self.levels)
    if not self.dropna:
        has_mi = isinstance(self.result_index, MultiIndex)
        if not has_mi and self.result_index.hasnans:
            result = {np.nan if isna(key) else key: value for key, value in result.items()}
        elif has_mi:
            result = {tuple((np.nan if isna(comp) else comp for comp in key)): value for key, value in result.items()}
    return result

@final
@cache_readonly
def result_ilocs(self) -> npt.NDArray[np.intp]:
    ids = self.ids
    if self.has_dropped_na:
        mask = np.where(ids >= 0)
        null_gaps = np.cumsum(ids == -1)[mask]
        ids = ids[mask]
    result = get_group_index_sorter(ids, self.ngroups)
    if self.has_dropped_na:
        result += np.take(null_gaps, result)
    return result

@final
def size(self) -> Series:
    ids = self.ids
    ngroups = self.ngroups
    out: np.ndarray | list
    if ngroups:
        if self.has_dropped_na:
            out = np.bincount(ids + 1, minlength=ngroups + 1)[1:]
        else:
            out = np.bincount(ids, minlength=ngroups)
    else:
        out = []
    return Series(out, index=self.result_index, dtype='int64', copy=False)

@cache_readonly
def groups(self) -> dict[Hashable, Index]:
    if len(self.groupings) == 1:
        return self.groupings[0].groups
    result_index, ids = self.result_index_and_ids
    values = result_index._values
    categories = Categorical.from_codes(ids, categories=range(len(result_index)))
    result = {values[group]: self.axis.take(axis_ilocs) for group, axis_ilocs in categories._reverse_indexer().items()}
    return result

@final
@cache_readonly
def has_dropped_na(self) -> bool:
    return bool((self.ids < 0).any())

@final
@cache_readonly
def _reduceat_segment_info(self) -> tuple[int, npt.NDArray[np.intp], npt.NDArray[np.intp], np.ndarray] | None:
    comp_ids = self.ids
    if self.has_dropped_na:
        na_count = int((comp_ids < 0).sum())
        comp_ids = comp_ids[na_count:]
    else:
        na_count = 0
    if comp_ids.size == 0:
        return None
    group_starts = np.flatnonzero(np.r_[True, comp_ids[1:] != comp_ids[:-1]])
    segment_ids = comp_ids[group_starts]
    segment_sizes = np.diff(group_starts, append=comp_ids.size)
    return (na_count, group_starts, segment_ids, segment_sizes)

@final
def _cython_operation(self, kind: str, values, how: str, axis: AxisInt, min_count: int=-1, **kwargs) -> ArrayLike:
    assert kind in ['transform', 'aggregate']
    if kind == 'aggregate' and how in _REDUCEAT_UFUNCS and isinstance(values, np.ndarray) and (values.dtype.kind in 'iufb') and self.is_monotonic:
        result = self._reduceat_aggregate(values, how, axis, min_count)
        if result is not None:
            return result
    cy_op = WrappedCythonOp(kind=kind, how=how, has_dropped_na=self.has_dropped_na)
    return cy_op.cython_operation(values=values, axis=axis, min_count=min_count, comp_ids=self.ids, ngroups=self.ngroups, **kwargs)

@final
def _reduceat_aggregate(self, values: np.ndarray, how: str, axis: AxisInt, min_count: int) -> np.ndarray | None:
    info = self._reduceat_segment_info
    if info is None:
        return None
    na_count, group_starts, segment_ids, segment_sizes = info
    ngroups = self.ngroups
    orig_dtype = values.dtype
    if orig_dtype.kind == 'f' and np.isnan(values).any():
        return None
    if na_count > 0:
        if axis == 0:
            values = values[na_count:]
        else:
            values = values[:, na_count:]
    work_dtype: np.dtype
    if how == 'mean':
        work_dtype = np.dtype(np.float64)
    elif how in ('sum', 'prod') and orig_dtype.kind in 'ib':
        work_dtype = np.dtype(np.int64)
    elif how in ('sum', 'prod') and orig_dtype.kind == 'u':
        work_dtype = np.dtype(np.uint64)
    else:
        work_dtype = orig_dtype
    work_values = values.astype(work_dtype, copy=False)
    ufunc = _REDUCEAT_UFUNCS[how]
    seg = ufunc.reduceat(work_values, group_starts, axis=axis)
    if how == 'mean':
        sizes = segment_sizes.astype(np.float64)
        if seg.ndim == 1:
            seg = seg / sizes
        else:
            shape = [1] * seg.ndim
            shape[axis] = len(sizes)
            seg = seg / sizes.reshape(shape)
    res_dtype: np.dtype
    if how == 'mean':
        res_dtype = np.dtype(np.float64)
    elif how in ('sum', 'prod') and orig_dtype.kind == 'b':
        res_dtype = np.dtype(np.int64)
    else:
        res_dtype = orig_dtype
    out_shape = list(values.shape)
    out_shape[axis] = ngroups
    if how == 'sum':
        result = np.zeros(out_shape, dtype=work_dtype)
    elif how == 'prod':
        result = np.ones(out_shape, dtype=work_dtype)
    elif work_dtype.kind == 'f':
        result = np.full(out_shape, np.nan, dtype=work_dtype)
    elif work_dtype.kind == 'b':
        result = np.full(out_shape, how == 'min', dtype=work_dtype)
    else:
        iinfo = np.iinfo(work_dtype)
        fill = iinfo.max if how == 'min' else iinfo.min
        result = np.full(out_shape, fill, dtype=work_dtype)
    indexer: list[Any] = [slice(None)] * len(out_shape)
    indexer[axis] = segment_ids
    result[tuple(indexer)] = seg
    if how in ('sum', 'prod'):
        cutoff = max(0, min_count)
    else:
        cutoff = max(1, min_count)
    if cutoff > 0:
        group_counts = np.zeros(ngroups, dtype=np.int64)
        group_counts[segment_ids] = segment_sizes
        empty_mask = group_counts < cutoff
        if empty_mask.any():
            if result.dtype.kind in 'iub':
                result = result.astype(np.float64)
            indexer2: list[Any] = [slice(None)] * result.ndim
            indexer2[axis] = empty_mask
            result[tuple(indexer2)] = np.nan
    result = maybe_downcast_to_dtype(result, res_dtype)
    return result

@final
def agg_series(self, obj: Series, func: Callable, preserve_dtype: bool=False) -> ArrayLike:
    result = self._aggregate_series_pure_python(obj, func)
    return obj.array._cast_pointwise_result(result)

@cache_readonly
def groups(self):
    result = {key: value for key, value in zip(self.binlabels, self.bins, strict=True) if key is not NaT}
    return result

def get_iterator(self, data: NDFrame):
    slicer = lambda start, edge: data.iloc[start:edge]
    start: np.int64 | int = 0
    for edge, label in zip(self.bins, self.binlabels, strict=True):
        if label is not NaT:
            yield (label, slicer(start, edge))
        start = edge
    if start < len(data):
        yield (self.binlabels[-1], slicer(start, None))

def get_window_bounds(self, num_values: int=0, min_periods: int | None=None, center: bool | None=None, closed: str | None=None, step: int | None=None) -> tuple[np.ndarray, np.ndarray]:
    if center or self.window_size == 0:
        offset = (self.window_size - 1) // 2
    else:
        offset = 0
    end = np.arange(1 + offset, num_values + 1 + offset, step, dtype='int64')
    start = end - self.window_size
    if closed in ['left', 'both']:
        start -= 1
    if closed in ['left', 'neither']:
        end -= 1
    end = np.clip(end, 0, num_values)
    start = np.clip(start, 0, num_values)
    return (start, end)

def get_window_bounds(self, num_values: int=0, min_periods: int | None=None, center: bool | None=None, closed: str | None=None, step: int | None=None) -> tuple[np.ndarray, np.ndarray]:
    assert self.index_array is not None
    if (index_length := len(self.index_array)) < num_values:
        raise ValueError(f"Variable rolling window requires the index to be at least as long as the 'other' index. Got {index_length} < {num_values}. Please align 'other' to the rolling object's index using reindex_like() or similar method.")
    return calculate_variable_window_bounds(num_values, self.window_size, min_periods, center, closed, self.index_array)

def get_window_bounds(self, num_values: int=0, min_periods: int | None=None, center: bool | None=None, closed: str | None=None, step: int | None=None) -> tuple[np.ndarray, np.ndarray]:
    if step is not None:
        raise NotImplementedError('step not implemented for variable offset window')
    if num_values <= 0:
        return (np.empty(0, dtype='int64'), np.empty(0, dtype='int64'))
    if closed is None:
        closed = 'right' if self.index is not None else 'both'
    right_closed = closed in ['right', 'both']
    left_closed = closed in ['left', 'both']
    if self.index[num_values - 1] < self.index[0]:
        index_growth_sign = -1
    else:
        index_growth_sign = 1
    offset_diff = index_growth_sign * self.offset
    start = np.empty(num_values, dtype='int64')
    start.fill(-1)
    end = np.empty(num_values, dtype='int64')
    end.fill(-1)
    start[0] = 0
    if right_closed:
        end[0] = 1
    else:
        end[0] = 0
    zero = timedelta(0)
    for i in range(1, num_values):
        end_bound = self.index[i]
        start_bound = end_bound - offset_diff
        if left_closed:
            start_bound -= Nano(1)
        start[i] = i
        for j in range(start[i - 1], i):
            start_diff = (self.index[j] - start_bound) * index_growth_sign
            if start_diff > zero:
                start[i] = j
                break
        end_diff = (self.index[end[i - 1]] - end_bound) * index_growth_sign
        if end_diff == zero and (not right_closed):
            end[i] = end[i - 1] + 1
        elif end_diff <= zero:
            end[i] = i + 1
        else:
            end[i] = end[i - 1]
        if not right_closed:
            end[i] -= 1
    return (start, end)

def get_window_bounds(self, num_values: int=0, min_periods: int | None=None, center: bool | None=None, closed: str | None=None, step: int | None=None) -> tuple[np.ndarray, np.ndarray]:
    if center:
        raise ValueError("Forward-looking windows can't have center=True")
    if closed is not None:
        raise ValueError("Forward-looking windows don't support setting the closed argument")
    if step is None:
        step = 1
    start = np.arange(0, num_values, step, dtype='int64')
    end = start + self.window_size
    if self.window_size:
        end = np.clip(end, 0, num_values)
    return (start, end)

def __init__(self, index_array: np.ndarray | None=None, window_size: int | BaseIndexer=0, groupby_indices: dict | None=None, window_indexer: type[BaseIndexer]=BaseIndexer, indexer_kwargs: dict | None=None, **kwargs) -> None:
    self.groupby_indices = groupby_indices or {}
    self.window_indexer = window_indexer
    self.indexer_kwargs = indexer_kwargs.copy() if indexer_kwargs else {}
    super().__init__(index_array=index_array, window_size=self.indexer_kwargs.pop('window_size', window_size), **kwargs)

def get_window_bounds(self, num_values: int=0, min_periods: int | None=None, center: bool | None=None, closed: str | None=None, step: int | None=None) -> tuple[np.ndarray, np.ndarray]:
    start_arrays = []
    end_arrays = []
    window_indices_start = 0
    for indices in self.groupby_indices.values():
        index_array: np.ndarray | None
        if self.index_array is not None:
            index_array = self.index_array.take(ensure_platform_int(indices))
        else:
            index_array = self.index_array
        indexer = self.window_indexer(index_array=index_array, window_size=self.window_size, **self.indexer_kwargs)
        start, end = indexer.get_window_bounds(len(indices), min_periods, center, closed, step)
        start = start.astype(np.int64)
        end = end.astype(np.int64)
        assert len(start) == len(end), 'these should be equal in length from get_window_bounds'
        window_indices = np.arange(window_indices_start, window_indices_start + len(indices))
        window_indices_start += len(indices)
        window_indices = np.append(window_indices, [window_indices[-1] + 1]).astype(np.int64, copy=False)
        start_arrays.append(window_indices.take(ensure_platform_int(start)))
        end_arrays.append(window_indices.take(ensure_platform_int(end)))
    if len(start_arrays) == 0:
        return (np.array([], dtype=np.int64), np.array([], dtype=np.int64))
    start = np.concatenate(start_arrays)
    end = np.concatenate(end_arrays)
    return (start, end)

def is_scalar_indexer(indexer, ndim: int) -> bool:
    if ndim == 1 and is_integer(indexer):
        return True
    if isinstance(indexer, tuple) and len(indexer) == ndim:
        return all((is_integer(x) for x in indexer))
    return False

def is_empty_indexer(indexer) -> bool:
    if is_list_like(indexer) and (not len(indexer)):
        return True
    if not isinstance(indexer, tuple):
        indexer = (indexer,)
    return any((isinstance(idx, np.ndarray) and len(idx) == 0 for idx in indexer))

def check_setitem_lengths(indexer, value, values) -> bool:
    no_op = False
    if isinstance(indexer, (np.ndarray, list)):
        if is_list_like(value):
            if len(indexer) != len(value) and values.ndim == 1:
                if isinstance(indexer, list):
                    indexer = np.array(indexer)
                if not (isinstance(indexer, np.ndarray) and indexer.dtype == np.bool_ and (indexer.sum() == len(value))):
                    raise ValueError('cannot set using a list-like indexer with a different length than the value')
            if not len(indexer):
                no_op = True
    elif isinstance(indexer, slice):
        if is_list_like(value):
            if len(value) != length_of_indexer(indexer, values) and values.ndim == 1:
                raise ValueError('cannot set using a slice indexer with a different length than the value')
            if not len(value):
                no_op = True
    return no_op

def validate_indices(indices: np.ndarray, n: int) -> None:
    if len(indices):
        min_idx = indices.min()
        if min_idx < -1:
            msg = f"'indices' contains values less than allowed ({min_idx} < -1)"
            raise ValueError(msg)
        max_idx = indices.max()
        if max_idx >= n:
            raise IndexError('indices are out-of-bounds')

def maybe_convert_indices(indices, n: int, verify: bool=True) -> np.ndarray:
    if isinstance(indices, list):
        indices = np.array(indices)
        if len(indices) == 0:
            return np.empty(0, dtype=np.intp)
    mask = indices < 0
    if mask.any():
        indices = indices.copy()
        indices[mask] += n
    if verify:
        mask = (indices >= n) | (indices < 0)
        if mask.any():
            raise IndexError('indices are out-of-bounds')
    return indices

def length_of_indexer(indexer, target=None) -> int:
    if target is not None and isinstance(indexer, slice):
        target_len = len(target)
        start, stop, step = indexer.indices(target_len)
        return len(range(start, stop, step))
    elif isinstance(indexer, (ABCSeries, ABCIndex, np.ndarray, list)):
        if isinstance(indexer, list):
            indexer = np.array(indexer)
        if indexer.dtype == bool:
            return indexer.sum()
        return len(indexer)
    elif isinstance(indexer, range):
        try:
            return len(indexer)
        except OverflowError:
            step = indexer.step
            if step > 0:
                low, high = (indexer.start, indexer.stop)
            else:
                low, high = (indexer.stop, indexer.start)
                step = -step
            if low >= high:
                return 0
            return (high - low - 1) // step + 1
    elif not is_list_like_indexer(indexer):
        return 1
    raise AssertionError('cannot find the length of the indexer')

def disallow_ndim_indexing(result) -> None:
    if np.ndim(result) > 1:
        raise ValueError('Multi-dimensional indexing (e.g. `obj[:, None]`) is no longer supported. Convert to a numpy array before indexing instead.')

def unpack_1tuple(tup):
    if len(tup) == 1 and isinstance(tup[0], slice):
        if isinstance(tup, list):
            raise ValueError('Indexing with a single-item list containing a slice is not allowed. Pass a tuple instead.')
        return tup[0]
    return tup

def check_key_length(columns: Index, key, value: DataFrame) -> None:
    if columns.is_unique:
        if len(value.columns) != len(key):
            raise ValueError('Columns must be same length as key')
    elif len(columns.get_indexer_non_unique(key)[0]) != len(value.columns):
        raise ValueError('Columns must be same length as key')

def unpack_tuple_and_ellipses(item: tuple):
    if len(item) > 1:
        if item[0] is Ellipsis:
            item = item[1:]
        elif item[-1] is Ellipsis:
            item = item[:-1]
    if len(item) > 1:
        raise IndexError('too many indices for array.')
    item = item[0]
    return item

def getitem_returns_view(arr, key) -> bool:
    if not isinstance(key, tuple):
        key = (key,)
    key = tuple((k for k in key if k is not Ellipsis and k is not np.newaxis))
    if not key:
        return True
    if arr.ndim == 2 and lib.is_integer(key[0]):
        return True
    if all((isinstance(k, slice) for k in key)):
        return True
    return False

@set_module('pandas.api.indexers')
def check_array_indexer(array: AnyArrayLike, indexer: Any) -> Any:
    from pandas.core.construction import array as pd_array
    if is_list_like(indexer):
        if isinstance(indexer, tuple):
            return indexer
    else:
        return indexer
    if not is_array_like(indexer):
        indexer = pd_array(indexer)
        if len(indexer) == 0:
            indexer = np.array([], dtype=np.intp)
    dtype = indexer.dtype
    if is_bool_dtype(dtype):
        if isinstance(dtype, ExtensionDtype):
            indexer = indexer.to_numpy(dtype=bool, na_value=False)
        else:
            indexer = np.asarray(indexer, dtype=bool)
        if len(indexer) != len(array):
            raise IndexError(f'Boolean index has wrong length: {len(indexer)} instead of {len(array)}')
    elif is_integer_dtype(dtype):
        try:
            indexer = np.asarray(indexer, dtype=np.intp)
        except ValueError as err:
            raise ValueError('Cannot index with an integer indexer containing NA values') from err
    else:
        raise IndexError('arrays used as indices must be of integer or boolean type')
    return indexer

def to_pydatetime(self) -> Series:
    from pandas import Series
    return Series(self._get_values().to_pydatetime(), dtype=object)

@property
def freq(self):
    return self._get_values()._inferred_freq_str

def to_pytimedelta(self) -> np.ndarray:
    warnings.warn(f'The behavior of {type(self).__name__}.to_pytimedelta is deprecated, in a future version this will return a Series containing python datetime.timedelta objects instead of an ndarray. To retain the old behavior, call `np.array` on the result', Pandas4Warning, stacklevel=find_stack_level())
    return self._get_values().to_pytimedelta()

@property
def components(self) -> DataFrame:
    return self._get_values().components.set_index(self._parent.index).__finalize__(self._parent)

def get_objs_combined_axis(objs, intersect: bool=False, axis: Axis=0, sort: bool | lib.NoDefault=True) -> Index:
    obs_idxes = [obj._get_axis(axis) for obj in objs]
    return _get_combined_index(obs_idxes, intersect=intersect, sort=sort)

def _get_distinct_objs(objs: list[Index]) -> list[Index]:
    ids = set()
    res = []
    for obj in objs:
        if obj._id not in ids:
            ids.add(obj._id)
            res.append(obj)
    return res

def _get_combined_index(indexes: list[Index], intersect: bool=False, sort: bool | lib.NoDefault=False) -> Index:
    indexes = _get_distinct_objs(indexes)
    if len(indexes) == 0:
        index: Index = default_index(0)
    elif len(indexes) == 1:
        index = indexes[0]
    elif intersect:
        index = indexes[0]
        for other in indexes[1:]:
            index = index.intersection(other)
    else:
        index = union_indexes(indexes, sort=sort if sort is lib.no_default else False)
        index = ensure_index(index)
    if sort and sort is not lib.no_default:
        index = safe_sort_index(index)
    return index

def safe_sort_index(index: Index) -> Index:
    if index.is_monotonic_increasing:
        return index
    try:
        array_sorted = safe_sort(index)
    except TypeError:
        pass
    else:
        if isinstance(array_sorted, Index):
            return array_sorted
        array_sorted = cast('np.ndarray', array_sorted)
        if isinstance(index, MultiIndex):
            index = MultiIndex.from_tuples(array_sorted, names=index.names)
        else:
            index = Index(array_sorted, name=index.name, dtype=index.dtype)
    return index

def union_indexes(indexes, sort: bool | lib.NoDefault=True) -> Index:
    if len(indexes) == 0:
        raise AssertionError('Must have at least 1 Index to union')
    if len(indexes) == 1:
        result = indexes[0]
        if isinstance(result, list):
            if not sort or sort is lib.no_default:
                result = Index(result)
            else:
                result = Index(sorted(result))
        return result
    indexes, kind = _sanitize_and_check(indexes)
    if kind == 'special':
        result = indexes[0]
        num_dtis = 0
        num_dti_tzs = 0
        for idx in indexes:
            if isinstance(idx, DatetimeIndex):
                num_dtis += 1
                if idx.tz is not None:
                    num_dti_tzs += 1
        if num_dti_tzs not in [0, num_dtis]:
            raise TypeError('Cannot join tz-naive with tz-aware DatetimeIndex')
        if num_dtis == len(indexes):
            if sort is lib.no_default:
                sort = True
            result = indexes[0]
        elif num_dtis > 1:
            sort = False
            indexes = [x.astype(object, copy=False) for x in indexes]
            result = indexes[0]
        for other in indexes[1:]:
            result = result.union(other, sort=None if sort else False)
        return result
    elif kind == 'array':
        if not all_indexes_same(indexes):
            dtype = find_common_type([idx.dtype for idx in indexes])
            inds = [ind.astype(dtype, copy=False) for ind in indexes]
            index = inds[0].unique()
            other = inds[1].append(inds[2:])
            diff = other[index.get_indexer_for(other) == -1]
            if len(diff):
                index = index.append(diff.unique())
            if sort:
                index = index.sort_values()
        else:
            index = indexes[0]
        name = get_unanimous_names(*indexes)[0]
        if name != index.name:
            index = index.rename(name)
        return index
    elif kind == 'list':
        dtypes = [idx.dtype for idx in indexes if isinstance(idx, Index)]
        if dtypes:
            dtype = find_common_type(dtypes)
        else:
            dtype = None
        all_lists = (idx.tolist() if isinstance(idx, Index) else idx for idx in indexes)
        return Index(lib.fast_unique_multiple_list_gen(all_lists, sort=bool(sort)), dtype=dtype)
    else:
        raise ValueError(f"kind={kind!r} must be 'special', 'array' or 'list'.")

def _sanitize_and_check(indexes):
    kinds = {type(index) for index in indexes}
    if list in kinds:
        if len(kinds) > 1:
            indexes = [Index(list(x)) if not isinstance(x, Index) else x for x in indexes]
            kinds -= {list}
        else:
            return (indexes, 'list')
    if len(kinds) > 1 or Index not in kinds:
        return (indexes, 'special')
    else:
        return (indexes, 'array')

def all_indexes_same(indexes) -> bool:
    itr = iter(indexes)
    first = next(itr)
    return all((first.equals(index) for index in itr))

def _maybe_return_indexers(meth: F) -> F:

    @functools.wraps(meth)
    def join(self: Index, other: Index, *, how: JoinHow='left', level: Level | None=None, return_indexers: bool=False, sort: bool=False) -> Index | tuple[Index, npt.NDArray[np.intp] | None, npt.NDArray[np.intp] | None]:
        join_index, lidx, ridx = meth(self, other, how=how, level=level, sort=sort)
        if not return_indexers:
            return join_index
        if lidx is not None:
            lidx = ensure_platform_int(lidx)
        if ridx is not None:
            ridx = ensure_platform_int(ridx)
        return (join_index, lidx, ridx)
    return cast('F', join)

def _new_Index(cls: type[Index], d: dict) -> Index:
    d['copy'] = False
    if issubclass(cls, ABCPeriodIndex):
        from pandas.core.indexes.period import _new_PeriodIndex
        return _new_PeriodIndex(cls, **d)
    if issubclass(cls, ABCMultiIndex):
        if 'labels' in d and 'codes' not in d:
            d['codes'] = d.pop('labels')
        d['verify_integrity'] = False
    elif 'dtype' not in d and 'data' in d:
        d['dtype'] = d['data'].dtype
    return cls.__new__(cls, **d)

def maybe_sequence_to_range(sequence: Axes) -> Axes:
    if isinstance(sequence, (range, ExtensionArray)):
        return sequence
    elif len(sequence) == 1 or lib.infer_dtype(sequence, skipna=False) != 'integer':
        return sequence
    elif isinstance(sequence, (ABCSeries, Index)) and (not (isinstance(sequence.dtype, np.dtype) and sequence.dtype.kind == 'i')):
        return sequence
    if len(sequence) == 0:
        return range(0)
    try:
        np_sequence = np.asarray(sequence, dtype=np.int64)
    except OverflowError:
        return sequence
    diff = np_sequence[1] - np_sequence[0]
    if diff == 0:
        return sequence
    elif len(sequence) == 2 or lib.is_sequence_range(np_sequence, diff):
        return range(np_sequence[0], np_sequence[-1] + diff, diff)
    else:
        return sequence

def ensure_index_from_sequences(sequences: Sequence[Axes], names: Sequence[Hashable] | None=None) -> Index:
    from pandas.core.indexes.api import default_index
    from pandas.core.indexes.multi import MultiIndex
    if len(sequences) == 0:
        return default_index(0)
    elif len(sequences) == 1:
        if names is not None:
            names = names[0]
        return Index(maybe_sequence_to_range(sequences[0]), name=names)
    else:
        return MultiIndex.from_arrays(sequences, names=names)

def ensure_index(index_like: Axes, copy: bool=False) -> Index:
    if isinstance(index_like, Index):
        if copy:
            index_like = index_like.copy()
        return index_like
    if isinstance(index_like, ABCSeries):
        name = index_like.name
        return Index(index_like, name=name, copy=copy)
    if is_iterator(index_like):
        index_like = list(index_like)
    if isinstance(index_like, list):
        if type(index_like) is not list:
            index_like = list(index_like)
        if index_like and lib.is_all_arraylike(index_like):
            from pandas.core.indexes.multi import MultiIndex
            return MultiIndex.from_arrays(index_like)
        else:
            return Index(index_like, copy=copy, tupleize_cols=False)
    else:
        return Index(index_like, copy=copy)

def trim_front(strings: list[str]) -> list[str]:
    if not strings:
        return strings
    smallest_leading_space = min((len(x) - len(x.lstrip()) for x in strings))
    if smallest_leading_space > 0:
        strings = [x[smallest_leading_space:] for x in strings]
    return strings

def maybe_extract_name(name: Hashable, obj: object, cls: type) -> Hashable:
    if name is None and isinstance(obj, (Index, ABCSeries)):
        name = obj.name
    if not is_hashable(name):
        raise TypeError(f'{cls.__name__}.name must be a hashable type')
    return name

def droplevel_result(new_levels: list[Index], new_codes: list[npt.NDArray[np.intp]], new_names: list[Hashable]) -> Index:
    if len(new_levels) == 1:
        lev = new_levels[0]
        if len(lev) == 0 and len(new_codes[0]) == 0:
            result = lev[:0]
        else:
            result = lev.take(new_codes[0], allow_fill=True)
            result._name = new_names[0]
        return result
    else:
        from pandas.core.indexes.multi import MultiIndex
        return MultiIndex(levels=new_levels, codes=new_codes, names=new_names, verify_integrity=False)

def _unpack_nested_dtype(other: Index) -> DtypeObj:
    dtype = other.dtype
    if isinstance(dtype, CategoricalDtype):
        return dtype.categories.dtype
    elif isinstance(dtype, ArrowDtype):
        import pyarrow as pa
        if pa.types.is_dictionary(dtype.pyarrow_dtype):
            other = other[:0].astype(ArrowDtype(dtype.pyarrow_dtype.value_type))
    return other.dtype

def get_values_for_csv(values: ArrayLike, *, date_format: str_t | None, na_rep: str='nan', quoting: int | None=None, float_format: str_t | None=None, decimal: str='.') -> npt.NDArray[np.object_]:
    if isinstance(values, Categorical) and values.categories.dtype.kind in 'Mm':
        values = algos.take_nd(values.categories._values, ensure_platform_int(values._codes))
    values = ensure_wrapped_if_datetimelike(values)
    if isinstance(values, (DatetimeArray, TimedeltaArray, PeriodArray)):
        if values.ndim == 1:
            result = values._format_native_types(na_rep=na_rep, date_format=date_format)
            result = result.astype(object, copy=False)
            return result
        results_converted = []
        for i in range(len(values)):
            result = values[i, :]._format_native_types(na_rep=na_rep, date_format=date_format)
            results_converted.append(result.astype(object, copy=False))
        return np.vstack(results_converted)
    elif isinstance(values.dtype, IntervalDtype):
        values = cast('IntervalArray', values)
        mask = values.isna()
        if not quoting:
            result = np.asarray(values).astype(str)
        else:
            result = np.array(values, dtype=object, copy=True)
        result[mask] = na_rep
        return result
    elif values.dtype.kind == 'f' and (not isinstance(values.dtype, SparseDtype)):
        if float_format is None and decimal == '.':
            mask = isna(values)
            if not quoting:
                if isinstance(values, ExtensionArray) and values.ndim == 2:
                    values = np.asarray(values.to_numpy(), dtype=str)
                else:
                    values = values.astype(str)
            else:
                values = np.array(values, dtype='object')
            values[mask] = na_rep
            values = values.astype(object, copy=False)
            return values
        from pandas.io.formats.format import FloatArrayFormatter
        formatter = FloatArrayFormatter(values, na_rep=na_rep, float_format=float_format, decimal=decimal, quoting=quoting, fixed_width=False)
        res = formatter.get_result_as_array()
        res = res.astype(object, copy=False)
        return res
    elif isinstance(values, ExtensionArray):
        mask = isna(values)
        new_values = np.asarray(values.astype(object))
        new_values[mask] = na_rep
        return new_values
    else:
        mask = isna(values)
        itemsize = writers.word_len(na_rep)
        if values.dtype != _dtype_obj and (not quoting) and itemsize:
            values = values.astype(str)
            if values.dtype.itemsize / np.dtype('U1').itemsize < itemsize:
                values = values.astype(f'<U{itemsize}')
        else:
            values = np.array(values, dtype='object')
        values[mask] = na_rep
        values = values.astype(object, copy=False)
        return values

@classmethod
def _ensure_array(cls, data: ArrayLike, dtype: DtypeObj, copy: bool) -> ArrayLike:
    if data.ndim > 1:
        raise ValueError('Index data must be 1-dimensional')
    elif dtype == np.float16:
        raise NotImplementedError('float16 indexes are not supported')
    if copy:
        data = data.copy()
    return data

@classmethod
def _simple_new(cls, values: ArrayLike, name: Hashable | None=None, refs: BlockValuesRefs | None=None) -> Self:
    assert isinstance(values, cls._data_cls), type(values)
    result = object.__new__(cls)
    result._data = values
    result._name = name
    result._cache = {}
    result._reset_identity()
    if refs is not None:
        result._references = refs
    else:
        result._references = BlockValuesRefs()
    result._references.add_index_reference(result)
    return result

@classmethod
def _with_infer(cls, *args: Any, **kwargs: Any) -> Self:
    result = cls(*args, **kwargs)
    if result.dtype == _dtype_obj and (not result._is_multi):
        values = lib.maybe_convert_objects(result._values)
        if values.dtype.kind in 'iufb':
            return Index(values, name=result.name, copy=False)
    return result

@final
def _maybe_check_unique(self) -> None:
    if not self.is_unique:
        msg = 'Index has duplicates.'
        duplicates = self._format_duplicate_message()
        msg += f'\n{duplicates}'
        raise DuplicateLabelError(msg)

@final
def _format_duplicate_message(self) -> DataFrame:
    from pandas import Series
    duplicates = self[self.duplicated(keep='first')].unique()
    assert len(duplicates)
    out = Series(np.arange(len(self)), copy=False).groupby(self, observed=False).agg(list)[duplicates]
    if self._is_multi:
        out.index = type(self).from_tuples(out.index)
    if self.nlevels == 1:
        out = out.rename_axis('label')
    return out.to_frame(name='positions')

def _shallow_copy(self, values: ArrayLike, name: Hashable=no_default) -> Self:
    name = self._name if name is no_default else name
    return self._simple_new(values, name=name, refs=self._references)

@final
def _rename(self, name: Hashable) -> Self:
    result = self._view()
    result._name = name
    return result

@final
def is_(self, other: Index) -> bool:
    if self is other:
        return True
    elif not hasattr(other, '_id'):
        return False
    elif self._id is None or other._id is None:
        return False
    else:
        return self._id is other._id

@final
def _reset_identity(self) -> None:
    self._id = object()

@final
@cache_readonly
def _dir_additions_for_owner(self) -> set[str_t]:
    max_items = config['display']['max_dir_items']
    if max_items is not None and len(self) > max_items * 10:
        prefix_uniq = self[:max_items * 10].unique(level=0)
        if len(prefix_uniq) >= max_items:
            return {c for c in prefix_uniq[:max_items] if isinstance(c, str) and c.isidentifier()}
    return {c for c in self.unique(level=0)[:max_items] if isinstance(c, str) and c.isidentifier()}

def __array__(self, dtype: npt.DTypeLike | None=None, copy: bool | None=None) -> np.ndarray:
    if copy is None:
        return np.asarray(self._data, dtype=dtype)
    return np.array(self._data, dtype=dtype, copy=copy)

@final
def __array_wrap__(self, result: np.ndarray, context: tuple | None=None, return_scalar: bool=False) -> Any:
    result = lib.item_from_zerodim(result)
    if np.ndim(result) > 1:
        return result
    return Index(result, name=self.name)

@cache_readonly
def dtype(self) -> DtypeObj:
    return self._data.dtype

@final
def ravel(self, order: str_t='C') -> Self:
    return self[:]

def view(self, cls: npt.DTypeLike | None=None) -> Index:
    if cls is not None:
        dtype = cls
        if isinstance(cls, str):
            dtype = pandas_dtype(cls)
        if needs_i8_conversion(dtype):
            idx_cls = self._dtype_to_subclass(dtype)
            arr = self.array.view(dtype)
            if isinstance(arr, ExtensionArray):
                return idx_cls._simple_new(arr, name=self.name, refs=self._references)
            return arr
        result = self._data.view(cls)
    else:
        result = self._view()
    if isinstance(result, Index):
        result._id = self._id
    return result

def astype(self, dtype: Dtype, copy: bool=True) -> Index:
    if dtype is not None:
        dtype = pandas_dtype(dtype)
    if self.dtype == dtype:
        return self.copy() if copy else self
    values = self._data
    if isinstance(values, ExtensionArray):
        with rewrite_exception(type(values).__name__, type(self).__name__):
            new_values = values.astype(dtype, copy=copy)
    elif isinstance(dtype, ExtensionDtype):
        cls = dtype.construct_array_type()
        new_values = cls._from_sequence(self, dtype=dtype, copy=copy)
    else:
        new_values = astype_array(values, dtype=dtype, copy=copy)
    result = Index(new_values, name=self.name, dtype=new_values.dtype, copy=False)
    if not copy and self._references is not None and astype_is_view(self.dtype, dtype):
        result._references = self._references
        result._references.add_index_reference(result)
    return result

def take(self, indices: Sequence[int] | np.ndarray, axis: Axis=0, allow_fill: bool | lib.NoDefault=no_default, fill_value: object=no_default, **kwargs: Any) -> Self:
    if kwargs:
        nv.validate_take((), kwargs)
    if is_scalar(indices):
        raise TypeError('Expected indices to be array-like')
    indices = ensure_platform_int(indices)
    if allow_fill is no_default:
        if fill_value is None:
            warnings.warn("Passing fill_value=None without allow_fill previously used numpy-style wrapping of negative indices. In a future version this will trigger fill semantics (filling -1 entries with the dtype's NA value). Pass allow_fill=False to keep wrapping behavior, or allow_fill=True to opt into fill semantics.", Pandas4Warning, stacklevel=find_stack_level())
            allow_fill = False
        else:
            allow_fill = fill_value is not no_default
    if allow_fill:
        if fill_value is no_default or fill_value is None:
            fill_value = self._na_value
        if (indices < -1).any():
            raise ValueError('When allow_fill=True, all indices must be >= -1')
    elif fill_value is no_default:
        fill_value = None
    if indices.ndim == 1 and lib.is_range_indexer(indices, len(self)):
        return self.copy()
    values = self._values
    if isinstance(values, np.ndarray):
        taken = algos.take(values, indices, allow_fill=allow_fill, fill_value=fill_value)
    else:
        taken = values.take(indices, allow_fill=allow_fill, fill_value=fill_value)
    return self._constructor._simple_new(taken, name=self.name)

def repeat(self, repeats: int | Sequence[int], axis: None=None) -> Self:
    repeats = ensure_platform_int(repeats)
    nv.validate_repeat((), {'axis': axis})
    res_values = self._values.repeat(repeats)
    return self._constructor._simple_new(res_values, name=self.name)

def copy(self, name: Hashable | None=None, deep: bool=False) -> Self:
    name = self._validate_names(name=name, deep=deep)[0]
    if deep:
        new_data = self._data.copy()
        new_index = type(self)._simple_new(new_data, name=name)
    else:
        new_index = self._rename(name=name)
    return new_index

@final
def __deepcopy__(self, memo: dict[int, Any] | None=None) -> Self:
    return self.copy(deep=True)

@final
def __repr__(self) -> str_t:
    klass_name = type(self).__name__
    data = self._format_data()
    attrs = self._format_attrs()
    display_width = config['display']['width'] or 80
    indent = len(klass_name) + 1
    indent_str = ' ' * indent
    if '\n' in data:
        last_line = data.rsplit('\n', 1)[-1]
        line_len = len(last_line)
    else:
        line_len = indent + len(data)
    adj = get_adjustment()
    parts: list[str_t] = []
    num_attrs = len(attrs)
    for attr_idx, (key, val) in enumerate(attrs):
        attr = f'{key}={val}'
        attr_len = adj.len(attr)
        comma = 1 if attr_idx < num_attrs - 1 else 0
        if not parts:
            if line_len + attr_len + comma > display_width:
                parts.append('\n' + indent_str + attr)
                line_len = indent + attr_len
            else:
                parts.append(attr)
                line_len += attr_len
        else:
            sep = ', '
            if line_len + len(sep) + attr_len + comma > display_width:
                parts.append(',\n' + indent_str + attr)
                line_len = indent + attr_len
            else:
                parts.append(sep + attr)
                line_len += len(sep) + attr_len
    prepr = ''.join(parts)
    if prepr.startswith('\n'):
        data = data.rstrip()
    return f'{klass_name}({data}{prepr})'

@final
def _format_data(self, name: str_t | None=None) -> str_t:
    is_justify = True
    if self.inferred_type == 'string':
        is_justify = False
    elif isinstance(self.dtype, CategoricalDtype):
        self = cast('CategoricalIndex', self)
        if is_string_dtype(self.categories.dtype):
            is_justify = False
    elif isinstance(self, ABCRangeIndex):
        return ''
    return format_object_summary(self, self._formatter_func, is_justify=is_justify, name=name, line_break_each_value=self._is_multi)

def _format_attrs(self) -> list[tuple[str_t, str_t | int | bool | None]]:
    attrs: list[tuple[str_t, str_t | int | bool | None]] = []
    if not self._is_multi:
        attrs.append(('dtype', f"'{self.dtype}'"))
    if self.name is not None:
        attrs.append(('name', default_pprint(self.name)))
    elif self._is_multi and any((x is not None for x in self.names)):
        attrs.append(('names', default_pprint(self.names)))
    max_seq_items = config['display']['max_seq_items'] or len(self)
    if len(self) > max_seq_items:
        attrs.append(('length', len(self)))
    return attrs

@final
def _get_level_names(self) -> range | Sequence[Hashable]:
    if self._is_multi:
        return maybe_sequence_to_range([level if name is None else name for level, name in enumerate(self.names)])
    else:
        return range(1) if self.name is None else [self.name]

@final
def _format_flat(self, *, include_name: bool, formatter: Callable | None=None) -> list[str_t]:
    header = []
    if include_name:
        header.append(pprint_thing(self.name, escape_chars=('\t', '\r', '\n')) if self.name is not None else '')
    if formatter is not None:
        return header + list(self.map(formatter))
    return self._format_with_header(header=header, na_rep=self._default_na_rep)

def _summary(self, name: str_t | None=None) -> str_t:
    if len(self) > 0:
        head = self[0]
        if hasattr(head, 'format') and (not isinstance(head, str)):
            head = head.format()
        elif needs_i8_conversion(self.dtype):
            head = self._formatter_func(head).replace("'", '')
        tail = self[-1]
        if hasattr(tail, 'format') and (not isinstance(tail, str)):
            tail = tail.format()
        elif needs_i8_conversion(self.dtype):
            tail = self._formatter_func(tail).replace("'", '')
        index_summary = f', {head} to {tail}'
    else:
        index_summary = ''
    if name is None:
        name = type(self).__name__
    return f'{name}: {len(self)} entries{index_summary}'

@final
def to_series(self, index: Axes | None=None, name: Hashable | None=None) -> Series:
    from pandas import Series
    if index is None:
        index = self._view()
    if name is None:
        name = self.name
    return Series(self._values.copy(), index=index, name=name)

def to_frame(self, index: bool=True, name: Hashable=lib.no_default) -> DataFrame:
    from pandas import DataFrame
    if name is lib.no_default:
        result_name = self._get_level_names()
    else:
        result_name = Index([name])
    result = DataFrame(self, copy=False)
    result.columns = result_name
    if index:
        result.index = self
    return result

@property
def name(self) -> Hashable:
    return self._name

@final
def _validate_names(self, name: Hashable=None, names: Sequence[Hashable] | None=None, deep: bool=False) -> list[Hashable]:
    from copy import deepcopy
    if names is not None and name is not None:
        raise TypeError('Can only provide one of `names` and `name`')
    if names is None and name is None:
        new_names = deepcopy(self.names) if deep else self.names
    elif names is not None:
        if not is_list_like(names):
            raise TypeError('Must pass list-like as `names`.')
        new_names = names
    elif not is_list_like(name):
        new_names = [name]
    else:
        new_names = name
    if len(new_names) != len(self.names):
        raise ValueError(f'Length of new names must be {len(self.names)}, got {len(new_names)}')
    validate_all_hashable(*new_names, error_name=f'{type(self).__name__}.name')
    return new_names

def _get_default_index_names(self, names: Sequence[Hashable] | int | str_t | None=None, default: Hashable=None) -> list[Hashable]:
    from pandas.core.indexes.multi import MultiIndex
    if names is not None:
        if isinstance(names, (int, str)):
            names = [names]
    if not isinstance(names, list) and names is not None:
        raise ValueError('Index names must be str or 1-dimensional list')
    if not names:
        if isinstance(self, MultiIndex):
            names = com.fill_missing_names(self.names)
        else:
            names = [default] if self.name is None else [self.name]
    return names

def _set_names(self, values: Sequence[Hashable], *, level: int | Sequence[int] | None=None) -> None:
    if not is_list_like(values):
        raise ValueError('Names must be a list-like')
    if len(values) != 1:
        raise ValueError(f'Length of new names must be 1, got {len(values)}')
    validate_all_hashable(*values, error_name=f'{type(self).__name__}.name')
    self._name = values[0]

def set_names(self, names: Hashable | Sequence[Hashable] | dict[Hashable, Hashable], *, level: Hashable | Sequence[Hashable] | None=None, inplace: bool=False) -> Self | None:
    if level is not None and (not isinstance(self, ABCMultiIndex)):
        raise ValueError('Level must be None for non-MultiIndex')
    if level is not None and (not is_list_like(level)) and is_list_like(names):
        raise TypeError('Names must be a string when a single level is provided.')
    if not is_list_like(names) and level is None and (self.nlevels > 1):
        raise TypeError('Must pass list-like as `names`.')
    if is_dict_like(names) and (not isinstance(self, ABCMultiIndex)):
        raise TypeError('Can only pass dict-like as `names` for MultiIndex.')
    if is_dict_like(names) and level is not None:
        raise TypeError('Can not pass level for dictlike `names`.')
    if isinstance(self, ABCMultiIndex) and is_dict_like(names) and (level is None):
        level_list: list[int] = []
        names_adjusted: list[Hashable] = []
        for i, name in enumerate(self.names):
            if name in names.keys():
                level_list.append(i)
                names_adjusted.append(names[name])
        level = level_list
        names = names_adjusted
    if not is_list_like(names):
        names = [names]
    if level is not None and (not is_list_like(level)):
        level = [level]
    if inplace:
        idx = self
    else:
        idx = self._view()
    idx._set_names(names, level=level)
    if not inplace:
        return idx
    return None

@property
def nlevels(self) -> int:
    return 1

@final
def _validate_index_level(self, level: Level) -> None:
    is_level_na = cast('bool', isna(level))
    is_name_na = cast('bool', isna(self.name))
    if is_level_na and is_name_na:
        if is_matching_na(level, self.name):
            return
        raise KeyError(f'Requested level ({level}) does not match index name ({self.name})')
    elif is_level_na:
        raise KeyError(f'Requested level ({level}) does not match index name ({self.name})')
    if is_integer(level):
        if is_integer(self.name) and level == self.name:
            return
        if level < 0 and level != -1:
            raise IndexError(f'Too many levels: Index has only 1 level, {level} is not a valid level number')
        if level > 0:
            raise IndexError(f'Too many levels: Index has only 1 level, not {level + 1}')
        return
    elif level != self.name:
        raise KeyError(f'Requested level ({level}) does not match index name ({self.name})')

def sortlevel(self, level: Level | None=None, ascending: bool | list[bool]=True, sort_remaining: bool | None=None, na_position: NaPosition='first') -> tuple[Self, np.ndarray]:
    if not isinstance(ascending, (list, bool)):
        raise TypeError('ascending must be a single bool value ora list of bool values of length 1')
    if isinstance(ascending, list):
        if len(ascending) != 1:
            raise TypeError('ascending must be a list of bool values of length 1')
        ascending = ascending[0]
    if not isinstance(ascending, bool):
        raise TypeError('ascending must be a bool value')
    return self.sort_values(return_indexer=True, ascending=ascending, na_position=na_position)

def _get_level_values(self, level: Level) -> Index:
    self._validate_index_level(level)
    return self

@final
def droplevel(self, level: IndexLabel=0) -> Index:
    if not isinstance(level, (tuple, list)):
        level = [level]
    levnums = sorted((self._get_level_number(lev) for lev in level), reverse=True)
    return self._drop_level_numbers(levnums)

@final
def _drop_level_numbers(self, levnums: list[int]) -> Index:
    if not levnums and (not isinstance(self, ABCMultiIndex)):
        return self
    if len(levnums) >= self.nlevels:
        raise ValueError(f'Cannot remove {len(levnums)} levels from an index with {self.nlevels} levels: at least one level must be left.')
    self = cast('MultiIndex', self)
    new_levels = list(self.levels)
    new_codes = list(self.codes)
    new_names = list(self.names)
    for i in levnums:
        new_levels.pop(i)
        new_codes.pop(i)
        new_names.pop(i)
    return droplevel_result(new_levels, new_codes, new_names)

@property
def is_monotonic_increasing(self) -> bool:
    if isinstance(self._values, ExtensionArray) and type(self._engine) is libindex.ObjectEngine:
        return self._values._is_monotonic_increasing
    return self._engine.is_monotonic_increasing

@property
def is_monotonic_decreasing(self) -> bool:
    if isinstance(self._values, ExtensionArray) and type(self._engine) is libindex.ObjectEngine:
        return self._values._is_monotonic_decreasing
    return self._engine.is_monotonic_decreasing

@final
@property
def _is_strictly_monotonic_increasing(self) -> bool:
    return self.is_unique and self.is_monotonic_increasing

@final
@property
def _is_strictly_monotonic_decreasing(self) -> bool:
    return self.is_unique and self.is_monotonic_decreasing

@cache_readonly
def is_unique(self) -> bool:
    return self._engine.is_unique

@final
@property
def has_duplicates(self) -> bool:
    return not self.is_unique

@cache_readonly
def inferred_type(self) -> str_t:
    return lib.infer_dtype(self._values, skipna=False)

@cache_readonly
@final
def _is_all_dates(self) -> bool:
    if needs_i8_conversion(self.dtype):
        return True
    elif self.dtype != _dtype_obj:
        return False
    elif self._is_multi:
        return False
    return is_datetime_array(ensure_object(self._values))

@final
@cache_readonly
def _is_multi(self) -> bool:
    return isinstance(self, ABCMultiIndex)

@cache_readonly
def _na_value(self) -> Hashable:
    dtype = self.dtype
    if isinstance(dtype, np.dtype):
        if dtype.kind in 'mM':
            return NaT
        return np.nan
    return dtype.na_value

@cache_readonly
def _isnan(self) -> npt.NDArray[np.bool_]:
    if self._can_hold_na:
        return isna(self)
    else:
        values = np.empty(len(self), dtype=np.bool_)
        values.fill(False)
        return values

@cache_readonly
def hasnans(self) -> bool:
    if self._can_hold_na:
        return bool(self._isnan.any())
    else:
        return False

@final
def isna(self) -> npt.NDArray[np.bool_]:
    return self._isnan

@final
def notna(self) -> npt.NDArray[np.bool_]:
    return ~self.isna()

def fillna(self, value: object) -> Index:
    if is_list_like(value, allow_sets=False) and (not isinstance(value, tuple)):
        raise TypeError(f"'value' must be a scalar, passed: {type(value).__name__}")
    if self.hasnans:
        result = self.putmask(self._isnan, value)
        return Index._with_infer(result, name=self.name, copy=False)
    return self._view()

def dropna(self, how: AnyAll='any') -> Self:
    if how not in ('any', 'all'):
        raise ValueError(f'invalid how option: {how}')
    if self.hasnans:
        res_values = self._values[~self._isnan]
        return type(self)._simple_new(res_values, name=self.name)
    return self._view()

def unique(self, level: Hashable | None=None) -> Self:
    if level is not None:
        self._validate_index_level(level)
    if self.is_unique:
        return self._view()
    result = super().unique()
    return self._shallow_copy(result)

def drop_duplicates(self, *, keep: DropKeep='first') -> Self:
    if self.is_unique:
        return self._view()
    return super().drop_duplicates(keep=keep)

def duplicated(self, keep: DropKeep='first') -> npt.NDArray[np.bool_]:
    if self.is_unique:
        return np.zeros(len(self), dtype=bool)
    return self._duplicated(keep=keep)

def _get_reconciled_name_object(self, other: Index) -> Self:
    name = get_op_result_name(self, other)
    if self.name is not name:
        return self.rename(name)
    return self.copy(deep=False)

@final
def _dti_setop_align_tzs(self, other: Index, setop: str_t) -> tuple[Index, Index]:
    if isinstance(self, ABCDatetimeIndex) and isinstance(other, ABCDatetimeIndex) and (self.tz is not None) and (other.tz is not None):
        if self.tz == other.tz:
            return (self, other)
        else:
            left = self.tz_convert('UTC')
            right = other.tz_convert('UTC')
            return (left, right)
    return (self, other)

@final
def union(self, other: Axes, sort: bool | None=None) -> Index:
    self._validate_sort_keyword(sort)
    self._assert_can_do_setop(other)
    other, result_name = self._convert_can_do_setop(other)
    if self.dtype != other.dtype:
        if isinstance(self, ABCMultiIndex) and (not is_object_dtype(_unpack_nested_dtype(other))) and (len(other) > 0):
            raise NotImplementedError('Can only union MultiIndex with MultiIndex or Index of tuples, try mi.to_flat_index().union(other) instead.')
        self, other = self._dti_setop_align_tzs(other, 'union')
        dtype = self._find_common_type_compat(other)
        left = self.astype(dtype, copy=False)
        right = other.astype(dtype, copy=False)
        return left.union(right, sort=sort)
    elif not len(other) or self.equals(other):
        result = self._get_reconciled_name_object(other)
        if sort is True:
            return result.sort_values()
        return result
    elif not len(self):
        result = other._get_reconciled_name_object(self)
        if sort is True:
            return result.sort_values()
        return result
    union_result = self._union(other, sort=sort)
    return self._wrap_setop_result(other, union_result)

def _union(self, other: Index, sort: bool | None) -> Index | ArrayLike | MultiIndex:
    lvals = self._values
    rvals = other._values
    if sort in (None, True) and (self.is_unique or other.is_unique) and self._can_use_libjoin and other._can_use_libjoin:
        try:
            return self._outer_indexer(other)[0]
        except TypeError:
            value_list = list(lvals)
            value_set = set(lvals)
            value_list.extend((x for x in rvals if x not in value_set))
            return np.array(value_list, dtype=object)
    elif not other.is_unique:
        result_dups = algos.union_with_duplicates(self, other)
        return _maybe_try_sort(result_dups, sort)
    if self._index_as_unique:
        indexer = self.get_indexer(other)
        missing = (indexer == -1).nonzero()[0]
    else:
        missing = algos.unique1d(self.get_indexer_non_unique(other)[1])
    result: Index | MultiIndex | ArrayLike
    if self._is_multi:
        result = self.append(other.take(missing))
    elif len(missing) > 0:
        other_diff = rvals.take(missing)
        result = concat_compat((lvals, other_diff))
    else:
        result = lvals
    result = _maybe_try_sort(result, sort)
    return result

@final
def intersection(self, other: Axes, sort: bool=False) -> Index:
    self._validate_sort_keyword(sort)
    self._assert_can_do_setop(other)
    other, result_name = self._convert_can_do_setop(other)
    if self.dtype != other.dtype:
        self, other = self._dti_setop_align_tzs(other, 'intersection')
    if self.equals(other):
        if not self.is_unique:
            result = self.unique()._get_reconciled_name_object(other)
        else:
            result = self._get_reconciled_name_object(other)
        if sort is True:
            result = result.sort_values()
        return result
    if len(self) == 0 or len(other) == 0:
        if self._is_multi or other._is_multi:
            return self[:0].rename(result_name)
        dtype = self._find_common_type_compat(other)
        if self.dtype == dtype:
            if len(self) == 0:
                return self[:0].rename(result_name)
            else:
                return other[:0].rename(result_name)
        return Index([], dtype=dtype, name=result_name)
    elif not self._should_compare(other):
        if isinstance(self, ABCMultiIndex):
            return self[:0].rename(result_name)
        return Index([], name=result_name)
    elif self.dtype != other.dtype:
        dtype = self._find_common_type_compat(other)
        this = self.astype(dtype, copy=False)
        other = other.astype(dtype, copy=False)
        return this.intersection(other, sort=sort)
    result = self._intersection(other, sort=sort)
    return self._wrap_intersection_result(other, result)

def _intersection(self, other: Index, sort: bool=False) -> Index | ArrayLike | MultiIndex:
    if self._can_use_libjoin and other._can_use_libjoin:
        try:
            res_indexer, indexer, _ = self._inner_indexer(other)
        except TypeError:
            pass
        else:
            if is_numeric_dtype(self.dtype):
                res = algos.unique1d(res_indexer)
            else:
                result = self.take(indexer)
                res = result.drop_duplicates()
            return ensure_wrapped_if_datetimelike(res)
    res_values = self._intersection_via_get_indexer(other, sort=sort)
    res_values = _maybe_try_sort(res_values, sort)
    return res_values

@final
def _intersection_via_get_indexer(self, other: Index | MultiIndex, sort: bool | None) -> ArrayLike | MultiIndex:
    left_unique = self.unique()
    right_unique = other.unique()
    indexer = left_unique.get_indexer_for(right_unique)
    mask = indexer != -1
    taker = indexer.take(mask.nonzero()[0])
    if sort is False:
        taker = np.sort(taker)
    result: MultiIndex | ExtensionArray | np.ndarray
    if isinstance(left_unique, ABCMultiIndex):
        result = left_unique.take(taker)
    else:
        result = left_unique.take(taker)._values
    return result

@final
def difference(self, other: Axes, sort: bool | None=None) -> Index:
    self._validate_sort_keyword(sort)
    self._assert_can_do_setop(other)
    other, result_name = self._convert_can_do_setop(other)
    if self.equals(other):
        return self[:0].rename(result_name)
    if len(other) == 0:
        result = self.unique().rename(result_name)
        if sort is True:
            return result.sort_values()
        return result
    if not self._should_compare(other):
        result = self.unique().rename(result_name)
        if sort is True:
            return result.sort_values()
        return result
    result = self._difference(other, sort=sort)
    return self._wrap_difference_result(other, result)

def symmetric_difference(self, other: Axes, result_name: abc.Hashable | None=None, sort: bool | None=None) -> Index:
    self._validate_sort_keyword(sort)
    self._assert_can_do_setop(other)
    other, result_name_update = self._convert_can_do_setop(other)
    if result_name is None:
        result_name = result_name_update
    if self.dtype != other.dtype:
        self, other = self._dti_setop_align_tzs(other, 'symmetric_difference')
    if not self._should_compare(other):
        return self.union(other, sort=sort).rename(result_name)
    elif self.dtype != other.dtype:
        dtype = self._find_common_type_compat(other)
        this = self.astype(dtype, copy=False)
        that = other.astype(dtype, copy=False)
        return this.symmetric_difference(that, sort=sort).rename(result_name)
    this = self.unique()
    other = other.unique()
    indexer = this.get_indexer_for(other)
    common_indexer = indexer.take((indexer != -1).nonzero()[0])
    left_indexer = np.setdiff1d(np.arange(this.size), common_indexer, assume_unique=True)
    left_diff = this.take(left_indexer)
    right_indexer = (indexer == -1).nonzero()[0]
    right_diff = other.take(right_indexer)
    res_values = left_diff.append(right_diff)
    result = _maybe_try_sort(res_values, sort)
    if not self._is_multi:
        return Index(result, name=result_name, dtype=res_values.dtype)
    else:
        left_diff = cast('MultiIndex', left_diff)
        if len(result) == 0:
            return left_diff.remove_unused_levels().set_names(result_name)
        result = cast('Index', result)
        return result.set_names(result_name)

def get_loc(self, key: Hashable) -> int | slice | npt.NDArray[np.bool_]:
    casted_key = self._maybe_cast_indexer(key)
    try:
        return self._engine.get_loc(casted_key)
    except KeyError as err:
        if isinstance(casted_key, slice) or (isinstance(casted_key, abc.Iterable) and any((isinstance(x, slice) for x in casted_key))):
            raise InvalidIndexError(key) from err
        raise KeyError(key) from err
    except TypeError:
        self._check_indexing_error(key)
        raise

@final
def get_indexer(self, target: Axes, method: ReindexMethod | None=None, limit: int | None=None, tolerance: Any=None) -> npt.NDArray[np.intp]:
    method = clean_reindex_fill_method(method)
    orig_target = target
    target = self._maybe_cast_listlike_indexer(target)
    self._check_indexing_method(method, limit, tolerance)
    if not self._index_as_unique:
        raise InvalidIndexError(self._requires_unique_msg)
    if len(target) == 0:
        return np.array([], dtype=np.intp)
    if not self._should_compare(target) and (not self._should_partial_index(target)):
        return self._get_indexer_non_comparable(target, method=method, unique=True)
    if isinstance(self.dtype, CategoricalDtype):
        assert self.dtype == target.dtype
        target = cast('CategoricalIndex', target)
        indexer = self._engine.get_indexer(target.codes)
        if self.hasnans and target.hasnans:
            target_nans = isna(orig_target)
            loc = self.get_loc(np.nan)
            mask = target.isna()
            indexer[target_nans] = loc
            indexer[mask & ~target_nans] = -1
        return indexer
    if isinstance(target.dtype, CategoricalDtype):
        target = cast('CategoricalIndex', target)
        categories_indexer = self.get_indexer(target.categories)
        indexer = algos.take_nd(categories_indexer, target.codes, fill_value=-1)
        if (not self._is_multi and self.hasnans) and target.hasnans:
            loc = self.get_loc(np.nan)
            mask = target.isna()
            indexer[mask] = loc
        return ensure_platform_int(indexer)
    pself, ptarget = self._maybe_downcast_for_indexing(target)
    if pself is not self or ptarget is not target:
        return pself.get_indexer(ptarget, method=method, limit=limit, tolerance=tolerance)
    if self.dtype == target.dtype and self.equals(target):
        return np.arange(len(target), dtype=np.intp)
    if self.dtype != target.dtype and (not self._should_partial_index(target)):
        dtype = self._find_common_type_compat(target)
        this = self.astype(dtype, copy=False)
        target = target.astype(dtype, copy=False)
        return this._get_indexer(target, method=method, limit=limit, tolerance=tolerance)
    return self._get_indexer(target, method, limit, tolerance)

@final
def _should_partial_index(self, target: Index) -> bool:
    if isinstance(self.dtype, IntervalDtype):
        if isinstance(target.dtype, IntervalDtype):
            return False
        return self.left._should_compare(target)
    return False

@final
def _check_indexing_method(self, method: str_t | None, limit: int | None=None, tolerance: Any=None) -> None:
    if method not in [None, 'bfill', 'backfill', 'pad', 'ffill', 'nearest']:
        raise ValueError('Invalid fill method')
    if self._is_multi:
        if method == 'nearest':
            raise NotImplementedError("method='nearest' not implemented yet for MultiIndex; see GitHub issue 9365")
        if method in ('pad', 'backfill'):
            if tolerance is not None:
                raise NotImplementedError('tolerance not implemented yet for MultiIndex')
    if isinstance(self.dtype, (IntervalDtype, CategoricalDtype)):
        if method is not None:
            raise NotImplementedError(f'method {method} not yet implemented for {type(self).__name__}')
    if method is None:
        if tolerance is not None:
            raise ValueError('tolerance argument only valid if doing pad, backfill or nearest reindexing')
        if limit is not None:
            raise ValueError('limit argument only valid if doing pad, backfill or nearest reindexing')

@final
def _get_fill_indexer_searchsorted(self, target: Index, method: str_t, limit: int | None=None) -> npt.NDArray[np.intp]:
    if limit is not None:
        raise ValueError(f'limit argument for {method!r} method only well-defined if index and target are monotonic')
    side: Literal['left', 'right'] = 'left' if method == 'pad' else 'right'
    indexer = self.get_indexer(target)
    nonexact = indexer == -1
    indexer[nonexact] = self._searchsorted_monotonic(target[nonexact], side)
    if side == 'left':
        indexer[nonexact] -= 1
    else:
        indexer[indexer == len(self)] = -1
    return indexer

@final
def _get_nearest_indexer(self, target: Index, limit: int | None, tolerance: Any) -> npt.NDArray[np.intp]:
    if not len(self):
        return self._get_fill_indexer(target, 'pad')
    left_indexer = self.get_indexer(target, 'pad', limit=limit)
    right_indexer = self.get_indexer(target, 'backfill', limit=limit)
    left_distances = self._difference_compat(target, left_indexer)
    right_distances = self._difference_compat(target, right_indexer)
    op = operator.lt if self.is_monotonic_increasing else operator.le
    indexer = np.where(op(left_distances, right_distances) | (right_indexer == -1), left_indexer, right_indexer)
    if tolerance is not None:
        indexer = self._filter_indexer_tolerance(target, indexer, tolerance)
    return indexer

@final
def _validate_positional_slice(self, key: slice) -> None:
    self._validate_indexer('positional', key.start, 'iloc')
    self._validate_indexer('positional', key.stop, 'iloc')
    self._validate_indexer('positional', key.step, 'iloc')

def _convert_slice_indexer(self, key: slice, kind: Literal['loc', 'getitem']) -> slice:
    start, stop, step = (key.start, key.stop, key.step)
    is_index_slice = is_valid_positional_slice(key)
    if kind == 'getitem':
        if is_index_slice:
            return key
        elif self.dtype.kind in 'iu':
            self._validate_indexer('slice', key.start, 'getitem')
            self._validate_indexer('slice', key.stop, 'getitem')
            self._validate_indexer('slice', key.step, 'getitem')
            return key
    is_positional = is_index_slice and self._should_fallback_to_positional
    if is_positional:
        try:
            if start is not None:
                self.get_loc(start)
            if stop is not None:
                self.get_loc(stop)
            is_positional = False
        except KeyError:
            pass
    if com.is_null_slice(key):
        indexer = key
    elif is_positional:
        if kind == 'loc':
            raise TypeError('Slicing a positional slice with .loc is not allowed, Use .loc with labels or .iloc with positions instead.')
        indexer = key
    else:
        indexer = self.slice_indexer(start, stop, step)
    return indexer

@final
def _raise_invalid_indexer(self, form: Literal['slice', 'positional'], key: object, reraise: lib.NoDefault | None | Exception=lib.no_default) -> None:
    msg = f'cannot do {form} indexing on {type(self).__name__} with these indexers [{key}] of type {type(key).__name__}'
    if reraise is not lib.no_default:
        raise TypeError(msg) from reraise
    raise TypeError(msg)

@final
def _validate_can_reindex(self, indexer: np.ndarray) -> None:
    if not self._index_as_unique and len(indexer):
        raise ValueError('cannot reindex on an axis with duplicate labels')

def reindex(self, target: Axes, method: ReindexMethod | None=None, level: Level | None=None, limit: int | None=None, tolerance: float | None=None) -> tuple[Index, npt.NDArray[np.intp] | None]:
    preserve_names = not hasattr(target, 'name')
    if is_iterator(target):
        target = list(target)
    if not isinstance(target, Index) and len(target) == 0:
        if level is not None and self._is_multi:
            idx = self.levels[level]
        else:
            idx = self
        target = idx[:0]
    else:
        target = ensure_index(target)
    if level is not None and (isinstance(self, ABCMultiIndex) or isinstance(target, ABCMultiIndex)):
        if method is not None:
            raise TypeError('Fill method not supported if level passed')
        target, indexer, _ = self._join_level(target, level, how='right', keep_order=not self._is_multi)
    elif self.equals(target):
        indexer = None
    elif self._index_as_unique:
        indexer = self.get_indexer(target, method=method, limit=limit, tolerance=tolerance)
    elif self._is_multi:
        raise ValueError('cannot handle a non-unique multi-index!')
    elif not self.is_unique:
        raise ValueError('cannot reindex on an axis with duplicate labels')
    else:
        indexer, _ = self.get_indexer_non_unique(target)
    target = self._wrap_reindex_result(target, indexer, preserve_names)
    return (target, indexer)

@final
def _reindex_non_unique(self, target: Index) -> tuple[Index, npt.NDArray[np.intp], npt.NDArray[np.intp] | None]:
    target = ensure_index(target)
    if len(target) == 0:
        return (self[:0], np.array([], dtype=np.intp), None)
    indexer, missing = self.get_indexer_non_unique(target)
    check = indexer != -1
    new_labels: Index | np.ndarray = self.take(indexer[check])
    new_indexer = None
    if len(missing):
        length = np.arange(len(indexer), dtype=np.intp)
        missing = ensure_platform_int(missing)
        missing_labels = target.take(missing)
        missing_indexer = length[~check]
        cur_labels = self.take(indexer[check]).values
        cur_indexer = length[check]
        new_labels = np.empty((len(indexer),), dtype=object)
        new_labels[cur_indexer] = cur_labels
        new_labels[missing_indexer] = missing_labels
        if not len(self):
            new_indexer = np.arange(0, dtype=np.intp)
        elif target.is_unique:
            new_indexer = np.arange(len(indexer), dtype=np.intp)
            new_indexer[cur_indexer] = np.arange(len(cur_labels))
            new_indexer[missing_indexer] = -1
        else:
            indexer[~check] = -1
            new_indexer = np.arange(len(self.take(indexer)), dtype=np.intp)
            new_indexer[~check] = -1
    if not isinstance(self, ABCMultiIndex):
        new_index = Index(new_labels, name=self.name, copy=False)
    else:
        new_index = type(self).from_tuples(new_labels, names=self.names)
    return (new_index, indexer, new_indexer)

@final
@_maybe_return_indexers
def join(self, other: Index, *, how: JoinHow='left', level: Level | None=None, return_indexers: bool=False, sort: bool=False) -> Index | tuple[Index, npt.NDArray[np.intp] | None, npt.NDArray[np.intp] | None]:
    if not isinstance(other, Index):
        warnings.warn(f'Passing {type(other).__name__} to {type(self).__name__}.join is deprecated and will raise in a future version. Pass an Index instead.', Pandas4Warning, stacklevel=find_stack_level())
    other = ensure_index(other)
    sort = sort or how == 'outer'
    if isinstance(self, ABCDatetimeIndex) and isinstance(other, ABCDatetimeIndex):
        if (self.tz is None) ^ (other.tz is None):
            raise TypeError('Cannot join tz-naive with tz-aware DatetimeIndex')
    if not self._is_multi and (not other._is_multi):
        pself, pother = self._maybe_downcast_for_indexing(other)
        if pself is not self or pother is not other:
            return pself.join(pother, how=how, level=level, return_indexers=True, sort=sort)
    if level is None and (self._is_multi or other._is_multi):
        if self.names == other.names:
            pass
        else:
            return self._join_multi(other, how=how)
    if level is not None and (self._is_multi or other._is_multi):
        return self._join_level(other, level, how=how)
    if len(self) == 0 or len(other) == 0:
        try:
            return self._join_empty(other, how, sort)
        except TypeError:
            pass
    if self.dtype != other.dtype:
        dtype = self._find_common_type_compat(other)
        this = self.astype(dtype, copy=False)
        other = other.astype(dtype, copy=False)
        return this.join(other, how=how, return_indexers=True)
    elif isinstance(self, ABCCategoricalIndex) and isinstance(other, ABCCategoricalIndex) and (not self.ordered) and (not self.categories.equals(other.categories)):
        other = Index(other._values.reorder_categories(self.categories), copy=False)
    _validate_join_method(how)
    if self.is_monotonic_increasing and other.is_monotonic_increasing and (self.is_unique or other.is_unique):
        if self._can_use_libjoin and other._can_use_libjoin:
            if self.equals(other):
                ret_index = other if how == 'right' else self
                return (ret_index, None, None)
            try:
                return self._join_monotonic(other, how=how)
            except TypeError:
                pass
        elif isinstance(self, ABCRangeIndex):
            try:
                return self._join_monotonic(other, how=how)
            except (TypeError, NotImplementedError):
                pass
    if self.equals(other) and (self.is_unique or other.is_unique) and (not sort or self.is_monotonic_increasing):
        ret_index = other if how == 'right' else self
        return (ret_index, None, None)
    if not self.is_unique or not other.is_unique:
        return self._join_non_unique(other, how=how, sort=sort)
    return self._join_via_get_indexer(other, how, sort)

@final
def _join_level(self, other: Index, level: Level, how: JoinHow='left', keep_order: bool=True) -> tuple[MultiIndex, npt.NDArray[np.intp] | None, npt.NDArray[np.intp] | None]:
    from pandas.core.indexes.multi import MultiIndex

    def _get_leaf_sorter(labels: list[np.ndarray]) -> npt.NDArray[np.intp]:
        """
            Returns sorter for the inner most level while preserving the
            order of higher levels.

            Parameters
            ----------
            labels : list[np.ndarray]
                Each ndarray has signed integer dtype, not necessarily identical.

            Returns
            -------
            np.ndarray[np.intp]
            """
        if labels[0].size == 0:
            return np.empty(0, dtype=np.intp)
        if len(labels) == 1:
            return get_group_index_sorter(ensure_platform_int(labels[0]))
        tic = labels[0][:-1] != labels[0][1:]
        for lab in labels[1:-1]:
            tic |= lab[:-1] != lab[1:]
        starts = np.hstack(([True], tic, [True])).nonzero()[0]
        lab = ensure_int64(labels[-1])
        return lib.get_level_sorter(lab, ensure_platform_int(starts))
    if isinstance(self, MultiIndex) and isinstance(other, MultiIndex):
        raise TypeError('Join on level between two MultiIndex objects is ambiguous')
    left, right = (self, other)
    flip_order = not isinstance(self, MultiIndex)
    if flip_order:
        left, right = (right, left)
        flip: dict[JoinHow, JoinHow] = {'right': 'left', 'left': 'right'}
        how = flip.get(how, how)
    assert isinstance(left, MultiIndex)
    level = left._get_level_number(level)
    old_level = left.levels[level]
    if not right.is_unique:
        raise NotImplementedError('Index._join_level on non-unique index is not implemented')
    new_level, left_lev_indexer, right_lev_indexer = old_level.join(right, how=how, return_indexers=True)
    if left_lev_indexer is None:
        if keep_order or len(left) == 0:
            left_indexer = None
            join_index = left
        else:
            left_indexer = _get_leaf_sorter(left.codes[:level + 1])
            join_index = left[left_indexer]
    else:
        left_lev_indexer = ensure_platform_int(left_lev_indexer)
        rev_indexer = lib.get_reverse_indexer(left_lev_indexer, len(old_level))
        old_codes = left.codes[level]
        taker = old_codes[old_codes != -1]
        new_lev_codes = rev_indexer.take(taker)
        new_codes = list(left.codes)
        new_codes[level] = new_lev_codes
        new_levels = list(left.levels)
        new_levels[level] = new_level
        if keep_order:
            left_indexer = np.arange(len(left), dtype=np.intp)
            left_indexer = cast('np.ndarray', left_indexer)
            mask = new_lev_codes != -1
            if not mask.all():
                new_codes = [lab[mask] for lab in new_codes]
                left_indexer = left_indexer[mask]
        elif level == 0:
            max_new_lev = 0 if len(new_lev_codes) == 0 else new_lev_codes.max()
            ngroups = 1 + max_new_lev
            left_indexer, counts = libalgos.groupsort_indexer(new_lev_codes, ngroups)
            left_indexer = left_indexer[counts[0]:]
            new_codes = [lab[left_indexer] for lab in new_codes]
        else:
            mask = new_lev_codes != -1
            mask_all = mask.all()
            if not mask_all:
                new_codes = [lab[mask] for lab in new_codes]
            left_indexer = _get_leaf_sorter(new_codes[:level + 1])
            new_codes = [lab[left_indexer] for lab in new_codes]
            if not mask_all:
                left_indexer = mask.nonzero()[0][left_indexer]
        join_index = MultiIndex(levels=new_levels, codes=new_codes, names=left.names, verify_integrity=False)
    if right_lev_indexer is not None:
        right_indexer = right_lev_indexer.take(join_index.codes[level])
    else:
        right_indexer = join_index.codes[level]
    if flip_order:
        left_indexer, right_indexer = (right_indexer, left_indexer)
    left_indexer = None if left_indexer is None else ensure_platform_int(left_indexer)
    right_indexer = None if right_indexer is None else ensure_platform_int(right_indexer)
    return (join_index, left_indexer, right_indexer)

@final
@cache_readonly
def _can_use_libjoin(self) -> bool:
    if not self.is_monotonic_increasing:
        return False
    if type(self) is Index:
        return isinstance(self.dtype, np.dtype) or isinstance(self._values, (ArrowExtensionArray, BaseMaskedArray)) or (isinstance(self.dtype, StringDtype) and self.dtype.storage == 'python')
    return not isinstance(self, (ABCIntervalIndex, ABCMultiIndex, ABCRangeIndex))

@property
def values(self) -> ArrayLike:
    data = self._data
    if isinstance(data, np.ndarray):
        data = data.view()
        data.flags.writeable = False
    return data

@cache_readonly
def array(self) -> ExtensionArray:
    array = self._data
    if isinstance(array, np.ndarray):
        from pandas.core.arrays.numpy_ import NumpyExtensionArray
        array = NumpyExtensionArray(array)
    return array

@property
def _values(self) -> ExtensionArray | np.ndarray:
    return self._data

def _get_engine_target(self) -> ArrayLike:
    vals = self._values
    if isinstance(vals, StringArray):
        return vals._ndarray
    if isinstance(vals, ArrowExtensionArray) and self.dtype.kind in 'Mm':
        import pyarrow as pa
        pa_type = vals._pa_array.type
        if pa.types.is_timestamp(pa_type):
            vals = vals._to_datetimearray()
            return vals._ndarray.view('i8')
        elif pa.types.is_duration(pa_type):
            vals = vals._to_timedeltaarray()
            return vals._ndarray.view('i8')
    if type(self) is Index and isinstance(vals, ExtensionArray) and (not isinstance(vals, BaseMaskedArray)) and (not (isinstance(vals, ArrowExtensionArray) and is_numeric_dtype(self.dtype) and (self.dtype.kind != 'O'))):
        return vals.astype(object)
    return vals

@final
def _get_join_target(self) -> np.ndarray:
    if isinstance(self._values, BaseMaskedArray):
        return self._values._data
    elif isinstance(self._values, ArrowExtensionArray) and self.dtype.kind not in 'mM':
        return self._values.to_numpy()
    target = self._get_engine_target()
    if not isinstance(target, np.ndarray):
        raise ValueError('_can_use_libjoin should return False.')
    return target

def _from_join_target(self, result: np.ndarray) -> ArrayLike:
    if isinstance(self.values, BaseMaskedArray):
        return type(self.values)(result, np.zeros(result.shape, dtype=np.bool_))
    elif isinstance(self.values, (ArrowExtensionArray, StringArray)):
        return type(self.values)._from_sequence(result, dtype=self.dtype)
    return result

def memory_usage(self, deep: bool=False) -> int:
    result = self._memory_usage(deep=deep)
    if '_engine' in self._cache:
        result += self._engine.sizeof(deep=deep)
    return result

@final
def where(self, cond: np.ndarray, other: object=None) -> Index:
    if isinstance(self, ABCMultiIndex):
        raise NotImplementedError('.where is not supported for MultiIndex operations')
    cond = np.asarray(cond, dtype=bool)
    from pandas import Series
    ser = Series(self, copy=False)
    try:
        result_ser = ser.where(cond, other)
    except (TypeError, ValueError):
        dtype = self._find_common_type_compat(other)
        if dtype == self.dtype:
            raise
        return self.astype(dtype).where(cond, other)
    return Index(result_ser, dtype=result_ser.dtype, name=self.name, copy=False)

@classmethod
def _maybe_copy_array_input(cls, data: object, copy: bool | None, dtype: Dtype | None) -> tuple[Any, bool]:
    if isinstance(data, (ExtensionArray, np.ndarray)):
        if copy is not False:
            if dtype is None or astype_is_view(data.dtype, pandas_dtype(dtype)):
                data = data.copy()
                copy = False
    return (data, bool(copy))

def _validate_fill_value(self, value: object) -> object:
    dtype = self.dtype
    if isinstance(dtype, np.dtype) and dtype.kind not in 'mM':
        if isinstance(value, tuple) and dtype != object:
            raise TypeError
        try:
            return np_can_hold_element(dtype, value)
        except LossySetitemError as err:
            raise TypeError from err
    elif not can_hold_element(self._values, value):
        raise TypeError
    return value

@cache_readonly
def _is_memory_usage_qualified(self) -> bool:
    return is_object_dtype(self.dtype) or (is_string_dtype(self.dtype) and self.dtype.storage == 'python')

def __contains__(self, key: Any) -> bool:
    hash(key)
    try:
        return key in self._engine
    except (OverflowError, TypeError, ValueError):
        return False

def __getitem__(self, key: Any) -> Any:
    getitem = self._data.__getitem__
    key = lib.item_from_zerodim(key)
    if is_integer(key) or is_float(key):
        key = com.cast_scalar_indexer(key)
        return getitem(key)
    if isinstance(key, slice):
        return self._getitem_slice(key)
    if com.is_bool_indexer(key):
        if isinstance(getattr(key, 'dtype', None), ExtensionDtype):
            key = key.to_numpy(dtype=bool, na_value=False)
        else:
            key = np.asarray(key, dtype=bool)
        if not isinstance(self.dtype, ExtensionDtype):
            if len(key) == 0 and len(key) != len(self):
                raise ValueError('The length of the boolean indexer cannot be 0 when the Index has length greater than 0.')
    result = getitem(key)
    if result.ndim > 1:
        disallow_ndim_indexing(result)
    return self._constructor._simple_new(result, name=self._name)

@final
def _can_hold_identifiers_and_holds_name(self, name: Hashable) -> bool:
    if self.dtype == object or is_string_dtype(self.dtype) or isinstance(self.dtype, CategoricalDtype):
        return name in self
    return False

def append(self, other: Index | Sequence[Index]) -> Index:
    to_concat = [self]
    if isinstance(other, (list, tuple)):
        to_concat += list(other)
    else:
        to_concat.append(other)
    for obj in to_concat:
        if not isinstance(obj, Index):
            raise TypeError('all inputs must be Index')
    names = {obj.name for obj in to_concat}
    name = None if len(names) > 1 else self.name
    return self._concat(to_concat, name)

def _concat(self, to_concat: list[Index], name: Hashable) -> Index:
    to_concat_vals = [x._values for x in to_concat]
    result = concat_compat(to_concat_vals)
    return Index._with_infer(result, name=name, copy=False)

def putmask(self, mask: npt.NDArray[np.bool_], value: object) -> Index:
    mask, noop = validate_putmask(self._values, mask)
    if noop:
        return self.copy()
    return self.where(~mask, value)

def equals(self, other: Any) -> bool:
    if self.is_(other):
        return True
    if not isinstance(other, Index):
        return False
    if len(self) != len(other):
        return False
    if isinstance(self.dtype, StringDtype) and other.dtype != self.dtype:
        return other.equals(self.astype(object))
    if is_object_dtype(self.dtype) and (not is_object_dtype(other.dtype)):
        return other.equals(self)
    if isinstance(other, ABCMultiIndex):
        return other.equals(self)
    if isinstance(self._values, ExtensionArray):
        if not isinstance(other, type(self)):
            return False
        earr = cast('ExtensionArray', self._data)
        return earr.equals(other._data)
    if isinstance(other.dtype, ExtensionDtype):
        return other.equals(self)
    return array_equivalent(self._values, other._values)

@final
def identical(self, other: Index) -> bool:
    return self.equals(other) and all((getattr(self, c, None) == getattr(other, c, None) for c in self._comparables)) and (type(self) == type(other)) and (self.dtype == other.dtype)

@final
def asof(self, label: Hashable) -> Hashable:
    self._searchsorted_monotonic(label)
    try:
        loc = self.get_loc(label)
    except (KeyError, TypeError) as err:
        indexer = self.get_indexer([label], method='pad')
        if indexer.ndim > 1 or indexer.size > 1:
            raise TypeError('asof requires scalar valued input') from err
        loc = indexer.item()
        if loc == -1:
            return self._na_value
    else:
        if isinstance(loc, slice):
            return self[loc][-1]
    return self[loc]

def sort_values(self, *, return_indexer: bool=False, ascending: bool=True, na_position: NaPosition='last', key: Callable | None=None) -> Self | tuple[Self, np.ndarray]:
    if key is None and (ascending and self.is_monotonic_increasing or (not ascending and self.is_monotonic_decreasing)):
        if return_indexer:
            indexer = np.arange(len(self), dtype=np.intp)
            return (self.copy(), indexer)
        else:
            return self.copy()
    if not isinstance(self, ABCMultiIndex):
        _as = nargsort(items=self, ascending=ascending, na_position=na_position, key=key)
    else:
        idx = cast('Index', ensure_key_mapped(self, key))
        _as = idx.argsort(na_position=na_position)
        if not ascending:
            _as = _as[::-1]
    sorted_index = self.take(_as)
    if return_indexer:
        return (sorted_index, _as)
    else:
        return sorted_index

@cache_readonly
def _should_fallback_to_positional(self) -> bool:
    return self.inferred_type not in {'integer', 'mixed-integer', 'floating', 'complex'}

def get_indexer_non_unique(self, target: Axes) -> tuple[npt.NDArray[np.intp], npt.NDArray[np.intp]]:
    target = self._maybe_cast_listlike_indexer(target)
    if not self._should_compare(target) and (not self._should_partial_index(target)):
        return self._get_indexer_non_comparable(target, method=None, unique=False)
    pself, ptarget = self._maybe_downcast_for_indexing(target)
    if pself is not self or ptarget is not target:
        return pself.get_indexer_non_unique(ptarget)
    if self.dtype != target.dtype:
        dtype = self._find_common_type_compat(target)
        this = self.astype(dtype, copy=False)
        that = target.astype(dtype, copy=False)
        return this.get_indexer_non_unique(that)
    if self._is_multi and target._is_multi:
        engine = self._engine
        tgt_values = engine._extract_level_codes(target)
    else:
        tgt_values = target._get_engine_target()
    indexer, missing = self._engine.get_indexer_non_unique(tgt_values)
    return (ensure_platform_int(indexer), ensure_platform_int(missing))

@final
def get_indexer_for(self, target: Axes) -> npt.NDArray[np.intp]:
    if self._index_as_unique:
        return self.get_indexer(target)
    indexer, _ = self.get_indexer_non_unique(target)
    return indexer

def _get_indexer_strict(self, key: Axes, axis_name: str_t) -> tuple[Index, np.ndarray]:
    keyarr = key
    if not isinstance(keyarr, Index):
        keyarr = com.asarray_tuplesafe(keyarr)
    if self._index_as_unique:
        indexer = self.get_indexer_for(keyarr)
        if not isinstance(keyarr, Index):
            keyarr = ensure_index(keyarr)
            keyarr.name = self.name
    else:
        keyarr, indexer, new_indexer = self._reindex_non_unique(keyarr)
    self._raise_if_missing(keyarr, indexer, axis_name)
    keyarr = self.take(indexer)
    if lib.is_np_dtype(keyarr.dtype, 'mM') or isinstance(keyarr.dtype, DatetimeTZDtype):
        if isinstance(key, list) or (isinstance(key, type(self)) and key.freq is None):
            keyarr = keyarr._with_freq(None)
    return (keyarr, indexer)

def _raise_if_missing(self, key: Index, indexer: npt.NDArray[np.intp], axis_name: str_t) -> None:
    if len(key) == 0:
        return
    missing_mask = indexer < 0
    nmissing = missing_mask.sum()
    if nmissing:
        if nmissing == len(indexer):
            raise KeyError(f'None of [{key}] are in the [{axis_name}]')
        not_found = list(ensure_index(key)[missing_mask.nonzero()[0]].unique())
        raise KeyError(f'{not_found} not in index')

@final
def _get_indexer_non_comparable(self, target: Index, method: str_t | None, unique: bool=True) -> npt.NDArray[np.intp] | tuple[npt.NDArray[np.intp], npt.NDArray[np.intp]]:
    if method is not None:
        other_dtype = _unpack_nested_dtype(target)
        raise TypeError(f'Cannot compare dtypes {self.dtype} and {other_dtype}')
    no_matches = -1 * np.ones(target.shape, dtype=np.intp)
    if unique:
        return no_matches
    else:
        missing = np.arange(len(target), dtype=np.intp)
        return (no_matches, missing)

@property
def _index_as_unique(self) -> bool:
    return self.is_unique

@final
def _maybe_downcast_for_indexing(self, other: Index) -> tuple[Index, Index]:
    if isinstance(self, ABCDatetimeIndex) and isinstance(other, ABCDatetimeIndex):
        if self.tz is not None and other.tz is not None and (not tz_compare(self.tz, other.tz)):
            return (self.tz_convert('UTC'), other.tz_convert('UTC'))
    elif self.inferred_type == 'date' and isinstance(other, ABCDatetimeIndex):
        try:
            result = (type(other)(self), other)
        except OutOfBoundsDatetime:
            return (self, other)
        else:
            warnings.warn('Indexing a DatetimeIndex with a sequence of datetime.date objects is deprecated. Use Timestamp objects instead.', Pandas4Warning, stacklevel=find_stack_level())
            return result
    elif self.inferred_type == 'timedelta' and isinstance(other, ABCTimedeltaIndex):
        return (type(other)(self), other)
    elif self.dtype.kind == 'u' and other.dtype.kind == 'i':
        if other.min() >= 0:
            return (self, other.astype(self.dtype))
    elif self._is_multi and (not other._is_multi):
        try:
            other = type(self).from_tuples(other)
        except (TypeError, ValueError):
            self = Index(self._values, copy=False)
    if not is_object_dtype(self.dtype) and is_object_dtype(other.dtype):
        other, self = other._maybe_downcast_for_indexing(self)
    return (self, other)

@final
def _find_common_type_compat(self, target: Any) -> DtypeObj:
    target_dtype, _ = infer_dtype_from(target)
    if isinstance(target, tuple):
        return np.dtype(object)
    if using_string_dtype():
        from pandas.core.indexes.range import RangeIndex
        if len(self) == 0 and (isinstance(self, RangeIndex) or self.dtype == np.object_):
            return target_dtype
        if isinstance(target, Index) and len(target) == 0 and (isinstance(target, RangeIndex) or target_dtype == np.object_):
            return self.dtype
    if self.dtype == 'uint64' or target_dtype == 'uint64':
        if is_signed_integer_dtype(self.dtype) or is_signed_integer_dtype(target_dtype):
            return _dtype_obj
    dtype = find_result_type(self.dtype, target)
    dtype = common_dtype_categorical_compat([self, target], dtype)
    return dtype

@final
def _should_compare(self, other: Index) -> bool:
    if other.inferred_type == 'boolean' and is_any_real_numeric_dtype(self.dtype) or (self.inferred_type == 'boolean' and is_any_real_numeric_dtype(other.dtype)):
        return False
    dtype = _unpack_nested_dtype(other)
    return self._is_comparable_dtype(dtype) or is_object_dtype(dtype) or is_string_dtype(dtype)

def _is_comparable_dtype(self, dtype: DtypeObj) -> bool:
    if self.dtype.kind == 'b':
        return dtype.kind == 'b'
    elif is_numeric_dtype(self.dtype):
        return is_numeric_dtype(dtype)
    return True

@final
def groupby(self, values: Axes) -> PrettyDict[Hashable, Index]:
    if isinstance(values, ABCMultiIndex):
        values = values._values
    values = Categorical(values)
    result = values._reverse_indexer()
    result = {k: self.take(v) for k, v in result.items()}
    return PrettyDict(result)

def map(self, mapper: Callable | dict | Series, na_action: Literal['ignore'] | None=None) -> Index:
    from pandas.core.indexes.multi import MultiIndex
    new_values = self._map_values(mapper, na_action=na_action)
    if new_values.size and isinstance(new_values[0], tuple):
        if isinstance(self, MultiIndex):
            names = self.names
        elif self.name:
            names = [self.name] * len(new_values[0])
        else:
            names = None
        return MultiIndex.from_tuples(new_values, names=names)
    dtype = None
    if not new_values.size:
        dtype = self.dtype
    elif isinstance(new_values, Categorical):
        dtype = new_values.dtype
    else:
        if isinstance(self, MultiIndex):
            arr = self[:0].to_flat_index().array
        else:
            arr = self[:0].array
        new_values = arr._cast_pointwise_result(new_values)
        dtype = new_values.dtype
    return Index(new_values, dtype=dtype, copy=False, name=self.name)

def replace(self, to_replace: Any=None, value: Any=lib.no_default, regex: bool=False) -> Index:
    if self._is_multi:
        raise NotImplementedError('replace is not implemented for MultiIndex')
    ser = self.to_series()
    replaced = ser.replace(to_replace, value, regex=regex)
    return self._shallow_copy(replaced._values, name=self.name)

@final
def _transform_index(self, func: Callable, *, level: int | None=None) -> Index:
    if isinstance(self, ABCMultiIndex):
        values = [self.get_level_values(i).map(func) if i == level or level is None else self.get_level_values(i) for i in range(self.nlevels)]
        return type(self).from_arrays(values)
    else:
        items = [func(x) for x in self]
        if not items:
            return Index(items, dtype=self.dtype, name=self.name, tupleize_cols=False)
        new_values = self.array._cast_pointwise_result(items)
        return Index(new_values, dtype=new_values.dtype, copy=False, name=self.name, tupleize_cols=False)

def isin(self, values: Axes | set, level: str_t | int | None=None) -> npt.NDArray[np.bool_]:
    if level is not None:
        self._validate_index_level(level)
    return algos.isin(self._values, values)

def slice_indexer(self, start: Hashable | None=None, end: Hashable | None=None, step: int | None=None) -> slice:
    start_slice, end_slice = self.slice_locs(start, end, step=step)
    if not is_scalar(start_slice):
        raise AssertionError('Start slice bound is non-scalar')
    if not is_scalar(end_slice):
        raise AssertionError('End slice bound is non-scalar')
    return slice(start_slice, end_slice, step)

def _maybe_cast_indexer(self, key: Hashable) -> Hashable:
    if is_float(key) and np.isnan(key) and isinstance(self.dtype, FloatingDtype) and is_nan_na():
        key = self.dtype.na_value
    return key

def _maybe_cast_listlike_indexer(self, target: Axes) -> Index:
    target_index = ensure_index(target)
    if not hasattr(target, 'dtype') and self.dtype == object and (target_index.dtype == 'string'):
        target_index = Index(target, dtype=self.dtype)
    elif not hasattr(target, 'dtype') and isinstance(self.dtype, StringDtype) and (self.dtype.na_value is np.nan) and using_string_dtype():
        target_index = target_index.fillna(np.nan)
    return target_index

@final
def _validate_indexer(self, form: Literal['positional', 'slice'], key: object, kind: Literal['getitem', 'iloc']) -> None:
    if not lib.is_int_or_none(key):
        self._raise_invalid_indexer(form, key)

def _maybe_cast_slice_bound(self, label: Hashable, side: str_t) -> Hashable:
    if is_numeric_dtype(self.dtype):
        return self._maybe_cast_indexer(label)
    if (is_float(label) or is_integer(label)) and label not in self:
        self._raise_invalid_indexer('slice', label)
    return label

def get_slice_bound(self, label: Hashable, side: Literal['left', 'right']) -> int:
    if side not in ('left', 'right'):
        raise ValueError(f"Invalid value for side kwarg, must be either 'left' or 'right': {side}")
    original_label = label
    label = self._maybe_cast_slice_bound(label, side)
    try:
        slc = self.get_loc(label)
    except KeyError:
        try:
            return self._searchsorted_monotonic(label, side)
        except ValueError:
            raise KeyError(f'Cannot get {side} slice bound for non-monotonic index with a missing label {original_label!r}. Either sort the index or specify an existing label.') from None
    if isinstance(slc, np.ndarray):
        assert is_bool_dtype(slc.dtype)
        slc = lib.maybe_booleans_to_slice(slc.view('u1'))
        if isinstance(slc, np.ndarray):
            raise KeyError(f'Cannot get {side} slice bound for non-unique label: {original_label!r}')
    if isinstance(slc, slice):
        if side == 'left':
            return slc.start
        else:
            return slc.stop
    elif side == 'right':
        return slc + 1
    else:
        return slc

def slice_locs(self, start: SliceType=None, end: SliceType=None, step: int | None=None) -> tuple[int, int]:
    inc = step is None or step >= 0
    if not inc:
        start, end = (end, start)
    if isinstance(start, (str, datetime)) and isinstance(end, (str, datetime)):
        try:
            ts_start = Timestamp(start)
            ts_end = Timestamp(end)
        except (ValueError, TypeError):
            pass
        else:
            if not tz_compare(ts_start.tzinfo, ts_end.tzinfo):
                raise ValueError('Both dates must have the same UTC offset')
    start_slice = None
    if start is not None:
        start_slice = self.get_slice_bound(start, 'left')
    if start_slice is None:
        start_slice = 0
    end_slice = None
    if end is not None:
        end_slice = self.get_slice_bound(end, 'right')
    if end_slice is None:
        end_slice = len(self)
    if not inc:
        end_slice, start_slice = (start_slice - 1, end_slice - 1)
        if end_slice == -1:
            end_slice -= len(self)
        if start_slice == -1:
            start_slice -= len(self)
    start_slice = maybe_unbox_numpy_scalar(start_slice)
    end_slice = maybe_unbox_numpy_scalar(end_slice)
    return (start_slice, end_slice)

def delete(self, loc: int | np.integer | list[int] | npt.NDArray[np.integer]) -> Self:
    values = self._values
    res_values: ArrayLike
    if isinstance(values, np.ndarray):
        res_values = np.delete(values, loc)
    else:
        res_values = values.delete(loc)
    return self._constructor._simple_new(res_values, name=self.name)

def insert(self, loc: int, item: Hashable) -> Index:
    item = lib.item_from_zerodim(item)
    if is_valid_na_for_dtype(item, self.dtype) and self.dtype != object:
        item = self._na_value
    arr = self._values
    if using_string_dtype() and len(self) == 0 and (self.dtype == np.object_):
        dtype = self._find_common_type_compat(item)
        if dtype != self.dtype:
            return self.astype(dtype).insert(loc, item)
    try:
        if isinstance(arr, ExtensionArray):
            res_values = arr.insert(loc, item)
            return type(self)._simple_new(res_values, name=self.name)
        else:
            item = self._validate_fill_value(item)
    except (TypeError, ValueError, LossySetitemError):
        dtype = self._find_common_type_compat(item)
        if dtype == self.dtype:
            raise
        return self.astype(dtype).insert(loc, item)
    if arr.dtype != object or not isinstance(item, (tuple, np.datetime64, np.timedelta64)):
        casted = arr.dtype.type(item)
        new_values = np.insert(arr, loc, casted)
    else:
        new_values = np.insert(arr, loc, None)
        loc = loc if loc >= 0 else loc - 1
        new_values[loc] = item
    out = Index(new_values, dtype=new_values.dtype, name=self.name, copy=False)
    return out

def drop(self, labels: Index | np.ndarray | Iterable[Hashable], errors: IgnoreRaise='raise') -> Index:
    if not isinstance(labels, Index):
        arr_dtype = 'object' if self.dtype == 'object' else None
        labels = com.index_labels_to_array(labels, dtype=arr_dtype)
    indexer = self.get_indexer_for(labels)
    mask = indexer == -1
    if mask.any():
        if errors != 'ignore':
            raise KeyError(f'{labels[mask].tolist()} not found in axis')
        indexer = indexer[~mask]
    return self.delete(indexer)

@final
def infer_objects(self, copy: bool=True) -> Index:
    if self._is_multi:
        raise NotImplementedError('infer_objects is not implemented for MultiIndex. Use index.to_frame().infer_objects() instead.')
    if self.dtype != object:
        return self.copy() if copy else self
    values = self._values
    values = cast('npt.NDArray[np.object_]', values)
    res_values = lib.maybe_convert_objects(values, convert_non_numeric=True)
    if copy and res_values is values:
        return self.copy()
    result = Index(res_values, name=self.name, copy=False)
    if not copy and res_values is values and (self._references is not None):
        result._references = self._references
        result._references.add_index_reference(result)
    return result

@final
def diff(self, periods: int=1) -> Index:
    return Index(self.to_series().diff(periods))

def _cmp_method(self, other: object, op: Callable) -> Any:
    if isinstance(other, Index) and self.is_(other):
        if op in {operator.eq, operator.le, operator.ge}:
            arr = np.ones(len(self), dtype=bool)
            if self._can_hold_na and (not isinstance(self, ABCMultiIndex)):
                arr[self.isna()] = False
            return arr
        elif op is operator.ne:
            arr = np.zeros(len(self), dtype=bool)
            if self._can_hold_na and (not isinstance(self, ABCMultiIndex)):
                arr[self.isna()] = True
            return arr
    if isinstance(other, (np.ndarray, Index, ABCSeries, ExtensionArray)) and len(self) != len(other):
        raise ValueError('Lengths must match to compare')
    if not isinstance(other, ABCMultiIndex):
        other = extract_array(other, extract_numpy=True)
    else:
        other = np.asarray(other)
    result = ops.comparison_op(self._values, other, op)
    return result

def any(self, *args: Any, **kwargs: Any) -> Any:
    nv.validate_any(args, kwargs)
    self._maybe_disable_logical_methods('any')
    vals = self._values
    if not isinstance(vals, np.ndarray):
        return vals._reduce('any')
    return maybe_unbox_numpy_scalar(np.any(vals))

def all(self, *args: Any, **kwargs: Any) -> Any:
    nv.validate_all(args, kwargs)
    self._maybe_disable_logical_methods('all')
    vals = self._values
    if not isinstance(vals, np.ndarray):
        return vals._reduce('all')
    return maybe_unbox_numpy_scalar(np.all(vals))

@final
