        data, others = data.align(others, join=join)
        others = [others[x] for x in others]
    all_cols = [ensure_object(x) for x in [data, *others]]
    na_masks = np.array([isna(x) for x in all_cols])
    union_mask = np.logical_or.reduce(na_masks, axis=0)
    if na_rep is None and union_mask.any():
        result = np.empty(len(data), dtype=object)
        np.putmask(result, union_mask, np.nan)
        not_masked = ~union_mask
        result[not_masked] = cat_safe([x[not_masked] for x in all_cols], sep)
    elif na_rep is not None and union_mask.any():
        all_cols = [np.where(nm, na_rep, col) for nm, col in zip(na_masks, all_cols, strict=True)]
        result = cat_safe(all_cols, sep)
    else:
        result = cat_safe(all_cols, sep)
    out: Index | Series
    if isinstance(self._orig.dtype, CategoricalDtype):
        dtype = self._orig.dtype.categories.dtype
    else:
        dtype = self._orig.dtype
    if isinstance(self._orig, ABCIndex):
        if isna(result).all():
            dtype = object
        out = Index(result, dtype=dtype, name=self._orig.name, copy=False)
    else:
