        for j in numba.prange(len(cur)):
            if not np.isnan(weighted_avg[j]):
                if is_observations[j] or not ignore_na:
                    old_wt[j] *= old_wt_factor ** deltas[j - 1]
                    if is_observations[j]:
                        if weighted_avg[j] != cur[j]:
