@classmethod
def _convert_to_style_kwargs(cls, style_dict: dict[str, Serialisable]) -> dict[str, Serialisable]:
    _style_key_map = {'borders': 'border'}
    style_kwargs: dict[str, Serialisable] = {}
    for k, v in style_dict.items():
        k = _style_key_map.get(k, k)
        _conv_to_x = getattr(cls, f'_convert_to_{k}', lambda x: None)
        new_v = _conv_to_x(v)
        if new_v:
            style_kwargs[k] = new_v
    return style_kwargs

@classmethod
def _convert_to_color(cls, color_spec):
    from openpyxl.styles import Color
    if isinstance(color_spec, str):
        return Color(color_spec)
    else:
        return Color(**color_spec)

@classmethod
def _convert_to_font(cls, font_dict):
    from openpyxl.styles import Font
    _font_key_map = {'sz': 'size', 'b': 'bold', 'i': 'italic', 'u': 'underline', 'strike': 'strikethrough', 'vertalign': 'vertAlign'}
    font_kwargs = {}
    for k, v in font_dict.items():
        k = _font_key_map.get(k, k)
        if k == 'color':
            v = cls._convert_to_color(v)
        font_kwargs[k] = v
    return Font(**font_kwargs)

@classmethod
def _convert_to_stop(cls, stop_seq):
    return map(cls._convert_to_color, stop_seq)

@classmethod
def _convert_to_fill(cls, fill_dict: dict[str, Any]) -> Fill:
    from openpyxl.styles import GradientFill, PatternFill
    _pattern_fill_key_map = {'patternType': 'fill_type', 'patterntype': 'fill_type', 'fgColor': 'start_color', 'fgcolor': 'start_color', 'bgColor': 'end_color', 'bgcolor': 'end_color'}
    _gradient_fill_key_map = {'fill_type': 'type'}
    pfill_kwargs = {}
    gfill_kwargs = {}
    for k, v in fill_dict.items():
        pk = _pattern_fill_key_map.get(k)
        gk = _gradient_fill_key_map.get(k)
        if pk in ['start_color', 'end_color']:
            v = cls._convert_to_color(v)
        if gk == 'stop':
            v = cls._convert_to_stop(v)
        if pk:
            pfill_kwargs[pk] = v
        elif gk:
            gfill_kwargs[gk] = v
        else:
            pfill_kwargs[k] = v
            gfill_kwargs[k] = v
    try:
        return PatternFill(**pfill_kwargs)
    except TypeError:
        return GradientFill(**gfill_kwargs)

@classmethod
def _convert_to_side(cls, side_spec):
    from openpyxl.styles import Side
    _side_key_map = {'border_style': 'style'}
    if isinstance(side_spec, str):
        return Side(style=side_spec)
    side_kwargs = {}
    for k, v in side_spec.items():
        k = _side_key_map.get(k, k)
        if k == 'color':
            v = cls._convert_to_color(v)
        side_kwargs[k] = v
    return Side(**side_kwargs)

@classmethod
def _convert_to_border(cls, border_dict):
    from openpyxl.styles import Border
    _border_key_map = {'diagonalup': 'diagonalUp', 'diagonaldown': 'diagonalDown'}
    border_kwargs = {}
    for k, v in border_dict.items():
        k = _border_key_map.get(k, k)
        if k == 'color':
            v = cls._convert_to_color(v)
        if k in ['left', 'right', 'top', 'bottom', 'diagonal']:
            v = cls._convert_to_side(v)
        border_kwargs[k] = v
    return Border(**border_kwargs)

@classmethod
def _convert_to_alignment(cls, alignment_dict):
