def _num2excel(self, index: int) -> str:
    if index < 0:
        raise ValueError(f'Index cannot be negative: {index}')
    column_name = ''
    while index > 0 or not column_name:
        index, remainder = divmod(index, 26)
        column_name = chr(65 + remainder) + column_name
    return column_name

def write(self, writer: FilePath | WriteExcelBuffer | ExcelWriter, sheet_name: str='Sheet1', startrow: int=0, startcol: int=0, freeze_panes: tuple[int, int] | None=None, engine: str | None=None, storage_options: StorageOptions | None=None, engine_kwargs: dict | None=None) -> None:
    from pandas.io.excel import ExcelWriter
    num_rows, num_cols = self.df.shape
    if num_rows > self.max_rows or num_cols > self.max_cols:
        raise ValueError(f'This sheet is too large! Your sheet size is: {num_rows}, {num_cols} Max sheet size is: {self.max_rows}, {self.max_cols}')
    if self.autofilter:
        startrowsoffset = 1
        endrowsoffset = 1
        if num_cols == 0:
            indexoffset = 0
        elif self.index:
            indexoffset = 0
            if isinstance(self.df.index, MultiIndex):
                if self.merge_cells:
                    raise ValueError("Excel filters merged cells by showing only the first row. 'autofilter' and 'merge_cells' cannot be used simultaneously.")
                else:
                    indexoffset = self.df.index.nlevels - 1
            if isinstance(self.columns, MultiIndex):
                if self.merge_cells:
                    raise ValueError("Excel filters merged cells by showing only the first row. 'autofilter' and 'merge_cells' cannot be used simultaneously.")
                else:
                    startrowsoffset = self.columns.nlevels
                    endrowsoffset = self.columns.nlevels + 1
        else:
            indexoffset = -1
        start = f'{self._num2excel(startcol)}{startrow + startrowsoffset}'
        autofilter_end_column = self._num2excel(startcol + num_cols + indexoffset)
        end = f'{autofilter_end_column}{startrow + num_rows + endrowsoffset}'
        autofilter_range = f'{start}:{end}'
    else:
        autofilter_range = None
    if engine_kwargs is None:
        engine_kwargs = {}
    formatted_cells = self.get_formatted_cells()
    if isinstance(writer, ExcelWriter):
        need_save = False
    else:
        writer = ExcelWriter(writer, engine=engine, storage_options=storage_options, engine_kwargs=engine_kwargs)
        need_save = True
    try:
        writer._write_cells(formatted_cells, sheet_name, startrow=startrow, startcol=startcol, freeze_panes=freeze_panes, autofilter_range=autofilter_range)
    finally:
        if need_save:
            writer.close()

