def get_format_timedelta64(values: TimedeltaArray, na_rep: str | float='NaT', box: bool=False) -> Callable:
    even_days = values._is_dates_only
    if even_days:
        format = None
    else:
        format = 'long'

    def _formatter(x):
        if x is None or (is_scalar(x) and isna(x)):
            return na_rep
        if not isinstance(x, Timedelta):
            x = Timedelta(x)
        result = x._repr_base(format=format)
        if box:
            result = f"'{result}'"
        return result
    return _formatter

def _trim_zeros_single_float(str_float: str) -> str:
    str_float = str_float.rstrip('0')
    if str_float.endswith('.'):
        str_float += '0'
    return str_float

def _trim_zeros_float(str_floats: ArrayLike | list[str], decimal: str='.') -> list[str]:
    if decimal != '.':
        number_regex = re.compile(f'^\\s*[+-]?[0-9]+\\{decimal}[0-9]*$')
    else:
        number_regex = _NUMBER_WITH_DECIMAL_RE
    is_number = [number_regex.match(x) is not None for x in str_floats]
    if not any(is_number):
        return list(str_floats)
    trimmed = list(str_floats)
    while True:
        if not all((x.endswith('0') for x, is_num in zip(trimmed, is_number, strict=True) if is_num)):
            break
        trimmed = [x[:-1] if is_num else x for x, is_num in zip(trimmed, is_number, strict=True)]
    result = [x + '0' if is_num and x.endswith(decimal) else x for x, is_num in zip(trimmed, is_number, strict=True)]
    return result

