def do_adjust_figure(fig: Figure) -> bool:
    if not hasattr(fig, 'get_constrained_layout'):
        return False
    return not fig.get_constrained_layout()

def maybe_adjust_figure(fig: Figure, *args, **kwargs) -> None:
