@contextlib.contextmanager
def rewrite_exception(old_name: str, new_name: str) -> Generator[None]:
    try:
        yield
    except Exception as err:
        if not err.args:
            raise
        msg = str(err.args[0])
        msg = msg.replace(old_name, new_name)
        args: tuple[Any, ...] = (msg,)
        if len(err.args) > 1:
            args = args + err.args[1:]
        err.args = args
        raise

@contextlib.contextmanager
def rewrite_warning(target_message: str, target_category: type[Warning], new_message: str, new_category: type[Warning] | None=None) -> Generator[None]:
    if new_category is None:
        new_category = target_category
    with warnings.catch_warnings(record=True) as record:
        yield
    if len(record) > 0:
        match = re.compile(target_message)
        for warning in record:
            if warning.category is target_category and re.search(match, str(warning.message)):
                category = new_category
                message: Warning | str = new_message
            else:
                category, message = (warning.category, warning.message)
            warnings.warn_explicit(message=message, category=category, filename=warning.filename, lineno=warning.lineno)

