@contextmanager
def set_timezone(tz: str) -> Generator[None]:
    import time

    def setTZ(tz: str | None) -> None:
        if hasattr(time, 'tzset'):
            if tz is None:
                try:
                    del os.environ['TZ']
                except KeyError:
                    pass
            else:
                os.environ['TZ'] = tz
                if sys.platform != 'win32':
                    time.tzset()
    orig_tz = os.environ.get('TZ')
    setTZ(tz)
    try:
        yield
    finally:
        setTZ(orig_tz)

