@contextmanager
def assert_produces_warning(expected_warning: type[Warning] | bool | tuple[type[Warning], ...] | None=Warning, filter_level: Literal['error', 'ignore', 'always', 'default', 'module', 'once']='always', check_stacklevel: bool=True, raise_on_extra_warnings: bool=True, match: str | tuple[str | None, ...] | None=None, must_find_all_warnings: bool=True) -> Generator[list[warnings.WarningMessage]]:
    __tracebackhide__ = True
    with warnings.catch_warnings(record=True) as w:
        warnings.simplefilter(filter_level)
        try:
            yield w
        finally:
            if expected_warning:
                if isinstance(expected_warning, tuple) and must_find_all_warnings:
                    match = match if isinstance(match, tuple) else (match,) * len(expected_warning)
                    for warning_type, warning_match in zip(expected_warning, match, strict=True):
                        _assert_caught_expected_warnings(caught_warnings=w, expected_warning=warning_type, match=warning_match, check_stacklevel=check_stacklevel)
                else:
                    expected_warning = cast('Union[type[Warning], tuple[type[Warning], ...]]', expected_warning)
                    match = '|'.join((m for m in match if m)) if isinstance(match, tuple) else match
                    _assert_caught_expected_warnings(caught_warnings=w, expected_warning=expected_warning, match=match, check_stacklevel=check_stacklevel)
            if raise_on_extra_warnings:
                _assert_caught_no_extra_warnings(caught_warnings=w, expected_warning=expected_warning)

def maybe_produces_warning(warning: type[Warning], condition: bool, **kwargs: Any) -> AbstractContextManager:
    if condition:
        return assert_produces_warning(warning, **kwargs)
    else:
        return nullcontext()

def _assert_caught_expected_warnings(*, caught_warnings: Sequence[warnings.WarningMessage], expected_warning: type[Warning] | tuple[type[Warning], ...], match: str | None, check_stacklevel: bool) -> None:
    saw_warning = False
    matched_message = False
    unmatched_messages = []
    warning_name = tuple((x.__name__ for x in expected_warning)) if isinstance(expected_warning, tuple) else expected_warning.__name__
    for actual_warning in caught_warnings:
        if issubclass(actual_warning.category, expected_warning):
            saw_warning = True
            if check_stacklevel:
                _assert_raised_with_correct_stacklevel(actual_warning)
            if match is not None:
                if re.search(match, str(actual_warning.message)):
                    matched_message = True
                else:
                    unmatched_messages.append(actual_warning.message)
    if not saw_warning:
        raise AssertionError(f'Did not see expected warning of class {warning_name!r}')
    if match and (not matched_message):
        raise AssertionError(f"Did not see warning {warning_name!r} matching '{match}'. The emitted warning messages are {unmatched_messages}")

def _assert_caught_no_extra_warnings(*, caught_warnings: Sequence[warnings.WarningMessage], expected_warning: type[Warning] | bool | tuple[type[Warning], ...] | None) -> None:
    extra_warnings = []
    for actual_warning in caught_warnings:
        if _is_unexpected_warning(actual_warning, expected_warning):
            if actual_warning.category == ResourceWarning:
                if 'unclosed <ssl.SSLSocket' in str(actual_warning.message):
                    continue
                if any(('matplotlib' in mod for mod in sys.modules)):
                    continue
            if actual_warning.category == EncodingWarning:
                continue
            extra_warnings.append((actual_warning.category.__name__, actual_warning.message, actual_warning.filename, actual_warning.lineno))
    if extra_warnings:
        raise AssertionError(f'Caused unexpected warning(s): {extra_warnings!r}')

def _is_unexpected_warning(actual_warning: warnings.WarningMessage, expected_warning: type[Warning] | bool | tuple[type[Warning], ...] | None) -> bool:
    if actual_warning and (not expected_warning):
        return True
    expected_warning = cast('type[Warning]', expected_warning)
    return bool(not issubclass(actual_warning.category, expected_warning))

def box_expected(expected: Any, box_cls: Any, transpose: bool=True) -> Any:
    if box_cls is pd.array:
        if isinstance(expected, RangeIndex):
            expected = NumpyExtensionArray(np.asarray(expected._values))
        else:
            expected = pd.array(expected, copy=False)
    elif box_cls is Index:
        expected = Index(expected, copy=False)
    elif box_cls is Series:
        expected = Series(expected)
    elif box_cls is DataFrame:
        expected = Series(expected).to_frame()
        if transpose:
            expected = expected.T
            expected = pd.concat([expected] * 2, ignore_index=True)
    elif box_cls is np.ndarray or box_cls is np.array:
        expected = np.array(expected)
    elif box_cls is to_array:
        expected = to_array(expected)
    else:
        raise NotImplementedError(box_cls)
    return expected

