@staticmethod
def blog_add_posts(context):
    tag_expr = re.compile('<.*?>')
    posts = []
    if context['blog']['posts_path']:
        posts_path = context['source_path'] / context['blog']['posts_path']
        for fname in posts_path.iterdir():
            if fname.name.startswith('index.'):
                continue
            link = f"/{context['blog']['posts_path']}/{fname.stem}.html"
            md = markdown.Markdown(extensions=context['main']['markdown_extensions'])
            with fname.open(encoding='utf-8') as f:
                html = md.convert(f.read())
            title = md.Meta['title'][0]
            summary = re.sub(tag_expr, '', html)
            try:
                body_position = summary.index(title) + len(title)
            except ValueError as err:
                raise ValueError(f'Blog post "{fname}" should have a markdown header corresponding to its "Title" element "{title}"') from err
            summary = ' '.join(summary[body_position:].split(' ')[:30])
            posts.append({'title': title, 'author': context['blog']['author'], 'published': datetime.datetime.strptime(md.Meta['date'][0], '%Y-%m-%d'), 'feed': context['blog']['feed_name'], 'link': link, 'description': summary, 'summary': summary})
    for feed_url in context['blog']['feed']:
        feed_data = feedparser.parse(feed_url)
        for entry in feed_data.entries:
            published = datetime.datetime.fromtimestamp(time.mktime(entry.published_parsed))
            summary = re.sub(tag_expr, '', entry.summary)
            posts.append({'title': entry.title, 'author': entry.author, 'published': published, 'feed': feed_data['feed']['title'], 'link': entry.link, 'description': entry.description, 'summary': summary})
    posts.sort(key=operator.itemgetter('published'), reverse=True)
    context['blog']['posts'] = posts[:context['blog']['num_posts']]
    return context

@staticmethod
def maintainers_add_info(context):
    repeated = set(context['maintainers']['active']) & set(context['maintainers']['inactive'])
    if repeated:
        raise ValueError(f'Maintainers {repeated} are both active and inactive')
    maintainers_info = {}
    for user in context['maintainers']['active'] + context['maintainers']['inactive'] + context['maintainers']['pandasstubs']:
        resp = requests.get(f'https://api.github.com/users/{user}', headers=GITHUB_API_HEADERS, timeout=5)
        if resp.status_code == 403:
            sys.stderr.write('WARN: GitHub API quota exceeded when fetching maintainers\n')
            resp_bkp = requests.get(context['main']['production_url'] + 'maintainers.json', timeout=5)
            resp_bkp.raise_for_status()
            maintainers_info = resp_bkp.json()
            break
        resp.raise_for_status()
        maintainers_info[user] = resp.json()
    context['maintainers']['github_info'] = maintainers_info
    with open(pathlib.Path(context['target_path']) / 'maintainers.json', 'w', encoding='utf-8') as f:
        json.dump(maintainers_info, f)
    return context

@staticmethod
def roadmap_pdeps(context):
    KNOWN_STATUS = {'Draft', 'Under discussion', 'Accepted', 'Implemented', 'Rejected', 'Withdrawn'}
    context['pdeps'] = collections.defaultdict(list)
    pdeps_path = pathlib.Path(context['source_path']) / context['roadmap']['pdeps_path']
    for pdep in sorted(pdeps_path.iterdir()):
        if pdep.suffix != '.md':
            continue
        with pdep.open() as f:
            title = f.readline()[2:]
            status = None
            for line in f:
                if line.startswith('- Status: '):
                    status = line.strip().split(': ', 1)[1]
                    break
            if status not in KNOWN_STATUS:
                raise RuntimeError(f'PDEP "{pdep}" status "{status}" is unknown. Should be one of: {KNOWN_STATUS}')
        html_file = pdep.with_suffix('.html').name
        context['pdeps'][status].append({'title': title, 'url': f'pdeps/{html_file}'})
    github_repo_url = context['main']['github_repo_url']
    resp = requests.get(f'https://api.github.com/search/issues?q=is:pr is:open label:PDEP draft:false repo:{github_repo_url}', headers=GITHUB_API_HEADERS, timeout=5)
    if resp.status_code == 403:
        sys.stderr.write('WARN: GitHub API quota exceeded when fetching pdeps\n')
        resp_bkp = requests.get(context['main']['production_url'] + 'pdeps.json', timeout=5)
        resp_bkp.raise_for_status()
        pdeps = resp_bkp.json()
    else:
        resp.raise_for_status()
        pdeps = resp.json()
    with open(pathlib.Path(context['target_path']) / 'pdeps.json', 'w', encoding='utf-8') as f:
        json.dump(pdeps, f)
    compiled_pattern = re.compile('^PDEP-(\\d+)')

    def sort_pdep(pdep: dict) -> int:
        title = pdep['title']
        match = compiled_pattern.match(title)
        if not match:
            msg = f"Could not find PDEP number in '{title}'. Please make sure to\n                write the title as: 'PDEP-num: {title}'."
            raise ValueError(msg)
        return int(match[1])
    context['pdeps']['Under discussion'].extend(({'title': pdep['title'], 'url': pdep['html_url']} for pdep in sorted(pdeps['items'], key=sort_pdep)))
    return context

def proxy_manager_for(self, proxy: str, **proxy_kwargs: Any) -> Any:
    if proxy in self.proxy_manager:
        manager = self.proxy_manager[proxy]
    elif proxy.lower().startswith('socks'):
        username, password = get_auth_from_url(proxy)
        manager = self.proxy_manager[proxy] = SOCKSProxyManager(proxy, username=username, password=password, num_pools=self._pool_connections, maxsize=self._pool_maxsize, block=self._pool_block, **proxy_kwargs)
    else:
        proxy_headers = self.proxy_headers(proxy)
        manager = self.proxy_manager[proxy] = proxy_from_url(proxy, proxy_headers=proxy_headers, num_pools=self._pool_connections, maxsize=self._pool_maxsize, block=self._pool_block, **proxy_kwargs)
    return manager

def cert_verify(self, conn: Any, url: str, verify: _t.VerifyType, cert: _t.CertType) -> None:
    if url.lower().startswith('https') and verify:
        cert_loc = None
        if verify is not True:
            cert_loc = verify
        if not cert_loc:
            cert_loc = DEFAULT_CA_BUNDLE_PATH
        if not cert_loc or not os.path.exists(cert_loc):
            raise OSError(f'Could not find a suitable TLS CA certificate bundle, invalid path: {cert_loc}')
        conn.cert_reqs = 'CERT_REQUIRED'
        if not os.path.isdir(cert_loc):
            conn.ca_certs = cert_loc
        else:
            conn.ca_cert_dir = cert_loc
    else:
        conn.cert_reqs = 'CERT_NONE'
        conn.ca_certs = None
        conn.ca_cert_dir = None
    if cert:
        if not isinstance(cert, basestring):
            conn.cert_file = cert[0]
            conn.key_file = cert[1]
        else:
            conn.cert_file = cert
            conn.key_file = None
        if conn.cert_file and (not os.path.exists(conn.cert_file)):
            raise OSError(f'Could not find the TLS certificate file, invalid path: {conn.cert_file}')
        if conn.key_file and (not os.path.exists(conn.key_file)):
            raise OSError(f'Could not find the TLS key file, invalid path: {conn.key_file}')

def get_connection_with_tls_context(self, request: PreparedRequest, verify: _t.VerifyType, proxies: dict[str, str] | None=None, cert: _t.CertType=None) -> HTTPConnectionPool:
    assert _is_prepared(request)
    proxy = select_proxy(request.url, proxies)
    try:
        host_params, pool_kwargs = self.build_connection_pool_key_attributes(request, verify, cert)
    except ValueError as e:
        raise InvalidURL(e, request=request)
    if proxy:
        proxy = prepend_scheme_if_needed(proxy, 'http')
        proxy_url = parse_url(proxy)
        if not proxy_url.host:
            raise InvalidProxyURL('Please check proxy URL. It is malformed and could be missing the host.')
        proxy_manager = self.proxy_manager_for(proxy)
        conn = proxy_manager.connection_from_host(**host_params, pool_kwargs=pool_kwargs)
    else:
        conn = self.poolmanager.connection_from_host(**host_params, pool_kwargs=pool_kwargs)
    return conn

def close(self) -> None:
    self.poolmanager.clear()
    for proxy in self.proxy_manager.values():
        proxy.clear()

def proxy_headers(self, proxy: str) -> dict[str, str]:
    headers: dict[str, str] = {}
    username, password = get_auth_from_url(proxy)
    if username:
        headers['Proxy-Authorization'] = _basic_auth_str(username, password)
    return headers

def send(self, request: PreparedRequest, stream: bool=False, timeout: _t.TimeoutType=None, verify: _t.VerifyType=True, cert: _t.CertType=None, proxies: dict[str, str] | None=None) -> Response:
    assert _is_prepared(request)
    try:
        conn = self.get_connection_with_tls_context(request, verify, proxies=proxies, cert=cert)
    except LocationValueError as e:
        raise InvalidURL(e, request=request)
    self.cert_verify(conn, request.url, verify, cert)
    url = self.request_url(request, proxies)
    self.add_headers(request, stream=stream, timeout=timeout, verify=verify, cert=cert, proxies=proxies)
    chunked = not (request.body is None or 'Content-Length' in request.headers)
    if isinstance(timeout, tuple):
        try:
            connect, read = timeout
            resolved_timeout = TimeoutSauce(connect=connect, read=read)
        except ValueError:
            raise ValueError(f'Invalid timeout {timeout}. Pass a (connect, read) timeout tuple, or a single float to set both timeouts to the same value.')
    elif isinstance(timeout, TimeoutSauce):
        resolved_timeout = timeout
    else:
        resolved_timeout = TimeoutSauce(connect=timeout, read=timeout)
    try:
        resp = conn.urlopen(method=request.method, url=url, body=request.body, headers=request.headers, redirect=False, assert_same_host=False, preload_content=False, decode_content=False, retries=self.max_retries, timeout=resolved_timeout, chunked=chunked)
    except (ProtocolError, OSError) as err:
        raise ConnectionError(err, request=request)
    except MaxRetryError as e:
        if isinstance(e.reason, ConnectTimeoutError):
            if not isinstance(e.reason, NewConnectionError):
                raise ConnectTimeout(e, request=request)
        if isinstance(e.reason, ResponseError):
            raise RetryError(e, request=request)
        if isinstance(e.reason, _ProxyError):
            raise ProxyError(e, request=request)
        if isinstance(e.reason, _SSLError):
            raise SSLError(e, request=request)
        raise ConnectionError(e, request=request)
    except ClosedPoolError as e:
        raise ConnectionError(e, request=request)
    except _ProxyError as e:
        raise ProxyError(e)
    except (_SSLError, _HTTPError) as e:
        if isinstance(e, _SSLError):
            raise SSLError(e, request=request)
        elif isinstance(e, ReadTimeoutError):
            raise ReadTimeout(e, request=request)
        elif isinstance(e, _InvalidHeader):
            raise InvalidHeader(e, request=request)
        else:
            raise
    return self.build_response(request, resp)

def request(method: str, url: _t.UriType, **kwargs: Unpack[_t.RequestKwargs]) -> Response:
    with sessions.Session() as session:
        return session.request(method=method, url=url, **kwargs)

def head(url: _t.UriType, **kwargs: Unpack[_t.RequestKwargs]) -> Response:
    kwargs.setdefault('allow_redirects', False)
    return request('head', url, **kwargs)

def _basic_auth_str(username: bytes | str, password: bytes | str) -> str:
    if not isinstance(username, basestring):
        warnings.warn(f"Non-string usernames will no longer be supported in Requests 3.0.0. Please convert the object you've passed in ({username!r}) to a string or bytes object in the near future to avoid problems.", category=DeprecationWarning)
        username = str(username)
    if not isinstance(password, basestring):
        warnings.warn(f"Non-string passwords will no longer be supported in Requests 3.0.0. Please convert the object you've passed in ({type(password)!r}) to a string or bytes object in the near future to avoid problems.", category=DeprecationWarning)
        password = str(password)
    if isinstance(username, str):
        username = username.encode('latin1')
    if isinstance(password, str):
        password = password.encode('latin1')
    authstr = 'Basic ' + to_native_string(b64encode(b':'.join((username, password))).strip())
    return authstr

def build_digest_header(self, method: str, url: str) -> str | None:
    realm = self._thread_local.chal['realm']
    nonce = self._thread_local.chal['nonce']
    qop = self._thread_local.chal.get('qop')
    algorithm = self._thread_local.chal.get('algorithm')
    opaque = self._thread_local.chal.get('opaque')
    hash_utf8 = None
    if algorithm is None:
        _algorithm = 'MD5'
    else:
        _algorithm = algorithm.upper()
    if _algorithm == 'MD5' or _algorithm == 'MD5-SESS':

        def md5_utf8(x: str | bytes) -> str:
            if isinstance(x, str):
                x = x.encode('utf-8')
            return hashlib.md5(x, usedforsecurity=False).hexdigest()
        hash_utf8 = md5_utf8
    elif _algorithm == 'SHA':

        def sha_utf8(x: str | bytes) -> str:
            if isinstance(x, str):
                x = x.encode('utf-8')
            return hashlib.sha1(x, usedforsecurity=False).hexdigest()
        hash_utf8 = sha_utf8
    elif _algorithm == 'SHA-256':

        def sha256_utf8(x: str | bytes) -> str:
            if isinstance(x, str):
                x = x.encode('utf-8')
            return hashlib.sha256(x, usedforsecurity=False).hexdigest()
        hash_utf8 = sha256_utf8
    elif _algorithm == 'SHA-512':

        def sha512_utf8(x: str | bytes) -> str:
            if isinstance(x, str):
                x = x.encode('utf-8')
            return hashlib.sha512(x, usedforsecurity=False).hexdigest()
        hash_utf8 = sha512_utf8
    if hash_utf8 is None:
        return None

    def KD(s: str, d: str) -> str:
        return hash_utf8(f'{s}:{d}')
    entdig = None
    p_parsed = urlparse(url)
    path = p_parsed.path or '/'
    if p_parsed.query:
        path += f'?{p_parsed.query}'
    A1 = f'{self.username}:{realm}:{self.password}'
    A2 = f'{method}:{path}'
    HA1 = hash_utf8(A1)
    HA2 = hash_utf8(A2)
    if nonce == self._thread_local.last_nonce:
        self._thread_local.nonce_count += 1
    else:
        self._thread_local.nonce_count = 1
    ncvalue = f'{self._thread_local.nonce_count:08x}'
    s = str(self._thread_local.nonce_count).encode('utf-8')
    s += nonce.encode('utf-8')
    s += time.ctime().encode('utf-8')
    s += os.urandom(8)
    cnonce = hashlib.sha1(s, usedforsecurity=False).hexdigest()[:16]
    if _algorithm == 'MD5-SESS':
        HA1 = hash_utf8(f'{HA1}:{nonce}:{cnonce}')
    if not qop:
        respdig = KD(HA1, f'{nonce}:{HA2}')
    elif qop == 'auth' or 'auth' in qop.split(','):
        noncebit = f'{nonce}:{ncvalue}:{cnonce}:auth:{HA2}'
        respdig = KD(HA1, noncebit)
    else:
        return None
    self._thread_local.last_nonce = nonce
    base = f'username="{self.username}", realm="{realm}", nonce="{nonce}", uri="{path}", response="{respdig}"'
    if opaque:
        base += f', opaque="{opaque}"'
    if algorithm:
        base += f', algorithm="{algorithm}"'
    if entdig:
        base += f', digest="{entdig}"'
    if qop:
        base += f', qop="auth", nc={ncvalue}, cnonce="{cnonce}"'
    return f'Digest {base}'

def handle_redirect(self, r: Response, **kwargs: Any) -> None:
    if r.is_redirect:
        self._thread_local.num_401_calls = 1

def _resolve_char_detection() -> ModuleType | None:
    chardet = None
    for lib in ('chardet', 'charset_normalizer'):
        if chardet is None:
            try:
                chardet = importlib.import_module(lib)
            except ImportError:
                pass
    return chardet

def extract_cookies_to_jar(jar: CookieJar, request: PreparedRequest, response: Any) -> None:
    if not (hasattr(response, '_original_response') and response._original_response):
        return
    req = MockRequest(request)
    res = MockResponse(response._original_response.msg)
    jar.extract_cookies(res, req)

def get_cookie_header(jar: CookieJar, request: PreparedRequest) -> str | None:
    r = MockRequest(request)
    jar.add_cookie_header(r)
    return r.get_new_headers().get('Cookie')

def remove_cookie_by_name(cookiejar: CookieJar, name: str, domain: str | None=None, path: str | None=None) -> None:
    clearables: list[tuple[str, str, str]] = []
    for cookie in cookiejar:
        if cookie.name != name:
            continue
        if domain is not None and domain != cookie.domain:
            continue
        if path is not None and path != cookie.path:
            continue
        clearables.append((cookie.domain, cookie.path, cookie.name))
    for domain, path, name in clearables:
        cookiejar.clear(domain, path, name)

def create_cookie(name: str, value: str, **kwargs: Any) -> Cookie:
    result: dict[str, Any] = {'version': 0, 'name': name, 'value': value, 'port': None, 'domain': '', 'path': '/', 'secure': False, 'expires': None, 'discard': True, 'comment': None, 'comment_url': None, 'rest': {'HttpOnly': None}, 'rfc2109': False}
    badargs = set(kwargs) - set(result)
    if badargs:
        raise TypeError(f'create_cookie() got unexpected keyword arguments: {list(badargs)}')
    result.update(kwargs)
    result['port_specified'] = bool(result['port'])
    result['domain_specified'] = bool(result['domain'])
    result['domain_initial_dot'] = result['domain'].startswith('.')
    result['path_specified'] = bool(result['path'])
    return cookielib.Cookie(**result)

def morsel_to_cookie(morsel: Morsel[Any]) -> Cookie:
    expires: int | None = None
    if morsel['max-age']:
        try:
            expires = int(time.time() + int(morsel['max-age']))
        except ValueError:
            raise TypeError(f"max-age: {morsel['max-age']} must be integer")
    elif morsel['expires']:
        time_template = '%a, %d-%b-%Y %H:%M:%S GMT'
        expires = calendar.timegm(time.strptime(morsel['expires'], time_template))
    return create_cookie(comment=morsel['comment'], comment_url=bool(morsel['comment']), discard=False, domain=morsel['domain'], expires=expires, name=morsel.key, path=morsel['path'], port=None, rest={'HttpOnly': morsel['httponly']}, rfc2109=False, secure=bool(morsel['secure']), value=morsel.value, version=morsel['version'] or 0)

def cookiejar_from_dict(cookie_dict: dict[str, str] | None, cookiejar: CookieJar | None=None, overwrite: bool=True) -> CookieJar:
    if cookiejar is None:
        cookiejar = RequestsCookieJar()
    if cookie_dict is not None:
        names_from_jar = [cookie.name for cookie in cookiejar]
        for name in cookie_dict:
            if overwrite or name not in names_from_jar:
                cookiejar.set_cookie(create_cookie(name, cookie_dict[name]))
    return cookiejar

def merge_cookies(cookiejar: CookieJar, cookies: dict[str, str] | CookieJar | None) -> CookieJar:
    if not isinstance(cookiejar, cookielib.CookieJar):
        raise ValueError('You can only merge into CookieJar')
    if isinstance(cookies, dict):
        cookiejar = cookiejar_from_dict(cookies, cookiejar=cookiejar, overwrite=False)
    elif isinstance(cookies, cookielib.CookieJar):
        if (update_method := getattr(cookiejar, 'update', None)):
            update_method(cookies)
        else:
            for cookie_in_jar in cookies:
                cookiejar.set_cookie(cookie_in_jar)
    return cookiejar

def get(self, name: str, default: str | None=None, domain: str | None=None, path: str | None=None) -> str | None:
    try:
        return self._find_no_duplicates(name, domain, path)
    except KeyError:
        return default

def set(self, name: str, value: str | Morsel[dict[str, str]] | None, **kwargs: Any) -> Cookie | None:
    if value is None:
        remove_cookie_by_name(self, name, domain=kwargs.get('domain'), path=kwargs.get('path'))
        return
    if isinstance(value, Morsel):
        c = morsel_to_cookie(value)
    else:
        c = create_cookie(name, value, **kwargs)
    self.set_cookie(c)
    return c

def iterkeys(self) -> Iterator[str]:
    for cookie in iter(self):
        yield cookie.name

def itervalues(self) -> Iterator[str | None]:
    for cookie in iter(self):
        yield cookie.value

def iteritems(self) -> Iterator[tuple[str, str | None]]:
    for cookie in iter(self):
        yield (cookie.name, cookie.value)

def list_domains(self) -> list[str]:
    domains: list[str] = []
    for cookie in iter(self):
        if cookie.domain not in domains:
            domains.append(cookie.domain)
    return domains

def list_paths(self) -> list[str]:
    paths: list[str] = []
    for cookie in iter(self):
        if cookie.path not in paths:
            paths.append(cookie.path)
    return paths

def multiple_domains(self) -> bool:
    domains: list[str] = []
    for cookie in iter(self):
        if cookie.domain is not None and cookie.domain in domains:
            return True
        domains.append(cookie.domain)
    return False

def get_dict(self, domain: str | None=None, path: str | None=None) -> dict[str, str | None]:
    dictionary: dict[str, str | None] = {}
    for cookie in iter(self):
        if (domain is None or cookie.domain == domain) and (path is None or cookie.path == path):
            dictionary[cookie.name] = cookie.value
    return dictionary

def update(self, other: CookieJar | SupportsKeysAndGetItem[str, str]) -> None:
    if isinstance(other, cookielib.CookieJar):
        for cookie in other:
            self.set_cookie(copy.copy(cookie))
    else:
        super().update(other)

def _find(self, name: str, domain: str | None=None, path: str | None=None) -> str | None:
    for cookie in iter(self):
        if cookie.name == name:
            if domain is None or cookie.domain == domain:
                if path is None or cookie.path == path:
                    return cookie.value
    raise KeyError(f'name={name!r}, domain={domain!r}, path={path!r}')

def _find_no_duplicates(self, name: str, domain: str | None=None, path: str | None=None) -> str:
    toReturn = None
    for cookie in iter(self):
        if cookie.name == name:
            if domain is None or cookie.domain == domain:
                if path is None or cookie.path == path:
                    if toReturn is not None:
                        raise CookieConflictError(f'There are multiple cookies with name, {name!r}')
                    toReturn = cookie.value
    if toReturn is not None:
        return toReturn
    raise KeyError(f'name={name!r}, domain={domain!r}, path={path!r}')

def __setstate__(self, state: dict[str, Any]) -> None:
    self.__dict__.update(state)
    if '_cookies_lock' not in self.__dict__:
        self._cookies_lock = threading.RLock()

def __init__(self, *args: Any, **kwargs: Any) -> None:
    CompatJSONDecodeError.__init__(self, *args)
    InvalidJSONError.__init__(self, *self.args, **kwargs)

def _implementation():
    implementation = platform.python_implementation()
    if implementation == 'CPython':
        implementation_version = platform.python_version()
    elif implementation == 'PyPy':
        pypy = sys.pypy_version_info
        implementation_version = f'{pypy.major}.{pypy.minor}.{pypy.micro}'
        if sys.pypy_version_info.releaselevel != 'final':
            implementation_version = ''.join([implementation_version, sys.pypy_version_info.releaselevel])
    elif implementation == 'Jython':
        implementation_version = platform.python_version()
    elif implementation == 'IronPython':
        implementation_version = platform.python_version()
    else:
        implementation_version = 'Unknown'
    return {'name': implementation, 'version': implementation_version}

def info() -> dict[str, Any]:
    try:
        platform_info = {'system': platform.system(), 'release': platform.release()}
    except OSError:
        platform_info = {'system': 'Unknown', 'release': 'Unknown'}
    implementation_info = _implementation()
    urllib3_info = {'version': urllib3.__version__}
    charset_normalizer_info = {'version': None}
    chardet_info: dict[str, str | None] = {'version': None}
    if charset_normalizer:
        charset_normalizer_info = {'version': charset_normalizer.__version__}
    if chardet:
        chardet_info = {'version': chardet.__version__}
    pyopenssl_info: dict[str, str | None] = {'version': None, 'openssl_version': ''}
    if OpenSSL:
        pyopenssl_info = {'version': OpenSSL.__version__, 'openssl_version': f'{OpenSSL.SSL.OPENSSL_VERSION_NUMBER:x}'}
    cryptography_info = {'version': getattr(cryptography, '__version__', '')}
    idna_info = {'version': getattr(idna, '__version__', '')}
    system_ssl = ssl.OPENSSL_VERSION_NUMBER
    system_ssl_info = {'version': f'{system_ssl:x}' if system_ssl is not None else ''}
    return {'platform': platform_info, 'implementation': implementation_info, 'system_ssl': system_ssl_info, 'using_pyopenssl': pyopenssl is not None, 'using_charset_normalizer': chardet is None, 'pyOpenSSL': pyopenssl_info, 'urllib3': urllib3_info, 'chardet': chardet_info, 'charset_normalizer': charset_normalizer_info, 'cryptography': cryptography_info, 'idna': idna_info, 'requests': {'version': requests_version}}

def dispatch_hook(key: str, hooks: _t.HooksInputType | None, hook_data: Response, **kwargs: Any) -> Response:
    hooks_dict = hooks or {}
    hook_list: Iterable[_t.HookType] | _t.HookType | None = hooks_dict.get(key)
    if hook_list:
        if isinstance(hook_list, Callable):
            hook_list = [hook_list]
        for hook in hook_list:
            _hook_data = hook(hook_data, **kwargs)
            if _hook_data is not None:
                hook_data = _hook_data
    return hook_data

@property
def path_url(self) -> str:
    url: list[str] = []
    p = urlsplit(cast(str, self.url))
    path = p.path
    if not path:
        path = '/'
    url.append(path)
    query = p.query
    if query:
        url.append('?')
        url.append(query)
    return ''.join(url)

@staticmethod
def _encode_params(data: _t.EncodableDataType) -> str | bytes | _t.SupportsRead[str | bytes]:
    if isinstance(data, (str, bytes)):
        return data
    elif _t.has_read(data):
        return data
    elif hasattr(data, '__iter__'):
        result: list[tuple[bytes, bytes]] = []
        for k, vs in to_key_val_list(data):
            if isinstance(vs, basestring) or not hasattr(vs, '__iter__'):
                vs = [vs]
            for v in vs:
                if v is not None:
                    result.append((k.encode('utf-8') if isinstance(k, str) else k, v.encode('utf-8') if isinstance(v, str) else v))
        return urlencode(result, doseq=True)
    else:
        return data

@staticmethod
def _encode_files(files: _t.FilesType, data: _t.RawDataType | None) -> tuple[bytes, str]:
    if not files:
        raise ValueError('Files must be provided.')
    elif isinstance(data, basestring):
        raise ValueError('Data must not be a string.')
    new_fields: list[RequestField | tuple[str, bytes]] = []
    fields = to_key_val_list(data or {})
    files = to_key_val_list(files or {})
    for field, val in fields:
        if isinstance(val, basestring) or not hasattr(val, '__iter__'):
            val = [val]
        for v in val:
            if v is not None:
                if not isinstance(v, bytes):
                    v = str(v)
                new_fields.append((field.decode('utf-8') if isinstance(field, bytes) else field, v.encode('utf-8') if isinstance(v, str) else v))
    for k, v in files:
        ft = None
        fh = None
        if isinstance(v, (tuple, list)):
            if len(v) == 2:
                fn, fp = v
            elif len(v) == 3:
                fn, fp, ft = v
            else:
                fn, fp, ft, fh = v
        else:
            fn = guess_filename(v) or k
            fp = v
        if isinstance(fp, (str, bytes, bytearray)):
            fdata = fp
        elif _t.has_read(fp):
            fdata = fp.read()
        elif fp is None:
            continue
        else:
            fdata = fp
        rf = RequestField(name=k, data=fdata, filename=fn, headers=fh)
        rf.make_multipart(content_type=ft)
        new_fields.append(rf)
    body, content_type = encode_multipart_formdata(new_fields)
    return (body, content_type)

def register_hook(self, event: str, hook: Iterable[_t.HookType] | _t.HookType) -> None:
    if event not in self.hooks:
        raise ValueError(f'Unsupported event specified, with event name "{event}"')
    if isinstance(hook, Callable):
        self.hooks[event].append(hook)
    elif hasattr(hook, '__iter__'):
        self.hooks[event].extend((h for h in hook if isinstance(h, Callable)))

def deregister_hook(self, event: str, hook: _t.HookType) -> bool:
    try:
        self.hooks[event].remove(hook)
        return True
    except ValueError:
        return False

def prepare_method(self, method: str | None) -> None:
    self.method = method
    if self.method is not None:
        self.method = to_native_string(self.method.upper())

def prepare_url(self, url: _t.UriType, params: _t.ParamsType) -> None:
    if isinstance(url, bytes):
        url = url.decode('utf8')
    else:
        url = str(url)
    url = url.lstrip()
    if ':' in url and (not url.lower().startswith('http')):
        self.url = url
        return
    try:
        scheme, auth, host, port, path, query, fragment = parse_url(url)
    except LocationParseError as e:
        raise InvalidURL(*e.args)
    if not scheme:
        raise MissingSchema(f'Invalid URL {url!r}: No scheme supplied. Perhaps you meant https://{url}?')
    if not host:
        raise InvalidURL(f'Invalid URL {url!r}: No host supplied')
    if not unicode_is_ascii(host):
        try:
            host = self._get_idna_encoded_host(host)
        except UnicodeError:
            raise InvalidURL('URL has an invalid label.')
    elif host.startswith(('*', '.')):
        raise InvalidURL('URL has an invalid label.')
    netloc = auth or ''
    if netloc:
        netloc += '@'
    netloc += host
    if port:
        netloc += f':{port}'
    if not path:
        path = '/'
    if isinstance(params, (str, bytes)):
        params = to_native_string(params)
    if params is not None:
        enc_params = self._encode_params(params)
    else:
        enc_params = ''
    if enc_params:
        if query:
            query = f'{query}&{enc_params}'
        else:
            query = enc_params
    url = requote_uri(urlunparse((scheme, netloc, path, '', query, fragment)))
    self.url = url

def prepare_headers(self, headers: Mapping[str, str | bytes] | None) -> None:
    self.headers = CaseInsensitiveDict()
    if headers:
        for header in headers.items():
            check_header_validity(header)
            name, value = header
            self.headers[to_native_string(name)] = value

def prepare_body(self, data: _t.DataType, files: _t.FilesType, json: _t.JsonType=None) -> None:
    body = None
    content_type = None
    if not data and json is not None:
        content_type = 'application/json'
        try:
            body = complexjson.dumps(json, allow_nan=False)
        except ValueError as ve:
            raise InvalidJSONError(ve, request=self)
        if not isinstance(body, bytes):
            body = body.encode('utf-8')
    is_iterable = isinstance(data, Iterable) or hasattr(data, '__iter__')
    if is_iterable and (not isinstance(data, (str, bytes, list, tuple, Mapping))):
        try:
            length = super_len(data)
        except (TypeError, AttributeError, UnsupportedOperation):
            length = None
        body = data
        if getattr(body, 'tell', None) is not None:
            try:
                self._body_position = body.tell()
            except OSError:
                self._body_position = object()
        if files:
            raise NotImplementedError('Streamed bodies and files are mutually exclusive.')
        if length:
            self.headers['Content-Length'] = builtin_str(length)
        else:
            self.headers['Transfer-Encoding'] = 'chunked'
    else:
        raw_data = cast('_t.RawDataType | None', data)
        if files:
            body, content_type = self._encode_files(files, raw_data)
        elif raw_data:
            body = self._encode_params(raw_data)
            if isinstance(data, basestring) or _t.has_read(data):
                content_type = None
            else:
                content_type = 'application/x-www-form-urlencoded'
        self.prepare_content_length(body)
        if content_type and 'content-type' not in self.headers:
            self.headers['Content-Type'] = content_type
    self.body = body

def prepare_content_length(self, body: _t.BodyType) -> None:
    if body is not None:
        length = super_len(body)
        if length:
            self.headers['Content-Length'] = builtin_str(length)
    elif self.method not in ('GET', 'HEAD') and self.headers.get('Content-Length') is None:
        self.headers['Content-Length'] = '0'

def prepare_auth(self, auth: _t.AuthType, url: _t.UriType='') -> None:
    if auth is None:
        url_auth = get_auth_from_url(cast(str, self.url))
        auth = url_auth if any(url_auth) else None
    if auth:
        if isinstance(auth, tuple) and len(auth) == 2:
            auth_handler = HTTPBasicAuth(*auth)
        else:
            auth_handler = cast('Callable[..., PreparedRequest]', auth)
        r = auth_handler(self)
        self.__dict__.update(r.__dict__)
        self.prepare_content_length(self.body)

def prepare_cookies(self, cookies: RequestsCookieJar | CookieJar | dict[str, str] | None) -> None:
    if isinstance(cookies, cookielib.CookieJar):
        self._cookies = cookies
    else:
        self._cookies = cookiejar_from_dict(cookies)
    cookies_jar = cast('CookieJar', self._cookies)
    cookie_header = get_cookie_header(cookies_jar, self)
    if cookie_header is not None:
        self.headers['Cookie'] = cookie_header

def prepare_hooks(self, hooks: _t.HooksInputType | None) -> None:
    hooks = hooks or {}
    for event in hooks:
        self.register_hook(event, hooks[event])

@property
def ok(self) -> bool:
    try:
        self.raise_for_status()
    except HTTPError:
        return False
    return True

@property
def is_redirect(self) -> bool:
    return 'location' in self.headers and self.status_code in REDIRECT_STATI

@property
def is_permanent_redirect(self) -> bool:
    return 'location' in self.headers and self.status_code in (codes.moved_permanently, codes.permanent_redirect)

@property
def next(self) -> PreparedRequest | None:
    return self._next

@property
def apparent_encoding(self) -> str | None:
    if chardet is not None:
        return chardet.detect(self.content)['encoding']
    else:
        return 'utf-8'

def iter_content(self, chunk_size: int | None=1, decode_unicode: bool=False) -> Iterator[str | bytes]:

    def generate() -> Generator[bytes, None, None]:
        if hasattr(self.raw, 'stream'):
            try:
                yield from self.raw.stream(chunk_size, decode_content=True)
            except ProtocolError as e:
                raise ChunkedEncodingError(e)
            except DecodeError as e:
                raise ContentDecodingError(e)
            except ReadTimeoutError as e:
                raise ConnectionError(e)
            except SSLError as e:
                raise RequestsSSLError(e)
        else:
            while True:
                chunk = self.raw.read(chunk_size)
                if not chunk:
                    break
                yield chunk
        self._content_consumed = True
    if self._content_consumed and isinstance(self._content, bool):
        raise StreamConsumedError()
    elif chunk_size is not None and (not isinstance(chunk_size, int)):
        raise TypeError(f'chunk_size must be an int, it is instead a {type(chunk_size)}.')
    if self._content_consumed:
        content = cast(bytes, self._content)
        chunks = iter_slices(content, chunk_size)
    else:
        chunks = generate()
    if decode_unicode:
        chunks = stream_decode_response_unicode(chunks, self)
    return chunks

def iter_lines(self, chunk_size: int=ITER_CHUNK_SIZE, decode_unicode: bool=False, delimiter: str | bytes | None=None) -> Iterator[str | bytes]:
    pending: str | bytes | None = None
    for chunk in self.iter_content(chunk_size=chunk_size, decode_unicode=decode_unicode):
        if pending is not None:
            chunk = cast('str | bytes', pending + chunk)
        if delimiter:
            lines = chunk.split(delimiter)
        else:
            lines = chunk.splitlines()
        if lines and lines[-1] and chunk and (lines[-1][-1] == chunk[-1]):
            pending = lines.pop()
        else:
            pending = None
        yield from lines
    if pending is not None:
        yield pending

@property
def content(self) -> bytes:
    if self._content is False:
        if self._content_consumed:
            raise RuntimeError('The content for this response was already consumed')
        if self.status_code == 0 or self.raw is None:
            self._content = None
        else:
            self._content = b''.join(self.iter_content(CONTENT_CHUNK_SIZE)) or b''
    self._content_consumed = True
    return self._content

@property
def text(self) -> str:
    content = None
    encoding = self.encoding
    if not self.content:
        return ''
    if self.encoding is None:
        encoding = self.apparent_encoding
    try:
        content = str(self.content, encoding or 'utf-8', errors='replace')
    except (LookupError, TypeError):
        content = str(self.content, errors='replace')
    return content

def json(self, **kwargs: Any) -> Any:
    if not self.encoding and self.content and (len(self.content) > 3):
        encoding = guess_json_utf(self.content)
        if encoding is not None:
            try:
                return complexjson.loads(self.content.decode(encoding), **kwargs)
            except UnicodeDecodeError:
                pass
            except JSONDecodeError as e:
                raise RequestsJSONDecodeError(e.msg, e.doc, e.pos)
    try:
        return complexjson.loads(self.text, **kwargs)
    except JSONDecodeError as e:
        raise RequestsJSONDecodeError(e.msg, e.doc, e.pos)

@property
def links(self) -> dict[str, dict[str, str]]:
    header = self.headers.get('link')
    resolved_links: dict[str, dict[str, str]] = {}
    if header:
        links = parse_header_links(header)
        for link in links:
            key = link.get('rel') or link.get('url')
            if key is not None:
                resolved_links[key] = link
    return resolved_links

def raise_for_status(self) -> None:
    http_error_msg = ''
    if isinstance(self.reason, bytes):
        try:
            reason = self.reason.decode('utf-8')
        except UnicodeDecodeError:
            reason = self.reason.decode('iso-8859-1')
    else:
        reason = self.reason
    if 400 <= self.status_code < 500:
        http_error_msg = f'{self.status_code} Client Error: {reason} for url: {self.url}'
    elif 500 <= self.status_code < 600:
        http_error_msg = f'{self.status_code} Server Error: {reason} for url: {self.url}'
    if http_error_msg:
        raise HTTPError(http_error_msg, response=self)

def close(self) -> None:
    if not self._content_consumed:
        self.raw.close()
    release_conn = getattr(self.raw, 'release_conn', None)
    if release_conn is not None:
        release_conn()

def merge_setting(request_setting: Any, session_setting: Any, dict_class: type=OrderedDict) -> Any:
    if session_setting is None:
        return request_setting
    if request_setting is None:
        return session_setting
    if not (isinstance(session_setting, Mapping) and isinstance(request_setting, Mapping)):
        return request_setting
    merged_setting = dict_class(to_key_val_list(session_setting))
    merged_setting.update(to_key_val_list(request_setting))
    none_keys = [k for k, v in merged_setting.items() if v is None]
    for key in none_keys:
        del merged_setting[key]
    return merged_setting

def merge_hooks(request_hooks: _t.HooksType, session_hooks: _t.HooksType, dict_class: type=OrderedDict) -> _t.HooksType:
    if session_hooks is None or session_hooks.get('response') == []:
        return request_hooks
    if request_hooks is None or request_hooks.get('response') == []:
        return session_hooks
    return merge_setting(request_hooks, session_hooks, dict_class)

def get_redirect_target(self, resp: Response) -> str | None:
    if resp.is_redirect:
        location = resp.headers['location']
        location = location.encode('latin1')
        return to_native_string(location, 'utf8')
    return None

def should_strip_auth(self, old_url: str, new_url: str) -> bool:
    old_parsed = urlparse(old_url)
    new_parsed = urlparse(new_url)
    if old_parsed.hostname != new_parsed.hostname:
        return True
    if old_parsed.scheme == 'http' and old_parsed.port in (80, None) and (new_parsed.scheme == 'https') and (new_parsed.port in (443, None)):
        return False
    changed_port = old_parsed.port != new_parsed.port
    changed_scheme = old_parsed.scheme != new_parsed.scheme
    default_port = (DEFAULT_PORTS.get(old_parsed.scheme, None), None)
    if not changed_scheme and old_parsed.port in default_port and (new_parsed.port in default_port):
        return False
    return changed_port or changed_scheme

def rebuild_proxies(self, prepared_request: PreparedRequest, proxies: dict[str, str] | None) -> dict[str, str]:
    assert _is_prepared(prepared_request)
    headers = prepared_request.headers
    scheme = urlparse(prepared_request.url).scheme
    new_proxies = resolve_proxies(prepared_request, proxies, self.trust_env)
    if 'Proxy-Authorization' in headers:
        del headers['Proxy-Authorization']
    try:
        username, password = get_auth_from_url(new_proxies[scheme])
    except KeyError:
        username, password = (None, None)
    if not scheme.startswith('https') and username and password:
        headers['Proxy-Authorization'] = _basic_auth_str(username, password)
    return new_proxies

def rebuild_method(self, prepared_request: PreparedRequest, response: Response) -> None:
    method = prepared_request.method
    if response.status_code == codes.see_other and method != 'HEAD':
        method = 'GET'
    if response.status_code == codes.found and method != 'HEAD':
        method = 'GET'
    if response.status_code == codes.moved and method == 'POST':
        method = 'GET'
    prepared_request.method = method

def prepare_request(self, request: Request) -> PreparedRequest:
    url = cast('_t.UriType', request.url)
    method = cast(str, request.method)
    cookies = request.cookies or {}
    if not isinstance(cookies, cookielib.CookieJar):
        cookies = cookiejar_from_dict(cookies)
    merged_cookies = merge_cookies(merge_cookies(RequestsCookieJar(), self.cookies), cookies)
    auth = request.auth
    if self.trust_env and (not auth) and (not self.auth):
        auth = get_netrc_auth(url)
    p = PreparedRequest()
    p.prepare(method=method.upper(), url=url, files=request.files, data=request.data, json=request.json, headers=merge_setting(request.headers, self.headers, dict_class=CaseInsensitiveDict), params=merge_setting(request.params, self.params), auth=merge_setting(auth, self.auth), cookies=merged_cookies, hooks=merge_hooks(request.hooks, self.hooks))
    return p

def get(self, url: _t.UriType, params: _t.ParamsType=None, **kwargs: Unpack[_t.GetKwargs]) -> Response:
    kwargs.setdefault('allow_redirects', True)
    return self.request('GET', url, params=params, **kwargs)

def options(self, url: _t.UriType, **kwargs: Unpack[_t.RequestKwargs]) -> Response:
    kwargs.setdefault('allow_redirects', True)
    return self.request('OPTIONS', url, **kwargs)

def head(self, url: _t.UriType, **kwargs: Unpack[_t.RequestKwargs]) -> Response:
    kwargs.setdefault('allow_redirects', False)
    return self.request('HEAD', url, **kwargs)

def send(self, request: PreparedRequest, **kwargs: Any) -> Response:
    kwargs.setdefault('stream', self.stream)
    kwargs.setdefault('verify', self.verify)
    kwargs.setdefault('cert', self.cert)
    if 'proxies' not in kwargs:
        kwargs['proxies'] = resolve_proxies(request, self.proxies, self.trust_env)
    if isinstance(request, Request):
        raise ValueError('You can only send PreparedRequests.')
    assert _is_prepared(request)
    allow_redirects = kwargs.pop('allow_redirects', True)
    stream = kwargs.get('stream')
    hooks = request.hooks
    adapter = self.get_adapter(url=request.url)
    start = preferred_clock()
    r = adapter.send(request, **kwargs)
    elapsed = preferred_clock() - start
    r.elapsed = timedelta(seconds=elapsed)
    r = dispatch_hook('response', hooks, r, **kwargs)
    if r.history:
        for resp in r.history:
            extract_cookies_to_jar(self.cookies, resp.request, resp.raw)
    extract_cookies_to_jar(self.cookies, request, r.raw)
    if allow_redirects:
        gen = self.resolve_redirects(r, request, **kwargs)
        history = [resp for resp in gen]
    else:
        history = []
    if history:
        history.insert(0, r)
        r = history.pop()
        r.history = history
    if not allow_redirects:
        try:
            r._next = next(self.resolve_redirects(r, request, yield_requests=True, **kwargs))
        except StopIteration:
            pass
    if not stream:
        r.content
    return r

def merge_environment_settings(self, url: str, proxies: dict[str, str] | None, stream: bool | None, verify: _t.VerifyType | None, cert: _t.CertType) -> dict[str, Any]:
    if self.trust_env:
        no_proxy = proxies.get('no_proxy') if proxies is not None else None
        env_proxies = get_environ_proxies(url, no_proxy=no_proxy)
        if proxies is not None:
            for k, v in env_proxies.items():
                proxies.setdefault(k, v)
        if verify is True or verify is None:
            verify = os.environ.get('REQUESTS_CA_BUNDLE') or os.environ.get('CURL_CA_BUNDLE') or verify
    proxies = merge_setting(proxies, self.proxies)
    stream = merge_setting(stream, self.stream)
    verify = merge_setting(verify, self.verify)
    cert = merge_setting(cert, self.cert)
    return {'proxies': proxies, 'stream': stream, 'verify': verify, 'cert': cert}

def get_adapter(self, url: str) -> BaseAdapter:
    for prefix, adapter in self.adapters.items():
        if url.lower().startswith(prefix.lower()):
            return adapter
    raise InvalidSchema(f'No connection adapters were found for {url!r}')

def close(self) -> None:
    for v in self.adapters.values():
        v.close()

def mount(self, prefix: str, adapter: BaseAdapter) -> None:
    self.adapters[prefix] = adapter
    keys_to_move = [k for k in self.adapters if len(k) < len(prefix)]
    for key in keys_to_move:
        self.adapters[key] = self.adapters.pop(key)

def dict_to_sequence(d: _t.SupportsItems[Any, Any] | Iterable[tuple[Any, Any]]) -> Iterable[tuple[Any, Any]]:
    if isinstance(d, _SupportsItems):
        return d.items()
    return d

def get_netrc_auth(url: _t.UriType, raise_errors: bool=False) -> tuple[str, str] | None:
    if isinstance(url, bytes):
        url = url.decode('utf-8')
    netrc_file = os.environ.get('NETRC')
    if netrc_file is not None:
        netrc_locations = (netrc_file,)
    else:
        netrc_locations = (f'~/{f}' for f in NETRC_FILES)
    try:
        from netrc import NetrcParseError, netrc
        netrc_path = None
        for f in netrc_locations:
            loc = os.path.expanduser(f)
            if os.path.exists(loc):
                netrc_path = loc
                break
        if netrc_path is None:
            return
        ri = urlparse(url)
        host = ri.hostname
        if host is None:
            return
        try:
            _netrc = netrc(netrc_path).authenticators(host)
            if _netrc and any(_netrc):
                login_i = 0 if _netrc[0] else 1
                return (_netrc[login_i] or '', _netrc[2] or '')
        except (NetrcParseError, OSError):
            if raise_errors:
                raise
    except (ImportError, AttributeError):
        pass

def guess_filename(obj: Any) -> str | None:
    name = getattr(obj, 'name', None)
    if name and isinstance(name, (str, bytes)) and (name[0] != '<') and (name[-1] != '>'):
        return os.path.basename(name)

def extract_zipped_paths(path: str) -> str:
    if os.path.exists(path):
        return path
    archive, member = os.path.split(path)
    while archive and (not os.path.exists(archive)):
        archive, prefix = os.path.split(archive)
        if not prefix:
            break
        member = '/'.join([prefix, member])
    if not zipfile.is_zipfile(archive):
        return path
    zip_file = zipfile.ZipFile(archive)
    if member not in zip_file.namelist():
        return path
    suffix = os.path.splitext(member.split('/')[-1])[-1]
    fd, extracted_path = tempfile.mkstemp(suffix=suffix)
    try:
        os.write(fd, zip_file.read(member))
    finally:
        os.close(fd)
    return extracted_path

@contextlib.contextmanager
def atomic_open(filename: str) -> Generator[BufferedWriter, None, None]:
    tmp_descriptor, tmp_name = tempfile.mkstemp(dir=os.path.dirname(filename))
    try:
        with os.fdopen(tmp_descriptor, 'wb') as tmp_handler:
            yield tmp_handler
        os.replace(tmp_name, filename)
    except BaseException:
        os.remove(tmp_name)
        raise

def from_key_val_list(value: Mapping[Any, Any] | Iterable[tuple[Any, Any]] | None) -> dict[Any, Any] | None:
    if value is None:
        return None
    if isinstance(value, (str, bytes, bool, int)):
        raise ValueError('cannot encode objects that are not 2-tuples')
    return OrderedDict(value)

def to_key_val_list(value: _t.SupportsItems[_KT, _VT] | Iterable[tuple[_KT, _VT]] | None) -> list[tuple[_KT, _VT]] | None:
    if value is None:
        return None
    if isinstance(value, (str, bytes, bool, int)):
        raise ValueError('cannot encode objects that are not 2-tuples')
    if isinstance(value, _SupportsItems):
        return list(value.items())
    return list(value)

def parse_list_header(value: str) -> list[str]:
    result: list[str] = []
    for item in _parse_list_header(value):
        if item[:1] == item[-1:] == '"':
            item = unquote_header_value(item[1:-1])
        result.append(item)
    return result

def parse_dict_header(value: str) -> dict[str, str | None]:
    result: dict[str, str | None] = {}
    for item in _parse_list_header(value):
        if '=' not in item:
            result[item] = None
            continue
        name, value = item.split('=', 1)
        if value[:1] == value[-1:] == '"':
            value = unquote_header_value(value[1:-1])
        result[name] = value
    return result

def unquote_header_value(value: str, is_filename: bool=False) -> str:
    if value and value[0] == value[-1] == '"':
        value = value[1:-1]
        if not is_filename or value[:2] != '\\\\':
            return value.replace('\\\\', '\\').replace('\\"', '"')
    return value

def dict_from_cookiejar(cj: CookieJar) -> dict[str, str | None]:
    cookie_dict = {cookie.name: cookie.value for cookie in cj}
    return cookie_dict

def get_encodings_from_content(content: str) -> list[str]:
    warnings.warn('In requests 3.0, get_encodings_from_content will be removed. For more information, please see the discussion on issue #2266. (This warning should only appear once.)', DeprecationWarning)
    charset_re = re.compile('<meta.*?charset=["\\\']*(.+?)["\\\'>]', flags=re.I)
    pragma_re = re.compile('<meta.*?content=["\\\']*;?charset=(.+?)["\\\'>]', flags=re.I)
    xml_re = re.compile('^<\\?xml.*?encoding=["\\\']*(.+?)["\\\'>]')
    return charset_re.findall(content) + pragma_re.findall(content) + xml_re.findall(content)

def _parse_content_type_header(header: str) -> tuple[str, dict[str, Any]]:
    tokens = header.split(';')
    content_type, params = (tokens[0].strip(), tokens[1:])
    params_dict: dict[str, str | bool] = {}
    strip_chars = '"\' '
    for param in params:
        param = param.strip()
        if param and (idx := param.find('=')) != -1:
            key = param[:idx].strip(strip_chars)
            value = param[idx + 1:].strip(strip_chars)
            params_dict[key.lower()] = value
    return (content_type, params_dict)

def get_encoding_from_headers(headers: CaseInsensitiveDict[str]) -> str | None:
    content_type = headers.get('content-type')
    if not content_type:
        return None
    content_type, params = _parse_content_type_header(content_type)
    if 'charset' in params:
        return params['charset'].strip('\'"')
    if 'text' in content_type:
        return 'ISO-8859-1'
    if 'application/json' in content_type:
        return 'utf-8'

def stream_decode_response_unicode(iterator: Iterable[bytes], r: Response) -> Generator[str | bytes, None, None]:
    if r.encoding is None:
        yield from iterator
        return
    decoder = codecs.getincrementaldecoder(r.encoding)(errors='replace')
    for chunk in iterator:
        rv = decoder.decode(chunk)
        if rv:
            yield rv
    rv = decoder.decode(b'', final=True)
    if rv:
        yield rv

def iter_slices(string: bytes | str, slice_length: int | None) -> Generator[bytes | str, None, None]:
    pos = 0
    if slice_length is None or slice_length <= 0:
        slice_length = len(string)
    while pos < len(string):
        yield string[pos:pos + slice_length]
        pos += slice_length

def get_unicode_from_response(r: Response) -> str | bytes | None:
    warnings.warn('In requests 3.0, get_unicode_from_response will be removed. For more information, please see the discussion on issue #2266. (This warning should only appear once.)', DeprecationWarning)
    if r.content is None:
        return None
    tried_encodings: list[str] = []
    encoding = get_encoding_from_headers(r.headers)
    if encoding:
        try:
            return str(r.content, encoding)
        except UnicodeError:
            tried_encodings.append(encoding)
    try:
        return str(r.content, encoding or 'utf-8', errors='replace')
    except TypeError:
        return r.content

def unquote_unreserved(uri: str) -> str:
    parts = uri.split('%')
    for i in range(1, len(parts)):
        h = parts[i][0:2]
        if len(h) == 2 and h.isalnum():
            try:
                c = chr(int(h, 16))
            except ValueError:
                raise InvalidURL(f"Invalid percent-escape sequence: '{h}'")
            if c in UNRESERVED_SET:
                parts[i] = c + parts[i][2:]
            else:
                parts[i] = f'%{parts[i]}'
        else:
            parts[i] = f'%{parts[i]}'
    return ''.join(parts)

def requote_uri(uri: str) -> str:
    safe_with_percent = "!#$%&'()*+,/:;=?@[]~"
    safe_without_percent = "!#$&'()*+,/:;=?@[]~"
    try:
        return quote(unquote_unreserved(uri), safe=safe_with_percent)
    except InvalidURL:
        return quote(uri, safe=safe_without_percent)

def dotted_netmask(mask: int) -> str:
    bits = 4294967295 ^ (1 << 32 - mask) - 1
    return socket.inet_ntoa(struct.pack('>I', bits))

def is_ipv4_address(string_ip: str) -> bool:
    try:
        socket.inet_aton(string_ip)
    except OSError:
        return False
    return True

def is_valid_cidr(string_network: str) -> bool:
    if string_network.count('/') == 1:
        try:
            mask = int(string_network.split('/')[1])
        except ValueError:
            return False
        if mask < 1 or mask > 32:
            return False
        try:
            socket.inet_aton(string_network.split('/')[0])
        except OSError:
            return False
    else:
        return False
    return True

@contextlib.contextmanager
def set_environ(env_name: str, value: str | None) -> Generator[None, None, None]:
    value_changed = value is not None
    old_value: str | None = None
    if value_changed:
        old_value = os.environ.get(env_name)
        os.environ[env_name] = value
    try:
        yield
    finally:
        if value_changed:
            if old_value is None:
                del os.environ[env_name]
            else:
                os.environ[env_name] = old_value

def should_bypass_proxies(url: str, no_proxy: str | None) -> bool:

    def get_proxy(key: str) -> str | None:
        return os.environ.get(key) or os.environ.get(key.upper())
    no_proxy_arg = no_proxy
    if no_proxy is None:
        no_proxy = get_proxy('no_proxy')
    parsed = urlparse(url)
    hostname = parsed.hostname
    if hostname is None:
        return True
    if no_proxy:
        no_proxy_hosts = (host for host in no_proxy.replace(' ', '').split(',') if host)
        if is_ipv4_address(hostname):
            for proxy_ip in no_proxy_hosts:
                if is_valid_cidr(proxy_ip):
                    if address_in_network(hostname, proxy_ip):
                        return True
                elif hostname == proxy_ip:
                    return True
        else:
            host_with_port = hostname
            if parsed.port:
                host_with_port += f':{parsed.port}'
            for host in no_proxy_hosts:
                host = host.lstrip('.')
                if hostname == host or host_with_port == host:
                    return True
                host = '.' + host
                if hostname.endswith(host) or host_with_port.endswith(host):
                    return True
    with set_environ('no_proxy', no_proxy_arg):
        try:
            bypass = proxy_bypass(hostname)
        except (TypeError, socket.gaierror):
            bypass = False
    if bypass:
        return True
    return False

def get_environ_proxies(url: str, no_proxy: str | None=None) -> dict[str, str]:
    if should_bypass_proxies(url, no_proxy=no_proxy):
        return {}
    else:
        return getproxies()

def select_proxy(url: str, proxies: dict[str, str] | None) -> str | None:
    proxies = proxies or {}
    urlparts = urlparse(url)
    if urlparts.hostname is None:
        return proxies.get(urlparts.scheme, proxies.get('all'))
    proxy_keys = [urlparts.scheme + '://' + urlparts.hostname, urlparts.scheme, 'all://' + urlparts.hostname, 'all']
    proxy = None
    for proxy_key in proxy_keys:
        if proxy_key in proxies:
            proxy = proxies[proxy_key]
            break
    return proxy

def resolve_proxies(request: Request | PreparedRequest, proxies: dict[str, str] | None, trust_env: bool=True) -> dict[str, str]:
    proxies = proxies if proxies is not None else {}
    url = cast(str, request.url)
    scheme = urlparse(url).scheme
    no_proxy = proxies.get('no_proxy')
    new_proxies = proxies.copy()
    if trust_env and (not should_bypass_proxies(url, no_proxy=no_proxy)):
        environ_proxies = get_environ_proxies(url, no_proxy=no_proxy)
        proxy = environ_proxies.get(scheme, environ_proxies.get('all'))
        if proxy:
            new_proxies.setdefault(scheme, proxy)
    return new_proxies

def parse_header_links(value: str) -> list[dict[str, str]]:
    links: list[dict[str, str]] = []
    replace_chars = ' \'"'
    value = value.strip(replace_chars)
    if not value:
        return links
    for val in re.split(', *<', value):
        try:
            url, params = val.split(';', 1)
        except ValueError:
            url, params = (val, '')
        link: dict[str, str] = {'url': url.strip('<> \'"')}
        for param in params.split(';'):
            try:
                key, value = param.split('=')
            except ValueError:
                break
            link[key.strip(replace_chars)] = value.strip(replace_chars)
        links.append(link)
    return links

def guess_json_utf(data: bytes) -> str | None:
    sample = data[:4]
    if sample in (codecs.BOM_UTF32_LE, codecs.BOM_UTF32_BE):
        return 'utf-32'
    if sample[:3] == codecs.BOM_UTF8:
        return 'utf-8-sig'
    if sample[:2] in (codecs.BOM_UTF16_LE, codecs.BOM_UTF16_BE):
        return 'utf-16'
    nullcount = sample.count(_null)
    if nullcount == 0:
        return 'utf-8'
    if nullcount == 2:
        if sample[::2] == _null2:
            return 'utf-16-be'
        if sample[1::2] == _null2:
            return 'utf-16-le'
    if nullcount == 3:
        if sample[:3] == _null3:
            return 'utf-32-be'
        if sample[1:] == _null3:
            return 'utf-32-le'
    return None

def prepend_scheme_if_needed(url: str, new_scheme: str) -> str:
    parsed = parse_url(url)
