def _get_param_names(cls):
    init = cls.__init__
    if init is object.__init__:
        return []
    init_signature = inspect.signature(init)
    parameters = [p for p in init_signature.parameters.values() if p.name != 'self' and p.kind != p.VAR_KEYWORD]
    for p in parameters:
