            return True
        if not np.array_equal(param_value, init_default_params[param_name]) and (not (is_scalar_nan(init_default_params[param_name]) and is_scalar_nan(param_value))):
            return True
        return False
    unordered_params = {name: out[name] for name in init_default_params if name in out}
    unordered_params.update({name: value for name, value in out.items() if name not in init_default_params})
    non_default_params, default_params = ([], [])
    for name, value in unordered_params.items():
        if is_non_default(name, value):
            non_default_params.append(name)
