def get_metadata_routing(self):
    router = MetadataRouter(owner=self).add_self_request(self).add(estimator=self._get_estimator(), method_mapping=MethodMapping().add(caller='fit', callee='fit')).add(splitter=self.cv, method_mapping=MethodMapping().add(caller='fit', callee='split'))
