def _cov(X, shrinkage=None, covariance_estimator=None):
    if covariance_estimator is None:
        shrinkage = 'empirical' if shrinkage is None else shrinkage
        if isinstance(shrinkage, str):
            if shrinkage == 'auto':
                sc = StandardScaler()
                X = sc.fit_transform(X)
                s = ledoit_wolf(X)[0]
                s = sc.scale_[:, np.newaxis] * s * sc.scale_[np.newaxis, :]
            elif shrinkage == 'empirical':
                s = empirical_covariance(X)
        elif isinstance(shrinkage, Real):
            s = shrunk_covariance(empirical_covariance(X), shrinkage)
    else:
        if shrinkage is not None and shrinkage != 0:
            raise ValueError('covariance_estimator and shrinkage parameters are not None. Only one of the two can be set.')
        covariance_estimator.fit(X)
        if not hasattr(covariance_estimator, 'covariance_'):
            raise ValueError('%s does not have a covariance_ attribute' % covariance_estimator.__class__.__name__)
        s = covariance_estimator.covariance_
    return s

def _class_means(X, y):
    xp, is_array_api_compliant = get_namespace(X)
    classes, y = xp.unique_inverse(y)
    means = xp.zeros((classes.shape[0], X.shape[1]), device=device(X), dtype=X.dtype)
    if is_array_api_compliant:
        for i in range(classes.shape[0]):
            means[i, :] = xp.mean(X[y == i], axis=0)
    else:
        cnt = np.bincount(y)
        np.add.at(means, y, X)
        means /= cnt[:, None]
    return means

def decision_function(self, X):
    y_scores = self._decision_function(X)
    if len(self.classes_) == 2:
        return y_scores[:, 1] - y_scores[:, 0]
    return y_scores

def predict(self, X):
    scores = self._decision_function(X)
    return self.classes_.take(scores.argmax(axis=1))

def predict_log_proba(self, X):
    scores = self._decision_function(X)
    log_likelihood = scores - scores.max(axis=1)[:, np.newaxis]
    return log_likelihood - np.log(np.exp(log_likelihood).sum(axis=1)[:, np.newaxis])

@_fit_context(prefer_skip_nested_validation=False)
def fit(self, X, y):
    xp, _ = get_namespace(X)
    X, y = validate_data(self, X, y, ensure_min_samples=2, dtype=[xp.float64, xp.float32])
    self.classes_ = unique_labels(y)
    n_samples, n_features = X.shape
    n_classes = self.classes_.shape[0]
    if n_samples == n_classes:
        raise ValueError('The number of samples must be more than the number of classes.')
    if self.priors is None:
        _, cnts = xp.unique_counts(y)
        self.priors_ = xp.astype(cnts, X.dtype) / float(n_samples)
    else:
        self.priors_ = xp.asarray(self.priors, dtype=X.dtype)
    if xp.any(self.priors_ < 0):
        raise ValueError('priors must be non-negative')
    if xp.abs(xp.sum(self.priors_) - 1.0) > 1e-05:
        warnings.warn('The priors do not sum to 1. Renormalizing', UserWarning)
        self.priors_ = self.priors_ / self.priors_.sum()
    max_components = min(n_classes - 1, n_features)
    if self.n_components is None:
        self._max_components = max_components
    else:
        if self.n_components > max_components:
            raise ValueError('n_components cannot be larger than min(n_features, n_classes - 1).')
        self._max_components = self.n_components
    if self.solver == 'svd':
        if self.shrinkage is not None:
            raise NotImplementedError("shrinkage not supported with 'svd' solver.")
        if self.covariance_estimator is not None:
            raise ValueError('covariance estimator is not supported with svd solver. Try another solver')
        self._solve_svd(X, y)
    elif self.solver == 'lsqr':
        self._solve_lstsq(X, y, shrinkage=self.shrinkage, covariance_estimator=self.covariance_estimator)
    elif self.solver == 'eigen':
        self._solve_eigen(X, y, shrinkage=self.shrinkage, covariance_estimator=self.covariance_estimator)
    if size(self.classes_) == 2:
        coef_ = xp.asarray(self.coef_[1, :] - self.coef_[0, :], dtype=X.dtype)
        self.coef_ = xp.reshape(coef_, (1, -1))
        intercept_ = xp.asarray(self.intercept_[1] - self.intercept_[0], dtype=X.dtype)
        self.intercept_ = xp.reshape(intercept_, (1,))
    self._n_features_out = self._max_components
    return self

def transform(self, X):
    if self.solver == 'lsqr':
        raise NotImplementedError("transform not implemented for 'lsqr' solver (use 'svd' or 'eigen').")
    check_is_fitted(self)
    check_same_namespace(X, self, attribute='coef_', method='transform')
    X = validate_data(self, X, reset=False)
    if self.solver == 'svd':
        X_new = (X - self.xbar_) @ self.scalings_
    elif self.solver == 'eigen':
        X_new = X @ self.scalings_
    return X_new[:, :self._max_components]

def predict_proba(self, X):
    check_is_fitted(self)
    check_same_namespace(X, self, attribute='coef_', method='predict_proba')
    xp, _ = get_namespace(X)
    decision = self.decision_function(X)
    if size(self.classes_) == 2:
        proba = _expit(decision, xp=xp)
        return xp.stack([1 - proba, proba], axis=1)
    else:
        return softmax(decision)

@_fit_context(prefer_skip_nested_validation=True)
def fit(self, X, y):
    X, y = validate_data(self, X, y)
    check_classification_targets(y)
    self.classes_ = np.unique(y)
    n_samples, n_features = X.shape
    n_classes = len(self.classes_)
    if n_classes < 2:
        raise ValueError(f'The number of classes has to be greater than one. Got {n_classes} class.')
    if self.priors is None:
        _, cnts = np.unique(y, return_counts=True)
        self.priors_ = cnts / float(n_samples)
    else:
        self.priors_ = np.array(self.priors)
    if self.solver == 'svd':
        if self.shrinkage is not None:
            raise NotImplementedError("shrinkage not supported with 'svd' solver.")
        if self.covariance_estimator is not None:
            raise ValueError("covariance_estimator is not supported with solver='svd'. Try solver='eigen' instead.")
        specific_solver = self._solve_svd
    elif self.solver == 'eigen':
        specific_solver = self._solve_eigen
    means = []
    cov = []
    scalings = []
    rotations = []
    for class_idx, class_label in enumerate(self.classes_):
        X_class = X[y == class_label, :]
        if len(X_class) == 1:
            raise ValueError('y has only 1 sample in class %s, covariance is ill defined.' % str(self.classes_[class_idx]))
        mean_class = X_class.mean(0)
        means.append(mean_class)
        scaling_class, rotation_class, cov_class = specific_solver(X_class)
        rank = np.sum(scaling_class > self.tol)
        if rank < n_features:
            n_samples_class = X_class.shape[0]
            if self.solver == 'svd' and n_samples_class <= n_features:
                raise linalg.LinAlgError(f"The covariance matrix of class {class_label} is not full rank. When using `solver='svd'` the number of samples in each class should be more than the number of features, but class {class_label} has {n_samples_class} samples and {n_features} features. Try using `solver='eigen'` and setting the parameter `shrinkage` for regularization.")
            else:
                msg_param = 'shrinkage' if self.solver == 'eigen' else 'reg_param'
                raise linalg.LinAlgError(f'The covariance matrix of class {class_label} is not full rank. Increase the value of `{msg_param}` to reduce the collinearity.')
        cov.append(cov_class)
        scalings.append(scaling_class)
        rotations.append(rotation_class)
    if self.store_covariance:
        self.covariance_ = cov
    self.means_ = np.asarray(means)
    self.scalings_ = scalings
    self.rotations_ = rotations
    return self

