def predict(self, X):
    check_is_fitted(self)
    n_samples = _num_samples(X)
    rs = check_random_state(self.random_state)
    n_classes_ = self.n_classes_
    classes_ = self.classes_
    class_prior_ = self.class_prior_
    constant = self.constant
    if self.n_outputs_ == 1:
        n_classes_ = [n_classes_]
        classes_ = [classes_]
        class_prior_ = [class_prior_]
        constant = [constant]
    if self._strategy == 'stratified':
        proba = self.predict_proba(X)
        if self.n_outputs_ == 1:
            proba = [proba]
    if self.sparse_output_:
        class_prob = None
        if self._strategy in ('most_frequent', 'prior'):
            classes_ = [np.array([cp.argmax()]) for cp in class_prior_]
        elif self._strategy == 'stratified':
            class_prob = class_prior_
        elif self._strategy == 'uniform':
            raise ValueError('Sparse target prediction is not supported with the uniform strategy')
        elif self._strategy == 'constant':
            classes_ = [np.array([c]) for c in constant]
        y = _random_choice_csc(n_samples, classes_, class_prob, self.random_state)
    else:
        if self._strategy in ('most_frequent', 'prior'):
            y = np.tile([classes_[k][class_prior_[k].argmax()] for k in range(self.n_outputs_)], [n_samples, 1])
        elif self._strategy == 'stratified':
            y = np.vstack([classes_[k][proba[k].argmax(axis=1)] for k in range(self.n_outputs_)]).T
        elif self._strategy == 'uniform':
            ret = [classes_[k][rs.randint(n_classes_[k], size=n_samples)] for k in range(self.n_outputs_)]
            y = np.vstack(ret).T
        elif self._strategy == 'constant':
            y = np.tile(self.constant, (n_samples, 1))
        if self.n_outputs_ == 1:
            y = np.ravel(y)
    return y

def predict_log_proba(self, X):
    proba = self.predict_proba(X)
    if self.n_outputs_ == 1:
        return np.log(proba)
    else:
        return [np.log(p) for p in proba]

def score(self, X, y, sample_weight=None):
    if X is None:
        X = np.zeros(shape=(len(y), 1))
    return super().score(X, y, sample_weight)

@_fit_context(prefer_skip_nested_validation=True)
def fit(self, X, y, sample_weight=None):
    validate_data(self, X, skip_check_array=True)
    y = check_array(y, ensure_2d=False, input_name='y')
    if len(y) == 0:
        raise ValueError('y must not be empty.')
    if y.ndim == 1:
        y = np.reshape(y, (-1, 1))
    self.n_outputs_ = y.shape[1]
    check_consistent_length(X, y, sample_weight)
    if sample_weight is not None:
        sample_weight = _check_sample_weight(sample_weight, X)
    if self.strategy == 'mean':
        self.constant_ = np.average(y, axis=0, weights=sample_weight)
    elif self.strategy == 'median':
        if sample_weight is None:
            self.constant_ = np.median(y, axis=0)
        else:
            self.constant_ = _weighted_percentile(y, sample_weight, percentile_rank=50.0)
    elif self.strategy == 'quantile':
        if self.quantile is None:
            raise ValueError("When using `strategy='quantile', you have to specify the desired quantile in the range [0, 1].")
        percentile_rank = self.quantile * 100.0
        if sample_weight is None:
            self.constant_ = np.percentile(y, axis=0, q=percentile_rank)
        else:
            self.constant_ = _weighted_percentile(y, sample_weight, percentile_rank=percentile_rank)
    elif self.strategy == 'constant':
        if self.constant is None:
            raise TypeError('Constant target value has to be specified when the constant strategy is used.')
        self.constant_ = check_array(self.constant, accept_sparse=['csr', 'csc', 'coo'], ensure_2d=False, ensure_min_samples=0)
        if self.n_outputs_ != 1 and self.constant_.shape[0] != y.shape[1]:
            raise ValueError('Constant target value should have shape (%d, 1).' % y.shape[1])
    self.constant_ = np.reshape(self.constant_, (1, -1))
    return self

def score(self, X, y, sample_weight=None):
    if X is None:
        X = np.zeros(shape=(len(y), 1))
    return super().score(X, y, sample_weight)

@validate_params({'x': ['array-like'], 'y': ['array-like']}, prefer_skip_nested_validation=True)
def check_increasing(x, y):
    rho, _ = spearmanr(x, y)
    increasing_bool = rho >= 0
    if rho not in [-1.0, 1.0] and len(x) > 3:
        F = 0.5 * math.log((1.0 + rho) / (1.0 - rho))
        F_se = 1 / math.sqrt(len(x) - 3)
        rho_0 = math.tanh(F - 1.96 * F_se)
        rho_1 = math.tanh(F + 1.96 * F_se)
        if np.sign(rho_0) != np.sign(rho_1):
            warnings.warn('Confidence interval of the Spearman correlation coefficient spans zero. Determination of ``increasing`` may be suspect.')
    return increasing_bool

@validate_params({'y': ['array-like'], 'sample_weight': ['array-like', None], 'y_min': [Interval(Real, None, None, closed='both'), None], 'y_max': [Interval(Real, None, None, closed='both'), None], 'increasing': ['boolean']}, prefer_skip_nested_validation=True)
def isotonic_regression(y, *, sample_weight=None, y_min=None, y_max=None, increasing=True):
    y = check_array(y, ensure_2d=False, input_name='y', dtype=[np.float64, np.float32])
    if sp_base_version >= parse_version('1.12.0'):
        res = optimize.isotonic_regression(y=y, weights=sample_weight, increasing=increasing)
        y = np.asarray(res.x, dtype=y.dtype)
    else:
        order = np.s_[:] if increasing else np.s_[::-1]
        y = np.array(y[order], dtype=y.dtype)
        sample_weight = _check_sample_weight(sample_weight, y, dtype=y.dtype, copy=True)
        sample_weight = np.ascontiguousarray(sample_weight[order])
        _inplace_contiguous_isotonic_regression(y, sample_weight)
        y = y[order]
    if y_min is not None or y_max is not None:
        if y_min is None:
            y_min = -np.inf
        if y_max is None:
            y_max = np.inf
        np.clip(y, y_min, y_max, y)
    return y

def _build_f(self, X, y):
    bounds_error = self.out_of_bounds == 'raise'
    if len(y) == 1:
        self.f_ = lambda x: y.repeat(x.shape)
    else:
        self.f_ = interpolate.interp1d(X, y, kind='linear', bounds_error=bounds_error)

def _build_y(self, X, y, sample_weight, trim_duplicates=True):
    self._check_input_data_shape(X)
    X = X.reshape(-1)
    if self.increasing == 'auto':
        self.increasing_ = check_increasing(X, y)
    else:
        self.increasing_ = self.increasing
    sample_weight = _check_sample_weight(sample_weight, X, dtype=X.dtype)
    mask = sample_weight > 0
    X, y, sample_weight = (X[mask], y[mask], sample_weight[mask])
    order = np.lexsort((y, X))
    X, y, sample_weight = [array[order] for array in [X, y, sample_weight]]
    unique_X, unique_y, unique_sample_weight = _make_unique(X, y, sample_weight)
    X = unique_X
    y = isotonic_regression(unique_y, sample_weight=unique_sample_weight, y_min=self.y_min, y_max=self.y_max, increasing=self.increasing_)
    self.X_min_, self.X_max_ = (np.min(X), np.max(X))
    if trim_duplicates:
        keep_data = np.ones((len(y),), dtype=bool)
        keep_data[1:-1] = np.logical_or(np.not_equal(y[1:-1], y[:-2]), np.not_equal(y[1:-1], y[2:]))
        return (X[keep_data], y[keep_data])
    else:
        return (X, y)

def _transform(self, T):
    if hasattr(self, 'X_thresholds_'):
        dtype = self.X_thresholds_.dtype
    else:
        dtype = np.float64
    T = check_array(T, dtype=dtype, ensure_2d=False)
    self._check_input_data_shape(T)
    T = T.reshape(-1)
    if self.out_of_bounds == 'clip':
        T = np.clip(T, self.X_min_, self.X_max_)
    res = self.f_(T)
    res = res.astype(T.dtype)
    return res

def get_feature_names_out(self, input_features=None):
    check_is_fitted(self, 'f_')
    class_name = self.__class__.__name__.lower()
    return np.asarray([f'{class_name}0'], dtype=object)

def __setstate__(self, state):
    super().__setstate__(state)
    if hasattr(self, 'X_thresholds_') and hasattr(self, 'y_thresholds_'):
        self._build_f(self.X_thresholds_, self.y_thresholds_)

def transform(self, X):
    check_is_fitted(self)
    X = validate_data(self, X, accept_sparse='csc', reset=False)
    X_gamma = np.sqrt(self.gamma) * X
    if sp.issparse(X_gamma) and self.coef0 != 0:
        X_gamma = sp.hstack([X_gamma, np.sqrt(self.coef0) * np.ones((X_gamma.shape[0], 1))], format='csc')
    elif not sp.issparse(X_gamma) and self.coef0 != 0:
        X_gamma = np.hstack([X_gamma, np.sqrt(self.coef0) * np.ones((X_gamma.shape[0], 1))])
    if X_gamma.shape[1] != self.indexHash_.shape[1]:
        raise ValueError('Number of features of test samples does not match that of training samples.')
    count_sketches = np.zeros((X_gamma.shape[0], self.degree, self.n_components))
    if sp.issparse(X_gamma):
        for j in range(X_gamma.shape[1]):
            for d in range(self.degree):
                iHashIndex = self.indexHash_[d, j]
                iHashBit = self.bitHash_[d, j]
                count_sketches[:, d, iHashIndex] += (iHashBit * X_gamma[:, [j]]).toarray().ravel()
    else:
        for j in range(X_gamma.shape[1]):
            for d in range(self.degree):
                iHashIndex = self.indexHash_[d, j]
                iHashBit = self.bitHash_[d, j]
                count_sketches[:, d, iHashIndex] += iHashBit * X_gamma[:, j]
    count_sketches_fft = fft(count_sketches, axis=2, overwrite_x=True)
    count_sketches_fft_prod = np.prod(count_sketches_fft, axis=1)
    data_sketch = np.real(ifft(count_sketches_fft_prod, overwrite_x=True))
    return data_sketch

@_fit_context(prefer_skip_nested_validation=True)
def fit(self, X, y=None):
    X = validate_data(self, X, accept_sparse='csr', ensure_non_negative=True)
    if self.sample_interval is None and self.sample_steps not in (1, 2, 3):
        raise ValueError('If sample_steps is not in [1, 2, 3], you need to provide sample_interval')
    return self

def transform(self, X):
    X = validate_data(self, X, accept_sparse='csr', reset=False, ensure_non_negative=True)
    sparse = sp.issparse(X)
    if self.sample_interval is None:
        if self.sample_steps == 1:
            sample_interval = 0.8
        elif self.sample_steps == 2:
            sample_interval = 0.5
        elif self.sample_steps == 3:
            sample_interval = 0.4
        else:
            raise ValueError('If sample_steps is not in [1, 2, 3], you need to provide sample_interval')
    else:
        sample_interval = self.sample_interval
    transf = self._transform_sparse if sparse else self._transform_dense
    return transf(X, self.sample_steps, sample_interval)

def get_feature_names_out(self, input_features=None):
    check_is_fitted(self, attributes='n_features_in_')
    input_features = _check_feature_names_in(self, input_features, generate_names=True)
    est_name = self.__class__.__name__.lower()
    names_list = [f'{est_name}_{name}_sqrt' for name in input_features]
    for j in range(1, self.sample_steps):
        cos_names = [f'{est_name}_{name}_cos{j}' for name in input_features]
        sin_names = [f'{est_name}_{name}_sin{j}' for name in input_features]
        names_list.extend(cos_names + sin_names)
    return np.asarray(names_list, dtype=object)

def predict(self, X):
    check_is_fitted(self)
    X = validate_data(self, X, accept_sparse=('csr', 'csc'), reset=False)
    K = self._get_kernel(X, self.X_fit_)
    return np.dot(K, self.dual_coef_)

def _fit_binary(estimator, X, y, fit_params, classes=None):
    unique_y = np.unique(y)
    if len(unique_y) == 1:
        if classes is not None:
            if y[0] == -1:
                c = 0
            else:
                c = y[0]
            warnings.warn('Label %s is present in all training examples.' % str(classes[c]))
        estimator = _ConstantPredictor().fit(X, unique_y)
    else:
        estimator = clone(estimator)
        estimator.fit(X, y, **fit_params)
    return estimator

def _partial_fit_binary(estimator, X, y, partial_fit_params):
    estimator.partial_fit(X, y, classes=np.array((0, 1)), **partial_fit_params)
    return estimator

def _predict_binary(estimator, X):
    if is_regressor(estimator):
        return estimator.predict(X)
    try:
        score = np.ravel(estimator.decision_function(X))
    except (AttributeError, NotImplementedError):
        score = estimator.predict_proba(X)[:, 1]
    return score

def _threshold_for_binary_predict(estimator):
    if hasattr(estimator, 'decision_function') and is_classifier(estimator):
        return 0.0
    else:
        return 0.5

def _estimators_has(attr):

    def check(self):
        if hasattr(self, 'estimators_'):
            getattr(self.estimators_[0], attr)
        else:
            getattr(self.estimator, attr)
        return True
    return check

def _partial_fit_ovo_binary(estimator, X, y, i, j, partial_fit_params):
    cond = np.logical_or(y == i, y == j)
    y = y[cond]
    if len(y) != 0:
        y_binary = np.zeros_like(y)
        y_binary[y == j] = 1
        partial_fit_params_subset = _check_method_params(X, params=partial_fit_params, indices=cond)
        return _partial_fit_binary(estimator, X[cond], y_binary, partial_fit_params=partial_fit_params_subset)
    return estimator

@available_if(_estimators_has('partial_fit'))
@_fit_context(prefer_skip_nested_validation=False)
def partial_fit(self, X, y, classes=None, **partial_fit_params):
    _raise_for_params(partial_fit_params, self, 'partial_fit')
    routed_params = process_routing(self, 'partial_fit', **partial_fit_params)
    if _check_partial_fit_first_call(self, classes):
        self.estimators_ = [clone(self.estimator) for _ in range(self.n_classes_)]
        self.label_binarizer_ = LabelBinarizer(sparse_output=True)
        self.label_binarizer_.fit(self.classes_)
    if len(np.setdiff1d(y, self.classes_)):
        raise ValueError(('Mini-batch contains {0} while classes ' + 'must be subset of {1}').format(np.unique(y), self.classes_))
    Y = self.label_binarizer_.transform(y)
    Y = Y.tocsc()
    columns = (col.toarray().ravel() for col in Y.T)
    self.estimators_ = Parallel(n_jobs=self.n_jobs)((delayed(_partial_fit_binary)(estimator, X, column, partial_fit_params=routed_params.estimator.partial_fit) for estimator, column in zip(self.estimators_, columns)))
    if hasattr(self.estimators_[0], 'n_features_in_'):
        self.n_features_in_ = self.estimators_[0].n_features_in_
    return self

@available_if(_estimators_has('predict_proba'))
def predict_proba(self, X):
    check_is_fitted(self)
    Y = np.array([e.predict_proba(X)[:, 1] for e in self.estimators_]).T
    if len(self.estimators_) == 1:
        Y = np.concatenate((1 - Y, Y), axis=1)
    if not self.multilabel_:
        row_sums = np.sum(Y, axis=1)[:, np.newaxis]
        np.divide(Y, row_sums, out=Y, where=row_sums != 0)
    return Y

@available_if(_estimators_has('decision_function'))
def decision_function(self, X):
    check_is_fitted(self)
    if len(self.estimators_) == 1:
        return self.estimators_[0].decision_function(X)
    return np.array([est.decision_function(X).ravel() for est in self.estimators_]).T

@property
def multilabel_(self):
    return self.label_binarizer_.y_type_.startswith('multilabel')

@property
def n_classes_(self):
    return len(self.classes_)

def get_metadata_routing(self):
    router = MetadataRouter(owner=self).add_self_request(self).add(estimator=self.estimator, method_mapping=MethodMapping().add(caller='fit', callee='fit').add(caller='partial_fit', callee='partial_fit'))
    return router

@available_if(_estimators_has('partial_fit'))
@_fit_context(prefer_skip_nested_validation=False)
def partial_fit(self, X, y, classes=None, **partial_fit_params):
    _raise_for_params(partial_fit_params, self, 'partial_fit')
    routed_params = process_routing(self, 'partial_fit', **partial_fit_params)
    first_call = _check_partial_fit_first_call(self, classes)
    if first_call:
        self.estimators_ = [clone(self.estimator) for _ in range(self.n_classes_ * (self.n_classes_ - 1) // 2)]
    if len(np.setdiff1d(y, self.classes_)):
        raise ValueError('Mini-batch contains {0} while it must be subset of {1}'.format(np.unique(y), self.classes_))
    X, y = validate_data(self, X, y, accept_sparse=['csr', 'csc'], ensure_all_finite=False, reset=first_call)
    check_classification_targets(y)
    combinations = itertools.combinations(range(self.n_classes_), 2)
    self.estimators_ = Parallel(n_jobs=self.n_jobs)((delayed(_partial_fit_ovo_binary)(estimator, X, y, self.classes_[i], self.classes_[j], partial_fit_params=routed_params.estimator.partial_fit) for estimator, (i, j) in zip(self.estimators_, combinations)))
    self.pairwise_indices_ = None
    if hasattr(self.estimators_[0], 'n_features_in_'):
        self.n_features_in_ = self.estimators_[0].n_features_in_
    return self

def predict(self, X):
    Y = self.decision_function(X)
    if self.n_classes_ == 2:
        thresh = _threshold_for_binary_predict(self.estimators_[0])
        return self.classes_[(Y > thresh).astype(int)]
    return self.classes_[Y.argmax(axis=1)]

@property
def n_classes_(self):
    return len(self.classes_)

def get_metadata_routing(self):
    router = MetadataRouter(owner=self).add_self_request(self).add(estimator=self.estimator, method_mapping=MethodMapping().add(caller='fit', callee='fit').add(caller='partial_fit', callee='partial_fit'))
    return router

@_fit_context(prefer_skip_nested_validation=False)
def fit(self, X, y, **fit_params):
    _raise_for_params(fit_params, self, 'fit')
    routed_params = process_routing(self, 'fit', **fit_params)
    y = validate_data(self, X='no_validation', y=y)
    random_state = check_random_state(self.random_state)
    check_classification_targets(y)
    self.classes_ = np.unique(y)
    n_classes = self.classes_.shape[0]
    if n_classes == 0:
        raise ValueError('OutputCodeClassifier can not be fit when no class is present.')
    n_estimators = int(n_classes * self.code_size)
    self.code_book_ = random_state.uniform(size=(n_classes, n_estimators))
    self.code_book_[self.code_book_ > 0.5] = 1.0
    if hasattr(self.estimator, 'decision_function'):
        self.code_book_[self.code_book_ != 1] = -1.0
    else:
        self.code_book_[self.code_book_ != 1] = 0.0
    classes_index = {c: i for i, c in enumerate(self.classes_)}
    Y = np.array([self.code_book_[classes_index[y[i]]] for i in range(_num_samples(y))], dtype=int)
    self.estimators_ = Parallel(n_jobs=self.n_jobs)((delayed(_fit_binary)(self.estimator, X, Y[:, i], fit_params=routed_params.estimator.fit) for i in range(Y.shape[1])))
    if hasattr(self.estimators_[0], 'n_features_in_'):
        self.n_features_in_ = self.estimators_[0].n_features_in_
    if hasattr(self.estimators_[0], 'feature_names_in_'):
        self.feature_names_in_ = self.estimators_[0].feature_names_in_
    return self

def get_metadata_routing(self):
    router = MetadataRouter(owner=self).add(estimator=self.estimator, method_mapping=MethodMapping().add(caller='fit', callee='fit'))
    return router

def _available_if_estimator_has(attr):

    def _check(self):
        if hasattr(self, 'estimators_'):
            return all((hasattr(est, attr) for est in self.estimators_))
        if hasattr(self.estimator, attr):
            return True
        return False
    return available_if(_check)

def _available_if_base_estimator_has(attr):

    def _check(self):
        return hasattr(self.estimator, attr) or all((hasattr(est, attr) for est in self.estimators_))
    return available_if(_check)

@_available_if_estimator_has('partial_fit')
@_fit_context(prefer_skip_nested_validation=False)
def partial_fit(self, X, y, classes=None, sample_weight=None, **partial_fit_params):
    _raise_for_params(partial_fit_params, self, 'partial_fit')
    first_time = not hasattr(self, 'estimators_')
    y = validate_data(self, X='no_validation', y=y, multi_output=True)
    if y.ndim == 1:
        raise ValueError('y must have at least two dimensions for multi-output regression but has only one.')
    if _routing_enabled():
        if sample_weight is not None:
            partial_fit_params['sample_weight'] = sample_weight
        routed_params = process_routing(self, 'partial_fit', **partial_fit_params)
    else:
        if sample_weight is not None and (not has_fit_parameter(self.estimator, 'sample_weight')):
            raise ValueError('Underlying estimator does not support sample weights.')
        sw = {'sample_weight': sample_weight} if sample_weight is not None else {}
        routed_params = _manual_routing({'estimator': {'partial_fit': sw}})
    self.estimators_ = Parallel(n_jobs=self.n_jobs)((delayed(_partial_fit_estimator)(self.estimators_[i] if not first_time else self.estimator, X, y[:, i], classes[i] if classes is not None else None, partial_fit_params=routed_params.estimator.partial_fit, first_time=first_time) for i in range(y.shape[1])))
    if first_time and hasattr(self.estimators_[0], 'n_features_in_'):
        self.n_features_in_ = self.estimators_[0].n_features_in_
    if first_time and hasattr(self.estimators_[0], 'feature_names_in_'):
        self.feature_names_in_ = self.estimators_[0].feature_names_in_
    return self

@_fit_context(prefer_skip_nested_validation=False)
def fit(self, X, y, sample_weight=None, **fit_params):
    if not hasattr(self.estimator, 'fit'):
        raise ValueError('The base estimator should implement a fit method')
    y = validate_data(self, X='no_validation', y=y, multi_output=True)
    if is_classifier(self):
        check_classification_targets(y)
    if y.ndim == 1:
        raise ValueError('y must have at least two dimensions for multi-output regression but has only one.')
    if _routing_enabled():
        if sample_weight is not None:
            fit_params['sample_weight'] = sample_weight
        routed_params = process_routing(self, 'fit', **fit_params)
    else:
        if sample_weight is not None and (not has_fit_parameter(self.estimator, 'sample_weight')):
            raise ValueError('Underlying estimator does not support sample weights.')
        fit_kwargs = dict(_check_method_params(X, params=fit_params))
        if sample_weight is not None:
            fit_kwargs['sample_weight'] = sample_weight
        routed_params = _manual_routing({'estimator': {'fit': fit_kwargs}})
    self.estimators_ = Parallel(n_jobs=self.n_jobs)((delayed(_fit_estimator)(self.estimator, X, y[:, i], **routed_params.estimator.fit) for i in range(y.shape[1])))
    if hasattr(self.estimators_[0], 'n_features_in_'):
        self.n_features_in_ = self.estimators_[0].n_features_in_
    if hasattr(self.estimators_[0], 'feature_names_in_'):
        self.feature_names_in_ = self.estimators_[0].feature_names_in_
    return self

def predict(self, X):
    check_is_fitted(self)
    if not hasattr(self.estimators_[0], 'predict'):
        raise ValueError('The base estimator should implement a predict method')
    y = Parallel(n_jobs=self.n_jobs)((delayed(e.predict)(X) for e in self.estimators_))
    return np.asarray(y).T

def get_metadata_routing(self):
    router = MetadataRouter(owner=self).add(estimator=self.estimator, method_mapping=MethodMapping().add(caller='partial_fit', callee='partial_fit').add(caller='fit', callee='fit'))
    return router

@_available_if_estimator_has('partial_fit')
def partial_fit(self, X, y, sample_weight=None, **partial_fit_params):
    super().partial_fit(X, y, sample_weight=sample_weight, **partial_fit_params)

@available_if(_check_predict_proba)
def predict_proba(self, X):
    check_is_fitted(self)
    results = [estimator.predict_proba(X) for estimator in self.estimators_]
    return results

def score(self, X, y):
    check_is_fitted(self)
    n_outputs_ = len(self.estimators_)
    if y.ndim == 1:
        raise ValueError('y must have at least two dimensions for multi target classification but has only one')
    if y.shape[1] != n_outputs_:
        raise ValueError('The number of outputs of Y for fit {0} and score {1} should be same'.format(n_outputs_, y.shape[1]))
    y_pred = self.predict(X)
    return np.mean(np.all(y == y_pred, axis=1))

@abstractmethod
def fit(self, X, Y, **fit_params):
    X, Y = validate_data(self, X, Y, multi_output=True, accept_sparse=True)
    random_state = check_random_state(self.random_state)
    self.order_ = self.order
    if isinstance(self.order_, tuple):
        self.order_ = np.array(self.order_)
    if self.order_ is None:
        self.order_ = np.array(range(Y.shape[1]))
    elif isinstance(self.order_, str):
        if self.order_ == 'random':
            self.order_ = random_state.permutation(Y.shape[1])
    elif sorted(self.order_) != list(range(Y.shape[1])):
        raise ValueError('invalid order')
    self.estimators_ = [clone(self.estimator) for _ in range(Y.shape[1])]
    if self.cv is None:
        Y_pred_chain = Y[:, self.order_]
        if sp.issparse(X):
            X_aug = sp.hstack((X, Y_pred_chain), format='lil')
            X_aug = X_aug.tocsr()
        else:
            X_aug = np.hstack((X, Y_pred_chain))
    elif sp.issparse(X):
        if not sp.isspmatrix(X):
            if X.format == 'dok':
                X = sp.coo_array(X)
            Y_pred_chain = sp.coo_array((X.shape[0], Y.shape[1]))
        else:
            Y_pred_chain = sp.coo_matrix((X.shape[0], Y.shape[1]))
        X_aug = sp.hstack((X, Y_pred_chain), format='lil')
    else:
        Y_pred_chain = np.zeros((X.shape[0], Y.shape[1]))
        X_aug = np.hstack((X, Y_pred_chain))
    del Y_pred_chain
    if _routing_enabled():
        routed_params = process_routing(self, 'fit', **fit_params)
    else:
        routed_params = _manual_routing({'estimator': {'fit': fit_params}})
    if hasattr(self, 'chain_method'):
        chain_method = _check_response_method(self.estimator, self.chain_method).__name__
        self.chain_method_ = chain_method
    else:
        chain_method = 'predict'
    for chain_idx, estimator in enumerate(self.estimators_):
        message = self._log_message(estimator_idx=chain_idx + 1, n_estimators=len(self.estimators_), processing_msg=f'Processing order {self.order_[chain_idx]}')
        y = Y[:, self.order_[chain_idx]]
        with _print_elapsed_time('Chain', message):
            estimator.fit(X_aug[:, :X.shape[1] + chain_idx], y, **routed_params.estimator.fit)
        if self.cv is not None and chain_idx < len(self.estimators_) - 1:
            col_idx = X.shape[1] + chain_idx
            cv_result = cross_val_predict(self.estimator, X_aug[:, :col_idx], y=y, cv=self.cv, method=chain_method)
            if cv_result.ndim > 1:
                cv_result = cv_result[:, 1]
            if sp.issparse(X_aug):
                X_aug[:, col_idx] = np.expand_dims(cv_result, 1)
            else:
                X_aug[:, col_idx] = cv_result
    return self

