def _update_class_log_prior(self, class_prior=None):
    n_classes = len(self.classes_)
    if class_prior is not None:
        if len(class_prior) != n_classes:
            raise ValueError('Number of priors must match number of classes.')
        self.class_log_prior_ = np.log(class_prior)
    elif self.fit_prior:
        with warnings.catch_warnings():
            warnings.simplefilter('ignore', RuntimeWarning)
            log_class_count = np.log(self.class_count_)
        self.class_log_prior_ = log_class_count - np.log(self.class_count_.sum())
    else:
        self.class_log_prior_ = np.full(n_classes, -np.log(n_classes))

def _update_feature_log_prob(self, alpha):
    comp_count = self.feature_all_ + alpha - self.feature_count_
    logged = np.log(comp_count / comp_count.sum(axis=1, keepdims=True))
    if self.norm:
        summed = logged.sum(axis=1, keepdims=True)
        feature_log_prob = logged / summed
    else:
        feature_log_prob = -logged
    self.feature_log_prob_ = feature_log_prob

def _joint_log_likelihood(self, X):
    jll = safe_sparse_dot(X, self.feature_log_prob_.T)
    if len(self.classes_) == 1:
        jll += self.class_log_prior_
    return jll

def _check_X(self, X):
    X = super()._check_X(X)
    if self.binarize is not None:
        X = binarize(X, threshold=self.binarize)
    return X

def _count(self, X, Y):
    self.feature_count_ += safe_sparse_dot(Y.T, X)
    self.class_count_ += Y.sum(axis=0)

def _final_estimator_has(attr):

    def check(self):
        getattr(self._final_estimator, attr)
        return True
    return check

def _cached_transform(sub_pipeline, *, cache, param_name, param_value, transform_params):
    if param_name not in cache:
        if isinstance(param_value, tuple):
            cache[param_name] = tuple((sub_pipeline.transform(element, **transform_params) for element in param_value))
        else:
            cache[param_name] = sub_pipeline.transform(param_value, **transform_params)
    return cache[param_name]

def _name_estimators(estimators):
    names = [estimator if isinstance(estimator, str) else type(estimator).__name__.lower() for estimator in estimators]
    namecount = defaultdict(int)
    for est, name in zip(estimators, names):
        namecount[name] += 1
    for k, v in list(namecount.items()):
        if v == 1:
            del namecount[k]
    for i in reversed(range(len(estimators))):
        name = names[i]
        if name in namecount:
            names[i] += '-%d' % namecount[name]
            namecount[name] -= 1
    return list(zip(names, estimators))

def _transform_one(transformer, X, y, weight, params):
    res = transformer.transform(X, **params['transform'])
    if weight is None:
        return res
    return res * weight

def _fit_transform_one(transformer, X, y, weight, message_clsname='', message=None, params=None):
    params = params or {}
    with _print_elapsed_time(message_clsname, message):
        if hasattr(transformer, 'fit_transform'):
            res = transformer.fit_transform(X, y, **params.get('fit_transform', {}))
        else:
            res = transformer.fit(X, y, **params.get('fit', {})).transform(X, **params.get('transform', {}))
    if weight is None:
        return (res, transformer)
    return (res * weight, transformer)

def _fit_one(transformer, X, y, weight, message_clsname='', message=None, params=None):
    with _print_elapsed_time(message_clsname, message):
        return transformer.fit(X, y, **params['fit'])

