def __sklearn_is_fitted__(self):
    last_step = None
    for _, estimator in reversed(self.steps):
        if estimator != 'passthrough':
            last_step = estimator
            break
    if last_step is None:
        return True
    try:
        check_is_fitted(last_step)
        return True
    except NotFittedError:
        return False

def get_metadata_routing(self):
    router = MetadataRouter(owner=self)
    for _, name, trans in self._iter(with_final=False, filter_passthrough=True):
        method_mapping = MethodMapping()
        if hasattr(trans, 'fit_transform'):
            method_mapping.add(caller='fit', callee='fit_transform').add(caller='fit_transform', callee='fit_transform').add(caller='fit_predict', callee='fit_transform')
        else:
            method_mapping.add(caller='fit', callee='fit').add(caller='fit', callee='transform').add(caller='fit_transform', callee='fit').add(caller='fit_transform', callee='transform').add(caller='fit_predict', callee='fit').add(caller='fit_predict', callee='transform')
        method_mapping.add(caller='predict', callee='transform').add(caller='predict', callee='transform').add(caller='predict_proba', callee='transform').add(caller='decision_function', callee='transform').add(caller='predict_log_proba', callee='transform').add(caller='transform', callee='transform').add(caller='inverse_transform', callee='inverse_transform').add(caller='score', callee='transform')
        router.add(method_mapping=method_mapping, **{name: trans})
    final_name, final_est = self.steps[-1]
    if final_est is None or final_est == 'passthrough':
        return router
    method_mapping = MethodMapping()
    if hasattr(final_est, 'fit_transform'):
        method_mapping.add(caller='fit_transform', callee='fit_transform')
    else:
        method_mapping.add(caller='fit', callee='fit').add(caller='fit', callee='transform')
    method_mapping.add(caller='fit', callee='fit').add(caller='predict', callee='predict').add(caller='fit_predict', callee='fit_predict').add(caller='predict_proba', callee='predict_proba').add(caller='decision_function', callee='decision_function').add(caller='predict_log_proba', callee='predict_log_proba').add(caller='transform', callee='transform').add(caller='inverse_transform', callee='inverse_transform').add(caller='score', callee='score')
    router.add(method_mapping=method_mapping, **{final_name: final_est})
    return router

def set_output(self, *, transform=None):
    super().set_output(transform=transform)
    for _, step, _ in self._iter():
        _safe_set_output(step, transform=transform)
    return self

def set_params(self, **kwargs):
    self._set_params('transformer_list', **kwargs)
    return self

def _iter(self):
    get_weight = (self.transformer_weights or {}).get
    for name, trans in self.transformer_list:
        if trans == 'drop':
            continue
        if trans == 'passthrough':
            trans = FunctionTransformer(feature_names_out='one-to-one')
        yield (name, trans, get_weight(name))

def get_feature_names_out(self, input_features=None):
    transformer_with_feature_names_out = []
    for i, (name, trans, _) in enumerate(self._iter()):
        if hasattr(trans, 'get_feature_names_out'):
            feature_names_out = trans.get_feature_names_out(input_features)
        elif hasattr(self, '_transformers_feature_names_out'):
            feature_names_out = self._transformers_feature_names_out[i]
        else:
            raise AttributeError(f'Transformer {name} (type {type(trans).__name__}) does not provide get_feature_names_out.')
        transformer_with_feature_names_out.append((name, feature_names_out))
    return self._add_prefix_for_feature_names_out(transformer_with_feature_names_out)

def _add_prefix_for_feature_names_out(self, transformer_with_feature_names_out):
    if self.verbose_feature_names_out:
        names = list(chain.from_iterable(((f'{name}__{i}' for i in feature_names_out) for name, feature_names_out in transformer_with_feature_names_out)))
        return np.asarray(names, dtype=object)
    feature_names_count = Counter(chain.from_iterable((s for _, s in transformer_with_feature_names_out)))
    top_6_overlap = [name for name, count in feature_names_count.most_common(6) if count > 1]
    top_6_overlap.sort()
    if top_6_overlap:
        if len(top_6_overlap) == 6:
            names_repr = str(top_6_overlap[:5])[:-1] + ', ...]'
        else:
            names_repr = str(top_6_overlap)
        raise ValueError(f'Output feature names: {names_repr} are not unique. Please set verbose_feature_names_out=True to add prefixes to feature names')
    return np.concatenate([name for _, name in transformer_with_feature_names_out])

def fit(self, X, y=None, **fit_params):
    if _routing_enabled():
        routed_params = process_routing(self, 'fit', **fit_params)
    else:
        routed_params = _manual_routing({name: {'fit': fit_params} for name, _ in self.transformer_list})
    transformers = self._parallel_func(X, y, _fit_one, routed_params)
    if not transformers:
        return self
    self._update_transformer_list(transformers)
    return self

def fit_transform(self, X, y=None, **params):
    if _routing_enabled():
        routed_params = process_routing(self, 'fit_transform', **params)
    else:
        routed_params = _manual_routing({name: {'fit': params, 'fit_transform': params} for name, _ in self.transformer_list})
    results = self._parallel_func(X, y, _fit_transform_one, routed_params)
    if not results:
        xp, _, device = get_namespace_and_device(X)
        return xp.zeros((X.shape[0], 0), device=device)
    Xs, transformers = zip(*results)
    self._update_transformer_list(transformers)
    return self._hstack(Xs)

def _parallel_func(self, X, y, func, routed_params):
    self.transformer_list = list(self.transformer_list)
    self._validate_transformers()
    self._validate_transformer_weights()
    transformers = list(self._iter())
    return Parallel(n_jobs=self.n_jobs)((delayed(func)(transformer, X, y, weight, message_clsname='FeatureUnion', message=self._log_message(name, idx, len(transformers)), params=routed_params[name]) for idx, (name, transformer, weight) in enumerate(transformers, 1)))

def transform(self, X, **params):
    _raise_for_params(params, self, 'transform')
    if _routing_enabled():
        routed_params = process_routing(self, 'transform', **params)
    else:
        routed_params = _manual_routing({name: {} for name, _ in self.transformer_list})
    Xs = Parallel(n_jobs=self.n_jobs)((delayed(_transform_one)(trans, X, None, weight, params=routed_params[name]) for name, trans, weight in self._iter()))
    if not Xs:
        xp, _, device = get_namespace_and_device(X)
        return xp.zeros((X.shape[0], 0), device=device)
    return self._hstack(Xs)

@property
def n_features_in_(self):
    return self.transformer_list[0][1].n_features_in_

@property
def feature_names_in_(self):
    return self.transformer_list[0][1].feature_names_in_

def __getitem__(self, name):
    if not isinstance(name, str):
        raise KeyError('Only string keys are supported')
    return self.named_transformers[name]

def get_metadata_routing(self):
    router = MetadataRouter(owner=self)
    for name, transformer in self.transformer_list:
        router.add(**{name: transformer}, method_mapping=MethodMapping().add(caller='fit', callee='fit').add(caller='fit_transform', callee='fit_transform').add(caller='fit_transform', callee='fit').add(caller='fit_transform', callee='transform').add(caller='transform', callee='transform'))
    return router

@validate_params({'n_samples': ['array-like', Interval(Real, 1, None, closed='left')], 'eps': ['array-like', Interval(Real, 0, 1, closed='neither')]}, prefer_skip_nested_validation=True)
def johnson_lindenstrauss_min_dim(n_samples, *, eps=0.1):
    eps = np.asarray(eps)
    n_samples = np.asarray(n_samples)
    if np.any(eps <= 0.0) or np.any(eps >= 1):
        raise ValueError('The JL bound is defined for eps in ]0, 1[, got %r' % eps)
    if np.any(n_samples <= 0):
        raise ValueError('The JL bound is defined for n_samples greater than zero, got %r' % n_samples)
    denominator = eps ** 2 / 2 - eps ** 3 / 3
    return (4 * np.log(n_samples) / denominator).astype(np.int64)

def _check_density(density, n_features):
    if density == 'auto':
        density = 1 / np.sqrt(n_features)
    elif density <= 0 or density > 1:
        raise ValueError('Expected density in range ]0, 1], got: %r' % density)
    return density

def _check_input_size(n_components, n_features):
    if n_components <= 0:
        raise ValueError('n_components must be strictly positive, got %d' % n_components)
    if n_features <= 0:
        raise ValueError('n_features must be strictly positive, got %d' % n_features)

@abstractmethod
def _make_random_matrix(self, n_components, n_features):
    pass

def _compute_inverse_components(self):
    components = self.components_
    if sp.issparse(components):
        components = components.toarray()
    return linalg.pinv(components, check_finite=False)

@_fit_context(prefer_skip_nested_validation=True)
def fit(self, X, y=None):
    X = validate_data(self, X, accept_sparse=['csr', 'csc'], dtype=[np.float64, np.float32])
    n_samples, n_features = X.shape
    if self.n_components == 'auto':
        self.n_components_ = johnson_lindenstrauss_min_dim(n_samples=n_samples, eps=self.eps)
        if self.n_components_ <= 0:
            raise ValueError('eps=%f and n_samples=%d lead to a target dimension of %d which is invalid' % (self.eps, n_samples, self.n_components_))
        elif self.n_components_ > n_features:
            raise ValueError('eps=%f and n_samples=%d lead to a target dimension of %d which is larger than the original space with n_features=%d' % (self.eps, n_samples, self.n_components_, n_features))
    else:
        if self.n_components > n_features:
            warnings.warn('The number of components is higher than the number of features: n_features < n_components (%s < %s).The dimensionality of the problem will not be reduced.' % (n_features, self.n_components), DataDimensionalityWarning)
        self.n_components_ = self.n_components
    self.components_ = self._make_random_matrix(self.n_components_, n_features).astype(X.dtype, copy=False)
    if self.compute_inverse_components:
        self.inverse_components_ = self._compute_inverse_components()
    self._n_features_out = self.n_components
    return self

def inverse_transform(self, X):
    check_is_fitted(self)
    X = check_array(X, dtype=[np.float64, np.float32], accept_sparse=('csr', 'csc'))
    if self.compute_inverse_components:
        return _align_api_if_sparse(X @ self.inverse_components_.T)
    inverse_components = self._compute_inverse_components()
    return _align_api_if_sparse(X @ inverse_components.T)

def _make_random_matrix(self, n_components, n_features):
    random_state = check_random_state(self.random_state)
    return _gaussian_random_matrix(n_components, n_features, random_state=random_state)

def transform(self, X):
    check_is_fitted(self)
    X = validate_data(self, X, accept_sparse=['csr', 'csc'], reset=False, dtype=[np.float64, np.float32])
    return _align_api_if_sparse(X @ self.components_.T)

def _make_random_matrix(self, n_components, n_features):
    random_state = check_random_state(self.random_state)
    self.density_ = _check_density(self.density, n_features)
    return _sparse_random_matrix(n_components, n_features, density=self.density_, random_state=random_state)

def transform(self, X):
    check_is_fitted(self)
    X = validate_data(self, X, accept_sparse=['csr', 'csc'], reset=False, dtype=[np.float64, np.float32])
    return _align_api_if_sparse(safe_sparse_dot(X, self.components_.T, dense_output=self.dense_output))

def _get_threadlocal_config():
    if not hasattr(_threadlocal, 'global_config'):
        _threadlocal.global_config = _global_config.copy()
    return _threadlocal.global_config

def set_config(assume_finite=None, working_memory=None, print_changed_only=None, display=None, pairwise_dist_chunk_size=None, enable_cython_pairwise_dist=None, array_api_dispatch=None, transform_output=None, enable_metadata_routing=None, skip_parameter_validation=None, sparse_interface=None):
    local_config = _get_threadlocal_config()
    if assume_finite is not None:
        local_config['assume_finite'] = assume_finite
    if working_memory is not None:
        local_config['working_memory'] = working_memory
    if print_changed_only is not None:
        local_config['print_changed_only'] = print_changed_only
    if display is not None:
        local_config['display'] = display
    if pairwise_dist_chunk_size is not None:
        local_config['pairwise_dist_chunk_size'] = pairwise_dist_chunk_size
    if enable_cython_pairwise_dist is not None:
        local_config['enable_cython_pairwise_dist'] = enable_cython_pairwise_dist
    if array_api_dispatch is not None:
        from sklearn.utils._array_api import _check_array_api_dispatch
        _check_array_api_dispatch(array_api_dispatch)
        local_config['array_api_dispatch'] = array_api_dispatch
    if transform_output is not None:
        local_config['transform_output'] = transform_output
    if enable_metadata_routing is not None:
        local_config['enable_metadata_routing'] = enable_metadata_routing
    if skip_parameter_validation is not None:
        local_config['skip_parameter_validation'] = skip_parameter_validation
    if sparse_interface is not None:
        local_config['sparse_interface'] = sparse_interface

@contextmanager
def config_context(*, assume_finite=None, working_memory=None, print_changed_only=None, display=None, pairwise_dist_chunk_size=None, enable_cython_pairwise_dist=None, array_api_dispatch=None, transform_output=None, enable_metadata_routing=None, skip_parameter_validation=None, sparse_interface=None):
    old_config = get_config()
    set_config(assume_finite=assume_finite, working_memory=working_memory, print_changed_only=print_changed_only, display=display, pairwise_dist_chunk_size=pairwise_dist_chunk_size, enable_cython_pairwise_dist=enable_cython_pairwise_dist, array_api_dispatch=array_api_dispatch, transform_output=transform_output, enable_metadata_routing=enable_metadata_routing, skip_parameter_validation=skip_parameter_validation, sparse_interface=sparse_interface)
    try:
        yield
    finally:
        set_config(**old_config)

@property
def max_propagation_depth(self):
    pass

def _from_reconstruction_attributes(estimator, reconstruction_attributes):
    new_estimator = copy.copy(estimator)
    for key, val in reconstruction_attributes.items():
        setattr(new_estimator, key, val)
    return new_estimator

def __iter__(self):
    yield self
    for context in self._children_map.values():
        yield from context

def _add_child(self, child_context):
    if child_context.task_id in self._children_map:
        raise ValueError(f'Callback context {self.task_name} of estimator {self.estimator_name} already has a child with task_id={child_context.task_id}.')
    if self.max_subtasks is not None and len(self._children_map) >= self.max_subtasks:
        raise ValueError(f'Cannot add child to callback context {self.task_name} of estimator {self.estimator_name} because it already has its maximum number of children ({self.max_subtasks}).')
    self._children_map[child_context.task_id] = child_context
    child_context.parent = self

def subcontext(self, task_name='', task_id=None, max_subtasks=0, sequential_subtasks=True):
    if self.sequential_subtasks and task_id is not None:
        raise ValueError(f'task_id for {self.estimator_name} {task_name} must be None if sequential_subtasks is True for {self.task_name}.')
    if not self.sequential_subtasks and task_id is None:
        raise ValueError(f'task_id for {self.estimator_name} {task_name} must be provided if sequential_subtasks is False for {self.task_name}.')
    if task_id is None:
        task_id = len(self._children_map)
    return CallbackContext._from_parent(parent_context=self, task_name=task_name, task_id=task_id, max_subtasks=max_subtasks, sequential_subtasks=sequential_subtasks)

def _call_hooks(self, estimator, hook_name, **kwargs):
    result = False
    evaluated_args = {}
    for callback in self._callbacks:
        if callback in getattr(self, '_propagated_callbacks', []):
            continue
        signature = _cached_signature(getattr(callback, hook_name))
        params_names = {p.name for p in signature.parameters.values() if p.kind == p.KEYWORD_ONLY}
        if (diff := (set(params_names) - set(VALID_HOOK_PARAMS_OUT))):
            raise TypeError(f'Hook {hook_name} of the callback {callback.__class__.__name__} has parameters that are not valid: {diff}. The valid parameters are: {VALID_HOOK_PARAMS_OUT}.')
        args_to_pass = {}
        for param_name in params_names:
            if param_name not in evaluated_args:
                if param_name == 'fitted_estimator':
                    attrs = kwargs.get('reconstruction_attributes', None)
                    attrs = attrs() if callable(attrs) else attrs
                    new_est = _from_reconstruction_attributes(estimator, attrs) if attrs is not None else None
                    evaluated_args['fitted_estimator'] = new_est
                else:
                    val = kwargs.get(param_name, None)
                    val = val() if callable(val) else val
                    evaluated_args[param_name] = val
            args_to_pass[param_name] = evaluated_args[param_name]
        result |= bool(getattr(callback, hook_name)(estimator, self, **args_to_pass))
    return result

def call_on_fit_task_begin(self, *, estimator, X=None, y=None, metadata=None, reconstruction_attributes=None):
    self._call_hooks(estimator, hook_name='on_fit_task_begin', X=X, y=y, metadata=metadata, reconstruction_attributes=reconstruction_attributes)
    return self

@contextmanager
def callback_management_context(estimator):
    try:
        yield
    finally:
        if hasattr(estimator, '_callback_fit_ctx'):
            teardown_errors = []
            for callback in estimator._skl_callbacks_to_teardown:
                try:
                    callback.teardown(estimator=estimator, context=estimator._callback_fit_ctx)
                except Exception as exc:
                    teardown_errors.append(exc)
            del estimator._skl_callbacks_to_teardown
            del estimator._callback_fit_ctx
            if len(teardown_errors) == 1:
                raise teardown_errors[0]
            if teardown_errors:
                raise ExceptionGroup('The following callback teardown errors occurred', teardown_errors)

def with_callbacks(method):

    @functools.wraps(method)
    def callback_managed_method(estimator, *args, **kwargs):
        with callback_management_context(estimator):
            return method(estimator, *args, **kwargs)
    return callback_managed_method

def set_callbacks(self, *callbacks):
    if not all((isinstance(callback, FitCallback) and (not isinstance(callback, type)) for callback in callbacks)):
        raise TypeError('callbacks must be instances following the FitCallback protocol.')
    if callbacks:
        self._skl_callbacks = list(callbacks)
    else:
        self.__dict__.pop('_skl_callbacks', None)
    return self

def _init_callback_context(self, task_name='fit', task_id=0, max_subtasks=0, sequential_subtasks=True):
    self._callback_fit_ctx = CallbackContext._from_estimator(estimator=self, task_name=task_name, task_id=task_id, max_subtasks=max_subtasks, sequential_subtasks=sequential_subtasks)
    self._skl_callbacks_to_teardown = []
    for callback in getattr(self, '_skl_callbacks', []):
        if not (isinstance(callback, AutoPropagatedCallback) and hasattr(self, '_parent_callback_ctx')):
            self._skl_callbacks_to_teardown.append(callback)
            callback.setup(estimator=self, context=self._callback_fit_ctx)
    return self._callback_fit_ctx

def _on_task_begin(self, task_info):
    path = task_info.pop('path')
    rich_task = RichTask(progress_ctx=self.progress_ctx, task_info=task_info, depth=len(path) - 1)
    if rich_task.depth == 0:
        self.root_rich_task = rich_task
    else:
        parent = self.root_rich_task.get_descendants(path)[-2]
        parent.children[path[-1]] = rich_task
    self.progress_ctx._ordered_tasks = [self.progress_ctx.tasks[task.id] for task in self.root_rich_task]

def _on_task_end(self, task_info):
    path = task_info.pop('path')
    *ancestors, task = self.root_rich_task.get_descendants(path)
    if task is None:
        task = RichTask(self.progress_ctx, task_info, depth=len(ancestors))
        ancestors[-1].children[path[-1]] = task
    else:
        task.completed = task.total
        self.progress_ctx.update(task.id, completed=1, total=1)
    for ancestor in reversed(ancestors):
        if ancestor.total is None:
            continue
        completed = ancestor.progress * ancestor.total
        self.progress_ctx.update(ancestor.id, completed=completed)

@property
def progress(self):
    if self.completed == self.total:
        return 1.0
    if self.total is None:
        return 0.0
    return sum((child.progress for child in self.children.values())) / self.total

def get_descendants(self, path):
    if len(path) == 1:
        return [self]
    if path[1] not in self.children:
        return [self, None]
    return [self] + self.children[path[1]].get_descendants(path[1:])

def __iter__(self):
    if hasattr(self, 'id'):
        yield self
        for child in self.children.values():
            yield from child

def __setstate__(self, state):
    self.__dict__.update(state)
    if not can_reuse_listener(self._listener_handle):
        self._listener_handle = open_listener(self._log.append, owner=self)

@validate_params({'select': [StrOptions({'all', 'most_recent'})], 'as_frame': ['boolean'], 'include_lineage': ['boolean']}, prefer_skip_nested_validation=True)
def get_logs(self, select='most_recent', include_lineage=False):
    logs = defaultdict(lambda: {'data': []})
    run_to_task_id_path = defaultdict(set)
    if len(self._log) == 0:
        raise ValueError('No logs to retrieve. No scores were computed during the runs or the estimator is not fitted yet')
    for run_id, run_info, task_info_path, scores in self._log:
        logs[run_id].update(run_info)
        task_id_path = tuple((task_info['task_id'] for task_info in task_info_path))
        logs[run_id]['data'].append({'task_id_path': task_id_path, 'parent_task_id_path': task_id_path[:-1], 'parent_task_info_path': task_info_path[:-1], **task_info_path[-1], **scores})
        run_to_task_id_path[run_id].add(task_id_path)
    for run_id, log in logs.items():
        if include_lineage:
            extra_rows = []
            for row in log['data']:
                for i in range(len(row['parent_task_info_path'])):
                    task_info_path = row['parent_task_info_path'][:i + 1]
                    task_id_path = tuple((task_info['task_id'] for task_info in task_info_path))
                    if task_id_path not in run_to_task_id_path[run_id]:
                        extra_rows.append({'task_id_path': task_id_path, 'parent_task_id_path': task_id_path[:-1], 'parent_task_info_path': task_info_path[:-1], **task_info_path[-1]})
                        run_to_task_id_path[run_id].add(task_id_path)
            log['data'] += extra_rows
        sorting_key = lambda x: (len(x['task_id_path']), x['task_id_path'])
        log['data'] = sorted(log['data'], key=sorting_key)
        for row in log['data']:
            row.pop('parent_task_info_path', None)
    logs = [ScoringMonitorLog(run_id=run_id, **log) for run_id, log in logs.items()]
    logs.sort(key=lambda log: (log.timestamp, log.estimator_name))
    if select == 'most_recent':
        return logs[-1]
    return logs

def open_listener(message_consumer, *, owner=None):
    authkey = os.urandom(32)
    listener = Listener(authkey=authkey, backlog=128)
    listener_handle = ListenerHandle(address=listener.address, authkey=authkey)
    _listeners[listener_handle.address] = listener
    _message_consumers[listener_handle.address] = message_consumer
    if owner is not None:
        weakref.finalize(owner, close_listener, listener_handle)

    def _handle(conn):
        try:
            while True:
                message_consumer(conn.recv())
                conn.send(None)
        except (EOFError, OSError):
            return

    def _accept():
        while True:
            try:
                conn = listener.accept()
            except OSError:
                return
            Thread(target=_handle, args=(conn,), daemon=True).start()
    Thread(target=_accept, daemon=True).start()
    return listener_handle

def close_listener(listener_handle):
    _message_consumers.pop(listener_handle.address, None)
    listener = _listeners.pop(listener_handle.address, None)
    if listener is not None:
        listener.close()

def can_reuse_listener(listener_handle):
    if listener_handle.address in _listeners:
        return False
    try:
        Client(listener_handle.address, authkey=listener_handle.authkey).close()
    except OSError:
        return False
    return True

@validate_params({'S': ['array-like'], 'return_n_iter': ['boolean']}, prefer_skip_nested_validation=False)
def affinity_propagation(S, *, preference=None, convergence_iter=15, max_iter=200, damping=0.5, copy=True, verbose=False, return_n_iter=False, random_state=None):
    estimator = AffinityPropagation(damping=damping, max_iter=max_iter, convergence_iter=convergence_iter, copy=copy, preference=preference, affinity='precomputed', verbose=verbose, random_state=random_state).fit(S)
    if return_n_iter:
        return (estimator.cluster_centers_indices_, estimator.labels_, estimator.n_iter_)
    return (estimator.cluster_centers_indices_, estimator.labels_)

@_fit_context(prefer_skip_nested_validation=True)
def fit(self, X, y=None):
    if self.affinity == 'precomputed':
        X = validate_data(self, X, copy=self.copy, force_writeable=True)
        self.affinity_matrix_ = X
    else:
        X = validate_data(self, X, accept_sparse='csr')
        self.affinity_matrix_ = -euclidean_distances(X, squared=True)
    if self.affinity_matrix_.shape[0] != self.affinity_matrix_.shape[1]:
        raise ValueError(f'The matrix of similarities must be a square array. Got {self.affinity_matrix_.shape} instead.')
    if self.preference is None:
        preference = np.median(self.affinity_matrix_)
    else:
        preference = self.preference
    preference = np.asarray(preference)
    random_state = check_random_state(self.random_state)
    self.cluster_centers_indices_, self.labels_, self.n_iter_ = _affinity_propagation(self.affinity_matrix_, max_iter=self.max_iter, convergence_iter=self.convergence_iter, preference=preference, damping=self.damping, verbose=self.verbose, return_n_iter=True, random_state=random_state)
    if self.affinity != 'precomputed':
        self.cluster_centers_ = X[self.cluster_centers_indices_].copy()
    return self

def predict(self, X):
    check_is_fitted(self)
    X = validate_data(self, X, reset=False, accept_sparse='csr')
    if not hasattr(self, 'cluster_centers_'):
        raise ValueError("Predict method is not supported when affinity='precomputed'.")
    if self.cluster_centers_.shape[0] > 0:
        with config_context(assume_finite=True):
            return pairwise_distances_argmin(X, self.cluster_centers_)
    else:
        warnings.warn("This model does not have any cluster centers because affinity propagation did not converge. Labeling every sample as '-1'.", ConvergenceWarning)
        return np.array([-1] * X.shape[0])

def _fix_connectivity(X, connectivity, affinity):
    n_samples = X.shape[0]
    if connectivity.shape[0] != n_samples or connectivity.shape[1] != n_samples:
        raise ValueError('Wrong shape for connectivity matrix: %s when X is %s' % (connectivity.shape, X.shape))
    connectivity = connectivity + connectivity.T
    if not sparse.issparse(connectivity):
        connectivity = sparse.lil_array(connectivity)
    if connectivity.format != 'lil':
        connectivity = connectivity.tolil()
    n_connected_components, labels = connected_components(connectivity)
    if n_connected_components > 1:
        warnings.warn('the number of connected components of the connectivity matrix is %d > 1. Completing it to avoid stopping the tree early.' % n_connected_components, stacklevel=2)
        connectivity = _fix_connected_components(X=X, graph=connectivity, n_connected_components=n_connected_components, component_labels=labels, metric=affinity, mode='connectivity')
    return (_align_api_if_sparse(connectivity), n_connected_components)

def _single_linkage_tree(connectivity, n_samples, n_nodes, n_clusters, n_connected_components, return_distance):
    from scipy.sparse.csgraph import minimum_spanning_tree
    connectivity = connectivity.astype(np.float64, copy=False)
    epsilon_value = np.finfo(dtype=connectivity.data.dtype).eps
    connectivity.data[connectivity.data == 0] = epsilon_value
    mst = minimum_spanning_tree(connectivity.tocsr())
    mst = mst.tocoo()
    mst.data[mst.data == epsilon_value] = 0
    mst_array = np.vstack([mst.row, mst.col, mst.data]).T
    mst_array = mst_array[np.argsort(mst_array.T[2], kind='mergesort'), :]
    single_linkage_tree = _hierarchical._single_linkage_label(mst_array)
    children_ = single_linkage_tree[:, :2].astype(int)
    parent = np.arange(n_nodes, dtype=np.intp)
    for i, (left, right) in enumerate(children_, n_samples):
        if n_clusters is not None and i >= n_nodes:
            break
        if left < n_nodes:
            parent[left] = i
        if right < n_nodes:
            parent[right] = i
    if return_distance:
        distances = single_linkage_tree[:, 2]
        return (children_, n_connected_components, n_samples, parent, distances)
    return (children_, n_connected_components, n_samples, parent)

def linkage_tree(X, connectivity=None, n_clusters=None, linkage='complete', affinity='euclidean', return_distance=False):
    X = np.asarray(X)
    if X.ndim == 1:
        X = np.reshape(X, (-1, 1))
    n_samples, n_features = X.shape
    linkage_choices = {'complete': _hierarchical.max_merge, 'average': _hierarchical.average_merge, 'single': None}
    try:
        join_func = linkage_choices[linkage]
    except KeyError as e:
        raise ValueError('Unknown linkage option, linkage should be one of %s, but %s was given' % (linkage_choices.keys(), linkage)) from e
    if affinity == 'cosine' and np.any(~np.any(X, axis=1)):
        raise ValueError('Cosine affinity cannot be used when X contains zero vectors')
    if connectivity is None:
        from scipy.cluster import hierarchy
        if n_clusters is not None:
            warnings.warn('Partial build of the tree is implemented only for structured clustering (i.e. with explicit connectivity). The algorithm will build the full tree and only retain the lower branches required for the specified number of clusters', stacklevel=2)
        if affinity == 'precomputed':
            if X.shape[0] != X.shape[1]:
                raise ValueError(f'Distance matrix should be square, got matrix of shape {X.shape}')
            i, j = np.triu_indices(X.shape[0], k=1)
            X = X[i, j]
        elif affinity == 'l2':
            affinity = 'euclidean'
        elif affinity in ('l1', 'manhattan'):
            affinity = 'cityblock'
        elif callable(affinity):
            X = affinity(X)
            i, j = np.triu_indices(X.shape[0], k=1)
            X = X[i, j]
        if linkage == 'single' and affinity != 'precomputed' and (not callable(affinity)) and (affinity in METRIC_MAPPING64):
            dist_metric = DistanceMetric.get_metric(affinity)
            X = np.ascontiguousarray(X, dtype=np.double)
            mst = _hierarchical.mst_linkage_core(X, dist_metric)
            mst = mst[np.argsort(mst.T[2], kind='mergesort'), :]
            out = _hierarchical.single_linkage_label(mst)
        else:
            out = hierarchy.linkage(X, method=linkage, metric=affinity)
        children_ = out[:, :2].astype(int, copy=False)
        if return_distance:
            distances = out[:, 2]
            return (children_, 1, n_samples, None, distances)
        return (children_, 1, n_samples, None)
    connectivity, n_connected_components = _fix_connectivity(X, connectivity, affinity=affinity)
    connectivity = connectivity.tocoo()
    diag_mask = connectivity.row != connectivity.col
    connectivity.row = connectivity.row[diag_mask]
    connectivity.col = connectivity.col[diag_mask]
    connectivity.data = connectivity.data[diag_mask]
    del diag_mask
    if affinity == 'precomputed':
        distances = X[connectivity.row, connectivity.col].astype(np.float64, copy=False)
    else:
        distances = paired_distances(X[connectivity.row], X[connectivity.col], metric=affinity)
    connectivity.data = distances
    if n_clusters is None:
        n_nodes = 2 * n_samples - 1
    else:
        assert n_clusters <= n_samples
        n_nodes = 2 * n_samples - n_clusters
    if linkage == 'single':
        return _single_linkage_tree(connectivity, n_samples, n_nodes, n_clusters, n_connected_components, return_distance)
    if return_distance:
        distances = np.empty(n_nodes - n_samples)
    A = np.empty(n_nodes, dtype=object)
    inertia = list()
    connectivity = connectivity.tolil()
    for ind, (data, row) in enumerate(zip(connectivity.data, connectivity.rows)):
        A[ind] = IntFloatDict(np.asarray(row, dtype=np.intp), np.asarray(data, dtype=np.float64))
        inertia.extend((_hierarchical.WeightedEdge(d, ind, r) for r, d in zip(row, data) if r < ind))
    del connectivity
    heapify(inertia)
    parent = np.arange(n_nodes, dtype=np.intp)
    used_node = np.ones(n_nodes, dtype=np.intp)
    children = []
    for k in range(n_samples, n_nodes):
        while True:
            edge = heappop(inertia)
            if used_node[edge.a] and used_node[edge.b]:
                break
        i = edge.a
        j = edge.b
        if return_distance:
            distances[k - n_samples] = edge.weight
        parent[i] = parent[j] = k
        children.append((i, j))
        n_i = used_node[i]
        n_j = used_node[j]
        used_node[k] = n_i + n_j
        used_node[i] = used_node[j] = False
        coord_col = join_func(A[i], A[j], used_node, n_i, n_j)
        for col, d in coord_col:
            A[col].append(k, d)
            heappush(inertia, _hierarchical.WeightedEdge(d, k, col))
        A[k] = coord_col
        A[i] = A[j] = 0
    n_leaves = n_samples
    children = np.array(children)[:, ::-1]
    if return_distance:
        return (children, n_connected_components, n_leaves, parent, distances)
    return (children, n_connected_components, n_leaves, parent)

def _hc_cut(n_clusters, children, n_leaves):
    if n_clusters > n_leaves:
        raise ValueError(f'Cannot extract more clusters than samples: {n_clusters} clusters were given for a tree with {n_leaves} leaves.')
    nodes = [-(max(children[-1]) + 1)]
    for _ in range(n_clusters - 1):
        these_children = children[-nodes[0] - n_leaves]
        heappush(nodes, -these_children[0])
        heappushpop(nodes, -these_children[1])
    label = np.zeros(n_leaves, dtype=np.intp)
    for i, node in enumerate(nodes):
        label[_hierarchical._hc_get_descendent(-node, children, n_leaves)] = i
    return label

@_fit_context(prefer_skip_nested_validation=True)
def fit(self, X, y=None):
    X = validate_data(self, X, ensure_min_samples=2)
    return self._fit(X)

def _fit(self, X):
    memory = check_memory(self.memory)
    if not (self.n_clusters is None) ^ (self.distance_threshold is None):
        raise ValueError('Exactly one of n_clusters and distance_threshold has to be set, and the other needs to be None.')
    if self.distance_threshold is not None and (not self.compute_full_tree):
        raise ValueError('compute_full_tree must be True if distance_threshold is set.')
    if self.linkage == 'ward' and self.metric not in ('euclidean', 'l2'):
        raise ValueError(f"{self.metric} was provided as metric. Ward can only work with euclidean distances (i.e. 'euclidean' and 'l2').")
    tree_builder = _TREE_BUILDERS[self.linkage]
    connectivity = self.connectivity
    if self.connectivity is not None:
        if callable(self.connectivity):
            connectivity = self.connectivity(X)
        connectivity = check_array(connectivity, accept_sparse=['csr', 'coo', 'lil'])
    n_samples = len(X)
    compute_full_tree = self.compute_full_tree
    if self.connectivity is None:
        compute_full_tree = True
    if compute_full_tree == 'auto':
        if self.distance_threshold is not None:
            compute_full_tree = True
        else:
            compute_full_tree = self.n_clusters < max(100, 0.02 * n_samples)
    n_clusters = self.n_clusters
    if compute_full_tree:
        n_clusters = None
    kwargs = {}
    if self.linkage != 'ward':
        kwargs['linkage'] = self.linkage
        kwargs['affinity'] = self.metric
    distance_threshold = self.distance_threshold
    return_distance = distance_threshold is not None or self.compute_distances
    out = memory.cache(tree_builder)(X, connectivity=connectivity, n_clusters=n_clusters, return_distance=return_distance, **kwargs)
    self.children_, self.n_connected_components_, self.n_leaves_, parents = out[:4]
    if return_distance:
        self.distances_ = out[-1]
    if self.distance_threshold is not None:
        self.n_clusters_ = np.count_nonzero(self.distances_ >= distance_threshold) + 1
    else:
        self.n_clusters_ = self.n_clusters
    if compute_full_tree:
        self.labels_ = _hc_cut(self.n_clusters_, self.children_, self.n_leaves_)
    else:
        labels = _hierarchical.hc_get_heads(parents, copy=False)
        labels = np.copy(labels[:n_samples])
        self.labels_ = np.searchsorted(np.unique(labels), labels)
    return self

@_fit_context(prefer_skip_nested_validation=True)
def fit(self, X, y=None):
    X = validate_data(self, X, ensure_min_features=2)
    super()._fit(X.T)
    self._n_features_out = self.n_clusters_
    return self

@property
def fit_predict(self):
    raise AttributeError

def _bistochastic_normalize(X, max_iter=1000, tol=1e-05):
    X = make_nonnegative(X)
    X_scaled = X
    for _ in range(max_iter):
        X_new, _, _ = _scale_normalize(X_scaled)
        if issparse(X):
            dist = norm(X_scaled.data - X.data)
        else:
            dist = norm(X_scaled - X_new)
        X_scaled = X_new
        if dist is not None and dist < tol:
            break
    return X_scaled

@abstractmethod
def _check_parameters(self, n_samples):
    pass

@_fit_context(prefer_skip_nested_validation=True)
def fit(self, X, y=None):
    X = validate_data(self, X, accept_sparse='csr', dtype=np.float64)
    self._check_parameters(X.shape[0])
    self._fit(X)
    return self

def _svd(self, array, n_components, n_discard):
    if self.svd_method == 'randomized':
        kwargs = {}
        if self.n_svd_vecs is not None:
            kwargs['n_oversamples'] = self.n_svd_vecs
        u, _, vt = _randomized_svd(array, n_components, random_state=self.random_state, **kwargs)
    elif self.svd_method == 'arpack':
        u, _, vt = svds(array, k=n_components, ncv=self.n_svd_vecs)
        if np.any(np.isnan(vt)):
            A = safe_sparse_dot(array.T, array)
            random_state = check_random_state(self.random_state)
            v0 = random_state.uniform(-1, 1, A.shape[0])
            _, v = eigsh(A, ncv=self.n_svd_vecs, v0=v0)
            vt = v.T
        if np.any(np.isnan(u)):
            A = safe_sparse_dot(array, array.T)
            random_state = check_random_state(self.random_state)
            v0 = random_state.uniform(-1, 1, A.shape[0])
            _, u = eigsh(A, ncv=self.n_svd_vecs, v0=v0)
    assert_all_finite(u)
    assert_all_finite(vt)
    u = u[:, n_discard:]
    vt = vt[n_discard:]
    return (u, vt.T)

def _fit_best_piecewise(self, vectors, n_best, n_clusters):

    def make_piecewise(v):
        centroid, labels = self._k_means(v.reshape(-1, 1), n_clusters)
        return centroid[labels].ravel()
    piecewise_vectors = np.apply_along_axis(make_piecewise, axis=1, arr=vectors)
    dists = np.apply_along_axis(norm, axis=1, arr=vectors - piecewise_vectors)
    result = vectors[np.argsort(dists)[:n_best]]
    return result

@property
def radius(self):
    sq_radius = self.squared_sum_ / self.n_samples_ - self.sq_norm_
    return sqrt(max(0, sq_radius))

@_fit_context(prefer_skip_nested_validation=True)
def fit(self, X, y=None):
    return self._fit(X, partial=False)

@_fit_context(prefer_skip_nested_validation=True)
def partial_fit(self, X=None, y=None):
    if X is None:
        self._global_clustering()
        return self
    else:
        return self._fit(X, partial=True)

def predict(self, X):
    check_is_fitted(self)
    X = validate_data(self, X, accept_sparse='csr', reset=False)
    return self._predict(X)

def _predict(self, X):
    kwargs = {'Y_norm_squared': self._subcluster_norms}
    with config_context(assume_finite=True):
        argmin = pairwise_distances_argmin(X, self.subcluster_centers_, metric_kwargs=kwargs)
    return self.subcluster_labels_[argmin]

def transform(self, X):
    check_is_fitted(self)
    X = validate_data(self, X, accept_sparse='csr', reset=False)
    with config_context(assume_finite=True):
        return euclidean_distances(X, self.subcluster_centers_)

def _global_clustering(self, X=None):
    clusterer = self.n_clusters
    centroids = self.subcluster_centers_
    compute_labels = X is not None and self.compute_labels
    not_enough_centroids = False
    if isinstance(clusterer, Integral):
        clusterer = AgglomerativeClustering(n_clusters=self.n_clusters)
        if len(centroids) < self.n_clusters:
            not_enough_centroids = True
    self._subcluster_norms = row_norms(self.subcluster_centers_, squared=True)
    if clusterer is None or not_enough_centroids:
        self.subcluster_labels_ = np.arange(len(centroids))
        if not_enough_centroids:
            warnings.warn('Number of subclusters found (%d) by BIRCH is less than (%d). Decrease the threshold.' % (len(centroids), self.n_clusters), ConvergenceWarning)
    else:
        self.subcluster_labels_ = clusterer.fit_predict(self.subcluster_centers_)
    if compute_labels:
        self.labels_ = self._predict(X)

def get_cluster_to_bisect(self):
    max_score = None
    for cluster_leaf in self.iter_leaves():
        if max_score is None or cluster_leaf.score > max_score:
            max_score = cluster_leaf.score
            best_cluster_leaf = cluster_leaf
    return best_cluster_leaf

def iter_leaves(self):
    if self.left is None:
        yield self
    else:
        yield from self.left.iter_leaves()
        yield from self.right.iter_leaves()

def _bisect(self, X, x_squared_norms, sample_weight, cluster_to_bisect):
    X = X[cluster_to_bisect.indices]
    x_squared_norms = x_squared_norms[cluster_to_bisect.indices]
    sample_weight = sample_weight[cluster_to_bisect.indices]
    best_inertia = None
    for _ in range(self.n_init):
        centers_init = self._init_centroids(X, x_squared_norms=x_squared_norms, init=self.init, random_state=self._random_state, n_centroids=2, sample_weight=sample_weight)
        labels, inertia, centers, _ = self._kmeans_single(X, sample_weight, centers_init, max_iter=self.max_iter, verbose=self.verbose, tol=self.tol, n_threads=self._n_threads)
        if best_inertia is None or inertia < best_inertia * (1 - 1e-06):
            best_labels = labels
            best_centers = centers
            best_inertia = inertia
    if self.verbose:
        print(f'New centroids from bisection: {best_centers}')
    if self.bisecting_strategy == 'biggest_inertia':
        scores = self._inertia_per_cluster(X, best_centers, best_labels, sample_weight)
    else:
        scores = np.bincount(best_labels, minlength=2)
    cluster_to_bisect.split(best_labels, best_centers, scores)

def _predict_recursive(self, X, sample_weight, cluster_node):
    if cluster_node.left is None:
        return np.full(X.shape[0], cluster_node.label, dtype=np.int32)
    centers = np.vstack((cluster_node.left.center, cluster_node.right.center))
    if hasattr(self, '_X_mean'):
        centers += self._X_mean
    cluster_labels = _labels_inertia_threadpool_limit(X, sample_weight, centers, self._n_threads, return_inertia=False)
    mask = cluster_labels == 0
    labels = np.full(X.shape[0], -1, dtype=np.int32)
    labels[mask] = self._predict_recursive(X[mask], sample_weight[mask], cluster_node.left)
    labels[~mask] = self._predict_recursive(X[~mask], sample_weight[~mask], cluster_node.right)
    return labels

@validate_params({'X': ['array-like', 'sparse matrix'], 'sample_weight': ['array-like', None]}, prefer_skip_nested_validation=False)
def dbscan(X, eps=0.5, *, min_samples=5, metric='minkowski', metric_params=None, algorithm='auto', leaf_size=30, p=2, sample_weight=None, n_jobs=None):
    est = DBSCAN(eps=eps, min_samples=min_samples, metric=metric, metric_params=metric_params, algorithm=algorithm, leaf_size=leaf_size, p=p, n_jobs=n_jobs)
    est.fit(X, sample_weight=sample_weight)
    return (est.core_sample_indices_, est.labels_)

def fit_predict(self, X, y=None, sample_weight=None):
    self.fit(X, sample_weight=sample_weight)
    return self.labels_

@validate_params({'X': ['array-like', 'sparse matrix'], 'n_clusters': [Interval(Integral, 1, None, closed='left')], 'sample_weight': ['array-like', None], 'x_squared_norms': ['array-like', None], 'random_state': ['random_state'], 'n_local_trials': [Interval(Integral, 1, None, closed='left'), None]}, prefer_skip_nested_validation=True)
def kmeans_plusplus(X, n_clusters, *, sample_weight=None, x_squared_norms=None, random_state=None, n_local_trials=None):
    check_array(X, accept_sparse='csr', dtype=[np.float64, np.float32])
    sample_weight = _check_sample_weight(sample_weight, X, dtype=X.dtype)
    if X.shape[0] < n_clusters:
        raise ValueError(f'n_samples={X.shape[0]} should be >= n_clusters={n_clusters}.')
    if x_squared_norms is None:
        x_squared_norms = row_norms(X, squared=True)
    else:
        x_squared_norms = check_array(x_squared_norms, dtype=X.dtype, ensure_2d=False)
    if x_squared_norms.shape[0] != X.shape[0]:
        raise ValueError(f'The length of x_squared_norms {x_squared_norms.shape[0]} should be equal to the length of n_samples {X.shape[0]}.')
    random_state = check_random_state(random_state)
    centers, indices = _kmeans_plusplus(X, n_clusters, x_squared_norms, sample_weight, random_state, n_local_trials)
    return (centers, indices)

def _tolerance(X, tol):
    if tol == 0:
        return 0
    if sp.issparse(X):
        variances = mean_variance_axis(X, axis=0)[1]
    else:
        variances = np.var(X, axis=0)
    return np.mean(variances) * tol

@validate_params({'X': ['array-like', 'sparse matrix'], 'sample_weight': ['array-like', None], 'return_n_iter': [bool]}, prefer_skip_nested_validation=False)
def k_means(X, n_clusters, *, sample_weight=None, init='k-means++', n_init='auto', max_iter=300, verbose=False, tol=0.0001, random_state=None, copy_x=True, algorithm='lloyd', return_n_iter=False):
    est = KMeans(n_clusters=n_clusters, init=init, n_init=n_init, max_iter=max_iter, verbose=verbose, tol=tol, random_state=random_state, copy_x=copy_x, algorithm=algorithm).fit(X, sample_weight=sample_weight)
    if return_n_iter:
        return (est.cluster_centers_, est.labels_, est.inertia_, est.n_iter_)
    else:
        return (est.cluster_centers_, est.labels_, est.inertia_)

@_threadpool_controller_decorator(limits=1, user_api='blas')
def _kmeans_single_lloyd(X, sample_weight, centers_init, max_iter=300, verbose=False, tol=0.0001, n_threads=1):
    n_clusters = centers_init.shape[0]
    centers = centers_init
    centers_new = np.zeros_like(centers)
    labels = np.full(X.shape[0], -1, dtype=np.int32)
    labels_old = labels.copy()
    weight_in_clusters = np.zeros(n_clusters, dtype=X.dtype)
    center_shift = np.zeros(n_clusters, dtype=X.dtype)
    if sp.issparse(X):
        lloyd_iter = lloyd_iter_chunked_sparse
        _inertia = _inertia_sparse
    else:
        lloyd_iter = lloyd_iter_chunked_dense
        _inertia = _inertia_dense
    strict_convergence = False
    for i in range(max_iter):
        lloyd_iter(X, sample_weight, centers, centers_new, weight_in_clusters, labels, center_shift, n_threads)
        if verbose:
            inertia = _inertia(X, sample_weight, centers, labels, n_threads)
            print(f'Iteration {i}, inertia {inertia}.')
        centers, centers_new = (centers_new, centers)
        if np.array_equal(labels, labels_old):
            if verbose:
                print(f'Converged at iteration {i}: strict convergence.')
            strict_convergence = True
            break
        else:
            center_shift_tot = (center_shift ** 2).sum()
            if center_shift_tot <= tol:
                if verbose:
                    print(f'Converged at iteration {i}: center shift {center_shift_tot} within tolerance {tol}.')
                break
        labels_old[:] = labels
    if not strict_convergence:
        lloyd_iter(X, sample_weight, centers, centers, weight_in_clusters, labels, center_shift, n_threads, update_centers=False)
    inertia = _inertia(X, sample_weight, centers, labels, n_threads)
    return (labels, inertia, centers, i + 1)

def _labels_inertia(X, sample_weight, centers, n_threads=1, return_inertia=True):
    n_samples = X.shape[0]
    n_clusters = centers.shape[0]
    labels = np.full(n_samples, -1, dtype=np.int32)
    center_shift = np.zeros(n_clusters, dtype=centers.dtype)
    if sp.issparse(X):
        _labels = lloyd_iter_chunked_sparse
        _inertia = _inertia_sparse
    else:
        _labels = lloyd_iter_chunked_dense
        _inertia = _inertia_dense
    _labels(X, sample_weight, centers, centers_new=None, weight_in_clusters=None, labels=labels, center_shift=center_shift, n_threads=n_threads, update_centers=False)
    if return_inertia:
        inertia = _inertia(X, sample_weight, centers, labels, n_threads)
        return (labels, inertia)
    return labels

def _mini_batch_step(X, sample_weight, centers, centers_new, weight_sums, random_state, random_reassign=False, reassignment_ratio=0.01, verbose=False, n_threads=1):
    labels, inertia = _labels_inertia(X, sample_weight, centers, n_threads=n_threads)
    if sp.issparse(X):
        _minibatch_update_sparse(X, sample_weight, centers, centers_new, weight_sums, labels, n_threads)
    else:
        _minibatch_update_dense(X, sample_weight, centers, centers_new, weight_sums, labels, n_threads)
    if random_reassign and reassignment_ratio > 0:
        to_reassign = weight_sums < reassignment_ratio * weight_sums.max()
        if to_reassign.sum() > 0.5 * X.shape[0]:
            indices_dont_reassign = np.argsort(weight_sums)[int(0.5 * X.shape[0]):]
            to_reassign[indices_dont_reassign] = False
        n_reassigns = to_reassign.sum()
        if n_reassigns:
            new_centers = random_state.choice(X.shape[0], replace=False, size=n_reassigns)
            if verbose:
                print(f'[MiniBatchKMeans] Reassigning {n_reassigns} cluster centers.')
            if sp.issparse(X):
                assign_rows_csr(X, new_centers.astype(np.intp, copy=False), np.where(to_reassign)[0].astype(np.intp, copy=False), centers_new)
            else:
                centers_new[to_reassign] = X[new_centers]
        weight_sums[to_reassign] = np.min(weight_sums[~to_reassign])
    return inertia

@abstractmethod
def _warn_mkl_vcomp(self, n_active_threads):
    pass

def _check_mkl_vcomp(self, X, n_samples):
    if sp.issparse(X):
        return
    n_active_threads = int(np.ceil(n_samples / CHUNK_SIZE))
    if n_active_threads < self._n_threads:
        modules = _get_threadpool_controller().info()
        has_vcomp = 'vcomp' in [module['prefix'] for module in modules]
        has_mkl = ('mkl', 'intel') in [(module['internal_api'], module.get('threading_layer', None)) for module in modules]
        if has_vcomp and has_mkl:
            self._warn_mkl_vcomp(n_active_threads)

def _validate_center_shape(self, X, centers, n_centroids=None):
    if n_centroids is None:
        n_centroids = self.n_clusters
    if centers.shape[0] != n_centroids:
        raise ValueError(f'The shape of the initial centers {centers.shape} does not match the number of clusters {n_centroids}.')
    if centers.shape[1] != X.shape[1]:
        raise ValueError(f'The shape of the initial centers {centers.shape} does not match the number of features of the data {X.shape[1]}.')

def _init_centroids(self, X, x_squared_norms, init, random_state, sample_weight, init_size=None, n_centroids=None):
    n_samples = X.shape[0]
    n_clusters = self.n_clusters if n_centroids is None else n_centroids
    if init_size is not None and init_size < n_samples:
        init_indices = random_state.randint(0, n_samples, init_size)
        X = X[init_indices]
        x_squared_norms = x_squared_norms[init_indices]
        n_samples = X.shape[0]
        sample_weight = sample_weight[init_indices]
    if isinstance(init, str) and init == 'k-means++':
        centers, _ = _kmeans_plusplus(X, n_clusters, random_state=random_state, x_squared_norms=x_squared_norms, sample_weight=sample_weight)
    elif isinstance(init, str) and init == 'random':
        seeds = random_state.choice(n_samples, size=n_clusters, replace=False, p=sample_weight / sample_weight.sum())
        centers = X[seeds]
    elif _is_arraylike_not_scalar(self.init):
        centers = init
    elif callable(init):
        centers = init(X, n_clusters, random_state=random_state)
        centers = check_array(centers, dtype=X.dtype, copy=False, order='C')
        self._validate_center_shape(X, centers, n_centroids=n_clusters)
    if sp.issparse(centers):
        centers = centers.toarray()
    return centers

def transform(self, X):
    check_is_fitted(self)
    X = self._check_test_data(X)
    return self._transform(X)

def _mini_batch_convergence(self, step, n_steps, n_samples, centers_squared_diff, batch_inertia):
    batch_inertia /= self._batch_size
    step = step + 1
    if step == 1:
        if self.verbose:
            print(f'Minibatch step {step}/{n_steps}: mean batch inertia: {batch_inertia}')
        return False
    if self._ewa_inertia is None:
        self._ewa_inertia = batch_inertia
    else:
        alpha = self._batch_size * 2.0 / (n_samples + 1)
        alpha = min(alpha, 1)
        self._ewa_inertia = self._ewa_inertia * (1 - alpha) + batch_inertia * alpha
    if self.verbose:
        print(f'Minibatch step {step}/{n_steps}: mean batch inertia: {batch_inertia}, ewa inertia: {self._ewa_inertia}')
    if self._tol > 0.0 and centers_squared_diff <= self._tol:
        if self.verbose:
            print(f'Converged (small centers change) at step {step}/{n_steps}')
        return True
    if self._ewa_inertia_min is None or self._ewa_inertia < self._ewa_inertia_min:
        self._no_improvement = 0
        self._ewa_inertia_min = self._ewa_inertia
    else:
        self._no_improvement += 1
    if self.max_no_improvement is not None and self._no_improvement >= self.max_no_improvement:
        if self.verbose:
            print(f'Converged (lack of improvement in inertia) at step {step}/{n_steps}')
        return True
    return False

def _random_reassign(self):
    self._n_since_last_reassign += self._batch_size
    if (self._counts == 0).any() or self._n_since_last_reassign >= 10 * self.n_clusters:
        self._n_since_last_reassign = 0
        return True
    return False

@validate_params({'X': ['array-like']}, prefer_skip_nested_validation=False)
def mean_shift(X, *, bandwidth=None, seeds=None, bin_seeding=False, min_bin_freq=1, cluster_all=True, max_iter=300, n_jobs=None):
    model = MeanShift(bandwidth=bandwidth, seeds=seeds, min_bin_freq=min_bin_freq, bin_seeding=bin_seeding, cluster_all=cluster_all, n_jobs=n_jobs, max_iter=max_iter).fit(X)
    return (model.cluster_centers_, model.labels_)

def get_bin_seeds(X, bin_size, min_bin_freq=1):
    if bin_size == 0:
        return X
    bin_sizes = defaultdict(int)
    for point in X:
        binned_point = np.round(point / bin_size)
        bin_sizes[tuple(binned_point)] += 1
    bin_seeds = np.array([point for point, freq in bin_sizes.items() if freq >= min_bin_freq], dtype=np.float32)
    if len(bin_seeds) == len(X):
        warnings.warn('Binning data failed with provided bin_size=%f, using data points as seeds.' % bin_size)
        return X
    bin_seeds = bin_seeds * bin_size
    return bin_seeds

@_fit_context(prefer_skip_nested_validation=True)
def fit(self, X, y=None):
    X = validate_data(self, X)
    bandwidth = self.bandwidth
    if bandwidth is None:
        bandwidth = estimate_bandwidth(X, n_jobs=self.n_jobs)
    seeds = self.seeds
    if seeds is None:
        if self.bin_seeding:
            seeds = get_bin_seeds(X, bandwidth, self.min_bin_freq)
        else:
            seeds = X
    n_samples, n_features = X.shape
    center_intensity_dict = {}
    nbrs = NearestNeighbors(radius=bandwidth, n_jobs=1).fit(X)
    all_res = Parallel(n_jobs=self.n_jobs)((delayed(_mean_shift_single_seed)(seed, X, nbrs, self.max_iter) for seed in seeds))
    for i in range(len(seeds)):
        if all_res[i][1]:
            center_intensity_dict[all_res[i][0]] = all_res[i][1]
    self.n_iter_ = max([x[2] for x in all_res])
    if not center_intensity_dict:
        raise ValueError('No point was within bandwidth=%f of any seed. Try a different seeding strategy                              or increase the bandwidth.' % bandwidth)
    sorted_by_intensity = sorted(center_intensity_dict.items(), key=lambda tup: (tup[1], tup[0]), reverse=True)
    sorted_centers = np.array([tup[0] for tup in sorted_by_intensity])
    unique = np.ones(len(sorted_centers), dtype=bool)
    nbrs = NearestNeighbors(radius=bandwidth, n_jobs=self.n_jobs).fit(sorted_centers)
    for i, center in enumerate(sorted_centers):
        if unique[i]:
            neighbor_idxs = nbrs.radius_neighbors([center], return_distance=False)[0]
            unique[neighbor_idxs] = 0
            unique[i] = 1
    cluster_centers = sorted_centers[unique]
    nbrs = NearestNeighbors(n_neighbors=1, n_jobs=self.n_jobs).fit(cluster_centers)
    labels = np.zeros(n_samples, dtype=int)
    distances, idxs = nbrs.kneighbors(X)
    if self.cluster_all:
        labels = idxs.flatten()
    else:
        labels.fill(-1)
        bool_selector = distances.flatten() <= bandwidth
        labels[bool_selector] = idxs.flatten()[bool_selector]
    self.cluster_centers_, self.labels_ = (cluster_centers, labels)
    return self

def predict(self, X):
    check_is_fitted(self)
    X = validate_data(self, X, reset=False)
    with config_context(assume_finite=True):
        return pairwise_distances_argmin(X, self.cluster_centers_)

@validate_params({'reachability': [np.ndarray], 'predecessor': [np.ndarray], 'ordering': [np.ndarray], 'min_samples': [Interval(Integral, 2, None, closed='left'), Interval(RealNotInt, 0, 1, closed='both')], 'min_cluster_size': [Interval(Integral, 2, None, closed='left'), Interval(RealNotInt, 0, 1, closed='both'), None], 'xi': [Interval(Real, 0, 1, closed='both')], 'predecessor_correction': ['boolean']}, prefer_skip_nested_validation=True)
def cluster_optics_xi(*, reachability, predecessor, ordering, min_samples, min_cluster_size=None, xi=0.05, predecessor_correction=True):
    n_samples = len(reachability)
    _validate_size(min_samples, n_samples, 'min_samples')
    if min_samples <= 1:
        min_samples = max(2, int(min_samples * n_samples))
    if min_cluster_size is None:
        min_cluster_size = min_samples
    _validate_size(min_cluster_size, n_samples, 'min_cluster_size')
    if min_cluster_size <= 1:
        min_cluster_size = max(2, int(min_cluster_size * n_samples))
    clusters = _xi_cluster(reachability[ordering], predecessor[ordering], ordering, xi, min_samples, min_cluster_size, predecessor_correction)
    labels = _extract_xi_labels(ordering, clusters)
    return (labels, clusters)

def _extend_region(steep_point, xward_point, start, min_samples):
    n_samples = len(steep_point)
    non_xward_points = 0
    index = start
    end = start
    while index < n_samples:
        if steep_point[index]:
            non_xward_points = 0
            end = index
        elif not xward_point[index]:
            non_xward_points += 1
            if non_xward_points > min_samples:
                break
        else:
            return end
        index += 1
    return end

def _update_filter_sdas(sdas, mib, xi_complement, reachability_plot):
    if np.isinf(mib):
        return []
    res = [sda for sda in sdas if mib <= reachability_plot[sda['start']] * xi_complement]
    for sda in res:
        sda['mib'] = max(sda['mib'], mib)
    return res

def _correct_predecessor(reachability_plot, predecessor_plot, ordering, s, e):
    while s < e:
        if reachability_plot[s] > reachability_plot[e]:
            return (s, e)
        p_e = predecessor_plot[e]
        for i in range(s, e):
            if p_e == ordering[i]:
                return (s, e)
        e -= 1
    return (None, None)

def _xi_cluster(reachability_plot, predecessor_plot, ordering, xi, min_samples, min_cluster_size, predecessor_correction):
    reachability_plot = np.hstack((reachability_plot, np.inf))
    xi_complement = 1 - xi
    sdas = []
    clusters = []
    index = 0
    mib = 0.0
    with np.errstate(invalid='ignore'):
        ratio = reachability_plot[:-1] / reachability_plot[1:]
        steep_upward = ratio <= xi_complement
        steep_downward = ratio >= 1 / xi_complement
        downward = ratio > 1
        upward = ratio < 1
    for steep_index in iter(np.flatnonzero(steep_upward | steep_downward)):
        if steep_index < index:
            continue
        mib = max(mib, np.max(reachability_plot[index:steep_index + 1]))
        if steep_downward[steep_index]:
            sdas = _update_filter_sdas(sdas, mib, xi_complement, reachability_plot)
            D_start = steep_index
            D_end = _extend_region(steep_downward, upward, D_start, min_samples)
            D = {'start': D_start, 'end': D_end, 'mib': 0.0}
            sdas.append(D)
            index = D_end + 1
            mib = reachability_plot[index]
        else:
            sdas = _update_filter_sdas(sdas, mib, xi_complement, reachability_plot)
            U_start = steep_index
            U_end = _extend_region(steep_upward, downward, U_start, min_samples)
            index = U_end + 1
            mib = reachability_plot[index]
            U_clusters = []
            for D in sdas:
                c_start = D['start']
                c_end = U_end
                if reachability_plot[c_end + 1] * xi_complement < D['mib']:
                    continue
                D_max = reachability_plot[D['start']]
                if D_max * xi_complement >= reachability_plot[c_end + 1]:
                    while reachability_plot[c_start + 1] > reachability_plot[c_end + 1] and c_start < D['end']:
                        c_start += 1
                elif reachability_plot[c_end + 1] * xi_complement >= D_max:
                    while reachability_plot[c_end - 1] > D_max and c_end > U_start:
                        c_end -= 1
                if predecessor_correction:
                    c_start, c_end = _correct_predecessor(reachability_plot, predecessor_plot, ordering, c_start, c_end)
                if c_start is None:
                    continue
                if c_end - c_start + 1 < min_cluster_size:
                    continue
                if c_start > D['end']:
                    continue
                if c_end < U_start:
                    continue
                U_clusters.append((c_start, c_end))
            U_clusters.reverse()
            clusters.extend(U_clusters)
    return np.array(clusters)

def _extract_xi_labels(ordering, clusters):
    labels = np.full(len(ordering), -1, dtype=int)
    label = 0
    for c in clusters:
        if not np.any(labels[c[0]:c[1] + 1] != -1):
            labels[c[0]:c[1] + 1] = label
            label += 1
    labels[ordering] = labels.copy()
    return labels

@_fit_context(prefer_skip_nested_validation=False)
def fit(self, X, y=None):
    dtype = bool if self.metric in PAIRWISE_BOOLEAN_FUNCTIONS else float
    if dtype is bool and X.dtype != bool:
        msg = f'Data will be converted to boolean for metric {self.metric}, to avoid this warning, you may convert the data prior to calling fit.'
        warnings.warn(msg, DataConversionWarning)
    X = validate_data(self, X, dtype=dtype, accept_sparse='csr')
    if self.metric == 'precomputed' and issparse(X):
        X = X.copy()
        with warnings.catch_warnings():
            warnings.simplefilter('ignore', SparseEfficiencyWarning)
            X.setdiag(X.diagonal())
    memory = check_memory(self.memory)
    self.ordering_, self.core_distances_, self.reachability_, self.predecessor_ = memory.cache(compute_optics_graph)(X=X, min_samples=self.min_samples, algorithm=self.algorithm, leaf_size=self.leaf_size, metric=self.metric, metric_params=self.metric_params, p=self.p, n_jobs=self.n_jobs, max_eps=self.max_eps)
    if self.cluster_method == 'xi':
        labels_, clusters_ = cluster_optics_xi(reachability=self.reachability_, predecessor=self.predecessor_, ordering=self.ordering_, min_samples=self.min_samples, min_cluster_size=self.min_cluster_size, xi=self.xi, predecessor_correction=self.predecessor_correction)
        self.cluster_hierarchy_ = clusters_
    elif self.cluster_method == 'dbscan':
        if self.eps is None:
            eps = self.max_eps
        else:
            eps = self.eps
        if eps > self.max_eps:
            raise ValueError('Specify an epsilon smaller than %s. Got %s.' % (self.max_eps, eps))
        labels_ = cluster_optics_dbscan(reachability=self.reachability_, core_distances=self.core_distances_, ordering=self.ordering_, eps=eps)
    self.labels_ = labels_
    return self

def cluster_qr(vectors):
    k = vectors.shape[1]
    _, _, piv = qr(vectors.T, pivoting=True)
    ut, _, v = svd(vectors[piv[:k], :].T)
    vectors = abs(np.dot(vectors, np.dot(ut, v.conj())))
    return vectors.argmax(axis=1)

@validate_params({'affinity': ['array-like', 'sparse matrix']}, prefer_skip_nested_validation=False)
def spectral_clustering(affinity, *, n_clusters=8, n_components=None, eigen_solver=None, random_state=None, n_init=10, eigen_tol='auto', assign_labels='kmeans', verbose=False):
    clusterer = SpectralClustering(n_clusters=n_clusters, n_components=n_components, eigen_solver=eigen_solver, random_state=random_state, n_init=n_init, affinity='precomputed', eigen_tol=eigen_tol, assign_labels=assign_labels, verbose=verbose).fit(affinity)
    return clusterer.labels_

@_fit_context(prefer_skip_nested_validation=True)
def fit(self, X, y=None):
    X = validate_data(self, X, accept_sparse=['csr', 'csc', 'coo'], dtype=np.float64, ensure_min_samples=2)
    allow_squared = self.affinity in ['precomputed', 'precomputed_nearest_neighbors']
    if X.shape[0] == X.shape[1] and (not allow_squared):
        warnings.warn('The spectral clustering API has changed. ``fit``now constructs an affinity matrix from data. To use a custom affinity matrix, set ``affinity=precomputed``.')
    if self.affinity == 'nearest_neighbors':
        connectivity = kneighbors_graph(X, n_neighbors=self.n_neighbors, include_self=True, n_jobs=self.n_jobs)
        self.affinity_matrix_ = 0.5 * (connectivity + connectivity.T)
    elif self.affinity == 'precomputed_nearest_neighbors':
        estimator = NearestNeighbors(n_neighbors=self.n_neighbors, n_jobs=self.n_jobs, metric='precomputed').fit(X)
        connectivity = estimator.kneighbors_graph(X=X, mode='connectivity')
        self.affinity_matrix_ = 0.5 * (connectivity + connectivity.T)
    elif self.affinity == 'precomputed':
        self.affinity_matrix_ = X
    else:
        params = self.kernel_params
        if params is None:
            params = {}
        if not callable(self.affinity):
            params['gamma'] = self.gamma
            params['degree'] = self.degree
            params['coef0'] = self.coef0
        self.affinity_matrix_ = pairwise_kernels(X, metric=self.affinity, filter_params=True, **params)
    random_state = check_random_state(self.random_state)
    n_components = self.n_clusters if self.n_components is None else self.n_components
    maps = _spectral_embedding(self.affinity_matrix_, n_components=n_components, eigen_solver=self.eigen_solver, random_state=random_state, eigen_tol=self.eigen_tol, drop_first=False)
    if self.verbose:
        print(f'Computing label assignment using {self.assign_labels}')
    if self.assign_labels == 'kmeans':
        _, self.labels_, _ = k_means(maps, self.n_clusters, random_state=random_state, n_init=self.n_init, verbose=self.verbose)
    elif self.assign_labels == 'cluster_qr':
        self.labels_ = cluster_qr(maps)
    else:
        self.labels_ = discretize(maps, random_state=random_state)
    return self

def _brute_mst(mutual_reachability, min_samples):
    if not issparse(mutual_reachability):
        return mst_from_mutual_reachability(mutual_reachability)
    indptr = mutual_reachability.indptr
    num_points = mutual_reachability.shape[0]
    if any((indptr[i + 1] - indptr[i] < min_samples for i in range(num_points))):
        raise ValueError(f'There exists points with fewer than {min_samples} neighbors. Ensure your distance matrix has non-zero values for at least `min_sample`={min_samples} neighbors for each points (i.e. K-nn graph), or specify a `max_distance` in `metric_params` to use when distances are missing.')
    n_components = csgraph.connected_components(mutual_reachability, directed=False, return_labels=False)
    if n_components > 1:
        raise ValueError(f'Sparse mutual reachability matrix has {n_components} connected components. HDBSCAN cannot be performed on a disconnected graph. Ensure that the sparse distance matrix has only one connected component.')
    sparse_min_spanning_tree = csgraph.minimum_spanning_tree(mutual_reachability)
    rows, cols = sparse_min_spanning_tree.nonzero()
    mst = np.rec.fromarrays([rows, cols, sparse_min_spanning_tree.data], dtype=MST_edge_dtype)
    return mst

def _process_mst(min_spanning_tree):
    row_order = np.argsort(min_spanning_tree['distance'])
    min_spanning_tree = min_spanning_tree[row_order]
    return make_single_linkage(min_spanning_tree)

def _hdbscan_brute(X, min_samples=5, alpha=None, metric='euclidean', n_jobs=None, copy=False, **metric_params):
    if metric == 'precomputed':
        if X.shape[0] != X.shape[1]:
            raise ValueError(f'The precomputed distance matrix is expected to be symmetric, however it has shape {X.shape}. Please verify that the distance matrix was constructed correctly.')
        if not _allclose_dense_sparse(X, X.T):
            raise ValueError('The precomputed distance matrix is expected to be symmetric, however its values appear to be asymmetric. Please verify that the distance matrix was constructed correctly.')
        distance_matrix = X.copy() if copy else X
    else:
        distance_matrix = pairwise_distances(X, metric=metric, n_jobs=n_jobs, **metric_params)
    distance_matrix /= alpha
    max_distance = metric_params.get('max_distance', 0.0)
    if issparse(distance_matrix) and distance_matrix.format != 'csr':
        distance_matrix = distance_matrix.tocsr()
    mutual_reachability_ = mutual_reachability_graph(distance_matrix, min_samples=min_samples, max_distance=max_distance)
    min_spanning_tree = _brute_mst(mutual_reachability_, min_samples=min_samples)
    if np.isinf(min_spanning_tree['distance']).any():
        warn('The minimum spanning tree contains edge weights with value infinity. Potentially, you are missing too many distances in the initial distance matrix for the given neighborhood size.', UserWarning)
    return _process_mst(min_spanning_tree)

def remap_single_linkage_tree(tree, internal_to_raw, non_finite):
    finite_count = len(internal_to_raw)
    outlier_count = len(non_finite)
    for i, _ in enumerate(tree):
        left = tree[i]['left_node']
        right = tree[i]['right_node']
        if left < finite_count:
            tree[i]['left_node'] = internal_to_raw[left]
        else:
            tree[i]['left_node'] = left + outlier_count
        if right < finite_count:
            tree[i]['right_node'] = internal_to_raw[right]
        else:
            tree[i]['right_node'] = right + outlier_count
    outlier_tree = np.zeros(len(non_finite), dtype=HIERARCHY_dtype)
    last_cluster_id = max(tree[tree.shape[0] - 1]['left_node'], tree[tree.shape[0] - 1]['right_node'])
    last_cluster_size = tree[tree.shape[0] - 1]['cluster_size']
    for i, outlier in enumerate(non_finite):
        outlier_tree[i] = (outlier, last_cluster_id + 1, np.inf, last_cluster_size + 1)
        last_cluster_id += 1
        last_cluster_size += 1
    tree = np.concatenate([tree, outlier_tree])
    return tree

def _get_finite_row_indices(matrix):
    if issparse(matrix):
        row_indices = np.array([i for i, row in enumerate(matrix.tolil().data) if np.all(np.isfinite(row))])
    else:
        row_indices, = np.isfinite(matrix.sum(axis=1)).nonzero()
    return row_indices

@_fit_context(prefer_skip_nested_validation=False)
def fit(self, X, y=None):
    if self.copy == 'warn':
        warn('The default value of `copy` will change from False to True in 1.10. Explicitly set a value for `copy` to silence this warning.', FutureWarning)
        _copy = False
    else:
        _copy = self.copy
    if self.metric == 'precomputed' and self.store_centers is not None:
        raise ValueError('Cannot store centers when using a precomputed distance matrix.')
    self._metric_params = self.metric_params or {}
    if self.metric != 'precomputed':
        X = validate_data(self, X, accept_sparse=['csr', 'lil'], ensure_all_finite=False, dtype=np.float64)
        self._raw_data = X
        all_finite = True
        try:
            _assert_all_finite(X.data if issparse(X) else X)
        except ValueError:
            all_finite = False
        if not all_finite:
            reduced_X = X.sum(axis=1)
            missing_index = np.isnan(reduced_X).nonzero()[0]
            infinite_index = np.isinf(reduced_X).nonzero()[0]
            finite_index = _get_finite_row_indices(X)
            internal_to_raw = {x: y for x, y in enumerate(finite_index)}
            X = X[finite_index]
    elif issparse(X):
        X = validate_data(self, X, accept_sparse=['csr', 'lil'], dtype=np.float64, force_writeable=True)
    else:
        X = validate_data(self, X, ensure_all_finite=False, dtype=np.float64, force_writeable=True)
        if np.isnan(X).any():
            raise ValueError('np.nan values found in precomputed-dense')
    if X.shape[0] == 1:
        raise ValueError('n_samples=1 while HDBSCAN requires more than one sample')
    self._min_samples = self.min_cluster_size if self.min_samples is None else self.min_samples
    if self._min_samples > X.shape[0]:
        raise ValueError(f'min_samples ({self._min_samples}) must be at most the number of samples in X ({X.shape[0]})')
    mst_func = None
    kwargs = dict(X=X, min_samples=self._min_samples, alpha=self.alpha, metric=self.metric, n_jobs=self.n_jobs, **self._metric_params)
    if self.algorithm == 'kd_tree' and self.metric not in KDTree.valid_metrics:
        raise ValueError(f'{self.metric} is not a valid metric for a KDTree-based algorithm. Please select a different metric.')
    elif self.algorithm == 'ball_tree' and self.metric not in BallTree.valid_metrics:
        raise ValueError(f'{self.metric} is not a valid metric for a BallTree-based algorithm. Please select a different metric.')
    if self.algorithm != 'auto':
        if self.metric != 'precomputed' and issparse(X) and (self.algorithm != 'brute'):
            raise ValueError('Sparse data matrices only support algorithm `brute`.')
        if self.algorithm == 'brute':
            mst_func = _hdbscan_brute
            kwargs['copy'] = _copy
        elif self.algorithm == 'kd_tree':
            mst_func = _hdbscan_prims
            kwargs['algo'] = 'kd_tree'
            kwargs['leaf_size'] = self.leaf_size
        else:
            mst_func = _hdbscan_prims
            kwargs['algo'] = 'ball_tree'
            kwargs['leaf_size'] = self.leaf_size
    elif issparse(X) or self.metric not in FAST_METRICS:
        mst_func = _hdbscan_brute
        kwargs['copy'] = _copy
    elif self.metric in KDTree.valid_metrics:
        mst_func = _hdbscan_prims
        kwargs['algo'] = 'kd_tree'
        kwargs['leaf_size'] = self.leaf_size
    else:
        mst_func = _hdbscan_prims
        kwargs['algo'] = 'ball_tree'
        kwargs['leaf_size'] = self.leaf_size
    self._single_linkage_tree_ = mst_func(**kwargs)
    self.labels_, self.probabilities_ = tree_to_labels(self._single_linkage_tree_, self.min_cluster_size, self.cluster_selection_method, self.allow_single_cluster, self.cluster_selection_epsilon, self.max_cluster_size)
    if self.metric != 'precomputed' and (not all_finite):
        self._single_linkage_tree_ = remap_single_linkage_tree(self._single_linkage_tree_, internal_to_raw, non_finite=set(np.hstack([infinite_index, missing_index])))
        new_labels = np.empty(self._raw_data.shape[0], dtype=np.int32)
        new_labels[finite_index] = self.labels_
        new_labels[infinite_index] = _OUTLIER_ENCODING['infinite']['label']
        new_labels[missing_index] = _OUTLIER_ENCODING['missing']['label']
        self.labels_ = new_labels
        new_probabilities = np.zeros(self._raw_data.shape[0], dtype=np.float64)
        new_probabilities[finite_index] = self.probabilities_
        new_probabilities[infinite_index] = _OUTLIER_ENCODING['infinite']['prob']
        new_probabilities[missing_index] = _OUTLIER_ENCODING['missing']['prob']
        self.probabilities_ = new_probabilities
    if self.store_centers:
        self._weighted_cluster_center(X)
    return self

def fit_predict(self, X, y=None):
    self.fit(X)
    return self.labels_

def _check_X(X):
    if hasattr(X, '__array__') and hasattr(X, 'shape') or nw.dependencies.is_into_dataframe(X) or sparse.issparse(X):
        return X
    return check_array(X, ensure_all_finite='allow-nan', dtype=object)

def _is_empty_column_selection(column):
    if hasattr(column, 'dtype') and isinstance(column.dtype, np.dtype) and np.issubdtype(column.dtype, np.bool_):
        return not column.any()
    elif hasattr(column, '__len__'):
        return len(column) == 0 or (all((isinstance(col, bool) for col in column)) and (not any(column)))
    else:
        return False

def make_column_transformer(*transformers, remainder='drop', sparse_threshold=0.3, n_jobs=None, verbose=False, verbose_feature_names_out=True):
    transformer_list = _get_transformer_list(transformers)
    return ColumnTransformer(transformer_list, n_jobs=n_jobs, remainder=remainder, sparse_threshold=sparse_threshold, verbose=verbose, verbose_feature_names_out=verbose_feature_names_out)

@property
def _transformers(self):
    try:
        return [(name, trans) for name, trans, _ in self.transformers]
    except (TypeError, ValueError):
        return self.transformers

@_transformers.setter
def _transformers(self, value):
    try:
        self.transformers = [(name, trans, col) for (name, trans), (_, _, col) in zip(value, self.transformers)]
    except (TypeError, ValueError):
        self.transformers = value

def set_output(self, *, transform=None):
    super().set_output(transform=transform)
    transformers = (trans for _, trans, _ in chain(self.transformers, getattr(self, 'transformers_', [])) if trans not in {'passthrough', 'drop'})
    for trans in transformers:
        _safe_set_output(trans, transform=transform)
    if self.remainder not in {'passthrough', 'drop'}:
        _safe_set_output(self.remainder, transform=transform)
    return self

def set_params(self, **kwargs):
    self._set_params('_transformers', **kwargs)
    return self

def _iter(self, fitted, column_as_labels, skip_drop, skip_empty_columns):
    if fitted:
        transformers = self.transformers_
    else:
        transformers = [(name, trans, column) for (name, trans, _), column in zip(self.transformers, self._columns)]
        if self._remainder[2]:
            transformers = chain(transformers, [self._remainder])
    get_weight = (self.transformer_weights or {}).get
    for name, trans, columns in transformers:
        if skip_drop and trans == 'drop':
            continue
        if skip_empty_columns and _is_empty_column_selection(columns):
            continue
        if column_as_labels:
            columns_is_scalar = np.isscalar(columns)
            indices = self._transformer_to_input_indices[name]
            columns = self.feature_names_in_[indices]
            if columns_is_scalar:
                columns = columns[0]
        yield (name, trans, columns, get_weight(name))

def _validate_transformers(self):
    if not self.transformers:
        return
    names, transformers, _ = zip(*self.transformers)
    self._validate_names(names)
    self._check_estimators_are_instances(transformers)
    for t in transformers:
        if t in ('drop', 'passthrough'):
            continue
        if not (hasattr(t, 'fit') or hasattr(t, 'fit_transform')) or not hasattr(t, 'transform'):
            raise TypeError("All estimators should implement fit and transform, or can be 'drop' or 'passthrough' specifiers. '%s' (type %s) doesn't." % (t, type(t)))

def _validate_column_callables(self, X):
    all_columns = []
    transformer_to_input_indices = {}
    for name, _, columns in self.transformers:
        if callable(columns):
            columns = columns(X)
        all_columns.append(columns)
        transformer_to_input_indices[name] = _get_column_indices(X, columns)
    self._columns = all_columns
    self._transformer_to_input_indices = transformer_to_input_indices

@property
def named_transformers_(self):
    return Bunch(**{name: trans for name, trans, _ in self.transformers_})

def _get_feature_name_out_for_transformer(self, name, trans, feature_names_in):
    column_indices = self._transformer_to_input_indices[name]
    names = feature_names_in[column_indices]
    if hasattr(trans, 'get_feature_names_out'):
        return trans.get_feature_names_out(names)
    elif hasattr(self, '_transformers_feature_names_out'):
        return self._transformers_feature_names_out[self.output_indices_[name]]
    else:
        raise AttributeError(f'Transformer {name} (type {type(trans).__name__}) does not provide get_feature_names_out.')

def get_feature_names_out(self, input_features=None):
    check_is_fitted(self)
    input_features = _check_feature_names_in(self, input_features)
    transformer_with_feature_names_out = []
    for name, trans, *_ in self._iter(fitted=True, column_as_labels=False, skip_empty_columns=True, skip_drop=True):
        feature_names_out = self._get_feature_name_out_for_transformer(name, trans, input_features)
        if feature_names_out is None:
            continue
        transformer_with_feature_names_out.append((name, feature_names_out))
    if not transformer_with_feature_names_out:
        return np.array([], dtype=object)
    return self._add_prefix_for_feature_names_out(transformer_with_feature_names_out)

def _add_prefix_for_feature_names_out(self, transformer_with_feature_names_out):
    feature_names_out_callable = None
    if callable(self.verbose_feature_names_out):
        feature_names_out_callable = self.verbose_feature_names_out
    elif isinstance(self.verbose_feature_names_out, str):
        feature_names_out_callable = partial(_feature_names_out_with_str_format, str_format=self.verbose_feature_names_out)
    elif self.verbose_feature_names_out is True:
        feature_names_out_callable = partial(_feature_names_out_with_str_format, str_format='{transformer_name}__{feature_name}')
    if feature_names_out_callable is not None:
        names = list(chain.from_iterable(((feature_names_out_callable(name, i) for i in feature_names_out) for name, feature_names_out in transformer_with_feature_names_out)))
        return np.asarray(names, dtype=object)
    feature_names_count = Counter(chain.from_iterable((s for _, s in transformer_with_feature_names_out)))
    top_6_overlap = [name for name, count in feature_names_count.most_common(6) if count > 1]
    top_6_overlap.sort()
    if top_6_overlap:
        if len(top_6_overlap) == 6:
            names_repr = str(top_6_overlap[:5])[:-1] + ', ...]'
        else:
            names_repr = str(top_6_overlap)
        raise ValueError(f'Output feature names: {names_repr} are not unique. Please set verbose_feature_names_out=True to add prefixes to feature names')
    return np.concatenate([name for _, name in transformer_with_feature_names_out])

def _update_fitted_transformers(self, transformers):
    fitted_transformers = iter(transformers)
    transformers_ = []
    for name, old, column, _ in self._iter(fitted=False, column_as_labels=False, skip_drop=False, skip_empty_columns=False):
        if old == 'drop':
            trans = 'drop'
        elif _is_empty_column_selection(column):
            trans = old
        else:
            trans = next(fitted_transformers)
        transformers_.append((name, trans, column))
    assert not list(fitted_transformers)
    self.transformers_ = transformers_

def _validate_output(self, result):
    names = [name for name, _, _, _ in self._iter(fitted=True, column_as_labels=False, skip_drop=True, skip_empty_columns=True)]
    for Xs, name in zip(result, names):
        if not (getattr(Xs, 'ndim', 0) == 2 or nw.dependencies.is_into_dataframe(Xs)):
            raise ValueError(f"The output of the '{name}' transformer should be 2D (numpy array, scipy sparse array, dataframe).")
    if _get_output_config('transform', self)['dense'] == 'pandas':
        return
    try:
        import pandas as pd
    except ImportError:
        return
    for Xs, name in zip(result, names):
        if not isinstance(Xs, pd.DataFrame):
            continue
        for col_name, dtype in Xs.dtypes.to_dict().items():
            if getattr(dtype, 'na_value', None) is not pd.NA:
                continue
            if pd.NA not in Xs[col_name].values:
                continue
            class_name = self.__class__.__name__
            raise ValueError(f"The output of the '{name}' transformer for column '{col_name}' has dtype {dtype} and uses pandas.NA to represent null values. Storing this output in a numpy array can cause errors in downstream scikit-learn estimators, and inefficiencies. To avoid this problem you can (i) store the output in a pandas DataFrame by using {class_name}.set_output(transform='pandas') or (ii) modify the input data or the '{name}' transformer to avoid the presence of pandas.NA (for example by using pandas.DataFrame.astype).")

def _record_output_indices(self, Xs):
    idx = 0
    self.output_indices_ = {}
    for transformer_idx, (name, _, _, _) in enumerate(self._iter(fitted=True, column_as_labels=False, skip_drop=True, skip_empty_columns=True)):
        n_columns = Xs[transformer_idx].shape[1]
        self.output_indices_[name] = slice(idx, idx + n_columns)
        idx += n_columns
    all_names = [t[0] for t in self.transformers] + ['remainder']
    for name in all_names:
        if name not in self.output_indices_:
            self.output_indices_[name] = slice(0, 0)

def _call_func_on_transformers(self, X, y, func, column_as_labels, routed_params):
    if func is _fit_transform_one:
        fitted = False
    else:
        fitted = True
    transformers = list(self._iter(fitted=fitted, column_as_labels=column_as_labels, skip_drop=True, skip_empty_columns=True))
    try:
        jobs = []
        for idx, (name, trans, columns, weight) in enumerate(transformers, start=1):
            if func is _fit_transform_one:
                if trans == 'passthrough':
                    output_config = _get_output_config('transform', self)
                    trans = FunctionTransformer(accept_sparse=True, check_inverse=False, feature_names_out='one-to-one').set_output(transform=output_config['dense'])
                extra_args = dict(message_clsname='ColumnTransformer', message=self._log_message(name, idx, len(transformers)))
            else:
                extra_args = {}
            jobs.append(delayed(func)(transformer=clone(trans) if not fitted else trans, X=_safe_indexing(X, columns, axis=1), y=y, weight=weight, **extra_args, params=routed_params[name]))
        return Parallel(n_jobs=self.n_jobs)(jobs)
    except ValueError as e:
        if 'Expected 2D array, got 1D array instead' in str(e):
            raise ValueError(_ERR_MSG_1DCOLUMN) from e
        else:
            raise

def transform(self, X, **params):
    _raise_for_params(params, self, 'transform')
    check_is_fitted(self)
    X = _check_X(X)
    fit_dataframe_and_transform_dataframe = hasattr(self, 'feature_names_in_') and nw.dependencies.is_into_dataframe(X)
    n_samples = _num_samples(X)
    column_names = _get_feature_names(X)
    if fit_dataframe_and_transform_dataframe:
        named_transformers = self.named_transformers_
        non_dropped_indices = [ind for name, ind in self._transformer_to_input_indices.items() if name in named_transformers and named_transformers[name] != 'drop']
        all_indices = set(chain(*non_dropped_indices))
        all_names = set((self.feature_names_in_[ind] for ind in all_indices))
        diff = all_names - set(column_names)
        if diff:
            raise ValueError(f'columns are missing: {diff}')
    else:
        _check_n_features(self, X, reset=False)
    routed_params = process_routing(self, 'transform', **params)
    Xs = self._call_func_on_transformers(X, None, _transform_one, column_as_labels=fit_dataframe_and_transform_dataframe, routed_params=routed_params)
    self._validate_output(Xs)
    if not Xs:
        return np.zeros((n_samples, 0))
    return self._hstack(list(Xs), n_samples=n_samples)

def _hstack(self, Xs, *, n_samples):
    if self.sparse_output_:
        try:
            converted_Xs = [check_array(X, accept_sparse=True, ensure_all_finite=False) for X in Xs]
        except ValueError as e:
            raise ValueError('For a sparse output, all columns should be a numeric or convertible to a numeric.') from e
        return sparse.hstack(converted_Xs).tocsr()
    else:
        Xs = [f.toarray() if sparse.issparse(f) else f for f in Xs]
        adapter = _get_container_adapter('transform', self)
        if adapter and all((adapter.is_supported_container(X) for X in Xs)):
            self._transformers_feature_names_out = np.hstack([_get_feature_names(X) for X in Xs])
            Xs = [adapter.rename_columns(X, [f'tmp_col_name_{i}_{j}' for j in range(X.shape[1])]) for i, X in enumerate(Xs)]
            output = adapter.hstack(Xs)
            output_samples = output.shape[0]
            if output_samples != n_samples:
                raise ValueError("Concatenating DataFrames from the transformer's output lead to an inconsistent number of samples. The output may have Pandas Indexes that do not match, or that transformers are returning number of samples which are not the same as the number input samples.")
            return output
        return np.hstack(Xs)

def get_metadata_routing(self):
    router = MetadataRouter(owner=self)
    transformers = self.transformers
    if self.remainder != 'drop':
        transformers = chain(transformers, [('remainder', self.remainder, None)])
    for name, step, _ in transformers:
        method_mapping = MethodMapping()
        if hasattr(step, 'fit_transform'):
            method_mapping.add(caller='fit', callee='fit_transform').add(caller='fit_transform', callee='fit_transform')
        else:
            method_mapping.add(caller='fit', callee='fit').add(caller='fit', callee='transform').add(caller='fit_transform', callee='fit').add(caller='fit_transform', callee='transform')
        method_mapping.add(caller='transform', callee='transform')
        router.add(method_mapping=method_mapping, **{name: step})
    return router

def __call__(self, df):
    if not hasattr(df, 'iloc'):
        raise ValueError('make_column_selector can only be applied to pandas dataframes')
    df_row = df.iloc[:1]
    if self.dtype_include is not None or self.dtype_exclude is not None:
        df_row = df_row.select_dtypes(include=self.dtype_include, exclude=self.dtype_exclude)
    cols = df_row.columns
    if self.pattern is not None:
        cols = cols[cols.str.contains(self.pattern, regex=True)]
    return cols.tolist()

def _fit_transformer(self, y):
    if self.transformer is not None and (self.func is not None or self.inverse_func is not None):
        raise ValueError("'transformer' and functions 'func'/'inverse_func' cannot both be set.")
    elif self.transformer is not None:
        self.transformer_ = clone(self.transformer)
    else:
        if self.func is not None and self.inverse_func is None or (self.func is None and self.inverse_func is not None):
            lacking_param, existing_param = ('func', 'inverse_func') if self.func is None else ('inverse_func', 'func')
            raise ValueError(f"When '{existing_param}' is provided, '{lacking_param}' must also be provided. If {lacking_param} is supposed to be the default, you need to explicitly pass it the identity function.")
        self.transformer_ = FunctionTransformer(func=self.func, inverse_func=self.inverse_func, validate=True, check_inverse=self.check_inverse)
        self.transformer_.set_output(transform='default')
    self.transformer_.fit(y)
    if self.check_inverse:
        idx_selected = slice(None, None, max(1, y.shape[0] // 10))
        y_sel = _safe_indexing(y, idx_selected)
        y_sel_t = self.transformer_.transform(y_sel)
        if not np.allclose(y_sel, self.transformer_.inverse_transform(y_sel_t)):
            warnings.warn("The provided functions or transformer are not strictly inverse of each other. If you are sure you want to proceed regardless, set 'check_inverse=False'", UserWarning)

@_fit_context(prefer_skip_nested_validation=False)
def fit(self, X, y, **fit_params):
    if y is None:
        raise ValueError(f'This {self.__class__.__name__} estimator requires y to be passed, but the target y is None.')
    y = check_array(y, input_name='y', accept_sparse=False, ensure_all_finite=True, ensure_2d=False, dtype='numeric', allow_nd=True)
    self._training_dim = y.ndim
    if y.ndim == 1:
        y_2d = y.reshape(-1, 1)
    else:
        y_2d = y
    self._fit_transformer(y_2d)
    y_trans = self.transformer_.transform(y_2d)
    if y_trans.ndim == 2 and y_trans.shape[1] == 1 and (self._training_dim == 1):
        y_trans = y_trans.squeeze(axis=1)
    self.regressor_ = self._get_regressor(get_clone=True)
    if _routing_enabled():
        routed_params = process_routing(self, 'fit', **fit_params)
    else:
        routed_params = _manual_routing({'regressor': {'fit': fit_params}})
    self.regressor_.fit(X, y_trans, **routed_params.regressor.fit)
    if hasattr(self.regressor_, 'feature_names_in_'):
        self.feature_names_in_ = self.regressor_.feature_names_in_
    return self

def predict(self, X, **predict_params):
    check_is_fitted(self)
    if _routing_enabled():
        routed_params = process_routing(self, 'predict', **predict_params)
    else:
        routed_params = _manual_routing({'regressor': {'predict': predict_params}})
    pred = self.regressor_.predict(X, **routed_params.regressor.predict)
    if pred.ndim == 1:
        pred_trans = self.transformer_.inverse_transform(pred.reshape(-1, 1))
    else:
        pred_trans = self.transformer_.inverse_transform(pred)
    if self._training_dim == 1 and pred_trans.ndim == 2 and (pred_trans.shape[1] == 1):
        pred_trans = pred_trans.squeeze(axis=1)
    return pred_trans

@property
def n_features_in_(self):
    try:
        check_is_fitted(self)
    except NotFittedError as nfe:
        raise AttributeError('{} object has no n_features_in_ attribute.'.format(self.__class__.__name__)) from nfe
    return self.regressor_.n_features_in_

def get_metadata_routing(self):
    router = MetadataRouter(owner=self).add(regressor=self._get_regressor(), method_mapping=MethodMapping().add(caller='fit', callee='fit').add(caller='predict', callee='predict'))
    return router

@_fit_context(prefer_skip_nested_validation=True)
def fit(self, X, y=None):
    super().fit(X)
    self.offset_ = np.percentile(-self.dist_, 100.0 * self.contamination)
    return self

def score_samples(self, X):
    check_is_fitted(self)
    return -self.mahalanobis(X)

@validate_params({'X': ['array-like'], 'assume_centered': ['boolean']}, prefer_skip_nested_validation=True)
def empirical_covariance(X, *, assume_centered=False):
    X = check_array(X, ensure_2d=False, ensure_all_finite=False)
    xp, _ = get_namespace(X)
    if X.ndim == 1:
        X = xp.reshape(X, (1, -1))
    if X.shape[0] == 1:
        warnings.warn('Only one sample available. You may want to reshape your data array')
    if assume_centered:
        covariance = X.T @ X / X.shape[0]
    elif _is_numpy_namespace(xp):
        covariance = np.cov(X.T, bias=1)
    else:
        covariance = _cov(X, xp=xp)
    if covariance.ndim == 0:
        covariance = xp.reshape(covariance, (1, 1))
    return covariance

def _set_covariance(self, covariance):
    xp, _ = get_namespace(covariance)
    covariance = check_array(covariance)
    self.covariance_ = covariance
    if self.store_precision:
        if _is_numpy_namespace(xp):
            self.precision_ = linalg.pinvh(covariance, check_finite=False)
        else:
            self.precision_ = xp.linalg.pinv(covariance)
    else:
        self.precision_ = None

def get_precision(self):
    if self.store_precision:
        precision = self.precision_
    else:
        xp, _ = get_namespace(self.covariance_)
        if _is_numpy_namespace(xp):
            precision = linalg.pinvh(self.covariance_, check_finite=False)
        else:
            precision = xp.linalg.pinv(self.covariance_)
    return precision

@_fit_context(prefer_skip_nested_validation=True)
def fit(self, X, y=None):
    xp, _, device_ = get_namespace_and_device(X)
    X = validate_data(self, X, dtype=supported_float_dtypes(xp, device_))
    if self.assume_centered:
        self.location_ = xp.zeros(X.shape[1], dtype=X.dtype, device=device_)
    else:
        self.location_ = xp.mean(X, axis=0)
    covariance = empirical_covariance(X, assume_centered=self.assume_centered)
    self._set_covariance(covariance)
    return self

def error_norm(self, comp_cov, norm='frobenius', scaling=True, squared=True):
    xp, _ = get_namespace(comp_cov, self.covariance_)
    error = comp_cov - self.covariance_
    if norm == 'frobenius':
        squared_norm = float(xp.sum(error ** 2))
    elif norm == 'spectral':
        if _is_numpy_namespace(xp):
            squared_norm = float(np.amax(linalg.svdvals(error.T @ error)))
        else:
            s = xp.linalg.svdvals(error.T @ error)
            squared_norm = float(xp.max(s))
    else:
        raise NotImplementedError('Only spectral and frobenius norms are implemented')
    if scaling:
        squared_norm = squared_norm / error.shape[0]
    if squared:
        result = squared_norm
    else:
        result = math.sqrt(squared_norm)
    return result

def mahalanobis(self, X):
    xp, _, device_ = get_namespace_and_device(X)
    X = validate_data(self, X, reset=False, dtype=supported_float_dtypes(xp, device_))
    precision = self.get_precision()
    if _is_numpy_namespace(xp):
        with config_context(assume_finite=True):
            dist = pairwise_distances(X, self.location_[np.newaxis, :], metric='mahalanobis', VI=precision)
        return np.reshape(dist, (len(X),)) ** 2
    else:
        X_centered = X - self.location_
        return xp.sum(X_centered @ precision * X_centered, axis=1)

def alpha_max(emp_cov):
    A = np.copy(emp_cov)
    A.flat[::A.shape[0] + 1] = 0
    return np.max(np.abs(A))

@validate_params({'emp_cov': ['array-like'], 'return_costs': ['boolean'], 'return_n_iter': ['boolean']}, prefer_skip_nested_validation=False)
def graphical_lasso(emp_cov, alpha, *, mode='cd', tol=0.0001, enet_tol=0.0001, max_iter=100, verbose=False, return_costs=False, eps=np.finfo(np.float64).eps, return_n_iter=False):
    model = GraphicalLasso(alpha=alpha, mode=mode, covariance='precomputed', tol=tol, enet_tol=enet_tol, max_iter=max_iter, verbose=verbose, eps=eps, assume_centered=True).fit(emp_cov)
    output = [model.covariance_, model.precision_]
    if return_costs:
        output.append(model.costs_)
    if return_n_iter:
        output.append(model.n_iter_)
    return tuple(output)

def graphical_lasso_path(X, alphas, cov_init=None, X_test=None, mode='cd', tol=0.0001, enet_tol=0.0001, max_iter=100, verbose=False, eps=np.finfo(np.float64).eps):
    inner_verbose = max(0, verbose - 1)
    emp_cov = empirical_covariance(X)
    if cov_init is None:
        covariance_ = emp_cov.copy()
    else:
        covariance_ = cov_init
    covariances_ = list()
    precisions_ = list()
    scores_ = list()
    if X_test is not None:
        test_emp_cov = empirical_covariance(X_test)
    for alpha in alphas:
        try:
            covariance_, precision_, _, _ = _graphical_lasso(emp_cov, alpha=alpha, cov_init=covariance_, mode=mode, tol=tol, enet_tol=enet_tol, max_iter=max_iter, verbose=inner_verbose, eps=eps)
            covariances_.append(covariance_)
            precisions_.append(precision_)
            if X_test is not None:
                this_score = log_likelihood(test_emp_cov, precision_)
        except FloatingPointError:
            this_score = -np.inf
            covariances_.append(np.nan)
            precisions_.append(np.nan)
        if X_test is not None:
            if not np.isfinite(this_score):
                this_score = -np.inf
            scores_.append(this_score)
        if verbose == 1:
            sys.stderr.write('.')
        elif verbose > 1:
            if X_test is not None:
                print('[graphical_lasso_path] alpha: %.2e, score: %.2e' % (alpha, this_score))
            else:
                print('[graphical_lasso_path] alpha: %.2e' % alpha)
    if X_test is not None:
        return (covariances_, precisions_, scores_)
    return (covariances_, precisions_)

@_fit_context(prefer_skip_nested_validation=True)
def fit(self, X, y=None):
    X = validate_data(self, X, ensure_min_features=2, ensure_min_samples=2)
    if self.covariance == 'precomputed':
        emp_cov = X.copy()
        self.location_ = np.zeros(X.shape[1])
    else:
        emp_cov = empirical_covariance(X, assume_centered=self.assume_centered)
        if self.assume_centered:
            self.location_ = np.zeros(X.shape[1])
        else:
            self.location_ = X.mean(0)
    self.covariance_, self.precision_, self.costs_, self.n_iter_ = _graphical_lasso(emp_cov, alpha=self.alpha, cov_init=None, mode=self.mode, tol=self.tol, enet_tol=self.enet_tol, max_iter=self.max_iter, verbose=self.verbose, eps=self.eps)
    return self

def get_metadata_routing(self):
    router = MetadataRouter(owner=self).add(splitter=check_cv(self.cv), method_mapping=MethodMapping().add(callee='split', caller='fit'))
    return router

def c_step(X, n_support, remaining_iterations=30, initial_estimates=None, verbose=False, cov_computation_method=empirical_covariance, random_state=None):
    X = np.asarray(X)
    random_state = check_random_state(random_state)
    return _c_step(X, n_support, remaining_iterations=remaining_iterations, initial_estimates=initial_estimates, verbose=verbose, cov_computation_method=cov_computation_method, random_state=random_state)

def select_candidates(X, n_support, n_trials, select=1, n_iter=30, verbose=False, cov_computation_method=empirical_covariance, random_state=None):
    random_state = check_random_state(random_state)
    if isinstance(n_trials, Integral):
        run_from_estimates = False
    elif isinstance(n_trials, tuple):
        run_from_estimates = True
        estimates_list = n_trials
        n_trials = estimates_list[0].shape[0]
    else:
        raise TypeError("Invalid 'n_trials' parameter, expected tuple or  integer, got %s (%s)" % (n_trials, type(n_trials)))
    all_estimates = []
    if not run_from_estimates:
        for j in range(n_trials):
            all_estimates.append(_c_step(X, n_support, remaining_iterations=n_iter, verbose=verbose, cov_computation_method=cov_computation_method, random_state=random_state))
    else:
        for j in range(n_trials):
            initial_estimates = (estimates_list[0][j], estimates_list[1][j])
            all_estimates.append(_c_step(X, n_support, remaining_iterations=n_iter, initial_estimates=initial_estimates, verbose=verbose, cov_computation_method=cov_computation_method, random_state=random_state))
    all_locs_sub, all_covs_sub, all_dets_sub, all_supports_sub, all_ds_sub = zip(*all_estimates)
    index_best = np.argsort(all_dets_sub)[:select]
    best_locations = np.asarray(all_locs_sub)[index_best]
    best_covariances = np.asarray(all_covs_sub)[index_best]
    best_supports = np.asarray(all_supports_sub)[index_best]
    best_ds = np.asarray(all_ds_sub)[index_best]
    return (best_locations, best_covariances, best_supports, best_ds)

def _ledoit_wolf(X, *, assume_centered, block_size):
    xp, _ = get_namespace(X)
    if len(X.shape) == 2 and X.shape[1] == 1:
        if not assume_centered:
            X = X - xp.mean(X)
        return (xp.reshape(xp.mean(X ** 2), (1, 1)), 0.0)
    n_features = X.shape[1]
    shrinkage = ledoit_wolf_shrinkage(X, assume_centered=assume_centered, block_size=block_size)
    emp_cov = empirical_covariance(X, assume_centered=assume_centered)
    mu = float(xp.linalg.trace(emp_cov)) / n_features
    shrunk_cov = (1.0 - shrinkage) * emp_cov
    _add_to_diagonal(shrunk_cov, shrinkage * mu, xp)
    return (shrunk_cov, shrinkage)

def _oas(X, *, assume_centered=False):
    if len(X.shape) == 2 and X.shape[1] == 1:
        if not assume_centered:
            X = X - X.mean()
        return (np.atleast_2d((X ** 2).mean()), 0.0)
    n_samples, n_features = X.shape
    emp_cov = empirical_covariance(X, assume_centered=assume_centered)
    alpha = np.mean(emp_cov ** 2)
    mu = np.trace(emp_cov) / n_features
    mu_squared = mu ** 2
    num = alpha + mu_squared
    den = (n_samples + 1) * (alpha - mu_squared / n_features)
    shrinkage = 1.0 if den == 0 else min(num / den, 1.0)
    shrunk_cov = (1.0 - shrinkage) * emp_cov
    shrunk_cov.flat[::n_features + 1] += shrinkage * mu
    return (shrunk_cov, shrinkage)

@validate_params({'X': ['array-like']}, prefer_skip_nested_validation=False)
def ledoit_wolf(X, *, assume_centered=False, block_size=1000):
    estimator = LedoitWolf(assume_centered=assume_centered, block_size=block_size, store_precision=False).fit(X)
    return (estimator.covariance_, estimator.shrinkage_)

@validate_params({'X': ['array-like']}, prefer_skip_nested_validation=False)
def oas(X, *, assume_centered=False):
    estimator = OAS(assume_centered=assume_centered).fit(X)
    return (estimator.covariance_, estimator.shrinkage_)

@_fit_context(prefer_skip_nested_validation=True)
