@validate_params({'container_path': [str, os.PathLike], 'description': [str, None], 'categories': [list, None], 'load_content': ['boolean'], 'shuffle': ['boolean'], 'encoding': [str, None], 'decode_error': [StrOptions({'strict', 'ignore', 'replace'})], 'random_state': ['random_state'], 'allowed_extensions': [list, None]}, prefer_skip_nested_validation=True)
def load_files(container_path, *, description=None, categories=None, load_content=True, shuffle=True, encoding=None, decode_error='strict', random_state=0, allowed_extensions=None):
    target = []
    target_names = []
    filenames = []
    folders = [f for f in sorted(listdir(container_path)) if isdir(join(container_path, f))]
    if categories is not None:
        folders = [f for f in folders if f in categories]
    if allowed_extensions is not None:
        allowed_extensions = frozenset(allowed_extensions)
    for label, folder in enumerate(folders):
        target_names.append(folder)
        folder_path = join(container_path, folder)
        files = sorted(listdir(folder_path))
        if allowed_extensions is not None:
            documents = [join(folder_path, file) for file in files if os.path.splitext(file)[1] in allowed_extensions]
        else:
            documents = [join(folder_path, file) for file in files]
        target.extend(len(documents) * [label])
        filenames.extend(documents)
    filenames = np.array(filenames)
    target = np.array(target)
    if shuffle:
        random_state = check_random_state(random_state)
        indices = np.arange(filenames.shape[0])
        random_state.shuffle(indices)
        filenames = filenames[indices]
        target = target[indices]
    if load_content:
        data = []
        for filename in filenames:
            data.append(Path(filename).read_bytes())
        if encoding is not None:
            data = [d.decode(encoding, decode_error) for d in data]
        return Bunch(data=data, filenames=filenames, target_names=target_names, target=target, DESCR=description)
    return Bunch(filenames=filenames, target_names=target_names, target=target, DESCR=description)

def load_csv_data(data_file_name, *, data_module=DATA_MODULE, descr_file_name=None, descr_module=DESCR_MODULE, encoding='utf-8'):
    data_path = resources.files(data_module) / data_file_name
    with data_path.open('r', encoding='utf-8') as csv_file:
        data_file = csv.reader(csv_file)
        temp = next(data_file)
        n_samples = int(temp[0])
        n_features = int(temp[1])
        target_names = np.array(temp[2:])
        data = np.empty((n_samples, n_features))
        target = np.empty((n_samples,), dtype=int)
        for i, ir in enumerate(data_file):
            data[i] = np.asarray(ir[:-1], dtype=np.float64)
            target[i] = np.asarray(ir[-1], dtype=int)
    if descr_file_name is None:
        return (data, target, target_names)
    else:
        assert descr_module is not None
        descr = load_descr(descr_module=descr_module, descr_file_name=descr_file_name)
        return (data, target, target_names, descr)

def load_gzip_compressed_csv_data(data_file_name, *, data_module=DATA_MODULE, descr_file_name=None, descr_module=DESCR_MODULE, encoding='utf-8', **kwargs):
    data_path = resources.files(data_module) / data_file_name
    with data_path.open('rb') as compressed_file:
        compressed_file = gzip.open(compressed_file, mode='rt', encoding=encoding)
        data = np.loadtxt(compressed_file, **kwargs)
    if descr_file_name is None:
        return data
    else:
        assert descr_module is not None
        descr = load_descr(descr_module=descr_module, descr_file_name=descr_file_name)
        return (data, descr)

def load_descr(descr_file_name, *, descr_module=DESCR_MODULE, encoding='utf-8'):
    path = resources.files(descr_module) / descr_file_name
    return path.read_text(encoding=encoding)

