def _pkl_filepath(*args, **kwargs):
    py3_suffix = kwargs.get('py3_suffix', '_py3')
    basename, ext = splitext(args[-1])
    basename += py3_suffix
    new_args = args[:-1] + (basename + ext,)
    return join(*new_args)

def _sha256(path):
    sha256hash = hashlib.sha256()
    chunk_size = 8192
    with open(path, 'rb') as f:
        while True:
            buffer = f.read(chunk_size)
            if not buffer:
                break
            sha256hash.update(buffer)
    return sha256hash.hexdigest()

def _fetch_remote(remote, dirname=None, n_retries=3, delay=1):
    if dirname is None:
        folder_path = Path('.')
    else:
        folder_path = Path(dirname)
    file_path = folder_path / remote.filename
    if file_path.exists():
        if remote.checksum is None:
            return file_path
        checksum = _sha256(file_path)
        if checksum == remote.checksum:
            return file_path
        else:
            warnings.warn(f'SHA256 checksum of existing local file {file_path.name} ({checksum}) differs from expected ({remote.checksum}): re-downloading from {remote.url} .')
    temp_file = NamedTemporaryFile(prefix=remote.filename + '.part_', dir=folder_path, delete=False)
    temp_file.close()
    try:
        temp_file_path = Path(temp_file.name)
        while True:
            try:
                urlretrieve(remote.url, temp_file_path)
                break
            except (URLError, TimeoutError):
                if n_retries == 0:
                    raise
                warnings.warn(f'Retry downloading from url: {remote.url}')
                n_retries -= 1
                time.sleep(delay)
        checksum = _sha256(temp_file_path)
        if remote.checksum is not None and remote.checksum != checksum:
            raise OSError(f'The SHA256 checksum of {remote.filename} ({checksum}) differs from expected ({remote.checksum}).')
    except (Exception, KeyboardInterrupt):
        os.unlink(temp_file.name)
        raise
    shutil.move(temp_file_path, file_path)
    return file_path

def _filter_filename(value, filter_dots=True):
    value = unicodedata.normalize('NFKD', value).lower()
    if filter_dots:
        value = re.sub('[^\\w\\s-]+', '_', value)
    else:
        value = re.sub('[^.\\w\\s-]+', '_', value)
    value = re.sub('[\\s-]+', '-', value)
    return value.strip('-_.')

def fetch_file(url, folder=None, local_filename=None, sha256=None, n_retries=3, delay=1):
    folder_from_url, filename_from_url = _derive_folder_and_filename_from_url(url)
    if local_filename is None:
        local_filename = filename_from_url
    if folder is None:
        folder = Path(get_data_home()) / folder_from_url
        makedirs(folder, exist_ok=True)
    remote_metadata = RemoteFileMetadata(filename=local_filename, url=url, checksum=sha256)
    return _fetch_remote(remote_metadata, dirname=folder, n_retries=n_retries, delay=delay)

def _mkdirp(d):
    try:
        os.makedirs(d)
    except OSError as e:
        if e.errno != errno.EEXIST:
            raise

def _check_fetch_lfw(data_home=None, funneled=True, download_if_missing=True, n_retries=3, delay=1.0):
    data_home = get_data_home(data_home=data_home)
    lfw_home = join(data_home, 'lfw_home')
    if not exists(lfw_home):
        makedirs(lfw_home)
    for target in TARGETS:
        target_filepath = join(lfw_home, target.filename)
        if not exists(target_filepath):
            if download_if_missing:
                logger.info('Downloading LFW metadata: %s', target.url)
                _fetch_remote(target, dirname=lfw_home, n_retries=n_retries, delay=delay)
            else:
                raise OSError('%s is missing' % target_filepath)
    if funneled:
        data_folder_path = join(lfw_home, 'lfw_funneled')
        archive = FUNNELED_ARCHIVE
    else:
        data_folder_path = join(lfw_home, 'lfw')
        archive = ARCHIVE
    if not exists(data_folder_path):
        archive_path = join(lfw_home, archive.filename)
        if not exists(archive_path):
            if download_if_missing:
                logger.info('Downloading LFW data (~200MB): %s', archive.url)
                _fetch_remote(archive, dirname=lfw_home, n_retries=n_retries, delay=delay)
            else:
                raise OSError('%s is missing' % archive_path)
        import tarfile
        logger.debug('Decompressing the data archive to %s', data_folder_path)
        with tarfile.open(archive_path, 'r:gz') as fp:
            tarfile_extractall(fp, path=lfw_home)
        remove(archive_path)
    return (lfw_home, data_folder_path)

def _load_imgs(file_paths, slice_, color, resize):
    try:
        from PIL import Image
    except ImportError:
        raise ImportError('The Python Imaging Library (PIL) is required to load data from jpeg files. Please refer to https://pillow.readthedocs.io/en/stable/installation.html for installing PIL.')
    default_slice = (slice(0, 250), slice(0, 250))
    if slice_ is None:
        slice_ = default_slice
    else:
        slice_ = tuple((s or ds for s, ds in zip(slice_, default_slice)))
    h_slice, w_slice = slice_
    h = (h_slice.stop - h_slice.start) // (h_slice.step or 1)
    w = (w_slice.stop - w_slice.start) // (w_slice.step or 1)
    if resize is not None:
        resize = float(resize)
        h = int(resize * h)
        w = int(resize * w)
    n_faces = len(file_paths)
    if not color:
        faces = np.zeros((n_faces, h, w), dtype=np.float32)
    else:
        faces = np.zeros((n_faces, h, w, 3), dtype=np.float32)
    for i, file_path in enumerate(file_paths):
        if i % 1000 == 0:
            logger.debug('Loading face #%05d / %05d', i + 1, n_faces)
        with Image.open(file_path) as pil_img:
            pil_img = pil_img.crop((w_slice.start, h_slice.start, w_slice.stop, h_slice.stop))
            if resize is not None:
                pil_img = pil_img.resize((w, h))
            face = np.asarray(pil_img, dtype=np.float32)
        if face.ndim == 0:
            raise RuntimeError('Failed to read the image file %s, Please make sure that libjpeg is installed' % file_path)
        face /= 255.0
        if not color:
            face = face.mean(axis=2)
        faces[i, ...] = face
    return faces

