@validate_params({'n_samples': [Interval(Integral, 0, None, closed='left'), tuple], 'shuffle': ['boolean'], 'noise': [Interval(Real, 0, None, closed='left'), None], 'random_state': ['random_state'], 'factor': [Interval(Real, 0, 1, closed='left')]}, prefer_skip_nested_validation=True)
def make_circles(n_samples=100, *, shuffle=True, noise=None, random_state=None, factor=0.8):
    if isinstance(n_samples, numbers.Integral):
        n_samples_out = n_samples // 2
        n_samples_in = n_samples - n_samples_out
    else:
        if len(n_samples) != 2:
            raise ValueError('When a tuple, n_samples must have exactly two elements.')
        n_samples_out, n_samples_in = n_samples
    generator = check_random_state(random_state)
    linspace_out = np.linspace(0, 2 * np.pi, n_samples_out, endpoint=False)
    linspace_in = np.linspace(0, 2 * np.pi, n_samples_in, endpoint=False)
    outer_circ_x = np.cos(linspace_out)
    outer_circ_y = np.sin(linspace_out)
    inner_circ_x = np.cos(linspace_in) * factor
    inner_circ_y = np.sin(linspace_in) * factor
    X = np.vstack([np.append(outer_circ_x, inner_circ_x), np.append(outer_circ_y, inner_circ_y)]).T
    y = np.hstack([np.zeros(n_samples_out, dtype=np.intp), np.ones(n_samples_in, dtype=np.intp)])
    if shuffle:
        X, y = util_shuffle(X, y, random_state=generator)
    if noise is not None:
        X += generator.normal(scale=noise, size=X.shape)
    return (X, y)

@validate_params({'n_samples': [Interval(Integral, 1, None, closed='left'), tuple], 'shuffle': ['boolean'], 'noise': [Interval(Real, 0, None, closed='left'), None], 'random_state': ['random_state']}, prefer_skip_nested_validation=True)
def make_moons(n_samples=100, *, shuffle=True, noise=None, random_state=None):
    if isinstance(n_samples, numbers.Integral):
        n_samples_out = n_samples // 2
        n_samples_in = n_samples - n_samples_out
    else:
        try:
            n_samples_out, n_samples_in = n_samples
        except ValueError as e:
            raise ValueError('`n_samples` can be either an int or a two-element tuple.') from e
    generator = check_random_state(random_state)
    outer_circ_x = np.cos(np.linspace(0, np.pi, n_samples_out))
    outer_circ_y = np.sin(np.linspace(0, np.pi, n_samples_out))
    inner_circ_x = 1 - np.cos(np.linspace(0, np.pi, n_samples_in))
    inner_circ_y = 1 - np.sin(np.linspace(0, np.pi, n_samples_in)) - 0.5
    X = np.vstack([np.append(outer_circ_x, inner_circ_x), np.append(outer_circ_y, inner_circ_y)]).T
    y = np.hstack([np.zeros(n_samples_out, dtype=np.intp), np.ones(n_samples_in, dtype=np.intp)])
    if shuffle:
        X, y = util_shuffle(X, y, random_state=generator)
    if noise is not None:
        X += generator.normal(scale=noise, size=X.shape)
    return (X, y)

@validate_params({'n_samples': [Interval(Integral, 1, None, closed='left'), 'array-like'], 'n_features': [Interval(Integral, 1, None, closed='left')], 'centers': [Interval(Integral, 1, None, closed='left'), 'array-like', None], 'cluster_std': [Interval(Real, 0, None, closed='left'), 'array-like'], 'center_box': [tuple], 'shuffle': ['boolean'], 'random_state': ['random_state'], 'return_centers': ['boolean']}, prefer_skip_nested_validation=True)
def make_blobs(n_samples=100, n_features=2, *, centers=None, cluster_std=1.0, center_box=(-10.0, 10.0), shuffle=True, random_state=None, return_centers=False):
    generator = check_random_state(random_state)
    if isinstance(n_samples, numbers.Integral):
        if centers is None:
            centers = 3
        if isinstance(centers, numbers.Integral):
            n_centers = centers
            centers = generator.uniform(center_box[0], center_box[1], size=(n_centers, n_features))
        else:
            centers = check_array(centers)
            n_features = centers.shape[1]
            n_centers = centers.shape[0]
    else:
        n_centers = len(n_samples)
        if centers is None:
            centers = generator.uniform(center_box[0], center_box[1], size=(n_centers, n_features))
        if not isinstance(centers, Iterable):
            raise ValueError('Parameter `centers` must be array-like. Got {!r} instead'.format(centers))
        if len(centers) != n_centers:
            raise ValueError(f'Length of `n_samples` not consistent with number of centers. Got n_samples = {n_samples} and centers = {centers}')
        centers = check_array(centers)
        n_features = centers.shape[1]
    if hasattr(cluster_std, '__len__') and len(cluster_std) != n_centers:
        raise ValueError('Length of `clusters_std` not consistent with number of centers. Got centers = {} and cluster_std = {}'.format(centers, cluster_std))
    if isinstance(cluster_std, numbers.Real):
        cluster_std = np.full(len(centers), cluster_std)
    if isinstance(n_samples, Iterable):
        n_samples_per_center = n_samples
    else:
        n_samples_per_center = [int(n_samples // n_centers)] * n_centers
        for i in range(n_samples % n_centers):
            n_samples_per_center[i] += 1
    cum_sum_n_samples = np.cumsum(n_samples_per_center)
    X = np.empty(shape=(sum(n_samples_per_center), n_features), dtype=np.float64)
    y = np.empty(shape=(sum(n_samples_per_center),), dtype=int)
    for i, (n, std) in enumerate(zip(n_samples_per_center, cluster_std)):
        start_idx = cum_sum_n_samples[i - 1] if i > 0 else 0
        end_idx = cum_sum_n_samples[i]
        X[start_idx:end_idx] = generator.normal(loc=centers[i], scale=std, size=(n, n_features))
        y[start_idx:end_idx] = i
    if shuffle:
        X, y = util_shuffle(X, y, random_state=generator)
    if return_centers:
        return (X, y, centers)
    else:
        return (X, y)

@validate_params({'n_samples': [Interval(Integral, 1, None, closed='left')], 'n_features': [Interval(Integral, 5, None, closed='left')], 'noise': [Interval(Real, 0.0, None, closed='left')], 'random_state': ['random_state']}, prefer_skip_nested_validation=True)
def make_friedman1(n_samples=100, n_features=10, *, noise=0.0, random_state=None):
    generator = check_random_state(random_state)
    X = generator.uniform(size=(n_samples, n_features))
    y = 10 * np.sin(np.pi * X[:, 0] * X[:, 1]) + 20 * (X[:, 2] - 0.5) ** 2 + 10 * X[:, 3] + 5 * X[:, 4] + noise * generator.standard_normal(size=n_samples)
    return (X, y)

@validate_params({'n_samples': [Interval(Integral, 1, None, closed='left')], 'n_features': [Interval(Integral, 1, None, closed='left')], 'random_state': ['random_state']}, prefer_skip_nested_validation=True)
