@validate_params({'n_dim': [Interval(Integral, 1, None, closed='left')], 'alpha': [Interval(Real, 0, 1, closed='both')], 'norm_diag': ['boolean'], 'smallest_coef': [Interval(Real, 0, 1, closed='both')], 'largest_coef': [Interval(Real, 0, 1, closed='both')], 'sparse_format': [StrOptions({'bsr', 'coo', 'csc', 'csr', 'dia', 'dok', 'lil'}), None], 'random_state': ['random_state']}, prefer_skip_nested_validation=True)
def make_sparse_spd_matrix(n_dim=1, *, alpha=0.95, norm_diag=False, smallest_coef=0.1, largest_coef=0.9, sparse_format=None, random_state=None):
    random_state = check_random_state(random_state)
    chol = -_sparse_eye_array(n_dim)
    aux = _sparse_random_array(shape=(n_dim, n_dim), density=1 - alpha, data_sampler=lambda size: random_state.uniform(low=smallest_coef, high=largest_coef, size=size), random_state=random_state)
    aux = sp.tril(aux, k=-1, format='csc')
    permutation = random_state.permutation(n_dim)
    aux = aux[permutation].T[permutation]
    chol += aux
    prec = chol.T @ chol
    if norm_diag:
        d = _sparse_diags_array(1.0 / np.sqrt(prec.diagonal()))
        prec = d @ prec @ d
    if sparse_format is None:
        return prec.toarray()
    else:
        return _align_api_if_sparse(prec.asformat(sparse_format))

@validate_params({'mean': ['array-like', None], 'cov': [Interval(Real, 0, None, closed='left')], 'n_samples': [Interval(Integral, 1, None, closed='left')], 'n_features': [Interval(Integral, 1, None, closed='left')], 'n_classes': [Interval(Integral, 1, None, closed='left')], 'shuffle': ['boolean'], 'random_state': ['random_state']}, prefer_skip_nested_validation=True)
def make_gaussian_quantiles(*, mean=None, cov=1.0, n_samples=100, n_features=2, n_classes=3, shuffle=True, random_state=None):
