def get_precision(self):
    xp, is_array_api_compliant = get_namespace(self.components_)
    n_features = self.components_.shape[1]
    if self.n_components_ == 0:
        return xp.eye(n_features) / self.noise_variance_
    if is_array_api_compliant:
        linalg_inv = xp.linalg.inv
    else:
        linalg_inv = linalg.inv
    if self.noise_variance_ == 0.0:
        return linalg_inv(self.get_covariance())
    components_ = self.components_
    exp_var = self.explained_variance_
    if self.whiten:
        components_ = components_ * xp.sqrt(exp_var[:, np.newaxis])
    exp_var_diff = exp_var - self.noise_variance_
    exp_var_diff = xp.where(exp_var > self.noise_variance_, exp_var_diff, xp.asarray(0.0, device=device(exp_var)))
    precision = components_ @ components_.T / self.noise_variance_
    _add_to_diagonal(precision, 1.0 / exp_var_diff, xp)
    precision = components_.T @ linalg_inv(precision) @ components_
    precision /= -self.noise_variance_ ** 2
    _add_to_diagonal(precision, 1.0 / self.noise_variance_, xp)
    return precision

@abstractmethod
def fit(self, X, y=None):
    pass

def transform(self, X):
    xp, _ = get_namespace(X, self.components_, self.explained_variance_)
    check_is_fitted(self)
    X = validate_data(self, X, dtype=[xp.float64, xp.float32], accept_sparse=('csr', 'csc'), reset=False)
    return self._transform(X, xp=xp, x_is_centered=False)

def inverse_transform(self, X):
    xp, _ = get_namespace(X, self.components_, self.explained_variance_)
    check_is_fitted(self)
    X = check_array(X, input_name='X', dtype=[xp.float64, xp.float32])
    if self.whiten:
        scaled_components = xp.sqrt(self.explained_variance_[:, np.newaxis]) * self.components_
        return X @ scaled_components + self.mean_
    else:
        return X @ self.components_ + self.mean_

@property
def _n_features_out(self):
    return self.components_.shape[0]

def _sparse_encode_precomputed(X, dictionary, *, gram=None, cov=None, algorithm='lasso_lars', regularization=None, copy_cov=True, init=None, max_iter=1000, verbose=0, positive=False):
    n_samples, n_features = X.shape
    n_components = dictionary.shape[0]
    if algorithm == 'lasso_lars':
        alpha = float(regularization) / n_features
        try:
            err_mgt = np.seterr(all='ignore')
            lasso_lars = LassoLars(alpha=alpha, fit_intercept=False, verbose=verbose, precompute=gram, fit_path=False, positive=positive, max_iter=max_iter)
            lasso_lars.fit(dictionary.T, X.T, Xy=cov)
            new_code = lasso_lars.coef_
        finally:
            np.seterr(**err_mgt)
    elif algorithm == 'lasso_cd':
        alpha = float(regularization) / n_features
        clf = Lasso(alpha=alpha, fit_intercept=False, precompute=gram, tol=1e-08, max_iter=max_iter, warm_start=True, positive=positive)
        if init is not None:
            if not init.flags['WRITEABLE']:
                init = np.array(init)
            clf.coef_ = init
        clf.fit(dictionary.T, X.T, check_input=False)
        new_code = clf.coef_
    elif algorithm == 'lars':
        try:
            err_mgt = np.seterr(all='ignore')
            lars = Lars(fit_intercept=False, verbose=verbose, precompute=gram, n_nonzero_coefs=int(regularization), fit_path=False)
            lars.fit(dictionary.T, X.T, Xy=cov)
            new_code = lars.coef_
        finally:
            np.seterr(**err_mgt)
    elif algorithm == 'threshold':
        new_code = (np.sign(cov) * np.maximum(np.abs(cov) - regularization, 0)).T
        if positive:
            np.clip(new_code, 0, None, out=new_code)
    elif algorithm == 'omp':
        new_code = orthogonal_mp_gram(Gram=gram, Xy=cov, n_nonzero_coefs=int(regularization), tol=None, norms_squared=row_norms(X, squared=True), copy_Xy=copy_cov).T
    return new_code.reshape(n_samples, n_components)

@validate_params({'X': ['array-like'], 'dictionary': ['array-like'], 'gram': ['array-like', None], 'cov': ['array-like', None], 'algorithm': [StrOptions({'lasso_lars', 'lasso_cd', 'lars', 'omp', 'threshold'})], 'n_nonzero_coefs': [Interval(Integral, 1, None, closed='left'), None], 'alpha': [Interval(Real, 0, None, closed='left'), None], 'copy_cov': ['boolean'], 'init': ['array-like', None], 'max_iter': [Interval(Integral, 0, None, closed='left')], 'n_jobs': [Integral, None], 'check_input': ['boolean'], 'verbose': ['verbose'], 'positive': ['boolean']}, prefer_skip_nested_validation=True)
def sparse_encode(X, dictionary, *, gram=None, cov=None, algorithm='lasso_lars', n_nonzero_coefs=None, alpha=None, copy_cov=True, init=None, max_iter=1000, n_jobs=None, check_input=True, verbose=0, positive=False):
    if check_input:
        order = 'C' if algorithm == 'lasso_cd' else None
        dictionary = check_array(dictionary, order=order, dtype=[np.float64, np.float32])
        X = check_array(X, order=order, dtype=[np.float64, np.float32])
    if dictionary.shape[1] != X.shape[1]:
        raise ValueError('Dictionary and X have different numbers of features:dictionary.shape: {} X.shape{}'.format(dictionary.shape, X.shape))
    _check_positive_coding(algorithm, positive)
    return _sparse_encode(X, dictionary, gram=gram, cov=cov, algorithm=algorithm, n_nonzero_coefs=n_nonzero_coefs, alpha=alpha, copy_cov=copy_cov, init=init, max_iter=max_iter, n_jobs=n_jobs, verbose=verbose, positive=positive)

def _sparse_encode(X, dictionary, *, gram=None, cov=None, algorithm='lasso_lars', n_nonzero_coefs=None, alpha=None, copy_cov=True, init=None, max_iter=1000, n_jobs=None, verbose=0, positive=False):
    n_samples, n_features = X.shape
    n_components = dictionary.shape[0]
    if algorithm in ('lars', 'omp'):
        regularization = n_nonzero_coefs
        if regularization is None:
            regularization = min(max(n_features / 10, 1), n_components)
    else:
        regularization = alpha
        if regularization is None:
            regularization = 1.0
    if gram is None and algorithm != 'threshold':
        gram = np.dot(dictionary, dictionary.T).astype(X.dtype, copy=False)
    if cov is None and algorithm != 'lasso_cd':
        copy_cov = False
        cov = np.dot(dictionary, X.T)
    if effective_n_jobs(n_jobs) == 1 or algorithm == 'threshold':
        code = _sparse_encode_precomputed(X, dictionary, gram=gram, cov=cov, algorithm=algorithm, regularization=regularization, copy_cov=copy_cov, init=init, max_iter=max_iter, verbose=verbose, positive=positive)
        return code
    n_samples = X.shape[0]
    n_components = dictionary.shape[0]
    code = np.empty((n_samples, n_components))
    slices = list(gen_even_slices(n_samples, effective_n_jobs(n_jobs)))
    code_views = Parallel(n_jobs=n_jobs, verbose=verbose)((delayed(_sparse_encode_precomputed)(X[this_slice], dictionary, gram=gram, cov=cov[:, this_slice] if cov is not None else None, algorithm=algorithm, regularization=regularization, copy_cov=copy_cov, init=init[this_slice] if init is not None else None, max_iter=max_iter, verbose=verbose, positive=positive) for this_slice in slices))
    for this_slice, this_view in zip(slices, code_views):
        code[this_slice] = this_view
    return code

def _update_dict(dictionary, Y, code, A=None, B=None, verbose=False, random_state=None, positive=False):
    n_samples, n_components = code.shape
    random_state = check_random_state(random_state)
    if A is None:
        A = code.T @ code
    if B is None:
        B = Y.T @ code
    n_unused = 0
    for k in range(n_components):
        if A[k, k] > 1e-06:
            dictionary[k] += (B[:, k] - A[k] @ dictionary) / A[k, k]
        else:
            newd = Y[random_state.choice(n_samples)]
            noise_level = 0.01 * (newd.std() or 1)
            noise = random_state.normal(0, noise_level, size=len(newd))
            dictionary[k] = newd + noise
            code[:, k] = 0
            n_unused += 1
        if positive:
            np.clip(dictionary[k], 0, None, out=dictionary[k])
        dictionary[k] /= max(linalg.norm(dictionary[k]), 1)
    if verbose and n_unused > 0:
        print(f'{n_unused} unused atoms resampled.')

def _dict_learning(X, n_components, *, alpha, max_iter, tol, method, n_jobs, dict_init, code_init, callback, verbose, random_state, return_n_iter, positive_dict, positive_code, method_max_iter):
    t0 = time.time()
    if code_init is not None and dict_init is not None:
        code = np.array(code_init, order='F')
        dictionary = dict_init
    else:
        code, S, dictionary = linalg.svd(X, full_matrices=False)
        code, dictionary = svd_flip(code, dictionary)
        dictionary = S[:, np.newaxis] * dictionary
    r = len(dictionary)
    if n_components <= r:
        code = code[:, :n_components]
        dictionary = dictionary[:n_components, :]
    else:
        code = np.c_[code, np.zeros((len(code), n_components - r))]
        dictionary = np.r_[dictionary, np.zeros((n_components - r, dictionary.shape[1]))]
    dictionary = np.asfortranarray(dictionary)
    errors = []
    current_cost = np.nan
    if verbose == 1:
        print('[dict_learning]', end=' ')
    ii = -1
    for ii in range(max_iter):
        dt = time.time() - t0
        if verbose == 1:
            sys.stdout.write('.')
            sys.stdout.flush()
        elif verbose:
            print('Iteration % 3i (elapsed time: % 3is, % 4.1fmn, current cost % 7.3f)' % (ii, dt, dt / 60, current_cost))
        code = sparse_encode(X, dictionary, algorithm=method, alpha=alpha, init=code, n_jobs=n_jobs, positive=positive_code, max_iter=method_max_iter, verbose=verbose)
        _update_dict(dictionary, X, code, verbose=verbose, random_state=random_state, positive=positive_dict)
        current_cost = 0.5 * np.sum((X - code @ dictionary) ** 2) + alpha * np.sum(np.abs(code))
        errors.append(current_cost)
        if ii > 0:
            dE = errors[-2] - errors[-1]
            if dE < tol * errors[-1]:
                if verbose == 1:
                    print('')
                elif verbose:
                    print('--- Convergence reached after %d iterations' % ii)
                break
        if ii % 5 == 0 and callback is not None:
            callback(locals())
    if return_n_iter:
        return (code, dictionary, errors, ii + 1)
    else:
        return (code, dictionary, errors)

@validate_params({'X': ['array-like'], 'return_code': ['boolean'], 'method': [StrOptions({'cd', 'lars'})], 'method_max_iter': [Interval(Integral, 0, None, closed='left')]}, prefer_skip_nested_validation=False)
def dict_learning_online(X, n_components=2, *, alpha=1, max_iter=100, return_code=True, dict_init=None, callback=None, batch_size=256, verbose=False, shuffle=True, n_jobs=None, method='lars', random_state=None, positive_dict=False, positive_code=False, method_max_iter=1000, tol=0.001, max_no_improvement=10):
