    if return_n_iter:
        return (code, estimator.components_, estimator.error_, estimator.n_iter_)
    return (code, estimator.components_, estimator.error_)

def transform(self, X):
    check_is_fitted(self)
    return self._transform(X, self.components_)

def _inverse_transform(self, code, dictionary):
    code = check_array(code)
    expected_n_components = dictionary.shape[0]
    if self.split_sign:
        expected_n_components += expected_n_components
    if not code.shape[1] == expected_n_components:
        raise ValueError(f'The number of components in the code is different from the number of components in the dictionary.Expected {expected_n_components}, got {code.shape[1]}.')
    if self.split_sign:
        n_samples, n_features = code.shape
        n_features //= 2
        code = code[:, :n_features] - code[:, n_features:]
    return code @ dictionary

def inverse_transform(self, X):
    check_is_fitted(self)
    return self._inverse_transform(X, self.components_)

@_fit_context(prefer_skip_nested_validation=True)
def fit(self, X, y=None):
    X = validate_data(self, X)
    self.n_components_ = self.dictionary.shape[0]
    if X.shape[1] != self.dictionary.shape[1]:
        raise ValueError(f'Dictionary and X have different numbers of features:dictionary.shape: {self.dictionary.shape} X.shape: {X.shape}')
    return self

@property
def _n_features_out(self):
    return self.n_components_

def fit(self, X, y=None):
    self.fit_transform(X)
    return self

@property
def _n_features_out(self):
    return self.components_.shape[0]

def _initialize_dict(self, X, random_state):
    if self.dict_init is not None:
        dictionary = self.dict_init
    else:
        _, S, dictionary = _randomized_svd(X, self._n_components, random_state=random_state)
        dictionary = S[:, np.newaxis] * dictionary
    if self._n_components <= len(dictionary):
        dictionary = dictionary[:self._n_components, :]
    else:
        dictionary = np.concatenate((dictionary, np.zeros((self._n_components - len(dictionary), dictionary.shape[1]), dtype=dictionary.dtype)))
    dictionary = check_array(dictionary, order='F', dtype=X.dtype, copy=False)
    dictionary = np.require(dictionary, requirements='W')
    return dictionary

def _update_inner_stats(self, X, code, batch_size, step):
    if step < batch_size - 1:
        theta = (step + 1) * batch_size
    else:
        theta = batch_size ** 2 + step + 1 - batch_size
    beta = (theta + 1 - batch_size) / (theta + 1)
    self._A *= beta
    self._A += code.T @ code / batch_size
    self._B *= beta
    self._B += X.T @ code / batch_size

def _check_convergence(self, X, batch_cost, new_dict, old_dict, n_samples, step, n_steps):
    batch_size = X.shape[0]
    step = step + 1
    if step <= min(100, n_samples / batch_size):
        if self.verbose:
            print(f'Minibatch step {step}/{n_steps}: mean batch cost: {batch_cost}')
        return False
    if self._ewa_cost is None:
        self._ewa_cost = batch_cost
    else:
        alpha = batch_size / (n_samples + 1)
        alpha = min(alpha, 1)
        self._ewa_cost = self._ewa_cost * (1 - alpha) + batch_cost * alpha
    if self.verbose:
        print(f'Minibatch step {step}/{n_steps}: mean batch cost: {batch_cost}, ewa cost: {self._ewa_cost}')
    dict_diff = linalg.norm(new_dict - old_dict) / self._n_components
    if self.tol > 0 and dict_diff <= self.tol:
        if self.verbose:
            print(f'Converged (small dictionary change) at step {step}/{n_steps}')
        return True
    if self._ewa_cost_min is None or self._ewa_cost < self._ewa_cost_min:
        self._no_improvement = 0
        self._ewa_cost_min = self._ewa_cost
    else:
        self._no_improvement += 1
    if self.max_no_improvement is not None and self._no_improvement >= self.max_no_improvement:
        if self.verbose:
            print(f'Converged (lack of improvement in objective function) at step {step}/{n_steps}')
        return True
    return False

@property
def _n_features_out(self):
    return self.components_.shape[0]

@_fit_context(prefer_skip_nested_validation=True)
def fit(self, X, y=None):
    X = validate_data(self, X, copy=self.copy, dtype=np.float64, force_writeable=True)
    n_samples, n_features = X.shape
    n_components = self.n_components
    if n_components is None:
        n_components = n_features
    self.mean_ = np.mean(X, axis=0)
    X -= self.mean_
    nsqrt = sqrt(n_samples)
    llconst = n_features * log(2.0 * np.pi) + n_components
    var = np.var(X, axis=0)
    if self.noise_variance_init is None:
        psi = np.ones(n_features, dtype=X.dtype)
    else:
        if len(self.noise_variance_init) != n_features:
            raise ValueError('noise_variance_init dimension does not with number of features : %d != %d' % (len(self.noise_variance_init), n_features))
        psi = np.array(self.noise_variance_init)
    loglike = []
    old_ll = -np.inf
    SMALL = 1e-12
    if self.svd_method == 'lapack':

        def my_svd(X):
            _, s, Vt = linalg.svd(X, full_matrices=False, check_finite=False)
            return (s[:n_components], Vt[:n_components], squared_norm(s[n_components:]))
    else:
        random_state = check_random_state(self.random_state)

        def my_svd(X):
            _, s, Vt = _randomized_svd(X, n_components, random_state=random_state, n_iter=self.iterated_power)
            return (s, Vt, squared_norm(X) - squared_norm(s))
    for i in range(self.max_iter):
        sqrt_psi = np.sqrt(psi) + SMALL
        s, Vt, unexp_var = my_svd(X / (sqrt_psi * nsqrt))
        s **= 2
        W = np.sqrt(np.maximum(s - 1.0, 0.0))[:, np.newaxis] * Vt
        del Vt
        W *= sqrt_psi
        ll = llconst + np.sum(np.log(s))
        ll += unexp_var + np.sum(np.log(psi))
        ll *= -n_samples / 2.0
        loglike.append(ll)
        if ll - old_ll < self.tol:
            break
        old_ll = ll
        psi = np.maximum(var - np.sum(W ** 2, axis=0), SMALL)
    else:
        warnings.warn('FactorAnalysis did not converge. You might want to increase the number of iterations.', ConvergenceWarning)
    self.components_ = W
    if self.rotation is not None:
        self.components_ = self._rotate(W)
    self.noise_variance_ = psi
    self.loglike_ = loglike
    self.n_iter_ = i + 1
    return self

def get_precision(self):
    check_is_fitted(self)
    n_features = self.components_.shape[1]
    if self.n_components == 0:
        return np.diag(1.0 / self.noise_variance_)
    if self.n_components == n_features:
        return linalg.inv(self.get_covariance())
    components_ = self.components_
    precision = np.dot(components_ / self.noise_variance_, components_.T)
    precision.flat[::len(precision) + 1] += 1.0
    precision = np.dot(components_.T, np.dot(linalg.inv(precision), components_))
    precision /= self.noise_variance_[:, np.newaxis]
    precision /= -self.noise_variance_[np.newaxis, :]
    precision.flat[::len(precision) + 1] += 1.0 / self.noise_variance_
    return precision

@property
def _n_features_out(self):
    return self.components_.shape[0]

def _gs_decorrelation(w, W, j):
    w -= np.linalg.multi_dot([w, W[:j].T, W[:j]])
    return w

def _sym_decorrelation(W):
    s, u = linalg.eigh(np.dot(W, W.T))
    s = np.clip(s, a_min=np.finfo(W.dtype).tiny, a_max=None)
    return np.linalg.multi_dot([u * (1.0 / np.sqrt(s)), u.T, W])

def _ica_par(X, tol, g, fun_args, max_iter, w_init):
    W = _sym_decorrelation(w_init)
    del w_init
    p_ = float(X.shape[1])
    for ii in range(max_iter):
        gwtx, g_wtx = g(np.dot(W, X), fun_args)
        W1 = _sym_decorrelation(np.dot(gwtx, X.T) / p_ - g_wtx[:, np.newaxis] * W)
        del gwtx, g_wtx
        lim = max(abs(abs(np.einsum('ij,ij->i', W1, W)) - 1))
        W = W1
        if lim < tol:
            break
    else:
        warnings.warn('FastICA did not converge. Consider increasing tolerance or the maximum number of iterations.', ConvergenceWarning)
    return (W, ii + 1)

@validate_params({'X': ['array-like'], 'return_X_mean': ['boolean'], 'compute_sources': ['boolean'], 'return_n_iter': ['boolean']}, prefer_skip_nested_validation=False)
def fastica(X, n_components=None, *, algorithm='parallel', whiten='unit-variance', fun='logcosh', fun_args=None, max_iter=200, tol=0.0001, w_init=None, whiten_solver='svd', random_state=None, return_X_mean=False, compute_sources=True, return_n_iter=False):
    est = FastICA(n_components=n_components, algorithm=algorithm, whiten=whiten, fun=fun, fun_args=fun_args, max_iter=max_iter, tol=tol, w_init=w_init, whiten_solver=whiten_solver, random_state=random_state)
    est._validate_params()
    S = est._fit_transform(X, compute_sources=compute_sources)
    if est.whiten in ['unit-variance', 'arbitrary-variance']:
        K = est.whitening_
        X_mean = est.mean_
    else:
        K = None
        X_mean = None
    returned_values = [K, est._unmixing, S]
    if return_X_mean:
        returned_values.append(X_mean)
    if return_n_iter:
        returned_values.append(est.n_iter_)
    return returned_values

def _fit_transform(self, X, compute_sources=False):
    XT = validate_data(self, X, copy=self.whiten, dtype=[np.float64, np.float32], ensure_min_samples=2).T
    fun_args = {} if self.fun_args is None else self.fun_args
    random_state = check_random_state(self.random_state)
    alpha = fun_args.get('alpha', 1.0)
    if not 1 <= alpha <= 2:
        raise ValueError('alpha must be in [1,2]')
    if self.fun == 'logcosh':
        g = _logcosh
    elif self.fun == 'exp':
        g = _exp
    elif self.fun == 'cube':
        g = _cube
    elif callable(self.fun):

        def g(x, fun_args):
            return self.fun(x, **fun_args)
    n_features, n_samples = XT.shape
    n_components = self.n_components
    if not self.whiten and n_components is not None:
        n_components = None
        warnings.warn('Ignoring n_components with whiten=False.')
    if n_components is None:
        n_components = min(n_samples, n_features)
    if n_components > min(n_samples, n_features):
        n_components = min(n_samples, n_features)
        warnings.warn('n_components is too large: it will be set to %s' % n_components)
    if self.whiten:
        X_mean = XT.mean(axis=-1)
        XT -= X_mean[:, np.newaxis]
        if self.whiten_solver == 'eigh':
            d, u = linalg.eigh(XT.dot(X))
            sort_indices = np.argsort(d)[::-1]
            eps = np.finfo(d.dtype).eps * 10
            degenerate_idx = d < eps
            if np.any(degenerate_idx):
                warnings.warn("There are some small singular values, using whiten_solver = 'svd' might lead to more accurate results.")
            d[degenerate_idx] = eps
            np.sqrt(d, out=d)
            d, u = (d[sort_indices], u[:, sort_indices])
        elif self.whiten_solver == 'svd':
            u, d = linalg.svd(XT, full_matrices=False, check_finite=False)[:2]
        u *= np.sign(u[0])
        K = (u / d).T[:n_components]
        del u, d
        X1 = np.dot(K, XT)
        X1 *= np.sqrt(n_samples)
    else:
        X1 = as_float_array(XT, copy=False)
    w_init = self.w_init
    if w_init is None:
        w_init = np.asarray(random_state.normal(size=(n_components, n_components)), dtype=X1.dtype)
    else:
        w_init = np.asarray(w_init)
        if w_init.shape != (n_components, n_components):
            raise ValueError('w_init has invalid shape -- should be %(shape)s' % {'shape': (n_components, n_components)})
    kwargs = {'tol': self.tol, 'g': g, 'fun_args': fun_args, 'max_iter': self.max_iter, 'w_init': w_init}
    if self.algorithm == 'parallel':
        W, n_iter = _ica_par(X1, **kwargs)
    elif self.algorithm == 'deflation':
        W, n_iter = _ica_def(X1, **kwargs)
    del X1
    self.n_iter_ = n_iter
    if compute_sources:
        if self.whiten:
            S = np.linalg.multi_dot([W, K, XT]).T
        else:
            S = np.dot(W, XT).T
    else:
        S = None
    if self.whiten:
        if self.whiten == 'unit-variance':
            if not compute_sources:
                S = np.linalg.multi_dot([W, K, XT]).T
            S_std = np.std(S, axis=0, keepdims=True)
            S /= S_std
            W /= S_std.T
        self.components_ = np.dot(W, K)
        self.mean_ = X_mean
        self.whitening_ = K
    else:
        self.components_ = W
    self.mixing_ = linalg.pinv(self.components_, check_finite=False)
    self._unmixing = W
    return S

@_fit_context(prefer_skip_nested_validation=True)
def fit_transform(self, X, y=None):
    return self._fit_transform(X, compute_sources=True)

@_fit_context(prefer_skip_nested_validation=True)
def fit(self, X, y=None):
    self._fit_transform(X, compute_sources=False)
    return self

def transform(self, X, copy=True):
    check_is_fitted(self)
    X = validate_data(self, X, copy=copy and self.whiten, dtype=[np.float64, np.float32], reset=False)
    if self.whiten:
        X -= self.mean_
    return np.dot(X, self.components_.T)

@property
def _n_features_out(self):
    return self.components_.shape[0]

@_fit_context(prefer_skip_nested_validation=True)
def partial_fit(self, X, y=None, check_input=True):
    first_pass = not hasattr(self, 'components_')
    if check_input:
        if sparse.issparse(X):
            raise TypeError('IncrementalPCA.partial_fit does not support sparse input. Either convert data to dense or use IncrementalPCA.fit to do so in batches.')
        X = validate_data(self, X, copy=self.copy, dtype=[np.float64, np.float32], force_writeable=True, reset=first_pass)
    n_samples, n_features = X.shape
    if first_pass:
        self.components_ = None
    if self.n_components is None:
        if self.components_ is None:
            self.n_components_ = min(n_samples, n_features)
        else:
            self.n_components_ = self.components_.shape[0]
    elif not self.n_components <= n_features:
        raise ValueError('n_components=%r invalid for n_features=%d, need more rows than columns for IncrementalPCA processing' % (self.n_components, n_features))
    elif self.n_components > n_samples and first_pass:
        raise ValueError(f'n_components={self.n_components} must be less or equal to the batch number of samples {n_samples} for the first partial_fit call.')
    else:
        self.n_components_ = self.n_components
    if self.components_ is not None and self.components_.shape[0] != self.n_components_:
        raise ValueError('Number of input features has changed from %i to %i between calls to partial_fit! Try setting n_components to a fixed value.' % (self.components_.shape[0], self.n_components_))
    if not hasattr(self, 'n_samples_seen_'):
        self.n_samples_seen_ = 0
        self.mean_ = 0.0
        self.var_ = 0.0
    col_mean, col_var, n_total_samples = _incremental_mean_and_var(X, last_mean=self.mean_, last_variance=self.var_, last_sample_count=np.repeat(self.n_samples_seen_, X.shape[1]))
    n_total_samples = n_total_samples[0]
    if self.n_samples_seen_ == 0:
        X -= col_mean
    else:
        col_batch_mean = np.mean(X, axis=0)
        X -= col_batch_mean
        mean_correction = np.sqrt(self.n_samples_seen_ / n_total_samples * n_samples) * (self.mean_ - col_batch_mean)
        X = np.vstack((self.singular_values_.reshape((-1, 1)) * self.components_, X, mean_correction))
    U, S, Vt = linalg.svd(X, full_matrices=False, check_finite=False)
    U, Vt = svd_flip(U, Vt, u_based_decision=False)
    explained_variance = S ** 2 / (n_total_samples - 1)
    explained_variance_ratio = S ** 2 / np.sum(col_var * n_total_samples)
    self.n_samples_seen_ = n_total_samples
    self.components_ = Vt[:self.n_components_]
    self.singular_values_ = S[:self.n_components_]
    self.mean_ = col_mean
    self.var_ = col_var
    self.explained_variance_ = explained_variance[:self.n_components_]
    self.explained_variance_ratio_ = explained_variance_ratio[:self.n_components_]
    if self.n_components_ not in (n_samples, n_features):
        self.noise_variance_ = explained_variance[self.n_components_:].mean()
    else:
        self.noise_variance_ = 0.0
    return self

def transform(self, X):
    if sparse.issparse(X):
        n_samples = X.shape[0]
        output = []
        for batch in gen_batches(n_samples, self.batch_size_, min_batch_size=self.n_components or 0):
            output.append(super().transform(X[batch].toarray()))
        return np.vstack(output)
    else:
        return super().transform(X)

def _fit_transform_in_place(self, K):
    K = self._centerer.fit(K).transform(K, copy=False)
    if self.n_components is None:
        n_components = K.shape[0]
    else:
        n_components = min(K.shape[0], self.n_components)
    if self.eigen_solver == 'auto':
        if K.shape[0] > 200 and n_components < 10:
            eigen_solver = 'arpack'
        else:
            eigen_solver = 'dense'
    else:
        eigen_solver = self.eigen_solver
    if eigen_solver == 'dense':
        self.eigenvalues_, self.eigenvectors_ = eigh(K, subset_by_index=(K.shape[0] - n_components, K.shape[0] - 1))
    elif eigen_solver == 'arpack':
        v0 = _init_arpack_v0(K.shape[0], self.random_state)
        self.eigenvalues_, self.eigenvectors_ = eigsh(K, n_components, which='LA', tol=self.tol, maxiter=self.max_iter, v0=v0)
    elif eigen_solver == 'randomized':
        self.eigenvalues_, self.eigenvectors_ = _randomized_eigsh(K, n_components=n_components, n_iter=self.iterated_power, random_state=self.random_state, selection='module')
    self.eigenvalues_ = _check_psd_eigenvalues(self.eigenvalues_, enable_warnings=False)
    self.eigenvectors_, _ = svd_flip(u=self.eigenvectors_, v=None)
    indices = self.eigenvalues_.argsort()[::-1]
    self.eigenvalues_ = self.eigenvalues_[indices]
    self.eigenvectors_ = self.eigenvectors_[:, indices]
    if self.remove_zero_eig or self.n_components is None:
        self.eigenvectors_ = self.eigenvectors_[:, self.eigenvalues_ > 0]
        self.eigenvalues_ = self.eigenvalues_[self.eigenvalues_ > 0]
    return K

def fit_transform(self, X, y=None, **params):
    self.fit(X, **params)
    X_transformed = self.eigenvectors_ * np.sqrt(self.eigenvalues_)
    if self.fit_inverse_transform:
        self._fit_inverse_transform(X_transformed, X)
    return X_transformed

def inverse_transform(self, X):
    if not self.fit_inverse_transform:
        raise NotFittedError('The fit_inverse_transform parameter was not set to True when instantiating and hence the inverse transform is not available.')
    K = self._get_kernel(X, self.X_transformed_fit_)
    return np.dot(K, self.dual_coef_)

@property
def _n_features_out(self):
    return self.eigenvalues_.shape[0]

def _init_latent_vars(self, n_features, dtype=np.float64):
    self.random_state_ = check_random_state(self.random_state)
    self.n_batch_iter_ = 1
    self.n_iter_ = 0
    if self.doc_topic_prior is None:
        self.doc_topic_prior_ = 1.0 / self.n_components
    else:
        self.doc_topic_prior_ = self.doc_topic_prior
    if self.topic_word_prior is None:
        self.topic_word_prior_ = 1.0 / self.n_components
    else:
        self.topic_word_prior_ = self.topic_word_prior
    init_gamma = 100.0
    init_var = 1.0 / init_gamma
    self.components_ = self.random_state_.gamma(init_gamma, init_var, (self.n_components, n_features)).astype(dtype, copy=False)
    self.exp_dirichlet_component_ = np.exp(_dirichlet_expectation_2d(self.components_))

def _e_step(self, X, cal_sstats, random_init, parallel=None):
    random_state = self.random_state_ if random_init else None
    n_jobs = effective_n_jobs(self.n_jobs)
    if parallel is None:
        parallel = Parallel(n_jobs=n_jobs, verbose=max(0, self.verbose - 1))
    results = parallel((delayed(_update_doc_distribution)(X[idx_slice, :], self.exp_dirichlet_component_, self.doc_topic_prior_, self.max_doc_update_iter, self.mean_change_tol, cal_sstats, random_state) for idx_slice in gen_even_slices(X.shape[0], n_jobs)))
    doc_topics, sstats_list = zip(*results)
    doc_topic_distr = np.vstack(doc_topics)
    if cal_sstats:
        suff_stats = np.zeros(self.components_.shape, dtype=self.components_.dtype)
        for sstats in sstats_list:
            suff_stats += sstats
        suff_stats *= self.exp_dirichlet_component_
    else:
        suff_stats = None
    return (doc_topic_distr, suff_stats)

@_fit_context(prefer_skip_nested_validation=True)
def partial_fit(self, X, y=None):
    first_time = not hasattr(self, 'components_')
    X = self._check_non_neg_array(X, reset_n_features=first_time, whom='LatentDirichletAllocation.partial_fit')
    n_samples, n_features = X.shape
    batch_size = self.batch_size
    if first_time:
        self._init_latent_vars(n_features, dtype=X.dtype)
    if n_features != self.components_.shape[1]:
        raise ValueError('The provided data has %d dimensions while the model was trained with feature size %d.' % (n_features, self.components_.shape[1]))
    n_jobs = effective_n_jobs(self.n_jobs)
    with Parallel(n_jobs=n_jobs, verbose=max(0, self.verbose - 1)) as parallel:
        for idx_slice in gen_batches(n_samples, batch_size):
            self._em_step(X[idx_slice, :], total_samples=self.total_samples, batch_update=False, parallel=parallel)
    return self

@_fit_context(prefer_skip_nested_validation=True)
def fit(self, X, y=None):
    X = self._check_non_neg_array(X, reset_n_features=True, whom='LatentDirichletAllocation.fit')
    n_samples, n_features = X.shape
    max_iter = self.max_iter
    evaluate_every = self.evaluate_every
    learning_method = self.learning_method
    batch_size = self.batch_size
    self._init_latent_vars(n_features, dtype=X.dtype)
    last_bound = None
    n_jobs = effective_n_jobs(self.n_jobs)
    with Parallel(n_jobs=n_jobs, verbose=max(0, self.verbose - 1)) as parallel:
        for i in range(max_iter):
            if learning_method == 'online':
                for idx_slice in gen_batches(n_samples, batch_size):
                    self._em_step(X[idx_slice, :], total_samples=n_samples, batch_update=False, parallel=parallel)
            else:
                self._em_step(X, total_samples=n_samples, batch_update=True, parallel=parallel)
            if evaluate_every > 0 and (i + 1) % evaluate_every == 0:
                doc_topics_distr, _ = self._e_step(X, cal_sstats=False, random_init=False, parallel=parallel)
                bound = self._perplexity_precomp_distr(X, doc_topics_distr, sub_sampling=False)
                if self.verbose:
                    print('iteration: %d of max_iter: %d, perplexity: %.4f' % (i + 1, max_iter, bound))
                if last_bound and abs(last_bound - bound) < self.perp_tol:
                    break
                last_bound = bound
            elif self.verbose:
                print('iteration: %d of max_iter: %d' % (i + 1, max_iter))
            self.n_iter_ += 1
    doc_topics_distr, _ = self._e_step(X, cal_sstats=False, random_init=False, parallel=parallel)
    self.bound_ = self._perplexity_precomp_distr(X, doc_topics_distr, sub_sampling=False)
    return self

def _unnormalized_transform(self, X):
    doc_topic_distr, _ = self._e_step(X, cal_sstats=False, random_init=False)
    return doc_topic_distr

def _perplexity_precomp_distr(self, X, doc_topic_distr=None, sub_sampling=False):
    if doc_topic_distr is None:
        doc_topic_distr = self._unnormalized_transform(X)
    else:
        n_samples, n_components = doc_topic_distr.shape
        if n_samples != X.shape[0]:
            raise ValueError('Number of samples in X and doc_topic_distr do not match.')
        if n_components != self.n_components:
            raise ValueError('Number of topics does not match.')
    current_samples = X.shape[0]
    bound = self._approx_bound(X, doc_topic_distr, sub_sampling)
    if sub_sampling:
        word_cnt = X.sum() * (float(self.total_samples) / current_samples)
    else:
        word_cnt = X.sum()
    perword_bound = bound / word_cnt
    return np.exp(-1.0 * perword_bound)

def perplexity(self, X, sub_sampling=False):
    check_is_fitted(self)
    X = self._check_non_neg_array(X, reset_n_features=True, whom='LatentDirichletAllocation.perplexity')
    return self._perplexity_precomp_distr(X, sub_sampling=sub_sampling)

@property
def _n_features_out(self):
    return self.components_.shape[0]

def _beta_divergence(X, W, H, beta, square_root=False):
    beta = _beta_loss_to_float(beta)
    if not sp.issparse(X):
        X = np.atleast_2d(X)
    W = np.atleast_2d(W)
    H = np.atleast_2d(H)
    if beta == 2:
        if sp.issparse(X):
            norm_X = np.dot(X.data, X.data)
            norm_WH = trace_dot(np.linalg.multi_dot([W.T, W, H]), H)
            cross_prod = trace_dot(X @ H.T, W)
            res = (norm_X + norm_WH - 2.0 * cross_prod) / 2.0
        else:
            res = squared_norm(X - np.dot(W, H)) / 2.0
        if square_root:
            return np.sqrt(res * 2)
        else:
            return res
    if sp.issparse(X):
        WH_data = _special_sparse_dot(W, H, X).data
        X_data = X.data
    else:
        WH = np.dot(W, H)
        WH_data = WH.ravel()
        X_data = X.ravel()
    indices = X_data > EPSILON
    WH_data = WH_data[indices]
    X_data = X_data[indices]
    WH_data[WH_data < EPSILON] = EPSILON
    if beta == 1:
        sum_WH = np.dot(np.sum(W, axis=0), np.sum(H, axis=1))
        div = X_data / WH_data
        res = np.dot(X_data, np.log(div))
        res += sum_WH - X_data.sum()
    elif beta == 0:
        div = X_data / WH_data
        res = np.sum(div) - np.prod(X.shape) - np.sum(np.log(div))
    else:
        if sp.issparse(X):
            sum_WH_beta = 0
            for i in range(X.shape[1]):
                sum_WH_beta += np.sum(np.dot(W, H[:, i]) ** beta)
        else:
            sum_WH_beta = np.sum(WH ** beta)
        sum_X_WH = np.dot(X_data, WH_data ** (beta - 1))
        res = (X_data ** beta).sum() - beta * sum_X_WH
        res += sum_WH_beta * (beta - 1)
        res /= beta * (beta - 1)
    if square_root:
        res = max(res, 0)
        return np.sqrt(2 * res)
    else:
        return res

def _special_sparse_dot(W, H, X):
    if sp.issparse(X):
        ii, jj = X.nonzero()
        n_vals = ii.shape[0]
        dot_vals = np.empty(n_vals)
        n_components = W.shape[1]
        batch_size = max(n_components, n_vals // n_components)
        for start in range(0, n_vals, batch_size):
            batch = slice(start, start + batch_size)
            dot_vals[batch] = np.multiply(W[ii[batch], :], H.T[jj[batch], :]).sum(axis=1)
        WH = sp.coo_array((dot_vals, (ii, jj)), shape=X.shape)
        return _align_api_if_sparse(WH.tocsr())
    else:
        return np.dot(W, H)

def _beta_loss_to_float(beta_loss):
    beta_loss_map = {'frobenius': 2, 'kullback-leibler': 1, 'itakura-saito': 0}
    if isinstance(beta_loss, str):
        beta_loss = beta_loss_map[beta_loss]
    return beta_loss

def _update_coordinate_descent(X, W, Ht, l1_reg, l2_reg, shuffle, random_state):
    n_components = Ht.shape[1]
    HHt = np.dot(Ht.T, Ht)
    XHt = safe_sparse_dot(X, Ht)
    if l2_reg != 0.0:
        HHt.flat[::n_components + 1] += l2_reg
    if l1_reg != 0.0:
        XHt -= l1_reg
    if shuffle:
        permutation = random_state.permutation(n_components)
    else:
        permutation = np.arange(n_components)
    permutation = np.asarray(permutation, dtype=np.intp)
    return _update_cdnmf_fast(W, HHt, XHt, permutation)

def _fit_coordinate_descent(X, W, H, tol=0.0001, max_iter=200, l1_reg_W=0, l1_reg_H=0, l2_reg_W=0, l2_reg_H=0, update_H=True, verbose=0, shuffle=False, random_state=None):
    W = np.ascontiguousarray(W)
    Ht = np.ascontiguousarray(H.T)
    if sp.issparse(X) and X.format == 'csc':
        X = X.tocsr()
    rng = check_random_state(random_state)
    for n_iter in range(1, max_iter + 1):
        violation = 0.0
        violation += _update_coordinate_descent(X, W, Ht, l1_reg_W, l2_reg_W, shuffle, rng)
        if update_H:
            violation += _update_coordinate_descent(X.T, Ht, W, l1_reg_H, l2_reg_H, shuffle, rng)
        if n_iter == 1:
            violation_init = violation
        if violation_init == 0:
            break
        if verbose:
            print('violation:', violation / violation_init)
        if violation / violation_init <= tol:
            if verbose:
                print('Converged at iteration', n_iter + 1)
            break
    return (W, Ht.T, n_iter)

def _multiplicative_update_w(X, W, H, beta_loss, l1_reg_W, l2_reg_W, gamma, H_sum=None, HHt=None, XHt=None, update_H=True):
    if beta_loss == 2:
        if XHt is None:
            XHt = safe_sparse_dot(X, H.T)
        if update_H:
            numerator = XHt
        else:
            numerator = XHt.copy()
        if HHt is None:
            HHt = np.dot(H, H.T)
        denominator = np.dot(W, HHt)
    else:
        WH_safe_X = _special_sparse_dot(W, H, X)
        if sp.issparse(X):
            WH_safe_X_data = WH_safe_X.data
            X_data = X.data
        else:
            WH_safe_X_data = WH_safe_X
            X_data = X
            WH = WH_safe_X.copy()
            if beta_loss - 1.0 < 0:
                WH[WH < EPSILON] = EPSILON
        if beta_loss - 2.0 < 0:
            WH_safe_X_data[WH_safe_X_data < EPSILON] = EPSILON
        if beta_loss == 1:
            np.divide(X_data, WH_safe_X_data, out=WH_safe_X_data)
        elif beta_loss == 0:
            WH_safe_X_data **= -1
            WH_safe_X_data **= 2
            WH_safe_X_data *= X_data
        else:
            WH_safe_X_data **= beta_loss - 2
            WH_safe_X_data *= X_data
        numerator = safe_sparse_dot(WH_safe_X, H.T)
        if beta_loss == 1:
            if H_sum is None:
                H_sum = np.sum(H, axis=1)
            denominator = H_sum[np.newaxis, :]
        else:
            if sp.issparse(X):
                WHHt = np.empty(W.shape)
                for i in range(X.shape[0]):
                    WHi = np.dot(W[i, :], H)
                    if beta_loss - 1 < 0:
                        WHi[WHi < EPSILON] = EPSILON
                    WHi **= beta_loss - 1
                    WHHt[i, :] = np.dot(WHi, H.T)
            else:
                WH **= beta_loss - 1
                WHHt = np.dot(WH, H.T)
            denominator = WHHt
    if l1_reg_W > 0:
        denominator += l1_reg_W
    if l2_reg_W > 0:
        denominator = denominator + l2_reg_W * W
    denominator[denominator == 0] = EPSILON
    numerator /= denominator
    delta_W = numerator
    if gamma != 1:
        delta_W **= gamma
    W *= delta_W
    return (W, H_sum, HHt, XHt)

def _multiplicative_update_h(X, W, H, beta_loss, l1_reg_H, l2_reg_H, gamma, A=None, B=None, rho=None):
    if beta_loss == 2:
        numerator = safe_sparse_dot(W.T, X)
        denominator = np.linalg.multi_dot([W.T, W, H])
    else:
        WH_safe_X = _special_sparse_dot(W, H, X)
        if sp.issparse(X):
            WH_safe_X_data = WH_safe_X.data
            X_data = X.data
        else:
            WH_safe_X_data = WH_safe_X
            X_data = X
            WH = WH_safe_X.copy()
            if beta_loss - 1.0 < 0:
                WH[WH < EPSILON] = EPSILON
        if beta_loss - 2.0 < 0:
            WH_safe_X_data[WH_safe_X_data < EPSILON] = EPSILON
        if beta_loss == 1:
            np.divide(X_data, WH_safe_X_data, out=WH_safe_X_data)
        elif beta_loss == 0:
            WH_safe_X_data **= -1
            WH_safe_X_data **= 2
            WH_safe_X_data *= X_data
        else:
            WH_safe_X_data **= beta_loss - 2
            WH_safe_X_data *= X_data
        numerator = safe_sparse_dot(W.T, WH_safe_X)
        if beta_loss == 1:
            W_sum = np.sum(W, axis=0)
            W_sum[W_sum == 0] = 1.0
            denominator = W_sum[:, np.newaxis]
        else:
            if sp.issparse(X):
                WtWH = np.empty(H.shape)
                for i in range(X.shape[1]):
                    WHi = np.dot(W, H[:, i])
                    if beta_loss - 1 < 0:
                        WHi[WHi < EPSILON] = EPSILON
                    WHi **= beta_loss - 1
                    WtWH[:, i] = np.dot(W.T, WHi)
            else:
                WH **= beta_loss - 1
                WtWH = np.dot(W.T, WH)
            denominator = WtWH
    if l1_reg_H > 0:
        denominator += l1_reg_H
    if l2_reg_H > 0:
        denominator = denominator + l2_reg_H * H
    denominator[denominator == 0] = EPSILON
    if A is not None and B is not None:
        if gamma != 1:
            H **= 1 / gamma
        numerator *= H
        A *= rho
        B *= rho
        A += numerator
        B += denominator
        H = A / B
        if gamma != 1:
            H **= gamma
    else:
        delta_H = numerator
        delta_H /= denominator
        if gamma != 1:
            delta_H **= gamma
        H *= delta_H
    return H

def _fit_multiplicative_update(X, W, H, beta_loss='frobenius', max_iter=200, tol=0.0001, l1_reg_W=0, l1_reg_H=0, l2_reg_W=0, l2_reg_H=0, update_H=True, verbose=0):
    start_time = time.time()
    beta_loss = _beta_loss_to_float(beta_loss)
    if beta_loss < 1:
        gamma = 1.0 / (2.0 - beta_loss)
    elif beta_loss > 2:
        gamma = 1.0 / (beta_loss - 1.0)
    else:
        gamma = 1.0
    error_at_init = _beta_divergence(X, W, H, beta_loss, square_root=True)
    previous_error = error_at_init
    H_sum, HHt, XHt = (None, None, None)
    for n_iter in range(1, max_iter + 1):
        W, H_sum, HHt, XHt = _multiplicative_update_w(X, W, H, beta_loss=beta_loss, l1_reg_W=l1_reg_W, l2_reg_W=l2_reg_W, gamma=gamma, H_sum=H_sum, HHt=HHt, XHt=XHt, update_H=update_H)
        if beta_loss < 1:
            W[W < np.finfo(np.float64).eps] = 0.0
        if update_H:
            H = _multiplicative_update_h(X, W, H, beta_loss=beta_loss, l1_reg_H=l1_reg_H, l2_reg_H=l2_reg_H, gamma=gamma)
            H_sum, HHt, XHt = (None, None, None)
            if beta_loss <= 1:
                H[H < np.finfo(np.float64).eps] = 0.0
        if tol > 0 and n_iter % 10 == 0:
            error = _beta_divergence(X, W, H, beta_loss, square_root=True)
            if verbose:
                iter_time = time.time()
                print('Epoch %02d reached after %.3f seconds, error: %f' % (n_iter, iter_time - start_time, error))
            if (previous_error - error) / error_at_init < tol:
                break
            previous_error = error
    if verbose and (tol == 0 or n_iter % 10 != 0):
        end_time = time.time()
        print('Epoch %02d reached after %.3f seconds.' % (n_iter, end_time - start_time))
    return (W, H, n_iter)

@validate_params({'X': ['array-like', 'sparse matrix'], 'W': ['array-like', None], 'H': ['array-like', None], 'update_H': ['boolean']}, prefer_skip_nested_validation=False)
def non_negative_factorization(X, W=None, H=None, n_components='auto', *, init=None, update_H=True, solver='cd', beta_loss='frobenius', tol=0.0001, max_iter=200, alpha_W=0.0, alpha_H='same', l1_ratio=0.0, random_state=None, verbose=0, shuffle=False):
    est = NMF(n_components=n_components, init=init, solver=solver, beta_loss=beta_loss, tol=tol, max_iter=max_iter, random_state=random_state, alpha_W=alpha_W, alpha_H=alpha_H, l1_ratio=l1_ratio, verbose=verbose, shuffle=shuffle)
    est._validate_params()
    X = check_array(X, accept_sparse=('csr', 'csc'), dtype=[np.float64, np.float32])
    with config_context(assume_finite=True):
        W, H, n_iter = est._fit_transform(X, W=W, H=H, update_H=update_H)
    return (W, H, n_iter)

def _check_w_h(self, X, W, H, update_H):
    n_samples, n_features = X.shape
    if self.init == 'custom' and update_H:
        _check_init(H, (self._n_components, n_features), 'NMF (input H)')
        _check_init(W, (n_samples, self._n_components), 'NMF (input W)')
        if self._n_components == 'auto':
            self._n_components = H.shape[0]
        if H.dtype != X.dtype or W.dtype != X.dtype:
            raise TypeError('H and W should have the same dtype as X. Got H.dtype = {} and W.dtype = {}.'.format(H.dtype, W.dtype))
    elif not update_H:
        if W is not None:
            warnings.warn('When update_H=False, the provided initial W is not used.', RuntimeWarning)
        _check_init(H, (self._n_components, n_features), 'NMF (input H)')
        if self._n_components == 'auto':
            self._n_components = H.shape[0]
        if H.dtype != X.dtype:
            raise TypeError('H should have the same dtype as X. Got H.dtype = {}.'.format(H.dtype))
        if self.solver == 'mu':
            avg = np.sqrt(X.mean() / self._n_components)
            W = np.full((n_samples, self._n_components), avg, dtype=X.dtype)
        else:
            W = np.zeros((n_samples, self._n_components), dtype=X.dtype)
    else:
        if W is not None or H is not None:
            warnings.warn("When init!='custom', provided W or H are ignored. Set  init='custom' to use them as initialization.", RuntimeWarning)
        if self._n_components == 'auto':
            self._n_components = X.shape[1]
        W, H = _initialize_nmf(X, self._n_components, init=self.init, random_state=self.random_state)
    return (W, H)

def fit(self, X, y=None, **params):
    self.fit_transform(X, **params)
    return self

def inverse_transform(self, X):
    check_is_fitted(self)
    return X @ self.components_

@property
def _n_features_out(self):
    return self.components_.shape[0]

def _fit_transform(self, X, y=None, W=None, H=None, update_H=True):
    self._check_params(X)
    if X.min() == 0 and self._beta_loss <= 0:
        raise ValueError('When beta_loss <= 0 and X contains zeros, the solver may diverge. Please add small values to X, or use a positive beta_loss.')
    W, H = self._check_w_h(X, W, H, update_H)
    l1_reg_W, l1_reg_H, l2_reg_W, l2_reg_H = self._compute_regularization(X)
    if self.solver == 'cd':
        W, H, n_iter = _fit_coordinate_descent(X, W, H, self.tol, self.max_iter, l1_reg_W, l1_reg_H, l2_reg_W, l2_reg_H, update_H=update_H, verbose=self.verbose, shuffle=self.shuffle, random_state=self.random_state)
    elif self.solver == 'mu':
        W, H, n_iter, *_ = _fit_multiplicative_update(X, W, H, self._beta_loss, self.max_iter, self.tol, l1_reg_W, l1_reg_H, l2_reg_W, l2_reg_H, update_H, self.verbose)
    else:
        raise ValueError("Invalid solver parameter '%s'." % self.solver)
    if n_iter == self.max_iter and self.tol > 0:
        warnings.warn('Maximum number of iterations %d reached. Increase it to improve convergence.' % self.max_iter, ConvergenceWarning)
    return (W, H, n_iter)

def _minibatch_step(self, X, W, H, update_H):
    batch_size = X.shape[0]
    l1_reg_W, l1_reg_H, l2_reg_W, l2_reg_H = self._compute_regularization(X)
    if self.fresh_restarts or W is None:
        W = self._solve_W(X, H, self.fresh_restarts_max_iter)
    else:
        W, *_ = _multiplicative_update_w(X, W, H, self._beta_loss, l1_reg_W, l2_reg_W, self._gamma)
    if self._beta_loss < 1:
        W[W < np.finfo(np.float64).eps] = 0.0
    batch_cost = (_beta_divergence(X, W, H, self._beta_loss) + l1_reg_W * W.sum() + l1_reg_H * H.sum() + l2_reg_W * (W ** 2).sum() + l2_reg_H * (H ** 2).sum()) / batch_size
    if update_H:
        H[:] = _multiplicative_update_h(X, W, H, beta_loss=self._beta_loss, l1_reg_H=l1_reg_H, l2_reg_H=l2_reg_H, gamma=self._gamma, A=self._components_numerator, B=self._components_denominator, rho=self._rho)
        if self._beta_loss <= 1:
            H[H < np.finfo(np.float64).eps] = 0.0
    return batch_cost

def _minibatch_convergence(self, X, batch_cost, H, H_buffer, n_samples, step, n_steps):
    batch_size = X.shape[0]
    step = step + 1
    if step == 1:
        if self.verbose:
            print(f'Minibatch step {step}/{n_steps}: mean batch cost: {batch_cost}')
        return False
    if self._ewa_cost is None:
        self._ewa_cost = batch_cost
    else:
        alpha = batch_size / (n_samples + 1)
        alpha = min(alpha, 1)
        self._ewa_cost = self._ewa_cost * (1 - alpha) + batch_cost * alpha
    if self.verbose:
        print(f'Minibatch step {step}/{n_steps}: mean batch cost: {batch_cost}, ewa cost: {self._ewa_cost}')
    H_diff = linalg.norm(H - H_buffer) / linalg.norm(H)
    if self.tol > 0 and H_diff <= self.tol:
        if self.verbose:
            print(f'Converged (small H change) at step {step}/{n_steps}')
        return True
    if self._ewa_cost_min is None or self._ewa_cost < self._ewa_cost_min:
        self._no_improvement = 0
        self._ewa_cost_min = self._ewa_cost
    else:
        self._no_improvement += 1
    if self.max_no_improvement is not None and self._no_improvement >= self.max_no_improvement:
        if self.verbose:
            print(f'Converged (lack of improvement in objective function) at step {step}/{n_steps}')
        return True
    return False

def _infer_dimension(spectrum, n_samples):
    xp, _ = get_namespace(spectrum)
    ll = xp.empty_like(spectrum)
    ll[0] = -xp.inf
    for rank in range(1, spectrum.shape[0]):
        ll[rank] = _assess_dimension(spectrum, rank, n_samples)
    return xp.argmax(ll)

@_fit_context(prefer_skip_nested_validation=True)
def fit(self, X, y=None):
    self._fit(X)
    return self

@_fit_context(prefer_skip_nested_validation=True)
def fit_transform(self, X, y=None):
    U, S, _, X, x_is_centered, xp = self._fit(X)
    if U is not None:
        U = U[:, :self.n_components_]
        if self.whiten:
            U *= sqrt(X.shape[0] - 1)
        else:
            U *= S[:self.n_components_]
        return U
    else:
        return self._transform(X, xp, x_is_centered=x_is_centered)

def _fit(self, X):
    xp, is_array_api_compliant = get_namespace(X)
    if issparse(X) and self.svd_solver not in ['auto', 'arpack', 'covariance_eigh']:
        raise TypeError(f'PCA only support sparse inputs with the "arpack" and "covariance_eigh" solvers, while "{self.svd_solver}" was passed. See TruncatedSVD for a possible alternative.')
    if self.svd_solver == 'arpack' and is_array_api_compliant:
        raise ValueError("PCA with svd_solver='arpack' is not supported for Array API inputs.")
    X = validate_data(self, X, dtype=[xp.float64, xp.float32], force_writeable=True, accept_sparse=('csr', 'csc'), ensure_2d=True, copy=False)
    self._fit_svd_solver = self.svd_solver
    if self._fit_svd_solver == 'auto' and issparse(X):
        self._fit_svd_solver = 'arpack'
    if self.n_components is None:
        if self._fit_svd_solver != 'arpack':
            n_components = min(X.shape)
        else:
            n_components = min(X.shape) - 1
    else:
        n_components = self.n_components
    if self._fit_svd_solver == 'auto':
        if X.shape[1] <= 1000 and X.shape[0] >= 10 * X.shape[1]:
            self._fit_svd_solver = 'covariance_eigh'
        elif max(X.shape) <= 500 or n_components == 'mle':
            self._fit_svd_solver = 'full'
        elif 1 <= n_components < 0.8 * min(X.shape):
            self._fit_svd_solver = 'randomized'
        else:
            self._fit_svd_solver = 'full'
    if self._fit_svd_solver in ('full', 'covariance_eigh'):
        return self._fit_full(X, n_components, xp, is_array_api_compliant)
    elif self._fit_svd_solver in ['arpack', 'randomized']:
        return self._fit_truncated(X, n_components, xp)

def score(self, X, y=None):
    xp, _ = get_namespace(X)
    return float(xp.mean(self.score_samples(X)))

@_fit_context(prefer_skip_nested_validation=True)
def fit(self, X, y=None):
    random_state = check_random_state(self.random_state)
    X = validate_data(self, X)
    self.mean_ = X.mean(axis=0)
    X = X - self.mean_
    if self.n_components is None:
        n_components = X.shape[1]
    else:
        n_components = self.n_components
    return self._fit(X, n_components, random_state)

@property
def _n_features_out(self):
    return self.components_.shape[0]

def fit(self, X, y=None):
    self.fit_transform(X)
    return self

@_fit_context(prefer_skip_nested_validation=True)
def fit_transform(self, X, y=None):
    X = validate_data(self, X, accept_sparse=['csr', 'csc'], ensure_min_features=2)
    random_state = check_random_state(self.random_state)
    if self.algorithm == 'arpack':
        v0 = _init_arpack_v0(min(X.shape), random_state)
        U, Sigma, VT = svds(X, k=self.n_components, tol=self.tol, v0=v0)
        Sigma = Sigma[::-1]
        U, VT = svd_flip(U[:, ::-1], VT[::-1], u_based_decision=False)
    elif self.algorithm == 'randomized':
        if self.n_components > X.shape[1]:
            raise ValueError(f'n_components({self.n_components}) must be <= n_features({X.shape[1]}).')
        U, Sigma, VT = _randomized_svd(X, self.n_components, n_iter=self.n_iter, n_oversamples=self.n_oversamples, power_iteration_normalizer=self.power_iteration_normalizer, random_state=random_state, flip_sign=False)
        U, VT = svd_flip(U, VT, u_based_decision=False)
    self.components_ = VT
    if self.algorithm == 'randomized' or (self.algorithm == 'arpack' and self.tol > 0):
        X_transformed = safe_sparse_dot(X, self.components_.T)
    else:
        X_transformed = U * Sigma
    self.explained_variance_ = exp_var = np.var(X_transformed, axis=0)
    if sp.issparse(X):
        _, full_var = mean_variance_axis(X, axis=0)
        full_var = full_var.sum()
    else:
        full_var = np.var(X, axis=0).sum()
    self.explained_variance_ratio_ = exp_var / full_var
    self.singular_values_ = Sigma
    return X_transformed

def transform(self, X):
    check_is_fitted(self)
    X = validate_data(self, X, accept_sparse=['csr', 'csc'], reset=False)
    return safe_sparse_dot(X, self.components_.T)

def inverse_transform(self, X):
    X = check_array(X)
    return np.dot(X, self.components_)

@property
def _n_features_out(self):
    return self.components_.shape[0]

def _generate_indices(random_state, bootstrap, n_population, n_samples):
    if bootstrap:
        indices = random_state.randint(0, n_population, n_samples)
    else:
        indices = sample_without_replacement(n_population, n_samples, random_state=random_state)
    return indices

def _generate_bagging_indices(random_state, bootstrap_features, bootstrap_samples, n_features, n_samples, max_features, max_samples, sample_weight):
    random_state = check_random_state(random_state)
    feature_indices = _generate_indices(random_state, bootstrap_features, n_features, max_features)
    if sample_weight is None:
        sample_indices = _generate_indices(random_state, bootstrap_samples, n_samples, max_samples)
    else:
        normalized_sample_weight = sample_weight / np.sum(sample_weight)
        sample_indices = random_state.choice(n_samples, max_samples, replace=bootstrap_samples, p=normalized_sample_weight)
    return (feature_indices, sample_indices)

def _parallel_predict_proba(estimators, estimators_features, X, n_classes, predict_params=None, predict_proba_params=None):
    n_samples = X.shape[0]
    proba = np.zeros((n_samples, n_classes))
    for estimator, features in zip(estimators, estimators_features):
        if hasattr(estimator, 'predict_proba'):
            proba_estimator = estimator.predict_proba(X[:, features], **predict_proba_params or {})
            if n_classes == len(estimator.classes_):
                proba += proba_estimator
            else:
                proba[:, estimator.classes_] += proba_estimator[:, range(len(estimator.classes_))]
        else:
            predictions = estimator.predict(X[:, features], **predict_params or {})
            for i in range(n_samples):
                proba[i, predictions[i]] += 1
    return proba

@_fit_context(prefer_skip_nested_validation=False)
def fit(self, X, y, sample_weight=None, **fit_params):
    _raise_for_params(fit_params, self, 'fit')
    X, y = validate_data(self, X, y, accept_sparse=['csr', 'csc'], dtype=None, ensure_all_finite=False, multi_output=True)
    if sample_weight is not None:
        sample_weight = _check_sample_weight(sample_weight, X, dtype=None)
        if not self.bootstrap:
            warn(f'When fitting {self.__class__.__name__} with sample_weight it is recommended to use bootstrap=True, got {self.bootstrap}.')
    return self._fit(X, y, max_samples=self.max_samples, sample_weight=sample_weight, **fit_params)

def _fit(self, X, y, max_samples=None, max_depth=None, check_input=True, sample_weight=None, **fit_params):
    random_state = check_random_state(self.random_state)
    n_samples = X.shape[0]
    self._n_samples = n_samples
    y = self._validate_y(y)
    self._validate_estimator(self._get_estimator())
    if _routing_enabled():
        routed_params = process_routing(self, 'fit', **fit_params)
    else:
        routed_params = _manual_routing({'estimator': {'fit': fit_params}})
    if max_depth is not None:
        self.estimator_.max_depth = max_depth
    if max_samples is None:
        max_samples = self.max_samples
    max_samples = _get_n_samples_bootstrap(X.shape[0], max_samples, sample_weight)
    if not self.bootstrap and max_samples > X.shape[0]:
        raise ValueError(f'Effective max_samples={max_samples} must be <= n_samples={X.shape[0]} to be able to sample without replacement.')
    self._max_samples = max_samples
    if isinstance(self.max_features, numbers.Integral):
        max_features = self.max_features
    elif isinstance(self.max_features, float):
        max_features = int(self.max_features * self.n_features_in_)
    if max_features > self.n_features_in_:
        raise ValueError('max_features must be <= n_features')
    max_features = max(1, int(max_features))
    self._max_features = max_features
    self._sample_weight = sample_weight
    if not self.bootstrap and self.oob_score:
        raise ValueError('Out of bag estimation only available if bootstrap=True')
    if self.warm_start and self.oob_score:
        raise ValueError('Out of bag estimate only available if warm_start=False')
    if hasattr(self, 'oob_score_') and self.warm_start:
        del self.oob_score_
    if not self.warm_start or not hasattr(self, 'estimators_'):
        self.estimators_ = []
        self.estimators_features_ = []
    n_more_estimators = self.n_estimators - len(self.estimators_)
    if n_more_estimators < 0:
        raise ValueError('n_estimators=%d must be larger or equal to len(estimators_)=%d when warm_start==True' % (self.n_estimators, len(self.estimators_)))
    elif n_more_estimators == 0:
        warn('Warm-start fitting without increasing n_estimators does not fit new trees.')
        return self
    n_jobs, n_estimators, starts = _partition_estimators(n_more_estimators, self.n_jobs)
    total_n_estimators = sum(n_estimators)
    if self.warm_start and len(self.estimators_) > 0:
        random_state.randint(MAX_INT, size=len(self.estimators_))
    seeds = random_state.randint(MAX_INT, size=n_more_estimators)
    self._seeds = seeds
    all_results = Parallel(n_jobs=n_jobs, verbose=self.verbose, **self._parallel_args())((delayed(_parallel_build_estimators)(n_estimators[i], self, X, y, sample_weight, seeds[starts[i]:starts[i + 1]], total_n_estimators, verbose=self.verbose, check_input=check_input, fit_params=routed_params.estimator.fit) for i in range(n_jobs)))
    self.estimators_ += list(itertools.chain.from_iterable((t[0] for t in all_results)))
    self.estimators_features_ += list(itertools.chain.from_iterable((t[1] for t in all_results)))
    if self.oob_score:
        self._set_oob_score(X, y)
    return self

@abstractmethod
def _set_oob_score(self, X, y):
    pass

@property
def estimators_samples_(self):
    return [sample_indices for _, sample_indices in self._get_estimators_indices()]

def get_metadata_routing(self):
    router = MetadataRouter(owner=self)
    method_mapping = MethodMapping()
    method_mapping.add(caller='fit', callee='fit').add(caller='decision_function', callee='decision_function')
    if hasattr(self._get_estimator(), 'predict_proba'):
        method_mapping.add(caller='predict', callee='predict_proba').add(caller='predict_proba', callee='predict_proba')
    else:
        method_mapping.add(caller='predict', callee='predict').add(caller='predict_proba', callee='predict')
    if hasattr(self._get_estimator(), 'predict_log_proba'):
        method_mapping.add(caller='predict_log_proba', callee='predict_log_proba')
    elif hasattr(self._get_estimator(), 'predict_proba'):
        method_mapping.add(caller='predict_log_proba', callee='predict_proba')
    else:
        method_mapping.add(caller='predict_log_proba', callee='predict')
    router.add(estimator=self._get_estimator(), method_mapping=method_mapping)
    return router

@abstractmethod
def _get_estimator(self):
    pass

def _get_estimator(self):
    if self.estimator is None:
        return DecisionTreeClassifier()
    return self.estimator

def predict(self, X, **params):
    _raise_for_params(params, self, 'predict')
    predicted_probabilitiy = self.predict_proba(X, **params)
    return self.classes_.take(np.argmax(predicted_probabilitiy, axis=1), axis=0)

def predict_log_proba(self, X, **params):
    _raise_for_params(params, self, 'predict_log_proba')
    check_is_fitted(self)
    if hasattr(self.estimator_, 'predict_log_proba'):
        X = validate_data(self, X, accept_sparse=['csr', 'csc'], dtype=None, ensure_all_finite=False, reset=False)
        if _routing_enabled():
            routed_params = process_routing(self, 'predict_log_proba', **params)
        else:
            routed_params = _manual_routing({'estimator': {}})
        n_jobs, _, starts = _partition_estimators(self.n_estimators, self.n_jobs)
        all_log_proba = Parallel(n_jobs=n_jobs, verbose=self.verbose)((delayed(_parallel_predict_log_proba)(self.estimators_[starts[i]:starts[i + 1]], self.estimators_features_[starts[i]:starts[i + 1]], X, self.n_classes_, params=routed_params.estimator.predict_log_proba) for i in range(n_jobs)))
        log_proba = all_log_proba[0]
        for j in range(1, len(all_log_proba)):
            log_proba = np.logaddexp(log_proba, all_log_proba[j])
        log_proba -= np.log(self.n_estimators)
    else:
        log_proba = np.log(self.predict_proba(X, **params))
    return log_proba

@available_if(_estimator_has('decision_function', delegates=('estimators_', 'estimator')))
def decision_function(self, X, **params):
    _raise_for_params(params, self, 'decision_function')
    check_is_fitted(self)
    X = validate_data(self, X, accept_sparse=['csr', 'csc'], dtype=None, ensure_all_finite=False, reset=False)
    if _routing_enabled():
        routed_params = process_routing(self, 'decision_function', **params)
    else:
        routed_params = _manual_routing({'estimator': {}})
    n_jobs, _, starts = _partition_estimators(self.n_estimators, self.n_jobs)
    all_decisions = Parallel(n_jobs=n_jobs, verbose=self.verbose)((delayed(_parallel_decision_function)(self.estimators_[starts[i]:starts[i + 1]], self.estimators_features_[starts[i]:starts[i + 1]], X, params=routed_params.estimator.decision_function) for i in range(n_jobs)))
    decisions = sum(all_decisions) / self.n_estimators
    return decisions

def _get_estimator(self):
    if self.estimator is None:
        return DecisionTreeRegressor()
    return self.estimator

def _fit_single_estimator(estimator, X, y, fit_params, message_clsname=None, message=None):
    if not _routing_enabled() and 'sample_weight' in fit_params:
        try:
            with _print_elapsed_time(message_clsname, message):
                estimator.fit(X, y, sample_weight=fit_params['sample_weight'])
        except TypeError as exc:
            if "unexpected keyword argument 'sample_weight'" in str(exc):
                raise TypeError('Underlying estimator {} does not support sample weights.'.format(estimator.__class__.__name__)) from exc
            raise
    else:
        with _print_elapsed_time(message_clsname, message):
            estimator.fit(X, y, **fit_params)
    return estimator

def _set_random_states(estimator, random_state=None):
    random_state = check_random_state(random_state)
    to_set = {}
    for key in sorted(estimator.get_params(deep=True)):
        if key == 'random_state' or key.endswith('__random_state'):
            to_set[key] = random_state.randint(np.iinfo(np.int32).max)
    if to_set:
        estimator.set_params(**to_set)

def _partition_estimators(n_estimators, n_jobs):
    n_jobs = min(effective_n_jobs(n_jobs), n_estimators)
    n_estimators_per_job = np.full(n_jobs, n_estimators // n_jobs, dtype=int)
    n_estimators_per_job[:n_estimators % n_jobs] += 1
    starts = np.cumsum(n_estimators_per_job)
    return (n_jobs, n_estimators_per_job.tolist(), [0] + starts.tolist())

def _validate_estimator(self, default=None):
    if self.estimator is not None:
        self.estimator_ = self.estimator
    else:
        self.estimator_ = default

def _make_estimator(self, append=True, random_state=None):
    estimator = clone(self.estimator_)
    estimator.set_params(**{p: getattr(self, p) for p in self.estimator_params})
    if random_state is not None:
        _set_random_states(estimator, random_state)
    if append:
        self.estimators_.append(estimator)
    return estimator

@property
def named_estimators(self):
    return Bunch(**dict(self.estimators))

def set_params(self, **params):
    super()._set_params('estimators', **params)
    return self

def _get_n_samples_bootstrap(n_samples, max_samples, sample_weight):
    if max_samples is None:
        return n_samples
    elif isinstance(max_samples, Integral):
        return max_samples
    if sample_weight is None:
        weighted_n_samples = n_samples
        weighted_n_samples_msg = f'the number of samples is {weighted_n_samples} '
    else:
        weighted_n_samples = sample_weight.sum()
        weighted_n_samples_msg = f'the total sum of sample weights is {weighted_n_samples} '
    n_samples_bootstrap = max(int(max_samples * weighted_n_samples), 1)
    if n_samples_bootstrap < max(10, n_samples ** (1 / 3)):
        warn(f'Using the fractional value max_samples={max_samples!r} when {weighted_n_samples_msg}results in a low number ({n_samples_bootstrap}) of bootstrap samples. We recommend passing `max_samples` as an integer instead.')
    return n_samples_bootstrap

def _generate_sample_indices(random_state, n_samples, n_samples_bootstrap, sample_weight):
    random_instance = check_random_state(random_state)
    if sample_weight is None:
        sample_indices = random_instance.randint(0, n_samples, n_samples_bootstrap)
    else:
        normalized_sample_weight = sample_weight / np.sum(sample_weight)
        sample_indices = random_instance.choice(n_samples, n_samples_bootstrap, replace=True, p=normalized_sample_weight)
    sample_indices = sample_indices.astype(np.int32)
    return sample_indices

def _parallel_build_trees(tree, bootstrap, X, y, sample_weight, tree_idx, n_trees, verbose=0, class_weight=None, n_samples_bootstrap=None, missing_values_in_feature_mask=None):
    if verbose > 1:
        print('building tree %d of %d' % (tree_idx + 1, n_trees))
    if bootstrap:
        n_samples = X.shape[0]
        indices = _generate_sample_indices(tree.random_state, n_samples, n_samples_bootstrap, sample_weight)
        sample_weight_tree = np.bincount(indices, minlength=n_samples)
        if class_weight == 'balanced_subsample':
            expanded_class_weight = compute_sample_weight('balanced', y, indices=indices)
            sample_weight_tree = sample_weight_tree * expanded_class_weight
        tree._fit(X, y, sample_weight=sample_weight_tree, check_input=False, missing_values_in_feature_mask=missing_values_in_feature_mask)
    else:
        tree._fit(X, y, sample_weight=sample_weight, check_input=False, missing_values_in_feature_mask=missing_values_in_feature_mask)
    return tree

def _accumulate_prediction(predict, X, out, lock):
    prediction = predict(X, check_input=False)
    with lock:
        if len(out) == 1:
            out[0] += prediction
        else:
            for i in range(len(out)):
                out[i] += prediction[i]

@_fit_context(prefer_skip_nested_validation=True)
def fit(self, X, y, sample_weight=None):
    if issparse(y):
        raise ValueError('sparse multilabel-indicator for y is not supported.')
    X, y = validate_data(self, X, y, multi_output=True, accept_sparse='csc', dtype=np.float32, ensure_all_finite=False)
    estimator = type(self.estimator)(criterion=self.criterion)
    missing_values_in_feature_mask = estimator._compute_missing_values_in_feature_mask(X, estimator_name=self.__class__.__name__)
    if sample_weight is not None:
        sample_weight = _check_sample_weight(sample_weight, X)
    if issparse(X):
        X.sort_indices()
    y = np.atleast_1d(y)
    if y.ndim == 2 and y.shape[1] == 1:
        warn('A column-vector y was passed when a 1d array was expected. Please change the shape of y to (n_samples,), for example using ravel().', DataConversionWarning, stacklevel=2)
    if y.ndim == 1:
        y = np.reshape(y, (-1, 1))
    if self.criterion == 'poisson':
        if np.any(y < 0):
            raise ValueError('Some value(s) of y are negative which is not allowed for Poisson regression.')
        if np.sum(y) <= 0:
            raise ValueError('Sum of y is not strictly positive which is necessary for Poisson regression.')
    self._n_samples, self.n_outputs_ = y.shape
    y, expanded_class_weight = self._validate_y_class_weight(y, sample_weight)
    if getattr(y, 'dtype', None) != np.float64 or not y.flags.contiguous:
        y = np.ascontiguousarray(y, dtype=np.float64)
    if sample_weight is None:
        _sample_weight = expanded_class_weight
    elif expanded_class_weight is None:
        _sample_weight = sample_weight
    else:
        _sample_weight = sample_weight * expanded_class_weight
    self._sample_weight = _sample_weight
    if not self.bootstrap and self.max_samples is not None:
        raise ValueError('`max_sample` cannot be set if `bootstrap=False`. Either switch to `bootstrap=True` or set `max_sample=None`.')
    elif self.bootstrap:
        n_samples_bootstrap = _get_n_samples_bootstrap(X.shape[0], self.max_samples, _sample_weight)
    else:
        n_samples_bootstrap = None
    self._n_samples_bootstrap = n_samples_bootstrap
    self._validate_estimator()
    if not self.bootstrap and self.oob_score:
        raise ValueError('Out of bag estimation only available if bootstrap=True')
    random_state = check_random_state(self.random_state)
    if not self.warm_start or not hasattr(self, 'estimators_'):
        self.estimators_ = []
    n_more_estimators = self.n_estimators - len(self.estimators_)
    if n_more_estimators < 0:
        raise ValueError('n_estimators=%d must be larger or equal to len(estimators_)=%d when warm_start==True' % (self.n_estimators, len(self.estimators_)))
    elif n_more_estimators == 0:
        warn('Warm-start fitting without increasing n_estimators does not fit new trees.')
    else:
        if self.warm_start and len(self.estimators_) > 0:
            random_state.randint(MAX_INT, size=len(self.estimators_))
        trees = [self._make_estimator(append=False, random_state=random_state) for i in range(n_more_estimators)]
        trees = Parallel(n_jobs=self.n_jobs, verbose=self.verbose, prefer='threads')((delayed(_parallel_build_trees)(t, self.bootstrap, X, y, _sample_weight, i, len(trees), verbose=self.verbose, class_weight=self.class_weight, n_samples_bootstrap=n_samples_bootstrap, missing_values_in_feature_mask=missing_values_in_feature_mask) for i, t in enumerate(trees)))
        self.estimators_.extend(trees)
    if self.oob_score and (n_more_estimators > 0 or not hasattr(self, 'oob_score_')):
        y_type = type_of_target(y)
        if y_type == 'unknown' or (is_classifier(self) and y_type == 'multiclass-multioutput'):
            raise ValueError(f'The type of target cannot be used to compute OOB estimates. Got {y_type} while only the following are supported: continuous, continuous-multioutput, binary, multiclass, multilabel-indicator.')
        if callable(self.oob_score):
            self._set_oob_score_and_attributes(X, y, scoring_function=self.oob_score)
        else:
            self._set_oob_score_and_attributes(X, y)
    if hasattr(self, 'classes_') and self.n_outputs_ == 1:
        self.n_classes_ = self.n_classes_[0]
        self.classes_ = self.classes_[0]
    return self

@abstractmethod
def _set_oob_score_and_attributes(self, X, y, scoring_function=None):
    pass

def _compute_oob_predictions(self, X, y):
    if issparse(X):
        X = X.tocsr()
    n_samples = y.shape[0]
    n_outputs = self.n_outputs_
    if is_classifier(self) and hasattr(self, 'n_classes_'):
        oob_pred_shape = (n_samples, self.n_classes_[0], n_outputs)
    else:
        oob_pred_shape = (n_samples, 1, n_outputs)
    oob_pred = np.zeros(shape=oob_pred_shape, dtype=np.float64)
    n_oob_pred = np.zeros((n_samples, n_outputs), dtype=np.int64)
    for estimator in self.estimators_:
        unsampled_indices = _generate_unsampled_indices(estimator.random_state, n_samples, self._n_samples_bootstrap, self._sample_weight)
        y_pred = self._get_oob_predictions(estimator, X[unsampled_indices, :])
        oob_pred[unsampled_indices, ...] += y_pred
        n_oob_pred[unsampled_indices, :] += 1
    for k in range(n_outputs):
        if (n_oob_pred == 0).any():
            warn('Some inputs do not have OOB scores. This probably means too few trees were used to compute any reliable OOB estimates.', UserWarning)
            n_oob_pred[n_oob_pred == 0] = 1
        oob_pred[..., k] /= n_oob_pred[..., [k]]
    return oob_pred

def _validate_X_predict(self, X):
    check_is_fitted(self)
    if self.estimators_[0]._support_missing_values(X):
        ensure_all_finite = 'allow-nan'
    else:
        ensure_all_finite = True
    X = validate_data(self, X, dtype=np.float32, accept_sparse='csr', reset=False, ensure_all_finite=ensure_all_finite)
    if issparse(X) and (X.indices.dtype != np.intc or X.indptr.dtype != np.intc):
        raise ValueError('No support for np.int64 index based sparse matrices')
    return X

@property
def feature_importances_(self):
    check_is_fitted(self)
    all_importances = Parallel(n_jobs=self.n_jobs, prefer='threads')((delayed(getattr)(tree, 'feature_importances_') for tree in self.estimators_ if tree.tree_.node_count > 1))
    if not all_importances:
        return np.zeros(self.n_features_in_, dtype=np.float64)
    all_importances = np.mean(all_importances, axis=0, dtype=np.float64)
    return all_importances / np.sum(all_importances)

@property
def estimators_samples_(self):
    return [sample_indices for sample_indices in self._get_estimators_indices()]

@staticmethod
def _get_oob_predictions(tree, X):
    y_pred = tree.predict_proba(X, check_input=False)
    y_pred = np.asarray(y_pred)
    if y_pred.ndim == 2:
        y_pred = y_pred[..., np.newaxis]
    else:
        y_pred = np.rollaxis(y_pred, axis=0, start=3)
    return y_pred

def _set_oob_score_and_attributes(self, X, y, scoring_function=None):
    self.oob_decision_function_ = super()._compute_oob_predictions(X, y)
    if self.oob_decision_function_.shape[-1] == 1:
        self.oob_decision_function_ = self.oob_decision_function_.squeeze(axis=-1)
    if scoring_function is None:
        scoring_function = accuracy_score
    self.oob_score_ = scoring_function(y, np.argmax(self.oob_decision_function_, axis=1))

def predict(self, X):
    proba = self.predict_proba(X)
    if self.n_outputs_ == 1:
        return self.classes_.take(np.argmax(proba, axis=1), axis=0)
    else:
        n_samples = proba[0].shape[0]
        class_type = self.classes_[0].dtype
        predictions = np.empty((n_samples, self.n_outputs_), dtype=class_type)
        for k in range(self.n_outputs_):
            predictions[:, k] = self.classes_[k].take(np.argmax(proba[k], axis=1), axis=0)
        return predictions

def predict_proba(self, X):
    check_is_fitted(self)
    X = self._validate_X_predict(X)
    n_jobs, _, _ = _partition_estimators(self.n_estimators, self.n_jobs)
    all_proba = [np.zeros((X.shape[0], j), dtype=np.float64) for j in np.atleast_1d(self.n_classes_)]
    lock = threading.Lock()
    Parallel(n_jobs=n_jobs, verbose=self.verbose, require='sharedmem')((delayed(_accumulate_prediction)(e.predict_proba, X, all_proba, lock) for e in self.estimators_))
    for proba in all_proba:
        proba /= len(self.estimators_)
    if len(all_proba) == 1:
        return all_proba[0]
    else:
        return all_proba

def predict_log_proba(self, X):
    proba = self.predict_proba(X)
    if self.n_outputs_ == 1:
        return np.log(proba)
    else:
        for k in range(self.n_outputs_):
            proba[k] = np.log(proba[k])
        return proba

@staticmethod
def _get_oob_predictions(tree, X):
    y_pred = tree.predict(X, check_input=False)
    if y_pred.ndim == 1:
        y_pred = y_pred[:, np.newaxis, np.newaxis]
    else:
        y_pred = y_pred[:, np.newaxis, :]
    return y_pred

def _set_oob_score_and_attributes(self, X, y, scoring_function=None):
    self.oob_prediction_ = super()._compute_oob_predictions(X, y).squeeze(axis=1)
    if self.oob_prediction_.shape[-1] == 1:
        self.oob_prediction_ = self.oob_prediction_.squeeze(axis=-1)
    if scoring_function is None:
        scoring_function = r2_score
    self.oob_score_ = scoring_function(y, self.oob_prediction_)

def fit(self, X, y=None, sample_weight=None):
    self.fit_transform(X, y, sample_weight=sample_weight)
    return self

def get_feature_names_out(self, input_features=None):
    check_is_fitted(self, '_n_features_out')
    _check_feature_names_in(self, input_features=input_features, generate_names=False)
    feature_names = [f'randomtreesembedding_{tree}_{leaf}' for tree in range(self.n_estimators) for leaf in self.one_hot_encoder_.categories_[tree]]
    return np.asarray(feature_names, dtype=object)

def transform(self, X):
    check_is_fitted(self)
    return self.one_hot_encoder_.transform(self.apply(X))

def _init_raw_predictions(X, estimator, loss, use_predict_proba):
    if use_predict_proba:
        predictions = estimator.predict_proba(X)
        if not loss.is_multiclass:
            predictions = predictions[:, 1]
        eps = np.finfo(np.float64).eps
        predictions = np.clip(predictions, eps, 1 - eps, dtype=np.float64)
    else:
        predictions = estimator.predict(X).astype(np.float64)
    if predictions.ndim == 1:
        return loss.link.link(predictions).reshape(-1, 1)
    else:
        return loss.link.link(predictions)

def update(self, j, est):
    do_oob = est.subsample < 1
    i = j - self.begin_at_stage
    if (i + 1) % self.verbose_mod == 0:
        oob_impr = est.oob_improvement_[j] if do_oob else 0
        remaining_time = (est.n_estimators - (j + 1)) * (time() - self.start_time) / float(i + 1)
        if remaining_time > 60:
            remaining_time = '{0:.2f}m'.format(remaining_time / 60.0)
        else:
            remaining_time = '{0:.2f}s'.format(remaining_time)
        print(self.verbose_fmt.format(iter=j + 1, train_score=est.train_score_[j], oob_impr=oob_impr, remaining_time=remaining_time))
        if self.verbose == 1 and (i + 1) // (self.verbose_mod * 10) > 0:
            self.verbose_mod *= 10

@abstractmethod
def _encode_y(self, y=None, sample_weight=None):
    pass

@abstractmethod
def _get_loss(self, sample_weight):
    pass

def _fit_stage(self, i, X, y, raw_predictions, sample_weight, sample_mask, random_state, X_csc=None, X_csr=None):
    original_y = y
    if isinstance(self._loss, HuberLoss):
        set_huber_delta(loss=self._loss, y_true=y, raw_prediction=raw_predictions, sample_weight=sample_weight)
    neg_gradient = -self._loss.gradient(y_true=y, raw_prediction=raw_predictions, sample_weight=None)
    if neg_gradient.ndim == 1:
        neg_g_view = neg_gradient.reshape((-1, 1))
    else:
        neg_g_view = neg_gradient
    for k in range(self.n_trees_per_iteration_):
        if self._loss.is_multiclass:
            y = np.array(original_y == k, dtype=np.float64)
        tree = DecisionTreeRegressor(criterion='squared_error', splitter='best', max_depth=self.max_depth, min_samples_split=self.min_samples_split, min_samples_leaf=self.min_samples_leaf, min_weight_fraction_leaf=self.min_weight_fraction_leaf, min_impurity_decrease=self.min_impurity_decrease, max_features=self.max_features, max_leaf_nodes=self.max_leaf_nodes, random_state=random_state, ccp_alpha=self.ccp_alpha)
        if self.subsample < 1.0:
            sample_weight = sample_weight * sample_mask.astype(np.float64)
        X = X_csc if X_csc is not None else X
        tree.fit(X, neg_g_view[:, k], sample_weight=sample_weight, check_input=False)
        X_for_tree_update = X_csr if X_csr is not None else X
        _update_terminal_regions(self._loss, tree.tree_, X_for_tree_update, y, neg_g_view[:, k], raw_predictions, sample_weight, sample_mask, learning_rate=self.learning_rate, k=k)
        self.estimators_[i, k] = tree
    return raw_predictions

def _set_max_features(self):
    if isinstance(self.max_features, str):
        if self.max_features == 'auto':
            if is_classifier(self):
                max_features = max(1, int(np.sqrt(self.n_features_in_)))
            else:
                max_features = self.n_features_in_
        elif self.max_features == 'sqrt':
            max_features = max(1, int(np.sqrt(self.n_features_in_)))
        else:
            max_features = max(1, int(np.log2(self.n_features_in_)))
    elif self.max_features is None:
        max_features = self.n_features_in_
    elif isinstance(self.max_features, Integral):
        max_features = self.max_features
    else:
        max_features = max(1, int(self.max_features * self.n_features_in_))
    self.max_features_ = max_features

def _init_state(self):
    self.init_ = self.init
    if self.init_ is None:
        if is_classifier(self):
            self.init_ = DummyClassifier(strategy='prior')
        elif isinstance(self._loss, (AbsoluteError, HuberLoss)):
            self.init_ = DummyRegressor(strategy='quantile', quantile=0.5)
        elif isinstance(self._loss, PinballLoss):
            self.init_ = DummyRegressor(strategy='quantile', quantile=self.alpha)
        else:
            self.init_ = DummyRegressor(strategy='mean')
    self.estimators_ = np.empty((self.n_estimators, self.n_trees_per_iteration_), dtype=object)
    self.train_score_ = np.zeros((self.n_estimators,), dtype=np.float64)
    if self.subsample < 1.0:
        self.oob_improvement_ = np.zeros(self.n_estimators, dtype=np.float64)
        self.oob_scores_ = np.zeros(self.n_estimators, dtype=np.float64)
        self.oob_score_ = np.nan

def _clear_state(self):
    if hasattr(self, 'estimators_'):
        self.estimators_ = np.empty((0, 0), dtype=object)
    if hasattr(self, 'train_score_'):
        del self.train_score_
    if hasattr(self, 'oob_improvement_'):
        del self.oob_improvement_
    if hasattr(self, 'oob_scores_'):
        del self.oob_scores_
    if hasattr(self, 'oob_score_'):
        del self.oob_score_
    if hasattr(self, 'init_'):
        del self.init_
    if hasattr(self, '_rng'):
        del self._rng

def _resize_state(self):
    total_n_estimators = self.n_estimators
    if total_n_estimators < self.estimators_.shape[0]:
        raise ValueError('resize with smaller n_estimators %d < %d' % (total_n_estimators, self.estimators_[0]))
    self.estimators_ = np.resize(self.estimators_, (total_n_estimators, self.n_trees_per_iteration_))
    self.train_score_ = np.resize(self.train_score_, total_n_estimators)
    if self.subsample < 1 or hasattr(self, 'oob_improvement_'):
        if hasattr(self, 'oob_improvement_'):
            self.oob_improvement_ = np.resize(self.oob_improvement_, total_n_estimators)
            self.oob_scores_ = np.resize(self.oob_scores_, total_n_estimators)
            self.oob_score_ = np.nan
        else:
            self.oob_improvement_ = np.zeros((total_n_estimators,), dtype=np.float64)
            self.oob_scores_ = np.zeros((total_n_estimators,), dtype=np.float64)
            self.oob_score_ = np.nan

@_fit_context(prefer_skip_nested_validation=False)
def fit(self, X, y, sample_weight=None, monitor=None):
    if not self.warm_start:
        self._clear_state()
    if self.criterion != 'deprecated':
        warnings.warn('The parameter `criterion` is deprecated and will be removed in 1.11. It has no effect. Leave it to its default value to avoid this warning.', FutureWarning)
    X, y = validate_data(self, X, y, accept_sparse=['csr', 'csc', 'coo'], dtype=np.float32, multi_output=True)
    sample_weight_is_none = sample_weight is None
    sample_weight = _check_sample_weight(sample_weight, X)
    if sample_weight_is_none:
        y = self._encode_y(y=y, sample_weight=None)
    else:
        y = self._encode_y(y=y, sample_weight=sample_weight)
    y = column_or_1d(y, warn=True)
    self._set_max_features()
    self._loss = self._get_loss(sample_weight=sample_weight)
    if self.n_iter_no_change is not None:
        stratify = y if is_classifier(self) else None
        X_train, X_val, y_train, y_val, sample_weight_train, sample_weight_val = train_test_split(X, y, sample_weight, random_state=self.random_state, test_size=self.validation_fraction, stratify=stratify)
        if is_classifier(self):
            if self.n_classes_ != np.unique(y_train).shape[0]:
                raise ValueError('The training data after the early stopping split is missing some classes. Try using another random seed.')
    else:
        X_train, y_train, sample_weight_train = (X, y, sample_weight)
        X_val = y_val = sample_weight_val = None
    n_samples = X_train.shape[0]
    if not self._is_fitted():
        self._init_state()
        if self.init_ == 'zero':
            raw_predictions = np.zeros(shape=(n_samples, self.n_trees_per_iteration_), dtype=np.float64)
        else:
            if sample_weight_is_none:
                self.init_.fit(X_train, y_train)
            else:
                msg = 'The initial estimator {} does not support sample weights.'.format(self.init_.__class__.__name__)
                try:
                    self.init_.fit(X_train, y_train, sample_weight=sample_weight_train)
                except TypeError as e:
                    if "unexpected keyword argument 'sample_weight'" in str(e):
                        raise ValueError(msg) from e
                    else:
                        raise
                except ValueError as e:
                    if 'pass parameters to specific steps of your pipeline using the stepname__parameter' in str(e):
                        raise ValueError(msg) from e
                    else:
                        raise
            raw_predictions = _init_raw_predictions(X_train, self.init_, self._loss, is_classifier(self))
        begin_at_stage = 0
        self._rng = check_random_state(self.random_state)
    else:
        if self.n_estimators < self.estimators_.shape[0]:
            raise ValueError('n_estimators=%d must be larger or equal to estimators_.shape[0]=%d when warm_start==True' % (self.n_estimators, self.estimators_.shape[0]))
        begin_at_stage = self.estimators_.shape[0]
        X_train = check_array(X_train, dtype=np.float32, order='C', accept_sparse='csr', ensure_all_finite=False)
        raw_predictions = self._raw_predict(X_train)
        self._resize_state()
    n_stages = self._fit_stages(X_train, y_train, raw_predictions, sample_weight_train, self._rng, X_val, y_val, sample_weight_val, begin_at_stage, monitor)
    if n_stages != self.estimators_.shape[0]:
        self.estimators_ = self.estimators_[:n_stages]
        self.train_score_ = self.train_score_[:n_stages]
        if hasattr(self, 'oob_improvement_'):
            self.oob_improvement_ = self.oob_improvement_[:n_stages]
            self.oob_scores_ = self.oob_scores_[:n_stages]
            self.oob_score_ = self.oob_scores_[-1]
    self.n_estimators_ = n_stages
    return self

def _fit_stages(self, X, y, raw_predictions, sample_weight, random_state, X_val, y_val, sample_weight_val, begin_at_stage=0, monitor=None):
    n_samples = X.shape[0]
    do_oob = self.subsample < 1.0
    sample_mask = np.ones((n_samples,), dtype=bool)
    n_inbag = max(1, int(self.subsample * n_samples))
    if self.verbose:
        verbose_reporter = VerboseReporter(verbose=self.verbose)
        verbose_reporter.init(self, begin_at_stage)
    X_csc = csc_array(X) if issparse(X) else None
    X_csr = csr_array(X) if issparse(X) else None
    if self.n_iter_no_change is not None:
        loss_history = np.full(self.n_iter_no_change, np.inf)
        y_val_pred_iter = self._staged_raw_predict(X_val, check_input=False)
    if isinstance(self._loss, (HalfSquaredError, HalfBinomialLoss)):
        factor = 2
    else:
        factor = 1
    i = begin_at_stage
    for i in range(begin_at_stage, self.n_estimators):
        if do_oob:
            sample_mask = _random_sample_mask(n_samples, n_inbag, random_state)
            y_oob_masked = y[~sample_mask]
            sample_weight_oob_masked = sample_weight[~sample_mask]
            if i == 0:
                initial_loss = factor * self._loss(y_true=y_oob_masked, raw_prediction=raw_predictions[~sample_mask], sample_weight=sample_weight_oob_masked)
        raw_predictions = self._fit_stage(i, X, y, raw_predictions, sample_weight, sample_mask, random_state, X_csc=X_csc, X_csr=X_csr)
        if do_oob:
            self.train_score_[i] = factor * self._loss(y_true=y[sample_mask], raw_prediction=raw_predictions[sample_mask], sample_weight=sample_weight[sample_mask])
            self.oob_scores_[i] = factor * self._loss(y_true=y_oob_masked, raw_prediction=raw_predictions[~sample_mask], sample_weight=sample_weight_oob_masked)
            previous_loss = initial_loss if i == 0 else self.oob_scores_[i - 1]
            self.oob_improvement_[i] = previous_loss - self.oob_scores_[i]
            self.oob_score_ = self.oob_scores_[-1]
        else:
            self.train_score_[i] = factor * self._loss(y_true=y, raw_prediction=raw_predictions, sample_weight=sample_weight)
        if self.verbose > 0:
            verbose_reporter.update(i, self)
        if monitor is not None:
            early_stopping = monitor(i, self, locals())
            if early_stopping:
                break
        if self.n_iter_no_change is not None:
            validation_loss = factor * self._loss(y_val, next(y_val_pred_iter), sample_weight_val)
            if np.any(validation_loss + self.tol < loss_history):
                loss_history[i % len(loss_history)] = validation_loss
            else:
                break
    return i + 1

def _raw_predict_init(self, X):
    self._check_initialized()
    X = self.estimators_[0, 0]._validate_X_predict(X, check_input=True)
    if self.init_ == 'zero':
        raw_predictions = np.zeros(shape=(X.shape[0], self.n_trees_per_iteration_), dtype=np.float64)
    else:
        raw_predictions = _init_raw_predictions(X, self.init_, self._loss, is_classifier(self))
    return raw_predictions

def _staged_raw_predict(self, X, check_input=True):
    if check_input:
        X = validate_data(self, X, dtype=np.float32, order='C', accept_sparse='csr', reset=False)
    raw_predictions = self._raw_predict_init(X)
    for i in range(self.estimators_.shape[0]):
        predict_stage(self.estimators_, i, X, self.learning_rate, raw_predictions)
        yield raw_predictions.copy()

@property
def feature_importances_(self):
    self._check_initialized()
    relevant_trees = [tree for stage in self.estimators_ for tree in stage if tree.tree_.node_count > 1]
    if not relevant_trees:
        return np.zeros(shape=self.n_features_in_, dtype=np.float64)
    relevant_feature_importances = [tree.tree_.compute_feature_importances(normalize=False) for tree in relevant_trees]
    avg_feature_importances = np.mean(relevant_feature_importances, axis=0, dtype=np.float64)
    return avg_feature_importances / np.sum(avg_feature_importances)

def _compute_partial_dependence_recursion(self, grid, target_features):
    if self.init is not None:
        warnings.warn('Using recursion method with a non-constant init predictor will lead to incorrect partial dependence values. Got init=%s.' % self.init, UserWarning)
    grid = np.asarray(grid, dtype=np.float32, order='C')
    n_estimators, n_trees_per_stage = self.estimators_.shape
    averaged_predictions = np.zeros((n_trees_per_stage, grid.shape[0]), dtype=np.float64, order='C')
    target_features = np.asarray(target_features, dtype=np.intp, order='C')
    for stage in range(n_estimators):
        for k in range(n_trees_per_stage):
            tree = self.estimators_[stage, k].tree_
            tree.compute_partial_dependence(grid, target_features, averaged_predictions[k])
    averaged_predictions *= self.learning_rate
    return averaged_predictions

def apply(self, X):
    self._check_initialized()
    X = self.estimators_[0, 0]._validate_X_predict(X, check_input=True)
    n_estimators, n_classes = self.estimators_.shape
    leaves = np.zeros((X.shape[0], n_estimators, n_classes))
    for i in range(n_estimators):
        for j in range(n_classes):
            estimator = self.estimators_[i, j]
            leaves[:, i, j] = estimator.apply(X, check_input=False)
    return leaves

def decision_function(self, X):
    X = validate_data(self, X, dtype=np.float32, order='C', accept_sparse='csr', reset=False)
    raw_predictions = self._raw_predict(X)
    if raw_predictions.shape[1] == 1:
        return raw_predictions.ravel()
    return raw_predictions

def predict(self, X):
    raw_predictions = self.decision_function(X)
    if raw_predictions.ndim == 1:
        encoded_classes = (raw_predictions >= 0).astype(int)
    else:
        encoded_classes = np.argmax(raw_predictions, axis=1)
    return self.classes_[encoded_classes]

def staged_predict(self, X):
    if self.n_classes_ == 2:
        for raw_predictions in self._staged_raw_predict(X):
            encoded_classes = (raw_predictions.squeeze() >= 0).astype(int)
            yield self.classes_.take(encoded_classes, axis=0)
    else:
        for raw_predictions in self._staged_raw_predict(X):
            encoded_classes = np.argmax(raw_predictions, axis=1)
            yield self.classes_.take(encoded_classes, axis=0)

def predict_proba(self, X):
    raw_predictions = self.decision_function(X)
    return self._loss.predict_proba(raw_predictions)

def predict_log_proba(self, X):
    proba = self.predict_proba(X)
    return np.log(proba)

def staged_predict_proba(self, X):
    try:
        for raw_predictions in self._staged_raw_predict(X):
            yield self._loss.predict_proba(raw_predictions)
    except NotFittedError:
        raise
    except AttributeError as e:
        raise AttributeError('loss=%r does not support predict_proba' % self.loss) from e

def predict(self, X):
    X = validate_data(self, X, dtype=np.float32, order='C', accept_sparse='csr', reset=False)
    return self._raw_predict(X).ravel()

def staged_predict(self, X):
    for raw_predictions in self._staged_raw_predict(X):
        yield raw_predictions.ravel()

def _parallel_compute_tree_depths(tree, X, features, tree_decision_path_lengths, tree_avg_path_lengths, depths, lock):
    if features is None:
        X_subset = X
    else:
        X_subset = X[:, features]
    leaves_index = tree.apply(X_subset, check_input=False)
    with lock:
        depths += tree_decision_path_lengths[leaves_index] + tree_avg_path_lengths[leaves_index] - 1.0

@_fit_context(prefer_skip_nested_validation=True)
def fit(self, X, y=None, sample_weight=None):
    X = validate_data(self, X, accept_sparse=['csc'], dtype=np.float32, ensure_all_finite=False)
    if sample_weight is not None:
        sample_weight = _check_sample_weight(sample_weight, X, dtype=None)
    if issparse(X):
        X.sort_indices()
    rnd = check_random_state(self.random_state)
    y = rnd.uniform(size=X.shape[0])
    n_samples = X.shape[0]
    if isinstance(self.max_samples, str) and self.max_samples == 'auto':
        max_samples = min(256, n_samples)
    elif isinstance(self.max_samples, numbers.Integral):
        if self.max_samples > n_samples:
            warn('max_samples (%s) is greater than the total number of samples (%s). max_samples will be set to n_samples for estimation.' % (self.max_samples, n_samples))
            max_samples = n_samples
        else:
            max_samples = self.max_samples
    else:
        max_samples = int(self.max_samples * X.shape[0])
    self.max_samples_ = max_samples
    max_depth = int(np.ceil(np.log2(max(max_samples, 2))))
    super()._fit(X, y, max_samples=max_samples, max_depth=max_depth, sample_weight=sample_weight, check_input=False)
    self._average_path_length_per_tree, self._decision_path_lengths = zip(*[(_average_path_length(tree.tree_.n_node_samples), tree.tree_.compute_node_depths()) for tree in self.estimators_])
    if self.contamination == 'auto':
        self.offset_ = -0.5
        return self
    if issparse(X):
        X = X.tocsr()
    self.offset_ = np.percentile(self._score_samples(X), 100.0 * self.contamination)
    return self

def score_samples(self, X):
    X = validate_data(self, X, accept_sparse='csr', dtype=np.float32, reset=False, ensure_all_finite=False)
    return self._score_samples(X)

def _score_samples(self, X):
    check_is_fitted(self)
    return -self._compute_chunked_score_samples(X)

def _concatenate_predictions(self, X, predictions):
    X_meta = []
    for est_idx, preds in enumerate(predictions):
        if isinstance(preds, list):
            for pred in preds:
                X_meta.append(pred[:, 1:])
        elif preds.ndim == 1:
            X_meta.append(preds.reshape(-1, 1))
        elif self.stack_method_[est_idx] == 'predict_proba' and len(self.classes_) == 2:
            X_meta.append(preds[:, 1:])
        else:
            X_meta.append(preds)
    self._n_feature_outs = [pred.shape[1] for pred in X_meta]
    if self.passthrough:
        X_meta.append(X)
        if sparse.issparse(X):
            return sparse.hstack(X_meta, format=X.format)
    return np.hstack(X_meta)

@_fit_context(prefer_skip_nested_validation=False)
def fit(self, X, y, **fit_params):
    names, all_estimators = self._validate_estimators()
    self._validate_final_estimator()
    stack_method = [self.stack_method] * len(all_estimators)
    if _routing_enabled():
        routed_params = process_routing(self, 'fit', **fit_params)
    else:
        sw = {'sample_weight': fit_params['sample_weight']} if 'sample_weight' in fit_params else {}
        routed_params = _manual_routing({name: {'fit': sw} for name in names})
    if self.cv == 'prefit':
        self.estimators_ = []
        for estimator in all_estimators:
            if estimator != 'drop':
                check_is_fitted(estimator)
                self.estimators_.append(estimator)
    else:
        self.estimators_ = Parallel(n_jobs=self.n_jobs)((delayed(_fit_single_estimator)(clone(est), X, y, routed_params[name]['fit']) for name, est in zip(names, all_estimators) if est != 'drop'))
    self.named_estimators_ = Bunch()
    est_fitted_idx = 0
    for name_est, org_est in zip(names, all_estimators):
        if org_est != 'drop':
            current_estimator = self.estimators_[est_fitted_idx]
            self.named_estimators_[name_est] = current_estimator
            est_fitted_idx += 1
            if hasattr(current_estimator, 'feature_names_in_'):
                self.feature_names_in_ = current_estimator.feature_names_in_
        else:
            self.named_estimators_[name_est] = 'drop'
    self.stack_method_ = [self._method_name(name, est, meth) for name, est, meth in zip(names, all_estimators, stack_method)]
    if self.cv == 'prefit':
        predictions = [getattr(estimator, predict_method)(X) for estimator, predict_method in zip(all_estimators, self.stack_method_) if estimator != 'drop']
    else:
        cv = check_cv(self.cv, y=y, classifier=is_classifier(self))
        if hasattr(cv, 'random_state') and cv.random_state is None:
            cv.random_state = np.random.RandomState()
        predictions = Parallel(n_jobs=self.n_jobs)((delayed(cross_val_predict)(clone(est), X, y, cv=deepcopy(cv), method=meth, n_jobs=self.n_jobs, params=routed_params[name]['fit'], verbose=self.verbose) for name, est, meth in zip(names, all_estimators, self.stack_method_) if est != 'drop'))
    self.stack_method_ = [meth for meth, est in zip(self.stack_method_, all_estimators) if est != 'drop']
    X_meta = self._concatenate_predictions(X, predictions)
    _fit_single_estimator(self.final_estimator_, X_meta, y, fit_params=fit_params)
    return self

@property
def n_features_in_(self):
    try:
        check_is_fitted(self)
    except NotFittedError as nfe:
        raise AttributeError(f'{self.__class__.__name__} object has no attribute n_features_in_') from nfe
    return self.estimators_[0].n_features_in_

def _transform(self, X):
    check_is_fitted(self)
    predictions = [getattr(est, meth)(X) for est, meth in zip(self.estimators_, self.stack_method_) if est != 'drop']
    return self._concatenate_predictions(X, predictions)

def get_feature_names_out(self, input_features=None):
    check_is_fitted(self, 'n_features_in_')
    input_features = _check_feature_names_in(self, input_features, generate_names=self.passthrough)
    class_name = self.__class__.__name__.lower()
    non_dropped_estimators = (name for name, est in self.estimators if est != 'drop')
    meta_names = []
    for est, n_features_out in zip(non_dropped_estimators, self._n_feature_outs):
        if n_features_out == 1:
            meta_names.append(f'{class_name}_{est}')
        else:
            meta_names.extend((f'{class_name}_{est}{i}' for i in range(n_features_out)))
    if self.passthrough:
        return np.concatenate((meta_names, input_features))
    return np.asarray(meta_names, dtype=object)

@available_if(_estimator_has('predict', delegates=('final_estimator_', 'final_estimator')))
def predict(self, X, **predict_params):
    check_is_fitted(self)
    return self.final_estimator_.predict(self.transform(X), **predict_params)

def get_metadata_routing(self):
    router = MetadataRouter(owner=self)
    for name, estimator in self.estimators:
        router.add(**{name: estimator}, method_mapping=MethodMapping().add(callee='fit', caller='fit'))
    try:
        final_estimator_ = self.final_estimator_
    except AttributeError:
        final_estimator_ = self.final_estimator
    router.add(final_estimator_=final_estimator_, method_mapping=MethodMapping().add(caller='predict', callee='predict'))
    return router

def _validate_estimators(self):
    if len(self.estimators) == 0:
        raise ValueError("Invalid 'estimators' attribute, 'estimators' should be a non-empty list of (string, estimator) tuples.")
    names, estimators = zip(*self.estimators)
    self._validate_names(names)
    has_estimator = any((est != 'drop' for est in estimators))
    if not has_estimator:
        raise ValueError('All estimators are dropped. At least one is required to be an estimator.')
    return (names, estimators)

def fit(self, X, y, **fit_params):
    _raise_for_params(fit_params, self, 'fit', allow=['sample_weight'])
    check_classification_targets(y)
    if type_of_target(y) == 'multilabel-indicator':
        self._label_encoder = [LabelEncoder().fit(yk) for yk in y.T]
        self.classes_ = [le.classes_ for le in self._label_encoder]
        y_encoded = np.array([self._label_encoder[target_idx].transform(target) for target_idx, target in enumerate(y.T)]).T
    else:
        self._label_encoder = LabelEncoder().fit(y)
        self.classes_ = self._label_encoder.classes_
        y_encoded = self._label_encoder.transform(y)
    return super().fit(X, y_encoded, **fit_params)

@available_if(_estimator_has('predict', delegates=('final_estimator_', 'final_estimator')))
def predict(self, X, **predict_params):
    if _routing_enabled():
        routed_params = process_routing(self, 'predict', **predict_params)
    else:
        routed_params = _manual_routing({'final_estimator_': {'predict': predict_params}})
    y_pred = super().predict(X, **routed_params.final_estimator_['predict'])
    if isinstance(self._label_encoder, list):
        y_pred = np.array([self._label_encoder[target_idx].inverse_transform(target) for target_idx, target in enumerate(y_pred.T)]).T
    else:
        y_pred = self._label_encoder.inverse_transform(y_pred)
    return y_pred

@available_if(_estimator_has('predict_proba', delegates=('final_estimator_', 'final_estimator')))
def predict_proba(self, X):
    check_is_fitted(self)
    y_pred = self.final_estimator_.predict_proba(self.transform(X))
    if isinstance(self._label_encoder, list):
        y_pred = np.array([preds[:, 0] for preds in y_pred]).T
    return y_pred

@available_if(_estimator_has('decision_function', delegates=('final_estimator_', 'final_estimator')))
def decision_function(self, X):
    check_is_fitted(self)
    return self.final_estimator_.decision_function(self.transform(X))

def fit(self, X, y, **fit_params):
    _raise_for_params(fit_params, self, 'fit', allow=['sample_weight'])
    y = column_or_1d(y, warn=True)
    return super().fit(X, y, **fit_params)

def fit_transform(self, X, y, **fit_params):
    _raise_for_params(fit_params, self, 'fit', allow=['sample_weight'])
    return super().fit_transform(X, y, **fit_params)

@available_if(_estimator_has('predict', delegates=('final_estimator_', 'final_estimator')))
def predict(self, X, **predict_params):
    if _routing_enabled():
        routed_params = process_routing(self, 'predict', **predict_params)
    else:
        routed_params = _manual_routing({'final_estimator_': {'predict': predict_params}})
    y_pred = super().predict(X, **routed_params.final_estimator_['predict'])
    return y_pred

@property
def _weights_not_none(self):
    if self.weights is None:
        return None
    return [w for est, w in zip(self.estimators, self.weights) if est[1] != 'drop']

@abstractmethod
def fit(self, X, y, **fit_params):
    names, clfs = self._validate_estimators()
    if self.weights is not None and len(self.weights) != len(self.estimators):
        raise ValueError(f'Number of `estimators` and weights must be equal; got {len(self.weights)} weights, {len(self.estimators)} estimators')
    if _routing_enabled():
        routed_params = process_routing(self, 'fit', **fit_params)
    else:
        sw = {'sample_weight': fit_params['sample_weight']} if 'sample_weight' in fit_params else {}
        routed_params = _manual_routing({name: {'fit': sw} for name in names})
    self.estimators_ = Parallel(n_jobs=self.n_jobs)((delayed(_fit_single_estimator)(clone(clf), X, y, fit_params=routed_params[name]['fit'], message_clsname='Voting', message=self._log_message(name, idx + 1, len(clfs))) for idx, (name, clf) in enumerate(zip(names, clfs)) if clf != 'drop'))
    self.named_estimators_ = Bunch()
    est_iter = iter(self.estimators_)
    for name, est in self.estimators:
        current_est = est if est == 'drop' else next(est_iter)
        self.named_estimators_[name] = current_est
        if hasattr(current_est, 'feature_names_in_'):
            self.feature_names_in_ = current_est.feature_names_in_
    return self

@property
def n_features_in_(self):
    try:
        check_is_fitted(self)
    except NotFittedError as nfe:
        raise AttributeError('{} object has no n_features_in_ attribute.'.format(self.__class__.__name__)) from nfe
    return self.estimators_[0].n_features_in_

def get_metadata_routing(self):
    router = MetadataRouter(owner=self)
    for name, estimator in self.estimators:
        router.add(**{name: estimator}, method_mapping=MethodMapping().add(callee='fit', caller='fit'))
    return router

@_fit_context(prefer_skip_nested_validation=False)
def fit(self, X, y, **fit_params):
    _raise_for_params(fit_params, self, 'fit', allow=['sample_weight'])
    y_type = type_of_target(y, input_name='y')
    if y_type in ('unknown', 'continuous'):
        raise ValueError(f'Unknown label type: {y_type}. Maybe you are trying to fit a classifier, which expects discrete classes on a regression target with continuous values.')
    elif y_type not in ('binary', 'multiclass'):
        raise NotImplementedError(f'{self.__class__.__name__} only supports binary or multiclass classification. Multilabel and multi-output classification are not supported.')
    self.le_ = LabelEncoder().fit(y)
    self.classes_ = self.le_.classes_
    transformed_y = self.le_.transform(y)
    return super().fit(X, transformed_y, **fit_params)

def predict(self, X):
    check_is_fitted(self)
    if self.voting == 'soft':
        maj = np.argmax(self.predict_proba(X), axis=1)
    else:
        predictions = self._predict(X)
        maj = np.apply_along_axis(lambda x: np.argmax(np.bincount(x, weights=self._weights_not_none)), axis=1, arr=predictions)
    maj = self.le_.inverse_transform(maj)
    return maj

@available_if(_check_voting)
def predict_proba(self, X):
    check_is_fitted(self)
    avg = np.average(self._collect_probas(X), axis=0, weights=self._weights_not_none)
    return avg

def transform(self, X):
    check_is_fitted(self)
    if self.voting == 'soft':
        probas = self._collect_probas(X)
        if not self.flatten_transform:
            return probas
        return np.hstack(probas)
    else:
        return self._predict(X)

def get_feature_names_out(self, input_features=None):
    check_is_fitted(self, 'n_features_in_')
    if self.voting == 'soft' and (not self.flatten_transform):
        raise ValueError("get_feature_names_out is not supported when `voting='soft'` and `flatten_transform=False`")
    _check_feature_names_in(self, input_features, generate_names=False)
    class_name = self.__class__.__name__.lower()
    active_names = [name for name, est in self.estimators if est != 'drop']
    if self.voting == 'hard':
        return np.asarray([f'{class_name}_{name}' for name in active_names], dtype=object)
    n_classes = len(self.classes_)
    names_out = [f'{class_name}_{name}{i}' for name in active_names for i in range(n_classes)]
    return np.asarray(names_out, dtype=object)

@_fit_context(prefer_skip_nested_validation=False)
def fit(self, X, y, **fit_params):
    _raise_for_params(fit_params, self, 'fit', allow=['sample_weight'])
    y = column_or_1d(y, warn=True)
    return super().fit(X, y, **fit_params)

def predict(self, X):
    check_is_fitted(self)
    return np.average(self._predict(X), axis=1, weights=self._weights_not_none)

def transform(self, X):
    check_is_fitted(self)
    return self._predict(X)

def get_feature_names_out(self, input_features=None):
    check_is_fitted(self, 'n_features_in_')
    _check_feature_names_in(self, input_features, generate_names=False)
    class_name = self.__class__.__name__.lower()
    return np.asarray([f'{class_name}_{name}' for name, est in self.estimators if est != 'drop'], dtype=object)

@abstractmethod
def _boost(self, iboost, X, y, sample_weight, random_state):
    pass

def staged_score(self, X, y, sample_weight=None):
    X = self._check_X(X)
    for y_pred in self.staged_predict(X):
        if is_classifier(self):
            yield accuracy_score(y, y_pred, sample_weight=sample_weight)
        else:
            yield r2_score(y, y_pred, sample_weight=sample_weight)

@property
def feature_importances_(self):
    if self.estimators_ is None or len(self.estimators_) == 0:
        raise ValueError('Estimator not fitted, call `fit` before `feature_importances_`.')
    try:
        norm = self.estimator_weights_.sum()
        return sum((weight * clf.feature_importances_ for weight, clf in zip(self.estimator_weights_, self.estimators_))) / norm
    except AttributeError as e:
        raise AttributeError('Unable to compute feature importances since estimator does not have a feature_importances_ attribute') from e

def _validate_estimator(self):
    super()._validate_estimator(default=DecisionTreeClassifier(max_depth=1))
    if not has_fit_parameter(self.estimator_, 'sample_weight'):
        raise ValueError(f"{self.estimator.__class__.__name__} doesn't support sample_weight.")

def _boost(self, iboost, X, y, sample_weight, random_state):
    estimator = self._make_estimator(random_state=random_state)
    estimator.fit(X, y, sample_weight=sample_weight)
    y_predict = estimator.predict(X)
    if iboost == 0:
        self.classes_ = getattr(estimator, 'classes_', None)
        self.n_classes_ = len(self.classes_)
    incorrect = y_predict != y
    estimator_error = np.mean(np.average(incorrect, weights=sample_weight, axis=0))
    if estimator_error <= 0:
        return (sample_weight, 1.0, 0.0)
    n_classes = self.n_classes_
    if estimator_error >= 1.0 - 1.0 / n_classes:
        self.estimators_.pop(-1)
        if len(self.estimators_) == 0:
            raise ValueError('BaseClassifier in AdaBoostClassifier ensemble is worse than random, ensemble can not be fit.')
        return (None, None, None)
    estimator_weight = self.learning_rate * (np.log((1.0 - estimator_error) / estimator_error) + np.log(n_classes - 1.0))
    if not iboost == self.n_estimators - 1:
        sample_weight = np.exp(np.log(sample_weight) + estimator_weight * incorrect * (sample_weight > 0))
    return (sample_weight, estimator_weight, estimator_error)

def predict(self, X):
    pred = self.decision_function(X)
    if self.n_classes_ == 2:
        return self.classes_.take(pred > 0, axis=0)
    return self.classes_.take(np.argmax(pred, axis=1), axis=0)

def staged_predict(self, X):
    X = self._check_X(X)
    n_classes = self.n_classes_
    classes = self.classes_
    if n_classes == 2:
        for pred in self.staged_decision_function(X):
            yield np.array(classes.take(pred > 0, axis=0))
    else:
        for pred in self.staged_decision_function(X):
            yield np.array(classes.take(np.argmax(pred, axis=1), axis=0))

def decision_function(self, X):
    check_is_fitted(self)
    X = self._check_X(X)
    n_classes = self.n_classes_
    classes = self.classes_[:, np.newaxis]
    if n_classes == 1:
        return np.zeros_like(X, shape=(X.shape[0], 1))
    pred = sum((np.where((estimator.predict(X) == classes).T, w, -1 / (n_classes - 1) * w) for estimator, w in zip(self.estimators_, self.estimator_weights_)))
    pred /= self.estimator_weights_.sum()
    if n_classes == 2:
        pred[:, 0] *= -1
        return pred.sum(axis=1)
    return pred

def staged_decision_function(self, X):
    check_is_fitted(self)
    X = self._check_X(X)
    n_classes = self.n_classes_
    classes = self.classes_[:, np.newaxis]
    pred = None
    norm = 0.0
    for weight, estimator in zip(self.estimator_weights_, self.estimators_):
        norm += weight
        current_pred = np.where((estimator.predict(X) == classes).T, weight, -1 / (n_classes - 1) * weight)
        if pred is None:
            pred = current_pred
        else:
            pred += current_pred
        if n_classes == 2:
            tmp_pred = np.copy(pred)
            tmp_pred[:, 0] *= -1
            yield (tmp_pred / norm).sum(axis=1)
        else:
            yield (pred / norm)

@staticmethod
def _compute_proba_from_decision(decision, n_classes):
    if n_classes == 2:
        decision = np.vstack([-decision, decision]).T / 2
    else:
        decision /= n_classes - 1
    return softmax(decision, copy=False)

def predict_proba(self, X):
    check_is_fitted(self)
    n_classes = self.n_classes_
    if n_classes == 1:
        return np.ones((_num_samples(X), 1))
    decision = self.decision_function(X)
    return self._compute_proba_from_decision(decision, n_classes)

def staged_predict_proba(self, X):
    n_classes = self.n_classes_
    for decision in self.staged_decision_function(X):
        yield self._compute_proba_from_decision(decision, n_classes)

def _boost(self, iboost, X, y, sample_weight, random_state):
    estimator = self._make_estimator(random_state=random_state)
    bootstrap_idx = random_state.choice(np.arange(_num_samples(X)), size=_num_samples(X), replace=True, p=sample_weight)
    X_ = _safe_indexing(X, bootstrap_idx)
    y_ = _safe_indexing(y, bootstrap_idx)
    estimator.fit(X_, y_)
    y_predict = estimator.predict(X)
    error_vect = np.abs(y_predict - y)
    sample_mask = sample_weight > 0
    masked_sample_weight = sample_weight[sample_mask]
    masked_error_vector = error_vect[sample_mask]
    error_max = masked_error_vector.max()
    if error_max != 0:
        masked_error_vector /= error_max
    if self.loss == 'square':
        masked_error_vector **= 2
    elif self.loss == 'exponential':
        masked_error_vector = 1.0 - np.exp(-masked_error_vector)
    estimator_error = (masked_sample_weight * masked_error_vector).sum()
    if estimator_error <= 0:
        return (sample_weight, 1.0, 0.0)
    elif estimator_error >= 0.5:
        if len(self.estimators_) > 1:
            self.estimators_.pop(-1)
        return (None, None, None)
    beta = estimator_error / (1.0 - estimator_error)
    estimator_weight = self.learning_rate * np.log(1.0 / beta)
    if not iboost == self.n_estimators - 1:
        sample_weight[sample_mask] *= np.power(beta, (1.0 - masked_error_vector) * self.learning_rate)
    return (sample_weight, estimator_weight, estimator_error)

def predict(self, X):
    check_is_fitted(self)
    X = self._check_X(X)
    return self._get_median_predict(X, len(self.estimators_))

def staged_predict(self, X):
    check_is_fitted(self)
    X = self._check_X(X)
    for i, _ in enumerate(self.estimators_, 1):
        yield self._get_median_predict(X, limit=i)

def make_known_categories_bitsets(self):
    categorical_features_indices = np.flatnonzero(self.is_categorical_)
    n_features = self.is_categorical_.size
    n_categorical_features = categorical_features_indices.size
    f_idx_map = np.zeros(n_features, dtype=np.uint32)
    f_idx_map[categorical_features_indices] = np.arange(n_categorical_features, dtype=np.uint32)
    known_categories = self.bin_thresholds_
    known_cat_bitsets = np.zeros((n_categorical_features, 8), dtype=X_BITSET_INNER_DTYPE)
    for mapped_f_idx, f_idx in enumerate(categorical_features_indices):
        for raw_cat_val in known_categories[f_idx]:
            set_bitset_memoryview(known_cat_bitsets[mapped_f_idx], raw_cat_val)
    return (known_cat_bitsets, f_idx_map)

def _update_leaves_values(loss, grower, y_true, raw_prediction, sample_weight):
    for leaf in grower.finalized_leaves:
        indices = leaf.sample_indices
        if sample_weight is None:
            sw = None
        else:
            sw = sample_weight[indices]
        update = loss.fit_intercept_only(y_true=y_true[indices] - raw_prediction[indices], sample_weight=sw)
        leaf.value = grower.shrinkage * update

@contextmanager
def _patch_raw_predict(estimator, raw_predictions):
    orig_raw_predict = estimator._raw_predict

    def _patched_raw_predicts(*args, **kwargs):
        return raw_predictions
    estimator._raw_predict = _patched_raw_predicts
    yield estimator
    estimator._raw_predict = orig_raw_predict

def _validate_parameters(self):
    if self.monotonic_cst is not None and self.n_trees_per_iteration_ != 1:
        raise ValueError('monotonic constraints are not supported for multiclass classification.')

def _check_categories(self):
    encoder = self._preprocessor.named_transformers_['encoder']
    known_categories = [None] * self._preprocessor.n_features_in_
    categorical_column_indices = np.arange(self._preprocessor.n_features_in_)[self._preprocessor.output_indices_['encoder']]
    for feature_idx, categories in zip(categorical_column_indices, encoder.categories_):
        if len(categories) and is_scalar_nan(categories[-1]):
            categories = categories[:-1]
        if categories.size > self.max_bins:
            try:
                feature_name = repr(encoder.feature_names_in_[feature_idx])
            except AttributeError:
                feature_name = f'at index {feature_idx}'
            raise ValueError(f'Categorical feature {feature_name} is expected to have a cardinality <= {self.max_bins} but actually has a cardinality of {categories.size}.')
        known_categories[feature_idx] = np.arange(len(categories), dtype=X_DTYPE)
    return known_categories

def _check_interaction_cst(self, n_features):
    if self.interaction_cst is None:
        return None
    if self.interaction_cst == 'no_interactions':
        interaction_cst = [[i] for i in range(n_features)]
    elif self.interaction_cst == 'pairwise':
        interaction_cst = itertools.combinations(range(n_features), 2)
    else:
        interaction_cst = self.interaction_cst
    try:
        constraints = [set(group) for group in interaction_cst]
    except TypeError:
        raise ValueError(f'Interaction constraints must be a sequence of tuples or lists, got: {self.interaction_cst!r}.')
    for group in constraints:
        for x in group:
            if not (isinstance(x, Integral) and 0 <= x < n_features):
                raise ValueError(f'Interaction constraints must consist of integer indices in [0, n_features - 1] = [0, {n_features - 1}], specifying the position of features, got invalid indices: {group!r}')
    rest = set(range(n_features)) - set().union(*constraints)
    if len(rest) > 0:
        constraints.append(rest)
    return constraints

@_fit_context(prefer_skip_nested_validation=True)
def fit(self, X, y, sample_weight=None, *, X_val=None, y_val=None, sample_weight_val=None):
    fit_start_time = time()
    acc_find_split_time = 0.0
    acc_apply_split_time = 0.0
    acc_compute_hist_time = 0.0
    acc_prediction_time = 0.0
    X, known_categories = self._preprocess_X(X, reset=True)
    y = _check_y(y, estimator=self)
    y = self._encode_y(y)
    check_consistent_length(X, y)
    if sample_weight is not None:
        sample_weight = _check_sample_weight(sample_weight, X, dtype=np.float64)
        self._fitted_with_sw = True
    sample_weight = self._finalize_sample_weight(sample_weight, y)
    validation_data_provided = X_val is not None or y_val is not None
    if validation_data_provided:
        if y_val is None:
            raise ValueError('X_val is provided, but y_val was not provided.')
        if X_val is None:
            raise ValueError('y_val is provided, but X_val was not provided.')
        X_val = self._preprocess_X(X_val, reset=False)
        y_val = _check_y(y_val, estimator=self)
        y_val = self._encode_y_val(y_val)
        check_consistent_length(X_val, y_val)
        if sample_weight_val is not None:
            sample_weight_val = _check_sample_weight(sample_weight_val, X_val, dtype=np.float64)
        if self.early_stopping is False:
            raise ValueError("X_val and y_val are passed to fit while at the same time early_stopping is False. When passing X_val and y_val to fit,early_stopping should be set to either 'auto' or True.")
    rng = check_random_state(self.random_state)
    if not self.warm_start or not self._is_fitted():
        self._random_seed = rng.randint(np.iinfo(np.uint32).max, dtype='u8')
        feature_subsample_seed = rng.randint(np.iinfo(np.uint32).max, dtype='u8')
        self._feature_subsample_rng = np.random.default_rng(feature_subsample_seed)
    self._validate_parameters()
    monotonic_cst = _check_monotonic_cst(self, self.monotonic_cst)
    if self.is_categorical_ is not None:
        monotonic_cst_remapped = np.concatenate((monotonic_cst[self.is_categorical_], monotonic_cst[~self.is_categorical_]))
    else:
        monotonic_cst_remapped = monotonic_cst
    n_samples, self._n_features = X.shape
    interaction_cst = self._check_interaction_cst(self._n_features)
    self._in_fit = True
    n_threads = _openmp_effective_n_threads()
    if isinstance(self.loss, str):
        self._loss = self._get_loss(sample_weight=sample_weight)
    elif isinstance(self.loss, BaseLoss):
        self._loss = self.loss
    if self.early_stopping == 'auto':
        self.do_early_stopping_ = n_samples > 10000
    else:
        self.do_early_stopping_ = self.early_stopping
    self._use_validation_data = self.validation_fraction is not None or validation_data_provided
    if self.do_early_stopping_ and self._use_validation_data and (not validation_data_provided):
        stratify = y if hasattr(self._loss, 'predict_proba') else None
        if sample_weight is None:
            X_train, X_val, y_train, y_val = train_test_split(X, y, test_size=self.validation_fraction, stratify=stratify, random_state=self._random_seed)
            sample_weight_train = sample_weight_val = None
        else:
            X_train, X_val, y_train, y_val, sample_weight_train, sample_weight_val = train_test_split(X, y, sample_weight, test_size=self.validation_fraction, stratify=stratify, random_state=self._random_seed)
    else:
        X_train, y_train, sample_weight_train = (X, y, sample_weight)
        if not validation_data_provided:
            X_val = y_val = sample_weight_val = None
    n_bins = self.max_bins + 1
    self._bin_mapper = _BinMapper(n_bins=n_bins, is_categorical=self._is_categorical_remapped, known_categories=known_categories, random_state=self._random_seed, n_threads=n_threads)
    X_binned_train = self._bin_data(X_train, sample_weight_train, is_training_data=True)
    if X_val is not None:
        X_binned_val = self._bin_data(X_val, sample_weight_val, is_training_data=False)
    else:
        X_binned_val = None
    has_missing_values = (X_binned_train == self._bin_mapper.missing_values_bin_idx_).any(axis=0).astype(np.uint8)
    if self.verbose:
        print('Fitting gradient boosted rounds:')
    n_samples = X_binned_train.shape[0]
    scoring_is_predefined_string = self.scoring in _SCORERS
    need_raw_predictions_val = X_binned_val is not None and (scoring_is_predefined_string or self.scoring == 'loss')
    if not (self._is_fitted() and self.warm_start):
        self._clear_state()
        self._baseline_prediction = self._loss.fit_intercept_only(y_true=y_train, sample_weight=sample_weight_train).reshape((1, -1))
        raw_predictions = np.zeros(shape=(n_samples, self.n_trees_per_iteration_), dtype=self._baseline_prediction.dtype, order='F')
        raw_predictions += self._baseline_prediction
        self._predictors = predictors = []
        self._scorer = None
        raw_predictions_val = None
        self.train_score_ = []
        self.validation_score_ = []
        if self.do_early_stopping_:
            if need_raw_predictions_val:
                raw_predictions_val = np.zeros(shape=(X_binned_val.shape[0], self.n_trees_per_iteration_), dtype=self._baseline_prediction.dtype, order='F')
                raw_predictions_val += self._baseline_prediction
            if self.scoring == 'loss':
                self._check_early_stopping_loss(raw_predictions=raw_predictions, y_train=y_train, sample_weight_train=sample_weight_train, raw_predictions_val=raw_predictions_val, y_val=y_val, sample_weight_val=sample_weight_val, n_threads=n_threads)
            else:
                self._scorer = check_scoring(self, self.scoring)
                X_binned_small_train, y_small_train, sample_weight_small_train, indices_small_train = self._get_small_trainset(X_binned_train, y_train, sample_weight_train, self._random_seed)
                if scoring_is_predefined_string:
                    raw_predictions_small_train = raw_predictions[indices_small_train]
                else:
                    raw_predictions_small_train = None
                self._check_early_stopping_scorer(X_binned_small_train, y_small_train, sample_weight_small_train, X_binned_val, y_val, sample_weight_val, raw_predictions_small_train=raw_predictions_small_train, raw_predictions_val=raw_predictions_val)
        begin_at_stage = 0
    else:
        if self.max_iter < self.n_iter_:
            raise ValueError('max_iter=%d must be larger than or equal to n_iter_=%d when warm_start==True' % (self.max_iter, self.n_iter_))
        self.train_score_ = self.train_score_.tolist()
        self.validation_score_ = self.validation_score_.tolist()
        raw_predictions = self._raw_predict(X_binned_train, n_threads=n_threads)
        if self.do_early_stopping_ and need_raw_predictions_val:
            raw_predictions_val = self._raw_predict(X_binned_val, n_threads=n_threads)
        else:
            raw_predictions_val = None
        if self.do_early_stopping_ and self.scoring != 'loss':
            X_binned_small_train, y_small_train, sample_weight_small_train, indices_small_train = self._get_small_trainset(X_binned_train, y_train, sample_weight_train, self._random_seed)
        predictors = self._predictors
        begin_at_stage = self.n_iter_
    gradient, hessian = self._loss.init_gradient_and_hessian(n_samples=n_samples, dtype=G_H_DTYPE, order='F')
    for iteration in range(begin_at_stage, self.max_iter):
        if self.verbose >= 2:
            iteration_start_time = time()
            print('[{}/{}] '.format(iteration + 1, self.max_iter), end='', flush=True)
        if self._loss.constant_hessian:
            self._loss.gradient(y_true=y_train, raw_prediction=raw_predictions, sample_weight=sample_weight_train, gradient_out=gradient, n_threads=n_threads)
        else:
            self._loss.gradient_hessian(y_true=y_train, raw_prediction=raw_predictions, sample_weight=sample_weight_train, gradient_out=gradient, hessian_out=hessian, n_threads=n_threads)
        predictors.append([])
        if gradient.ndim == 1:
            g_view = gradient.reshape((-1, 1))
            h_view = hessian.reshape((-1, 1))
        else:
            g_view = gradient
            h_view = hessian
        for k in range(self.n_trees_per_iteration_):
            grower = TreeGrower(X_binned=X_binned_train, gradients=g_view[:, k], hessians=h_view[:, k], n_bins=n_bins, n_bins_non_missing=self._bin_mapper.n_bins_non_missing_, has_missing_values=has_missing_values, is_categorical=self._is_categorical_remapped, monotonic_cst=monotonic_cst_remapped, interaction_cst=interaction_cst, max_leaf_nodes=self.max_leaf_nodes, max_depth=self.max_depth, min_samples_leaf=self.min_samples_leaf, l2_regularization=self.l2_regularization, feature_fraction_per_split=self.max_features, rng=self._feature_subsample_rng, shrinkage=self.learning_rate, n_threads=n_threads)
            grower.grow()
            acc_apply_split_time += grower.total_apply_split_time
            acc_find_split_time += grower.total_find_split_time
            acc_compute_hist_time += grower.total_compute_hist_time
            if not self._loss.differentiable:
                _update_leaves_values(loss=self._loss, grower=grower, y_true=y_train, raw_prediction=raw_predictions[:, k], sample_weight=sample_weight_train)
            predictor = grower.make_predictor(binning_thresholds=self._bin_mapper.bin_thresholds_)
            predictors[-1].append(predictor)
            tic_pred = time()
            _update_raw_predictions(raw_predictions[:, k], grower, n_threads)
            toc_pred = time()
            acc_prediction_time += toc_pred - tic_pred
        should_early_stop = False
        if self.do_early_stopping_:
            if need_raw_predictions_val:
                for k, pred in enumerate(self._predictors[-1]):
                    raw_predictions_val[:, k] += pred.predict_binned(X_binned_val, self._bin_mapper.missing_values_bin_idx_, n_threads)
            if self.scoring == 'loss':
                should_early_stop = self._check_early_stopping_loss(raw_predictions=raw_predictions, y_train=y_train, sample_weight_train=sample_weight_train, raw_predictions_val=raw_predictions_val, y_val=y_val, sample_weight_val=sample_weight_val, n_threads=n_threads)
            else:
                if scoring_is_predefined_string:
                    raw_predictions_small_train = raw_predictions[indices_small_train]
                else:
                    raw_predictions_small_train = None
                should_early_stop = self._check_early_stopping_scorer(X_binned_small_train, y_small_train, sample_weight_small_train, X_binned_val, y_val, sample_weight_val, raw_predictions_small_train=raw_predictions_small_train, raw_predictions_val=raw_predictions_val)
        if self.verbose >= 2:
            self._print_iteration_stats(iteration_start_time)
        if should_early_stop:
            break
    if self.verbose:
        duration = time() - fit_start_time
        n_total_leaves = sum((predictor.get_n_leaf_nodes() for predictors_at_ith_iteration in self._predictors for predictor in predictors_at_ith_iteration))
        n_predictors = sum((len(predictors_at_ith_iteration) for predictors_at_ith_iteration in self._predictors))
        print('Fit {} trees in {:.3f} s, ({} total leaves)'.format(n_predictors, duration, n_total_leaves))
        print('{:<32} {:.3f}s'.format('Time spent computing histograms:', acc_compute_hist_time))
        print('{:<32} {:.3f}s'.format('Time spent finding best splits:', acc_find_split_time))
        print('{:<32} {:.3f}s'.format('Time spent applying splits:', acc_apply_split_time))
        print('{:<32} {:.3f}s'.format('Time spent predicting:', acc_prediction_time))
    self.train_score_ = np.asarray(self.train_score_)
    self.validation_score_ = np.asarray(self.validation_score_)
    del self._in_fit
    return self

def _clear_state(self):
    for var in ('train_score_', 'validation_score_'):
        if hasattr(self, var):
            delattr(self, var)

def _get_small_trainset(self, X_binned_train, y_train, sample_weight_train, seed):
    subsample_size = 10000
    if X_binned_train.shape[0] > subsample_size:
        indices = np.arange(X_binned_train.shape[0])
        stratify = y_train if is_classifier(self) else None
        indices = resample(indices, n_samples=subsample_size, replace=False, random_state=seed, stratify=stratify)
        X_binned_small_train = X_binned_train[indices]
        y_small_train = y_train[indices]
        if sample_weight_train is not None:
            sample_weight_small_train = sample_weight_train[indices]
        else:
            sample_weight_small_train = None
        X_binned_small_train = np.ascontiguousarray(X_binned_small_train)
        return (X_binned_small_train, y_small_train, sample_weight_small_train, indices)
    else:
        return (X_binned_train, y_train, sample_weight_train, slice(None))

def _check_early_stopping_scorer(self, X_binned_small_train, y_small_train, sample_weight_small_train, X_binned_val, y_val, sample_weight_val, raw_predictions_small_train=None, raw_predictions_val=None):
    if is_classifier(self):
        y_small_train = self.classes_[y_small_train.astype(int)]
    self.train_score_.append(self._score_with_raw_predictions(X_binned_small_train, y_small_train, sample_weight_small_train, raw_predictions_small_train))
    if self._use_validation_data:
        if is_classifier(self):
            y_val = self.classes_[y_val.astype(int)]
        self.validation_score_.append(self._score_with_raw_predictions(X_binned_val, y_val, sample_weight_val, raw_predictions_val))
        return self._should_stop(self.validation_score_)
    else:
        return self._should_stop(self.train_score_)

def _check_early_stopping_loss(self, raw_predictions, y_train, sample_weight_train, raw_predictions_val, y_val, sample_weight_val, n_threads=1):
    self.train_score_.append(-self._loss(y_true=y_train, raw_prediction=raw_predictions, sample_weight=sample_weight_train, n_threads=n_threads))
    if self._use_validation_data:
        self.validation_score_.append(-self._loss(y_true=y_val, raw_prediction=raw_predictions_val, sample_weight=sample_weight_val, n_threads=n_threads))
        return self._should_stop(self.validation_score_)
    else:
        return self._should_stop(self.train_score_)

def _should_stop(self, scores):
    reference_position = self.n_iter_no_change + 1
    if len(scores) < reference_position:
        return False
    reference_score = scores[-reference_position] + self.tol
    recent_scores = scores[-reference_position + 1:]
    recent_improvements = [score > reference_score for score in recent_scores]
    return not any(recent_improvements)

def _bin_data(self, X, sample_weight, is_training_data):
    description = 'training' if is_training_data else 'validation'
    if self.verbose:
        print('Binning {:.3f} GB of {} data: '.format(X.nbytes / 1000000000.0, description), end='', flush=True)
    tic = time()
    if is_training_data:
        X_binned = self._bin_mapper.fit_transform(X, sample_weight=sample_weight)
    else:
        X_binned = self._bin_mapper.transform(X)
        X_binned = np.ascontiguousarray(X_binned)
    toc = time()
    if self.verbose:
        duration = toc - tic
        print('{:.3f} s'.format(duration))
    return X_binned

def _predict_iterations(self, X, predictors, raw_predictions, is_binned, n_threads):
    if not is_binned:
        known_cat_bitsets, f_idx_map = self._bin_mapper.make_known_categories_bitsets()
    for predictors_of_ith_iteration in predictors:
        for k, predictor in enumerate(predictors_of_ith_iteration):
            if is_binned:
                predict = partial(predictor.predict_binned, missing_values_bin_idx=self._bin_mapper.missing_values_bin_idx_, n_threads=n_threads)
            else:
                predict = partial(predictor.predict, known_cat_bitsets=known_cat_bitsets, f_idx_map=f_idx_map, n_threads=n_threads)
            raw_predictions[:, k] += predict(X)

def _compute_partial_dependence_recursion(self, grid, target_features):
    if getattr(self, '_fitted_with_sw', False):
        raise NotImplementedError("{} does not support partial dependence plots with the 'recursion' method when sample weights were given during fit time.".format(self.__class__.__name__))
    grid = np.asarray(grid, dtype=X_DTYPE, order='C')
    averaged_predictions = np.zeros((self.n_trees_per_iteration_, grid.shape[0]), dtype=Y_DTYPE)
    target_features = np.asarray(target_features, dtype=np.intp, order='C')
    for predictors_of_ith_iteration in self._predictors:
        for k, predictor in enumerate(predictors_of_ith_iteration):
            predictor.compute_partial_dependence(grid, target_features, averaged_predictions[k])
    return averaged_predictions

@property
def n_iter_(self):
    check_is_fitted(self)
    return len(self._predictors)

def predict(self, X):
    check_is_fitted(self)
    return self._loss.link.inverse(self._raw_predict(X).ravel())

def staged_predict(self, X):
    for raw_predictions in self._staged_raw_predict(X):
        yield self._loss.link.inverse(raw_predictions.ravel())

def _finalize_sample_weight(self, sample_weight, y):
    if self.class_weight is None:
        return sample_weight
    expanded_class_weight = compute_sample_weight(self.class_weight, y)
    if sample_weight is not None:
        return sample_weight * expanded_class_weight
    else:
        return expanded_class_weight

def predict(self, X):
    raw_predictions = self._raw_predict(X)
    if raw_predictions.shape[1] == 1:
        encoded_classes = (raw_predictions.ravel() > 0).astype(int)
    else:
        encoded_classes = np.argmax(raw_predictions, axis=1)
    return self.classes_[encoded_classes]

def staged_predict(self, X):
    for raw_predictions in self._staged_raw_predict(X):
        if raw_predictions.shape[1] == 1:
            encoded_classes = (raw_predictions.ravel() > 0).astype(int)
        else:
            encoded_classes = np.argmax(raw_predictions, axis=1)
        yield self.classes_.take(encoded_classes, axis=0)

def predict_proba(self, X):
    raw_predictions = self._raw_predict(X)
    return self._loss.predict_proba(raw_predictions)

def staged_predict_proba(self, X):
    for raw_predictions in self._staged_raw_predict(X):
        yield self._loss.predict_proba(raw_predictions)

def decision_function(self, X):
    decision = self._raw_predict(X)
    if decision.shape[1] == 1:
        decision = decision.ravel()
    return decision

def staged_decision_function(self, X):
    for staged_decision in self._staged_raw_predict(X):
        if staged_decision.shape[1] == 1:
            staged_decision = staged_decision.ravel()
        yield staged_decision

def set_children_bounds(self, lower, upper):
    self.children_lower_bound = lower
    self.children_upper_bound = upper

def _validate_parameters(self, X_binned, min_gain_to_split, min_hessian_to_split):
    if X_binned.dtype != np.uint8:
        raise NotImplementedError('X_binned must be of type uint8.')
    if not X_binned.flags.f_contiguous:
        raise ValueError('X_binned should be passed as Fortran contiguous array for maximum efficiency.')
    if min_gain_to_split < 0:
        raise ValueError('min_gain_to_split={} must be positive.'.format(min_gain_to_split))
    if min_hessian_to_split < 0:
        raise ValueError('min_hessian_to_split={} must be positive.'.format(min_hessian_to_split))

def grow(self):
    while self.splittable_nodes:
        self.split_next()
    self._apply_shrinkage()

def _apply_shrinkage(self):
    for leaf in self.finalized_leaves:
        leaf.value *= self.shrinkage

def _compute_best_split_and_push(self, node):
    node.split_info = self.splitter.find_node_split(n_samples=node.n_samples, histograms=node.histograms, sum_gradients=node.sum_gradients, sum_hessians=node.sum_hessians, value=node.value, lower_bound=node.children_lower_bound, upper_bound=node.children_upper_bound, allowed_features=node.allowed_features)
    if node.split_info.gain <= 0:
        self._finalize_leaf(node)
    else:
        heappush(self.splittable_nodes, node)

def _compute_interactions(self, node):
    allowed_features = set()
    interaction_cst_indices = []
    for i in node.interaction_cst_indices:
        if node.split_info.feature_idx in self.interaction_cst[i]:
            interaction_cst_indices.append(i)
            allowed_features.update(self.interaction_cst[i])
    return (np.fromiter(allowed_features, dtype=np.uint32, count=len(allowed_features)), interaction_cst_indices)

def _finalize_leaf(self, node):
    node.is_leaf = True
    self.finalized_leaves.append(node)

def _finalize_splittable_nodes(self):
    while len(self.splittable_nodes) > 0:
        node = self.splittable_nodes.pop()
        self._finalize_leaf(node)

def make_predictor(self, binning_thresholds):
    predictor_nodes = np.zeros(self.n_nodes, dtype=PREDICTOR_RECORD_DTYPE)
    binned_left_cat_bitsets = np.zeros((self.n_categorical_splits, 8), dtype=X_BITSET_INNER_DTYPE)
    raw_left_cat_bitsets = np.zeros((self.n_categorical_splits, 8), dtype=X_BITSET_INNER_DTYPE)
    _fill_predictor_arrays(predictor_nodes, binned_left_cat_bitsets, raw_left_cat_bitsets, self.root, binning_thresholds, self.n_bins_non_missing)
    return TreePredictor(predictor_nodes, binned_left_cat_bitsets, raw_left_cat_bitsets)

def get_equivalent_estimator(estimator, lib='lightgbm', n_classes=None):
    if lib not in ('lightgbm', 'xgboost', 'catboost'):
        raise ValueError('accepted libs are lightgbm, xgboost, and catboost.  got {}'.format(lib))
    sklearn_params = estimator.get_params()
    if sklearn_params['loss'] == 'auto':
        raise ValueError('auto loss is not accepted. We need to know if the problem is binary or multiclass classification.')
    if sklearn_params['early_stopping']:
        raise NotImplementedError('Early stopping should be deactivated.')
    lightgbm_loss_mapping = {'squared_error': 'regression_l2', 'absolute_error': 'regression_l1', 'log_loss': 'binary' if n_classes == 2 else 'multiclass', 'gamma': 'gamma', 'poisson': 'poisson'}
    lightgbm_params = {'objective': lightgbm_loss_mapping[sklearn_params['loss']], 'learning_rate': sklearn_params['learning_rate'], 'n_estimators': sklearn_params['max_iter'], 'num_leaves': sklearn_params['max_leaf_nodes'], 'max_depth': sklearn_params['max_depth'], 'min_data_in_leaf': sklearn_params['min_samples_leaf'], 'reg_lambda': sklearn_params['l2_regularization'], 'max_bin': sklearn_params['max_bins'], 'min_data_in_bin': 1, 'min_sum_hessian_in_leaf': 0.001, 'min_split_gain': 0, 'verbosity': 10 if sklearn_params['verbose'] else -10, 'boost_from_average': True, 'enable_bundle': False, 'subsample_for_bin': _BinMapper().subsample, 'poisson_max_delta_step': 1e-12, 'feature_fraction_bynode': sklearn_params['max_features']}
    if sklearn_params['loss'] == 'log_loss' and n_classes > 2:
        lightgbm_params['min_sum_hessian_in_leaf'] *= 2
        if n_classes is not None:
            lightgbm_params['learning_rate'] *= n_classes / (n_classes - 1)
    xgboost_loss_mapping = {'squared_error': 'reg:linear', 'absolute_error': 'LEAST_ABSOLUTE_DEV_NOT_SUPPORTED', 'log_loss': 'reg:logistic' if n_classes == 2 else 'multi:softmax', 'gamma': 'reg:gamma', 'poisson': 'count:poisson'}
