    for k, v in res.copy().items():
        try:
            torch.empty((0,), dtype=v, device=device)
        except:
            del res[k]
    return res

@cache
def devices(self):
    try:
        torch.device('notadevice')
        raise AssertionError('unreachable')
    except RuntimeError as e:
        devices_names = e.args[0].split('Expected one of ')[1].split(' device type')[0].split(', ')
    devices = []
    for device_name in devices_names:
        i = 0
        while True:
            try:
                a = torch.empty((0,), device=torch.device(device_name, index=i))
                if a.device in devices:
                    break
                devices.append(a.device)
            except:
                break
            i += 1
    return tuple(devices)

def _clone_function(f: Callable[..., Any]) -> Callable[..., Any]:
    f_new = FunctionType(f.__code__, f.__globals__, name=f.__name__, argdefs=f.__defaults__, closure=f.__closure__)
    f_new.__kwdefaults__ = f.__kwdefaults__
    return update_wrapper(f_new, f)

def lazy_xp_function(func: Callable[..., Any] | tuple[type, str], *, allow_dask_compute: bool | int=False, jax_jit: bool=True, static_argnums: Deprecated=DEPRECATED, static_argnames: Deprecated=DEPRECATED) -> None:
    if static_argnums is not DEPRECATED or static_argnames is not DEPRECATED:
        warnings.warn('The `static_argnums` and `static_argnames` parameters are deprecated and ignored. They will be removed in a future version.', DeprecationWarning, stacklevel=2)
    tags: dict[str, bool | int | type] = {'allow_dask_compute': allow_dask_compute, 'jax_jit': jax_jit}
    if isinstance(func, tuple):
        cls, method_name = func
        raw_attr = getattr_static(cls, method_name)
        method = getattr(cls, method_name)
        if isinstance(raw_attr, classmethod):
            method = method.__func__
        cloned_method = _clone_function(method)
        method_to_set: Any
        if isinstance(raw_attr, staticmethod):
            method_to_set = staticmethod(cloned_method)
        elif isinstance(raw_attr, classmethod):
            method_to_set = classmethod(cloned_method)
        else:
            method_to_set = cloned_method
        setattr(cls, method_name, method_to_set)
        f = getattr(cls, method_name)
        if isinstance(raw_attr, classmethod):
            f = f.__func__
        tags['owner'] = cls
    else:
        f = func
    try:
        f._lazy_xp_function = tags
    except AttributeError:
        _ufuncs_tags[f] = tags

def patch_lazy_xp_functions(request: pytest.FixtureRequest, monkeypatch: pytest.MonkeyPatch | None=None, *, xp: ModuleType) -> contextlib.AbstractContextManager[None]:
    mod = cast(ModuleType, request.module)
    search_targets: list[ModuleType | type] = [mod, *cast(list[ModuleType], getattr(mod, 'lazy_xp_modules', []))]
    classes: set[type] = set()
    for target in search_targets:
        for obj in target.__dict__.values():
            if isinstance(obj, type):
                classes.add(obj)
    search_targets.extend(classes)
    to_revert: list[tuple[ModuleType | type, str, object]] = []

    def temp_setattr(target: ModuleType | type, name: str, func: object) -> None:
        """
        Temporary setattr.

        Variant of monkeypatch.setattr, which allows monkey-patching only selected
        parameters of a test so that pytest-run-parallel can run on the remainder.
        """
        assert hasattr(target, name)
        original = getattr_static(target, name)
        to_revert.append((target, name, original))
        setattr(target, name, func)
    if monkeypatch is not None:
        warnings.warn('The `monkeypatch` parameter is deprecated and will be removed in a future version. Use `patch_lazy_xp_function` as a context manager instead.', DeprecationWarning, stacklevel=2)
        temp_setattr = monkeypatch.setattr

    def iter_tagged() -> Iterator[tuple[ModuleType | type, str, Any, Callable[..., Any], dict[str, Any]]]:
        for target in search_targets:
            for name, attr in target.__dict__.items():
                func: Any = attr.__func__ if isinstance(attr, (staticmethod, classmethod)) else attr
                tags: dict[str, Any] | None = None
                with contextlib.suppress(AttributeError):
                    tags = func._lazy_xp_function
                if tags is None:
                    with contextlib.suppress(KeyError, TypeError):
                        tags = _ufuncs_tags[func]
                if tags is not None:
                    if isinstance(target, type) and tags.get('owner') is not target:
                        continue
                    yield (target, name, attr, func, tags)
    wrapped: Any
    if is_dask_namespace(xp):
        for target, name, attr, func, tags in iter_tagged():
            n = tags['allow_dask_compute']
            if n is True:
                n = 1000000
            elif n is False:
                n = 0
            wrapped = _dask_wrap(func, n)
            if isinstance(attr, staticmethod):
                wrapped = staticmethod(wrapped)
            elif isinstance(attr, classmethod):
                wrapped = classmethod(wrapped)
            temp_setattr(target, name, wrapped)
    elif is_jax_namespace(xp):
        for target, name, attr, func, tags in iter_tagged():
            if tags['jax_jit']:
                wrapped = jax_autojit(func)
                if isinstance(attr, staticmethod):
                    wrapped = staticmethod(wrapped)
                elif isinstance(attr, classmethod):
                    wrapped = classmethod(wrapped)
                temp_setattr(target, name, wrapped)

    @contextlib.contextmanager
    def revert_on_exit() -> Generator[None]:
        try:
            yield
        finally:
            for target, name, orig_func in to_revert:
                setattr(target, name, orig_func)
    return revert_on_exit()

def _require_numpy() -> ModuleType:
    try:
        import numpy as np
    except ImportError as e:
        msg = 'The assertion functions of `xpx.testing` require the numpy module to be importable in the Python environment.'
        raise ImportError(msg) from e
    return np

def _as_numpy_array(array: Array, *, xp: ModuleType) -> np.typing.NDArray[Any]:
    np = _require_numpy()
    if is_cupy_namespace(xp):
        return xp.asnumpy(array)
    if is_pydata_sparse_namespace(xp):
        return array.todense()
    if is_torch_namespace(xp):
        array = cast(Array, array.resolve_conj())
        array = to_device(array, 'cpu')
    if is_array_api_strict_namespace(xp):
        cpu: Device = xp.Device('CPU_DEVICE')
        array = to_device(array, cpu)
    if is_jax_namespace(xp):
        import jax
        cpu = cast(Device, jax.devices('cpu')[0])
        array = to_device(array, cpu)
    if hasattr(array, '__dlpack__'):
        try:
            return np.from_dlpack(array)
        except (TypeError, BufferError):
            pass
    return np.asarray(array)

def assert_close(actual: Array, desired: Array, *, rtol: float | Array | None=None, atol: float | Array=0, equal_nan: bool=True, err_msg: str='', verbose: bool=True, check_dtype: bool=True, check_shape: bool=True, check_scalar: bool=False, xp: ModuleType | None=None) -> None:
    actual, desired, xp, np = _check_ns_shape_dtype(actual, desired, check_dtype, check_shape, check_scalar, xp)
    if not _is_materializable(actual):
        return
    if rtol is None:
        if xp.isdtype(actual.dtype, ('real floating', 'complex floating')):
            rtol = xp.finfo(actual.dtype).eps ** 0.5 * 4
        else:
            rtol = 1e-07
    else:
        rtol = float(rtol)
    atol = float(atol)
    actual_np = _as_numpy_array(actual, xp=xp)
    desired_np = _as_numpy_array(desired, xp=xp)
    np.testing.assert_allclose(actual_np, desired_np, rtol=rtol, atol=atol, equal_nan=equal_nan, err_msg=err_msg, verbose=verbose)

