def one_hot(x: Array, /, num_classes: int, *, dtype: DType | None=None, axis: int=-1, xp: ModuleType | None=None) -> Array:
    if xp is None:
        xp = array_namespace(x)
    if not xp.isdtype(x.dtype, 'integral'):
        msg = 'x must have an integral dtype.'
        raise TypeError(msg)
    if dtype is None:
        dtype = _funcs.default_dtype(xp, device=get_device(x))
    if is_jax_namespace(xp):
        from jax.nn import one_hot as jax_one_hot
        return jax_one_hot(x, num_classes, dtype=dtype, axis=axis)
    if is_torch_namespace(xp):
        from torch.nn.functional import one_hot as torch_one_hot
        x = xp.astype(x, xp.int64)
        try:
            out = torch_one_hot(x, num_classes)
        except RuntimeError as e:
            raise IndexError from e
    else:
        out = _funcs.one_hot(x, num_classes, xp=xp)
    out = xp.astype(out, dtype, copy=False)
    if axis != -1:
        out = xp.moveaxis(out, -1, axis)
    return out

def pad(x: Array, pad_width: int | tuple[int, int] | Sequence[tuple[int, int]], mode: Literal['constant']='constant', *, constant_values: complex=0, xp: ModuleType | None=None) -> Array:
    xp = array_namespace(x) if xp is None else xp
    if mode != 'constant':
        msg = "Only `'constant'` mode is currently supported"
        raise NotImplementedError(msg)
    if is_numpy_namespace(xp) or is_cupy_namespace(xp) or is_jax_namespace(xp) or is_pydata_sparse_namespace(xp):
        return xp.pad(x, pad_width, mode, constant_values=constant_values)
    if is_torch_namespace(xp):
        pad_width = xp.asarray(pad_width)
        pad_width = xp.broadcast_to(pad_width, (x.ndim, 2))
        pad_width = xp.flip(pad_width, axis=(0,)).flatten()
        return xp.nn.functional.pad(x, tuple(pad_width), value=constant_values)
    return _funcs.pad(x, pad_width, constant_values=constant_values, xp=xp)

def searchsorted(x1: Array, x2: Array, /, *, side: Literal['left', 'right']='left', xp: ModuleType | None=None) -> Array:
