def partition(a: Array, kth: int, /, axis: int | None=-1, *, xp: ModuleType | None=None) -> Array:
    if xp is None:
        xp = array_namespace(a)
    if a.ndim < 1:
        msg = '`a` must be at least 1-dimensional'
        raise TypeError(msg)
    if axis is None:
        return partition(xp.reshape(a, (-1,)), kth, axis=0, xp=xp)
    size, = eager_shape(a, axis)
    if not 0 <= kth < size:
        msg = f'kth(={kth}) out of bounds [0 {size})'
        raise ValueError(msg)
    if is_numpy_namespace(xp) or is_cupy_namespace(xp) or is_jax_namespace(xp):
        return xp.partition(a, kth, axis=axis)
    if is_torch_namespace(xp):
        if not (axis == -1 or axis == a.ndim - 1):
            a = xp.transpose(a, axis, -1)
        out = xp.empty_like(a)
        ranks = xp.arange(a.shape[-1]).expand_as(a)
        split_value, indices = xp.kthvalue(a, kth + 1, keepdim=True)
        del indices
        mask_src = a < split_value
        n_left = mask_src.sum(dim=-1, keepdim=True)
        mask_dest = ranks < n_left
        out[mask_dest] = a[mask_src]
        mask_src = a == split_value
        n_left += mask_src.sum(dim=-1, keepdim=True)
        mask_dest ^= ranks < n_left
        out[mask_dest] = a[mask_src]
        mask_src = a > split_value
        mask_dest = ranks >= n_left
        out[mask_dest] = a[mask_src]
        if not (axis == -1 or axis == a.ndim - 1):
            out = xp.transpose(out, axis, -1)
        return out
    return _funcs.partition(a, kth, axis=axis, xp=xp)

def argpartition(a: Array, kth: int, /, axis: int | None=-1, *, xp: ModuleType | None=None) -> Array:
    if xp is None:
        xp = array_namespace(a)
    if is_pydata_sparse_namespace(xp):
        msg = 'Not implemented for sparse backend: no argsort'
        raise NotImplementedError(msg)
    if a.ndim < 1:
        msg = '`a` must be at least 1-dimensional'
        raise TypeError(msg)
    if axis is None:
        return argpartition(xp.reshape(a, (-1,)), kth, axis=0, xp=xp)
    size, = eager_shape(a, axis)
    if not 0 <= kth < size:
        msg = f'kth(={kth}) out of bounds [0 {size})'
        raise ValueError(msg)
    if is_numpy_namespace(xp) or is_cupy_namespace(xp) or is_jax_namespace(xp):
        return xp.argpartition(a, kth, axis=axis)
    if is_torch_namespace(xp):
        if not (axis == -1 or axis == a.ndim - 1):
            a = xp.transpose(a, axis, -1)
        ranks = xp.arange(a.shape[-1]).expand_as(a)
        out = xp.empty_like(ranks)
        split_value, indices = xp.kthvalue(a, kth + 1, keepdim=True)
        del indices
        mask_src = a < split_value
        n_left = mask_src.sum(dim=-1, keepdim=True)
        mask_dest = ranks < n_left
        out[mask_dest] = ranks[mask_src]
        mask_src = a == split_value
        n_left += mask_src.sum(dim=-1, keepdim=True)
        mask_dest ^= ranks < n_left
        out[mask_dest] = ranks[mask_src]
        mask_src = a > split_value
        mask_dest = ranks >= n_left
        out[mask_dest] = ranks[mask_src]
        if not (axis == -1 or axis == a.ndim - 1):
            out = xp.transpose(out, axis, -1)
        return out
    return _funcs.argpartition(a, kth, axis=axis, xp=xp)

def isin(a: Array, b: Array, /, *, assume_unique: bool=False, invert: bool=False, kind: str | None=None, xp: ModuleType | None=None) -> Array:
    if xp is None:
        xp = array_namespace(a, b)
    if is_numpy_namespace(xp):
        return xp.isin(a, b, assume_unique=assume_unique, invert=invert, kind=kind)
    if is_jax_namespace(xp):
        if kind is None:
            kind = 'auto'
        return xp.isin(a, b, assume_unique=assume_unique, invert=invert, method=kind)
    if is_cupy_namespace(xp) or is_torch_namespace(xp) or is_dask_namespace(xp):
        return xp.isin(a, b, assume_unique=assume_unique, invert=invert)
    return _funcs.isin(a, b, assume_unique=assume_unique, invert=invert, xp=xp)

def union1d(a: Array, b: Array, /, *, xp: ModuleType | None=None) -> Array:
    if xp is None:
        xp = array_namespace(a, b)
    if is_numpy_namespace(xp) or is_cupy_namespace(xp) or is_dask_namespace(xp) or is_jax_namespace(xp):
        return xp.union1d(a, b)
    return _funcs.union1d(a, b, xp=xp)

def __getitem__(self, idx: SetIndex, /) -> Self:
    if self._idx is not _undef:
        msg = 'Index has already been set'
        raise ValueError(msg)
    return type(self)(self._x, idx)

def _op(self, at_op: _AtOp, in_place_op: Callable[[Array, Array | complex], Array] | None, out_of_place_op: Callable[[Array, Array], Array] | None, y: Array | complex, /, copy: bool | None, xp: ModuleType | None) -> Array:
    from ._funcs import apply_where
    x, idx = (self._x, self._idx)
    xp = array_namespace(x, y) if xp is None else xp
    if isinstance(idx, Undef):
        msg = 'Index has not been set.\nUsage: either\n    at(x, idx).set(value)\nor\n    at(x)[idx].set(value)\n(same for all other methods).'
        raise ValueError(msg)
    if copy not in (True, False, None):
        msg = f'copy must be True, False, or None; got {copy!r}'
        raise ValueError(msg)
    writeable = None if copy else is_writeable_array(x)
    if (is_dask_array(idx) or is_jax_array(idx)) and idx.dtype == xp.bool and (idx.shape == x.shape):
        y_xp = xp.asarray(y, dtype=x.dtype, device=_compat.device(x))
        if y_xp.ndim == 0:
            if out_of_place_op:
                out = apply_where(idx, (x, y_xp), out_of_place_op, fill_value=x, xp=xp)
                out = xp.astype(out, x.dtype, copy=False)
            else:
                out = xp.where(idx, y_xp, x)
            if copy is False:
                x[()] = out
                return x
            return out
    if copy or (copy is None and (not writeable)):
        if is_jax_array(x):
            func = cast(Callable[[Array | complex], Array], getattr(x.at[idx], at_op.value))
            out = func(y)
            return xp.astype(out, x.dtype, copy=False)
        x = xp.asarray(x, copy=True)
        assert not writeable
        writeable = None
    if writeable is None:
        writeable = is_writeable_array(x)
    if not writeable:
        msg = f"Can't update read-only array {x}"
        raise ValueError(msg)
    if is_torch_array(y):
        y = xp.astype(y, x.dtype, copy=False)
    if in_place_op:
        x[idx] = in_place_op(x[idx], y)
    else:
        x[idx] = y
    return x

def min(self, y: Array | complex, /, copy: bool | None=None, xp: ModuleType | None=None) -> Array:
    xp = array_namespace(self._x) if xp is None else xp
    mxp = meta_namespace(self._x, xp=xp)
    y = xp.asarray(y)
    return self._op(_AtOp.MIN, mxp.minimum, mxp.minimum, y, copy=copy, xp=xp)

def max(self, y: Array | complex, /, copy: bool | None=None, xp: ModuleType | None=None) -> Array:
    xp = array_namespace(self._x) if xp is None else xp
    mxp = meta_namespace(self._x, xp=xp)
    y = xp.asarray(y)
    return self._op(_AtOp.MAX, mxp.maximum, mxp.maximum, y, copy=copy, xp=xp)

@property
def modname(self) -> str:
    return self.value.split(':')[0]

def pytest_param(self) -> Any:
    id_ = self.name.lower().replace('_gpu', ':gpu').replace('_readonly', ':readonly')
    marks = []
    if self.like(Backend.ARRAY_API_STRICT):
        marks.append(pytest.mark.skipif(NUMPY_VERSION < (1, 26), reason='array_api_strict is untested on NumPy <1.26'))
    if self.like(Backend.DASK, Backend.JAX):
        marks.append(pytest.mark.thread_unsafe)
    return pytest.param(self, id=id_, marks=marks)

def apply_where(cond: Array, args: Array | tuple[Array, ...], f1: Callable[..., Array], f2: Callable[..., Array] | None=None, /, *, fill_value: Array | complex | None=None, kwargs: dict[str, Array] | None=None, xp: ModuleType | None=None) -> Array:
    if (f2 is None) == (fill_value is None):
        msg = 'Exactly one of `fill_value` or `f2` must be given.'
        raise TypeError(msg)
    args_ = list(args) if isinstance(args, tuple) else [args]
    del args
    kwargs_ = {} if kwargs is None else kwargs
    kwkeys = list(kwargs_.keys())
    args_ = [*args_, *kwargs_.values()]
    del kwargs
    xp = array_namespace(cond, fill_value, *args_) if xp is None else xp
    if isinstance(fill_value, int | float | complex | NoneType):
        cond, *args_ = xp.broadcast_arrays(cond, *args_)
    else:
        cond, fill_value, *args_ = xp.broadcast_arrays(cond, fill_value, *args_)
    if is_dask_namespace(xp):
        meta_xp = meta_namespace(cond, fill_value, *args_, xp=xp)
        return xp.map_blocks(_apply_where, cond, f1, f2, fill_value, *args_, kwkeys=kwkeys, xp=meta_xp)
    return _apply_where(cond, f1, f2, fill_value, *args_, kwkeys=kwkeys, xp=xp)

def _apply_where(cond: Array, f1: Callable[..., Array], f2: Callable[..., Array] | None, fill_value: Array | int | float | complex | bool | None, *args: Array, kwkeys: list[str], xp: ModuleType) -> Array:
    nargs = len(args) - len(kwkeys)
    kwargs = dict(zip(kwkeys, args[nargs:], strict=True))
    args = args[:nargs]
    if not capabilities(xp, device=_compat.device(cond))['boolean indexing']:
        return xp.where(cond, f1(*args, **kwargs), f2(*args, **kwargs) if f2 is not None else fill_value)
    temp1 = f1(*(arr[cond] for arr in args), **{key: val[cond] for key, val in kwargs.items()})
    if f2 is None:
        dtype = xp.result_type(temp1, fill_value)
        if isinstance(fill_value, int | float | complex):
            out = xp.full_like(cond, dtype=dtype, fill_value=fill_value)
        else:
            out = xp.astype(fill_value, dtype, copy=True)
    else:
        ncond = ~cond
        temp2 = f2(*(arr[ncond] for arr in args), **{key: val[ncond] for key, val in kwargs.items()})
        dtype = xp.result_type(temp1, temp2)
        out = xp.empty_like(cond, dtype=dtype)
        out = at(out, ncond).set(temp2)
    return at(out, cond).set(temp1)

def atleast_nd(x: Array, /, *, ndim: int, xp: ModuleType) -> Array:
    if x.ndim < ndim:
        x = xp.expand_dims(x, axis=0)
        x = atleast_nd(x, ndim=ndim, xp=xp)
    return x

def broadcast_shapes(*shapes: tuple[float | None, ...]) -> tuple[int | None, ...]:
    if not shapes:
        return ()
    ndim = max((len(shape) for shape in shapes))
    out: list[int | None] = []
    for axis in range(-ndim, 0):
        sizes = {shape[axis] for shape in shapes if axis >= -len(shape)}
        none_size = None in sizes or math.nan in sizes
        sizes -= {1, None, math.nan}
        if len(sizes) > 1:
            msg = f'shape mismatch: objects cannot be broadcast to a single shape: {shapes}.'
            raise ValueError(msg)
        out.append(None if none_size else cast(int, sizes.pop()) if sizes else 1)
    return tuple(out)

def one_hot(x: Array, /, num_classes: int, *, xp: ModuleType) -> Array:
    range_num_classes = xp.arange(num_classes, dtype=x.dtype, device=_compat.device(x))
    return x[..., xp.newaxis] == range_num_classes

def create_diagonal(x: Array, /, *, offset: int=0, xp: ModuleType) -> Array:
    x_shape = eager_shape(x)
    batch_dims = x_shape[:-1]
    n = x_shape[-1] + abs(offset)
    diag = xp.zeros((*batch_dims, n ** 2), dtype=x.dtype, device=_compat.device(x))
    target_slice = slice(offset if offset >= 0 else abs(offset) * n, min(n * (n - offset), diag.shape[-1]), n + 1)
    for index in ndindex(*batch_dims):
        diag = at(diag)[*index, target_slice].set(x[*index, slice(None)])
    return xp.reshape(diag, (*batch_dims, n, n))

def default_dtype(xp: ModuleType, kind: Literal['real floating', 'complex floating', 'integral', 'indexing']='real floating', *, device: Device | None=None) -> DType:
    dtypes = xp.__array_namespace_info__().default_dtypes(device=device)
    try:
        return dtypes[kind]
    except KeyError as e:
        domain = ('real floating', 'complex floating', 'integral', 'indexing')
        assert set(dtypes) == set(domain), f'Non-compliant namespace: {dtypes}'
        msg = f"Unknown kind '{kind}'. Expected one of {domain}."
        raise ValueError(msg) from e

def expand_dims(a: Array, /, *, axis: tuple[int, ...]=(0,), xp: ModuleType) -> Array:
    for i in sorted(axis):
        a = xp.expand_dims(a, axis=i)
    return a

def isclose(a: Array | complex, b: Array | complex, *, rtol: float=1e-05, atol: float=1e-08, equal_nan: bool=False, xp: ModuleType) -> Array:
    a, b = asarrays(a, b, xp=xp)
    a_inexact = xp.isdtype(a.dtype, ('real floating', 'complex floating'))
    b_inexact = xp.isdtype(b.dtype, ('real floating', 'complex floating'))
    if a_inexact or b_inexact:
        mxp = meta_namespace(a, b, xp=xp)
        out = apply_where(xp.isinf(a) | xp.isinf(b), (a, b), lambda a, b: mxp.isinf(a) & mxp.isinf(b) & (mxp.sign(a) == mxp.sign(b)), lambda a, b: mxp.abs(a - b) <= atol + rtol * mxp.abs(b), xp=xp)
        if equal_nan:
            out = xp.where(xp.isnan(a) & xp.isnan(b), True, out)
        return out
    if xp.isdtype(a.dtype, 'bool') or xp.isdtype(b.dtype, 'bool'):
        if atol >= 1 or rtol >= 1:
            return xp.ones_like(a == b)
        return a == b
    atol = int(atol)
    if rtol == 0:
        return xp.abs(a - b) <= atol
    nrtol = int(1.0 / rtol)
    if nrtol > xp.iinfo(b.dtype).max:
        return xp.abs(a - b) <= atol
    return xp.abs(a - b) <= atol + xp.abs(b) // nrtol

def nan_to_num(x: Array, /, fill_value: int | float=0.0, *, xp: ModuleType) -> Array:

    def perform_replacements(x: Array, fill_value: int | float, xp: ModuleType) -> Array:
        """Internal function to perform the replacements."""
        x = xp.where(xp.isnan(x), fill_value, x)
        finfo = xp.finfo(x.dtype)
        idx_posinf = xp.isinf(x) & ~xp.signbit(x)
        idx_neginf = xp.isinf(x) & xp.signbit(x)
        x = xp.where(idx_posinf, finfo.max, x)
        return xp.where(idx_neginf, finfo.min, x)
    if xp.isdtype(x.dtype, 'complex floating'):
        return perform_replacements(xp.real(x), fill_value, xp) + 1j * perform_replacements(xp.imag(x), fill_value, xp)
    if xp.isdtype(x.dtype, 'numeric'):
        return perform_replacements(x, fill_value, xp)
    return x

def nunique(x: Array, /, *, xp: ModuleType | None=None) -> Array:
    if xp is None:
        xp = array_namespace(x)
    if is_jax_array(x):
        _, counts = xp.unique_counts(x, size=_compat.size(x))
        return (counts > 0).sum()
    if capabilities(xp, device=_compat.device(x))['data-dependent shapes']:
        _, counts = xp.unique_counts(x)
        n = _compat.size(counts)
        if n is None:
            return xp.sum(xp.ones_like(counts))
        return xp.asarray(n, device=_compat.device(x))
    x = xp.reshape(x, (-1,))
    x = xp.sort(x, stable=False)
    mask = x != xp.roll(x, -1)
    default_int = default_dtype(xp, 'integral', device=_compat.device(x))
    return xp.maximum(xp.astype(xp.any(~mask), default_int), xp.sum(xp.astype(mask, default_int)))

def pad(x: Array, pad_width: int | tuple[int, int] | Sequence[tuple[int, int]], *, constant_values: complex=0, xp: ModuleType) -> Array:
    if isinstance(pad_width, int):
        pad_width_seq = [(pad_width, pad_width)] * x.ndim
    elif isinstance(pad_width, tuple) and len(pad_width) == 2 and all((isinstance(i, int) for i in pad_width)):
        pad_width_seq = [cast(tuple[int, int], pad_width)] * x.ndim
    else:
        pad_width_seq = cast(list[tuple[int, int]], list(pad_width))
    slices: list[slice] = []
    newshape: list[int] = []
    for ax, w_tpl in enumerate(pad_width_seq):
        if len(w_tpl) != 2:
            msg = f'expect a 2-tuple (before, after), got {w_tpl}.'
            raise ValueError(msg)
        sh = eager_shape(x)[ax]
        if w_tpl[0] == 0 and w_tpl[1] == 0:
            sl = slice(None, None, None)
        else:
            stop: int | None
            start, stop = w_tpl
            stop = None if stop == 0 else -stop
            sl = slice(start, stop, None)
            sh += w_tpl[0] + w_tpl[1]
        newshape.append(sh)
        slices.append(sl)
    padded = xp.full(tuple(newshape), fill_value=constant_values, dtype=x.dtype, device=_compat.device(x))
    return at(padded, tuple(slices)).set(x)

def setdiff1d(x1: Array | complex, x2: Array | complex, /, *, assume_unique: bool=False, xp: ModuleType) -> Array:
    x1_, x2_ = asarrays(x1, x2, xp=xp)
    if assume_unique:
        x1_ = xp.reshape(x1_, (-1,))
        x2_ = xp.reshape(x2_, (-1,))
    else:
        x1_ = xp.unique_values(x1_)
        x2_ = xp.unique_values(x2_)
    return x1_[_helpers.in1d(x1_, x2_, assume_unique=True, invert=True, xp=xp)]

def sinc(x: Array, /, *, xp: ModuleType) -> Array:
    y = xp.pi * xp.where(xp.astype(x, xp.bool), x, xp.asarray(xp.finfo(x.dtype).eps, dtype=x.dtype, device=_compat.device(x)))
    return xp.sin(y) / y

def isin(a: Array, b: Array, /, *, assume_unique: bool=False, invert: bool=False, xp: ModuleType) -> Array:
    original_a_shape = a.shape
    a = xp.reshape(a, (-1,))
    b = xp.reshape(b, (-1,))
    return xp.reshape(_helpers.in1d(a, b, assume_unique=assume_unique, invert=invert, xp=xp), original_a_shape)

def union1d(a: Array, b: Array, /, *, xp: ModuleType) -> Array:
    a = xp.reshape(a, (-1,))
    b = xp.reshape(b, (-1,))
    return xp.asarray(xp.unique_values(xp.concat([a, b])))

def angle(z: Array, /, *, deg: bool=False, xp: ModuleType | None=None) -> Array:
    if xp is None:
        xp = array_namespace(z)
    if xp.isdtype(z.dtype, 'complex floating'):
        zimag = xp.imag(z)
        zreal = xp.real(z)
    else:
        if not xp.isdtype(z.dtype, 'real floating'):
            z = xp.astype(z, default_dtype(xp, device=_compat.device(z)))
        zimag = xp.zeros_like(z)
        zreal = z
    a = xp.atan2(zimag, zreal)
    if deg:
        a = a * 180 / xp.pi
    return a

def _is_jax_jit_enabled(xp: ModuleType) -> bool:
    import jax
    x = xp.asarray(False)
    try:
        return bool(x)
    except jax.errors.TracerBoolConversionError:
        return True

def _lazy_apply_wrapper(func: Callable[..., Array | ArrayLike | Sequence[Array | ArrayLike]], as_numpy: bool, multi_output: bool, xp: ModuleType) -> Callable[..., tuple[Array, ...]]:

    @wraps(func)
    def wrapper(*args: Array | complex | None, **kwargs: Any) -> tuple[Array, ...]:
        args_list = []
        device = None
        for arg in args:
            if arg is not None and (not is_python_scalar(arg)):
                if device is None:
                    device = _compat.device(arg)
                if as_numpy:
                    import numpy as np
                    arg = cast(Array, np.asarray(arg))
            args_list.append(arg)
        assert device is not None
        out = func(*args_list, **kwargs)
        if multi_output:
            assert isinstance(out, Sequence)
            return tuple((xp.asarray(o, device=device) for o in out))
        return (xp.asarray(out, device=device),)
    return wrapper

def xfail(request: pytest.FixtureRequest, *, reason: str, strict: bool | None=None) -> None:
    if strict is not None:
        marker = pytest.mark.xfail(reason=reason, strict=strict)
    else:
        marker = pytest.mark.xfail(reason=reason)
    request.node.add_marker(marker)

def in1d(x1: Array, x2: Array, /, *, assume_unique: bool=False, invert: bool=False, xp: ModuleType | None=None) -> Array:
    if xp is None:
        xp = array_namespace(x1, x2)
    x1_shape = eager_shape(x1)
    x2_shape = eager_shape(x2)
    if x2_shape[0] < 10 * x1_shape[0] ** 0.145 and isinstance(x2, Iterable):
        if invert:
            mask = xp.ones(x1_shape[0], dtype=xp.bool, device=_compat.device(x1))
            for a in x2:
                mask &= x1 != a
        else:
            mask = xp.zeros(x1_shape[0], dtype=xp.bool, device=_compat.device(x1))
            for a in x2:
                mask |= x1 == a
        return mask
    rev_idx = xp.empty(0)
    if not assume_unique:
        x1, rev_idx = xp.unique_inverse(x1)
        x2 = xp.unique_values(x2)
    ar = xp.concat((x1, x2))
    device_ = _compat.device(ar)
    order = xp.argsort(ar, stable=True)
    reverse_order = xp.argsort(order, stable=True)
    sar = xp.take(ar, order, axis=0)
    ar_size = _compat.size(sar)
    assert ar_size is not None, 'xp.unique*() on lazy backends raises'
    if ar_size >= 1:
        bool_ar = sar[1:] != sar[:-1] if invert else sar[1:] == sar[:-1]
    else:
        bool_ar = xp.asarray([False]) if invert else xp.asarray([True])
    flag = xp.concat((bool_ar, xp.asarray([invert], device=device_)))
    ret = xp.take(flag, reverse_order, axis=0)
    if assume_unique:
        return ret[:x1.shape[0]]
    return xp.take(ret, rev_idx, axis=0)

def asarrays(a: Array | complex, b: Array | complex, xp: ModuleType) -> tuple[Array, Array]:
    a_scalar = is_python_scalar(a)
    b_scalar = is_python_scalar(b)
    if not a_scalar and (not b_scalar):
        return (a, b)
    swap = False
    if a_scalar:
        swap = True
        b, a = (a, b)
    if is_array_api_obj(a):
        xa = a
        same_dtype = {bool: 'bool', int: ('integral', 'real floating', 'complex floating'), float: ('real floating', 'complex floating'), complex: 'complex floating'}
        kind = same_dtype[type(cast(complex, b))]
        if xp.isdtype(a.dtype, kind):
            xb = xp.asarray(b, dtype=a.dtype, device=_compat.device(a))
        else:
            xb = xp.asarray(b, device=_compat.device(a))
    else:
        xa, xb = (xp.asarray(a), xp.asarray(b))
    return (xb, xa) if swap else (xa, xb)

def ndindex(*x: int) -> Generator[tuple[int, ...]]:
    if not x:
        yield ()
        return
    for i in ndindex(*x[:-1]):
        for j in range(x[-1]):
            yield (*i, j)

def eager_shape(x: Array, /, axis: int | None=None) -> tuple[int, ...]:
    shape = x.shape
    if axis is not None:
        s = shape[axis]
        if s is None or math.isnan(s):
            msg = f'Unsupported lazy shape for axis {axis}'
            raise TypeError(msg)
        return (s,)
    if any((s is None or math.isnan(s) for s in shape)):
        msg = 'Unsupported lazy shape'
        raise TypeError(msg)
    return cast(tuple[int, ...], shape)

def meta_namespace(*arrays: Array | complex | None, xp: ModuleType | None=None) -> ModuleType:
    xp = array_namespace(*arrays) if xp is None else xp
    if not is_dask_namespace(xp):
        return xp
    metas = [cast(Array | None, getattr(a, '_meta', None)) for a in arrays]
    return array_namespace(*metas)

def capabilities(xp: ModuleType, *, device: Device | None=None) -> dict[str, int | None]:
    out = xp.__array_namespace_info__().capabilities()
    if is_jax_namespace(xp):
        if out['boolean indexing']:
            out = out.copy()
            out['boolean indexing'] = False
    elif is_torch_namespace(xp):
        device = xp.get_default_device() if device is None else xp.device(device)
        if device.type == 'meta':
            out = out.copy()
            out['boolean indexing'] = False
            out['data-dependent shapes'] = False
    return out

def pickle_flatten(obj: object, cls: type[T] | tuple[type[T], ...]) -> tuple[list[T], FlattenRest]:
    instances: list[T] = []
    rest: list[object] = []

    class Pickler(pickle.Pickler):
        """
        Use the `pickle.Pickler.persistent_id` hook to extract objects.
        """

        @override
        def persistent_id(self, obj: object) -> Literal[0, 1, None]:
            if isinstance(obj, cls):
                instances.append(obj)
                return 0
            typ_ = type(obj)
            if typ_ in _BASIC_PICKLED_TYPES:
                return None
            if typ_ in _BASIC_REST_TYPES:
                rest.append(obj)
                return 1
            try:
                _ = obj.__reduce_ex__(pickle.HIGHEST_PROTOCOL)
            except Exception:
                rest.append(obj)
                return 1
            return None
    f = io.BytesIO()
    p = Pickler(f, protocol=pickle.HIGHEST_PROTOCOL)
    p.dump(obj)
    return (instances, (f.getvalue(), *rest))

def pickle_unflatten(instances: Iterable[object], rest: FlattenRest) -> Any:
    iters = (iter(instances), iter(rest))
    pik = cast(bytes, next(iters[1]))

    class Unpickler(pickle.Unpickler):
        """Mirror of the overridden Pickler in pickle_flatten."""

        @override
        def persistent_load(self, pid: Literal[0, 1]) -> object:
            try:
                return next(iters[pid])
            except StopIteration as e:
                msg = 'Not enough objects to unpickle'
                raise ValueError(msg) from e
    f = io.BytesIO(pik)
    return Unpickler(f).load()

def jax_autojit(func: Callable[P, T]) -> Callable[P, T]:
    import jax

    @jax.jit
    def inner(wargs: _AutoJITWrapper[Any]) -> _AutoJITWrapper[T]:
        args, kwargs = wargs.obj
        res = func(*args, **kwargs)
        return _AutoJITWrapper(res)

    @wraps(func)
    def outer(*args: P.args, **kwargs: P.kwargs) -> T:
        wargs = _AutoJITWrapper((args, kwargs))
        return inner(wargs).obj
    return outer

@property
def obj(self) -> T:
    return iter(self._obj) if self._is_iter else self._obj

@classmethod
def _register(cls) -> None:
    if not cls._registered:
        import jax
        jax.tree_util.register_pytree_node(cls, lambda instance: pickle_flatten(instance, jax.Array), lambda aux_data, children: pickle_unflatten(children, aux_data))
        cls._registered = True

def strip_blank_lines(l):
    while l and (not l[0].strip()):
        del l[0]
    while l and (not l[-1].strip()):
        del l[-1]
    return l

def __init__(self, data):
    if isinstance(data, list):
        self._str = data
    else:
        self._str = data.split('\n')
    self.reset()

def _parse_see_also(self, content):
    content = dedent_lines(content)
    items = []

    def parse_item_name(text):
        """Match ':role:`name`' or 'name'."""
        m = self._func_rgx.match(text)
        if not m:
            self._error_location(f'Error parsing See Also entry {line!r}')
        role = m.group('role')
        name = m.group('name') if role else m.group('name2')
        return (name, role, m.end())
    rest = []
    for line in content:
        if not line.strip():
            continue
        line_match = self._line_rgx.match(line)
        description = None
        if line_match:
            description = line_match.group('desc')
            if line_match.group('trailing') and description:
                self._error_location('Unexpected comma or period after function list at index %d of line "%s"' % (line_match.end('trailing'), line), error=False)
        if not description and line.startswith(' '):
            rest.append(line.strip())
        elif line_match:
            funcs = []
            text = line_match.group('allfuncs')
            while True:
                if not text.strip():
                    break
                name, role, match_end = parse_item_name(text)
                funcs.append((name, role))
                text = text[match_end:].strip()
                if text and text[0] == ',':
                    text = text[1:].strip()
            rest = list(filter(None, [description]))
            items.append((funcs, rest))
        else:
            self._error_location(f'Error parsing See Also entry {line!r}')
    return items

def _parse_index(self, section, content):

    def strip_each_in(lst):
        return [s.strip() for s in lst]
    out = {}
    section = section.split('::')
    if len(section) > 1:
        out['default'] = strip_each_in(section[1].split(','))[0]
    for line in content:
        line = line.split(':')
        if len(line) > 2:
            out[line[1]] = strip_each_in(line[2].split(','))
    return out

def _parse_summary(self):
    if self._is_at_section():
        return
    while True:
        summary = self._doc.read_to_next_empty_line()
        summary_str = ' '.join([s.strip() for s in summary]).strip()
        compiled = re.compile('^([\\w., ]+=)?\\s*[\\w\\.]+\\(.*\\)$')
        if compiled.match(summary_str):
            self['Signature'] = summary_str
            if not self._is_at_section():
                continue
        break
    if summary is not None:
        self['Summary'] = summary
    if not self._is_at_section():
        self['Extended Summary'] = self._read_to_next_section()

def parse_item_name(text):
    m = self._func_rgx.match(text)
    if not m:
        self._error_location(f'Error parsing See Also entry {line!r}')
    role = m.group('role')
    name = m.group('name') if role else m.group('name2')
    return (name, role, m.end())

def parse(version: str) -> Union['LegacyVersion', 'Version']:
    try:
        return Version(version)
    except InvalidVersion:
        return LegacyVersion(version)

def _parse_local_version(local: str) -> Optional[LocalType]:
    if local is not None:
        return tuple((part.lower() if not part.isdigit() else int(part) for part in _local_version_separators.split(local)))
    return None

def laplacian(csgraph, normed=False, return_diag=False, use_out_degree=False, *, copy=True, form='array', dtype=None, symmetrized=False):
    if csgraph.ndim != 2 or csgraph.shape[0] != csgraph.shape[1]:
        raise ValueError('csgraph must be a square matrix or array')
    if normed and (np.issubdtype(csgraph.dtype, np.signedinteger) or np.issubdtype(csgraph.dtype, np.uint)):
        csgraph = csgraph.astype(np.float64)
    if form == 'array':
        create_lap = _laplacian_sparse if issparse(csgraph) else _laplacian_dense
    else:
        create_lap = _laplacian_sparse_flo if issparse(csgraph) else _laplacian_dense_flo
    degree_axis = 1 if use_out_degree else 0
    lap, d = create_lap(csgraph, normed=normed, axis=degree_axis, copy=copy, form=form, dtype=dtype, symmetrized=symmetrized)
    if return_diag:
        return (lap, d)
    return lap

def _mask_edges_weights(mask, edges, weights=None):
    inds = np.arange(mask.size)
    inds = inds[mask.ravel()]
    ind_mask = np.logical_and(np.isin(edges[0], inds), np.isin(edges[1], inds))
    edges = edges[:, ind_mask]
    if weights is not None:
        weights = weights[ind_mask]
    if len(edges.ravel()):
        maxval = edges.max()
    else:
        maxval = 0
    order = np.searchsorted(np.flatnonzero(mask), np.arange(maxval + 1))
    edges = order[edges]
    if weights is None:
        return edges
    else:
        return (edges, weights)

def _to_graph(n_x, n_y, n_z, mask=None, img=None, return_as=sparse.coo_array, dtype=None):
    edges = _make_edges_3d(n_x, n_y, n_z)
    if dtype is None:
        if img is None:
            dtype = int
        else:
            dtype = img.dtype
    if img is not None:
        img = np.atleast_3d(img)
        weights = _compute_gradient_3d(edges, img)
        if mask is not None:
            edges, weights = _mask_edges_weights(mask, edges, weights)
            diag = img.squeeze()[mask]
        else:
            diag = img.ravel()
        n_voxels = diag.size
    else:
        if mask is not None:
            mask = mask.astype(dtype=bool, copy=False)
            edges = _mask_edges_weights(mask, edges)
            n_voxels = np.sum(mask)
        else:
            n_voxels = n_x * n_y * n_z
        weights = np.ones(edges.shape[1], dtype=dtype)
        diag = np.ones(n_voxels, dtype=dtype)
    diag_idx = np.arange(n_voxels)
    i_idx = np.hstack((edges[0], edges[1]))
    j_idx = np.hstack((edges[1], edges[0]))
    graph = sparse.coo_array((np.hstack((weights, weights, diag)), (np.hstack((i_idx, diag_idx)), np.hstack((j_idx, diag_idx)))), (n_voxels, n_voxels), dtype=dtype)
    if return_as is np.ndarray:
        return graph.toarray()
    return _align_api_if_sparse(return_as(graph))

@validate_params({'img': ['array-like'], 'mask': [None, np.ndarray], 'return_as': [type], 'dtype': 'no_validation'}, prefer_skip_nested_validation=True)
def img_to_graph(img, *, mask=None, return_as=sparse.coo_array, dtype=None):
    img = np.atleast_3d(img)
    n_x, n_y, n_z = img.shape
    return _to_graph(n_x, n_y, n_z, mask, img, return_as, dtype)

@validate_params({'n_x': [Interval(Integral, left=1, right=None, closed='left')], 'n_y': [Interval(Integral, left=1, right=None, closed='left')], 'n_z': [Interval(Integral, left=1, right=None, closed='left')], 'mask': [None, np.ndarray], 'return_as': [type], 'dtype': 'no_validation'}, prefer_skip_nested_validation=True)
def grid_to_graph(n_x, n_y, n_z=1, *, mask=None, return_as=sparse.coo_array, dtype=int):
    return _to_graph(n_x, n_y, n_z, mask=mask, return_as=return_as, dtype=dtype)

def _compute_n_patches(i_h, i_w, p_h, p_w, max_patches=None):
    n_h = i_h - p_h + 1
    n_w = i_w - p_w + 1
    all_patches = n_h * n_w
    if max_patches:
        if isinstance(max_patches, Integral) and max_patches < all_patches:
            return max_patches
        elif isinstance(max_patches, Integral) and max_patches >= all_patches:
            return all_patches
        elif isinstance(max_patches, Real) and 0 < max_patches < 1:
            return int(max_patches * all_patches)
        else:
            raise ValueError('Invalid value for max_patches: %r' % max_patches)
    else:
        return all_patches

@validate_params({'image': [np.ndarray], 'patch_size': [tuple, list], 'max_patches': [Interval(RealNotInt, 0, 1, closed='neither'), Interval(Integral, 1, None, closed='left'), None], 'random_state': ['random_state']}, prefer_skip_nested_validation=True)
def extract_patches_2d(image, patch_size, *, max_patches=None, random_state=None):
    i_h, i_w = image.shape[:2]
    p_h, p_w = patch_size
    if p_h > i_h:
        raise ValueError('Height of the patch should be less than the height of the image.')
    if p_w > i_w:
        raise ValueError('Width of the patch should be less than the width of the image.')
    image = check_array(image, allow_nd=True)
    image = image.reshape((i_h, i_w, -1))
    n_colors = image.shape[-1]
    extracted_patches = _extract_patches(image, patch_shape=(p_h, p_w, n_colors), extraction_step=1)
    n_patches = _compute_n_patches(i_h, i_w, p_h, p_w, max_patches)
    if max_patches:
        rng = check_random_state(random_state)
        i_s = rng.randint(i_h - p_h + 1, size=n_patches)
        j_s = rng.randint(i_w - p_w + 1, size=n_patches)
        patches = extracted_patches[i_s, j_s, 0]
    else:
        patches = extracted_patches
    patches = patches.reshape(-1, p_h, p_w, n_colors)
    if patches.shape[-1] == 1:
        return patches.reshape((n_patches, p_h, p_w))
    else:
        return patches

@validate_params({'patches': [np.ndarray], 'image_size': [tuple, Hidden(list)]}, prefer_skip_nested_validation=True)
def reconstruct_from_patches_2d(patches, image_size):
    i_h, i_w = image_size[:2]
    p_h, p_w = patches.shape[1:3]
    img = np.zeros(image_size)
    n_h = i_h - p_h + 1
    n_w = i_w - p_w + 1
    for p, (i, j) in zip(patches, product(range(n_h), range(n_w))):
        img[i:i + p_h, j:j + p_w] += p
    for i in range(i_h):
        for j in range(i_w):
            img[i, j] /= float(min(i + 1, p_h, n_h, i_h - i) * min(j + 1, p_w, n_w, i_w - j))
    return img

@_fit_context(prefer_skip_nested_validation=True)
def fit(self, X, y=None):
    return self

def _preprocess(doc, accent_function=None, lower=False):
    if lower:
        doc = doc.lower()
    if accent_function is not None:
        doc = accent_function(doc)
    return doc

def _analyze(doc, analyzer=None, tokenizer=None, ngrams=None, preprocessor=None, decoder=None, stop_words=None):
    if decoder is not None:
        doc = decoder(doc)
    if analyzer is not None:
        doc = analyzer(doc)
    else:
        if preprocessor is not None:
            doc = preprocessor(doc)
        if tokenizer is not None:
            doc = tokenizer(doc)
        if ngrams is not None:
            if stop_words is not None:
                doc = ngrams(doc, stop_words)
            else:
                doc = ngrams(doc)
    return doc

def strip_accents_unicode(s):
    try:
        s.encode('ASCII', errors='strict')
        return s
    except UnicodeEncodeError:
        normalized = unicodedata.normalize('NFKD', s)
        return ''.join([c for c in normalized if not unicodedata.combining(c)])

def strip_accents_ascii(s):
    nkfd_form = unicodedata.normalize('NFKD', s)
    return nkfd_form.encode('ASCII', 'ignore').decode('ASCII')

def _document_frequency(X):
    if sp.issparse(X) and X.format == 'csr':
        return np.bincount(X.indices, minlength=X.shape[1])
    else:
        return np.diff(X.indptr)

def decode(self, doc):
    if self.input == 'filename':
        with open(doc, 'rb') as fh:
            doc = fh.read()
    elif self.input == 'file':
        doc = doc.read()
    if isinstance(doc, bytes):
        doc = doc.decode(self.encoding, self.decode_error)
    if doc is np.nan:
        raise ValueError('np.nan is an invalid document, expected byte or unicode string.')
    return doc

def _word_ngrams(self, tokens, stop_words=None):
    if stop_words is not None:
        tokens = [w for w in tokens if w not in stop_words]
    min_n, max_n = self.ngram_range
    if max_n != 1:
        original_tokens = tokens
        if min_n == 1:
            tokens = list(original_tokens)
            min_n += 1
        else:
            tokens = []
        n_original_tokens = len(original_tokens)
        tokens_append = tokens.append
        space_join = ' '.join
        for n in range(min_n, min(max_n + 1, n_original_tokens + 1)):
            for i in range(n_original_tokens - n + 1):
                tokens_append(space_join(original_tokens[i:i + n]))
    return tokens

def _char_ngrams(self, text_document):
    text_document = self._white_spaces.sub(' ', text_document)
    text_len = len(text_document)
    min_n, max_n = self.ngram_range
    if min_n == 1:
        ngrams = list(text_document)
        min_n += 1
    else:
        ngrams = []
    ngrams_append = ngrams.append
    for n in range(min_n, min(max_n + 1, text_len + 1)):
        for i in range(text_len - n + 1):
            ngrams_append(text_document[i:i + n])
    return ngrams

def build_preprocessor(self):
    if self.preprocessor is not None:
        return self.preprocessor
    if not self.strip_accents:
        strip_accents = None
    elif callable(self.strip_accents):
        strip_accents = self.strip_accents
    elif self.strip_accents == 'ascii':
        strip_accents = strip_accents_ascii
    elif self.strip_accents == 'unicode':
        strip_accents = strip_accents_unicode
    else:
        raise ValueError('Invalid value for "strip_accents": %s' % self.strip_accents)
    return partial(_preprocess, accent_function=strip_accents, lower=self.lowercase)

def build_tokenizer(self):
    if self.tokenizer is not None:
        return self.tokenizer
    token_pattern = re.compile(self.token_pattern)
    if token_pattern.groups > 1:
        raise ValueError('More than 1 capturing group in token pattern. Only a single group should be captured.')
    return token_pattern.findall

def _check_stop_words_consistency(self, stop_words, preprocess, tokenize):
    if id(self.stop_words) == getattr(self, '_stop_words_id', None):
        return None
    try:
        inconsistent = set()
        for w in stop_words or ():
            tokens = list(tokenize(preprocess(w)))
            for token in tokens:
                if token not in stop_words:
                    inconsistent.add(token)
        self._stop_words_id = id(self.stop_words)
        if inconsistent:
            warnings.warn('Your stop_words may be inconsistent with your preprocessing. Tokenizing the stop words generated tokens %r not in stop_words.' % sorted(inconsistent))
        return not inconsistent
    except Exception:
        self._stop_words_id = id(self.stop_words)
        return 'error'

def build_analyzer(self):
    if callable(self.analyzer):
        return partial(_analyze, analyzer=self.analyzer, decoder=self.decode)
    preprocess = self.build_preprocessor()
    if self.analyzer == 'char':
        return partial(_analyze, ngrams=self._char_ngrams, preprocessor=preprocess, decoder=self.decode)
    elif self.analyzer == 'char_wb':
        return partial(_analyze, ngrams=self._char_wb_ngrams, preprocessor=preprocess, decoder=self.decode)
    elif self.analyzer == 'word':
        stop_words = self.get_stop_words()
        tokenize = self.build_tokenizer()
        self._check_stop_words_consistency(stop_words, preprocess, tokenize)
        return partial(_analyze, ngrams=self._word_ngrams, tokenizer=tokenize, preprocessor=preprocess, decoder=self.decode, stop_words=stop_words)
    else:
        raise ValueError('%s is not a valid tokenization scheme/analyzer' % self.analyzer)

def _check_vocabulary(self):
    if not hasattr(self, 'vocabulary_'):
        self._validate_vocabulary()
        if not self.fixed_vocabulary_:
            raise NotFittedError('Vocabulary not fitted or provided')
    if len(self.vocabulary_) == 0:
        raise ValueError('Vocabulary is empty')

def _validate_ngram_range(self):
    min_n, max_m = self.ngram_range
    if min_n > max_m:
        raise ValueError('Invalid value for ngram_range=%s lower boundary larger than the upper boundary.' % str(self.ngram_range))

@_fit_context(prefer_skip_nested_validation=True)
def partial_fit(self, X, y=None):
    return self

@_fit_context(prefer_skip_nested_validation=True)
def fit(self, X, y=None):
    if isinstance(X, str):
        raise ValueError('Iterable over raw text documents expected, string object received.')
    self._warn_for_unused_params()
    self._validate_ngram_range()
    self._get_hasher().fit(X, y=y)
    return self

def transform(self, X):
    if isinstance(X, str):
        raise ValueError('Iterable over raw text documents expected, string object received.')
    self._validate_ngram_range()
    analyzer = self.build_analyzer()
    X = self._get_hasher().transform((analyzer(doc) for doc in X))
    if self.binary:
        X.data.fill(1)
    if self.norm is not None:
        X = normalize(X, norm=self.norm, copy=False)
    return _align_api_if_sparse(X)

def _limit_features(self, X, vocabulary, high=None, low=None, limit=None):
    if high is None and low is None and (limit is None):
        return (X, set())
    dfs = _document_frequency(X)
    mask = np.ones(len(dfs), dtype=bool)
    if high is not None:
        mask &= dfs <= high
    if low is not None:
        mask &= dfs >= low
    if limit is not None and mask.sum() > limit:
        tfs = np.asarray(X.sum(axis=0)).ravel()
        mask_inds = (-tfs[mask]).argsort()[:limit]
        new_mask = np.zeros(len(dfs), dtype=bool)
        new_mask[np.where(mask)[0][mask_inds]] = True
        mask = new_mask
    new_indices = np.cumsum(mask) - 1
    for term, old_index in list(vocabulary.items()):
        if mask[old_index]:
            vocabulary[term] = new_indices[old_index]
        else:
            del vocabulary[term]
    kept_indices = np.where(mask)[0]
    if len(kept_indices) == 0:
        raise ValueError('After pruning, no terms remain. Try a lower min_df or a higher max_df.')
    return X[:, kept_indices]

def _count_vocab(self, raw_documents, fixed_vocab):
    if fixed_vocab:
        vocabulary = self.vocabulary_
    else:
        vocabulary = defaultdict()
        vocabulary.default_factory = vocabulary.__len__
    analyze = self.build_analyzer()
    j_indices = []
    indptr = []
    values = _make_int_array()
    indptr.append(0)
    for doc in raw_documents:
        feature_counter = {}
        for feature in analyze(doc):
            try:
                feature_idx = vocabulary[feature]
                if feature_idx not in feature_counter:
                    feature_counter[feature_idx] = 1
                else:
                    feature_counter[feature_idx] += 1
            except KeyError:
                continue
        j_indices.extend(feature_counter.keys())
        values.extend(feature_counter.values())
        indptr.append(len(j_indices))
    if not fixed_vocab:
        vocabulary = dict(vocabulary)
        if not vocabulary:
            raise ValueError('empty vocabulary; perhaps the documents only contain stop words')
    if indptr[-1] > np.iinfo(np.int32).max:
        if _IS_32BIT:
            raise ValueError('sparse CSR array has {} non-zero elements and requires 64 bit indexing, which is unsupported with 32 bit Python.'.format(indptr[-1]))
        indices_dtype = np.int64
    else:
        indices_dtype = np.int32
    j_indices = np.asarray(j_indices, dtype=indices_dtype)
    indptr = np.asarray(indptr, dtype=indices_dtype)
    values = np.frombuffer(values, dtype=np.intc)
    X = sp.csr_array((values, j_indices, indptr), shape=(len(indptr) - 1, len(vocabulary)), dtype=self.dtype)
    X.sort_indices()
    return (vocabulary, _align_api_if_sparse(X))

def fit(self, raw_documents, y=None):
    self.fit_transform(raw_documents)
    return self

@_fit_context(prefer_skip_nested_validation=True)
def fit_transform(self, raw_documents, y=None):
    if isinstance(raw_documents, str):
        raise ValueError('Iterable over raw text documents expected, string object received.')
    self._validate_ngram_range()
    self._warn_for_unused_params()
    self._validate_vocabulary()
    max_df = self.max_df
    min_df = self.min_df
    max_features = self.max_features
    if self.fixed_vocabulary_ and self.lowercase:
        for term in self.vocabulary:
            if any(map(str.isupper, term)):
                warnings.warn("Upper case characters found in vocabulary while 'lowercase' is True. These entries will not be matched with any documents")
                break
    vocabulary, X = self._count_vocab(raw_documents, self.fixed_vocabulary_)
    if self.binary:
        X.data.fill(1)
    if not self.fixed_vocabulary_:
        n_doc = X.shape[0]
        max_doc_count = max_df if isinstance(max_df, Integral) else max_df * n_doc
        min_doc_count = min_df if isinstance(min_df, Integral) else min_df * n_doc
        if max_doc_count < min_doc_count:
            raise ValueError('max_df corresponds to < documents than min_df')
        if max_features is not None:
            X = self._sort_features(X, vocabulary)
        X = self._limit_features(X, vocabulary, max_doc_count, min_doc_count, max_features)
        if max_features is None:
            X = self._sort_features(X, vocabulary)
        self.vocabulary_ = vocabulary
    return _align_api_if_sparse(X)

def transform(self, raw_documents):
    if isinstance(raw_documents, str):
        raise ValueError('Iterable over raw text documents expected, string object received.')
    self._check_vocabulary()
    _, X = self._count_vocab(raw_documents, fixed_vocab=True)
    if self.binary:
        X.data.fill(1)
    return _align_api_if_sparse(X)

def inverse_transform(self, X):
    self._check_vocabulary()
    X = check_array(X, accept_sparse='csr')
    n_samples = X.shape[0]
    terms = np.array(list(self.vocabulary_.keys()))
    indices = np.array(list(self.vocabulary_.values()))
    inverse_vocabulary = terms[np.argsort(indices)]
    if sp.issparse(X):
        if SCIPY_VERSION_BELOW_1_12:
            return [inverse_vocabulary[X[[i], :].nonzero()[-1]].ravel() for i in range(n_samples)]
        return [inverse_vocabulary[X[i, :].nonzero()[-1]].ravel() for i in range(n_samples)]
    else:
        return [inverse_vocabulary[np.flatnonzero(X[i, :])].ravel() for i in range(n_samples)]

def get_feature_names_out(self, input_features=None):
    self._check_vocabulary()
    return np.asarray([t for t, i in sorted(self.vocabulary_.items(), key=itemgetter(1))], dtype=object)

def transform(self, X, copy=True):
    check_is_fitted(self)
    X = validate_data(self, X, accept_sparse='csr', dtype=[np.float64, np.float32], copy=copy, reset=False)
    if not sp.issparse(X):
        X = sp.csr_array(X, dtype=X.dtype)
    if self.sublinear_tf:
        np.log(X.data, X.data)
        X.data += 1.0
    if hasattr(self, 'idf_'):
        X.data *= self.idf_[X.indices]
    if self.norm is not None:
        X = normalize(X, norm=self.norm, copy=False)
    return _align_api_if_sparse(X)

@property
def idf_(self):
    if not hasattr(self, '_tfidf'):
        raise NotFittedError(f"{self.__class__.__name__} is not fitted yet. Call 'fit' with appropriate arguments before using this attribute.")
    return self._tfidf.idf_

def fit_transform(self, raw_documents, y=None):
    self._check_params()
    self._tfidf = TfidfTransformer(norm=self.norm, use_idf=self.use_idf, smooth_idf=self.smooth_idf, sublinear_tf=self.sublinear_tf)
    X = super().fit_transform(raw_documents)
    self._tfidf.fit(X)
    return self._tfidf.transform(X, copy=False)

def transform(self, raw_documents):
    check_is_fitted(self, msg='The TF-IDF vectorizer is not fitted')
    X = super().transform(raw_documents)
    return self._tfidf.transform(X, copy=False)

def _add_iterable_element(self, f, v, feature_names, vocab, *, fitting=True, transforming=False, indices=None, values=None):
    for vv in v:
        if isinstance(vv, str):
            feature_name = '%s%s%s' % (f, self.separator, vv)
            vv = 1
        else:
            raise TypeError(f'Unsupported type {type(vv)} in iterable value. Only iterables of string are supported.')
        if fitting and feature_name not in vocab:
            vocab[feature_name] = len(feature_names)
            feature_names.append(feature_name)
        if transforming and feature_name in vocab:
            indices.append(vocab[feature_name])
            values.append(self.dtype(vv))

@_fit_context(prefer_skip_nested_validation=True)
def fit(self, X, y=None):
    feature_names = []
    vocab = {}
    for x in X:
        for f, v in x.items():
            if isinstance(v, str):
                feature_name = '%s%s%s' % (f, self.separator, v)
            elif isinstance(v, Number) or v is None:
                feature_name = f
            elif isinstance(v, Mapping):
                raise TypeError(f'Unsupported value type {type(v)} for {f}: {v}.\nMapping objects are not supported.')
            elif isinstance(v, Iterable):
                feature_name = None
                self._add_iterable_element(f, v, feature_names, vocab)
            if feature_name is not None:
                if feature_name not in vocab:
                    vocab[feature_name] = len(feature_names)
                    feature_names.append(feature_name)
    if self.sort:
        feature_names.sort()
        vocab = {f: i for i, f in enumerate(feature_names)}
    self.feature_names_ = feature_names
    self.vocabulary_ = vocab
    return self

@_fit_context(prefer_skip_nested_validation=True)
def fit_transform(self, X, y=None):
    return self._transform(X, fitting=True)

def inverse_transform(self, X, dict_type=dict):
    check_is_fitted(self, 'feature_names_')
    X = check_array(X, accept_sparse=['csr', 'csc'])
    n_samples = X.shape[0]
    names = self.feature_names_
    dicts = [dict_type() for _ in range(n_samples)]
    if sp.issparse(X):
        for i, j in zip(*X.nonzero()):
            dicts[i][names[j]] = X[i, j]
    else:
        for i, d in enumerate(dicts):
            for j, v in enumerate(X[i, :]):
                if v != 0:
                    d[names[j]] = X[i, j]
    return dicts

def transform(self, X):
    check_is_fitted(self, ['feature_names_', 'vocabulary_'])
    return self._transform(X, fitting=False)

def get_feature_names_out(self, input_features=None):
    check_is_fitted(self, 'feature_names_')
    if any((not isinstance(name, str) for name in self.feature_names_)):
        feature_names = [str(name) for name in self.feature_names_]
    else:
        feature_names = self.feature_names_
    return np.asarray(feature_names, dtype=object)

def restrict(self, support, indices=False):
    check_is_fitted(self, 'feature_names_')
    if not indices:
        support = np.where(support)[0]
    names = self.feature_names_
    new_vocab = {}
    for i in support:
        new_vocab[names[i]] = len(new_vocab)
    self.vocabulary_ = new_vocab
    self.feature_names_ = [f for f, i in sorted(new_vocab.items(), key=itemgetter(1))]
    return self

@_fit_context(prefer_skip_nested_validation=True)
def fit(self, X=None, y=None):
    return self

def transform(self, raw_X):
    raw_X = iter(raw_X)
    if self.input_type == 'dict':
        raw_X = (_iteritems(d) for d in raw_X)
    elif self.input_type == 'string':
        first_raw_X = next(raw_X)
        if isinstance(first_raw_X, str):
            raise ValueError('Samples can not be a single string. The input must be an iterable over iterables of strings.')
        raw_X_ = chain([first_raw_X], raw_X)
        raw_X = (((f, 1) for f in x) for x in raw_X_)
    indices, indptr, values = _hashing_transform(raw_X, self.n_features, self.dtype, self.alternate_sign, seed=0)
    n_samples = indptr.shape[0] - 1
    if n_samples == 0:
        raise ValueError('Cannot vectorize empty sequence.')
    X = sp.csr_array((values, indices, indptr), dtype=self.dtype, shape=(n_samples, self.n_features))
    X.sum_duplicates()
    return _align_api_if_sparse(X)

def _get_feature_importances(estimator, getter, transform_func=None, norm_order=1):
    if isinstance(getter, str):
        if getter == 'auto':
            if hasattr(estimator, 'coef_'):
                getter = attrgetter('coef_')
            elif hasattr(estimator, 'feature_importances_'):
                getter = attrgetter('feature_importances_')
            else:
                raise ValueError(f"when `importance_getter=='auto'`, the underlying estimator {estimator.__class__.__name__} should have `coef_` or `feature_importances_` attribute. Either pass a fitted estimator to feature selector or call fit before calling transform.")
        else:
            getter = attrgetter(getter)
    elif not callable(getter):
        raise ValueError('`importance_getter` has to be a string or `callable`')
    importances = getter(estimator)
    if issparse(importances):
        importances = _align_api_if_sparse(csr_array(importances))
    if transform_func is None:
        return importances
    elif transform_func == 'norm':
        if importances.ndim == 1:
            importances = np.abs(importances)
        else:
            norm = scipy.sparse.linalg.norm if issparse(importances) else np.linalg.norm
            importances = norm(importances, axis=0, ord=norm_order)
    elif transform_func == 'square':
        if importances.ndim == 1:
            importances = safe_sqr(importances)
        else:
            importances = safe_sqr(importances).sum(axis=0)
    else:
        raise ValueError("Valid values for `transform_func` are None, 'norm' and 'square'. Those two transformation are only supported now")
    return importances

def get_support(self, indices=False):
    mask = self._get_support_mask()
    return mask if not indices else np.nonzero(mask)[0]

@abstractmethod
def _get_support_mask(self):
    pass

def transform(self, X):
    output_config_dense = _get_output_config('transform', estimator=self)['dense']
    preserve_X = output_config_dense != 'default' and nw.dependencies.is_pandas_dataframe(X)
    X = validate_data(self, X, dtype=None, accept_sparse='csr', ensure_all_finite=not get_tags(self).input_tags.allow_nan, skip_check_array=preserve_X, reset=False)
    return self._transform(X)

def _transform(self, X):
    mask = self.get_support()
    if not mask.any():
        warnings.warn('No features were selected: either the data is too noisy or the selection test too strict.', UserWarning)
        if hasattr(X, 'iloc'):
            return X.iloc[:, :0]
        return np.empty(0, dtype=X.dtype).reshape((X.shape[0], 0))
    return _safe_indexing(X, mask, axis=1)

def _calculate_threshold(estimator, importances, threshold):
    if threshold is None:
        est_name = estimator.__class__.__name__
        is_l1_penalized = hasattr(estimator, 'penalty') and estimator.penalty == 'l1'
        is_lasso = 'Lasso' in est_name
        is_elasticnet_l1_penalized = est_name == 'ElasticNet' and (hasattr(estimator, 'l1_ratio') and np.isclose(estimator.l1_ratio, 1.0))
        is_elasticnetcv_l1_penalized = est_name == 'ElasticNetCV' and (hasattr(estimator, 'l1_ratio_') and np.isclose(estimator.l1_ratio_, 1.0))
        is_logreg_l1_penalized = est_name == 'LogisticRegression' and (hasattr(estimator, 'l1_ratio') and np.isclose(estimator.l1_ratio, 1.0))
        is_logregcv_l1_penalized = est_name == 'LogisticRegressionCV' and (hasattr(estimator, 'l1_ratio_') and np.all(np.isclose(estimator.l1_ratio_, 1.0)))
        if is_l1_penalized or is_lasso or is_elasticnet_l1_penalized or is_elasticnetcv_l1_penalized or is_logreg_l1_penalized or is_logregcv_l1_penalized:
            threshold = 1e-05
        else:
            threshold = 'mean'
    if isinstance(threshold, str):
        if '*' in threshold:
            scale, reference = threshold.split('*')
            scale = float(scale.strip())
            reference = reference.strip()
            if reference == 'median':
                reference = np.median(importances)
            elif reference == 'mean':
                reference = np.mean(importances)
            else:
                raise ValueError('Unknown reference: ' + reference)
            threshold = scale * reference
        elif threshold == 'median':
            threshold = np.median(importances)
        elif threshold == 'mean':
            threshold = np.mean(importances)
        else:
            raise ValueError("Expected threshold='mean' or threshold='median' got %s" % threshold)
    else:
        threshold = float(threshold)
    return threshold

@_fit_context(prefer_skip_nested_validation=False)
def fit(self, X, y=None, **fit_params):
    self._check_max_features(X)
    if self.prefit:
        try:
            check_is_fitted(self.estimator)
        except NotFittedError as exc:
            raise NotFittedError('When `prefit=True`, `estimator` is expected to be a fitted estimator.') from exc
        self.estimator_ = deepcopy(self.estimator)
    elif _routing_enabled():
        routed_params = process_routing(self, 'fit', **fit_params)
        self.estimator_ = clone(self.estimator)
        self.estimator_.fit(X, y, **routed_params.estimator.fit)
    else:
        self.estimator_ = clone(self.estimator)
        self.estimator_.fit(X, y, **fit_params)
    if hasattr(self.estimator_, 'feature_names_in_'):
        self.feature_names_in_ = self.estimator_.feature_names_in_
    else:
        _check_feature_names(self, X, reset=True)
    return self

@property
def threshold_(self):
    scores = _get_feature_importances(estimator=self.estimator_, getter=self.importance_getter, transform_func='norm', norm_order=self.norm_order)
    return _calculate_threshold(self.estimator, scores, self.threshold)

@available_if(_estimator_has('partial_fit'))
