def _compute_mi(x, y, x_discrete, y_discrete, n_neighbors=3):
    if x_discrete and y_discrete:
        return mutual_info_score(x, y)
    elif x_discrete and (not y_discrete):
        return _compute_mi_cd(y, x, n_neighbors)
    elif not x_discrete and y_discrete:
        return _compute_mi_cd(x, y, n_neighbors)
    else:
        return _compute_mi_cc(x, y, n_neighbors)

def _iterate_columns(X, columns=None):
    if columns is None:
        columns = range(X.shape[1])
    if issparse(X):
        for i in columns:
            x = np.zeros(X.shape[0])
            start_ptr, end_ptr = (X.indptr[i], X.indptr[i + 1])
            x[X.indices[start_ptr:end_ptr]] = X.data[start_ptr:end_ptr]
            yield x
    else:
        for i in columns:
            yield X[:, i]

def _estimate_mi(X, y, *, discrete_features='auto', discrete_target=False, n_neighbors=3, copy=True, random_state=None, n_jobs=None):
    X, y = check_X_y(X, y, accept_sparse='csc', y_numeric=not discrete_target)
    n_samples, n_features = X.shape
    if isinstance(discrete_features, (str, bool)):
        if isinstance(discrete_features, str):
            if discrete_features == 'auto':
                discrete_features = issparse(X)
            else:
                raise ValueError('Invalid string value for discrete_features.')
        discrete_mask = np.empty(n_features, dtype=bool)
        discrete_mask.fill(discrete_features)
    else:
        discrete_features = check_array(discrete_features, ensure_2d=False)
        if discrete_features.dtype != 'bool':
            discrete_mask = np.zeros(n_features, dtype=bool)
            discrete_mask[discrete_features] = True
        else:
            discrete_mask = discrete_features
    continuous_mask = ~discrete_mask
    if np.any(continuous_mask) and issparse(X):
        raise ValueError("Sparse matrix `X` can't have continuous features.")
    rng = check_random_state(random_state)
    if np.any(continuous_mask):
        X = X.astype(np.float64, copy=copy)
        X[:, continuous_mask] = scale(X[:, continuous_mask], with_mean=False, copy=False)
        means = np.maximum(1, np.mean(np.abs(X[:, continuous_mask]), axis=0))
        X[:, continuous_mask] += 1e-10 * means * rng.standard_normal(size=(n_samples, np.sum(continuous_mask)))
    if not discrete_target:
        y = scale(y, with_mean=False)
        y += 1e-10 * np.maximum(1, np.mean(np.abs(y))) * rng.standard_normal(size=n_samples)
    mi = Parallel(n_jobs=n_jobs)((delayed(_compute_mi)(x, y, discrete_feature, discrete_target, n_neighbors) for x, discrete_feature in zip(_iterate_columns(X), discrete_mask)))
    return np.array(mi)

@validate_params({'X': ['array-like', 'sparse matrix'], 'y': ['array-like'], 'discrete_features': [StrOptions({'auto'}), 'boolean', 'array-like'], 'n_neighbors': [Interval(Integral, 1, None, closed='left')], 'copy': ['boolean'], 'random_state': ['random_state'], 'n_jobs': [Integral, None]}, prefer_skip_nested_validation=True)
def mutual_info_regression(X, y, *, discrete_features='auto', n_neighbors=3, copy=True, random_state=None, n_jobs=None):
    return _estimate_mi(X, y, discrete_features=discrete_features, discrete_target=False, n_neighbors=n_neighbors, copy=copy, random_state=random_state, n_jobs=n_jobs)

@validate_params({'X': ['array-like', 'sparse matrix'], 'y': ['array-like'], 'discrete_features': [StrOptions({'auto'}), 'boolean', 'array-like'], 'n_neighbors': [Interval(Integral, 1, None, closed='left')], 'copy': ['boolean'], 'random_state': ['random_state'], 'n_jobs': [Integral, None]}, prefer_skip_nested_validation=True)
def mutual_info_classif(X, y, *, discrete_features='auto', n_neighbors=3, copy=True, random_state=None, n_jobs=None):
