@_fit_context(prefer_skip_nested_validation=False)
def fit(self, X, y=None, **params):
    _raise_for_params(params, self, 'fit')
    tags = self.__sklearn_tags__()
    X = validate_data(self, X, accept_sparse='csc', ensure_min_features=2, ensure_all_finite=not tags.input_tags.allow_nan)
    n_features = X.shape[1]
    if self.n_features_to_select == 'auto':
        if self.tol is not None:
            self.n_features_to_select_ = n_features - 1
        else:
            self.n_features_to_select_ = n_features // 2
    elif isinstance(self.n_features_to_select, Integral):
        if self.n_features_to_select >= n_features:
            raise ValueError('n_features_to_select must be < n_features.')
        self.n_features_to_select_ = self.n_features_to_select
    elif isinstance(self.n_features_to_select, Real):
        self.n_features_to_select_ = int(n_features * self.n_features_to_select)
    if self.tol is not None and self.tol < 0 and (self.direction == 'forward'):
        raise ValueError('tol must be strictly positive when doing forward selection')
    cv = check_cv(self.cv, y, classifier=is_classifier(self.estimator))
    cloned_estimator = clone(self.estimator)
    current_mask = np.zeros(shape=n_features, dtype=bool)
    n_iterations = self.n_features_to_select_ if self.n_features_to_select == 'auto' or self.direction == 'forward' else n_features - self.n_features_to_select_
    old_score = -np.inf
    is_auto_select = self.tol is not None and self.n_features_to_select == 'auto'
    if _routing_enabled():
        process_routing(self, 'fit', **params)
    for _ in range(n_iterations):
        new_feature_idx, new_score = self._get_best_new_feature_score(cloned_estimator, X, y, cv, current_mask, **params)
        if is_auto_select and new_score - old_score < self.tol:
            break
        old_score = new_score
        current_mask[new_feature_idx] = True
    if self.direction == 'backward':
        current_mask = ~current_mask
    self.support_ = current_mask
    self.n_features_to_select_ = self.support_.sum()
    return self

@validate_params({'X': ['array-like', 'sparse matrix'], 'y': ['array-like']}, prefer_skip_nested_validation=True)
def f_classif(X, y):
    X, y = check_X_y(X, y, accept_sparse=['csr', 'csc', 'coo'])
    args = [X[safe_mask(X, y == k)] for k in np.unique(y)]
    return f_oneway(*args)

@validate_params({'X': ['array-like', 'sparse matrix'], 'y': ['array-like']}, prefer_skip_nested_validation=True)
def chi2(X, y):
    X = check_array(X, accept_sparse='csr', dtype=(np.float64, np.float32))
    if np.any((X.data if issparse(X) else X) < 0):
        raise ValueError('Input X must be non-negative.')
    Y = LabelBinarizer(sparse_output=True).fit_transform(y)
    if Y.shape[1] == 1:
        Y = Y.toarray()
        Y = np.append(1 - Y, Y, axis=1)
    observed = safe_sparse_dot(Y.T, X)
    if issparse(observed):
        observed = observed.toarray()
    feature_count = X.sum(axis=0).reshape(1, -1)
    class_prob = Y.mean(axis=0).reshape(1, -1)
    expected = np.dot(class_prob.T, feature_count)
    return _chisquare(observed, expected)

@_fit_context(prefer_skip_nested_validation=True)
def fit(self, X, y=None):
    if y is None:
        X = validate_data(self, X, accept_sparse=['csr', 'csc'])
    else:
        X, y = validate_data(self, X, y, accept_sparse=['csr', 'csc'], multi_output=True)
    self._check_params(X, y)
    score_func_ret = self.score_func(X, y)
    if isinstance(score_func_ret, (list, tuple)):
        self.scores_, self.pvalues_ = score_func_ret
        self.pvalues_ = np.asarray(self.pvalues_)
    else:
        self.scores_ = score_func_ret
        self.pvalues_ = None
    self.scores_ = np.asarray(self.scores_)
    return self

@_fit_context(prefer_skip_nested_validation=True)
def fit(self, X, y=None):
    X = validate_data(self, X, accept_sparse=('csr', 'csc'), dtype=np.float64, ensure_all_finite='allow-nan')
    if hasattr(X, 'toarray'):
        _, self.variances_ = mean_variance_axis(X, axis=0)
        if self.threshold == 0:
            mins, maxes = min_max_axis(X, axis=0)
            peak_to_peaks = maxes - mins
    else:
        self.variances_ = np.nanvar(X, axis=0)
        if self.threshold == 0:
            peak_to_peaks = np.ptp(X, axis=0)
    if self.threshold == 0:
        compare_arr = np.array([self.variances_, peak_to_peaks])
        self.variances_ = np.nanmin(compare_arr, axis=0)
    if np.all(~np.isfinite(self.variances_) | (self.variances_ <= self.threshold)):
        msg = 'No feature in X meets the variance threshold {0:.5f}'
        if X.shape[0] == 1:
            msg += ' (X contains only one sample)'
        raise ValueError(msg.format(self.threshold))
    return self

