        K, K_gradient = kernel(self.X_train_, eval_gradient=True)
    else:
        K = kernel(self.X_train_)
    Z, (pi, W_sr, L, b, a) = self._posterior_mode(K, return_temporaries=True)
    if not eval_gradient:
        return Z
    d_Z = np.empty(theta.shape[0])
    R = W_sr[:, np.newaxis] * cho_solve((L, True), np.diag(W_sr))
    C = solve(L, W_sr[:, np.newaxis] * K)
    s_2 = -0.5 * (np.diag(K) - np.einsum('ij, ij -> j', C, C)) * (pi * (1 - pi) * (1 - 2 * pi))
    for j in range(d_Z.shape[0]):
        C = K_gradient[:, :, j]
        s_1 = 0.5 * a.T.dot(C).dot(a) - 0.5 * R.T.ravel().dot(C.ravel())
        b = C.dot(self.y_train_ - pi)
        s_3 = b - K.dot(R.dot(b))
        d_Z[j] = s_1 + s_2.T.dot(s_3)
    return (Z, d_Z)

def _posterior_mode(self, K, return_temporaries=False):
    if self.warm_start and hasattr(self, 'f_cached') and (self.f_cached.shape == self.y_train_.shape):
        f = self.f_cached
    else:
        f = np.zeros_like(self.y_train_, dtype=np.float64)
    log_marginal_likelihood = -np.inf
    for _ in range(self.max_iter_predict):
        pi = expit(f)
        W = pi * (1 - pi)
        W_sr = np.sqrt(W)
        W_sr_K = W_sr[:, np.newaxis] * K
        B = np.eye(W.shape[0]) + W_sr_K * W_sr
        L = cholesky(B, lower=True)
        b = W * f + (self.y_train_ - pi)
        a = b - W_sr * cho_solve((L, True), W_sr_K.dot(b))
        f = K.dot(a)
        lml = -0.5 * a.T.dot(f) - np.log1p(np.exp(-(self.y_train_ * 2 - 1) * f)).sum() - np.log(np.diag(L)).sum()
        if lml - log_marginal_likelihood < 1e-10:
            break
        log_marginal_likelihood = lml
    self.f_cached = f
    if return_temporaries:
        return (log_marginal_likelihood, (pi, W_sr, L, b, a))
    else:
        return log_marginal_likelihood

@_fit_context(prefer_skip_nested_validation=True)
def fit(self, X, y):
    if isinstance(self.kernel, CompoundKernel):
        raise ValueError('kernel cannot be a CompoundKernel')
    if self.kernel is None or self.kernel.requires_vector_input:
        X, y = validate_data(self, X, y, multi_output=False, ensure_2d=True, dtype='numeric')
    else:
        X, y = validate_data(self, X, y, multi_output=False, ensure_2d=False, dtype=None)
    self.base_estimator_ = _BinaryGaussianProcessClassifierLaplace(kernel=self.kernel, optimizer=self.optimizer, n_restarts_optimizer=self.n_restarts_optimizer, max_iter_predict=self.max_iter_predict, warm_start=self.warm_start, copy_X_train=self.copy_X_train, random_state=self.random_state)
    self.classes_ = np.unique(y)
    self.n_classes_ = self.classes_.size
    if self.n_classes_ == 1:
        raise ValueError('GaussianProcessClassifier requires 2 or more distinct classes; got %d class (only class %s is present)' % (self.n_classes_, self.classes_[0]))
    if self.n_classes_ > 2:
        if self.multi_class == 'one_vs_rest':
            self.base_estimator_ = OneVsRestClassifier(self.base_estimator_, n_jobs=self.n_jobs)
        elif self.multi_class == 'one_vs_one':
            self.base_estimator_ = OneVsOneClassifier(self.base_estimator_, n_jobs=self.n_jobs)
        else:
            raise ValueError('Unknown multi-class mode %s' % self.multi_class)
    self.base_estimator_.fit(X, y)
    if self.n_classes_ > 2:
        self.log_marginal_likelihood_value_ = np.mean([estimator.log_marginal_likelihood() for estimator in self.base_estimator_.estimators_])
    else:
        self.log_marginal_likelihood_value_ = self.base_estimator_.log_marginal_likelihood()
    return self

def predict(self, X):
    check_is_fitted(self)
    if self.kernel is None or self.kernel.requires_vector_input:
        X = validate_data(self, X, ensure_2d=True, dtype='numeric', reset=False)
    else:
        X = validate_data(self, X, ensure_2d=False, dtype=None, reset=False)
    return self.base_estimator_.predict(X)

def predict_proba(self, X):
    check_is_fitted(self)
    if self.n_classes_ > 2 and self.multi_class == 'one_vs_one':
        raise ValueError('one_vs_one multi-class mode does not support predicting probability estimates. Use one_vs_rest mode instead.')
    if self.kernel is None or self.kernel.requires_vector_input:
        X = validate_data(self, X, ensure_2d=True, dtype='numeric', reset=False)
    else:
        X = validate_data(self, X, ensure_2d=False, dtype=None, reset=False)
    return self.base_estimator_.predict_proba(X)

@property
def kernel_(self):
    if self.n_classes_ == 2:
        return self.base_estimator_.kernel_
    else:
        return CompoundKernel([estimator.kernel_ for estimator in self.base_estimator_.estimators_])

def log_marginal_likelihood(self, theta=None, eval_gradient=False, clone_kernel=True):
    check_is_fitted(self)
    if theta is None:
        if eval_gradient:
            raise ValueError('Gradient can only be evaluated for theta!=None')
        return self.log_marginal_likelihood_value_
    theta = np.asarray(theta)
    if self.n_classes_ == 2:
        return self.base_estimator_.log_marginal_likelihood(theta, eval_gradient, clone_kernel=clone_kernel)
    else:
        if eval_gradient:
            raise NotImplementedError('Gradient of log-marginal-likelihood not implemented for multi-class GPC.')
        estimators = self.base_estimator_.estimators_
        n_dims = estimators[0].kernel_.n_dims
        if theta.shape[0] == n_dims:
            return np.mean([estimator.log_marginal_likelihood(theta, clone_kernel=clone_kernel) for i, estimator in enumerate(estimators)])
        elif theta.shape[0] == n_dims * self.classes_.shape[0]:
            return np.mean([estimator.log_marginal_likelihood(theta[n_dims * i:n_dims * (i + 1)], clone_kernel=clone_kernel) for i, estimator in enumerate(estimators)])
        else:
            raise ValueError('Shape of theta must be either %d or %d. Obtained theta with shape %d.' % (n_dims, n_dims * self.classes_.shape[0], theta.shape[0]))

def latent_mean_and_variance(self, X):
    if self.n_classes_ > 2:
        raise ValueError(f'Returning the mean and variance of the latent function f is only supported for binary classification, received {self.n_classes_} classes.')
    check_is_fitted(self)
    if self.kernel is None or self.kernel.requires_vector_input:
        X = validate_data(self, X, ensure_2d=True, dtype='numeric', reset=False)
    else:
        X = validate_data(self, X, ensure_2d=False, dtype=None, reset=False)
    return self.base_estimator_.latent_mean_and_variance(X)

@_fit_context(prefer_skip_nested_validation=True)
def fit(self, X, y):
    self.kernel_ = C() * RBF() if self.kernel is None else clone(self.kernel)
    self._rng = check_random_state(self.random_state)
    if self.kernel_.requires_vector_input:
        dtype, ensure_2d = ('numeric', True)
    else:
        dtype, ensure_2d = (None, False)
    X, y = validate_data(self, X, y, multi_output=True, y_numeric=True, ensure_2d=ensure_2d, dtype=dtype)
    n_targets_seen = y.shape[1] if y.ndim > 1 else 1
    if self.n_targets is not None and n_targets_seen != self.n_targets:
        raise ValueError(f'The number of targets seen in `y` is different from the parameter `n_targets`. Got {n_targets_seen} != {self.n_targets}.')
    if self.normalize_y:
        self._y_train_mean = np.mean(y, axis=0)
        self._y_train_std = _handle_zeros_in_scale(np.std(y, axis=0), copy=False)
        y = (y - self._y_train_mean) / self._y_train_std
    else:
        shape_y_stats = (y.shape[1],) if y.ndim == 2 else 1
        self._y_train_mean = np.zeros(shape=shape_y_stats)
        self._y_train_std = np.ones(shape=shape_y_stats)
    if np.iterable(self.alpha) and self.alpha.shape[0] != y.shape[0]:
        if self.alpha.shape[0] == 1:
            self.alpha = self.alpha[0]
        else:
            raise ValueError(f'alpha must be a scalar or an array with same number of entries as y. ({self.alpha.shape[0]} != {y.shape[0]})')
    self.X_train_ = np.copy(X) if self.copy_X_train else X
    self.y_train_ = np.copy(y) if self.copy_X_train else y
    if self.optimizer is not None and self.kernel_.n_dims > 0:

        def obj_func(theta, eval_gradient=True):
            if eval_gradient:
                lml, grad = self.log_marginal_likelihood(theta, eval_gradient=True, clone_kernel=False)
                return (-lml, -grad)
            else:
                return -self.log_marginal_likelihood(theta, clone_kernel=False)
        optima = [self._constrained_optimization(obj_func, self.kernel_.theta, self.kernel_.bounds)]
        if self.n_restarts_optimizer > 0:
            if not np.isfinite(self.kernel_.bounds).all():
                raise ValueError('Multiple optimizer restarts (n_restarts_optimizer>0) requires that all bounds are finite.')
            bounds = self.kernel_.bounds
            for iteration in range(self.n_restarts_optimizer):
                theta_initial = self._rng.uniform(bounds[:, 0], bounds[:, 1])
                optima.append(self._constrained_optimization(obj_func, theta_initial, bounds))
        lml_values = list(map(itemgetter(1), optima))
        self.kernel_.theta = optima[np.argmin(lml_values)][0]
        self.kernel_._check_bounds_params()
        self.log_marginal_likelihood_value_ = -np.min(lml_values)
    else:
        self.log_marginal_likelihood_value_ = self.log_marginal_likelihood(self.kernel_.theta, clone_kernel=False)
    K = self.kernel_(self.X_train_)
    K[np.diag_indices_from(K)] += self.alpha
    try:
        self.L_ = cholesky(K, lower=GPR_CHOLESKY_LOWER, check_finite=False)
    except np.linalg.LinAlgError as exc:
        exc.args = (f"The kernel, {self.kernel_}, is not returning a positive definite matrix. Try gradually increasing the 'alpha' parameter of your GaussianProcessRegressor estimator.",) + exc.args
        raise
    self.alpha_ = cho_solve((self.L_, GPR_CHOLESKY_LOWER), self.y_train_, check_finite=False)
    return self

def predict(self, X, return_std=False, return_cov=False):
    if return_std and return_cov:
        raise RuntimeError('At most one of return_std or return_cov can be requested.')
    if self.kernel is None or self.kernel.requires_vector_input:
        dtype, ensure_2d = ('numeric', True)
    else:
        dtype, ensure_2d = (None, False)
    X = validate_data(self, X, ensure_2d=ensure_2d, dtype=dtype, reset=False)
    if not hasattr(self, 'X_train_'):
        if self.kernel is None:
            kernel = C(1.0, constant_value_bounds='fixed') * RBF(1.0, length_scale_bounds='fixed')
        else:
            kernel = self.kernel
        n_targets = self.n_targets if self.n_targets is not None else 1
        y_mean = np.zeros(shape=(X.shape[0], n_targets)).squeeze()
        if return_cov:
            y_cov = kernel(X)
            if n_targets > 1:
                y_cov = np.repeat(np.expand_dims(y_cov, -1), repeats=n_targets, axis=-1)
            return (y_mean, y_cov)
        elif return_std:
            y_var = kernel.diag(X)
            if n_targets > 1:
                y_var = np.repeat(np.expand_dims(y_var, -1), repeats=n_targets, axis=-1)
            return (y_mean, np.sqrt(y_var))
        else:
            return y_mean
    else:
        K_trans = self.kernel_(X, self.X_train_)
        y_mean = K_trans @ self.alpha_
        y_mean = self._y_train_std * y_mean + self._y_train_mean
        if y_mean.ndim > 1 and y_mean.shape[1] == 1:
            y_mean = np.squeeze(y_mean, axis=1)
        if not return_cov and (not return_std):
            return y_mean
        V = solve_triangular(self.L_, K_trans.T, lower=GPR_CHOLESKY_LOWER, check_finite=False)
        if return_cov:
            y_cov = self.kernel_(X) - V.T @ V
            y_cov = np.outer(y_cov, self._y_train_std ** 2).reshape(*y_cov.shape, -1)
            if y_cov.shape[2] == 1:
                y_cov = np.squeeze(y_cov, axis=2)
            return (y_mean, y_cov)
        else:
            y_var = self.kernel_.diag(X).copy()
            y_var -= np.einsum('ij,ji->i', V.T, V)
            y_var_negative = y_var < 0
            if np.any(y_var_negative):
                warnings.warn('Predicted variances smaller than 0. Setting those variances to 0.')
                y_var[y_var_negative] = 0.0
            y_var = np.outer(y_var, self._y_train_std ** 2).reshape(*y_var.shape, -1)
            if y_var.shape[1] == 1:
                y_var = np.squeeze(y_var, axis=1)
            return (y_mean, np.sqrt(y_var))

def sample_y(self, X, n_samples=1, random_state=0):
    rng = check_random_state(random_state)
    y_mean, y_cov = self.predict(X, return_cov=True)
    if y_mean.ndim == 1:
        y_samples = rng.multivariate_normal(y_mean, y_cov, n_samples).T
    else:
        y_samples = [rng.multivariate_normal(y_mean[:, target], y_cov[..., target], n_samples).T[:, np.newaxis] for target in range(y_mean.shape[1])]
        y_samples = np.hstack(y_samples)
    return y_samples

def log_marginal_likelihood(self, theta=None, eval_gradient=False, clone_kernel=True):
    if theta is None:
        if eval_gradient:
            raise ValueError('Gradient can only be evaluated for theta!=None')
        return self.log_marginal_likelihood_value_
    if clone_kernel:
        kernel = self.kernel_.clone_with_theta(theta)
    else:
        kernel = self.kernel_
        kernel.theta = theta
    if eval_gradient:
        K, K_gradient = kernel(self.X_train_, eval_gradient=True)
    else:
        K = kernel(self.X_train_)
    K[np.diag_indices_from(K)] += self.alpha
    try:
        L = cholesky(K, lower=GPR_CHOLESKY_LOWER, check_finite=False)
    except np.linalg.LinAlgError:
        return (-np.inf, np.zeros_like(theta)) if eval_gradient else -np.inf
    y_train = self.y_train_
    if y_train.ndim == 1:
        y_train = y_train[:, np.newaxis]
    alpha = cho_solve((L, GPR_CHOLESKY_LOWER), y_train, check_finite=False)
    log_likelihood_dims = -0.5 * np.einsum('ik,ik->k', y_train, alpha)
    log_likelihood_dims -= np.log(np.diag(L)).sum()
    log_likelihood_dims -= K.shape[0] / 2 * np.log(2 * np.pi)
    log_likelihood = log_likelihood_dims.sum(axis=-1)
    if eval_gradient:
        inner_term = np.einsum('ik,jk->ijk', alpha, alpha)
        K_inv = cho_solve((L, GPR_CHOLESKY_LOWER), np.eye(K.shape[0]), check_finite=False)
        inner_term -= K_inv[..., np.newaxis]
        log_likelihood_gradient_dims = 0.5 * np.einsum('ijl,jik->kl', inner_term, K_gradient)
        log_likelihood_gradient = log_likelihood_gradient_dims.sum(axis=-1)
    if eval_gradient:
        return (log_likelihood, log_likelihood_gradient)
    else:
        return log_likelihood

def _safe_min(items):
    try:
        return min(items)
    except TypeError as e:
        if "'<' not supported between" in str(e):
            return min(items, key=lambda x: (str(type(x)), str(x)))
        raise

def _most_frequent(array, extra_value, n_repeat):
    if array.size > 0:
        if array.dtype == object:
            counter = Counter(array)
            most_frequent_count = counter.most_common(1)[0][1]
            most_frequent_value = _safe_min([value for value, count in counter.items() if count == most_frequent_count])
        else:
            mode = _mode(array)
            most_frequent_value = mode[0][0]
            most_frequent_count = mode[1][0]
    else:
        most_frequent_value = 0
        most_frequent_count = 0
    if most_frequent_count == 0 and n_repeat == 0:
        return np.nan
    elif most_frequent_count < n_repeat:
        return extra_value
    elif most_frequent_count > n_repeat:
        return most_frequent_value
    elif most_frequent_count == n_repeat:
        return _safe_min([most_frequent_value, extra_value])

def _fit_indicator(self, X):
    if self.add_indicator:
        self.indicator_ = MissingIndicator(missing_values=self.missing_values, error_on_new=False)
        self.indicator_._fit(X, precomputed=True)
    else:
        self.indicator_ = None

def _transform_indicator(self, X):
    if self.add_indicator:
        if not hasattr(self, 'indicator_'):
            raise ValueError('Make sure to call _fit_indicator before _transform_indicator')
        return self.indicator_.transform(X)

def _concatenate_indicator(self, X_imputed, X_indicator):
    if not self.add_indicator:
        return X_imputed
    if sp.issparse(X_imputed):
        hstack = partial(sp.hstack, format=X_imputed.format)
    else:
        hstack = np.hstack
    if X_indicator is None:
        raise ValueError('Data from the missing indicator are not provided. Call _fit_indicator and _transform_indicator in the imputer implementation.')
    return _align_api_if_sparse(hstack((X_imputed, X_indicator)))

@_fit_context(prefer_skip_nested_validation=True)
def fit(self, X, y=None):
    X = self._validate_input(X, in_fit=True)
    if self.fill_value is None:
        if X.dtype.kind in ('i', 'u', 'f'):
            fill_value = 0
        else:
            fill_value = 'missing_value'
    else:
        fill_value = self.fill_value
    self._fill_dtype = X.dtype
    if sp.issparse(X):
        self.statistics_ = self._sparse_fit(X, self.strategy, self.missing_values, fill_value)
    else:
        self.statistics_ = self._dense_fit(X, self.strategy, self.missing_values, fill_value)
    return self

def _sparse_fit(self, X, strategy, missing_values, fill_value):
    missing_mask = _get_mask(X, missing_values)
    mask_data = missing_mask.data
    n_implicit_zeros = X.shape[0] - np.diff(X.indptr)
    statistics = np.empty(X.shape[1])
    if strategy == 'constant':
        statistics.fill(fill_value)
        if not self.keep_empty_features:
            if SCIPY_VERSION_BELOW_1_12:
                for i in range(missing_mask.shape[1]):
                    if all(missing_mask[:, [i]].data):
                        statistics[i] = np.nan
            else:
                for i in range(missing_mask.shape[1]):
                    if all(missing_mask[:, i].data):
                        statistics[i] = np.nan
    else:
        for i in range(X.shape[1]):
            column = X.data[X.indptr[i]:X.indptr[i + 1]]
            mask_column = mask_data[X.indptr[i]:X.indptr[i + 1]]
            column = column[~mask_column]
            mask_zeros = _get_mask(column, 0)
            column = column[~mask_zeros]
            n_explicit_zeros = mask_zeros.sum()
            n_zeros = n_implicit_zeros[i] + n_explicit_zeros
            if len(column) == 0 and self.keep_empty_features:
                statistics[i] = 0
            elif strategy == 'mean':
                s = column.size + n_zeros
                statistics[i] = np.nan if s == 0 else column.sum() / s
            elif strategy == 'median':
                statistics[i] = _get_median(column, n_zeros)
            elif strategy == 'most_frequent':
                statistics[i] = _most_frequent(column, 0, n_zeros)
            elif isinstance(strategy, Callable):
                statistics[i] = self.strategy(column)
    super()._fit_indicator(missing_mask)
    return statistics

def _dense_fit(self, X, strategy, missing_values, fill_value):
    missing_mask = _get_mask(X, missing_values)
    masked_X = ma.masked_array(X, mask=missing_mask)
    super()._fit_indicator(missing_mask)
    if strategy == 'mean':
        mean_masked = np.ma.mean(masked_X, axis=0)
        mean = np.ma.getdata(mean_masked)
        mean[np.ma.getmask(mean_masked)] = 0 if self.keep_empty_features else np.nan
        return mean
    elif strategy == 'median':
        median_masked = np.ma.median(masked_X, axis=0)
        median = np.ma.getdata(median_masked)
        median[np.ma.getmaskarray(median_masked)] = 0 if self.keep_empty_features else np.nan
        return median
    elif strategy == 'most_frequent':
        X = X.transpose()
        mask = missing_mask.transpose()
        if X.dtype.kind == 'O':
            most_frequent = np.empty(X.shape[0], dtype=object)
        else:
            most_frequent = np.empty(X.shape[0])
        for i, (row, row_mask) in enumerate(zip(X[:], mask[:])):
            row_mask = np.logical_not(row_mask).astype(bool)
            row = row[row_mask]
            if len(row) == 0 and self.keep_empty_features:
                most_frequent[i] = 0
            else:
                most_frequent[i] = _most_frequent(row, np.nan, 0)
        return most_frequent
    elif strategy == 'constant':
        statistics = np.full(X.shape[1], fill_value, dtype=np.object_)
        if not self.keep_empty_features:
            for i in range(missing_mask.shape[1]):
                if missing_mask[:, i].all():
                    statistics[i] = np.nan
        return statistics
    elif isinstance(strategy, Callable):
        statistics = np.empty(masked_X.shape[1])
        for i in range(masked_X.shape[1]):
            statistics[i] = self.strategy(masked_X[:, i].compressed())
        return statistics

def transform(self, X):
    check_is_fitted(self)
    X = self._validate_input(X, in_fit=False)
    statistics = self.statistics_
    if X.shape[1] != statistics.shape[0]:
        raise ValueError('X has %d features per sample, expected %d' % (X.shape[1], self.statistics_.shape[0]))
    missing_mask = _get_mask(X, self.missing_values)
    if self.keep_empty_features:
        valid_statistics = statistics.astype(self._fill_dtype, copy=False)
        valid_statistics_indexes = None
    else:
        invalid_mask = _get_mask(statistics, np.nan)
        valid_mask = np.logical_not(invalid_mask)
        valid_statistics = statistics[valid_mask].astype(self._fill_dtype, copy=False)
        valid_statistics_indexes = np.flatnonzero(valid_mask)
        if invalid_mask.any():
            invalid_features = np.arange(X.shape[1])[invalid_mask]
            if hasattr(self, 'feature_names_in_'):
                invalid_features = self.feature_names_in_[invalid_features]
            warnings.warn(f"Skipping features without any observed values: {invalid_features}. At least one non-missing value is needed for imputation with strategy='{self.strategy}'.")
            X = X[:, valid_statistics_indexes]
    if sp.issparse(X):
        if self.missing_values == 0:
            raise ValueError('Imputation not possible when missing_values == 0 and input is sparse. Provide a dense array instead.')
        else:
            if valid_statistics_indexes is None:
                mask = missing_mask.data
            else:
                mask = _get_mask(X.data, self.missing_values)
            indexes = np.repeat(np.arange(len(X.indptr) - 1, dtype=int), np.diff(X.indptr))[mask]
            X.data[mask] = valid_statistics[indexes]
    else:
        if valid_statistics_indexes is None:
            mask_valid_features = missing_mask
        else:
            mask_valid_features = missing_mask[:, valid_statistics_indexes]
        n_missing = np.sum(mask_valid_features, axis=0)
        values = np.repeat(valid_statistics, n_missing)
        coordinates = np.where(mask_valid_features.transpose())[::-1]
        X[coordinates] = values
    X_indicator = super()._transform_indicator(missing_mask)
    return super()._concatenate_indicator(X, X_indicator)

def get_feature_names_out(self, input_features=None):
    check_is_fitted(self, 'n_features_in_')
    input_features = _check_feature_names_in(self, input_features)
    non_missing_mask = np.logical_not(_get_mask(self.statistics_, np.nan))
    names = input_features[non_missing_mask]
    return self._concatenate_indicator_feature_names_out(names, input_features)

def _get_missing_features_info(self, X):
    if not self._precomputed:
        imputer_mask = _get_mask(X, self.missing_values)
    else:
        imputer_mask = X
    if sp.issparse(X):
        imputer_mask.eliminate_zeros()
        if self.features == 'missing-only':
            n_missing = imputer_mask.sum(axis=0)
        if self.sparse is False:
            imputer_mask = imputer_mask.toarray()
        elif imputer_mask.format == 'csr':
            imputer_mask = imputer_mask.tocsc()
    else:
        if not self._precomputed:
            imputer_mask = _get_mask(X, self.missing_values)
        else:
            imputer_mask = X
        if self.features == 'missing-only':
            n_missing = imputer_mask.sum(axis=0)
        if self.sparse is True:
            imputer_mask = _align_api_if_sparse(sp.csc_array(imputer_mask))
    if self.features == 'all':
        features_indices = np.arange(X.shape[1])
    else:
        features_indices = np.flatnonzero(n_missing)
    return (imputer_mask, features_indices)

def _fit(self, X, y=None, precomputed=False):
    if precomputed:
        if not (hasattr(X, 'dtype') and X.dtype.kind == 'b'):
            raise ValueError('precomputed is True but the input data is not a mask')
        self._precomputed = True
    else:
        self._precomputed = False
    if not self._precomputed:
        X = self._validate_input(X, in_fit=True)
    else:
        _check_n_features(self, X, reset=True)
    self._n_features = X.shape[1]
    missing_features_info = self._get_missing_features_info(X)
    self.features_ = missing_features_info[1]
    return missing_features_info[0]

@_fit_context(prefer_skip_nested_validation=True)
def fit(self, X, y=None):
    self._fit(X, y)
    return self

def transform(self, X):
    check_is_fitted(self)
    if not self._precomputed:
        X = self._validate_input(X, in_fit=False)
    elif not (hasattr(X, 'dtype') and X.dtype.kind == 'b'):
        raise ValueError('precomputed is True but the input data is not a mask')
    imputer_mask, features = self._get_missing_features_info(X)
    if self.features == 'missing-only':
        features_diff_fit_trans = np.setdiff1d(features, self.features_)
        if self.error_on_new and features_diff_fit_trans.size > 0:
            raise ValueError('The features {} have missing values in transform but have no missing values in fit.'.format(features_diff_fit_trans))
        if self.features_.size < self._n_features:
            imputer_mask = imputer_mask[:, self.features_]
    return imputer_mask

@_fit_context(prefer_skip_nested_validation=True)
def fit_transform(self, X, y=None):
    imputer_mask = self._fit(X, y)
    if self.features_.size < self._n_features:
        imputer_mask = imputer_mask[:, self.features_]
    return imputer_mask

def get_feature_names_out(self, input_features=None):
    check_is_fitted(self, 'n_features_in_')
    input_features = _check_feature_names_in(self, input_features)
    prefix = self.__class__.__name__.lower()
    return np.asarray([f'{prefix}_{feature_name}' for feature_name in input_features[self.features_]], dtype=object)

def _assign_where(X1, X2, cond):
    if hasattr(X1, 'mask'):
        X1.mask(cond=cond, other=X2, inplace=True)
    else:
        X1[cond] = X2[cond]

def _get_neighbor_feat_idx(self, n_features, feat_idx, abs_corr_mat):
    if self.n_nearest_features is not None and self.n_nearest_features < n_features:
        p = abs_corr_mat[:, feat_idx]
        neighbor_feat_idx = self.random_state_.choice(np.arange(n_features), self.n_nearest_features, replace=False, p=p)
    else:
        inds_left = np.arange(feat_idx)
        inds_right = np.arange(feat_idx + 1, n_features)
        neighbor_feat_idx = np.concatenate((inds_left, inds_right))
    return neighbor_feat_idx

def _get_ordered_idx(self, mask_missing_values):
    frac_of_missing_values = mask_missing_values.mean(axis=0)
    if self.skip_complete:
        missing_values_idx = np.flatnonzero(frac_of_missing_values)
    else:
        missing_values_idx = np.arange(np.shape(frac_of_missing_values)[0])
    if self.imputation_order == 'roman':
        ordered_idx = missing_values_idx
    elif self.imputation_order == 'arabic':
        ordered_idx = missing_values_idx[::-1]
    elif self.imputation_order == 'ascending':
        n = len(frac_of_missing_values) - len(missing_values_idx)
        ordered_idx = np.argsort(frac_of_missing_values, kind='mergesort')[n:]
    elif self.imputation_order == 'descending':
        n = len(frac_of_missing_values) - len(missing_values_idx)
        ordered_idx = np.argsort(frac_of_missing_values, kind='mergesort')[n:][::-1]
    elif self.imputation_order == 'random':
        ordered_idx = missing_values_idx
        self.random_state_.shuffle(ordered_idx)
    return ordered_idx

def _initial_imputation(self, X, in_fit=False):
    if is_scalar_nan(self.missing_values):
        ensure_all_finite = 'allow-nan'
    else:
        ensure_all_finite = True
    X = validate_data(self, X, dtype=FLOAT_DTYPES, order='F', reset=in_fit, ensure_all_finite=ensure_all_finite)
    _check_inputs_dtype(X, self.missing_values)
    X_missing_mask = _get_mask(X, self.missing_values)
    mask_missing_values = X_missing_mask.copy()
    if self.initial_imputer_ is None:
        self.initial_imputer_ = SimpleImputer(missing_values=self.missing_values, strategy=self.initial_strategy, fill_value=self.fill_value, keep_empty_features=self.keep_empty_features).set_output(transform='default')
        X_filled = self.initial_imputer_.fit_transform(X)
    else:
        X_filled = self.initial_imputer_.transform(X)
    if in_fit:
        self._is_empty_feature = np.all(mask_missing_values, axis=0)
    if not self.keep_empty_features:
        Xt = X[:, ~self._is_empty_feature]
        mask_missing_values = mask_missing_values[:, ~self._is_empty_feature]
    else:
        mask_missing_values[:, self._is_empty_feature] = False
        Xt = X
        Xt[:, self._is_empty_feature] = X_filled[:, self._is_empty_feature]
    return (Xt, X_filled, mask_missing_values, X_missing_mask)

@staticmethod
def _validate_limit(limit, limit_type, n_features, is_empty_feature, keep_empty_feature):
    n_features_in = _num_samples(is_empty_feature)
    if limit is not None and (not np.isscalar(limit)) and (_num_samples(limit) != n_features_in):
        raise ValueError(f"'{limit_type}_value' should be of shape ({n_features_in},) when an array-like is provided. Got {len(limit)}, instead.")
    limit_bound = np.inf if limit_type == 'max' else -np.inf
    limit = limit_bound if limit is None else limit
    if np.isscalar(limit):
        limit = np.full(n_features, limit)
    limit = check_array(limit, ensure_all_finite=False, copy=False, ensure_2d=False)
    if not keep_empty_feature and len(limit) == len(is_empty_feature):
        limit = limit[~is_empty_feature]
    return limit

@_fit_context(prefer_skip_nested_validation=False)
def fit_transform(self, X, y=None, **params):
    _raise_for_params(params, self, 'fit')
    routed_params = process_routing(self, 'fit', **params)
    self.random_state_ = getattr(self, 'random_state_', check_random_state(self.random_state))
    if self.estimator is None:
        from sklearn.linear_model import BayesianRidge
        self._estimator = BayesianRidge()
    else:
        self._estimator = clone(self.estimator)
    self.imputation_sequence_ = []
    self.initial_imputer_ = None
    X, Xt, mask_missing_values, complete_mask = self._initial_imputation(X, in_fit=True)
    super()._fit_indicator(complete_mask)
    X_indicator = super()._transform_indicator(complete_mask)
    if self.max_iter == 0 or np.all(mask_missing_values):
        self.n_iter_ = 0
        return super()._concatenate_indicator(Xt, X_indicator)
    if Xt.shape[1] == 1:
        self.n_iter_ = 0
        return super()._concatenate_indicator(Xt, X_indicator)
    self._min_value = self._validate_limit(self.min_value, 'min', X.shape[1], self._is_empty_feature, self.keep_empty_features)
    self._max_value = self._validate_limit(self.max_value, 'max', X.shape[1], self._is_empty_feature, self.keep_empty_features)
    if not np.all(np.greater(self._max_value, self._min_value)):
        raise ValueError('One (or more) features have min_value >= max_value.')
    ordered_idx = self._get_ordered_idx(mask_missing_values)
    self.n_features_with_missing_ = len(ordered_idx)
    abs_corr_mat = self._get_abs_corr_mat(Xt)
    n_samples, n_features = Xt.shape
    if self.verbose > 0:
        print('[IterativeImputer] Completing matrix with shape %s' % (X.shape,))
    start_t = time()
    if not self.sample_posterior:
        Xt_previous = Xt.copy()
        normalized_tol = self.tol * np.max(np.abs(X[~mask_missing_values]))
    for self.n_iter_ in range(1, self.max_iter + 1):
        if self.imputation_order == 'random':
            ordered_idx = self._get_ordered_idx(mask_missing_values)
        for feat_idx in ordered_idx:
            neighbor_feat_idx = self._get_neighbor_feat_idx(n_features, feat_idx, abs_corr_mat)
            Xt, estimator = self._impute_one_feature(Xt, mask_missing_values, feat_idx, neighbor_feat_idx, estimator=None, fit_mode=True, params=routed_params.estimator.fit)
            estimator_triplet = _ImputerTriplet(feat_idx, neighbor_feat_idx, estimator)
            self.imputation_sequence_.append(estimator_triplet)
        if self.verbose > 1:
            print('[IterativeImputer] Ending imputation round %d/%d, elapsed time %0.2f' % (self.n_iter_, self.max_iter, time() - start_t))
        if not self.sample_posterior:
            inf_norm = np.linalg.norm(Xt - Xt_previous, ord=np.inf, axis=None)
            if self.verbose > 0:
                print('[IterativeImputer] Change: {}, scaled tolerance: {} '.format(inf_norm, normalized_tol))
            if inf_norm < normalized_tol:
                if self.verbose > 0:
                    print('[IterativeImputer] Early stopping criterion reached.')
                break
            Xt_previous = Xt.copy()
    _assign_where(Xt, X, cond=~mask_missing_values)
    return super()._concatenate_indicator(Xt, X_indicator)

def transform(self, X):
    check_is_fitted(self)
    X, Xt, mask_missing_values, complete_mask = self._initial_imputation(X, in_fit=False)
    X_indicator = super()._transform_indicator(complete_mask)
    if self.n_iter_ == 0 or np.all(mask_missing_values):
        return super()._concatenate_indicator(Xt, X_indicator)
    imputations_per_round = len(self.imputation_sequence_) // self.n_iter_
    i_rnd = 0
    if self.verbose > 0:
        print('[IterativeImputer] Completing matrix with shape %s' % (X.shape,))
    start_t = time()
    for it, estimator_triplet in enumerate(self.imputation_sequence_):
        Xt, _ = self._impute_one_feature(Xt, mask_missing_values, estimator_triplet.feat_idx, estimator_triplet.neighbor_feat_idx, estimator=estimator_triplet.estimator, fit_mode=False)
        if not (it + 1) % imputations_per_round:
            if self.verbose > 1:
                print('[IterativeImputer] Ending imputation round %d/%d, elapsed time %0.2f' % (i_rnd + 1, self.n_iter_, time() - start_t))
            i_rnd += 1
    _assign_where(Xt, X, cond=~mask_missing_values)
    return super()._concatenate_indicator(Xt, X_indicator)

def fit(self, X, y=None, **fit_params):
    self.fit_transform(X, **fit_params)
    return self

def get_feature_names_out(self, input_features=None):
    check_is_fitted(self, 'n_features_in_')
    input_features = _check_feature_names_in(self, input_features)
    names = self.initial_imputer_.get_feature_names_out(input_features)
    return self._concatenate_indicator_feature_names_out(names, input_features)

def get_metadata_routing(self):
    router = MetadataRouter(owner=self).add(estimator=self.estimator, method_mapping=MethodMapping().add(callee='fit', caller='fit'))
    return router

@_fit_context(prefer_skip_nested_validation=True)
def fit(self, X, y=None):
    if not is_scalar_nan(self.missing_values):
        ensure_all_finite = True
    else:
        ensure_all_finite = 'allow-nan'
    X = validate_data(self, X, accept_sparse=False, dtype=FLOAT_DTYPES, ensure_all_finite=ensure_all_finite, copy=self.copy)
    self._fit_X = X
    self._mask_fit_X = _get_mask(self._fit_X, self.missing_values)
    self._valid_mask = ~np.all(self._mask_fit_X, axis=0)
    super()._fit_indicator(self._mask_fit_X)
    return self

def transform(self, X):
    check_is_fitted(self)
    if not is_scalar_nan(self.missing_values):
        ensure_all_finite = True
    else:
        ensure_all_finite = 'allow-nan'
    X = validate_data(self, X, accept_sparse=False, dtype=FLOAT_DTYPES, force_writeable=True, ensure_all_finite=ensure_all_finite, copy=self.copy, reset=False)
    mask = _get_mask(X, self.missing_values)
    mask_fit_X = self._mask_fit_X
    valid_mask = self._valid_mask
    X_indicator = super()._transform_indicator(mask)
    if not np.any(mask[:, valid_mask]):
        if self.keep_empty_features:
            Xc = X
            Xc[:, ~valid_mask] = 0
        else:
            Xc = X[:, valid_mask]
        return super()._concatenate_indicator(Xc, X_indicator)
    row_missing_idx = np.flatnonzero(mask[:, valid_mask].any(axis=1))
    non_missing_fix_X = np.logical_not(mask_fit_X)
    dist_idx_map = np.zeros(X.shape[0], dtype=int)
    dist_idx_map[row_missing_idx] = np.arange(row_missing_idx.shape[0])

    def process_chunk(dist_chunk, start):
        row_missing_chunk = row_missing_idx[start:start + len(dist_chunk)]
        for col in range(X.shape[1]):
            if not valid_mask[col]:
                continue
            col_mask = mask[row_missing_chunk, col]
            if not np.any(col_mask):
                continue
            potential_donors_idx, = np.nonzero(non_missing_fix_X[:, col])
            receivers_idx = row_missing_chunk[np.flatnonzero(col_mask)]
            dist_subset = dist_chunk[dist_idx_map[receivers_idx] - start][:, potential_donors_idx]
            all_nan_dist_mask = np.isnan(dist_subset).all(axis=1)
            all_nan_receivers_idx = receivers_idx[all_nan_dist_mask]
            if all_nan_receivers_idx.size:
                col_mean = np.ma.array(self._fit_X[:, col], mask=mask_fit_X[:, col]).mean()
                X[all_nan_receivers_idx, col] = col_mean
                if len(all_nan_receivers_idx) == len(receivers_idx):
                    continue
                receivers_idx = receivers_idx[~all_nan_dist_mask]
                dist_subset = dist_chunk[dist_idx_map[receivers_idx] - start][:, potential_donors_idx]
            n_neighbors = min(self.n_neighbors, len(potential_donors_idx))
            value = self._calc_impute(dist_subset, n_neighbors, self._fit_X[potential_donors_idx, col], mask_fit_X[potential_donors_idx, col])
            X[receivers_idx, col] = value
    gen = pairwise_distances_chunked(X[row_missing_idx, :], self._fit_X, metric=self.metric, missing_values=self.missing_values, ensure_all_finite=ensure_all_finite, reduce_func=process_chunk)
    for chunk in gen:
        pass
    if self.keep_empty_features:
        Xc = X
        Xc[:, ~valid_mask] = 0
    else:
        Xc = X[:, valid_mask]
    return super()._concatenate_indicator(Xc, X_indicator)

def get_feature_names_out(self, input_features=None):
    check_is_fitted(self, 'n_features_in_')
    input_features = _check_feature_names_in(self, input_features)
    names = input_features[self._valid_mask]
    return self._concatenate_indicator_feature_names_out(names, input_features)

def _grid_from_X(X, percentiles, is_categorical, grid_resolution, custom_values):
    if not isinstance(percentiles, Iterable) or len(percentiles) != 2:
        raise ValueError("'percentiles' must be a sequence of 2 elements.")
    if not all((0 <= x <= 1 for x in percentiles)):
        raise ValueError("'percentiles' values must be in [0, 1].")
    if percentiles[0] >= percentiles[1]:
        raise ValueError('percentiles[0] must be strictly less than percentiles[1].')
    if grid_resolution <= 1:
        raise ValueError("'grid_resolution' must be strictly greater than 1.")

    def _convert_custom_values(values):
        dtype = object if any((isinstance(v, str) for v in values)) else None
        return np.asarray(values, dtype=dtype)
    custom_values = {k: _convert_custom_values(v) for k, v in custom_values.items()}
    if any((v.ndim != 1 for v in custom_values.values())):
        error_string = ', '.join((f'Feature {k}: {v.ndim} dimensions' for k, v in custom_values.items() if v.ndim != 1))
        raise ValueError(f'The custom grid for some features is not a one-dimensional array. {error_string}')
    values = []
    for feature, is_cat in enumerate(is_categorical):
        if feature in custom_values:
            axis = custom_values[feature]
        else:
            try:
                uniques = np.unique(_safe_indexing(X, feature, axis=1))
            except TypeError as exc:
                raise ValueError(f'The column #{feature} contains mixed data types. Finding unique categories fail due to sorting. It usually means that the column contains `np.nan` values together with `str` categories. Such use case is not yet supported in scikit-learn.') from exc
            if is_cat or uniques.shape[0] < grid_resolution:
                axis = uniques
            else:
                emp_percentiles = mquantiles(_safe_indexing(X, feature, axis=1), prob=percentiles, axis=0)
                if np.allclose(emp_percentiles[0], emp_percentiles[1]):
                    raise ValueError('percentiles are too close to each other, unable to build the grid. Please choose percentiles that are further apart.')
                axis = np.linspace(emp_percentiles[0], emp_percentiles[1], num=grid_resolution, endpoint=True)
        values.append(axis)
    return (cartesian(values), values)

def _partial_dependence_recursion(est, grid, features):
    averaged_predictions = est._compute_partial_dependence_recursion(grid, features)
    if averaged_predictions.ndim == 1:
        averaged_predictions = averaged_predictions.reshape(1, -1)
    return averaged_predictions

def _partial_dependence_brute(est, grid, features, X, response_method, sample_weight=None):
    predictions = []
    averaged_predictions = []
    if response_method == 'auto':
        response_method = 'predict' if is_regressor(est) else ['predict_proba', 'decision_function']
    X_eval = X.copy()
    for new_values in grid:
        for i, variable in enumerate(features):
            _safe_assign(X_eval, new_values[i], column_indexer=variable)
        pred, _ = _get_response_values(est, X_eval, response_method=response_method)
        predictions.append(pred)
        averaged_predictions.append(np.average(pred, axis=0, weights=sample_weight))
    n_samples = X.shape[0]
    predictions = np.array(predictions).T
    if is_regressor(est) and predictions.ndim == 2:
        predictions = predictions.reshape(n_samples, -1)
    elif is_classifier(est) and predictions.shape[0] == 2:
        predictions = predictions[1]
        predictions = predictions.reshape(n_samples, -1)
    averaged_predictions = np.array(averaged_predictions).T
    if averaged_predictions.ndim == 1:
        averaged_predictions = averaged_predictions.reshape(1, -1)
    return (averaged_predictions, predictions)

@validate_params({'estimator': [HasMethods(['fit', 'predict']), HasMethods(['fit', 'predict_proba']), HasMethods(['fit', 'decision_function'])], 'X': ['array-like', 'sparse matrix'], 'features': ['array-like', Integral, str], 'sample_weight': ['array-like', None], 'categorical_features': ['array-like', None], 'feature_names': ['array-like', None], 'response_method': [StrOptions({'auto', 'predict_proba', 'decision_function'})], 'percentiles': [tuple], 'grid_resolution': [Interval(Integral, 1, None, closed='left')], 'method': [StrOptions({'auto', 'recursion', 'brute'})], 'kind': [StrOptions({'average', 'individual', 'both'})], 'custom_values': [dict, None]}, prefer_skip_nested_validation=True)
def partial_dependence(estimator, X, features, *, sample_weight=None, categorical_features=None, feature_names=None, response_method='auto', percentiles=(0.05, 0.95), grid_resolution=100, custom_values=None, method='auto', kind='average'):
    check_is_fitted(estimator)
    if not (is_classifier(estimator) or is_regressor(estimator)):
        raise ValueError("'estimator' must be a fitted regressor or classifier.")
    if is_classifier(estimator) and isinstance(estimator.classes_[0], np.ndarray):
        raise ValueError('Multiclass-multioutput estimators are not supported')
    if not (hasattr(X, '__array__') or sparse.issparse(X)):
        X = check_array(X, ensure_all_finite='allow-nan', dtype=object)
    if is_regressor(estimator) and response_method != 'auto':
        raise ValueError("The response_method parameter is ignored for regressors and must be 'auto'.")
    if kind != 'average':
        if method == 'recursion':
            raise ValueError("The 'recursion' method only applies when 'kind' is set to 'average'")
        method = 'brute'
    if method == 'recursion' and sample_weight is not None:
        raise ValueError("The 'recursion' method can only be applied when sample_weight is None.")
    if method == 'auto':
        if sample_weight is not None:
            method = 'brute'
        elif isinstance(estimator, BaseGradientBoosting) and estimator.init is None:
            method = 'recursion'
        elif isinstance(estimator, (BaseHistGradientBoosting, DecisionTreeRegressor, RandomForestRegressor)):
            method = 'recursion'
        else:
            method = 'brute'
    if method == 'recursion':
        if not isinstance(estimator, (BaseGradientBoosting, BaseHistGradientBoosting, DecisionTreeRegressor, RandomForestRegressor)):
            supported_classes_recursion = ('GradientBoostingClassifier', 'GradientBoostingRegressor', 'HistGradientBoostingClassifier', 'HistGradientBoostingRegressor', 'HistGradientBoostingRegressor', 'DecisionTreeRegressor', 'RandomForestRegressor')
            raise ValueError("Only the following estimators support the 'recursion' method: {}. Try using method='brute'.".format(', '.join(supported_classes_recursion)))
        if response_method == 'auto':
            response_method = 'decision_function'
        if response_method != 'decision_function':
            raise ValueError(f"With the 'recursion' method, the response_method must be 'decision_function'. Got {response_method}.")
    if sample_weight is not None:
        sample_weight = _check_sample_weight(sample_weight, X)
    if _determine_key_type(features, accept_slice=False) == 'int':
        if np.any(np.less(features, 0)):
            raise ValueError(f'all features must be in [0, {X.shape[1] - 1}]')
    features_indices = np.asarray(_get_column_indices(X, features), dtype=np.intp, order='C').ravel()
    feature_names = _check_feature_names(X, feature_names)
    n_features = X.shape[1]
    if categorical_features is None:
        is_categorical = [False] * len(features_indices)
    else:
        categorical_features = np.asarray(categorical_features)
        if categorical_features.size == 0:
            raise ValueError('Passing an empty list (`[]`) to `categorical_features` is not supported. Use `None` instead to indicate that there are no categorical features.')
        if categorical_features.dtype.kind == 'b':
            if categorical_features.size != n_features:
                raise ValueError(f'When `categorical_features` is a boolean array-like, the array should be of shape (n_features,). Got {categorical_features.size} elements while `X` contains {n_features} features.')
            is_categorical = [categorical_features[idx] for idx in features_indices]
        elif categorical_features.dtype.kind in ('i', 'O', 'U'):
            categorical_features_idx = [_get_feature_index(cat, feature_names=feature_names) for cat in categorical_features]
            is_categorical = [idx in categorical_features_idx for idx in features_indices]
        else:
            raise ValueError(f'Expected `categorical_features` to be an array-like of boolean, integer, or string. Got {categorical_features.dtype} instead.')
    custom_values = custom_values or {}
    if isinstance(features, (str, int)):
        features = [features]
    for feature_idx, feature, is_cat in zip(features_indices, features, is_categorical):
        if is_cat:
            continue
        if _safe_indexing(X, feature_idx, axis=1).dtype.kind in 'iu':
            raise ValueError(f'The column {feature!r} contains integer data. Partial dependence plots are not supported for integer data: this can lead to implicit rounding with NumPy arrays or even errors with newer pandas versions. Please convert numerical features to floating point dtypes ahead of time to avoid problems.')
    X_subset = _safe_indexing(X, features_indices, axis=1)
    custom_values_for_X_subset = {index: custom_values.get(feature) for index, feature in enumerate(features) if feature in custom_values}
    grid, values = _grid_from_X(X_subset, percentiles, is_categorical, grid_resolution, custom_values_for_X_subset)
    if method == 'brute':
        averaged_predictions, predictions = _partial_dependence_brute(estimator, grid, features_indices, X, response_method, sample_weight)
        predictions = predictions.reshape(-1, X.shape[0], *[val.shape[0] for val in values])
    else:
        averaged_predictions = _partial_dependence_recursion(estimator, grid, features_indices)
    averaged_predictions = averaged_predictions.reshape(-1, *[val.shape[0] for val in values])
    pdp_results = Bunch(grid_values=values)
    if kind == 'average':
        pdp_results['average'] = averaged_predictions
    elif kind == 'individual':
        pdp_results['individual'] = predictions
    else:
        pdp_results['average'] = averaged_predictions
        pdp_results['individual'] = predictions
    return pdp_results

def _check_feature_names(X, feature_names=None):
    if feature_names is None:
        if hasattr(X, 'columns') and hasattr(X.columns, 'tolist'):
            feature_names = X.columns.tolist()
        else:
            feature_names = [f'x{i}' for i in range(X.shape[1])]
    elif hasattr(feature_names, 'tolist'):
        feature_names = feature_names.tolist()
    if len(set(feature_names)) != len(feature_names):
        raise ValueError('feature_names should not contain duplicates.')
    return feature_names

def _get_feature_index(fx, feature_names=None):
    if isinstance(fx, str):
        if feature_names is None:
            raise ValueError(f'Cannot plot partial dependence for feature {fx!r} since the list of feature names was not provided, neither as column names of a pandas data-frame nor via the feature_names parameter.')
        try:
            return feature_names.index(fx)
        except ValueError as e:
            raise ValueError(f'Feature {fx!r} not in feature_names') from e
    return fx

def _calculate_permutation_scores(estimator, X, y, sample_weight, col_idx, random_state, n_repeats, scorer, max_samples):
    random_state = check_random_state(random_state)
    if max_samples < X.shape[0]:
        row_indices = _generate_indices(random_state=random_state, bootstrap=False, n_population=X.shape[0], n_samples=max_samples)
        X_permuted = _safe_indexing(X, row_indices, axis=0)
        y = _safe_indexing(y, row_indices, axis=0)
        if sample_weight is not None:
            sample_weight = _safe_indexing(sample_weight, row_indices, axis=0)
    else:
        X_permuted = X.copy()
    scores = []
    shuffling_idx = np.arange(X_permuted.shape[0])
    for _ in range(n_repeats):
        random_state.shuffle(shuffling_idx)
        if hasattr(X_permuted, 'iloc'):
            col = X_permuted.iloc[shuffling_idx, col_idx]
            col.index = X_permuted.index
            X_permuted[X_permuted.columns[col_idx]] = col
        else:
            X_permuted[:, col_idx] = X_permuted[shuffling_idx, col_idx]
        scores.append(_weights_scorer(scorer, estimator, X_permuted, y, sample_weight))
    if isinstance(scores[0], dict):
        scores = _aggregate_score_dicts(scores)
    else:
        scores = np.array(scores)
    return scores

def _create_importances_bunch(baseline_score, permuted_score):
    importances = baseline_score - permuted_score
    return Bunch(importances_mean=np.mean(importances, axis=1), importances_std=np.std(importances, axis=1), importances=importances)

@validate_params({'estimator': [HasMethods(['fit'])], 'X': ['array-like'], 'y': ['array-like', None], 'scoring': [StrOptions(set(get_scorer_names())), callable, list, tuple, dict, None], 'n_repeats': [Interval(Integral, 1, None, closed='left')], 'n_jobs': [Integral, None], 'random_state': ['random_state'], 'sample_weight': ['array-like', None], 'max_samples': [Interval(Integral, 1, None, closed='left'), Interval(RealNotInt, 0, 1, closed='right')]}, prefer_skip_nested_validation=True)
def permutation_importance(estimator, X, y, *, scoring=None, n_repeats=5, n_jobs=None, random_state=None, sample_weight=None, max_samples=1.0):
    if not hasattr(X, 'iloc'):
        X = check_array(X, ensure_all_finite='allow-nan', dtype=None)
    random_state = check_random_state(random_state)
    random_seed = random_state.randint(np.iinfo(np.int32).max + 1)
    if not isinstance(max_samples, numbers.Integral):
        max_samples = int(max_samples * X.shape[0])
    elif max_samples > X.shape[0]:
        raise ValueError('max_samples must be <= n_samples')
    scorer = check_scoring(estimator, scoring=scoring)
    baseline_score = _weights_scorer(scorer, estimator, X, y, sample_weight)
    scores = Parallel(n_jobs=n_jobs)((delayed(_calculate_permutation_scores)(estimator, X, y, sample_weight, col_idx, random_seed, n_repeats, scorer, max_samples) for col_idx in range(X.shape[1])))
    if isinstance(baseline_score, dict):
        return {name: _create_importances_bunch(baseline_score[name], np.array([scores[col_idx][name] for col_idx in range(X.shape[1])])) for name in baseline_score}
    else:
        return _create_importances_bunch(baseline_score, np.array(scores))

def _check_boundary_response_method(estimator, response_method):
    has_classes = hasattr(estimator, 'classes_')
    if has_classes and _is_arraylike_not_scalar(estimator.classes_[0]):
        msg = 'Multi-label and multi-output multi-class classifiers are not supported'
        raise ValueError(msg)
    if response_method == 'auto':
        if is_regressor(estimator):
            prediction_method = 'predict'
        else:
            prediction_method = ['decision_function', 'predict_proba', 'predict']
    else:
        prediction_method = response_method
    return prediction_method

def _deprecate_multiclass_colors(multiclass_colors, target_colors):
    if multiclass_colors != 'deprecated':
        warnings.warn("'multiclass_colors' was renamed to 'target_colors' in 1.10 and will be removed in 1.12.", FutureWarning)
        if target_colors is not None:
            raise ValueError("'multiclass_colors' and 'target_colors' cannot be used together. Pass `target_colors` only.")
        return multiclass_colors
    return target_colors

def _select_colors(mpl, target_colors, n_classes):
    if target_colors is None:
        if n_classes <= 10:
            target_colors = PETROFF_COLORS[:n_classes]
        else:
            target_colors = 'gist_rainbow'
    if isinstance(target_colors, str):
        if target_colors not in mpl.pyplot.colormaps():
            raise ValueError(f"When 'target_colors' is a string, it must be a valid Matplotlib colormap. Got: {target_colors}")
        cmap = mpl.pyplot.get_cmap(target_colors)
        if cmap.N < n_classes:
            raise ValueError(f"Colormap '{target_colors}' only has {cmap.N} colors, but {n_classes} classes are to be displayed. Please specify a different colormap or provide a list of colors via 'target_colors'.")
        return cmap(np.linspace(0, 1, n_classes))
    elif isinstance(target_colors, list):
        if len(target_colors) != n_classes:
            raise ValueError(f"When 'target_colors' is a list, it must be of the same length as the classes or labels to plot ({n_classes}), got: {len(target_colors)}.")
        elif any((not mpl.colors.is_color_like(col) for col in target_colors)):
            raise ValueError(f"When 'target_colors' is a list, it can only contain valid Matplotlib color names. Got: {target_colors}")
        return mpl.colors.to_rgba_array(target_colors)
    else:
        raise TypeError("'target_colors' must be a list or a str.")

def plot(self, plot_method='contourf', ax=None, xlabel=None, ylabel=None, **kwargs):
    check_matplotlib_support('DecisionBoundaryDisplay.plot')
    import matplotlib as mpl
    import matplotlib.pyplot as plt
    if plot_method not in ('contourf', 'contour', 'pcolormesh'):
        raise ValueError(f"plot_method must be 'contourf', 'contour', or 'pcolormesh'. Got {plot_method} instead.")
    if ax is None:
        _, ax = plt.subplots()
    plot_func = getattr(ax, plot_method)
    if self.n_classes == 2:
        self.surface_ = plot_func(self.xx0, self.xx1, self.response, **kwargs)
    else:
        for kwarg in ('cmap', 'colors'):
            if kwarg in kwargs:
                warnings.warn(f"'{kwarg}' is ignored in favor of 'target_colors' in the multiclass case.")
                del kwargs[kwarg]
        self.target_colors_ = _select_colors(mpl, self.target_colors, self.n_classes)
        if 'zorder' not in kwargs:
            kwargs['zorder'] = -1
        if self.response.ndim == 3:
            multiclass_cmaps = [mpl.colors.LinearSegmentedColormap.from_list(f'colormap_{class_idx}', [(1.0, 1.0, 1.0, 1.0), (r, g, b, 1.0)]) for class_idx, (r, g, b, _) in enumerate(self.target_colors_)]
            self.surface_ = []
            for class_idx, cmap in enumerate(multiclass_cmaps):
                response = np.ma.array(self.response[:, :, class_idx], mask=self.response.argmax(axis=2) != class_idx)
                self.surface_.append(plot_func(self.xx0, self.xx1, response, cmap=cmap, **kwargs))
            if plot_method == 'contour':
                self.surface_.append(plot_func(self.xx0, self.xx1, self.response.argmax(axis=2), colors='black', zorder=-1, levels=np.arange(self.n_classes)))
        elif self.response.ndim == 2:
            if 'levels' not in kwargs:
                if plot_method == 'contour':
                    kwargs['levels'] = np.arange(self.n_classes)
                elif plot_method == 'contourf':
                    kwargs['levels'] = np.arange(self.n_classes + 1) - 0.5
            if plot_method == 'contour':
                self.surface_ = plot_func(self.xx0, self.xx1, self.response, colors='black', **kwargs)
            else:
                cmap = mpl.colors.ListedColormap(self.target_colors_)
                self.surface_ = plot_func(self.xx0, self.xx1, self.response, cmap=cmap, **kwargs)
    if xlabel is not None or not ax.get_xlabel():
        xlabel = self.xlabel if xlabel is None else xlabel
        ax.set_xlabel(xlabel)
    if ylabel is not None or not ax.get_ylabel():
        ylabel = self.ylabel if ylabel is None else ylabel
        ax.set_ylabel(ylabel)
    self.ax_ = ax
    self.figure_ = ax.figure
    return self

@classmethod
def from_estimator(cls, estimator, X, *, grid_resolution=100, eps=1.0, plot_method='contourf', response_method='auto', class_of_interest=None, target_colors=None, xlabel=None, ylabel=None, ax=None, multiclass_colors='deprecated', **kwargs):
    check_is_fitted(estimator)
    if not grid_resolution > 1:
        raise ValueError(f'grid_resolution must be greater than 1. Got {grid_resolution} instead.')
    if not eps >= 0:
        raise ValueError(f'eps must be greater than or equal to 0. Got {eps} instead.')
    possible_plot_methods = ('contourf', 'contour', 'pcolormesh')
    if plot_method not in possible_plot_methods:
        available_methods = ', '.join(possible_plot_methods)
        raise ValueError(f'plot_method must be one of {available_methods}. Got {plot_method} instead.')
    num_features = _num_features(X)
    if num_features != 2:
        raise ValueError(f'n_features must be equal to 2. Got {num_features} instead.')
    x0, x1 = (_safe_indexing(X, 0, axis=1), _safe_indexing(X, 1, axis=1))
    x0_min, x0_max = (x0.min() - eps, x0.max() + eps)
    x1_min, x1_max = (x1.min() - eps, x1.max() + eps)
    xx0, xx1 = np.meshgrid(np.linspace(x0_min, x0_max, grid_resolution), np.linspace(x1_min, x1_max, grid_resolution))
    X_grid = np.c_[xx0.ravel(), xx1.ravel()]
    if nw.dependencies.is_pandas_dataframe(X) or is_polars_df(X):
        adapter = _get_adapter_from_container(X)
        X_grid = adapter.create_container(X_grid, X_grid, columns=X.columns)
    prediction_method = _check_boundary_response_method(estimator, response_method)
    if (class_of_interest is not None and hasattr(estimator, 'classes_')) and class_of_interest not in estimator.classes_:
        raise ValueError(f'class_of_interest={class_of_interest} is not a valid label: It should be one of {estimator.classes_}')
    response, _, response_method_used = _get_response_values(estimator, X_grid, response_method=prediction_method, pos_label=class_of_interest, return_response_method_used=True)
    if response_method_used == 'predict' and hasattr(estimator, 'classes_'):
        encoder = LabelEncoder()
        encoder.classes_ = estimator.classes_
        response = encoder.transform(response)
    if class_of_interest is not None or is_regressor(estimator) or is_outlier_detector(estimator):
        n_classes = 2
    elif is_classifier(estimator) and hasattr(estimator, 'classes_'):
        n_classes = len(estimator.classes_)
    elif is_clusterer(estimator) and hasattr(estimator, 'labels_'):
        n_classes = len(np.unique(estimator.labels_))
    else:
        target_type = type_of_target(response)
        if target_type in ('binary', 'continuous'):
            n_classes = 2
        elif target_type == 'multiclass':
            n_classes = len(np.unique(response))
        else:
            raise ValueError(f"Number of classes or labels cannot be inferred from {estimator.__class__.__name__}. Please make sure your estimator follows scikit-learn's estimator API as described here: https://scikit-learn.org/stable/developers/develop.html#rolling-your-own-estimator")
    if response.ndim == 1:
        response = response.reshape(*xx0.shape)
    else:
        if is_regressor(estimator):
            raise ValueError('Multi-output regressors are not supported')
        if class_of_interest is not None:
            col_idx = np.flatnonzero(estimator.classes_ == class_of_interest)[0]
            response = response[:, col_idx].reshape(*xx0.shape)
        else:
            response = response.reshape(*xx0.shape, response.shape[-1])
    if xlabel is None:
        xlabel = X.columns[0] if hasattr(X, 'columns') else ''
    if ylabel is None:
        ylabel = X.columns[1] if hasattr(X, 'columns') else ''
    target_colors = _deprecate_multiclass_colors(multiclass_colors, target_colors)
    display = cls(xx0=xx0, xx1=xx1, n_classes=n_classes, response=response, target_colors=target_colors, xlabel=xlabel, ylabel=ylabel)
    return display.plot(ax=ax, plot_method=plot_method, **kwargs)

@classmethod
def from_estimator(cls, estimator, X, features, *, sample_weight=None, categorical_features=None, feature_names=None, target=None, response_method='auto', n_cols=3, grid_resolution=100, percentiles=(0.05, 0.95), custom_values=None, method='auto', n_jobs=None, verbose=0, line_kw=None, ice_lines_kw=None, pd_line_kw=None, contour_kw=None, ax=None, kind='average', centered=False, subsample=1000, random_state=None):
    check_matplotlib_support(f'{cls.__name__}.from_estimator')
    import matplotlib.pyplot as plt
    if hasattr(estimator, 'classes_') and np.size(estimator.classes_) > 2:
        if target is None:
            raise ValueError('target must be specified for multi-class')
        target_idx = np.searchsorted(estimator.classes_, target)
        if not 0 <= target_idx < len(estimator.classes_) or estimator.classes_[target_idx] != target:
            raise ValueError('target not in est.classes_, got {}'.format(target))
    else:
        target_idx = 0
    if not (hasattr(X, '__array__') or sparse.issparse(X)):
        X = check_array(X, ensure_all_finite='allow-nan', dtype=object)
    n_features = X.shape[1]
    feature_names = _check_feature_names(X, feature_names)
    kind_ = [kind] * len(features) if isinstance(kind, str) else kind
    if len(kind_) != len(features):
        raise ValueError(f'When `kind` is provided as a list of strings, it should contain as many elements as `features`. `kind` contains {len(kind_)} element(s) and `features` contains {len(features)} element(s).')
    tmp_features, ice_for_two_way_pd = ([], [])
    for kind_plot, fxs in zip(kind_, features):
        if isinstance(fxs, (numbers.Integral, str)):
            fxs = (fxs,)
        try:
            fxs = tuple((_get_feature_index(fx, feature_names=feature_names) for fx in fxs))
        except TypeError as e:
            raise ValueError('Each entry in features must be either an int, a string, or an iterable of size at most 2.') from e
        if not 1 <= np.size(fxs) <= 2:
            raise ValueError('Each entry in features must be either an int, a string, or an iterable of size at most 2.')
        ice_for_two_way_pd.append(kind_plot != 'average' and np.size(fxs) > 1)
        tmp_features.append(fxs)
    if any(ice_for_two_way_pd):
        kind_ = ['average' if forcing_average else kind_plot for forcing_average, kind_plot in zip(ice_for_two_way_pd, kind_)]
        raise ValueError(f"ICE plot cannot be rendered for 2-way feature interactions. 2-way feature interactions mandates PD plots using the 'average' kind: features={features!r} should be configured to use kind={kind_!r} explicitly.")
    features = tmp_features
    if categorical_features is None:
        is_categorical = [(False,) if len(fxs) == 1 else (False, False) for fxs in features]
    else:
        categorical_features = np.asarray(categorical_features)
        if categorical_features.dtype.kind == 'b':
            if categorical_features.size != n_features:
                raise ValueError(f'When `categorical_features` is a boolean array-like, the array should be of shape (n_features,). Got {categorical_features.size} elements while `X` contains {n_features} features.')
            is_categorical = [tuple((categorical_features[fx] for fx in fxs)) for fxs in features]
        elif categorical_features.dtype.kind in ('i', 'O', 'U'):
            categorical_features_idx = [_get_feature_index(cat, feature_names=feature_names) for cat in categorical_features]
            is_categorical = [tuple([idx in categorical_features_idx for idx in fxs]) for fxs in features]
        else:
            raise ValueError(f'Expected `categorical_features` to be an array-like of boolean, integer, or string. Got {categorical_features.dtype} instead.')
        for cats in is_categorical:
            if np.size(cats) == 2 and cats[0] != cats[1]:
                raise ValueError('Two-way partial dependence plots are not supported for pairs of continuous and categorical features.')
        categorical_features_targeted = set([fx for fxs, cats in zip(features, is_categorical) for fx in fxs if any(cats)])
        if categorical_features_targeted:
            min_n_cats = min([len(_unique(_safe_indexing(X, idx, axis=1))) for idx in categorical_features_targeted])
            if grid_resolution < min_n_cats:
                raise ValueError(f'The resolution of the computed grid is less than the minimum number of categories in the targeted categorical features. Expect the `grid_resolution` to be greater than {min_n_cats}. Got {grid_resolution} instead.')
        for is_cat, kind_plot in zip(is_categorical, kind_):
            if any(is_cat) and kind_plot != 'average':
                raise ValueError('It is not possible to display individual effects for categorical features.')
    if ax is not None and (not isinstance(ax, plt.Axes)):
        axes = np.asarray(ax, dtype=object)
        if axes.size != len(features):
            raise ValueError('Expected ax to have {} axes, got {}'.format(len(features), axes.size))
    for i in chain.from_iterable(features):
        if i >= len(feature_names):
            raise ValueError('All entries of features must be less than len(feature_names) = {0}, got {1}.'.format(len(feature_names), i))
    if isinstance(subsample, numbers.Integral):
        if subsample <= 0:
            raise ValueError(f'When an integer, subsample={subsample} should be positive.')
    elif isinstance(subsample, numbers.Real):
        if subsample <= 0 or subsample >= 1:
            raise ValueError(f'When a floating-point, subsample={subsample} should be in the (0, 1) range.')
    pd_results = Parallel(n_jobs=n_jobs, verbose=verbose)((delayed(partial_dependence)(estimator, X, fxs, sample_weight=sample_weight, feature_names=feature_names, categorical_features=categorical_features, response_method=response_method, method=method, grid_resolution=grid_resolution, percentiles=percentiles, kind=kind_plot, custom_values=custom_values) for kind_plot, fxs in zip(kind_, features)))
    pd_result = pd_results[0]
    n_tasks = pd_result.average.shape[0] if kind_[0] == 'average' else pd_result.individual.shape[0]
    if is_regressor(estimator) and n_tasks > 1:
        if target is None:
            raise ValueError('target must be specified for multi-output regressors')
        if not 0 <= target <= n_tasks:
            raise ValueError('target must be in [0, n_tasks], got {}.'.format(target))
        target_idx = target
    deciles = {}
    for fxs, cats in zip(features, is_categorical):
        for fx, cat in zip(fxs, cats):
            if not cat and fx not in deciles:
                X_col = _safe_indexing(X, fx, axis=1)
                deciles[fx] = mquantiles(X_col, prob=np.arange(0.1, 1.0, 0.1))
    display = cls(pd_results=pd_results, features=features, feature_names=feature_names, target_idx=target_idx, deciles=deciles, kind=kind, subsample=subsample, random_state=random_state, is_categorical=is_categorical)
    return display.plot(ax=ax, n_cols=n_cols, line_kw=line_kw, ice_lines_kw=ice_lines_kw, pd_line_kw=pd_line_kw, contour_kw=contour_kw, centered=centered)

def _get_sample_count(self, n_samples):
    if isinstance(self.subsample, numbers.Integral):
        if self.subsample < n_samples:
            return self.subsample
        return n_samples
    elif isinstance(self.subsample, numbers.Real):
        return ceil(n_samples * self.subsample)
    return n_samples

def _plot_average_dependence(self, avg_preds, feature_values, ax, pd_line_idx, line_kw, categorical, bar_kw):
    if categorical:
        bar_idx = np.unravel_index(pd_line_idx, self.bars_.shape)
        self.bars_[bar_idx] = ax.bar(feature_values, avg_preds, **bar_kw)[0]
        ax.tick_params(axis='x', rotation=90)
    else:
        line_idx = np.unravel_index(pd_line_idx, self.lines_.shape)
        self.lines_[line_idx] = ax.plot(feature_values, avg_preds, **line_kw)[0]

def _plot_one_way_partial_dependence(self, kind, preds, avg_preds, feature_values, feature_idx, n_ice_lines, ax, n_cols, pd_plot_idx, n_lines, ice_lines_kw, pd_line_kw, categorical, bar_kw, pdp_lim):
    from matplotlib import transforms
    if kind in ('individual', 'both'):
        self._plot_ice_lines(preds[self.target_idx], feature_values, n_ice_lines, ax, pd_plot_idx, n_lines, ice_lines_kw)
    if kind in ('average', 'both'):
        if kind == 'average':
            pd_line_idx = pd_plot_idx
        else:
            pd_line_idx = pd_plot_idx * n_lines + n_ice_lines
        self._plot_average_dependence(avg_preds[self.target_idx].ravel(), feature_values, ax, pd_line_idx, pd_line_kw, categorical, bar_kw)
    trans = transforms.blended_transform_factory(ax.transData, ax.transAxes)
    vlines_idx = np.unravel_index(pd_plot_idx, self.deciles_vlines_.shape)
    if self.deciles.get(feature_idx[0], None) is not None:
        self.deciles_vlines_[vlines_idx] = ax.vlines(self.deciles[feature_idx[0]], 0, 0.05, transform=trans, color='k')
    min_val = min((val[0] for val in pdp_lim.values()))
    max_val = max((val[1] for val in pdp_lim.values()))
    ax.set_ylim([min_val, max_val])
    if not ax.get_xlabel():
        ax.set_xlabel(self.feature_names[feature_idx[0]])
    if n_cols is None or pd_plot_idx % n_cols == 0:
        if not ax.get_ylabel():
            ax.set_ylabel('Partial dependence')
    else:
        ax.set_yticklabels([])
    if pd_line_kw.get('label', None) and kind != 'individual' and (not categorical):
        ax.legend()

def plot(self, *, ax=None, n_cols=3, line_kw=None, ice_lines_kw=None, pd_line_kw=None, contour_kw=None, bar_kw=None, heatmap_kw=None, pdp_lim=None, centered=False):
    check_matplotlib_support('plot_partial_dependence')
    import matplotlib.pyplot as plt
    from matplotlib.gridspec import GridSpecFromSubplotSpec
    if isinstance(self.kind, str):
        kind = [self.kind] * len(self.features)
    else:
        kind = self.kind
    if self.is_categorical is None:
        is_categorical = [(False,) if len(fx) == 1 else (False, False) for fx in self.features]
    else:
        is_categorical = self.is_categorical
    if len(kind) != len(self.features):
        raise ValueError(f'When `kind` is provided as a list of strings, it should contain as many elements as `features`. `kind` contains {len(kind)} element(s) and `features` contains {len(self.features)} element(s).')
    valid_kinds = {'average', 'individual', 'both'}
    if any([k not in valid_kinds for k in kind]):
        raise ValueError(f'Values provided to `kind` must be one of: {valid_kinds!r} or a list of such values. Currently, kind={self.kind!r}')
    if not centered:
        pd_results_ = self.pd_results
    else:
        pd_results_ = []
        for kind_plot, pd_result in zip(kind, self.pd_results):
            current_results = {'grid_values': pd_result['grid_values']}
            if kind_plot in ('individual', 'both'):
                preds = pd_result.individual
                preds = preds - preds[self.target_idx, :, 0, None]
                current_results['individual'] = preds
            if kind_plot in ('average', 'both'):
                avg_preds = pd_result.average
                avg_preds = avg_preds - avg_preds[self.target_idx, 0, None]
                current_results['average'] = avg_preds
            pd_results_.append(Bunch(**current_results))
    if pdp_lim is None:
        pdp_lim = {}
        for kind_plot, pdp in zip(kind, pd_results_):
            values = pdp['grid_values']
            preds = pdp.average if kind_plot == 'average' else pdp.individual
            min_pd = preds[self.target_idx].min()
            max_pd = preds[self.target_idx].max()
            span = max_pd - min_pd
            min_pd -= 0.05 * span
            max_pd += 0.05 * span
            n_fx = len(values)
            old_min_pd, old_max_pd = pdp_lim.get(n_fx, (min_pd, max_pd))
            min_pd = min(min_pd, old_min_pd)
            max_pd = max(max_pd, old_max_pd)
            pdp_lim[n_fx] = (min_pd, max_pd)
    if line_kw is None:
        line_kw = {}
    if ice_lines_kw is None:
        ice_lines_kw = {}
    if pd_line_kw is None:
        pd_line_kw = {}
    if bar_kw is None:
        bar_kw = {}
    if heatmap_kw is None:
        heatmap_kw = {}
    if ax is None:
        _, ax = plt.subplots()
    if contour_kw is None:
        contour_kw = {}
    default_contour_kws = {'alpha': 0.75}
    contour_kw = _validate_style_kwargs(default_contour_kws, contour_kw)
    n_features = len(self.features)
    is_average_plot = [kind_plot == 'average' for kind_plot in kind]
    if all(is_average_plot):
        n_ice_lines = 0
        n_lines = 1
    else:
        ice_plot_idx = is_average_plot.index(False)
        n_ice_lines = self._get_sample_count(len(pd_results_[ice_plot_idx].individual[0]))
        if any([kind_plot == 'both' for kind_plot in kind]):
            n_lines = n_ice_lines + 1
        else:
            n_lines = n_ice_lines
    if isinstance(ax, plt.Axes):
        if not ax.axison:
            raise ValueError('The ax was already used in another plot function, please set ax=display.axes_ instead')
        ax.set_axis_off()
        self.bounding_ax_ = ax
        self.figure_ = ax.figure
        n_cols = min(n_cols, n_features)
        n_rows = int(np.ceil(n_features / float(n_cols)))
        self.axes_ = np.empty((n_rows, n_cols), dtype=object)
        if all(is_average_plot):
            self.lines_ = np.empty((n_rows, n_cols), dtype=object)
        else:
            self.lines_ = np.empty((n_rows, n_cols, n_lines), dtype=object)
        self.contours_ = np.empty((n_rows, n_cols), dtype=object)
        self.bars_ = np.empty((n_rows, n_cols), dtype=object)
        self.heatmaps_ = np.empty((n_rows, n_cols), dtype=object)
        axes_ravel = self.axes_.ravel()
        gs = GridSpecFromSubplotSpec(n_rows, n_cols, subplot_spec=ax.get_subplotspec())
        for i, spec in zip(range(n_features), gs):
            axes_ravel[i] = self.figure_.add_subplot(spec)
    else:
        ax = np.asarray(ax, dtype=object)
        if ax.size != n_features:
            raise ValueError('Expected ax to have {} axes, got {}'.format(n_features, ax.size))
        if ax.ndim == 2:
            n_cols = ax.shape[1]
        else:
            n_cols = None
        self.bounding_ax_ = None
        self.figure_ = ax.ravel()[0].figure
        self.axes_ = ax
        if all(is_average_plot):
            self.lines_ = np.empty_like(ax, dtype=object)
        else:
            self.lines_ = np.empty(ax.shape + (n_lines,), dtype=object)
        self.contours_ = np.empty_like(ax, dtype=object)
        self.bars_ = np.empty_like(ax, dtype=object)
        self.heatmaps_ = np.empty_like(ax, dtype=object)
    if 2 in pdp_lim:
        Z_level = np.linspace(*pdp_lim[2], num=8)
    self.deciles_vlines_ = np.empty_like(self.axes_, dtype=object)
    self.deciles_hlines_ = np.empty_like(self.axes_, dtype=object)
    for pd_plot_idx, (axi, feature_idx, cat, pd_result, kind_plot) in enumerate(zip(self.axes_.ravel(), self.features, is_categorical, pd_results_, kind)):
        avg_preds = None
        preds = None
        feature_values = pd_result['grid_values']
        if kind_plot == 'individual':
            preds = pd_result.individual
        elif kind_plot == 'average':
            avg_preds = pd_result.average
        else:
            avg_preds = pd_result.average
            preds = pd_result.individual
        if len(feature_values) == 1:
            default_line_kws = {'color': 'C0', 'label': 'average' if kind_plot == 'both' else None}
            if kind_plot == 'individual':
                default_ice_lines_kws = {'alpha': 0.3, 'linewidth': 0.5}
