            default_bar_kws = {'color': 'C0'}
            bar_kw = _validate_style_kwargs(default_bar_kws, bar_kw)
            default_heatmap_kw = {}
            heatmap_kw = _validate_style_kwargs(default_heatmap_kw, heatmap_kw)
            self._plot_one_way_partial_dependence(kind_plot, preds, avg_preds, feature_values[0], feature_idx, n_ice_lines, axi, n_cols, pd_plot_idx, n_lines, ice_lines_kw, pd_line_kw, cat[0], bar_kw, pdp_lim)
        else:
            self._plot_two_way_partial_dependence(avg_preds, feature_values, feature_idx, axi, pd_plot_idx, Z_level, contour_kw, cat[0] and cat[1], heatmap_kw)
    return self

def make_dataset(X, y, sample_weight, random_state=None):
    rng = check_random_state(random_state)
    seed = rng.randint(1, np.iinfo(np.int32).max)
    if X.dtype == np.float32:
        CSRData = CSRDataset32
        ArrayData = ArrayDataset32
    else:
        CSRData = CSRDataset64
        ArrayData = ArrayDataset64
    if sp.issparse(X):
        dataset = CSRData(X.data, X.indptr, X.indices, y, sample_weight, seed=seed)
        intercept_decay = SPARSE_INTERCEPT_DECAY
    else:
        X = np.ascontiguousarray(X)
        dataset = ArrayData(X, y, sample_weight, seed=seed)
        intercept_decay = 1.0
    return (dataset, intercept_decay)

def _preprocess_data(X, y, *, fit_intercept, copy=True, sample_weight=None, check_input=True, rescale_with_sw=True):
    xp, _, device_ = get_namespace_and_device(X, y, sample_weight)
    n_samples, n_features = X.shape
    X_is_sparse = sp.issparse(X)
    if check_input:
        X = check_array(X, copy=copy, accept_sparse=['csr', 'csc'], dtype=supported_float_dtypes(xp, device=device_))
        y = check_array(y, dtype=X.dtype, copy=True, ensure_2d=False)
    else:
        y = xp.astype(y, X.dtype)
        if copy:
            if X_is_sparse:
                X = X.copy()
            else:
                X = _asarray_with_order(X, order='K', copy=True, xp=xp)
    dtype_ = X.dtype
    if fit_intercept:
        if X_is_sparse:
            X_offset, X_var = mean_variance_axis(X, axis=0, weights=sample_weight)
        else:
            X_offset = _average(X, axis=0, weights=sample_weight, xp=xp)
            X_offset = xp.astype(X_offset, X.dtype, copy=False)
            X -= X_offset
        y_offset = _average(y, axis=0, weights=sample_weight, xp=xp)
        y -= y_offset
    else:
        X_offset = xp.zeros(n_features, dtype=X.dtype, device=device_)
        if y.ndim == 1:
            y_offset = xp.asarray(0.0, dtype=dtype_, device=device_)
        else:
            y_offset = xp.zeros(y.shape[1], dtype=dtype_, device=device_)
    X_scale = xp.ones(n_features, dtype=X.dtype, device=device_)
    if sample_weight is not None and rescale_with_sw:
        X, y, sample_weight_sqrt = _rescale_data(X, y, sample_weight, inplace=True)
    else:
        sample_weight_sqrt = None
    return (X, y, X_offset, y_offset, X_scale, sample_weight_sqrt)

def _rescale_data(X, y, sample_weight, inplace=False):
    xp, _ = get_namespace(X, y, sample_weight)
    n_samples = X.shape[0]
    sample_weight_sqrt = xp.sqrt(sample_weight)
    if sp.issparse(X) or sp.issparse(y):
        sw_matrix = sparse.dia_array((sample_weight_sqrt, 0), shape=(n_samples, n_samples))
    if sp.issparse(X):
        X = safe_sparse_dot(sw_matrix, X)
    elif inplace:
        X *= sample_weight_sqrt[:, None]
    else:
        X = X * sample_weight_sqrt[:, None]
    if sp.issparse(y):
        y = safe_sparse_dot(sw_matrix, y)
    elif inplace:
        if y.ndim == 1:
            y *= sample_weight_sqrt
        else:
            y *= sample_weight_sqrt[:, None]
    elif y.ndim == 1:
        y = y * sample_weight_sqrt
    else:
        y = y * sample_weight_sqrt[:, None]
    return (_align_api_if_sparse(X), _align_api_if_sparse(y), sample_weight_sqrt)

def _pre_fit(X, y, Xy, precompute, fit_intercept, copy, check_gram=True, sample_weight=None):
    n_samples, n_features = X.shape
    if sparse.issparse(X):
        copy = False
        precompute = False
        rescale_with_sw = False
    else:
        rescale_with_sw = True
    X, y, X_offset, y_offset, X_scale, _ = _preprocess_data(X, y, fit_intercept=fit_intercept, copy=copy, sample_weight=sample_weight, check_input=False, rescale_with_sw=rescale_with_sw)
    if hasattr(precompute, '__array__'):
        if fit_intercept and (not np.allclose(X_offset, np.zeros(n_features))):
            warnings.warn('Gram matrix was provided but X was centered to fit intercept: recomputing Gram matrix.', UserWarning)
            precompute = 'auto'
            Xy = None
        elif check_gram:
            _check_precomputed_gram_matrix(X, precompute, X_offset, X_scale)
    if isinstance(precompute, str) and precompute == 'auto':
        precompute = n_samples > n_features
    if precompute is True:
        precompute = np.empty(shape=(n_features, n_features), dtype=X.dtype, order='C')
        np.dot(X.T, X, out=precompute)
    if not hasattr(precompute, '__array__'):
        Xy = None
    if hasattr(precompute, '__array__') and Xy is None:
        common_dtype = np.result_type(X.dtype, y.dtype)
        if y.ndim == 1:
            Xy = np.empty(shape=n_features, dtype=common_dtype, order='C')
            np.dot(X.T, y, out=Xy)
        else:
            n_targets = y.shape[1]
            Xy = np.empty(shape=(n_features, n_targets), dtype=common_dtype, order='F')
            np.dot(y.T, X, out=Xy.T)
    return (X, y, X_offset, y_offset, X_scale, precompute, Xy)

@abstractmethod
def fit(self, X, y):
    pass

def predict(self, X):
    check_same_namespace(X, self, attribute='coef_', method='predict')
    return self._decision_function(X)

def _set_intercept(self, X_offset, y_offset, X_scale=None):
    xp, _ = get_namespace(X_offset, y_offset, X_scale)
    if self.fit_intercept:
        self.coef_ = xp.astype(self.coef_, X_offset.dtype, copy=False)
        if X_scale is not None:
            self.coef_ = xp.divide(self.coef_, X_scale)
        if self.coef_.ndim == 1:
            self.intercept_ = y_offset - X_offset @ self.coef_
        else:
            self.intercept_ = y_offset - X_offset @ self.coef_.T
    else:
        self.intercept_ = 0.0

def predict(self, X):
    check_same_namespace(X, self, attribute='coef_', method='predict')
    xp, _, device_ = get_namespace_and_device(X)
    scores = self.decision_function(X)
    if len(scores.shape) == 1:
        indices = xp.astype(scores > 0, indexing_dtype(xp))
    else:
        indices = xp.argmax(scores, axis=1)
    xp_classes, _, device_classes = get_namespace_and_device(self.classes_)
    indices = move_to(indices, xp=xp_classes, device=device_classes)
    y_pred = xp_classes.take(self.classes_, indices, axis=0)
    if isinstance(y_pred[0], str):
        return y_pred
    else:
        return move_to(y_pred, xp=xp, device=device_)

def _predict_proba_lr(self, X):
    xp, _ = get_namespace(X)
    prob = self.decision_function(X)
    prob = _expit(prob, out=prob, xp=xp)
    if prob.ndim == 1:
        return xp.stack([1 - prob, prob], axis=1)
    else:
        prob_sum = prob.sum(axis=1)
        all_zero = prob_sum == 0
        if xp.any(all_zero):
            prob[all_zero, :] = 1
            prob_sum[all_zero] = prob.shape[1]
        prob /= xp.reshape(prob_sum, (prob.shape[0], -1))
        return prob

def densify(self):
    msg = 'Estimator, %(name)s, must be fitted before densifying.'
    check_is_fitted(self, msg=msg)
    if sp.issparse(self.coef_):
        self.coef_ = self.coef_.toarray()
    return self

@_fit_context(prefer_skip_nested_validation=True)
def fit(self, X, y, sample_weight=None):
    n_jobs_ = self.n_jobs
    accept_sparse = False if self.positive else ['csr', 'csc', 'coo']
    X, y = validate_data(self, X, y, accept_sparse=accept_sparse, y_numeric=True, multi_output=True, force_writeable=True)
    has_sw = sample_weight is not None
    if has_sw:
        sample_weight = _check_sample_weight(sample_weight, X, dtype=X.dtype, ensure_non_negative=True)
    copy_X_in_preprocess_data = self.copy_X and (not sp.issparse(X))
    X, y, X_offset, y_offset, _, sample_weight_sqrt = _preprocess_data(X, y, fit_intercept=self.fit_intercept, copy=copy_X_in_preprocess_data, sample_weight=sample_weight)
    if self.positive:
        if y.ndim < 2:
            self.coef_ = optimize.nnls(X, y)[0]
        else:
            outs = Parallel(n_jobs=n_jobs_)((delayed(optimize.nnls)(X, y[:, j]) for j in range(y.shape[1])))
            self.coef_ = np.vstack([out[0] for out in outs])
    elif sp.issparse(X):
        if has_sw:

            def matvec(b):
                return X.dot(b) - sample_weight_sqrt * b.dot(X_offset)

            def rmatvec(b):
                return X.T.dot(b) - X_offset * b.dot(sample_weight_sqrt)
        else:

            def matvec(b):
                return X.dot(b) - b.dot(X_offset)

            def rmatvec(b):
                return X.T.dot(b) - X_offset * b.sum()
        X_centered = sparse.linalg.LinearOperator(shape=X.shape, matvec=matvec, rmatvec=rmatvec)
        if y.ndim < 2:
            self.coef_ = lsqr(X_centered, y, atol=self.tol, btol=self.tol)[0]
        else:
            outs = Parallel(n_jobs=n_jobs_)((delayed(lsqr)(X_centered, y[:, j].ravel(), atol=self.tol, btol=self.tol) for j in range(y.shape[1])))
            self.coef_ = np.vstack([out[0] for out in outs])
    else:
        self.coef_, _, self.rank_, self.singular_ = linalg.lstsq(X, y, cond=self.tol)
        self.coef_ = self.coef_.T
    if y.ndim == 1:
        self.coef_ = np.ravel(self.coef_)
    self._set_intercept(X_offset, y_offset)
    return self

def predict(self, X, return_std=False):
    y_mean = self._decision_function(X)
    if not return_std:
        return y_mean
    else:
        X = X - self.X_offset_
        sigmas_squared_data = (np.dot(X, self.sigma_) * X).sum(axis=1)
        y_std = np.sqrt(sigmas_squared_data + 1.0 / self.alpha_)
        return (y_mean, y_std)

def _update_coef_(self, X, y, n_samples, n_features, XT_y, U, Vh, eigen_vals_, alpha_, lambda_):
    if n_samples > n_features:
        coef_ = np.linalg.multi_dot([Vh.T, Vh / (eigen_vals_ + lambda_ / alpha_)[:, np.newaxis], XT_y])
    else:
        coef_ = np.linalg.multi_dot([X.T, U / (eigen_vals_ + lambda_ / alpha_)[None, :], U.T, y])
    sse_ = np.sum((y - np.dot(X, coef_)) ** 2)
    return (coef_, sse_)

def predict(self, X, return_std=False):
    y_mean = self._decision_function(X)
    if return_std is False:
        return y_mean
    else:
        col_index = self.lambda_ < self.threshold_lambda
        X = X - self.X_offset_
        X = _safe_indexing(X, indices=col_index, axis=1)
        sigmas_squared_data = (np.dot(X, self.sigma_) * X).sum(axis=1)
        y_std = np.sqrt(sigmas_squared_data + 1.0 / self.alpha_)
        return (y_mean, y_std)

def _set_order(X, y, order='C'):
    if order not in [None, 'C', 'F']:
        raise ValueError("Unknown value for order. Got {} instead of None, 'C' or 'F'.".format(order))
    sparse_X = sparse.issparse(X)
    sparse_y = sparse.issparse(y)
    if order is not None:
        sparse_format = 'csc' if order == 'F' else 'csr'
        if sparse_X:
            X = X.asformat(sparse_format, copy=False)
        else:
            X = np.asarray(X, order=order)
        if sparse_y:
            y = y.asformat(sparse_format)
        else:
            y = np.asarray(y, order=order)
    return (X, y)

def _alpha_grid(X, y, Xy=None, l1_ratio=1.0, fit_intercept=True, eps=0.001, n_alphas=100, sample_weight=None, *, positive: bool=False):
    if l1_ratio == 0:
        raise ValueError('Automatic alpha grid generation is not supported for l1_ratio=0. Please supply a grid by providing your estimator with the appropriate `alphas=` argument.')
    if Xy is not None:
        Xyw = Xy
    else:
        if fit_intercept:
            y = y - np.average(y, axis=0, weights=sample_weight)
            if sparse.issparse(X):
                X_mean, _ = mean_variance_axis(X, axis=0, weights=sample_weight)
            else:
                X_mean = np.average(X, axis=0, weights=sample_weight)
        if sample_weight is None:
            yw = y
        elif y.ndim > 1:
            yw = y * sample_weight.reshape(-1, 1)
        else:
            yw = y * sample_weight
        if fit_intercept:
            if y.ndim > 1:
                Xyw = X.T @ yw - X_mean[:, None] * np.sum(yw, axis=0)
            else:
                Xyw = X.T @ yw - X_mean * np.sum(yw, axis=0)
        else:
            Xyw = X.T @ yw
    if Xyw.ndim == 1:
        Xyw = Xyw[:, np.newaxis]
    if sample_weight is not None:
        n_samples = sample_weight.sum()
    else:
        n_samples = X.shape[0]
    if not positive:
        alpha_max = np.sqrt(np.max(np.sum(Xyw ** 2, axis=1))) / (n_samples * l1_ratio)
    else:
        alpha_max = max(0, np.max(Xyw)) / (n_samples * l1_ratio)
    if alpha_max <= np.finfo(np.float64).resolution:
        return np.full(n_alphas, np.finfo(np.float64).resolution)
    return np.geomspace(alpha_max, alpha_max * eps, num=n_alphas)

@validate_params({'X': ['array-like', 'sparse matrix'], 'y': ['array-like', 'sparse matrix'], 'eps': [Interval(Real, 0, None, closed='neither')], 'n_alphas': [Interval(Integral, 1, None, closed='left'), Hidden(StrOptions({'deprecated'}))], 'alphas': [Interval(Integral, 1, None, closed='left'), 'array-like', None, Hidden(StrOptions({'warn'}))], 'precompute': [StrOptions({'auto'}), 'boolean', 'array-like'], 'Xy': ['array-like', None], 'copy_X': ['boolean'], 'coef_init': ['array-like', None], 'verbose': ['verbose'], 'return_n_iter': ['boolean'], 'positive': ['boolean']}, prefer_skip_nested_validation=True)
def lasso_path(X, y, *, eps=0.001, n_alphas='deprecated', alphas='warn', precompute='auto', Xy=None, copy_X=True, coef_init=None, verbose=False, return_n_iter=False, positive=False, **params):
    if n_alphas == 'deprecated':
        _alphas = 100
    else:
        warnings.warn("'n_alphas' was deprecated in 1.9 and will be removed in 1.11. 'alphas' now accepts an integer value which removes the need to pass 'n_alphas'. The default value of 'alphas' will change from None to 100 in 1.11. Pass an explicit value to 'alphas' and leave 'n_alphas' to its default value to silence this warning.", FutureWarning)
        _alphas = n_alphas
    if isinstance(alphas, str) and alphas == 'warn':
        pass
    elif alphas is None:
        warnings.warn("'alphas=None' is deprecated and will be removed in 1.11, at which point the default value will be set to 100. Set 'alphas=100' to silence this warning.", FutureWarning)
    else:
        _alphas = alphas
    return enet_path(X, y, l1_ratio=1.0, eps=eps, alphas=_alphas, precompute=precompute, Xy=Xy, copy_X=copy_X, coef_init=coef_init, verbose=verbose, positive=positive, return_n_iter=return_n_iter, **params)

@validate_params({'X': ['array-like', 'sparse matrix'], 'y': ['array-like', 'sparse matrix'], 'l1_ratio': [Interval(Real, 0.0, 1.0, closed='both')], 'eps': [Interval(Real, 0.0, None, closed='neither')], 'n_alphas': [Interval(Integral, 1, None, closed='left'), Hidden(StrOptions({'deprecated'}))], 'alphas': [Interval(Integral, 1, None, closed='left'), 'array-like', None, Hidden(StrOptions({'warn'}))], 'precompute': [StrOptions({'auto'}), 'boolean', 'array-like'], 'Xy': ['array-like', None], 'copy_X': ['boolean'], 'coef_init': ['array-like', None], 'verbose': ['verbose'], 'return_n_iter': ['boolean'], 'positive': ['boolean'], 'check_input': ['boolean']}, prefer_skip_nested_validation=True)
def enet_path(X, y, *, l1_ratio=0.5, eps=0.001, n_alphas='deprecated', alphas='warn', precompute='auto', Xy=None, copy_X=True, coef_init=None, verbose=False, return_n_iter=False, positive=False, check_input=True, **params):
    if n_alphas == 'deprecated':
        _alphas = 100
    else:
        warnings.warn("'n_alphas' was deprecated in 1.9 and will be removed in 1.11. 'alphas' now accepts an integer value which removes the need to pass 'n_alphas'. The default value of 'alphas' will change from None to 100 in 1.11. Pass an explicit value to 'alphas' and leave 'n_alphas' to its default value to silence this warning.", FutureWarning)
        _alphas = n_alphas
    if isinstance(alphas, str) and alphas == 'warn':
        pass
    elif alphas is None:
        warnings.warn("'alphas=None' is deprecated and will be removed in 1.11, at which point the default value will be set to 100. Set 'alphas=100' to silence this warning.", FutureWarning)
    else:
        _alphas = alphas
    X_offset_param = params.pop('X_offset', None)
    X_scale_param = params.pop('X_scale', None)
    sample_weight = params.pop('sample_weight', None)
    tol = params.pop('tol', 0.0001)
    max_iter = params.pop('max_iter', 1000)
    random_state = params.pop('random_state', None)
    selection = params.pop('selection', 'cyclic')
    do_screening = params.pop('do_screening', True)
    early_stopping = params.pop('early_stopping', True)
    if len(params) > 0:
        raise ValueError('Unexpected parameters in params', params.keys())
    if check_input:
        X = check_array(X, accept_sparse='csc', dtype=[np.float64, np.float32], order='F', copy=copy_X)
        y = check_array(y, accept_sparse='csc', dtype=X.dtype.type, order='F', copy=False, ensure_2d=False)
        if Xy is not None:
            Xy = check_array(Xy, dtype=X.dtype.type, order='C', copy=False, ensure_2d=False)
    n_samples, n_features = X.shape
    multi_output = False
    if y.ndim != 1:
        multi_output = True
        n_targets = y.shape[1]
    if multi_output and positive:
        raise ValueError('positive=True is not allowed for multi-output (y.ndim != 1)')
    X_is_sparse = sparse.issparse(X)
    if X_is_sparse:
        if X_offset_param is not None:
            X_sparse_scaling = X_offset_param / X_scale_param
            X_sparse_scaling = np.asarray(X_sparse_scaling, dtype=X.dtype)
        else:
            X_sparse_scaling = np.zeros(n_features, dtype=X.dtype)
    else:
        X_sparse_scaling = None
    if check_input or precompute is not False:
        X, y, _, _, _, precompute, Xy = _pre_fit(X, y, Xy, precompute, fit_intercept=False, copy=False, check_gram=check_input)
    if isinstance(_alphas, Integral):
        alphas = _alpha_grid(X, y, Xy=Xy, l1_ratio=l1_ratio, fit_intercept=False, positive=positive, eps=eps, n_alphas=_alphas)
    elif len(_alphas) > 1:
        alphas = np.sort(_alphas)[::-1]
    n_alphas = len(alphas)
    dual_gaps = np.empty(n_alphas)
    n_iters = []
    rng = check_random_state(random_state)
    if selection not in ['random', 'cyclic']:
        raise ValueError('selection should be either random or cyclic.')
    random = selection == 'random'
    if not multi_output:
        coefs = np.empty((n_features, n_alphas), dtype=X.dtype)
    else:
        coefs = np.empty((n_targets, n_features, n_alphas), dtype=X.dtype)
    if coef_init is None:
        coef_ = np.zeros(coefs.shape[:-1], dtype=X.dtype, order='F')
    else:
        coef_ = np.asfortranarray(coef_init, dtype=X.dtype)
    if X_is_sparse:
        X_data = X.data
        X_indices = X.indices
        X_indptr = X.indptr
    else:
        X_data = None
        X_indices = None
        X_indptr = None
    for i, alpha in enumerate(alphas):
        l1_reg = alpha * l1_ratio * n_samples
        l2_reg = alpha * (1.0 - l1_ratio) * n_samples
        if not multi_output and X_is_sparse:
            model = cd_fast.sparse_enet_coordinate_descent(w=coef_, alpha=l1_reg, beta=l2_reg, X_data=X_data, X_indices=X_indices, X_indptr=X_indptr, y=y, sample_weight=sample_weight, X_mean=X_sparse_scaling, max_iter=max_iter, tol=tol, rng=rng, random=random, positive=positive, do_screening=do_screening, early_stopping=early_stopping)
        elif multi_output:
            model = cd_fast.enet_coordinate_descent_multi_task(W=coef_, alpha=l1_reg, beta=l2_reg, X=None if X_is_sparse else X, X_is_sparse=X_is_sparse, X_data=X_data, X_indices=X_indices, X_indptr=X_indptr, Y=y, sample_weight=sample_weight, X_mean=X_sparse_scaling, max_iter=max_iter, tol=tol, rng=rng, random=random, do_screening=do_screening, early_stopping=early_stopping)
        elif isinstance(precompute, np.ndarray):
            if check_input:
                precompute = check_array(precompute, dtype=X.dtype.type, order='C')
            model = cd_fast.enet_coordinate_descent_gram(coef_, l1_reg, l2_reg, precompute, Xy, y, max_iter, tol, rng, random, positive, do_screening, early_stopping)
        elif precompute is False:
            model = cd_fast.enet_coordinate_descent(coef_, l1_reg, l2_reg, X, y, max_iter, tol, rng, random, positive, do_screening, early_stopping)
        else:
            raise ValueError("Precompute should be one of True, False, 'auto' or array-like. Got %r" % precompute)
        coef_, dual_gap_, eps_, n_iter_ = model
        coefs[..., i] = coef_
        dual_gaps[i] = dual_gap_ / n_samples
        n_iters.append(n_iter_)
        if verbose:
            if verbose > 2:
                print(model)
            elif verbose > 1:
                print('Path: %03i out of %03i' % (i, n_alphas))
            else:
                sys.stderr.write('.')
    if return_n_iter:
        return (alphas, coefs, dual_gaps, n_iters)
    return (alphas, coefs, dual_gaps)

@_fit_context(prefer_skip_nested_validation=True)
def fit(self, X, y, sample_weight=None, check_input=True):
    if self.alpha == 0:
        warnings.warn('With alpha=0, this algorithm does not converge well. You are advised to use the LinearRegression estimator', stacklevel=2)
    X_copied = False
    if check_input:
        X_copied = self.copy_X and self.fit_intercept
        X, y = validate_data(self, X, y, accept_sparse='csc', order='F', dtype=[np.float64, np.float32], force_writeable=True, accept_large_sparse=False, copy=X_copied, multi_output=True, y_numeric=True)
        y = check_array(y, order='F', copy=False, dtype=X.dtype.type, ensure_2d=False)
    n_samples, n_features = X.shape
    if isinstance(sample_weight, numbers.Number):
        sample_weight = None
    if sample_weight is not None:
        if check_input:
            sample_weight = _check_sample_weight(sample_weight, X, dtype=X.dtype)
        sample_weight = sample_weight * (n_samples / np.sum(sample_weight))
    should_copy = self.copy_X and (not X_copied)
    X, y, X_offset, y_offset, X_scale, precompute, Xy = _pre_fit(X, y, None, self.precompute, fit_intercept=self.fit_intercept, copy=should_copy, check_gram=check_input, sample_weight=sample_weight)
    if check_input or sample_weight is not None:
        X, y = _set_order(X, y, order='F')
    if y.ndim == 1:
        y = y[:, np.newaxis]
    if Xy is not None and Xy.ndim == 1:
        Xy = Xy[:, np.newaxis]
    n_targets = y.shape[1]
    if not self.warm_start or not hasattr(self, 'coef_'):
        coef_ = np.zeros((n_targets, n_features), dtype=X.dtype, order='F')
    else:
        coef_ = self.coef_
        if coef_.ndim == 1:
            coef_ = coef_[np.newaxis, :]
    dual_gaps_ = np.zeros(n_targets, dtype=X.dtype)
    self.n_iter_ = []
    for k in range(n_targets):
        if Xy is not None:
            this_Xy = Xy[:, k]
        else:
            this_Xy = None
        _, this_coef, this_dual_gap, this_iter = self.path(X, y[:, k], l1_ratio=self.l1_ratio, eps=None, alphas=[self.alpha], precompute=precompute, Xy=this_Xy, copy_X=True, coef_init=coef_[k], verbose=False, return_n_iter=True, positive=self.positive, check_input=False, tol=self.tol, X_offset=X_offset, X_scale=X_scale, max_iter=self.max_iter, random_state=self.random_state, selection=self.selection, sample_weight=sample_weight)
        coef_[k] = this_coef[:, 0]
        dual_gaps_[k] = this_dual_gap[0]
        self.n_iter_.append(this_iter[0])
    if n_targets == 1:
        self.n_iter_ = self.n_iter_[0]
        self.coef_ = coef_[0]
        self.dual_gap_ = dual_gaps_[0]
    else:
        self.coef_ = coef_
        self.dual_gap_ = dual_gaps_
    self._set_intercept(X_offset, y_offset, X_scale)
    if not all((np.isfinite(w).all() for w in [self.coef_, self.intercept_])):
        raise ValueError('Coordinate descent iterations resulted in non-finite parameter values. The input data may contain large values and need to be preprocessed.')
    return self

@property
def sparse_coef_(self):
    return _align_api_if_sparse(sparse.csr_array(np.atleast_2d(self.coef_)))

def _decision_function(self, X):
    check_is_fitted(self)
    if sparse.issparse(X):
        return safe_sparse_dot(X, self.coef_.T, dense_output=True) + self.intercept_
    else:
        return super()._decision_function(X)

@abstractmethod
def _get_estimator(self):
    pass

@abstractmethod
def _is_multitask(self):
    pass

@staticmethod
@abstractmethod
def path(X, y, **kwargs):
    pass

@_fit_context(prefer_skip_nested_validation=True)
def fit(self, X, y, sample_weight=None, **params):
    _raise_for_params(params, self, 'fit')
    copy_X = self.copy_X and self.fit_intercept
    check_y_params = dict(copy=False, dtype=[np.float64, np.float32], ensure_2d=False)
    if isinstance(X, np.ndarray) or sparse.issparse(X):
        reference_to_old_X = X
        check_X_params = dict(accept_sparse='csc', dtype=[np.float64, np.float32], force_writeable=True, copy=False, accept_large_sparse=False)
        X, y = validate_data(self, X, y, validate_separately=(check_X_params, check_y_params))
        if sparse.issparse(X):
            if hasattr(reference_to_old_X, 'data') and (not np.may_share_memory(reference_to_old_X.data, X.data)):
                copy_X = False
        elif not np.may_share_memory(reference_to_old_X, X):
            copy_X = False
        del reference_to_old_X
    else:
        check_X_params = dict(accept_sparse='csc', dtype=[np.float64, np.float32], order='F', force_writeable=True, copy=copy_X)
        X, y = validate_data(self, X, y, validate_separately=(check_X_params, check_y_params))
        copy_X = False
    check_consistent_length(X, y)
    if not self._is_multitask():
        if y.ndim > 1 and y.shape[1] > 1:
            raise ValueError('For multi-task outputs, use MultiTask%s' % self.__class__.__name__)
        y = column_or_1d(y, warn=True)
    elif y.ndim == 1:
        raise ValueError('For mono-task outputs, use %sCV' % self.__class__.__name__[9:])
    if isinstance(sample_weight, numbers.Number):
        sample_weight = None
    if sample_weight is not None:
        sample_weight = _check_sample_weight(sample_weight, X, dtype=X.dtype)
    model = self._get_estimator()
    path_params = self.get_params()
    path_params.pop('fit_intercept', None)
    if 'l1_ratio' in path_params:
        l1_ratios = np.atleast_1d(path_params['l1_ratio'])
        path_params['l1_ratio'] = l1_ratios[0]
    else:
        l1_ratios = [1]
    path_params.pop('cv', None)
    path_params.pop('n_jobs', None)
    n_l1_ratio = len(l1_ratios)
    check_scalar_alpha = partial(check_scalar, target_type=Real, min_val=0.0, include_boundaries='left')
    if isinstance(self.alphas, Integral):
        alphas = [_alpha_grid(X, y, l1_ratio=l1_ratio, fit_intercept=self.fit_intercept, positive=getattr(self, 'positive', False), eps=self.eps, n_alphas=self.alphas, sample_weight=sample_weight) for l1_ratio in l1_ratios]
    else:
        for index, alpha in enumerate(self.alphas):
            check_scalar_alpha(alpha, f'alphas[{index}]')
        alphas = np.tile(np.sort(self.alphas)[::-1], (n_l1_ratio, 1))
    path_params['copy_X'] = copy_X
    if effective_n_jobs(self.n_jobs) > 1:
        path_params['copy_X'] = False
    cv = check_cv(self.cv)
    if _routing_enabled():
        routed_params = process_routing(self, 'fit', sample_weight=sample_weight, **params)
    else:
        routed_params = _manual_routing({'splitter': {}})
    folds = list(cv.split(X, y, **routed_params.splitter.split))
    best_mse = np.inf
    jobs = (delayed(_path_residuals)(X, y, sample_weight, train, test, self.fit_intercept, self.path, path_params, alphas=this_alphas, l1_ratio=this_l1_ratio, X_order='F', dtype=X.dtype.type) for this_l1_ratio, this_alphas in zip(l1_ratios, alphas) for train, test in folds)
    mse_paths = Parallel(n_jobs=self.n_jobs, verbose=self.verbose, prefer='threads')(jobs)
    mse_paths = np.reshape(mse_paths, (n_l1_ratio, len(folds), -1))
    mean_mse = np.mean(mse_paths, axis=1)
    self.mse_path_ = np.squeeze(np.moveaxis(mse_paths, 2, 1))
    for l1_ratio, l1_alphas, mse_alphas in zip(l1_ratios, alphas, mean_mse):
        i_best_alpha = np.argmin(mse_alphas)
        this_best_mse = mse_alphas[i_best_alpha]
        if this_best_mse < best_mse:
            best_alpha = l1_alphas[i_best_alpha]
            best_l1_ratio = l1_ratio
            best_mse = this_best_mse
    self.l1_ratio_ = best_l1_ratio
    self.alpha_ = best_alpha
    if isinstance(self.alphas, Integral):
        self.alphas_ = np.asarray(alphas)
        if n_l1_ratio == 1:
            self.alphas_ = self.alphas_[0]
    else:
        self.alphas_ = np.asarray(alphas[0])
    common_params = {name: value for name, value in self.get_params().items() if name in model.get_params()}
    model.set_params(**common_params)
    model.alpha = best_alpha
    model.l1_ratio = best_l1_ratio
    model.copy_X = copy_X
    precompute = getattr(self, 'precompute', None)
    if isinstance(precompute, str) and precompute == 'auto':
        model.precompute = False
    if sample_weight is None:
        model.fit(X, y)
    else:
        model.fit(X, y, sample_weight=sample_weight)
    if not hasattr(self, 'l1_ratio'):
        del self.l1_ratio_
    self.coef_ = model.coef_
    self.intercept_ = model.intercept_
    self.dual_gap_ = model.dual_gap_
    self.n_iter_ = model.n_iter_
    return self

def get_metadata_routing(self):
    router = MetadataRouter(owner=self).add_self_request(self).add(splitter=check_cv(self.cv), method_mapping=MethodMapping().add(caller='fit', callee='split'))
    return router

@_fit_context(prefer_skip_nested_validation=True)
def fit(self, X, y, sample_weight=None):
    X, y = validate_data(self, X, y, copy=False, accept_sparse=['csr'], y_numeric=True, dtype=[np.float64, np.float32])
    sample_weight = _check_sample_weight(sample_weight, X)
    if self.warm_start and hasattr(self, 'coef_'):
        parameters = np.concatenate((self.coef_, [self.intercept_, self.scale_]))
    else:
        if self.fit_intercept:
            parameters = np.zeros(X.shape[1] + 2)
        else:
            parameters = np.zeros(X.shape[1] + 1)
        parameters[-1] = 1
    bounds = np.tile([-np.inf, np.inf], (parameters.shape[0], 1))
    bounds[-1][0] = np.finfo(np.float64).eps * 10
    opt_res = optimize.minimize(_huber_loss_and_gradient, parameters, method='L-BFGS-B', jac=True, args=(X, y, self.epsilon, self.alpha, sample_weight), options={'maxiter': self.max_iter, 'gtol': self.tol, **_get_additional_lbfgs_options_dict('iprint', -1)}, bounds=bounds)
    parameters = opt_res.x
    if opt_res.status == 2:
        raise ValueError('HuberRegressor convergence failed: l-BFGS-b solver terminated with %s' % opt_res.message)
    self.n_iter_ = _check_optimize_result('lbfgs', opt_res, self.max_iter)
    self.scale_ = parameters[-1]
    if self.fit_intercept:
        self.intercept_ = parameters[-2]
    else:
        self.intercept_ = 0.0
    self.coef_ = parameters[:X.shape[1]]
    residual = np.abs(y - safe_sparse_dot(X, self.coef_) - self.intercept_)
    self.outliers_ = residual > self.scale_ * self.epsilon
    return self

@validate_params({'X': [np.ndarray, None], 'y': [np.ndarray, None], 'Xy': [np.ndarray, None], 'Gram': [StrOptions({'auto'}), 'boolean', np.ndarray, None], 'max_iter': [Interval(Integral, 0, None, closed='left')], 'alpha_min': [Interval(Real, 0, None, closed='left')], 'method': [StrOptions({'lar', 'lasso'})], 'copy_X': ['boolean'], 'eps': [Interval(Real, 0, None, closed='neither'), None], 'copy_Gram': ['boolean'], 'verbose': ['verbose'], 'return_path': ['boolean'], 'return_n_iter': ['boolean'], 'positive': ['boolean']}, prefer_skip_nested_validation=True)
def lars_path(X, y, Xy=None, *, Gram=None, max_iter=500, alpha_min=0, method='lar', copy_X=True, eps=np.finfo(float).eps, copy_Gram=True, verbose=0, return_path=True, return_n_iter=False, positive=False):
    if X is None and Gram is not None:
        raise ValueError('X cannot be None if Gram is not NoneUse lars_path_gram to avoid passing X and y.')
    return _lars_path_solver(X=X, y=y, Xy=Xy, Gram=Gram, n_samples=None, max_iter=max_iter, alpha_min=alpha_min, method=method, copy_X=copy_X, eps=eps, copy_Gram=copy_Gram, verbose=verbose, return_path=return_path, return_n_iter=return_n_iter, positive=positive)

@validate_params({'Xy': [np.ndarray], 'Gram': [np.ndarray], 'n_samples': [Interval(Integral, 0, None, closed='left')], 'max_iter': [Interval(Integral, 0, None, closed='left')], 'alpha_min': [Interval(Real, 0, None, closed='left')], 'method': [StrOptions({'lar', 'lasso'})], 'copy_X': ['boolean'], 'eps': [Interval(Real, 0, None, closed='neither'), None], 'copy_Gram': ['boolean'], 'verbose': ['verbose'], 'return_path': ['boolean'], 'return_n_iter': ['boolean'], 'positive': ['boolean']}, prefer_skip_nested_validation=True)
def lars_path_gram(Xy, Gram, *, n_samples, max_iter=500, alpha_min=0, method='lar', copy_X=True, eps=np.finfo(float).eps, copy_Gram=True, verbose=0, return_path=True, return_n_iter=False, positive=False):
    return _lars_path_solver(X=None, y=None, Xy=Xy, Gram=Gram, n_samples=n_samples, max_iter=max_iter, alpha_min=alpha_min, method=method, copy_X=copy_X, eps=eps, copy_Gram=copy_Gram, verbose=verbose, return_path=return_path, return_n_iter=return_n_iter, positive=positive)

def _lars_path_solver(X, y, Xy=None, Gram=None, n_samples=None, max_iter=500, alpha_min=0, method='lar', copy_X=True, eps=np.finfo(float).eps, copy_Gram=True, verbose=0, return_path=True, return_n_iter=False, positive=False):
    if method == 'lar' and positive:
        raise ValueError("Positive constraint not supported for 'lar' coding method.")
    n_samples = n_samples if n_samples is not None else y.size
    if Xy is None:
        Cov = np.dot(X.T, y)
    else:
        Cov = Xy.copy()
    if Gram is None or Gram is False:
        Gram = None
        if X is None:
            raise ValueError('X and Gram cannot both be unspecified.')
    elif isinstance(Gram, str) and Gram == 'auto' or Gram is True:
        if Gram is True or X.shape[0] > X.shape[1]:
            Gram = np.dot(X.T, X)
        else:
            Gram = None
    elif copy_Gram:
        Gram = Gram.copy()
    if Gram is None:
        n_features = X.shape[1]
    else:
        n_features = Cov.shape[0]
        if Gram.shape != (n_features, n_features):
            raise ValueError('The shapes of the inputs Gram and Xy do not match.')
    if copy_X and X is not None and (Gram is None):
        X = X.copy('F')
    max_features = min(max_iter, n_features)
    dtypes = set((a.dtype for a in (X, y, Xy, Gram) if a is not None))
    if len(dtypes) == 1:
        return_dtype = next(iter(dtypes))
    else:
        return_dtype = np.float64
    if return_path:
        coefs = np.zeros((max_features + 1, n_features), dtype=return_dtype)
        alphas = np.zeros(max_features + 1, dtype=return_dtype)
    else:
        coef, prev_coef = (np.zeros(n_features, dtype=return_dtype), np.zeros(n_features, dtype=return_dtype))
        alpha, prev_alpha = (np.array([0.0], dtype=return_dtype), np.array([0.0], dtype=return_dtype))
    n_iter, n_active = (0, 0)
    active, indices = (list(), np.arange(n_features))
    sign_active = np.empty(max_features, dtype=np.int8)
    drop = False
    if Gram is None:
        L = np.empty((max_features, max_features), dtype=X.dtype)
        swap, nrm2 = linalg.get_blas_funcs(('swap', 'nrm2'), (X,))
    else:
        L = np.empty((max_features, max_features), dtype=Gram.dtype)
        swap, nrm2 = linalg.get_blas_funcs(('swap', 'nrm2'), (Cov,))
    solve_cholesky, = get_lapack_funcs(('potrs',), (L,))
    if verbose:
        if verbose > 1:
            print('Step\t\tAdded\t\tDropped\t\tActive set size\t\tC')
        else:
            sys.stdout.write('.')
            sys.stdout.flush()
    tiny32 = np.finfo(np.float32).tiny
    cov_precision = np.finfo(Cov.dtype).precision
    equality_tolerance = np.finfo(np.float32).eps
    if Gram is not None:
        Gram_copy = Gram.copy()
        Cov_copy = Cov.copy()
    while True:
        if Cov.size:
            if positive:
                C_idx = np.argmax(Cov)
            else:
                C_idx = np.argmax(np.abs(Cov))
            C_ = Cov[C_idx]
            if positive:
                C = C_
            else:
                C = np.fabs(C_)
        else:
            C = 0.0
        if return_path:
            alpha = alphas[n_iter, np.newaxis]
            coef = coefs[n_iter]
            prev_alpha = alphas[n_iter - 1, np.newaxis]
            prev_coef = coefs[n_iter - 1]
        alpha[0] = C / n_samples
        if alpha[0] <= alpha_min + equality_tolerance:
            if abs(alpha[0] - alpha_min) > equality_tolerance:
                if n_iter > 0:
                    ss = (prev_alpha[0] - alpha_min) / (prev_alpha[0] - alpha[0])
                    coef[:] = prev_coef + ss * (coef - prev_coef)
                alpha[0] = alpha_min
            if return_path:
                coefs[n_iter] = coef
            break
        if n_iter >= max_iter or n_active >= n_features:
            break
        if not drop:
            if positive:
                sign_active[n_active] = np.ones_like(C_)
            else:
                sign_active[n_active] = np.sign(C_)
            m, n = (n_active, C_idx + n_active)
            Cov[C_idx], Cov[0] = swap(Cov[C_idx], Cov[0])
            indices[n], indices[m] = (indices[m], indices[n])
            Cov_not_shortened = Cov
            Cov = Cov[1:]
            if Gram is None:
                X.T[n], X.T[m] = swap(X.T[n], X.T[m])
                c = nrm2(X.T[n_active]) ** 2
                L[n_active, :n_active] = np.dot(X.T[n_active], X.T[:n_active].T)
            else:
                Gram[m], Gram[n] = swap(Gram[m], Gram[n])
                Gram[:, m], Gram[:, n] = swap(Gram[:, m], Gram[:, n])
                c = Gram[n_active, n_active]
                L[n_active, :n_active] = Gram[n_active, :n_active]
            if n_active:
                linalg.solve_triangular(L[:n_active, :n_active], L[n_active, :n_active], trans=0, lower=1, overwrite_b=True, **SOLVE_TRIANGULAR_ARGS)
            v = np.dot(L[n_active, :n_active], L[n_active, :n_active])
            diag = max(np.sqrt(np.abs(c - v)), eps)
            L[n_active, n_active] = diag
            if diag < 1e-07:
                warnings.warn('Regressors in active set degenerate. Dropping a regressor, after %i iterations, i.e. alpha=%.3e, with an active set of %i regressors, and the smallest cholesky pivot element being %.3e. Reduce max_iter or increase eps parameters.' % (n_iter, alpha.item(), n_active, diag), ConvergenceWarning)
                Cov = Cov_not_shortened
                Cov[0] = 0
                Cov[C_idx], Cov[0] = swap(Cov[C_idx], Cov[0])
                continue
            active.append(indices[n_active])
            n_active += 1
            if verbose > 1:
                print('%s\t\t%s\t\t%s\t\t%s\t\t%s' % (n_iter, active[-1], '', n_active, C))
        if method == 'lasso' and n_iter > 0 and (prev_alpha[0] < alpha[0]):
            warnings.warn('Early stopping the lars path, as the residues are small and the current value of alpha is no longer well controlled. %i iterations, alpha=%.3e, previous alpha=%.3e, with an active set of %i regressors.' % (n_iter, alpha.item(), prev_alpha.item(), n_active), ConvergenceWarning)
            break
        least_squares, _ = solve_cholesky(L[:n_active, :n_active], sign_active[:n_active], lower=True)
        if least_squares.size == 1 and least_squares == 0:
            least_squares[...] = 1
            AA = 1.0
        else:
            AA = 1.0 / np.sqrt(np.sum(least_squares * sign_active[:n_active]))
            if not np.isfinite(AA):
                i = 0
                L_ = L[:n_active, :n_active].copy()
                while not np.isfinite(AA):
                    L_.flat[::n_active + 1] += 2 ** i * eps
                    least_squares, _ = solve_cholesky(L_, sign_active[:n_active], lower=True)
                    tmp = max(np.sum(least_squares * sign_active[:n_active]), eps)
                    AA = 1.0 / np.sqrt(tmp)
                    i += 1
            least_squares *= AA
        if Gram is None:
            eq_dir = np.dot(X.T[:n_active].T, least_squares)
            corr_eq_dir = np.dot(X.T[n_active:], eq_dir)
        else:
            corr_eq_dir = np.dot(Gram[:n_active, n_active:].T, least_squares)
        np.around(corr_eq_dir, decimals=cov_precision, out=corr_eq_dir)
        g1 = arrayfuncs.min_pos((C - Cov) / (AA - corr_eq_dir + tiny32))
        if positive:
            gamma_ = min(g1, C / AA)
        else:
            g2 = arrayfuncs.min_pos((C + Cov) / (AA + corr_eq_dir + tiny32))
            gamma_ = min(g1, g2, C / AA)
        drop = False
        z = -coef[active] / (least_squares + tiny32)
        z_pos = arrayfuncs.min_pos(z)
        if z_pos < gamma_:
            idx = np.where(z == z_pos)[0][::-1]
            sign_active[idx] = -sign_active[idx]
            if method == 'lasso':
                gamma_ = z_pos
            drop = True
        n_iter += 1
        if return_path:
            if n_iter >= coefs.shape[0]:
                del coef, alpha, prev_alpha, prev_coef
                add_features = 2 * max(1, max_features - n_active)
                coefs = np.resize(coefs, (n_iter + add_features, n_features))
                coefs[-add_features:] = 0
                alphas = np.resize(alphas, n_iter + add_features)
                alphas[-add_features:] = 0
            coef = coefs[n_iter]
            prev_coef = coefs[n_iter - 1]
        else:
            prev_coef = coef
            prev_alpha[0] = alpha[0]
            coef = np.zeros_like(coef)
        coef[active] = prev_coef[active] + gamma_ * least_squares
        Cov -= gamma_ * corr_eq_dir
        if drop and method == 'lasso':
            for ii in idx:
                arrayfuncs.cholesky_delete(L[:n_active, :n_active], ii)
            n_active -= 1
            drop_idx = [active.pop(ii) for ii in idx]
            if Gram is None:
                for ii in idx:
                    for i in range(ii, n_active):
                        X.T[i], X.T[i + 1] = swap(X.T[i], X.T[i + 1])
                        indices[i], indices[i + 1] = (indices[i + 1], indices[i])
                residual = y - np.dot(X[:, :n_active], coef[active])
                temp = np.dot(X.T[n_active], residual)
                Cov = np.r_[temp, Cov]
            else:
                for ii in idx:
                    for i in range(ii, n_active):
                        indices[i], indices[i + 1] = (indices[i + 1], indices[i])
                        Gram[i], Gram[i + 1] = swap(Gram[i], Gram[i + 1])
                        Gram[:, i], Gram[:, i + 1] = swap(Gram[:, i], Gram[:, i + 1])
                temp = Cov_copy[drop_idx] - np.dot(Gram_copy[drop_idx], coef)
                Cov = np.r_[temp, Cov]
            sign_active = np.delete(sign_active, idx)
            sign_active = np.append(sign_active, 0.0)
            if verbose > 1:
                print('%s\t\t%s\t\t%s\t\t%s\t\t%s' % (n_iter, '', drop_idx, n_active, abs(temp)))
    if return_path:
        alphas = alphas[:n_iter + 1]
        coefs = coefs[:n_iter + 1]
        if return_n_iter:
            return (alphas, active, coefs.T, n_iter)
        else:
            return (alphas, active, coefs.T)
    elif return_n_iter:
        return (alpha, active, coef, n_iter)
    else:
        return (alpha, active, coef)

@_fit_context(prefer_skip_nested_validation=True)
def fit(self, X, y, Xy=None):
    X, y = validate_data(self, X, y, force_writeable=True, y_numeric=True, multi_output=True)
    alpha = getattr(self, 'alpha', 0.0)
    if hasattr(self, 'n_nonzero_coefs'):
        alpha = 0.0
        max_iter = self.n_nonzero_coefs
    else:
        max_iter = self.max_iter
    if self.jitter is not None:
        rng = check_random_state(self.random_state)
        noise = rng.uniform(high=self.jitter, size=len(y))
        y = y + noise
    self._fit(X, y, max_iter=max_iter, alpha=alpha, fit_path=self.fit_path, Xy=Xy)
    return self

def get_metadata_routing(self):
    router = MetadataRouter(owner=self).add(splitter=check_cv(self.cv), method_mapping=MethodMapping().add(caller='fit', callee='split'))
    return router

def _estimate_noise_variance(self, X, y, positive):
    if X.shape[0] <= X.shape[1] + self.fit_intercept:
        raise ValueError(f'You are using {self.__class__.__name__} in the case where the number of samples is smaller than the number of features. In this setting, getting a good estimate for the variance of the noise is not possible. Provide an estimate of the noise variance in the constructor.')
    ols_model = LinearRegression(positive=positive, fit_intercept=False)
    y_pred = ols_model.fit(X, y).predict(X)
    return np.sum((y - y_pred) ** 2) / (X.shape[0] - X.shape[1] - self.fit_intercept)

def sandwich_dot(X, W):
    n_samples = X.shape[0]
    if sparse.issparse(X):
        return _align_api_if_sparse(safe_sparse_dot(X.T, sparse.dia_array((W, 0), shape=(n_samples, n_samples)) @ X, dense_output=True))
    else:
        WX = W[:, None] * X
        return X.T @ WX

def init_zero_coef(self, X, dtype=None):
    n_features = X.shape[1]
    n_classes = self.base_loss.n_classes
    if self.fit_intercept:
        n_dof = n_features + 1
    else:
        n_dof = n_features
    if self.base_loss.is_multiclass:
        coef = np.zeros(shape=(n_classes, n_dof), dtype=dtype, order='F')
    else:
        coef = np.zeros(shape=n_dof, dtype=dtype)
    return coef

def weight_intercept(self, coef):
    if not self.base_loss.is_multiclass:
        if self.fit_intercept:
            intercept = coef[-1]
            weights = coef[:-1]
        else:
            intercept = 0.0
            weights = coef
    else:
        if coef.ndim == 1:
            xp, _ = get_namespace(coef)
            if _is_numpy_namespace(xp):
                weights = coef.reshape((self.base_loss.n_classes, -1), order='F')
            else:
                weights = xp.reshape(coef, (-1, self.base_loss.n_classes)).T
        else:
            weights = coef
        if self.fit_intercept:
            intercept = weights[:, -1]
            weights = weights[:, :-1]
        else:
            intercept = 0.0
    return (weights, intercept)

def weight_intercept_raw(self, coef, X):
    weights, intercept = self.weight_intercept(coef)
    xp, _, device_ = get_namespace_and_device(X)
    weights_xp = xp.asarray(weights, dtype=X.dtype, device=device_)
    intercept_xp = xp.asarray(intercept, dtype=X.dtype, device=device_)
    if not self.base_loss.is_multiclass:
        raw_prediction = X @ weights_xp + intercept_xp
    else:
        raw_prediction = X @ weights_xp.T + intercept_xp
    return (weights, intercept, raw_prediction)

def l2_penalty(self, weights, l2_reg_strength):
    norm2_w = weights @ weights if weights.ndim == 1 else squared_norm(weights)
    return float(0.5 * l2_reg_strength * norm2_w)

def loss(self, coef, X, y, sample_weight=None, l2_reg_strength=0.0, n_threads=1, raw_prediction=None):
    n_samples = X.shape[0]
    if raw_prediction is None:
        weights, intercept, raw_prediction = self.weight_intercept_raw(coef, X)
    else:
        weights, intercept = self.weight_intercept(coef)
    loss = self.base_loss.loss(y_true=y, raw_prediction=raw_prediction, sample_weight=sample_weight, n_threads=n_threads)
    xp, _ = get_namespace(X, y, sample_weight)
    sw_sum = n_samples if sample_weight is None else xp.sum(sample_weight)
    loss = float(xp.sum(loss) / sw_sum)
    if l2_reg_strength > 0:
        loss += self.l2_penalty(weights, l2_reg_strength)
    return loss

def loss_gradient(self, coef, X, y, sample_weight=None, l2_reg_strength=0.0, n_threads=1, raw_prediction=None):
    (n_samples, n_features), n_classes = (X.shape, self.base_loss.n_classes)
    n_dof = n_features + int(self.fit_intercept)
    if raw_prediction is None:
        weights, intercept, raw_prediction = self.weight_intercept_raw(coef, X)
    else:
        weights, intercept = self.weight_intercept(coef)
    loss, grad_pointwise = self.base_loss.loss_gradient(y_true=y, raw_prediction=raw_prediction, sample_weight=sample_weight, n_threads=n_threads)
    xp, _ = get_namespace(X, y, sample_weight)
    sw_sum = n_samples if sample_weight is None else xp.sum(sample_weight)
    loss = float(xp.sum(loss) / sw_sum)
    loss += self.l2_penalty(weights, l2_reg_strength)
    grad_pointwise /= sw_sum
    if not self.base_loss.is_multiclass:
        grad = np.empty_like(coef, dtype=weights.dtype)
        X_grad = X.T @ grad_pointwise
        grad[:n_features] = move_to(X_grad, xp=np, device='cpu') + l2_reg_strength * weights
        if self.fit_intercept:
            grad[-1] = xp.sum(grad_pointwise)
    else:
        grad = np.empty((n_classes, n_dof), dtype=weights.dtype, order='F')
        grad_X = grad_pointwise.T @ X
        grad[:, :n_features] = move_to(grad_X, xp=np, device='cpu') + l2_reg_strength * weights
        if self.fit_intercept:
            grad[:, -1] = move_to(xp.sum(grad_pointwise, axis=0), xp=np, device='cpu')
        if coef.ndim == 1:
            grad = grad.ravel(order='F')
    return (loss, grad)

def gradient(self, coef, X, y, sample_weight=None, l2_reg_strength=0.0, n_threads=1, raw_prediction=None):
    (n_samples, n_features), n_classes = (X.shape, self.base_loss.n_classes)
    n_dof = n_features + int(self.fit_intercept)
    if raw_prediction is None:
        weights, intercept, raw_prediction = self.weight_intercept_raw(coef, X)
    else:
        weights, intercept = self.weight_intercept(coef)
    grad_pointwise = self.base_loss.gradient(y_true=y, raw_prediction=raw_prediction, sample_weight=sample_weight, n_threads=n_threads)
    xp, _, device = get_namespace_and_device(X, y, sample_weight)
    sw_sum = n_samples if sample_weight is None else xp.sum(sample_weight)
    grad_pointwise /= sw_sum
    if not self.base_loss.is_multiclass:
        grad = xp.empty_like(coef, dtype=weights.dtype, device=device)
        grad[:n_features] = X.T @ grad_pointwise + l2_reg_strength * weights
        if self.fit_intercept:
            grad[-1] = xp.sum(grad_pointwise)
        return grad
    else:
        if _is_numpy_namespace(xp):
            grad = np.empty((n_classes, n_dof), dtype=weights.dtype, order='F')
        else:
            grad = xp.empty((n_classes, n_dof), dtype=weights.dtype, device=device)
        grad[:, :n_features] = grad_pointwise.T @ X + l2_reg_strength * weights
        if self.fit_intercept:
            grad[:, -1] = xp.sum(grad_pointwise, axis=0)
        if coef.ndim == 1:
            if _is_numpy_namespace(xp):
                return grad.ravel(order='F')
            else:
                return _ravel(grad.T, xp=xp)
        else:
            return grad

def gradient_hessian(self, coef, X, y, sample_weight=None, l2_reg_strength=0.0, n_threads=1, gradient_out=None, hessian_out=None, grad_pointwise_out=None, hess_pointwise_out=None, raw_prediction=None):
    (n_samples, n_features), n_classes = (X.shape, self.base_loss.n_classes)
    n_dof = n_features + int(self.fit_intercept)
    if raw_prediction is None:
        weights, intercept, raw_prediction = self.weight_intercept_raw(coef, X)
    else:
        weights, intercept = self.weight_intercept(coef)
    sw_sum = n_samples if sample_weight is None else np.sum(sample_weight)
    if gradient_out is None:
        grad = np.empty_like(coef, dtype=weights.dtype, order='F')
    elif gradient_out.shape != coef.shape:
        raise ValueError(f'gradient_out is required to have shape coef.shape = {coef.shape}; got {gradient_out.shape}.')
    elif self.base_loss.is_multiclass and (not gradient_out.flags.f_contiguous):
        raise ValueError('gradient_out must be F-contiguous.')
    else:
        grad = gradient_out
    n = coef.size
    if hessian_out is None:
        hess = np.empty((n, n), dtype=weights.dtype)
    elif hessian_out.shape != (n, n):
        raise ValueError(f'hessian_out is required to have shape ({(n, n)}); got hessian_out.shape={hessian_out.shape!r}.')
    elif self.base_loss.is_multiclass and (not hessian_out.flags.c_contiguous and (not hessian_out.flags.f_contiguous)):
        raise ValueError('hessian_out must be contiguous.')
    else:
        hess = hessian_out
    if not self.base_loss.is_multiclass:
        grad_pointwise, hess_pointwise = self.base_loss.gradient_hessian(y_true=y, raw_prediction=raw_prediction, sample_weight=sample_weight, gradient_out=grad_pointwise_out, hessian_out=hess_pointwise_out, n_threads=n_threads)
        grad_pointwise /= sw_sum
        hess_pointwise /= sw_sum
        hessian_warning = np.average(hess_pointwise <= 0, weights=sample_weight) > 0.25
        hess_pointwise = np.abs(hess_pointwise)
        grad[:n_features] = X.T @ grad_pointwise + l2_reg_strength * weights
        if self.fit_intercept:
            grad[-1] = grad_pointwise.sum()
        if hessian_warning:
            return (grad, hess, hessian_warning)
        hess[:n_features, :n_features] = sandwich_dot(X, hess_pointwise)
        if l2_reg_strength > 0:
            order = 'C' if hess.flags.c_contiguous else 'F'
            hess.reshape(-1, order=order)[:n_features * n_dof:n_dof + 1] += l2_reg_strength
        if self.fit_intercept:
            Xh = X.T @ hess_pointwise
            hess[:-1, -1] = Xh
            hess[-1, :-1] = Xh
            hess[-1, -1] = hess_pointwise.sum()
    else:
        grad_pointwise, proba = self.base_loss.gradient_proba(y_true=y, raw_prediction=raw_prediction, sample_weight=sample_weight, gradient_out=grad_pointwise_out, proba_out=hess_pointwise_out, n_threads=n_threads)
        grad_pointwise /= sw_sum
        grad = grad.reshape((n_classes, n_dof), order='F')
        grad[:, :n_features] = grad_pointwise.T @ X + l2_reg_strength * weights
        if self.fit_intercept:
            grad[:, -1] = grad_pointwise.sum(axis=0)
        if coef.ndim == 1:
            grad = grad.ravel(order='F')
        if sample_weight is not None:
            sw = sample_weight / sw_sum
        else:
            sw = 1.0 / sw_sum
        for k in range(n_classes):
            h = proba[:, k] * (1 - proba[:, k]) * sw
            hess[k:n_classes * n_features:n_classes, k:n_classes * n_features:n_classes] = sandwich_dot(X, h)
            if self.fit_intercept:
                Xh = X.T @ h
                hess[k:n_classes * n_features:n_classes, n_classes * n_features + k] = Xh
                hess[n_classes * n_features + k, k:n_classes * n_features:n_classes] = Xh
                hess[n_classes * n_features + k, n_classes * n_features + k] = h.sum()
            for l in range(k + 1, n_classes):
                h = -proba[:, k] * proba[:, l] * sw
                hess[k:n_classes * n_features:n_classes, l:n_classes * n_features:n_classes] = sandwich_dot(X, h)
                if self.fit_intercept:
                    Xh = X.T @ h
                    hess[k:n_classes * n_features:n_classes, n_classes * n_features + l] = Xh
                    hess[n_classes * n_features + k, l:n_classes * n_features:n_classes] = Xh
                    hess[n_classes * n_features + k, n_classes * n_features + l] = h.sum()
                hess[l::n_classes, k::n_classes] = hess[k::n_classes, l::n_classes]
        if l2_reg_strength > 0:
            order = 'C' if hess.flags.c_contiguous else 'F'
            hess.reshape(-1, order=order)[:n_classes ** 2 * n_features * n_dof:n_classes * n_dof + 1] += l2_reg_strength
        hessian_warning = False
    return (grad, hess, hessian_warning)

def gradient_hessian_product(self, coef, X, y, sample_weight=None, l2_reg_strength=0.0, n_threads=1):
    (n_samples, n_features), n_classes = (X.shape, self.base_loss.n_classes)
    n_dof = n_features + int(self.fit_intercept)
    weights, intercept, raw_prediction = self.weight_intercept_raw(coef, X)
    xp, _, device = get_namespace_and_device(X, y, sample_weight)
    is_numpy_ns = _is_numpy_namespace(xp)
    sw_sum = n_samples if sample_weight is None else xp.sum(sample_weight)
    if not self.base_loss.is_multiclass:
        grad_pointwise, hess_pointwise = self.base_loss.gradient_hessian(y_true=y, raw_prediction=raw_prediction, sample_weight=sample_weight, n_threads=n_threads)
        grad_pointwise /= sw_sum
        hess_pointwise /= sw_sum
        grad = xp.empty_like(coef, dtype=weights.dtype)
        grad[:n_features] = X.T @ grad_pointwise + l2_reg_strength * weights
        if self.fit_intercept:
            grad[-1] = xp.sum(grad_pointwise)
        hessian_sum = xp.sum(hess_pointwise)
        if sparse.issparse(X):
            hX = sparse.dia_array((hess_pointwise, 0), shape=(n_samples, n_samples)) @ X
        else:
            hX = hess_pointwise[:, None] * X
        if self.fit_intercept:
            if sparse.issparse(X):
                hX_sum = xp.asarray(hX.sum(axis=0))
            else:
                hX_sum = xp.sum(hX, axis=0)

        def hessp(s):
            ret = xp.empty_like(s)
            if sparse.issparse(X):
                ret[:n_features] = X.T @ (hX @ s[:n_features])
            elif is_numpy_ns:
                ret[:n_features] = np.linalg.multi_dot([X.T, hX, s[:n_features]])
            else:
                ret[:n_features] = X.T @ (hX @ s[:n_features])
            ret[:n_features] += l2_reg_strength * s[:n_features]
            if self.fit_intercept:
                ret[:n_features] += s[-1] * hX_sum
                ret[-1] = hX_sum @ s[:n_features] + hessian_sum * s[-1]
            return ret
    else:
        grad_pointwise, proba = self.base_loss.gradient_proba(y_true=y, raw_prediction=raw_prediction, sample_weight=sample_weight, n_threads=n_threads)
        grad_pointwise /= sw_sum
        if is_numpy_ns:
            grad = np.empty((n_classes, n_dof), dtype=weights.dtype, order='F')
        else:
            grad = xp.empty((n_classes, n_dof), dtype=weights.dtype, device=device)
        grad[:, :n_features] = grad_pointwise.T @ X + l2_reg_strength * weights
        if self.fit_intercept:
            grad[:, -1] = xp.sum(grad_pointwise, axis=0)

        def hessp(s):
            if is_numpy_ns:
                s = s.reshape((n_classes, -1), order='F')
            else:
                s = xp.reshape(s, (-1, n_classes)).T
            if self.fit_intercept:
                s_intercept = s[:, -1]
                s = s[:, :-1]
            else:
                s_intercept = 0
            tmp = X @ s.T + s_intercept
            tmp -= xp.sum(proba * tmp, axis=1)[:, None]
            tmp *= proba
            if sample_weight is not None:
                tmp *= sample_weight[:, None]
            if is_numpy_ns:
                hess_prod = np.empty((n_classes, n_dof), dtype=weights.dtype, order='F')
            else:
                hess_prod = xp.empty((n_classes, n_dof), dtype=weights.dtype, device=device)
            hess_prod[:, :n_features] = tmp.T @ X / sw_sum + l2_reg_strength * s
            if self.fit_intercept:
                hess_prod[:, -1] = xp.sum(tmp, axis=0) / sw_sum
            if coef.ndim == 1:
                if is_numpy_ns:
                    return hess_prod.ravel(order='F')
                else:
                    return _ravel(hess_prod.T, xp=xp)
            else:
                return hess_prod
        if coef.ndim == 1:
            if is_numpy_ns:
                return (grad.ravel(order='F'), hessp)
            else:
                return (_ravel(grad.T, xp=xp), hessp)
    return (grad, hessp)

def _compute_coef_intercept(w, *, n_classes, is_binary, fit_intercept, coefs_order, dtype, xp, device_):
    if is_binary:
        coef = xp.asarray(w.copy(order=coefs_order), dtype=dtype, device=device_)
        if fit_intercept:
            intercept = coef[-1:]
            coef = coef[:-1][None, :]
        else:
            intercept = xp.zeros(1, dtype=dtype, device=device_)
            coef = coef[None, :]
    else:
        multi_w = np.reshape(w, (n_classes, -1), order='F')
        coef = xp.asarray(multi_w.copy(order=coefs_order), dtype=dtype, device=device_)
        if fit_intercept:
            intercept = coef[:, -1]
            coef = coef[:, :-1]
        else:
            intercept = xp.zeros(n_classes, dtype=dtype, device=device_)
    return (coef, intercept)

def _logistic_regression_path(X, y, *, classes, Cs=10, fit_intercept=True, max_iter=100, tol=0.0001, verbose=0, solver='lbfgs', coef=None, class_weight=None, dual=False, penalty='l2', intercept_scaling=1.0, random_state=None, check_input=True, max_squared_sum=None, sample_weight=None, l1_ratio=None, n_threads=1, callback_ctx=None, estimator=None):
    if isinstance(Cs, numbers.Integral):
        Cs = np.logspace(-4, 4, Cs)
    solver = _check_solver(solver, penalty, dual)
    xp, _, device_ = get_namespace_and_device(X)
    coef_as_xp = solver == 'newton-cg'
    if check_input:
        X = check_array(X, accept_sparse='csr', dtype=[xp.float64, xp.float32], accept_large_sparse=solver not in ['liblinear', 'sag', 'saga'])
        y = check_array(y, ensure_2d=False, dtype=None)
        check_consistent_length(X, y)
    if sample_weight is not None or class_weight is not None:
        sample_weight = _check_sample_weight(sample_weight, X, dtype=X.dtype, copy=True, ensure_same_device=True)
    n_samples, n_features = X.shape
    n_classes = classes.shape[0] if hasattr(classes, 'shape') else len(classes)
    is_binary = n_classes == 2
    if solver == 'liblinear' and (not is_binary):
        raise ValueError("The 'liblinear' solver does not support multiclass classification (n_classes >= 3). Either use another solver or wrap the estimator in a OneVsRestClassifier to keep applying a one-versus-rest scheme.")
    random_state = check_random_state(random_state)
    le = LabelEncoder().fit(classes)
    if class_weight is not None:
        class_weight_ = compute_class_weight(class_weight, classes=classes, y=y, sample_weight=sample_weight)
        class_weight_ = xp.asarray(class_weight_[le.transform(y)], dtype=X.dtype, device=device_)
        sample_weight *= class_weight_
    if is_binary:
        if coef_as_xp:
            w0 = xp.zeros(n_features + int(fit_intercept), dtype=X.dtype, device=device_)
        else:
            w0 = np.zeros(n_features + int(fit_intercept), dtype=_matching_numpy_dtype(X, xp=xp))
        mask = move_to(y == classes[1], xp=xp, device=device_)
        y_bin = xp.ones(y.shape, dtype=X.dtype, device=device_)
        if solver == 'liblinear':
            y_bin[~mask] = -1.0
        else:
            y_bin[~mask] = 0.0
    else:
        Y_multi = xp.asarray(le.transform(y), dtype=X.dtype, device=device_)
        if coef_as_xp:
            w0 = xp.zeros((size(classes), n_features + int(fit_intercept)), dtype=X.dtype, device=device_)
        else:
            w0 = np.zeros((size(classes), n_features + int(fit_intercept)), order='F', dtype=_matching_numpy_dtype(X, xp=xp))
    if solver in ['lbfgs', 'newton-cg', 'newton-cholesky']:
        sw_sum = n_samples if sample_weight is None else float(xp.sum(sample_weight))
    if coef is not None:
        if is_binary:
            if coef.ndim == 1 and coef.shape[0] == n_features + int(fit_intercept):
                w0[:] = move_to(coef, xp=xp, device=device_) if coef_as_xp else coef
            elif coef.ndim == 2 and coef.shape[0] == 1 and (coef.shape[1] == n_features + int(fit_intercept)):
                w0[:] = move_to(coef[0], xp=xp, device=device_) if coef_as_xp else coef[0]
            else:
                msg = f'Initialization coef is of shape {coef.shape}, expected shape {w0.shape} or (1, {w0.shape[0]})'
                raise ValueError(msg)
        elif coef.ndim == 2 and coef.shape[0] == n_classes and (coef.shape[1] == n_features + int(fit_intercept)):
            w0[:, :coef.shape[1]] = move_to(coef, xp=xp, device=device_) if coef_as_xp else coef
        else:
            msg = f'Initialization coef is of shape {coef.shape}, expected shape {w0.shape}'
            raise ValueError(msg)
    if is_binary:
        target = y_bin
        loss = LinearModelLoss(base_loss=HalfBinomialLoss() if _is_numpy_namespace(xp) else HalfBinomialLossArrayAPI(xp=xp, device=device_), fit_intercept=fit_intercept)
        if solver == 'lbfgs':
            func = loss.loss_gradient
        elif solver == 'newton-cg':
            func = loss.loss
            grad = loss.gradient
            hess = loss.gradient_hessian_product
        warm_start_sag = {'coef': w0[:, None]}
    else:
        loss = LinearModelLoss(base_loss=HalfMultinomialLoss(n_classes=size(classes)) if _is_numpy_namespace(xp) else HalfMultinomialLossArrayAPI(n_classes=size(classes), xp=xp, device=device_), fit_intercept=fit_intercept)
        target = Y_multi
        if solver in ['lbfgs', 'newton-cg', 'newton-cholesky']:
            if _is_numpy_namespace(xp) or not coef_as_xp:
                w0 = w0.ravel(order='F')
            else:
                w0 = _ravel(w0.T, xp=xp)
        if solver == 'lbfgs':
            func = loss.loss_gradient
        elif solver == 'newton-cg':
            func = loss.loss
            grad = loss.gradient
            hess = loss.gradient_hessian_product
        warm_start_sag = {'coef': w0.T} if w0.ndim > 1 else {'coef': w0}
    coefs = list()
    n_iter = xp.zeros(len(Cs), dtype=xp.int32, device=device_)
    coefs_order = 'C' if not _is_numpy_namespace(xp) else 'K'
    callback_metadata = {'sample_weight': sample_weight} if sample_weight is not None else None
    for i, C in enumerate(Cs):
        if solver == 'lbfgs':
            lbfgs_bridge = None
            if callback_ctx is not None and hasattr(estimator, '_skl_callbacks'):
                lbfgs_bridge = _LbfgsCallbackBridge(callback_ctx, estimator, X, y, callback_metadata, w0, n_classes=n_classes, is_binary=is_binary, fit_intercept=fit_intercept, coefs_order=coefs_order, xp=xp, device_=device_)
            l2_reg_strength = 1.0 / (C * sw_sum)
            iprint = [-1, 50, 1, 100, 101][np.searchsorted(np.array([0, 1, 2, 3]), verbose)]
            opt_res = optimize.minimize(func, w0, method='L-BFGS-B', jac=True, args=(X, target, sample_weight, l2_reg_strength, n_threads), options={'maxiter': max_iter, 'maxls': 50, 'gtol': tol, 'ftol': 64 * np.finfo(float).eps, **_get_additional_lbfgs_options_dict('iprint', iprint)}, callback=lbfgs_bridge)
            n_iter_i = _check_optimize_result(solver, opt_res, max_iter, extra_warning_msg=_LOGISTIC_SOLVER_CONVERGENCE_MSG)
            w0, loss = (opt_res.x, opt_res.fun)
            if lbfgs_bridge is not None:
                lbfgs_bridge.close()
            if fit_intercept and (not is_binary):
                w0[-n_classes:] -= np.mean(w0[-n_classes:])
        elif solver == 'newton-cg':
            l2_reg_strength = 1.0 / (C * sw_sum)
            args = (X, target, sample_weight, l2_reg_strength, n_threads)
            w0, n_iter_i = _newton_cg(grad_hess=hess, func=func, grad=grad, x0=w0, args=args, maxiter=max_iter, tol=tol, verbose=verbose)
            if fit_intercept and (not is_binary):
                w0[-n_classes:] -= xp.mean(w0[-n_classes:])
        elif solver == 'newton-cholesky':
            l2_reg_strength = 1.0 / (C * sw_sum)
            sol = NewtonCholeskySolver(coef=w0, linear_loss=loss, l2_reg_strength=l2_reg_strength, tol=tol, max_iter=max_iter, n_threads=n_threads, verbose=verbose)
            w0 = sol.solve(X=X, y=target, sample_weight=sample_weight)
            n_iter_i = sol.iteration
        elif solver == 'liblinear':
            coef_, intercept_, n_iter_i = _fit_liblinear(X, target, C, fit_intercept, intercept_scaling, None, penalty, dual, verbose, max_iter, tol, random_state, sample_weight=sample_weight)
            if fit_intercept:
                w0 = np.concatenate([coef_.ravel(), intercept_])
            else:
                w0 = coef_.ravel()
            n_iter_i = n_iter_i.item()
        elif solver in ['sag', 'saga']:
            if is_binary:
                loss = 'log'
            else:
                target = target.astype(X.dtype, copy=False)
                loss = 'multinomial'
            if penalty == 'l1':
                alpha = 0.0
                beta = 1.0 / C
            elif penalty == 'l2':
                alpha = 1.0 / C
                beta = 0.0
            else:
                alpha = 1.0 / C * (1 - l1_ratio)
                beta = 1.0 / C * l1_ratio
            w0, n_iter_i, warm_start_sag = sag_solver(X, target, sample_weight, loss, alpha, beta, max_iter, tol, verbose, random_state, False, max_squared_sum, warm_start_sag, is_saga=solver == 'saga')
        else:
            msg = f"solver must be one of {{'lbfgs', 'liblinear', 'newton-cg', 'newton-cholesky', 'sag', 'saga'}}, got '{solver}' instead."
            raise ValueError(msg)
        if is_binary:
            if _is_numpy_namespace(xp):
                coefs.append(np.asarray(w0.copy(order=coefs_order), dtype=X.dtype))
            else:
                coefs.append(xp.asarray(w0, copy=True, dtype=X.dtype, device=device_))
        else:
            if solver in ['lbfgs', 'newton-cg', 'newton-cholesky']:
                if _is_numpy_namespace(xp) or not coef_as_xp:
                    multi_w0 = np.reshape(w0, (n_classes, -1), order='F')
                else:
                    multi_w0 = xp.reshape(w0, (-1, n_classes)).T
            else:
                multi_w0 = w0
            coefs.append(xp.asarray(multi_w0, copy=True, dtype=X.dtype, device=device_))
        n_iter[i] = n_iter_i
    return (xp.stack(coefs), xp.asarray(Cs, device=device_), n_iter)

def _log_reg_scoring_path(X, y, train, test, *, classes, Cs, scoring, fit_intercept, max_iter, tol, class_weight, verbose, solver, penalty, dual, intercept_scaling, random_state, max_squared_sum, sample_weight, l1_ratio, score_params):
    X_train = X[train]
    X_test = X[test]
    y_train = y[train]
    y_test = y[test]
    sw_train, sw_test = (None, None)
    if sample_weight is not None:
        sample_weight = _check_sample_weight(sample_weight, X)
        sw_train = sample_weight[train]
        sw_test = sample_weight[test]
    coefs, Cs, n_iter = _logistic_regression_path(X_train, y_train, classes=classes, Cs=Cs, l1_ratio=l1_ratio, fit_intercept=fit_intercept, solver=solver, max_iter=max_iter, class_weight=class_weight, tol=tol, verbose=verbose, dual=dual, penalty=penalty, intercept_scaling=intercept_scaling, random_state=random_state, check_input=False, max_squared_sum=max_squared_sum, sample_weight=sw_train, callback_ctx=None, estimator=None)
    log_reg = LogisticRegression(solver=solver)
    log_reg.classes_ = classes
    scores = list()
    scoring = get_scorer(scoring)
    if scoring is None:

        def calc_score(log_reg):
            return log_reg.score(X_test, y_test, sample_weight=sw_test)
    else:
        is_binary = len(classes) <= 2
        score_params = score_params or {}
        score_params = _check_method_params(X=X, params=score_params, indices=test)
        if hasattr(scoring, '_score_func'):
            sig = inspect.signature(scoring._score_func).parameters
        else:
            sig = []
        if 'labels' in sig:
            pos_label_kwarg = {}
            if is_binary and 'pos_label' in sig:
                pos_label_kwarg['pos_label'] = classes[-1]
            scoring = make_scorer(scoring._score_func, greater_is_better=True if scoring._sign == 1 else False, response_method=scoring._response_method, labels=classes, **pos_label_kwarg, **getattr(scoring, '_kwargs', {}))

        def calc_score(log_reg):
            return scoring(log_reg, X_test, y_test, **score_params)
    for w, C in zip(coefs, Cs):
        log_reg.C = C
        if fit_intercept:
            log_reg.coef_ = w[..., :-1]
            log_reg.intercept_ = w[..., -1]
        else:
            log_reg.coef_ = w
            log_reg.intercept_ = 0.0
        scores.append(calc_score(log_reg))
    return (coefs, Cs, np.array(scores), n_iter)

def set_callbacks(self, *callbacks):
    if self.solver != 'lbfgs':
        warnings.warn(f"Callbacks are only supported in {self.__class__.__name__} for solver='lbfgs'. This estimator has solver='{self.solver}', callbacks will be ignored during the solving of the regression.")
    return super().set_callbacks(*callbacks)

@_fit_context(prefer_skip_nested_validation=True)
def fit(self, X, y, sample_weight=None):
    if self.penalty == 'deprecated':
        if self.l1_ratio == 0 or self.l1_ratio is None:
            penalty = 'l2'
            if self.l1_ratio is None:
                warnings.warn("'l1_ratio=None' was deprecated in version 1.8 and will trigger an error in 1.10. Use 0<=l1_ratio<=1 instead.", FutureWarning)
        elif self.l1_ratio == 1:
            penalty = 'l1'
        else:
            penalty = 'elasticnet'
        if self.C == np.inf:
            penalty = None
    else:
        penalty = self.penalty
        warnings.warn("'penalty' was deprecated in version 1.8 and will be removed in 1.10. To avoid this warning, leave 'penalty' set to its default value and use 'l1_ratio' or 'C' instead. Use l1_ratio=0 instead of penalty='l2', l1_ratio=1 instead of penalty='l1', l1_ratio set to a float between 0 and 1 instead of penalty='elasticnet', and C=np.inf instead of penalty=None.", FutureWarning)
    solver = _check_solver(self.solver, penalty, self.dual)
    if penalty != 'elasticnet' and (self.l1_ratio is not None and 0 < self.l1_ratio < 1):
        warnings.warn("l1_ratio parameter is only used when penalty is 'elasticnet'. Got (penalty={})".format(penalty))
    if self.penalty == 'l2' and self.l1_ratio != 0 or (self.penalty == 'l1' and self.l1_ratio != 1):
        warnings.warn(f'Inconsistent values: penalty={self.penalty} with l1_ratio={self.l1_ratio}. penalty is deprecated. Please use l1_ratio only.')
    if penalty == 'elasticnet' and self.l1_ratio is None:
        raise ValueError('l1_ratio must be specified when penalty is elasticnet.')
    xp, _, device_ = get_namespace_and_device(X)
    sample_weight = move_to(sample_weight, xp=xp, device=device_)
    xp_y, _ = get_namespace(y)
    if self.penalty is None:
        if self.C != 1.0:
            warnings.warn('Setting penalty=None will ignore the C and l1_ratio parameters')
        C_ = xp.inf
        penalty = 'l2'
    else:
        C_ = self.C
    msg = f"'n_jobs' has no effect since 1.8 and will be removed in 1.10. You provided 'n_jobs={self.n_jobs}', please leave it unspecified."
    if self.n_jobs is not None:
        warnings.warn(msg, category=FutureWarning)
    X, y = validate_data(self, X, y, accept_sparse='csr', dtype=[xp.float64, xp.float32], order='C', accept_large_sparse=solver not in ['liblinear', 'sag', 'saga'])
    n_features = X.shape[1]
    check_classification_targets(y)
    self.classes_ = xp_y.unique_values(y)
    n_classes = size(self.classes_)
    is_binary = n_classes == 2
    max_subtasks = max(self.max_iter, 1) + 1
    callback_ctx = self._init_callback_context(max_subtasks=max_subtasks)
    callback_metadata = {'sample_weight': sample_weight} if sample_weight is not None else None
    callback_ctx.call_on_fit_task_begin(estimator=self, X=X, y=y, metadata=callback_metadata)
    if solver == 'liblinear':
        if not is_binary:
            raise ValueError("The 'liblinear' solver does not support multiclass classification (n_classes >= 3). Either use another solver or wrap the estimator in a OneVsRestClassifier to keep applying a one-versus-rest scheme.")
        if np.max(X) > 1e+30:
            raise ValueError("Using the 'liblinear' solver while X contains a maximum value > 1e30 results in a frozen fit. Please choose another solver or rescale the input X.")
        self.coef_, self.intercept_, self.n_iter_ = _fit_liblinear(X, y, self.C, self.fit_intercept, self.intercept_scaling, self.class_weight, penalty, self.dual, self.verbose, self.max_iter, self.tol, self.random_state, sample_weight=sample_weight)
        return self
    if solver in ['sag', 'saga']:
        max_squared_sum = row_norms(X, squared=True).max()
    else:
        max_squared_sum = None
    if n_classes < 2:
        raise ValueError('This solver needs samples of at least 2 classes in the data, but the data contains only one class: %r' % self.classes_[0])
    if self.warm_start:
        warm_start_coef = getattr(self, 'coef_', None)
    else:
        warm_start_coef = None
    if warm_start_coef is not None:
        warm_start_coef = move_to(warm_start_coef, xp=np, device='cpu')
        if self.fit_intercept:
            intercept_np = move_to(self.intercept_, xp=np, device='cpu')
            warm_start_coef = np.concatenate([warm_start_coef, intercept_np[:, None]], axis=1)
    n_threads = 1
    coefs, _, n_iter = _logistic_regression_path(X, y, classes=self.classes_, Cs=[C_], l1_ratio=self.l1_ratio, fit_intercept=self.fit_intercept, tol=self.tol, verbose=self.verbose, solver=solver, max_iter=self.max_iter, class_weight=self.class_weight, check_input=False, random_state=self.random_state, coef=warm_start_coef, penalty=penalty, max_squared_sum=max_squared_sum, sample_weight=sample_weight, n_threads=n_threads, callback_ctx=callback_ctx, estimator=self)
    self.n_iter_ = xp.asarray(n_iter, dtype=xp.int32)
    self.coef_ = coefs[0, ...]
    if self.fit_intercept:
        if is_binary:
            self.intercept_ = self.coef_[-1:]
            self.coef_ = self.coef_[:-1][None, :]
        else:
            self.intercept_ = self.coef_[:, -1]
            self.coef_ = self.coef_[:, :-1]
    elif is_binary:
        self.intercept_ = xp.zeros(1, dtype=X.dtype, device=device_)
        self.coef_ = self.coef_[None, :]
    else:
        self.intercept_ = xp.zeros(n_classes, dtype=X.dtype, device=device_)
    callback_ctx.call_on_fit_task_end(estimator=self, X=X, y=y, metadata=callback_metadata, reconstruction_attributes={})
    return self

def predict_proba(self, X):
    check_is_fitted(self)
    check_same_namespace(X, self, attribute='coef_', method='predict_proba')
    is_binary = size(self.classes_) <= 2
    if is_binary:
        return super()._predict_proba_lr(X)
    else:
        decision_2d = self.decision_function(X)
        return softmax(decision_2d, copy=False)

def predict_log_proba(self, X):
    check_same_namespace(X, self, attribute='coef_', method='predict_log_proba')
    xp, _ = get_namespace(X)
    return xp.log(self.predict_proba(X))

@_fit_context(prefer_skip_nested_validation=True)
def fit(self, X, y, sample_weight=None, **params):
    _raise_for_params(params, self, 'fit')
    if isinstance(self.l1_ratios, str) and self.l1_ratios == 'warn':
        l1_ratios = None
        warnings.warn('The default value for l1_ratios will change from None to (0.0,) in version 1.10. From version 1.10 onwards, only array-like with values in [0, 1] will be allowed, None will be forbidden. To avoid this warning, explicitly set a value, e.g. l1_ratios=(0,).', FutureWarning)
    else:
        l1_ratios = self.l1_ratios
    if self.penalty == 'deprecated':
        if self.l1_ratios is None:
            warnings.warn("'l1_ratios=None' was deprecated in version 1.8 and will trigger an error in 1.10. Use an array-like with valuesin [0, 1] instead.", FutureWarning)
        if np.all(np.asarray(l1_ratios) == 0) or l1_ratios is None:
            penalty = 'l2'
        elif np.all(np.asarray(l1_ratios) == 1):
            penalty = 'l1'
        else:
            penalty = 'elasticnet'
    else:
        penalty = self.penalty
        warnings.warn("'penalty' was deprecated in version 1.8 and will be removed in 1.10. To avoid this warning, leave 'penalty' set to its default value and use 'l1_ratios' and 'Cs' instead. Use l1_ratios=(0,) instead of penalty='l2', l1_ratios=(1,) instead of penalty='l1', l1_ratios set to floats between 0 and 1 instead of penalty='elasticnet', and Cs=(np.inf,) instead of penalty=None.", FutureWarning)
    if self.scoring == 'warn':
        warnings.warn("The default value of the parameter 'scoring' will change from None, i.e. accuracy, to 'neg_log_loss' in version 1.11. To silence this warning, explicitly set the scoring parameter: scoring='neg_log_loss' for the new, scoring='accuracy' or scoring=None for the old default.", FutureWarning)
        scoring = None
    else:
        scoring = self.scoring
    if self.use_legacy_attributes == 'warn':
        warnings.warn(f'The fitted attributes of {self.__class__.__name__} will be simplified in scikit-learn 1.10 to remove redundancy. Set`use_legacy_attributes=False` to enable the new behavior now, or set it to `True` to silence this warning during the transition period while keeping the deprecated behavior for the time being. The default value of use_legacy_attributes will change from True to False in scikit-learn 1.10. See the docstring of {self.__class__.__name__} for more details.', FutureWarning)
        use_legacy_attributes = True
