        c[0] = 0
        c[n_params] = 0
    if self.solver in ['highs', 'highs-ds', 'highs-ipm']:
        eye = _sparse_eye_array(n_indices, dtype=X.dtype, format='csc')
        if self.fit_intercept:
            ones = sparse.csc_array(np.ones(shape=(n_indices, 1), dtype=X.dtype))
            A_eq = sparse.hstack([ones, X, -ones, -X, eye, -eye], format='csc')
        else:
            A_eq = sparse.hstack([X, -X, eye, -eye], format='csc')
    else:
        eye = np.eye(n_indices)
        if self.fit_intercept:
            ones = np.ones((n_indices, 1))
            A_eq = np.concatenate([ones, X, -ones, -X, eye, -eye], axis=1)
        else:
            A_eq = np.concatenate([X, -X, eye, -eye], axis=1)
    b_eq = y
    result = linprog(c=c, A_eq=A_eq, b_eq=b_eq, method=self.solver, options=solver_options)
    solution = result.x
    if not result.success:
        failure = {1: 'Iteration limit reached.', 2: 'Problem appears to be infeasible.', 3: 'Problem appears to be unbounded.', 4: 'Numerical difficulties encountered.'}
        warnings.warn(f'Linear programming for QuantileRegressor did not succeed.\nStatus is {result.status}: ' + failure.setdefault(result.status, 'unknown reason') + '\n' + 'Result message of linprog:\n' + result.message, ConvergenceWarning)
    params = solution[:n_params] - solution[n_params:2 * n_params]
    self.n_iter_ = result.nit
    if self.fit_intercept:
        self.coef_ = params[1:]
        self.intercept_ = params[0]
    else:
        self.coef_ = params
        self.intercept_ = 0.0
    return self

def _dynamic_max_trials(n_inliers, n_samples, min_samples, probability):
    inlier_ratio = n_inliers / float(n_samples)
    nom = max(_EPSILON, 1 - probability)
    denom = max(_EPSILON, 1 - inlier_ratio ** min_samples)
    if nom == 1:
        return 0
    if denom == 1:
        return float('inf')
    return abs(float(np.ceil(np.log(nom) / np.log(denom))))

@_fit_context(prefer_skip_nested_validation=False)
def fit(self, X, y, sample_weight=None, **fit_params):
    _raise_for_params(fit_params, self, 'fit')
    check_X_params = dict(accept_sparse='csr', ensure_all_finite=False)
    check_y_params = dict(ensure_2d=False)
    X, y = validate_data(self, X, y, validate_separately=(check_X_params, check_y_params))
    check_consistent_length(X, y)
    if self.estimator is not None:
        estimator = clone(self.estimator)
    else:
        estimator = LinearRegression()
    if self.min_samples is None:
        if not isinstance(estimator, LinearRegression):
            raise ValueError('`min_samples` needs to be explicitly set when estimator is not a LinearRegression.')
        min_samples = X.shape[1] + 1
    elif 0 < self.min_samples < 1:
        min_samples = np.ceil(self.min_samples * X.shape[0])
    elif self.min_samples >= 1:
        min_samples = self.min_samples
    if min_samples > X.shape[0]:
        raise ValueError('`min_samples` may not be larger than number of samples: n_samples = %d.' % X.shape[0])
    if self.residual_threshold is None:
        residual_threshold = np.median(np.abs(y - np.median(y)))
    else:
        residual_threshold = self.residual_threshold
    if self.loss == 'absolute_error':
        if y.ndim == 1:
            loss_function = lambda y_true, y_pred: np.abs(y_true - y_pred)
        else:
            loss_function = lambda y_true, y_pred: np.sum(np.abs(y_true - y_pred), axis=1)
    elif self.loss == 'squared_error':
        if y.ndim == 1:
            loss_function = lambda y_true, y_pred: (y_true - y_pred) ** 2
        else:
            loss_function = lambda y_true, y_pred: np.sum((y_true - y_pred) ** 2, axis=1)
    elif callable(self.loss):
        loss_function = self.loss
    random_state = check_random_state(self.random_state)
    try:
        estimator.set_params(random_state=random_state)
    except ValueError:
        pass
    estimator_fit_has_sample_weight = has_fit_parameter(estimator, 'sample_weight')
    estimator_name = type(estimator).__name__
    if sample_weight is not None and (not estimator_fit_has_sample_weight):
        raise ValueError('%s does not support sample_weight. Sample weights are only used for the calibration itself.' % estimator_name)
    if sample_weight is not None:
        fit_params['sample_weight'] = sample_weight
    if _routing_enabled():
        routed_params = process_routing(self, 'fit', **fit_params)
    else:
        sw = {'sample_weight': _check_sample_weight(sample_weight, X)} if sample_weight is not None else {}
        routed_params = _manual_routing({'estimator': {'fit': sw}})
    n_inliers_best = 1
    score_best = -np.inf
    inlier_mask_best = None
    X_inlier_best = None
    y_inlier_best = None
    inlier_best_idxs_subset = None
    self.n_skips_no_inliers_ = 0
    self.n_skips_invalid_data_ = 0
    self.n_skips_invalid_model_ = 0
    n_samples = X.shape[0]
    sample_idxs = np.arange(n_samples)
    self.n_trials_ = 0
    max_trials = self.max_trials
    while self.n_trials_ < max_trials:
        self.n_trials_ += 1
        if self.n_skips_no_inliers_ + self.n_skips_invalid_data_ + self.n_skips_invalid_model_ > self.max_skips:
            break
        subset_idxs = sample_without_replacement(n_samples, min_samples, random_state=random_state)
        X_subset = X[subset_idxs]
        y_subset = y[subset_idxs]
        if self.is_data_valid is not None and (not self.is_data_valid(X_subset, y_subset)):
            self.n_skips_invalid_data_ += 1
            continue
        fit_params_subset = _check_method_params(X, params=routed_params.estimator.fit, indices=subset_idxs)
        estimator.fit(X_subset, y_subset, **fit_params_subset)
        if self.is_model_valid is not None and (not self.is_model_valid(estimator, X_subset, y_subset)):
            self.n_skips_invalid_model_ += 1
            continue
        y_pred = estimator.predict(X)
        residuals_subset = loss_function(y, y_pred)
        inlier_mask_subset = residuals_subset <= residual_threshold
        n_inliers_subset = np.sum(inlier_mask_subset)
        if n_inliers_subset < n_inliers_best:
            self.n_skips_no_inliers_ += 1
            continue
        inlier_idxs_subset = sample_idxs[inlier_mask_subset]
        X_inlier_subset = X[inlier_idxs_subset]
        y_inlier_subset = y[inlier_idxs_subset]
        score_params_inlier_subset = _check_method_params(X, params=routed_params.estimator.score, indices=inlier_idxs_subset)
        score_subset = estimator.score(X_inlier_subset, y_inlier_subset, **score_params_inlier_subset)
        if n_inliers_subset == n_inliers_best and score_subset < score_best:
            continue
        n_inliers_best = n_inliers_subset
        score_best = score_subset
        inlier_mask_best = inlier_mask_subset
        X_inlier_best = X_inlier_subset
        y_inlier_best = y_inlier_subset
        inlier_best_idxs_subset = inlier_idxs_subset
        max_trials = min(max_trials, _dynamic_max_trials(n_inliers_best, n_samples, min_samples, self.stop_probability))
        if n_inliers_best >= self.stop_n_inliers or score_best >= self.stop_score:
            break
    if inlier_mask_best is None:
        if self.n_skips_no_inliers_ + self.n_skips_invalid_data_ + self.n_skips_invalid_model_ > self.max_skips:
            raise ValueError('RANSAC skipped more iterations than `max_skips` without finding a valid consensus set. Iterations were skipped because each randomly chosen sub-sample failed the passing criteria. See estimator attributes for diagnostics (n_skips*).')
        else:
            raise ValueError('RANSAC could not find a valid consensus set. All `max_trials` iterations were skipped because each randomly chosen sub-sample failed the passing criteria. See estimator attributes for diagnostics (n_skips*).')
    elif self.n_skips_no_inliers_ + self.n_skips_invalid_data_ + self.n_skips_invalid_model_ > self.max_skips:
        warnings.warn('RANSAC found a valid consensus set but exited early due to skipping more iterations than `max_skips`. See estimator attributes for diagnostics (n_skips*).', ConvergenceWarning)
    fit_params_best_idxs_subset = _check_method_params(X, params=routed_params.estimator.fit, indices=inlier_best_idxs_subset)
    estimator.fit(X_inlier_best, y_inlier_best, **fit_params_best_idxs_subset)
    self.estimator_ = estimator
    self.inlier_mask_ = inlier_mask_best
    return self

def predict(self, X, **params):
    check_is_fitted(self)
    X = validate_data(self, X, ensure_all_finite=False, accept_sparse=True, reset=False)
    _raise_for_params(params, self, 'predict')
    if _routing_enabled():
        predict_params = process_routing(self, 'predict', **params).estimator['predict']
    else:
        predict_params = {}
    return self.estimator_.predict(X, **predict_params)

def score(self, X, y, **params):
    check_is_fitted(self)
    X = validate_data(self, X, ensure_all_finite=False, accept_sparse=True, reset=False)
    _raise_for_params(params, self, 'score')
    if _routing_enabled():
        score_params = process_routing(self, 'score', **params).estimator['score']
    else:
        score_params = {}
    return self.estimator_.score(X, y, **score_params)

def get_metadata_routing(self):
    router = MetadataRouter(owner=self).add(estimator=self.estimator, method_mapping=MethodMapping().add(caller='fit', callee='fit').add(caller='fit', callee='score').add(caller='score', callee='score').add(caller='predict', callee='predict'))
    return router

def _get_rescaled_operator(X, X_offset, sample_weight_sqrt):

    def matvec(b):
        return X.dot(b) - sample_weight_sqrt * b.dot(X_offset)

    def rmatvec(b):
        return X.T.dot(b) - X_offset * b.dot(sample_weight_sqrt)
    X1 = sparse.linalg.LinearOperator(shape=X.shape, matvec=matvec, rmatvec=rmatvec)
    return X1

def _solve_lsqr(X, y, *, alpha, fit_intercept=True, max_iter=None, tol=0.0001, X_offset=None, X_scale=None, sample_weight_sqrt=None):
    if sample_weight_sqrt is None:
        sample_weight_sqrt = np.ones(X.shape[0], dtype=X.dtype)
    if sparse.issparse(X) and fit_intercept:
        X_offset_scale = X_offset / X_scale
        X1 = _get_rescaled_operator(X, X_offset_scale, sample_weight_sqrt)
    else:
        X1 = X
    n_samples, n_features = X.shape
    coefs = np.empty((y.shape[1], n_features), dtype=X.dtype)
    n_iter = np.empty(y.shape[1], dtype=np.int32)
    sqrt_alpha = np.sqrt(alpha)
    for i in range(y.shape[1]):
        y_column = y[:, i]
        info = sp_linalg.lsqr(X1, y_column, damp=sqrt_alpha[i], atol=tol, btol=tol, iter_lim=max_iter)
        coefs[i] = info[0]
        n_iter[i] = info[2]
    return (coefs, n_iter)

def _solve_lbfgs(X, y, alpha, positive=True, max_iter=None, tol=0.0001, X_offset=None, X_scale=None, sample_weight_sqrt=None):
    n_samples, n_features = X.shape
    options = {}
    if max_iter is not None:
        options['maxiter'] = max_iter
    config = {'method': 'L-BFGS-B', 'tol': tol, 'jac': True, 'options': options}
    if positive:
        config['bounds'] = [(0, np.inf)] * n_features
    if X_offset is not None and X_scale is not None:
        X_offset_scale = X_offset / X_scale
    else:
        X_offset_scale = None
    if sample_weight_sqrt is None:
        sample_weight_sqrt = np.ones(X.shape[0], dtype=X.dtype)
    coefs = np.empty((y.shape[1], n_features), dtype=X.dtype)
    for i in range(y.shape[1]):
        x0 = np.zeros((n_features,))
        y_column = y[:, i]

        def func(w):
            residual = X.dot(w) - y_column
            if X_offset_scale is not None:
                residual -= sample_weight_sqrt * w.dot(X_offset_scale)
            f = 0.5 * residual.dot(residual) + 0.5 * alpha[i] * w.dot(w)
            grad = X.T @ residual + alpha[i] * w
            if X_offset_scale is not None:
                grad -= X_offset_scale * residual.dot(sample_weight_sqrt)
            return (f, grad)
        result = optimize.minimize(func, x0, **config)
        if not result['success']:
            warnings.warn(f'The lbfgs solver did not converge. Try increasing max_iter or tol. Currently: max_iter={max_iter} and tol={tol}', ConvergenceWarning)
        coefs[i] = result['x']
    return coefs

@validate_params({'X': ['array-like', 'sparse matrix', sp_linalg.LinearOperator], 'y': ['array-like'], 'alpha': [Interval(Real, 0, None, closed='left'), 'array-like'], 'sample_weight': [Interval(Real, None, None, closed='neither'), 'array-like', None], 'solver': [StrOptions({'auto', 'svd', 'cholesky', 'lsqr', 'sparse_cg', 'sag', 'saga', 'lbfgs'})], 'max_iter': [Interval(Integral, 0, None, closed='left'), None], 'tol': [Interval(Real, 0, None, closed='left')], 'verbose': ['verbose'], 'positive': ['boolean'], 'random_state': ['random_state'], 'return_n_iter': ['boolean'], 'return_intercept': ['boolean'], 'check_input': ['boolean']}, prefer_skip_nested_validation=True)
def ridge_regression(X, y, alpha, *, sample_weight=None, solver='auto', max_iter=None, tol=0.0001, verbose=0, positive=False, random_state=None, return_n_iter=False, return_intercept=False, check_input=True):
    return _ridge_regression(X, y, alpha, sample_weight=sample_weight, solver=solver, max_iter=max_iter, tol=tol, verbose=verbose, positive=positive, random_state=random_state, return_n_iter=return_n_iter, return_intercept=return_intercept, X_scale=None, X_offset=None, check_input=check_input)

@_fit_context(prefer_skip_nested_validation=True)
def fit(self, X, y, sample_weight=None):
    _accept_sparse = _get_valid_accept_sparse(sparse.issparse(X), self.solver)
    xp, _, device_ = get_namespace_and_device(X)
    y, sample_weight = move_to(y, sample_weight, xp=xp, device=device_)
    X, y = validate_data(self, X, y, accept_sparse=_accept_sparse, dtype=[xp.float64, xp.float32], force_writeable=True, multi_output=True, y_numeric=True)
    return super().fit(X, y, sample_weight=sample_weight)

def predict(self, X):
    check_is_fitted(self, attributes=['_label_binarizer'])
    if self._label_binarizer.y_type_.startswith('multilabel'):
        decision = self.decision_function(X)
        xp, _ = get_namespace(decision)
        scores = 2.0 * xp.astype(decision > 0, decision.dtype) - 1.0
        return self._label_binarizer.inverse_transform(scores)
    return super().predict(X)

@_fit_context(prefer_skip_nested_validation=True)
def fit(self, X, y, sample_weight=None):
    X, y, sample_weight, Y = self._prepare_data(X, y, sample_weight, self.solver)
    super().fit(X, Y, sample_weight=sample_weight)
    return self

def _compute_gram(self, X, X_mean, sqrt_sw):
    center = self.fit_intercept and sparse.issparse(X)
    if not center:
        return safe_sparse_dot(X, X.T, dense_output=True)
    X_Xm = safe_sparse_dot(X, X_mean, dense_output=True)
    return safe_sparse_dot(X, X.T, dense_output=True) - X_Xm[:, None] * sqrt_sw[None, :] - sqrt_sw[:, None] * X_Xm[None, :] + X_mean @ X_mean * sqrt_sw[:, None] * sqrt_sw[None, :]

def _compute_covariance(self, X, X_mean, sqrt_sw):
    center = self.fit_intercept and sparse.issparse(X)
    if not center:
        return safe_sparse_dot(X.T, X, dense_output=True)
    sw_sum = sqrt_sw @ sqrt_sw
    return safe_sparse_dot(X.T, X, dense_output=True) - sw_sum * X_mean[:, None] * X_mean[None, :]

def _sparse_multidot_diag(self, X, A, X_mean, sqrt_sw):
    xp, _ = get_namespace(X)
    XA = X @ A
    if sparse.isspmatrix(X):
        XAX = np.ravel(X.multiply(XA).sum(axis=1))
    else:
        XAX = xp.sum(XA * X, axis=1)
    center = self.fit_intercept and sparse.issparse(X)
    if not center:
        return XAX
    XA_Xm = XA @ X_mean
    A_Xm = A @ X_mean
    sw = sqrt_sw * sqrt_sw
    return XAX - 2 * sqrt_sw * XA_Xm + sw * (X_mean @ A_Xm)

def _solve_eigen_gram(self, alpha, y, sqrt_sw, eigvals, Q, QT_y, QT_sqrt_sw, XT, X_mean):
    D = 1.0 / (eigvals + alpha)
    c = Q @ self._diag_dot(D, QT_y)
    d = self._decomp_diag(D, Q)
    if self.fit_intercept:
        sw_sum = sqrt_sw @ sqrt_sw
        Ginv_sqrt_sw = Q @ self._diag_dot(D, QT_sqrt_sw)
        d -= Ginv_sqrt_sw * sqrt_sw / sw_sum
    if y.ndim == 2:
        d = d[:, None]
    XT_c = XT @ c
    if self.fit_intercept and sparse.issparse(XT):
        if y.ndim == 2:
            XT_c -= X_mean[:, None] * (sqrt_sw @ c)
        else:
            XT_c -= X_mean * (sqrt_sw @ c)
    looe = c / d
    coef = XT_c
    return (looe, coef)

def _eigen_decompose_covariance(self, X, X_mean, y, sqrt_sw):
    xp, is_array_api = get_namespace(X)
    cov = self._compute_covariance(X, X_mean, sqrt_sw)
    eigvals, V = xp.linalg.eigh(cov)
    XT_y = safe_sparse_dot(X.T, y, dense_output=True)
    XT_sqrt_sw = safe_sparse_dot(X.T, sqrt_sw, dense_output=True)
    if self.fit_intercept and sparse.issparse(X):
        if y.ndim == 2:
            XT_y -= X_mean[:, None] * (sqrt_sw @ y)
        else:
            XT_y -= X_mean * (sqrt_sw @ y)
        XT_sqrt_sw -= X_mean * (sqrt_sw @ sqrt_sw)
    return (eigvals, V, X, X_mean, XT_y, XT_sqrt_sw)

def _solve_svd_design_matrix_long(self, alpha, y, sqrt_sw, singvals, U, V, UT_y, UT_sqrt_sw):
    M = alpha / (singvals ** 2 + alpha) - 1
    alpha_c = U @ self._diag_dot(M, UT_y) + y
    alpha_d = self._decomp_diag(M, U) + 1
    if self.fit_intercept:
        sw_sum = sqrt_sw @ sqrt_sw
        alpha_Ginv_sqrt_sw = U @ self._diag_dot(M, UT_sqrt_sw) + sqrt_sw
        alpha_d -= alpha_Ginv_sqrt_sw * sqrt_sw / sw_sum
    if y.ndim == 2:
        alpha_d = alpha_d[:, None]
    looe = alpha_c / alpha_d
    coef = V @ self._diag_dot(singvals / (singvals ** 2 + alpha), UT_y)
    return (looe, coef)

def _solve_svd_design_matrix_wide(self, alpha, y, sqrt_sw, singvals, U, V, UT_y, UT_sqrt_sw):
    alpha_D = alpha / (singvals ** 2 + alpha)
    alpha_c = U @ self._diag_dot(alpha_D, UT_y)
    alpha_d = self._decomp_diag(alpha_D, U)
    if self.fit_intercept:
        sw_sum = sqrt_sw @ sqrt_sw
        alpha_Ginv_sqrt_sw = U @ self._diag_dot(alpha_D, UT_sqrt_sw)
        alpha_d -= alpha_Ginv_sqrt_sw * sqrt_sw / sw_sum
    if y.ndim == 2:
        alpha_d = alpha_d[:, None]
    looe = alpha_c / alpha_d
    coef = V @ self._diag_dot(singvals / (singvals ** 2 + alpha), UT_y)
    return (looe, coef)

def _solve_svd_design_matrix(self, alpha, y, sqrt_sw, singvals, U, V, UT_y, UT_sqrt_sw):
    n_samples = U.shape[0]
    n_features = V.shape[0]
    if n_samples <= n_features:
        return self._solve_svd_design_matrix_wide(alpha, y, sqrt_sw, singvals, U, V, UT_y, UT_sqrt_sw)
    else:
        return self._solve_svd_design_matrix_long(alpha, y, sqrt_sw, singvals, U, V, UT_y, UT_sqrt_sw)

def fit(self, X, y, sample_weight=None, score_params=None):
    xp, is_array_api, device_ = get_namespace_and_device(X)
    y, sample_weight = move_to(y, sample_weight, xp=xp, device=device_)
    if is_array_api and xp.isdtype(X.dtype, 'real floating') or getattr(getattr(X, 'dtype', None), 'kind', None) == 'f':
        original_floating_dtype = X.dtype
    else:
        original_floating_dtype = None
    dtype = _max_precision_float_dtype(xp, device=device_)
    X, y = validate_data(self, X, y, accept_sparse=['csr', 'csc', 'coo'], dtype=dtype, multi_output=True, y_numeric=True)
    assert not (self.is_clf and self.alpha_per_target)
    if sample_weight is not None:
        sample_weight = _check_sample_weight(sample_weight, X, dtype=X.dtype)
    self.alphas = np.asarray(self.alphas)
    unscaled_y = y
    X, y, X_offset, y_offset, X_scale, sqrt_sw = _preprocess_data(X, y, fit_intercept=self.fit_intercept, copy=self.copy_X, sample_weight=sample_weight, rescale_with_sw=True)
    gcv_mode = _check_gcv_mode(X, self.gcv_mode)
    n_samples, n_features = X.shape
    if gcv_mode == 'gram':
        decompose = self._eigen_decompose_gram
        solve = self._solve_eigen_gram
    elif gcv_mode == 'cov':
        decompose = self._eigen_decompose_covariance
        solve = self._solve_eigen_covariance
    elif gcv_mode == 'svd':
        decompose = self._svd_decompose_design_matrix
        solve = self._solve_svd_design_matrix
    else:
        raise ValueError(f'Unknown gcv_mode={gcv_mode!r}')
    if sqrt_sw is None:
        sqrt_sw = xp.ones(n_samples, dtype=X.dtype, device=device_)
    decomposition = decompose(X, X_offset, y, sqrt_sw)
    n_y = 1 if y.ndim == 1 else y.shape[1]
    if isinstance(self.alphas, numbers.Number) or getattr(self.alphas, 'ndim', None) == 0:
        alphas = [float(self.alphas)]
    else:
        alphas = list(map(float, self.alphas))
    n_alphas = len(alphas)
    if self.store_cv_results:
        self.cv_results_ = xp.empty((n_samples * n_y, n_alphas), dtype=X.dtype, device=device_)
    best_coef, best_score, best_alpha = (None, None, None)
    for i, alpha in enumerate(alphas):
        looe, coef = solve(float(alpha), y, sqrt_sw, *decomposition)
        if self.scoring is None:
            squared_errors = looe ** 2
            alpha_score = self._score_without_scorer(squared_errors=squared_errors)
            if self.store_cv_results:
                self.cv_results_[:, i] = _ravel(squared_errors)
        else:
            predictions = y - looe
            if sample_weight is not None:
                if predictions.ndim > 1:
                    predictions /= sqrt_sw[:, None]
                else:
                    predictions /= sqrt_sw
            predictions += y_offset
            if self.store_cv_results:
                self.cv_results_[:, i] = _ravel(predictions)
            score_params = score_params or {}
            alpha_score = self._score(predictions=predictions, y=unscaled_y, n_y=n_y, scorer=self.scoring, score_params=score_params)
        if best_score is None:
            if self.alpha_per_target and n_y > 1:
                best_coef = coef
                best_score = xp.reshape(alpha_score, shape=(-1,))
                best_alpha = xp.full(n_y, alpha, device=device_)
            else:
                best_coef = coef
                best_score = alpha_score
                best_alpha = alpha
        elif self.alpha_per_target and n_y > 1:
            to_update = alpha_score > best_score
            best_coef[:, to_update] = coef[:, to_update]
            best_score[to_update] = alpha_score[to_update]
            best_alpha[to_update] = alpha
        elif alpha_score > best_score:
            best_coef, best_score, best_alpha = (coef, alpha_score, alpha)
    self.alpha_ = best_alpha
    self.best_score_ = best_score
    self.coef_ = best_coef
    if y.ndim == 2:
        self.coef_ = self.coef_.T
    if y.ndim == 1 or y.shape[1] == 1:
        self.coef_ = _ravel(self.coef_)
    self._set_intercept(X_offset, y_offset, X_scale)
    if self.store_cv_results:
        if y.ndim == 1:
            cv_results_shape = (n_samples, n_alphas)
        else:
            cv_results_shape = (n_samples, n_y, n_alphas)
        self.cv_results_ = xp.reshape(self.cv_results_, shape=cv_results_shape)
    if original_floating_dtype:
        if type(self.intercept_) is not float:
            self.intercept_ = xp.astype(self.intercept_, original_floating_dtype, copy=False)
        self.coef_ = xp.astype(self.coef_, original_floating_dtype, copy=False)
        if self.store_cv_results:
            self.cv_results_ = xp.astype(self.cv_results_, original_floating_dtype, copy=False)
    return self

def _score_without_scorer(self, squared_errors):
    xp, _ = get_namespace(squared_errors)
    if self.alpha_per_target:
        _score = xp.mean(-squared_errors, axis=0)
    else:
        _score = xp.mean(-squared_errors)
    return _score

def _score(self, *, predictions, y, n_y, scorer, score_params):
    xp, _, device_ = get_namespace_and_device(y)
    if self.is_clf:
        identity_estimator = _IdentityClassifier(classes=xp.arange(n_y, device=device_))
        _score = scorer(identity_estimator, predictions, xp.argmax(y, axis=1), **score_params)
    else:
        identity_estimator = _IdentityRegressor()
        if self.alpha_per_target:
            _score = xp.asarray([scorer(identity_estimator, predictions[:, j], y[:, j], **score_params) for j in range(n_y)], device=device_)
        else:
            _score = scorer(identity_estimator, predictions, y, **score_params)
    return _score

def fit(self, X, y, sample_weight=None, **params):
    _raise_for_params(params, self, 'fit')
    cv = self.cv
    scorer = self._get_scorer()
    if cv is None:
        check_scalar_alpha = partial(check_scalar, target_type=numbers.Real, min_val=0.0, include_boundaries='neither')
    else:
        check_scalar_alpha = partial(check_scalar, target_type=numbers.Real, min_val=0.0, include_boundaries='left')
    if isinstance(self.alphas, (np.ndarray, list, tuple)):
        n_alphas = 1 if np.ndim(self.alphas) == 0 else len(self.alphas)
        if n_alphas != 1:
            for index, alpha in enumerate(self.alphas):
                alpha = check_scalar_alpha(alpha, f'alphas[{index}]')
        else:
            self.alphas[0] = check_scalar_alpha(self.alphas[0], 'alphas')
    alphas = np.asarray(self.alphas)
    if sample_weight is not None:
        params['sample_weight'] = sample_weight
    if cv is None:
        if _routing_enabled():
            routed_params = process_routing(self, 'fit', **params)
        else:
            sw = {'sample_weight': sample_weight} if sample_weight is not None else {}
            routed_params = _manual_routing({'scorer': {'score': sw}})
        if self.scoring is None:
            scorer = None
        estimator = _RidgeGCV(alphas, fit_intercept=self.fit_intercept, scoring=scorer, gcv_mode=self.gcv_mode, store_cv_results=self.store_cv_results, is_clf=is_classifier(self), alpha_per_target=self.alpha_per_target)
        estimator.fit(X, y, sample_weight=sample_weight, score_params=routed_params.scorer.score)
        self.alpha_ = estimator.alpha_
        self.best_score_ = estimator.best_score_
        if self.store_cv_results:
            self.cv_results_ = estimator.cv_results_
    else:
        if self.store_cv_results:
            raise ValueError('cv!=None and store_cv_results=True are incompatible')
        if self.alpha_per_target:
            raise ValueError('cv!=None and alpha_per_target=True are incompatible')
        parameters = {'alpha': alphas}
        solver = 'sparse_cg' if sparse.issparse(X) else 'auto'
        model = RidgeClassifier if is_classifier(self) else Ridge
        estimator = model(fit_intercept=self.fit_intercept, solver=solver)
        if _routing_enabled():
            estimator.set_fit_request(sample_weight=True)
        grid_search = GridSearchCV(estimator, parameters, cv=cv, scoring=scorer)
        grid_search.fit(X, y, **params)
        estimator = grid_search.best_estimator_
        self.alpha_ = grid_search.best_estimator_.alpha
        self.best_score_ = grid_search.best_score_
    self.coef_ = estimator.coef_
    self.intercept_ = estimator.intercept_
    self.n_features_in_ = estimator.n_features_in_
    if hasattr(estimator, 'feature_names_in_'):
        self.feature_names_in_ = estimator.feature_names_in_
    return self

def get_metadata_routing(self):
    router = MetadataRouter(owner=self).add_self_request(self).add(scorer=self._get_scorer(), method_mapping=MethodMapping().add(caller='fit', callee='score')).add(splitter=self.cv, method_mapping=MethodMapping().add(caller='fit', callee='split'))
    return router

def _get_scorer(self):
    if _routing_enabled() and self.scoring is None:
        return self._get_scorer_instance().set_score_request(sample_weight=True)
    return check_scoring(estimator=self, scoring=self.scoring, allow_none=True)

@_fit_context(prefer_skip_nested_validation=True)
def fit(self, X, y, sample_weight=None, **params):
    super().fit(X, y, sample_weight=sample_weight, **params)
    return self

@_fit_context(prefer_skip_nested_validation=True)
def fit(self, X, y, sample_weight=None, **params):
    X, y, sample_weight, Y = self._prepare_data(X, y, sample_weight, solver='eigen')
    target = Y if self.cv is None else y
    super().fit(X, target, sample_weight=sample_weight, **params)
    return self

def get_auto_step_size(max_squared_sum, alpha_scaled, loss, fit_intercept, n_samples=None, is_saga=False):
    if loss in ('log', 'multinomial'):
        L = 0.25 * (max_squared_sum + int(fit_intercept)) + alpha_scaled
    elif loss == 'squared':
        L = max_squared_sum + int(fit_intercept) + alpha_scaled
    else:
        raise ValueError("Unknown loss function for SAG solver, got %s instead of 'log' or 'squared'" % loss)
    if is_saga:
        mun = min(2 * n_samples * alpha_scaled, L)
        step = 1.0 / (2 * L + mun)
    else:
        step = 1.0 / L
    return step

def sag_solver(X, y, sample_weight=None, loss='log', alpha=1.0, beta=0.0, max_iter=1000, tol=0.001, verbose=0, random_state=None, check_input=True, max_squared_sum=None, warm_start_mem=None, is_saga=False):
    if warm_start_mem is None:
        warm_start_mem = {}
    if max_iter is None:
        max_iter = 1000
    if check_input:
        _dtype = [np.float64, np.float32]
        X = check_array(X, dtype=_dtype, accept_sparse='csr', order='C')
        y = check_array(y, dtype=_dtype, ensure_2d=False, order='C')
    n_samples, n_features = (X.shape[0], X.shape[1])
    alpha_scaled = float(alpha) / n_samples
    beta_scaled = float(beta) / n_samples
    n_classes = int(y.max()) + 1 if loss == 'multinomial' else 1
    sample_weight = _check_sample_weight(sample_weight, X, dtype=X.dtype)
    if 'coef' in warm_start_mem.keys():
        coef_init = warm_start_mem['coef']
    else:
        coef_init = np.zeros((n_features, n_classes), dtype=X.dtype, order='C')
    fit_intercept = coef_init.shape[0] == n_features + 1
    if fit_intercept:
        intercept_init = coef_init[-1, :]
        coef_init = coef_init[:-1, :]
    else:
        intercept_init = np.zeros(n_classes, dtype=X.dtype)
    if 'intercept_sum_gradient' in warm_start_mem.keys():
        intercept_sum_gradient = warm_start_mem['intercept_sum_gradient']
    else:
        intercept_sum_gradient = np.zeros(n_classes, dtype=X.dtype)
    if 'gradient_memory' in warm_start_mem.keys():
        gradient_memory_init = warm_start_mem['gradient_memory']
    else:
        gradient_memory_init = np.zeros((n_samples, n_classes), dtype=X.dtype, order='C')
    if 'sum_gradient' in warm_start_mem.keys():
        sum_gradient_init = warm_start_mem['sum_gradient']
    else:
        sum_gradient_init = np.zeros((n_features, n_classes), dtype=X.dtype, order='C')
    if 'seen' in warm_start_mem.keys():
        seen_init = warm_start_mem['seen']
    else:
        seen_init = np.zeros(n_samples, dtype=np.int32, order='C')
    if 'num_seen' in warm_start_mem.keys():
        num_seen_init = warm_start_mem['num_seen']
    else:
        num_seen_init = 0
    dataset, intercept_decay = make_dataset(X, y, sample_weight, random_state)
    if max_squared_sum is None:
        max_squared_sum = row_norms(X, squared=True).max()
    step_size = get_auto_step_size(max_squared_sum, alpha_scaled, loss, fit_intercept, n_samples=n_samples, is_saga=is_saga)
    if step_size * alpha_scaled == 1:
        raise ZeroDivisionError('Current sag implementation does not handle the case step_size * alpha_scaled == 1')
    sag = sag64 if X.dtype == np.float64 else sag32
    num_seen, n_iter_ = sag(dataset, coef_init, intercept_init, n_samples, n_features, n_classes, tol, max_iter, loss, step_size, alpha_scaled, beta_scaled, sum_gradient_init, gradient_memory_init, seen_init, num_seen_init, fit_intercept, intercept_sum_gradient, intercept_decay, is_saga, verbose)
    if n_iter_ == max_iter:
        warnings.warn('The max_iter was reached which means the coef_ did not converge', ConvergenceWarning)
    if fit_intercept:
        coef_init = np.vstack((coef_init, intercept_init))
    warm_start_mem = {'coef': coef_init, 'sum_gradient': sum_gradient_init, 'intercept_sum_gradient': intercept_sum_gradient, 'gradient_memory': gradient_memory_init, 'seen': seen_init, 'num_seen': num_seen}
    if loss == 'multinomial':
        coef_ = coef_init.T
    else:
        coef_ = coef_init[:, 0]
    return (coef_, n_iter_, warm_start_mem)

def _prepare_fit_binary(est, y, i, input_dtype, label_encode=True):
    y_i = np.ones(y.shape, dtype=input_dtype, order='C')
    if label_encode:
        y_i[y != est.classes_[i]] = 0.0
    else:
        y_i[y != est.classes_[i]] = -1.0
    average_intercept = 0
    average_coef = None
    if len(est.classes_) == 2:
        if not est.average:
            coef = est.coef_.ravel()
            intercept = est.intercept_[0]
        else:
            coef = est._standard_coef.ravel()
            intercept = est._standard_intercept[0]
            average_coef = est._average_coef.ravel()
            average_intercept = est._average_intercept[0]
    elif not est.average:
        coef = est.coef_[i]
        intercept = est.intercept_[i]
    else:
        coef = est._standard_coef[i]
        intercept = est._standard_intercept[i]
        average_coef = est._average_coef[i]
        average_intercept = est._average_intercept[i]
    return (y_i, coef, intercept, average_coef, average_intercept)

@abstractmethod
def fit(self, X, y):
    pass

def _more_validate_params(self, for_partial_fit=False):
    if self.early_stopping and for_partial_fit:
        raise ValueError('early_stopping should be False with partial_fit')
    if self.learning_rate == 'optimal' and self.alpha == 0:
        raise ValueError("alpha must be > 0 since learning_rate is 'optimal'. alpha is used to compute the optimal learning rate.")
    if self.learning_rate in ('pa1', 'pa2'):
        if is_classifier(self):
            if self.loss != 'hinge':
                msg = f"Learning rate '{self.learning_rate}' only works with loss 'hinge'."
                raise ValueError(msg)
        elif self.loss != 'epsilon_insensitive':
            msg = f"Learning rate '{self.learning_rate}' only works with loss 'epsilon_insensitive'."
            raise ValueError(msg)
    if self.penalty == 'elasticnet' and self.l1_ratio is None:
        raise ValueError("l1_ratio must be set when penalty is 'elasticnet'")
    self._get_penalty_type(self.penalty)
    self._get_learning_rate_type(self.learning_rate)

def _get_loss_function(self, loss):
    loss_ = self.loss_functions[loss]
    loss_class, args = (loss_[0], loss_[1:])
    if loss in ('huber', 'epsilon_insensitive', 'squared_epsilon_insensitive'):
        args = (self.epsilon,)
    return loss_class(*args)

def _allocate_parameter_mem(self, n_classes, n_features, input_dtype, coef_init=None, intercept_init=None, one_class=0):
    if n_classes > 2:
        if coef_init is not None:
            coef_init = np.asarray(coef_init, dtype=input_dtype, order='C')
            if coef_init.shape != (n_classes, n_features):
                raise ValueError('Provided ``coef_`` does not match dataset. ')
            self.coef_ = coef_init
        else:
            self.coef_ = np.zeros((n_classes, n_features), dtype=input_dtype, order='C')
        if intercept_init is not None:
            intercept_init = np.asarray(intercept_init, order='C', dtype=input_dtype)
            if intercept_init.shape != (n_classes,):
                raise ValueError('Provided intercept_init does not match dataset.')
            self.intercept_ = intercept_init
        else:
            self.intercept_ = np.zeros(n_classes, dtype=input_dtype, order='C')
    else:
        if coef_init is not None:
            coef_init = np.asarray(coef_init, dtype=input_dtype, order='C')
            coef_init = coef_init.ravel()
            if coef_init.shape != (n_features,):
                raise ValueError('Provided coef_init does not match dataset.')
            self.coef_ = coef_init
        else:
            self.coef_ = np.zeros(n_features, dtype=input_dtype, order='C')
        if intercept_init is not None:
            intercept_init = np.asarray(intercept_init, dtype=input_dtype)
            if intercept_init.shape != (1,) and intercept_init.shape != ():
                raise ValueError('Provided intercept_init does not match dataset.')
            if one_class:
                self.offset_ = intercept_init.reshape(1)
            else:
                self.intercept_ = intercept_init.reshape(1)
        elif one_class:
            self.offset_ = np.zeros(1, dtype=input_dtype, order='C')
        else:
            self.intercept_ = np.zeros(1, dtype=input_dtype, order='C')
    if self.average > 0:
        self._standard_coef = self.coef_
        self._average_coef = np.zeros(self.coef_.shape, dtype=input_dtype, order='C')
        if one_class:
            self._standard_intercept = 1 - self.offset_
        else:
            self._standard_intercept = self.intercept_
        self._average_intercept = np.zeros(self._standard_intercept.shape, dtype=input_dtype, order='C')

def _make_validation_split(self, y, sample_mask):
    n_samples = y.shape[0]
    validation_mask = np.zeros(n_samples, dtype=np.bool_)
    if not self.early_stopping:
        return validation_mask
    if is_classifier(self):
        splitter_type = StratifiedShuffleSplit
    else:
        splitter_type = ShuffleSplit
    cv = splitter_type(test_size=self.validation_fraction, random_state=self.random_state)
    idx_train, idx_val = next(cv.split(np.zeros(shape=(y.shape[0], 1)), y))
    if not np.any(sample_mask[idx_val]):
        raise ValueError('The sample weights for validation set are all zero, consider using a different random state.')
    if idx_train.shape[0] == 0 or idx_val.shape[0] == 0:
        raise ValueError('Splitting %d samples into a train set and a validation set with validation_fraction=%r led to an empty set (%d and %d samples). Please either change validation_fraction, increase number of samples, or disable early_stopping.' % (n_samples, self.validation_fraction, idx_train.shape[0], idx_val.shape[0]))
    validation_mask[idx_val] = True
    return validation_mask

def _fit_binary(self, X, y, alpha, sample_weight, learning_rate, max_iter):
    coef, intercept, n_iter_ = fit_binary(self, 1, X, y, alpha, learning_rate, max_iter, self._expanded_class_weight[1], self._expanded_class_weight[0], sample_weight, random_state=self.random_state)
    self.t_ += n_iter_ * X.shape[0]
    self.n_iter_ = n_iter_
    if self.average > 0:
        if self.average <= self.t_ - 1:
            self.coef_ = self._average_coef.reshape(1, -1)
            self.intercept_ = self._average_intercept
        else:
            self.coef_ = self._standard_coef.reshape(1, -1)
            self._standard_intercept = np.atleast_1d(intercept)
            self.intercept_ = self._standard_intercept
    else:
        self.coef_ = coef.reshape(1, -1)
        self.intercept_ = np.atleast_1d(intercept)

@_fit_context(prefer_skip_nested_validation=True)
def partial_fit(self, X, y, classes=None, sample_weight=None):
    if not hasattr(self, 'classes_'):
        self._more_validate_params(for_partial_fit=True)
        if self.class_weight == 'balanced':
            raise ValueError("class_weight '{0}' is not supported for partial_fit. In order to use 'balanced' weights, use compute_class_weight('{0}', classes=classes, y=y). In place of y you can use a large enough sample of the full training set target to properly estimate the class frequency distributions. Pass the resulting weights as the class_weight parameter.".format(self.class_weight))
    return self._partial_fit(X, y, alpha=self.alpha, loss=self.loss, learning_rate=self.learning_rate, max_iter=1, classes=classes, sample_weight=sample_weight, coef_init=None, intercept_init=None)

