    return self._fit(X, y, alpha=self.alpha, loss=self.loss, learning_rate=self.learning_rate, coef_init=coef_init, intercept_init=intercept_init, sample_weight=sample_weight)

@available_if(_check_proba)
def predict_proba(self, X):
    check_is_fitted(self)
    if self.loss == 'log_loss':
        return self._predict_proba_lr(X)
    elif self.loss == 'modified_huber':
        binary = len(self.classes_) == 2
        scores = self.decision_function(X)
        if binary:
            prob2 = np.ones((scores.shape[0], 2))
            prob = prob2[:, 1]
        else:
            prob = scores
        np.clip(scores, -1, 1, prob)
        prob += 1.0
        prob /= 2.0
        if binary:
            prob2[:, 0] -= prob
            prob = prob2
        else:
            prob_sum = prob.sum(axis=1)
            all_zero = prob_sum == 0
            if np.any(all_zero):
                prob[all_zero, :] = 1
                prob_sum[all_zero] = len(self.classes_)
            prob /= prob_sum.reshape((prob.shape[0], -1))
        return prob
    else:
        raise NotImplementedError("predict_(log_)proba only supported when loss='log_loss' or loss='modified_huber' (%r given)" % self.loss)

@available_if(_check_proba)
def predict_log_proba(self, X):
    return np.log(self.predict_proba(X))

