    if self.init == 'warn':
        warnings.warn("The default value of `init` will change from 'random' to 'classical_mds' in 1.10. To suppress this warning, provide some value of `init`.", FutureWarning)
        self._init = 'random'
    else:
        self._init = self.init
    if self.dissimilarity != 'deprecated':
        if not isinstance(self.metric, bool) and self.metric != 'euclidean':
            raise ValueError('You provided both `dissimilarity` and `metric`. Please use only `metric`.')
        else:
            warnings.warn('The `dissimilarity` parameter is deprecated and will be removed in 1.10. Use `metric` instead.', FutureWarning)
            self._metric = self.dissimilarity
    if isinstance(self.metric, bool):
        warnings.warn(f'Use metric_mds={self.metric} instead of metric={self.metric}. The support for metric={{True/False}} will be dropped in 1.10.', FutureWarning)
        if self.dissimilarity == 'deprecated':
            self._metric = 'euclidean'
        self._metric_mds = self.metric
    else:
        if self.dissimilarity == 'deprecated':
            self._metric = self.metric
        self._metric_mds = self.metric_mds
    X = validate_data(self, X)
    if X.shape[0] == X.shape[1] and self._metric != 'precomputed':
        warnings.warn("The provided input is a square matrix. Note that ``fit`` constructs a dissimilarity matrix from data and will treat rows as samples and columns as features. To use a pre-computed dissimilarity matrix, set ``metric='precomputed'``.")
    if self._metric == 'precomputed':
        self.dissimilarity_matrix_ = X
        self.dissimilarity_matrix_ = check_symmetric(self.dissimilarity_matrix_, raise_exception=True)
    else:
        self.dissimilarity_matrix_ = pairwise_distances(X, metric=self._metric, **self.metric_params if self.metric_params is not None else {})
    if init is not None:
        init_array = init
    elif self._init == 'classical_mds':
        cmds = ClassicalMDS(metric='precomputed', n_components=self.n_components)
        init_array = cmds.fit_transform(self.dissimilarity_matrix_)
    else:
        init_array = None
    self.embedding_, self.stress_, self.n_iter_ = smacof(self.dissimilarity_matrix_, metric=self._metric_mds, n_components=self.n_components, init=init_array, n_init=self.n_init, n_jobs=self.n_jobs, max_iter=self.max_iter, verbose=self.verbose, eps=self.eps, random_state=self.random_state, return_n_iter=True, normalized_stress=self.normalized_stress)
    return self.embedding_

def _graph_connected_component(graph, node_id):
    n_node = graph.shape[0]
    if sparse.issparse(graph):
        graph = graph.tocsr()
    connected_nodes = np.zeros(n_node, dtype=bool)
    nodes_to_explore = np.zeros(n_node, dtype=bool)
    nodes_to_explore[node_id] = True
    for _ in range(n_node):
        last_num_component = connected_nodes.sum()
        np.logical_or(connected_nodes, nodes_to_explore, out=connected_nodes)
        if last_num_component >= connected_nodes.sum():
            break
        indices = np.where(nodes_to_explore)[0]
        nodes_to_explore.fill(False)
        for i in indices:
            if sparse.issparse(graph):
                neighbors = graph[[i], :].toarray().ravel()
            else:
                neighbors = graph[i]
            np.logical_or(nodes_to_explore, neighbors, out=nodes_to_explore)
    return connected_nodes

def _graph_is_connected(graph):
    if sparse.issparse(graph):
        accept_large_sparse = sp_version >= parse_version('1.11.3')
        graph = check_array(graph, accept_sparse=True, accept_large_sparse=accept_large_sparse)
        n_connected_components, _ = connected_components(graph)
        return n_connected_components == 1
    else:
        return _graph_connected_component(graph, 0).sum() == graph.shape[0]

def _set_diag(laplacian, value, norm_laplacian):
    n_nodes = laplacian.shape[0]
    if not sparse.issparse(laplacian):
        if norm_laplacian:
            laplacian.flat[::n_nodes + 1] = value
    else:
        laplacian = laplacian.tocoo()
        if norm_laplacian:
            diag_idx = laplacian.row == laplacian.col
            laplacian.data[diag_idx] = value
        n_diags = np.unique(laplacian.row - laplacian.col).size
        if n_diags <= 7:
            laplacian = laplacian.todia()
        else:
            laplacian = laplacian.tocsr()
    return laplacian

