def _return_float_dtype(X, Y):
    xp, _ = get_namespace(X, Y)
    if not issparse(X) and (not isinstance(X, np.ndarray)):
        X = xp.asarray(X)
    if Y is None:
        Y_dtype = X.dtype
    elif not issparse(Y) and (not isinstance(Y, np.ndarray)):
        Y = np.asarray(Y)
        Y_dtype = Y.dtype
    else:
        Y_dtype = Y.dtype
    if X.dtype == Y_dtype == np.float32:
        dtype = np.float32
    else:
        dtype = float
    return (X, Y, dtype)

def _find_floating_dtype_allow_sparse(X, Y, xp=None):
    if any([issparse(X), issparse(Y)]) or _is_numpy_namespace(xp):
        X, Y, dtype_float = _return_float_dtype(X, Y)
    else:
        dtype_float = _find_matching_floating_dtype(X, Y, xp=xp)
    return (X, Y, dtype_float)

def check_pairwise_arrays(X, Y, *, precomputed=False, dtype='infer_float', accept_sparse='csr', ensure_all_finite=True, ensure_2d=True, copy=False):
    xp, _ = get_namespace(X, Y)
    X, Y, dtype_float = _find_floating_dtype_allow_sparse(X, Y, xp=xp)
    estimator = 'check_pairwise_arrays'
    if dtype == 'infer_float':
        dtype = dtype_float
    if Y is X or Y is None:
        X = Y = check_array(X, accept_sparse=accept_sparse, dtype=dtype, copy=copy, ensure_all_finite=ensure_all_finite, estimator=estimator, ensure_2d=ensure_2d)
    else:
        X = check_array(X, accept_sparse=accept_sparse, dtype=dtype, copy=copy, ensure_all_finite=ensure_all_finite, estimator=estimator, ensure_2d=ensure_2d)
        Y = check_array(Y, accept_sparse=accept_sparse, dtype=dtype, copy=copy, ensure_all_finite=ensure_all_finite, estimator=estimator, ensure_2d=ensure_2d)
    if precomputed:
        if X.shape[1] != Y.shape[0]:
            raise ValueError('Precomputed metric requires shape (n_queries, n_indexed). Got (%d, %d) for %d indexed.' % (X.shape[0], X.shape[1], Y.shape[0]))
    elif ensure_2d and X.shape[1] != Y.shape[1]:
        raise ValueError('Incompatible dimension for X and Y matrices: X.shape[1] == %d while Y.shape[1] == %d' % (X.shape[1], Y.shape[1]))
    return (X, Y)

def check_paired_arrays(X, Y):
    X, Y = check_pairwise_arrays(X, Y)
    if X.shape != Y.shape:
        raise ValueError('X and Y should be of same shape. They were respectively %r and %r long.' % (X.shape, Y.shape))
    return (X, Y)

@validate_params({'X': ['array-like', 'sparse matrix'], 'Y': ['array-like', 'sparse matrix', None], 'Y_norm_squared': ['array-like', None], 'squared': ['boolean'], 'X_norm_squared': ['array-like', None]}, prefer_skip_nested_validation=True)
def euclidean_distances(X, Y=None, *, Y_norm_squared=None, squared=False, X_norm_squared=None):
    xp, _ = get_namespace(X, Y)
    X, Y = check_pairwise_arrays(X, Y)
    if X_norm_squared is not None:
        X_norm_squared = check_array(X_norm_squared, ensure_2d=False)
        original_shape = X_norm_squared.shape
        if X_norm_squared.shape == (X.shape[0],):
            X_norm_squared = xp.reshape(X_norm_squared, (-1, 1))
        if X_norm_squared.shape == (1, X.shape[0]):
            X_norm_squared = X_norm_squared.T
        if X_norm_squared.shape != (X.shape[0], 1):
            raise ValueError(f'Incompatible dimensions for X of shape {X.shape} and X_norm_squared of shape {original_shape}.')
    if Y_norm_squared is not None:
        Y_norm_squared = check_array(Y_norm_squared, ensure_2d=False)
        original_shape = Y_norm_squared.shape
        if Y_norm_squared.shape == (Y.shape[0],):
            Y_norm_squared = xp.reshape(Y_norm_squared, (1, -1))
        if Y_norm_squared.shape == (Y.shape[0], 1):
            Y_norm_squared = Y_norm_squared.T
        if Y_norm_squared.shape != (1, Y.shape[0]):
            raise ValueError(f'Incompatible dimensions for Y of shape {Y.shape} and Y_norm_squared of shape {original_shape}.')
    return _euclidean_distances(X, Y, X_norm_squared, Y_norm_squared, squared)

def _euclidean_distances(X, Y, X_norm_squared=None, Y_norm_squared=None, squared=False):
    xp, _, device_ = get_namespace_and_device(X, Y)
    if X_norm_squared is not None and X_norm_squared.dtype != xp.float32:
        XX = xp.reshape(X_norm_squared, (-1, 1))
    elif X.dtype != xp.float32:
        XX = row_norms(X, squared=True)[:, None]
    else:
        XX = None
    if Y is X:
        YY = None if XX is None else XX.T
    elif Y_norm_squared is not None and Y_norm_squared.dtype != xp.float32:
        YY = xp.reshape(Y_norm_squared, (1, -1))
    elif Y.dtype != xp.float32:
        YY = row_norms(Y, squared=True)[None, :]
    else:
        YY = None
    if X.dtype == xp.float32 or Y.dtype == xp.float32:
        distances = _euclidean_distances_upcast(X, XX, Y, YY)
    else:
        distances = -2 * safe_sparse_dot(X, Y.T, dense_output=True)
        distances += XX
        distances += YY
    xp_zero = xp.asarray(0, device=device_, dtype=distances.dtype)
    distances = _modify_in_place_if_numpy(xp, xp.maximum, distances, xp_zero, out=distances)
    if X is Y:
        _fill_diagonal(distances, 0, xp=xp)
    if squared:
        return distances
    distances = _modify_in_place_if_numpy(xp, xp.sqrt, distances, out=distances)
    return distances

@validate_params({'X': ['array-like', 'sparse matrix'], 'Y': ['array-like', 'sparse matrix'], 'axis': [Options(Integral, {0, 1})], 'metric': [StrOptions(set(_VALID_METRICS).union(ArgKmin.valid_metrics())), callable], 'metric_kwargs': [dict, None]}, prefer_skip_nested_validation=False)
def pairwise_distances_argmin_min(X, Y, *, axis=1, metric='euclidean', metric_kwargs=None):
    ensure_all_finite = 'allow-nan' if metric == 'nan_euclidean' else True
    X, Y = check_pairwise_arrays(X, Y, ensure_all_finite=ensure_all_finite)
    if axis == 0:
        X, Y = (Y, X)
    if metric_kwargs is None:
        metric_kwargs = {}
    if ArgKmin.is_usable_for(X, Y, metric):
        if metric_kwargs.get('squared', False) and metric == 'euclidean':
            metric = 'sqeuclidean'
            metric_kwargs = {}
        values, indices = ArgKmin.compute(X=X, Y=Y, k=1, metric=metric, metric_kwargs=metric_kwargs, strategy='auto', return_distance=True)
        values = values.flatten()
        indices = indices.flatten()
    else:
        with config_context(assume_finite=True):
            indices, values = zip(*pairwise_distances_chunked(X, Y, reduce_func=_argmin_min_reduce, metric=metric, **metric_kwargs))
        indices = np.concatenate(indices)
        values = np.concatenate(values)
    return (indices, values)

@validate_params({'X': ['array-like', 'sparse matrix'], 'Y': ['array-like', 'sparse matrix'], 'axis': [Options(Integral, {0, 1})], 'metric': [StrOptions(set(_VALID_METRICS).union(ArgKmin.valid_metrics())), callable], 'metric_kwargs': [dict, None]}, prefer_skip_nested_validation=False)
def pairwise_distances_argmin(X, Y, *, axis=1, metric='euclidean', metric_kwargs=None):
    ensure_all_finite = 'allow-nan' if metric == 'nan_euclidean' else True
    X, Y = check_pairwise_arrays(X, Y, ensure_all_finite=ensure_all_finite)
    xp, _ = get_namespace(X, Y)
    if axis == 0:
        X, Y = (Y, X)
    if metric_kwargs is None:
        metric_kwargs = {}
    if ArgKmin.is_usable_for(X, Y, metric) and _is_numpy_namespace(xp):
        if metric_kwargs.get('squared', False) and metric == 'euclidean':
            metric = 'sqeuclidean'
            metric_kwargs = {}
        indices = ArgKmin.compute(X=X, Y=Y, k=1, metric=metric, metric_kwargs=metric_kwargs, strategy='auto', return_distance=False)
        indices = indices.flatten()
    else:
        with config_context(assume_finite=True):
            indices = xp.concat(list(pairwise_distances_chunked(X, Y, reduce_func=_argmin_reduce, metric=metric, **metric_kwargs)), axis=0)
    return indices

@validate_params({'X': ['array-like', 'sparse matrix'], 'Y': ['array-like', 'sparse matrix', None]}, prefer_skip_nested_validation=True)
def haversine_distances(X, Y=None):
    from sklearn.metrics import DistanceMetric
    return DistanceMetric.get_metric('haversine').pairwise(X, Y)

@validate_params({'X': ['array-like', 'sparse matrix'], 'Y': ['array-like', 'sparse matrix', None]}, prefer_skip_nested_validation=True)
def cosine_distances(X, Y=None):
    xp, _ = get_namespace(X, Y)
    S = cosine_similarity(X, Y)
    S *= -1
    S += 1
    S = xp.clip(S, 0.0, 2.0)
    if X is Y or Y is None:
        _fill_diagonal(S, 0.0, xp)
    return S

@validate_params({'X': ['array-like', 'sparse matrix'], 'Y': ['array-like', 'sparse matrix']}, prefer_skip_nested_validation=True)
def paired_euclidean_distances(X, Y):
    X, Y = check_paired_arrays(X, Y)
    return row_norms(X - Y)

@validate_params({'X': ['array-like', 'sparse matrix'], 'Y': ['array-like', 'sparse matrix']}, prefer_skip_nested_validation=True)
def paired_manhattan_distances(X, Y):
    X, Y = check_paired_arrays(X, Y)
    xp, _ = get_namespace(X, Y)
    diff = X - Y
    if issparse(diff):
        diff.data = np.abs(diff.data)
        return np.squeeze(np.array(diff.sum(axis=1)))
    else:
        return xp.sum(xp.abs(diff), axis=-1)

@validate_params({'X': ['array-like', 'sparse matrix'], 'Y': ['array-like', 'sparse matrix']}, prefer_skip_nested_validation=True)
def paired_cosine_distances(X, Y):
    X, Y = check_paired_arrays(X, Y)
    return 0.5 * row_norms(normalize(X) - normalize(Y), squared=True)

@validate_params({'X': ['array-like'], 'Y': ['array-like'], 'metric': [StrOptions(set(PAIRED_DISTANCES)), callable]}, prefer_skip_nested_validation=True)
def paired_distances(X, Y, *, metric='euclidean', **kwds):
    if metric in PAIRED_DISTANCES:
        func = PAIRED_DISTANCES[metric]
        return func(X, Y)
    elif callable(metric):
        X, Y = check_paired_arrays(X, Y)
        distances = np.zeros(len(X))
        for i in range(len(X)):
            distances[i] = metric(X[i], Y[i])
        return distances

@validate_params({'X': ['array-like', 'sparse matrix'], 'Y': ['array-like', 'sparse matrix', None], 'dense_output': ['boolean']}, prefer_skip_nested_validation=True)
def linear_kernel(X, Y=None, dense_output=True):
    X, Y = check_pairwise_arrays(X, Y)
    return safe_sparse_dot(X, Y.T, dense_output=dense_output)

@validate_params({'X': ['array-like', 'sparse matrix'], 'Y': ['array-like', 'sparse matrix', None], 'degree': [Interval(Real, 1, None, closed='left')], 'gamma': [Interval(Real, 0, None, closed='left'), None, Hidden(np.ndarray)], 'coef0': [Interval(Real, None, None, closed='neither')]}, prefer_skip_nested_validation=True)
def polynomial_kernel(X, Y=None, degree=3, gamma=None, coef0=1):
    X, Y = check_pairwise_arrays(X, Y)
    if gamma is None:
        gamma = 1.0 / X.shape[1]
    K = safe_sparse_dot(X, Y.T, dense_output=True)
    K *= gamma
    K += coef0
    K **= degree
    return K

@validate_params({'X': ['array-like', 'sparse matrix'], 'Y': ['array-like', 'sparse matrix', None], 'gamma': [Interval(Real, 0, None, closed='left'), None, Hidden(np.ndarray)]}, prefer_skip_nested_validation=True)
def rbf_kernel(X, Y=None, gamma=None):
    xp, _ = get_namespace(X, Y)
    X, Y = check_pairwise_arrays(X, Y)
    if gamma is None:
        gamma = 1.0 / X.shape[1]
    K = euclidean_distances(X, Y, squared=True)
    K *= -gamma
    K = _modify_in_place_if_numpy(xp, xp.exp, K, out=K)
    return K

@validate_params({'X': ['array-like', 'sparse matrix'], 'Y': ['array-like', 'sparse matrix', None], 'gamma': [Interval(Real, 0, None, closed='neither'), Hidden(np.ndarray), None]}, prefer_skip_nested_validation=True)
def laplacian_kernel(X, Y=None, gamma=None):
    X, Y = check_pairwise_arrays(X, Y)
    if gamma is None:
        gamma = 1.0 / X.shape[1]
    K = -gamma * manhattan_distances(X, Y)
    xp, _ = get_namespace(X, Y)
    if _is_numpy_namespace(xp):
        np.exp(K, K)
    else:
        K = xp.exp(K)
    return K

@validate_params({'X': ['array-like', 'sparse matrix'], 'Y': ['array-like', 'sparse matrix', None], 'dense_output': ['boolean']}, prefer_skip_nested_validation=True)
def cosine_similarity(X, Y=None, dense_output=True):
    X, Y = check_pairwise_arrays(X, Y)
    X_normalized = normalize(X, copy=True)
    if X is Y:
        Y_normalized = X_normalized
    else:
        Y_normalized = normalize(Y, copy=True)
    K = safe_sparse_dot(X_normalized, Y_normalized.T, dense_output=dense_output)
    return _align_api_if_sparse(K)

@validate_params({'X': ['array-like'], 'Y': ['array-like', None]}, prefer_skip_nested_validation=True)
def additive_chi2_kernel(X, Y=None):
    xp, _, device_ = get_namespace_and_device(X, Y)
    X, Y = check_pairwise_arrays(X, Y, accept_sparse=False)
    if xp.any(X < 0):
        raise ValueError('X contains negative values.')
    if Y is not X and xp.any(Y < 0):
        raise ValueError('Y contains negative values.')
    if _is_numpy_namespace(xp):
        result = np.zeros((X.shape[0], Y.shape[0]), dtype=X.dtype)
        _chi2_kernel_fast(X, Y, result)
        return result
    else:
        dtype = _find_matching_floating_dtype(X, Y, xp=xp)
        xb = X[:, None, :]
        yb = Y[None, :, :]
        nom = -(xb - yb) ** 2
        denom = xb + yb
        nom = xp.where(denom == 0, xp.asarray(0, dtype=dtype, device=device_), nom)
        denom = xp.where(denom == 0, xp.asarray(1, dtype=dtype, device=device_), denom)
        return xp.sum(nom / denom, axis=2)

@validate_params({'X': ['array-like'], 'Y': ['array-like', None], 'gamma': [Interval(Real, 0, None, closed='neither'), Hidden(np.ndarray)]}, prefer_skip_nested_validation=True)
def chi2_kernel(X, Y=None, gamma=1.0):
    xp, _ = get_namespace(X, Y)
    K = additive_chi2_kernel(X, Y)
    K *= gamma
    if _is_numpy_namespace(xp):
        return np.exp(K, out=K)
    return xp.exp(K)

def _parallel_pairwise(X, Y, func, n_jobs, **kwds):
    xp, _, device = get_namespace_and_device(X, Y)
    X, Y, dtype_float = _find_floating_dtype_allow_sparse(X, Y, xp=xp)
    if Y is None:
        Y = X
    if effective_n_jobs(n_jobs) == 1:
        return func(X, Y, **kwds)
    fd = delayed(_transposed_dist_wrapper)
    ret = xp.empty((X.shape[0], Y.shape[0]), device=device, dtype=dtype_float).T
    Parallel(backend='threading', n_jobs=n_jobs)((fd(func, ret, s, X, Y[s, ...], **{k: v[s] if k == 'Y_norm_squared' else v for k, v in kwds.items()}) for s in gen_even_slices(_num_samples(Y), effective_n_jobs(n_jobs))))
    if (X is Y or Y is None) and func is euclidean_distances:
        _fill_diagonal(ret, 0, xp=xp)
    return ret.T

def _pairwise_callable(X, Y, metric, ensure_all_finite=True, **kwds):
    xp, _, device = get_namespace_and_device(X)
    X, Y = check_pairwise_arrays(X, Y, dtype=None, ensure_all_finite=ensure_all_finite, ensure_2d=False)
    _, _, dtype_float = _find_floating_dtype_allow_sparse(X, Y, xp=xp)

    def _get_slice(array, index):
        if issparse(array):
            return array[[index], :]
        if array.ndim == 1:
            return array[index]
        else:
            return array[index, ...]
    if X is Y:
        out = xp.zeros((X.shape[0], Y.shape[0]), dtype=dtype_float, device=device)
        iterator = itertools.combinations(range(X.shape[0]), 2)
        for i, j in iterator:
            x = _get_slice(X, i)
            y = _get_slice(Y, j)
            out[i, j] = metric(x, y, **kwds)
        out = out + out.T
        for i in range(X.shape[0]):
            x = _get_slice(X, i)
            out[i, i] = metric(x, x, **kwds)
    else:
        out = xp.empty((X.shape[0], Y.shape[0]), dtype=dtype_float, device=device)
        iterator = itertools.product(range(X.shape[0]), range(Y.shape[0]))
        for i, j in iterator:
            x = _get_slice(X, i)
            y = _get_slice(Y, j)
            out[i, j] = metric(x, y, **kwds)
    return out

def _check_chunk_size(reduced, chunk_size):
    if reduced is None:
        return
    is_tuple = isinstance(reduced, tuple)
    if not is_tuple:
        reduced = (reduced,)
    if any((isinstance(r, tuple) or not hasattr(r, '__iter__') for r in reduced)):
        raise TypeError('reduce_func returned %r. Expected sequence(s) of length %d.' % (reduced if is_tuple else reduced[0], chunk_size))
    if any((_num_samples(r) != chunk_size for r in reduced)):
        actual_size = tuple((_num_samples(r) for r in reduced))
        raise ValueError('reduce_func returned object of length %s. Expected same length as input: %d.' % (actual_size if is_tuple else actual_size[0], chunk_size))

def _precompute_metric_params(X, Y, metric=None, **kwds):
    if metric == 'seuclidean' and 'V' not in kwds:
        if X is Y:
            V = np.var(X, axis=0, ddof=1)
        else:
            raise ValueError("The 'V' parameter is required for the seuclidean metric when Y is passed.")
        return {'V': V}
    if metric == 'mahalanobis' and 'VI' not in kwds:
        if X is Y:
            VI = np.linalg.inv(np.cov(X.T)).T
        else:
            raise ValueError("The 'VI' parameter is required for the mahalanobis metric when Y is passed.")
        return {'VI': VI}
    return {}

@validate_params({'X': ['array-like', 'sparse matrix'], 'Y': ['array-like', 'sparse matrix', None], 'reduce_func': [callable, None], 'metric': [StrOptions({'precomputed'}.union(_VALID_METRICS)), callable], 'n_jobs': [Integral, None], 'working_memory': [Interval(Real, 0, None, closed='left'), None]}, prefer_skip_nested_validation=False)
def pairwise_distances_chunked(X, Y=None, *, reduce_func=None, metric='euclidean', n_jobs=None, working_memory=None, **kwds):
    n_samples_X = _num_samples(X)
    if metric == 'precomputed':
        slices = (slice(0, n_samples_X),)
    else:
        if Y is None:
            Y = X
        chunk_n_rows = get_chunk_n_rows(row_bytes=8 * _num_samples(Y), max_n_rows=n_samples_X, working_memory=working_memory)
        slices = gen_batches(n_samples_X, chunk_n_rows)
    params = _precompute_metric_params(X, Y, metric=metric, **kwds)
    kwds.update(**params)
    for sl in slices:
        if sl.start == 0 and sl.stop == n_samples_X:
            X_chunk = X
        else:
            X_chunk = X[sl]
        D_chunk = pairwise_distances(X_chunk, Y, metric=metric, n_jobs=n_jobs, **kwds)
        if (X is Y or Y is None) and PAIRWISE_DISTANCE_FUNCTIONS.get(metric, None) is euclidean_distances:
            D_chunk.flat[sl.start::_num_samples(X) + 1] = 0
        if reduce_func is not None:
            chunk_size = D_chunk.shape[0]
            D_chunk = reduce_func(D_chunk, sl.start)
            _check_chunk_size(D_chunk, chunk_size)
        yield D_chunk

@validate_params({'X': ['array-like', 'sparse matrix'], 'Y': ['array-like', 'sparse matrix', None], 'metric': [StrOptions(set(_VALID_METRICS) | {'precomputed'}), callable], 'n_jobs': [Integral, None], 'ensure_all_finite': ['boolean', StrOptions({'allow-nan'})]}, prefer_skip_nested_validation=True)
def pairwise_distances(X, Y=None, metric='euclidean', *, n_jobs=None, ensure_all_finite=True, **kwds):
    if metric == 'precomputed':
        X, _ = check_pairwise_arrays(X, Y, precomputed=True, ensure_all_finite=ensure_all_finite)
        whom = '`pairwise_distances`. Precomputed distance  need to have non-negative values.'
        check_non_negative(X, whom=whom)
        return X
    elif metric in PAIRWISE_DISTANCE_FUNCTIONS:
        func = PAIRWISE_DISTANCE_FUNCTIONS[metric]
    elif callable(metric):
        func = partial(_pairwise_callable, metric=metric, ensure_all_finite=ensure_all_finite, **kwds)
    else:
        if issparse(X) or issparse(Y):
            raise TypeError('scipy distance metrics do not support sparse matrices.')
        dtype = bool if metric in PAIRWISE_BOOLEAN_FUNCTIONS else 'infer_float'
        if dtype is bool and (X.dtype != bool or (Y is not None and Y.dtype != bool)):
            msg = 'Data was converted to boolean for metric %s' % metric
            warnings.warn(msg, DataConversionWarning)
        X, Y = check_pairwise_arrays(X, Y, dtype=dtype, ensure_all_finite=ensure_all_finite)
        params = _precompute_metric_params(X, Y, metric=metric, **kwds)
        kwds.update(**params)
        if effective_n_jobs(n_jobs) == 1 and X is Y:
            return distance.squareform(distance.pdist(X, metric=metric, **kwds))
        func = partial(distance.cdist, metric=metric, **kwds)
    return _parallel_pairwise(X, Y, func, n_jobs, **kwds)

@validate_params({'X': ['array-like', 'sparse matrix'], 'Y': ['array-like', 'sparse matrix', None], 'metric': [StrOptions(set(PAIRWISE_KERNEL_FUNCTIONS) | {'precomputed'}), callable], 'filter_params': ['boolean'], 'n_jobs': [Integral, None]}, prefer_skip_nested_validation=True)
def pairwise_kernels(X, Y=None, metric='linear', *, filter_params=False, n_jobs=None, **kwds):
    from sklearn.gaussian_process.kernels import Kernel as GPKernel
    if metric == 'precomputed':
        X, _ = check_pairwise_arrays(X, Y, precomputed=True)
        return X
    elif isinstance(metric, GPKernel):
        func = metric.__call__
    elif metric in PAIRWISE_KERNEL_FUNCTIONS:
        if filter_params:
            kwds = {k: kwds[k] for k in kwds if k in KERNEL_PARAMS[metric]}
        func = PAIRWISE_KERNEL_FUNCTIONS[metric]
    elif callable(metric):
        func = partial(_pairwise_callable, metric=metric, **kwds)
    return _parallel_pairwise(X, Y, func, n_jobs, **kwds)

def _average_binary_score(binary_metric, y_true, y_score, average, sample_weight=None):
    xp, _, _device = get_namespace_and_device(y_score, sample_weight)
    average_options = (None, 'micro', 'macro', 'weighted', 'samples')
    if average not in average_options:
        raise ValueError('average has to be one of {0}'.format(average_options))
    y_type = type_of_target(y_true)
    if y_type not in ('binary', 'multilabel-indicator'):
        raise ValueError('{0} format is not supported'.format(y_type))
    if y_type == 'binary':
        return binary_metric(y_true, y_score, sample_weight=sample_weight)
    check_consistent_length(y_true, y_score, sample_weight)
    y_true = check_array(y_true)
    y_score = check_array(y_score)
    not_average_axis = 1
    score_weight = sample_weight
    average_weight = None
    if average == 'micro':
        if score_weight is not None:
            score_weight = xp.repeat(score_weight, y_true.shape[1])
        y_true = _ravel(y_true)
        y_score = _ravel(y_score)
    elif average == 'weighted':
        if score_weight is not None:
            y_true = xp.asarray(y_true, dtype=score_weight.dtype)
            average_weight = xp.sum(xp.multiply(y_true, xp.reshape(score_weight, (-1, 1))), axis=0)
        else:
            average_weight = xp.sum(y_true, axis=0)
        if xpx.isclose(xp.sum(average_weight), xp.asarray(0, dtype=average_weight.dtype, device=_device)):
            return 0
    elif average == 'samples':
        average_weight = score_weight
        score_weight = None
        not_average_axis = 0
    if y_true.ndim == 1:
        y_true = xp.reshape(y_true, (-1, 1))
    if y_score.ndim == 1:
        y_score = xp.reshape(y_score, (-1, 1))
    n_classes = y_score.shape[not_average_axis]
    score = xp.zeros((n_classes,), device=_device)
    for c in range(n_classes):
        y_true_c = _ravel(xp.take(y_true, xp.asarray([c], device=_device), axis=not_average_axis))
        y_score_c = _ravel(xp.take(y_score, xp.asarray([c], device=_device), axis=not_average_axis))
        score[c] = binary_metric(y_true_c, y_score_c, sample_weight=score_weight)
    if average is not None:
        if average_weight is not None:
            score[average_weight == 0] = 0
        return float(_average(score, weights=average_weight, xp=xp))
    else:
        return score

def _check_targets(y_true, y_pred, sample_weight=None):
    xp, _ = get_namespace(y_true, y_pred, sample_weight)
    check_consistent_length(y_true, y_pred, sample_weight)
    type_true = type_of_target(y_true, input_name='y_true')
    type_pred = type_of_target(y_pred, input_name='y_pred')
    for array in [y_true, y_pred]:
        if _num_samples(array) < 1:
            raise ValueError('Found empty input array (e.g., `y_true` or `y_pred`) while a minimum of 1 sample is required.')
    if sample_weight is not None:
        sample_weight = _check_sample_weight(sample_weight, y_true, force_float_dtype=False)
    y_type = {type_true, type_pred}
    if y_type == {'binary', 'multiclass'}:
        y_type = {'multiclass'}
    if len(y_type) > 1:
        raise ValueError("Classification metrics can't handle a mix of {0} and {1} targets".format(type_true, type_pred))
    y_type = y_type.pop()
    if y_type not in ['binary', 'multiclass', 'multilabel-indicator']:
        raise ValueError('{0} is not supported'.format(y_type))
    if y_type in ['binary', 'multiclass']:
        try:
            y_true = column_or_1d(y_true, input_name='y_true')
            y_pred = column_or_1d(y_pred, input_name='y_pred')
        except TypeError as e:
            if 'Sparse data was passed' in str(e):
                raise TypeError('Sparse input is only supported when targets are of multilabel type') from e
            else:
                raise
    unique_labels_ = unique_labels(y_true, y_pred, ys_types={y_type})
    if y_type == 'binary':
        if unique_labels_.shape[0] > 2:
            y_type = 'multiclass'
    xp, _ = get_namespace(y_true, y_pred)
    if y_type.startswith('multilabel'):
        if _is_numpy_namespace(xp):
            y_true = _align_api_if_sparse(csr_array(y_true))
            y_pred = _align_api_if_sparse(csr_array(y_pred))
        y_type = 'multilabel-indicator'
    return (y_type, unique_labels_, y_true, y_pred, sample_weight)

def _one_hot_encoding_multiclass_target(y_true, labels, target_xp, target_device):
    xp, _ = get_namespace(y_true)
    lb = LabelBinarizer()
    if labels is not None:
        lb = lb.fit(labels)
        if not xp.all(lb.classes_ == labels):
            warnings.warn(f'Labels passed were {labels}. But this function assumes labels are ordered lexicographically. Pass the ordered labels={lb.classes_.tolist()} and ensure that the columns of y_prob correspond to this ordering.', UserWarning)
        if not xp.all(_isin(y_true, labels, xp=xp)):
            undeclared_labels = set(y_true) - set(labels)
            raise ValueError(f'y_true contains values {undeclared_labels} not belonging to the passed labels {labels}.')
    else:
        lb = lb.fit(y_true)
    if lb.classes_.shape[0] == 1:
        if labels is None:
            raise ValueError('y_true contains only one label ({0}). Please provide the list of all expected class labels explicitly through the labels argument.'.format(lb.classes_[0]))
        else:
            raise ValueError('The labels array needs to contain at least two labels, got {0}.'.format(lb.classes_))
    transformed_labels = lb.transform(y_true)
    transformed_labels = move_to(transformed_labels, xp=target_xp, device=target_device)
    if transformed_labels.shape[1] == 1:
        transformed_labels = target_xp.concat((1 - transformed_labels, transformed_labels), axis=1)
    return (transformed_labels, lb.classes_)

def _validate_multiclass_probabilistic_prediction(y_true, y_prob, sample_weight, labels):
    xp, _, device_ = get_namespace_and_device(y_prob)
    if xp.max(y_prob) > 1:
        raise ValueError(f'y_prob contains values greater than 1: {xp.max(y_prob)}')
    if xp.min(y_prob) < 0:
        raise ValueError(f'y_prob contains values lower than 0: {xp.min(y_prob)}')
    check_consistent_length(y_prob, y_true, sample_weight)
    if sample_weight is not None:
        _check_sample_weight(sample_weight, y_prob, force_float_dtype=False)
    transformed_labels, lb_classes = _one_hot_encoding_multiclass_target(y_true=y_true, labels=labels, target_xp=xp, target_device=device_)
    if y_prob.ndim == 1:
        y_prob = y_prob[:, xp.newaxis]
    if y_prob.shape[1] == 1:
        y_prob = xp.concat([1 - y_prob, y_prob], axis=1)
    eps = xp.finfo(y_prob.dtype).eps
    y_prob_sum = xp.sum(y_prob, axis=1)
    if not xp.all(xpx.isclose(y_prob_sum, xp.asarray(1, dtype=y_prob_sum.dtype, device=device_), rtol=sqrt(eps))):
        warnings.warn('The y_prob values do not sum to one. Make sure to pass probabilities.', UserWarning)
    if lb_classes.shape[0] != y_prob.shape[1]:
        if labels is None:
            raise ValueError('y_true and y_prob contain different number of classes: {0} vs {1}. Please provide the true labels explicitly through the labels argument. Classes found in y_true: {2}'.format(transformed_labels.shape[1], y_prob.shape[1], lb_classes))
        else:
            raise ValueError('The number of classes in labels is different from that in y_prob. Classes found in labels: {0}'.format(lb_classes))
    return (transformed_labels, y_prob)

@validate_params({'y_true': ['array-like', 'sparse matrix'], 'y_pred': ['array-like', 'sparse matrix'], 'normalize': ['boolean'], 'sample_weight': ['array-like', None]}, prefer_skip_nested_validation=True)
def accuracy_score(y_true, y_pred, *, normalize=True, sample_weight=None):
    xp, _, device = get_namespace_and_device(y_pred)
    y_true, sample_weight = move_to(y_true, sample_weight, xp=xp, device=device)
    y_true, y_pred = attach_unique(y_true, y_pred)
    y_type, _, y_true, y_pred, sample_weight = _check_targets(y_true, y_pred, sample_weight)
    if y_type.startswith('multilabel'):
        differing_labels = _count_nonzero(y_true - y_pred, xp=xp, device=device, axis=1)
        score = xp.asarray(differing_labels == 0, device=device)
    else:
        score = y_true == y_pred
    return float(_average(score, weights=sample_weight, normalize=normalize, xp=xp))

@validate_params({'y_true': ['array-like'], 'y_pred': ['array-like'], 'labels': ['array-like', None], 'sample_weight': ['array-like', None], 'normalize': [StrOptions({'true', 'pred', 'all'}), None]}, prefer_skip_nested_validation=True)
def confusion_matrix(y_true, y_pred, *, labels=None, sample_weight=None, normalize=None):
    xp, _, device_ = get_namespace_and_device(y_true, y_pred, labels, sample_weight)
    y_true = check_array(y_true, dtype=None, ensure_2d=False, ensure_all_finite=False, ensure_min_samples=0)
    y_pred = check_array(y_pred, dtype=None, ensure_2d=False, ensure_all_finite=False, ensure_min_samples=0)
    y_true = move_to(y_true, xp=np, device='cpu')
    y_pred = move_to(y_pred, xp=np, device='cpu')
    if sample_weight is None:
        sample_weight = np.ones(y_true.shape[0], dtype=np.int64)
    else:
        sample_weight = move_to(sample_weight, xp=np, device='cpu')
    if len(sample_weight) > 0:
        y_type, unique_labels, y_true, y_pred, sample_weight = _check_targets(y_true, y_pred, sample_weight)
    else:
        y_type, unique_labels, y_true, y_pred, _ = _check_targets(y_true, y_pred)
    y_true, y_pred = attach_unique(y_true, y_pred)
    if y_type not in ('binary', 'multiclass'):
        raise ValueError('%s is not supported' % y_type)
    if labels is None:
        labels = unique_labels
    else:
        labels = move_to(labels, xp=np, device='cpu')
        n_labels = labels.size
        if n_labels == 0:
            raise ValueError("'labels' should contain at least one label.")
        elif y_true.size == 0:
            return np.zeros((n_labels, n_labels), dtype=int)
        elif len(np.intersect1d(y_true, labels)) == 0:
            raise ValueError('At least one label specified must be in y_true')
    n_labels = labels.size
    need_index_conversion = not (labels.dtype.kind in {'i', 'u', 'b'} and np.all(labels == np.arange(n_labels)) and (y_true.min() >= 0) and (y_pred.min() >= 0))
    if need_index_conversion:
        label_to_ind = {label: index for index, label in enumerate(labels)}
        y_pred = np.array([label_to_ind.get(label, n_labels + 1) for label in y_pred])
        y_true = np.array([label_to_ind.get(label, n_labels + 1) for label in y_true])
    ind = np.logical_and(y_pred < n_labels, y_true < n_labels)
    if not np.all(ind):
        y_pred = y_pred[ind]
        y_true = y_true[ind]
        sample_weight = sample_weight[ind]
    if sample_weight.dtype.kind in {'i', 'u', 'b'}:
        dtype = np.int64
    else:
        dtype = np.float32 if str(device_).startswith('mps') else np.float64
    cm = coo_array((sample_weight, (y_true, y_pred)), shape=(n_labels, n_labels), dtype=dtype).toarray()
    with np.errstate(all='ignore'):
        if normalize == 'true':
            cm = cm / cm.sum(axis=1, keepdims=True)
        elif normalize == 'pred':
            cm = cm / cm.sum(axis=0, keepdims=True)
        elif normalize == 'all':
            cm = cm / cm.sum()
        cm = xpx.nan_to_num(cm)
    if cm.shape == (1, 1):
        warnings.warn("A single label was found in 'y_true' and 'y_pred'. For the confusion matrix to have the correct shape, use the 'labels' parameter to pass all known labels.", UserWarning)
    return xp.asarray(cm, device=device_)

@validate_params({'y_true': ['array-like', 'sparse matrix'], 'y_pred': ['array-like', 'sparse matrix'], 'sample_weight': ['array-like', None], 'labels': ['array-like', None], 'samplewise': ['boolean']}, prefer_skip_nested_validation=True)
def multilabel_confusion_matrix(y_true, y_pred, *, sample_weight=None, labels=None, samplewise=False):
    y_true, y_pred = attach_unique(y_true, y_pred)
    xp, _, device_ = get_namespace_and_device(y_pred)
    y_true, sample_weight = move_to(y_true, sample_weight, xp=xp, device=device_)
    y_type, present_labels, y_true, y_pred, sample_weight = _check_targets(y_true, y_pred, sample_weight)
    if y_type not in ('binary', 'multiclass', 'multilabel-indicator'):
        raise ValueError('%s is not supported' % y_type)
    if labels is None:
        labels = present_labels
        n_labels = None
    else:
        labels = xp.asarray(labels, device=device_)
        n_labels = labels.shape[0]
        labels = xp.concat([labels, xpx.setdiff1d(present_labels, labels, assume_unique=True, xp=xp)], axis=-1)
    if y_true.ndim == 1:
        if samplewise:
            raise ValueError('Samplewise metrics are not available outside of multilabel classification.')
        le = LabelEncoder()
        le.fit(labels)
        y_true = le.transform(y_true)
        y_pred = le.transform(y_pred)
        sorted_labels = le.classes_
        tp = y_true == y_pred
        tp_bins = y_true[tp]
        if sample_weight is not None:
            tp_bins_weights = sample_weight[tp]
        else:
            tp_bins_weights = None
        if tp_bins.shape[0]:
            tp_sum = _bincount(tp_bins, weights=tp_bins_weights, minlength=labels.shape[0], xp=xp)
        else:
            true_sum = pred_sum = tp_sum = xp.zeros(labels.shape[0])
        if y_pred.shape[0]:
            pred_sum = _bincount(y_pred, weights=sample_weight, minlength=labels.shape[0], xp=xp)
        if y_true.shape[0]:
            true_sum = _bincount(y_true, weights=sample_weight, minlength=labels.shape[0], xp=xp)
        indices = xp.searchsorted(sorted_labels, labels[:n_labels])
        tp_sum = xp.take(tp_sum, indices, axis=0)
        true_sum = xp.take(true_sum, indices, axis=0)
        pred_sum = xp.take(pred_sum, indices, axis=0)
    else:
        sum_axis = 1 if samplewise else 0
        if labels.shape != present_labels.shape or xp.any(xp.not_equal(labels, present_labels)):
            if xp.max(labels) > xp.max(present_labels):
                raise ValueError('All labels must be in [0, n labels) for multilabel targets. Got %d > %d' % (xp.max(labels), xp.max(present_labels)))
            if xp.min(labels) < 0:
                raise ValueError('All labels must be in [0, n labels) for multilabel targets. Got %d < 0' % xp.min(labels))
        if n_labels is not None:
            y_true = y_true[:, labels[:n_labels]]
            y_pred = y_pred[:, labels[:n_labels]]
        if issparse(y_true) or issparse(y_pred):
            true_and_pred = y_true.multiply(y_pred)
        else:
            true_and_pred = xp.multiply(y_true, y_pred)
        tp_sum = _count_nonzero(true_and_pred, axis=sum_axis, sample_weight=sample_weight, xp=xp, device=device_)
        pred_sum = _count_nonzero(y_pred, axis=sum_axis, sample_weight=sample_weight, xp=xp, device=device_)
        true_sum = _count_nonzero(y_true, axis=sum_axis, sample_weight=sample_weight, xp=xp, device=device_)
    fp = pred_sum - tp_sum
    fn = true_sum - tp_sum
    tp = tp_sum
    if sample_weight is not None and samplewise:
        tp = xp.asarray(tp)
        fp = xp.asarray(fp)
        fn = xp.asarray(fn)
        tn = sample_weight * y_true.shape[1] - tp - fp - fn
    elif sample_weight is not None:
        tn = xp.sum(sample_weight) - tp - fp - fn
    elif samplewise:
        tn = y_true.shape[1] - tp - fp - fn
    else:
        tn = y_true.shape[0] - tp - fp - fn
    return xp.reshape(xp.stack([tn, fp, fn, tp]).T, (-1, 2, 2))

@validate_params({'y1': ['array-like'], 'y2': ['array-like'], 'labels': ['array-like', None], 'weights': [StrOptions({'linear', 'quadratic'}), None], 'sample_weight': ['array-like', None], 'replace_undefined_by': [Interval(Real, -1.0, 1.0, closed='both'), np.nan]}, prefer_skip_nested_validation=True)
def cohen_kappa_score(y1, y2, *, labels=None, weights=None, sample_weight=None, replace_undefined_by=np.nan):
    try:
        confusion = confusion_matrix(y1, y2, labels=labels, sample_weight=sample_weight)
    except ValueError as e:
        if 'At least one label specified must be in y_true' in str(e):
            msg = 'At least one label in `labels` must be present in `y1` (even though `cohen_kappa_score` is otherwise agnostic to the order of `y1` and `y2`).'
            raise ValueError(msg) from e
        raise
    xp, _, device_ = get_namespace_and_device(y1, y2)
    n_classes = confusion.shape[0]
    max_float_dtype = _max_precision_float_dtype(xp, device=device_)
    confusion = xp.astype(confusion, max_float_dtype, copy=False)
    sum0 = xp.sum(confusion, axis=0)
    sum1 = xp.sum(confusion, axis=1)
    numerator = xp.linalg.outer(sum0, sum1)
    denominator = xp.sum(sum0)
    msg_zero_division = f'`y2` contains no labels that are present in both `y1` and `labels`.`cohen_kappa_score` is undefined and set to the value defined by the `replace_undefined_by` param, which is set to {replace_undefined_by}.'
    if denominator == 0:
        warnings.warn(msg_zero_division, UndefinedMetricWarning, stacklevel=2)
        return replace_undefined_by
    expected = numerator / denominator
    if weights is None:
        w_mat = xp.ones([n_classes, n_classes], dtype=max_float_dtype, device=device_)
        _fill_diagonal(w_mat, 0, xp=xp)
    else:
        w_mat = xp.zeros([n_classes, n_classes], dtype=max_float_dtype, device=device_)
        w_mat += xp.arange(n_classes)
        if weights == 'linear':
            w_mat = xp.abs(w_mat - w_mat.T)
        else:
            w_mat = (w_mat - w_mat.T) ** 2
    numerator = xp.sum(w_mat * confusion)
    denominator = xp.sum(w_mat * expected)
    msg_zero_division = f'`y1`, `y2` and `labels` have only one label in common. `cohen_kappa_score` is undefined and set to the value defined by the the `replace_undefined_by` param, which is set to {replace_undefined_by}.'
    if denominator == 0:
        warnings.warn(msg_zero_division, UndefinedMetricWarning, stacklevel=2)
        return replace_undefined_by
    k = numerator / denominator
    return float(1 - k)

@validate_params({'y_true': ['array-like', 'sparse matrix'], 'y_pred': ['array-like', 'sparse matrix'], 'labels': ['array-like', None], 'pos_label': [Real, str, 'boolean', None], 'average': [StrOptions({'micro', 'macro', 'samples', 'weighted', 'binary'}), None], 'sample_weight': ['array-like', None], 'zero_division': [Options(Real, {0, 1}), StrOptions({'warn'})]}, prefer_skip_nested_validation=True)
def jaccard_score(y_true, y_pred, *, labels=None, pos_label=1, average='binary', sample_weight=None, zero_division='warn'):
    labels = _check_set_wise_labels(y_true, y_pred, average, labels, pos_label)
    samplewise = average == 'samples'
    MCM = multilabel_confusion_matrix(y_true, y_pred, sample_weight=sample_weight, labels=labels, samplewise=samplewise)
    numerator = MCM[:, 1, 1]
    denominator = MCM[:, 1, 1] + MCM[:, 0, 1] + MCM[:, 1, 0]
    xp, _, device_ = get_namespace_and_device(y_true, y_pred)
    if average == 'micro':
        numerator = xp.asarray(xp.sum(numerator, keepdims=True), device=device_)
        denominator = xp.asarray(xp.sum(denominator, keepdims=True), device=device_)
    jaccard = _prf_divide(numerator, denominator, 'jaccard', 'true or predicted', average, ('jaccard',), zero_division=zero_division)
    if average is None:
        return jaccard
    if average == 'weighted':
        weights = MCM[:, 1, 0] + MCM[:, 1, 1]
        if not xp.any(weights):
            weights = None
    elif average == 'samples' and sample_weight is not None:
        weights = sample_weight
    else:
        weights = None
    return float(_average(jaccard, weights=weights, xp=xp))

@validate_params({'y_true': ['array-like', 'sparse matrix'], 'y_pred': ['array-like', 'sparse matrix'], 'normalize': ['boolean'], 'sample_weight': ['array-like', None]}, prefer_skip_nested_validation=True)
def zero_one_loss(y_true, y_pred, *, normalize=True, sample_weight=None):
    xp, _ = get_namespace(y_true, y_pred)
    score = accuracy_score(y_true, y_pred, normalize=normalize, sample_weight=sample_weight)
    if normalize:
        return 1 - score
    else:
        if sample_weight is not None:
            n_samples = xp.sum(sample_weight)
        else:
            n_samples = _num_samples(y_true)
        return n_samples - score

@validate_params({'y_true': ['array-like', 'sparse matrix'], 'y_pred': ['array-like', 'sparse matrix'], 'labels': ['array-like', None], 'pos_label': [Real, str, 'boolean', None], 'average': [StrOptions({'micro', 'macro', 'samples', 'weighted', 'binary'}), None], 'sample_weight': ['array-like', None], 'zero_division': [Options(Real, {0.0, 1.0}), 'nan', StrOptions({'warn'})]}, prefer_skip_nested_validation=True)
def f1_score(y_true, y_pred, *, labels=None, pos_label=1, average='binary', sample_weight=None, zero_division='warn'):
    return fbeta_score(y_true, y_pred, beta=1, labels=labels, pos_label=pos_label, average=average, sample_weight=sample_weight, zero_division=zero_division)

@validate_params({'y_true': ['array-like', 'sparse matrix'], 'y_pred': ['array-like', 'sparse matrix'], 'beta': [Interval(Real, 0.0, None, closed='both')], 'labels': ['array-like', None], 'pos_label': [Real, str, 'boolean', None], 'average': [StrOptions({'micro', 'macro', 'samples', 'weighted', 'binary'}), None], 'sample_weight': ['array-like', None], 'zero_division': [Options(Real, {0.0, 1.0}), 'nan', StrOptions({'warn'})]}, prefer_skip_nested_validation=True)
def fbeta_score(y_true, y_pred, *, beta, labels=None, pos_label=1, average='binary', sample_weight=None, zero_division='warn'):
    _, _, f, _ = precision_recall_fscore_support(y_true, y_pred, beta=beta, labels=labels, pos_label=pos_label, average=average, warn_for=('f-score',), sample_weight=sample_weight, zero_division=zero_division)
    return f

def _check_set_wise_labels(y_true, y_pred, average, labels, pos_label):
    average_options = (None, 'micro', 'macro', 'weighted', 'samples')
    if average not in average_options and average != 'binary':
        raise ValueError('average has to be one of ' + str(average_options))
    y_true, y_pred = attach_unique(y_true, y_pred)
    y_type, present_labels, y_true, y_pred, _ = _check_targets(y_true, y_pred)
    if average == 'binary':
        if y_type == 'binary':
            if pos_label not in present_labels:
                if len(present_labels) >= 2:
                    raise ValueError(f'pos_label={pos_label} is not a valid label. It should be one of {present_labels}')
            labels = [pos_label]
        else:
            average_options = list(average_options)
            if y_type == 'multiclass':
                average_options.remove('samples')
            raise ValueError("Target is %s but average='binary'. Please choose another average setting, one of %r." % (y_type, average_options))
    elif pos_label not in (None, 1):
        warnings.warn("Note that pos_label (set to %r) is ignored when average != 'binary' (got %r). You may use labels=[pos_label] to specify a single positive class." % (pos_label, average), UserWarning)
    return labels

@validate_params({'y_true': ['array-like', 'sparse matrix'], 'y_pred': ['array-like', 'sparse matrix'], 'labels': ['array-like', None], 'sample_weight': ['array-like', None], 'replace_undefined_by': [Options(Real, {1.0, np.nan}), dict]}, prefer_skip_nested_validation=True)
def class_likelihood_ratios(y_true, y_pred, *, labels=None, sample_weight=None, replace_undefined_by=np.nan):
    y_true, y_pred = attach_unique(y_true, y_pred)
    y_type, _, y_true, y_pred, sample_weight = _check_targets(y_true, y_pred, sample_weight)
    if y_type != 'binary':
        raise ValueError(f'class_likelihood_ratios only supports binary classification problems, got targets of type: {y_type}')
    if replace_undefined_by == 1.0:
        replace_undefined_by = {'LR+': 1.0, 'LR-': 1.0}
    if isinstance(replace_undefined_by, dict):
        msg = f"The dictionary passed as `replace_undefined_by` needs to be in the form `{{'LR+': `value_1`, 'LR-': `value_2`}}` where the value for `LR+` ranges from `1.0` to `np.inf` or is `np.nan` and the value for `LR-` ranges from `0.0` to `1.0` or is `np.nan`; got `{replace_undefined_by}`."
        if 'LR+' in replace_undefined_by and 'LR-' in replace_undefined_by:
            try:
                desired_lr_pos = replace_undefined_by.get('LR+', None)
                check_scalar(desired_lr_pos, 'positive_likelihood_ratio', target_type=Real, min_val=1.0, include_boundaries='left')
                desired_lr_neg = replace_undefined_by.get('LR-', None)
                check_scalar(desired_lr_neg, 'negative_likelihood_ratio', target_type=Real, min_val=0.0, max_val=1.0, include_boundaries='both')
            except Exception as e:
                raise ValueError(msg) from e
        else:
            raise ValueError(msg)
    cm = confusion_matrix(y_true, y_pred, sample_weight=sample_weight, labels=labels)
    tn, fp, fn, tp = cm.ravel()
    support_pos = tp + fn
    support_neg = tn + fp
    pos_num = tp * support_neg
    pos_denom = fp * support_pos
    neg_num = fn * support_neg
    neg_denom = tn * support_pos
    if support_pos == 0:
        msg = "No samples of the positive class are present in `y_true`. `positive_likelihood_ratio` and `negative_likelihood_ratio` are both set to `np.nan`. Use the `replace_undefined_by` param to control this behavior. To suppress this warning or turn it into an error, see Python's `warnings` module and `warnings.catch_warnings()`."
        warnings.warn(msg, UndefinedMetricWarning, stacklevel=2)
        positive_likelihood_ratio = np.nan
        negative_likelihood_ratio = np.nan
    if fp == 0:
        if tp == 0:
            msg_beginning = 'No samples were predicted for the positive class and `positive_likelihood_ratio` is '
        else:
            msg_beginning = '`positive_likelihood_ratio` is ill-defined and '
        msg_end = 'set to `np.nan`. Use the `replace_undefined_by` param to '
        'control this behavior. To suppress this warning or turn it into an error, '
        "see Python's `warnings` module and `warnings.catch_warnings()`."
        warnings.warn(msg_beginning + msg_end, UndefinedMetricWarning, stacklevel=2)
        if isinstance(replace_undefined_by, float) and np.isnan(replace_undefined_by):
            positive_likelihood_ratio = replace_undefined_by
        else:
            positive_likelihood_ratio = desired_lr_pos
    else:
        positive_likelihood_ratio = pos_num / pos_denom
    if tn == 0:
        msg = "`negative_likelihood_ratio` is ill-defined and set to `np.nan`. Use the `replace_undefined_by` param to control this behavior. To suppress this warning or turn it into an error, see Python's `warnings` module and `warnings.catch_warnings()`."
        warnings.warn(msg, UndefinedMetricWarning, stacklevel=2)
        if isinstance(replace_undefined_by, float) and np.isnan(replace_undefined_by):
            negative_likelihood_ratio = replace_undefined_by
        else:
            negative_likelihood_ratio = desired_lr_neg
    else:
        negative_likelihood_ratio = neg_num / neg_denom
    return (float(positive_likelihood_ratio), float(negative_likelihood_ratio))

@validate_params({'y_true': ['array-like', 'sparse matrix'], 'y_pred': ['array-like', 'sparse matrix'], 'labels': ['array-like', None], 'pos_label': [Real, str, 'boolean', None], 'average': [StrOptions({'micro', 'macro', 'samples', 'weighted', 'binary'}), None], 'sample_weight': ['array-like', None], 'zero_division': [Options(Real, {0.0, 1.0}), 'nan', StrOptions({'warn'})]}, prefer_skip_nested_validation=True)
def precision_score(y_true, y_pred, *, labels=None, pos_label=1, average='binary', sample_weight=None, zero_division='warn'):
    p, _, _, _ = precision_recall_fscore_support(y_true, y_pred, labels=labels, pos_label=pos_label, average=average, warn_for=('precision',), sample_weight=sample_weight, zero_division=zero_division)
    return p

@validate_params({'y_true': ['array-like', 'sparse matrix'], 'y_pred': ['array-like', 'sparse matrix'], 'labels': ['array-like', None], 'pos_label': [Real, str, 'boolean', None], 'average': [StrOptions({'micro', 'macro', 'samples', 'weighted', 'binary'}), None], 'sample_weight': ['array-like', None], 'zero_division': [Options(Real, {0.0, 1.0}), 'nan', StrOptions({'warn'})]}, prefer_skip_nested_validation=True)
def recall_score(y_true, y_pred, *, labels=None, pos_label=1, average='binary', sample_weight=None, zero_division='warn'):
    _, r, _, _ = precision_recall_fscore_support(y_true, y_pred, labels=labels, pos_label=pos_label, average=average, warn_for=('recall',), sample_weight=sample_weight, zero_division=zero_division)
    return r

@validate_params({'y_true': ['array-like'], 'y_pred': ['array-like'], 'sample_weight': ['array-like', None], 'adjusted': ['boolean']}, prefer_skip_nested_validation=True)
def balanced_accuracy_score(y_true, y_pred, *, sample_weight=None, adjusted=False):
    C = confusion_matrix(y_true, y_pred, sample_weight=sample_weight)
    xp, _, device_ = get_namespace_and_device(y_pred, y_true)
    if _is_xp_namespace(xp, 'array_api_strict'):
        C = xp.astype(C, _max_precision_float_dtype(xp, device=device_), copy=False)
    context_manager = np.errstate(divide='ignore', invalid='ignore') if _is_numpy_namespace(xp) else nullcontext()
    with context_manager:
        per_class = xp.linalg.diagonal(C) / xp.sum(C, axis=1)
    if xp.any(xp.isnan(per_class)):
        warnings.warn('y_pred contains classes not in y_true')
        per_class = per_class[~xp.isnan(per_class)]
    score = xp.mean(per_class)
    if adjusted:
        n_classes = per_class.shape[0]
        chance = 1 / n_classes
        score -= chance
        score /= 1 - chance
    return float(score)

@validate_params({'y_true': ['array-like', 'sparse matrix'], 'y_pred': ['array-like', 'sparse matrix'], 'labels': ['array-like', None], 'target_names': ['array-like', None], 'sample_weight': ['array-like', None], 'digits': [Interval(Integral, 0, None, closed='left')], 'output_dict': ['boolean'], 'zero_division': [Options(Real, {0.0, 1.0}), 'nan', StrOptions({'warn'})]}, prefer_skip_nested_validation=True)
def classification_report(y_true, y_pred, *, labels=None, target_names=None, sample_weight=None, digits=2, output_dict=False, zero_division='warn'):
    y_true, y_pred = attach_unique(y_true, y_pred)
    y_type, unique_labels_, y_true, y_pred, sample_weight = _check_targets(y_true, y_pred, sample_weight)
    if labels is None:
        labels = unique_labels_
        labels_given = False
    else:
        labels = np.asarray(labels)
        labels_given = True
    micro_is_accuracy = (y_type == 'multiclass' or y_type == 'binary') and (not labels_given or set(labels) >= set(unique_labels(y_true, y_pred)))
    if target_names is not None and len(labels) != len(target_names):
        if labels_given:
            warnings.warn('labels size, {0}, does not match size of target_names, {1}'.format(len(labels), len(target_names)))
        else:
            raise ValueError('Number of classes, {0}, does not match size of target_names, {1}. Try specifying the labels parameter'.format(len(labels), len(target_names)))
    if target_names is None:
        target_names = ['%s' % l for l in labels]
    headers = ['precision', 'recall', 'f1-score', 'support']
    p, r, f1, s = precision_recall_fscore_support(y_true, y_pred, labels=labels, average=None, sample_weight=sample_weight, zero_division=zero_division)
    rows = zip(target_names, p, r, f1, s)
    if y_type.startswith('multilabel'):
        average_options = ('micro', 'macro', 'weighted', 'samples')
    else:
        average_options = ('micro', 'macro', 'weighted')
    if output_dict:
        report_dict = {label[0]: label[1:] for label in rows}
        for label, scores in report_dict.items():
            report_dict[label] = dict(zip(headers, [float(i) for i in scores]))
    else:
        longest_last_line_heading = 'weighted avg'
        name_width = max((len(cn) for cn in target_names))
        width = max(name_width, len(longest_last_line_heading), digits)
        head_fmt = '{:>{width}s} ' + ' {:>9}' * len(headers)
        report = head_fmt.format('', *headers, width=width)
        report += '\n\n'
        row_fmt = '{:>{width}s} ' + ' {:>9.{digits}f}' * 3 + ' {:>9}\n'
        for row in rows:
            report += row_fmt.format(*row, width=width, digits=digits)
        report += '\n'
    for average in average_options:
        if average.startswith('micro') and micro_is_accuracy:
            line_heading = 'accuracy'
        else:
            line_heading = average + ' avg'
        avg_p, avg_r, avg_f1, _ = precision_recall_fscore_support(y_true, y_pred, labels=labels, average=average, sample_weight=sample_weight, zero_division=zero_division)
        avg = [avg_p, avg_r, avg_f1, np.sum(s)]
        if output_dict:
            report_dict[line_heading] = dict(zip(headers, [float(i) for i in avg]))
        elif line_heading == 'accuracy':
            row_fmt_accuracy = '{:>{width}s} ' + ' {:>9.{digits}}' * 2 + ' {:>9.{digits}f}' + ' {:>9}\n'
            report += row_fmt_accuracy.format(line_heading, '', '', *avg[2:], width=width, digits=digits)
        else:
            report += row_fmt.format(line_heading, *avg, width=width, digits=digits)
    if output_dict:
        if 'accuracy' in report_dict.keys():
            report_dict['accuracy'] = report_dict['accuracy']['precision']
        return report_dict
    else:
        return report

@validate_params({'y_true': ['array-like', 'sparse matrix'], 'y_pred': ['array-like', 'sparse matrix'], 'sample_weight': ['array-like', None]}, prefer_skip_nested_validation=True)
def hamming_loss(y_true, y_pred, *, sample_weight=None):
    y_true, y_pred = attach_unique(y_true, y_pred)
    y_type, _, y_true, y_pred, sample_weight = _check_targets(y_true, y_pred, sample_weight)
    xp, _, device = get_namespace_and_device(y_true, y_pred, sample_weight)
    if sample_weight is None:
        weight_average = 1.0
    else:
        weight_average = _average(sample_weight, xp=xp)
    if y_type.startswith('multilabel'):
        n_differences = _count_nonzero(y_true - y_pred, xp=xp, device=device, sample_weight=sample_weight)
        return float(n_differences) / (y_true.shape[0] * y_true.shape[1] * weight_average)
    elif y_type in ['binary', 'multiclass']:
        return float(_average(y_true != y_pred, weights=sample_weight, normalize=True, xp=xp))
    else:
        raise ValueError('{0} is not supported'.format(y_type))

@validate_params({'y_true': ['array-like'], 'y_proba': ['array-like', Hidden(None)], 'normalize': ['boolean'], 'sample_weight': ['array-like', None], 'labels': ['array-like', None], 'y_pred': ['array-like', str]}, prefer_skip_nested_validation=True)
def log_loss(y_true, y_proba=None, *, normalize=True, sample_weight=None, labels=None, y_pred='deprecated'):
    if not (isinstance(y_pred, str) and y_pred == 'deprecated'):
        if y_proba is not None:
            raise ValueError('Cannot use both `y_pred` and `y_proba`. `y_pred` is deprecated, use `y_proba` instead.')
        else:
            warnings.warn('`y_pred` was renamed to `y_proba` in version 1.9 and will be removed in 1.11. Use `y_proba` instead.', FutureWarning)
            y_proba = y_pred
    xp, _, device_ = get_namespace_and_device(y_proba)
    y_proba = check_array(y_proba, ensure_2d=False, dtype=supported_float_dtypes(xp, device=device_))
    if sample_weight is not None:
        sample_weight = move_to(sample_weight, xp=xp, device=device_)
    transformed_labels, y_proba = _validate_multiclass_probabilistic_prediction(y_true, y_proba, sample_weight, labels)
    return _log_loss(transformed_labels, y_proba, normalize=normalize, sample_weight=sample_weight)

def _log_loss(transformed_labels, y_proba, *, normalize=True, sample_weight=None):
    xp, _, device_ = get_namespace_and_device(y_proba)
    if sample_weight is not None:
        sample_weight = move_to(sample_weight, xp=xp, device=device_)
    eps = xp.finfo(y_proba.dtype).eps
    y_proba = xp.clip(y_proba, eps, 1 - eps)
    transformed_labels = xp.astype(transformed_labels, y_proba.dtype, copy=False)
    loss = -xp.sum(_xlogy(transformed_labels, y_proba, xp=xp), axis=1)
    return float(_average(loss, weights=sample_weight, normalize=normalize))

@validate_params({'y_true': ['array-like'], 'pred_decision': ['array-like'], 'labels': ['array-like', None], 'sample_weight': ['array-like', None]}, prefer_skip_nested_validation=True)
def hinge_loss(y_true, pred_decision, *, labels=None, sample_weight=None):
    check_consistent_length(y_true, pred_decision, sample_weight)
    pred_decision = check_array(pred_decision, ensure_2d=False)
    y_true = column_or_1d(y_true)
    y_true_unique = np.unique(labels if labels is not None else y_true)
    if y_true_unique.size > 2:
        if pred_decision.ndim <= 1:
            raise ValueError(f'The shape of pred_decision cannot be 1d arraywith a multiclass target. pred_decision shape must be (n_samples, n_classes), that is ({y_true.shape[0]}, {y_true_unique.size}). Got: {pred_decision.shape}')
        if y_true_unique.size != pred_decision.shape[1]:
            if labels is None:
                raise ValueError('Please include all labels in y_true or pass labels as third argument')
            else:
                raise ValueError(f'The shape of pred_decision is not consistent with the number of classes. With a multiclass target, pred_decision shape must be (n_samples, n_classes), that is ({y_true.shape[0]}, {y_true_unique.size}). Got: {pred_decision.shape}')
        if labels is None:
            labels = y_true_unique
        le = LabelEncoder()
        le.fit(labels)
        y_true = le.transform(y_true)
        mask = np.ones_like(pred_decision, dtype=bool)
        mask[np.arange(y_true.shape[0]), y_true] = False
        margin = pred_decision[~mask]
        margin -= np.max(pred_decision[mask].reshape(y_true.shape[0], -1), axis=1)
    else:
        pred_decision = column_or_1d(pred_decision)
        pred_decision = np.ravel(pred_decision)
        lbin = LabelBinarizer(neg_label=-1)
        y_true = lbin.fit_transform(y_true)[:, 0]
        try:
            margin = y_true * pred_decision
        except TypeError:
            raise TypeError('pred_decision should be an array of floats.')
    losses = 1 - margin
    np.clip(losses, 0, None, out=losses)
    return float(np.average(losses, weights=sample_weight))

def _one_hot_encoding_binary_target(y_true, pos_label, target_xp, target_device):
    xp_y_true, _ = get_namespace(y_true)
    y_true_pos = xp_y_true.asarray(y_true == pos_label, dtype=xp_y_true.int64)
    y_true_pos = move_to(y_true_pos, xp=target_xp, device=target_device)
    return target_xp.stack((1 - y_true_pos, y_true_pos), axis=1)

def _validate_binary_probabilistic_prediction(y_true, y_prob, sample_weight, pos_label):
    y_true = column_or_1d(y_true)
    y_prob = column_or_1d(y_prob)
    assert_all_finite(y_true)
    assert_all_finite(y_prob)
    check_consistent_length(y_prob, y_true, sample_weight)
    if sample_weight is not None:
        _check_sample_weight(sample_weight, y_prob, force_float_dtype=False)
    y_type = type_of_target(y_true, input_name='y_true')
    if y_type != 'binary':
        raise ValueError(f'The type of the target inferred from y_true is {y_type} but should be binary according to the shape of y_prob.')
    xp, _, device_ = get_namespace_and_device(y_prob)
    if xp.max(y_prob) > 1:
        raise ValueError(f'y_prob contains values greater than 1: {xp.max(y_prob)}')
    if xp.min(y_prob) < 0:
        raise ValueError(f'y_prob contains values less than 0: {xp.min(y_prob)}')
    try:
        pos_label = _check_pos_label_consistency(pos_label, y_true)
    except ValueError:
        xp_y_true, _ = get_namespace(y_true)
        classes = xp_y_true.unique_values(y_true)
        if not (_is_numpy_namespace(xp_y_true) and classes.dtype.kind in 'OUS'):
            pos_label = classes[-1]
        else:
            raise
    transformed_labels = _one_hot_encoding_binary_target(y_true=y_true, pos_label=pos_label, target_xp=xp, target_device=device_)
    y_prob = xp.stack((1 - y_prob, y_prob), axis=1)
    return (transformed_labels, y_prob)

@validate_params({'y_true': ['array-like'], 'y_proba': ['array-like'], 'sample_weight': ['array-like', None], 'pos_label': [Real, str, 'boolean', None], 'labels': ['array-like', None], 'scale_by_half': ['boolean', StrOptions({'auto'})]}, prefer_skip_nested_validation=True)
def brier_score_loss(y_true, y_proba, *, sample_weight=None, pos_label=None, labels=None, scale_by_half='auto'):
    xp, _, device_ = get_namespace_and_device(y_proba)
    y_proba = check_array(y_proba, ensure_2d=False, dtype=supported_float_dtypes(xp, device=device_))
    if sample_weight is not None:
        sample_weight = move_to(sample_weight, xp=xp, device=device_)
    if y_proba.ndim == 1 or y_proba.shape[1] == 1:
        transformed_labels, y_proba = _validate_binary_probabilistic_prediction(y_true, y_proba, sample_weight, pos_label)
    else:
        transformed_labels, y_proba = _validate_multiclass_probabilistic_prediction(y_true, y_proba, sample_weight, labels)
    transformed_labels = xp.astype(transformed_labels, y_proba.dtype, copy=False)
    brier_score = _average(xp.sum((transformed_labels - y_proba) ** 2, axis=1), weights=sample_weight)
    if scale_by_half == 'auto':
        scale_by_half = y_proba.ndim == 1 or y_proba.shape[1] < 3
    if scale_by_half:
        brier_score *= 0.5
    return float(brier_score)

@validate_params({'y_true': ['array-like'], 'y_proba': ['array-like', Hidden(None)], 'sample_weight': ['array-like', None], 'labels': ['array-like', None], 'y_pred': ['array-like', str]}, prefer_skip_nested_validation=True)
def d2_log_loss_score(y_true, y_proba=None, *, sample_weight=None, labels=None, y_pred='deprecated'):
    if not (isinstance(y_pred, str) and y_pred == 'deprecated'):
        if y_proba is not None:
            raise ValueError('Cannot use both `y_pred` and `y_proba`. `y_pred` is deprecated, use `y_proba` instead.')
        else:
            warnings.warn('`y_pred` was renamed to `y_proba` in version 1.9 and will be removed in 1.11. Use `y_proba` instead.', FutureWarning)
            y_proba = y_pred
    check_consistent_length(y_proba, y_true, sample_weight)
    if _num_samples(y_proba) < 2:
        msg = 'D^2 score is not well-defined with less than two samples.'
        warnings.warn(msg, UndefinedMetricWarning)
        return float('nan')
    xp, _, device_ = get_namespace_and_device(y_proba)
    y_proba = check_array(y_proba, ensure_2d=False, dtype=supported_float_dtypes(xp, device=device_))
    if sample_weight is not None:
        sample_weight = move_to(sample_weight, xp=xp, device=device_)
    transformed_labels, y_proba = _validate_multiclass_probabilistic_prediction(y_true, y_proba, sample_weight, labels)
    xp, _ = get_namespace(y_proba, transformed_labels)
    y_proba_null = _average(transformed_labels, axis=0, weights=sample_weight)
    y_proba_null = xp.tile(y_proba_null, (y_proba.shape[0], 1))
    numerator = _log_loss(transformed_labels, y_proba, normalize=False, sample_weight=sample_weight)
    denominator = _log_loss(transformed_labels, y_proba_null, normalize=False, sample_weight=sample_weight)
    return float(1 - numerator / denominator)

@validate_params({'y_true': ['array-like'], 'y_proba': ['array-like'], 'sample_weight': ['array-like', None], 'pos_label': [Real, str, 'boolean', None], 'labels': ['array-like', None]}, prefer_skip_nested_validation=True)
def d2_brier_score(y_true, y_proba, *, sample_weight=None, pos_label=None, labels=None):
    check_consistent_length(y_proba, y_true, sample_weight)
    if _num_samples(y_proba) < 2:
        msg = 'D^2 score is not well-defined with less than two samples.'
        warnings.warn(msg, UndefinedMetricWarning)
        return float('nan')
    xp, _, device_ = get_namespace_and_device(y_proba)
    y_proba = check_array(y_proba, ensure_2d=False, dtype=supported_float_dtypes(xp, device=device_))
    if sample_weight is not None:
        sample_weight = move_to(sample_weight, xp=xp, device=device_)
    if y_proba.ndim == 1 or y_proba.shape[1] == 1:
        transformed_labels, y_proba = _validate_binary_probabilistic_prediction(y_true, y_proba, sample_weight, pos_label)
    else:
        transformed_labels, y_proba = _validate_multiclass_probabilistic_prediction(y_true, y_proba, sample_weight, labels)
    transformed_labels = xp.astype(transformed_labels, y_proba.dtype, copy=False)
    y_proba_null = _average(transformed_labels, axis=0, weights=sample_weight)
    y_proba_null = xp.tile(y_proba_null, (y_proba.shape[0], 1))
    brier_score = _average(xp.sum((transformed_labels - y_proba) ** 2, axis=1), weights=sample_weight)
    brier_score_null = _average(xp.sum((transformed_labels - y_proba_null) ** 2, axis=1), weights=sample_weight)
    return float(1 - brier_score / brier_score_null)

@validate_params({'x': ['array-like'], 'y': ['array-like']}, prefer_skip_nested_validation=True)
def auc(x, y):
    check_consistent_length(x, y)
    x = column_or_1d(x)
    y = column_or_1d(y)
    if x.shape[0] < 2:
        raise ValueError('At least 2 points are needed to compute area under curve, but x.shape = %s' % x.shape)
    direction = 1
    dx = np.diff(x)
    if np.any(dx < 0):
        if np.all(dx <= 0):
            direction = -1
        else:
            raise ValueError('x is neither increasing nor decreasing : {}.'.format(x))
    area = direction * trapezoid(y, x)
    if isinstance(area, np.memmap):
        area = area.dtype.type(area)
    return float(area)

@validate_params({'y_true': ['array-like'], 'y_score': ['array-like'], 'average': [StrOptions({'micro', 'samples', 'weighted', 'macro'}), None], 'pos_label': [Real, str, 'boolean'], 'sample_weight': ['array-like', None]}, prefer_skip_nested_validation=True)
def average_precision_score(y_true, y_score, *, average='macro', pos_label=1, sample_weight=None):
    xp, _, device = get_namespace_and_device(y_score)
    y_score = check_array(y_score, ensure_2d=False)
    sample_weight = move_to(sample_weight, xp=xp, device=device)
    if sample_weight is not None:
        sample_weight = column_or_1d(sample_weight)

    def _binary_uninterpolated_average_precision(y_true, y_score, pos_label=1, sample_weight=None, xp=xp):
        precision, recall, _ = precision_recall_curve(y_true, y_score, pos_label=pos_label, sample_weight=sample_weight)
        return float(max(0.0, -xp.sum(xp.diff(recall) * precision[:-1])))
    y_type = type_of_target(y_true, input_name='y_true')
    xp_y_true, _ = get_namespace(y_true)
    present_labels = xp_y_true.unique_values(y_true)
    if y_type == 'binary':
        if present_labels.shape[0] == 2 and pos_label not in present_labels:
            raise ValueError(f'pos_label={pos_label} is not a valid label. It should be one of {present_labels}')
    elif y_type == 'multilabel-indicator' and pos_label != 1:
        raise ValueError('Parameter pos_label is fixed to 1 for multilabel-indicator y_true. Do not set pos_label or set pos_label to 1.')
    elif y_type == 'multiclass':
        if pos_label != 1:
            raise ValueError('Parameter pos_label is fixed to 1 for multiclass y_true. Do not set pos_label or set pos_label to 1.')
        y_true = label_binarize(y_true, classes=present_labels)
        y_true = move_to(y_true, xp=xp, device=device)
        if not y_score.shape == y_true.shape:
            raise ValueError(f'`y_score` needs to be of shape `(n_samples, n_classes)`, since `y_true` contains multiple classes. Got `y_score.shape={y_score.shape}`.')
    average_precision = partial(_binary_uninterpolated_average_precision, pos_label=pos_label, xp=xp)
    return _average_binary_score(average_precision, y_true, y_score, average, sample_weight=sample_weight)

def _binary_roc_auc_score(y_true, y_score, sample_weight=None, max_fpr=None):
    if len(np.unique(y_true)) != 2:
        warnings.warn('Only one class is present in y_true. ROC AUC score is not defined in that case.', UndefinedMetricWarning)
        return np.nan
    fpr, tpr, _ = roc_curve(y_true, y_score, sample_weight=sample_weight)
    if max_fpr is None or max_fpr == 1:
        return auc(fpr, tpr)
    if max_fpr <= 0 or max_fpr > 1:
        raise ValueError('Expected max_fpr in range (0, 1], got: %r' % max_fpr)
    stop = np.searchsorted(fpr, max_fpr, 'right')
    x_interp = [fpr[stop - 1], fpr[stop]]
    y_interp = [tpr[stop - 1], tpr[stop]]
    tpr = np.append(tpr[:stop], np.interp(max_fpr, x_interp, y_interp))
    fpr = np.append(fpr[:stop], max_fpr)
    partial_auc = auc(fpr, tpr)
    min_area = 0.5 * max_fpr ** 2
    max_area = max_fpr
    return 0.5 * (1 + (partial_auc - min_area) / (max_area - min_area))

@validate_params({'y_true': ['array-like'], 'y_score': ['array-like'], 'average': [StrOptions({'micro', 'macro', 'samples', 'weighted'}), None], 'sample_weight': ['array-like', None], 'max_fpr': [Interval(Real, 0.0, 1, closed='right'), None], 'multi_class': [StrOptions({'raise', 'ovr', 'ovo'})], 'labels': ['array-like', None]}, prefer_skip_nested_validation=True)
def roc_auc_score(y_true, y_score, *, average='macro', sample_weight=None, max_fpr=None, multi_class='raise', labels=None):
    y_type = type_of_target(y_true, input_name='y_true')
    y_true = check_array(y_true, ensure_2d=False, dtype=None)
    y_score = check_array(y_score, ensure_2d=False)
    if sample_weight is not None:
        sample_weight = column_or_1d(sample_weight)
    if y_type == 'multiclass' or (y_type == 'binary' and y_score.ndim == 2 and (y_score.shape[1] > 2)):
        if max_fpr is not None and max_fpr != 1.0:
            raise ValueError("Partial AUC computation not available in multiclass setting, 'max_fpr' must be set to `None`, received `max_fpr={0}` instead".format(max_fpr))
        if multi_class == 'raise':
            raise ValueError("multi_class must be in ('ovo', 'ovr')")
        return _multiclass_roc_auc_score(y_true, y_score, labels, multi_class, average, sample_weight)
    elif y_type == 'binary':
        labels = np.unique(y_true)
        y_true = label_binarize(y_true, classes=labels)[:, 0]
        return _average_binary_score(partial(_binary_roc_auc_score, max_fpr=max_fpr), y_true, y_score, average, sample_weight=sample_weight)
    else:
        return _average_binary_score(partial(_binary_roc_auc_score, max_fpr=max_fpr), y_true, y_score, average, sample_weight=sample_weight)

def _multiclass_roc_auc_score(y_true, y_score, labels, multi_class, average, sample_weight):
    if not y_score.ndim == 2:
        raise ValueError(f'`y_score` needs to be of shape `(n_samples, n_classes)`, since `y_true` contains multiple classes. Got `y_score.shape={y_score.shape}`.')
    if not np.allclose(1, y_score.sum(axis=1)):
        raise ValueError('Target scores need to be probabilities for multiclass roc_auc, i.e. they should sum up to 1.0 over classes')
    average_options = ('macro', 'weighted', None)
    if multi_class == 'ovr':
        average_options = ('micro',) + average_options
    if average not in average_options:
        raise ValueError('average must be one of {0} for multiclass problems'.format(average_options))
    multiclass_options = ('ovo', 'ovr')
    if multi_class not in multiclass_options:
        raise ValueError("multi_class='{0}' is not supported for multiclass ROC AUC, multi_class must be in {1}".format(multi_class, multiclass_options))
    if average is None and multi_class == 'ovo':
        raise NotImplementedError("average=None is not implemented for multi_class='ovo'.")
    if labels is not None:
        labels = column_or_1d(labels)
        classes = _unique(labels)
        if len(classes) != len(labels):
            raise ValueError("Parameter 'labels' must be unique")
        if not np.array_equal(classes, labels):
            raise ValueError("Parameter 'labels' must be ordered")
        if len(classes) != y_score.shape[1]:
            raise ValueError("Number of given labels, {0}, not equal to the number of columns in 'y_score', {1}".format(len(classes), y_score.shape[1]))
        if len(np.setdiff1d(y_true, classes)):
            raise ValueError("'y_true' contains labels not in parameter 'labels'")
    else:
        classes = _unique(y_true)
        if len(classes) != y_score.shape[1]:
            raise ValueError("Number of classes in y_true not equal to the number of columns in 'y_score'")
    if multi_class == 'ovo':
        if sample_weight is not None:
            raise ValueError("sample_weight is not supported for multiclass one-vs-one ROC AUC, 'sample_weight' must be None in this case.")
        y_true_encoded = _encode(y_true, uniques=classes)
        return _average_multiclass_ovo_score(_binary_roc_auc_score, y_true_encoded, y_score, average=average)
    else:
        y_true_multilabel = label_binarize(y_true, classes=classes)
        return _average_binary_score(_binary_roc_auc_score, y_true_multilabel, y_score, average, sample_weight=sample_weight)

@_deprecate_positional_args(version='1.11')
@validate_params({'y_true': ['array-like'], 'y_score': ['array-like'], 'pos_label': [Real, str, 'boolean', None], 'sample_weight': ['array-like', None]}, prefer_skip_nested_validation=True)
def confusion_matrix_at_thresholds(y_true, y_score, *, pos_label=None, sample_weight=None):
    y_type = type_of_target(y_true, input_name='y_true')
    if not (y_type == 'binary' or (y_type == 'multiclass' and pos_label is not None)):
        raise ValueError('{0} format is not supported'.format(y_type))
    xp, _, device = get_namespace_and_device(y_score)
    pos_label = _check_pos_label_consistency(pos_label, y_true)
    xp_y_true, _ = get_namespace(y_true)
    y_true = xp_y_true.asarray(xp_y_true.asarray(y_true) == pos_label, dtype=xp_y_true.int32)
    y_true, sample_weight = move_to(y_true, sample_weight, xp=xp, device=device)
    y_true, y_score, weight, threshold_idxs = _sort_inputs_and_compute_classification_thresholds(y_true, y_score, sample_weight)
    if weight is None:
        weight = 1.0
    max_float_dtype = _max_precision_float_dtype(xp, device)
    y_true = xp.astype(y_true, max_float_dtype)
    tps = xp.cumulative_sum(y_true * weight, dtype=max_float_dtype)[threshold_idxs]
    if sample_weight is not None:
        fps = xp.cumulative_sum((1 - y_true) * weight, dtype=max_float_dtype)[threshold_idxs]
    else:
        fps = 1 + xp.astype(threshold_idxs, max_float_dtype) - tps
    tns = fps[-1] - fps
    fns = tps[-1] - tps
    return (tns, fps, fns, tps, y_score[threshold_idxs])

@validate_params({'y_true': ['array-like'], 'y_score': ['array-like'], 'pos_label': [Real, str, 'boolean', None], 'sample_weight': ['array-like', None], 'drop_intermediate': ['boolean']}, prefer_skip_nested_validation=True)
def precision_recall_curve(y_true, y_score, *, pos_label=None, sample_weight=None, drop_intermediate=False):
    xp, _, device = get_namespace_and_device(y_score)
    _, fps, _, tps, thresholds = confusion_matrix_at_thresholds(y_true, y_score, pos_label=pos_label, sample_weight=sample_weight)
    if drop_intermediate and fps.shape[0] > 2:
        optimal_idxs = xp.where(xp.concat([xp.asarray([True], device=device), xp.logical_or(xp.diff(tps[:-1]), xp.diff(tps[1:])), xp.asarray([True], device=device)]))[0]
        fps = fps[optimal_idxs]
        tps = tps[optimal_idxs]
        thresholds = thresholds[optimal_idxs]
    ps = tps + fps
    precision = xp.where(ps != 0, xp.divide(tps, ps), 0.0)
    if tps[-1] == 0:
        warnings.warn('No positive class found in y_true, recall is set to one for all thresholds.')
        recall = xp.full(tps.shape, 1.0, device=device)
    else:
        recall = tps / tps[-1]
    return (xp.concat((xp.flip(precision), xp.asarray([1.0], device=device))), xp.concat((xp.flip(recall), xp.asarray([0.0], device=device))), xp.flip(thresholds))

@validate_params({'y_true': ['array-like'], 'y_score': ['array-like'], 'pos_label': [Real, str, 'boolean', None], 'sample_weight': ['array-like', None], 'drop_intermediate': ['boolean']}, prefer_skip_nested_validation=True)
def roc_curve(y_true, y_score, *, pos_label=None, sample_weight=None, drop_intermediate=True):
    xp, _, device = get_namespace_and_device(y_true, y_score)
    _, fps, _, tps, thresholds = confusion_matrix_at_thresholds(y_true, y_score, pos_label=pos_label, sample_weight=sample_weight)
    if drop_intermediate and fps.shape[0] > 2:
        optimal_idxs = xp.where(xp.concat([xp.asarray([True], device=device), xp.logical_or(xp.diff(fps, 2), xp.diff(tps, 2)), xp.asarray([True], device=device)]))[0]
        fps = fps[optimal_idxs]
        tps = tps[optimal_idxs]
        thresholds = thresholds[optimal_idxs]
    tps = xp.concat([xp.asarray([0.0], device=device), tps])
    fps = xp.concat([xp.asarray([0.0], device=device), fps])
    thresholds = xp.astype(thresholds, _max_precision_float_dtype(xp, device))
    thresholds = xp.concat([xp.asarray([xp.inf], device=device), thresholds])
    if fps[-1] <= 0:
        warnings.warn('No negative samples in y_true, false positive value should be meaningless', UndefinedMetricWarning)
        fpr = xp.full(fps.shape, xp.nan)
    else:
        fpr = fps / fps[-1]
    if tps[-1] <= 0:
        warnings.warn('No positive samples in y_true, true positive value should be meaningless', UndefinedMetricWarning)
        tpr = xp.full(tps.shape, xp.nan)
    else:
        tpr = tps / tps[-1]
    return (fpr, tpr, thresholds)

@validate_params({'y_true': ['array-like', 'sparse matrix'], 'y_score': ['array-like'], 'sample_weight': ['array-like', None]}, prefer_skip_nested_validation=True)
def label_ranking_average_precision_score(y_true, y_score, *, sample_weight=None):
    check_consistent_length(y_true, y_score, sample_weight)
    y_true = check_array(y_true, ensure_2d=False, accept_sparse='csr')
    y_score = check_array(y_score, ensure_2d=False)
    if y_true.shape != y_score.shape:
        raise ValueError('y_true and y_score have different shape')
    y_type = type_of_target(y_true, input_name='y_true')
    if y_type != 'multilabel-indicator' and (not (y_type == 'binary' and y_true.ndim == 2)):
        raise ValueError('{0} format is not supported'.format(y_type))
    if not issparse(y_true):
        y_true = csr_array(y_true)
    y_score = -y_score
    n_samples, n_labels = y_true.shape
    out = 0.0
    for i, (start, stop) in enumerate(zip(y_true.indptr, y_true.indptr[1:])):
        relevant = y_true.indices[start:stop]
        if relevant.size == 0 or relevant.size == n_labels:
            aux = 1.0
        else:
            scores_i = y_score[i]
            rank = rankdata(scores_i, 'max')[relevant]
            L = rankdata(scores_i[relevant], 'max')
            aux = (L / rank).mean()
        if sample_weight is not None:
            aux = aux * sample_weight[i]
        out += aux
    if sample_weight is None:
        out /= n_samples
    else:
        out /= np.sum(sample_weight)
    return float(out)

@validate_params({'y_true': ['array-like'], 'y_score': ['array-like'], 'sample_weight': ['array-like', None]}, prefer_skip_nested_validation=True)
def coverage_error(y_true, y_score, *, sample_weight=None):
    y_true = check_array(y_true, ensure_2d=True)
    y_score = check_array(y_score, ensure_2d=True)
    check_consistent_length(y_true, y_score, sample_weight)
    y_type = type_of_target(y_true, input_name='y_true')
    if y_type != 'multilabel-indicator':
        raise ValueError('{0} format is not supported'.format(y_type))
    if y_true.shape != y_score.shape:
        raise ValueError('y_true and y_score have different shape')
    y_score_mask = np.ma.masked_array(y_score, mask=np.logical_not(y_true))
    y_min_relevant = y_score_mask.min(axis=1).reshape((-1, 1))
    coverage = (y_score >= y_min_relevant).sum(axis=1)
    coverage = coverage.filled(0)
    return float(np.average(coverage, weights=sample_weight))

def _dcg_sample_scores(y_true, y_score, k=None, log_base=2, ignore_ties=False):
    discount = 1 / (np.log(np.arange(y_true.shape[1]) + 2) / np.log(log_base))
    if k is not None:
        discount[k:] = 0
    if ignore_ties:
        ranking = np.argsort(y_score)[:, ::-1]
        ranked = y_true[np.arange(ranking.shape[0])[:, np.newaxis], ranking]
        cumulative_gains = discount.dot(ranked.T)
    else:
        discount_cumsum = np.cumsum(discount)
        cumulative_gains = [_tie_averaged_dcg(y_t, y_s, discount_cumsum) for y_t, y_s in zip(y_true, y_score)]
        cumulative_gains = np.asarray(cumulative_gains)
    return cumulative_gains

@validate_params({'y_true': ['array-like'], 'y_score': ['array-like'], 'k': [Interval(Integral, 1, None, closed='left'), None], 'log_base': [Interval(Real, 0.0, None, closed='neither')], 'sample_weight': ['array-like', None], 'ignore_ties': ['boolean']}, prefer_skip_nested_validation=True)
def dcg_score(y_true, y_score, *, k=None, log_base=2, sample_weight=None, ignore_ties=False):
    y_true = check_array(y_true, ensure_2d=False)
    y_score = check_array(y_score, ensure_2d=False)
    check_consistent_length(y_true, y_score, sample_weight)
    _check_dcg_target_type(y_true)
    return float(np.average(_dcg_sample_scores(y_true, y_score, k=k, log_base=log_base, ignore_ties=ignore_ties), weights=sample_weight))

@validate_params({'y_true': ['array-like'], 'y_score': ['array-like'], 'k': [Interval(Integral, 1, None, closed='left'), None], 'sample_weight': ['array-like', None], 'ignore_ties': ['boolean']}, prefer_skip_nested_validation=True)
def ndcg_score(y_true, y_score, *, k=None, sample_weight=None, ignore_ties=False):
    y_true = check_array(y_true, ensure_2d=False)
    y_score = check_array(y_score, ensure_2d=False)
    check_consistent_length(y_true, y_score, sample_weight)
    if y_true.min() < 0:
        raise ValueError('ndcg_score should not be used on negative y_true values.')
    if y_true.ndim > 1 and y_true.shape[1] <= 1:
        raise ValueError(f'Computing NDCG is only meaningful when there is more than 1 document. Got {y_true.shape[1]} instead.')
    _check_dcg_target_type(y_true)
    gain = _ndcg_sample_scores(y_true, y_score, k=k, ignore_ties=ignore_ties)
    return float(np.average(gain, weights=sample_weight))

@validate_params({'y_true': ['array-like'], 'y_score': ['array-like'], 'k': [Interval(Integral, 1, None, closed='left')], 'normalize': ['boolean'], 'sample_weight': ['array-like', None], 'labels': ['array-like', None]}, prefer_skip_nested_validation=True)
def top_k_accuracy_score(y_true, y_score, *, k=2, normalize=True, sample_weight=None, labels=None):
    y_true = check_array(y_true, ensure_2d=False, dtype=None)
    y_true = column_or_1d(y_true)
    y_type = type_of_target(y_true, input_name='y_true')
    if y_type == 'binary' and labels is not None and (len(labels) > 2):
        y_type = 'multiclass'
    if y_type not in {'binary', 'multiclass'}:
        raise ValueError(f"y type must be 'binary' or 'multiclass', got '{y_type}' instead.")
    y_score = check_array(y_score, ensure_2d=False)
    if y_type == 'binary':
        if y_score.ndim == 2 and y_score.shape[1] != 1:
            raise ValueError(f'`y_true` is binary while y_score is 2d with {y_score.shape[1]} classes. If `y_true` does not contain all the labels, `labels` must be provided.')
        y_score = column_or_1d(y_score)
    elif not y_score.ndim == 2:
        raise ValueError(f'`y_score` needs to be of shape `(n_samples, n_classes)`, since `y_true` contains multiple classes. Got `y_score.shape={y_score.shape}`.')
    check_consistent_length(y_true, y_score, sample_weight)
    y_score_n_classes = y_score.shape[1] if y_score.ndim == 2 else 2
    if labels is None:
        classes = _unique(y_true)
        n_classes = len(classes)
        if n_classes != y_score_n_classes:
            raise ValueError(f"Number of classes in 'y_true' ({n_classes}) not equal to the number of classes in 'y_score' ({y_score_n_classes}).You can provide a list of all known classes by assigning it to the `labels` parameter.")
    else:
        labels = column_or_1d(labels)
        classes = _unique(labels)
        n_labels = len(labels)
        n_classes = len(classes)
        if n_classes != n_labels:
            raise ValueError("Parameter 'labels' must be unique.")
        if not np.array_equal(classes, labels):
            raise ValueError("Parameter 'labels' must be ordered.")
        if n_classes != y_score_n_classes:
            raise ValueError(f"Number of given labels ({n_classes}) not equal to the number of classes in 'y_score' ({y_score_n_classes}).")
        if len(np.setdiff1d(y_true, classes)):
            raise ValueError("'y_true' contains labels not in parameter 'labels'.")
    if k >= n_classes:
        warnings.warn(f"'k' ({k}) greater than or equal to 'n_classes' ({n_classes}) will result in a perfect score and is therefore meaningless.", UndefinedMetricWarning)
    y_true_encoded = _encode(y_true, uniques=classes)
    if y_type == 'binary':
        if k == 1:
            threshold = 0.5 if y_score.min() >= 0 and y_score.max() <= 1 else 0
            y_pred = (y_score > threshold).astype(np.int64)
            hits = y_pred == y_true_encoded
        else:
            hits = np.ones_like(y_score, dtype=np.bool_)
    elif y_type == 'multiclass':
        sorted_pred = np.argsort(y_score, axis=1, kind='mergesort')[:, ::-1]
        hits = (y_true_encoded == sorted_pred[:, :k].T).any(axis=0)
    if normalize:
        return float(np.average(hits, weights=sample_weight))
    elif sample_weight is None:
        return float(np.sum(hits))
    else:
        return float(np.dot(hits, sample_weight))

@validate_params({'y_true': ['array-like'], 'y_score': ['array-like'], 'metric_func': [callable], 'sample_weight': ['array-like', None], 'metric_params': [dict, None]}, prefer_skip_nested_validation=True)
def metric_at_thresholds(y_true, y_score, metric_func, *, sample_weight=None, metric_params=None):
    y_true, y_score, sample_weight, threshold_idxs = _sort_inputs_and_compute_classification_thresholds(y_true, y_score, sample_weight)
    metric_params = {**(metric_params or {}), **({'sample_weight': sample_weight} if sample_weight is not None else {})}
    thresholds = y_score[threshold_idxs]
    metric_values = []
    for threshold in thresholds:
        y_pred = (y_score >= threshold).astype(np.int32)
        metric_values.append(metric_func(y_true, y_pred, **metric_params))
    metric_values = np.asarray(metric_values)
    return (metric_values, thresholds)

def _check_reg_targets(y_true, y_pred, sample_weight, multioutput, dtype='numeric', xp=None):
    xp, _ = get_namespace(y_true, y_pred, multioutput, xp=xp)
    check_consistent_length(y_true, y_pred, sample_weight)
    y_true = check_array(y_true, ensure_2d=False, dtype=dtype)
    y_pred = check_array(y_pred, ensure_2d=False, dtype=dtype)
    if sample_weight is not None:
        sample_weight = _check_sample_weight(sample_weight, y_true, dtype=dtype)
    if y_true.ndim == 1:
        y_true = xp.reshape(y_true, (-1, 1))
    if y_pred.ndim == 1:
        y_pred = xp.reshape(y_pred, (-1, 1))
    if y_true.shape[1] != y_pred.shape[1]:
        raise ValueError('y_true and y_pred have different number of output ({0}!={1})'.format(y_true.shape[1], y_pred.shape[1]))
    n_outputs = y_true.shape[1]
    allowed_multioutput_str = ('raw_values', 'uniform_average', 'variance_weighted')
    if isinstance(multioutput, str):
        if multioutput not in allowed_multioutput_str:
            raise ValueError("Allowed 'multioutput' string values are {}. You provided multioutput={!r}".format(allowed_multioutput_str, multioutput))
    elif multioutput is not None:
        multioutput = check_array(multioutput, ensure_2d=False)
        if n_outputs == 1:
            raise ValueError('Custom weights are useful only in multi-output cases.')
        elif n_outputs != multioutput.shape[0]:
            raise ValueError(f'There must be equally many custom weights ({multioutput.shape[0]}) as outputs ({n_outputs}).')
    y_type = 'continuous' if n_outputs == 1 else 'continuous-multioutput'
    return (y_type, y_true, y_pred, sample_weight, multioutput)

def _check_reg_targets_with_floating_dtype(y_true, y_pred, sample_weight, multioutput, xp=None):
    dtype_name = _find_matching_floating_dtype(y_true, y_pred, sample_weight, xp=xp)
    y_type, y_true, y_pred, sample_weight, multioutput = _check_reg_targets(y_true, y_pred, sample_weight, multioutput, dtype=dtype_name, xp=xp)
    return (y_type, y_true, y_pred, sample_weight, multioutput)

@validate_params({'y_true': ['array-like'], 'y_pred': ['array-like'], 'sample_weight': ['array-like', None], 'multioutput': [StrOptions({'raw_values', 'uniform_average'}), 'array-like']}, prefer_skip_nested_validation=True)
def mean_absolute_error(y_true, y_pred, *, sample_weight=None, multioutput='uniform_average'):
    xp, _, device = get_namespace_and_device(y_pred)
    y_true, sample_weight = move_to(y_true, sample_weight, xp=xp, device=device)
    _, y_true, y_pred, sample_weight, multioutput = _check_reg_targets_with_floating_dtype(y_true, y_pred, sample_weight, multioutput, xp=xp)
    output_errors = _average(xp.abs(y_pred - y_true), weights=sample_weight, axis=0, xp=xp)
    if isinstance(multioutput, str):
        if multioutput == 'raw_values':
            return output_errors
        elif multioutput == 'uniform_average':
            multioutput = None
    mean_absolute_error = _average(output_errors, weights=multioutput, xp=xp)
    return float(mean_absolute_error)

@validate_params({'y_true': ['array-like'], 'y_pred': ['array-like'], 'sample_weight': ['array-like', None], 'alpha': [Interval(Real, 0, 1, closed='both')], 'multioutput': [StrOptions({'raw_values', 'uniform_average'}), 'array-like']}, prefer_skip_nested_validation=True)
def mean_pinball_loss(y_true, y_pred, *, sample_weight=None, alpha=0.5, multioutput='uniform_average'):
    xp, _, device = get_namespace_and_device(y_pred)
    y_true, sample_weight = move_to(y_true, sample_weight, xp=xp, device=device)
    _, y_true, y_pred, sample_weight, multioutput = _check_reg_targets_with_floating_dtype(y_true, y_pred, sample_weight, multioutput, xp=xp)
    diff = y_true - y_pred
    sign = xp.astype(diff >= 0, diff.dtype)
    loss = alpha * sign * diff - (1 - alpha) * (1 - sign) * diff
    output_errors = _average(loss, weights=sample_weight, axis=0, xp=xp)
    if isinstance(multioutput, str) and multioutput == 'raw_values':
        return output_errors
    if isinstance(multioutput, str) and multioutput == 'uniform_average':
        multioutput = None
    return float(_average(output_errors, weights=multioutput, xp=xp))

@validate_params({'y_true': ['array-like'], 'y_pred': ['array-like'], 'sample_weight': ['array-like', None], 'multioutput': [StrOptions({'raw_values', 'uniform_average'}), 'array-like']}, prefer_skip_nested_validation=True)
def mean_absolute_percentage_error(y_true, y_pred, *, sample_weight=None, multioutput='uniform_average'):
    xp, _, device_ = get_namespace_and_device(y_pred)
    y_true, sample_weight = move_to(y_true, sample_weight, xp=xp, device=device_)
    _, y_true, y_pred, sample_weight, multioutput = _check_reg_targets_with_floating_dtype(y_true, y_pred, sample_weight, multioutput, xp=xp)
    epsilon = xp.asarray(xp.finfo(xp.float64).eps, dtype=y_true.dtype, device=device_)
    y_true_abs = xp.abs(y_true)
    mape = xp.abs(y_pred - y_true) / xp.maximum(y_true_abs, epsilon)
    output_errors = _average(mape, weights=sample_weight, axis=0, xp=xp)
    if isinstance(multioutput, str):
        if multioutput == 'raw_values':
            return output_errors
        elif multioutput == 'uniform_average':
            multioutput = None
    mean_absolute_percentage_error = _average(output_errors, weights=multioutput, xp=xp)
    return float(mean_absolute_percentage_error)

@validate_params({'y_true': ['array-like'], 'y_pred': ['array-like'], 'sample_weight': ['array-like', None], 'multioutput': [StrOptions({'raw_values', 'uniform_average'}), 'array-like']}, prefer_skip_nested_validation=True)
def mean_squared_error(y_true, y_pred, *, sample_weight=None, multioutput='uniform_average'):
    xp, _, device = get_namespace_and_device(y_pred)
    y_true, sample_weight = move_to(y_true, sample_weight, xp=xp, device=device)
    _, y_true, y_pred, sample_weight, multioutput = _check_reg_targets_with_floating_dtype(y_true, y_pred, sample_weight, multioutput, xp=xp)
    output_errors = _average((y_true - y_pred) ** 2, axis=0, weights=sample_weight, xp=xp)
    if isinstance(multioutput, str):
        if multioutput == 'raw_values':
            return output_errors
        elif multioutput == 'uniform_average':
            multioutput = None
    mean_squared_error = _average(output_errors, weights=multioutput, xp=xp)
    return float(mean_squared_error)

@validate_params({'y_true': ['array-like'], 'y_pred': ['array-like'], 'sample_weight': ['array-like', None], 'multioutput': [StrOptions({'raw_values', 'uniform_average'}), 'array-like']}, prefer_skip_nested_validation=True)
def root_mean_squared_error(y_true, y_pred, *, sample_weight=None, multioutput='uniform_average'):
    xp, _, device = get_namespace_and_device(y_pred)
    y_true, sample_weight = move_to(y_true, sample_weight, xp=xp, device=device)
    output_errors = xp.sqrt(mean_squared_error(y_true, y_pred, sample_weight=sample_weight, multioutput='raw_values'))
    if isinstance(multioutput, str):
        if multioutput == 'raw_values':
            return output_errors
        elif multioutput == 'uniform_average':
            multioutput = None
    root_mean_squared_error = _average(output_errors, weights=multioutput, xp=xp)
    return float(root_mean_squared_error)

@validate_params({'y_true': ['array-like'], 'y_pred': ['array-like'], 'sample_weight': ['array-like', None], 'multioutput': [StrOptions({'raw_values', 'uniform_average'}), 'array-like']}, prefer_skip_nested_validation=True)
def mean_squared_log_error(y_true, y_pred, *, sample_weight=None, multioutput='uniform_average'):
    xp, _, device = get_namespace_and_device(y_pred)
    y_true, sample_weight = move_to(y_true, sample_weight, xp=xp, device=device)
    _, y_true, y_pred, sample_weight, multioutput = _check_reg_targets_with_floating_dtype(y_true, y_pred, sample_weight, multioutput, xp=xp)
    if xp.any(y_true <= -1) or xp.any(y_pred <= -1):
        raise ValueError('Mean Squared Logarithmic Error cannot be used when targets contain values less than or equal to -1.')
    return mean_squared_error(xp.log1p(y_true), xp.log1p(y_pred), sample_weight=sample_weight, multioutput=multioutput)

@validate_params({'y_true': ['array-like'], 'y_pred': ['array-like'], 'sample_weight': ['array-like', None], 'multioutput': [StrOptions({'raw_values', 'uniform_average'}), 'array-like']}, prefer_skip_nested_validation=True)
def root_mean_squared_log_error(y_true, y_pred, *, sample_weight=None, multioutput='uniform_average'):
