@validate_params({'y_true': ['array-like'], 'y_pred': ['array-like'], 'multioutput': [StrOptions({'raw_values', 'uniform_average'}), 'array-like'], 'sample_weight': ['array-like', None]}, prefer_skip_nested_validation=True)
def median_absolute_error(y_true, y_pred, *, multioutput='uniform_average', sample_weight=None):
    xp, _, device = get_namespace_and_device(y_pred)
    y_true, sample_weight = move_to(y_true, sample_weight, xp=xp, device=device)
    _, y_true, y_pred, sample_weight, multioutput = _check_reg_targets(y_true, y_pred, sample_weight, multioutput, xp=xp)
    if sample_weight is None:
        output_errors = _median(xp.abs(y_pred - y_true), axis=0)
    else:
        output_errors = _weighted_percentile(xp.abs(y_pred - y_true), sample_weight=sample_weight, average=True)
    if isinstance(multioutput, str):
        if multioutput == 'raw_values':
            return output_errors
        elif multioutput == 'uniform_average':
            multioutput = None
    return float(_average(output_errors, weights=multioutput, xp=xp))

def _assemble_fraction_of_explained_deviance(numerator, denominator, n_outputs, multioutput, force_finite, xp, device):
    dtype = numerator.dtype
    nonzero_denominator = denominator != 0
    if not force_finite:
        output_scores = 1 - numerator / denominator
    else:
        nonzero_numerator = numerator != 0
        output_scores = xp.ones([n_outputs], device=device, dtype=dtype)
        valid_score = nonzero_denominator & nonzero_numerator
        output_scores[valid_score] = 1 - numerator[valid_score] / denominator[valid_score]
        output_scores[nonzero_numerator & ~nonzero_denominator] = 0.0
    if isinstance(multioutput, str):
        if multioutput == 'raw_values':
            return output_scores
        elif multioutput == 'uniform_average':
            avg_weights = None
        elif multioutput == 'variance_weighted':
            avg_weights = denominator
            if not xp.any(nonzero_denominator):
                avg_weights = None
    else:
        avg_weights = multioutput
    result = _average(output_scores, weights=avg_weights, xp=xp)
    if size(result) == 1:
        return float(result)
    return result

@validate_params({'y_true': ['array-like'], 'y_pred': ['array-like'], 'sample_weight': ['array-like', None], 'multioutput': [StrOptions({'raw_values', 'uniform_average', 'variance_weighted'}), 'array-like'], 'force_finite': ['boolean']}, prefer_skip_nested_validation=True)
def explained_variance_score(y_true, y_pred, *, sample_weight=None, multioutput='uniform_average', force_finite=True):
    xp, _, device = get_namespace_and_device(y_pred)
    y_true, sample_weight = move_to(y_true, sample_weight, xp=xp, device=device)
    _, y_true, y_pred, sample_weight, multioutput = _check_reg_targets_with_floating_dtype(y_true, y_pred, sample_weight, multioutput, xp=xp)
    y_diff_avg = _average(y_true - y_pred, weights=sample_weight, axis=0, xp=xp)
    numerator = _average((y_true - y_pred - y_diff_avg) ** 2, weights=sample_weight, axis=0, xp=xp)
    y_true_avg = _average(y_true, weights=sample_weight, axis=0, xp=xp)
    denominator = _average((y_true - y_true_avg) ** 2, weights=sample_weight, axis=0, xp=xp)
    return _assemble_fraction_of_explained_deviance(numerator=numerator, denominator=denominator, n_outputs=y_true.shape[1], multioutput=multioutput, force_finite=force_finite, xp=xp, device=device)

@validate_params({'y_true': ['array-like'], 'y_pred': ['array-like'], 'sample_weight': ['array-like', None], 'multioutput': [StrOptions({'raw_values', 'uniform_average', 'variance_weighted'}), 'array-like', None], 'force_finite': ['boolean']}, prefer_skip_nested_validation=True)
def r2_score(y_true, y_pred, *, sample_weight=None, multioutput='uniform_average', force_finite=True):
    xp, _, device_ = get_namespace_and_device(y_pred)
    y_true, sample_weight = move_to(y_true, sample_weight, xp=xp, device=device_)
    _, y_true, y_pred, sample_weight, multioutput = _check_reg_targets_with_floating_dtype(y_true, y_pred, sample_weight, multioutput, xp=xp)
    if _num_samples(y_pred) < 2:
        msg = 'R^2 score is not well-defined with less than two samples.'
        warnings.warn(msg, UndefinedMetricWarning)
        return float('nan')
    if sample_weight is not None:
        sample_weight = column_or_1d(sample_weight)
        weight = sample_weight[:, None]
    else:
        weight = 1.0
    numerator = xp.sum(weight * (y_true - y_pred) ** 2, axis=0)
    denominator = xp.sum(weight * (y_true - _average(y_true, axis=0, weights=sample_weight, xp=xp)) ** 2, axis=0)
    return _assemble_fraction_of_explained_deviance(numerator=numerator, denominator=denominator, n_outputs=y_true.shape[1], multioutput=multioutput, force_finite=force_finite, xp=xp, device=device_)

@validate_params({'y_true': ['array-like'], 'y_pred': ['array-like']}, prefer_skip_nested_validation=True)
def max_error(y_true, y_pred):
    xp, _, device = get_namespace_and_device(y_pred)
    y_true = move_to(y_true, xp=xp, device=device)
    y_type, y_true, y_pred, _, _ = _check_reg_targets(y_true, y_pred, sample_weight=None, multioutput=None, xp=xp)
    if y_type == 'continuous-multioutput':
        raise ValueError('Multioutput not supported in max_error')
    return float(xp.max(xp.abs(y_true - y_pred)))

def _mean_tweedie_deviance(y_true, y_pred, sample_weight, power):
    xp, _ = get_namespace(y_true, y_pred)
    p = power
    if p < 0:
        dev = 2 * (xp.pow(xp.where(y_true > 0, y_true, 0.0), 2 - p) / ((1 - p) * (2 - p)) - y_true * xp.pow(y_pred, 1 - p) / (1 - p) + xp.pow(y_pred, 2 - p) / (2 - p))
    elif p == 0:
        dev = (y_true - y_pred) ** 2
    elif p == 1:
        dev = 2 * (xlogy(y_true, y_true / y_pred) - y_true + y_pred)
    elif p == 2:
        dev = 2 * (xp.log(y_pred / y_true) + y_true / y_pred - 1)
    else:
        dev = 2 * (xp.pow(y_true, 2 - p) / ((1 - p) * (2 - p)) - y_true * xp.pow(y_pred, 1 - p) / (1 - p) + xp.pow(y_pred, 2 - p) / (2 - p))
    return float(_average(dev, weights=sample_weight, xp=xp))

@validate_params({'y_true': ['array-like'], 'y_pred': ['array-like'], 'sample_weight': ['array-like', None], 'power': [Interval(Real, None, 0, closed='right'), Interval(Real, 1, None, closed='left')]}, prefer_skip_nested_validation=True)
def mean_tweedie_deviance(y_true, y_pred, *, sample_weight=None, power=0):
    xp, _, device = get_namespace_and_device(y_pred)
    y_true, sample_weight = move_to(y_true, sample_weight, xp=xp, device=device)
    y_type, y_true, y_pred, sample_weight, _ = _check_reg_targets_with_floating_dtype(y_true, y_pred, sample_weight, multioutput=None, xp=xp)
    if y_type == 'continuous-multioutput':
        raise ValueError('Multioutput not supported in mean_tweedie_deviance')
    if sample_weight is not None:
        sample_weight = column_or_1d(sample_weight)
        sample_weight = sample_weight[:, np.newaxis]
    message = f'Mean Tweedie deviance error with power={power} can only be used on '
    if power < 0:
        if xp.any(y_pred <= 0):
            raise ValueError(message + 'strictly positive y_pred.')
    elif power == 0:
        pass
    elif 1 <= power < 2:
        if xp.any(y_true < 0) or xp.any(y_pred <= 0):
            raise ValueError(message + 'non-negative y and strictly positive y_pred.')
    elif power >= 2:
        if xp.any(y_true <= 0) or xp.any(y_pred <= 0):
            raise ValueError(message + 'strictly positive y and y_pred.')
    else:
        raise ValueError
    return _mean_tweedie_deviance(y_true, y_pred, sample_weight=sample_weight, power=power)

@validate_params({'y_true': ['array-like'], 'y_pred': ['array-like'], 'sample_weight': ['array-like', None]}, prefer_skip_nested_validation=True)
def mean_poisson_deviance(y_true, y_pred, *, sample_weight=None):
    return mean_tweedie_deviance(y_true, y_pred, sample_weight=sample_weight, power=1)

@validate_params({'y_true': ['array-like'], 'y_pred': ['array-like'], 'sample_weight': ['array-like', None]}, prefer_skip_nested_validation=True)
def mean_gamma_deviance(y_true, y_pred, *, sample_weight=None):
    return mean_tweedie_deviance(y_true, y_pred, sample_weight=sample_weight, power=2)

@validate_params({'y_true': ['array-like'], 'y_pred': ['array-like'], 'sample_weight': ['array-like', None], 'power': [Interval(Real, None, 0, closed='right'), Interval(Real, 1, None, closed='left')]}, prefer_skip_nested_validation=True)
def d2_tweedie_score(y_true, y_pred, *, sample_weight=None, power=0):
    xp, _, device = get_namespace_and_device(y_pred)
    y_true, sample_weight = move_to(y_true, sample_weight, xp=xp, device=device)
    y_type, y_true, y_pred, sample_weight, _ = _check_reg_targets_with_floating_dtype(y_true, y_pred, sample_weight, multioutput=None, xp=xp)
    if y_type == 'continuous-multioutput':
        raise ValueError('Multioutput not supported in d2_tweedie_score')
    if _num_samples(y_pred) < 2:
        msg = 'D^2 score is not well-defined with less than two samples.'
        warnings.warn(msg, UndefinedMetricWarning)
        return float('nan')
    y_true, y_pred = (xp.squeeze(y_true, axis=1), xp.squeeze(y_pred, axis=1))
    numerator = mean_tweedie_deviance(y_true, y_pred, sample_weight=sample_weight, power=power)
    y_avg = _average(y_true, weights=sample_weight, xp=xp)
    denominator = _mean_tweedie_deviance(y_true, y_avg, sample_weight=sample_weight, power=power)
    return 1 - numerator / denominator

@validate_params({'y_true': ['array-like'], 'y_pred': ['array-like'], 'sample_weight': ['array-like', None], 'alpha': [Interval(Real, 0, 1, closed='both')], 'multioutput': [StrOptions({'raw_values', 'uniform_average'}), 'array-like']}, prefer_skip_nested_validation=True)
def d2_pinball_score(y_true, y_pred, *, sample_weight=None, alpha=0.5, multioutput='uniform_average'):
    xp, _, device_ = get_namespace_and_device(y_pred)
    y_true, sample_weight = move_to(y_true, sample_weight, xp=xp, device=device_)
    _, y_true, y_pred, sample_weight, multioutput = _check_reg_targets_with_floating_dtype(y_true, y_pred, sample_weight, multioutput, xp=xp)
    if _num_samples(y_pred) < 2:
        msg = 'D^2 score is not well-defined with less than two samples.'
        warnings.warn(msg, UndefinedMetricWarning)
        return float('nan')
    numerator = mean_pinball_loss(y_true, y_pred, sample_weight=sample_weight, alpha=alpha, multioutput='raw_values')
    if sample_weight is None:
        sample_weight = xp.ones([y_true.shape[0]], dtype=y_true.dtype, device=device_)
    y_quantile = xp.tile(_weighted_percentile(y_true, sample_weight=sample_weight, percentile_rank=alpha * 100, average=True, xp=xp), (y_true.shape[0], 1))
    denominator = mean_pinball_loss(y_true, y_quantile, sample_weight=sample_weight, alpha=alpha, multioutput='raw_values')
    return _assemble_fraction_of_explained_deviance(numerator=numerator, denominator=denominator, n_outputs=y_true.shape[1], multioutput=multioutput, force_finite=True, xp=xp, device=device_)

@validate_params({'y_true': ['array-like'], 'y_pred': ['array-like'], 'sample_weight': ['array-like', None], 'multioutput': [StrOptions({'raw_values', 'uniform_average'}), 'array-like']}, prefer_skip_nested_validation=True)
def d2_absolute_error_score(y_true, y_pred, *, sample_weight=None, multioutput='uniform_average'):
    return d2_pinball_score(y_true, y_pred, sample_weight=sample_weight, alpha=0.5, multioutput=multioutput)

def _cached_call(cache, estimator, response_method, *args, **kwargs):
    if cache is not None and response_method in cache:
        return cache[response_method]
    result, _ = _get_response_values(estimator, *args, response_method=response_method, **kwargs)
    if cache is not None:
        cache[response_method] = result
    return result

def _get_func_repr_or_name(func):
    if isinstance(func, partial):
        return repr(func)
    return func.__name__

@validate_params({'scoring': [str, callable, None]}, prefer_skip_nested_validation=True)
def get_scorer(scoring):
    if isinstance(scoring, str):
        try:
            scorer = copy.deepcopy(_SCORERS[scoring])
        except KeyError:
            raise ValueError('%r is not a valid scoring value. Use sklearn.metrics.get_scorer_names() to get valid options.' % scoring)
    else:
        scorer = scoring
    return scorer

def _check_multimetric_scoring(estimator, scoring):
    err_msg_generic = f'scoring is invalid (got {scoring!r}). Refer to the scoring glossary for details: https://scikit-learn.org/stable/glossary.html#term-scoring'
    if isinstance(scoring, (list, tuple, set)):
        err_msg = 'The list/tuple elements must be unique strings of predefined scorers. '
        try:
            keys = set(scoring)
        except TypeError as e:
            raise ValueError(err_msg) from e
        if len(keys) != len(scoring):
            raise ValueError(f'{err_msg} Duplicate elements were found in the given list. {scoring!r}')
        elif len(keys) > 0:
            if not all((isinstance(k, str) for k in keys)):
                if any((callable(k) for k in keys)):
                    raise ValueError(f'{err_msg} One or more of the elements were callables. Use a dict of score name mapped to the scorer callable. Got {scoring!r}')
                else:
                    raise ValueError(f'{err_msg} Non-string types were found in the given list. Got {scoring!r}')
            scorers = {scorer: check_scoring(estimator, scoring=scorer) for scorer in scoring}
        else:
            raise ValueError(f'{err_msg} Empty list was given. {scoring!r}')
    elif isinstance(scoring, dict):
        keys = set(scoring)
        if not all((isinstance(k, str) for k in keys)):
            raise ValueError(f'Non-string types were found in the keys of the given dict. scoring={scoring!r}')
        if len(keys) == 0:
            raise ValueError(f'An empty dict was passed. {scoring!r}')
        scorers = {key: check_scoring(estimator, scoring=scorer) for key, scorer in scoring.items()}
    else:
        raise ValueError(err_msg_generic)
    return scorers

@validate_params({'score_func': [callable], 'response_method': [list, tuple, StrOptions({'predict', 'predict_proba', 'decision_function'})], 'greater_is_better': ['boolean']}, prefer_skip_nested_validation=True)
def make_scorer(score_func, *, response_method='predict', greater_is_better=True, **kwargs):
    sign = 1 if greater_is_better else -1
    return _Scorer(score_func, sign, kwargs, response_method)

@validate_params({'estimator': [HasMethods('fit'), None], 'scoring': [StrOptions(set(get_scorer_names())), callable, list, set, tuple, dict, None], 'allow_none': ['boolean'], 'raise_exc': ['boolean']}, prefer_skip_nested_validation=True)
def check_scoring(estimator=None, scoring=None, *, allow_none=False, raise_exc=True):
    if isinstance(scoring, str):
        return get_scorer(scoring)
    if callable(scoring):
        module = getattr(scoring, '__module__', None)
        if hasattr(module, 'startswith') and module.startswith('sklearn.metrics.') and (not module.startswith('sklearn.metrics._scorer')) and (not module.startswith('sklearn.metrics.tests.')):
            raise ValueError('scoring value %r looks like it is a metric function rather than a scorer. A scorer should require an estimator as its first parameter. Please use `make_scorer` to convert a metric to a scorer.' % scoring)
        return get_scorer(scoring)
    if isinstance(scoring, (list, tuple, set, dict)):
        scorers = _check_multimetric_scoring(estimator, scoring=scoring)
        return _MultimetricScorer(scorers=scorers, raise_exc=raise_exc)
    if scoring is None:
        if hasattr(estimator, 'score'):
            return _PassthroughScorer(estimator)
        elif allow_none:
            return None
        else:
            raise TypeError("If no scoring is specified, the estimator passed should have a 'score' method. The estimator %r does not." % estimator)

def _threshold_scores_to_class_labels(y_score, threshold, classes, pos_label):
    if pos_label is None:
        map_thresholded_score_to_label = np.array([0, 1])
    else:
        pos_label_idx = np.flatnonzero(classes == pos_label)[0]
        neg_label_idx = np.flatnonzero(classes != pos_label)[0]
        map_thresholded_score_to_label = np.array([neg_label_idx, pos_label_idx])
    return classes[map_thresholded_score_to_label[(y_score >= threshold).astype(int)]]

def __call__(self, estimator, *args, **kwargs):
    scores = {}
    cache = {} if self._use_cache(estimator) else None
    cached_call = partial(_cached_call, cache)
    if _routing_enabled():
        routed_params = process_routing(self, 'score', **kwargs)
    else:
        common_kwargs = {arg: value for arg, value in kwargs.items() if arg != 'sample_weight'}
        sw = kwargs.get('sample_weight')
        routed_params = _manual_routing({name: {'score': {**common_kwargs, **({'sample_weight': sw} if sw is not None and scorer._accept_sample_weight() else {})}} for name, scorer in self._scorers.items()})
    for name, scorer in self._scorers.items():
        try:
            if isinstance(scorer, _BaseScorer):
                score = scorer._score(cached_call, estimator, *args, **routed_params.get(name).score)
            else:
                score = scorer(estimator, *args, **routed_params.get(name).score)
            scores[name] = score
        except Exception as e:
            if self._raise_exc:
                raise e
            else:
                scores[name] = format_exc()
    return scores

def _use_cache(self, estimator):
    if len(self._scorers) == 1:
        return False
    counter = Counter([_check_response_method(estimator, scorer._response_method).__name__ for scorer in self._scorers.values() if isinstance(scorer, _BaseScorer)])
    if any((val > 1 for val in counter.values())):
        return True
    return False

@_deprecate_positional_args(version='1.11')
def __call__(self, estimator, X, y_true, *, sample_weight=None, **kwargs):
    _raise_for_params(kwargs, self, None)
    if sample_weight is not None:
        kwargs['sample_weight'] = sample_weight
    return self._score(partial(_cached_call, None), estimator, X, y_true, **kwargs)

def _warn_overlap(self, message, kwargs):
    _kwargs = set() if self._kwargs is None else set(self._kwargs.keys())
    overlap = _kwargs.intersection(kwargs.keys())
    if overlap:
        warnings.warn(f'{message} Overlapping parameters are: {overlap}', UserWarning)

def set_score_request(self, **kwargs):
    if not _routing_enabled():
        raise RuntimeError('This method is only available when metadata routing is enabled. You can enable it using sklearn.set_config(enable_metadata_routing=True).')
    self._warn_overlap(message='You are setting metadata request for parameters which are already set as kwargs for this metric. These set values will be overridden by passed metadata if provided. Please pass them either as metadata or kwargs to `make_scorer`.', kwargs=kwargs)
    self._metadata_request = MetadataRequest(owner=self)
    for param, alias in kwargs.items():
        self._metadata_request.score.add_request(param=param, alias=alias)
    return self

def _get_metadata_request(self):
    if hasattr(self, '_metadata_request'):
        requests = get_routing_for_object(self._metadata_request)
    else:
        requests = MetadataRequest(owner=self)
        setattr(requests, 'score', MethodMetadataRequest(owner=self, method='score', requests=self._get_class_level_metadata_request_values(method_name='score', method=self._score_func, ignore_params={'y_true', 'y_pred', 'y_prob', 'y_proba', 'y_score', 'y2', 'pred_decision', 'labels_true', 'labels_pred'})))
    return requests

def _score(self, method_caller, estimator, X, y_true, **kwargs):
    self._warn_overlap(message='There is an overlap between set kwargs of this scorer instance and passed metadata. Please pass them either as kwargs to `make_scorer` or metadata, but not both.', kwargs=kwargs)
    pos_label = None if is_regressor(estimator) else self._get_pos_label()
    response_method = _check_response_method(estimator, self._response_method)
    y_pred = method_caller(estimator, _get_response_method_name(response_method), X, pos_label=pos_label)
    scoring_kwargs = {**self._kwargs, **kwargs}
    return self._sign * self._score_func(y_true, y_pred, **scoring_kwargs)

@classmethod
def from_scorer(cls, scorer, response_method, thresholds):
    instance = cls(score_func=scorer._score_func, sign=scorer._sign, response_method=response_method, thresholds=thresholds, kwargs=scorer._kwargs)
    instance._metadata_request = scorer.get_metadata_routing()
    return instance

def _score(self, method_caller, estimator, X, y_true, **kwargs):
    pos_label = self._get_pos_label()
    y_score = method_caller(estimator, self._response_method, X, pos_label=pos_label)
    scoring_kwargs = {**self._kwargs, **kwargs}
    if isinstance(self._thresholds, Integral):
        potential_thresholds = np.linspace(np.min(y_score), np.max(y_score), self._thresholds)
    else:
        potential_thresholds = np.asarray(self._thresholds)
    score_thresholds = [self._sign * self._score_func(y_true, _threshold_scores_to_class_labels(y_score, th, estimator.classes_, pos_label), **scoring_kwargs) for th in potential_thresholds]
    return (np.array(score_thresholds), potential_thresholds)

def _jaccard(a_rows, a_cols, b_rows, b_cols):
    intersection = (a_rows * b_rows).sum() * (a_cols * b_cols).sum()
    a_size = a_rows.sum() * a_cols.sum()
    b_size = b_rows.sum() * b_cols.sum()
    return intersection / (a_size + b_size - intersection)

@validate_params({'a': [tuple], 'b': [tuple], 'similarity': [callable, StrOptions({'jaccard'})]}, prefer_skip_nested_validation=True)
def consensus_score(a, b, *, similarity='jaccard'):
    if similarity == 'jaccard':
        similarity = _jaccard
    matrix = _pairwise_similarity(a, b, similarity)
    row_indices, col_indices = linear_sum_assignment(1.0 - matrix)
    n_a = len(a[0])
    n_b = len(b[0])
    return float(matrix[row_indices, col_indices].sum() / max(n_a, n_b))

def check_clusterings(labels_true, labels_pred):
    labels_true = check_array(labels_true, ensure_2d=False, ensure_min_samples=0, dtype=None)
    labels_pred = check_array(labels_pred, ensure_2d=False, ensure_min_samples=0, dtype=None)
    type_label = type_of_target(labels_true)
    type_pred = type_of_target(labels_pred)
    if 'continuous' in (type_pred, type_label):
        msg = f'Clustering metrics expects discrete values but received {type_label} values for label, and {type_pred} values for target'
        warnings.warn(msg, UserWarning)
    if labels_true.ndim != 1:
        raise ValueError('labels_true must be 1D: shape is %r' % (labels_true.shape,))
    if labels_pred.ndim != 1:
        raise ValueError('labels_pred must be 1D: shape is %r' % (labels_pred.shape,))
    check_consistent_length(labels_true, labels_pred)
    return (labels_true, labels_pred)

def _generalized_average(U, V, average_method):
    if average_method == 'min':
        return min(U, V)
    elif average_method == 'geometric':
        return np.sqrt(U * V)
    elif average_method == 'arithmetic':
        return np.mean([U, V])
    elif average_method == 'max':
        return max(U, V)
    else:
        raise ValueError("'average_method' must be 'min', 'geometric', 'arithmetic', or 'max'")

@validate_params({'labels_true': ['array-like', None], 'labels_pred': ['array-like', None], 'eps': [Interval(Real, 0, None, closed='left'), None], 'sparse': ['boolean'], 'dtype': 'no_validation'}, prefer_skip_nested_validation=True)
def contingency_matrix(labels_true, labels_pred, *, eps=None, sparse=False, dtype=np.int64):
    if eps is not None and sparse:
        raise ValueError("Cannot set 'eps' when sparse=True")
    classes, class_idx = np.unique(labels_true, return_inverse=True)
    clusters, cluster_idx = np.unique(labels_pred, return_inverse=True)
    n_classes = classes.shape[0]
    n_clusters = clusters.shape[0]
    contingency = sp.coo_array((np.ones(class_idx.shape[0]), (class_idx, cluster_idx)), shape=(n_classes, n_clusters), dtype=dtype)
    if sparse:
        contingency = _align_api_if_sparse(contingency)
        contingency = contingency.tocsr()
        contingency.sum_duplicates()
    else:
        contingency = contingency.toarray()
        if eps is not None:
            contingency = contingency + eps
    return contingency

@validate_params({'labels_true': ['array-like'], 'labels_pred': ['array-like']}, prefer_skip_nested_validation=True)
def rand_score(labels_true, labels_pred):
    contingency = pair_confusion_matrix(labels_true, labels_pred)
    numerator = contingency.diagonal().sum()
    denominator = contingency.sum()
    if numerator == denominator or denominator == 0:
        return 1.0
    return float(numerator / denominator)

@validate_params({'labels_true': ['array-like'], 'labels_pred': ['array-like']}, prefer_skip_nested_validation=True)
def adjusted_rand_score(labels_true, labels_pred):
    (tn, fp), (fn, tp) = pair_confusion_matrix(labels_true, labels_pred)
    tn, fp, fn, tp = (int(tn), int(fp), int(fn), int(tp))
    if fn == 0 and fp == 0:
        return 1.0
    return 2.0 * (tp * tn - fn * fp) / ((tp + fn) * (fn + tn) + (tp + fp) * (fp + tn))

@validate_params({'labels_true': ['array-like'], 'labels_pred': ['array-like'], 'beta': [Interval(Real, 0, None, closed='left')]}, prefer_skip_nested_validation=True)
def homogeneity_completeness_v_measure(labels_true, labels_pred, *, beta=1.0):
    labels_true, labels_pred = check_clusterings(labels_true, labels_pred)
    if len(labels_true) == 0:
        return (1.0, 1.0, 1.0)
    entropy_C = _entropy(labels_true)
    entropy_K = _entropy(labels_pred)
    contingency = contingency_matrix(labels_true, labels_pred, sparse=True)
    MI = mutual_info_score(None, None, contingency=contingency)
    homogeneity = MI / entropy_C if entropy_C else 1.0
    completeness = MI / entropy_K if entropy_K else 1.0
    if homogeneity + completeness == 0.0:
        v_measure_score = 0.0
    else:
        v_measure_score = (1 + beta) * homogeneity * completeness / (beta * homogeneity + completeness)
    return (float(homogeneity), float(completeness), float(v_measure_score))

@validate_params({'labels_true': ['array-like'], 'labels_pred': ['array-like']}, prefer_skip_nested_validation=True)
def homogeneity_score(labels_true, labels_pred):
    return homogeneity_completeness_v_measure(labels_true, labels_pred)[0]

@validate_params({'labels_true': ['array-like'], 'labels_pred': ['array-like']}, prefer_skip_nested_validation=True)
def completeness_score(labels_true, labels_pred):
    return homogeneity_completeness_v_measure(labels_true, labels_pred)[1]

@validate_params({'labels_true': ['array-like'], 'labels_pred': ['array-like'], 'beta': [Interval(Real, 0, None, closed='left')]}, prefer_skip_nested_validation=True)
def v_measure_score(labels_true, labels_pred, *, beta=1.0):
    return homogeneity_completeness_v_measure(labels_true, labels_pred, beta=beta)[2]

@validate_params({'labels_true': ['array-like', None], 'labels_pred': ['array-like', None], 'contingency': ['array-like', 'sparse matrix', None]}, prefer_skip_nested_validation=True)
def mutual_info_score(labels_true, labels_pred, *, contingency=None):
    if contingency is None:
        labels_true, labels_pred = check_clusterings(labels_true, labels_pred)
        contingency = contingency_matrix(labels_true, labels_pred, sparse=True)
    else:
        contingency = check_array(contingency, accept_sparse=['csr', 'csc', 'coo'], dtype=[int, np.int32, np.int64])
    if isinstance(contingency, np.ndarray):
        nzx, nzy = np.nonzero(contingency)
        nz_val = contingency[nzx, nzy]
    else:
        nzx, nzy, nz_val = sp.find(contingency)
    contingency_sum = contingency.sum()
    pi = np.ravel(contingency.sum(axis=1))
    pj = np.ravel(contingency.sum(axis=0))
    if pi.size == 1 or pj.size == 1:
        return 0.0
    log_contingency_nm = np.log(nz_val)
    contingency_nm = nz_val / contingency_sum
    outer = pi.take(nzx).astype(np.int64, copy=False) * pj.take(nzy).astype(np.int64, copy=False)
    log_outer = -np.log(outer) + log(pi.sum()) + log(pj.sum())
    mi = contingency_nm * (log_contingency_nm - log(contingency_sum)) + contingency_nm * log_outer
    mi = np.where(np.abs(mi) < np.finfo(mi.dtype).eps, 0.0, mi)
    return float(np.clip(mi.sum(), 0.0, None))

@validate_params({'labels_true': ['array-like'], 'labels_pred': ['array-like'], 'average_method': [StrOptions({'arithmetic', 'max', 'min', 'geometric'})]}, prefer_skip_nested_validation=True)
def adjusted_mutual_info_score(labels_true, labels_pred, *, average_method='arithmetic'):
    labels_true, labels_pred = check_clusterings(labels_true, labels_pred)
    n_samples = labels_true.shape[0]
    classes = np.unique(labels_true)
    clusters = np.unique(labels_pred)
    if classes.shape[0] == clusters.shape[0] == 1 or classes.shape[0] == clusters.shape[0] == 0:
        return 1.0
    elif classes.shape[0] == 1 or clusters.shape[0] == 1:
        return 0.0
    contingency = contingency_matrix(labels_true, labels_pred, sparse=True)
    mi = mutual_info_score(labels_true, labels_pred, contingency=contingency)
    emi = expected_mutual_information(contingency, n_samples)
    h_true, h_pred = (_entropy(labels_true), _entropy(labels_pred))
    normalizer = _generalized_average(h_true, h_pred, average_method)
    denominator = normalizer - emi
    if denominator < 0:
        denominator = min(denominator, -np.finfo('float64').eps)
    else:
        denominator = max(denominator, np.finfo('float64').eps)
    numerator = mi - emi
    if numerator < 0:
        numerator = min(numerator, -np.finfo('float64').eps)
    else:
        numerator = max(numerator, np.finfo('float64').eps)
    return float(numerator / denominator)

@validate_params({'labels_true': ['array-like'], 'labels_pred': ['array-like'], 'average_method': [StrOptions({'arithmetic', 'max', 'min', 'geometric'})]}, prefer_skip_nested_validation=True)
def normalized_mutual_info_score(labels_true, labels_pred, *, average_method='arithmetic'):
    labels_true, labels_pred = check_clusterings(labels_true, labels_pred)
    classes = np.unique(labels_true)
    clusters = np.unique(labels_pred)
    if classes.shape[0] == clusters.shape[0] == 1 or classes.shape[0] == clusters.shape[0] == 0:
        return 1.0
    contingency = contingency_matrix(labels_true, labels_pred, sparse=True)
    contingency = contingency.astype(np.float64, copy=False)
    mi = mutual_info_score(labels_true, labels_pred, contingency=contingency)
    if mi == 0:
        return 0.0
    h_true, h_pred = (_entropy(labels_true), _entropy(labels_pred))
    normalizer = _generalized_average(h_true, h_pred, average_method)
    return float(mi / normalizer)

def _entropy(labels):
    xp, is_array_api_compliant, device_ = get_namespace_and_device(labels)
    labels_len = labels.shape[0] if is_array_api_compliant else len(labels)
    if labels_len == 0:
        return 1.0
    pi = xp.astype(xp.unique_counts(labels)[1], _max_precision_float_dtype(xp, device_))
    if pi.size == 1:
        return 0.0
    pi_sum = xp.sum(pi)
    return float(-xp.sum(pi / pi_sum * (xp.log(pi) - log(pi_sum))))

@deprecated('`entropy` is deprecated in 1.8 and will be removed in 1.10.')
def entropy(labels):
    return _entropy(labels)

def check_number_of_labels(n_labels, n_samples):
    if not 1 < n_labels < n_samples:
        raise ValueError('Number of labels is %d. Valid values are 2 to n_samples - 1 (inclusive)' % n_labels)

@validate_params({'X': ['array-like', 'sparse matrix'], 'labels': ['array-like'], 'metric': [StrOptions(set(_VALID_METRICS) | {'precomputed'}), callable], 'sample_size': [Interval(Integral, 1, None, closed='left'), None], 'random_state': ['random_state']}, prefer_skip_nested_validation=True)
def silhouette_score(X, labels, *, metric='euclidean', sample_size=None, random_state=None, **kwds):
    if sample_size is not None:
        X, labels = check_X_y(X, labels, accept_sparse=['csc', 'csr'])
        random_state = check_random_state(random_state)
        indices = random_state.permutation(X.shape[0])[:sample_size]
        if metric == 'precomputed':
            X, labels = (X[indices].T[indices].T, labels[indices])
        else:
            X, labels = (X[indices], labels[indices])
    return float(np.mean(silhouette_samples(X, labels, metric=metric, **kwds)))

def sqeuclidean_row_norms(X, num_threads):
    if X.dtype == np.float64:
        return np.asarray(_sqeuclidean_row_norms64(X, num_threads))
    if X.dtype == np.float32:
        return np.asarray(_sqeuclidean_row_norms32(X, num_threads))
    raise ValueError(f'Only float64 or float32 datasets are supported at this time, got: X.dtype={X.dtype}.')

@classmethod
def is_usable_for(cls, X, Y, metric) -> bool:
    if issparse(X) and issparse(Y) and isinstance(metric, str) and ('euclidean' in metric):
        return False

    def is_numpy_c_ordered(X):
        return hasattr(X, 'flags') and getattr(X.flags, 'c_contiguous', False)

    def is_valid_sparse_matrix(X):
        return issparse(X) and X.format == 'csr' and (X.nnz > 0) and (X.indices.dtype == X.indptr.dtype == np.int32)
    is_usable = get_config().get('enable_cython_pairwise_dist', True) and (is_numpy_c_ordered(X) or is_valid_sparse_matrix(X)) and (is_numpy_c_ordered(Y) or is_valid_sparse_matrix(Y)) and (X.dtype == Y.dtype) and (X.dtype in (np.float32, np.float64)) and (metric in cls.valid_metrics() or isinstance(metric, DistanceMetric))
    return is_usable

