def plot(self, *, include_values=True, cmap='viridis', xticks_rotation='horizontal', values_format=None, ax=None, colorbar=True, im_kw=None, text_kw=None):
    check_matplotlib_support('ConfusionMatrixDisplay.plot')
    import matplotlib.pyplot as plt
    if ax is None:
        fig, ax = plt.subplots()
    else:
        fig = ax.figure
    cm = self.confusion_matrix
    n_classes = cm.shape[0]
    default_im_kw = dict(interpolation='nearest', cmap=cmap)
    im_kw = im_kw or {}
    im_kw = _validate_style_kwargs(default_im_kw, im_kw)
    text_kw = text_kw or {}
    self.im_ = ax.imshow(cm, **im_kw)
    self.text_ = None
    cmap_min, cmap_max = (self.im_.cmap(0), self.im_.cmap(1.0))
    if include_values:
        self.text_ = np.empty_like(cm, dtype=object)
        thresh = (cm.max() + cm.min()) / 2.0
        for i, j in product(range(n_classes), range(n_classes)):
            color = cmap_max if cm[i, j] < thresh else cmap_min
            if values_format is None:
                text_cm = format(cm[i, j], '.2g')
                if cm.dtype.kind != 'f':
                    text_d = format(cm[i, j], 'd')
                    if len(text_d) < len(text_cm):
                        text_cm = text_d
            else:
                text_cm = format(cm[i, j], values_format)
            default_text_kwargs = dict(ha='center', va='center', color=color)
            text_kwargs = _validate_style_kwargs(default_text_kwargs, text_kw)
            self.text_[i, j] = ax.text(j, i, text_cm, **text_kwargs)
    if self.display_labels is None:
        display_labels = np.arange(n_classes)
    else:
        display_labels = self.display_labels
    if colorbar:
        fig.colorbar(self.im_, ax=ax)
    ax.set(xticks=np.arange(n_classes), yticks=np.arange(n_classes), xticklabels=display_labels, yticklabels=display_labels, ylabel='True label', xlabel='Predicted label')
    ax.set_ylim((n_classes - 0.5, -0.5))
    plt.setp(ax.get_xticklabels(), rotation=xticks_rotation)
    self.figure_ = fig
    self.ax_ = ax
    return self

@classmethod
def from_estimator(cls, estimator, X, y, *, labels=None, sample_weight=None, normalize=None, display_labels=None, include_values=True, xticks_rotation='horizontal', values_format=None, cmap='viridis', ax=None, colorbar=True, im_kw=None, text_kw=None):
    method_name = f'{cls.__name__}.from_estimator'
    check_matplotlib_support(method_name)
    if not is_classifier(estimator):
        raise ValueError(f'{method_name} only supports classifiers')
    y_pred = estimator.predict(X)
    return cls.from_predictions(y, y_pred, sample_weight=sample_weight, labels=labels, normalize=normalize, display_labels=display_labels, include_values=include_values, cmap=cmap, ax=ax, xticks_rotation=xticks_rotation, values_format=values_format, colorbar=colorbar, im_kw=im_kw, text_kw=text_kw)

@classmethod
def from_predictions(cls, y_true, y_pred, *, labels=None, sample_weight=None, normalize=None, display_labels=None, include_values=True, xticks_rotation='horizontal', values_format=None, cmap='viridis', ax=None, colorbar=True, im_kw=None, text_kw=None):
    check_matplotlib_support(f'{cls.__name__}.from_predictions')
    if display_labels is None:
        if labels is None:
            display_labels = unique_labels(y_true, y_pred)
        else:
            display_labels = labels
    cm = confusion_matrix(y_true, y_pred, sample_weight=sample_weight, labels=labels, normalize=normalize)
    disp = cls(confusion_matrix=cm, display_labels=display_labels)
    return disp.plot(include_values=include_values, cmap=cmap, ax=ax, xticks_rotation=xticks_rotation, values_format=values_format, colorbar=colorbar, im_kw=im_kw, text_kw=text_kw)

@classmethod
def from_estimator(cls, estimator, X, y, *, sample_weight=None, drop_intermediate=True, response_method='auto', pos_label=None, name=None, ax=None, **kwargs):
    y_score, pos_label, name = cls._validate_and_get_response_values(estimator, X, y, response_method=response_method, pos_label=pos_label, name=name)
    return cls.from_predictions(y_true=y, y_score=y_score, sample_weight=sample_weight, drop_intermediate=drop_intermediate, name=name, ax=ax, pos_label=pos_label, **kwargs)

@classmethod
def from_predictions(cls, y_true, y_score=None, *, sample_weight=None, drop_intermediate=True, pos_label=None, name=None, ax=None, y_pred='deprecated', **kwargs):
    y_score = _deprecate_y_pred_parameter(y_score, y_pred, '1.8')
    pos_label_validated, name = cls._validate_from_predictions_params(y_true, y_score, sample_weight=sample_weight, pos_label=pos_label, name=name)
    fpr, fnr, _ = det_curve(y_true, y_score, pos_label=pos_label, sample_weight=sample_weight, drop_intermediate=drop_intermediate)
