def plot(self, ax=None, *, name=None, curve_kwargs=None, plot_chance_level=False, chance_level_kw=None, despine=False, **kwargs):
    precision, recall, average_precision, name, prevalence_pos_label = self._validate_plot_params(ax=ax, name=name)
    n_curves = len(precision)
    average_precision, legend_metric = self._get_legend_metric(curve_kwargs, n_curves, average_precision)
    curve_kwargs = self._validate_curve_kwargs(n_curves, name, legend_metric, 'AP', curve_kwargs=curve_kwargs, default_curve_kwargs={'drawstyle': 'steps-post'}, default_multi_curve_kwargs={'alpha': 0.5, 'linestyle': '--', 'color': 'blue'}, removed_version='1.11', **kwargs)
    self.line_ = []
    for recall_val, precision_val, curve_kwarg in zip(recall, precision, curve_kwargs):
        self.line_.extend(self.ax_.plot(recall_val, precision_val, **curve_kwarg))
    if len(self.line_) == 1:
        self.line_ = self.line_[0]
    info_pos_label = f' (Positive label: {self.pos_label})' if self.pos_label is not None else ''
    xlabel = 'Recall' + info_pos_label
    ylabel = 'Precision' + info_pos_label
    self.ax_.set(xlabel=xlabel, xlim=(-0.01, 1.01), ylabel=ylabel, ylim=(-0.01, 1.01), aspect='equal')
    if plot_chance_level:
        if self.prevalence_pos_label is None:
            raise ValueError('You must provide prevalence_pos_label when constructing the PrecisionRecallDisplay object in order to plot the chance level line. Alternatively, you may use PrecisionRecallDisplay.from_estimator or PrecisionRecallDisplay.from_predictions to automatically set prevalence_pos_label')
        default_chance_level_kwargs = {'color': 'k', 'linestyle': '--'}
        if n_curves > 1:
            default_chance_level_kwargs['alpha'] = 0.3
        if chance_level_kw is None:
            chance_level_kw = {}
        chance_level_kw = _validate_style_kwargs(default_chance_level_kwargs, chance_level_kw)
        self.chance_level_ = []
        for prevalence in prevalence_pos_label:
            self.chance_level_.extend(self.ax_.plot((0, 1), (prevalence, prevalence), **chance_level_kw))
        if 'label' not in chance_level_kw:
            label = f'Chance level (AP = {prevalence_pos_label[0]:0.2f})' if n_curves == 1 else f'Chance level (AP = {np.mean(prevalence_pos_label):0.2f} +/- {np.std(prevalence_pos_label):0.2f})'
            self.chance_level_[0].set_label(label)
        if n_curves == 1:
            self.chance_level_ = self.chance_level_[0]
    else:
        self.chance_level_ = None
    if despine:
        _despine(self.ax_)
    if curve_kwargs[0].get('label') is not None or (plot_chance_level and chance_level_kw.get('label') is not None):
        self.ax_.legend(loc='lower left')
    return self

@classmethod
def from_estimator(cls, estimator, X, y, *, sample_weight=None, drop_intermediate=False, response_method='auto', pos_label=None, name=None, ax=None, curve_kwargs=None, plot_chance_level=False, chance_level_kw=None, despine=False, **kwargs):
    y_score, pos_label, name = cls._validate_and_get_response_values(estimator, X, y, response_method=response_method, pos_label=pos_label, name=name)
    return cls.from_predictions(y, y_score, sample_weight=sample_weight, drop_intermediate=drop_intermediate, pos_label=pos_label, name=name, ax=ax, curve_kwargs=curve_kwargs, plot_chance_level=plot_chance_level, chance_level_kw=chance_level_kw, despine=despine, **kwargs)

@classmethod
def from_predictions(cls, y_true, y_score=None, *, sample_weight=None, drop_intermediate=False, pos_label=None, name=None, ax=None, curve_kwargs=None, plot_chance_level=False, chance_level_kw=None, despine=False, y_pred='deprecated', **kwargs):
    y_true = check_array(y_true, ensure_2d=False, dtype=None)
    y_score = _deprecate_y_pred_parameter(y_score, y_pred, '1.8')
    pos_label, name = cls._validate_from_predictions_params(y_true, y_score, sample_weight=sample_weight, pos_label=pos_label, name=name)
    precision, recall, _ = precision_recall_curve(y_true, y_score, pos_label=pos_label, sample_weight=sample_weight, drop_intermediate=drop_intermediate)
    average_precision = average_precision_score(y_true, y_score, pos_label=pos_label, sample_weight=sample_weight)
    prevalence_pos_label = (y_true == pos_label).sum() / len(y_true)
    viz = cls(precision=precision, recall=recall, average_precision=average_precision, name=name, pos_label=pos_label, prevalence_pos_label=prevalence_pos_label)
    return viz.plot(ax=ax, name=name, curve_kwargs=curve_kwargs, plot_chance_level=plot_chance_level, chance_level_kw=chance_level_kw, despine=despine, **kwargs)

def plot(self, ax=None, *, kind='residual_vs_predicted', scatter_kwargs=None, line_kwargs=None):
    check_matplotlib_support(f'{self.__class__.__name__}.plot')
    expected_kind = ('actual_vs_predicted', 'residual_vs_predicted')
    if kind not in expected_kind:
        raise ValueError(f"`kind` must be one of {', '.join(expected_kind)}. Got {kind!r} instead.")
    import matplotlib.pyplot as plt
    if scatter_kwargs is None:
        scatter_kwargs = {}
    if line_kwargs is None:
        line_kwargs = {}
    default_scatter_kwargs = {'color': 'tab:blue', 'alpha': 0.8}
    default_line_kwargs = {'color': 'black', 'alpha': 0.7, 'linestyle': '--'}
    scatter_kwargs = _validate_style_kwargs(default_scatter_kwargs, scatter_kwargs)
    line_kwargs = _validate_style_kwargs(default_line_kwargs, line_kwargs)
    scatter_kwargs = {**default_scatter_kwargs, **scatter_kwargs}
    line_kwargs = {**default_line_kwargs, **line_kwargs}
    if ax is None:
        _, ax = plt.subplots()
    if kind == 'actual_vs_predicted':
        max_value = max(np.max(self.y_true), np.max(self.y_pred))
        min_value = min(np.min(self.y_true), np.min(self.y_pred))
        self.line_ = ax.plot([min_value, max_value], [min_value, max_value], **line_kwargs)[0]
        x_data, y_data = (self.y_pred, self.y_true)
        xlabel, ylabel = ('Predicted values', 'Actual values')
        self.scatter_ = ax.scatter(x_data, y_data, **scatter_kwargs)
        ax.set_aspect('equal', adjustable='datalim')
        ax.set_xticks(np.linspace(min_value, max_value, num=5))
        ax.set_yticks(np.linspace(min_value, max_value, num=5))
    else:
        self.line_ = ax.plot([np.min(self.y_pred), np.max(self.y_pred)], [0, 0], **line_kwargs)[0]
        self.scatter_ = ax.scatter(self.y_pred, self.y_true - self.y_pred, **scatter_kwargs)
        xlabel, ylabel = ('Predicted values', 'Residuals (actual - predicted)')
    ax.set(xlabel=xlabel, ylabel=ylabel)
    self.ax_ = ax
    self.figure_ = ax.figure
    return self

@classmethod
def from_estimator(cls, estimator, X, y, *, kind='residual_vs_predicted', subsample=1000, random_state=None, ax=None, scatter_kwargs=None, line_kwargs=None):
    check_matplotlib_support(f'{cls.__name__}.from_estimator')
    y_pred = estimator.predict(X)
    return cls.from_predictions(y_true=y, y_pred=y_pred, kind=kind, subsample=subsample, random_state=random_state, ax=ax, scatter_kwargs=scatter_kwargs, line_kwargs=line_kwargs)

@classmethod
def from_predictions(cls, y_true, y_pred, *, kind='residual_vs_predicted', subsample=1000, random_state=None, ax=None, scatter_kwargs=None, line_kwargs=None):
    check_matplotlib_support(f'{cls.__name__}.from_predictions')
    random_state = check_random_state(random_state)
    n_samples = len(y_true)
    if isinstance(subsample, numbers.Integral):
        if subsample <= 0:
            raise ValueError(f'When an integer, subsample={subsample} should be positive.')
    elif isinstance(subsample, numbers.Real):
        if subsample <= 0 or subsample >= 1:
            raise ValueError(f'When a floating-point, subsample={subsample} should be in the (0, 1) range.')
        subsample = int(n_samples * subsample)
    if subsample is not None and subsample < n_samples:
        indices = random_state.choice(np.arange(n_samples), size=subsample)
        y_true = _safe_indexing(y_true, indices, axis=0)
        y_pred = _safe_indexing(y_pred, indices, axis=0)
    viz = cls(y_true=y_true, y_pred=y_pred)
    return viz.plot(ax=ax, kind=kind, scatter_kwargs=scatter_kwargs, line_kwargs=line_kwargs)

def plot(self, ax=None, *, name=None, curve_kwargs=None, plot_chance_level=False, chance_level_kw=None, despine=False):
    fpr, tpr, roc_auc, name = self._validate_plot_params(ax=ax, name=name)
    n_curves = len(fpr)
    roc_auc, legend_metric = self._get_legend_metric(curve_kwargs, n_curves, roc_auc)
    curve_kwargs = self._validate_curve_kwargs(n_curves, name, legend_metric, 'AUC', curve_kwargs=curve_kwargs, default_multi_curve_kwargs={'alpha': 0.5, 'linestyle': '--', 'color': 'blue'})
    default_chance_level_line_kw = {'label': 'Chance level (AUC = 0.5)', 'color': 'k', 'linestyle': '--'}
    if chance_level_kw is None:
        chance_level_kw = {}
    chance_level_kw = _validate_style_kwargs(default_chance_level_line_kw, chance_level_kw)
    self.line_ = []
    for fpr, tpr, line_kw in zip(fpr, tpr, curve_kwargs):
        self.line_.extend(self.ax_.plot(fpr, tpr, **line_kw))
    if len(self.line_) == 1:
        self.line_ = self.line_[0]
    info_pos_label = f' (Positive label: {self.pos_label})' if self.pos_label is not None else ''
    xlabel = 'False Positive Rate' + info_pos_label
    ylabel = 'True Positive Rate' + info_pos_label
    self.ax_.set(xlabel=xlabel, xlim=(-0.01, 1.01), ylabel=ylabel, ylim=(-0.01, 1.01), aspect='equal')
    if plot_chance_level:
        self.chance_level_, = self.ax_.plot((0, 1), (0, 1), **chance_level_kw)
    else:
        self.chance_level_ = None
    if despine:
        _despine(self.ax_)
    if curve_kwargs[0].get('label') is not None or (plot_chance_level and chance_level_kw.get('label') is not None):
        self.ax_.legend(loc='lower right')
    return self

