def _check_shape(param, param_shape, name):
    if param.shape != param_shape:
        raise ValueError("The parameter '%s' should have the shape of %s, but got %s" % (name, param_shape, param.shape))

@abstractmethod
def _check_parameters(self, X, xp=None):
    pass

def _initialize_parameters(self, X, random_state, xp=None):
    xp, _, device = get_namespace_and_device(X, xp=xp)
    n_samples, _ = X.shape
    if self.init_params == 'kmeans':
        resp = np.zeros((n_samples, self.n_components), dtype=X.dtype)
        label = cluster.KMeans(n_clusters=self.n_components, n_init=1, random_state=random_state).fit(X).labels_
        resp[np.arange(n_samples), label] = 1
    elif self.init_params == 'random':
        resp = xp.asarray(random_state.uniform(size=(n_samples, self.n_components)), dtype=X.dtype, device=device)
        resp /= xp.sum(resp, axis=1)[:, xp.newaxis]
    elif self.init_params == 'random_from_data':
        resp = xp.zeros((n_samples, self.n_components), dtype=X.dtype, device=device)
        indices = random_state.choice(n_samples, size=self.n_components, replace=False)
        for col, index in enumerate(indices):
            resp[index, col] = 1
    elif self.init_params == 'k-means++':
        resp = np.zeros((n_samples, self.n_components), dtype=X.dtype)
        _, indices = kmeans_plusplus(X, self.n_components, random_state=random_state)
        resp[indices, np.arange(self.n_components)] = 1
    self._initialize(X, resp)

@abstractmethod
def _initialize(self, X, resp):
    pass

def fit(self, X, y=None):
    self.fit_predict(X, y)
    return self

def _e_step(self, X, xp=None):
    xp, _ = get_namespace(X, xp=xp)
    log_prob_norm, log_resp = self._estimate_log_prob_resp(X, xp=xp)
    return (xp.mean(log_prob_norm), log_resp)

@abstractmethod
def _m_step(self, X, log_resp):
    pass

def score_samples(self, X):
    check_is_fitted(self)
    X = validate_data(self, X, reset=False)
    return _logsumexp(self._estimate_weighted_log_prob(X), axis=1)

def score(self, X, y=None):
    xp, _ = get_namespace(X)
    return float(xp.mean(self.score_samples(X)))

def predict(self, X):
    check_is_fitted(self)
    xp, _ = get_namespace(X)
    X = validate_data(self, X, reset=False)
    return xp.argmax(self._estimate_weighted_log_prob(X), axis=1)

def predict_proba(self, X):
    check_is_fitted(self)
    X = validate_data(self, X, reset=False)
    xp, _ = get_namespace(X)
    _, log_resp = self._estimate_log_prob_resp(X, xp=xp)
    return xp.exp(log_resp)

def sample(self, n_samples=1):
    check_is_fitted(self)
    xp, _, device_ = get_namespace_and_device(self.means_)
    if n_samples < 1:
        raise ValueError("Invalid value for 'n_samples': %d . The sampling requires at least one sample." % self.n_components)
    _, n_features = self.means_.shape
    rng = check_random_state(self.random_state)
    n_samples_comp = rng.multinomial(n_samples, move_to(self.weights_, xp=np, device='cpu'))
    if self.covariance_type == 'full':
        X = np.vstack([rng.multivariate_normal(mean, covariance, int(sample)) for mean, covariance, sample in zip(move_to(self.means_, xp=np, device='cpu'), move_to(self.covariances_, xp=np, device='cpu'), n_samples_comp)])
    elif self.covariance_type == 'tied':
        X = np.vstack([rng.multivariate_normal(mean, move_to(self.covariances_, xp=np, device='cpu'), int(sample)) for mean, sample in zip(move_to(self.means_, xp=np, device='cpu'), n_samples_comp)])
    else:
        X = np.vstack([mean + rng.standard_normal(size=(sample, n_features)) * np.sqrt(covariance) for mean, covariance, sample in zip(move_to(self.means_, xp=np, device='cpu'), move_to(self.covariances_, xp=np, device='cpu'), n_samples_comp)])
    y = xp.concat([xp.full(int(n_samples_comp[i]), i, dtype=xp.int64, device=device_) for i in range(len(n_samples_comp))])
    max_float_dtype = _max_precision_float_dtype(xp=xp, device=device_)
    return (xp.asarray(X, dtype=max_float_dtype, device=device_), y)

@abstractmethod
def _estimate_log_weights(self, xp=None):
    pass

@abstractmethod
def _estimate_log_prob(self, X, xp=None):
    pass

def _print_verbose_msg_init_beg(self, n_init):
    if self.verbose == 1:
        print('Initialization %d' % n_init)
    elif self.verbose >= 2:
        print('Initialization %d' % n_init)
        self._init_prev_time = time()
        self._iter_prev_time = self._init_prev_time

def _print_verbose_msg_iter_end(self, n_iter, diff_ll):
    if n_iter % self.verbose_interval == 0:
        if self.verbose == 1:
            print('  Iteration %d' % n_iter)
        elif self.verbose >= 2:
            cur_time = time()
            print('  Iteration %d\t time lapse %.5fs\t ll change %.5f' % (n_iter, cur_time - self._iter_prev_time, diff_ll))
            self._iter_prev_time = cur_time

def _print_verbose_msg_init_end(self, lb, init_has_converged):
    converged_msg = 'converged' if init_has_converged else 'did not converge'
    if self.verbose == 1:
        print(f'Initialization {converged_msg}.')
    elif self.verbose >= 2:
        t = time() - self._init_prev_time
        print(f'Initialization {converged_msg}. time lapse {t:.5f}s\t lower bound {lb:.5f}.')

def _check_weights_parameters(self):
    if self.weight_concentration_prior is None:
        self.weight_concentration_prior_ = 1.0 / self.n_components
    else:
        self.weight_concentration_prior_ = self.weight_concentration_prior

def _check_means_parameters(self, X):
    _, n_features = X.shape
    if self.mean_precision_prior is None:
        self.mean_precision_prior_ = 1.0
    else:
        self.mean_precision_prior_ = self.mean_precision_prior
    if self.mean_prior is None:
        self.mean_prior_ = X.mean(axis=0)
    else:
        self.mean_prior_ = check_array(self.mean_prior, dtype=[np.float64, np.float32], ensure_2d=False)
        _check_shape(self.mean_prior_, (n_features,), 'means')

def _check_precision_parameters(self, X):
    _, n_features = X.shape
    if self.degrees_of_freedom_prior is None:
        self.degrees_of_freedom_prior_ = n_features
    elif self.degrees_of_freedom_prior > n_features - 1.0:
        self.degrees_of_freedom_prior_ = self.degrees_of_freedom_prior
    else:
        raise ValueError("The parameter 'degrees_of_freedom_prior' should be greater than %d, but got %.3f." % (n_features - 1, self.degrees_of_freedom_prior))

def _checkcovariance_prior_parameter(self, X):
    _, n_features = X.shape
    if self.covariance_prior is None:
        self.covariance_prior_ = {'full': np.atleast_2d(np.cov(X.T)), 'tied': np.atleast_2d(np.cov(X.T)), 'diag': np.var(X, axis=0, ddof=1), 'spherical': np.var(X, axis=0, ddof=1).mean()}[self.covariance_type]
    elif self.covariance_type in ['full', 'tied']:
        self.covariance_prior_ = check_array(self.covariance_prior, dtype=[np.float64, np.float32], ensure_2d=False)
        _check_shape(self.covariance_prior_, (n_features, n_features), '%s covariance_prior' % self.covariance_type)
        _check_precision_matrix(self.covariance_prior_, self.covariance_type)
    elif self.covariance_type == 'diag':
        self.covariance_prior_ = check_array(self.covariance_prior, dtype=[np.float64, np.float32], ensure_2d=False)
        _check_shape(self.covariance_prior_, (n_features,), '%s covariance_prior' % self.covariance_type)
        _check_precision_positivity(self.covariance_prior_, self.covariance_type)
    else:
        self.covariance_prior_ = self.covariance_prior

def _estimate_weights(self, nk):
    if self.weight_concentration_prior_type == 'dirichlet_process':
        self.weight_concentration_ = (1.0 + nk, self.weight_concentration_prior_ + np.hstack((np.cumsum(nk[::-1])[-2::-1], 0)))
    else:
        self.weight_concentration_ = self.weight_concentration_prior_ + nk

def _estimate_means(self, nk, xk):
    self.mean_precision_ = self.mean_precision_prior_ + nk
    self.means_ = (self.mean_precision_prior_ * self.mean_prior_ + nk[:, np.newaxis] * xk) / self.mean_precision_[:, np.newaxis]

def _estimate_precisions(self, nk, xk, sk):
    {'full': self._estimate_wishart_full, 'tied': self._estimate_wishart_tied, 'diag': self._estimate_wishart_diag, 'spherical': self._estimate_wishart_spherical}[self.covariance_type](nk, xk, sk)
    self.precisions_cholesky_ = _compute_precision_cholesky(self.covariances_, self.covariance_type)

def _compute_lower_bound(self, log_resp, log_prob_norm):
    n_features, = self.mean_prior_.shape
    log_det_precisions_chol = _compute_log_det_cholesky(self.precisions_cholesky_, self.covariance_type, n_features) - 0.5 * n_features * np.log(self.degrees_of_freedom_)
    if self.covariance_type == 'tied':
        log_wishart = self.n_components * np.float64(_log_wishart_norm(self.degrees_of_freedom_, log_det_precisions_chol, n_features))
    else:
        log_wishart = np.sum(_log_wishart_norm(self.degrees_of_freedom_, log_det_precisions_chol, n_features))
    if self.weight_concentration_prior_type == 'dirichlet_process':
        log_norm_weight = -np.sum(betaln(self.weight_concentration_[0], self.weight_concentration_[1]))
    else:
        log_norm_weight = _log_dirichlet_norm(self.weight_concentration_)
    return -np.sum(np.exp(log_resp) * log_resp) - log_wishart - log_norm_weight - 0.5 * n_features * np.sum(np.log(self.mean_precision_))

def _check_weights(weights, n_components, xp=None):
    weights = check_array(weights, dtype=[xp.float64, xp.float32], ensure_2d=False)
    _check_shape(weights, (n_components,), 'weights')
    if any(xp.less(weights, 0.0)) or any(xp.greater(weights, 1.0)):
        raise ValueError("The parameter 'weights' should be in the range [0, 1], but got max value %.5f, min value %.5f" % (xp.min(weights), xp.max(weights)))
    atol = 1e-06 if weights.dtype == xp.float32 else 1e-08
    if not np.allclose(float(xp.abs(1.0 - xp.sum(weights))), 0.0, atol=atol):
        raise ValueError("The parameter 'weights' should be normalized, but got sum(weights) = %.5f" % xp.sum(weights))
    return weights

def _check_precision_positivity(precision, covariance_type, xp=None):
    xp, _ = get_namespace(precision, xp=xp)
    if xp.any(xp.less_equal(precision, 0.0)):
        raise ValueError("'%s precision' should be positive" % covariance_type)

def _check_precision_matrix(precision, covariance_type, xp=None):
    xp, _ = get_namespace(precision, xp=xp)
    if not (xp.all(xpx.isclose(precision, precision.T)) and xp.all(xp.linalg.eigvalsh(precision) > 0.0)):
        raise ValueError("'%s precision' should be symmetric, positive-definite" % covariance_type)

def _check_precisions_full(precisions, covariance_type, xp=None):
    xp, _ = get_namespace(precisions, xp=xp)
    for i in range(precisions.shape[0]):
        _check_precision_matrix(precisions[i, :, :], covariance_type, xp=xp)

def _check_precisions(precisions, covariance_type, n_components, n_features, xp=None):
    xp, _ = get_namespace(precisions, xp=xp)
    precisions = check_array(precisions, dtype=[xp.float64, xp.float32], ensure_2d=False, allow_nd=covariance_type == 'full')
    precisions_shape = {'full': (n_components, n_features, n_features), 'tied': (n_features, n_features), 'diag': (n_components, n_features), 'spherical': (n_components,)}
    _check_shape(precisions, precisions_shape[covariance_type], '%s precision' % covariance_type)
    _check_precisions = {'full': _check_precisions_full, 'tied': _check_precision_matrix, 'diag': _check_precision_positivity, 'spherical': _check_precision_positivity}
    _check_precisions[covariance_type](precisions, covariance_type, xp=xp)
    return precisions

def _estimate_gaussian_covariances_spherical(resp, X, nk, means, reg_covar, xp=None):
    xp, _ = get_namespace(X)
    return xp.mean(_estimate_gaussian_covariances_diag(resp, X, nk, means, reg_covar, xp=xp), axis=1)

def _estimate_gaussian_parameters(X, resp, reg_covar, covariance_type, xp=None):
    xp, _ = get_namespace(X, xp=xp)
    nk = xp.sum(resp, axis=0) + 10 * xp.finfo(resp.dtype).eps
    means = resp.T @ X / nk[:, xp.newaxis]
    covariances = {'full': _estimate_gaussian_covariances_full, 'tied': _estimate_gaussian_covariances_tied, 'diag': _estimate_gaussian_covariances_diag, 'spherical': _estimate_gaussian_covariances_spherical}[covariance_type](resp, X, nk, means, reg_covar, xp=xp)
    return (nk, means, covariances)

def _compute_precision_cholesky(covariances, covariance_type, xp=None):
    xp, _, device_ = get_namespace_and_device(covariances, xp=xp)
    estimate_precision_error_message = 'Fitting the mixture model failed because some components have ill-defined empirical covariance (for instance caused by singleton or collapsed samples). Try to decrease the number of components, increase reg_covar, or scale the input data.'
    dtype = covariances.dtype
    if dtype == xp.float32:
        estimate_precision_error_message += ' The numerical accuracy can also be improved by passing float64 data instead of float32.'
    if covariance_type == 'full':
        n_components, n_features, _ = covariances.shape
        precisions_chol = xp.empty((n_components, n_features, n_features), device=device_, dtype=dtype)
        for k in range(covariances.shape[0]):
            covariance = covariances[k, :, :]
            try:
                cov_chol = _cholesky(covariance, xp)
            except np.linalg.LinAlgError:
                raise ValueError(estimate_precision_error_message)
            precisions_chol[k, :, :] = _linalg_solve(cov_chol, xp.eye(n_features, dtype=dtype, device=device_), xp).T
    elif covariance_type == 'tied':
        _, n_features = covariances.shape
        try:
            cov_chol = _cholesky(covariances, xp)
        except np.linalg.LinAlgError:
            raise ValueError(estimate_precision_error_message)
        precisions_chol = _linalg_solve(cov_chol, xp.eye(n_features, dtype=dtype, device=device_), xp).T
    else:
        if xp.any(covariances <= 0.0):
            raise ValueError(estimate_precision_error_message)
        precisions_chol = 1.0 / xp.sqrt(covariances)
    return precisions_chol

def _flipudlr(array, xp=None):
    xp, _ = get_namespace(array, xp=xp)
    return xp.flip(xp.flip(array, axis=1), axis=0)

def _compute_precision_cholesky_from_precisions(precisions, covariance_type, xp=None):
    if covariance_type == 'full':
        precisions_cholesky = xp.stack([_flipudlr(_cholesky(_flipudlr(precisions[i, :, :], xp=xp), xp=xp), xp=xp) for i in range(precisions.shape[0])])
    elif covariance_type == 'tied':
        precisions_cholesky = _flipudlr(_cholesky(_flipudlr(precisions, xp=xp), xp=xp), xp=xp)
    else:
        precisions_cholesky = xp.sqrt(precisions)
    return precisions_cholesky

def _compute_log_det_cholesky(matrix_chol, covariance_type, n_features, xp=None):
    xp, _ = get_namespace(matrix_chol, xp=xp)
    if covariance_type == 'full':
        n_components, _, _ = matrix_chol.shape
        log_det_chol = xp.sum(xp.log(xp.reshape(matrix_chol, (n_components, -1))[:, ::n_features + 1]), axis=1)
    elif covariance_type == 'tied':
        log_det_chol = xp.sum(xp.log(xp.linalg.diagonal(matrix_chol)))
    elif covariance_type == 'diag':
        log_det_chol = xp.sum(xp.log(matrix_chol), axis=1)
    else:
        log_det_chol = n_features * xp.log(matrix_chol)
    return log_det_chol

def _check_parameters(self, X, xp=None):
    _, n_features = X.shape
    if self.weights_init is not None:
        self.weights_init = _check_weights(self.weights_init, self.n_components, xp=xp)
    if self.means_init is not None:
        self.means_init = _check_means(self.means_init, self.n_components, n_features, xp=xp)
    if self.precisions_init is not None:
        self.precisions_init = _check_precisions(self.precisions_init, self.covariance_type, self.n_components, n_features, xp=xp)
    allowed_init_params = ['random', 'random_from_data']
    if get_config()['array_api_dispatch'] and self.init_params not in allowed_init_params:
        raise NotImplementedError(f"Allowed `init_params` are {allowed_init_params} if 'array_api_dispatch' is enabled. You passed init_params={self.init_params!r}, which are not implemented to work with 'array_api_dispatch' enabled. Please disable 'array_api_dispatch' to use init_params={self.init_params!r}.")

def _initialize(self, X, resp, xp=None):
    xp, _, device_ = get_namespace_and_device(X, xp=xp)
    n_samples, _ = X.shape
    weights, means, covariances = (None, None, None)
    if resp is not None:
        weights, means, covariances = _estimate_gaussian_parameters(X, resp, self.reg_covar, self.covariance_type, xp=xp)
        if self.weights_init is None:
            weights /= n_samples
    self.weights_ = weights if self.weights_init is None else self.weights_init
    self.weights_ = xp.asarray(self.weights_, device=device_)
    self.means_ = means if self.means_init is None else self.means_init
    if self.precisions_init is None:
        self.covariances_ = covariances
        self.precisions_cholesky_ = _compute_precision_cholesky(covariances, self.covariance_type, xp=xp)
    else:
        self.precisions_cholesky_ = _compute_precision_cholesky_from_precisions(self.precisions_init, self.covariance_type, xp=xp)

def _n_parameters(self):
    _, n_features = self.means_.shape
    if self.covariance_type == 'full':
        cov_params = self.n_components * n_features * (n_features + 1) / 2.0
    elif self.covariance_type == 'diag':
        cov_params = self.n_components * n_features
    elif self.covariance_type == 'tied':
        cov_params = n_features * (n_features + 1) / 2.0
    elif self.covariance_type == 'spherical':
        cov_params = self.n_components
    mean_params = n_features * self.n_components
    return int(cov_params + mean_params + self.n_components - 1)

def _fit_and_score_over_thresholds(classifier, X, y, *, fit_params, train_idx, val_idx, curve_scorer, score_params):
    if train_idx is not None:
        X_train, X_val = (_safe_indexing(X, train_idx), _safe_indexing(X, val_idx))
        y_train, y_val = (_safe_indexing(y, train_idx), _safe_indexing(y, val_idx))
        fit_params_train = _check_method_params(X, fit_params, indices=train_idx)
        score_params_val = _check_method_params(X, score_params, indices=val_idx)
        classifier.fit(X_train, y_train, **fit_params_train)
    else:
        X_val, y_val, score_params_val = (X, y, score_params)
    return curve_scorer(classifier, X_val, y_val, **score_params_val)

def _get_response_method(self):
    if self.response_method == 'auto':
        response_method = ['predict_proba', 'decision_function']
    else:
