def get_metadata_routing(self):
    router = MetadataRouter(owner=self).add(estimator=self.estimator, method_mapping=MethodMapping().add(callee='fit', caller='fit'))
    return router

def _fit(self, X, y, **params):
    if isinstance(self.cv, Real) and 0 < self.cv < 1:
        cv = StratifiedShuffleSplit(n_splits=1, test_size=self.cv, random_state=self.random_state)
    elif self.cv == 'prefit':
        if self.refit is True:
            raise ValueError("When cv='prefit', refit cannot be True.")
        try:
            check_is_fitted(self.estimator, 'classes_')
        except NotFittedError as exc:
            raise NotFittedError("When cv='prefit', `estimator` must be fitted.") from exc
        cv = self.cv
    else:
        cv = check_cv(self.cv, y=y, classifier=True)
        if self.refit is False and cv.get_n_splits() > 1:
            raise ValueError('When cv has several folds, refit cannot be False.')
    routed_params = process_routing(self, 'fit', **params)
    self._curve_scorer = self._get_curve_scorer()
    if cv == 'prefit':
        self.estimator_ = self.estimator
        classifier = self.estimator_
        splits = [(None, range(_num_samples(X)))]
    else:
        self.estimator_ = clone(self.estimator)
        classifier = clone(self.estimator)
        splits = cv.split(X, y, **routed_params.splitter.split)
        if self.refit:
            X_train, y_train, fit_params_train = (X, y, routed_params.estimator.fit)
        else:
            train_idx, _ = next(cv.split(X, y, **routed_params.splitter.split))
            X_train = _safe_indexing(X, train_idx)
            y_train = _safe_indexing(y, train_idx)
            fit_params_train = _check_method_params(X, routed_params.estimator.fit, indices=train_idx)
        self.estimator_.fit(X_train, y_train, **fit_params_train)
    cv_scores, cv_thresholds = zip(*Parallel(n_jobs=self.n_jobs)((delayed(_fit_and_score_over_thresholds)(clone(classifier) if cv != 'prefit' else classifier, X, y, fit_params=routed_params.estimator.fit, train_idx=train_idx, val_idx=val_idx, curve_scorer=self._curve_scorer, score_params=routed_params.scorer.score) for train_idx, val_idx in splits)))
    if any((np.isclose(th[0], th[-1]) for th in cv_thresholds)):
        raise ValueError('The provided estimator makes constant predictions. Therefore, it is impossible to optimize the decision threshold.')
    min_threshold = min((split_thresholds.min() for split_thresholds in cv_thresholds))
    max_threshold = max((split_thresholds.max() for split_thresholds in cv_thresholds))
    if isinstance(self.thresholds, Integral):
        decision_thresholds = np.linspace(min_threshold, max_threshold, num=self.thresholds)
    else:
        decision_thresholds = np.asarray(self.thresholds)
    objective_scores = _mean_interpolated_score(decision_thresholds, cv_thresholds, cv_scores)
    best_idx = objective_scores.argmax()
    self.best_score_ = objective_scores[best_idx]
    self.best_threshold_ = decision_thresholds[best_idx]
    if self.store_cv_results:
        self.cv_results_ = {'thresholds': decision_thresholds, 'scores': objective_scores}
    return self

def predict(self, X):
    check_is_fitted(self, 'estimator_')
    pos_label = self._curve_scorer._get_pos_label()
    y_score, _ = _get_response_values_binary(self.estimator_, X, self._get_response_method(), pos_label=pos_label)
    return _threshold_scores_to_class_labels(y_score, self.best_threshold_, self.classes_, pos_label)

def get_metadata_routing(self):
    router = MetadataRouter(owner=self).add(estimator=self.estimator, method_mapping=MethodMapping().add(callee='fit', caller='fit')).add(splitter=self.cv, method_mapping=MethodMapping().add(callee='split', caller='fit')).add(scorer=self._get_curve_scorer(), method_mapping=MethodMapping().add(callee='score', caller='fit'))
    return router

def _search_estimator_has(attr):

    def check(self):
        _check_refit(self, attr)
        if hasattr(self, 'best_estimator_'):
            getattr(self.best_estimator_, attr)
            return True
        getattr(self.estimator, attr)
        return True
    return check

def _yield_masked_array_for_each_param(candidate_params):
    n_candidates = len(candidate_params)
    param_results = defaultdict(dict)
    for cand_idx, params in enumerate(candidate_params):
        for name, value in params.items():
            param_results['param_%s' % name][cand_idx] = value
    for key, param_result in param_results.items():
        param_list = list(param_result.values())
        try:
            arr = np.array(param_list)
        except ValueError:
            arr_dtype = np.dtype(object)
        else:
            arr_dtype = arr.dtype if arr.dtype.kind != 'U' and arr.ndim == 1 else object
        ma = MaskedArray(np.empty(n_candidates, dtype=arr_dtype), mask=True)
        for index, value in param_result.items():
            ma[index] = value
        yield (key, ma)

def __iter__(self):
    for p in self.param_grid:
        items = sorted(p.items())
        if not items:
            yield {}
        else:
            keys, values = zip(*items)
            for v in product(*values):
                params = dict(zip(keys, v))
                yield params

def __len__(self):
    product = partial(reduce, operator.mul)
    return sum((product((len(v) for v in p.values())) if p else 1 for p in self.param_grid))

def __getitem__(self, ind):
    for sub_grid in self.param_grid:
        if not sub_grid:
            if ind == 0:
                return {}
            else:
                ind -= 1
                continue
        keys, values_lists = zip(*sorted(sub_grid.items())[::-1])
        sizes = [len(v_list) for v_list in values_lists]
        total = np.prod(sizes)
        if ind >= total:
            ind -= total
        else:
            out = {}
            for key, v_list, n in zip(keys, values_lists, sizes):
                ind, offset = divmod(ind, n)
                out[key] = v_list[offset]
            return out
    raise IndexError('ParameterGrid index out of range')

def __len__(self):
    if self._is_all_lists():
        grid_size = len(ParameterGrid(self.param_distributions))
        return min(self.n_iter, grid_size)
    else:
        return self.n_iter

def score(self, X, y=None, **params):
    _check_refit(self, 'score')
    check_is_fitted(self)
    _raise_for_params(params, self, 'score')
    if _routing_enabled():
        score_params = process_routing(self, 'score', **params).scorer['score']
    else:
        score_params = dict()
    if self.scorer_ is None:
        raise ValueError("No score function explicitly defined, and the estimator doesn't provide one %s" % self.best_estimator_)
    if isinstance(self.scorer_, dict):
        if self.multimetric_:
            scorer = self.scorer_[self.refit]
        else:
            scorer = self.scorer_
        return scorer(self.best_estimator_, X, y, **score_params)
    score = self.scorer_(self.best_estimator_, X, y, **score_params)
    if self.multimetric_:
        score = score[self.refit]
    return score

def _wrap_namespace_error(self, method_name, call, *args, **kwargs):
    try:
        return call(*args, **kwargs)
    except ValueError as e:
        if 'must use the same namespace' not in str(e):
            raise
        inner_class = self.best_estimator_.__class__.__name__
        outer_class = self.__class__.__name__
        msg = str(e)
        msg = re.sub(f'{re.escape(inner_class)}\\.\\w+\\(\\)', f'{outer_class}.{method_name}()', msg)
        raise ValueError(msg) from None

