def _check_refit_for_multimetric(self, scores):
    multimetric_refit_msg = f'For multi-metric scoring, the parameter refit must be set to a scorer key or a callable to refit an estimator with the best parameter setting on the whole data and make the best_* attributes available for that metric. If this is not needed, refit should be set to False explicitly. {self.refit!r} was passed.'
    valid_refit_dict = isinstance(self.refit, str) and self.refit in scores
    if self.refit is not False and (not valid_refit_dict) and (not callable(self.refit)):
        raise ValueError(multimetric_refit_msg)

@staticmethod
def _select_best_index(refit, refit_metric, results):
    if callable(refit):
        best_index = refit(results)
        if not isinstance(best_index, numbers.Integral):
            raise TypeError('best_index_ returned is not an integer')
        if best_index < 0 or best_index >= len(results['params']):
            raise IndexError('best_index_ index out of range')
    else:
        best_index = results[f'rank_test_{refit_metric}'].argmin()
    return best_index

def _get_scorers(self):
    refit_metric = 'score'
    if callable(self.scoring):
        scorers = self.scoring
    elif self.scoring is None or isinstance(self.scoring, str):
        scorers = check_scoring(self.estimator, self.scoring)
    else:
        scorers = _check_multimetric_scoring(self.estimator, self.scoring)
        self._check_refit_for_multimetric(scorers)
        refit_metric = self.refit
        scorers = _MultimetricScorer(scorers=scorers, raise_exc=self.error_score == 'raise')
    return (scorers, refit_metric)

def _get_routed_params_for_fit(self, params):
    if _routing_enabled():
        routed_params = process_routing(self, 'fit', **params)
    else:
        params = params.copy()
        groups = params.pop('groups', None)
        score_kwargs = {}
        if params.get('sample_weight') is not None and self._check_scorers_accept_sample_weight():
            score_kwargs['sample_weight'] = params['sample_weight']
        routed_params = _manual_routing({'estimator': {'fit': params}, 'splitter': {'split': {'groups': groups}}, 'scorer': {'score': score_kwargs}})
    return routed_params

def _store(key_name, array, weights=None, splits=False, rank=False):
    array = np.array(array, dtype=np.float64).reshape(n_candidates, n_splits)
    if splits:
        for split_idx in range(n_splits):
            results['split%d_%s' % (split_idx, key_name)] = array[:, split_idx]
    array_means = np.average(array, axis=1, weights=weights)
    results['mean_%s' % key_name] = array_means
    if key_name.startswith(('train_', 'test_')) and np.any(~np.isfinite(array_means)):
        warnings.warn(f"One or more of the {key_name.split('_')[0]} scores are non-finite: {array_means}", category=UserWarning)
    array_stds = np.sqrt(np.average((array - array_means[:, np.newaxis]) ** 2, axis=1, weights=weights))
    results['std_%s' % key_name] = array_stds
    if rank:
        if np.isnan(array_means).all():
            rank_result = np.ones_like(array_means, dtype=np.int32)
        else:
            min_array_means = np.nanmin(array_means) - 1
            array_means = xpx.nan_to_num(array_means, fill_value=min_array_means)
            rank_result = rankdata(-array_means, method='min').astype(np.int32, copy=False)
        results['rank_%s' % key_name] = rank_result

def _trim_cv_results_to_last_iter(results, best_index):
    last_iter_indices = np.flatnonzero(results['iter'] == np.max(results['iter']))
    start = int(last_iter_indices[0])
    trimmed = {key: value[start:] for key, value in results.items()}
    mean_test_score = trimmed['mean_test_score']
    if np.isnan(mean_test_score).all():
        rank_result = np.ones_like(mean_test_score, dtype=np.int32)
    else:
        min_array_means = np.nanmin(mean_test_score) - 1
        scores_for_rank = xpx.nan_to_num(mean_test_score, fill_value=min_array_means)
        rank_result = rankdata(-scores_for_rank, method='min').astype(np.int32, copy=False)
    trimmed['rank_test_score'] = rank_result
    new_best_index = best_index - start
    return (trimmed, new_best_index)

@staticmethod
def _select_best_index(refit, refit_metric, results):
    last_iter = np.max(results['iter'])
    last_iter_indices = np.flatnonzero(results['iter'] == last_iter)
    test_scores = results['mean_test_score'][last_iter_indices]
    if np.isnan(test_scores).all():
        best_idx = 0
    else:
        best_idx = np.nanargmax(test_scores)
    return last_iter_indices[best_idx]

@_fit_context(prefer_skip_nested_validation=False)
def fit(self, X, y=None, **params):
    self._n_samples_orig = _num_samples(X)
    super().fit(X, y=y, **params)
    self.all_cv_results_ = {key: value for key, value in self.cv_results_.items() if key != 'rank_test_score'}
    self.cv_results_, self.best_index_ = _trim_cv_results_to_last_iter(self.all_cv_results_, self.best_index_)
    self.best_score_ = self.cv_results_['mean_test_score'][self.best_index_]
    return self

def _validate_shuffle_split(n_samples, test_size, train_size, default_test_size=None):
    if test_size is None and train_size is None:
        test_size = default_test_size
    test_size_type = np.asarray(test_size).dtype.kind
    train_size_type = np.asarray(train_size).dtype.kind
    if test_size_type == 'i' and (test_size >= n_samples or test_size <= 0) or (test_size_type == 'f' and (test_size <= 0 or test_size >= 1)):
        raise ValueError('test_size={0} should be either positive and smaller than the number of samples {1} or a float in the (0, 1) range'.format(test_size, n_samples))
    if train_size_type == 'i' and (train_size >= n_samples or train_size <= 0) or (train_size_type == 'f' and (train_size <= 0 or train_size >= 1)):
        raise ValueError('train_size={0} should be either positive and smaller than the number of samples {1} or a float in the (0, 1) range'.format(train_size, n_samples))
    if train_size is not None and train_size_type not in ('i', 'f'):
        raise ValueError('Invalid value for train_size: {}'.format(train_size))
    if test_size is not None and test_size_type not in ('i', 'f'):
        raise ValueError('Invalid value for test_size: {}'.format(test_size))
    if train_size_type == 'f' and test_size_type == 'f' and (train_size + test_size > 1):
        raise ValueError('The sum of test_size and train_size = {}, should be in the (0, 1) range. Reduce test_size and/or train_size.'.format(train_size + test_size))
    if test_size_type == 'f':
        n_test = ceil(test_size * n_samples)
    elif test_size_type == 'i':
        n_test = float(test_size)
    if train_size_type == 'f':
        n_train = floor(train_size * n_samples)
    elif train_size_type == 'i':
        n_train = float(train_size)
    if train_size is None:
        n_train = n_samples - n_test
    elif test_size is None:
        n_test = n_samples - n_train
    if n_train + n_test > n_samples:
        raise ValueError('The sum of train_size and test_size = %d, should be smaller than the number of samples %d. Reduce test_size and/or train_size.' % (n_train + n_test, n_samples))
    n_train, n_test = (int(n_train), int(n_test))
    if n_train == 0:
