            return StratifiedKFold(cv, shuffle=shuffle, random_state=random_state)
        else:
            return KFold(cv, shuffle=shuffle, random_state=random_state)
    if not hasattr(cv, 'split') or isinstance(cv, str):
        if not isinstance(cv, Iterable) or isinstance(cv, str):
            raise ValueError(f'Expected `cv` as an integer, a cross-validation object (from sklearn.model_selection), or an iterable yielding (train, test) splits as arrays of indices. Got {cv}.')
