def _fit_and_score(estimator, X, y, *, scorer, train, test, verbose, parameters, fit_params, score_params, return_train_score=False, return_parameters=False, return_n_test_samples=False, return_times=False, return_estimator=False, split_progress=None, candidate_progress=None, error_score=np.nan, caller=None, callback_ctx=None):
    xp, _ = get_namespace(X)
    X_device = device(X)
    train, test = (xp.asarray(train, device=X_device), xp.asarray(test, device=X_device))
    if not isinstance(error_score, numbers.Number) and error_score != 'raise':
        raise ValueError("error_score must be the string 'raise' or a numeric value. (Hint: if using 'raise', please make sure that it has been spelled correctly.)")
    progress_msg = ''
    if verbose > 2:
        if split_progress is not None:
            progress_msg = f' {split_progress[0] + 1}/{split_progress[1]}'
        if candidate_progress and verbose > 9:
            progress_msg += f'; {candidate_progress[0] + 1}/{candidate_progress[1]}'
    if verbose > 1:
        if parameters is None:
            params_msg = ''
        else:
            sorted_keys = sorted(parameters)
            params_msg = ', '.join((f'{k}={parameters[k]}' for k in sorted_keys))
    if verbose > 9:
        start_msg = f'[CV{progress_msg}] START {params_msg}'
        print(f"{start_msg}{(80 - len(start_msg)) * '.'}")
    fit_params = fit_params if fit_params is not None else {}
    fit_params = _check_method_params(X, params=fit_params, indices=train)
    score_params = score_params if score_params is not None else {}
    score_params_train = _check_method_params(X, params=score_params, indices=train)
    score_params_test = _check_method_params(X, params=score_params, indices=test)
    if parameters is not None:
        estimator = estimator.set_params(**clone(parameters, safe=False))
    start_time = time.time()
    X_train, y_train = _safe_split(estimator, X, y, train)
    X_test, y_test = _safe_split(estimator, X, y, test, train)
    if (sample_weight := fit_params.get('sample_weight')) is not None:
        metadata_callbacks = {'sample_weight': sample_weight}
    else:
        metadata_callbacks = None
    result = {}
    try:
        if callback_ctx is not None:
            with callback_ctx.propagate_callback_context(estimator):
                callback_ctx.call_on_fit_task_begin(estimator=caller, X=X_train, y=y_train, metadata=metadata_callbacks)
                if y_train is None:
                    estimator.fit(X_train, **fit_params)
                else:
                    estimator.fit(X_train, y_train, **fit_params)
        elif y_train is None:
            estimator.fit(X_train, **fit_params)
        else:
            estimator.fit(X_train, y_train, **fit_params)
    except Exception:
        fit_time = time.time() - start_time
        score_time = 0.0
        if error_score == 'raise':
            raise
        elif isinstance(error_score, numbers.Number):
            if isinstance(scorer, _MultimetricScorer):
                test_scores = {name: error_score for name in scorer._scorers}
                if return_train_score:
                    train_scores = test_scores.copy()
            else:
                test_scores = error_score
                if return_train_score:
                    train_scores = error_score
        result['fit_error'] = format_exc()
    else:
        result['fit_error'] = None
        fit_time = time.time() - start_time
        test_scores = _score(estimator, X_test, y_test, scorer, score_params_test, error_score)
        score_time = time.time() - start_time - fit_time
        if return_train_score:
            train_scores = _score(estimator, X_train, y_train, scorer, score_params_train, error_score)
    finally:
        if callback_ctx is not None:
            callback_ctx.call_on_fit_task_end(estimator=caller, X=X_train, y=y_train, metadata=metadata_callbacks)
    if verbose > 1:
        total_time = score_time + fit_time
        end_msg = f'[CV{progress_msg}] END '
        result_msg = params_msg + (';' if params_msg else '')
        if verbose > 2:
            if isinstance(test_scores, dict):
                for scorer_name in sorted(test_scores):
                    result_msg += f' {scorer_name}: ('
                    if return_train_score:
                        scorer_scores = train_scores[scorer_name]
                        result_msg += f'train={scorer_scores:.3f}, '
                    result_msg += f'test={test_scores[scorer_name]:.3f})'
            else:
                result_msg += ', score='
                if return_train_score:
                    result_msg += f'(train={train_scores:.3f}, test={test_scores:.3f})'
                else:
                    result_msg += f'{test_scores:.3f}'
        result_msg += f' total time={logger.short_format_time(total_time)}'
        end_msg += '.' * (80 - len(end_msg) - len(result_msg))
        end_msg += result_msg
        print(end_msg)
    result['test_scores'] = test_scores
    if return_train_score:
        result['train_scores'] = train_scores
    if return_n_test_samples:
        result['n_test_samples'] = _num_samples(X_test)
    if return_times:
        result['fit_time'] = fit_time
        result['score_time'] = score_time
    if return_parameters:
        result['parameters'] = parameters
    if return_estimator:
        result['estimator'] = estimator
    return result

def _score(estimator, X_test, y_test, scorer, score_params, error_score='raise'):
    score_params = {} if score_params is None else score_params
    try:
        if y_test is None:
            scores = scorer(estimator, X_test, **score_params)
        else:
            scores = scorer(estimator, X_test, y_test, **score_params)
    except Exception:
        if isinstance(scorer, _MultimetricScorer):
            raise
        elif error_score == 'raise':
            raise
        else:
            scores = error_score
            warnings.warn(f'Scoring failed. The score on this train-test partition for these parameters will be set to {error_score}. Details: \n{format_exc()}', UserWarning)
    if isinstance(scorer, _MultimetricScorer):
        exception_messages = [(name, str_e) for name, str_e in scores.items() if isinstance(str_e, str)]
        if exception_messages:
            for name, str_e in exception_messages:
                scores[name] = error_score
                warnings.warn(f'Scoring failed. The score on this train-test partition for these parameters will be set to {error_score}. Details: \n{str_e}', UserWarning)
    error_msg = 'scoring must return a number, got %s (%s) instead. (scorer=%s)'
    if isinstance(scores, dict):
        for name, score in scores.items():
            if hasattr(score, 'item'):
                with suppress(ValueError):
                    score = score.item()
            if not isinstance(score, numbers.Number):
                raise ValueError(error_msg % (score, type(score), name))
            scores[name] = score
    else:
        if hasattr(scores, 'item'):
            with suppress(ValueError):
                scores = scores.item()
        if not isinstance(scores, numbers.Number):
            raise ValueError(error_msg % (scores, type(scores), scorer))
    return scores

