        return [p[inv_test_indices] for p in predictions]
    elif is_array_api:
        return xp.take(predictions, inv_test_indices, axis=0)
    else:
        return predictions[inv_test_indices]

def _fit_and_predict(estimator, X, y, train, test, fit_params, method):
    fit_params = fit_params if fit_params is not None else {}
    fit_params = _check_method_params(X, params=fit_params, indices=train)
    X_train, y_train = _safe_split(estimator, X, y, train)
    X_test, _ = _safe_split(estimator, X, y, test, train)
    if y_train is None:
        estimator.fit(X_train, **fit_params)
    else:
        estimator.fit(X_train, y_train, **fit_params)
    func = getattr(estimator, method)
    predictions = func(X_test)
    encode = method in ['decision_function', 'predict_proba', 'predict_log_proba'] and y is not None
    if encode:
        if isinstance(predictions, list):
            predictions = [_enforce_prediction_order(estimator.classes_[i_label], predictions[i_label], n_classes=len(set(y[:, i_label])), method=method) for i_label in range(len(predictions))]
        else:
            xp, _ = get_namespace(X, y)
            n_classes = len(set(move_to(y, xp=np, device='cpu'))) if y.ndim == 1 else y.shape[1]
            predictions = _enforce_prediction_order(estimator.classes_, predictions, n_classes, method)
    return predictions

def _enforce_prediction_order(classes, predictions, n_classes, method):
    xp, _ = get_namespace(predictions, classes)
    classes_length = classes.shape[0]
    if n_classes != classes_length:
        recommendation = 'To fix this, use a cross-validation technique resulting in properly stratified folds'
        warnings.warn('Number of classes in training fold ({}) does not match total number of classes ({}). Results may not be appropriate for your use case. {}'.format(classes_length, n_classes, recommendation), RuntimeWarning)
        if method == 'decision_function':
            if predictions.ndim == 2 and predictions.shape[1] != classes_length:
                raise ValueError('Output shape {} of {} does not match number of classes ({}) in fold. Irregular decision_function outputs are not currently supported by cross_val_predict'.format(predictions.shape, method, classes_length))
            if classes_length <= 2:
                raise ValueError('Only {} class/es in training fold, but {} in overall dataset. This is not supported for decision_function with imbalanced folds. {}'.format(classes_length, n_classes, recommendation))
        float_min = xp.finfo(predictions.dtype).min
        default_values = {'decision_function': float_min, 'predict_log_proba': float_min, 'predict_proba': 0}
        predictions_for_all_classes = xp.full((_num_samples(predictions), n_classes), default_values[method], dtype=predictions.dtype)
        predictions_for_all_classes[:, classes] = predictions
        predictions = predictions_for_all_classes
    return predictions

def _check_is_permutation(indices, n_samples):
    if len(indices) != n_samples:
        return False
    hit = np.zeros(n_samples, dtype=bool)
    hit[indices] = True
    if not np.all(hit):
        return False
    return True

@validate_params({'estimator': [HasMethods('fit')], 'X': ['array-like', 'sparse matrix'], 'y': ['array-like', None], 'groups': ['array-like', None], 'cv': ['cv_object'], 'n_permutations': [Interval(Integral, 1, None, closed='left')], 'n_jobs': [Integral, None], 'random_state': ['random_state'], 'verbose': ['verbose'], 'scoring': [StrOptions(set(get_scorer_names())), callable, None], 'params': [dict, None]}, prefer_skip_nested_validation=False)
def permutation_test_score(estimator, X, y, *, groups=None, cv=None, n_permutations=100, n_jobs=None, random_state=0, verbose=0, scoring=None, params=None):
    _check_groups_routing_disabled(groups)
    params = {} if params is None else params
    X, y, groups = indexable(X, y, groups)
    cv = check_cv(cv, y, classifier=is_classifier(estimator))
    scorer = check_scoring(estimator, scoring=scoring)
    random_state = check_random_state(random_state)
    if _routing_enabled():
        router = MetadataRouter(owner='permutation_test_score').add(estimator=estimator, method_mapping=MethodMapping().add(caller='fit', callee='fit')).add(splitter=cv, method_mapping=MethodMapping().add(caller='fit', callee='split')).add(scorer=scorer, method_mapping=MethodMapping().add(caller='fit', callee='score'))
        try:
            routed_params = process_routing(router, 'fit', **params)
        except UnsetMetadataPassedError as e:
            raise UnsetMetadataPassedError(message=str(e).replace('permutation_test_score.fit', 'permutation_test_score'), unrequested_params=e.unrequested_params, routed_params=e.routed_params)
    else:
        routed_params = _manual_routing({'estimator': {'fit': params}, 'splitter': {'split': {'groups': groups}}, 'scorer': {}})
    score = _permutation_test_score(clone(estimator), X, y, cv, scorer, split_params=routed_params.splitter.split, fit_params=routed_params.estimator.fit, score_params=routed_params.scorer.score)
    permutation_scores = Parallel(n_jobs=n_jobs, verbose=verbose)((delayed(_permutation_test_score)(clone(estimator), X, _shuffle(y, groups, random_state), cv, scorer, split_params=routed_params.splitter.split, fit_params=routed_params.estimator.fit, score_params=routed_params.scorer.score) for _ in range(n_permutations)))
    permutation_scores = np.array(permutation_scores)
    pvalue = (np.sum(permutation_scores >= score) + 1.0) / (n_permutations + 1)
    return (score, permutation_scores, pvalue)

def _permutation_test_score(estimator, X, y, cv, scorer, split_params, fit_params, score_params):
    fit_params = fit_params if fit_params is not None else {}
    score_params = score_params if score_params is not None else {}
    avg_score = []
    for train, test in cv.split(X, y, **split_params):
        X_train, y_train = _safe_split(estimator, X, y, train)
        X_test, y_test = _safe_split(estimator, X, y, test, train)
        fit_params_train = _check_method_params(X, params=fit_params, indices=train)
        score_params_test = _check_method_params(X, params=score_params, indices=test)
        estimator.fit(X_train, y_train, **fit_params_train)
        avg_score.append(scorer(estimator, X_test, y_test, **score_params_test))
    return np.mean(avg_score)

def _shuffle(y, groups, random_state):
    if groups is None:
        indices = random_state.permutation(len(y))
    else:
        indices = np.arange(len(groups))
        for group in np.unique(groups):
            this_mask = groups == group
            indices[this_mask] = random_state.permutation(indices[this_mask])
    return _safe_indexing(y, indices)

@validate_params({'estimator': [HasMethods(['fit'])], 'X': ['array-like', 'sparse matrix'], 'y': ['array-like', None], 'groups': ['array-like', None], 'train_sizes': ['array-like'], 'cv': ['cv_object'], 'scoring': [StrOptions(set(get_scorer_names())), callable, None], 'exploit_incremental_learning': ['boolean'], 'n_jobs': [Integral, None], 'pre_dispatch': [Integral, str], 'verbose': ['verbose'], 'shuffle': ['boolean'], 'random_state': ['random_state'], 'error_score': [StrOptions({'raise'}), Real], 'return_times': ['boolean'], 'params': [dict, None]}, prefer_skip_nested_validation=False)
def learning_curve(estimator, X, y, *, groups=None, train_sizes=np.linspace(0.1, 1.0, 5), cv=None, scoring=None, exploit_incremental_learning=False, n_jobs=None, pre_dispatch='all', verbose=0, shuffle=False, random_state=None, error_score=np.nan, return_times=False, params=None):
    if exploit_incremental_learning and (not hasattr(estimator, 'partial_fit')):
        raise ValueError('An estimator must support the partial_fit interface to exploit incremental learning')
    _check_groups_routing_disabled(groups)
    params = {} if params is None else params
    X, y, groups = indexable(X, y, groups)
    cv = check_cv(cv, y, classifier=is_classifier(estimator))
    scorer = check_scoring(estimator, scoring=scoring)
    if _routing_enabled():
        router = MetadataRouter(owner='learning_curve').add(estimator=estimator, method_mapping=MethodMapping().add(caller='fit', callee='fit').add(caller='fit', callee='partial_fit')).add(splitter=cv, method_mapping=MethodMapping().add(caller='fit', callee='split')).add(scorer=scorer, method_mapping=MethodMapping().add(caller='fit', callee='score'))
        try:
            routed_params = process_routing(router, 'fit', **params)
        except UnsetMetadataPassedError as e:
            raise UnsetMetadataPassedError(message=str(e).replace('learning_curve.fit', 'learning_curve'), unrequested_params=e.unrequested_params, routed_params=e.routed_params)
    else:
        routed_params = _manual_routing({'estimator': {'fit': params, 'partial_fit': params}, 'splitter': {'split': {'groups': groups}}, 'scorer': {}})
    cv_iter = list(cv.split(X, y, **routed_params.splitter.split))
    n_max_training_samples = len(cv_iter[0][0])
    train_sizes_abs = _translate_train_sizes(train_sizes, n_max_training_samples)
    n_unique_ticks = train_sizes_abs.shape[0]
    if verbose > 0:
        print('[learning_curve] Training set sizes: ' + str(train_sizes_abs))
    parallel = Parallel(n_jobs=n_jobs, pre_dispatch=pre_dispatch, verbose=verbose)
    if shuffle:
        rng = check_random_state(random_state)
        cv_iter = ((rng.permutation(train), test) for train, test in cv_iter)
    if exploit_incremental_learning:
        classes = np.unique(y) if is_classifier(estimator) else None
        out = parallel((delayed(_incremental_fit_estimator)(clone(estimator), X, y, classes, train, test, train_sizes_abs, scorer, return_times, error_score=error_score, fit_params=routed_params.estimator.partial_fit, score_params=routed_params.scorer.score) for train, test in cv_iter))
        out = np.asarray(out).transpose((2, 1, 0))
    else:
        train_test_proportions = []
        for train, test in cv_iter:
            for n_train_samples in train_sizes_abs:
                train_test_proportions.append((train[:n_train_samples], test))
        results = parallel((delayed(_fit_and_score)(clone(estimator), X, y, scorer=scorer, train=train, test=test, verbose=verbose, parameters=None, fit_params=routed_params.estimator.fit, score_params=routed_params.scorer.score, return_train_score=True, error_score=error_score, return_times=return_times) for train, test in train_test_proportions))
        _warn_or_raise_about_fit_failures(results, error_score)
        results = _aggregate_score_dicts(results)
        train_scores = results['train_scores'].reshape(-1, n_unique_ticks).T
        test_scores = results['test_scores'].reshape(-1, n_unique_ticks).T
        out = [train_scores, test_scores]
        if return_times:
            fit_times = results['fit_time'].reshape(-1, n_unique_ticks).T
            score_times = results['score_time'].reshape(-1, n_unique_ticks).T
            out.extend([fit_times, score_times])
    ret = (train_sizes_abs, out[0], out[1])
    if return_times:
        ret = ret + (out[2], out[3])
    return ret

def _translate_train_sizes(train_sizes, n_max_training_samples):
    train_sizes_abs = np.asarray(train_sizes)
    n_ticks = train_sizes_abs.shape[0]
    n_min_required_samples = np.min(train_sizes_abs)
    n_max_required_samples = np.max(train_sizes_abs)
    if np.issubdtype(train_sizes_abs.dtype, np.floating):
        if n_min_required_samples <= 0.0 or n_max_required_samples > 1.0:
            raise ValueError('train_sizes has been interpreted as fractions of the maximum number of training samples and must be within (0, 1], but is within [%f, %f].' % (n_min_required_samples, n_max_required_samples))
        train_sizes_abs = (train_sizes_abs * n_max_training_samples).astype(dtype=int, copy=False)
        train_sizes_abs = np.clip(train_sizes_abs, 1, n_max_training_samples)
    elif n_min_required_samples <= 0 or n_max_required_samples > n_max_training_samples:
        raise ValueError('train_sizes has been interpreted as absolute numbers of training samples and must be within (0, %d], but is within [%d, %d].' % (n_max_training_samples, n_min_required_samples, n_max_required_samples))
    train_sizes_abs = np.unique(train_sizes_abs)
    if n_ticks > train_sizes_abs.shape[0]:
        warnings.warn("Removed duplicate entries from 'train_sizes'. Number of ticks will be less than the size of 'train_sizes': %d instead of %d." % (train_sizes_abs.shape[0], n_ticks), RuntimeWarning)
    return train_sizes_abs

@validate_params({'estimator': [HasMethods(['fit'])], 'X': ['array-like', 'sparse matrix'], 'y': ['array-like', None], 'param_name': [str], 'param_range': ['array-like'], 'groups': ['array-like', None], 'cv': ['cv_object'], 'scoring': [StrOptions(set(get_scorer_names())), callable, None], 'n_jobs': [Integral, None], 'pre_dispatch': [Integral, str], 'verbose': ['verbose'], 'error_score': [StrOptions({'raise'}), Real], 'params': [dict, None]}, prefer_skip_nested_validation=False)
