def _get_weights(dist, weights):
    if weights in (None, 'uniform'):
        return None
    if weights == 'distance':
        if dist.dtype is np.dtype(object):
            for point_dist_i, point_dist in enumerate(dist):
                if hasattr(point_dist, '__contains__') and 0.0 in point_dist:
                    dist[point_dist_i] = point_dist == 0.0
                else:
                    dist[point_dist_i] = 1.0 / point_dist
        else:
            with np.errstate(divide='ignore'):
                dist = 1.0 / dist
            inf_mask = np.isinf(dist)
            inf_row = np.any(inf_mask, axis=1)
            dist[inf_row] = inf_mask[inf_row]
        return dist
    if callable(weights):
        return weights(dist)

def _is_sorted_by_data(graph):
    assert graph.format == 'csr'
    out_of_order = graph.data[:-1] > graph.data[1:]
    line_change = np.unique(graph.indptr[1:-1] - 1)
    line_change = line_change[line_change < out_of_order.shape[0]]
    return out_of_order.sum() == out_of_order[line_change].sum()

def _check_precomputed(X):
    if not issparse(X):
        X = check_array(X, ensure_non_negative=True, input_name='X')
        return X
    else:
        graph = X
    if graph.format not in ('csr', 'csc', 'coo', 'lil'):
        raise TypeError('Sparse matrix in {!r} format is not supported due to its handling of explicit zeros'.format(graph.format))
    copied = graph.format != 'csr'
    graph = check_array(graph, accept_sparse='csr', ensure_non_negative=True, input_name='precomputed distance matrix')
    graph = sort_graph_by_row_values(graph, copy=not copied, warn_when_not_sorted=True)
    return graph

@validate_params({'graph': ['sparse matrix'], 'copy': ['boolean'], 'warn_when_not_sorted': ['boolean']}, prefer_skip_nested_validation=True)
def sort_graph_by_row_values(graph, copy=False, warn_when_not_sorted=True):
    if graph.format == 'csr' and _is_sorted_by_data(graph):
        return graph
    if warn_when_not_sorted:
        warnings.warn('Precomputed sparse input was not sorted by row values. Use the function sklearn.neighbors.sort_graph_by_row_values to sort the input by row values, with warn_when_not_sorted=False to remove this warning.', EfficiencyWarning)
    if graph.format not in ('csr', 'csc', 'coo', 'lil'):
        raise TypeError(f'Sparse matrix in {graph.format!r} format is not supported due to its handling of explicit zeros')
    elif graph.format != 'csr':
        if not copy:
            raise ValueError('The input graph is not in CSR format. Use copy=True to allow the conversion to CSR format.')
        graph = graph.asformat('csr')
    elif copy:
        graph = graph.copy()
    row_nnz = np.diff(graph.indptr)
    if row_nnz.max() == row_nnz.min():
        n_samples = graph.shape[0]
        distances = graph.data.reshape(n_samples, -1)
        order = np.argsort(distances, kind='mergesort')
        order += np.arange(n_samples)[:, None] * row_nnz[0]
        order = order.ravel()
        graph.data = graph.data[order]
        graph.indices = graph.indices[order]
    else:
        for start, stop in zip(graph.indptr, graph.indptr[1:]):
            order = np.argsort(graph.data[start:stop], kind='mergesort')
            graph.data[start:stop] = graph.data[start:stop][order]
            graph.indices[start:stop] = graph.indices[start:stop][order]
    return graph

def _kneighbors_from_graph(graph, n_neighbors, return_distance):
    n_samples = graph.shape[0]
    assert graph.format == 'csr'
    row_nnz = np.diff(graph.indptr)
    row_nnz_min = row_nnz.min()
    if n_neighbors is not None and row_nnz_min < n_neighbors:
        raise ValueError('%d neighbors per samples are required, but some samples have only %d neighbors in precomputed graph matrix. Decrease number of neighbors used or recompute the graph with more neighbors.' % (n_neighbors, row_nnz_min))

    def extract(a):
        if row_nnz.max() == row_nnz_min:
            return a.reshape(n_samples, -1)[:, :n_neighbors]
        else:
            idx = np.tile(np.arange(n_neighbors), (n_samples, 1))
            idx += graph.indptr[:-1, None]
            return a.take(idx, mode='clip').reshape(n_samples, n_neighbors)
    if return_distance:
        return (extract(graph.data), extract(graph.indices))
    else:
        return extract(graph.indices)

def _radius_neighbors_from_graph(graph, radius, return_distance):
    assert graph.format == 'csr'
    no_filter_needed = bool(graph.data.max() <= radius)
    if no_filter_needed:
        data, indices, indptr = (graph.data, graph.indices, graph.indptr)
    else:
        mask = graph.data <= radius
        if return_distance:
            data = np.compress(mask, graph.data)
        indices = np.compress(mask, graph.indices)
        indptr = np.concatenate(([0], np.cumsum(mask)))[graph.indptr]
    indices = indices.astype(np.intp, copy=no_filter_needed)
    if return_distance:
        neigh_dist = _to_object_array(np.split(data, indptr[1:-1]))
    neigh_ind = _to_object_array(np.split(indices, indptr[1:-1]))
    if return_distance:
        return (neigh_dist, neigh_ind)
    else:
        return neigh_ind

def _kneighbors_reduce_func(self, dist, start, n_neighbors, return_distance):
    sample_range = np.arange(dist.shape[0])[:, None]
    neigh_ind = np.argpartition(dist, n_neighbors - 1, axis=1)
    neigh_ind = neigh_ind[:, :n_neighbors]
    neigh_ind = neigh_ind[sample_range, np.argsort(dist[sample_range, neigh_ind])]
    if return_distance:
        if self.effective_metric_ == 'euclidean':
            result = (np.sqrt(dist[sample_range, neigh_ind]), neigh_ind)
        else:
            result = (dist[sample_range, neigh_ind], neigh_ind)
    else:
        result = neigh_ind
    return result

def kneighbors(self, X=None, n_neighbors=None, return_distance=True):
    check_is_fitted(self)
    if n_neighbors is None:
        n_neighbors = self.n_neighbors
    elif n_neighbors <= 0:
        raise ValueError('Expected n_neighbors > 0. Got %d' % n_neighbors)
    elif not isinstance(n_neighbors, numbers.Integral):
        raise TypeError('n_neighbors does not take %s value, enter integer value' % type(n_neighbors))
    ensure_all_finite = 'allow-nan' if get_tags(self).input_tags.allow_nan else True
    query_is_train = X is None
    if query_is_train:
        X = self._fit_X
        n_neighbors += 1
    elif self.metric == 'precomputed':
        X = _check_precomputed(X)
    else:
        X = validate_data(self, X, ensure_all_finite=ensure_all_finite, accept_sparse='csr', reset=False, order='C')
    n_samples_fit = self.n_samples_fit_
    if n_neighbors > n_samples_fit:
        if query_is_train:
            n_neighbors -= 1
            inequality_str = 'n_neighbors < n_samples_fit'
        else:
            inequality_str = 'n_neighbors <= n_samples_fit'
        raise ValueError(f'Expected {inequality_str}, but n_neighbors = {n_neighbors}, n_samples_fit = {n_samples_fit}, n_samples = {X.shape[0]}')
    n_jobs = effective_n_jobs(self.n_jobs)
    chunked_results = None
    use_pairwise_distances_reductions = self._fit_method == 'brute' and ArgKmin.is_usable_for(X if X is not None else self._fit_X, self._fit_X, self.effective_metric_)
    if use_pairwise_distances_reductions:
        results = ArgKmin.compute(X=X, Y=self._fit_X, k=n_neighbors, metric=self.effective_metric_, metric_kwargs=self.effective_metric_params_, strategy='auto', return_distance=return_distance)
    elif self._fit_method == 'brute' and self.metric == 'precomputed' and issparse(X):
        results = _kneighbors_from_graph(X, n_neighbors=n_neighbors, return_distance=return_distance)
    elif self._fit_method == 'brute':
        reduce_func = partial(self._kneighbors_reduce_func, n_neighbors=n_neighbors, return_distance=return_distance)
        if self.effective_metric_ == 'euclidean':
            kwds = {'squared': True}
        else:
            kwds = self.effective_metric_params_
        chunked_results = list(pairwise_distances_chunked(X, self._fit_X, reduce_func=reduce_func, metric=self.effective_metric_, n_jobs=n_jobs, **kwds))
    elif self._fit_method in ['ball_tree', 'kd_tree']:
        if issparse(X):
            raise ValueError("%s does not work with sparse matrices. Densify the data, or set algorithm='brute'" % self._fit_method)
        chunked_results = Parallel(n_jobs, prefer='threads')((delayed(self._tree.query)(X[s], n_neighbors, return_distance) for s in gen_even_slices(X.shape[0], n_jobs)))
    else:
        raise ValueError('internal: _fit_method not recognized')
    if chunked_results is not None:
        if return_distance:
            neigh_dist, neigh_ind = zip(*chunked_results)
            results = (np.vstack(neigh_dist), np.vstack(neigh_ind))
        else:
            results = np.vstack(chunked_results)
    if not query_is_train:
        return results
    else:
        if return_distance:
            neigh_dist, neigh_ind = results
        else:
            neigh_ind = results
        n_queries, _ = X.shape
        sample_range = np.arange(n_queries)[:, None]
        sample_mask = neigh_ind != sample_range
        dup_gr_nbrs = np.all(sample_mask, axis=1)
        sample_mask[:, 0][dup_gr_nbrs] = False
        neigh_ind = np.reshape(neigh_ind[sample_mask], (n_queries, n_neighbors - 1))
        if return_distance:
            neigh_dist = np.reshape(neigh_dist[sample_mask], (n_queries, n_neighbors - 1))
            return (neigh_dist, neigh_ind)
        return neigh_ind

def kneighbors_graph(self, X=None, n_neighbors=None, mode='connectivity'):
    check_is_fitted(self)
    if n_neighbors is None:
        n_neighbors = self.n_neighbors
    if mode == 'connectivity':
        A_ind = self.kneighbors(X, n_neighbors, return_distance=False)
        n_queries = A_ind.shape[0]
        A_data = np.ones(n_queries * n_neighbors)
    elif mode == 'distance':
        A_data, A_ind = self.kneighbors(X, n_neighbors, return_distance=True)
        A_data = np.ravel(A_data)
    else:
        raise ValueError(f'Unsupported mode, must be one of "connectivity", or "distance" but got "{mode}" instead')
    n_queries = A_ind.shape[0]
    n_samples_fit = self.n_samples_fit_
    n_nonzero = n_queries * n_neighbors
    A_indptr = np.arange(0, n_nonzero + 1, n_neighbors)
    kneighbors_graph = csr_array((A_data, A_ind.ravel(), A_indptr), shape=(n_queries, n_samples_fit))
    return _align_api_if_sparse(kneighbors_graph)

def _radius_neighbors_reduce_func(self, dist, start, radius, return_distance):
    neigh_ind = [np.where(d <= radius)[0] for d in dist]
    if return_distance:
        if self.effective_metric_ == 'euclidean':
            dist = [np.sqrt(d[neigh_ind[i]]) for i, d in enumerate(dist)]
        else:
            dist = [d[neigh_ind[i]] for i, d in enumerate(dist)]
        results = (dist, neigh_ind)
    else:
        results = neigh_ind
    return results

def radius_neighbors(self, X=None, radius=None, return_distance=True, sort_results=False):
    check_is_fitted(self)
    if sort_results and (not return_distance):
        raise ValueError('return_distance must be True if sort_results is True.')
    ensure_all_finite = 'allow-nan' if get_tags(self).input_tags.allow_nan else True
    query_is_train = X is None
    if query_is_train:
        X = self._fit_X
    elif self.metric == 'precomputed':
        X = _check_precomputed(X)
    else:
        X = validate_data(self, X, ensure_all_finite=ensure_all_finite, accept_sparse='csr', reset=False, order='C')
    if radius is None:
        radius = self.radius
    use_pairwise_distances_reductions = self._fit_method == 'brute' and RadiusNeighbors.is_usable_for(X if X is not None else self._fit_X, self._fit_X, self.effective_metric_)
    if use_pairwise_distances_reductions:
        results = RadiusNeighbors.compute(X=X, Y=self._fit_X, radius=radius, metric=self.effective_metric_, metric_kwargs=self.effective_metric_params_, strategy='auto', return_distance=return_distance, sort_results=sort_results)
    elif self._fit_method == 'brute' and self.metric == 'precomputed' and issparse(X):
        results = _radius_neighbors_from_graph(X, radius=radius, return_distance=return_distance)
    elif self._fit_method == 'brute':
        if self.effective_metric_ == 'euclidean':
            radius *= radius
            kwds = {'squared': True}
        else:
            kwds = self.effective_metric_params_
        reduce_func = partial(self._radius_neighbors_reduce_func, radius=radius, return_distance=return_distance)
        chunked_results = pairwise_distances_chunked(X, self._fit_X, reduce_func=reduce_func, metric=self.effective_metric_, n_jobs=self.n_jobs, **kwds)
        if return_distance:
            neigh_dist_chunks, neigh_ind_chunks = zip(*chunked_results)
            neigh_dist_list = list(itertools.chain.from_iterable(neigh_dist_chunks))
            neigh_ind_list = list(itertools.chain.from_iterable(neigh_ind_chunks))
            neigh_dist = _to_object_array(neigh_dist_list)
            neigh_ind = _to_object_array(neigh_ind_list)
            results = (neigh_dist, neigh_ind)
        else:
            neigh_ind_list = list(itertools.chain.from_iterable(chunked_results))
            results = _to_object_array(neigh_ind_list)
        if sort_results:
            for ii in range(len(neigh_dist)):
                order = np.argsort(neigh_dist[ii], kind='mergesort')
                neigh_ind[ii] = neigh_ind[ii][order]
                neigh_dist[ii] = neigh_dist[ii][order]
            results = (neigh_dist, neigh_ind)
    elif self._fit_method in ['ball_tree', 'kd_tree']:
        if issparse(X):
            raise ValueError("%s does not work with sparse matrices. Densify the data, or set algorithm='brute'" % self._fit_method)
        n_jobs = effective_n_jobs(self.n_jobs)
        delayed_query = delayed(self._tree.query_radius)
        chunked_results = Parallel(n_jobs, prefer='threads')((delayed_query(X[s], radius, return_distance, sort_results=sort_results) for s in gen_even_slices(X.shape[0], n_jobs)))
        if return_distance:
            neigh_ind, neigh_dist = tuple(zip(*chunked_results))
            results = (np.hstack(neigh_dist), np.hstack(neigh_ind))
        else:
            results = np.hstack(chunked_results)
    else:
        raise ValueError('internal: _fit_method not recognized')
    if not query_is_train:
        return results
    else:
        if return_distance:
            neigh_dist, neigh_ind = results
        else:
            neigh_ind = results
        for ind, ind_neighbor in enumerate(neigh_ind):
            mask = ind_neighbor != ind
            neigh_ind[ind] = ind_neighbor[mask]
            if return_distance:
                neigh_dist[ind] = neigh_dist[ind][mask]
        if return_distance:
            return (neigh_dist, neigh_ind)
        return neigh_ind

def radius_neighbors_graph(self, X=None, radius=None, mode='connectivity', sort_results=False):
    check_is_fitted(self)
    if radius is None:
        radius = self.radius
    if mode == 'connectivity':
        A_ind = self.radius_neighbors(X, radius, return_distance=False)
        A_data = None
    elif mode == 'distance':
        dist, A_ind = self.radius_neighbors(X, radius, return_distance=True, sort_results=sort_results)
        A_data = np.concatenate(list(dist))
    else:
        raise ValueError(f'Unsupported mode, must be one of "connectivity", or "distance" but got "{mode}" instead')
    n_queries = A_ind.shape[0]
    n_samples_fit = self.n_samples_fit_
    n_neighbors = np.array([len(a) for a in A_ind])
    A_ind = np.concatenate(list(A_ind))
    if A_data is None:
        A_data = np.ones(len(A_ind))
    A_indptr = np.concatenate((np.zeros(1, dtype=int), np.cumsum(n_neighbors)))
    csr = csr_array((A_data, A_ind, A_indptr), shape=(n_queries, n_samples_fit))
    return _align_api_if_sparse(csr)

@_fit_context(prefer_skip_nested_validation=False)
def fit(self, X, y):
    return self._fit(X, y)

def predict(self, X):
    check_is_fitted(self, '_fit_method')
    if self.weights == 'uniform':
        if self._fit_method == 'brute' and ArgKminClassMode.is_usable_for(X, self._fit_X, self.metric):
            probabilities = self.predict_proba(X)
            if self.outputs_2d_:
                return np.stack([self.classes_[idx][np.argmax(probas, axis=1)] for idx, probas in enumerate(probabilities)], axis=1)
            return self.classes_[np.argmax(probabilities, axis=1)]
        neigh_ind = self.kneighbors(X, return_distance=False)
        neigh_dist = None
    else:
        neigh_dist, neigh_ind = self.kneighbors(X)
    classes_ = self.classes_
    _y = self._y
    if not self.outputs_2d_:
        _y = self._y.reshape((-1, 1))
        classes_ = [self.classes_]
    n_outputs = len(classes_)
    n_queries = _num_samples(self._fit_X if X is None else X)
    weights = _get_weights(neigh_dist, self.weights)
    if weights is not None and _all_with_any_reduction_axis_1(weights, value=0):
        raise ValueError("All neighbors of some sample is getting zero weights. Please modify 'weights' to avoid this case if you are using a user-defined function.")
    y_pred = np.empty((n_queries, n_outputs), dtype=classes_[0].dtype)
    for k, classes_k in enumerate(classes_):
        if weights is None:
            mode, _ = _mode(_y[neigh_ind, k], axis=1)
        else:
            mode, _ = weighted_mode(_y[neigh_ind, k], weights, axis=1)
        mode = np.asarray(mode.ravel(), dtype=np.intp)
        y_pred[:, k] = classes_k.take(mode)
    if not self.outputs_2d_:
        y_pred = y_pred.ravel()
    return y_pred

def predict_proba(self, X):
    check_is_fitted(self, '_fit_method')
    if self.weights == 'uniform':
        metric, metric_kwargs = _adjusted_metric(metric=self.metric, metric_kwargs=self.metric_params, p=self.p)
        if self._fit_method == 'brute' and ArgKminClassMode.is_usable_for(X, self._fit_X, metric) and (not self.outputs_2d_):
            if self.metric == 'precomputed':
                X = _check_precomputed(X)
            else:
                X = validate_data(self, X, accept_sparse='csr', reset=False, order='C')
            probabilities = ArgKminClassMode.compute(X, self._fit_X, k=self.n_neighbors, weights=self.weights, Y_labels=self._y, unique_Y_labels=np.arange(len(self.classes_), dtype=np.intp), metric=metric, metric_kwargs=metric_kwargs, strategy='parallel_on_X')
            return probabilities
        neigh_ind = self.kneighbors(X, return_distance=False)
        neigh_dist = None
    else:
        neigh_dist, neigh_ind = self.kneighbors(X)
    classes_ = self.classes_
    _y = self._y
    if not self.outputs_2d_:
        _y = self._y.reshape((-1, 1))
        classes_ = [self.classes_]
    n_queries = _num_samples(self._fit_X if X is None else X)
    weights = _get_weights(neigh_dist, self.weights)
    if weights is None:
        weights = np.ones_like(neigh_ind)
    elif _all_with_any_reduction_axis_1(weights, value=0):
        raise ValueError("All neighbors of some sample is getting zero weights. Please modify 'weights' to avoid this case if you are using a user-defined function.")
    all_rows = np.arange(n_queries)
    probabilities = []
    for k, classes_k in enumerate(classes_):
        pred_labels = _y[:, k][neigh_ind]
        proba_k = np.zeros((n_queries, classes_k.size))
        for i, idx in enumerate(pred_labels.T):
            proba_k[all_rows, idx] += weights[:, i]
        normalizer = proba_k.sum(axis=1)[:, np.newaxis]
        proba_k /= normalizer
        probabilities.append(proba_k)
    if not self.outputs_2d_:
        probabilities = probabilities[0]
    return probabilities

@_fit_context(prefer_skip_nested_validation=False)
def fit(self, X, y):
    self._fit(X, y)
    classes_ = self.classes_
    _y = self._y
    if not self.outputs_2d_:
        _y = self._y.reshape((-1, 1))
        classes_ = [self.classes_]
    if self.outlier_label is None:
        outlier_label_ = None
    elif self.outlier_label == 'most_frequent':
        outlier_label_ = []
        for k, classes_k in enumerate(classes_):
            label_count = np.bincount(_y[:, k])
            outlier_label_.append(classes_k[label_count.argmax()])
    else:
        if _is_arraylike(self.outlier_label) and (not isinstance(self.outlier_label, str)):
            if len(self.outlier_label) != len(classes_):
                raise ValueError('The length of outlier_label: {} is inconsistent with the output length: {}'.format(self.outlier_label, len(classes_)))
            outlier_label_ = self.outlier_label
        else:
            outlier_label_ = [self.outlier_label] * len(classes_)
        for classes, label in zip(classes_, outlier_label_):
            if _is_arraylike(label) and (not isinstance(label, str)):
                raise TypeError('The outlier_label of classes {} is supposed to be a scalar, got {}.'.format(classes, label))
            if np.append(classes, label).dtype != classes.dtype:
                raise TypeError('The dtype of outlier_label {} is inconsistent with classes {} in y.'.format(label, classes))
    self.outlier_label_ = outlier_label_
    return self

def _check_params(X, metric, p, metric_params):
    params = zip(['metric', 'p', 'metric_params'], [metric, p, metric_params])
    est_params = X.get_params()
    for param_name, func_param in params:
        if func_param != est_params[param_name]:
            raise ValueError('Got %s for %s, while the estimator has %s for the same parameter.' % (func_param, param_name, est_params[param_name]))

def _query_include_self(X, include_self, mode):
    if include_self == 'auto':
        include_self = mode == 'connectivity'
    if not include_self:
        X = None
    return X

@validate_params({'X': ['array-like', 'sparse matrix', KNeighborsMixin], 'n_neighbors': [Interval(Integral, 1, None, closed='left')], 'mode': [StrOptions({'connectivity', 'distance'})], 'metric': [StrOptions(set(itertools.chain(*VALID_METRICS.values()))), callable], 'p': [Interval(Real, 0, None, closed='right'), None], 'metric_params': [dict, None], 'include_self': ['boolean', StrOptions({'auto'})], 'n_jobs': [Integral, None]}, prefer_skip_nested_validation=False)
def kneighbors_graph(X, n_neighbors, *, mode='connectivity', metric='minkowski', p=2, metric_params=None, include_self=False, n_jobs=None):
    if not isinstance(X, KNeighborsMixin):
        X = NearestNeighbors(n_neighbors=n_neighbors, metric=metric, p=p, metric_params=metric_params, n_jobs=n_jobs).fit(X)
    else:
        _check_params(X, metric, p, metric_params)
    query = _query_include_self(X._fit_X, include_self, mode)
    return X.kneighbors_graph(X=query, n_neighbors=n_neighbors, mode=mode)

@validate_params({'X': ['array-like', 'sparse matrix', RadiusNeighborsMixin], 'radius': [Interval(Real, 0, None, closed='both')], 'mode': [StrOptions({'connectivity', 'distance'})], 'metric': [StrOptions(set(itertools.chain(*VALID_METRICS.values()))), callable], 'p': [Interval(Real, 0, None, closed='right'), None], 'metric_params': [dict, None], 'include_self': ['boolean', StrOptions({'auto'})], 'n_jobs': [Integral, None]}, prefer_skip_nested_validation=False)
def radius_neighbors_graph(X, radius, *, mode='connectivity', metric='minkowski', p=2, metric_params=None, include_self=False, n_jobs=None):
    if not isinstance(X, RadiusNeighborsMixin):
        X = NearestNeighbors(radius=radius, metric=metric, p=p, metric_params=metric_params, n_jobs=n_jobs).fit(X)
    else:
        _check_params(X, metric, p, metric_params)
    query = _query_include_self(X._fit_X, include_self, mode)
    return X.radius_neighbors_graph(query, radius, mode)

@_fit_context(prefer_skip_nested_validation=False)
def fit(self, X, y=None):
    self._fit(X)
    self._n_features_out = self.n_samples_fit_
    return self

def transform(self, X):
    check_is_fitted(self)
    add_one = self.mode == 'distance'
    return self.kneighbors_graph(X, mode=self.mode, n_neighbors=self.n_neighbors + add_one)

@_fit_context(prefer_skip_nested_validation=False)
def fit(self, X, y=None):
    self._fit(X)
    self._n_features_out = self.n_samples_fit_
    return self

def transform(self, X):
    check_is_fitted(self)
    return self.radius_neighbors_graph(X, mode=self.mode, sort_results=True)

@_fit_context(prefer_skip_nested_validation=False)
def fit(self, X, y=None, sample_weight=None):
    algorithm = self._choose_algorithm(self.algorithm, self.metric)
    if isinstance(self.bandwidth, str):
        if self.bandwidth == 'scott':
            self.bandwidth_ = X.shape[0] ** (-1 / (X.shape[1] + 4))
        elif self.bandwidth == 'silverman':
            self.bandwidth_ = (X.shape[0] * (X.shape[1] + 2) / 4) ** (-1 / (X.shape[1] + 4))
    else:
        self.bandwidth_ = self.bandwidth
    X = validate_data(self, X, order='C', dtype=np.float64)
    if sample_weight is not None:
        sample_weight = _check_sample_weight(sample_weight, X, dtype=np.float64, ensure_non_negative=True)
    kwargs = self.metric_params
    if kwargs is None:
        kwargs = {}
    self.tree_ = TREE_DICT[algorithm](X, metric=self.metric, leaf_size=self.leaf_size, sample_weight=sample_weight, **kwargs)
    return self

def sample(self, n_samples=1, random_state=None):
    check_is_fitted(self)
    if self.kernel not in ['gaussian', 'tophat']:
        raise NotImplementedError()
    data = np.asarray(self.tree_.data)
    rng = check_random_state(random_state)
    u = rng.uniform(0, 1, size=n_samples)
    if self.tree_.sample_weight is None:
        i = (u * data.shape[0]).astype(np.int64)
    else:
        cumsum_weight = np.cumsum(np.asarray(self.tree_.sample_weight))
        sum_weight = cumsum_weight[-1]
        i = np.searchsorted(cumsum_weight, u * sum_weight)
    if self.kernel == 'gaussian':
        return np.atleast_2d(rng.normal(data[i], self.bandwidth_))
    elif self.kernel == 'tophat':
        dim = data.shape[1]
        X = rng.normal(size=(n_samples, dim))
        s_sq = row_norms(X, squared=True)
        correction = gammainc(0.5 * dim, 0.5 * s_sq) ** (1.0 / dim) * self.bandwidth_ / np.sqrt(s_sq)
        return data[i] + X * correction[:, np.newaxis]

@available_if(_check_novelty_fit_predict)
def fit_predict(self, X, y=None):
    return self.fit(X)._predict()

@_fit_context(prefer_skip_nested_validation=False)
def fit(self, X, y=None):
    self._fit(X)
    n_samples = self.n_samples_fit_
    if self.n_neighbors > n_samples:
        warnings.warn('n_neighbors (%s) is greater than the total number of samples (%s). n_neighbors will be set to (n_samples - 1) for estimation.' % (self.n_neighbors, n_samples))
    self.n_neighbors_ = max(1, min(self.n_neighbors, n_samples - 1))
    self._distances_fit_X_, _neighbors_indices_fit_X_ = self.kneighbors(n_neighbors=self.n_neighbors_)
    if self._fit_X.dtype == np.float32:
        self._distances_fit_X_ = self._distances_fit_X_.astype(self._fit_X.dtype, copy=False)
    self._lrd = self._local_reachability_density(self._distances_fit_X_, _neighbors_indices_fit_X_)
    lrd_ratios_array = self._lrd[_neighbors_indices_fit_X_] / self._lrd[:, np.newaxis]
    self.negative_outlier_factor_ = -np.mean(lrd_ratios_array, axis=1)
    if self.contamination == 'auto':
        self.offset_ = -1.5
    else:
        self.offset_ = np.percentile(self.negative_outlier_factor_, 100.0 * self.contamination)
    if np.min(self.negative_outlier_factor_) < -10000000.0 and (not self.novelty):
        warnings.warn('Duplicate values are leading to incorrect results. Increase the number of neighbors for more accurate results.')
    return self

@available_if(_check_novelty_predict)
def predict(self, X=None):
    return self._predict(X)

def _predict(self, X=None):
    check_is_fitted(self)
    if X is not None:
        shifted_opposite_lof_scores = self.decision_function(X)
        is_inlier = np.ones(shifted_opposite_lof_scores.shape[0], dtype=int)
        is_inlier[shifted_opposite_lof_scores < 0] = -1
    else:
        is_inlier = np.ones(self.n_samples_fit_, dtype=int)
        is_inlier[self.negative_outlier_factor_ < self.offset_] = -1
    return is_inlier

@available_if(_check_novelty_decision_function)
def decision_function(self, X):
    return self.score_samples(X) - self.offset_

@available_if(_check_novelty_score_samples)
def score_samples(self, X):
    check_is_fitted(self)
    X = check_array(X, accept_sparse='csr')
    distances_X, neighbors_indices_X = self.kneighbors(X, n_neighbors=self.n_neighbors_)
    if X.dtype == np.float32:
        distances_X = distances_X.astype(X.dtype, copy=False)
    X_lrd = self._local_reachability_density(distances_X, neighbors_indices_X)
    lrd_ratios_array = self._lrd[neighbors_indices_X] / X_lrd[:, np.newaxis]
    return -np.mean(lrd_ratios_array, axis=1)

def _local_reachability_density(self, distances_X, neighbors_indices):
    dist_k = self._distances_fit_X_[neighbors_indices, self.n_neighbors_ - 1]
    reach_dist_array = np.maximum(distances_X, dist_k)
    return 1.0 / (np.mean(reach_dist_array, axis=1) + 1e-10)

@_fit_context(prefer_skip_nested_validation=True)
def fit(self, X, y):
    X, y = validate_data(self, X, y, validate_separately=({'accept_sparse': True, 'ensure_min_samples': 2}, {'accept_sparse': False, 'ensure_2d': False}))
    check_classification_targets(y)
    y = LabelEncoder().fit_transform(y)
    if self.n_components is not None and self.n_components > X.shape[1]:
        raise ValueError(f'The preferred dimensionality of the projected space `n_components` ({self.n_components}) cannot be greater than the given data dimensionality ({X.shape[1]})!')
    if self.warm_start and hasattr(self, 'components_') and (self.components_.shape[1] != X.shape[1]):
        raise ValueError(f'The new inputs dimensionality ({X.shape[1]}) does not match the input dimensionality of the previously learned transformation ({self.components_.shape[1]}).')
    init = self.init
    if isinstance(init, np.ndarray):
        init = check_array(init)
        if init.shape[1] != X.shape[1]:
            raise ValueError(f'The input dimensionality ({init.shape[1]}) of the given linear transformation `init` must match the dimensionality of the given inputs `X` ({X.shape[1]}).')
        if init.shape[0] > init.shape[1]:
            raise ValueError(f'The output dimensionality ({init.shape[0]}) of the given linear transformation `init` cannot be greater than its input dimensionality ({init.shape[1]}).')
        if self.n_components is not None and self.n_components != init.shape[0]:
            raise ValueError(f'The preferred dimensionality of the projected space `n_components` ({self.n_components}) does not match the output dimensionality of the given linear transformation `init` ({init.shape[0]})!')
    self.random_state_ = check_random_state(self.random_state)
    t_train = time.time()
    same_class_mask = y[:, np.newaxis] == y[np.newaxis, :]
    transformation = np.ravel(self._initialize(X, y, init))
    disp = self.verbose - 2 if self.verbose > 1 else -1
    optimizer_params = {'method': 'L-BFGS-B', 'fun': self._loss_grad_lbfgs, 'args': (X, same_class_mask, -1.0), 'jac': True, 'x0': transformation, 'tol': self.tol, 'options': dict(maxiter=self.max_iter, **_get_additional_lbfgs_options_dict('disp', disp)), 'callback': self._callback}
    self.n_iter_ = 0
    opt_result = minimize(**optimizer_params)
    self.components_ = opt_result.x.reshape(-1, X.shape[1])
    t_train = time.time() - t_train
    if self.verbose:
        cls_name = self.__class__.__name__
        if not opt_result.success:
            warn('[{}] NCA did not converge: {}'.format(cls_name, opt_result.message), ConvergenceWarning)
        print('[{}] Training took {:8.2f}s.'.format(cls_name, t_train))
    return self

def transform(self, X):
    check_is_fitted(self)
    X = validate_data(self, X, reset=False, accept_sparse=True)
    return safe_sparse_dot(X, self.components_.T, dense_output=True)

def _initialize(self, X, y, init):
    transformation = init
    if self.warm_start and hasattr(self, 'components_'):
        transformation = self.components_
    elif isinstance(init, np.ndarray):
        pass
    else:
        if issparse(X) and init not in ('pca', 'random', 'identity'):
            raise ValueError("Sparse input is only supported for init in ['pca', 'random', 'identity']")
        n_samples, n_features = X.shape
        n_components = self.n_components or n_features
        if init == 'auto':
            n_classes = len(np.unique(y))
            if n_components <= min(n_features, n_classes - 1):
                init = 'lda'
            elif n_components < min(n_features, n_samples):
                init = 'pca'
            else:
                init = 'identity'
        if init == 'identity':
            transformation = np.eye(n_components, X.shape[1])
        elif init == 'random':
            transformation = self.random_state_.standard_normal(size=(n_components, X.shape[1]))
        elif init in {'pca', 'lda'}:
            init_time = time.time()
            if init == 'pca':
                pca = PCA(n_components=n_components, random_state=self.random_state_)
                if self.verbose:
                    print('Finding principal components... ', end='')
                    sys.stdout.flush()
                pca.fit(X)
                transformation = pca.components_
            elif init == 'lda':
                from sklearn.discriminant_analysis import LinearDiscriminantAnalysis
                lda = LinearDiscriminantAnalysis(n_components=n_components)
                if self.verbose:
                    print('Finding most discriminative components... ', end='')
                    sys.stdout.flush()
                lda.fit(X, y)
                transformation = lda.scalings_.T[:n_components]
            if self.verbose:
                print('done in {:5.2f}s'.format(time.time() - init_time))
    return transformation

def _callback(self, transformation):
    if self.callback is not None:
        self.callback(transformation, self.n_iter_)
    self.n_iter_ += 1

@property
def _n_features_out(self):
    return self.components_.shape[0]

@_fit_context(prefer_skip_nested_validation=True)
def fit(self, X, y):
    if self.metric == 'manhattan':
        X, y = validate_data(self, X, y, accept_sparse=['csc'])
    else:
        ensure_all_finite = 'allow-nan' if get_tags(self).input_tags.allow_nan else True
        X, y = validate_data(self, X, y, ensure_all_finite=ensure_all_finite, accept_sparse=['csr', 'csc'])
    is_X_sparse = sp.issparse(X)
    check_classification_targets(y)
    n_samples, n_features = X.shape
    le = LabelEncoder()
    y_ind = le.fit_transform(y)
    self.classes_ = classes = le.classes_
    n_classes = classes.size
    if n_classes < 2:
        raise ValueError('The number of classes has to be greater than one; got %d class' % n_classes)
    if self.priors == 'empirical':
        _, class_counts = np.unique(y, return_inverse=True)
        self.class_prior_ = np.bincount(class_counts) / float(len(y))
    elif self.priors == 'uniform':
        self.class_prior_ = np.asarray([1 / n_classes] * n_classes)
    else:
        self.class_prior_ = np.asarray(self.priors)
    if (self.class_prior_ < 0).any():
        raise ValueError('priors must be non-negative')
    if not np.isclose(self.class_prior_.sum(), 1.0):
        warnings.warn('The priors do not sum to 1. Normalizing such that it sums to one.', UserWarning)
        self.class_prior_ = self.class_prior_ / self.class_prior_.sum()
    self.centroids_ = np.empty((n_classes, n_features), dtype=np.float64)
    nk = np.zeros(n_classes)
    for cur_class in range(n_classes):
        center_mask = y_ind == cur_class
        nk[cur_class] = np.sum(center_mask)
        if is_X_sparse:
            center_mask = np.where(center_mask)[0]
        if self.metric == 'manhattan':
            if not is_X_sparse:
                self.centroids_[cur_class] = np.median(X[center_mask], axis=0)
            else:
                self.centroids_[cur_class] = csc_median_axis_0(X[center_mask])
        else:
            self.centroids_[cur_class] = X[center_mask].mean(axis=0)
    variance = np.array(X - self.centroids_[y_ind], copy=False) ** 2
    self.within_class_std_dev_ = np.array(np.sqrt(variance.sum(axis=0) / (n_samples - n_classes)), copy=False)
    if any(self.within_class_std_dev_ == 0):
        warnings.warn('self.within_class_std_dev_ has at least 1 zero standard deviation.Inputs within the same classes for at least 1 feature are identical.')
    err_msg = 'All features have zero variance. Division by zero.'
    if is_X_sparse and np.all((X.max(axis=0) - X.min(axis=0)).toarray() == 0):
        raise ValueError(err_msg)
    elif not is_X_sparse and np.all(np.ptp(X, axis=0) == 0):
        raise ValueError(err_msg)
    dataset_centroid_ = X.mean(axis=0)
    m = np.sqrt(1.0 / nk - 1.0 / n_samples)
    s = self.within_class_std_dev_ + np.median(self.within_class_std_dev_)
    mm = m.reshape(len(m), 1)
    ms = mm * s
    self.deviations_ = np.array((self.centroids_ - dataset_centroid_) / ms, copy=False)
    if self.shrink_threshold:
        signs = np.sign(self.deviations_)
        self.deviations_ = np.abs(self.deviations_) - self.shrink_threshold
        np.clip(self.deviations_, 0, None, out=self.deviations_)
        self.deviations_ *= signs
        msd = ms * self.deviations_
        self.centroids_ = np.array(dataset_centroid_ + msd, copy=False)
    return self

def predict(self, X):
    check_is_fitted(self)
    if np.isclose(self.class_prior_, 1 / len(self.classes_)).all():
        ensure_all_finite = 'allow-nan' if get_tags(self).input_tags.allow_nan else True
        X = validate_data(self, X, ensure_all_finite=ensure_all_finite, accept_sparse='csr', reset=False)
        return self.classes_[pairwise_distances_argmin(X, self.centroids_, metric=self.metric)]
    else:
        return super().predict(X)

@_fit_context(prefer_skip_nested_validation=False)
def fit(self, X, y):
    return self._fit(X, y)

def predict(self, X):
    if self.weights == 'uniform':
        neigh_ind = self.kneighbors(X, return_distance=False)
        neigh_dist = None
    else:
        neigh_dist, neigh_ind = self.kneighbors(X)
    weights = _get_weights(neigh_dist, self.weights)
    _y = self._y
    if _y.ndim == 1:
        _y = _y.reshape((-1, 1))
    if weights is None:
        y_pred = np.mean(_y[neigh_ind], axis=1)
    else:
        denom = np.sum(weights, axis=1)
        num = np.einsum('ijk,ij->ik', _y[neigh_ind], weights)
        y_pred = num / denom[:, None]
    if self._y.ndim == 1:
        y_pred = y_pred.ravel()
    return y_pred

@_fit_context(prefer_skip_nested_validation=False)
def fit(self, X, y):
    return self._fit(X, y)

def predict(self, X):
    neigh_dist, neigh_ind = self.radius_neighbors(X)
    weights = _get_weights(neigh_dist, self.weights)
    _y = self._y
    if _y.ndim == 1:
        _y = _y.reshape((-1, 1))
    empty_obs = np.full_like(_y[0], np.nan)
    if weights is None:
        y_pred = np.array([np.mean(_y[ind, :], axis=0) if len(ind) else empty_obs for i, ind in enumerate(neigh_ind)])
    else:
        y_pred = np.array([np.average(_y[ind, :], axis=0, weights=weights[i]) if len(ind) else empty_obs for i, ind in enumerate(neigh_ind)])
    if np.any(np.isnan(y_pred)):
        empty_warning_msg = 'One or more samples have no neighbors within specified radius; predicting NaN.'
        warnings.warn(empty_warning_msg)
    if self._y.ndim == 1:
        y_pred = y_pred.ravel()
    return y_pred

@_fit_context(prefer_skip_nested_validation=False)
def fit(self, X, y=None):
    return self._fit(X)

def inplace_logistic_derivative(Z, delta):
    delta *= Z
    delta *= 1 - Z

def log_loss(y_true, y_prob, sample_weight=None):
    eps = np.finfo(y_prob.dtype).eps
    y_prob = np.clip(y_prob, eps, 1 - eps)
    if y_prob.shape[1] == 1:
        y_prob = np.append(1 - y_prob, y_prob, axis=1)
    if y_true.shape[1] == 1:
        y_true = np.append(1 - y_true, y_true, axis=1)
    return -np.average(xlogy(y_true, y_prob), weights=sample_weight, axis=0).sum()

def binary_log_loss(y_true, y_prob, sample_weight=None):
    eps = np.finfo(y_prob.dtype).eps
    y_prob = np.clip(y_prob, eps, 1 - eps)
    return -np.average(xlogy(y_true, y_prob) + xlogy(1 - y_true, 1 - y_prob), weights=sample_weight, axis=0).sum()

def _unpack(self, packed_parameters):
    for i in range(self.n_layers_ - 1):
        start, end, shape = self._coef_indptr[i]
        self.coefs_[i] = np.reshape(packed_parameters[start:end], shape)
        start, end = self._intercept_indptr[i]
        self.intercepts_[i] = packed_parameters[start:end]

def _forward_pass(self, activations):
    hidden_activation = ACTIVATIONS[self.activation]
    for i in range(self.n_layers_ - 1):
        activations[i + 1] = safe_sparse_dot(activations[i], self.coefs_[i])
        activations[i + 1] += self.intercepts_[i]
        if i + 1 != self.n_layers_ - 1:
            hidden_activation(activations[i + 1])
    output_activation = ACTIVATIONS[self.out_activation_]
    output_activation(activations[i + 1])
    return activations

def _forward_pass_fast(self, X, check_input=True):
    if check_input:
        X = validate_data(self, X, accept_sparse=['csr', 'csc'], reset=False)
    activation = X
    hidden_activation = ACTIVATIONS[self.activation]
    for i in range(self.n_layers_ - 1):
        activation = safe_sparse_dot(activation, self.coefs_[i])
        activation += self.intercepts_[i]
        if i != self.n_layers_ - 2:
            hidden_activation(activation)
    output_activation = ACTIVATIONS[self.out_activation_]
    output_activation(activation)
    return activation

def _loss_grad_lbfgs(self, packed_coef_inter, X, y, sample_weight, activations, deltas, coef_grads, intercept_grads):
    self._unpack(packed_coef_inter)
    loss, coef_grads, intercept_grads = self._backprop(X, y, sample_weight, activations, deltas, coef_grads, intercept_grads)
    grad = _pack(coef_grads, intercept_grads)
    return (loss, grad)

@_fit_context(prefer_skip_nested_validation=True)
def fit(self, X, y, sample_weight=None):
    return self._fit(X, y, sample_weight=sample_weight, incremental=False)

def _score_with_function(self, X, y, sample_weight, score_function):
    y_pred = self._predict(X, check_input=False)
    if np.issubdtype(y_pred.dtype, np.floating) and (not np.isfinite(y_pred).all()):
        return np.nan
    return score_function(y, y_pred, sample_weight=sample_weight)

def predict(self, X):
    check_is_fitted(self)
    return self._predict(X)

def _predict(self, X, check_input=True):
    y_pred = self._forward_pass_fast(X, check_input=check_input)
    if self.n_outputs_ == 1:
        y_pred = y_pred.ravel()
    return self._label_binarizer.inverse_transform(y_pred)

