def predict_log_proba(self, X):
    y_prob = self.predict_proba(X)
    return np.log(y_prob, out=y_prob)

def predict_proba(self, X):
    check_is_fitted(self)
    y_pred = self._forward_pass_fast(X)
    if self.n_outputs_ == 1:
        y_pred = y_pred.ravel()
    if y_pred.ndim == 1:
        return np.vstack([1 - y_pred, y_pred]).T
    else:
        return y_pred

def predict(self, X):
    check_is_fitted(self)
    return self._predict(X)

def _predict(self, X, check_input=True):
    y_pred = self._forward_pass_fast(X, check_input=check_input)
    if y_pred.shape[1] == 1:
        return y_pred.ravel()
    return y_pred

@available_if(lambda est: est._check_solver)
@_fit_context(prefer_skip_nested_validation=True)
def partial_fit(self, X, y, sample_weight=None):
    return self._fit(X, y, sample_weight=sample_weight, incremental=True)

def transform(self, X):
    check_is_fitted(self)
    X = validate_data(self, X, accept_sparse='csr', reset=False, dtype=(np.float64, np.float32))
    return self._mean_hiddens(X)

def _mean_hiddens(self, v):
    p = safe_sparse_dot(v, self.components_.T)
    p += self.intercept_hidden_
    return expit(p, out=p)

def _sample_hiddens(self, v, rng):
    p = self._mean_hiddens(v)
    return rng.uniform(size=p.shape) < p

@_fit_context(prefer_skip_nested_validation=True)
def partial_fit(self, X, y=None):
    first_pass = not hasattr(self, 'components_')
    X = validate_data(self, X, accept_sparse='csr', dtype=np.float64, reset=first_pass)
    if not hasattr(self, 'random_state_'):
        self.random_state_ = check_random_state(self.random_state)
    if not hasattr(self, 'components_'):
        self.components_ = np.asarray(self.random_state_.normal(0, 0.01, (self.n_components, X.shape[1])), order='F')
        self._n_features_out = self.components_.shape[0]
    if not hasattr(self, 'intercept_hidden_'):
        self.intercept_hidden_ = np.zeros(self.n_components)
    if not hasattr(self, 'intercept_visible_'):
        self.intercept_visible_ = np.zeros(X.shape[1])
    if not hasattr(self, 'h_samples_'):
        self.h_samples_ = np.zeros((self.batch_size, self.n_components))
    self._fit(X, self.random_state_)

def score_samples(self, X):
    check_is_fitted(self)
    v = validate_data(self, X, accept_sparse='csr', reset=False)
    rng = check_random_state(self.random_state)
    ind = (np.arange(v.shape[0]), rng.randint(0, v.shape[1], v.shape[0]))
    if sp.issparse(v):
        data = -2 * v[ind] + 1
        if isinstance(data, np.matrix):
            v_ = v + sp.csr_matrix((data.A.ravel(), ind), shape=v.shape)
        else:
            v_ = v + sp.csr_array((data.ravel(), ind), shape=v.shape)
    else:
        v_ = v.copy()
        v_[ind] = 1 - v_[ind]
    fe = self._free_energy(v)
    fe_ = self._free_energy(v_)
    return -v.shape[1] * np.logaddexp(0, -(fe_ - fe))

def update_params(self, params, grads):
    updates = self._get_updates(grads)
    for param, update in zip((p for p in params), updates):
        param += update

def trigger_stopping(self, msg, verbose):
    if verbose:
        print(msg + ' Stopping.')
    return True

def iteration_ends(self, time_step):
    if self.lr_schedule == 'invscaling':
        self.learning_rate = float(self.learning_rate_init) / (time_step + 1) ** self.power_t

def _get_updates(self, grads):
    updates = [self.momentum * velocity - self.learning_rate * grad for velocity, grad in zip(self.velocities, grads)]
    self.velocities = updates
    if self.nesterov:
        updates = [self.momentum * velocity - self.learning_rate * grad for velocity, grad in zip(self.velocities, grads)]
    return updates

def _handle_zeros_in_scale(scale, copy=True, constant_mask=None):
    if np.isscalar(scale):
        if scale == 0.0:
            scale = 1.0
        return scale
    else:
        xp, _ = get_namespace(scale)
        if constant_mask is None:
            constant_mask = scale < 10 * xp.finfo(scale.dtype).eps
        if copy:
            scale = xp.asarray(scale, copy=True)
        scale[constant_mask] = 1.0
        return scale

@validate_params({'X': ['array-like', 'sparse matrix'], 'axis': [Options(Integral, {0, 1})], 'with_mean': ['boolean'], 'with_std': ['boolean'], 'copy': ['boolean']}, prefer_skip_nested_validation=True)
def scale(X, *, axis=0, with_mean=True, with_std=True, copy=True):
    X = check_array(X, accept_sparse='csc', copy=copy, ensure_2d=False, estimator='the scale function', dtype=FLOAT_DTYPES, ensure_all_finite='allow-nan', input_name='X')
    if sparse.issparse(X):
        if with_mean:
            raise ValueError('Cannot center sparse matrices: pass `with_mean=False` instead See docstring for motivation and alternatives.')
        if axis != 0:
            raise ValueError('Can only scale sparse matrix on axis=0,  got axis=%d' % axis)
        if with_std:
            _, var = mean_variance_axis(X, axis=0)
            var = _handle_zeros_in_scale(var, copy=False)
            inplace_column_scale(X, 1 / np.sqrt(var))
    else:
        X = np.asarray(X)
        if with_mean:
            mean_ = np.nanmean(X, axis)
        if with_std:
            scale_ = np.nanstd(X, axis)
        Xr = np.rollaxis(X, axis)
        if with_mean:
            Xr -= mean_
            mean_1 = np.nanmean(Xr, axis=0)
            if not np.allclose(mean_1, 0):
                warnings.warn('Numerical issues were encountered when centering the data and might not be solved. Dataset may contain too large values. You may need to prescale your features.')
                Xr -= mean_1
        if with_std:
            scale_ = _handle_zeros_in_scale(scale_, copy=False)
            Xr /= scale_
            if with_mean:
                mean_2 = np.nanmean(Xr, axis=0)
                if not np.allclose(mean_2, 0):
                    warnings.warn('Numerical issues were encountered when scaling the data and might not be solved. The standard deviation of the data is probably very close to 0. ')
                    Xr -= mean_2
    return X

@validate_params({'X': ['array-like'], 'axis': [Options(Integral, {0, 1})]}, prefer_skip_nested_validation=False)
def minmax_scale(X, feature_range=(0, 1), *, axis=0, copy=True):
    X = check_array(X, copy=False, ensure_2d=False, dtype=FLOAT_DTYPES, ensure_all_finite='allow-nan')
    original_ndim = X.ndim
    if original_ndim == 1:
        X = X.reshape(X.shape[0], 1)
    s = MinMaxScaler(feature_range=feature_range, copy=copy)
    if axis == 0:
        X = s.fit_transform(X)
    else:
        X = s.fit_transform(X.T).T
    if original_ndim == 1:
        X = X.ravel()
    return X

