@validate_params({'X': ['array-like', 'sparse matrix'], 'norm': [StrOptions({'l1', 'l2', 'max'})], 'axis': [Options(Integral, {0, 1})], 'copy': ['boolean'], 'return_norm': ['boolean']}, prefer_skip_nested_validation=True)
def normalize(X, norm='l2', *, axis=1, copy=True, return_norm=False):
    if axis == 0:
        sparse_format = 'csc'
    else:
        sparse_format = 'csr'
    xp, _ = get_namespace(X)
    X = check_array(X, accept_sparse=sparse_format, copy=copy, estimator='the normalize function', dtype=_array_api.supported_float_dtypes(xp, device=device(X)), force_writeable=True)
    if axis == 0:
        X = X.T
    if sparse.issparse(X):
        if return_norm and norm in ('l1', 'l2'):
            raise NotImplementedError("return_norm=True is not implemented for sparse matrices with norm 'l1' or norm 'l2'")
        if norm == 'l1':
            inplace_csr_row_normalize_l1(X)
        elif norm == 'l2':
            inplace_csr_row_normalize_l2(X)
        elif norm == 'max':
            mins, maxes = min_max_axis(X, 1)
            norms = np.maximum(abs(mins), maxes)
            norms_elementwise = norms.repeat(np.diff(X.indptr))
            mask = norms_elementwise != 0
            X.data[mask] /= norms_elementwise[mask]
    else:
        if norm == 'l1':
            norms = xp.sum(xp.abs(X), axis=1)
        elif norm == 'l2':
            norms = row_norms(X)
        elif norm == 'max':
            norms = xp.max(xp.abs(X), axis=1)
        norms = _handle_zeros_in_scale(norms, copy=False)
        X /= norms[:, None]
    if axis == 0:
        X = X.T
    if return_norm:
        return (X, norms)
    else:
        return X

@validate_params({'X': ['array-like', 'sparse matrix'], 'value': [Interval(Real, None, None, closed='neither')]}, prefer_skip_nested_validation=True)
def add_dummy_feature(X, value=1.0):
    X = check_array(X, accept_sparse=['csc', 'csr', 'coo'], dtype=FLOAT_DTYPES)
    n_samples, n_features = X.shape
    shape = (n_samples, n_features + 1)
    if sparse.issparse(X):
        if X.format == 'coo':
            col = X.col + 1
            col = np.concatenate((np.zeros(n_samples), col))
            row = np.concatenate((np.arange(n_samples), X.row))
            data = np.concatenate((np.full(n_samples, value), X.data))
            result = sparse.coo_array((data, (row, col)), shape)
            return _align_api_if_sparse(result)
        elif X.format == 'csc':
            indptr = X.indptr + n_samples
            indptr = np.concatenate((np.array([0]), indptr))
            indices = np.concatenate((np.arange(n_samples), X.indices))
            data = np.concatenate((np.full(n_samples, value), X.data))
            result = sparse.csc_array((data, indices, indptr), shape)
            return _align_api_if_sparse(result)
        else:
            return _align_api_if_sparse(add_dummy_feature(X.tocoo(), value).tocsr())
    else:
        return np.hstack((np.full((n_samples, 1), value), X))

@validate_params({'X': ['array-like', 'sparse matrix'], 'axis': [Options(Integral, {0, 1})]}, prefer_skip_nested_validation=False)
def quantile_transform(X, *, axis=0, n_quantiles=1000, output_distribution='uniform', ignore_implicit_zeros=False, subsample=int(100000.0), random_state=None, copy=True):
    n = QuantileTransformer(n_quantiles=n_quantiles, output_distribution=output_distribution, subsample=subsample, ignore_implicit_zeros=ignore_implicit_zeros, random_state=random_state, copy=copy)
    if axis == 0:
        X = n.fit_transform(X)
    else:
        X = n.fit_transform(X.T).T
    return X

@validate_params({'X': ['array-like']}, prefer_skip_nested_validation=False)
def power_transform(X, method='yeo-johnson', *, standardize=True, copy=True):
    pt = PowerTransformer(method=method, standardize=standardize, copy=copy)
    return pt.fit_transform(X)

def fit(self, X, y=None):
    self._reset()
    return self.partial_fit(X, y)

def _reset(self):
    if hasattr(self, 'scale_'):
        del self.scale_
        del self.n_samples_seen_
        del self.mean_
        del self.var_

def fit(self, X, y=None, sample_weight=None):
    self._reset()
    return self.partial_fit(X, y, sample_weight)

@_fit_context(prefer_skip_nested_validation=True)
def partial_fit(self, X, y=None, sample_weight=None):
    xp, _, X_device = get_namespace_and_device(X)
    first_call = not hasattr(self, 'n_samples_seen_')
    X = validate_data(self, X, accept_sparse=('csr', 'csc'), dtype=supported_float_dtypes(xp, X_device), ensure_all_finite='allow-nan', reset=first_call)
    n_features = X.shape[1]
    callback_ctx = self._init_callback_context()
    callback_ctx.call_on_fit_task_begin(estimator=self, X=X, y=y, metadata={'sample_weight': sample_weight})
    if sample_weight is not None:
        sample_weight = _check_sample_weight(sample_weight, X, dtype=X.dtype)
    dtype = xp.int64 if sample_weight is None else X.dtype
    if first_call:
        self.n_samples_seen_ = xp.zeros(n_features, dtype=dtype, device=X_device)
    elif size(self.n_samples_seen_) == 1:
        self.n_samples_seen_ = xp.repeat(self.n_samples_seen_, X.shape[1])
        self.n_samples_seen_ = xp.astype(self.n_samples_seen_, dtype, copy=False)
    if sparse.issparse(X):
        if self.with_mean:
            raise ValueError('Cannot center sparse matrices: pass `with_mean=False` instead. See docstring for motivation and alternatives.')
        sparse_constructor = sparse.csr_array if X.format == 'csr' else sparse.csc_array
        if self.with_std:
            if not hasattr(self, 'scale_'):
                self.mean_, self.var_, self.n_samples_seen_ = mean_variance_axis(X, axis=0, weights=sample_weight, return_sum_weights=True)
            else:
                self.mean_, self.var_, self.n_samples_seen_ = incr_mean_variance_axis(X, axis=0, last_mean=self.mean_, last_var=self.var_, last_n=self.n_samples_seen_, weights=sample_weight)
            self.mean_ = self.mean_.astype(np.float64, copy=False)
            self.var_ = self.var_.astype(np.float64, copy=False)
        else:
            self.mean_ = None
            self.var_ = None
            weights = _check_sample_weight(sample_weight, X)
            sum_weights_nan = weights @ sparse_constructor((np.isnan(X.data), X.indices, X.indptr), shape=X.shape)
            self.n_samples_seen_ += (np.sum(weights) - sum_weights_nan).astype(dtype)
    else:
        if not hasattr(self, 'scale_'):
            self.mean_ = 0.0
            if self.with_std:
                self.var_ = 0.0
            else:
                self.var_ = None
        if not self.with_mean and (not self.with_std):
            self.mean_ = None
            self.var_ = None
            self.n_samples_seen_ += X.shape[0] - xp.isnan(X).sum(axis=0)
        else:
            self.mean_, self.var_, self.n_samples_seen_ = _incremental_mean_and_var(X, self.mean_, self.var_, self.n_samples_seen_, sample_weight=sample_weight)
    if xp.max(self.n_samples_seen_) == xp.min(self.n_samples_seen_):
        self.n_samples_seen_ = self.n_samples_seen_[0]
    if self.with_std:
        constant_mask = _is_constant_feature(self.var_, self.mean_, self.n_samples_seen_)
        self.scale_ = _handle_zeros_in_scale(xp.sqrt(self.var_), copy=False, constant_mask=constant_mask)
    else:
        self.scale_ = None
    callback_ctx.call_on_fit_task_end(estimator=self, X=X, y=y, metadata={'sample_weight': sample_weight}, reconstruction_attributes={})
    return self

def transform(self, X, copy=None):
    xp, _, X_device = get_namespace_and_device(X)
    check_is_fitted(self)
    copy = copy if copy is not None else self.copy
    X = validate_data(self, X, reset=False, accept_sparse='csr', copy=copy, dtype=supported_float_dtypes(xp, X_device), force_writeable=True, ensure_all_finite='allow-nan')
    if sparse.issparse(X):
        if self.with_mean:
            raise ValueError('Cannot center sparse matrices: pass `with_mean=False` instead. See docstring for motivation and alternatives.')
        if self.scale_ is not None:
            inplace_column_scale(X, 1 / self.scale_)
    else:
        if self.with_mean:
            X -= xp.astype(self.mean_, X.dtype)
        if self.with_std:
            X /= xp.astype(self.scale_, X.dtype)
    return X

def inverse_transform(self, X, copy=None):
    xp, _, X_device = get_namespace_and_device(X)
    check_is_fitted(self)
    copy = copy if copy is not None else self.copy
    X = check_array(X, accept_sparse='csr', copy=copy, dtype=supported_float_dtypes(xp, X_device), force_writeable=True, ensure_all_finite='allow-nan')
    if sparse.issparse(X):
        if self.with_mean:
            raise ValueError('Cannot uncenter sparse matrices: pass `with_mean=False` instead See docstring for motivation and alternatives.')
        if self.scale_ is not None:
            inplace_column_scale(X, self.scale_)
    else:
        if self.with_std:
            X *= xp.astype(self.scale_, X.dtype)
        if self.with_mean:
            X += xp.astype(self.mean_, X.dtype)
    return X

def _reset(self):
    if hasattr(self, 'scale_'):
        del self.scale_
        del self.n_samples_seen_
        del self.max_abs_

def fit(self, X, y=None):
    self._reset()
    return self.partial_fit(X, y)

@_fit_context(prefer_skip_nested_validation=True)
def partial_fit(self, X, y=None):
    xp, _ = get_namespace(X)
    first_pass = not hasattr(self, 'n_samples_seen_')
    X = validate_data(self, X, reset=first_pass, accept_sparse=('csr', 'csc'), dtype=_array_api.supported_float_dtypes(xp, device=device(X)), ensure_all_finite='allow-nan')
    if sparse.issparse(X):
        mins, maxs = min_max_axis(X, axis=0, ignore_nan=True)
        max_abs = np.maximum(np.abs(mins), np.abs(maxs))
    else:
        max_abs = _array_api._nanmax(xp.abs(X), axis=0, xp=xp)
    if first_pass:
        self.n_samples_seen_ = X.shape[0]
    else:
        max_abs = xp.maximum(self.max_abs_, max_abs)
        self.n_samples_seen_ += X.shape[0]
    self.max_abs_ = max_abs
    self.scale_ = _handle_zeros_in_scale(max_abs, copy=True)
    return self

def transform(self, X):
    check_is_fitted(self)
    xp, _ = get_namespace(X)
    X = validate_data(self, X, accept_sparse=('csr', 'csc'), copy=self.copy, reset=False, dtype=_array_api.supported_float_dtypes(xp, device=device(X)), force_writeable=True, ensure_all_finite='allow-nan')
    if sparse.issparse(X):
        inplace_column_scale(X, 1.0 / self.scale_)
        if self.clip:
            np.clip(X.data, -1.0, 1.0, out=X.data)
    else:
        X /= self.scale_
        if self.clip:
            device_ = device(X)
            X = _modify_in_place_if_numpy(xp, xp.clip, X, xp.asarray(-1.0, dtype=X.dtype, device=device_), xp.asarray(1.0, dtype=X.dtype, device=device_), out=X)
    return X

def inverse_transform(self, X):
    check_is_fitted(self)
    xp, _ = get_namespace(X)
    X = check_array(X, accept_sparse=('csr', 'csc'), copy=self.copy, dtype=_array_api.supported_float_dtypes(xp, device=device(X)), force_writeable=True, ensure_all_finite='allow-nan')
    if sparse.issparse(X):
        inplace_column_scale(X, self.scale_)
    else:
        X *= self.scale_
    return X

@_fit_context(prefer_skip_nested_validation=True)
def fit(self, X, y=None):
    X = validate_data(self, X, accept_sparse='csc', dtype=FLOAT_DTYPES, ensure_all_finite='allow-nan')
    q_min, q_max = self.quantile_range
    if not 0 <= q_min <= q_max <= 100:
        raise ValueError('Invalid quantile range: %s' % str(self.quantile_range))
    if self.with_centering:
        if sparse.issparse(X):
            raise ValueError('Cannot center sparse matrices: use `with_centering=False` instead. See docstring for motivation and alternatives.')
        self.center_ = np.nanmedian(X, axis=0)
    else:
        self.center_ = None
    if self.with_scaling:
        quantiles = []
        for feature_idx in range(X.shape[1]):
            if sparse.issparse(X):
                column_nnz_data = X.data[X.indptr[feature_idx]:X.indptr[feature_idx + 1]]
                column_data = np.zeros(shape=X.shape[0], dtype=X.dtype)
                column_data[:len(column_nnz_data)] = column_nnz_data
            else:
                column_data = X[:, feature_idx]
            quantiles.append(np.nanpercentile(column_data, self.quantile_range))
        quantiles = np.transpose(quantiles)
        self.scale_ = quantiles[1] - quantiles[0]
        self.scale_ = _handle_zeros_in_scale(self.scale_, copy=False)
        if self.unit_variance:
            adjust = stats.norm.ppf(q_max / 100.0) - stats.norm.ppf(q_min / 100.0)
            self.scale_ = self.scale_ / adjust
    else:
        self.scale_ = None
    return self

def transform(self, X):
    check_is_fitted(self)
    X = validate_data(self, X, accept_sparse=('csr', 'csc'), copy=self.copy, dtype=FLOAT_DTYPES, force_writeable=True, reset=False, ensure_all_finite='allow-nan')
    if sparse.issparse(X):
        if self.with_scaling:
            inplace_column_scale(X, 1.0 / self.scale_)
    else:
        if self.with_centering:
            X -= self.center_
        if self.with_scaling:
            X /= self.scale_
    return X

def inverse_transform(self, X):
    check_is_fitted(self)
    X = check_array(X, accept_sparse=('csr', 'csc'), copy=self.copy, dtype=FLOAT_DTYPES, force_writeable=True, ensure_all_finite='allow-nan')
    if sparse.issparse(X):
        if self.with_scaling:
            inplace_column_scale(X, self.scale_)
    else:
        if self.with_scaling:
            X *= self.scale_
        if self.with_centering:
            X += self.center_
    return X

@_fit_context(prefer_skip_nested_validation=True)
def fit(self, X, y=None):
    validate_data(self, X, accept_sparse='csr')
    return self

def transform(self, X, copy=None):
    copy = copy if copy is not None else self.copy
    X = validate_data(self, X, accept_sparse='csr', force_writeable=True, copy=copy, reset=False)
    return normalize(X, norm=self.norm, axis=1, copy=False)

@_fit_context(prefer_skip_nested_validation=True)
def fit(self, X, y=None):
    validate_data(self, X, accept_sparse='csr')
    return self

def transform(self, X, copy=None):
    copy = copy if copy is not None else self.copy
    X = validate_data(self, X, accept_sparse=['csr', 'csc'], force_writeable=True, copy=copy, reset=False)
    return binarize(X, threshold=self.threshold, copy=False)

@property
def _n_features_out(self):
    return self.n_features_in_

def _dense_fit(self, X, random_state):
    if self.ignore_implicit_zeros:
        warnings.warn("'ignore_implicit_zeros' takes effect only with sparse matrix. This parameter has no effect.")
    n_samples, n_features = X.shape
    references = self.references_ * 100
    if self.subsample is not None and self.subsample < n_samples:
        X = resample(X, replace=False, n_samples=self.subsample, random_state=random_state)
    self.quantiles_ = np.nanpercentile(X, references, axis=0)

def _sparse_fit(self, X, random_state):
    n_samples, n_features = X.shape
    references = self.references_ * 100
    self.quantiles_ = []
    for feature_idx in range(n_features):
        column_nnz_data = X.data[X.indptr[feature_idx]:X.indptr[feature_idx + 1]]
        if self.subsample is not None and len(column_nnz_data) > self.subsample:
            column_subsample = self.subsample * len(column_nnz_data) // n_samples
            if self.ignore_implicit_zeros:
                column_data = np.zeros(shape=column_subsample, dtype=X.dtype)
            else:
                column_data = np.zeros(shape=self.subsample, dtype=X.dtype)
            column_data[:column_subsample] = random_state.choice(column_nnz_data, size=column_subsample, replace=False)
        else:
            if self.ignore_implicit_zeros:
                column_data = np.zeros(shape=len(column_nnz_data), dtype=X.dtype)
            else:
                column_data = np.zeros(shape=n_samples, dtype=X.dtype)
            column_data[:len(column_nnz_data)] = column_nnz_data
        if not column_data.size:
            self.quantiles_.append([0] * len(references))
        else:
            self.quantiles_.append(np.nanpercentile(column_data, references))
    self.quantiles_ = np.transpose(self.quantiles_)

@_fit_context(prefer_skip_nested_validation=True)
def fit(self, X, y=None):
    if self.subsample is not None and self.n_quantiles > self.subsample:
        raise ValueError('The number of quantiles cannot be greater than the number of samples used. Got {} quantiles and {} samples.'.format(self.n_quantiles, self.subsample))
    X = self._check_inputs(X, in_fit=True, copy=False)
    n_samples = X.shape[0]
    if self.n_quantiles > n_samples:
        warnings.warn('n_quantiles (%s) is greater than the total number of samples (%s). n_quantiles is set to n_samples.' % (self.n_quantiles, n_samples))
    self.n_quantiles_ = max(1, min(self.n_quantiles, n_samples))
    rng = check_random_state(self.random_state)
    self.references_ = np.linspace(0, 1, self.n_quantiles_, endpoint=True)
    if sparse.issparse(X):
        self._sparse_fit(X, rng)
    else:
        self._dense_fit(X, rng)
    return self

def _check_inputs(self, X, in_fit, accept_sparse_negative=False, copy=False):
    X = validate_data(self, X, reset=in_fit, accept_sparse='csc', copy=copy, dtype=FLOAT_DTYPES, force_writeable=True if not in_fit else None, ensure_all_finite='allow-nan')
    with np.errstate(invalid='ignore'):
        if not accept_sparse_negative and (not self.ignore_implicit_zeros) and (sparse.issparse(X) and np.any(X.data < 0)):
            raise ValueError('QuantileTransformer only accepts non-negative sparse matrices.')
    return X

def _transform(self, X, inverse=False):
    if sparse.issparse(X):
        for feature_idx in range(X.shape[1]):
            column_slice = slice(X.indptr[feature_idx], X.indptr[feature_idx + 1])
            X.data[column_slice] = self._transform_col(X.data[column_slice], self.quantiles_[:, feature_idx], inverse)
    else:
        for feature_idx in range(X.shape[1]):
            X[:, feature_idx] = self._transform_col(X[:, feature_idx], self.quantiles_[:, feature_idx], inverse)
    return X

def transform(self, X):
    check_is_fitted(self)
    X = self._check_inputs(X, in_fit=False, copy=self.copy)
    return self._transform(X, inverse=False)

def inverse_transform(self, X):
    check_is_fitted(self)
    X = check_array(X, accept_sparse='csc', copy=self.copy, dtype=FLOAT_DTYPES, force_writeable=True, ensure_all_finite='allow-nan')
    if not X.shape[1] == self.n_features_in_:
        raise ValueError(f'X has {X.shape[1]} features, but QuantileTransformer is expecting {self.n_features_in_} features as input.')
    return self._transform(X, inverse=True)

@_fit_context(prefer_skip_nested_validation=True)
def fit(self, X, y=None):
    self._fit(X, y=y, force_transform=False)
    return self

@_fit_context(prefer_skip_nested_validation=True)
def fit_transform(self, X, y=None):
    return self._fit(X, y, force_transform=True)

def transform(self, X):
    check_is_fitted(self)
    X = self._check_input(X, in_fit=False, check_positive=True, check_shape=True)
    transform_function = {'box-cox': boxcox, 'yeo-johnson': stats.yeojohnson}[self.method]
    for i, lmbda in enumerate(self.lambdas_):
        with np.errstate(invalid='ignore'):
            X[:, i] = transform_function(X[:, i], lmbda)
    if self.standardize:
        X = self._scaler.transform(X)
    return X

def inverse_transform(self, X):
    check_is_fitted(self)
    X = check_array(X, copy=self.copy, dtype=FLOAT_DTYPES, force_writeable=True, ensure_all_finite='allow-nan')
    if not X.shape[1] == self.n_features_in_:
        raise ValueError(f'X has {X.shape[1]} features, but PowerTransformer is expecting {self.n_features_in_} features as input.')
    if self.standardize:
        X = self._scaler.inverse_transform(X)
    inv_fun = {'box-cox': inv_boxcox, 'yeo-johnson': self._yeo_johnson_inverse_transform}[self.method]
    for i, lmbda in enumerate(self.lambdas_):
        with warnings.catch_warnings(record=True) as captured_warnings:
            with np.errstate(invalid='warn'):
                X[:, i] = inv_fun(X[:, i], lmbda)
        if any(('invalid value encountered in power' in str(w.message) for w in captured_warnings)):
            warnings.warn(f'Some values in column {i} of the inverse-transformed data are NaN. This may be caused by numerical issues in the transformation process, e.g. extremely skewed data. Consider inspecting the input data or preprocessing it before applying the transformation.', UserWarning)
    return X

def _yeo_johnson_inverse_transform(self, x, lmbda):
    x_inv = np.zeros_like(x)
    pos = x >= 0
    if abs(lmbda) < np.spacing(1.0):
        x_inv[pos] = np.exp(x[pos]) - 1
    else:
        x_inv[pos] = np.power(x[pos] * lmbda + 1, 1 / lmbda) - 1
    if abs(lmbda - 2) > np.spacing(1.0):
        x_inv[~pos] = 1 - np.power(-(2 - lmbda) * x[~pos] + 1, 1 / (2 - lmbda))
    else:
        x_inv[~pos] = 1 - np.exp(-x[~pos])
    return x_inv

def _box_cox_optimize(self, x):
    mask = np.isnan(x)
    if np.all(mask):
        raise ValueError('Column must not be all nan.')
    _, lmbda = stats.boxcox(x[~mask], lmbda=None)
    return lmbda

def _check_input(self, X, in_fit, check_positive=False, check_shape=False):
    X = validate_data(self, X, ensure_2d=True, dtype=FLOAT_DTYPES, force_writeable=True, copy=self.copy, ensure_all_finite='allow-nan', reset=in_fit)
    with warnings.catch_warnings():
        warnings.filterwarnings('ignore', 'All-NaN (slice|axis) encountered')
        if check_positive and self.method == 'box-cox' and (np.nanmin(X) <= 0):
            raise ValueError('The Box-Cox transformation can only be applied to strictly positive data')
    if check_shape and (not X.shape[1] == len(self.lambdas_)):
        raise ValueError('Input data has a different number of features than fitting data. Should have {n}, data has {m}'.format(n=len(self.lambdas_), m=X.shape[1]))
    return X

@_fit_context(prefer_skip_nested_validation=True)
def fit(self, X, y=None, sample_weight=None):
    X = validate_data(self, X, dtype='numeric')
    if self.dtype in (np.float64, np.float32):
        output_dtype = self.dtype
    else:
        output_dtype = X.dtype
    n_samples, n_features = X.shape
    if sample_weight is not None:
        sample_weight = _check_sample_weight(sample_weight, X, dtype=X.dtype)
    if self.subsample is not None and n_samples > self.subsample:
        X = resample(X, replace=True, n_samples=self.subsample, random_state=self.random_state, sample_weight=sample_weight)
        sample_weight = None
    n_features = X.shape[1]
    n_bins = self._validate_n_bins(n_features)
    bin_edges = np.zeros(n_features, dtype=object)
    quantile_method = self.quantile_method
    if self.strategy == 'quantile' and quantile_method not in ['inverted_cdf', 'averaged_inverted_cdf'] and (sample_weight is not None):
        raise ValueError(f"When fitting with strategy='quantile' and sample weights, quantile_method should either be set to 'averaged_inverted_cdf' or 'inverted_cdf', got quantile_method='{quantile_method}' instead.")
    if self.strategy != 'quantile' and sample_weight is not None:
        nnz_weight_mask = sample_weight != 0
    else:
        nnz_weight_mask = slice(None)
    for jj in range(n_features):
        column = X[:, jj]
        col_min = column[nnz_weight_mask].min()
        col_max = column[nnz_weight_mask].max()
        if col_min == col_max:
            warnings.warn('Feature %d is constant and will be replaced with 0.' % jj)
            n_bins[jj] = 1
            bin_edges[jj] = np.array([-np.inf, np.inf])
            continue
        if self.strategy == 'uniform':
            bin_edges[jj] = np.linspace(col_min, col_max, n_bins[jj] + 1)
        elif self.strategy == 'quantile':
            percentile_levels = np.linspace(0, 100, n_bins[jj] + 1)
            percentile_kwargs = {}
            if quantile_method != 'linear' and sample_weight is None:
                percentile_kwargs['method'] = quantile_method
            if sample_weight is None:
                bin_edges[jj] = np.asarray(np.percentile(column, percentile_levels, **percentile_kwargs), dtype=np.float64)
            else:
                average = True if quantile_method == 'averaged_inverted_cdf' else False
                bin_edges[jj] = _weighted_percentile(column, sample_weight, percentile_levels, average=average)
        elif self.strategy == 'kmeans':
            from sklearn.cluster import KMeans
            uniform_edges = np.linspace(col_min, col_max, n_bins[jj] + 1)
            init = (uniform_edges[1:] + uniform_edges[:-1])[:, None] * 0.5
            km = KMeans(n_clusters=n_bins[jj], init=init, n_init=1)
            centers = km.fit(column[:, None], sample_weight=sample_weight).cluster_centers_[:, 0]
            centers.sort()
            bin_edges[jj] = (centers[1:] + centers[:-1]) * 0.5
            bin_edges[jj] = np.r_[col_min, bin_edges[jj], col_max]
        if self.strategy in ('quantile', 'kmeans'):
            mask = np.ediff1d(bin_edges[jj], to_begin=np.inf) > 1e-08
            bin_edges[jj] = bin_edges[jj][mask]
            if len(bin_edges[jj]) - 1 != n_bins[jj]:
                warnings.warn('Bins whose width are too small (i.e., <= 1e-8) in feature %d are removed. Consider decreasing the number of bins.' % jj)
                n_bins[jj] = len(bin_edges[jj]) - 1
    self.bin_edges_ = bin_edges
    self.n_bins_ = n_bins
    if 'onehot' in self.encode:
        self._encoder = OneHotEncoder(categories=[np.arange(i) for i in self.n_bins_], sparse_output=self.encode == 'onehot', dtype=output_dtype)
        self._encoder.fit(np.zeros((1, len(self.n_bins_))))
    return self

def _validate_n_bins(self, n_features):
    orig_bins = self.n_bins
    if isinstance(orig_bins, Integral):
        return np.full(n_features, orig_bins, dtype=int)
    n_bins = check_array(orig_bins, dtype=int, copy=True, ensure_2d=False)
    if n_bins.ndim > 1 or n_bins.shape[0] != n_features:
        raise ValueError('n_bins must be a scalar or array of shape (n_features,).')
    bad_nbins_value = (n_bins < 2) | (n_bins != orig_bins)
    violating_indices = np.where(bad_nbins_value)[0]
    if violating_indices.shape[0] > 0:
        indices = ', '.join((str(i) for i in violating_indices))
        raise ValueError('{} received an invalid number of bins at indices {}. Number of bins must be at least 2, and must be an int.'.format(KBinsDiscretizer.__name__, indices))
    return n_bins

def inverse_transform(self, X):
    check_is_fitted(self)
    if 'onehot' in self.encode:
        X = self._encoder.inverse_transform(X)
    Xinv = check_array(X, copy=True, dtype=(np.float64, np.float32))
    n_features = self.n_bins_.shape[0]
    if Xinv.shape[1] != n_features:
        raise ValueError('Incorrect number of features. Expecting {}, received {}.'.format(n_features, Xinv.shape[1]))
    for jj in range(n_features):
        bin_edges = self.bin_edges_[jj]
        bin_centers = (bin_edges[1:] + bin_edges[:-1]) * 0.5
        Xinv[:, jj] = bin_centers[Xinv[:, jj].astype(np.int64)]
    return Xinv

def get_feature_names_out(self, input_features=None):
    check_is_fitted(self, 'n_features_in_')
    input_features = _check_feature_names_in(self, input_features)
    if hasattr(self, '_encoder'):
        return self._encoder.get_feature_names_out(input_features)
    return input_features

def _check_X(self, X, ensure_all_finite=True):
    if not (hasattr(X, 'iloc') and getattr(X, 'ndim', 0) == 2):
        X_temp = check_array(X, dtype=None, ensure_all_finite=ensure_all_finite)
        if not hasattr(X, 'dtype') and np.issubdtype(X_temp.dtype, np.str_):
            X = check_array(X, dtype=object, ensure_all_finite=ensure_all_finite)
        else:
            X = X_temp
        needs_validation = False
    else:
        needs_validation = ensure_all_finite
    n_samples, n_features = X.shape
    X_columns = []
    for i in range(n_features):
        Xi = _safe_indexing(X, indices=i, axis=1)
        Xi = check_array(Xi, ensure_2d=False, dtype=None, ensure_all_finite=needs_validation)
        X_columns.append(Xi)
    return (X_columns, n_samples, n_features)

@property
def infrequent_categories_(self):
    infrequent_indices = self._infrequent_indices
    return [None if indices is None else category[indices] for category, indices in zip(self.categories_, infrequent_indices)]

def _identify_infrequent(self, category_count, n_samples, col_idx):
    if isinstance(self.min_frequency, numbers.Integral):
        infrequent_mask = category_count < self.min_frequency
    elif isinstance(self.min_frequency, numbers.Real):
        min_frequency_abs = n_samples * self.min_frequency
        infrequent_mask = category_count < min_frequency_abs
    else:
        infrequent_mask = np.zeros(category_count.shape[0], dtype=bool)
    n_current_features = category_count.size - infrequent_mask.sum() + 1
    if self.max_categories is not None and self.max_categories < n_current_features:
        frequent_category_count = self.max_categories - 1
        if frequent_category_count == 0:
            infrequent_mask[:] = True
        else:
            smallest_levels = np.argsort(category_count, kind='mergesort')[:-frequent_category_count]
            infrequent_mask[smallest_levels] = True
    output = np.flatnonzero(infrequent_mask)
    return output if output.size > 0 else None

def _fit_infrequent_category_mapping(self, n_samples, category_counts, missing_indices):
    if missing_indices:
        category_counts_ = []
        for feature_idx, count in enumerate(category_counts):
            if feature_idx in missing_indices:
                category_counts_.append(np.delete(count, missing_indices[feature_idx]))
            else:
                category_counts_.append(count)
    else:
        category_counts_ = category_counts
    self._infrequent_indices = [self._identify_infrequent(category_count, n_samples, col_idx) for col_idx, category_count in enumerate(category_counts_)]
    self._default_to_infrequent_mappings = []
    for feature_idx, infreq_idx in enumerate(self._infrequent_indices):
        cats = self.categories_[feature_idx]
        if infreq_idx is None:
            self._default_to_infrequent_mappings.append(None)
            continue
        n_cats = len(cats)
        if feature_idx in missing_indices:
            n_cats -= 1
        mapping = np.empty(n_cats, dtype=np.int64)
        n_infrequent_cats = infreq_idx.size
        n_frequent_cats = n_cats - n_infrequent_cats
        mapping[infreq_idx] = n_frequent_cats
        frequent_indices = np.setdiff1d(np.arange(n_cats), infreq_idx)
        mapping[frequent_indices] = np.arange(n_frequent_cats)
        self._default_to_infrequent_mappings.append(mapping)

def _map_infrequent_categories(self, X_int, X_mask, ignore_category_indices):
    if not self._infrequent_enabled:
        return
    ignore_category_indices = ignore_category_indices or {}
    for col_idx in range(X_int.shape[1]):
        infrequent_idx = self._infrequent_indices[col_idx]
        if infrequent_idx is None:
            continue
        X_int[~X_mask[:, col_idx], col_idx] = infrequent_idx[0]
        if self.handle_unknown in ('infrequent_if_exist', 'warn'):
            X_mask[:, col_idx] = True
    for i, mapping in enumerate(self._default_to_infrequent_mappings):
        if mapping is None:
            continue
        if i in ignore_category_indices:
            rows_to_update = X_int[:, i] != ignore_category_indices[i]
        else:
            rows_to_update = slice(None)
        X_int[rows_to_update, i] = np.take(mapping, X_int[rows_to_update, i])

def _map_drop_idx_to_infrequent(self, feature_idx, drop_idx):
    if not self._infrequent_enabled:
        return drop_idx
    default_to_infrequent = self._default_to_infrequent_mappings[feature_idx]
    if default_to_infrequent is None:
        return drop_idx
    infrequent_indices = self._infrequent_indices[feature_idx]
    if infrequent_indices is not None and drop_idx in infrequent_indices:
        categories = self.categories_[feature_idx]
        raise ValueError(f'Unable to drop category {categories[drop_idx].item()!r} from feature {feature_idx} because it is infrequent')
    return default_to_infrequent[drop_idx]

def _set_drop_idx(self):
    if self.drop is None:
        drop_idx_after_grouping = None
    elif isinstance(self.drop, str):
        if self.drop == 'first':
            drop_idx_after_grouping = np.zeros(len(self.categories_), dtype=object)
        elif self.drop == 'if_binary':
            n_features_out_no_drop = [len(cat) for cat in self.categories_]
            if self._infrequent_enabled:
                for i, infreq_idx in enumerate(self._infrequent_indices):
                    if infreq_idx is None:
                        continue
                    n_features_out_no_drop[i] -= infreq_idx.size - 1
            drop_idx_after_grouping = np.array([0 if n_features_out == 2 else None for n_features_out in n_features_out_no_drop], dtype=object)
    else:
        drop_array = np.asarray(self.drop, dtype=object)
        droplen = len(drop_array)
        if droplen != len(self.categories_):
            msg = '`drop` should have length equal to the number of features ({}), got {}'
            raise ValueError(msg.format(len(self.categories_), droplen))
        missing_drops = []
        drop_indices = []
        for feature_idx, (drop_val, cat_list) in enumerate(zip(drop_array, self.categories_)):
            if not is_scalar_nan(drop_val):
                drop_idx = np.where(cat_list == drop_val)[0]
                if drop_idx.size:
                    drop_indices.append(self._map_drop_idx_to_infrequent(feature_idx, drop_idx[0]))
                else:
                    missing_drops.append((feature_idx, drop_val))
                continue
            if is_scalar_nan(cat_list[-1]):
                drop_indices.append(self._map_drop_idx_to_infrequent(feature_idx, cat_list.size - 1))
            else:
                missing_drops.append((feature_idx, drop_val))
        if any(missing_drops):
            msg = 'The following categories were supposed to be dropped, but were not found in the training data.\n{}'.format('\n'.join(['Category: {}, Feature: {}'.format(c, v) for c, v in missing_drops]))
            raise ValueError(msg)
        drop_idx_after_grouping = np.array(drop_indices, dtype=object)
    self._drop_idx_after_grouping = drop_idx_after_grouping
    if not self._infrequent_enabled or drop_idx_after_grouping is None:
        self.drop_idx_ = self._drop_idx_after_grouping
    else:
        drop_idx_ = []
        for feature_idx, drop_idx in enumerate(drop_idx_after_grouping):
            default_to_infrequent = self._default_to_infrequent_mappings[feature_idx]
            if drop_idx is None or default_to_infrequent is None:
                orig_drop_idx = drop_idx
            else:
                orig_drop_idx = np.flatnonzero(default_to_infrequent == drop_idx)[0]
            drop_idx_.append(orig_drop_idx)
        self.drop_idx_ = np.asarray(drop_idx_, dtype=object)

def _compute_transformed_categories(self, i, remove_dropped=True):
    cats = self.categories_[i]
    if self._infrequent_enabled:
        infreq_map = self._default_to_infrequent_mappings[i]
        if infreq_map is not None:
            frequent_mask = infreq_map < infreq_map.max()
            infrequent_cat = 'infrequent_sklearn'
            cats = np.concatenate((cats[frequent_mask], np.array([infrequent_cat], dtype=object)))
    if remove_dropped:
        cats = self._remove_dropped_categories(cats, i)
    return cats

def _remove_dropped_categories(self, categories, i):
    if self._drop_idx_after_grouping is not None and self._drop_idx_after_grouping[i] is not None:
        return np.delete(categories, self._drop_idx_after_grouping[i])
    return categories

def _compute_n_features_outs(self):
    output = [len(cats) for cats in self.categories_]
    if self._drop_idx_after_grouping is not None:
        for i, drop_idx in enumerate(self._drop_idx_after_grouping):
            if drop_idx is not None:
                output[i] -= 1
    if not self._infrequent_enabled:
        return output
    for i, infreq_idx in enumerate(self._infrequent_indices):
        if infreq_idx is None:
            continue
        output[i] -= infreq_idx.size - 1
    return output

@_fit_context(prefer_skip_nested_validation=True)
def fit(self, X, y=None):
    self._fit(X, handle_unknown=self.handle_unknown, ensure_all_finite='allow-nan')
    self._set_drop_idx()
    self._n_features_outs = self._compute_n_features_outs()
    return self

def transform(self, X):
    check_is_fitted(self)
    transform_output = _get_output_config('transform', estimator=self)['dense']
    if transform_output != 'default' and self.sparse_output:
        capitalize_transform_output = transform_output.capitalize()
        raise ValueError(f'{capitalize_transform_output} output does not support sparse data. Set sparse_output=False to output {transform_output} dataframes or disable {capitalize_transform_output} output via` ohe.set_output(transform="default").')
    if self.handle_unknown == 'warn':
        warn_on_unknown, handle_unknown = (True, 'infrequent_if_exist')
    else:
        warn_on_unknown = self.drop is not None and self.handle_unknown in {'ignore', 'infrequent_if_exist'}
        handle_unknown = self.handle_unknown
    X_int, X_mask = self._transform(X, handle_unknown=handle_unknown, ensure_all_finite='allow-nan', warn_on_unknown=warn_on_unknown)
    n_samples, n_features = X_int.shape
    if self._drop_idx_after_grouping is not None:
        to_drop = self._drop_idx_after_grouping.copy()
        keep_cells = X_int != to_drop
        for i, cats in enumerate(self.categories_):
            if to_drop[i] is None:
                to_drop[i] = len(cats)
        to_drop = to_drop.reshape(1, -1)
        X_int[X_int > to_drop] -= 1
        X_mask &= keep_cells
    feature_indices = np.cumsum([0] + self._n_features_outs)
    X_int += feature_indices[:-1]
    indices = X_int[X_mask].ravel()
    indptr = np.empty(n_samples + 1, dtype=int)
    indptr[0] = 0
    np.sum(X_mask, axis=1, out=indptr[1:], dtype=indptr.dtype)
    np.cumsum(indptr[1:], out=indptr[1:])
    data = np.ones(indptr[-1])
    out = sparse.csr_array((data, indices, indptr), shape=(n_samples, feature_indices[-1]), dtype=self.dtype)
    if self.sparse_output:
        _ensure_sparse_index_int32(out)
        return _align_api_if_sparse(out)
    else:
        return out.toarray()

def inverse_transform(self, X):
    check_is_fitted(self)
    X = check_array(X, accept_sparse='csr')
    n_samples, _ = X.shape
    n_features = len(self.categories_)
    n_features_out = np.sum(self._n_features_outs)
    msg = 'Shape of the passed X data is not correct. Expected {0} columns, got {1}.'
    if X.shape[1] != n_features_out:
        raise ValueError(msg.format(n_features_out, X.shape[1]))
    transformed_features = [self._compute_transformed_categories(i, remove_dropped=False) for i, _ in enumerate(self.categories_)]
    dt = np.result_type(*[cat.dtype for cat in transformed_features])
    X_tr = np.empty((n_samples, n_features), dtype=dt)
    j = 0
    found_unknown = {}
    if self._infrequent_enabled:
        infrequent_indices = self._infrequent_indices
    else:
        infrequent_indices = [None] * n_features
    for i in range(n_features):
        cats_wo_dropped = self._remove_dropped_categories(transformed_features[i], i)
        n_categories = cats_wo_dropped.shape[0]
        if n_categories == 0:
            X_tr[:, i] = self.categories_[i][self._drop_idx_after_grouping[i]]
            j += n_categories
            continue
        sub = X[:, j:j + n_categories]
        labels = np.asarray(sub.argmax(axis=1)).flatten()
        X_tr[:, i] = cats_wo_dropped[labels]
        if self.handle_unknown == 'ignore' or (self.handle_unknown in ('infrequent_if_exist', 'warn') and infrequent_indices[i] is None):
            unknown = np.asarray(sub.sum(axis=1) == 0).flatten()
            if unknown.any():
                if self._drop_idx_after_grouping is None or self._drop_idx_after_grouping[i] is None:
                    found_unknown[i] = unknown
                else:
                    X_tr[unknown, i] = self.categories_[i][self._drop_idx_after_grouping[i]]
        else:
            dropped = np.asarray(sub.sum(axis=1) == 0).flatten()
            if dropped.any():
                if self._drop_idx_after_grouping is None:
                    all_zero_samples = np.flatnonzero(dropped)
                    raise ValueError(f"Samples {all_zero_samples} can not be inverted when drop=None and handle_unknown='error' because they contain all zeros")
                drop_idx = self._drop_idx_after_grouping[i]
                X_tr[dropped, i] = transformed_features[i][drop_idx]
        j += n_categories
    if found_unknown:
        if X_tr.dtype != object:
            X_tr = X_tr.astype(object)
        for idx, mask in found_unknown.items():
            X_tr[mask, idx] = None
    return X_tr

def get_feature_names_out(self, input_features=None):
    check_is_fitted(self)
    input_features = _check_feature_names_in(self, input_features)
    cats = [self._compute_transformed_categories(i) for i, _ in enumerate(self.categories_)]
    name_combiner = self._check_get_feature_name_combiner()
    feature_names = []
    for i in range(len(cats)):
        names = [name_combiner(input_features[i], t) for t in cats[i]]
        feature_names.extend(names)
    return np.array(feature_names, dtype=object)

@_fit_context(prefer_skip_nested_validation=True)
def fit(self, X, y=None):
    if self.handle_unknown == 'use_encoded_value':
        if is_scalar_nan(self.unknown_value):
            if np.dtype(self.dtype).kind != 'f':
                raise ValueError(f'When unknown_value is np.nan, the dtype parameter should be a float dtype. Got {self.dtype}.')
        elif not isinstance(self.unknown_value, numbers.Integral):
            raise TypeError(f"unknown_value should be an integer or np.nan when handle_unknown is 'use_encoded_value', got {self.unknown_value}.")
    elif self.unknown_value is not None:
        raise TypeError(f"unknown_value should only be set when handle_unknown is 'use_encoded_value', got {self.unknown_value}.")
    fit_results = self._fit(X, handle_unknown=self.handle_unknown, ensure_all_finite='allow-nan', return_and_ignore_missing_for_infrequent=True)
    self._missing_indices = fit_results['missing_indices']
    cardinalities = [len(categories) for categories in self.categories_]
    if self._infrequent_enabled:
        for feature_idx, infrequent in enumerate(self.infrequent_categories_):
            if infrequent is not None:
                cardinalities[feature_idx] -= len(infrequent)
    for cat_idx, categories_for_idx in enumerate(self.categories_):
        if is_scalar_nan(categories_for_idx[-1]):
            cardinalities[cat_idx] -= 1
    if self.handle_unknown == 'use_encoded_value':
        for cardinality in cardinalities:
            if 0 <= self.unknown_value < cardinality:
                raise ValueError(f'The used value for unknown_value {self.unknown_value} is one of the values already used for encoding the seen categories.')
    if self._missing_indices:
        if np.dtype(self.dtype).kind != 'f' and is_scalar_nan(self.encoded_missing_value):
            raise ValueError(f'There are missing values in features {list(self._missing_indices)}. For OrdinalEncoder to encode missing values with dtype: {self.dtype}, set encoded_missing_value to a non-nan value, or set dtype to a float')
        if not is_scalar_nan(self.encoded_missing_value):
            invalid_features = [cat_idx for cat_idx, cardinality in enumerate(cardinalities) if cat_idx in self._missing_indices and 0 <= self.encoded_missing_value < cardinality]
            if invalid_features:
                if hasattr(self, 'feature_names_in_'):
                    invalid_features = self.feature_names_in_[invalid_features]
                raise ValueError(f'encoded_missing_value ({self.encoded_missing_value}) is already used to encode a known category in features: {invalid_features}')
    return self

def transform(self, X):
    check_is_fitted(self, 'categories_')
    X_int, X_mask = self._transform(X, handle_unknown=self.handle_unknown, ensure_all_finite='allow-nan', ignore_category_indices=self._missing_indices)
    X_trans = X_int.astype(self.dtype, copy=False)
    for cat_idx, missing_idx in self._missing_indices.items():
        X_missing_mask = X_int[:, cat_idx] == missing_idx
        X_trans[X_missing_mask, cat_idx] = self.encoded_missing_value
    if self.handle_unknown == 'use_encoded_value':
        X_trans[~X_mask] = self.unknown_value
    return X_trans

def inverse_transform(self, X):
    check_is_fitted(self)
    X = check_array(X, ensure_all_finite='allow-nan')
    n_samples, _ = X.shape
    n_features = len(self.categories_)
    msg = 'Shape of the passed X data is not correct. Expected {0} columns, got {1}.'
    if X.shape[1] != n_features:
        raise ValueError(msg.format(n_features, X.shape[1]))
    dt = np.result_type(*[cat.dtype for cat in self.categories_])
    X_tr = np.empty((n_samples, n_features), dtype=dt)
    found_unknown = {}
    infrequent_masks = {}
    infrequent_indices = getattr(self, '_infrequent_indices', None)
    for i in range(n_features):
        labels = X[:, i]
        if i in self._missing_indices:
            X_i_mask = _get_mask(labels, self.encoded_missing_value)
            labels[X_i_mask] = self._missing_indices[i]
        rows_to_update = slice(None)
        categories = self.categories_[i]
        if infrequent_indices is not None and infrequent_indices[i] is not None:
            infrequent_encoding_value = len(categories) - len(infrequent_indices[i])
            infrequent_masks[i] = labels == infrequent_encoding_value
            rows_to_update = ~infrequent_masks[i]
            frequent_categories_mask = np.ones_like(categories, dtype=bool)
            frequent_categories_mask[infrequent_indices[i]] = False
            categories = categories[frequent_categories_mask]
        if self.handle_unknown == 'use_encoded_value':
            unknown_labels = _get_mask(labels, self.unknown_value)
            found_unknown[i] = unknown_labels
            known_labels = ~unknown_labels
            if isinstance(rows_to_update, np.ndarray):
                rows_to_update &= known_labels
            else:
                rows_to_update = known_labels
        labels_int = labels[rows_to_update].astype('int64', copy=False)
        X_tr[rows_to_update, i] = categories[labels_int]
    if found_unknown or infrequent_masks:
        X_tr = X_tr.astype(object, copy=False)
    if found_unknown:
        for idx, mask in found_unknown.items():
            X_tr[mask, idx] = None
    if infrequent_masks:
        for idx, mask in infrequent_masks.items():
            X_tr[mask, idx] = 'infrequent_sklearn'
    return X_tr

def _check_inverse_transform(self, X):
    idx_selected = slice(None, None, max(1, X.shape[0] // 100))
    X_round_trip = self.inverse_transform(self.transform(X[idx_selected]))
    if hasattr(X, 'dtype'):
        dtypes = [X.dtype]
    elif hasattr(X, 'dtypes'):
        dtypes = X.dtypes
    if not all((isinstance(d, np.dtype) and np.issubdtype(d, np.number) for d in dtypes)):
        raise ValueError("'check_inverse' is only supported when all the elements in `X` is numerical.")
    if not _allclose_dense_sparse(X[idx_selected], X_round_trip):
        warnings.warn("The provided functions are not strictly inverse of each other. If you are sure you want to proceed regardless, set 'check_inverse=False'.", UserWarning)

@_fit_context(prefer_skip_nested_validation=True)
def fit(self, X, y=None):
    X = validate_data(self, X, reset=True, accept_sparse=self.accept_sparse, skip_check_array=not self.validate)
    if self.check_inverse and (not (self.func is None or self.inverse_func is None)):
        self._check_inverse_transform(X)
    return self

def transform(self, X):
    if self.validate:
        X = validate_data(self, X, reset=False, accept_sparse=self.accept_sparse)
    out = self._transform(X, func=self.func, kw_args=self.kw_args)
    output_config = _get_output_config('transform', self)['dense']
    if hasattr(out, 'columns') and self.feature_names_out is not None:
        feature_names_out = self.get_feature_names_out()
        if list(out.columns) != list(feature_names_out):
            feature_names_in = getattr(X, 'feature_names_in_', _get_feature_names(X))
            same_feature_names_in_out = feature_names_in is not None and list(feature_names_in) == list(out.columns)
            not_all_str_columns = not all((isinstance(col, str) for col in out.columns))
            if same_feature_names_in_out or not_all_str_columns:
                adapter = _get_adapter_from_container(out)
                out = adapter.create_container(X_output=out, X_original=out, columns=feature_names_out, inplace=False)
            else:
                raise ValueError(f"The output generated by `func` have different column names than the ones provided by `get_feature_names_out`. Got output with columns names: {list(out.columns)} and `get_feature_names_out` returned: {list(self.get_feature_names_out())}. The column names can be overridden by setting `set_output(transform='pandas')` or `set_output(transform='polars')` such that the column names are set to the names provided by `get_feature_names_out`.")
    if self.feature_names_out is None:
        warn_msg = "When `set_output` is configured to be '{0}', `func` should return a {0} DataFrame to follow the `set_output` API  or `feature_names_out` should be defined."
        if output_config == 'pandas' and (not nw.dependencies.is_pandas_dataframe(out)):
            warnings.warn(warn_msg.format('pandas'))
        elif output_config == 'polars' and (not is_polars_df(out)):
            warnings.warn(warn_msg.format('polars'))
    return out

def inverse_transform(self, X):
    if self.validate:
        X = check_array(X, accept_sparse=self.accept_sparse)
    return self._transform(X, func=self.inverse_func, kw_args=self.inv_kw_args)

@available_if(lambda self: self.feature_names_out is not None)
def get_feature_names_out(self, input_features=None):
    if hasattr(self, 'n_features_in_') or input_features is not None:
        input_features = _check_feature_names_in(self, input_features)
    if self.feature_names_out == 'one-to-one':
        names_out = input_features
    elif callable(self.feature_names_out):
        names_out = self.feature_names_out(self, input_features)
    else:
        raise ValueError(f'feature_names_out={self.feature_names_out!r} is invalid. It must either be "one-to-one" or a callable with two arguments: the function transformer and an array-like of input feature names. The callable must return an array-like of output feature names.')
    return np.asarray(names_out, dtype=object)

def set_output(self, *, transform=None):
    if not hasattr(self, '_sklearn_output_config'):
        self._sklearn_output_config = {}
    self._sklearn_output_config['transform'] = transform
    return self

def _get_function_name(self):
    if hasattr(self.func, '__name__'):
        return self.func.__name__
    if isinstance(self.func, partial):
        return self.func.func.__name__
    return f'{self.func.__class__.__name__}(...)'

@validate_params({'y': ['array-like', 'sparse matrix'], 'classes': ['array-like'], 'neg_label': [Interval(Integral, None, None, closed='neither')], 'pos_label': [Interval(Integral, None, None, closed='neither')], 'sparse_output': ['boolean']}, prefer_skip_nested_validation=True)
def label_binarize(y, *, classes, neg_label=0, pos_label=1, sparse_output=False):
    if not isinstance(y, list):
        y = check_array(y, input_name='y', accept_sparse='csr', ensure_2d=False, dtype=None)
    elif _num_samples(y) == 0:
        raise ValueError('y has 0 samples: %r' % y)
    if neg_label >= pos_label:
        raise ValueError('neg_label={0} must be strictly less than pos_label={1}.'.format(neg_label, pos_label))
    if sparse_output and (pos_label == 0 or neg_label != 0):
        raise ValueError('Sparse binarization is only supported with non zero pos_label and zero neg_label, got pos_label={0} and neg_label={1}'.format(pos_label, neg_label))
    pos_switch = pos_label == 0
    if pos_switch:
        pos_label = -neg_label
    y_type = type_of_target(y)
    if 'multioutput' in y_type:
        raise ValueError('Multioutput target data is not supported with label binarization')
    if y_type == 'unknown':
        raise ValueError('The type of target data is not known')
    xp, is_array_api, device_ = get_namespace_and_device(y)
    if is_array_api and sparse_output and (not _is_numpy_namespace(xp)):
        raise ValueError(f"`sparse_output=True` is not supported for array API 'namespace {xp.__name__}'. Use `sparse_output=False` to return a dense array instead.")
    try:
        classes = xp.asarray(classes, device=device_)
    except (ValueError, TypeError) as e:
        raise ValueError(f"`classes` contains unsupported dtype for array API namespace '{xp.__name__}'.") from e
    n_samples = y.shape[0] if hasattr(y, 'shape') else len(y)
    n_classes = classes.shape[0]
    y_has_dtype = hasattr(y, 'dtype')
    if y_has_dtype and xp.isdtype(y.dtype, 'signed integer'):
        int_dtype_ = y.dtype
    else:
        int_dtype_ = indexing_dtype(xp)
    if y_has_dtype and xp.isdtype(y.dtype, 'integral'):
        classes = xp.astype(classes, y.dtype, copy=False)
    if y_type == 'binary':
        if n_classes == 1:
            if sparse_output:
                return _align_api_if_sparse(sp.csr_array((n_samples, 1), dtype=int))
            else:
                Y = xp.zeros((n_samples, 1), dtype=int_dtype_)
                Y += neg_label
                return Y
        elif n_classes >= 3:
            y_type = 'multiclass'
    sorted_class = xp.sort(classes)
    if y_type == 'multilabel-indicator':
        y_n_classes = y.shape[1] if hasattr(y, 'shape') else len(y[0])
        if n_classes != y_n_classes:
            raise ValueError('classes {0} mismatch with the labels {1} found in the data'.format(classes, unique_labels(y)))
    if y_type in ('binary', 'multiclass'):
        y = column_or_1d(y)
        y_in_classes = _isin(y, classes, xp=xp)
        y_seen = y[y_in_classes]
        indices = xp.searchsorted(sorted_class, y_seen)
        y_in_classes = xp.astype(y_in_classes, int_dtype_)
        indptr = xp.concat((xp.asarray([0], device=device_), xp.cumulative_sum(y_in_classes, axis=0)))
        data = xp.full_like(indices, pos_label)
        Y = sp.csr_array((move_to(data, xp=np, device='cpu'), move_to(indices, xp=np, device='cpu'), move_to(indptr, xp=np, device='cpu')), shape=(n_samples, n_classes))
        if not sparse_output:
            Y = xp.asarray(Y.toarray(), device=device_)
    elif y_type == 'multilabel-indicator':
        if sparse_output:
            Y = sp.csr_array(y)
            if pos_label != 1:
                data = xp.full_like(Y.data, pos_label)
                Y.data = data
        else:
            if sp.issparse(y):
                y = y.toarray()
            Y = xp.asarray(y, device=device_, copy=True)
            if pos_label != 1:
                Y[Y != 0] = pos_label
    else:
        raise ValueError('%s target data is not supported with label binarization' % y_type)
    if not sparse_output:
        if neg_label != 0:
            Y[Y == 0] = neg_label
        if pos_switch:
            Y[Y == pos_label] = 0
        Y = xp.astype(Y, int_dtype_, copy=False)
    else:
        Y.data = Y.data.astype(int, copy=False)
    if xp.any(classes != sorted_class):
        indices = xp.searchsorted(sorted_class, classes)
        Y = Y[:, indices]
    if y_type == 'binary':
        if sparse_output:
            Y = Y[:, [-1]]
        else:
            Y = xp.reshape(Y[:, -1], (-1, 1))
    return _align_api_if_sparse(Y)

def _inverse_binarize_thresholding(y, output_type, classes, threshold, xp=None):
    if output_type == 'binary' and y.ndim == 2 and (y.shape[1] > 2):
        raise ValueError("output_type='binary', but y.shape = {0}".format(y.shape))
    xp, _, device_ = get_namespace_and_device(y, xp=xp)
    classes = xp.asarray(classes, device=device_)
    if output_type != 'binary' and y.shape[1] != classes.shape[0]:
        raise ValueError('The number of class is not equal to the number of dimension of y.')
    dtype_ = _find_matching_floating_dtype(y, xp=xp)
    if hasattr(y, 'dtype') and xp.isdtype(y.dtype, 'signed integer'):
        int_dtype_ = y.dtype
    else:
        int_dtype_ = indexing_dtype(xp)
    if sp.issparse(y):
        if threshold > 0:
            if y.format not in ('csr', 'csc'):
                y = y.tocsr()
            y.data = np.array(y.data > threshold, dtype=int)
            y.eliminate_zeros()
        else:
            y = xp.asarray(y.toarray() > threshold, dtype=int_dtype_, device=device_)
    else:
        y = xp.asarray(xp.asarray(y, dtype=dtype_, device=device_) > threshold, dtype=int_dtype_, device=device_)
    if output_type == 'binary':
        if sp.issparse(y):
            y = y.toarray()
        if y.ndim == 2 and y.shape[1] == 2:
            return classes[y[:, 1]]
        elif classes.shape[0] == 1:
            return xp.repeat(classes[0], len(y))
        else:
            return classes[xp.reshape(y, (-1,))]
    elif output_type == 'multilabel-indicator':
        return y
    else:
        raise ValueError('{0} format is not supported'.format(output_type))

def transform(self, y):
    check_is_fitted(self)
    xp, _ = get_namespace(y)
    y = column_or_1d(y, dtype=self.classes_.dtype, warn=True)
    if _num_samples(y) == 0:
        return xp.asarray([])
    return _encode(y, uniques=self.classes_)

def inverse_transform(self, y):
    check_is_fitted(self)
    xp, _ = get_namespace(y)
    y = column_or_1d(y, warn=True)
    if _num_samples(y) == 0:
        return xp.asarray([])
    diff = xpx.setdiff1d(y, xp.arange(self.classes_.shape[0], device=device(y)), xp=xp)
    if diff.shape[0]:
        raise ValueError('y contains previously unseen labels: %s' % str(diff))
    y = xp.asarray(y)
    return xp.take(self.classes_, y, axis=0)

@_fit_context(prefer_skip_nested_validation=True)
def fit(self, y):
    if self.neg_label >= self.pos_label:
        raise ValueError(f'neg_label={self.neg_label} must be strictly less than pos_label={self.pos_label}.')
    if self.sparse_output and (self.pos_label == 0 or self.neg_label != 0):
        raise ValueError(f'Sparse binarization is only supported with non zero pos_label and zero neg_label, got pos_label={self.pos_label} and neg_label={self.neg_label}')
    xp, is_array_api = get_namespace(y)
    if is_array_api and self.sparse_output and (not _is_numpy_namespace(xp)):
        raise ValueError(f'`sparse_output=True` is not supported for array API namespace {xp.__name__}. Use `sparse_output=False` to return a dense array instead.')
    self.y_type_ = type_of_target(y, input_name='y')
    if 'multioutput' in self.y_type_:
        raise ValueError('Multioutput target data is not supported with label binarization')
    if _num_samples(y) == 0:
        raise ValueError('y has 0 samples: %r' % y)
    self.sparse_input_ = sp.issparse(y)
    self.classes_ = unique_labels(y)
    return self

def transform(self, y):
    check_is_fitted(self)
    xp, is_array_api = get_namespace(y)
    if is_array_api and self.sparse_output and (not _is_numpy_namespace(xp)):
        raise ValueError(f'`sparse_output=True` is not supported for array API namespace {xp.__name__}. Use `sparse_output=False` to return a dense array instead.')
    y_is_multilabel = type_of_target(y).startswith('multilabel')
    if y_is_multilabel and (not self.y_type_.startswith('multilabel')):
        raise ValueError('The object was not fitted with multilabel input.')
    return label_binarize(y, classes=self.classes_, pos_label=self.pos_label, neg_label=self.neg_label, sparse_output=self.sparse_output)

def inverse_transform(self, Y, threshold=None):
    check_is_fitted(self)
    xp, is_array_api = get_namespace(Y)
    if is_array_api and self.sparse_input_ and (not _is_numpy_namespace(xp)):
        raise ValueError(f'`LabelBinarizer` was fitted on a sparse matrix, and therefore cannot inverse transform a {xp.__name__} array back to a sparse matrix.')
    if threshold is None:
        threshold = (self.pos_label + self.neg_label) / 2.0
    if self.y_type_ == 'multiclass':
        y_inv = _inverse_binarize_multiclass(Y, self.classes_, xp=xp)
    else:
        y_inv = _inverse_binarize_thresholding(Y, self.y_type_, self.classes_, threshold, xp=xp)
    if self.sparse_input_:
        y_inv = _align_api_if_sparse(sp.csr_array(y_inv))
    elif sp.issparse(y_inv):
        y_inv = y_inv.toarray()
    return y_inv

@_fit_context(prefer_skip_nested_validation=True)
def fit(self, y):
    self._cached_dict = None
    if self.classes is None:
        classes = sorted(set(itertools.chain.from_iterable(y)))
    elif len(set(self.classes)) < len(self.classes):
        raise ValueError('The classes argument contains duplicate classes. Remove these duplicates before passing them to MultiLabelBinarizer.')
    else:
        classes = self.classes
    dtype = int if all((isinstance(c, int) for c in classes)) else object
    self.classes_ = np.empty(len(classes), dtype=dtype)
    self.classes_[:] = classes
    return self

def _transform(self, y, class_mapping):
    indices = array.array('i')
    indptr = array.array('i', [0])
    unknown = set()
    for labels in y:
        index = set()
        for label in labels:
            try:
                index.add(class_mapping[label])
            except KeyError:
                unknown.add(label)
        indices.extend(index)
        indptr.append(len(indices))
    if unknown:
        warnings.warn('unknown class(es) {0} will be ignored'.format(sorted(unknown, key=str)))
    data = np.ones(len(indices), dtype=int)
    return _align_api_if_sparse(sp.csr_array((data, indices, indptr), shape=(len(indptr) - 1, len(class_mapping))))

def inverse_transform(self, yt):
    check_is_fitted(self)
    if yt.shape[1] != len(self.classes_):
        raise ValueError('Expected indicator for {0} classes, but got {1}'.format(len(self.classes_), yt.shape[1]))
    if sp.issparse(yt):
        yt = yt.tocsr()
        if len(yt.data) != 0 and len(np.setdiff1d(yt.data, [0, 1])) > 0:
            raise ValueError('Expected only 0s and 1s in label indicator.')
        return [tuple(self.classes_.take(yt.indices[start:end])) for start, end in zip(yt.indptr[:-1], yt.indptr[1:])]
    else:
        unexpected = np.setdiff1d(yt, [0, 1])
        if len(unexpected) > 0:
            raise ValueError('Expected only 0s and 1s in label indicator. Also got {0}'.format(unexpected))
        return [tuple(self.classes_.compress(indicators)) for indicators in yt]

@staticmethod
def _num_combinations(n_features, min_degree, max_degree, interaction_only, include_bias):
    if interaction_only:
        combinations = sum([comb(n_features, i, exact=True) for i in range(max(1, min_degree), min(max_degree, n_features) + 1)])
    else:
        combinations = comb(n_features + max_degree, max_degree, exact=True) - 1
        if min_degree > 0:
            d = min_degree - 1
            combinations -= comb(n_features + d, d, exact=True) - 1
    if include_bias:
        combinations += 1
    return combinations

@property
def powers_(self):
    check_is_fitted(self)
    combinations = self._combinations(n_features=self.n_features_in_, min_degree=self._min_degree, max_degree=self._max_degree, interaction_only=self.interaction_only, include_bias=self.include_bias)
    return np.vstack([np.bincount(c, minlength=self.n_features_in_) for c in combinations])

def get_feature_names_out(self, input_features=None):
    powers = self.powers_
    input_features = _check_feature_names_in(self, input_features)
    feature_names = []
    for row in powers:
        inds = np.where(row)[0]
        if len(inds):
            name = ' '.join(('%s^%d' % (input_features[ind], exp) if exp != 1 else input_features[ind] for ind, exp in zip(inds, row[inds])))
        else:
            name = '1'
        feature_names.append(name)
    return np.asarray(feature_names, dtype=object)

@_fit_context(prefer_skip_nested_validation=True)
def fit(self, X, y=None):
    _, n_features = validate_data(self, X, accept_sparse=True).shape
    if isinstance(self.degree, Integral):
        if self.degree == 0 and (not self.include_bias):
            raise ValueError('Setting degree to zero and include_bias to False would result in an empty output array.')
        self._min_degree = 0
        self._max_degree = self.degree
    elif isinstance(self.degree, collections.abc.Iterable) and len(self.degree) == 2:
        self._min_degree, self._max_degree = self.degree
        if not (isinstance(self._min_degree, Integral) and isinstance(self._max_degree, Integral) and (self._min_degree >= 0) and (self._min_degree <= self._max_degree)):
            raise ValueError(f'degree=(min_degree, max_degree) must be non-negative integers that fulfil min_degree <= max_degree, got {self.degree}.')
        elif self._max_degree == 0 and (not self.include_bias):
            raise ValueError('Setting both min_degree and max_degree to zero and include_bias to False would result in an empty output array.')
    else:
        raise ValueError(f'degree must be a non-negative int or tuple (min_degree, max_degree), got {self.degree}.')
    self.n_output_features_ = self._num_combinations(n_features=n_features, min_degree=self._min_degree, max_degree=self._max_degree, interaction_only=self.interaction_only, include_bias=self.include_bias)
    if self.n_output_features_ > np.iinfo(np.intp).max:
        msg = f'The output that would result from the current configuration would have {self.n_output_features_} features which is too large to be indexed by {np.intp().dtype.name}. Please change some or all of the following:\n- The number of features in the input, currently n_features={n_features!r}\n- The range of degrees to calculate, currently [{self._min_degree}, {self._max_degree}]\n- Whether to include only interaction terms, currently {self.interaction_only}\n- Whether to include a bias term, currently {self.include_bias}.'
        if np.intp == np.int32 and self.n_output_features_ <= np.iinfo(np.int64).max:
            msg += '\nNote that the current Python runtime has a limited 32 bit address space and that this configuration would have been admissible if run on a 64 bit Python runtime.'
        raise ValueError(msg)
    self._n_out_full = self._num_combinations(n_features=n_features, min_degree=0, max_degree=self._max_degree, interaction_only=self.interaction_only, include_bias=self.include_bias)
    return self

def transform(self, X):
    check_is_fitted(self)
    xp, _, device_ = get_namespace_and_device(X)
    X = validate_data(self, X, order='F', dtype=supported_float_dtypes(xp=xp, device=device_), reset=False, accept_sparse=('csr', 'csc'))
    n_samples, n_features = X.shape
    max_int32 = xp.iinfo(xp.int32).max
    if sparse.issparse(X) and X.format == 'csr':
        if self._max_degree > 3:
            return self.transform(X.tocsc()).tocsr()
        to_stack = []
        if self.include_bias:
            to_stack.append(sparse.csr_array(np.ones(shape=(n_samples, 1), dtype=X.dtype)))
        if self._min_degree <= 1 and self._max_degree > 0:
            to_stack.append(X)
        cumulative_size = sum((mat.shape[1] for mat in to_stack))
        for deg in range(max(2, self._min_degree), self._max_degree + 1):
            expanded = _create_expansion(X=X, interaction_only=self.interaction_only, deg=deg, n_features=n_features, cumulative_size=cumulative_size)
            if expanded is not None:
                to_stack.append(expanded)
                cumulative_size += expanded.shape[1]
        if len(to_stack) == 0:
            XP = sparse.csr_array((n_samples, 0), dtype=X.dtype)
        else:
            XP = sparse.hstack(to_stack, dtype=X.dtype, format='csr')
    elif sparse.issparse(X) and X.format == 'csc' and (self._max_degree < 4):
        return self.transform(X.tocsr()).tocsc()
    elif sparse.issparse(X):
        combinations = self._combinations(n_features=n_features, min_degree=self._min_degree, max_degree=self._max_degree, interaction_only=self.interaction_only, include_bias=self.include_bias)
        columns = []
        for combi in combinations:
            if combi:
                out_col = 1
                for col_idx in combi:
                    out_col = X[:, [col_idx]].multiply(out_col)
                columns.append(out_col)
            else:
                bias = sparse.csc_array(np.ones((X.shape[0], 1)))
                columns.append(bias)
        XP = sparse.hstack(columns, dtype=X.dtype).tocsc()
    else:
        order_kwargs = {}
        if _is_numpy_namespace(xp=xp):
            order_kwargs['order'] = self.order
        elif self.order == 'F':
            raise ValueError("PolynomialFeatures does not support order='F' for non-numpy arrays")
        XP = xp.empty(shape=(n_samples, self._n_out_full), dtype=X.dtype, device=device_, **order_kwargs)
        if self.include_bias:
            XP[:, 0] = 1
            current_col = 1
        else:
            current_col = 0
        if self._max_degree == 0:
            return _align_api_if_sparse(XP)
        XP[:, current_col:current_col + n_features] = X
        index = list(range(current_col, current_col + n_features))
        current_col += n_features
        index.append(current_col)
        for _ in range(2, self._max_degree + 1):
            new_index = []
            end = index[-1]
            for feature_idx in range(n_features):
                start = index[feature_idx]
                new_index.append(current_col)
                if self.interaction_only:
                    start += index[feature_idx + 1] - index[feature_idx]
                next_col = current_col + end - start
                if next_col <= current_col:
                    break
                if _is_numpy_namespace(xp):
                    np.multiply(XP[:, start:end], X[:, feature_idx:feature_idx + 1], out=XP[:, current_col:next_col], casting='no')
                else:
                    XP[:, current_col:next_col] = xp.multiply(XP[:, start:end], X[:, feature_idx:feature_idx + 1])
                current_col = next_col
            new_index.append(current_col)
            index = new_index
        if self._min_degree > 1:
            n_XP, n_Xout = (self._n_out_full, self.n_output_features_)
            if self.include_bias:
                Xout = xp.empty(shape=(n_samples, n_Xout), dtype=XP.dtype, device=device_, **order_kwargs)
                Xout[:, 0] = 1
                Xout[:, 1:] = XP[:, n_XP - n_Xout + 1:]
            else:
                Xout = xp.asarray(XP[:, n_XP - n_Xout:], copy=True)
            XP = Xout
    return _align_api_if_sparse(XP)

@staticmethod
def _get_base_knot_positions(X, n_knots=10, knots='uniform', sample_weight=None):
    if knots == 'quantile':
        percentile_ranks = 100 * np.linspace(start=0, stop=1, num=n_knots, dtype=np.float64)
        if sample_weight is None:
            knots = np.nanpercentile(X, percentile_ranks, axis=0)
        else:
            knots = _weighted_percentile(X, sample_weight, percentile_ranks).T
    else:
        mask = slice(None, None, 1) if sample_weight is None else sample_weight > 0
        x_min = np.zeros(X.shape[1], dtype=np.float64)
        x_max = np.zeros(X.shape[1], dtype=np.float64)
        for feature_idx in range(X.shape[1]):
            x = X[mask, feature_idx]
            if np.all(np.isnan(x)):
                continue
            else:
                x_min[feature_idx] = np.nanmin(x)
                x_max[feature_idx] = np.nanmax(x)
        knots = np.linspace(start=x_min, stop=x_max, num=n_knots, endpoint=True, dtype=np.float64)
    return knots

def get_feature_names_out(self, input_features=None):
    check_is_fitted(self, 'n_features_in_')
    n_splines = self.bsplines_[0].c.shape[1]
    input_features = _check_feature_names_in(self, input_features)
    feature_names = []
    for i in range(self.n_features_in_):
        for j in range(n_splines - 1 + self.include_bias):
            feature_names.append(f'{input_features[i]}_sp_{j}')
    return np.asarray(feature_names, dtype=object)

@_fit_context(prefer_skip_nested_validation=True)
def fit(self, X, y=None, sample_weight=None):
    try:
        X = validate_data(self, X, reset=True, accept_sparse=False, ensure_min_samples=2, ensure_2d=True, ensure_all_finite=self.handle_missing != 'zeros')
    except ValueError as e:
        if 'Input X contains NaN.' in str(e) and self.handle_missing == 'error':
            raise ValueError("Input X contains NaN values and `SplineTransformer` is configured to error in this case (handle_missing='error'). To avoid this error, set handle_missing='zeros' to encode missing values as splines with value 0 or ensure no missing values in X.") from e
        raise e
    if sample_weight is not None:
        sample_weight = _check_sample_weight(sample_weight, X, dtype=X.dtype)
    _, n_features = X.shape
    if isinstance(self.knots, str):
        base_knots = self._get_base_knot_positions(X, n_knots=self.n_knots, knots=self.knots, sample_weight=sample_weight)
    else:
        base_knots = check_array(self.knots, dtype=np.float64)
        if base_knots.shape[0] < 2:
            raise ValueError('Number of knots, knots.shape[0], must be >= 2.')
        elif base_knots.shape[1] != n_features:
            raise ValueError('knots.shape[1] == n_features is violated.')
        elif not np.all(np.diff(base_knots, axis=0) > 0):
            raise ValueError('knots must be sorted without duplicates.')
    n_knots = base_knots.shape[0]
    if self.extrapolation == 'periodic' and n_knots <= self.degree:
        raise ValueError(f'Periodic splines require degree < n_knots. Got n_knots={n_knots} and degree={self.degree}.')
    if self.extrapolation != 'periodic':
        n_splines = n_knots + self.degree - 1
    else:
        n_splines = n_knots - 1
    degree = self.degree
    n_out = n_features * n_splines
    if self.extrapolation == 'periodic':
        period = base_knots[-1] - base_knots[0]
        knots = np.r_[base_knots[-(degree + 1):-1] - period, base_knots, base_knots[1:degree + 1] + period]
    else:
        dist_min = base_knots[1] - base_knots[0]
        dist_max = base_knots[-1] - base_knots[-2]
        knots = np.r_[np.linspace(base_knots[0] - degree * dist_min, base_knots[0] - dist_min, num=degree), base_knots, np.linspace(base_knots[-1] + dist_max, base_knots[-1] + degree * dist_max, num=degree)]
    coef = np.eye(n_splines, dtype=np.float64)
    if self.extrapolation == 'periodic':
        coef = np.concatenate((coef, coef[:degree, :]))
    extrapolate = self.extrapolation in ['periodic', 'continue']
    bsplines = [BSpline.construct_fast(knots[:, i], coef, self.degree, extrapolate=extrapolate) for i in range(n_features)]
    self.bsplines_ = bsplines
    self.n_features_out_ = n_out - n_features * (1 - self.include_bias)
    return self

def transform(self, X):
    check_is_fitted(self)
    X = validate_data(self, X, reset=False, accept_sparse=False, ensure_2d=True, ensure_all_finite=self.handle_missing != 'zeros')
    n_samples, n_features = X.shape
    n_splines = self.bsplines_[0].c.shape[1]
    degree = self.degree
    n_out = self.n_features_out_ + n_features * (1 - self.include_bias)
    if X.dtype in FLOAT_DTYPES:
        dtype = X.dtype
    else:
        dtype = np.float64
    if self.sparse_output:
        output_list = []
    else:
        XBS = np.zeros((n_samples, n_out), dtype=dtype, order=self.order)
    for feature_idx in range(n_features):
        spl = self.bsplines_[feature_idx]
        nan_row_indices = np.flatnonzero(_get_mask(X[:, feature_idx], np.nan))
        if self.extrapolation in ('continue', 'error', 'periodic'):
            if self.extrapolation == 'periodic':
                n = spl.t.size - spl.k - 1
                if spl.t[n] - spl.t[spl.k] > 0:
                    x = spl.t[spl.k] + (X[:, feature_idx] - spl.t[spl.k]) % (spl.t[n] - spl.t[spl.k])
                else:
                    x = np.zeros_like(X[:, feature_idx])
            else:
                x = X[:, feature_idx]
            if self.sparse_output:
                if nan_row_indices.size == x.size:
                    x = np.zeros_like(x)
                elif nan_row_indices.shape[0] > 0:
                    x = x.copy()
                    x[nan_row_indices] = np.nanmin(x)
                XBS_sparse = BSpline.design_matrix(x, spl.t, spl.k, self.bsplines_[0].extrapolate)
                if self.extrapolation == 'periodic':
                    XBS_sparse = XBS_sparse.tolil()
                    XBS_sparse[:, :degree] += XBS_sparse[:, -degree:]
                    XBS_sparse = XBS_sparse[:, :-degree]
                if nan_row_indices.shape[0] > 0:
                    XBS = XBS_sparse.tolil()
            else:
                XBS[:, feature_idx * n_splines:(feature_idx + 1) * n_splines] = spl(x)
            if nan_row_indices.shape[0] > 0:
                for spline_idx in range(n_splines):
                    output_feature_idx = n_splines * feature_idx + spline_idx
                    XBS[nan_row_indices, output_feature_idx:output_feature_idx + 1] = 0
                if self.sparse_output:
                    XBS_sparse = XBS
        else:
            xmin, xmax = (spl.t[degree], spl.t[-degree - 1])
            f_min, f_max = (spl(xmin), spl(xmax))
            inside_range_mask = (xmin <= X[:, feature_idx]) & (X[:, feature_idx] <= xmax)
            if self.sparse_output:
                outside_range_mask = ~inside_range_mask
                x = X[:, feature_idx].copy()
                x[outside_range_mask] = xmin
                XBS_sparse = BSpline.design_matrix(x, spl.t, spl.k)
                if np.any(outside_range_mask):
                    XBS_sparse = XBS_sparse.tolil()
                    XBS_sparse[outside_range_mask, :] = 0
            else:
                XBS[inside_range_mask, feature_idx * n_splines:(feature_idx + 1) * n_splines] = spl(X[inside_range_mask, feature_idx])
        if self.extrapolation == 'error':
            has_nan_output_values = False
            if self.sparse_output:
                XBS_sparse = XBS_sparse.tocsr()
                has_nan_output_values = np.any(np.isnan(XBS_sparse.data))
            else:
                output_features = slice(feature_idx * n_splines, (feature_idx + 1) * n_splines)
                has_nan_output_values = np.any(np.isnan(XBS[:, output_features]))
            if has_nan_output_values:
                raise ValueError('`X` contains values beyond the limits of the knots.')
        elif self.extrapolation == 'constant':
            below_xmin_mask = X[:, feature_idx] < xmin
            if np.any(below_xmin_mask):
                if self.sparse_output:
                    XBS_sparse = XBS_sparse.tolil()
                    XBS_sparse[below_xmin_mask, :degree] = f_min[:degree]
                else:
                    XBS[below_xmin_mask, feature_idx * n_splines:feature_idx * n_splines + degree] = f_min[:degree]
            above_xmax_mask = X[:, feature_idx] > xmax
            if np.any(above_xmax_mask):
                if self.sparse_output:
                    XBS_sparse = XBS_sparse.tolil()
                    XBS_sparse[above_xmax_mask, -degree:] = f_max[-degree:]
                else:
                    XBS[above_xmax_mask, (feature_idx + 1) * n_splines - degree:(feature_idx + 1) * n_splines] = f_max[-degree:]
        elif self.extrapolation == 'linear':
            fp_min, fp_max = (spl(xmin, nu=1), spl(xmax, nu=1))
            if degree <= 1:
                degree += 1
            for j in range(degree):
                below_xmin_mask = X[:, feature_idx] < xmin
                if np.any(below_xmin_mask):
                    linear_extr = f_min[j] + (X[below_xmin_mask, feature_idx] - xmin) * fp_min[j]
                    if self.sparse_output:
                        XBS_sparse = XBS_sparse.tolil()
                        XBS_sparse[below_xmin_mask, j] = linear_extr
                    else:
                        XBS[below_xmin_mask, feature_idx * n_splines + j] = linear_extr
                above_xmax_mask = X[:, feature_idx] > xmax
                if np.any(above_xmax_mask):
                    k = n_splines - 1 - j
                    linear_extr = f_max[k] + (X[above_xmax_mask, feature_idx] - xmax) * fp_max[k]
                    if self.sparse_output:
                        XBS_sparse = XBS_sparse.tolil()
                        XBS_sparse[above_xmax_mask, k:k + 1] = linear_extr[:, None]
                    else:
                        XBS[above_xmax_mask, feature_idx * n_splines + k] = linear_extr
        if self.sparse_output:
            XBS_sparse = XBS_sparse.tocsr()
            output_list.append(XBS_sparse)
    if self.sparse_output:
        XBS = sparse.hstack(output_list, format='csr')
    XBS = _align_api_if_sparse(XBS)
    if self.include_bias:
        return XBS
    else:
        indices = [j for j in range(XBS.shape[1]) if (j + 1) % n_splines != 0]
        return XBS[:, indices]

@_fit_context(prefer_skip_nested_validation=True)
def fit(self, X, y):
    self._fit_encodings_all(X, y)
    return self

@_fit_context(prefer_skip_nested_validation=True)
def fit_transform(self, X, y, **params):
    from sklearn.model_selection import GroupKFold, KFold, StratifiedGroupKFold, StratifiedKFold
    from sklearn.model_selection._split import check_cv
    _raise_for_params(params, self, 'fit_transform')
    X_ordinal, X_known_mask, y_encoded, n_categories = self._fit_encodings_all(X, y)
    if self.shuffle != 'deprecated' or self.random_state != 'deprecated':
        warnings.warn('`TargetEncoder.shuffle` and `TargetEncoder.random_state` are deprecated in version 1.9 and will be removed in version 1.11. Pass a cross-validation generator as `cv` argument to specify the shuffling behaviour instead.', FutureWarning)
    shuffle = True if self.shuffle == 'deprecated' else self.shuffle
    cv_kwargs = {'shuffle': shuffle}
    if self.random_state != 'deprecated':
        cv_kwargs['random_state'] = self.random_state
    cv = check_cv(self.cv, y, classifier=self.target_type_ != 'continuous', **cv_kwargs)
    if _routing_enabled():
        if params['groups'] is not None:
            X, y, params['groups'] = indexable(X, y, params['groups'])
        routed_params = process_routing(self, 'fit_transform', **params)
    else:
        routed_params = _manual_routing({'splitter': {}})
    if not isinstance(cv, (GroupKFold, KFold, StratifiedKFold, StratifiedGroupKFold)):
        seen_count = np.zeros(X.shape[0])
        for _, test_idx in cv.split(X, y, **routed_params.splitter.split):
            seen_count[test_idx] += 1
        if not np.all(seen_count == 1):
            raise ValueError('Validation indices from `cv` must cover each sample index exactly once with no overlap. Pass a splitter with non-overlapping validation folds as `cv` or refer to the docs for other options.')
    if self.target_type_ == 'multiclass':
        X_out = np.empty((X_ordinal.shape[0], X_ordinal.shape[1] * len(self.classes_)), dtype=np.float64, order='F')
    else:
        X_out = np.empty_like(X_ordinal, dtype=np.float64)
    for train_idx, test_idx in cv.split(X, y, **routed_params.splitter.split):
        X_indices = np.ascontiguousarray(train_idx, dtype=np.intp)
        y_train = y_encoded[train_idx]
        y_train_mean = np.mean(y_train, axis=0)
        if self.target_type_ == 'multiclass':
            encodings = self._fit_encoding_multiclass(X_ordinal, y_train, n_categories, y_train_mean, X_indices=X_indices)
        else:
            encodings = self._fit_encoding_binary_or_continuous(X_ordinal, y_train, n_categories, y_train_mean, X_indices=X_indices)
        self._transform_X_ordinal(X_out, X_ordinal, ~X_known_mask, test_idx, encodings, y_train_mean)
    return X_out

def transform(self, X):
    X_ordinal, X_known_mask = self._transform(X, handle_unknown='ignore', ensure_all_finite='allow-nan')
    if self.target_type_ == 'multiclass':
        X_out = np.empty((X_ordinal.shape[0], X_ordinal.shape[1] * len(self.classes_)), dtype=np.float64, order='F')
    else:
        X_out = np.empty_like(X_ordinal, dtype=np.float64)
    self._transform_X_ordinal(X_out, X_ordinal, ~X_known_mask, slice(None), self.encodings_, self.target_mean_)
    return X_out

def _fit_encodings_all(self, X, y):
    from sklearn.preprocessing import LabelBinarizer, LabelEncoder
    check_consistent_length(X, y)
    self._fit(X, handle_unknown='ignore', ensure_all_finite='allow-nan')
    if self.target_type == 'auto':
        accepted_target_types = ('binary', 'multiclass', 'continuous')
        inferred_type_of_target = type_of_target(y, input_name='y')
        if inferred_type_of_target not in accepted_target_types:
            raise ValueError(f'Unknown label type: Target type was inferred to be {inferred_type_of_target!r}. Only {accepted_target_types} are supported.')
        self.target_type_ = inferred_type_of_target
    else:
        self.target_type_ = self.target_type
    self.classes_ = None
    if self.target_type_ == 'binary':
        label_encoder = LabelEncoder()
        y = label_encoder.fit_transform(y)
        self.classes_ = label_encoder.classes_
    elif self.target_type_ == 'multiclass':
        label_binarizer = LabelBinarizer()
        y = label_binarizer.fit_transform(y)
        self.classes_ = label_binarizer.classes_
    else:
        y = _check_y(y, y_numeric=True, estimator=self)
    self.target_mean_ = np.mean(y, axis=0)
    X_ordinal, X_known_mask = self._transform(X, handle_unknown='ignore', ensure_all_finite='allow-nan')
    n_categories = np.fromiter((len(category_for_feature) for category_for_feature in self.categories_), dtype=np.int64, count=len(self.categories_))
    if self.target_type_ == 'multiclass':
        encodings = self._fit_encoding_multiclass(X_ordinal, y, n_categories, self.target_mean_)
    else:
        encodings = self._fit_encoding_binary_or_continuous(X_ordinal, y, n_categories, self.target_mean_)
    self.encodings_ = encodings
    return (X_ordinal, X_known_mask, y, n_categories)

def _fit_encoding_binary_or_continuous(self, X_ordinal, y, n_categories, target_mean, X_indices=None):
    if self.smooth == 'auto':
        y_variance = np.var(y)
        encodings = _fit_encoding_fast_auto_smooth(X_ordinal, y, n_categories, target_mean, y_variance, X_indices)
    else:
        encodings = _fit_encoding_fast(X_ordinal, y, n_categories, self.smooth, target_mean, X_indices)
    return encodings

def _transform_X_ordinal(self, X_out, X_ordinal, X_unknown_mask, row_indices, encodings, target_mean):
    if self.target_type_ == 'multiclass':
        n_classes = len(self.classes_)
        for e_idx, encoding in enumerate(encodings):
            feat_idx = e_idx // n_classes
            mean_idx = e_idx % n_classes
            X_out[row_indices, e_idx] = encoding[X_ordinal[row_indices, feat_idx]]
            X_out[X_unknown_mask[:, feat_idx], e_idx] = target_mean[mean_idx]
    else:
        for e_idx, encoding in enumerate(encodings):
            X_out[row_indices, e_idx] = encoding[X_ordinal[row_indices, e_idx]]
            X_out[X_unknown_mask[:, e_idx], e_idx] = target_mean

def get_feature_names_out(self, input_features=None):
    check_is_fitted(self, 'n_features_in_')
    feature_names = _check_feature_names_in(self, input_features)
    if self.target_type_ == 'multiclass':
        feature_names = [f'{feature_name}_{class_name}' for feature_name in feature_names for class_name in self.classes_]
        return np.asarray(feature_names, dtype=object)
    else:
        return feature_names

def predict(self, X):
    probas = self.predict_proba(X)
    return self.classes_[np.argmax(probas, axis=1)].ravel()

def _build_graph(self):
    if self.kernel == 'knn':
        self.nn_fit = None
    affinity_matrix = self._get_kernel(self.X_)
    normalizer = affinity_matrix.sum(axis=1)
    if sparse.isspmatrix(affinity_matrix):
        normalizer = np.ravel(normalizer)
    if SCIPY_VERSION_BELOW_1_12:
        if sparse.issparse(affinity_matrix):
            inv_normalizer = sparse.diags(1.0 / normalizer)
            affinity_matrix = inv_normalizer @ affinity_matrix
        else:
            affinity_matrix /= normalizer[:, np.newaxis]
        return affinity_matrix
    affinity_matrix /= normalizer[:, np.newaxis]
    return affinity_matrix

def _build_graph(self):
    if self.kernel == 'knn':
        self.nn_fit = None
    n_samples = self.X_.shape[0]
    affinity_matrix = self._get_kernel(self.X_)
    laplacian = csgraph_laplacian(affinity_matrix, normed=True)
    laplacian = -laplacian
    if sparse.issparse(laplacian):
        diag_mask = laplacian.row == laplacian.col
        laplacian.data[diag_mask] = 0.0
    else:
        laplacian.flat[::n_samples + 1] = 0.0
    return laplacian

@_fit_context(prefer_skip_nested_validation=False)
def fit(self, X, y, **params):
    _raise_for_params(params, self, 'fit')
    self.estimator_ = self._get_estimator()
    X, y = validate_data(self, X, y, accept_sparse=['csr', 'csc', 'lil', 'dok'], ensure_all_finite=False)
    if y.dtype.kind in ['U', 'S']:
        raise ValueError('y has dtype string. If you wish to predict on string targets, use dtype object, and use -1 as the label for unlabeled samples.')
    has_label = y != -1
    if np.all(has_label):
        warnings.warn('y contains no unlabeled samples', UserWarning)
    if self.criterion == 'k_best' and self.k_best > X.shape[0] - np.sum(has_label):
        warnings.warn('k_best is larger than the amount of unlabeled samples. All unlabeled samples will be labeled in the first iteration', UserWarning)
    if _routing_enabled():
        routed_params = process_routing(self, 'fit', **params)
    else:
        routed_params = _manual_routing({'estimator': {}})
    self.transduction_ = np.copy(y)
    self.labeled_iter_ = np.full_like(y, -1)
    self.labeled_iter_[has_label] = 0
    self.n_iter_ = 0
    while not np.all(has_label) and (self.max_iter is None or self.n_iter_ < self.max_iter):
        self.n_iter_ += 1
        self.estimator_.fit(X[safe_mask(X, has_label)], self.transduction_[has_label], **routed_params.estimator.fit)
        prob = self.estimator_.predict_proba(X[safe_mask(X, ~has_label)])
        pred = self.estimator_.classes_[np.argmax(prob, axis=1)]
        max_proba = np.max(prob, axis=1)
        if self.criterion == 'threshold':
            selected = max_proba > self.threshold
        else:
            n_to_select = min(self.k_best, max_proba.shape[0])
            if n_to_select == max_proba.shape[0]:
                selected = np.ones_like(max_proba, dtype=bool)
            else:
                selected = np.argpartition(-max_proba, n_to_select)[:n_to_select]
        selected_full = np.nonzero(~has_label)[0][selected]
        self.transduction_[selected_full] = pred[selected]
        has_label[selected_full] = True
        self.labeled_iter_[selected_full] = self.n_iter_
        if selected_full.shape[0] == 0:
            self.termination_condition_ = 'no_change'
            break
        if self.verbose:
            print(f'End of iteration {self.n_iter_}, added {selected_full.shape[0]} new labels.')
    if self.n_iter_ == self.max_iter:
        self.termination_condition_ = 'max_iter'
    if np.all(has_label):
        self.termination_condition_ = 'all_labeled'
    self.estimator_.fit(X[safe_mask(X, has_label)], self.transduction_[has_label], **routed_params.estimator.fit)
    self.classes_ = self.estimator_.classes_
    return self

