def _one_vs_one_coef(dual_coef, n_support, support_vectors):
    n_class = dual_coef.shape[0] + 1
    coef = []
    sv_locs = np.cumsum(np.hstack([[0], n_support]))
    for class1 in range(n_class):
        sv1 = support_vectors[sv_locs[class1]:sv_locs[class1 + 1], :]
        for class2 in range(class1 + 1, n_class):
            sv2 = support_vectors[sv_locs[class2]:sv_locs[class2 + 1], :]
            if SCIPY_VERSION_BELOW_1_12:
                alpha1 = dual_coef[[class2 - 1], sv_locs[class1]:sv_locs[class1 + 1]]
                alpha2 = dual_coef[[class1], sv_locs[class2]:sv_locs[class2 + 1]]
            else:
                alpha1 = dual_coef[class2 - 1, sv_locs[class1]:sv_locs[class1 + 1]]
                alpha2 = dual_coef[class1, sv_locs[class2]:sv_locs[class2 + 1]]
            coef.append(safe_sparse_dot(alpha1, sv1) + safe_sparse_dot(alpha2, sv2))
    return coef

def _get_liblinear_solver_type(multi_class, penalty, loss, dual):
    _solver_type_dict = {'logistic_regression': {'l1': {False: 6}, 'l2': {False: 0, True: 7}}, 'hinge': {'l2': {True: 3}}, 'squared_hinge': {'l1': {False: 5}, 'l2': {False: 2, True: 1}}, 'epsilon_insensitive': {'l2': {True: 13}}, 'squared_epsilon_insensitive': {'l2': {False: 11, True: 12}}, 'crammer_singer': 4}
    if multi_class == 'crammer_singer':
        return _solver_type_dict[multi_class]
    elif multi_class != 'ovr':
        raise ValueError('`multi_class` must be one of `ovr`, `crammer_singer`, got %r' % multi_class)
    _solver_pen = _solver_type_dict.get(loss, None)
    if _solver_pen is None:
        error_string = "loss='%s' is not supported" % loss
    else:
        _solver_dual = _solver_pen.get(penalty, None)
        if _solver_dual is None:
            error_string = "The combination of penalty='%s' and loss='%s' is not supported" % (penalty, loss)
        else:
            solver_num = _solver_dual.get(dual, None)
            if solver_num is None:
                error_string = "The combination of penalty='%s' and loss='%s' are not supported when dual=%s" % (penalty, loss, dual)
            else:
                return solver_num
    raise ValueError('Unsupported set of arguments: %s, Parameters: penalty=%r, loss=%r, dual=%r' % (error_string, penalty, loss, dual))

def _fit_liblinear(X, y, C, fit_intercept, intercept_scaling, class_weight, penalty, dual, verbose, max_iter, tol, random_state=None, multi_class='ovr', loss='logistic_regression', epsilon=0.1, sample_weight=None):
    if loss not in ['epsilon_insensitive', 'squared_epsilon_insensitive']:
        enc = LabelEncoder()
        y_ind = enc.fit_transform(y)
        classes_ = enc.classes_
        if len(classes_) < 2:
            raise ValueError('This solver needs samples of at least 2 classes in the data, but the data contains only one class: %r' % classes_[0])
        class_weight_ = compute_class_weight(class_weight, classes=classes_, y=y, sample_weight=sample_weight)
    else:
        class_weight_ = np.empty(0, dtype=np.float64)
        y_ind = y
    liblinear.set_verbosity_wrap(verbose)
    rnd = check_random_state(random_state)
    if verbose:
        print('[LibLinear]', end='')
    bias = -1.0
    if fit_intercept:
        if intercept_scaling <= 0:
            raise ValueError('Intercept scaling is %r but needs to be greater than 0. To disable fitting an intercept, set fit_intercept=False.' % intercept_scaling)
        else:
            bias = intercept_scaling
    libsvm.set_verbosity_wrap(verbose)
    libsvm_sparse.set_verbosity_wrap(verbose)
    liblinear.set_verbosity_wrap(verbose)
    if sp.issparse(X):
        _check_large_sparse(X)
    y_ind = np.asarray(y_ind, dtype=np.float64).ravel()
    y_ind = np.require(y_ind, requirements='W')
    sample_weight = _check_sample_weight(sample_weight, X, dtype=np.float64)
    solver_type = _get_liblinear_solver_type(multi_class, penalty, loss, dual)
    raw_coef_, n_iter_ = liblinear.train_wrap(X, y_ind, sp.issparse(X), solver_type, tol, bias, C, class_weight_, max_iter, rnd.randint(np.iinfo('i').max), epsilon, sample_weight)
    n_iter_max = max(n_iter_)
    if n_iter_max >= max_iter:
        warnings.warn('Liblinear failed to converge, increase the number of iterations.', ConvergenceWarning)
    if fit_intercept:
        coef_ = raw_coef_[:, :-1]
        intercept_ = intercept_scaling * raw_coef_[:, -1]
    else:
        coef_ = raw_coef_
        intercept_ = 0.0
    return (coef_, intercept_, n_iter_)

@_fit_context(prefer_skip_nested_validation=True)
def fit(self, X, y, sample_weight=None):
    rnd = check_random_state(self.random_state)
    sparse = sp.issparse(X)
    if sparse and self.kernel == 'precomputed':
        raise TypeError('Sparse precomputed kernels are not supported.')
    self._sparse = sparse and (not callable(self.kernel))
    if callable(self.kernel):
        check_consistent_length(X, y)
    else:
        X, y = validate_data(self, X, y, dtype=np.float64, order='C', accept_sparse='csr', accept_large_sparse=False)
    y = self._validate_targets(y)
    sample_weight = np.asarray([] if sample_weight is None else sample_weight, dtype=np.float64)
    solver_type = LIBSVM_IMPL.index(self._impl)
    self._effective_probability = self.probability
    if self._impl in ['c_svc', 'nu_svc']:
        if self._impl == 'nu_scv':
            est_dep = 'NuSVC'
        else:
            est_dep = 'SVC'
        if self.probability != 'deprecated':
            warnings.warn(f'The `probability` parameter was deprecated in 1.9 and will be removed in version 1.11. Use `CalibratedClassifierCV({est_dep}(), ensemble=False)` instead of `{est_dep}(probability=True)`', FutureWarning)
        else:
            self._effective_probability = False
    n_samples = _num_samples(X)
    if solver_type != 2 and n_samples != y.shape[0]:
        raise ValueError('X and y have incompatible shapes.\n' + 'X has %s samples, but y has %s.' % (n_samples, y.shape[0]))
    if self.kernel == 'precomputed' and n_samples != X.shape[1]:
        raise ValueError('Precomputed matrix must be a square matrix. Input is a {}x{} matrix.'.format(X.shape[0], X.shape[1]))
    if sample_weight.shape[0] > 0 and sample_weight.shape[0] != n_samples:
        raise ValueError('sample_weight and X have incompatible shapes: %r vs %r\nNote: Sparse matrices cannot be indexed w/boolean masks (use `indices=True` in CV).' % (sample_weight.shape, X.shape))
    kernel = 'precomputed' if callable(self.kernel) else self.kernel
    if kernel == 'precomputed':
        self._gamma = 0.0
    elif isinstance(self.gamma, str):
        if self.gamma == 'scale':
            X_var = X.multiply(X).mean() - X.mean() ** 2 if sparse else X.var()
            self._gamma = 1.0 / (X.shape[1] * X_var) if X_var != 0 else 1.0
        elif self.gamma == 'auto':
            self._gamma = 1.0 / X.shape[1]
    elif isinstance(self.gamma, Real):
        self._gamma = self.gamma
    fit = self._sparse_fit if self._sparse else self._dense_fit
    if self.verbose:
        print('[LibSVM]', end='')
    seed = rnd.randint(np.iinfo('i').max)
    fit(X, y, sample_weight, solver_type, kernel, random_seed=seed)
    self.shape_fit_ = X.shape if hasattr(X, 'shape') else (n_samples,)
    self._intercept_ = self.intercept_.copy()
    self._dual_coef_ = self.dual_coef_
    if self._impl in ['c_svc', 'nu_svc'] and len(self.classes_) == 2:
        self.intercept_ *= -1
        self.dual_coef_ = -self.dual_coef_
    dual_coef = self._dual_coef_.data if self._sparse else self._dual_coef_
    intercept_finiteness = np.isfinite(self._intercept_).all()
    dual_coef_finiteness = np.isfinite(dual_coef).all()
    if not (intercept_finiteness and dual_coef_finiteness):
        raise ValueError('The dual coefficients or intercepts are not finite. The input data may contain large values and need to be preprocessed.')
    if self._impl in ['c_svc', 'nu_svc']:
        self.n_iter_ = self._num_iter
    else:
        self.n_iter_ = self._num_iter.item()
    return self

def predict(self, X):
    X = self._validate_for_predict(X)
    predict = self._sparse_predict if self._sparse else self._dense_predict
    return predict(X)

def _compute_kernel(self, X):
    if callable(self.kernel):
        kernel = self.kernel(X, self.__Xfit)
        if sp.issparse(kernel):
            kernel = kernel.toarray()
        X = np.asarray(kernel, dtype=np.float64, order='C')
    return X

def _decision_function(self, X):
    X = self._validate_for_predict(X)
    X = self._compute_kernel(X)
    if self._sparse:
        dec_func = self._sparse_decision_function(X)
    else:
        dec_func = self._dense_decision_function(X)
    if self._impl in ['c_svc', 'nu_svc'] and len(self.classes_) == 2:
        return -dec_func.ravel()
    return dec_func

@property
def coef_(self):
    if self.kernel != 'linear':
        raise AttributeError('coef_ is only available when using a linear kernel')
    coef = self._get_coef()
    if sp.issparse(coef):
        coef.data.flags.writeable = False
    else:
        coef.flags.writeable = False
    return coef

@property
def n_support_(self):
    try:
        check_is_fitted(self)
    except NotFittedError:
        raise AttributeError
    svm_type = LIBSVM_IMPL.index(self._impl)
    if svm_type in (0, 1):
        return self._n_support
    else:
        return np.array([self._n_support[0]])

def decision_function(self, X):
    dec = self._decision_function(X)
    if self.decision_function_shape == 'ovr' and len(self.classes_) > 2:
        return _ovr_decision_function(dec < 0, -dec, len(self.classes_))
    return dec

def predict(self, X):
    check_is_fitted(self)
    if self.break_ties and self.decision_function_shape == 'ovo':
        raise ValueError("break_ties must be False when decision_function_shape is 'ovo'")
    if self.break_ties and self.decision_function_shape == 'ovr' and (len(self.classes_) > 2):
        y = np.argmax(self.decision_function(X), axis=1)
    else:
        y = super().predict(X)
    return self.classes_.take(np.asarray(y, dtype=np.intp))

@available_if(_check_proba)
def predict_proba(self, X):
    X = self._validate_for_predict(X)
    if self._probA.size == 0 or self._probB.size == 0:
        raise NotFittedError('predict_proba is not available when fitted with probability=False')
    pred_proba = self._sparse_predict_proba if self._sparse else self._dense_predict_proba
    return pred_proba(X)

@available_if(_check_proba)
def predict_log_proba(self, X):
    return np.log(self.predict_proba(X))

@deprecated('Attribute `probA_` was deprecated in version 1.9 and will be removed in 1.11 as the `probability=True` option for SVC and NuSVC was deprecated and will be removed in 1.11.')
@property
def probA_(self):
    return self._probA

@deprecated('Attribute `probB_` was deprecated in version 1.9 and will be removed in 1.11 as the `probability=True` option for SVC and NuSVC was deprecated and will be removed in 1.11.')
@property
def probB_(self):
    return self._probB

@validate_params({'X': ['array-like', 'sparse matrix'], 'y': ['array-like'], 'loss': [StrOptions({'squared_hinge', 'log'})], 'fit_intercept': ['boolean'], 'intercept_scaling': [Interval(Real, 0, None, closed='neither')]}, prefer_skip_nested_validation=True)
def l1_min_c(X, y, *, loss='squared_hinge', fit_intercept=True, intercept_scaling=1.0):
    X = check_array(X, accept_sparse='csc')
    check_consistent_length(X, y)
    Y = LabelBinarizer(neg_label=-1).fit_transform(y).T
    den = np.max(np.abs(safe_sparse_dot(Y, X)))
    if fit_intercept:
        bias = np.full((np.size(y), 1), intercept_scaling, dtype=np.array(intercept_scaling).dtype)
        den = max(den, abs(np.dot(Y, bias)).max())
    if den == 0.0:
        raise ValueError('Ill-posed l1_min_c calculation: l1 will always select zero coefficients for this data')
    if loss == 'squared_hinge':
        return 0.5 / den
    else:
        return 2.0 / den

def _validate_dual_parameter(dual, loss, penalty, multi_class, X):
    if dual == 'auto':
        if X.shape[0] < X.shape[1]:
            try:
                _get_liblinear_solver_type(multi_class, penalty, loss, True)
                return True
            except ValueError:
                return False
        else:
            try:
                _get_liblinear_solver_type(multi_class, penalty, loss, False)
                return False
            except ValueError:
                return True
    else:
        return dual

def decision_function(self, X):
    dec = self._decision_function(X).ravel()
    return dec

def predict(self, X):
    y = super().predict(X)
    return np.asarray(y, dtype=np.intp)

def get_depth(self):
    check_is_fitted(self)
    return self.tree_.max_depth

def get_n_leaves(self):
    check_is_fitted(self)
    return self.tree_.n_leaves

def _validate_X_predict(self, X, check_input):
    if check_input:
        if self._support_missing_values(X):
            ensure_all_finite = 'allow-nan'
        else:
            ensure_all_finite = True
        X = validate_data(self, X, dtype=np.float32, accept_sparse='csr', reset=False, ensure_all_finite=ensure_all_finite)
        if issparse(X) and (X.indices.dtype != np.intc or X.indptr.dtype != np.intc):
            raise ValueError('No support for np.int64 index based sparse matrices')
    else:
        _check_n_features(self, X, reset=False)
    return X

def predict(self, X, check_input=True):
    check_is_fitted(self)
    X = self._validate_X_predict(X, check_input)
    proba = self.tree_.predict(X)
    n_samples = X.shape[0]
    if is_classifier(self):
        if self.n_outputs_ == 1:
            return self.classes_.take(np.argmax(proba, axis=1), axis=0)
        else:
            class_type = self.classes_[0].dtype
            predictions = np.zeros((n_samples, self.n_outputs_), dtype=class_type)
            for k in range(self.n_outputs_):
                predictions[:, k] = self.classes_[k].take(np.argmax(proba[:, k], axis=1), axis=0)
            return predictions
    elif self.n_outputs_ == 1:
        return proba[:, 0]
    else:
        return proba[:, :, 0]

def apply(self, X, check_input=True):
    check_is_fitted(self)
    X = self._validate_X_predict(X, check_input)
    return self.tree_.apply(X)

def decision_path(self, X, check_input=True):
    X = self._validate_X_predict(X, check_input)
    return self.tree_.decision_path(X)

def _prune_tree(self):
    check_is_fitted(self)
    if self.ccp_alpha == 0.0:
        return
    if is_classifier(self):
        n_classes = np.atleast_1d(self.n_classes_)
        pruned_tree = Tree(self.n_features_in_, n_classes, self.n_outputs_)
    else:
        pruned_tree = Tree(self.n_features_in_, np.array([1] * self.n_outputs_, dtype=np.intp), self.n_outputs_)
    _build_pruned_tree_ccp(pruned_tree, self.tree_, self.ccp_alpha)
    self.tree_ = pruned_tree

def cost_complexity_pruning_path(self, X, y, sample_weight=None):
    est = clone(self).set_params(ccp_alpha=0.0)
    est.fit(X, y, sample_weight=sample_weight)
    return Bunch(**ccp_pruning_path(est.tree_))

@property
def feature_importances_(self):
    check_is_fitted(self)
    return self.tree_.compute_feature_importances()

@_fit_context(prefer_skip_nested_validation=True)
def fit(self, X, y, sample_weight=None, check_input=True):
    super()._fit(X, y, sample_weight=sample_weight, check_input=check_input)
    return self

def predict_proba(self, X, check_input=True):
    check_is_fitted(self)
    X = self._validate_X_predict(X, check_input)
    proba = self.tree_.predict(X)
    if self.n_outputs_ == 1:
        return proba[:, :self.n_classes_]
    else:
        all_proba = []
        for k in range(self.n_outputs_):
            proba_k = proba[:, k, :self.n_classes_[k]]
            all_proba.append(proba_k)
        return all_proba

def predict_log_proba(self, X):
    proba = self.predict_proba(X)
    if self.n_outputs_ == 1:
        return np.log(proba)
    else:
        for k in range(self.n_outputs_):
            proba[k] = np.log(proba[k])
        return proba

@_fit_context(prefer_skip_nested_validation=True)
def fit(self, X, y, sample_weight=None, check_input=True):
    super()._fit(X, y, sample_weight=sample_weight, check_input=check_input)
    return self

