@validate_params({'decision_tree': 'no_validation', 'out_file': [str, None, HasMethods('write')], 'max_depth': [Interval(Integral, 0, None, closed='left'), None], 'feature_names': ['array-like', None], 'class_names': ['array-like', 'boolean', None], 'label': [StrOptions({'all', 'root', 'none'})], 'filled': ['boolean'], 'leaves_parallel': ['boolean'], 'impurity': ['boolean'], 'node_ids': ['boolean'], 'proportion': ['boolean'], 'rotate': ['boolean'], 'rounded': ['boolean'], 'special_characters': ['boolean'], 'precision': [Interval(Integral, 0, None, closed='left'), None], 'fontname': [str], 'fill_colors': ['array-like', None]}, prefer_skip_nested_validation=True)
def export_graphviz(decision_tree, out_file=None, *, max_depth=None, feature_names=None, class_names=None, label='all', filled=False, leaves_parallel=False, impurity=True, node_ids=False, proportion=False, rotate=False, rounded=False, special_characters=False, precision=3, fontname='helvetica', fill_colors=None):
