def _compute_depth(tree, node):

    def compute_depth_(current_node, current_depth, children_left, children_right, depths):
        depths += [current_depth]
        left = children_left[current_node]
        right = children_right[current_node]
        if left != -1 and right != -1:
            compute_depth_(left, current_depth + 1, children_left, children_right, depths)
            compute_depth_(right, current_depth + 1, children_left, children_right, depths)
    depths = []
    compute_depth_(node, 1, tree.children_left, tree.children_right, depths)
    return max(depths)

@validate_params({'decision_tree': [DecisionTreeClassifier, DecisionTreeRegressor], 'feature_names': ['array-like', None], 'class_names': ['array-like', None], 'max_depth': [Interval(Integral, 0, None, closed='left'), None], 'spacing': [Interval(Integral, 1, None, closed='left'), None], 'decimals': [Interval(Integral, 0, None, closed='left'), None], 'show_weights': ['boolean']}, prefer_skip_nested_validation=True)
def export_text(decision_tree, *, feature_names=None, class_names=None, max_depth=10, spacing=3, decimals=2, show_weights=False):
    if feature_names is not None:
        feature_names = check_array(feature_names, ensure_2d=False, dtype=None, ensure_min_samples=0)
    if class_names is not None:
        class_names = check_array(class_names, ensure_2d=False, dtype=None, ensure_min_samples=0)
    check_is_fitted(decision_tree)
    tree_ = decision_tree.tree_
    if is_classifier(decision_tree):
        if class_names is None:
            class_names = decision_tree.classes_
        elif len(class_names) != len(decision_tree.classes_):
            raise ValueError(f'When `class_names` is an array, it should contain as many items as `decision_tree.classes_`. Got {len(class_names)} while the tree was fitted with {len(decision_tree.classes_)} classes.')
    right_child_fmt = '{} {} <= {}\n'
    left_child_fmt = '{} {} >  {}\n'
    truncation_fmt = '{} {}\n'
    if feature_names is not None and len(feature_names) != tree_.n_features:
        raise ValueError('feature_names must contain %d elements, got %d' % (tree_.n_features, len(feature_names)))
    if isinstance(decision_tree, DecisionTreeClassifier):
        value_fmt = '{}{} weights: {}\n'
        if not show_weights:
            value_fmt = '{}{}{}\n'
    else:
        value_fmt = '{}{} value: {}\n'
    if feature_names is not None:
        feature_names_ = [feature_names[i] if i != _tree.TREE_UNDEFINED else None for i in tree_.feature]
    else:
        feature_names_ = ['feature_{}'.format(i) for i in tree_.feature]
    report = StringIO()

    def _add_leaf(value, weighted_n_node_samples, class_name, indent):
        val = ''
        if isinstance(decision_tree, DecisionTreeClassifier):
            if show_weights:
                val = ['{1:.{0}f}, '.format(decimals, v * weighted_n_node_samples) for v in value]
                val = '[' + ''.join(val)[:-2] + ']'
                weighted_n_node_samples
            val += ' class: ' + str(class_name)
        else:
            val = ['{1:.{0}f}, '.format(decimals, v) for v in value]
            val = '[' + ''.join(val)[:-2] + ']'
        report.write(value_fmt.format(indent, '', val))

    def print_tree_recurse(report, node, depth):
        indent = ('|' + ' ' * spacing) * depth
        indent = indent[:-spacing] + '-' * spacing
        value = None
        if tree_.n_outputs == 1:
            value = tree_.value[node][0]
        else:
            value = tree_.value[node].T[0]
        class_name = np.argmax(value)
        if tree_.n_classes[0] != 1 and tree_.n_outputs == 1:
            class_name = class_names[class_name]
        weighted_n_node_samples = tree_.weighted_n_node_samples[node]
        if depth <= max_depth + 1:
            info_fmt = ''
            info_fmt_left = info_fmt
            info_fmt_right = info_fmt
            if tree_.feature[node] != _tree.TREE_UNDEFINED:
                name = feature_names_[node]
                threshold = tree_.threshold[node]
                threshold = '{1:.{0}f}'.format(decimals, threshold)
                report.write(right_child_fmt.format(indent, name, threshold))
                report.write(info_fmt_left)
                print_tree_recurse(report, tree_.children_left[node], depth + 1)
                report.write(left_child_fmt.format(indent, name, threshold))
                report.write(info_fmt_right)
                print_tree_recurse(report, tree_.children_right[node], depth + 1)
            else:
                _add_leaf(value, weighted_n_node_samples, class_name, indent)
        else:
            subtree_depth = _compute_depth(tree_, node)
            if subtree_depth == 1:
                _add_leaf(value, weighted_n_node_samples, class_name, indent)
            else:
                trunc_report = 'truncated branch of depth %d' % subtree_depth
                report.write(truncation_fmt.format(indent, trunc_report))
    print_tree_recurse(report, 0, 1)
    return report.getvalue()

@validate_params({'class_weight': [dict, StrOptions({'balanced'}), None], 'classes': [np.ndarray], 'y': ['array-like'], 'sample_weight': ['array-like', None]}, prefer_skip_nested_validation=True)
def compute_class_weight(class_weight, *, classes, y, sample_weight=None):
    from sklearn.preprocessing import LabelEncoder
    xp, _, device_ = get_namespace_and_device(y, classes)
    unique_y = xp.unique_values(y)
    if set(move_to(unique_y, xp=np, device='cpu')) - set(move_to(classes, xp=np, device='cpu')):
        raise ValueError('classes should include all valid labels that can be in y')
    if class_weight is None or len(class_weight) == 0:
        weight = xp.ones(classes.shape[0], device=device_)
    elif class_weight == 'balanced':
        le = LabelEncoder()
        y_ind = le.fit_transform(y)
        if not all(_isin(classes, xp.astype(le.classes_, classes.dtype), xp=xp)):
            raise ValueError('classes should have valid labels that are in y')
        if _is_numpy_namespace(xp) and sample_weight is not None:
            sample_weight = move_to(sample_weight, xp=np, device='cpu')
        sample_weight = _check_sample_weight(sample_weight, y)
        weighted_class_counts = _bincount(y_ind, weights=sample_weight, xp=xp)
        recip_freq = xp.sum(weighted_class_counts) / (size(le.classes_) * weighted_class_counts)
        weight = recip_freq[le.transform(classes)]
    else:
        weight = xp.ones(size(classes), device=device_)
        unweighted_classes = []
        for i, c in enumerate(classes):
            try:
                c = int(c)
            except ValueError:
                c = str(c)
            if c in class_weight:
                weight[i] = class_weight[c]
            else:
                unweighted_classes.append(c)
        n_weighted_classes = size(classes) - len(unweighted_classes)
        if unweighted_classes and n_weighted_classes != len(class_weight):
            unweighted_classes_user_friendly_str = np.array(unweighted_classes).tolist()
            raise ValueError(f'The classes, {unweighted_classes_user_friendly_str}, are not in class_weight')
    return weight

@validate_params({'class_weight': [dict, list, StrOptions({'balanced'}), None], 'y': ['array-like', 'sparse matrix'], 'indices': ['array-like', None]}, prefer_skip_nested_validation=True)
def compute_sample_weight(class_weight, y, *, indices=None):
    if not sparse.issparse(y):
        y = np.atleast_1d(y)
        if y.ndim == 1:
            y = np.reshape(y, (-1, 1))
    n_outputs = y.shape[1]
    if indices is not None and class_weight != 'balanced':
        raise ValueError(f"The only valid class_weight for subsampling is 'balanced'. Given {class_weight}.")
    elif n_outputs > 1:
        if class_weight is None or isinstance(class_weight, dict):
            raise ValueError("For multi-output, class_weight should be a list of dicts, or the string 'balanced'.")
        elif isinstance(class_weight, list) and len(class_weight) != n_outputs:
            raise ValueError(f'For multi-output, number of elements in class_weight should match number of outputs. Got {len(class_weight)} element(s) while having {n_outputs} outputs.')
    expanded_class_weight = []
    for k in range(n_outputs):
        if sparse.issparse(y):
            y_full = y[:, [k]].toarray().flatten()
        else:
            y_full = y[:, k]
        classes_full = np.unique(y_full)
        classes_missing = None
        if class_weight == 'balanced' or n_outputs == 1:
            class_weight_k = class_weight
        else:
            class_weight_k = class_weight[k]
        if indices is not None:
            y_subsample = y_full[indices]
            classes_subsample = np.unique(y_subsample)
            weight_k = np.take(compute_class_weight(class_weight_k, classes=classes_subsample, y=y_subsample), np.searchsorted(classes_subsample, classes_full), mode='clip')
            classes_missing = set(classes_full) - set(classes_subsample)
        else:
            weight_k = compute_class_weight(class_weight_k, classes=classes_full, y=y_full)
        weight_k = weight_k[np.searchsorted(classes_full, y_full)]
        if classes_missing:
            weight_k[np.isin(y_full, list(classes_missing))] = 0.0
        expanded_class_weight.append(weight_k)
    expanded_class_weight = np.prod(expanded_class_weight, axis=0, dtype=np.float64)
    return expanded_class_weight

def _is_deprecated(func):
    closures = getattr(func, '__closure__', [])
    if closures is None:
        closures = []
    is_deprecated = 'deprecated' in ''.join([c.cell_contents for c in closures if isinstance(c.cell_contents, str)])
    return is_deprecated

def __call__(self, obj):
    if isinstance(obj, type):
        return self._decorate_class(obj)
    elif isinstance(obj, property):
        return self._decorate_property(obj)
    else:
        return self._decorate_fun(obj)

def _decorate_fun(self, fun):
    msg = 'Function %s is deprecated' % fun.__name__
    if self.extra:
        msg += '; %s' % self.extra

    @functools.wraps(fun)
    def wrapped(*args, **kwargs):
        warnings.warn(msg, category=FutureWarning)
        return fun(*args, **kwargs)
    wrapped.__wrapped__ = fun
    return wrapped

def all_estimators(type_filter=None):
    from sklearn.base import BaseEstimator, ClassifierMixin, ClusterMixin, RegressorMixin, TransformerMixin
    from sklearn.utils._testing import ignore_warnings

    def is_abstract(c):
        if not hasattr(c, '__abstractmethods__'):
            return False
        if not len(c.__abstractmethods__):
            return False
        return True
    all_classes = []
    root = str(Path(__file__).parent.parent)
    with ignore_warnings(category=FutureWarning):
        for _, module_name, _ in pkgutil.walk_packages(path=[root], prefix='sklearn.'):
            module_parts = module_name.split('.')
            if any((part in _MODULE_TO_IGNORE for part in module_parts)) or '._' in module_name:
                continue
            module = import_module(module_name)
            classes = inspect.getmembers(module, inspect.isclass)
            classes = [(name, est_cls) for name, est_cls in classes if not name.startswith('_')]
            all_classes.extend(classes)
    all_classes = set(all_classes)
    estimators = [c for c in all_classes if issubclass(c[1], BaseEstimator) and c[0] != 'BaseEstimator']
    estimators = [c for c in estimators if not is_abstract(c[1])]
    if type_filter is not None:
        if not isinstance(type_filter, list):
            type_filter = [type_filter]
        else:
            type_filter = list(type_filter)
        filtered_estimators = []
        filters = {'classifier': ClassifierMixin, 'regressor': RegressorMixin, 'transformer': TransformerMixin, 'cluster': ClusterMixin}
        for name, mixin in filters.items():
            if name in type_filter:
                type_filter.remove(name)
                filtered_estimators.extend([est for est in estimators if issubclass(est[1], mixin)])
        estimators = filtered_estimators
        if type_filter:
            raise ValueError(f"Parameter type_filter must be 'classifier', 'regressor', 'transformer', 'cluster' or None, got {type_filter!r}.")
    return sorted(set(estimators), key=itemgetter(0))

def _maybe_mark(estimator, check, expected_failed_checks: dict[str, str] | None=None, mark: Literal['xfail', 'skip', None]=None, pytest=None, xfail_strict: bool | None=None):
    should_be_marked, reason = _should_be_skipped_or_marked(estimator, check, expected_failed_checks)
    if not should_be_marked or mark is None:
        return (estimator, check)
    estimator_name = estimator.__class__.__name__
    if mark == 'xfail':
        if xfail_strict is None:
            mark = pytest.mark.xfail(reason=reason)
        else:
            mark = pytest.mark.xfail(reason=reason, strict=xfail_strict)
        return pytest.param(estimator, check, marks=mark)
    else:

        @wraps(check)
        def wrapped(*args, **kwargs):
            raise SkipTest(f'Skipping {_check_name(check)} for {estimator_name}: {reason}')
        return (estimator, wrapped)

def _should_be_skipped_or_marked(estimator, check, expected_failed_checks: dict[str, str] | None=None) -> tuple[bool, str]:
    expected_failed_checks = expected_failed_checks or {}
    check_name = _check_name(check)
    if check_name in expected_failed_checks:
        return (True, expected_failed_checks[check_name])
    return (False, 'Check is not expected to fail')

def estimator_checks_generator(estimator, *, legacy: bool=True, expected_failed_checks: dict[str, str] | None=None, mark: Literal['xfail', 'skip', None]=None, xfail_strict: bool | None=None):
    if mark == 'xfail':
        import pytest
    else:
        pytest = None
    name = type(estimator).__name__
    yield (estimator, partial(check_estimator_cloneable, name))
    for check in _yield_all_checks(estimator, legacy=legacy):
        check_with_name = partial(check, name)
        for check_instance in _yield_instances_for_check(check, estimator):
            yield _maybe_mark(check_instance, check_with_name, expected_failed_checks=expected_failed_checks, mark=mark, pytest=pytest, xfail_strict=xfail_strict)

def parametrize_with_checks(estimators, *, legacy: bool=True, expected_failed_checks: Callable | None=None, xfail_strict: bool | None=None):
    import pytest
    if any((isinstance(est, type) for est in estimators)):
        msg = "Passing a class was deprecated in version 0.23 and isn't supported anymore from 0.24.Please pass an instance instead."
        raise TypeError(msg)

    def _checks_generator(estimators, legacy, expected_failed_checks):
        for estimator in estimators:
            args = {'estimator': estimator, 'legacy': legacy, 'mark': 'xfail', 'xfail_strict': xfail_strict}
            if callable(expected_failed_checks):
                args['expected_failed_checks'] = expected_failed_checks(estimator)
            yield from estimator_checks_generator(**args)
    return pytest.mark.parametrize('estimator, check', _checks_generator(estimators, legacy, expected_failed_checks), ids=_get_check_estimator_ids)

@validate_params({'legacy': ['boolean'], 'expected_failed_checks': [dict, None], 'on_skip': [StrOptions({'warn'}), None], 'on_fail': [StrOptions({'raise', 'warn'}), None], 'callback': [callable, None]}, prefer_skip_nested_validation=False)
def check_estimator(estimator=None, *, legacy: bool=True, expected_failed_checks: dict[str, str] | None=None, on_skip: Literal['warn'] | None='warn', on_fail: Literal['raise', 'warn'] | None='raise', callback: Callable | None=None):
    if isinstance(estimator, type):
        msg = "Passing a class was deprecated in version 0.23 and isn't supported anymore from 0.24.Please pass an instance instead."
        raise TypeError(msg)
    if on_fail == 'raise' and callback is not None:
        raise ValueError("callback cannot be provided together with on_fail='raise'")
    name = type(estimator).__name__
    test_results = []
    for estimator, check in estimator_checks_generator(estimator, legacy=legacy, expected_failed_checks=expected_failed_checks, mark=None):
        test_can_fail, reason = _should_be_skipped_or_marked(estimator, check, expected_failed_checks)
        try:
            check(estimator)
        except SkipTest as e:
            check_result = {'estimator': estimator, 'check_name': _check_name(check), 'exception': e, 'status': 'skipped', 'expected_to_fail': test_can_fail, 'expected_to_fail_reason': reason}
            if on_skip == 'warn':
                warnings.warn(f'Skipping check {_check_name(check)} for {name} because it raised {type(e).__name__}: {e}', SkipTestWarning)
        except Exception as e:
            if on_fail == 'raise' and (not test_can_fail):
                raise
            check_result = {'estimator': estimator, 'check_name': _check_name(check), 'exception': e, 'expected_to_fail': test_can_fail, 'expected_to_fail_reason': reason}
            if test_can_fail:
                check_result['status'] = 'xfail'
            else:
                check_result['status'] = 'failed'
            if on_fail == 'warn':
                warning = EstimatorCheckFailedWarning(**check_result)
                warnings.warn(warning)
        else:
            check_result = {'estimator': estimator, 'check_name': _check_name(check), 'exception': None, 'status': 'passed', 'expected_to_fail': test_can_fail, 'expected_to_fail_reason': reason}
        test_results.append(check_result)
        if callback:
            callback(**check_result)
    return test_results

