def check_estimator_sparse_tag(name, estimator_orig):
    estimator = clone(estimator_orig)
    rng = np.random.RandomState(0)
    n_samples = 15 if name == 'SpectralCoclustering' else 40
    X = rng.uniform(size=(n_samples, 3))
    X[X < 0.6] = 0
    y = rng.randint(0, 3, size=n_samples)
    X = _enforce_estimator_tags_X(estimator, X)
    y = _enforce_estimator_tags_y(estimator, y)
    X = sparse.csr_array(X)
    tags = get_tags(estimator)
    if tags.input_tags.sparse:
        try:
            estimator.fit(X, y)
        except Exception as e:
            err_msg = f"Estimator {name} raised an exception. The tag self.input_tags.sparse={tags.input_tags.sparse} might not be consistent with the estimator's ability to handle sparse data (i.e. controlled by the parameter `accept_sparse` in `validate_data` or `check_array` functions)."
            raise AssertionError(err_msg) from e
    else:
        err_msg = f"Estimator {name} raised an exception. The estimator failed when fitted on sparse data in accordance with its tag self.input_tags.sparse={tags.input_tags.sparse} but didn't raise the appropriate error: error message should state explicitly that sparse input is not supported if this is not the case, e.g. by using check_array(X, accept_sparse=False)."
        try:
            estimator.fit(X, y)
        except (ValueError, TypeError) as e:
            if re.search('[Ss]parse', str(e)):
                return
            raise AssertionError(err_msg) from e
        except Exception as e:
            raise AssertionError(err_msg) from e
        raise AssertionError(f"Estimator {name} didn't fail when fitted on sparse data but should have according to its tag self.input_tags.sparse={tags.input_tags.sparse}. The tag is inconsistent and must be fixed.")

@ignore_warnings
def check_mixin_order(name, estimator_orig):
    dag = [(ClassifierMixin, BaseEstimator), (RegressorMixin, BaseEstimator), (ClusterMixin, BaseEstimator), (TransformerMixin, BaseEstimator), (BiclusterMixin, BaseEstimator), (OneToOneFeatureMixin, BaseEstimator), (ClassNamePrefixFeaturesOutMixin, BaseEstimator), (DensityMixin, BaseEstimator), (OutlierMixin, BaseEstimator), (MetaEstimatorMixin, BaseEstimator), (MultiOutputMixin, BaseEstimator)]
    violations = []
    mro = type(estimator_orig).mro()
    for mixin_a, mixin_b in dag:
        if mixin_a in mro and mixin_b in mro and (mro.index(mixin_a) > mro.index(mixin_b)):
            violations.append((mixin_a, mixin_b))
    violation_str = '\n'.join((f'{mixin_a.__name__} comes before/left side of {mixin_b.__name__}' for mixin_a, mixin_b in violations))
    assert not violations, f'{name} is inheriting from mixins in the wrong order. In general, in mixin inheritance, more specialized mixins must come before more general ones. This means, for instance, `BaseEstimator` should be on the right side of most other mixins. You need to change the order so that:\n{violation_str}'

