        raise AssertionError(f'{name} does not generate a valid dataframe in the {case} case. The generated dataframe is not equal to the expected dataframe. The error message is: {e}') from e

def check_do_not_raise_errors_in_init_or_set_params(name, estimator_orig):
    Estimator = type(estimator_orig)
    params = signature(Estimator).parameters
    smoke_test_values = [-1, 3.0, 'helloworld', np.array([1.0, 4.0]), [1], {}, []]
    for value in smoke_test_values:
        new_params = {key: value for key in params}
        est = Estimator(**new_params)
        est.set_params(**new_params)

def squared_norm(x):
    xp, _ = get_namespace(x)
    if _is_numpy_namespace(xp) and np.issubdtype(x.dtype, np.integer):
        warnings.warn('Array type is integer, np.dot may overflow. Data should be float type to avoid this issue', UserWarning)
    return xp.tensordot(x, x, axes=x.ndim)

def row_norms(X, squared=False):
    if sparse.issparse(X):
        X = X.tocsr()
        norms = csr_row_norms(X)
        if not squared:
            norms = np.sqrt(norms)
    else:
        xp, _ = get_namespace(X)
        if _is_numpy_namespace(xp):
            X = np.asarray(X)
            norms = np.einsum('ij,ij->i', X, X)
            norms = xp.asarray(norms)
        else:
            norms = xp.sum(xp.multiply(X, X), axis=1)
        if not squared:
            norms = xp.sqrt(norms)
    return norms

def fast_logdet(A):
    xp, _ = get_namespace(A)
    sign, ld = xp.linalg.slogdet(A)
    if not sign > 0:
        return -xp.inf
    return ld

def density(w):
    if hasattr(w, 'toarray'):
        d = float(w.nnz) / (w.shape[0] * w.shape[1])
    else:
        d = 0 if w is None else float((w != 0).sum()) / w.size
    return d

def safe_sparse_dot(a, b, *, dense_output=False):
    xp, _ = get_namespace(a, b)
    if a.ndim > 2 or b.ndim > 2:
        if sparse.issparse(a):
            b_ = np.rollaxis(b, -2)
            b_2d = b_.reshape((b.shape[-2], -1))
            ret = a @ b_2d
            ret = ret.reshape(a.shape[0], *b_.shape[1:])
        elif sparse.issparse(b):
            a_2d = a.reshape(-1, a.shape[-1])
            ret = a_2d @ b
            ret = ret.reshape(*a.shape[:-1], b.shape[1])
        else:
            b_axis = -1 if b.ndim == 1 else -2
            ret = xp.tensordot(a, b, axes=[-1, b_axis])
    elif dense_output and a.ndim == 2 and (b.ndim == 2) and (sparse.issparse(a) and a.format in ('csc', 'csr')) and (sparse.issparse(b) and b.format in ('csc', 'csr')) and (a.dtype in (np.float32, np.float64)) and (b.dtype in (np.float32, np.float64)):
        return sparse_matmul_to_dense(a, b)
    else:
        ret = a @ b
    if sparse.issparse(a) and sparse.issparse(b) and dense_output and hasattr(ret, 'toarray'):
        return ret.toarray()
    return ret

def randomized_range_finder(A, *, size, n_iter, power_iteration_normalizer='auto', random_state=None):
    A = check_array(A, accept_sparse=True)
    return _randomized_range_finder(A, size=size, n_iter=n_iter, power_iteration_normalizer=power_iteration_normalizer, random_state=random_state)

def _randomized_range_finder(A, *, size, n_iter, power_iteration_normalizer='auto', random_state=None):
    xp, is_array_api_compliant = get_namespace(A)
    random_state = check_random_state(random_state)
    Q = random_state.normal(size=(A.shape[1], size))
    if A.dtype == xp.float32 or (is_array_api_compliant and _max_precision_float_dtype(xp, device=device(A)) == xp.float32):
        Q = Q.astype(np.float32, copy=False)
    if is_array_api_compliant:
        Q = xp.asarray(Q, device=device(A))
    else:
        Q = xp.asarray(Q)
    if power_iteration_normalizer == 'auto':
        if n_iter <= 2:
            power_iteration_normalizer = 'none'
        elif is_array_api_compliant:
            warnings.warn("Array API does not support LU factorization, falling back to QR instead. Set `power_iteration_normalizer='QR'` explicitly to silence this warning.")
            power_iteration_normalizer = 'QR'
        else:
            power_iteration_normalizer = 'LU'
    elif power_iteration_normalizer == 'LU' and is_array_api_compliant:
        raise ValueError("Array API does not support LU factorization. Set `power_iteration_normalizer='QR'` instead.")
    if is_array_api_compliant:
        qr_normalizer = partial(xp.linalg.qr, mode='reduced')
    else:
        qr_normalizer = partial(linalg.qr, mode='economic', check_finite=False)
    if power_iteration_normalizer == 'QR':
        normalizer = qr_normalizer
    elif power_iteration_normalizer == 'LU':
        normalizer = partial(linalg.lu, permute_l=True, check_finite=False)
    else:
        normalizer = lambda x: (x, None)
    for _ in range(n_iter):
        Q, _ = normalizer(A @ Q)
        Q, _ = normalizer(A.T @ Q)
    Q, _ = qr_normalizer(A @ Q)
    return Q

@validate_params({'M': ['array-like', 'sparse matrix'], 'n_components': [Interval(Integral, 1, None, closed='left')], 'n_oversamples': [Interval(Integral, 0, None, closed='left')], 'n_iter': [Interval(Integral, 0, None, closed='left'), StrOptions({'auto'})], 'power_iteration_normalizer': [StrOptions({'auto', 'QR', 'LU', 'none'})], 'transpose': ['boolean', StrOptions({'auto'})], 'flip_sign': ['boolean'], 'random_state': ['random_state'], 'svd_lapack_driver': [StrOptions({'gesdd', 'gesvd'})]}, prefer_skip_nested_validation=True)
def randomized_svd(M, n_components, *, n_oversamples=10, n_iter='auto', power_iteration_normalizer='auto', transpose='auto', flip_sign=True, random_state=None, svd_lapack_driver='gesdd'):
    M = check_array(M, accept_sparse=True)
    return _randomized_svd(M, n_components=n_components, n_oversamples=n_oversamples, n_iter=n_iter, power_iteration_normalizer=power_iteration_normalizer, transpose=transpose, flip_sign=flip_sign, random_state=random_state, svd_lapack_driver=svd_lapack_driver)

def _randomized_svd(M, n_components, *, n_oversamples=10, n_iter='auto', power_iteration_normalizer='auto', transpose='auto', flip_sign=True, random_state=None, svd_lapack_driver='gesdd'):
    xp, is_array_api_compliant = get_namespace(M)
    if sparse.issparse(M) and M.format in ('lil', 'dok'):
        warnings.warn('Calculating SVD of a {} is expensive. CSR format is more efficient.'.format(type(M).__name__), sparse.SparseEfficiencyWarning)
    random_state = check_random_state(random_state)
    n_random = n_components + n_oversamples
    n_samples, n_features = M.shape
    if n_iter == 'auto':
        n_iter = 7 if n_components < 0.1 * min(M.shape) else 4
    if transpose == 'auto':
        transpose = n_samples < n_features
    if transpose:
        M = M.T
    Q = _randomized_range_finder(M, size=n_random, n_iter=n_iter, power_iteration_normalizer=power_iteration_normalizer, random_state=random_state)
    B = Q.T @ M
    if is_array_api_compliant:
        Uhat, s, Vt = xp.linalg.svd(B, full_matrices=False)
    else:
        Uhat, s, Vt = linalg.svd(B, full_matrices=False, lapack_driver=svd_lapack_driver)
    del B
    U = Q @ Uhat
    if flip_sign:
        if not transpose:
            U, Vt = svd_flip(U, Vt)
        else:
            U, Vt = svd_flip(U, Vt, u_based_decision=False)
    if transpose:
        return (Vt[:n_components, :].T, s[:n_components], U[:, :n_components].T)
    else:
        return (U[:, :n_components], s[:n_components], Vt[:n_components, :])

def _randomized_eigsh(M, n_components, *, n_oversamples=10, n_iter='auto', power_iteration_normalizer='auto', selection='module', random_state=None):
    if selection == 'value':
        raise NotImplementedError()
    elif selection == 'module':
        U, S, Vt = randomized_svd(M, n_components=n_components, n_oversamples=n_oversamples, n_iter=n_iter, power_iteration_normalizer=power_iteration_normalizer, flip_sign=False, random_state=random_state)
        eigvecs = U[:, :n_components]
        eigvals = S[:n_components]
        diag_VtU = np.einsum('ji,ij->j', Vt[:n_components, :], U[:, :n_components])
        signs = np.sign(diag_VtU)
        eigvals = eigvals * signs
    else:
        raise ValueError('Invalid `selection`: %r' % selection)
    return (eigvals, eigvecs)

def svd_flip(u, v, u_based_decision=True):
    xp, _ = get_namespace(*[a for a in [u, v] if a is not None])
    if u_based_decision:
        max_abs_u_cols = xp.argmax(xp.abs(u.T), axis=1)
        shift = xp.arange(u.T.shape[0], device=device(u))
        indices = max_abs_u_cols + shift * u.T.shape[1]
        signs = xp.sign(xp.take(xp.reshape(u.T, (-1,)), indices, axis=0))
        u *= signs[np.newaxis, :]
        if v is not None:
            v *= signs[:, np.newaxis]
    else:
        max_abs_v_rows = xp.argmax(xp.abs(v), axis=1)
        shift = xp.arange(v.shape[0], device=device(v))
        indices = max_abs_v_rows + shift * v.shape[1]
        signs = xp.sign(xp.take(xp.reshape(v, (-1,)), indices, axis=0))
        if u is not None:
            u *= signs[np.newaxis, :]
        v *= signs[:, np.newaxis]
    return (u, v)

def softmax(X, copy=True):
    xp, is_array_api_compliant = get_namespace(X)
    if copy:
        X = xp.asarray(X, copy=True)
    max_prob = xp.reshape(xp.max(X, axis=1), (-1, 1))
    X -= max_prob
    if _is_numpy_namespace(xp):
        np.exp(X, out=np.asarray(X))
    else:
        X = xp.exp(X)
    sum_prob = xp.reshape(xp.sum(X, axis=1), (-1, 1))
    X /= sum_prob
    return X

def make_nonnegative(X, min_value=0):
    min_ = X.min()
    if min_ < min_value:
        if sparse.issparse(X):
            raise ValueError('Cannot make the data matrix nonnegative because it is sparse. Adding a value to every entry would make it no longer sparse.')
        X = X + (min_value - min_)
    return X

def _safe_accumulator_op(op, x, *args, **kwargs):
    xp, _, x_device = get_namespace_and_device(x)
    max_float_dtype = _max_precision_float_dtype(xp, device=x_device)
    if xp.isdtype(x.dtype, 'real floating') and xp.finfo(x.dtype).bits < xp.finfo(max_float_dtype).bits:
        target_dtype = _max_precision_float_dtype(xp, device=x_device)

        def convert_dtype(arr):
            return xp.astype(arr, target_dtype, copy=False)
        if 'dtype' in inspect.signature(op).parameters:
            return op(x, *args, **kwargs, dtype=target_dtype)
        else:
            x = convert_dtype(x)
            args = [convert_dtype(arg) if hasattr(arg, 'dtype') else arg for arg in args]
    return op(x, *args, **kwargs)

@deprecated('`sklearn.utils.extmath.stable_cumsum` is deprecated in version 1.8 and will be removed in 1.10. Use `np.cumulative_sum` with the desired dtype directly instead.')
def stable_cumsum(arr, axis=None, rtol=1e-05, atol=1e-08):
    out = np.cumsum(arr, axis=axis, dtype=np.float64)
    expected = np.sum(arr, axis=axis, dtype=np.float64)
    if not np.allclose(out.take(-1, axis=axis), expected, rtol=rtol, atol=atol, equal_nan=True):
        warnings.warn('cumsum was found to be unstable: its last element does not correspond to sum', RuntimeWarning)
    return out

def _nanaverage(a, weights=None):
    xp, _ = get_namespace(a)
    if a.shape[0] == 0:
        return xp.nan
    mask = xp.isnan(a)
    if xp.all(mask):
        return xp.nan
    if weights is None:
        return _nanmean(a, xp=xp)
    weights = xp.asarray(weights)
    a, weights = (a[~mask], weights[~mask])
    try:
        return _average(a, weights=weights)
    except ZeroDivisionError:
        return _average(a)

def safe_sqr(X, *, copy=True):
    X = check_array(X, accept_sparse=['csr', 'csc', 'coo'], ensure_2d=False)
    if sparse.issparse(X):
        if copy:
            X = X.copy()
        X.data **= 2
    elif copy:
        X = X ** 2
    else:
        X **= 2
    return X

def _preserve_dia_indices_dtype(sparse_container, original_container_format, requested_sparse_format):
    if original_container_format == 'dia_array' and requested_sparse_format in ('csr', 'coo'):
        if requested_sparse_format == 'csr':
            index_dtype = _smallest_admissible_index_dtype(arrays=(sparse_container.indptr, sparse_container.indices), maxval=max(sparse_container.nnz, sparse_container.shape[1]), check_contents=True)
            sparse_container.indices = sparse_container.indices.astype(index_dtype, copy=False)
            sparse_container.indptr = sparse_container.indptr.astype(index_dtype, copy=False)
        else:
            index_dtype = _smallest_admissible_index_dtype(maxval=max(sparse_container.shape))
            sparse_container.row = sparse_container.row.astype(index_dtype, copy=False)
            sparse_container.col = sparse_container.col.astype(index_dtype, copy=False)

def _smallest_admissible_index_dtype(arrays=(), maxval=None, check_contents=False):
    int32min = np.int32(np.iinfo(np.int32).min)
    int32max = np.int32(np.iinfo(np.int32).max)
    if maxval is not None:
        if maxval > np.iinfo(np.int64).max:
            raise ValueError(f'maxval={maxval} is to large to be represented as np.int64.')
        if maxval > int32max:
            return np.int64
    if isinstance(arrays, np.ndarray):
        arrays = (arrays,)
    for arr in arrays:
        if not isinstance(arr, np.ndarray):
            raise TypeError(f'Arrays should be of type np.ndarray, got {type(arr)} instead.')
        if not np.issubdtype(arr.dtype, np.integer):
            raise ValueError(f'Array dtype {arr.dtype} is not supported for index dtype. We expect integral values.')
        if not np.can_cast(arr.dtype, np.int32):
            if not check_contents:
                return np.int64
            if arr.size == 0:
                continue
            else:
                maxval = arr.max()
                minval = arr.min()
                if minval < int32min or maxval > int32max:
                    return np.int64
    return np.int32

def _in_unstable_openblas_configuration():
    import numpy
    import scipy
    modules_info = _get_threadpool_controller().info()
    open_blas_used = any((info['internal_api'] == 'openblas' for info in modules_info))
    if not open_blas_used:
        return False
    openblas_arm64_stable_version = parse_version('0.3.16')
    for info in modules_info:
        if info['internal_api'] != 'openblas':
            continue
        openblas_version = info.get('version')
        openblas_architecture = info.get('architecture')
        if openblas_version is None or openblas_architecture is None:
            return True
        if openblas_architecture == 'neoversen1' and parse_version(openblas_version) < openblas_arm64_stable_version:
            return True
    return False

def _ensure_sparse_index_int32(A):
    if A.format in ('csc', 'csr', 'bsr'):
        A.indices, A.indptr = _safely_cast_index_arrays(A)
    elif A.format == 'coo':
        if hasattr(A, 'coords'):
            A.coords = _safely_cast_index_arrays(A)
        elif hasattr(A, 'indices'):
            A.indices = _safely_cast_index_arrays(A)
        else:
            A.row, A.col = _safely_cast_index_arrays(A)
    elif A.format == 'dia':
        A.offsets = _safely_cast_index_arrays(A)

def _safely_cast_index_arrays(A, idx_dtype=np.int32, msg=''):
    max_value = np.iinfo(idx_dtype).max
    if A.format in ('csc', 'csr'):
        if A.indptr[-1] > max_value:
            raise ValueError(f'indptr values too large for {msg}')
        if max(*A.shape) > max_value:
            if (A.indices > max_value).any():
                raise ValueError(f'indices values too large for {msg}')
        indices = A.indices.astype(idx_dtype, copy=False)
        indptr = A.indptr.astype(idx_dtype, copy=False)
        return (indices, indptr)
    elif A.format == 'coo':
        coords = getattr(A, 'coords', None)
        if coords is None:
            coords = getattr(A, 'indices', None)
            if coords is None:
                coords = (A.row, A.col)
        if max(*A.shape) > max_value:
            if any(((co > max_value).any() for co in coords)):
                raise ValueError(f'coords values too large for {msg}')
        return tuple((co.astype(idx_dtype, copy=False) for co in coords))
    elif A.format == 'dia':
        if max(*A.shape) > max_value:
            if (A.offsets > max_value).any():
                raise ValueError(f'offsets values too large for {msg}')
        offsets = A.offsets.astype(idx_dtype, copy=False)
        return offsets
    elif A.format == 'bsr':
        R, C = A.blocksize
        if A.indptr[-1] * R > max_value:
            raise ValueError('indptr values too large for {msg}')
        if max(*A.shape) > max_value:
            if (A.indices * C > max_value).any():
                raise ValueError(f'indices values too large for {msg}')
        indices = A.indices.astype(idx_dtype, copy=False)
        indptr = A.indptr.astype(idx_dtype, copy=False)
        return (indices, indptr)

@validate_params({'graph': ['array-like', 'sparse matrix'], 'source': [Interval(Integral, 0, None, closed='left')], 'cutoff': [Interval(Integral, 0, None, closed='left'), None]}, prefer_skip_nested_validation=True)
def single_source_shortest_path_length(graph, source, *, cutoff=None):
    if sparse.issparse(graph):
        graph = graph.tolil()
    else:
        graph = sparse.lil_array(graph)
    seen = {}
    level = 0
    next_level = [source]
    while next_level:
        this_level = next_level
        next_level = set()
        for v in this_level:
            if v not in seen:
                seen[v] = level
                next_level.update(graph.rows[v])
        if cutoff is not None and cutoff <= level:
            break
        level += 1
    return seen

def _fix_connected_components(X, graph, n_connected_components, component_labels, mode='distance', metric='euclidean', **kwargs):
    if metric == 'precomputed' and sparse.issparse(X):
        raise RuntimeError("_fix_connected_components with metric='precomputed' requires the full distance matrix in X, and does not work with a sparse neighbors graph.")
    for i in range(n_connected_components):
        idx_i = np.flatnonzero(component_labels == i)
        Xi = X[idx_i]
        for j in range(i):
            idx_j = np.flatnonzero(component_labels == j)
            Xj = X[idx_j]
            if metric == 'precomputed':
                D = X[np.ix_(idx_i, idx_j)]
            else:
                D = pairwise_distances(Xi, Xj, metric=metric, **kwargs)
            ii, jj = np.unravel_index(D.argmin(axis=None), D.shape)
            if mode == 'connectivity':
                graph[idx_i[ii], idx_j[jj]] = 1
                graph[idx_j[jj], idx_i[ii]] = 1
            elif mode == 'distance':
                graph[idx_i[ii], idx_j[jj]] = D[ii, jj]
                graph[idx_j[jj], idx_i[ii]] = D[ii, jj]
            else:
                raise ValueError("Unknown mode=%r, should be one of ['connectivity', 'distance']." % mode)
    return graph

def _safe_split(estimator, X, y, indices, train_indices=None):
    if get_tags(estimator).input_tags.pairwise:
        if not hasattr(X, 'shape'):
            raise ValueError('Precomputed kernels or affinity matrices have to be passed as arrays or sparse matrices.')
        if X.shape[0] != X.shape[1]:
            raise ValueError('X should be a square kernel matrix')
        if train_indices is None:
            X_subset = X[np.ix_(indices, indices)]
        else:
            X_subset = X[np.ix_(indices, train_indices)]
    else:
        X_subset = _safe_indexing(X, indices)
    if y is not None:
        y_subset = _safe_indexing(y, indices)
    else:
        y_subset = None
    return (X_subset, y_subset)

def unique_labels(*ys, ys_types=None):
    ys = attach_unique(*ys, return_tuple=True)
    xp, is_array_api_compliant = get_namespace(*ys)
    if len(ys) == 0:
        raise ValueError('No argument has been passed.')
    if ys_types is None:
        ys_types = set((type_of_target(x) for x in ys))
        if ys_types == {'binary', 'multiclass'}:
            ys_types = {'multiclass'}
    if len(ys_types) > 1:
        raise ValueError('Mix type of y not allowed, got types %s' % ys_types)
    label_type = ys_types.pop()
    if label_type == 'multilabel-indicator' and len(set((check_array(y, accept_sparse=['csr', 'csc', 'coo']).shape[1] for y in ys))) > 1:
        raise ValueError('Multi-label binary indicator input with different numbers of labels')
    _unique_labels = _FN_UNIQUE_LABELS.get(label_type, None)
    if not _unique_labels:
        raise ValueError('Unknown label type: %s' % repr(ys))
    if is_array_api_compliant and (not _is_numpy_namespace(xp)):
        unique_ys = xp.concat([_unique_labels(y, xp=xp) for y in ys])
        return xp.unique_values(unique_ys)
    ys_labels = set(chain.from_iterable(((i for i in _unique_labels(y, xp=xp)) for y in ys)))
    if len(set((isinstance(label, str) for label in ys_labels))) > 1:
        msg_details = 'Got ' + ' and '.join([f'{xp.unique_values(y)}' for y in ys]) + '.'
        raise ValueError(f'Mix of label input types (string and number); {msg_details}')
    return xp.asarray(sorted(ys_labels))

def is_multilabel(y):
    xp, is_array_api_compliant = get_namespace(y)
    if hasattr(y, '__array__') or isinstance(y, Sequence) or is_array_api_compliant:
        check_y_kwargs = dict(accept_sparse=True, allow_nd=True, ensure_all_finite=False, ensure_2d=False, ensure_min_samples=0, ensure_min_features=0)
        with warnings.catch_warnings():
            warnings.simplefilter('error', VisibleDeprecationWarning)
            try:
                y = check_array(y, dtype=None, **check_y_kwargs)
            except (VisibleDeprecationWarning, ValueError) as e:
                if str(e).startswith('Complex data not supported'):
                    raise
                y = check_array(y, dtype=object, **check_y_kwargs)
    if not (hasattr(y, 'shape') and y.ndim == 2 and (y.shape[1] > 1)):
        return False
    if issparse(y):
        if y.format in ('dok', 'lil'):
            y = y.tocsr()
        labels = xp.unique_values(y.data)
        return len(y.data) == 0 or ((labels.size == 1 or (labels.size == 2 and 0 in labels)) and (y.dtype.kind in 'biu' or _is_integral_float(labels)))
    else:
        labels = cached_unique(y, xp=xp)
        return labels.shape[0] < 3 and (xp.isdtype(y.dtype, ('bool', 'signed integer', 'unsigned integer')) or _is_integral_float(labels))

def check_classification_targets(y):
    y_type = type_of_target(y, input_name='y')
    if y_type not in ['binary', 'multiclass', 'multiclass-multioutput', 'multilabel-indicator', 'multilabel-sequences']:
        raise ValueError(f'Unknown label type: {y_type}. Maybe you are trying to fit a classifier, which expects discrete classes on a regression target with continuous values.')
    if 'multiclass' in y_type:
        n_samples = _num_samples(y)
        if n_samples > 20 and cached_unique(y).shape[0] > round(0.5 * n_samples):
            warnings.warn('The number of unique classes is greater than 50% of the number of samples. `y` could represent a regression problem, not a classification problem.', UserWarning, stacklevel=2)

def type_of_target(y, input_name='', raise_unknown=False):
    xp, is_array_api_compliant = get_namespace(y)

    def _raise_or_return():
        """Depending on the value of raise_unknown, either raise an error or return
        'unknown'.
        """
        if raise_unknown:
            input = input_name if input_name else 'data'
            raise ValueError(f'Unknown label type for {input}: {y!r}')
        else:
            return 'unknown'
    valid = (isinstance(y, Sequence) or issparse(y) or hasattr(y, '__array__')) and (not isinstance(y, str)) or is_array_api_compliant
    if not valid:
        raise ValueError('Expected array-like (array or non-string sequence), got %r' % y)
    sparse_pandas = y.__class__.__name__ in ['SparseSeries', 'SparseArray']
    if sparse_pandas:
        raise ValueError("y cannot be class 'SparseSeries' or 'SparseArray'")
    if is_multilabel(y):
        return 'multilabel-indicator'
    check_y_kwargs = dict(accept_sparse=True, allow_nd=True, ensure_all_finite=False, ensure_2d=False, ensure_min_samples=0, ensure_min_features=0)
    with warnings.catch_warnings():
        warnings.simplefilter('error', VisibleDeprecationWarning)
        if not issparse(y):
            try:
                y = check_array(y, dtype=None, **check_y_kwargs)
            except (VisibleDeprecationWarning, ValueError) as e:
                if str(e).startswith('Complex data not supported'):
                    raise
                y = check_array(y, dtype=object, **check_y_kwargs)
    try:
        first_row_or_val = y[[0], :] if issparse(y) else y[0]
        if isinstance(first_row_or_val, bytes):
            raise TypeError('Support for labels represented as bytes is not supported. Convert the labels to a string or integer format.')
        if not hasattr(first_row_or_val, '__array__') and isinstance(first_row_or_val, Sequence) and (not isinstance(first_row_or_val, str)):
            raise ValueError('You appear to be using a legacy multi-label data representation. Sequence of sequences are no longer supported; use a binary array or sparse matrix instead - the MultiLabelBinarizer transformer can convert to this format.')
    except IndexError:
        pass
    if y.ndim not in (1, 2):
        return _raise_or_return()
    if not min(y.shape):
        if y.ndim == 1:
            return 'binary'
        return _raise_or_return()
    if not issparse(y) and y.dtype == object and (not isinstance(y.flat[0], str)):
        return _raise_or_return()
    if y.ndim == 2 and y.shape[1] > 1:
        suffix = '-multioutput'
    else:
        suffix = ''
    if xp.isdtype(y.dtype, 'real floating'):
        data = y.data if issparse(y) else y
        integral_data = xp.astype(data, xp.int64)
        if xp.any(data != xp.astype(integral_data, y.dtype)):
            _assert_all_finite(data, input_name=input_name)
            return 'continuous' + suffix
    if issparse(first_row_or_val):
        first_row_or_val = first_row_or_val.data
    if cached_unique(y).shape[0] > 2 or (y.ndim == 2 and len(first_row_or_val) > 1):
        return 'multiclass' + suffix
    else:
        return 'binary'

def _check_partial_fit_first_call(clf, classes=None):
    if getattr(clf, 'classes_', None) is None and classes is None:
        raise ValueError('classes must be passed on the first call to partial_fit.')
    elif classes is not None:
        if getattr(clf, 'classes_', None) is not None:
            if not np.array_equal(clf.classes_, unique_labels(classes)):
                raise ValueError('`classes=%r` is not the same as on last call to partial_fit, was: %r' % (classes, clf.classes_))
        else:
            clf.classes_ = unique_labels(classes)
            return True
    return False

def class_distribution(y, sample_weight=None):
    classes = []
    n_classes = []
    class_prior = []
    n_samples, n_outputs = y.shape
    if sample_weight is not None:
        sample_weight = np.asarray(sample_weight)
    if issparse(y):
        y = y.tocsc()
        y_nnz = np.diff(y.indptr)
        for k in range(n_outputs):
            col_nonzero = y.indices[y.indptr[k]:y.indptr[k + 1]]
            if sample_weight is not None:
                nz_samp_weight = sample_weight[col_nonzero]
                zeros_samp_weight_sum = np.sum(sample_weight) - np.sum(nz_samp_weight)
            else:
                nz_samp_weight = None
                zeros_samp_weight_sum = y.shape[0] - y_nnz[k]
            classes_k, y_k = np.unique(y.data[y.indptr[k]:y.indptr[k + 1]], return_inverse=True)
            class_prior_k = np.bincount(y_k, weights=nz_samp_weight)
            if 0 in classes_k:
                class_prior_k[classes_k == 0] += zeros_samp_weight_sum
            if 0 not in classes_k and y_nnz[k] < y.shape[0]:
                classes_k = np.insert(classes_k, 0, 0)
                class_prior_k = np.insert(class_prior_k, 0, zeros_samp_weight_sum)
            classes.append(classes_k)
            n_classes.append(classes_k.shape[0])
            class_prior.append(class_prior_k / class_prior_k.sum())
    else:
        for k in range(n_outputs):
            classes_k, y_k = np.unique(y[:, k], return_inverse=True)
            classes.append(classes_k)
            n_classes.append(classes_k.shape[0])
            class_prior_k = np.bincount(y_k, weights=sample_weight)
            class_prior.append(class_prior_k / class_prior_k.sum())
    return (classes, n_classes, class_prior)

def _raise_or_return():
    if raise_unknown:
        input = input_name if input_name else 'data'
        raise ValueError(f'Unknown label type for {input}: {y!r}')
    else:
        return 'unknown'

def _line_search_wolfe1(f, fprime, xk, pk, gfk=None, old_fval=None, old_old_fval=None, args=(), c1=0.0001, c2=0.9, amax=50, amin=1e-08, xtol=1e-14):
    if gfk is None:
        gfk = fprime(xk, *args)
    gval = [gfk]
    gc = [0]
    fc = [0]

    def phi(s):
        fc[0] += 1
        s = float(s)
        return float(f(xk + s * pk, *args))

    def derphi(s):
        s = float(s)
        gval[0] = fprime(xk + s * pk, *args)
        gc[0] += 1
        return float(gval[0] @ pk)
    derphi0 = float(gfk @ pk)
    stp, fval, old_fval = scalar_search_wolfe1(phi, derphi, old_fval, old_old_fval, derphi0, c1=c1, c2=c2, amax=amax, amin=amin, xtol=xtol)
    return (stp, fc[0], gc[0], fval, old_fval, gval[0])

def _line_search_wolfe12(f, fprime, xk, pk, gfk, old_fval, old_old_fval, tol, xp, device, verbose=0, **kwargs):
    is_verbose = verbose >= 2
    eps = 16 * xp.finfo(xk.dtype).eps
    if is_verbose:
        print('  Line Search')
        print(f'    eps=16 * finfo.eps={eps}')
        print('    try line search wolfe1')
    ret = _line_search_wolfe1(f, fprime, xk, pk, gfk, old_fval, old_old_fval, **kwargs)
    if is_verbose:
        if ret[0] is None:
            print('    wolfe1 line search was not successful')
        else:
            print(f'    wolfe1 line search was successful with step length={ret[0]}')
    if ret[0] is None:
        args = kwargs.get('args', tuple())
        fval = f(xk + pk, *args)
        grad = fprime(xk + pk, *args)
        gradient_times_newton = grad @ pk
        sigma = 0.00048828125
        armijo_term = sigma * gradient_times_newton
        if xp.abs(armijo_term) <= tol:
            g_max_abs = xp.max(xp.abs(grad))
            check = g_max_abs <= tol
            if is_verbose:
                print(f'    check max |gradient| <= tol: {float(g_max_abs)} <= {tol} {bool(check)}')
            if check:
                ret = (1.0, ret[1] + 1, ret[2] + 1, fval, old_fval, grad)
    if ret[0] is None:
        tiny_loss = abs(old_fval * eps)
        loss_improvement = fval - old_fval
        check = abs(loss_improvement) <= tiny_loss
        if is_verbose:
            print(f'    check loss |improvement| <= eps * |loss_old|: {abs(loss_improvement)} <= {tiny_loss} {check}')
        if check:
            sum_abs_grad_old = xp.sum(xp.abs(gfk))
            sum_abs_grad = xp.sum(xp.abs(grad))
            check = sum_abs_grad < sum_abs_grad_old
            if is_verbose:
                print(f'    check sum(|gradient|) < sum(|gradient_old|): {float(sum_abs_grad)} < {float(sum_abs_grad_old)} {bool(check)}')
            if check:
                ret = (1.0, ret[1] + 1, ret[2] + 1, fval, old_fval, grad)
    if ret[0] is None:
        if is_verbose:
            print('    last resort: try line search wolfe2')
        if not _is_numpy_namespace(xp) and sp_version < parse_version('2.0.0'):
            msg = 'Array API compatible line search requires scipy >= 2.0.0.'
            raise _LineSearchError(msg)
        ret = line_search_wolfe2(f, fprime, xk, pk, gfk, old_fval, old_old_fval, **kwargs)
        if is_verbose:
            _not_ = 'not ' if ret[0] is None else ''
            print('    wolfe2 line search was ' + _not_ + 'successful')
    if ret[0] is None:
        raise _LineSearchError()
    elif is_verbose:
        print(f'    line search successful with loss={ret[3]}.')
    return ret

def _newton_cg(grad_hess, func, grad, x0, args=(), tol=0.0001, maxiter=100, maxinner=200, line_search=True, warn=True, verbose=0):
    xp, _, device = get_namespace_and_device(x0)
    x0 = xp.asarray(x0, device=device)
    if x0.ndim != 1:
        msg = f'x0 must be 1-dimensional; got x0.ndim={x0.ndim!r}'
        raise ValueError(msg)
    xk = xp.asarray(x0, copy=True, device=device)
    k = 0
    if line_search:
        old_fval = func(x0, *args)
        old_old_fval = None
    else:
        old_fval = 0
    is_verbose = verbose > 0
    while k < maxiter:
        fgrad, fhess_p = grad_hess(xk, *args)
        absgrad = xp.abs(fgrad)
        max_absgrad = xp.max(absgrad)
        check = max_absgrad <= tol
        if is_verbose:
            print(f'Newton-CG iter = {k}')
            print('  Check Convergence')
            print(f'    max |gradient| <= tol: {float(max_absgrad)} <= {tol} {bool(check)}')
        if check:
            break
        maggrad = xp.sum(absgrad)
        eta = min([0.5, xp.sqrt(maggrad)])
        termcond = float(eta * maggrad)
        xsupi = _cg(fhess_p, fgrad, maxiter=maxinner, tol=termcond, xp=xp, device=device, verbose=verbose)
        alphak = 1.0
        if line_search:
            try:
                alphak, fc, gc, old_fval, old_old_fval, gfkp1 = _line_search_wolfe12(func, grad, xk, xsupi, fgrad, old_fval, old_old_fval, tol=tol, xp=xp, device=device, verbose=verbose, args=args)
            except _LineSearchError:
                warnings.warn('Line Search failed')
                break
        xk += float(alphak) * xsupi
        k += 1
    if warn and k >= maxiter:
        warnings.warn(f'newton-cg failed to converge at loss = {old_fval}. Increase the number of iterations.', ConvergenceWarning)
    elif is_verbose:
        print(f'  Solver did converge at loss = {old_fval}.')
    return (xk, k)

def _check_optimize_result(solver, result, max_iter=None, extra_warning_msg=None):
    if solver == 'lbfgs':
        if max_iter is not None:
            n_iter_i = min(result.nit, max_iter)
        else:
            n_iter_i = result.nit
        if result.status != 0:
            warning_msg = f'{solver} failed to converge after {n_iter_i} iteration(s) (status={result.status}):\n{result.message}\n'
            if max_iter is not None and n_iter_i == max_iter:
                warning_msg += f'\nIncrease the number of iterations to improve the convergence (max_iter={max_iter}).'
            warning_msg += '\nYou might also want to scale the data as shown in:\n    https://scikit-learn.org/stable/modules/preprocessing.html'
            if extra_warning_msg is not None:
                warning_msg += '\n' + extra_warning_msg
            warnings.warn(warning_msg, ConvergenceWarning, stacklevel=2)
    else:
        raise NotImplementedError
    return n_iter_i

def _with_config_and_warning_filters(delayed_func, config, warning_filters):
    if hasattr(delayed_func, 'with_config_and_warning_filters'):
        return delayed_func.with_config_and_warning_filters(config, warning_filters)
    else:
        warnings.warn('`sklearn.utils.parallel.Parallel` needs to be used in conjunction with `sklearn.utils.parallel.delayed` instead of `joblib.delayed` to correctly propagate the scikit-learn configuration to the joblib workers.', UserWarning)
        return delayed_func

def delayed(function):

    @functools.wraps(function)
    def delayed_function(*args, **kwargs):
        return (_FuncWrapper(function), args, kwargs)
    return delayed_function

def _get_threadpool_controller():
    global _threadpool_controller
    if _threadpool_controller is None:
        _threadpool_controller = ThreadpoolController()
    return _threadpool_controller

def _threadpool_controller_decorator(limits=1, user_api='blas'):

    def decorator(func):

        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            controller = _get_threadpool_controller()
            with controller.limit(limits=limits, user_api=user_api):
                return func(*args, **kwargs)
        return wrapper
    return decorator

def __call__(self, iterable):
    config = get_config()
    filters_func = getattr(warnings, '_get_filters', None)
    warning_filters = filters_func() if filters_func is not None else warnings.filters
    iterable_with_config_and_warning_filters = ((_with_config_and_warning_filters(delayed_func, config, warning_filters), args, kwargs) for delayed_func, args, kwargs in iterable)
    return super().__call__(iterable_with_config_and_warning_filters)

def inplace_csr_column_scale(X, scale):
    assert scale.shape[0] == X.shape[1]
    X.data *= scale.take(X.indices, mode='clip')

def inplace_csr_row_scale(X, scale):
    assert scale.shape[0] == X.shape[0]
    X.data *= np.repeat(scale, np.diff(X.indptr))

def mean_variance_axis(X, axis, weights=None, return_sum_weights=False):
    _raise_error_wrong_axis(axis)
    if sp.issparse(X) and X.format == 'csr':
        if axis == 0:
            return _csr_mean_var_axis0(X, weights=weights, return_sum_weights=return_sum_weights)
        else:
            return _csc_mean_var_axis0(X.T, weights=weights, return_sum_weights=return_sum_weights)
    elif sp.issparse(X) and X.format == 'csc':
        if axis == 0:
            return _csc_mean_var_axis0(X, weights=weights, return_sum_weights=return_sum_weights)
        else:
            return _csr_mean_var_axis0(X.T, weights=weights, return_sum_weights=return_sum_weights)
    else:
        _raise_typeerror(X)

def incr_mean_variance_axis(X, *, axis, last_mean, last_var, last_n, weights=None):
    _raise_error_wrong_axis(axis)
    if not (sp.issparse(X) and X.format in ('csc', 'csr')):
        _raise_typeerror(X)
    if np.size(last_n) == 1:
        last_n = np.full(last_mean.shape, last_n, dtype=last_mean.dtype)
    if not np.size(last_mean) == np.size(last_var) == np.size(last_n):
        raise ValueError('last_mean, last_var, last_n do not have the same shapes.')
    if axis == 1:
        if np.size(last_mean) != X.shape[0]:
            raise ValueError(f'If axis=1, then last_mean, last_n, last_var should be of size n_samples {X.shape[0]} (Got {np.size(last_mean)}).')
    elif np.size(last_mean) != X.shape[1]:
        raise ValueError(f'If axis=0, then last_mean, last_n, last_var should be of size n_features {X.shape[1]} (Got {np.size(last_mean)}).')
    X = X.T if axis == 1 else X
    if weights is not None:
        weights = _check_sample_weight(weights, X, dtype=X.dtype)
    return _incr_mean_var_axis0(X, last_mean=last_mean, last_var=last_var, last_n=last_n, weights=weights)

def inplace_column_scale(X, scale):
    if sp.issparse(X) and X.format == 'csc':
        inplace_csr_row_scale(X.T, scale)
    elif sp.issparse(X) and X.format == 'csr':
        inplace_csr_column_scale(X, scale)
    else:
        _raise_typeerror(X)

def inplace_row_scale(X, scale):
    if sp.issparse(X) and X.format == 'csc':
        inplace_csr_column_scale(X.T, scale)
    elif sp.issparse(X) and X.format == 'csr':
        inplace_csr_row_scale(X, scale)
    else:
        _raise_typeerror(X)

def inplace_swap_row_csc(X, m, n):
    for t in [m, n]:
        if isinstance(t, np.ndarray):
            raise TypeError('m and n should be valid integers')
    if m < 0:
        m += X.shape[0]
    if n < 0:
        n += X.shape[0]
    m_mask = X.indices == m
    X.indices[X.indices == n] = m
    X.indices[m_mask] = n

def inplace_swap_row_csr(X, m, n):
    for t in [m, n]:
        if isinstance(t, np.ndarray):
            raise TypeError('m and n should be valid integers')
    if m < 0:
        m += X.shape[0]
    if n < 0:
        n += X.shape[0]
    if m > n:
        m, n = (n, m)
    indptr = X.indptr
    m_start = indptr[m]
    m_stop = indptr[m + 1]
    n_start = indptr[n]
    n_stop = indptr[n + 1]
    nz_m = m_stop - m_start
    nz_n = n_stop - n_start
    if nz_m != nz_n:
        X.indptr[m + 2:n] += nz_n - nz_m
        X.indptr[m + 1] = m_start + nz_n
        X.indptr[n] = n_stop - nz_m
    X.indices = np.concatenate([X.indices[:m_start], X.indices[n_start:n_stop], X.indices[m_stop:n_start], X.indices[m_start:m_stop], X.indices[n_stop:]])
    X.data = np.concatenate([X.data[:m_start], X.data[n_start:n_stop], X.data[m_stop:n_start], X.data[m_start:m_stop], X.data[n_stop:]])

def inplace_swap_row(X, m, n):
    if sp.issparse(X) and X.format == 'csc':
        inplace_swap_row_csc(X, m, n)
    elif sp.issparse(X) and X.format == 'csr':
        inplace_swap_row_csr(X, m, n)
    else:
        _raise_typeerror(X)

def inplace_swap_column(X, m, n):
    if m < 0:
        m += X.shape[1]
    if n < 0:
        n += X.shape[1]
    if sp.issparse(X) and X.format == 'csc':
        inplace_swap_row_csr(X, m, n)
    elif sp.issparse(X) and X.format == 'csr':
        inplace_swap_row_csc(X, m, n)
    else:
        _raise_typeerror(X)

def min_max_axis(X, axis, ignore_nan=False):
    if sp.issparse(X) and X.format in ('csr', 'csc'):
        if ignore_nan:
            return _sparse_nan_min_max(X, axis=axis)
        else:
            return _sparse_min_max(X, axis=axis)
    else:
        _raise_typeerror(X)

def count_nonzero(X, axis=None, sample_weight=None):
    if axis == -1:
        axis = 1
    elif axis == -2:
        axis = 0
    elif X.format != 'csr':
        raise TypeError('Expected CSR sparse format, got {0}'.format(X.format))
    if axis is None:
        if sample_weight is None:
            return X.nnz
        else:
            return np.dot(np.diff(X.indptr), sample_weight)
    elif axis == 1:
        out = np.diff(X.indptr)
        if sample_weight is None:
            return out.astype('intp')
        return out * sample_weight
    elif axis == 0:
        if sample_weight is None:
            return np.bincount(X.indices, minlength=X.shape[1])
        else:
            weights = np.repeat(sample_weight, np.diff(X.indptr))
            return np.bincount(X.indices, minlength=X.shape[1], weights=weights)
    else:
        raise ValueError('Unsupported axis: {0}'.format(axis))

def _get_median(data, n_zeros):
    n_elems = len(data) + n_zeros
    if not n_elems:
        return np.nan
    n_negative = np.count_nonzero(data < 0)
    middle, is_odd = divmod(n_elems, 2)
    data.sort()
    if is_odd:
        return _get_elem_at_rank(middle, data, n_negative, n_zeros)
    return (_get_elem_at_rank(middle - 1, data, n_negative, n_zeros) + _get_elem_at_rank(middle, data, n_negative, n_zeros)) / 2.0

def _get_elem_at_rank(rank, data, n_negative, n_zeros):
    if rank < n_negative:
        return data[rank]
    if rank - n_negative < n_zeros:
        return 0
    return data[rank - n_zeros]

def _implicit_column_offset(X, offset):
    offset = offset[None, :]
    XT = X.T
    return LinearOperator(matvec=lambda x: X @ x - offset @ x, matmat=lambda x: X @ x - offset @ x, rmatvec=lambda x: XT @ x - offset * x.sum(), rmatmat=lambda x: XT @ x - offset.T @ x.sum(axis=0)[None, :], dtype=X.dtype, shape=X.shape)

def sparse_matmul_to_dense(A, B, out=None):
    if not (sp.issparse(A) and A.format in ('csc', 'csr') and (A.ndim == 2)):
        raise ValueError("Input 'A' must be a sparse 2-dim CSC or CSR array.")
    if not (sp.issparse(B) and B.format in ('csc', 'csr') and (B.ndim == 2)):
        raise ValueError("Input 'B' must be a sparse 2-dim CSC or CSR array.")
    if A.shape[1] != B.shape[0]:
        msg = f'Shapes must fulfil A.shape[1] == B.shape[0], got {A.shape[1]} == {B.shape[0]}.'
        raise ValueError(msg)
    n1, n2 = A.shape
    n3 = B.shape[1]
    if A.dtype != B.dtype or A.dtype not in (np.float32, np.float64):
        msg = 'Dtype of A and B must be the same, either both float32 or float64.'
        raise ValueError(msg)
    if out is None:
        out = np.empty((n1, n3), dtype=A.data.dtype)
    else:
        if out.shape[0] != n1 or out.shape[1] != n3:
            raise ValueError('Shape of out must be ({n1}, {n3}), got {out.shape}.')
        if out.dtype != A.data.dtype:
            raise ValueError('Dtype of out must match that of input A.')
    transpose_out = False
    if A.format == 'csc':
        if B.format == 'csc':
            transpose_out = True
            A, B, out = (B.T, A.T, out.T)
            n1, n3 = (n3, n1)
        else:
            A = A.tocsr()
    elif B.format == 'csc':
        B = B.tocsr()
    csr_matmul_csr_to_dense(A.data, A.indices, A.indptr, B.data, B.indices, B.indptr, out, n1, n2, n3)
    if transpose_out:
        out = out.T
    return out

def _deprecate_positional_args(func=None, *, version='1.3'):

    def _inner_deprecate_positional_args(f):
        sig = signature(f)
        kwonly_args = []
        all_args = []
        for name, param in sig.parameters.items():
            if param.kind == Parameter.POSITIONAL_OR_KEYWORD:
                all_args.append(name)
            elif param.kind == Parameter.KEYWORD_ONLY:
                kwonly_args.append(name)

        @wraps(f)
        def inner_f(*args, **kwargs):
            extra_args = len(args) - len(all_args)
            if extra_args <= 0:
                return f(*args, **kwargs)
            args_msg = [f'{name}={arg}' for name, arg in zip(kwonly_args[:extra_args], args[-extra_args:])]
            args_msg = ', '.join(args_msg)
            warnings.warn(f'Pass {args_msg} as keyword args. From version {version} passing these as positional arguments will result in an error', FutureWarning)
            kwargs.update(zip(sig.parameters, args))
            return f(**kwargs)
        return inner_f
    if func is not None:
        return _inner_deprecate_positional_args(func)
    return _inner_deprecate_positional_args

def _assert_all_finite(X, allow_nan=False, msg_dtype=None, estimator_name=None, input_name=''):
    xp, is_array_api = get_namespace(X)
    if _get_config()['assume_finite']:
        return
    X = xp.asarray(X)
    if not is_array_api and X.dtype == np.dtype('object') and (not allow_nan):
        if _object_dtype_isnan(X).any():
            raise ValueError('Input contains NaN')
    if not xp.isdtype(X.dtype, ('real floating', 'complex floating')):
        return
    with np.errstate(over='ignore'):
        first_pass_isfinite = xp.isfinite(xp.sum(X))
    if first_pass_isfinite:
        return
    _assert_all_finite_element_wise(X, xp=xp, allow_nan=allow_nan, msg_dtype=msg_dtype, estimator_name=estimator_name, input_name=input_name)

def as_float_array(X, *, copy=True, ensure_all_finite=True):
    if isinstance(X, np.matrix) or (not isinstance(X, np.ndarray) and (not sp.issparse(X))):
        return check_array(X, accept_sparse=['csr', 'csc', 'coo'], dtype=np.float64, copy=copy, ensure_all_finite=ensure_all_finite, ensure_2d=False)
    elif sp.issparse(X) and X.dtype in [np.float32, np.float64]:
        return X.copy() if copy else X
    elif X.dtype in [np.float32, np.float64]:
        return X.copy('F' if X.flags['F_CONTIGUOUS'] else 'C') if copy else X
    else:
        if X.dtype.kind in 'uib' and X.dtype.itemsize <= 4:
            return_dtype = np.float32
        else:
            return_dtype = np.float64
        return X.astype(return_dtype)

def _is_arraylike(x):
    if sp.issparse(x):
        return False
    return hasattr(x, '__len__') or hasattr(x, 'shape') or hasattr(x, '__array__')

def _num_features(X):
    type_ = type(X)
    if type_.__module__ == 'builtins':
        type_name = type_.__qualname__
    else:
        type_name = f'{type_.__module__}.{type_.__qualname__}'
    message = f'Unable to find the number of features from X of type {type_name}'
    if not hasattr(X, '__len__') and (not hasattr(X, 'shape')):
        if not hasattr(X, '__array__'):
            raise TypeError(message)
        X = np.asarray(X)
    if hasattr(X, 'shape'):
        if not hasattr(X.shape, '__len__') or len(X.shape) <= 1:
            message += f' with shape {X.shape}'
            raise TypeError(message)
        return X.shape[1]
    first_sample = X[0]
    if isinstance(first_sample, (str, bytes, dict)):
        message += f' where the samples are of type {type(first_sample).__qualname__}'
        raise TypeError(message)
    try:
        return len(first_sample)
    except Exception as err:
        raise TypeError(message) from err

def _num_samples(x):
    message = 'Expected sequence or array-like, got %s' % type(x)
    if hasattr(x, 'fit') and callable(x.fit):
        raise TypeError(message)
    if hasattr(x, 'shape') and x.shape is not None:
        if len(x.shape) == 0:
            raise TypeError(f'Input should have at least 1 dimension i.e. satisfy `len(x.shape) > 0`, got scalar `{x!r}` instead.')
        if isinstance(x.shape[0], numbers.Integral):
            return x.shape[0]
    if _nw_into_df_or_series(x):
        return nw.from_native(x, allow_series=True).shape[0]
    if not hasattr(x, '__len__') and (not hasattr(x, 'shape')):
        if hasattr(x, '__array__'):
            xp, _ = get_namespace(x)
            x = xp.asarray(x)
        else:
            raise TypeError(message)
    try:
        return len(x)
    except TypeError as type_error:
        raise TypeError(message) from type_error

def check_memory(memory):
    if memory is None or isinstance(memory, str):
        memory = joblib.Memory(location=memory, verbose=0)
    elif not hasattr(memory, 'cache'):
        raise ValueError(f"'memory' should be None, a string or have the same interface as joblib.Memory. Got memory='{memory}' instead.")
    return memory

def check_consistent_length(*arrays):
    lengths = [_num_samples(X) for X in arrays if X is not None]
    if len(set(lengths)) > 1:
        raise ValueError('Found input variables with inconsistent numbers of samples: %r' % [int(l) for l in lengths])

def _make_indexable(iterable):
    if sp.issparse(iterable):
        return iterable.tocsr()
    elif hasattr(iterable, '__getitem__') or hasattr(iterable, 'iloc'):
        return iterable
    elif iterable is None:
        return iterable
    return np.array(iterable)

def _ensure_sparse_format(sparse_container, accept_sparse, dtype, copy, ensure_all_finite, accept_large_sparse, estimator_name=None, input_name=''):
    if dtype is None:
        dtype = sparse_container.dtype
    changed_format = False
    sparse_container_type_name = type(sparse_container).__name__
    if isinstance(accept_sparse, str):
        accept_sparse = [accept_sparse]
    _check_large_sparse(sparse_container, accept_large_sparse)
    if accept_sparse is False:
        padded_input = ' for ' + input_name if input_name else ''
        raise TypeError(f"Sparse data was passed{padded_input}, but dense data is required. Use '.toarray()' to convert to a dense numpy array.")
    elif isinstance(accept_sparse, (list, tuple)):
        if len(accept_sparse) == 0:
            raise ValueError("When providing 'accept_sparse' as a tuple or list, it must contain at least one string value.")
        if sparse_container.format not in accept_sparse:
            sparse_container = sparse_container.asformat(accept_sparse[0])
            changed_format = True
    elif accept_sparse is not True:
        raise ValueError(f"Parameter 'accept_sparse' should be a string, boolean or list of strings. You provided 'accept_sparse={accept_sparse}'.")
    if dtype != sparse_container.dtype:
        sparse_container = sparse_container.astype(dtype)
    elif copy and (not changed_format):
        sparse_container = sparse_container.copy()
    if ensure_all_finite:
        if not hasattr(sparse_container, 'data'):
            warnings.warn(f"Can't check {sparse_container.format} sparse matrix for nan or inf.", stacklevel=2)
        else:
            _assert_all_finite(sparse_container.data, allow_nan=ensure_all_finite == 'allow-nan', estimator_name=estimator_name, input_name=input_name)
    if changed_format:
        requested_sparse_format = accept_sparse[0]
        _preserve_dia_indices_dtype(sparse_container, sparse_container_type_name, requested_sparse_format)
    return sparse_container

def _pandas_dtype_needs_early_conversion(pd_dtype):
    from pandas import SparseDtype
    from pandas.api.types import is_bool_dtype, is_float_dtype, is_integer_dtype
    if is_bool_dtype(pd_dtype):
        return True
    if isinstance(pd_dtype, SparseDtype):
        return False
    try:
        from pandas.api.types import is_extension_array_dtype
    except ImportError:
        return False
    if isinstance(pd_dtype, SparseDtype) or not is_extension_array_dtype(pd_dtype):
        return False
    elif is_float_dtype(pd_dtype):
        return True
    elif is_integer_dtype(pd_dtype):
        return True
    return False

def _is_pandas_string_dtype(dtype):
    try:
        from pandas import StringDtype
        return isinstance(dtype, StringDtype)
    except ImportError:
        return False

def check_array(array, accept_sparse=False, *, accept_large_sparse=True, dtype='numeric', order=None, copy=False, force_writeable=False, ensure_all_finite=True, ensure_non_negative=False, ensure_2d=True, allow_nd=False, ensure_min_samples=1, ensure_min_features=1, estimator=None, input_name=''):
    if isinstance(array, np.matrix):
        raise TypeError('np.matrix is not supported. Please convert to a numpy array with np.asarray. For more information see: https://numpy.org/doc/stable/reference/generated/numpy.matrix.html')
    xp, is_array_api_compliant = get_namespace(array)
    array_orig = array
    dtype_numeric = isinstance(dtype, str) and dtype == 'numeric'
    dtype_orig = getattr(array, 'dtype', None)
    if not is_array_api_compliant and (not hasattr(dtype_orig, 'kind')):
        dtype_orig = None
    dtypes_orig = None
    pandas_requires_conversion = False
    type_if_series = None
    if _nw_into_df_or_series(array):
        array_df = nw.from_native(array, allow_series=True)
    else:
        array_df = None
    is_pandas_fully_sparse_df = False
    if array_df is not None and array_df.implementation.is_pandas() and (len(array_df.shape) >= 2):
        from pandas import SparseDtype

        def is_pd_sparse(dtype):
            return isinstance(dtype, SparseDtype)
        df_pandas = array_df.to_native()
        if hasattr(df_pandas, 'sparse') and df_pandas.dtypes.apply(is_pd_sparse).all():
            is_pandas_fully_sparse_df = True
        elif df_pandas.dtypes.apply(is_pd_sparse).any():
            warnings.warn('pandas.DataFrame with sparse columns found.It will be converted to a dense numpy array.')
        dtypes_orig = list(df_pandas.dtypes)
        pandas_requires_conversion = any((_pandas_dtype_needs_early_conversion(i) for i in dtypes_orig))
        has_pandas_string = any((_is_pandas_string_dtype(d) for d in dtypes_orig))
        if all((isinstance(dtype_iter, np.dtype) for dtype_iter in dtypes_orig)):
            dtype_orig = np.result_type(*dtypes_orig)
        elif has_pandas_string:
            dtype_orig = object
        elif pandas_requires_conversion and any((d == object for d in dtypes_orig)):
            dtype_orig = object
    elif (_is_extension_array_dtype(array) or hasattr(array, 'iloc')) and hasattr(array, 'dtype'):
        type_if_series = type(array)
        pandas_requires_conversion = _pandas_dtype_needs_early_conversion(array.dtype)
        if isinstance(array.dtype, np.dtype):
            dtype_orig = array.dtype
        elif _is_pandas_string_dtype(array.dtype):
            dtype_orig = object
        else:
            dtype_orig = None
    if dtype_numeric:
        if dtype_orig is not None and (hasattr(dtype_orig, 'kind') and dtype_orig.kind == 'O' or dtype_orig == object):
            dtype = xp.float64
        else:
            dtype = None
    if isinstance(dtype, (list, tuple)):
        if dtype_orig is not None and dtype_orig in dtype:
            dtype = None
        else:
            dtype = dtype[0]
    if pandas_requires_conversion:
        new_dtype = dtype_orig if dtype is None else dtype
        array = array.astype(new_dtype)
        dtype = None
    if ensure_all_finite not in (True, False, 'allow-nan'):
        raise ValueError(f"ensure_all_finite should be a bool or 'allow-nan'. Got {ensure_all_finite!r} instead.")
    if dtype is not None and _is_numpy_namespace(xp):
        dtype = np.dtype(dtype)
    estimator_name = _check_estimator_name(estimator)
    context = ' by %s' % estimator_name if estimator is not None else ''
    if is_pandas_fully_sparse_df:
        array = df_pandas.sparse.to_coo()
    if sp.issparse(array):
        _ensure_no_complex_data(array)
        array = _ensure_sparse_format(array, accept_sparse=accept_sparse, dtype=dtype, copy=copy, ensure_all_finite=ensure_all_finite, accept_large_sparse=accept_large_sparse, estimator_name=estimator_name, input_name=input_name)
        if ensure_2d and array.ndim < 2:
            raise ValueError(f'Expected 2D input, got input with shape {array.shape}.\nReshape your data either using array.reshape(-1, 1) if your data has a single feature or array.reshape(1, -1) if it contains a single sample.')
    else:
        with warnings.catch_warnings():
            try:
                warnings.simplefilter('error', ComplexWarning)
                if dtype is not None and xp.isdtype(dtype, 'integral'):
                    array = _asarray_with_order(array, order=order, xp=xp)
                    if xp.isdtype(array.dtype, ('real floating', 'complex floating')):
                        _assert_all_finite(array, allow_nan=False, msg_dtype=dtype, estimator_name=estimator_name, input_name=input_name)
                    array = xp.astype(array, dtype, copy=False)
                else:
                    array = _asarray_with_order(array, order=order, dtype=dtype, xp=xp)
            except ComplexWarning as complex_warning:
                raise ValueError('Complex data not supported\n{}\n'.format(array)) from complex_warning
        _ensure_no_complex_data(array)
        if ensure_2d:
            if array.ndim == 0:
                raise ValueError('Expected 2D array, got scalar array instead:\narray={}.\nReshape your data either using array.reshape(-1, 1) if your data has a single feature or array.reshape(1, -1) if it contains a single sample.'.format(array))
            if array.ndim == 1:
                if type_if_series is not None:
                    msg = f'Expected a 2-dimensional container but got {type_if_series} instead. Pass a DataFrame containing a single row (i.e. single sample) or a single column (i.e. single feature) instead.'
                else:
                    msg = f'Expected 2D array, got 1D array instead:\narray={array}.\nReshape your data either using array.reshape(-1, 1) if your data has a single feature or array.reshape(1, -1) if it contains a single sample.'
                raise ValueError(msg)
        if dtype_numeric and hasattr(array.dtype, 'kind') and (array.dtype.kind in 'USV'):
            raise ValueError("dtype='numeric' is not compatible with arrays of bytes/strings.Convert your data to numeric values explicitly instead.")
        if not allow_nd and array.ndim >= 3:
            raise ValueError(f'Found array with dim {array.ndim}, while dim <= 2 is required{context}.')
        if ensure_all_finite:
            _assert_all_finite(array, input_name=input_name, estimator_name=estimator_name, allow_nan=ensure_all_finite == 'allow-nan')
        if copy:
            if _is_numpy_namespace(xp):
                if np.may_share_memory(array, array_orig):
                    array = _asarray_with_order(array, dtype=dtype, order=order, copy=True, xp=xp)
            else:
                array = _asarray_with_order(array, dtype=dtype, order=order, copy=True, xp=xp)
    if ensure_min_samples > 0:
        n_samples = _num_samples(array)
        if n_samples < ensure_min_samples:
            raise ValueError('Found array with %d sample(s) (shape=%s) while a minimum of %d is required%s.' % (n_samples, array.shape, ensure_min_samples, context))
    if ensure_min_features > 0 and array.ndim == 2:
        n_features = array.shape[1]
        if n_features < ensure_min_features:
            raise ValueError('Found array with %d feature(s) (shape=%s) while a minimum of %d is required%s.' % (n_features, array.shape, ensure_min_features, context))
    if ensure_non_negative:
        whom = input_name
        if estimator_name:
            whom += f' in {estimator_name}'
        check_non_negative(array, whom)
    if force_writeable:
        copy_params = {'order': 'K'} if not sp.issparse(array) else {}
        array_data = array.data if sp.issparse(array) else array
        flags = getattr(array_data, 'flags', None)
        if not getattr(flags, 'writeable', True):
            if is_pandas_df_or_series(array_orig):
                try:
                    array_data.flags.writeable = True
                except ValueError:
                    array = array.copy(**copy_params)
            else:
                array = array.copy(**copy_params)
    return array

def _check_large_sparse(X, accept_large_sparse=False):
    if not accept_large_sparse:
        supported_indices = ['int32']
        if X.format == 'coo':
            index_keys = ['col', 'row']
        elif X.format in ['csr', 'csc', 'bsr']:
            index_keys = ['indices', 'indptr']
        else:
            return
        for key in index_keys:
            indices_datatype = getattr(X, key).dtype
            if indices_datatype not in supported_indices:
                raise ValueError(f'Only sparse matrices with 32-bit integer indices are accepted. Got {indices_datatype} indices. Please do report a minimal reproducer on scikit-learn issue tracker so that support for your use-case can be studied by maintainers. See: https://scikit-learn.org/dev/developers/minimal_reproducer.html')

def check_X_y(X, y, accept_sparse=False, *, accept_large_sparse=True, dtype='numeric', order=None, copy=False, force_writeable=False, ensure_all_finite=True, ensure_2d=True, allow_nd=False, multi_output=False, ensure_min_samples=1, ensure_min_features=1, y_numeric=False, estimator=None):
    if y is None:
        if estimator is None:
            estimator_name = 'estimator'
        else:
            estimator_name = _check_estimator_name(estimator)
        raise ValueError(f'{estimator_name} requires y to be passed, but the target y is None')
    X = check_array(X, accept_sparse=accept_sparse, accept_large_sparse=accept_large_sparse, dtype=dtype, order=order, copy=copy, force_writeable=force_writeable, ensure_all_finite=ensure_all_finite, ensure_2d=ensure_2d, allow_nd=allow_nd, ensure_min_samples=ensure_min_samples, ensure_min_features=ensure_min_features, estimator=estimator, input_name='X')
    y = _check_y(y, multi_output=multi_output, y_numeric=y_numeric, estimator=estimator)
    check_consistent_length(X, y)
    return (X, y)

def _check_y(y, multi_output=False, y_numeric=False, estimator=None):
    if multi_output:
        y = check_array(y, accept_sparse='csr', ensure_all_finite=True, ensure_2d=False, dtype=None, input_name='y', estimator=estimator)
    else:
        estimator_name = _check_estimator_name(estimator)
        y = column_or_1d(y, warn=True)
        _assert_all_finite(y, input_name='y', estimator_name=estimator_name)
        _ensure_no_complex_data(y)
    if y_numeric and hasattr(y.dtype, 'kind') and (y.dtype.kind == 'O'):
        y = y.astype(np.float64)
    return y

def column_or_1d(y, *, dtype=None, input_name='y', warn=False, device=None):
    xp, _ = get_namespace(y)
    y = check_array(y, ensure_2d=False, dtype=dtype, input_name=input_name, ensure_all_finite=False, ensure_min_samples=0)
    shape = y.shape
    if len(shape) == 1:
        return _asarray_with_order(xp.reshape(y, (-1,)), order='C', xp=xp, device=device)
    if len(shape) == 2 and shape[1] == 1:
        if warn:
            warnings.warn('A column-vector y was passed when a 1d array was expected. Please change the shape of y to (n_samples, ), for example using ravel().', DataConversionWarning, stacklevel=2)
        return _asarray_with_order(xp.reshape(y, (-1,)), order='C', xp=xp, device=device)
    raise ValueError('y should be a 1d array, got an array of shape {} instead.'.format(shape))

def check_random_state(seed):
    if seed is None or seed is np.random:
        return np.random.mtrand._rand
    if isinstance(seed, numbers.Integral):
        return np.random.RandomState(seed)
    if isinstance(seed, np.random.RandomState):
        return seed
    raise ValueError(f'{seed!r} cannot be used to seed a numpy.random.RandomState instance')

def check_symmetric(array, *, tol=1e-10, raise_warning=True, raise_exception=False):
    if array.ndim != 2 or array.shape[0] != array.shape[1]:
        raise ValueError('array must be 2-dimensional and square. shape = {0}'.format(array.shape))
    if sp.issparse(array):
        diff = array - array.T
        if diff.format not in ['csr', 'csc', 'coo']:
            diff = diff.tocsr()
        symmetric = np.all(abs(diff.data) < tol)
    else:
        symmetric = np.allclose(array, array.T, atol=tol)
    if not symmetric:
        if raise_exception:
            raise ValueError('Array must be symmetric')
        if raise_warning:
            warnings.warn('Array is not symmetric, and will be converted to symmetric by average with its transpose.', stacklevel=2)
        if sp.issparse(array):
            conversion = 'to' + array.format
            array = getattr(0.5 * (array + array.T), conversion)()
        else:
            array = 0.5 * (array + array.T)
    return array

def _is_fitted(estimator, attributes=None, all_or_any=all):
    if attributes is not None:
        if not isinstance(attributes, (list, tuple)):
            attributes = [attributes]
        return all_or_any([hasattr(estimator, attr) for attr in attributes])
    if hasattr(estimator, '__sklearn_is_fitted__'):
        return estimator.__sklearn_is_fitted__()
    fitted_attrs = [v for v in vars(estimator) if v.endswith('_') and (not v.startswith('__'))]
    return len(fitted_attrs) > 0

def check_is_fitted(estimator, attributes=None, *, msg=None, all_or_any=all):
    if isclass(estimator):
        raise TypeError(f'{estimator} is a class, not an instance.')
    if msg is None:
        msg = "This %(name)s instance is not fitted yet. Call 'fit' with appropriate arguments before using this estimator."
    if not hasattr(estimator, 'fit'):
        raise TypeError(f'{estimator} is not an estimator instance.')
    tags = get_tags(estimator)
    if not tags.requires_fit and attributes is None:
        return
    if not _is_fitted(estimator, attributes, all_or_any):
        raise NotFittedError(msg % {'name': type(estimator).__name__})

def _estimator_has(attr, *, delegates=('estimator_', 'estimator')):

    def check(self):
        for delegate in delegates:
            if hasattr(self, delegate):
                delegator = getattr(self, delegate)
                if isinstance(delegator, Sequence):
                    return getattr(delegator[0], attr)
                else:
                    return getattr(delegator, attr)
        raise ValueError(f'None of the delegates {delegates} are present in the class.')
    return check

def check_non_negative(X, whom):
    xp, _ = get_namespace(X)
    if sp.issparse(X):
        if X.format in ['lil', 'dok']:
            X = X.tocsr()
        if X.data.size == 0:
            X_min = 0
        else:
            X_min = X.data.min()
    else:
        X_min = xp.min(X)
    if X_min < 0:
        raise ValueError(f'Negative values in data passed to {whom}.')

def check_scalar(x, name, target_type, *, min_val=None, max_val=None, include_boundaries='both'):

    def type_name(t):
        """Convert type into humman readable string."""
        module = t.__module__
        qualname = t.__qualname__
        if module == 'builtins':
            return qualname
        elif t == numbers.Real:
            return 'float'
        elif t == numbers.Integral:
            return 'int'
        return f'{module}.{qualname}'
    if not isinstance(x, target_type):
        if isinstance(target_type, tuple):
            types_str = ', '.join((type_name(t) for t in target_type))
            target_type_str = f'{{{types_str}}}'
        else:
            target_type_str = type_name(target_type)
        raise TypeError(f'{name} must be an instance of {target_type_str}, not {type(x).__qualname__}.')
    expected_include_boundaries = ('left', 'right', 'both', 'neither')
    if include_boundaries not in expected_include_boundaries:
        raise ValueError(f'Unknown value for `include_boundaries`: {include_boundaries!r}. Possible values are: {expected_include_boundaries}.')
    if max_val is None and include_boundaries == 'right':
        raise ValueError("`include_boundaries`='right' without specifying explicitly `max_val` is inconsistent.")
    if min_val is None and include_boundaries == 'left':
        raise ValueError("`include_boundaries`='left' without specifying explicitly `min_val` is inconsistent.")
    comparison_operator = operator.lt if include_boundaries in ('left', 'both') else operator.le
    if min_val is not None and comparison_operator(x, min_val):
        raise ValueError(f"{name} == {x}, must be {('>=' if include_boundaries in ('left', 'both') else '>')} {min_val}.")
    comparison_operator = operator.gt if include_boundaries in ('right', 'both') else operator.ge
    if max_val is not None and comparison_operator(x, max_val):
        raise ValueError(f"{name} == {x}, must be {('<=' if include_boundaries in ('right', 'both') else '<')} {max_val}.")
    return x

def _check_psd_eigenvalues(lambdas, enable_warnings=False):
    lambdas = np.array(lambdas)
    is_double_precision = lambdas.dtype == np.float64
    significant_imag_ratio = 1e-05
    significant_neg_ratio = 1e-05 if is_double_precision else 0.005
    significant_neg_value = 1e-10 if is_double_precision else 1e-06
    small_pos_ratio = 1e-12 if is_double_precision else 2e-07
    if not np.isreal(lambdas).all():
        max_imag_abs = np.abs(np.imag(lambdas)).max()
        max_real_abs = np.abs(np.real(lambdas)).max()
        if max_imag_abs > significant_imag_ratio * max_real_abs:
            raise ValueError('There are significant imaginary parts in eigenvalues (%g of the maximum real part). Either the matrix is not PSD, or there was an issue while computing the eigendecomposition of the matrix.' % (max_imag_abs / max_real_abs))
        if enable_warnings:
            warnings.warn('There are imaginary parts in eigenvalues (%g of the maximum real part). Either the matrix is not PSD, or there was an issue while computing the eigendecomposition of the matrix. Only the real parts will be kept.' % (max_imag_abs / max_real_abs), PositiveSpectrumWarning)
    lambdas = np.real(lambdas)
    max_eig = lambdas.max()
    if max_eig < 0:
        raise ValueError('All eigenvalues are negative (maximum is %g). Either the matrix is not PSD, or there was an issue while computing the eigendecomposition of the matrix.' % max_eig)
    else:
        min_eig = lambdas.min()
        if min_eig < -significant_neg_ratio * max_eig and min_eig < -significant_neg_value:
            raise ValueError('There are significant negative eigenvalues (%g of the maximum positive). Either the matrix is not PSD, or there was an issue while computing the eigendecomposition of the matrix.' % (-min_eig / max_eig))
        elif min_eig < 0:
            if enable_warnings:
                warnings.warn('There are negative eigenvalues (%g of the maximum positive). Either the matrix is not PSD, or there was an issue while computing the eigendecomposition of the matrix. Negative eigenvalues will be replaced with 0.' % (-min_eig / max_eig), PositiveSpectrumWarning)
            lambdas[lambdas < 0] = 0
    too_small_lambdas = (0 < lambdas) & (lambdas < small_pos_ratio * max_eig)
    if too_small_lambdas.any():
        if enable_warnings:
            warnings.warn('Badly conditioned PSD matrix spectrum: the largest eigenvalue is more than %g times the smallest. Small eigenvalues will be replaced with 0.' % (1 / small_pos_ratio), PositiveSpectrumWarning)
        lambdas[too_small_lambdas] = 0
    return lambdas

def _check_sample_weight(sample_weight, X, *, dtype=None, force_float_dtype=True, ensure_non_negative=False, ensure_same_device=True, copy=False, allow_all_zero_weights=False):
    xp, is_array_api, device = get_namespace_and_device(X, remove_types=(list, int, float))
    n_samples = _num_samples(X)
    max_float_type = _max_precision_float_dtype(xp, device)
    float_dtypes = [xp.float32] if max_float_type == xp.float32 else [xp.float64, xp.float32]
    if force_float_dtype and dtype is not None and (dtype not in float_dtypes):
        dtype = max_float_type
    if sample_weight is None:
        sample_weight = xp.ones(n_samples, dtype=dtype, device=device)
    elif isinstance(sample_weight, numbers.Number):
        sample_weight = xp.full(n_samples, sample_weight, dtype=dtype, device=device)
    else:
        if force_float_dtype and dtype is None:
            dtype = float_dtypes
        if is_array_api and ensure_same_device:
            sample_weight = move_to(sample_weight, xp=xp, device=device)
        sample_weight = check_array(sample_weight, accept_sparse=False, ensure_2d=False, dtype=dtype, order='C', copy=copy, input_name='sample_weight')
        if sample_weight.ndim != 1:
            raise ValueError(f'Sample weights must be 1D array or scalar, got {sample_weight.ndim}D array. Expected either a scalar value or a 1D array of length {n_samples}.')
        if sample_weight.shape != (n_samples,):
            raise ValueError('sample_weight.shape == {}, expected {}!'.format(sample_weight.shape, (n_samples,)))
    if not allow_all_zero_weights:
        if xp.all(sample_weight == 0):
            raise ValueError('Sample weights must contain at least one non-zero number.')
    if ensure_non_negative:
        check_non_negative(sample_weight, '`sample_weight`')
    return sample_weight

def _allclose_dense_sparse(x, y, rtol=1e-07, atol=1e-09):
    if sp.issparse(x) and sp.issparse(y):
        x = x.tocsr()
        y = y.tocsr()
        x.sum_duplicates()
        y.sum_duplicates()
        return np.array_equal(x.indices, y.indices) and np.array_equal(x.indptr, y.indptr) and np.allclose(x.data, y.data, rtol=rtol, atol=atol)
    elif not sp.issparse(x) and (not sp.issparse(y)):
        return np.allclose(x, y, rtol=rtol, atol=atol)
    raise ValueError('Can only compare two sparse matrices, not a sparse matrix and an array')

def _check_response_method(estimator, response_method):
    if isinstance(response_method, str):
        list_methods = [response_method]
    else:
        list_methods = response_method
    prediction_method = [getattr(estimator, method, None) for method in list_methods]
    prediction_method = reduce(lambda x, y: x or y, prediction_method)
    if prediction_method is None:
        raise AttributeError(f"{estimator.__class__.__name__} has none of the following attributes: {', '.join(list_methods)}.")
    return prediction_method

def _check_method_params(X, params, indices=None):
    from sklearn.utils import _safe_indexing
    method_params_validated = {}
    for param_key, param_value in params.items():
        if not _is_arraylike(param_value) and (not sp.issparse(param_value)) or _num_samples(param_value) != _num_samples(X):
            method_params_validated[param_key] = param_value
        else:
            method_params_validated[param_key] = _make_indexable(param_value)
            method_params_validated[param_key] = _safe_indexing(method_params_validated[param_key], indices)
    return method_params_validated

def _get_feature_names(X):
    feature_names = None
    if nw.dependencies.is_into_dataframe(X):
        feature_names = np.asarray(nw.from_native(X).columns, dtype=object)
    if feature_names is None or len(feature_names) == 0:
        return
    types = sorted((t.__qualname__ for t in set((type(v) for v in feature_names))))
    if len(types) > 1 and 'str' in types:
        raise TypeError(f'Feature names are only supported if all input features have string names, but your input has {types} as feature name / column name types. If you want feature names to be stored and validated, you must convert them all to strings, by using X.columns = X.columns.astype(str) for example. Otherwise you can remove feature / column names from your input data, or convert them all to a non-string data type.')
    if len(types) == 1 and types[0] == 'str':
        return feature_names

def _check_feature_names_in(estimator, input_features=None, *, generate_names=True):
    feature_names_in_ = getattr(estimator, 'feature_names_in_', None)
    n_features_in_ = getattr(estimator, 'n_features_in_', None)
    if input_features is not None:
        input_features = np.asarray(input_features, dtype=object)
        if feature_names_in_ is not None and (not np.array_equal(feature_names_in_, input_features)):
            raise ValueError('input_features is not equal to feature_names_in_')
        if n_features_in_ is not None and len(input_features) != n_features_in_:
            raise ValueError(f'input_features should have length equal to number of features ({n_features_in_}), got {len(input_features)}')
        return input_features
    if feature_names_in_ is not None:
        return feature_names_in_
    if not generate_names:
        return
    if n_features_in_ is None:
        raise ValueError('Unable to generate feature names without n_features_in_')
    return np.asarray([f'x{i}' for i in range(n_features_in_)], dtype=object)

def _generate_get_feature_names_out(estimator, n_features_out, input_features=None):
    _check_feature_names_in(estimator, input_features, generate_names=False)
    estimator_name = estimator.__class__.__name__.lower()
    return np.asarray([f'{estimator_name}{i}' for i in range(n_features_out)], dtype=object)

def _check_categorical_features(X, categorical_features):
    if nw.dependencies.is_into_dataframe(X):
        X = nw.from_native(X)
        dtypes = X.schema.dtypes()
        X_is_dataframe = True
        categorical_columns_mask = np.asarray([d in (nw.Categorical, nw.Enum) for d in dtypes])
    else:
        X_is_dataframe = False
        categorical_columns_mask = None
    categorical_by_dtype = isinstance(categorical_features, str) and categorical_features == 'from_dtype'
    no_categorical_dtype = categorical_features is None or (categorical_by_dtype and (not X_is_dataframe))
    if no_categorical_dtype:
        return None
    if categorical_by_dtype and X_is_dataframe:
        categorical_features = categorical_columns_mask
    else:
        categorical_features = np.asarray(categorical_features)
    if categorical_features.size == 0:
        return None
    if categorical_features.dtype.kind not in ('i', 'b', 'U', 'O'):
        raise ValueError(f'categorical_features must be an array-like of bool, int or str, got: {categorical_features.dtype.name}.')
    if categorical_features.dtype.kind == 'O':
        types = set((type(f) for f in categorical_features))
        if types != {str}:
            raise ValueError(f"categorical_features must be an array-like of bool, int or str, got: {', '.join(sorted((t.__name__ for t in types)))}.")
    n_features = X.shape[1]
    feature_names_in_ = getattr(X, 'columns', None)
    if categorical_features.dtype.kind in ('U', 'O'):
        if feature_names_in_ is None:
            raise ValueError('categorical_features should be passed as an array of integers or as a boolean mask when the model is fitted on data without feature names.')
        is_categorical = np.zeros(n_features, dtype=bool)
        feature_names = list(feature_names_in_)
        for feature_name in categorical_features:
            try:
                is_categorical[feature_names.index(feature_name)] = True
            except ValueError as e:
                raise ValueError(f"categorical_features has an item value '{feature_name}' which is not a valid feature name of the training data. Observed feature names: {feature_names}") from e
    elif categorical_features.dtype.kind == 'i':
        if np.max(categorical_features) >= n_features or np.min(categorical_features) < 0:
            raise ValueError('categorical_features set as integer indices must be in [0, n_features - 1]')
        is_categorical = np.zeros(n_features, dtype=bool)
        is_categorical[categorical_features] = True
    else:
        if categorical_features.shape[0] != n_features:
            raise ValueError(f'categorical_features set as a boolean mask must have shape (n_features,), got: {categorical_features.shape}')
        is_categorical = categorical_features
    if not np.any(is_categorical):
        return None
    return is_categorical

def _check_monotonic_cst(estimator, monotonic_cst=None):
    original_monotonic_cst = monotonic_cst
    if monotonic_cst is None or isinstance(monotonic_cst, dict):
        monotonic_cst = np.full(shape=estimator.n_features_in_, fill_value=0, dtype=np.int8)
        if isinstance(original_monotonic_cst, dict):
            if not hasattr(estimator, 'feature_names_in_'):
                raise ValueError(f'{estimator.__class__.__name__} was not fitted on data with feature names. Pass monotonic_cst as an integer array instead.')
            unexpected_feature_names = list(set(original_monotonic_cst) - set(estimator.feature_names_in_))
            unexpected_feature_names.sort()
            n_unexpected = len(unexpected_feature_names)
            if unexpected_feature_names:
                if len(unexpected_feature_names) > 5:
                    unexpected_feature_names = unexpected_feature_names[:5]
                    unexpected_feature_names.append('...')
                raise ValueError(f'monotonic_cst contains {n_unexpected} unexpected feature names: {unexpected_feature_names}.')
            for feature_idx, feature_name in enumerate(estimator.feature_names_in_):
                if feature_name in original_monotonic_cst:
                    cst = original_monotonic_cst[feature_name]
                    if cst not in [-1, 0, 1]:
                        raise ValueError(f"monotonic_cst['{feature_name}'] must be either -1, 0 or 1. Got {cst!r}.")
                    monotonic_cst[feature_idx] = cst
    else:
        unexpected_cst = np.setdiff1d(monotonic_cst, [-1, 0, 1])
        if unexpected_cst.shape[0]:
            raise ValueError(f'monotonic_cst must be an array-like of -1, 0 or 1. Observed values: {unexpected_cst.tolist()}.')
        monotonic_cst = np.asarray(monotonic_cst, dtype=np.int8)
        if monotonic_cst.shape[0] != estimator.n_features_in_:
            raise ValueError(f'monotonic_cst has shape {monotonic_cst.shape} but the input data X has {estimator.n_features_in_} features.')
    return monotonic_cst

def _check_feature_names(estimator, X, *, reset):
    if reset:
        feature_names_in = _get_feature_names(X)
        if feature_names_in is not None:
            estimator.feature_names_in_ = feature_names_in
        elif hasattr(estimator, 'feature_names_in_'):
            delattr(estimator, 'feature_names_in_')
        return
    fitted_feature_names = getattr(estimator, 'feature_names_in_', None)
    X_feature_names = _get_feature_names(X)
    if fitted_feature_names is None and X_feature_names is None:
        return
    if X_feature_names is not None and fitted_feature_names is None:
        warnings.warn(f'X has feature names, but {estimator.__class__.__name__} was fitted without feature names')
        return
    if X_feature_names is None and fitted_feature_names is not None:
        warnings.warn(f'X does not have valid feature names, but {estimator.__class__.__name__} was fitted with feature names')
        return
    if len(fitted_feature_names) != len(X_feature_names) or np.any(fitted_feature_names != X_feature_names):
        message = 'The feature names should match those that were passed during fit.\n'
        fitted_feature_names_set = set(fitted_feature_names)
        X_feature_names_set = set(X_feature_names)
        unexpected_names = sorted(X_feature_names_set - fitted_feature_names_set)
        missing_names = sorted(fitted_feature_names_set - X_feature_names_set)

        def add_names(names):
            output = ''
            max_n_names = 5
            for i, name in enumerate(names):
                if i >= max_n_names:
                    output += '- ...\n'
                    break
                output += f'- {name}\n'
            return output
        if unexpected_names:
            message += 'Feature names unseen at fit time:\n'
            message += add_names(unexpected_names)
        if missing_names:
            message += 'Feature names seen at fit time, yet now missing:\n'
            message += add_names(missing_names)
        if not missing_names and (not unexpected_names):
            message += 'Feature names must be in the same order as they were in fit.\n'
        raise ValueError(message)

def _check_n_features(estimator, X, reset):
    try:
        n_features = _num_features(X)
    except TypeError as e:
        if not reset and hasattr(estimator, 'n_features_in_'):
            raise ValueError(f'X does not contain any features, but {estimator.__class__.__name__} is expecting {estimator.n_features_in_} features') from e
        return
    if reset:
        estimator.n_features_in_ = n_features
        return
    if not hasattr(estimator, 'n_features_in_'):
        return
    if n_features != estimator.n_features_in_:
        raise ValueError(f'X has {n_features} features, but {estimator.__class__.__name__} is expecting {estimator.n_features_in_} features as input.')

def validate_data(_estimator, /, X='no_validation', y='no_validation', reset=True, validate_separately=False, skip_check_array=False, **check_params):
    _check_feature_names(_estimator, X, reset=reset)
    tags = get_tags(_estimator)
    if y is None and tags.target_tags.required:
        raise ValueError(f'This {_estimator.__class__.__name__} estimator requires y to be passed, but the target y is None.')
    no_val_X = isinstance(X, str) and X == 'no_validation'
    no_val_y = y is None or (isinstance(y, str) and y == 'no_validation')
    if no_val_X and no_val_y:
        raise ValueError('Validation should be done on X, y or both.')
    default_check_params = {'estimator': _estimator}
    check_params = {**default_check_params, **check_params}
    if skip_check_array:
        if not no_val_X and no_val_y:
            out = X
        elif no_val_X and (not no_val_y):
            out = y
        else:
            out = (X, y)
    elif not no_val_X and no_val_y:
        out = check_array(X, input_name='X', **check_params)
    elif no_val_X and (not no_val_y):
        out = _check_y(y, **check_params)
    else:
        if validate_separately:
            check_X_params, check_y_params = validate_separately
            if 'estimator' not in check_X_params:
                check_X_params = {**default_check_params, **check_X_params}
            X = check_array(X, input_name='X', **check_X_params)
            if 'estimator' not in check_y_params:
                check_y_params = {**default_check_params, **check_y_params}
            y = check_array(y, input_name='y', **check_y_params)
        else:
            X, y = check_X_y(X, y, **check_params)
        out = (X, y)
    if not no_val_X and check_params.get('ensure_2d', True):
        _check_n_features(_estimator, X, reset=reset)
    return out

def type_name(t):
    module = t.__module__
    qualname = t.__qualname__
    if module == 'builtins':
        return qualname
    elif t == numbers.Real:
        return 'float'
    elif t == numbers.Integral:
        return 'int'
    return f'{module}.{qualname}'

def yield_namespaces(include_numpy_namespaces=True):
    for array_namespace in ['numpy', 'array_api_strict', 'cupy', 'torch', 'dpnp']:
        if not include_numpy_namespaces and array_namespace in _NUMPY_NAMESPACE_NAMES:
            continue
        yield array_namespace

def yield_namespace_device_dtype_combinations(include_numpy_namespaces=True):
    for array_namespace in yield_namespaces(include_numpy_namespaces=include_numpy_namespaces):
        if array_namespace == 'torch':
            for device_name, dtype in itertools.product(('cpu', 'cuda', 'xpu'), ('float64', 'float32')):
                yield (array_namespace, device_name, dtype)
            yield (array_namespace, 'mps', 'float32')
        elif array_namespace == 'dpnp':
            for device_name, dtype in itertools.product(('cpu', 'gpu'), ('float64', 'float32')):
                yield (array_namespace, device_name, dtype)
        elif array_namespace == 'array_api_strict':
            yield (array_namespace, 'CPU_DEVICE', 'float64')
            yield (array_namespace, 'device1', 'float32')
        else:
            yield (array_namespace, None, None)

def _check_array_api_dispatch(array_api_dispatch):
    if not array_api_dispatch:
        return
    scipy_version = parse_version(scipy.__version__)
    min_scipy_version = '1.14.0'
    if scipy_version < parse_version(min_scipy_version):
        raise ImportError(f'SciPy must be {min_scipy_version} or newer (found {{scipy.__version__}}) to dispatch array using the array API specification')
    if os.environ.get('SCIPY_ARRAY_API') != '1':
        raise RuntimeError("Scikit-learn array API support was enabled but scipy's own support is not enabled. Please set the SCIPY_ARRAY_API=1 environment variable before importing sklearn or scipy. More details at: https://docs.scipy.org/doc/scipy/dev/api-dev/array_api.html")

def _single_array_device(array):
    if not hasattr(array, 'device') or not get_config()['array_api_dispatch']:
        return None
    else:
        return array.device

def device(*array_list, remove_none=True, remove_types=REMOVE_TYPES_DEFAULT):
    array_list = _remove_non_arrays(*array_list, remove_none=remove_none, remove_types=remove_types)
    if not array_list:
        return None
    device_ = _single_array_device(array_list[0])
    for array in array_list[1:]:
        device_other = _single_array_device(array)
        if device_ != device_other:
            raise ValueError(f'Input arrays use different devices: {device_}, {device_other}')
    return device_

def supported_float_dtypes(xp, device=None):
    dtypes_dict = xp.__array_namespace_info__().dtypes(kind='real floating', device=device)
    valid_float_dtypes = []
    for dtype_key in ('float64', 'float32'):
        if dtype_key in dtypes_dict:
            valid_float_dtypes.append(dtypes_dict[dtype_key])
    if hasattr(xp, 'float16'):
        valid_float_dtypes.append(xp.float16)
    return tuple(valid_float_dtypes)

def _remove_non_arrays(*arrays, remove_none=True, remove_types=REMOVE_TYPES_DEFAULT):
    filtered_arrays = []
    remove_types = tuple(remove_types)
    for array in arrays:
        if remove_none and array is None:
            continue
        if isinstance(array, remove_types):
            continue
        if sp.issparse(array):
            continue
        if is_df_or_series(array):
            continue
        filtered_arrays.append(array)
    return filtered_arrays

def get_namespace(*arrays, remove_none=True, remove_types=REMOVE_TYPES_DEFAULT, xp=None):
    array_api_dispatch = get_config()['array_api_dispatch']
    if not array_api_dispatch:
        if xp is not None:
            return (xp, False)
        else:
            return (np_compat, False)
    if xp is not None:
        return (xp, True)
    arrays = _remove_non_arrays(*arrays, remove_none=remove_none, remove_types=remove_types)
    arrays = _unwrap_memoryviewslices(*arrays)
    if not arrays:
        return (np_compat, False)
    _check_array_api_dispatch(array_api_dispatch)
    namespace = array_api_compat.get_namespace(*arrays)
    is_array_api_compliant = True
    if namespace.__name__ == 'array_api_strict' and hasattr(namespace, 'set_array_api_strict_flags'):
        namespace.set_array_api_strict_flags(api_version='2025.12')
    return (namespace, is_array_api_compliant)

def get_namespace_and_device(*array_list, remove_none=True, remove_types=REMOVE_TYPES_DEFAULT, xp=None):
    skip_remove_kwargs = dict(remove_none=False, remove_types=[])
    array_list = _remove_non_arrays(*array_list, remove_none=remove_none, remove_types=remove_types)
    arrays_device = device(*array_list, **skip_remove_kwargs)
    if xp is None:
        xp, is_array_api = get_namespace(*array_list, **skip_remove_kwargs)
    else:
        xp, is_array_api = (xp, True)
    if is_array_api:
        return (xp, is_array_api, arrays_device)
    else:
        return (xp, False, arrays_device)

def move_to(*arrays, xp, device):
    if isinstance(device, str) and device == 'xpu':
        device += ':0'
    sparse_mask = [sp.issparse(array) for array in arrays]
    none_mask = [array is None for array in arrays]
    if any(sparse_mask) and (not _is_numpy_namespace(xp)):
        raise TypeError('Sparse arrays are only accepted (and passed through) when the target namespace is Numpy')
    arrays_ = arrays
    if _max_precision_float_dtype(xp, device) == xp.float32:
        arrays_ = []
        for array in arrays:
            xp_array, _ = get_namespace(array)
            if getattr(array, 'dtype', None) == xp_array.float64:
                arrays_.append(xp_array.astype(array, xp_array.float32))
            else:
                arrays_.append(array)
    converted_arrays = []
    for array, is_sparse, is_none in zip(arrays_, sparse_mask, none_mask):
        if is_none:
            converted_arrays.append(None)
        elif is_sparse:
            converted_arrays.append(array)
        else:
            xp_array, _, device_array = get_namespace_and_device(array)
            if xp == xp_array and device == device_array:
                converted_arrays.append(array)
            else:
                try:
                    array_converted = xp.from_dlpack(array, device=device)
                except (AttributeError, TypeError, NotImplementedError, BufferError, ValueError):
                    if _is_numpy_namespace(xp):
                        array_converted = _convert_to_numpy(array, xp_array)
                    elif _is_numpy_namespace(xp_array):
                        array_converted = xp.asarray(array, device=device)
                    else:
                        array_np = _convert_to_numpy(array, xp_array)
                        array_converted = xp.asarray(array_np, device=device)
                converted_arrays.append(array_converted)
    return converted_arrays[0] if len(converted_arrays) == 1 else tuple(converted_arrays)

def _validate_diagonal_args(array, value, xp):
    if array.ndim != 2:
        raise ValueError(f'`array` should be 2D. Got array with shape {tuple(array.shape)}')
    value = xp.asarray(value, dtype=array.dtype, device=device(array))
    if value.ndim not in [0, 1]:
        raise ValueError(f'`value` needs to be a scalar or a 1D array, got a {value.ndim}D array instead.')
    min_rows_columns = min(array.shape)
    if value.ndim == 1 and value.shape[0] != min_rows_columns:
        raise ValueError(f'`value` needs to be a scalar or 1D array of the same length as the diagonal of `array` ({min_rows_columns}). Got {value.shape[0]}')
    return (value, min_rows_columns)

def _fill_diagonal(array, value, xp):
    value, min_rows_columns = _validate_diagonal_args(array, value, xp)
    if _is_numpy_namespace(xp):
        xp.fill_diagonal(array, value, wrap=False)
    elif value.ndim == 0:
        for i in range(min_rows_columns):
            array[i, i] = value
    else:
        for i in range(min_rows_columns):
            array[i, i] = value[i]

def _add_to_diagonal(array, value, xp):
    value, min_rows_columns = _validate_diagonal_args(array, value, xp)
    if _is_numpy_namespace(xp):
        step = array.shape[1] + 1
        end = array.shape[1] * array.shape[1]
        array.flat[:end:step] += value
        return
    value = xp.linalg.diagonal(array) + value
    for i in range(min_rows_columns):
        array[i, i] = value[i]

def _max_precision_float_dtype(xp, device):
    if _is_numpy_namespace(xp):
        return xp.float64
    floating_dtypes = xp.__array_namespace_info__().dtypes(kind='real floating', device=device)
    if 'float64' in floating_dtypes:
        return xp.float64
    return xp.float32

def _find_matching_floating_dtype(*arrays, xp):
    dtyped_arrays = [xp.asarray(a) for a in arrays if hasattr(a, 'dtype')]
    floating_dtypes = [a.dtype for a in dtyped_arrays if xp.isdtype(a.dtype, 'real floating')]
    if floating_dtypes:
        return xp.result_type(*floating_dtypes)
    return xp.asarray(0.0).dtype

def _average(a, axis=None, weights=None, normalize=True, xp=None):
    xp, _, device_ = get_namespace_and_device(a, weights, xp=xp)
    if _is_numpy_namespace(xp):
        if normalize:
            return xp.asarray(numpy.average(a, axis=axis, weights=weights))
        elif axis is None and weights is not None:
            return xp.asarray(numpy.dot(a, weights))
    a = xp.asarray(a, device=device_)
    if weights is not None:
        weights = xp.asarray(weights, device=device_)
    if weights is not None and a.shape != weights.shape:
        if axis is None:
            raise TypeError(f'Axis must be specified when the shape of a {tuple(a.shape)} and weights {tuple(weights.shape)} differ.')
        if tuple(weights.shape) != (a.shape[axis],):
            raise ValueError(f'Shape of weights weights.shape={tuple(weights.shape)} must be consistent with a.shape={tuple(a.shape)} and axis={axis!r}.')
        shape = [1] * a.ndim
        shape[axis] = a.shape[axis]
        weights = xp.reshape(weights, tuple(shape))
    if xp.isdtype(a.dtype, 'complex floating'):
        raise NotImplementedError('Complex floating point values are not supported by average.')
    if weights is not None and xp.isdtype(weights.dtype, 'complex floating'):
        raise NotImplementedError('Complex floating point values are not supported by average.')
    output_dtype = _find_matching_floating_dtype(a, weights, xp=xp)
    a = xp.astype(a, output_dtype)
    if weights is None:
        return (xp.mean if normalize else xp.sum)(a, axis=axis)
    weights = xp.astype(weights, output_dtype)
    sum_ = xp.sum(xp.multiply(a, weights), axis=axis)
    if not normalize:
        return sum_
    scale = xp.sum(weights, axis=axis)
    if xp.any(scale == 0.0):
        raise ZeroDivisionError("Weights sum to zero, can't be normalized")
    return sum_ / scale

def _asarray_with_order(array, dtype=None, order=None, copy=None, *, xp=None, device=None):
    xp, _ = get_namespace(array, xp=xp)
    if _is_numpy_namespace(xp):
        if copy is True:
            array = numpy.array(array, order=order, dtype=dtype)
        else:
            array = numpy.asarray(array, order=order, dtype=dtype)
        return xp.asarray(array)
    else:
        return xp.asarray(array, dtype=dtype, copy=copy, device=device)

def _ravel(array, xp=None):
    xp, _ = get_namespace(array, xp=xp)
    if _is_numpy_namespace(xp):
        array = numpy.asarray(array)
        return xp.asarray(numpy.ravel(array, order='C'))
    return xp.reshape(array, shape=(-1,))

def _convert_to_numpy(array, xp):
    if _is_xp_namespace(xp, 'torch'):
        return array.cpu().numpy()
    elif _is_xp_namespace(xp, 'cupy'):
        return array.get()
    elif _is_xp_namespace(xp, 'array_api_strict'):
        return numpy.asarray(xp.asarray(array, device=xp.Device('CPU_DEVICE')))
    elif _is_xp_namespace(xp, 'dpnp'):
        return array.asnumpy()
    return numpy.asarray(array)

def _estimator_with_converted_arrays(estimator, converter):
    from sklearn.base import clone
    estimator_type = type(estimator)
    if hasattr(estimator, '__sklearn_array_api_convert__') and (not inspect.isclass(estimator)):
        return estimator.__sklearn_array_api_convert__(converter)
    if estimator_type is dict:
        return {k: _estimator_with_converted_arrays(v, converter) for k, v in estimator.items()}
    if estimator_type in (list, tuple, set, frozenset):
        return estimator_type((_estimator_with_converted_arrays(v, converter) for v in estimator))
    if hasattr(estimator, '__dlpack__') or isinstance(estimator, (numpy.ndarray, numpy.generic)):
        return converter(estimator)
    if not hasattr(estimator, 'get_params') or isinstance(estimator, type):
        return estimator
    new_estimator = clone(estimator)
    for key, attribute in vars(estimator).items():
        attribute = _estimator_with_converted_arrays(attribute, converter)
        setattr(new_estimator, key, attribute)
    return new_estimator

def check_same_namespace(X, estimator, *, attribute, method):
    if not get_config()['array_api_dispatch']:
        return
    attr = getattr(estimator, attribute)
    a_xp, _, a_device = get_namespace_and_device(attr)
    X_xp, _, X_device = get_namespace_and_device(X)
    if X_xp == a_xp and X_device == a_device:
        return
    if _is_numpy_namespace(a_xp) and _is_numpy_namespace(X_xp):
        return
    if X_device is None:
        type_name = 'sparse array' if sp.issparse(X) else 'array-like'
        msg = f'Array namespace used during fit ({a_xp.__name__}) is not compatible with the {type_name} input passed to {method}. Only the NumPy namespace is compatible with {type_name} inputs.'
    elif X_xp != a_xp:
        msg = f'Array namespaces used during fit ({a_xp.__name__}) and {method} ({X_xp.__name__}) differ.'
    else:
        msg = f'Devices used during fit ({a_device}) and {method} ({X_device}) differ.'
    raise ValueError(f"Inputs passed to {estimator.__class__.__name__}.{method}() must use the same namespace and the same device as those passed to fit(). {msg} You can move the estimator to the same namespace and device as X with: 'from sklearn.utils._array_api import get_namespace_and_device, move_estimator_to; xp, _, device = get_namespace_and_device(X); estimator = move_estimator_to(estimator, xp, device)'")

def _atol_for_type(dtype_or_dtype_name):
    if dtype_or_dtype_name is None:
        dtype_or_dtype_name = numpy.float64
    return numpy.finfo(dtype_or_dtype_name).eps * 1000

def _isin(element, test_elements, xp, assume_unique=False, invert=False):
    if _is_numpy_namespace(xp):
        return xp.asarray(numpy.isin(element=element, test_elements=test_elements, assume_unique=assume_unique, invert=invert))
    original_element_shape = element.shape
    element = xp.reshape(element, (-1,))
    test_elements = xp.reshape(test_elements, (-1,))
    return xp.reshape(_in1d(ar1=element, ar2=test_elements, xp=xp, assume_unique=assume_unique, invert=invert), original_element_shape)

def _in1d(ar1, ar2, xp, assume_unique=False, invert=False):
    xp, _ = get_namespace(ar1, ar2, xp=xp)
    if ar2.shape[0] < 10 * ar1.shape[0] ** 0.145:
        if invert:
            mask = xp.ones(ar1.shape[0], dtype=xp.bool, device=device(ar1))
            for a in ar2:
                mask &= ar1 != a
        else:
            mask = xp.zeros(ar1.shape[0], dtype=xp.bool, device=device(ar1))
            for a in ar2:
                mask |= ar1 == a
        return mask
    if not assume_unique:
        ar1, rev_idx = xp.unique_inverse(ar1)
        ar2 = xp.unique_values(ar2)
    ar = xp.concat((ar1, ar2))
    device_ = device(ar)
    order = xp.argsort(ar, stable=True)
    reverse_order = xp.argsort(order, stable=True)
    sar = xp.take(ar, order, axis=0)
    if size(sar) >= 1:
        bool_ar = sar[1:] != sar[:-1] if invert else sar[1:] == sar[:-1]
    else:
        bool_ar = xp.asarray([False]) if invert else xp.asarray([True])
    flag = xp.concat((bool_ar, xp.asarray([invert], device=device_)))
    ret = xp.take(flag, reverse_order, axis=0)
    if assume_unique:
        return ret[:ar1.shape[0]]
    else:
        return xp.take(ret, rev_idx, axis=0)

def _count_nonzero(X, axis=None, sample_weight=None, xp=None, device=None):
    from sklearn.utils.sparsefuncs import count_nonzero
    xp, _ = get_namespace(X, sample_weight, xp=xp)
    if _is_numpy_namespace(xp) and sp.issparse(X):
        return count_nonzero(X, axis=axis, sample_weight=sample_weight)
    assert X.ndim == 2
    weights = xp.ones_like(X, device=device)
    if sample_weight is not None:
        sample_weight = xp.asarray(sample_weight, device=device)
        sample_weight = xp.reshape(sample_weight, (sample_weight.shape[0], 1))
        weights = xp.astype(weights, sample_weight.dtype) * sample_weight
    zero_scalar = xp.asarray(0, device=device, dtype=weights.dtype)
    return xp.sum(xp.where(X != 0, weights, zero_scalar), axis=axis)

def _set_deprecated(self, value, *, new_key, deprecated_key, warning_message):
    self.__dict__['_deprecated_key_to_warnings'][deprecated_key] = warning_message
    self[new_key] = self[deprecated_key] = value

def chunk_generator(gen, chunksize):
    while True:
        chunk = list(islice(gen, chunksize))
        if chunk:
            yield chunk
        else:
            return

@validate_params({'n': [Interval(Integral, 1, None, closed='left')], 'batch_size': [Interval(Integral, 1, None, closed='left')], 'min_batch_size': [Interval(Integral, 0, None, closed='left')]}, prefer_skip_nested_validation=True)
def gen_batches(n, batch_size, *, min_batch_size=0):
    start = 0
    for _ in range(int(n // batch_size)):
        end = start + batch_size
        if end + min_batch_size > n:
            continue
        yield slice(start, end)
        start = end
    if start < n:
        yield slice(start, n)

@validate_params({'n': [Interval(Integral, 1, None, closed='left')], 'n_packs': [Interval(Integral, 1, None, closed='left')], 'n_samples': [Interval(Integral, 1, None, closed='left'), None]}, prefer_skip_nested_validation=True)
def gen_even_slices(n, n_packs, *, n_samples=None):
    start = 0
    for pack_num in range(n_packs):
        this_n = n // n_packs
        if pack_num < n % n_packs:
            this_n += 1
        if this_n > 0:
            end = start + this_n
            if n_samples is not None:
                end = min(n_samples, end)
            yield slice(start, end, None)
            start = end

def get_chunk_n_rows(row_bytes, *, max_n_rows=None, working_memory=None):
    if working_memory is None:
        working_memory = get_config()['working_memory']
    chunk_n_rows = int(working_memory * 2 ** 20 // row_bytes)
    if max_n_rows is not None:
        chunk_n_rows = min(chunk_n_rows, max_n_rows)
    if chunk_n_rows < 1:
        warnings.warn('Could not adhere to working_memory config. Currently %.0fMiB, %.0fMiB required.' % (working_memory, np.ceil(row_bytes * 2 ** (-20))))
        chunk_n_rows = 1
    return chunk_n_rows

def is_pandas_df_or_series(X):
    try:
        pd = sys.modules['pandas']
    except KeyError:
        return False
    return isinstance(X, (pd.DataFrame, pd.Series))

def is_pyarrow_data(X):
    try:
        pa = sys.modules['pyarrow']
    except KeyError:
        return False
    return isinstance(X, (pa.Table, pa.RecordBatch, pa.Array, pa.ChunkedArray))

def is_polars_df_or_series(X):
    try:
        pl = sys.modules['polars']
    except KeyError:
        return False
    return isinstance(X, (pl.DataFrame, pl.Series))

def is_polars_df(X):
    try:
        pl = sys.modules['polars']
    except KeyError:
        return False
    return isinstance(X, pl.DataFrame)

def _unique(values, *, return_inverse=False, return_counts=False):
    if values.dtype == object:
        return _unique_python(values, return_inverse=return_inverse, return_counts=return_counts)
    return _unique_np(values, return_inverse=return_inverse, return_counts=return_counts)

def _unique_np(values, return_inverse=False, return_counts=False):
    xp, _ = get_namespace(values)
    inverse, counts = (None, None)
    if return_inverse and return_counts:
        uniques, _, inverse, counts = xp.unique_all(values)
    elif return_inverse:
        uniques, inverse = xp.unique_inverse(values)
    elif return_counts:
        uniques, counts = xp.unique_counts(values)
    else:
        uniques = xp.unique_values(values)
    if uniques.size and is_scalar_nan(uniques[-1]):
        nan_idx = xp.searchsorted(uniques, xp.nan)
        uniques = uniques[:nan_idx + 1]
        if return_inverse:
            inverse[inverse > nan_idx] = nan_idx
        if return_counts:
            counts[nan_idx] = xp.sum(counts[nan_idx:])
            counts = counts[:nan_idx + 1]
    ret = (uniques,)
    if return_inverse:
        ret += (inverse,)
    if return_counts:
        ret += (counts,)
    return ret[0] if len(ret) == 1 else ret

def _extract_missing(values):
    missing_values_set = {value for value in values if value is None or is_scalar_nan(value)}
    if not missing_values_set:
        return (values, MissingValues(nan=False, none=False))
    all_nans = missing_values_set - {None}
    if None in missing_values_set:
        if len(missing_values_set) == 1:
            output_missing_values = MissingValues(nan=False, none=True, all_nans=all_nans)
        else:
            output_missing_values = MissingValues(nan=True, none=True, all_nans=all_nans)
    else:
        output_missing_values = MissingValues(nan=True, none=False, all_nans=all_nans)
    output = values - missing_values_set
    return (output, output_missing_values)

def _map_to_integer(values, uniques):
    xp, _ = get_namespace(values, uniques)
    table = _nandict({val: i for i, val in enumerate(uniques)})
    return xp.asarray([table[v] for v in values], device=device(values))

def _encode(values, *, uniques, check_unknown=True):
    xp, _ = get_namespace(values, uniques)
    if not xp.isdtype(values.dtype, 'numeric'):
        try:
            return _map_to_integer(values, uniques)
        except KeyError as e:
            raise ValueError(f'y contains previously unseen labels: {e}')
    else:
        if check_unknown:
            diff = _check_unknown(values, uniques)
            if diff:
                raise ValueError(f'y contains previously unseen labels: {diff}')
        return xp.searchsorted(uniques, values)

def _check_unknown(values, known_values, return_mask=False):
    xp, _ = get_namespace(values, known_values)
    valid_mask = None
    if not xp.isdtype(values.dtype, 'numeric'):
        values_set = set(values)
        values_set, missing_in_values = _extract_missing(values_set)
        uniques_set = set(known_values)
        uniques_set, missing_in_uniques = _extract_missing(uniques_set)
        diff = values_set - uniques_set
        nan_in_diff = missing_in_values.nan and (not missing_in_uniques.nan)
        none_in_diff = missing_in_values.none and (not missing_in_uniques.none)

        def is_valid(value):
            return value in uniques_set or (missing_in_uniques.none and value is None) or (missing_in_uniques.nan and is_scalar_nan(value))
        if return_mask:
            if diff or nan_in_diff or none_in_diff:
                valid_mask = xp.array([is_valid(value) for value in values])
            else:
                valid_mask = xp.ones(len(values), dtype=xp.bool)
        diff = list(diff)
        if none_in_diff:
            diff.append(None)
        if nan_in_diff:
            diff.append(np.nan)
    else:
        unique_values = xp.unique_values(values)
        diff = xpx.setdiff1d(unique_values, known_values, assume_unique=True, xp=xp)
        if return_mask:
            if diff.size:
                valid_mask = _isin(values, known_values, xp)
            else:
                valid_mask = xp.ones(len(values), dtype=xp.bool)
        if xp.any(xp.isnan(known_values)):
            diff_is_nan = xp.isnan(diff)
            if xp.any(diff_is_nan):
                if diff.size and return_mask:
                    is_nan = xp.isnan(values)
                    valid_mask[is_nan] = 1
                diff = diff[~diff_is_nan]
        diff = list(diff)
    if return_mask:
        return (diff, valid_mask)
    return diff

def to_list(self):
    output = []
    if self.none:
        output.append(None)
    if self.nan:
        output.append(np.nan)
    return output

def _array_indexing(array, key, key_dtype, axis):
    xp, is_array_api, device_ = get_namespace_and_device(array)
    if is_array_api:
        if hasattr(key, 'shape'):
            key = move_to(key, xp=xp, device=device_)
        elif isinstance(key, (int, slice)):
            pass
        else:
            key = xp.asarray(key, device=device_)
        if hasattr(key, 'dtype'):
            if xp.isdtype(key.dtype, 'integral'):
                return xp.take(array, key, axis=axis)
            elif xp.isdtype(key.dtype, 'bool'):
                indices = xp.arange(array.shape[axis], device=device_)
                return xp.take(array, indices[key], axis=axis)
    if issparse(array):
        if key_dtype == 'bool':
            key = np.asarray(key)
        elif SCIPY_VERSION_BELOW_1_12:
            if isinstance(key, numbers.Integral):
                key = [key]
    if isinstance(key, tuple):
        key = list(key)
    return array[key, ...] if axis == 0 else array[:, key]

def _narwhals_indexing(X, key, key_dtype, axis):
    X = nw.from_native(X, allow_series=True)
    if not (isinstance(key, (list, slice)) or key is None):
        key = np.asarray(key).tolist()
    if axis == 1:
        if key_dtype == 'bool':
            subset = X.select((col for col, select in zip(X.columns, key) if select))
            return subset.to_native()
        return X[:, key].to_native()
    if key_dtype == 'bool':
        X_indexed = X.filter(key)
    else:
        X_indexed = X[key]
    if np.isscalar(key):
        if len(X.shape) <= 1:
            return X_indexed
        return np.array([col.item(0) for col in X_indexed.iter_columns()])
    return X_indexed.to_native()

def _pandas_indexing(X, key, key_dtype, axis):
    if _is_arraylike_not_scalar(key):
        key = np.asarray(key)
    if key_dtype == 'int' and (not (isinstance(key, slice) or np.isscalar(key))):
        return X.take(key, axis=axis)
    else:
        indexer = X.iloc if key_dtype == 'int' else X.loc
        return indexer[:, key] if axis else indexer[key]

def _list_indexing(X, key, key_dtype):
    if np.isscalar(key) or isinstance(key, slice):
        return X[key]
    if key_dtype == 'bool':
        return list(compress(X, key))
    return [X[idx] for idx in key]

def _determine_key_type(key, accept_slice=True):
    err_msg = 'No valid specification of the columns. Only a scalar, list or slice of all integers or all strings, or boolean mask is allowed'
    dtype_to_str = {int: 'int', str: 'str', bool: 'bool', np.bool_: 'bool'}
    array_dtype_to_str = {'i': 'int', 'u': 'int', 'b': 'bool', 'O': 'str', 'U': 'str', 'S': 'str'}
    if key is None:
        return None
    if isinstance(key, tuple(dtype_to_str.keys())):
        try:
            return dtype_to_str[type(key)]
        except KeyError:
            raise ValueError(err_msg)
    if isinstance(key, slice):
        if not accept_slice:
            raise TypeError('Only array-like or scalar are supported. A Python slice was given.')
        if key.start is None and key.stop is None:
            return None
        key_start_type = _determine_key_type(key.start)
        key_stop_type = _determine_key_type(key.stop)
        if key_start_type is not None and key_stop_type is not None:
            if key_start_type != key_stop_type:
                raise ValueError(err_msg)
        if key_start_type is not None:
            return key_start_type
        return key_stop_type
    if isinstance(key, (list, tuple)):
        unique_key = set(key)
        key_type = {_determine_key_type(elt) for elt in unique_key}
        if not key_type:
            return None
        if len(key_type) != 1:
            raise ValueError(err_msg)
        return key_type.pop()
    if hasattr(key, 'dtype'):
        xp, is_array_api = get_namespace(key)
        if is_array_api and (not _is_numpy_namespace(xp)):
            if xp.isdtype(key.dtype, 'bool'):
                return 'bool'
            elif xp.isdtype(key.dtype, 'integral'):
                return 'int'
            else:
                raise ValueError(err_msg)
        else:
            try:
                return array_dtype_to_str[key.dtype.kind]
            except KeyError:
                raise ValueError(err_msg)
    raise ValueError(err_msg)

def _safe_indexing(X, indices, *, axis=0):
    if indices is None:
        return X
    if axis not in (0, 1):
        raise ValueError("'axis' should be either 0 (to index rows) or 1 (to index  column). Got {} instead.".format(axis))
    indices_dtype = _determine_key_type(indices)
    if axis == 0 and indices_dtype == 'str':
        raise ValueError(f"String indexing (indices={indices}) is not supported with 'axis=0'. Did you mean to use axis=1 for column selection?")
    if axis == 1 and isinstance(X, list):
        raise ValueError('axis=1 is not supported for lists')
    if axis == 1 and (ndim := len(getattr(X, 'shape', [0]))) != 2:
        raise ValueError(f"'X' should be a 2D NumPy array, 2D sparse matrix or dataframe when indexing the columns (i.e. 'axis=1'). Got {type(X)} instead with {ndim} dimension(s).")
    if axis == 1 and indices_dtype == 'str' and (not (nw.dependencies.is_into_dataframe(X) or nw.dependencies.is_into_series(X))):
        raise ValueError('Specifying the columns using strings is only supported for dataframes.')
    if hasattr(X, 'iloc'):
        return _pandas_indexing(X, indices, indices_dtype, axis=axis)
    elif nw.dependencies.is_into_dataframe(X) or nw.dependencies.is_into_series(X):
        return _narwhals_indexing(X, indices, indices_dtype, axis=axis)
    elif is_pyarrow_data(X):
        pa = sys.modules['pyarrow']
        X = pa.chunked_array(X)
        ret = _narwhals_indexing(X, indices, indices_dtype, axis=axis)
        if isinstance(ret, pa.ChunkedArray):
            return ret.combine_chunks()
        return ret
    if hasattr(X, 'shape'):
        return _array_indexing(X, indices, indices_dtype, axis=axis)
    else:
        return _list_indexing(X, indices, indices_dtype)

def _safe_assign(X, values, *, row_indexer=None, column_indexer=None):
    row_indexer = slice(None, None, None) if row_indexer is None else row_indexer
    column_indexer = slice(None, None, None) if column_indexer is None else column_indexer
    if hasattr(X, 'iloc'):
        with warnings.catch_warnings():
            warnings.simplefilter('ignore', FutureWarning)
            X.iloc[row_indexer, column_indexer] = values
    else:
        X[row_indexer, column_indexer] = values

def _get_column_indices(X, key):
    key_dtype = _determine_key_type(key)
    if nw.dependencies.is_into_dataframe(X):
        df_nw = nw.from_native(X)
        n_columns = df_nw.shape[1]
        column_names = df_nw.columns
    else:
        n_columns = X.shape[1]
        column_names = None
    if isinstance(key, (list, tuple)) and (not key):
        return []
    elif key_dtype in ('bool', 'int'):
        return _get_column_indices_for_bool_or_int(key, n_columns)
    else:
        if column_names is None:
            raise ValueError('Specifying the columns using strings is only supported for dataframes.')
        if isinstance(key, slice):
            if key.step not in [1, None]:
                raise NotImplementedError('key.step must be 1 or None')
            start, stop = (key.start, key.stop)
            if start is not None:
                start = column_names.index(start)
            if stop is not None:
                stop = column_names.index(stop) + 1
            else:
                stop = n_columns + 1
            return list(islice(range(n_columns), start, stop))
        else:
            selected_columns = [key] if np.isscalar(key) else key
            try:
                return [column_names.index(col) for col in selected_columns]
            except ValueError as e:
                missing = {*selected_columns} - {*column_names}
                msg = f'Some column names are not columns of the dataframe: {missing}'
                raise ValueError(msg) from e

@validate_params({'replace': ['boolean'], 'n_samples': [Interval(numbers.Integral, 1, None, closed='left'), None], 'random_state': ['random_state'], 'stratify': ['array-like', 'sparse matrix', None], 'sample_weight': ['array-like', None]}, prefer_skip_nested_validation=True)
def resample(*arrays, replace=True, n_samples=None, random_state=None, stratify=None, sample_weight=None):
    max_n_samples = n_samples
    random_state = check_random_state(random_state)
    if len(arrays) == 0:
        return None
    first = arrays[0]
    n_samples = first.shape[0] if hasattr(first, 'shape') else len(first)
    if max_n_samples is None:
        max_n_samples = n_samples
    elif max_n_samples > n_samples and (not replace):
        raise ValueError('Cannot sample %d out of arrays with dim %d when replace is False' % (max_n_samples, n_samples))
    check_consistent_length(*arrays)
    if sample_weight is not None and (not replace):
        raise NotImplementedError('Resampling with sample_weight is only implemented for replace=True.')
    if sample_weight is not None and stratify is not None:
        raise NotImplementedError('Resampling with sample_weight is only implemented for stratify=None.')
    if stratify is None:
        if replace:
            if sample_weight is not None:
                sample_weight = _check_sample_weight(sample_weight, first, dtype=np.float64)
                p = sample_weight / sample_weight.sum()
            else:
                p = None
            indices = random_state.choice(n_samples, size=max_n_samples, p=p, replace=True)
        else:
            indices = np.arange(n_samples)
            random_state.shuffle(indices)
            indices = indices[:max_n_samples]
    else:
        y = check_array(stratify, ensure_2d=False, dtype=None)
        if y.ndim == 2:
            y = np.array([' '.join(row.astype('str')) for row in y])
        classes, y_indices = np.unique(y, return_inverse=True)
        n_classes = classes.shape[0]
        class_counts = np.bincount(y_indices)
        class_indices = np.split(np.argsort(y_indices, kind='mergesort'), np.cumsum(class_counts)[:-1])
        n_i = _approximate_mode(class_counts, max_n_samples, random_state)
        indices = []
        for i in range(n_classes):
            indices_i = random_state.choice(class_indices[i], n_i[i], replace=replace)
            indices.extend(indices_i)
        indices = random_state.permutation(indices)
    arrays = [a.tocsr() if issparse(a) else a for a in arrays]
    resampled_arrays = [_safe_indexing(a, indices) for a in arrays]
    if len(resampled_arrays) == 1:
        return resampled_arrays[0]
    else:
        return resampled_arrays

def _get_mask(X, value_to_mask):
    if not sp.issparse(X):
        return _get_dense_mask(X, value_to_mask)
    Xt = _get_dense_mask(X.data, value_to_mask)
    sparse_constructor = sp.csr_array if X.format == 'csr' else sp.csc_array
    Xt_sparse = sparse_constructor((Xt, X.indices.copy(), X.indptr.copy()), shape=X.shape, dtype=bool)
    return _align_api_if_sparse(Xt_sparse)

@validate_params({'X': ['array-like', 'sparse matrix'], 'mask': ['array-like']}, prefer_skip_nested_validation=True)
def safe_mask(X, mask):
    mask = np.asarray(mask)
    if np.issubdtype(mask.dtype, np.signedinteger):
        return mask
    if hasattr(X, 'toarray'):
        ind = np.arange(mask.shape[0])
        mask = ind[mask]
    return mask

def axis0_safe_slice(X, mask, len_mask):
    if len_mask != 0:
        return X[safe_mask(X, mask), :]
    return np.zeros(shape=(0, X.shape[1]))

def indices_to_mask(indices, mask_length):
    if mask_length <= np.max(indices):
        raise ValueError('mask_length must be greater than max(indices)')
    mask = np.zeros(mask_length, dtype=bool)
    mask[indices] = True
    return mask

def _routing_repr(obj):
    try:
        return obj._routing_repr()
    except AttributeError:
        return obj if isinstance(obj, str) else type(obj).__name__

def _raise_for_params(params, owner, method, allow=None):
    caller = f'{_routing_repr(owner)}.{method}' if method else _routing_repr(owner)
    allow = allow if allow is not None else {}
    if not _routing_enabled() and params.keys() - allow:
        raise ValueError(f'Passing extra keyword arguments to {caller} is only supported if enable_metadata_routing=True, which you can set using `sklearn.set_config`. See the User Guide <https://scikit-learn.org/stable/metadata_routing.html> for more details. Extra parameters passed are: {set(params)}')

def _raise_for_unsupported_routing(obj, method, **kwargs):
    kwargs = {key: value for key, value in kwargs.items() if value is not None}
    if _routing_enabled() and kwargs:
        cls_name = _routing_repr(obj)
        raise NotImplementedError(f'{cls_name}.{method} cannot accept given metadata ({set(kwargs.keys())}) since metadata routing is not yet implemented for {cls_name}.')

def request_is_alias(item):
    if item in VALID_REQUEST_VALUES:
        return False
    return isinstance(item, str) and item.isidentifier()

def get_routing_for_object(obj=None):
    if hasattr(obj, 'get_metadata_routing'):
        return obj.get_metadata_routing().__sklearn_clone__()
    elif getattr(obj, '_type', None) in ['metadata_request', 'metadata_router']:
        return obj.__sklearn_clone__()
    return MetadataRequest(owner=None)

def process_routing(_obj, _method, /, **kwargs):
    if not kwargs:

        class EmptyRequest:

            def get(self, name, default=None):
                return Bunch(**{method: dict() for method in METHODS})

            def __getitem__(self, name):
                return Bunch(**{method: dict() for method in METHODS})

            def __getattr__(self, name):
                return Bunch(**{method: dict() for method in METHODS})
        return EmptyRequest()
    if not (hasattr(_obj, 'get_metadata_routing') or isinstance(_obj, MetadataRouter)):
        raise AttributeError(f'The given object ({_routing_repr(_obj)}) needs to either implement the routing method `get_metadata_routing` or be a `MetadataRouter` instance.')
    if _method not in METHODS:
        raise TypeError(f'Can only route and process input on these methods: {METHODS}, while the passed method is: {_method}.')
    request_routing = get_routing_for_object(_obj)
    request_routing.validate_metadata(params=kwargs, method=_method)
    routed_params = request_routing.route_params(params=kwargs, caller=_method)
    return routed_params

@property
def requests(self):
    return self._requests

def add_request(self, *, param, alias):
    if not request_is_alias(alias) and (not request_is_valid(alias)):
        raise ValueError(f"The alias you're setting for `{param}` should be either a valid identifier or one of {{None, True, False}}, but given value is: `{alias}`")
    if alias == param:
        alias = True
    if alias == UNUSED:
        if param in self._requests:
            del self._requests[param]
        else:
            raise ValueError(f"Trying to remove parameter {param} with UNUSED which doesn't exist.")
    else:
        self._requests[param] = alias
    return self

def _check_warnings(self, *, params):
    params = {} if params is None else params
    warn_params = {prop for prop, alias in self._requests.items() if alias == WARN and prop in params}
    for param in warn_params:
        warn(f'Support for {param} has recently been added to {self.owner} class. To maintain backward compatibility, it is ignored now. Using `set_{self.method}_request({param}={{True, False}})` on this method of the class, you can set the request value to False to silence this warning, or to True to consume and use the metadata.')

def _route_params(self, params, parent, caller):
    self._check_warnings(params=params)
    unrequested = dict()
    args = {arg: value for arg, value in params.items() if value is not None}
    res = Bunch()
    for prop, alias in self._requests.items():
        if alias is False or alias == WARN:
            continue
        elif alias is True and prop in args:
            res[prop] = args[prop]
        elif alias is None and prop in args:
            unrequested[prop] = args[prop]
        elif alias in args:
            res[prop] = args[alias]
    if unrequested:
        if self.method in COMPOSITE_METHODS:
            callee_methods = COMPOSITE_METHODS[self.method]
        else:
            callee_methods = [self.method]
        set_requests_on = ''.join([f'.set_{method}_request({{metadata}}=True/False)' for method in callee_methods])
        message = f"[{', '.join([key for key in unrequested])}] are passed but are not explicitly set as requested or not requested for {_routing_repr(self.owner)}.{self.method}, which is used within {_routing_repr(parent)}.{caller}. Call `{_routing_repr(self.owner)}" + set_requests_on + '` for each metadata you want to request/ignore. See the Metadata Routing User guide <https://scikit-learn.org/stable/metadata_routing.html> for more information.'
        raise UnsetMetadataPassedError(message=message, unrequested_params=unrequested, routed_params=res)
    return res

def _consumes(self, params):
    params = set(params)
    consumed_params = set()
    for metadata_name, alias in self._requests.items():
        if alias is True and metadata_name in params:
            consumed_params.add(metadata_name)
        elif isinstance(alias, str) and alias in params:
            consumed_params.add(alias)
    return consumed_params

def _serialize(self):
    output = dict()
    for method in SIMPLE_METHODS:
        mmr = getattr(self, method)
        if len(mmr.requests):
            output[method] = mmr._serialize()
    return output

def add(self, *, caller, callee):
    if caller not in METHODS:
        raise ValueError(f'Given caller:{caller} is not a valid method. Valid methods are: {METHODS}')
    if callee not in METHODS:
        raise ValueError(f'Given callee:{callee} is not a valid method. Valid methods are: {METHODS}')
    self._routes.append(MethodPair(caller=caller, callee=callee))
    return self

def _serialize(self):
    result = list()
    for route in self._routes:
        result.append({'caller': route.caller, 'callee': route.callee})
    return result

def add_self_request(self, obj):
    if getattr(obj, '_type', None) == 'metadata_request':
        self._self_request = obj.__sklearn_clone__()
    elif hasattr(obj, '_get_metadata_request'):
        self._self_request = obj._get_metadata_request().__sklearn_clone__()
    else:
        raise ValueError('Given `obj` is neither a `MetadataRequest` nor does it implement the required API. Inheriting from `BaseEstimator` implements the required API.')
    return self

def add(self, *, method_mapping, **objs):
    method_mapping = deepcopy(method_mapping)
    for name, obj in objs.items():
        self._route_mappings[name] = RouterMappingPair(mapping=method_mapping, router=get_routing_for_object(obj))
    return self

def consumes(self, method, params):
    consumed_params = set()
    if self._self_request:
        consumed_params.update(self._self_request.consumes(method=method, params=params))
    for _, route_mapping in self._route_mappings.items():
        for caller, callee in route_mapping.mapping:
            if caller == method:
                consumed_params.update(route_mapping.router.consumes(method=callee, params=params))
    return consumed_params

def _get_param_names(self, *, method, return_alias, ignore_self_request):
    res = set()
    if self._self_request and (not ignore_self_request):
        res = res.union(self._self_request._get_param_names(method=method, return_alias=return_alias))
    for name, route_mapping in self._route_mappings.items():
        for caller, callee in route_mapping.mapping:
            if caller == method:
                res = res.union(route_mapping.router._get_param_names(method=callee, return_alias=True, ignore_self_request=False))
    return res

def _route_params(self, *, params, method, parent, caller):
    res = Bunch()
    if self._self_request:
        res.update(self._self_request._route_params(params=params, method=method, parent=parent, caller=caller))
    param_names = self._get_param_names(method=method, return_alias=True, ignore_self_request=True)
    child_params = {key: value for key, value in params.items() if key in param_names}
    for key in set(res.keys()).intersection(child_params.keys()):
        if child_params[key] is not res[key]:
            raise ValueError(f"In {_routing_repr(self.owner)}, there is a conflict on {key} between what is requested for this estimator and what is requested by its children. You can resolve this conflict by using an alias for the child estimators' requested metadata.")
    res.update(child_params)
    return res

def route_params(self, *, caller, params):
    if self._self_request:
        self._self_request._check_warnings(params=params, method=caller)
    res = Bunch()
    for name, route_mapping in self._route_mappings.items():
        router, mapping = (route_mapping.router, route_mapping.mapping)
        res[name] = Bunch()
        for _caller, _callee in mapping:
            if _caller == caller:
                res[name][_callee] = router._route_params(params=params, method=_callee, parent=self.owner, caller=caller)
    return res

def validate_metadata(self, *, method, params):
    param_names = self._get_param_names(method=method, return_alias=False, ignore_self_request=False)
    if self._self_request:
        self_params = self._self_request._get_param_names(method=method, return_alias=False)
    else:
        self_params = set()
    extra_keys = set(params.keys()) - param_names - self_params
    if extra_keys:
        raise TypeError(f'{_routing_repr(self.owner)}.{method} got unexpected argument(s) {extra_keys}, which are not routed to any object.')

def _serialize(self):
    res = dict()
    if self._self_request:
        res['$self_request'] = self._self_request._serialize()
    for name, route_mapping in self._route_mappings.items():
        res[name] = dict()
        res[name]['mapping'] = route_mapping.mapping._serialize()
        res[name]['router'] = route_mapping.router._serialize()
    return res

def __init_subclass__(cls, **kwargs):

    def is_RequestMethod(obj, name: str):
        """Check if obj.name is a RequestMethod"""
        value = inspect.getattr_static(obj, name)
        return isinstance(value, RequestMethod)

    def _has_explicit_set_method_request(cls, name):
        return hasattr(cls, name) and (not is_RequestMethod(cls, name))

    def _needs_generated_set_request(cls, name, requests):
        if requests:
            return True
        return hasattr(cls, name) and is_RequestMethod(cls, name)
    try:
        for method in SIMPLE_METHODS:
            set_method_name = f'set_{method}_request'
            requests = cls._get_class_level_metadata_request_values(method)
            if _has_explicit_set_method_request(cls, set_method_name):
                continue
            if _needs_generated_set_request(cls, set_method_name, requests):
                setattr(cls, set_method_name, RequestMethod(method, sorted(requests)))
    except Exception:
        pass
    super().__init_subclass__(**kwargs)

@classmethod
def _get_class_level_metadata_request_values(cls, method_name: str, method: Callable | None=None, ignore_params: Iterable[str] | None=None):
    if method is None and (not hasattr(cls, method_name) or not inspect.isfunction(getattr(cls, method_name))):
        return dict()
    resolved_method: Callable = method if method is not None else getattr(cls, method_name)
    signature_items = list(inspect.signature(resolved_method).parameters.items())[1:]
    ignore_params = set() if ignore_params is None else set(ignore_params)
    ignore_params.update({'X', 'y', 'Y', 'Xt', 'yt'})
    params = defaultdict(str, {param_name: None for param_name, param_info in signature_items if param_name not in ignore_params and param_info.kind not in {param_info.VAR_POSITIONAL, param_info.VAR_KEYWORD}})
    substr = f'__metadata_request__{method_name}'
    for base_class in reversed(inspect.getmro(cls)):
        base_class_items = vars(base_class).copy().items()
        for attr, value in base_class_items:
            if substr not in attr:
                continue
            for prop, alias in value.items():
                if prop not in params and alias == UNUSED:
                    raise ValueError(f"Trying to remove parameter {prop} with UNUSED which doesn't exist.")
                params[prop] = alias
    return {param: alias for param, alias in params.items() if alias is not UNUSED}

def _get_metadata_request(self):
    if hasattr(self, '_metadata_request'):
        requests = get_routing_for_object(self._metadata_request)
    else:
        requests = MetadataRequest(owner=self)
        for method_name in SIMPLE_METHODS:
            setattr(requests, method_name, MethodMetadataRequest(owner=self, method=method_name, requests=self._get_class_level_metadata_request_values(method_name)))
    return requests

def func(*args, **kw):
    if not _routing_enabled():
        raise RuntimeError('This method is only available when metadata routing is enabled. You can enable it using sklearn.set_config(enable_metadata_routing=True).')
    if self.validate_keys and set(kw) - set(self.keys):
        raise TypeError(f'Unexpected args: {set(kw) - set(self.keys)} in {self.name}. Accepted arguments are: {set(self.keys)}')
    if instance is None:
        _instance = args[0]
        args = args[1:]
    else:
        _instance = instance
    if args:
        raise TypeError(f'set_{self.name}_request() takes 0 positional argument but {len(args)} were given')
    requests = _instance._get_metadata_request()
    method_metadata_request = getattr(requests, self.name)
    for prop, alias in kw.items():
        if alias is not UNCHANGED:
            method_metadata_request.add_request(param=prop, alias=alias)
    _instance._metadata_request = requests
    return _instance

def is_RequestMethod(obj, name: str):
    value = inspect.getattr_static(obj, name)
    return isinstance(value, RequestMethod)

def _check_X_y(self, X, y=None, should_be_fitted=True):
    if should_be_fitted:
        check_is_fitted(self)
    if self.check_X is not None:
        params = {} if self.check_X_params is None else self.check_X_params
        checked_X = self.check_X(X, **params)
        if isinstance(checked_X, (bool, np.bool_)):
            assert checked_X
        else:
            X = checked_X
    if y is not None and self.check_y is not None:
        params = {} if self.check_y_params is None else self.check_y_params
        checked_y = self.check_y(y, **params)
        if isinstance(checked_y, (bool, np.bool_)):
            assert checked_y
        else:
            y = checked_y
    return (X, y)

def fit(self, X, y, sample_weight=None, **fit_params):
    assert _num_samples(X) == _num_samples(y)
    if self.methods_to_check == 'all' or 'fit' in self.methods_to_check:
        X, y = self._check_X_y(X, y, should_be_fitted=False)
    self.n_features_in_ = np.shape(X)[1]
    self.classes_ = np.unique(check_array(y, ensure_2d=False, allow_nd=True))
    if self.expected_fit_params:
        missing = set(self.expected_fit_params) - set(fit_params)
        if missing:
            raise AssertionError(f'Expected fit parameter(s) {list(missing)} not seen.')
        for key, value in fit_params.items():
            if _num_samples(value) != _num_samples(X):
                raise AssertionError(f'Fit parameter {key} has length {_num_samples(value)}; expected {_num_samples(X)}.')
    if self.expected_sample_weight:
        if sample_weight is None:
            raise AssertionError('Expected sample_weight to be passed')
        _check_sample_weight(sample_weight, X)
    return self

def predict(self, X):
    if self.methods_to_check == 'all' or 'predict' in self.methods_to_check:
        X, y = self._check_X_y(X)
    rng = check_random_state(self.random_state)
    return rng.choice(self.classes_, size=_num_samples(X))

def decision_function(self, X):
    if self.methods_to_check == 'all' or 'decision_function' in self.methods_to_check:
        X, y = self._check_X_y(X)
    rng = check_random_state(self.random_state)
    if len(self.classes_) == 2:
        return rng.randn(_num_samples(X))
    else:
        return rng.randn(_num_samples(X), len(self.classes_))

def score(self, X=None, Y=None):
    if self.methods_to_check == 'all' or 'score' in self.methods_to_check:
        self._check_X_y(X, Y)
    if self.foo_param > 1:
        score = 1.0
    else:
        score = 0.0
    return score

