def validate_parameter_constraints(parameter_constraints, params, caller_name):
    for param_name, param_val in params.items():
        if param_name not in parameter_constraints:
            continue
        constraints = parameter_constraints[param_name]
        if constraints == 'no_validation':
            continue
        constraints = [make_constraint(constraint) for constraint in constraints]
        for constraint in constraints:
            if constraint.is_satisfied_by(param_val):
                break
        else:
            constraints = [constraint for constraint in constraints if not constraint.hidden]
            if len(constraints) == 1:
                constraints_str = f'{constraints[0]}'
            else:
                constraints_str = f"{', '.join([str(c) for c in constraints[:-1]])} or {constraints[-1]}"
            raise InvalidParameterError(f'The {param_name!r} parameter of {caller_name} must be {constraints_str}. Got {param_val!r} instead.')

def make_constraint(constraint):
    if isinstance(constraint, str) and constraint == 'array-like':
        return _ArrayLikes()
    if isinstance(constraint, str) and constraint == 'sparse matrix':
        return _SparseMatrices()
    if isinstance(constraint, str) and constraint == 'random_state':
        return _RandomStates()
    if constraint is callable:
        return _Callables()
    if constraint is None:
        return _NoneConstraint()
    if isinstance(constraint, type):
        return _InstancesOf(constraint)
    if isinstance(constraint, (Interval, StrOptions, Options, HasMethods, MissingValues)):
        return constraint
    if isinstance(constraint, str) and constraint == 'boolean':
        return _Booleans()
    if isinstance(constraint, str) and constraint == 'verbose':
        return _VerboseHelper()
    if isinstance(constraint, str) and constraint == 'cv_object':
        return _CVObjects()
    if isinstance(constraint, Hidden):
        constraint = make_constraint(constraint.constraint)
        constraint.hidden = True
        return constraint
    if isinstance(constraint, str) and constraint == 'nan' or (isinstance(constraint, float) and np.isnan(constraint)):
        return _NanConstraint()
    raise ValueError(f'Unknown constraint type: {constraint}')

def validate_params(parameter_constraints, *, prefer_skip_nested_validation):

    def decorator(func):
        setattr(func, '_skl_parameter_constraints', parameter_constraints)

        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            global_skip_validation = get_config()['skip_parameter_validation']
            if global_skip_validation:
                return func(*args, **kwargs)
            func_sig = signature(func)
            params = func_sig.bind(*args, **kwargs)
            params.apply_defaults()
            to_ignore = [p.name for p in func_sig.parameters.values() if p.kind in (p.VAR_POSITIONAL, p.VAR_KEYWORD)]
            to_ignore += ['self', 'cls']
            params = {k: v for k, v in params.arguments.items() if k not in to_ignore}
            validate_parameter_constraints(parameter_constraints, params, caller_name=func.__qualname__)
            try:
                with config_context(skip_parameter_validation=prefer_skip_nested_validation or global_skip_validation):
                    return func(*args, **kwargs)
            except InvalidParameterError as e:
                msg = re.sub('parameter of \\w+ must be', f'parameter of {func.__qualname__} must be', str(e))
                raise InvalidParameterError(msg) from e
        return wrapper
    return decorator

def _type_name(t):
    module = t.__module__
    qualname = t.__qualname__
    if module == 'builtins':
        return qualname
    elif t == Real:
        return 'float'
    elif t == Integral:
        return 'int'
    return f'{module}.{qualname}'

def generate_invalid_param_val(constraint):
    if isinstance(constraint, StrOptions):
        return f"not {' or '.join(constraint.options)}"
    if isinstance(constraint, MissingValues):
        return np.array([1, 2, 3])
    if isinstance(constraint, _VerboseHelper):
        return -1
    if isinstance(constraint, HasMethods):
        return type('HasNotMethods', (), {})()
    if isinstance(constraint, _IterablesNotString):
        return 'a string'
    if isinstance(constraint, _CVObjects):
        return 'not a cv object'
    if isinstance(constraint, Interval) and constraint.type is Integral:
        if constraint.left is not None:
            return constraint.left - 1
        if constraint.right is not None:
            return constraint.right + 1
        raise NotImplementedError
    if isinstance(constraint, Interval) and constraint.type in (Real, RealNotInt):
        if constraint.left is not None:
            return constraint.left - 1e-06
        if constraint.right is not None:
            return constraint.right + 1e-06
        if constraint.closed in ('right', 'neither'):
            return -np.inf
        if constraint.closed in ('left', 'neither'):
            return np.inf
        return np.nan
    raise NotImplementedError

def generate_valid_param(constraint):
    if isinstance(constraint, _ArrayLikes):
        return np.array([1, 2, 3])
    if isinstance(constraint, _SparseMatrices):
        return csr_array([[0, 1], [1, 0]])
    if isinstance(constraint, _RandomStates):
        return np.random.RandomState(42)
    if isinstance(constraint, _Callables):
        return lambda x: x
    if isinstance(constraint, _NoneConstraint):
        return None
    if isinstance(constraint, _InstancesOf):
        if constraint.type is np.ndarray:
            return np.array([1, 2, 3])
        if constraint.type in (Integral, Real):
            return 1
        return constraint.type()
    if isinstance(constraint, _Booleans):
        return True
    if isinstance(constraint, _VerboseHelper):
        return 1
    if isinstance(constraint, MissingValues) and constraint.numeric_only:
        return np.nan
    if isinstance(constraint, MissingValues) and (not constraint.numeric_only):
        return 'missing'
    if isinstance(constraint, HasMethods):
        return type('ValidHasMethods', (), {m: lambda self: None for m in constraint.methods})()
    if isinstance(constraint, _IterablesNotString):
        return [1, 2, 3]
    if isinstance(constraint, _CVObjects):
        return 5
    if isinstance(constraint, Options):
        for option in constraint.options:
            return option
    if isinstance(constraint, Interval):
        interval = constraint
        if interval.left is None and interval.right is None:
            return 0
        elif interval.left is None:
            return interval.right - 1
        elif interval.right is None:
            return interval.left + 1
        elif interval.type is Real:
            return (interval.left + interval.right) / 2
        else:
            return interval.left + 1
    raise ValueError(f'Unknown constraint type: {constraint}')

@abstractmethod
def is_satisfied_by(self, val):
    pass

@abstractmethod
def __str__(self):
    pass

def _mark_if_deprecated(self, option):
    option_str = f'{option!r}'
    if option in self.deprecated:
        option_str = f'{option_str} (deprecated)'
    return option_str

def _validate_score_name(score_name, scoring, negate_score):
    if score_name is not None:
        return score_name
    elif scoring is None:
        return 'Negative score' if negate_score else 'Score'
    else:
        score_name = scoring.__name__ if callable(scoring) else scoring
        if negate_score:
            if score_name.startswith('neg_'):
                score_name = score_name[4:]
            else:
                score_name = f'Negative {score_name}'
        elif score_name.startswith('neg_'):
            score_name = f'Negative {score_name[4:]}'
        score_name = score_name.replace('_', ' ')
        return score_name.capitalize()

def _interval_max_min_ratio(data):
    diff = np.diff(np.sort(data))
    return diff.max() / diff.min()

def _validate_style_kwargs(default_style_kwargs, user_style_kwargs):
    invalid_to_valid_kw = {'ls': 'linestyle', 'c': 'color', 'ec': 'edgecolor', 'fc': 'facecolor', 'lw': 'linewidth', 'mec': 'markeredgecolor', 'mfcalt': 'markerfacecoloralt', 'ms': 'markersize', 'mew': 'markeredgewidth', 'mfc': 'markerfacecolor', 'aa': 'antialiased', 'ds': 'drawstyle', 'font': 'fontproperties', 'family': 'fontfamily', 'name': 'fontname', 'size': 'fontsize', 'stretch': 'fontstretch', 'style': 'fontstyle', 'variant': 'fontvariant', 'weight': 'fontweight', 'ha': 'horizontalalignment', 'va': 'verticalalignment', 'ma': 'multialignment'}
    for invalid_key, valid_key in invalid_to_valid_kw.items():
        if invalid_key in user_style_kwargs and valid_key in user_style_kwargs:
            raise TypeError(f'Got both {invalid_key} and {valid_key}, which are aliases of one another')
    valid_style_kwargs = default_style_kwargs.copy()
    for key in user_style_kwargs.keys():
        if key in invalid_to_valid_kw:
            valid_style_kwargs[invalid_to_valid_kw[key]] = user_style_kwargs[key]
        else:
            valid_style_kwargs[key] = user_style_kwargs[key]
    return valid_style_kwargs

def _despine(ax):
    for s in ['top', 'right']:
        ax.spines[s].set_visible(False)
    for s in ['bottom', 'left']:
        ax.spines[s].set_bounds(0, 1)

def _deprecate_estimator_name(estimator_name, name, version):
    version = parse_version(version)
    version_remove = f'{version.major}.{version.minor + 2}'
    if estimator_name != 'deprecated':
        if name:
            raise ValueError(f'Cannot provide both `estimator_name` and `name`. `estimator_name` is deprecated in {version} and will be removed in {version_remove}. Use `name` only.')
        warnings.warn(f'`estimator_name` is deprecated in {version} and will be removed in {version_remove}. Use `name` instead.', FutureWarning)
        return estimator_name
    return name

def _convert_to_list_leaving_none(param):
    if param is None:
        return None
    if isinstance(param, list):
        return param
    return [param]

def _check_param_lengths(required, optional, class_name):
    optional_provided = {}
    for name, param in optional.items():
        if isinstance(param, list):
            optional_provided[name] = param
    all_params = {**required, **optional_provided}
    if len({len(param) for param in all_params.values()}) > 1:
        param_keys = [key for key in all_params.keys()]
        params_formatted = ' and '.join([', '.join(param_keys[:-1]), param_keys[-1]])
        or_plot = ''
        if "'name' (or self.name)" in param_keys:
            or_plot = ' (or `plot`)'
        lengths_formatted = ', '.join((f'{key}: {len(value)}' for key, value in all_params.items()))
        raise ValueError(f'{params_formatted} from `{class_name}` initialization{or_plot}, should all be lists of the same length. Got: {lengths_formatted}')

def _deprecate_y_pred_parameter(y_score, y_pred, version):
    version = parse_version(version)
    version_remove = f'{version.major}.{version.minor + 2}'
    if y_score is not None and (not (isinstance(y_pred, str) and y_pred == 'deprecated')):
        raise ValueError(f'`y_pred` and `y_score` cannot be both specified. Please use `y_score` only as `y_pred` was deprecated in {version} and will be removed in {version_remove}.')
    if not (isinstance(y_pred, str) and y_pred == 'deprecated'):
        warnings.warn(f'y_pred was deprecated in {version} and will be removed in {version_remove}. Please use `y_score` instead.', FutureWarning)
        return y_pred
    return y_score

@staticmethod
def _get_legend_metric(curve_kwargs, n_curves, metric):
    if not isinstance(curve_kwargs, list) and n_curves > 1:
        if metric:
            legend_metric = {'mean': np.mean(metric), 'std': np.std(metric)}
        else:
            legend_metric = {'mean': None, 'std': None}
    else:
        metric = metric if metric is not None else [None] * n_curves
        legend_metric = {'metric': metric}
    return (metric, legend_metric)

@staticmethod
def _get_legend_label(curve_legend_metric, curve_name, legend_metric_name):
    if curve_legend_metric is not None and curve_name is not None:
        label = f'{curve_name} ({legend_metric_name} = {curve_legend_metric:0.2f})'
    elif curve_legend_metric is not None:
        label = f'{legend_metric_name} = {curve_legend_metric:0.2f}'
    elif curve_name is not None:
        label = curve_name
    else:
        label = None
    return label

@staticmethod
def _validate_curve_kwargs(n_curves, name, legend_metric, legend_metric_name, curve_kwargs, default_curve_kwargs=None, default_multi_curve_kwargs=None, removed_version='1.9', **kwargs):
    if curve_kwargs and kwargs:
        raise ValueError(f'Cannot provide both `curve_kwargs` and `kwargs`. `**kwargs` is deprecated and will be removed in {removed_version}. Pass all matplotlib arguments to `curve_kwargs` as a dictionary.')
    if kwargs:
        warnings.warn(f'`**kwargs` is deprecated and will be removed in {removed_version}. Pass all matplotlib arguments to `curve_kwargs` as a dictionary instead.', FutureWarning)
        curve_kwargs = kwargs
    if isinstance(curve_kwargs, list) and len(curve_kwargs) != n_curves:
        raise ValueError(f'`curve_kwargs` must be None, a dictionary or a list of length {n_curves}. Got: {curve_kwargs}.')
    if isinstance(name, list) and len(name) != 1 and (not isinstance(curve_kwargs, list)):
        raise ValueError(f'To avoid labeling individual curves that have the same appearance, `curve_kwargs` should be a list of {n_curves} dictionaries. Alternatively, set `name` to `None` or a single string to label a single legend entry for all curves.')
    if isinstance(name, str):
        name = [name]
    if isinstance(name, list) and len(name) == 1:
        name = name * n_curves
    name = [None] * n_curves if name is None else name
    if isinstance(curve_kwargs, Mapping):
        curve_kwargs = [curve_kwargs] * n_curves
    elif curve_kwargs is None:
        curve_kwargs = [{}] * n_curves
    if default_curve_kwargs is None:
        default_curve_kwargs = {}
    if default_multi_curve_kwargs is None:
        default_multi_curve_kwargs = {}
    if n_curves > 1:
        default_curve_kwargs.update(default_multi_curve_kwargs)
    labels = []
    if 'mean' in legend_metric:
        label_aggregate = _BinaryClassifierCurveDisplayMixin._get_legend_label(legend_metric['mean'], name[0], legend_metric_name)
        if legend_metric['std'] is not None:
            if name[0] is not None:
                label_aggregate = label_aggregate[:-1] + f" +/- {legend_metric['std']:0.2f})"
            else:
                label_aggregate = label_aggregate + f" +/- {legend_metric['std']:0.2f}"
        labels.extend([label_aggregate] + [None] * (n_curves - 1))
    else:
        for curve_legend_metric, curve_name in zip(legend_metric['metric'], name):
            labels.append(_BinaryClassifierCurveDisplayMixin._get_legend_label(curve_legend_metric, curve_name, legend_metric_name))
    curve_kwargs_ = [_validate_style_kwargs({'label': label, **default_curve_kwargs}, curve_kwargs[fold_idx]) for fold_idx, label in enumerate(labels)]
    return curve_kwargs_

def _changed_params(estimator):
    params = estimator.get_params(deep=False)
    init_params = inspect.signature(estimator.__init__).parameters
    init_params = {name: param.default for name, param in init_params.items()}

    def has_changed(k, v):
        if k not in init_params:
            return True
        if init_params[k] == inspect._empty:
            return True
        if isinstance(v, BaseEstimator) and v.__class__ != init_params[k].__class__:
            return True
        if repr(v) != repr(init_params[k]) and (not (is_scalar_nan(init_params[k]) and is_scalar_nan(v))):
            return True
        return False
    return {k: v for k, v in params.items() if has_changed(k, v)}

def _safe_repr(object, context, maxlevels, level, changed_only=False):
    typ = type(object)
    if typ in pprint._builtin_scalars:
        return (repr(object), True, False)
    r = getattr(typ, '__repr__', None)
    if issubclass(typ, dict) and r is dict.__repr__:
        if not object:
            return ('{}', True, False)
        objid = id(object)
        if maxlevels and level >= maxlevels:
            return ('{...}', False, objid in context)
        if objid in context:
            return (pprint._recursion(object), False, True)
        context[objid] = 1
        readable = True
        recursive = False
        components = []
        append = components.append
        level += 1
        saferepr = _safe_repr
        items = sorted(object.items(), key=pprint._safe_tuple)
        for k, v in items:
            krepr, kreadable, krecur = saferepr(k, context, maxlevels, level, changed_only=changed_only)
            vrepr, vreadable, vrecur = saferepr(v, context, maxlevels, level, changed_only=changed_only)
            append('%s: %s' % (krepr, vrepr))
            readable = readable and kreadable and vreadable
            if krecur or vrecur:
                recursive = True
        del context[objid]
        return ('{%s}' % ', '.join(components), readable, recursive)
    if issubclass(typ, list) and r is list.__repr__ or (issubclass(typ, tuple) and r is tuple.__repr__):
        if issubclass(typ, list):
            if not object:
                return ('[]', True, False)
            format = '[%s]'
        elif len(object) == 1:
            format = '(%s,)'
        else:
            if not object:
                return ('()', True, False)
            format = '(%s)'
        objid = id(object)
        if maxlevels and level >= maxlevels:
            return (format % '...', False, objid in context)
        if objid in context:
            return (pprint._recursion(object), False, True)
        context[objid] = 1
        readable = True
        recursive = False
        components = []
        append = components.append
        level += 1
        for o in object:
            orepr, oreadable, orecur = _safe_repr(o, context, maxlevels, level, changed_only=changed_only)
            append(orepr)
            if not oreadable:
                readable = False
            if orecur:
                recursive = True
        del context[objid]
        return (format % ', '.join(components), readable, recursive)
    if issubclass(typ, BaseEstimator):
        objid = id(object)
        if maxlevels and level >= maxlevels:
            return (f'{typ.__name__}(...)', False, objid in context)
        if objid in context:
            return (pprint._recursion(object), False, True)
        context[objid] = 1
        readable = True
        recursive = False
        if changed_only:
            params = _changed_params(object)
        else:
            params = object.get_params(deep=False)
        components = []
        append = components.append
        level += 1
        saferepr = _safe_repr
        items = sorted(params.items(), key=pprint._safe_tuple)
        for k, v in items:
            krepr, kreadable, krecur = saferepr(k, context, maxlevels, level, changed_only=changed_only)
            vrepr, vreadable, vrecur = saferepr(v, context, maxlevels, level, changed_only=changed_only)
            append('%s=%s' % (krepr.strip("'"), vrepr))
            readable = readable and kreadable and vreadable
            if krecur or vrecur:
                recursive = True
        del context[objid]
        return ('%s(%s)' % (typ.__name__, ', '.join(components)), readable, recursive)
    rep = repr(object)
    return (rep, rep and (not rep.startswith('<')), False)

def _process_predict_proba(*, y_pred, target_type, classes, pos_label):
    if target_type == 'binary' and y_pred.shape[1] < 2:
        raise ValueError(f'Got predict_proba of shape {y_pred.shape}, but need classifier with two classes.')
    if target_type == 'binary':
        col_idx = np.flatnonzero(classes == pos_label)[0]
        return y_pred[:, col_idx]
    elif target_type == 'multilabel-indicator':
        if isinstance(y_pred, list):
            return np.vstack([p[:, -1] for p in y_pred]).T
        else:
            return y_pred
    return y_pred

def _process_decision_function(*, y_pred, target_type, classes, pos_label):
    if target_type == 'binary' and pos_label == classes[0]:
        return -1 * y_pred
    return y_pred

def _get_response_values(estimator, X, response_method, pos_label=None, return_response_method_used=False):
    prediction_method = _check_response_method(estimator, response_method)
    if is_classifier(estimator):
        classes = estimator.classes_
        target_type = type_of_target(classes)
        if target_type == 'binary':
            if pos_label is not None and pos_label not in classes.tolist():
                raise ValueError(f'pos_label={pos_label} is not a valid label: It should be one of {classes}')
            elif pos_label is None:
                pos_label = classes[-1]
        y_pred = prediction_method(X)
        if prediction_method.__name__ in ('predict_proba', 'predict_log_proba'):
            y_pred = _process_predict_proba(y_pred=y_pred, target_type=target_type, classes=classes, pos_label=pos_label)
        elif prediction_method.__name__ == 'decision_function':
            y_pred = _process_decision_function(y_pred=y_pred, target_type=target_type, classes=classes, pos_label=pos_label)
    else:
        y_pred, pos_label = (prediction_method(X), None)
    if return_response_method_used:
        return (y_pred, pos_label, prediction_method.__name__)
    return (y_pred, pos_label)

def _get_response_values_binary(estimator, X, response_method, pos_label=None, return_response_method_used=False):
    classification_error = "Expected 'estimator' to be a binary classifier."
    check_is_fitted(estimator)
    if not is_classifier(estimator):
        raise ValueError(classification_error + f' Got {estimator.__class__.__name__} instead.')
    elif len(estimator.classes_) != 2:
        raise ValueError(classification_error + f' Got {len(estimator.classes_)} classes instead.')
    if response_method == 'auto':
        response_method = ['predict_proba', 'decision_function']
    return _get_response_values(estimator, X, response_method, pos_label=pos_label, return_response_method_used=return_response_method_used)

def check_library_installed(library):
    try:
        return importlib.import_module(library)
    except ImportError as exc:
        raise ImportError(f"Setting output container to '{library}' requires {library} to be installed") from exc

def _get_adapter_from_container(container):
    module_name = container.__class__.__module__.split('.')[0]
    try:
        return ADAPTERS_MANAGER.adapters[module_name]
    except KeyError as exc:
        available_adapters = list(ADAPTERS_MANAGER.adapters.keys())
        raise ValueError(f'The container does not have a registered adapter in scikit-learn. Available adapters are: {available_adapters} while the container provided is: {container!r}.') from exc

def _get_container_adapter(method, estimator=None):
    dense_config = _get_output_config(method, estimator)['dense']
    try:
        return ADAPTERS_MANAGER.adapters[dense_config]
    except KeyError:
        return None

def _get_output_config(method, estimator=None):
    est_sklearn_output_config = getattr(estimator, '_sklearn_output_config', {})
    if method in est_sklearn_output_config:
        dense_config = est_sklearn_output_config[method]
    else:
        dense_config = get_config()[f'{method}_output']
    supported_outputs = ADAPTERS_MANAGER.supported_outputs
    if dense_config not in supported_outputs:
        raise ValueError(f'output config must be in {sorted(supported_outputs)}, got {dense_config}')
    return {'dense': dense_config}

def _wrap_data_with_container(method, data_to_wrap, original_input, estimator):
    output_config = _get_output_config(method, estimator)
    if output_config['dense'] == 'default' or not _auto_wrap_is_configured(estimator):
        return data_to_wrap
    dense_config = output_config['dense']
    if issparse(data_to_wrap):
        raise ValueError(f"The transformer outputs a scipy sparse matrix. Try to set the transformer output to a dense array or disable {dense_config.capitalize()} output with set_output(transform='default').")
    adapter = ADAPTERS_MANAGER.adapters[dense_config]
    try:
        columns = estimator.get_feature_names_out()
    except AttributeError as e:
        if 'does not provide get_feature_names_out' in str(e):
            columns = None
        else:
            raise
    return adapter.create_container(data_to_wrap, original_input, columns=columns)

def _wrap_method_output(f, method):

    @wraps(f)
    def wrapped(self, X, *args, **kwargs):
        data_to_wrap = f(self, X, *args, **kwargs)
        if isinstance(data_to_wrap, tuple):
            return_tuple = (_wrap_data_with_container(method, data_to_wrap[0], X, self), *data_to_wrap[1:])
            if hasattr(type(data_to_wrap), '_make'):
                return type(data_to_wrap)._make(return_tuple)
            return return_tuple
        return _wrap_data_with_container(method, data_to_wrap, X, self)
    return wrapped

def _auto_wrap_is_configured(estimator):
    auto_wrap_output_keys = getattr(estimator, '_sklearn_auto_wrap_output_keys', set())
    return hasattr(estimator, 'get_feature_names_out') and 'transform' in auto_wrap_output_keys

def _safe_set_output(estimator, *, transform=None):
    set_output_for_transform = hasattr(estimator, 'transform') or (hasattr(estimator, 'fit_transform') and transform is not None)
    if not set_output_for_transform:
        return
    if not hasattr(estimator, 'set_output'):
        raise ValueError(f'Unable to configure output for {estimator} because `set_output` is not available.')
    return estimator.set_output(transform=transform)

@available_if(_auto_wrap_is_configured)
def set_output(self, *, transform=None):
    if transform is None:
        return self
    if not hasattr(self, '_sklearn_output_config'):
        self._sklearn_output_config = {}
    self._sklearn_output_config['transform'] = transform
    return self

def _get_sys_info():
    python = sys.version.replace('\n', ' ')
    blob = [('python', python), ('executable', sys.executable), ('machine', platform.platform())]
    return dict(blob)

def _get_deps_info():
    deps = ['pip', 'setuptools', 'numpy', 'scipy', 'Cython', 'pandas', 'matplotlib', 'joblib', 'threadpoolctl', 'narwhals']
    deps_info = {'sklearn': __version__}
    from importlib.metadata import PackageNotFoundError, version
    for modname in deps:
        try:
            deps_info[modname] = version(modname)
        except PackageNotFoundError:
            deps_info[modname] = None
    return deps_info

def show_versions():
    sys_info = _get_sys_info()
    deps_info = _get_deps_info()
    print('\nSystem:')
    for k, stat in sys_info.items():
        print('{k:>10}: {stat}'.format(k=k, stat=stat))
    print('\nPython dependencies:')
    for k, stat in deps_info.items():
