def _align_api_if_sparse(X):
    if not sp.sparse.issparse(X):
        return X
    config_sparse_interface = get_config()['sparse_interface']
    if config_sparse_interface == 'sparray':
        if sp.sparse.isspmatrix(X):
            return getattr(sp.sparse, X.format + '_array')(X)
        return X
    elif config_sparse_interface == 'spmatrix':
        if sp.sparse.isspmatrix(X):
            return X
        return getattr(sp.sparse, X.format + '_matrix')(X)
    else:
        raise ValueError(f'Config "sparse_interface" is {config_sparse_interface}. It should be either "sparray" or "spmatrix".')

def get_tags(estimator) -> Tags:
    if isinstance(estimator, type):
        raise TypeError(f'Expected an estimator instance ({estimator.__name__}()), got estimator class instead ({estimator.__name__}).')
    try:
        tags = estimator.__sklearn_tags__()
    except AttributeError as exc:
        if "object has no attribute '__sklearn_tags__'" in str(exc):
            raise AttributeError(f"The following error was raised: {exc}. It seems that there are no classes that implement `__sklearn_tags__` in the MRO and/or all classes in the MRO call `super().__sklearn_tags__()`. Make sure to inherit from `BaseEstimator` which implements `__sklearn_tags__` (or alternatively define `__sklearn_tags__` but we don't recommend this approach). Note that `BaseEstimator` needs to be on the right side of other Mixins in the inheritance order.")
        else:
            raise
    return tags

def ignore_warnings(obj=None, category=Warning):
    if isinstance(obj, type) and issubclass(obj, Warning):
        warning_name = obj.__name__
        raise ValueError("'obj' should be a callable where you want to ignore warnings. You passed a warning class instead: 'obj={warning_name}'. If you want to pass a warning class to ignore_warnings, you should use 'category={warning_name}'".format(warning_name=warning_name))
    elif callable(obj):
        return _IgnoreWarnings(category=category)(obj)
    else:
        return _IgnoreWarnings(category=category)

def assert_allclose_dense_sparse(x, y, rtol=1e-07, atol=1e-09, err_msg=''):
    if sp.sparse.issparse(x) and sp.sparse.issparse(y):
        x = x.tocsr()
        y = y.tocsr()
        x.sum_duplicates()
        y.sum_duplicates()
        assert_array_equal(x.indices, y.indices, err_msg=err_msg)
        assert_array_equal(x.indptr, y.indptr, err_msg=err_msg)
        assert_allclose(x.data, y.data, rtol=rtol, atol=atol, err_msg=err_msg)
    elif not sp.sparse.issparse(x) and (not sp.sparse.issparse(y)):
        assert_allclose(x, y, rtol=rtol, atol=atol, err_msg=err_msg)
    else:
        raise ValueError('Can only compare two sparse matrices, not a sparse matrix and an array.')

