def _get_args(function, varargs=False):
    try:
        params = signature(function).parameters
    except ValueError:
        return []
    args = [key for key, param in params.items() if param.kind not in (param.VAR_POSITIONAL, param.VAR_KEYWORD)]
    if varargs:
        varargs = [param.name for param in params.values() if param.kind == param.VAR_POSITIONAL]
        if len(varargs) == 0:
            varargs = None
        return (args, varargs)
    else:
        return args

def _get_func_name(func):
    parts = []
    module = inspect.getmodule(func)
    if module:
        parts.append(module.__name__)
    qualname = func.__qualname__
    if qualname != func.__name__:
        parts.append(qualname[:qualname.find('.')])
    parts.append(func.__name__)
    return '.'.join(parts)

def check_docstring_parameters(func, doc=None, ignore=None):
    from numpydoc import docscrape
    incorrect = []
    ignore = [] if ignore is None else ignore
    func_name = _get_func_name(func)
    if not func_name.startswith('sklearn.') or func_name.startswith('sklearn.externals'):
        return incorrect
    if inspect.isdatadescriptor(func):
        return incorrect
    if func_name.split('.')[-1] in ('setup_module', 'teardown_module'):
        return incorrect
    if func_name.split('.')[2] == 'estimator_checks':
        return incorrect
    param_signature = list(filter(lambda x: x not in ignore, _get_args(func)))
    if len(param_signature) > 0 and param_signature[0] == 'self':
        param_signature.remove('self')
    if doc is None:
        records = []
        with warnings.catch_warnings(record=True):
            warnings.simplefilter('error', UserWarning)
            try:
                doc = docscrape.FunctionDoc(func)
            except UserWarning as exp:
                if 'potentially wrong underline length' in str(exp):
                    message = str(exp).split('\n')[:3]
                    incorrect += [f'In function: {func_name}'] + message
                    return incorrect
                records.append(str(exp))
            except Exception as exp:
                incorrect += [func_name + ' parsing error: ' + str(exp)]
                return incorrect
        if len(records):
            raise RuntimeError('Error for %s:\n%s' % (func_name, records[0]))
    param_docs = []
    for name, type_definition, param_doc in doc['Parameters']:
        if not type_definition.strip():
            if ':' in name and name[:name.index(':')][-1:].strip():
                incorrect += [func_name + ' There was no space between the param name and colon (%r)' % name]
            elif name.rstrip().endswith(':'):
                incorrect += [func_name + ' Parameter %r has an empty type spec. Remove the colon' % name.lstrip()]
        if '*' not in name:
            param_docs.append(name.split(':')[0].strip('` '))
    if len(incorrect) > 0:
        return incorrect
    param_docs = list(filter(lambda x: x not in ignore, param_docs))
    message = []
    for i in range(min(len(param_docs), len(param_signature))):
        if param_signature[i] != param_docs[i]:
            message += ["There's a parameter name mismatch in function docstring w.r.t. function signature, at index %s diff: %r != %r" % (i, param_signature[i], param_docs[i])]
            break
    if len(param_signature) > len(param_docs):
        message += ['Parameters in function docstring have less items w.r.t. function signature, first missing item: %s' % param_signature[len(param_docs)]]
    elif len(param_signature) < len(param_docs):
        message += ['Parameters in function docstring have more items w.r.t. function signature, first extra item: %s' % param_docs[len(param_signature)]]
    if len(message) == 0:
        return []
    import difflib
    import pprint
    param_docs_formatted = pprint.pformat(param_docs).splitlines()
    param_signature_formatted = pprint.pformat(param_signature).splitlines()
    message += ['Full diff:']
    message.extend((line.strip() for line in difflib.ndiff(param_signature_formatted, param_docs_formatted)))
    incorrect.extend(message)
    incorrect = ['In function: ' + func_name] + incorrect
    return incorrect

def _check_item_included(item_name, args):
    if args.include is not True and item_name not in args.include:
        return False
    if args.exclude is not None and item_name in args.exclude:
        return False
    return True

def _diff_key(line):
    if line.startswith('  '):
        return '  '
    elif line.startswith('- '):
        return '- '
    elif line.startswith('+ '):
        return '+ '
    elif line.startswith('! '):
        return '! '
    return None

def _get_diff_msg(docstrings_grouped):
    msg_diff = ''
    ref_str = ''
    ref_group = []
    for docstring, group in docstrings_grouped.items():
        if not ref_str and (not ref_group):
            ref_str += docstring
            ref_group.extend(group)
        diff = list(context_diff(ref_str.split(), docstring.split(), fromfile=str(ref_group), tofile=str(group), n=8))
        msg_diff += ''.join(diff[:3])
        for start, group in groupby(diff[3:], key=_diff_key):
            if start is None:
                msg_diff += '\n' + '\n'.join(group)
            else:
                msg_diff += '\n' + start + ' '.join((word[2:] for word in group))
        msg_diff += '\n\n'
    return msg_diff

def _check_consistency_items(items_docs, type_or_desc, section, n_objects, descr_regex_pattern='', ignore_types=tuple()):
    skipped = []
    for item_name, docstrings_grouped in items_docs.items():
        if sum([len(objs) for objs in docstrings_grouped.values()]) < n_objects:
            skipped.append(item_name)
        elif type_or_desc == 'description' and descr_regex_pattern:
            not_matched = []
            for docstring, group in docstrings_grouped.items():
                if not re.search(descr_regex_pattern, docstring):
                    not_matched.extend(group)
            if not_matched:
                msg = textwrap.fill(f"The description of {section[:-1]} '{item_name}' in {not_matched} does not match 'descr_regex_pattern': {descr_regex_pattern} ")
                raise AssertionError(msg)
        elif type_or_desc == 'type specification' and item_name in ignore_types:
            continue
        elif len(docstrings_grouped.keys()) > 1:
            msg_diff = _get_diff_msg(docstrings_grouped)
            obj_groups = ' and '.join((str(group) for group in docstrings_grouped.values()))
            msg = textwrap.fill(f"The {type_or_desc} of {section[:-1]} '{item_name}' is inconsistent between {obj_groups}:")
            msg += msg_diff
            raise AssertionError(msg)
    if skipped:
        warnings.warn(f'Checking was skipped for {section}: {skipped} as they were not found in all objects.')

def assert_docstring_consistency(objects, include_params=False, exclude_params=None, include_attrs=False, exclude_attrs=None, include_returns=False, exclude_returns=None, descr_regex_pattern=None, ignore_types=tuple()):
    from numpydoc.docscrape import NumpyDocString
    Args = namedtuple('args', ['include', 'exclude', 'arg_name'])

    def _create_args(include, exclude, arg_name, section_name):
        if exclude and include is not True:
            raise TypeError(f"The 'exclude_{arg_name}' argument can be set only when the 'include_{arg_name}' argument is True.")
        if include is False:
            return {}
        return {section_name: Args(include, exclude, arg_name)}
    section_args = {**_create_args(include_params, exclude_params, 'params', 'Parameters'), **_create_args(include_attrs, exclude_attrs, 'attrs', 'Attributes'), **_create_args(include_returns, exclude_returns, 'returns', 'Returns')}
    objects_doc = dict()
    for obj in objects:
        if inspect.isdatadescriptor(obj) or inspect.isfunction(obj) or inspect.isclass(obj):
            objects_doc[obj.__name__] = NumpyDocString(inspect.getdoc(obj))
        else:
            raise TypeError(f"All 'objects' must be one of: function, class or descriptor, got a: {type(obj)}.")
    n_objects = len(objects)
    for section, args in section_args.items():
        type_items = defaultdict(lambda: defaultdict(list))
        desc_items = defaultdict(lambda: defaultdict(list))
        for obj_name, obj_doc in objects_doc.items():
            for item_name, type_def, desc in obj_doc[section]:
                if _check_item_included(item_name, args):
                    type_def = ' '.join(type_def.strip().split())
                    desc = ' '.join(chain.from_iterable((line.split() for line in desc)))
                    type_items[item_name][type_def].append(obj_name)
                    desc_items[item_name][desc].append(obj_name)
        _check_consistency_items(type_items, 'type specification', section, n_objects, ignore_types=ignore_types)
        _check_consistency_items(desc_items, 'description', section, n_objects, descr_regex_pattern=descr_regex_pattern)

def assert_run_python_script_without_output(source_code, pattern='.+', timeout=60):
    fd, source_file = tempfile.mkstemp(suffix='_src_test_sklearn.py')
    os.close(fd)
    try:
        with open(source_file, 'wb') as f:
            f.write(source_code.encode('utf-8'))
        cmd = [sys.executable, source_file]
        cwd = op.normpath(op.join(op.dirname(sklearn_path), '..'))
        env = os.environ.copy()
        try:
            env['PYTHONPATH'] = os.pathsep.join([cwd, env['PYTHONPATH']])
        except KeyError:
            env['PYTHONPATH'] = cwd
        kwargs = {'cwd': cwd, 'stderr': STDOUT, 'env': env}
        coverage_rc = os.environ.get('COVERAGE_PROCESS_START')
        if coverage_rc:
            kwargs['env']['COVERAGE_PROCESS_START'] = coverage_rc
        kwargs['timeout'] = timeout
        try:
            try:
                out = check_output(cmd, **kwargs)
            except CalledProcessError as e:
                raise RuntimeError('script errored with output:\n%s' % e.output.decode('utf-8'))
            out = out.decode('utf-8')
            if re.search(pattern, out):
                if pattern == '.+':
                    expectation = 'Expected no output'
                else:
                    expectation = f'The output was not supposed to match {pattern!r}'
                message = f'{expectation}, got the following output instead: {out!r}'
                raise AssertionError(message)
        except TimeoutExpired as e:
            raise RuntimeError('script timeout, output so far:\n%s' % e.output.decode('utf-8'))
    finally:
        os.unlink(source_file)

def _convert_container(container, constructor_name, column_names=None, dtype=None, minversion=None, categorical_feature_names=None):
    if constructor_name == 'list':
        if dtype is None:
            return list(container)
        else:
            return np.asarray(container, dtype=dtype).tolist()
    elif constructor_name == 'tuple':
        if dtype is None:
            return tuple(container)
        else:
            return tuple(np.asarray(container, dtype=dtype).tolist())
    elif constructor_name == 'array':
        return np.asarray(container, dtype=dtype)
    elif constructor_name == 'pandas':
        pd = pytest.importorskip('pandas', minversion=minversion)
        result = pd.DataFrame(container, columns=column_names, dtype=dtype, copy=False)
        if categorical_feature_names is not None:
            for col_name in categorical_feature_names:
                result[col_name] = result[col_name].astype('category')
        return result
    elif constructor_name == 'pyarrow':
        pa = pytest.importorskip('pyarrow', minversion=minversion)
        array = np.asarray(container)
        array = array[:, None] if array.ndim == 1 else array
        if column_names is None:
            column_names = [f'col{i}' for i in range(array.shape[1])]
        data = {name: array[:, i] for i, name in enumerate(column_names)}
        result = pa.Table.from_pydict(data)
        if categorical_feature_names is not None:
            for col_idx, col_name in enumerate(result.column_names):
                if col_name in categorical_feature_names:
                    result = result.set_column(col_idx, col_name, result.column(col_name).dictionary_encode())
        return result
    elif constructor_name == 'polars':
        pl = pytest.importorskip('polars', minversion=minversion)
        result = pl.DataFrame(container, schema=column_names, orient='row')
        if categorical_feature_names is not None:
            for col_name in categorical_feature_names:
                result = result.with_columns(pl.col(col_name).cast(pl.Categorical))
        return result
    elif constructor_name == 'series':
        pd = pytest.importorskip('pandas', minversion=minversion)
        return pd.Series(container, dtype=dtype)
    elif constructor_name == 'pyarrow_array':
        pa = pytest.importorskip('pyarrow', minversion=minversion)
        return pa.array(container)
    elif constructor_name == 'polars_series':
        pl = pytest.importorskip('polars', minversion=minversion)
        return pl.Series(values=container)
    elif constructor_name == 'index':
        pd = pytest.importorskip('pandas', minversion=minversion)
        return pd.Index(container, dtype=dtype)
    elif constructor_name == 'slice':
        return slice(container[0], container[1])
    elif 'sparse' in constructor_name:
        if not sp.sparse.issparse(container):
            container = np.atleast_2d(container)
        if constructor_name in ('sparse', 'sparse_csr'):
            return sp.sparse.csr_matrix(container, dtype=dtype)
        elif constructor_name == 'sparse_csr_array':
            return sp.sparse.csr_array(container, dtype=dtype)
        elif constructor_name == 'sparse_csc':
            return sp.sparse.csc_matrix(container, dtype=dtype)
        elif constructor_name == 'sparse_csc_array':
            return sp.sparse.csc_array(container, dtype=dtype)

def _array_api_for_tests(array_namespace, device_name=None, dtype_name=None):
    try:
        array_mod = importlib.import_module(array_namespace)
    except (ModuleNotFoundError, ImportError):
        raise SkipTest(f'{array_namespace} is not installed: not checking array_api input')
    if os.environ.get('SCIPY_ARRAY_API') is None:
        raise SkipTest('SCIPY_ARRAY_API is not set: not checking array_api input')
    from sklearn.externals.array_api_compat import get_namespace
    device = None
    xp = get_namespace(array_mod.asarray(1))
    if array_namespace == 'torch' and device_name == 'cuda' and (not xp.backends.cuda.is_built()):
        raise SkipTest('PyTorch test requires cuda, which is not available')
    elif array_namespace == 'dpnp':
        dpctl = pytest.importorskip('dpctl')
        if device_name is None:
            available_devices = dpctl.get_devices()
            if not available_devices:
                raise SkipTest('Skipping dpnp test because no SYCL devices found')
            else:
                device = available_devices[0]
        elif not dpctl.get_devices(device_type=device_name):
            raise SkipTest(f'Skipping dpnp test because no {device_name} device found')
    elif array_namespace == 'torch' and device_name == 'mps':
        if os.getenv('PYTORCH_ENABLE_MPS_FALLBACK') != '1':
            raise SkipTest('Skipping MPS device test because PYTORCH_ENABLE_MPS_FALLBACK is not set.')
        if not xp.backends.mps.is_built():
            raise SkipTest('MPS is not available because the current PyTorch install was not built with MPS enabled.')
    elif array_namespace == 'torch' and device_name == 'xpu':
        if not hasattr(xp, 'xpu'):
            raise SkipTest('XPU is not available because the current PyTorch install was not built with XPU support.')
        if not xp.xpu.is_available():
            raise SkipTest('Skipping XPU device test because no XPU device is available')
    elif array_namespace == 'cupy':
        import cupy
        if cupy.cuda.runtime.getDeviceCount() == 0:
            raise SkipTest('CuPy test requires cuda, which is not available')
    elif array_namespace == 'array_api_strict':
        if device_name is not None:
            device = xp.Device(device_name)
    device = device_name if device is None else device
    if dtype_name == 'float64' and _max_precision_float_dtype(xp, device) != xp.float64:
        skip_msg = f'{array_namespace} does not support float64 on device {device}'
        raise SkipTest(skip_msg)
    return (xp, device)

def __call__(self, fn):

    @wraps(fn)
    def wrapper(*args, **kwargs):
        with warnings.catch_warnings():
            warnings.simplefilter('ignore', self.category)
            return fn(*args, **kwargs)
    return wrapper

def _attach_unique(y):
    if not isinstance(y, np.ndarray):
        return y
    try:
        if 'unique' in y.dtype.metadata:
            return y
    except (AttributeError, TypeError):
        pass
    unique = np.unique(y)
    unique_dtype = np.dtype(y.dtype, metadata={'unique': unique})
    return y.view(dtype=unique_dtype)

def attach_unique(*ys, return_tuple=False):
    res = tuple((_attach_unique(y) for y in ys))
    if len(res) == 1 and (not return_tuple):
        return res[0]
    return res

def _cached_unique(y, xp=None):
    try:
        if y.dtype.metadata is not None and 'unique' in y.dtype.metadata:
            return y.dtype.metadata['unique']
    except AttributeError:
        pass
    xp, _ = get_namespace(y, xp=xp)
    return xp.unique_values(y)

def cached_unique(*ys, xp=None):
    res = tuple((_cached_unique(y, xp=xp) for y in ys))
    if len(res) == 1:
        return res[0]
    return res

def _message_with_time(source, message, time):
    start_message = '[%s] ' % source
    if time > 60:
        time_str = '%4.1fmin' % (time / 60)
    else:
        time_str = ' %5.1fs' % time
    end_message = ' %s, total=%s' % (message, time_str)
    dots_len = 70 - len(start_message) - len(end_message)
    return '%s%s%s' % (start_message, dots_len * '.', end_message)

@contextmanager
def _print_elapsed_time(source, message=None):
    if message is None:
        yield
    else:
        start = timeit.default_timer()
        yield
        print(_message_with_time(source, message, timeit.default_timer() - start))

