def get_docstring(estimator_class, section_name, item):
    estimator_class_docs = inspect.getdoc(estimator_class)
    if estimator_class_docs and (structured_docstring := scrape_estimator_docstring(estimator_class_docs)):
        docstring_map = {item_docstring.name: item_docstring for item_docstring in structured_docstring[section_name]}
    else:
        docstring_map = {}
    if (item_numpydoc := docstring_map.get(item, None)):
        item_description = f"{html.escape(item_numpydoc.name)}: {html.escape(item_numpydoc.type)}<br><br>{'<br>'.join((html.escape(line) for line in item_numpydoc.desc))}"
    else:
        item_description = None
    return item_description

def _get_visual_block(estimator):
    if hasattr(estimator, '_sk_visual_block_'):
        try:
            return estimator._sk_visual_block_()
        except Exception:
            return _VisualBlock('single', estimator, names=estimator.__class__.__name__, name_details=str(estimator))
    if isinstance(estimator, str):
        return _VisualBlock('single', estimator, names=estimator, name_details=estimator)
    elif estimator is None:
        return _VisualBlock('single', estimator, names='None', name_details='None')
    if hasattr(estimator, 'get_params') and (not isclass(estimator)):
        estimators = [(key, est) for key, est in estimator.get_params(deep=False).items() if hasattr(est, 'get_params') and hasattr(est, 'fit') and (not isclass(est))]
        if estimators:
            return _VisualBlock('parallel', [est for _, est in estimators], names=[f'{key}: {est.__class__.__name__}' for key, est in estimators], name_details=[str(est) for _, est in estimators])
    return _VisualBlock('single', estimator, names=estimator.__class__.__name__, name_details=str(estimator))

def _write_estimator_html(out, estimator, estimator_label, estimator_label_details, is_fitted_css_class, is_fitted_icon='', first_call=False, param_prefix=''):
