    is_not_pipeline_step = not hasattr(estimator, 'steps')
    if est_block.kind in ('serial', 'parallel'):
        dashed_wrapped = first_call or est_block.dash_wrapped
        dash_cls = ' sk-dashed-wrapped' if dashed_wrapped else ''
        out.write(f'<div class="sk-item{dash_cls}">')
        if estimator_label:
            if hasattr(estimator, 'get_params') and hasattr(estimator, '_get_params_html'):
                params = estimator._get_params_html(False, doc_link)._repr_html_inner()
            else:
                params = ''
            if hasattr(estimator, '_get_fitted_attr_html') and is_fitted_css_class == 'fitted':
                fitted_attrs = estimator._get_fitted_attr_html(doc_link)
                attrs = fitted_attrs._repr_html_inner() if len(fitted_attrs) > 0 else ''
            else:
                attrs = ''
            _write_label_html(out, params, attrs, estimator_label, estimator_label_details, doc_link=doc_link, features=None, is_fitted_css_class=is_fitted_css_class, is_fitted_icon=is_fitted_icon, param_prefix=param_prefix)
        kind = est_block.kind
        out.write(f'<div class="sk-{kind}">')
        est_infos = zip(est_block.estimators, est_block.names, est_block.name_details)
        for est, name, name_details in est_infos:
            if param_prefix and hasattr(name, 'split'):
                new_prefix = f"{param_prefix}{name.split(':')[0]}__"
            elif hasattr(name, 'split'):
                new_prefix = f"{name.split(':')[0]}__" if name else ''
            else:
                new_prefix = param_prefix
            if kind == 'serial':
                _write_estimator_html(out, est, name, name_details, is_fitted_css_class=is_fitted_css_class, param_prefix=new_prefix)
            else:
                out.write('<div class="sk-parallel-item">')
                serial_block = _VisualBlock('serial', [est], dash_wrapped=False)
                _write_estimator_html(out, serial_block, name, name_details, is_fitted_css_class=is_fitted_css_class, param_prefix=new_prefix)
                out.write('</div>')
        out.write('</div>')
        is_column_transformer = isinstance(estimator, ColumnTransformer)
        has_single_estimator = len(est_block.estimators) == 1
        if is_fitted_css_class and has_feature_names_out and is_not_pipeline_step and (not (is_column_transformer and has_single_estimator)):
            try:
                output_features = estimator.get_feature_names_out()
            except Exception:
                output_features = None
            if output_features is not None:
                features_div = _features_html(output_features, is_fitted_css_class)
                total_output_features_item = f"<div class='total_features'>{features_div}</div>"
                out.write(total_output_features_item)
        out.write('</div>')
    elif est_block.kind == 'single':
        if has_feature_names_out and is_not_pipeline_step and is_fitted_css_class:
            try:
                output_features = estimator.get_feature_names_out()
            except Exception:
                output_features = None
        else:
            output_features = ''
        if est_block.names == 'NoneType(...)':
            est_block.names = 'passthrough'
        if hasattr(estimator, '_get_params_html') and (not est_block.names == 'passthrough'):
            params = estimator._get_params_html(doc_link=doc_link)._repr_html_inner()
        else:
            params = ''
        if hasattr(estimator, '_get_fitted_attr_html') and (not est_block.names == 'passthrough') and (is_fitted_css_class == 'fitted'):
            fitted_attrs = estimator._get_fitted_attr_html(doc_link)
            attrs = fitted_attrs._repr_html_inner() if len(fitted_attrs) > 0 else ''
        else:
            attrs = ''
        _write_label_html(out, params, attrs, est_block.names, est_block.name_details, est_block.name_caption, est_block.doc_link_label, outer_class='sk-item', inner_class='sk-estimator', checked=first_call, doc_link=doc_link, features=output_features, is_fitted_css_class=is_fitted_css_class, is_fitted_icon=is_fitted_icon, param_prefix=param_prefix)

def _construct_instances(Estimator):
    if Estimator in SKIPPED_ESTIMATORS:
        msg = f"Can't instantiate estimator {Estimator.__name__}"
        warnings.warn(msg, SkipTestWarning)
        raise SkipTest(msg)
    if Estimator in INIT_PARAMS:
        param_sets = INIT_PARAMS[Estimator]
        if not isinstance(param_sets, list):
            param_sets = [param_sets]
        for params in param_sets:
            est = Estimator(**params)
            yield est
    else:
        yield Estimator()

def _get_check_estimator_ids(obj):
    if isfunction(obj):
        return obj.__name__
    if isinstance(obj, partial):
        if not obj.keywords:
            return obj.func.__name__
        kwstring = ','.join(['{}={}'.format(k, v) for k, v in obj.keywords.items()])
        return '{}({})'.format(obj.func.__name__, kwstring)
    if hasattr(obj, 'get_params'):
        with config_context(print_changed_only=True):
            return re.sub('\\s', '', str(obj))

def _yield_instances_for_check(check, estimator_orig):
    if type(estimator_orig) not in PER_ESTIMATOR_CHECK_PARAMS:
        yield estimator_orig
        return
    check_params = PER_ESTIMATOR_CHECK_PARAMS[type(estimator_orig)]
    try:
        check_name = check.__name__
    except AttributeError:
        check_name = check.func.__name__
    if check_name not in check_params:
        yield estimator_orig
        return
    param_set = check_params[check_name]
    if isinstance(param_set, dict):
        param_set = [param_set]
    for params in param_set:
        estimator = clone(estimator_orig)
        estimator.set_params(**params)
        yield estimator

def _get_expected_failed_checks(estimator):
    failed_checks = PER_ESTIMATOR_XFAIL_CHECKS.get(type(estimator), {})
    tags = get_tags(estimator)
    if type(estimator) in [KNeighborsClassifier, KNeighborsRegressor]:
        if tags.input_tags.pairwise:
            failed_checks.update({'check_n_features_in_after_fitting': 'FIXME', 'check_dataframe_column_names_consistency': 'FIXME'})
    if type(estimator) == LinearRegression:
        if parse_version('1.15.0') <= sp_base_version < parse_version('1.16') and _IS_32BIT:
            failed_checks.update({'check_sample_weight_equivalence_on_dense_data': 'Issue #31098. Fails on 32-bit platforms with recent scipy.', 'check_sample_weight_equivalence_on_sparse_data': 'Issue #31098. Fails on 32-bit platforms with recent scipy.'})
    return failed_checks

def _inclusive_low_high(interval):
    eps = 10 * ulp(1)
    if interval.low == -float('inf'):
        low = -10000000000.0
    elif interval.low < 0:
        low = interval.low * (1 - eps) + eps
    else:
        low = interval.low * (1 + eps) + eps
    if interval.high == float('inf'):
        high = 10000000000.0
    elif interval.high < 0:
        high = interval.high * (1 + eps) - eps
    else:
        high = interval.high * (1 - eps) - eps
    return (float(low), float(high))

def __post_init__(self):
    if self.low > self.high:
        raise ValueError(f'One must have low <= high; got low={self.low}, high={self.high}.')

def includes(self, x):
    xp, _ = get_namespace(x)
    if self.low_inclusive:
        low = xp.greater_equal(x, self.low)
    else:
        low = xp.greater(x, self.low)
    if not xp.all(low):
        return False
    if self.high_inclusive:
        high = xp.less_equal(x, self.high)
    else:
        high = xp.less(x, self.high)
    return bool(xp.all(high))

@abstractmethod
def link(self, y_pred):
    pass

@abstractmethod
def inverse(self, raw_prediction):
    pass

def _log1pexp(raw_prediction, raw_prediction_exp, xp):
    constants = [-37, -2, 18, 33.3] if raw_prediction.dtype == xp.float64 else [-17, -1, 9, 14.6]
    return xp.where(raw_prediction <= constants[0], raw_prediction_exp, xp.where(raw_prediction <= constants[1], xp.log1p(raw_prediction_exp), xp.where(raw_prediction <= constants[2], xp.log(1.0 + raw_prediction_exp), xp.where(raw_prediction <= constants[3], raw_prediction + 1 / raw_prediction_exp, raw_prediction))))

def loss(self, y_true, raw_prediction, sample_weight=None, loss_out=None, n_threads=1):
    if loss_out is None:
        loss_out = np.empty_like(y_true)
    if raw_prediction.ndim == 2 and raw_prediction.shape[1] == 1:
        raw_prediction = raw_prediction.squeeze(1)
    self.closs.loss(y_true=y_true, raw_prediction=raw_prediction, sample_weight=sample_weight, loss_out=loss_out, n_threads=n_threads)
    return loss_out

def loss_gradient(self, y_true, raw_prediction, sample_weight=None, loss_out=None, gradient_out=None, n_threads=1):
    if loss_out is None:
        if gradient_out is None:
            loss_out = np.empty_like(y_true)
            gradient_out = np.empty_like(raw_prediction)
        else:
            loss_out = np.empty_like(y_true, dtype=gradient_out.dtype)
    elif gradient_out is None:
        gradient_out = np.empty_like(raw_prediction, dtype=loss_out.dtype)
    if raw_prediction.ndim == 2 and raw_prediction.shape[1] == 1:
        raw_prediction = raw_prediction.squeeze(1)
    if gradient_out.ndim == 2 and gradient_out.shape[1] == 1:
        gradient_out = gradient_out.squeeze(1)
    self.closs.loss_gradient(y_true=y_true, raw_prediction=raw_prediction, sample_weight=sample_weight, loss_out=loss_out, gradient_out=gradient_out, n_threads=n_threads)
    return (loss_out, gradient_out)

def gradient(self, y_true, raw_prediction, sample_weight=None, gradient_out=None, n_threads=1):
    if gradient_out is None:
        gradient_out = np.empty_like(raw_prediction)
    if raw_prediction.ndim == 2 and raw_prediction.shape[1] == 1:
        raw_prediction = raw_prediction.squeeze(1)
    if gradient_out.ndim == 2 and gradient_out.shape[1] == 1:
        gradient_out = gradient_out.squeeze(1)
    self.closs.gradient(y_true=y_true, raw_prediction=raw_prediction, sample_weight=sample_weight, gradient_out=gradient_out, n_threads=n_threads)
    return gradient_out

def gradient_hessian(self, y_true, raw_prediction, sample_weight=None, gradient_out=None, hessian_out=None, n_threads=1):
    if gradient_out is None:
        if hessian_out is None:
            gradient_out = np.empty_like(raw_prediction)
            hessian_out = np.empty_like(raw_prediction)
        else:
            gradient_out = np.empty_like(hessian_out)
    elif hessian_out is None:
        hessian_out = np.empty_like(gradient_out)
    if raw_prediction.ndim == 2 and raw_prediction.shape[1] == 1:
        raw_prediction = raw_prediction.squeeze(1)
    if gradient_out.ndim == 2 and gradient_out.shape[1] == 1:
        gradient_out = gradient_out.squeeze(1)
    if hessian_out.ndim == 2 and hessian_out.shape[1] == 1:
        hessian_out = hessian_out.squeeze(1)
